const MINERALS     =['Ferro','Silício','Carbono','Hélio','Hidrogênio','Urânio','Titânio','Osmium','Ouro','Diamante','Iridium','Platina'];
// Traços de cada mineral: atributo próprio do astro (selfMassMult/selfResist) +
// campo de influência de curto alcance sobre astros vizinhos (fieldType/fieldStrength).
const MINERAL_TRAITS={
  'Ferro':     {selfMassMult:1.10, selfResist:1.15, fieldType:'grav',     fieldStrength:0.10},
  'Titânio':   {selfMassMult:1.05, selfResist:1.35, fieldType:'grav',     fieldStrength:0.06},
  'Osmium':    {selfMassMult:1.30, selfResist:1.20, fieldType:'grav',     fieldStrength:0.16},
  'Iridium':   {selfMassMult:1.22, selfResist:1.25, fieldType:'grav',     fieldStrength:0.13},
  'Silício':   {selfMassMult:1.00, selfResist:1.05, fieldType:'bio',      fieldStrength:0.05},
  'Carbono':   {selfMassMult:0.95, selfResist:1.00, fieldType:'bio',      fieldStrength:0.14},
  'Ouro':      {selfMassMult:1.08, selfResist:1.10, fieldType:'bio',      fieldStrength:0.10},
  'Platina':   {selfMassMult:1.12, selfResist:1.18, fieldType:'bio',      fieldStrength:0.08},
  'Hélio':     {selfMassMult:0.85, selfResist:0.90, fieldType:'cold',     fieldStrength:0.12},
  'Hidrogênio':{selfMassMult:0.80, selfResist:0.85, fieldType:'heat',     fieldStrength:0.10},
  'Urânio':    {selfMassMult:1.18, selfResist:0.80, fieldType:'radiation',fieldStrength:0.16},
  'Diamante':  {selfMassMult:1.02, selfResist:1.60, fieldType:'none',     fieldStrength:0},
};
function _mineralTraits(m){return MINERAL_TRAITS[m]||MINERAL_TRAITS['Ferro'];}

// ═══════════════════════════════════════════════════════════════════
//  CAMPO DE INFLUÊNCIA MINERAL — astros com mineral raro/pesado afetam
//  astros vizinhos próximos (gravidade, temperatura ou bio), reaproveitando
//  os campos que todo astro já tem (gravMultiplier/temp/bioTemp/bioO2).
//  Throttle: roda a cada ~0.4s (não todo frame) e só considera pares dentro
//  de um raio curto (proporcional ao raio do emissor), mantendo custo baixo.
// ═══════════════════════════════════════════════════════════════════
let _mineralFieldTimer=0;
const MINERAL_FIELD_INTERVAL=0.4;
function mineralFieldsUpdate(dt){
  _mineralFieldTimer+=dt;
  if(_mineralFieldTimer<MINERAL_FIELD_INTERVAL)return;
  const step=_mineralFieldTimer; // aplica de uma vez o intervalo acumulado
  _mineralFieldTimer=0;
  for(let i=0;i<objects.length;i++){
    const src=objects[i];
    if(!src||src.dead||!src.mineral)continue;
    if(src._mineralBaseMass==null&&typeof src.applyMineralTraits==='function')src.applyMineralTraits(); // 1ª aplicação: mass ainda "crua" no momento em que o astro entra no loop
    const tr=_mineralTraits(src.mineral);
    if(tr.fieldType==='none'||tr.fieldStrength<=0)continue;
    const range=(src.radius||10)*10+80;
    for(let j=0;j<objects.length;j++){
      if(i===j)continue;
      const tgt=objects[j];
      if(!tgt||tgt.dead||typeof tgt.x!=='number')continue;
      const d=dist(src,tgt);
      if(d>range)continue;
      const falloff=1-(d/range); // mais forte perto, zero na borda
      const amt=tr.fieldStrength*falloff*step;
      if(tr.fieldType==='grav'){
        tgt.gravMultiplier=Math.min(200,(tgt.gravMultiplier??1)+amt*0.5);
      }else if(tr.fieldType==='heat'){
        tgt.temp=(tgt.temp??5000)+amt*400;
      }else if(tr.fieldType==='cold'){
        tgt.temp=Math.max(2,(tgt.temp??5000)-amt*400);
      }else if(tr.fieldType==='radiation'){
        tgt.bioO2=Math.max(0,(tgt.bioO2??21)-amt*3);
        tgt.bioTemp=Math.min(100,(tgt.bioTemp??50)+amt*5);
      }else if(tr.fieldType==='bio'){
        tgt.bioWater=Math.min(100,(tgt.bioWater??30)+amt*2);
        tgt.bioO2=Math.min(100,(tgt.bioO2??21)+amt*1.5);
      }
    }
  }
}
// Raridade/energia de cada minério, usada apenas pelo sistema de Rochas
// Cósmicas da Fase Cósmica (não altera nenhum outro uso de MINERALS no
// jogo, que continua uniforme). Quanto mais raro, mais pontos de
// upgrade a rocha concede ao ser coletada.
const COSMIC_MINERAL_TIERS = {
  'Ferro':      { weight: 26, energy: 1 },
  'Silício':    { weight: 22, energy: 1 },
  'Carbono':    { weight: 18, energy: 2 },
  'Hélio':      { weight: 14, energy: 2 },
  'Hidrogênio': { weight: 10, energy: 3 },
  'Titânio':    { weight: 7,  energy: 4 },
  'Urânio':     { weight: 4,  energy: 6 },
  'Osmium':     { weight: 2.4,energy: 8 },
  'Ouro':       { weight: 1.6,energy: 10 },
  'Platina':    { weight: 1,  energy: 14 },
  'Iridium':    { weight: 0.6,energy: 18 },
  'Diamante':   { weight: 0.4,energy: 24 },
};
const COSMIC_MINERAL_TOTAL_WEIGHT = Object.values(COSMIC_MINERAL_TIERS).reduce((s,t)=>s+t.weight,0);

// Sorteia um minério ponderado pela raridade acima (mais raro = menos
// provável). Usado apenas ao criar uma nova Rocha Cósmica.
function _cosmicRollWeightedMineral() {
  let r = Math.random() * COSMIC_MINERAL_TOTAL_WEIGHT;
  for (const name of MINERALS) {
    const tier = COSMIC_MINERAL_TIERS[name];
    if (!tier) continue;
    r -= tier.weight;
    if (r <= 0) return name;
  }
  return MINERALS[0]; // fallback de segurança, nunca deve ser alcançado
}
const ALPHABET     ='ABCDEFGHIJKLMNOPQRSTUVWXYZ';
const ALPHANUM     ='ABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789';

// Generate ID like X-4F2JA
function genID(){
  const letter=ALPHABET[randInt(0,25)];
  const len=randInt(1,6);
  let seq='';for(let i=0;i<len;i++)seq+=ALPHANUM[randInt(0,ALPHANUM.length-1)];
  return `${letter}-${seq}`;
}

