// ── Camera ─────────────────────────────────────────────────────────
const cam={x:0,y:0,zoom:1.0};
// ── Zoom fixo para Bosses/Invasões ──────────────────────────────────
// Evita que o zoom do jogador (baixo/alto) antes da batalha faça a arena,
// astros e boss aparecerem minúsculos ou gigantes. Todas as batalhas
// (Alien, Marciana, Reptiliana/Quasord, Polvicullus, Galaximy) travam
// cam.zoom neste valor fixo via Object.defineProperty (ignora writes
// externos), e restauram o zoom original do jogador ao terminar.
const BATTLE_FIXED_ZOOM=1.0;
function worldToScreen(wx,wy){return{x:(wx-cam.x)*cam.zoom+canvas.width*.5,y:(wy-cam.y)*cam.zoom+canvas.height*.5};}
function screenToWorld(sx,sy){return{x:(sx-canvas.width*.5)/cam.zoom+cam.x,y:(sy-canvas.height*.5)/cam.zoom+cam.y};}

// ── Zoom ───────────────────────────────────────────────────────────
const zoomSlider=document.getElementById('zoom-slider');
const zoomLabel=document.getElementById('zoom-label');
function setZoom(z){cam.zoom=clamp(z,.2,3.0);const p=Math.round(cam.zoom*100);zoomSlider.value=p;zoomLabel.textContent=p+'%';}
zoomSlider.addEventListener('input',()=>setZoom(parseInt(zoomSlider.value)/100));
document.getElementById('zoom-in').addEventListener('click',()=>setZoom(cam.zoom*1.25));
document.getElementById('zoom-out').addEventListener('click',()=>setZoom(cam.zoom*.8));
let pinchD0=null;
canvas.addEventListener('touchstart',e=>{if(e.touches.length===2)pinchD0=Math.hypot(e.touches[0].clientX-e.touches[1].clientX,e.touches[0].clientY-e.touches[1].clientY);},{passive:true});
canvas.addEventListener('touchmove',e=>{if(e.touches.length===2&&pinchD0!==null){const d=Math.hypot(e.touches[0].clientX-e.touches[1].clientX,e.touches[0].clientY-e.touches[1].clientY);setZoom(cam.zoom*(d/pinchD0));pinchD0=d;}},{passive:true});
canvas.addEventListener('touchend',e=>{if(e.touches.length<2)pinchD0=null;},{passive:true});
// wheel zoom handled by centered-zoom listener below

// ── Grav grid toggle ───────────────────────────────────────────────
const gravBtn=document.getElementById('btn-grav');
gravBtn.addEventListener('click',()=>{
  showGravGrid=!showGravGrid;
  gravBtn.classList.toggle('on',showGravGrid);
  gravCvs.style.display=showGravGrid?'block':'none';
  if(!showGravGrid)gCtx.clearRect(0,0,gravCvs.width,gravCvs.height);
});

// ── Microscópio Quântico ─────────────────────────────────────────────
document.getElementById('btn-microscope').addEventListener('click',()=>{
  if(typeof openMicroscope==='function')openMicroscope();
});
document.getElementById('microscope-close').addEventListener('click',()=>{
  if(typeof closeMicroscope==='function')closeMicroscope();
});
const msZoomSlider=document.getElementById('ms-zoom-slider');
const msZoomLabel=document.getElementById('ms-zoom-label');
function setMicroscopeZoom(z){
  microscopeZoom=clamp(z,0.5,4.0);
  const p=Math.round(microscopeZoom*100);
  msZoomSlider.value=p;
  msZoomLabel.textContent=p+'%';
}
msZoomSlider.addEventListener('input',()=>setMicroscopeZoom(parseInt(msZoomSlider.value)/100));
document.getElementById('ms-zoom-in').addEventListener('click',()=>setMicroscopeZoom(microscopeZoom*1.2));
document.getElementById('ms-zoom-out').addEventListener('click',()=>setMicroscopeZoom(microscopeZoom*0.83));
window.addEventListener('resize',()=>{ if(microscopeActive&&typeof _microscopeResizeCanvas==='function')_microscopeResizeCanvas(); });

// Segurar (mouse/touch) em cima de uma molécula para coletá-la
const microscopeCanvas=document.getElementById('microscope-canvas');
function _msPointerPos(e){
  const rect=microscopeCanvas.getBoundingClientRect();
  const cx=(e.touches?e.touches[0].clientX:e.clientX)-rect.left;
  const cy=(e.touches?e.touches[0].clientY:e.clientY)-rect.top;
  return {x:cx,y:cy};
}
let _msLastTapTime=0,_msLastTapPos=null;
function _msHandleDoubleTap(p){
  const now=performance.now();
  const isDoubleTap=(now-_msLastTapTime<320)&&_msLastTapPos&&Math.hypot(p.x-_msLastTapPos.x,p.y-_msLastTapPos.y)<30;
  _msLastTapTime=now;_msLastTapPos=p;
  if(!isDoubleTap)return;
  const m=_microscopeFindMoleculeAt(p.x,p.y);
  if(m&&typeof openTelescope==='function'){
    closeMicroscope();
    openTelescope(m);
  }
}
// ── Arrastar para mover a câmera (pan) ──────────────────────────────
// Mesmo padrão usado na visão interna (_tsc*): só ativa o pan se o
// ponteiro se mover além de um pequeno limiar, evitando que um toque
// rápido (coleta por hold, duplo toque) seja interpretado como arrasto.
const MS_DRAG_THRESHOLD=6; // px
let _msDragStartPos=null;
let _msDragMoved=false;
let _msDragging=false;
let _msDragLast=null;
function _msPointerDown(p){
  _msDragStartPos=p;
  _msDragMoved=false;
  _msDragging=false;
  _msDragLast=p;
}
function _msPointerMove(p){
  if(!_msDragStartPos)return;
  if(!_msDragMoved){
    const d=Math.hypot(p.x-_msDragStartPos.x,p.y-_msDragStartPos.y);
    if(d<MS_DRAG_THRESHOLD)return;
    _msDragMoved=true;
    _msDragging=true;
    _microscopeEndHold(); // cancela coleta por hold em andamento, já que virou arrasto
  }
  if(!_msDragging||!_msDragLast)return;
  const scale=msCam.zoom;
  msCam.x-=(p.x-_msDragLast.x)/scale;
  msCam.y-=(p.y-_msDragLast.y)/scale;
  _msDragLast=p;
}
function _msPointerUp(){
  _msDragging=false;
  _msDragLast=null;
  _msDragStartPos=null;
  _msDragMoved=false;
}
// Pinça para zoom (mesmo padrão do canvas principal do jogo)
let _msPinchD0=null;
microscopeCanvas.addEventListener('mousedown',e=>{const p=_msPointerPos(e);_microscopeStartHold(p.x,p.y);_msHandleDoubleTap(p);_msPointerDown(p);});
microscopeCanvas.addEventListener('touchstart',e=>{
  if(e.touches.length===2){
    // segundo dedo: vira pinça, cancela pan/hold em andamento
    _msPinchD0=Math.hypot(e.touches[0].clientX-e.touches[1].clientX,e.touches[0].clientY-e.touches[1].clientY);
    _microscopeEndHold();_msPointerUp();
    e.preventDefault();
    return;
  }
  const p=_msPointerPos(e);_microscopeStartHold(p.x,p.y);_msHandleDoubleTap(p);_msPointerDown(p);
  e.preventDefault();
},{passive:false});
microscopeCanvas.addEventListener('mousemove',e=>{if(_msDragStartPos)_msPointerMove(_msPointerPos(e));});
microscopeCanvas.addEventListener('touchmove',e=>{
  if(e.touches.length===2&&_msPinchD0!==null){
    const d=Math.hypot(e.touches[0].clientX-e.touches[1].clientX,e.touches[0].clientY-e.touches[1].clientY);
    setMicroscopeZoom(microscopeZoom*(d/_msPinchD0));
    _msPinchD0=d;
    e.preventDefault();
    return;
  }
  if(_msDragStartPos){_msPointerMove(_msPointerPos(e));e.preventDefault();}
},{passive:false});
microscopeCanvas.addEventListener('mouseup',()=>{_microscopeEndHold();_msPointerUp();});
microscopeCanvas.addEventListener('mouseleave',()=>{_microscopeEndHold();_msPointerUp();});
microscopeCanvas.addEventListener('touchend',e=>{if(e.touches.length<2)_msPinchD0=null;_microscopeEndHold();_msPointerUp();},{passive:true});
microscopeCanvas.addEventListener('touchcancel',()=>{_msPinchD0=null;_microscopeEndHold();_msPointerUp();},{passive:true});

// ── Telescópio Quântico ──────────────────────────────────────────────
document.getElementById('telescope-close').addEventListener('click',()=>{
  if(typeof closeTelescope==='function')closeTelescope();
});
const tscZoomSlider=document.getElementById('tsc-zoom-slider');
document.getElementById('tsc-zoom-in').addEventListener('click',()=>setTelescopeZoom(telescopeCam.zoom*1.2));
document.getElementById('tsc-zoom-out').addEventListener('click',()=>setTelescopeZoom(telescopeCam.zoom*0.83));
tscZoomSlider.addEventListener('input',()=>setTelescopeZoom(parseInt(tscZoomSlider.value)/100));
window.addEventListener('resize',()=>{ if(document.getElementById('telescope-overlay')?.classList.contains('open')&&typeof _telescopeResizeCanvas==='function')_telescopeResizeCanvas(); });

const telescopeCanvas=document.getElementById('telescope-canvas');
function _tscPointerPos(e){
  const rect=telescopeCanvas.getBoundingClientRect();
  const cx=(e.touches?e.touches[0].clientX:e.clientX)-rect.left;
  const cy=(e.touches?e.touches[0].clientY:e.clientY)-rect.top;
  return {x:cx,y:cy};
}
let _tscLastTapTime=0,_tscLastTapPos=null;
function _tscHandleTap(p){
  const now=performance.now();
  const isDoubleTap=(now-_tscLastTapTime<320)&&_tscLastTapPos&&Math.hypot(p.x-_tscLastTapPos.x,p.y-_tscLastTapPos.y)<30;
  _tscLastTapTime=now;_tscLastTapPos=p;
  if(!isDoubleTap)return;
  const el=_telescopeFindElementAt(p.x,p.y);
  if(el){ _telescopeZoomInto(el); }
  else { _telescopeZoomOut(); } // duplo-toque no vazio: volta uma camada
}

// ── Arrastar para mover a câmera (pan) ──────────────────────────────
// Só ativa o pan se o ponteiro se mover além de um pequeno limiar —
// evita que um toque/clique rápido (coleta por hold, duplo toque) seja
// interpretado como arrasto acidental.
const TSC_DRAG_THRESHOLD=6; // px
let _tscDragStartPos=null;
let _tscDragMoved=false;
function _tscPointerDown(p){
  _tscDragStartPos=p;
  _tscDragMoved=false;
  _telescopeDragging=false;
  _telescopeDragLast=p;
}
function _tscPointerMove(p){
  if(!_tscDragStartPos)return;
  if(!_tscDragMoved){
    const d=Math.hypot(p.x-_tscDragStartPos.x,p.y-_tscDragStartPos.y);
    if(d<TSC_DRAG_THRESHOLD)return;
    _tscDragMoved=true;
    _telescopeDragging=true;
    _telescopeEndHold(); // cancela coleta por hold em andamento, já que virou arrasto
  }
  if(!_telescopeDragging||!_telescopeDragLast)return;
  const cvs=telescopeCanvas;
  const scale=Math.min(cvs.width,cvs.height)*telescopeCam.zoom;
  telescopeCam.x-=(p.x-_telescopeDragLast.x)/scale;
  telescopeCam.y-=(p.y-_telescopeDragLast.y)/scale;
  _telescopeDragLast=p;
}
function _tscPointerUp(p){
  // Só trata como toque/duplo-toque se o gesto NÃO virou arrasto —
  // antes disso rodava no pointerDown e um drag real era lido como clique.
  if(!_tscDragMoved&&p)_tscHandleTap(p);
  _telescopeDragging=false;
  _telescopeDragLast=null;
  _tscDragStartPos=null;
  _tscDragMoved=false;
}
// Pinça para zoom (mesmo padrão do canvas principal do jogo)
let _tscPinchD0=null;
telescopeCanvas.addEventListener('mousedown',e=>{const p=_tscPointerPos(e);_telescopeStartHold(p.x,p.y);_tscPointerDown(p);});
telescopeCanvas.addEventListener('touchstart',e=>{
  if(e.touches.length===2){
    _tscPinchD0=Math.hypot(e.touches[0].clientX-e.touches[1].clientX,e.touches[0].clientY-e.touches[1].clientY);
    _telescopeEndHold();_tscPointerUp(null);
    e.preventDefault();
    return;
  }
  const p=_tscPointerPos(e);_telescopeStartHold(p.x,p.y);_tscPointerDown(p);
  e.preventDefault();
},{passive:false});
telescopeCanvas.addEventListener('mousemove',e=>{if(_tscDragStartPos)_tscPointerMove(_tscPointerPos(e));});
telescopeCanvas.addEventListener('touchmove',e=>{
  if(e.touches.length===2&&_tscPinchD0!==null){
    const d=Math.hypot(e.touches[0].clientX-e.touches[1].clientX,e.touches[0].clientY-e.touches[1].clientY);
    setTelescopeZoom(telescopeCam.zoom*(d/_tscPinchD0));
    _tscPinchD0=d;
    e.preventDefault();
    return;
  }
  if(_tscDragStartPos){_tscPointerMove(_tscPointerPos(e));e.preventDefault();}
},{passive:false});
telescopeCanvas.addEventListener('mouseup',e=>{_telescopeEndHold();_tscPointerUp(_tscPointerPos(e));});
telescopeCanvas.addEventListener('mouseleave',()=>{_telescopeEndHold();_tscPointerUp(null);});
telescopeCanvas.addEventListener('touchend',e=>{if(e.touches.length<2)_tscPinchD0=null;_telescopeEndHold();_tscPointerUp(_tscDragStartPos);},{passive:true});
telescopeCanvas.addEventListener('touchcancel',()=>{_tscPinchD0=null;_telescopeEndHold();_tscPointerUp(null);},{passive:true});



// ═══════════════════════════════════════════════════════════════════
//  SCREEN NAVIGATION
// ═══════════════════════════════════════════════════════════════════
function showScreen(id){
  document.querySelectorAll('.screen').forEach(s=>s.classList.toggle('hidden',s.id!==id));
  currentScreen=id;
  const inGame=(id==='game');
  const tb=document.getElementById('toolbar');
  const zb=document.getElementById('zoom-bar');
  const hud=document.getElementById('hud');
  const mb=document.getElementById('mode-badge');
  const tt=document.getElementById('tooltip');
  if(hud)hud.style.display=inGame?'flex':'none';
  if(mb) mb.style.display=inGame?'block':'none';
  if(tb) tb.style.display=inGame?'flex':'none';
  if(zb) zb.style.display=inGame?'flex':'none';
  if(tt) tt.style.display=inGame?'':'none';
  canvas.style.display=inGame?'block':'none';
  gravCvs.style.display=inGame&&showGravGrid?'block':'none';
  // Retoma a animação de fundo do menu se voltamos para uma tela não-jogo
  // (ela se auto-pausa quando escondida — ver drawMenuStars).
  if(!inGame&&window._resumeMenuStars) window._resumeMenuStars();
}
['hud','mode-badge','zoom-bar','toolbar','tooltip'].forEach(eid=>{const el=document.getElementById(eid);if(el)el.style.display='none';});
canvas.style.display='none';gravCvs.style.display='none';
