// Aplica visual de bloqueio nos modos Sandbox e Exploração antes do tutorial
(function _applyPreTutorialLocks(){
  function _isTutDone(){try{return !!localStorage.getItem('cosmos_sim_tutorial_done_v1');}catch(e){return false;}}
  function _refresh(){
    const done=_isTutDone();
    const sbCard=document.getElementById('btn-mode-sandbox');
    const exCard=document.getElementById('btn-mode-explore');
    if(!sbCard||!exCard)return;
    // Sandbox lock
    if(!done){
      sbCard.classList.add('locked-mode');
      if(!sbCard.querySelector('.sb-lock-tag')){
        const t=document.createElement('div');
        t.className='explore-lock-tag sb-lock-tag';
        t.textContent='🔒 Conclua o Tutorial';
        sbCard.appendChild(t);
      }
    } else {
      sbCard.classList.remove('locked-mode');
      const old=sbCard.querySelector('.sb-lock-tag');
      if(old)old.remove();
    }
    // Explore já tem sua própria lógica de rank — apenas adiciona bloqueio de tutorial por cima
    if(!done){
      exCard.classList.add('locked-mode');
      if(!exCard.querySelector('.ex-tut-lock-tag')){
        const t=document.createElement('div');
        t.className='explore-lock-tag ex-tut-lock-tag';
        t.style.top='28px';
        t.textContent='🔒 Conclua o Tutorial';
        exCard.appendChild(t);
      }
    } else {
      const old=exCard.querySelector('.ex-tut-lock-tag');
      if(old)old.remove();
      // Deixa a lógica de rank do explore decidir
    }
  }
  _refresh();
  // Re-verifica cada vez que a mode-screen é exibida
  const _origSS2=showScreen;
  const _patchedSS2=function(id){_origSS2(id);if(id==='mode-screen')_refresh();};
  // Não re-patcha showScreen aqui, usamos evento
  document.getElementById('mode-screen').addEventListener('transitionend',_refresh,{passive:true});
  // Também atualiza após tutorial concluído
  window._refreshModeLocks=_refresh;
})();
function _isTutorialDoneForLock(){
  try{return !!localStorage.getItem('cosmos_sim_tutorial_done_v1');}catch(e){return true;}
}

// ═══════════════════════════════════════════════════════════════════
//  INTERNAL STORAGE — persiste Rank entre sessões
// ═══════════════════════════════════════════════════════════════════
const STORAGE_KEY='cosmos_sim_internal_v1';

// Sistema legado unificado com o sistema principal (LS_KEY).
// _storageSave delega para _doSaveToLS quando disponível.
function _storageSave(){
  if(typeof _doSaveToLS==='function') _doSaveToLS();
}

function _storageLoad(){
  // Apenas migra dados do STORAGE_KEY legado se LS_KEY ainda não existir.
  try{
    if(localStorage.getItem(LS_KEY))return;
    const raw=localStorage.getItem(STORAGE_KEY);
    if(!raw)return;
    const d=JSON.parse(raw);
    if(d.playerRank&&d.playerRank>playerRank) playerRank=d.playerRank;
    if(Array.isArray(d.mClaimedSnap)) d.mClaimedSnap.forEach(id=>mClaimed.add(id));
  }catch(e){}
}

// Carrega ao iniciar
_storageLoad();

// Salva automaticamente a cada 30s e quando o rank sobe
(function _autoSaveTick(){
  setInterval(()=>{if(sandboxMode||currentScreen==='game')_storageSave();},30000);
})();

// Hook no checkRankUp para salvar ao subir de rank
const _origCheckRankUp=typeof checkRankUp==='function'?checkRankUp:null;
// Será aplicado após checkRankUp ser definido (ver patch abaixo em startGame)

// ═══════════════════════════════════════════════════════════════════
//  EXIT MODAL — botão de saída nos 3 modos
// ═══════════════════════════════════════════════════════════════════
const _exitModal=document.getElementById('exit-modal');

function _showExitModal(onConfirm){
  _exitModal.classList.add('open');
  _exitModal.style.display='flex';
  const yes=document.getElementById('exit-confirm-yes');
  const no =document.getElementById('exit-confirm-no');
  function cleanup(){_exitModal.classList.remove('open');_exitModal.style.display='none';yes.onclick=null;no.onclick=null;}
  yes.onclick=()=>{cleanup();onConfirm();};
  no.onclick =()=>{cleanup();};
}

// Mostra brevemente a tela de carregamento (Cefeida pulsante) e, ao
// final da duração, troca para a tela de destino. Usada nas transições
// de saída de modo — atualmente apenas ao sair da Fase Cósmica, a
// pedido — sem afetar o fluxo normal de troca de telas (showScreen).
function showLoadingTransition(nextScreenId, duration=1400){
  const loadEl=document.getElementById('loading-screen');
  document.querySelectorAll('.screen').forEach(s=>s.classList.toggle('hidden',s.id!=='loading-screen'));
  loadEl.classList.remove('hidden');
  currentScreen='loading-screen';
  ['hud','mode-badge','zoom-bar','toolbar','tooltip'].forEach(eid=>{const el=document.getElementById(eid);if(el)el.style.display='none';});
  canvas.style.display='none';gravCvs.style.display='none';
  setTimeout(()=>{ showScreen(nextScreenId); }, duration);
}

// Botão no HUD (Modo Normal e Sandbox)
document.getElementById('btn-exit-game').addEventListener('click',()=>{
  _showExitModal(()=>{
    _storageSave();
    const wasCosmicPhase=(sandboxMode&&_sandboxPhase==='cosmic');
    // Para o loop, limpa estado
    objects=[];particles=[];
    if(wasCosmicPhase){
      showLoadingTransition('main-screen');
    }else{
      showScreen('main-screen');
    }
  });
});

// Botão de sair da Exploração já existente — agora usa o modal
document.getElementById('exp-back').addEventListener('click',()=>{
  _showExitModal(()=>{
    EXP.stop();
    _storageSave();
    showScreen('main-screen');
  });
});

// ═══════════════════════════════════════════════════════════════════
//  EXPLORATION MODE — setup and rank gate
// ═══════════════════════════════════════════════════════════════════
(function setupExploreCard(){
  const EXPLORE_RANK=25;
  const card=document.getElementById('btn-mode-explore');
  const desc=document.getElementById('explore-mode-desc');

  function refreshExploreCard(){
    const unlocked=playerRank>=EXPLORE_RANK;
    card.classList.toggle('locked-mode',!unlocked);
    // Remove old lock tag if any
    const old=card.querySelector('.explore-lock-tag');
    if(old)old.remove();
    if(!unlocked){
      const tag=document.createElement('div');
      tag.className='explore-lock-tag';
      tag.textContent='🔒 Rank '+EXPLORE_RANK;
      card.appendChild(tag);
      desc.textContent='Desbloqueie no Rank '+EXPLORE_RANK+' do Modo Sandbox para viajar pelo universo em 3D simulado.';
    } else {
      desc.textContent='Viaje pelo universo em 3D simulado. Explore planetas, estrelas e astros raros. Descubra mundos e registre o cosmos.';
    }
  }
  refreshExploreCard();

  card.addEventListener('click',()=>{
    if(playerRank<EXPLORE_RANK){
      // Flash the lock tag
      const tag=card.querySelector('.explore-lock-tag');
      if(tag){tag.style.background='rgba(255,212,59,.3)';setTimeout(()=>tag.style.background='rgba(255,212,59,.12)',400);}
      return;
    }
    startExploreMode();
  });

  // Refresh whenever mode-screen is shown
  const _origShowScreen=showScreen;
  // Patch showScreen to refresh card
  const _patchedShow=window.showScreen=function(id){
    _origShowScreen(id);
    if(id==='mode-screen')refreshExploreCard();
  };
})();

