document.getElementById('btn-quit').addEventListener('click',()=>{
  if(window.close){try{window.close();}catch(e){}}
  window.location.href='about:blank';
});

// ── Menu card mini-animations ─────────────────────────────────────
(function initMenuCards(){
  // Estrela com planetas — card Criar
  const cc=document.getElementById('mc-canvas-create');
  if(cc){
    const cx2=cc.getContext('2d');
    let t=0;
    function drawCreate(){
      cc.width=80;cc.height=66;
      cx2.clearRect(0,0,80,66);
      const sx=40,sy=33;
      // Halo da estrela
      const sg=cx2.createRadialGradient(sx,sy,0,sx,sy,22);
      sg.addColorStop(0,'rgba(123,232,255,0.18)');sg.addColorStop(1,'transparent');
      cx2.beginPath();cx2.arc(sx,sy,22,0,Math.PI*2);cx2.fillStyle=sg;cx2.fill();
      // Estrela
      const starG=cx2.createRadialGradient(sx-2,sy-2,0,sx,sy,9);
      starG.addColorStop(0,'#ffffff');starG.addColorStop(.35,'#aaeeff');
      starG.addColorStop(1,'rgba(80,200,255,.3)');
      cx2.beginPath();cx2.arc(sx,sy,9,0,Math.PI*2);cx2.fillStyle=starG;cx2.fill();
      // Planetas
      [[16,0.8,3.2,'#4488ff'],[24,1.3,2.5,'#88cc44'],[31,0.5,1.8,'#ffaa33']].forEach(([r,spd,pR,col])=>{
        const a=t*spd;
        const px=sx+Math.cos(a)*r, py=sy+Math.sin(a)*r*.35;
        cx2.beginPath();cx2.arc(px,py,pR,0,Math.PI*2);cx2.fillStyle=col;cx2.fill();
      });
      t+=0.025;requestAnimationFrame(drawCreate);
    }
    drawCreate();
  }

  // Galáxia espiral — card Importar
  const ci=document.getElementById('mc-canvas-import');
  if(ci){
    const ix=ci.getContext('2d');
    let t2=0;
    function drawImport(){
      ci.width=80;ci.height=66;
      ix.clearRect(0,0,80,66);
      const sx=40,sy=33;
      for(let i=0;i<60;i++){
        const arm=i%2;
        const frac=i/60;
        const a=frac*Math.PI*3+(arm*Math.PI)+t2;
        const r=frac*24;
        const px=sx+Math.cos(a)*r, py=sy+Math.sin(a)*r*.45;
        const alpha=frac*.7+.1;
        ix.beginPath();ix.arc(px,py,1.1,0,Math.PI*2);
        ix.fillStyle=`rgba(255,212,59,${alpha})`;ix.fill();
      }
      // Núcleo brilhante
      const ng=ix.createRadialGradient(sx,sy,0,sx,sy,6);
      ng.addColorStop(0,'rgba(255,240,160,0.9)');ng.addColorStop(1,'transparent');
      ix.beginPath();ix.arc(sx,sy,6,0,Math.PI*2);ix.fillStyle=ng;ix.fill();
      t2+=0.018;requestAnimationFrame(drawImport);
    }
    drawImport();
  }

  // Documento JSON entrando — card Carregar Save
  const cij=document.getElementById('mc-canvas-import-json');
  if(cij){
    const ixj=cij.getContext('2d');
    let t2b=0;
    function drawImportJson(){
      cij.width=80;cij.height=66;
      ixj.clearRect(0,0,80,66);
      const sx=40,sy=33;
      const hg=ixj.createRadialGradient(sx,sy,0,sx,sy,20);
      hg.addColorStop(0,'rgba(255,212,59,0.14)');hg.addColorStop(1,'transparent');
      ixj.beginPath();ixj.arc(sx,sy,20,0,Math.PI*2);ixj.fillStyle=hg;ixj.fill();
      const dw=22,dh=28,dx=sx-dw/2,dy=sy-dh/2+2;
      const bob=Math.sin(t2b*1.4)*2;
      ixj.save();ixj.translate(0,bob);
      ixj.beginPath();
      ixj.moveTo(dx,dy);
      ixj.lineTo(dx+dw-7,dy);
      ixj.lineTo(dx+dw,dy+7);
      ixj.lineTo(dx+dw,dy+dh);
      ixj.lineTo(dx,dy+dh);
      ixj.closePath();
      ixj.fillStyle='rgba(255,212,59,.12)';ixj.fill();
      ixj.strokeStyle='rgba(255,212,59,.7)';ixj.lineWidth=1.4;ixj.stroke();
      ixj.beginPath();
      ixj.moveTo(dx+dw-7,dy);ixj.lineTo(dx+dw-7,dy+7);ixj.lineTo(dx+dw,dy+7);
      ixj.strokeStyle='rgba(255,212,59,.5)';ixj.lineWidth=1;ixj.stroke();
      ixj.strokeStyle='rgba(255,212,59,.4)';ixj.lineWidth=1.2;
      [0,5,10,15].forEach(off=>{
        ixj.beginPath();ixj.moveTo(dx+3,dy+13+off);ixj.lineTo(dx+dw-3-(off===15?7:0),dy+13+off);ixj.stroke();
      });
      ixj.restore();
      const arrowY=sy+dh/2+8+Math.sin(t2b*2)*1.5;
      ixj.beginPath();
      ixj.moveTo(sx-5,arrowY-4);ixj.lineTo(sx,arrowY);ixj.lineTo(sx+5,arrowY-4);
      ixj.strokeStyle='rgba(255,212,59,.65)';ixj.lineWidth=1.6;ixj.lineCap='round';ixj.lineJoin='round';ixj.stroke();
      t2b+=0.03;requestAnimationFrame(drawImportJson);
    }
    drawImportJson();
  }

  // Pilha de discos locais — card Salvamentos Locais
  const cls=document.getElementById('mc-canvas-local-saves');
  if(cls){
    const lx=cls.getContext('2d');
    let t4=0;
    function drawLocalSaves(){
      cls.width=80;cls.height=66;
      lx.clearRect(0,0,80,66);
      const sx=40,sy=33;
      const hg=lx.createRadialGradient(sx,sy,0,sx,sy,20);
      hg.addColorStop(0,'rgba(200,120,255,0.14)');hg.addColorStop(1,'transparent');
      lx.beginPath();lx.arc(sx,sy,20,0,Math.PI*2);lx.fillStyle=hg;lx.fill();
      // Pilha de 3 discos empilhados (elipses), leve flutuação individual
      const discs=[[0,10],[1,0],[2,-10]];
      discs.forEach(([i,dyOff])=>{
        const bob=Math.sin(t4*1.3+i*1.1)*1.2;
        const dy=sy+dyOff+bob;
        const rw=17-i*1.2, rh=6;
        lx.beginPath();lx.ellipse(sx,dy,rw,rh,0,0,Math.PI*2);
        lx.fillStyle=`rgba(200,120,255,${.10+i*.05})`;lx.fill();
        lx.strokeStyle=`rgba(200,120,255,${.55+i*.1})`;lx.lineWidth=1.3;lx.stroke();
        // fenda central do disco
        lx.beginPath();lx.ellipse(sx,dy,rw*.32,rh*.4,0,0,Math.PI*2);
        lx.strokeStyle=`rgba(200,120,255,${.4+i*.1})`;lx.lineWidth=1;lx.stroke();
      });
      // Luz de leitura piscando no disco de cima
      const blink=(Math.sin(t4*4)+1)/2;
      lx.beginPath();lx.arc(sx+13,sy-10,1.4,0,Math.PI*2);
      lx.fillStyle=`rgba(120,255,180,${.35+blink*.55})`;lx.fill();
      t4+=0.025;requestAnimationFrame(drawLocalSaves);
    }
    drawLocalSaves();
  }

  // Engrenagem cósmica — card Configurações
  const cs2=document.getElementById('mc-canvas-settings');
  if(cs2){
    const sx2=cs2.getContext('2d');
    let t3=0;
    function drawSettings(){
      cs2.width=80;cs2.height=66;
      sx2.clearRect(0,0,80,66);
      const cx3=40,cy3=33,R=16,r2=10,teeth=8;
      // Órbitas decorativas
      for(let i=0;i<3;i++){
        const orR=6+i*7;
        sx2.beginPath();sx2.arc(cx3,cy3,orR,0,Math.PI*2);
        sx2.strokeStyle=`rgba(200,120,255,${.08+i*.04})`;sx2.lineWidth=1;sx2.stroke();
        // ponto orbital
        const oa=t3*(1.5-i*.4)+i*2.1;
        const opx=cx3+Math.cos(oa)*orR, opy=cy3+Math.sin(oa)*orR*.6;
        sx2.beginPath();sx2.arc(opx,opy,1.5,0,Math.PI*2);
        sx2.fillStyle=`rgba(200,120,255,${.5+i*.1})`;sx2.fill();
      }
      // Engrenagem
      sx2.save();sx2.translate(cx3,cy3);sx2.rotate(t3*.4);
      sx2.beginPath();
      for(let i=0;i<teeth*2;i++){
        const a=(i/teeth)*Math.PI;
        const rad=(i%2===0)?R:r2;
        const px2=Math.cos(a)*rad, py2=Math.sin(a)*rad;
        i===0?sx2.moveTo(px2,py2):sx2.lineTo(px2,py2);
      }
      sx2.closePath();
      sx2.strokeStyle='rgba(200,120,255,.55)';sx2.lineWidth=1.5;sx2.stroke();
      sx2.fillStyle='rgba(200,120,255,.07)';sx2.fill();
      // Centro
      sx2.beginPath();sx2.arc(0,0,5,0,Math.PI*2);
      sx2.fillStyle='rgba(200,120,255,.5)';sx2.fill();
      sx2.restore();
      t3+=0.022;requestAnimationFrame(drawSettings);
    }
    drawSettings();
  }

  // Menu stars background
  const ms=document.getElementById('menu-stars');
  if(ms){
    const mctx=ms.getContext('2d');
    let mT=0;
    const mStars=Array.from({length:120},()=>({
      x:Math.random(),y:Math.random(),
      r:.4+Math.random()*.9,
      phase:Math.random()*Math.PI*2,
      spd:.3+Math.random()*.7,
    }));
    function drawMenuStars(){
      // Otimização: para de rodar (e de pedir novo frame) assim que a tela
      // de menu não estiver mais visível — antes rodava para sempre, mesmo
      // durante o jogo/invasões, competindo por CPU com o loop principal.
      if(ms.offsetParent===null){
        window._menuStarsRAF=null;
        return;
      }
      ms.width=ms.offsetWidth||window.innerWidth;
      ms.height=ms.offsetHeight||window.innerHeight;
      mctx.clearRect(0,0,ms.width,ms.height);
      mStars.forEach(s=>{
        const a=.15+.12*Math.sin(mT*s.spd+s.phase);
        mctx.beginPath();mctx.arc(s.x*ms.width,s.y*ms.height,s.r,0,Math.PI*2);
        mctx.fillStyle=`rgba(255,255,255,${a})`;mctx.fill();
      });
      mT+=0.012;window._menuStarsRAF=requestAnimationFrame(drawMenuStars);
    }
    window._resumeMenuStars=function(){
      if(!window._menuStarsRAF) drawMenuStars();
    };
    drawMenuStars();
  }
})();

// ── Configurações — listeners ─────────────────────────────────────
(function initSettings(){
  // Volume ambiente
  const va=document.getElementById('cfg-vol-ambient');
  const vaV=document.getElementById('cfg-vol-ambient-val');
  va.addEventListener('input',()=>{
    vaV.textContent=va.value+'%';
    if(typeof AudioSys!=='undefined')AudioSys.setVolAmbient(va.value/100);
  });
  // Volume astros
  const vas=document.getElementById('cfg-vol-astros');
  const vasV=document.getElementById('cfg-vol-astros-val');
  vas.addEventListener('input',()=>{
    vasV.textContent=vas.value+'%';
    if(typeof AudioSys!=='undefined')AudioSys.setVolAstros(vas.value/100);
  });
  // Partículas
  const cp=document.getElementById('cfg-particles');
  const cpV=document.getElementById('cfg-particles-val');
  cp.addEventListener('input',()=>{cpV.textContent=cp.value+'%';window._particleScale=cp.value/100;});
  // Malha grav
  document.getElementById('cfg-grav-grid').addEventListener('change',e=>{
    showGravGrid=e.target.checked;
    if(gravCvs)gravCvs.style.display=(showGravGrid&&currentScreen==='game')?'block':'none';
  });
  // FPS counter
  document.getElementById('cfg-fps').addEventListener('change',e=>{
    const el=document.getElementById('fps-counter');
    if(el)el.style.display=e.target.checked?'block':'none';
  });
  // Coords
  document.getElementById('cfg-coords').addEventListener('change',e=>{
    const el=document.getElementById('cam-coords');
    if(el)el.style.display=e.target.checked?'block':'none';
  });
  // Velocidade simulação
  const sv=document.getElementById('cfg-sim-speed');
  const svV=document.getElementById('cfg-sim-speed-val');
  sv.addEventListener('input',()=>{
    const mult=sv.value/100;
    svV.textContent=mult.toFixed(1)+'×';
    window._simSpeed=mult;
  });
  // Modo escuro+
  document.getElementById('cfg-dark-plus').addEventListener('change',e=>{
    document.body.classList.toggle('dark-plus',e.target.checked);
  });

  // ── Setas de scroll da toolbar (Desktop/TV/Landscape) ──
  (function(){
    const chk=document.getElementById('cfg-tb-scroll');
    const wrap=document.getElementById('tb-scroll-wrap');

    function applyTbScroll(on){
      document.body.classList.toggle('no-tb-scroll',!on);
    }
    chk.addEventListener('change',e=>applyTbScroll(e.target.checked));
    applyTbScroll(chk.checked);

    let _scrollIv=null;

    function doScroll(dir){
      const tb=document.getElementById('toolbar');
      if(!tb)return;
      // Em desktop/landscape a toolbar é vertical → scrollTop
      // Em landscape horizontal → scrollLeft (fallback)
      if(tb.scrollHeight>tb.clientHeight){
        tb.scrollTop+=dir*52;
      } else {
        tb.scrollLeft+=dir*52;
      }
    }
    function startScroll(dir){
      doScroll(dir);
      _scrollIv=setInterval(()=>doScroll(dir),110);
    }
    function stopScroll(){if(_scrollIv){clearInterval(_scrollIv);_scrollIv=null;}}

    ['tb-scroll-up','tb-scroll-dn'].forEach(id=>{
      const btn=document.getElementById(id);
      if(!btn)return;
      const dir=id==='tb-scroll-dn'?1:-1;
      btn.addEventListener('mousedown',e=>{e.preventDefault();startScroll(dir);});
      btn.addEventListener('touchstart',e=>{e.preventDefault();startScroll(dir);},{passive:false});
      btn.addEventListener('touchend',e=>{e.preventDefault();stopScroll();});
      btn.addEventListener('touchcancel',stopScroll);
      btn.addEventListener('click',()=>doScroll(dir));
    });
    window.addEventListener('mouseup',stopScroll);

    // Reposicionar o wrapper sempre que o modo muda (desktop/landscape)
    function repositionWrap(){
      if(!wrap)return;
      const isLandscape=document.body.classList.contains('landscape-mode');
      const isDesktop  =document.body.classList.contains('desktop-mode');
      if(isLandscape){
        // Toolbar landscape: 60px de largura, posição left=60
        wrap.style.left='64px';
      } else if(isDesktop){
        // Toolbar desktop: 72px de largura
        wrap.style.left='76px';
      }
    }

    // Observa mudanças de classe no body para reposicionar
    const obs=new MutationObserver(repositionWrap);
    obs.observe(document.body,{attributes:true,attributeFilter:['class']});
    repositionWrap();
  })();
  // Redefinir
  document.getElementById('cfg-reset-btn').addEventListener('click',()=>{
    va.value=100;vaV.textContent='100%';
    vas.value=100;vasV.textContent='100%';
    cp.value=100;cpV.textContent='100%';
    sv.value=100;svV.textContent='1.0×';
    document.getElementById('cfg-fps').checked=true;
    document.getElementById('cfg-coords').checked=true;
    document.getElementById('cfg-grav-grid').checked=false;
    document.getElementById('cfg-dark-plus').checked=false;
    document.getElementById('cfg-tb-scroll').checked=true;
    document.body.classList.remove('no-tb-scroll');
    if(typeof AudioSys!=='undefined'){AudioSys.setVolAmbient(1);AudioSys.setVolAstros(1);}
    window._particleScale=1;window._simSpeed=1;
    showGravGrid=false;
  });
})();

// ═══════════════════════════════════════════════════════════════════
//  INFINITE CHUNK BACKGROUND
// ═══════════════════════════════════════════════════════════════════
const CHUNK=256,SPR=20,chunkCache=new Map();
function chunkHash(cx,cy){let s=(cx*73856093)^(cy*19349663);s=((s>>>16)^s)*0x45d9f3b|0;s=((s>>>16)^s)*0x45d9f3b|0;return(s>>>16)^s;}
function getChunkStars(cx,cy){
  const key=`${cx},${cy}`;if(chunkCache.has(key))return chunkCache.get(key);
  let seed=chunkHash(cx,cy);const lcg=()=>{seed=(seed*1664525+1013904223)&0xffffffff;return(seed>>>0)/0xffffffff;};
  const stars=[];for(let i=0;i<SPR;i++)stars.push({lx:lcg()*CHUNK,ly:lcg()*CHUNK,r:.3+lcg()*1.3,alpha:.15+lcg()*.75,phase:lcg()*Math.PI*2,speed:.003+lcg()*.012});
  chunkCache.set(key,stars);if(chunkCache.size>600){const k=[...chunkCache.keys()];for(let i=0;i<80;i++)chunkCache.delete(k[i]);}
  return stars;
}
function drawBgStars(t){
  const iz=1/cam.zoom,pad=CHUNK;
  const x0=cam.x-(canvas.width*.5)*iz-pad,y0=cam.y-(canvas.height*.5)*iz-pad;
  const x1=cam.x+(canvas.width*.5)*iz+pad,y1=cam.y+(canvas.height*.5)*iz+pad;
  // Durante o Eclipse do Núcleo Dimensional, as estrelas de fundo (o campo
  // decorativo do céu, não os astros comuns) ficam vermelhas.
  const _starColor=_eclipseActive?'255,60,40':'255,255,255';
  for(let cy=Math.floor(y0/CHUNK);cy<=Math.ceil(y1/CHUNK);cy++)
    for(let cx=Math.floor(x0/CHUNK);cx<=Math.ceil(x1/CHUNK);cx++){
      const ox=cx*CHUNK,oy=cy*CHUNK;
      getChunkStars(cx,cy).forEach(s=>{
        const sc=worldToScreen(ox+s.lx,oy+s.ly);
        ctx.beginPath();ctx.arc(sc.x,sc.y,s.r,0,Math.PI*2);
        ctx.fillStyle=`rgba(${_starColor},${s.alpha*(.5+.5*Math.sin(t*s.speed*10+s.phase))})`;ctx.fill();
      });
    }
}

// ═══════════════════════════════════════════════════════════════════
//  EVC BACKGROUND — Fundo astronômico de alta fidelidade 4K
//  Ativo apenas quando _isEvcActive() === true
//  Camadas: nebulosas, galáxias distantes, cometas de fundo,
//           filamentos cósmicos, pó interestelar, chuva de meteoros
// ═══════════════════════════════════════════════════════════════════

// ── Seed hash reutilizando o mesmo sistema de chunks ─────────────
const EVC_CHUNK=512;
const evcNebulaCache=new Map(),evcGalaxyCache=new Map(),evcCometCache=new Map();

function _evcHash(cx,cy,salt=0){
  let s=(cx*73856093)^(cy*19349663)^(salt*2654435761);
  s=((s>>>16)^s)*0x45d9f3b|0;s=((s>>>16)^s)*0x45d9f3b|0;return(s>>>16)^s;
}
function _evcLCG(seed){
  let s=seed|0;
  return ()=>{s=(s*1664525+1013904223)&0xffffffff;return(s>>>0)/0xffffffff;};
}

// ── Chunk de Nebulosas (3–5 por chunk de 512u) ───────────────────
function _getEvcNebulas(cx,cy){
  const key=`${cx},${cy}`;
  if(evcNebulaCache.has(key))return evcNebulaCache.get(key);
  const rng=_evcLCG(_evcHash(cx,cy,1));
  const count=2+Math.floor(rng()*3);           // 2–4 nebulosas por chunk
  const nebulas=[];
  const palettes=[
    ['rgba(120,40,200,','rgba(200,80,255,','rgba(60,0,120,'],  // violeta/púrpura
    ['rgba(20,80,200,', 'rgba(60,160,255,','rgba(0,40,120,'],  // azul nebulosa
    ['rgba(200,60,20,', 'rgba(255,130,40,','rgba(140,20,0,'],  // vermelho/laranja
    ['rgba(20,160,120,','rgba(60,255,180,','rgba(0,80,60,'],   // verde-ciano
    ['rgba(200,160,20,','rgba(255,210,80,','rgba(100,60,0,'],  // dourado
    ['rgba(180,20,80,', 'rgba(255,80,160,','rgba(80,0,40,'],   // rosa/carmim
  ];
  for(let i=0;i<count;i++){
    const pal=palettes[Math.floor(rng()*palettes.length)];
    nebulas.push({
      lx:rng()*EVC_CHUNK, ly:rng()*EVC_CHUNK,
      rx:(60+rng()*220)*cam.zoom||1,   // raio X (recalculado no draw)
      ry:(40+rng()*160)*cam.zoom||1,   // raio Y
      rxBase:60+rng()*220,
      ryBase:40+rng()*160,
      rot:rng()*Math.PI*2,
      alpha:0.04+rng()*0.13,
      pal,
      layers:2+Math.floor(rng()*3),
      phase:rng()*Math.PI*2,
      speed:0.0002+rng()*0.0006,
      tendrils:Math.floor(rng()*4),    // 0–3 braços filamentosos
    });
  }
  evcNebulaCache.set(key,nebulas);
  if(evcNebulaCache.size>300){const k=[...evcNebulaCache.keys()];for(let i=0;i<60;i++)evcNebulaCache.delete(k[i]);}
  return nebulas;
}

// ── Chunk de Galáxias Distantes (1–3 por chunk de 512u) ──────────
function _getEvcGalaxies(cx,cy){
  const key=`${cx},${cy}`;
  if(evcGalaxyCache.has(key))return evcGalaxyCache.get(key);
  const rng=_evcLCG(_evcHash(cx,cy,7));
  const count=Math.floor(rng()*3);   // 0–2 galáxias por chunk (menos densas)
  const types=['spiral','elliptical','lenticular','irregular'];
  const galaxies=[];
  for(let i=0;i<count;i++){
    galaxies.push({
      lx:rng()*EVC_CHUNK, ly:rng()*EVC_CHUNK,
      sizeBase:8+rng()*28,
      rot:rng()*Math.PI*2,
      tilt:0.18+rng()*0.55,
      alpha:0.07+rng()*0.18,
      arms:2+Math.floor(rng()*3),
      type:types[Math.floor(rng()*types.length)],
      hue:Math.floor(rng()*360),
      phase:rng()*Math.PI*2,
      speed:0.00015+rng()*0.0003,
    });
  }
  evcGalaxyCache.set(key,galaxies);
  if(evcGalaxyCache.size>300){const k=[...evcGalaxyCache.keys()];for(let i=0;i<60;i++)evcGalaxyCache.delete(k[i]);}
  return galaxies;
}

// ── Cometas de Fundo — estado global, animados ───────────────────
const _evcBgComets=[];
const _EVC_COMET_MAX=28;
function _evcInitBgComets(){
  if(_evcBgComets.length>0)return;
  for(let i=0;i<_EVC_COMET_MAX;i++) _evcSpawnBgComet(true);
}
function _evcSpawnBgComet(init=false){
  const W=canvas.width,H=canvas.height;
  const angle=Math.random()*Math.PI*2;
  // Spawn na borda da tela
  const side=Math.floor(Math.random()*4);
  let sx,sy;
  if(side===0){sx=Math.random()*W;sy=-20;}
  else if(side===1){sx=W+20;sy=Math.random()*H;}
  else if(side===2){sx=Math.random()*W;sy=H+20;}
  else{sx=-20;sy=Math.random()*H;}
  const spd=0.18+Math.random()*0.55;
  const dir=Math.atan2(H/2-sy,W/2-sx)+( Math.random()-.5)*1.2;
  _evcBgComets.push({
    x:init?Math.random()*W:sx,
    y:init?Math.random()*H:sy,
    vx:Math.cos(dir)*spd, vy:Math.sin(dir)*spd,
    len:40+Math.random()*120,
    alpha:0.06+Math.random()*0.18,
    r:0.4+Math.random()*1.1,
    hue:180+Math.floor(Math.random()*120),
    life:1, dead:false,
  });
}

// ── Filamentos / Véu Cósmico ─────────────────────────────────────
const _evcFilaments=[];
function _evcInitFilaments(){
  if(_evcFilaments.length>0)return;
  for(let i=0;i<22;i++){
    const cx=( Math.random()-.5)*4000, cy=(Math.random()-.5)*4000;
    const len=400+Math.random()*1200;
    const angle=Math.random()*Math.PI;
    const pts=[];
    for(let j=0;j<8;j++){
      pts.push({
        ox:cx+Math.cos(angle)*len*(j/7)+( Math.random()-.5)*200,
        oy:cy+Math.sin(angle)*len*(j/7)+( Math.random()-.5)*200,
      });
    }
    _evcFilaments.push({
      pts, alpha:0.018+Math.random()*0.045,
      hue:180+Math.floor(Math.random()*160),
      width:1+Math.random()*2.5,
      phase:Math.random()*Math.PI*2,
      speed:0.00012+Math.random()*0.0003,
    });
  }
}

// ── Poeira Interestelar (dust lanes) ─────────────────────────────
const _evcDustChunkCache=new Map();
function _getEvcDust(cx,cy){
  const key=`${cx},${cy}`;
  if(_evcDustChunkCache.has(key))return _evcDustChunkCache.get(key);
  const rng=_evcLCG(_evcHash(cx,cy,13));
  const count=Math.floor(rng()*4);
  const dust=[];
  for(let i=0;i<count;i++){
    dust.push({
      lx:rng()*EVC_CHUNK, ly:rng()*EVC_CHUNK,
      rBase:30+rng()*90,
      alpha:0.015+rng()*0.045,
      hue:Math.floor(20+rng()*60),    // marrom-alaranjado
      rot:rng()*Math.PI*2,
    });
  }
  _evcDustChunkCache.set(key,dust);
  if(_evcDustChunkCache.size>300){const k=[...(_evcDustChunkCache.keys())];for(let i=0;i<60;i++)_evcDustChunkCache.delete(k[i]);}
  return dust;
}

// ── Chuva de Microestrelas EVC (camada densa extra) ──────────────
const evcDenseStarCache=new Map();
function _getEvcDenseStars(cx,cy){
  const key=`${cx},${cy}`;
  if(evcDenseStarCache.has(key))return evcDenseStarCache.get(key);
  const rng=_evcLCG(_evcHash(cx,cy,17));
  const stars=[];
  for(let i=0;i<60;i++){   // 60 microestrelas extras por chunk
    stars.push({
      lx:rng()*EVC_CHUNK, ly:rng()*EVC_CHUNK,
      r:0.15+rng()*0.7,
      alpha:0.08+rng()*0.55,
      phase:rng()*Math.PI*2,
      speed:0.002+rng()*0.008,
      // cor: branco, azulado, avermelhado
      hue:Math.random()<0.5?220+Math.floor(rng()*60):10+Math.floor(rng()*20),
      sat:rng()<0.4?80:0,
    });
  }
  evcDenseStarCache.set(key,stars);
  if(evcDenseStarCache.size>400){const k=[...evcDenseStarCache.keys()];for(let i=0;i<80;i++)evcDenseStarCache.delete(k[i]);}
  return stars;
}

// ── DRAW PRINCIPAL EVC ───────────────────────────────────────────
function drawEvcBackground(t){
  const iz=1/cam.zoom;
  const x0=cam.x-(canvas.width*.5)*iz-EVC_CHUNK;
  const y0=cam.y-(canvas.height*.5)*iz-EVC_CHUNK;
  const x1=cam.x+(canvas.width*.5)*iz+EVC_CHUNK;
  const y1=cam.y+(canvas.height*.5)*iz+EVC_CHUNK;
  const cxMin=Math.floor(x0/EVC_CHUNK), cxMax=Math.ceil(x1/EVC_CHUNK);
  const cyMin=Math.floor(y0/EVC_CHUNK), cyMax=Math.ceil(y1/EVC_CHUNK);

  // ── 1) CAMADA DENSA DE MICROESTRELAS ──────────────────────────
  for(let cy=cyMin;cy<=cyMax;cy++){
    for(let cx=cxMin;cx<=cxMax;cx++){
      const ox=cx*EVC_CHUNK, oy=cy*EVC_CHUNK;
      _getEvcDenseStars(cx,cy).forEach(s=>{
        const sc=worldToScreen(ox+s.lx,oy+s.ly);
        const flicker=0.5+0.5*Math.sin(t*s.speed*14+s.phase);
        const a=s.alpha*flicker;
        if(s.sat>0){
          ctx.beginPath();ctx.arc(sc.x,sc.y,s.r,0,Math.PI*2);
          ctx.fillStyle=`hsla(${s.hue},${s.sat}%,90%,${a})`;ctx.fill();
        } else {
          ctx.beginPath();ctx.arc(sc.x,sc.y,s.r,0,Math.PI*2);
          ctx.fillStyle=`rgba(255,255,255,${a})`;ctx.fill();
        }
      });
    }
  }

  // ── 2) NEBULOSAS ──────────────────────────────────────────────
  ctx.save();ctx.globalCompositeOperation='screen';
  for(let cy=cyMin;cy<=cyMax;cy++){
    for(let cx=cxMin;cx<=cxMax;cx++){
      const ox=cx*EVC_CHUNK, oy=cy*EVC_CHUNK;
      _getEvcNebulas(cx,cy).forEach(n=>{
        const sc=worldToScreen(ox+n.lx,oy+n.ly);
        const rx=n.rxBase*cam.zoom;
        const ry=n.ryBase*cam.zoom;
        const pulse=1+0.06*Math.sin(t*n.speed*1000+n.phase);
        ctx.save();
        ctx.translate(sc.x,sc.y);ctx.rotate(n.rot);ctx.scale(1,ry/Math.max(rx,1));
        for(let l=0;l<n.layers;l++){
          const lr=rx*pulse*(0.4+l*0.35);
          const la=n.alpha*(1-l*0.28);
          const g=ctx.createRadialGradient(0,0,lr*.1,0,0,lr);
          g.addColorStop(0,n.pal[0]+(la*0.9)+')');
          g.addColorStop(0.45,n.pal[1]+(la*0.45)+')');
          g.addColorStop(0.75,n.pal[2]+(la*0.2)+')');
          g.addColorStop(1,'rgba(0,0,0,0)');
          ctx.beginPath();ctx.arc(0,0,lr,0,Math.PI*2);
          ctx.fillStyle=g;ctx.fill();
        }
        // Braços filamentosos
        for(let f=0;f<n.tendrils;f++){
          const fa=(f/n.tendrils)*Math.PI*2+n.rot*0.3;
          const fx=Math.cos(fa)*rx*1.8;const fy=Math.sin(fa)*ry*1.8*(.5);
          const fg=ctx.createLinearGradient(0,0,fx,fy);
          fg.addColorStop(0,n.pal[1]+(n.alpha*0.3)+')');
          fg.addColorStop(1,'rgba(0,0,0,0)');
          ctx.beginPath();ctx.moveTo(0,0);
          ctx.quadraticCurveTo(fx*0.5+(Math.random()-.5)*rx*.3,fy*0.6,fx,fy);
          ctx.strokeStyle=fg;ctx.lineWidth=rx*0.18;ctx.stroke();
        }
        ctx.restore();
      });
    }
  }
  ctx.restore();

  // ── 3) POEIRA INTERESTELAR ────────────────────────────────────
  ctx.save();ctx.globalCompositeOperation='multiply';
  for(let cy=cyMin;cy<=cyMax;cy++){
    for(let cx=cxMin;cx<=cxMax;cx++){
      const ox=cx*EVC_CHUNK, oy=cy*EVC_CHUNK;
      _getEvcDust(cx,cy).forEach(d=>{
        const sc=worldToScreen(ox+d.lx,oy+d.ly);
        const r=d.rBase*cam.zoom;
        const g=ctx.createRadialGradient(sc.x,sc.y,0,sc.x,sc.y,r);
        g.addColorStop(0,`hsla(${d.hue},60%,12%,${d.alpha*1.4})`);
        g.addColorStop(0.6,`hsla(${d.hue},40%,8%,${d.alpha*0.7})`);
        g.addColorStop(1,'rgba(0,0,0,0)');
        ctx.beginPath();ctx.arc(sc.x,sc.y,r,0,Math.PI*2);
        ctx.fillStyle=g;ctx.fill();
      });
    }
  }
  ctx.restore();

  // ── 4) GALÁXIAS DISTANTES ─────────────────────────────────────
  ctx.save();ctx.globalCompositeOperation='screen';
  for(let cy=cyMin;cy<=cyMax;cy++){
    for(let cx=cxMin;cx<=cxMax;cx++){
      const ox=cx*EVC_CHUNK, oy=cy*EVC_CHUNK;
      _getEvcGalaxies(cx,cy).forEach(g=>{
        const sc=worldToScreen(ox+g.lx,oy+g.ly);
        const sz=g.sizeBase*cam.zoom;
        const rot=g.rot+t*g.speed;
        ctx.save();ctx.translate(sc.x,sc.y);ctx.rotate(rot);ctx.scale(1,g.tilt);
        if(g.type==='spiral'){
          // Núcleo
          const core=ctx.createRadialGradient(0,0,0,0,0,sz*.55);
          core.addColorStop(0,`hsla(${g.hue},40%,92%,${g.alpha*1.8})`);
          core.addColorStop(0.4,`hsla(${g.hue},55%,70%,${g.alpha})`);
          core.addColorStop(1,'rgba(0,0,0,0)');
          ctx.beginPath();ctx.arc(0,0,sz*.55,0,Math.PI*2);ctx.fillStyle=core;ctx.fill();
          // Braços espirais
          for(let a=0;a<g.arms;a++){
            const baseAngle=(a/g.arms)*Math.PI*2;
            ctx.beginPath();
            for(let step=0;step<32;step++){
              const frac=step/31;
              const angle=baseAngle+frac*Math.PI*1.8;
              const rad=sz*(0.2+frac*0.85);
              const px=Math.cos(angle)*rad;const py=Math.sin(angle)*rad*0.4;
              step===0?ctx.moveTo(px,py):ctx.lineTo(px,py);
            }
            ctx.strokeStyle=`hsla(${g.hue+20},60%,80%,${g.alpha*0.7})`;
            ctx.lineWidth=Math.max(0.5,sz*0.12);ctx.stroke();
          }
        } else if(g.type==='elliptical'){
          const eg=ctx.createRadialGradient(0,0,0,0,0,sz);
          eg.addColorStop(0,`hsla(${g.hue+30},20%,88%,${g.alpha*1.6})`);
          eg.addColorStop(0.5,`hsla(${g.hue},30%,65%,${g.alpha*0.8})`);
          eg.addColorStop(1,'rgba(0,0,0,0)');
          ctx.beginPath();ctx.arc(0,0,sz,0,Math.PI*2);ctx.fillStyle=eg;ctx.fill();
        } else {
          // Lenticular / irregular: brilho difuso + alguns pontos
          const lg=ctx.createRadialGradient(0,0,0,0,0,sz*0.9);
          lg.addColorStop(0,`hsla(${g.hue},25%,80%,${g.alpha*1.4})`);
          lg.addColorStop(1,'rgba(0,0,0,0)');
          ctx.beginPath();ctx.arc(0,0,sz*0.9,0,Math.PI*2);ctx.fillStyle=lg;ctx.fill();
          // Pontos irregulares
          for(let p=0;p<5;p++){
            const pa=(p/5)*Math.PI*2+g.phase;
            ctx.beginPath();ctx.arc(Math.cos(pa)*sz*.5,Math.sin(pa)*sz*.3,sz*.08,0,Math.PI*2);
            ctx.fillStyle=`hsla(${g.hue+40},50%,90%,${g.alpha*1.2})`;ctx.fill();
          }
        }
        ctx.restore();
      });
    }
  }
  ctx.restore();

  // ── 5) FILAMENTOS CÓSMICOS (Véu de Laniakea) ─────────────────
  _evcInitFilaments();
  ctx.save();ctx.globalCompositeOperation='screen';
  _evcFilaments.forEach(f=>{
    const pulse=0.6+0.4*Math.sin(t*f.speed*1000+f.phase);
    const pts=f.pts.map(p=>worldToScreen(p.ox,p.oy));
    if(pts.length<2)return;
    ctx.beginPath();ctx.moveTo(pts[0].x,pts[0].y);
    for(let i=1;i<pts.length-1;i++){
      const mx=(pts[i].x+pts[i+1].x)*.5;
      const my=(pts[i].y+pts[i+1].y)*.5;
      ctx.quadraticCurveTo(pts[i].x,pts[i].y,mx,my);
    }
    ctx.lineTo(pts[pts.length-1].x,pts[pts.length-1].y);
    ctx.strokeStyle=`hsla(${f.hue},55%,70%,${f.alpha*pulse})`;
    ctx.lineWidth=f.width*cam.zoom;ctx.stroke();
  });
  ctx.restore();

  // ── 6) COMETAS DE FUNDO ───────────────────────────────────────
  _evcInitBgComets();
  // Atualiza posições
  for(let i=_evcBgComets.length-1;i>=0;i--){
    const c=_evcBgComets[i];
    c.x+=c.vx;c.y+=c.vy;
    // Recicla se sair da tela
    const W=canvas.width,H=canvas.height;
    if(c.x<-200||c.x>W+200||c.y<-200||c.y>H+200){
      _evcBgComets.splice(i,1);_evcSpawnBgComet(false);
    }
  }
  // Desenha cometas
  ctx.save();ctx.globalCompositeOperation='screen';
  _evcBgComets.forEach(c=>{
    const tailLen=c.len;
    const nx=-c.vx/Math.max(Math.hypot(c.vx,c.vy),0.001);
    const ny=-c.vy/Math.max(Math.hypot(c.vx,c.vy),0.001);
    const grad=ctx.createLinearGradient(c.x,c.y,c.x+nx*tailLen,c.y+ny*tailLen);
    grad.addColorStop(0,`hsla(${c.hue},80%,90%,${c.alpha})`);
    grad.addColorStop(0.3,`hsla(${c.hue},60%,75%,${c.alpha*0.5})`);
    grad.addColorStop(1,'rgba(0,0,0,0)');
    ctx.beginPath();ctx.moveTo(c.x,c.y);ctx.lineTo(c.x+nx*tailLen,c.y+ny*tailLen);
    ctx.strokeStyle=grad;ctx.lineWidth=c.r*2;ctx.stroke();
    // Núcleo brilhante
    ctx.beginPath();ctx.arc(c.x,c.y,c.r,0,Math.PI*2);
    ctx.fillStyle=`hsla(${c.hue},90%,98%,${c.alpha*1.8})`;ctx.fill();
  });
  ctx.restore();

  // ── 7) VÉUS DE EMISSÃO — halos coloridos em baixa opacidade ──
  // Desenhados em screen para não escurecer o fundo
  ctx.save();ctx.globalCompositeOperation='screen';
  const _evcVeilSeeds=[
    {wx:-800,wy:-600, rx:700,ry:500, hue:260, a:0.025, phase:0.0},
    {wx: 400,wy: 900, rx:900,ry:600, hue:200, a:0.020, phase:1.2},
    {wx:-1400,wy:300, rx:550,ry:700, hue:10,  a:0.022, phase:2.5},
    {wx: 900,wy:-700, rx:650,ry:450, hue:170, a:0.018, phase:3.8},
  ];
  _evcVeilSeeds.forEach(v=>{
    const sc=worldToScreen(v.wx,v.wy);
    const rx=v.rx*cam.zoom, ry=v.ry*cam.zoom;
    const pulse=1+0.08*Math.sin(t*0.00035*1000+v.phase);
    ctx.save();ctx.translate(sc.x,sc.y);ctx.scale(1,ry/Math.max(rx,1));
    const gv=ctx.createRadialGradient(0,0,rx*.05,0,0,rx*pulse);
    gv.addColorStop(0,`hsla(${v.hue},70%,70%,${v.a*1.6})`);
    gv.addColorStop(0.5,`hsla(${v.hue},55%,55%,${v.a*0.7})`);
    gv.addColorStop(1,'rgba(0,0,0,0)');
    ctx.beginPath();ctx.arc(0,0,rx*pulse,0,Math.PI*2);ctx.fillStyle=gv;ctx.fill();
    ctx.restore();
  });
  ctx.restore();
}

// ═══════════════════════════════════════════════════════════════════
//  GRAVITY GRID (sandbox only)
// ═══════════════════════════════════════════════════════════════════
let gravFrame=0;
function drawGravGrid(){
  if(!showGravGrid||!sandboxMode)return;
  gravFrame++;if(gravFrame%2!==0)return;
  const W=gravCvs.width,H=gravCvs.height;
  gCtx.clearRect(0,0,W,H);
  const step=36,offX=(cam.x*cam.zoom)%step,offY=(cam.y*cam.zoom)%step;
  for(let r=0;r<Math.ceil(H/step)+2;r++)for(let c=0;c<Math.ceil(W/step)+2;c++){
    const sx=c*step-offX,sy=r*step-offY;
    const wx=(sx-W*.5)/cam.zoom+cam.x,wy=(sy-H*.5)/cam.zoom+cam.y;
    let fx=0,fy=0;
    objects.forEach(o=>{if(!o.mass||o.dead)return;const d=Math.hypot(wx-o.x,wy-o.y)+40;const f=o.mass*3/(d*d);fx+=(o.x-wx)/d*f;fy+=(o.y-wy)/d*f;});
    const cap=Math.min(Math.hypot(fx,fy)*200,1);
    gCtx.strokeStyle=`rgba(${Math.round(lerp(40,255,cap))},${Math.round(lerp(200,100,cap))},${Math.round(lerp(255,50,cap))},${.18+cap*.35})`;
    gCtx.lineWidth=.8;gCtx.beginPath();gCtx.moveTo(sx,sy);gCtx.lineTo(sx+fx*200,sy+fy*200);gCtx.stroke();
    gCtx.beginPath();gCtx.arc(sx,sy,1.2,0,Math.PI*2);gCtx.fillStyle=`rgba(100,200,255,${.2+cap*.4})`;gCtx.fill();
  }
}

// ═══════════════════════════════════════════════════════════════════
//  BASE CLASS
// ═══════════════════════════════════════════════════════════════════
class CelestialObject{
  constructor(wx,wy,type){
    this.id=idCounter++;this.name=genID();this.x=wx;this.y=wy;this.type=type;
    this.vx=0;this.vy=0;this.dead=false;this.age=0;this.fixed=false;
    this.mineral=MINERALS[randInt(0,MINERALS.length-1)];
    this.gravMultiplier=1;this.temp=5000;
    // bio fields — for ALL objects
    this.bioTemp=50;this.bioO2=21;this.bioWater=30;this.bioLevel=0;
    this._mineralBaseMass=null; // setado no primeiro applyMineralTraits()
  }
  // Aplica o efeito do mineral atual sobre o próprio astro (massa real, usada
  // na gravidade) — chamado na criação e sempre que o mineral é trocado
  // (ex: painel Bio-config). Guarda a massa "crua" para não acumular o
  // multiplicador se o mineral for trocado várias vezes.
  applyMineralTraits(){
    if(this._mineralBaseMass==null)this._mineralBaseMass=this.mass;
    const tr=_mineralTraits(this.mineral);
    this.mass=this._mineralBaseMass*tr.selfMassMult;
  }
  sx(){return worldToScreen(this.x,this.y).x;}
  sy(){return worldToScreen(this.x,this.y).y;}
  sr(){return this.radius*cam.zoom;}
  lifeChance(){
    const t=this.bioTemp,o=this.bioO2,w=this.bioWater;
    const ts=(t>30&&t<80)?1-(Math.abs(t-55)/25):0;
    const os=o>15&&o<35?1:o/35;const ws=w>20?1:w/20;
    return Math.round((ts*.4+os*.3+ws*.3)*100);
  }
}

// ═══════════════════════════════════════════════════════════════════
//  STAR
// ═══════════════════════════════════════════════════════════════════
function _starTempColor(temp){
  // Vermelho (fria) → Amarelo (média) → Ciano (quente) → Roxo (altíssima)
  const t=Math.max(1500,Math.min(50000,temp));
  let hue,sat=100,light;
  if(t<3700){ // fria: vermelho → laranja
    const f=(t-1500)/(3700-1500);
    hue=0+f*30; light=48+f*10;
  }else if(t<6000){ // média: laranja → amarelo
    const f=(t-3700)/(6000-3700);
    hue=30+f*30; light=58+f*8;
  }else if(t<10000){ // quente: amarelo → ciano
    const f=(t-6000)/(10000-6000);
    hue=60+f*(190-60); light=66+f*10;
  }else if(t<22000){ // muito quente: ciano → azul
    const f=(t-10000)/(22000-10000);
    hue=190+f*(240-190); light=76-f*8;
  }else{ // altíssima: azul → roxo
    const f=Math.min(1,(t-22000)/(50000-22000));
    hue=240+f*(280-240); light=68-f*6;
  }
  return `hsl(${hue.toFixed(1)},${sat}%,${light.toFixed(1)}%)`;
}
// Sorteia a temperatura de uma nova estrela com viés forte para o tipo
// "anã amarela comum" (~5000-6200K, tipo o Sol) — o tipo mais comum de
// nascer tanto naturalmente (universo/galáxias geradas) quanto
// artificialmente (jogador criando manualmente). Extremos (muito fria,
// muito quente, ou ALTÍSSIMA/roxa) continuam possíveis, só que raros.
function _randomStarTemp(){
  // Distribuição por faixas com pesos — dá controle direto sobre a
  // probabilidade de cada tipo, em vez de depender de uma curva contínua
  // difícil de calibrar. Anã amarela comum (5000-6200K, mesma faixa que
  // _starTempColor já pinta de amarelo) é disparada a mais provável —
  // tanto criação natural (galáxias geradas) quanto manual (jogador)
  // passam por aqui, já que é o único ponto de sorteio de temp no construtor.
  const bands=[
    {min:3000, max:3900,  w:8},  // fria/vermelha — rara
    {min:3900, max:5000,  w:14}, // laranja — incomum
    {min:5000, max:6200,  w:52}, // amarela comum (tipo o Sol) — a mais provável, de longe
    {min:6200, max:10000, w:16}, // quente/ciano — incomum
    {min:10000,max:22000, w:8},  // azul — rara
    {min:22000,max:30000, w:2},  // altíssima/roxa — muito rara
  ];
  const total=bands.reduce((s,b)=>s+b.w,0);
  let r=rand(0,total);
  for(const b of bands){
    if(r<b.w)return rand(b.min,b.max);
    r-=b.w;
  }
  return rand(5000,6200); // fallback (não deveria ser alcançado)
}
class Star extends CelestialObject{
  constructor(wx,wy){
    super(wx,wy,'star');
    this.radius=rand(14,22);this.mass=this.radius*12;
    this.temp=_randomStarTemp();
    this.color=_starTempColor(this.temp);
    this.glowPhase=rand(0,Math.PI*2);this.fixed=false;
  }
  draw(t){
    this.color=_starTempColor(this.temp);
    const sx=this.sx(),sy=this.sy(),r=this.sr();
    const p=1+.12*Math.sin(t*1.8+this.glowPhase);
    const g=ctx.createRadialGradient(sx,sy,r*.5,sx,sy,r*3.5*p);
    g.addColorStop(0,this.color.replace('hsl','hsla').replace(')',',0.22)'));g.addColorStop(1,'transparent');
    ctx.beginPath();ctx.arc(sx,sy,r*3.5*p,0,Math.PI*2);ctx.fillStyle=g;ctx.fill();
    const g2=ctx.createRadialGradient(sx-r*.3,sy-r*.3,r*.1,sx,sy,r);
    g2.addColorStop(0,'#fff');g2.addColorStop(.4,this.color);
    g2.addColorStop(1,this.color.replace('hsl','hsla').replace(')',',0.55)'));
    ctx.beginPath();ctx.arc(sx,sy,r*p,0,Math.PI*2);ctx.fillStyle=g2;ctx.fill();
    if(sandboxMode){
      ctx.font=`${Math.max(7,r*.5)}px 'Courier New'`;ctx.fillStyle='rgba(255,255,255,.22)';
      ctx.textAlign='center';ctx.fillText(this.name,sx,sy+r+9*cam.zoom);ctx.textAlign='left';
    }
  }
}

// ═══════════════════════════════════════════════════════════════════
//  PLANET — clean original visual (no aura/patches)
// ═══════════════════════════════════════════════════════════════════
class Planet extends CelestialObject{
  constructor(wx,wy,parent){
    super(wx,wy,'planet');
    this.radius=rand(5,12);this.mass=this.radius*3;
    this.color=PLANET_COLORS[randInt(0,PLANET_COLORS.length-1)];
    this.parent=parent||null;
    this.orbitAngle=rand(0,Math.PI*2);
    this.orbitDist=this.parent?dist(this,this.parent):rand(60,160);
    this.orbitSpeed=this.parent?(0.4+rand(0,.3))/Math.sqrt(this.orbitDist/50):rand(.5,1.5);
    this.hasRings=Math.random()<.25;this.ringTilt=rand(.2,.6);
    this.temp=rand(50,800);
  }
  draw(){
    const sx=this.sx(),sy=this.sy(),r=this.sr();
    // Rings (behind planet)
    if(this.hasRings){
      ctx.save();ctx.translate(sx,sy);ctx.scale(1,this.ringTilt);
      ctx.beginPath();ctx.arc(0,0,r*2,0,Math.PI*2);
      ctx.strokeStyle=this.color+'55';ctx.lineWidth=r*.7;ctx.stroke();ctx.restore();
    }
    // Planet body — usa cor congelada se aplicável
    const drawColor=this._frozenColor||this.color;
    const g2=ctx.createRadialGradient(sx-r*.3,sy-r*.3,r*.1,sx,sy,r);
    g2.addColorStop(0, this._frozenColor?'#eef8ff':'#fff8');
    g2.addColorStop(.5,drawColor);g2.addColorStop(1,'#0007');
    ctx.beginPath();ctx.arc(sx,sy,r,0,Math.PI*2);ctx.fillStyle=g2;ctx.fill();
    // Calota de gelo polar quando muito congelado
    if(this._frozenSurface&&this._frozenSurface>0.55){
      const capA=this._frozenSurface*0.65;
      ctx.save();ctx.translate(sx,sy);
      const capR=r*(0.45+this._frozenSurface*0.25);
      const gc=ctx.createRadialGradient(0,-r*0.55,0,0,-r*0.3,capR);
      gc.addColorStop(0,`rgba(245,252,255,${capA})`);
      gc.addColorStop(0.6,`rgba(200,240,255,${capA*0.5})`);
      gc.addColorStop(1,'transparent');
      ctx.beginPath();ctx.arc(0,-r*0.3,capR,0,Math.PI*2);ctx.fillStyle=gc;ctx.fill();
      ctx.restore();
    }
    if(sandboxMode){
      ctx.font=`${Math.max(6,r*.5)}px 'Courier New'`;ctx.fillStyle='rgba(255,255,255,.2)';
      ctx.textAlign='center';ctx.fillText(this.name,sx,sy+r+8*cam.zoom);ctx.textAlign='left';
    }
  }
}

// ═══════════════════════════════════════════════════════════════════
//  MOON
// ═══════════════════════════════════════════════════════════════════
class Moon extends CelestialObject{
  constructor(wx,wy,parent){
    super(wx,wy,'moon');
    this.radius=rand(2.5,5);this.mass=this.radius;
    this.color=`hsl(0,0%,${rand(62,84)}%)`;
    this.parent=parent||null;
    this.orbitAngle=rand(0,Math.PI*2);
    this.orbitDist=this.parent?rand(18,34):rand(20,40);
    this.orbitSpeed=rand(1.2,2.5);
  }
  draw(){
    const sx=this.sx(),sy=this.sy(),r=this.sr();
    ctx.beginPath();ctx.arc(sx,sy,r,0,Math.PI*2);ctx.fillStyle=this.color;ctx.fill();
    ctx.beginPath();ctx.arc(sx+r*.25,sy-r*.2,r*.28,0,Math.PI*2);ctx.fillStyle='rgba(0,0,0,.32)';ctx.fill();
  }
}

// ═══════════════════════════════════════════════════════════════════
//  COMET
// ═══════════════════════════════════════════════════════════════════
class Comet extends CelestialObject{
  constructor(wx,wy){
    super(wx,wy,'comet');
    this.radius=rand(3,7);this.mass=this.radius*.5;
    this.color='#c8f0ff';this.temp=200;
    // Comets fly in a direction with a tail
    const ang=rand(0,Math.PI*2);
    const spd=rand(120,280);
    this.vx=Math.cos(ang)*spd;this.vy=Math.sin(ang)*spd;
    this.fixed=false;this.trailPts=[];
  }
  draw(){
    const sx=this.sx(),sy=this.sy(),r=this.sr();
    // Trail
    this.trailPts.unshift({x:this.x,y:this.y});
    if(this.trailPts.length>28)this.trailPts.length=28;
    for(let i=1;i<this.trailPts.length;i++){
      const pa=worldToScreen(this.trailPts[i-1].x,this.trailPts[i-1].y);
      const pb=worldToScreen(this.trailPts[i].x,this.trailPts[i].y);
      const alpha=(1-i/this.trailPts.length)*.7;
      ctx.beginPath();ctx.moveTo(pa.x,pa.y);ctx.lineTo(pb.x,pb.y);
      ctx.strokeStyle=`rgba(180,230,255,${alpha})`;ctx.lineWidth=Math.max(.5,(r-(i/this.trailPts.length)*r)*.8);ctx.stroke();
    }
    // Head
    const g=ctx.createRadialGradient(sx,sy,0,sx,sy,r*1.6);
    g.addColorStop(0,'#fff');g.addColorStop(.4,this.color);g.addColorStop(1,'rgba(100,200,255,0)');
    ctx.beginPath();ctx.arc(sx,sy,r*1.6,0,Math.PI*2);ctx.fillStyle=g;ctx.fill();
  }
}

// ═══════════════════════════════════════════════════════════════════
//  METEOR
// ═══════════════════════════════════════════════════════════════════
class Meteor extends CelestialObject{
  constructor(wx,wy){
    super(wx,wy,'meteor');
    this.radius=rand(2,5);this.mass=this.radius*.3;
    this.color=`hsl(${rand(20,40)},80%,${rand(55,70)}%)`;this.temp=800;
    const ang=rand(0,Math.PI*2);const spd=rand(200,500);
    this.vx=Math.cos(ang)*spd;this.vy=Math.sin(ang)*spd;
    this.fixed=false;this.trailPts=[];
  }
  draw(){
    const sx=this.sx(),sy=this.sy(),r=this.sr();
    this.trailPts.unshift({x:this.x,y:this.y});
    if(this.trailPts.length>14)this.trailPts.length=14;
    for(let i=1;i<this.trailPts.length;i++){
      const pa=worldToScreen(this.trailPts[i-1].x,this.trailPts[i-1].y);
      const pb=worldToScreen(this.trailPts[i].x,this.trailPts[i].y);
      ctx.beginPath();ctx.moveTo(pa.x,pa.y);ctx.lineTo(pb.x,pb.y);
      ctx.strokeStyle=`rgba(255,160,60,${(1-i/this.trailPts.length)*.8})`;
      ctx.lineWidth=Math.max(.4,r*(1-i/this.trailPts.length));ctx.stroke();
    }
    const g=ctx.createRadialGradient(sx,sy,0,sx,sy,r);
    g.addColorStop(0,'#fff');g.addColorStop(.5,this.color);g.addColorStop(1,'rgba(255,100,0,0)');
    ctx.beginPath();ctx.arc(sx,sy,r,0,Math.PI*2);ctx.fillStyle=g;ctx.fill();
  }
}

// ═══════════════════════════════════════════════════════════════════
//  BLACK HOLE
// ═══════════════════════════════════════════════════════════════════
class BlackHole extends CelestialObject{
  constructor(wx,wy,radiusOverride){
    super(wx,wy,'blackhole');
    this.radius=radiusOverride||rand(16,26);this.mass=this.radius*60;
    this.accretAngle=0;this.pullRange=this.radius*9;
    this.fixed=false;this.merging=false;
  }
  draw(){
    const sx=this.sx(),sy=this.sy(),r=this.sr();
    this.accretAngle+=.038;
    const g=ctx.createRadialGradient(sx,sy,r*1.1,sx,sy,r*5.5);
    g.addColorStop(0,'rgba(255,130,50,0.42)');g.addColorStop(.45,'rgba(255,50,110,0.14)');g.addColorStop(1,'transparent');
    ctx.beginPath();ctx.arc(sx,sy,r*5.5,0,Math.PI*2);ctx.fillStyle=g;ctx.fill();
    for(let i=0;i<3;i++){
      const ang=this.accretAngle+i*(Math.PI*2/3);
      ctx.save();ctx.translate(sx,sy);ctx.rotate(ang);ctx.scale(1,.28);
      ctx.beginPath();ctx.arc(0,0,r*2.2,0,Math.PI);
      ctx.strokeStyle=`rgba(255,${100+i*40},${30+i*20},${.82-i*.16})`;ctx.lineWidth=3-i*.6;ctx.stroke();ctx.restore();
    }
    const g2=ctx.createRadialGradient(sx,sy,0,sx,sy,r);
    g2.addColorStop(0,'#000');g2.addColorStop(.85,'#060006');g2.addColorStop(1,'#190012');
    ctx.beginPath();ctx.arc(sx,sy,r,0,Math.PI*2);ctx.fillStyle=g2;ctx.fill();
    ctx.beginPath();ctx.arc(sx,sy,r*1.06,0,Math.PI*2);ctx.strokeStyle='rgba(255,200,100,0.9)';ctx.lineWidth=1.5;ctx.stroke();
    ctx.beginPath();ctx.arc(sx,sy,this.pullRange*cam.zoom,0,Math.PI*2);ctx.strokeStyle='rgba(255,80,30,0.05)';ctx.lineWidth=1;ctx.stroke();
  }
}

// ═══════════════════════════════════════════════════════════════════
//  PULSAR — corpo estático, sem rotação, sem movimento.
//  A cada 1s sorteia novo ângulo-alvo para os feixes e eles giram
//  suavemente (lerp) até lá. Dois cones bipolares azul-branco elétrico
//  → roxo profundo, com cintilação de alta frequência.
//  Bloom gravitacional nas bordas do núcleo.
// ═══════════════════════════════════════════════════════════════════
class Pulsar extends CelestialObject{
  constructor(wx,wy){
    super(wx,wy,'pulsar');
    this.radius=rand(8,14);this.mass=this.radius*8;
    this.pushRange=200;this.waves=[];this.fixed=true;

    // Ângulo ATUAL dos feixes (o que é desenhado)
    this.poleAngle=Math.random()*Math.PI*2;
    // Ângulo ALVO — para onde os feixes estão girando
    this._targetAngle=this.poleAngle;
    // Velocidade de rotação dos feixes em direção ao alvo (rad/s)
    this._rotSpeed=rand(3.5,6.0); // rápido mas suave
    // Timer para sortear novo alvo
    this._angleTimer=0;
    this._angleInterval=0.9+Math.random()*0.3; // ~1s

    // Cintilação — duas frequências irregulares
    this._shimPhase=Math.random()*Math.PI*2;
    this._shimSpeed=rand(14,26);
  }

  draw(t){
    const sx=this.sx(),sy=this.sy(),r=this.sr();

    // ── Cintilação: combinação de dois senos → pulso irregular ──
    const sh1=Math.sin(t*this._shimSpeed + this._shimPhase);
    const sh2=Math.sin(t*this._shimSpeed*1.41 + this._shimPhase*0.6);
    const shimmer=Math.max(0.08, 0.52+0.28*sh1+0.20*sh2); // 0.08..1.0

    // ── Ondas de choque (emitidas quando o alvo muda) ──
    this.waves=this.waves.filter(w=>w.alpha>.015);
    this.waves.forEach(w=>{
      ctx.beginPath();ctx.arc(sx,sy,w.r*cam.zoom,0,Math.PI*2);
      ctx.strokeStyle=`rgba(160,190,255,${w.alpha})`;ctx.lineWidth=1.5;ctx.stroke();
      w.r+=4.5;w.alpha*=.87;
    });

    // ══════════════════════════════════════════════════════════════
    //  FEIXES BIPOLARES — polo norte (poleAngle) e sul (+π)
    // ══════════════════════════════════════════════════════════════
    const beamLen=170*cam.zoom;
    const coneHalf=0.10; // ~5.7° meio-ângulo do cone

    for(let pole=0;pole<2;pole++){
      const poleDir=this.poleAngle + pole*Math.PI;
      const bax=Math.cos(poleDir), bay=Math.sin(poleDir);
      const tipX=sx+bax*beamLen, tipY=sy+bay*beamLen;

      // Cone externo — volume do feixe
      const e1x=Math.cos(poleDir+coneHalf), e1y=Math.sin(poleDir+coneHalf);
      const e2x=Math.cos(poleDir-coneHalf), e2y=Math.sin(poleDir-coneHalf);
      ctx.save();
      ctx.beginPath();
      ctx.moveTo(sx,sy);
      ctx.lineTo(sx+e1x*beamLen, sy+e1y*beamLen);
      ctx.lineTo(sx+e2x*beamLen, sy+e2y*beamLen);
      ctx.closePath();
      const cg=ctx.createLinearGradient(sx,sy,tipX,tipY);
      cg.addColorStop(0,    'rgba(220,240,255,0)');
      cg.addColorStop(0.03, `rgba(210,235,255,${0.68*shimmer})`);  // azul-branco elétrico
      cg.addColorStop(0.15, `rgba(130,185,255,${0.42*shimmer})`);  // azul claro
      cg.addColorStop(0.40, `rgba(80,80,210,${0.20*shimmer})`);    // azul-roxo
      cg.addColorStop(0.72, `rgba(55,15,145,${0.07*shimmer})`);    // roxo profundo
      cg.addColorStop(1,    'rgba(30,0,90,0)');
      ctx.fillStyle=cg; ctx.fill();
      ctx.restore();

      // Feixe central — linha grossa com gradiente longitudinal
      const bg=ctx.createLinearGradient(sx,sy,tipX,tipY);
      bg.addColorStop(0,    'rgba(255,255,255,0)');
      bg.addColorStop(0.015,`rgba(255,255,255,${shimmer})`);        // branco puro na saída
      bg.addColorStop(0.07, `rgba(190,225,255,${0.92*shimmer})`);   // azul-branco
      bg.addColorStop(0.22, `rgba(110,155,255,${0.62*shimmer})`);   // azul médio
      bg.addColorStop(0.50, `rgba(75,35,185,${0.28*shimmer})`);     // roxo
      bg.addColorStop(0.82, `rgba(45,5,115,${0.07*shimmer})`);      // roxo escuro
      bg.addColorStop(1,    'rgba(15,0,55,0)');
      ctx.beginPath();ctx.moveTo(sx,sy);ctx.lineTo(tipX,tipY);
      ctx.strokeStyle=bg;
      ctx.lineWidth=3.8*cam.zoom;
      ctx.lineCap='round'; ctx.stroke();

      // Espinha branca — ultrabrilhante nos primeiros 40% do feixe
      const spLen=beamLen*0.40;
      const sg=ctx.createLinearGradient(sx,sy, sx+bax*spLen,sy+bay*spLen);
      sg.addColorStop(0,   'rgba(255,255,255,0)');
      sg.addColorStop(0.04,`rgba(255,255,255,${shimmer})`);
      sg.addColorStop(0.55,`rgba(210,235,255,${0.38*shimmer})`);
      sg.addColorStop(1,   'rgba(180,210,255,0)');
      ctx.beginPath();ctx.moveTo(sx,sy);ctx.lineTo(sx+bax*spLen,sy+bay*spLen);
      ctx.strokeStyle=sg;
      ctx.lineWidth=1.4*cam.zoom; ctx.stroke();

      // Bloom na base de cada polo
      const boomR=r*2.0*cam.zoom;
      const boomX=sx+bax*r*0.85*cam.zoom, boomY=sy+bay*r*0.85*cam.zoom;
      const bg2=ctx.createRadialGradient(boomX,boomY,0, boomX,boomY,boomR);
      bg2.addColorStop(0,  `rgba(210,235,255,${0.50*shimmer})`);
      bg2.addColorStop(0.4,`rgba(120,160,255,${0.18*shimmer})`);
      bg2.addColorStop(1,  'transparent');
      ctx.beginPath();ctx.arc(boomX,boomY,boomR,0,Math.PI*2);
      ctx.fillStyle=bg2; ctx.fill();
    }

    // ══════════════════════════════════════════════════════════════
    //  NÚCLEO ESTÁTICO — bloom gravitacional nas bordas
    // ══════════════════════════════════════════════════════════════

    // Halo externo em 3 camadas (bloom gravitacional)
    for(let i=3;i>=1;i--){
      const hg=ctx.createRadialGradient(sx,sy,r*0.9,sx,sy,r*(1.1+i*0.85));
      hg.addColorStop(0,  `rgba(150,200,255,${(0.16-i*0.03)*shimmer})`);
      hg.addColorStop(0.5,`rgba(90,130,255,${(0.07-i*0.015)*shimmer})`);
      hg.addColorStop(1,  'transparent');
      ctx.beginPath();ctx.arc(sx,sy,r*(1.1+i*0.85),0,Math.PI*2);
      ctx.fillStyle=hg; ctx.fill();
    }

    // Corpo do núcleo — gradiente não-uniforme com bloom nas bordas
    const cg2=ctx.createRadialGradient(sx-r*.2,sy-r*.2,r*.04, sx,sy,r);
    cg2.addColorStop(0,    '#ffffff');
    cg2.addColorStop(0.22, 'rgba(215,235,255,1)');
    cg2.addColorStop(0.50, 'rgba(120,165,255,0.97)');
    cg2.addColorStop(0.78, 'rgba(55,75,205,0.92)');
    cg2.addColorStop(0.91, `rgba(145,185,255,${0.68+shimmer*0.28})`); // bloom borda
    cg2.addColorStop(1,    `rgba(85,125,255,${0.38+shimmer*0.38})`);
    ctx.beginPath();ctx.arc(sx,sy,r,0,Math.PI*2);
    ctx.fillStyle=cg2; ctx.fill();

    // Push range hint
    ctx.beginPath();ctx.arc(sx,sy,this.pushRange*cam.zoom,0,Math.PI*2);
    ctx.strokeStyle='rgba(100,160,255,0.03)'; ctx.lineWidth=1; ctx.stroke();
  }
}

// ═══════════════════════════════════════════════════════════════════
//  WHITE HOLE
// ═══════════════════════════════════════════════════════════════════
class WhiteHole extends CelestialObject{
  constructor(wx,wy){
    super(wx,wy,'whitehole');
    this.radius=rand(14,20);this.mass=this.radius*45;
    this.pushRange=this.radius*8;this.angle=0;this.emitTimer=0;this.fixed=true;
  }
  draw(){
    const sx=this.sx(),sy=this.sy(),r=this.sr();
    this.angle+=.025;
    if(this.emitTimer>=0)this.emitTimer++;
    if(this.emitTimer>0&&this.emitTimer%6===0){const ang=rand(0,Math.PI*2);particles.push({x:this.x+Math.cos(ang)*this.radius,y:this.y+Math.sin(ang)*this.radius,vx:Math.cos(ang)*rand(1.5,4.5),vy:Math.sin(ang)*rand(1.5,4.5),r:rand(1.5,3.5),alpha:.9,color:`hsl(${rand(175,240)},90%,80%)`});}
    ctx.beginPath();ctx.arc(sx,sy,this.pushRange*cam.zoom,0,Math.PI*2);ctx.strokeStyle='rgba(100,200,255,0.05)';ctx.lineWidth=1;ctx.stroke();
    for(let i=3;i>=1;i--){const g=ctx.createRadialGradient(sx,sy,r*i*.35,sx,sy,r*i*1.4);g.addColorStop(0,`rgba(200,240,255,${.07/i})`);g.addColorStop(1,'transparent');ctx.beginPath();ctx.arc(sx,sy,r*i*1.4,0,Math.PI*2);ctx.fillStyle=g;ctx.fill();}
    ctx.save();ctx.translate(sx,sy);ctx.rotate(this.angle);
    for(let i=0;i<6;i++){const a=(i/6)*Math.PI*2;ctx.beginPath();ctx.arc(Math.cos(a)*r*1.45,Math.sin(a)*r*1.45,2.5,0,Math.PI*2);ctx.fillStyle='rgba(150,235,255,.85)';ctx.fill();}
    ctx.restore();
    const g2=ctx.createRadialGradient(sx,sy,0,sx,sy,r);g2.addColorStop(0,'#fff');g2.addColorStop(.5,'#c8f0ff');g2.addColorStop(1,'rgba(100,200,255,.38)');
    ctx.beginPath();ctx.arc(sx,sy,r,0,Math.PI*2);ctx.fillStyle=g2;ctx.fill();
  }
}

// ═══════════════════════════════════════════════════════════════════
//  WORMHOLE
// ═══════════════════════════════════════════════════════════════════
class Wormhole extends CelestialObject{
  constructor(wx,wy,pairId,colorSet){
    super(wx,wy,'wormhole');
    this.radius=rand(14,20);this.pairId=pairId;
    this.colorSet=colorSet||WORM_COLORS[randInt(0,WORM_COLORS.length-1)];
    this.angle=0;this.fixed=true;
  }
  draw(){
    const sx=this.sx(),sy=this.sy(),r=this.sr();
    this.angle+=.04;
    for(let i=4;i>=1;i--){ctx.save();ctx.translate(sx,sy);ctx.rotate(this.angle*i);ctx.scale(1,.4+i*.1);ctx.beginPath();ctx.arc(0,0,r*.5*i,0,Math.PI*2);ctx.strokeStyle=`rgba(${i%2?'150,80,255':'80,200,255'},${.15*i})`;ctx.lineWidth=2;ctx.stroke();ctx.restore();}
    const g=ctx.createRadialGradient(sx,sy,r*.3,sx,sy,r*3);g.addColorStop(0,this.colorSet[0]+'88');g.addColorStop(1,'transparent');
    ctx.beginPath();ctx.arc(sx,sy,r*3,0,Math.PI*2);ctx.fillStyle=g;ctx.fill();
    const g2=ctx.createRadialGradient(sx,sy,0,sx,sy,r);g2.addColorStop(0,'#fff');g2.addColorStop(.3,this.colorSet[0]);g2.addColorStop(1,this.colorSet[1]);
    ctx.beginPath();ctx.arc(sx,sy,r,0,Math.PI*2);ctx.fillStyle=g2;ctx.fill();
    ctx.beginPath();ctx.arc(sx,sy,r*.45,0,Math.PI*2);ctx.fillStyle='rgba(0,0,0,.9)';ctx.fill();
  }
}

// ═══════════════════════════════════════════════════════════════════
//  QUASAR
// ═══════════════════════════════════════════════════════════════════
class Quasar extends CelestialObject{
  constructor(wx,wy){
    super(wx,wy,'quasar');
    this.radius=rand(18,28);this.mass=this.radius*80;this.pullRange=this.radius*12;
    this.jetAngle=rand(0,Math.PI);this.jetSpeed=rand(.4,.9);
    this.flickerT=0;this.accretAngle=0;this.fixed=true;
    this.color=`hsl(${rand(40,70)},100%,70%)`;
    // Anel de detritos arrancados de astros
    this._ring=[];      // {a,dist,vA,r,color,alpha,life}
    this._baseRadius=this.radius; // raio original para referência
  }
  draw(t){
    const sx=this.sx(),sy=this.sy(),r=this.sr();
    this.accretAngle+=.025;this.flickerT+=.08;
    const fl=.8+.2*Math.sin(this.flickerT*15);
    const jl=220*cam.zoom;

    // ── Glow externo ──
    const glow=ctx.createRadialGradient(sx,sy,r,sx,sy,r*6);
    glow.addColorStop(0,`rgba(255,200,60,${.35*fl})`);
    glow.addColorStop(.5,'rgba(255,100,20,0.1)');
    glow.addColorStop(1,'transparent');
    ctx.beginPath();ctx.arc(sx,sy,r*6,0,Math.PI*2);ctx.fillStyle=glow;ctx.fill();

    // ── Disco de acreção ──
    for(let i=0;i<4;i++){
      ctx.save();ctx.translate(sx,sy);
      ctx.rotate(this.accretAngle+i*(Math.PI*2/4));
      ctx.scale(1,.2);
      ctx.beginPath();ctx.arc(0,0,r*2.5,0,Math.PI);
      ctx.strokeStyle=`rgba(255,${160-i*20},${40+i*15},${.75-i*.12})`;
      ctx.lineWidth=3*cam.zoom;ctx.stroke();
      ctx.restore();
    }

    // ── Jatos relativísticos ──
    for(let s=-1;s<=1;s+=2){
      const jx=Math.cos(this.jetAngle+s*Math.PI)*jl;
      const jy=Math.sin(this.jetAngle+s*Math.PI)*jl;
      const g=ctx.createLinearGradient(sx,sy,sx+jx,sy+jy);
      g.addColorStop(0,`rgba(255,220,80,${.9*fl})`);
      g.addColorStop(.3,`rgba(255,140,40,${.55*fl})`);
      g.addColorStop(1,'rgba(255,80,20,0)');
      ctx.beginPath();ctx.moveTo(sx,sy);ctx.lineTo(sx+jx,sy+jy);
      ctx.strokeStyle=g;ctx.lineWidth=6*cam.zoom;ctx.stroke();
      const g2=ctx.createLinearGradient(sx,sy,sx+jx*.5,sy+jy*.5);
      g2.addColorStop(0,'rgba(255,255,200,1)');g2.addColorStop(1,'rgba(255,255,200,0)');
      ctx.beginPath();ctx.moveTo(sx,sy);ctx.lineTo(sx+jx*.5,sy+jy*.5);
      ctx.strokeStyle=g2;ctx.lineWidth=2*cam.zoom;ctx.stroke();
    }

    // ── Núcleo ──
    const gc=ctx.createRadialGradient(sx,sy,0,sx,sy,r);
    gc.addColorStop(0,'#fffbe0');gc.addColorStop(.3,this.color);
    gc.addColorStop(.7,'#c05000');gc.addColorStop(1,'#300010');
    ctx.beginPath();ctx.arc(sx,sy,r,0,Math.PI*2);ctx.fillStyle=gc;ctx.fill();

    // ── Anel de partículas arrancadas ──
    if(this._ring.length>0){
      this._ring.forEach(p=>{
        // Partícula em espiral para o núcleo
        p.a+=p.vA;
        p.dist=Math.max(r*1.1, p.dist - p.infall);
        p.life-=.005;
        p.alpha=Math.min(p.life*3, .92);
        if(p.dist<=r*1.15) p.life=0; // chegou ao núcleo
        const px=sx+Math.cos(p.a)*p.dist*cam.zoom;
        const py=sy+Math.sin(p.a)*p.dist*cam.zoom;
        ctx.beginPath();ctx.arc(px,py,Math.max(.8,p.r*cam.zoom),0,Math.PI*2);
        ctx.fillStyle=p.color.replace(')',`,${p.alpha})`).replace('rgb(','rgba(');
        ctx.fill();
      });
      // Remove partículas mortas
      this._ring=this._ring.filter(p=>p.life>0);
    }

    // Pull range hint
    ctx.beginPath();ctx.arc(sx,sy,this.pullRange*cam.zoom,0,Math.PI*2);
    ctx.strokeStyle='rgba(255,150,30,0.05)';ctx.lineWidth=1;ctx.stroke();
  }
}

// ═══════════════════════════════════════════════════════════════════
//  MAGNETAR — força de órbita aleatória: a cada 3s muda a forma da
//  órbita (excentricidade, velocidade angular, direção). Sem repulsão.
// ═══════════════════════════════════════════════════════════════════
class Magnetar extends CelestialObject{
  constructor(wx,wy){
    super(wx,wy,'magnetar');
    this.radius=rand(7,12);this.mass=this.radius*10;
    this.magAngle=rand(0,Math.PI);this.spinSpeed=rand(8,14);
    this.burstTimer=0;this.burstActive=false;this.burstR=0;this.burstAlpha=0;
    this.fieldRange=200;this.fixed=true;
    // Orbit shift state
    this._orbitTimer=0;
    this._orbitInterval=3.0;
    this._orbitEcc=rand(0,.7);      // eccentricity 0=circular, 1=very elliptic
    this._orbitDir=Math.random()<.5?1:-1; // clockwise or counter
    this._orbitSpeed=rand(0.6,1.8); // tangential strength multiplier
    this._orbitTargetDist=rand(60,160); // preferred orbit radius
    this._shiftFlash=0; // visual flash when orbit changes
  }
  draw(t){
    const sx=this.sx(),sy=this.sy(),r=this.sr();
    this._shiftFlash=Math.max(0,this._shiftFlash-.05);

    // Burst ring (from catastrophe mode, kept)
    if(this.burstActive){
      ctx.beginPath();ctx.arc(sx,sy,this.burstR*cam.zoom,0,Math.PI*2);
      ctx.strokeStyle=`rgba(180,100,255,${this.burstAlpha})`;ctx.lineWidth=3;ctx.stroke();
    }

    // Magnetic field lines — lemniscate-style loops
    for(let i=0;i<6;i++){
      const la=this.magAngle+i*(Math.PI/3);
      ctx.save();ctx.translate(sx,sy);ctx.rotate(la);
      ctx.beginPath();
      for(let u=0;u<=Math.PI;u+=.12){
        const rr=r*3*Math.sin(u)*Math.sin(u);
        const xx=rr*Math.cos(u),yy=rr*Math.sin(u)*.38;
        u===0?ctx.moveTo(xx,yy):ctx.lineTo(xx,yy);
      }
      const lineAlpha=.1+.06*Math.sin(t*3+i)+this._shiftFlash*.2;
      ctx.strokeStyle=`rgba(180,100,255,${lineAlpha})`;ctx.lineWidth=1;ctx.stroke();
      ctx.restore();
    }

    // Outer glow
    const gm=ctx.createRadialGradient(sx,sy,r,sx,sy,r*4.5);
    gm.addColorStop(0,`rgba(150,80,255,${.18+this._shiftFlash*.15})`);
    gm.addColorStop(1,'transparent');
    ctx.beginPath();ctx.arc(sx,sy,r*4.5,0,Math.PI*2);ctx.fillStyle=gm;ctx.fill();



    // Core
    const gc=ctx.createRadialGradient(sx-r*.3,sy-r*.3,r*.1,sx,sy,r);
    gc.addColorStop(0,'#e0e8ff');gc.addColorStop(.4,'#7060e0');
    gc.addColorStop(.8,'#300080');gc.addColorStop(1,'#0a0020');
    ctx.beginPath();ctx.arc(sx,sy,r,0,Math.PI*2);ctx.fillStyle=gc;ctx.fill();

    // Pole dots
    for(let s=-1;s<=1;s+=2){
      const px=Math.cos(this.magAngle+s*Math.PI*.5)*r*.7;
      const py=Math.sin(this.magAngle+s*Math.PI*.5)*r*.7;
      ctx.beginPath();ctx.arc(sx+px,sy+py,r*.25,0,Math.PI*2);
      ctx.fillStyle='rgba(200,160,255,.9)';ctx.fill();
    }

    if(sandboxMode){
      ctx.font=`${Math.max(6,r*.5)}px 'Courier New'`;ctx.fillStyle='rgba(180,100,255,.3)';
      ctx.textAlign='center';ctx.fillText(this.name,sx,sy+r*cam.zoom+10);ctx.textAlign='left';
    }
  }
}

// ═══════════════════════════════════════════════════════════════════
//  PROTOSTAR
// ═══════════════════════════════════════════════════════════════════
class Protostar extends CelestialObject{
  constructor(wx,wy){
    super(wx,wy,'protostar');
    this.radius=rand(30,50);this.mass=this.radius*3;
    this.cloudPts=[];this.fixed=false;this.glowPhase=rand(0,Math.PI*2);
    this.collapseSpeed=rand(.004,.012);
    this.cloudColor=`hsl(${randInt(200,280)},60%,55%)`;
    for(let i=0;i<40;i++)this.cloudPts.push({a:rand(0,Math.PI*2),d:rand(.5,1),sp:rand(.002,.008),r:rand(1.5,4),al:rand(.2,.7)});
  }
  draw(){
    const sx=this.sx(),sy=this.sy(),r=this.sr();
    this.cloudPts.forEach(p=>{p.a+=p.sp;const px=sx+Math.cos(p.a)*r*p.d,py=sy+Math.sin(p.a)*r*p.d;ctx.beginPath();ctx.arc(px,py,p.r,0,Math.PI*2);ctx.fillStyle=this.cloudColor.replace('hsl','hsla').replace(')',`,${p.al})`);ctx.fill();});
    const heat=Math.min(this.age*.1,.8);const grd=ctx.createRadialGradient(sx,sy,0,sx,sy,r);
    grd.addColorStop(0,`rgba(255,${Math.round(200-heat*150)},${Math.round(100-heat*100)},${.3+heat*.5})`);grd.addColorStop(1,'transparent');
    ctx.beginPath();ctx.arc(sx,sy,r,0,Math.PI*2);ctx.fillStyle=grd;ctx.fill();
    if(this.radius>14)this.radius=Math.max(14,this.radius-this.collapseSpeed);
  }
}

// ═══════════════════════════════════════════════════════════════════
//  CEPHEID — pulsa visivelmente: expande/contrai o raio, muda cor
//  e emite anéis de choque a cada pulso completo
// ═══════════════════════════════════════════════════════════════════
class Cepheid extends CelestialObject{
  constructor(wx,wy){
    super(wx,wy,'cepheid');
    this.baseRadius=rand(14,22);this.radius=this.baseRadius;this.mass=this.radius*10;
    // Base hue shifts between warm (peak) and cooler (trough)
    this._hueBase=rand(30,55);
    this.glowPhase=rand(0,Math.PI*2);
    this.pulseFreq=rand(.5,1.4); // slower = more dramatic
    this.fixed=false;
    this._rings=[]; // {r, alpha} expanding rings
    this._lastPhase=0; // detect when pulse crosses peak
    this._peakFired=false;
  }
  draw(t){
    const raw=Math.sin(t*this.pulseFreq+this.glowPhase); // -1..1
    const pulse=1+.38*raw; // radius multiplier 0.62..1.38
    this.radius=this.baseRadius*pulse;

    // Detect peak (raw goes from <0.9 to >=0.9) — fire ring
    if(raw>=0.92&&!this._peakFired){
      this._peakFired=true;
      this._rings.push({r:this.baseRadius*1.5,alpha:.9});
    }
    if(raw<0.7) this._peakFired=false;
    this._lastPhase=raw;

    const sx=this.sx(),sy=this.sy(),r=this.sr();

    // Colour: hot yellow-white at peak, orange-red at trough
    const hue=this._hueBase-(1-Math.max(0,raw))*(this._hueBase-12);
    const lum=68+raw*14;
    const col=`hsl(${hue},100%,${lum}%)`;

    // Expanding rings
    this._rings=this._rings.filter(rg=>rg.alpha>.02);
    this._rings.forEach(rg=>{
      ctx.beginPath();ctx.arc(sx,sy,rg.r*cam.zoom,0,Math.PI*2);
      ctx.strokeStyle=`hsla(${hue},100%,80%,${rg.alpha})`;
      ctx.lineWidth=2;ctx.stroke();
      rg.r+=4;rg.alpha*=.87;
    });

    // Outer glow — scales with pulse
    const gp=ctx.createRadialGradient(sx,sy,r*.3,sx,sy,r*3.8*pulse);
    gp.addColorStop(0,`hsla(${hue},100%,80%,${.28*pulse})`);
    gp.addColorStop(.5,`hsla(${hue},100%,60%,${.1*pulse})`);
    gp.addColorStop(1,'transparent');
    ctx.beginPath();ctx.arc(sx,sy,r*3.8*pulse,0,Math.PI*2);ctx.fillStyle=gp;ctx.fill();

    // Body
    const gb=ctx.createRadialGradient(sx-r*.28,sy-r*.28,r*.08,sx,sy,r);
    gb.addColorStop(0,'#ffffff');
    gb.addColorStop(.35,col);
    gb.addColorStop(1,`hsla(${hue},100%,40%,.55)`);
    ctx.beginPath();ctx.arc(sx,sy,r,0,Math.PI*2);ctx.fillStyle=gb;ctx.fill();

    if(sandboxMode){
      ctx.font=`${Math.max(6,r*.45)}px 'Courier New'`;
      ctx.fillStyle='rgba(255,255,255,.2)';
      ctx.textAlign='center';ctx.fillText(this.name,sx,sy+r+8*cam.zoom);ctx.textAlign='left';
    }
  }
}

// ═══════════════════════════════════════════════════════════════════
//  BLAZAR — new visual: deep red + ultra-bright white focused beam
//  Jet angle is FIXED at construction (pre-defined exact angle)
//  Objects crossing jet beam are launched violently; small ones evaporate
// ═══════════════════════════════════════════════════════════════════
class Blazar extends CelestialObject{
  constructor(wx,wy){
    super(wx,wy,'blazar');
    this.radius=rand(20,30);this.mass=this.radius*90;this.pullRange=this.radius*10;
    // FIXED exact jet angle — chosen once, never rotates
    this.jetAngle=rand(0,Math.PI*2);
    this.flickerT=0;this.accretAngle=0;this.fixed=true;this.merging=false;
    // jet range for interaction
    this.jetRange=320;
    this.jetWidth=40; // half-width cone for hit detection
  }
  draw(){
    const sx=this.sx(),sy=this.sy(),r=this.sr();
    this.accretAngle+=.035;this.flickerT+=.09;
    const fl=.82+.18*Math.sin(this.flickerT*22);
    const jl=320*cam.zoom; // long focused beam

    // ── Single ultra-bright focused jet (fixed angle, both directions) ──
    for(let s=-1;s<=1;s+=2){
      const jx=Math.cos(this.jetAngle+s*Math.PI)*jl;
      const jy=Math.sin(this.jetAngle+s*Math.PI)*jl;
      // Outer red beam
      const gj=ctx.createLinearGradient(sx,sy,sx+jx,sy+jy);
      gj.addColorStop(0,`rgba(255,255,255,${.98*fl})`);
      gj.addColorStop(.06,`rgba(255,180,60,${.92*fl})`);
      gj.addColorStop(.18,`rgba(220,30,30,${.75*fl})`);
      gj.addColorStop(.55,`rgba(160,0,0,${.3*fl})`);
      gj.addColorStop(1,'rgba(80,0,0,0)');
      ctx.beginPath();ctx.moveTo(sx,sy);ctx.lineTo(sx+jx,sy+jy);
      ctx.strokeStyle=gj;ctx.lineWidth=13*cam.zoom;ctx.stroke();
      // Middle hot beam
      const gj2=ctx.createLinearGradient(sx,sy,sx+jx*.65,sy+jy*.65);
      gj2.addColorStop(0,'rgba(255,255,255,1)');
      gj2.addColorStop(.12,`rgba(255,230,180,${.88*fl})`);
      gj2.addColorStop(.4,`rgba(255,80,20,${.5*fl})`);
      gj2.addColorStop(1,'rgba(180,0,0,0)');
      ctx.beginPath();ctx.moveTo(sx,sy);ctx.lineTo(sx+jx*.65,sy+jy*.65);
      ctx.strokeStyle=gj2;ctx.lineWidth=5*cam.zoom;ctx.stroke();
      // Bright white core spine
      const gj3=ctx.createLinearGradient(sx,sy,sx+jx*.35,sy+jy*.35);
      gj3.addColorStop(0,'rgba(255,255,255,1)');
      gj3.addColorStop(1,'rgba(255,255,255,0)');
      ctx.beginPath();ctx.moveTo(sx,sy);ctx.lineTo(sx+jx*.35,sy+jy*.35);
      ctx.strokeStyle=gj3;ctx.lineWidth=2*cam.zoom;ctx.stroke();
    }

    // Deep red/crimson outer glow
    const glow=ctx.createRadialGradient(sx,sy,r*.4,sx,sy,r*7);
    glow.addColorStop(0,`rgba(255,60,20,${.45*fl})`);
    glow.addColorStop(.25,`rgba(200,0,0,${.25*fl})`);
    glow.addColorStop(.6,'rgba(120,0,0,0.07)');
    glow.addColorStop(1,'transparent');
    ctx.beginPath();ctx.arc(sx,sy,r*7,0,Math.PI*2);ctx.fillStyle=glow;ctx.fill();

    // Accretion disk — red/orange tones
    for(let i=0;i<5;i++){
      ctx.save();ctx.translate(sx,sy);ctx.rotate(this.accretAngle+i*(Math.PI*2/5));ctx.scale(1,.20);
      ctx.beginPath();ctx.arc(0,0,r*2.8,0,Math.PI);
      ctx.strokeStyle=`rgba(255,${40+i*18},${i*8},${.85-i*.1})`;
      ctx.lineWidth=3.5*cam.zoom;ctx.stroke();ctx.restore();
    }

    // Core — deep red to white center
    const gc=ctx.createRadialGradient(sx,sy,0,sx,sy,r);
    gc.addColorStop(0,'#ffffff');
    gc.addColorStop(.18,'#ffddaa');
    gc.addColorStop(.45,'#ff2200');
    gc.addColorStop(.75,'#880000');
    gc.addColorStop(1,'#1a0000');
    ctx.beginPath();ctx.arc(sx,sy,r,0,Math.PI*2);ctx.fillStyle=gc;ctx.fill();

    // White hot center pinpoint
    const gcore=ctx.createRadialGradient(sx,sy,0,sx,sy,r*.3);
    gcore.addColorStop(0,'rgba(255,255,255,0.95)');gcore.addColorStop(1,'transparent');
    ctx.beginPath();ctx.arc(sx,sy,r*.3,0,Math.PI*2);ctx.fillStyle=gcore;ctx.fill();
  }
}

// ═══════════════════════════════════════════════════════════════════
//  MICROQUASAR — strong gravitational pull, accreting smaller objects
// ═══════════════════════════════════════════════════════════════════
class Microquasar extends CelestialObject{
  constructor(wx,wy){
    super(wx,wy,'microquasar');
    this.radius=rand(10,16);this.mass=this.radius*40;
    // Strong pull range — attracts smaller/lighter objects
    this.pullRange=this.radius*14;
    this.accretAngle=0;this.jetT=0;this.distortAngle=0;this.fixed=true;
  }
  draw(){
    const sx=this.sx(),sy=this.sy(),r=this.sr();
    this.accretAngle+=.07;this.jetT+=.05;this.distortAngle+=.03;
    const fl=.65+.35*Math.sin(this.jetT*14),jl=140*cam.zoom;
    // Lensing rings
    for(let i=0;i<4;i++){ctx.save();ctx.translate(sx,sy);ctx.rotate(this.distortAngle+i*(Math.PI/2));ctx.scale(1,.2+i*.05);ctx.beginPath();ctx.arc(0,0,r*(2.5+i*.6),0,Math.PI*2);ctx.strokeStyle=`rgba(80,160,255,${.12-i*.02})`;ctx.lineWidth=1.5;ctx.stroke();ctx.restore();}
    // Pull range (visible subtle circle)
    ctx.beginPath();ctx.arc(sx,sy,this.pullRange*cam.zoom,0,Math.PI*2);ctx.strokeStyle='rgba(80,160,255,0.06)';ctx.lineWidth=1;ctx.stroke();
    // Outer glow
    const glow=ctx.createRadialGradient(sx,sy,r,sx,sy,r*5);glow.addColorStop(0,'rgba(80,180,255,0.28)');glow.addColorStop(.5,'rgba(40,100,200,0.1)');glow.addColorStop(1,'transparent');
    ctx.beginPath();ctx.arc(sx,sy,r*5,0,Math.PI*2);ctx.fillStyle=glow;ctx.fill();
    // Jets
    for(let s=-1;s<=1;s+=2){const g=ctx.createLinearGradient(sx,sy,sx+r*.5*s,sy+s*jl);g.addColorStop(0,`rgba(150,220,255,${.92*fl})`);g.addColorStop(.4,`rgba(80,160,255,${.55*fl})`);g.addColorStop(1,'rgba(50,100,200,0)');ctx.beginPath();ctx.moveTo(sx,sy);ctx.lineTo(sx+r*.5*s,sy+s*jl);ctx.strokeStyle=g;ctx.lineWidth=5*cam.zoom;ctx.stroke();for(let k=1;k<=3;k++){const ky=sy+s*jl*(k/3.5),kr=r*(.4-.08*k)*cam.zoom;const kg=ctx.createRadialGradient(sx,ky,0,sx,ky,kr);kg.addColorStop(0,`rgba(200,240,255,${.7*fl})`);kg.addColorStop(1,'transparent');ctx.beginPath();ctx.arc(sx,ky,kr,0,Math.PI*2);ctx.fillStyle=kg;ctx.fill();}}
    // Accretion disk
    for(let i=0;i<3;i++){ctx.save();ctx.translate(sx,sy);ctx.rotate(this.accretAngle+i*(Math.PI*2/3));ctx.scale(1,.28);ctx.beginPath();ctx.arc(0,0,r*2,0,Math.PI);ctx.strokeStyle=`rgba(255,${100+i*45},${30+i*20},${.82-i*.15})`;ctx.lineWidth=2.5*cam.zoom;ctx.stroke();ctx.restore();}
    // Core
    const g2=ctx.createRadialGradient(sx,sy,0,sx,sy,r);g2.addColorStop(0,'#000');g2.addColorStop(.8,'#040010');g2.addColorStop(1,'#1a0020');
    ctx.beginPath();ctx.arc(sx,sy,r,0,Math.PI*2);ctx.fillStyle=g2;ctx.fill();
    ctx.beginPath();ctx.arc(sx,sy,r*1.05,0,Math.PI*2);ctx.strokeStyle='rgba(100,200,255,.85)';ctx.lineWidth=1.5;ctx.stroke();
    // Particle ring
    for(let i=0;i<8;i++){const a=this.accretAngle*2+i*(Math.PI*2/8);const px=sx+Math.cos(a)*r*1.4,py=sy+Math.sin(a)*.28*r*1.4;ctx.beginPath();ctx.arc(px,py,1.2,0,Math.PI*2);ctx.fillStyle=`rgba(100,220,255,${.5+.3*Math.sin(this.accretAngle+i)})`;ctx.fill();}
  }
}

// ═══════════════════════════════════════════════════════════════════
//  GALAXY — procedurally generated, sandbox only
//  Types: 0=spiral, 1=elliptical, 2=irregular, 3=barred-spiral
// ═══════════════════════════════════════════════════════════════════
class Galaxy extends CelestialObject{
  constructor(wx,wy,typeOverride){
    super(wx,wy,'galaxy');
    this.galaxyType=typeOverride!==undefined?typeOverride:randInt(0,3);
    this.radius=rand(200,360);this.mass=0;this.fixed=true;
    this.angle=0;this.rotSpeed=rand(.001,.005);
    this.sizeScale=rand(.7,1.4); // allows size adjustment
    this.dustPts=this._generateDust();
    this.coreColor=`hsl(${rand(200,280)},60%,${rand(50,75)}%)`;
    this.armColor=`hsl(${rand(180,260)},50%,${rand(55,70)}%)`;
  }
  _generateDust(){
    const pts=[];const n=randInt(140,240);
    for(let i=0;i<n;i++){
      let a,d,arm;
      switch(this.galaxyType){
        case 0: // Spiral
          arm=Math.floor(rand(0,3));
          d=rand(.1,.98);
          a=rand(0,Math.PI*2)+arm*(Math.PI*2/3)+d*1.8;
          break;
        case 1: // Elliptical — uniform distribution
          a=rand(0,Math.PI*2);
          d=Math.sqrt(rand(0,1))*.95;
          break;
        case 2: // Irregular — clumpy
          a=rand(0,Math.PI*2);
          d=rand(0,.9);
          a+=Math.sin(a*3)*0.6;
          break;
        case 3: // Barred spiral
          arm=Math.floor(rand(0,2));
          d=rand(.05,.98);
          if(d<.3){a=rand(-Math.PI*.1,Math.PI*.1)+arm*Math.PI;} // bar
          else{a=rand(0,Math.PI*2)+arm*Math.PI+d*1.5;}
          break;
        default:a=rand(0,Math.PI*2);d=rand(.1,.95);
      }
      pts.push({
        a,d,r:rand(.8,3.5),
        c:randInt(160,255),
        blue:randInt(180,255),
        al:rand(.12,.55),
        sp:this.rotSpeed*(0.6+rand(0,.8)),
        scaleY:this.galaxyType===1?rand(.5,.95):rand(.38,.7)
      });
    }
    return pts;
  }
  draw(){
    const sx=this.sx(),sy=this.sy(),r=this.sr()*this.sizeScale;
    this.angle+=this.rotSpeed;
    // Core glow
    const gc=ctx.createRadialGradient(sx,sy,0,sx,sy,r*.45);
    gc.addColorStop(0,'rgba(255,245,210,0.45)');gc.addColorStop(.5,this.coreColor.replace('hsl','hsla').replace(')',',0.2)'));gc.addColorStop(1,'transparent');
    ctx.beginPath();ctx.arc(sx,sy,r*.45,0,Math.PI*2);ctx.fillStyle=gc;ctx.fill();
    // Dust particles
    this.dustPts.forEach(p=>{
      p.a+=p.sp;
      const a=p.a+this.angle;
      const px=sx+Math.cos(a)*r*p.d;
      const py=sy+Math.sin(a)*r*p.d*p.scaleY;
      const pr=Math.max(.4,p.r);
      ctx.beginPath();ctx.arc(px,py,pr,0,Math.PI*2);
      ctx.fillStyle=`rgba(${p.c},${Math.round(p.c*.85)},${p.blue},${p.al})`;ctx.fill();
    });
    if(sandboxMode){
      ctx.font=`${Math.max(8,r*.06)}px 'Courier New'`;ctx.fillStyle='rgba(255,255,255,.18)';
      ctx.textAlign='center';ctx.fillText(`${this.name} [${['Espiral','Elíptica','Irregular','Barrada'][this.galaxyType]}]`,sx,sy+r+12*cam.zoom);ctx.textAlign='left';
    }
  }
}

// ═══════════════════════════════════════════════════════════════════
//  DARK MATTER — immune to all gravity/orbit/spacetime
// ═══════════════════════════════════════════════════════════════════
class DarkMatter extends CelestialObject{
  constructor(wx,wy){
    super(wx,wy,'darkmatter');
    this.radius=rand(14,22);this.mass=0;
    this.fixed=true;this.immune=true;
    this.pulseT=rand(0,Math.PI*2);
  }
  draw(){
    const sx=this.sx(),sy=this.sy(),r=this.sr();
    this.pulseT+=.015;
    const p=1+.1*Math.sin(this.pulseT);
    // ── Revelação pela Cefeida ─────────────────────────────────────
    const revealed=(this._revealTimer||0)>0;
    const revAlpha=revealed?Math.min(1,this._revealTimer/0.6):0; // fade in/out
    if(revealed){
      // Halo dourado que "denuncia" a matéria escura
      const rg=ctx.createRadialGradient(sx,sy,r*.3,sx,sy,r*3.5*p);
      rg.addColorStop(0,`rgba(255,210,80,${revAlpha*.55})`);
      rg.addColorStop(.5,`rgba(255,170,30,${revAlpha*.22})`);
      rg.addColorStop(1,'transparent');
      ctx.beginPath();ctx.arc(sx,sy,r*3.5*p,0,Math.PI*2);ctx.fillStyle=rg;ctx.fill();
      // Borda pulsante
      ctx.beginPath();ctx.arc(sx,sy,r*p*1.15,0,Math.PI*2);
      ctx.strokeStyle=`rgba(255,220,60,${revAlpha*.7})`;ctx.lineWidth=2;ctx.stroke();
    }
    // ── Visual base ───────────────────────────────────────────────
    for(let i=4;i>=1;i--){
      const ringAlpha=(.04+.02*(5-i))*(revealed?Math.max(0.25,revAlpha):1);
      ctx.beginPath();ctx.arc(sx,sy,r*i*p*.65,0,Math.PI*2);
      ctx.strokeStyle=revealed?`rgba(200,160,50,${ringAlpha})`:`rgba(90,0,200,${ringAlpha})`;
      ctx.lineWidth=2;ctx.stroke();
    }
    const g=ctx.createRadialGradient(sx,sy,0,sx,sy,r);
    g.addColorStop(0,revealed?`rgba(80,60,0,${0.55*revAlpha})`:'rgba(50,0,120,0.55)');
    g.addColorStop(.6,revealed?`rgba(20,12,0,${0.35*revAlpha})`:'rgba(10,0,30,0.35)');
    g.addColorStop(1,'transparent');
    ctx.beginPath();ctx.arc(sx,sy,r,0,Math.PI*2);ctx.fillStyle=g;ctx.fill();
    if(sandboxMode||revealed){
      ctx.font=`${Math.max(6,r*.44)}px 'Courier New'`;
      ctx.fillStyle=revealed?`rgba(255,200,60,${revAlpha*.7})`:'rgba(130,60,255,.25)';
      ctx.textAlign='center';ctx.fillText(this.name,sx,sy+r+9*cam.zoom);ctx.textAlign='left';
    }
  }
}

// ═══════════════════════════════════════════════════════════════════
//  POLAR STAR — alternates attract (red) / repel (blue) every 5–10s
// ═══════════════════════════════════════════════════════════════════
class PolarStar extends CelestialObject{
  constructor(wx,wy){
    super(wx,wy,'polarstar');
    this.radius=rand(14,20);this.mass=this.radius*12;
    this.fixed=false;this.temp=rand(3000,20000);
    this.attracting=true;
    this._switchTimer=0;this._switchInterval=rand(5,10);
    this.pullRange=this.radius*13;this.glowPhase=rand(0,Math.PI*2);
  }
  draw(t){
    const sx=this.sx(),sy=this.sy(),r=this.sr();
    const p=1+.13*Math.sin(t*2.1+this.glowPhase);
    const col=this.attracting?[255,50,50]:[50,110,255];
    const hex=this.attracting?'#ff3232':'#3264ff';
    const g=ctx.createRadialGradient(sx,sy,r*.4,sx,sy,r*4*p);
    g.addColorStop(0,`rgba(${col[0]},${col[1]},${col[2]},0.28)`);g.addColorStop(1,'transparent');
    ctx.beginPath();ctx.arc(sx,sy,r*4*p,0,Math.PI*2);ctx.fillStyle=g;ctx.fill();
    const g2=ctx.createRadialGradient(sx-r*.3,sy-r*.3,r*.1,sx,sy,r);
    g2.addColorStop(0,'#fff');g2.addColorStop(.4,hex);g2.addColorStop(1,`rgba(${col[0]},${col[1]},${col[2]},0.5)`);
    ctx.beginPath();ctx.arc(sx,sy,r*p,0,Math.PI*2);ctx.fillStyle=g2;ctx.fill();
    ctx.beginPath();ctx.arc(sx,sy,this.pullRange*cam.zoom,0,Math.PI*2);
    ctx.strokeStyle=`rgba(${col[0]},${col[1]},${col[2]},0.06)`;ctx.lineWidth=1;ctx.stroke();
    ctx.font=`${Math.max(6,r*.42)}px 'Courier New'`;
    ctx.fillStyle=`rgba(${col[0]},${col[1]},${col[2]},.5)`;ctx.textAlign='center';
    ctx.fillText(this.attracting?'▼ ATRAI':'▲ REPELE',sx,sy+r+11*cam.zoom);ctx.textAlign='left';
  }
}

// ═══════════════════════════════════════════════════════════════════
//  VOID BELT — invisible patch; seals glitch-ghost of any passing astro
// ═══════════════════════════════════════════════════════════════════
class VoidBelt extends CelestialObject{
  constructor(wx,wy){
    super(wx,wy,'voidbelt');
    this.radius=rand(28,50);this.mass=0;
    this.fixed=true;this.immune=true;
    this.ghosts=[];// {x,y,type,radius,color,glitchT}
    this._pulseT=rand(0,Math.PI*2);
  }
  draw(t){
    this._pulseT+=.012;
    const sx=this.sx(),sy=this.sy(),r=this.sr();
    // ── Revelação pela Cefeida ─────────────────────────────────────
    const _vbRev=(this._revealTimer||0)>0;
    const _vbA=_vbRev?Math.min(1,this._revealTimer/0.6):0;
    if(_vbRev){
      // Cinturão iluminado — contorno dourado + halo interno
      const _vbG=ctx.createRadialGradient(sx,sy,r*.6,sx,sy,r*1.55);
      _vbG.addColorStop(0,`rgba(255,200,60,${_vbA*.35})`);
      _vbG.addColorStop(1,'transparent');
      ctx.beginPath();ctx.arc(sx,sy,r*1.55,0,Math.PI*2);ctx.fillStyle=_vbG;ctx.fill();
      ctx.beginPath();ctx.arc(sx,sy,r,0,Math.PI*2);
      ctx.strokeStyle=`rgba(255,220,80,${_vbA*.65})`;ctx.lineWidth=2.5;ctx.stroke();
      // Label "VAZIO" revelado
      ctx.font=`${Math.max(6,r*.32)}px 'Courier New'`;
      ctx.fillStyle=`rgba(255,210,60,${_vbA*.75})`;ctx.textAlign='center';
      ctx.fillText('CINTURÃO DO VAZIO',sx,sy+r+11*cam.zoom);ctx.textAlign='left';
    }
    // Very faint ring — barely visible (sempre presente mas tênue)
    ctx.beginPath();ctx.arc(sx,sy,r,0,Math.PI*2);
    ctx.strokeStyle=`rgba(255,255,255,${.03+.02*Math.sin(this._pulseT)+_vbA*.15})`;ctx.lineWidth=1;ctx.stroke();
    // Draw glitch ghosts
    this.ghosts.forEach(gh=>{
      gh.glitchT+=.07;
      const gsx=worldToScreen(gh.x,gh.y).x,gsy=worldToScreen(gh.x,gh.y).y;
      const gr=gh.radius*cam.zoom;
      // Random jitter
      const jx=(Math.random()-.5)*4*Math.sin(gh.glitchT*13);
      const jy=(Math.random()-.5)*4*Math.sin(gh.glitchT*17);
      // Glitch banding — draw sliced offset strips
      ctx.save();ctx.globalAlpha=.55+.2*Math.sin(gh.glitchT*7);
      // Color split (chromatic aberration style)
      ctx.globalCompositeOperation='lighter';
      ctx.beginPath();ctx.arc(gsx+jx-2,gsy+jy,gr,0,Math.PI*2);ctx.fillStyle='rgba(255,0,80,0.25)';ctx.fill();
      ctx.beginPath();ctx.arc(gsx+jx+2,gsy+jy,gr,0,Math.PI*2);ctx.fillStyle='rgba(0,200,255,0.25)';ctx.fill();
      ctx.globalCompositeOperation='source-over';
      // Main ghost body
      ctx.beginPath();ctx.arc(gsx+jx,gsy+jy,gr,0,Math.PI*2);
      ctx.fillStyle=(gh.color||'#aaa')+'55';ctx.fill();
      // Glitch scan lines
      for(let ln=0;ln<3;ln++){
        const ly=gsy+jy-gr+Math.random()*gr*2;
        if(Math.random()<.4){ctx.fillRect(gsx+jx-gr,ly,.5,1);} // random thin bars
      }
      ctx.globalAlpha=1;ctx.restore();
      // "ERROR" text flicker
      if(Math.random()<.18){
        ctx.font=`${Math.max(5,gr*.45)}px 'Courier New'`;
        ctx.fillStyle=`rgba(255,80,80,${Math.random()*.7+.2})`;
        ctx.textAlign='center';
        ctx.fillText(['ERR','???','NULL','VOID','0xFF'][Math.floor(Math.random()*5)],gsx+jx,gsy+jy-gr-4);
        ctx.textAlign='left';
      }
    });
  }
}

// ═══════════════════════════════════════════════════════════════════
//  RIFT FISSURE — neon purple crack; drastically slows nearby astros
// ═══════════════════════════════════════════════════════════════════
class RiftFissure extends CelestialObject{
  constructor(wx,wy){
    super(wx,wy,'riftfissure');
    this.radius=rand(18,32);this.mass=0;
    this.fixed=true;this.immune=true;
    this.angle=rand(0,Math.PI);
    this.slowRange=this.radius*6;
    this._glowT=rand(0,Math.PI*2);
    this._crackPts=this._genCrack();
  }
  _genCrack(){
    const pts=[{x:0,y:0}];let cx=0,cy=0;
    for(let i=0;i<8;i++){
      cx+=rand(-12,12);cy+=rand(-12,12);
      pts.push({x:cx,y:cy});
      if(Math.random()<.4){
        // Branch
        const bx=cx+rand(-8,8),by=cy+rand(-8,8);
        pts.push({x:bx,y:by},{x:cx,y:cy}); // back to main
      }
    }
    return pts;
  }
  draw(t){
    this._glowT+=.04;
    const sx=this.sx(),sy=this.sy(),r=this.sr();
    const bright=.7+.3*Math.sin(this._glowT*3);
    // Slow range ring
    ctx.beginPath();ctx.arc(sx,sy,this.slowRange*cam.zoom,0,Math.PI*2);
    ctx.strokeStyle=`rgba(180,0,255,${.06*bright})`;ctx.lineWidth=1;ctx.stroke();
    // Outer purple glow
    const glow=ctx.createRadialGradient(sx,sy,0,sx,sy,r*4);
    glow.addColorStop(0,`rgba(200,0,255,${.4*bright})`);glow.addColorStop(.5,'rgba(120,0,200,0.1)');glow.addColorStop(1,'transparent');
    ctx.beginPath();ctx.arc(sx,sy,r*4,0,Math.PI*2);ctx.fillStyle=glow;ctx.fill();
    // Draw crack
    ctx.save();ctx.translate(sx,sy);ctx.rotate(this.angle);ctx.scale(cam.zoom,cam.zoom);
    ctx.lineJoin='round';ctx.lineCap='round';
    // Outer glow pass
    ctx.beginPath();
    this._crackPts.forEach((p,i)=>i===0?ctx.moveTo(p.x,p.y):ctx.lineTo(p.x,p.y));
    ctx.strokeStyle=`rgba(220,100,255,${.45*bright})`;ctx.lineWidth=7;ctx.stroke();
    // Mid pass
    ctx.beginPath();
    this._crackPts.forEach((p,i)=>i===0?ctx.moveTo(p.x,p.y):ctx.lineTo(p.x,p.y));
    ctx.strokeStyle=`rgba(200,0,255,${.85*bright})`;ctx.lineWidth=3.5;ctx.stroke();
    // White core
    ctx.beginPath();
    this._crackPts.forEach((p,i)=>i===0?ctx.moveTo(p.x,p.y):ctx.lineTo(p.x,p.y));
    ctx.strokeStyle=`rgba(255,255,255,${.9*bright})`;ctx.lineWidth=1.2;ctx.stroke();
    ctx.restore();
    if(sandboxMode){ctx.font='7px Courier New';ctx.fillStyle='rgba(200,0,255,.35)';ctx.textAlign='center';ctx.fillText('FENDA',sx,sy+r*cam.zoom+10);ctx.textAlign='left';}
  }
}

// ═══════════════════════════════════════════════════════════════════
//  VETOCRINAZAR — entidade cósmica suprema. Maior que um BH.
//  Visual assustador, destrutivo e imponente.
//  Muda de cor ao mudar de modo. Tentáculos, olho maligno, cristais.
// ═══════════════════════════════════════════════════════════════════
class Vetocrinazar extends CelestialObject{
  constructor(wx,wy){
    super(wx,wy,'vetocrinazar');
    // Maior que buraco negro — bem grande
    this.radius=rand(34,48); this.mass=this.radius*50;
    this.fixed=true; this.immune=false;
    this.modeTimer=0; this.modeInterval=5;
    this.mode=0; // 0=attract 1=repel 2=orbit 3=chaotic
    this.pullRange=this.radius*18;
    this._orbitEcc=rand(0,0.7); this._orbitDist=rand(60,180);
    // Animação
    this._rotA=0; this._pulseT=rand(0,Math.PI*2); this._ringRot=0;
    this._tentT=rand(0,Math.PI*2); this._eyeT=rand(0,Math.PI*2);
    this._shockT=0; this._crackT=rand(0,Math.PI*2);
    this._crystalA=rand(0,Math.PI*2);
    // Paleta por modo — muda cor completamente ao trocar
    this._palettes=[
      {c1:'#ff0800',c2:'#ff4400',c3:'#ff8800',gA:'rgba(255,20,0,',   rA:'rgba(255,60,10,',  label:'▼▼ DEVORA TUDO',   bg:[40,0,0]},
      {c1:'#0044ff',c2:'#0099ff',c3:'#00ddff',gA:'rgba(0,60,255,',   rA:'rgba(10,160,255,', label:'▲▲ EXPELE FORÇA',  bg:[0,10,45]},
      {c1:'#ddcc00',c2:'#ff9900',c3:'#ffcc00',gA:'rgba(200,150,0,',  rA:'rgba(255,180,0,',  label:'◎ APRISIONA',      bg:[35,25,0]},
      {c1:'#cc00ff',c2:'#ff00cc',c3:'#ff44ff',gA:'rgba(170,0,255,',  rA:'rgba(255,0,200,',  label:'⚡ CAOS ABSOLUTO', bg:[30,0,40]},
    ];
  }
  draw(t){
    const sx=this.sx(),sy=this.sy(),r=this.sr();
    this._rotA +=.022+this.mode*.016;
    this._pulseT+=.06; this._ringRot+=.014;
    this._tentT +=.042; this._eyeT  +=.08;
    this._crackT+=.055; this._crystalA+=.01;
    const p=1+.16*Math.sin(this._pulseT);
    const P=this._palettes[this.mode];
    const {c1,c2,c3,gA,rA,label,bg}=P;

    // ── Onda de choque ao mudar modo ──
    if(this._shockT>0){
      this._shockT-=.028;
      const sw=this._shockT;
      // Múltiplas ondas de choque concêntricas
      for(let si=0;si<3;si++){
        const swi=Math.max(0,sw-si*.08);
        if(swi<=0)continue;
        ctx.beginPath();
        ctx.arc(sx,sy,r*(1+(1-swi)*(12+si*4))*cam.zoom,0,Math.PI*2);
        const hexAlpha=Math.round(swi*200).toString(16).padStart(2,'0');
        ctx.strokeStyle=c1+hexAlpha;
        ctx.lineWidth=(4-si*1.2); ctx.stroke();
      }
      triggerFlash(this._shockT*.15,200);
    }

    // ── Fundo local escurecido e tingido pela cor do modo ──
    const bgG=ctx.createRadialGradient(sx,sy,r*cam.zoom,sx,sy,r*14*cam.zoom);
    bgG.addColorStop(0,`rgba(${bg[0]},${bg[1]},${bg[2]},0.72)`);
    bgG.addColorStop(.4,`rgba(${bg[0]>>1},${bg[1]>>1},${bg[2]>>1},0.38)`);
    bgG.addColorStop(1,'transparent');
    ctx.beginPath();ctx.arc(sx,sy,r*14*cam.zoom,0,Math.PI*2);
    ctx.fillStyle=bgG;ctx.fill();

    // ── Range ring ──
    ctx.beginPath(); ctx.arc(sx,sy,this.pullRange*cam.zoom,0,Math.PI*2);
    ctx.strokeStyle=rA+'0.06)'; ctx.lineWidth=1; ctx.stroke();

    // ── Halos externos em 4 camadas com cor do modo ──
    [10,6.5,4,2.2].forEach((m,i)=>{
      const og=ctx.createRadialGradient(sx,sy,r*cam.zoom,sx,sy,r*m*p*cam.zoom);
      og.addColorStop(0,gA+['.32)','.22)','.14)','.06)'][i]);
      og.addColorStop(1,'transparent');
      ctx.beginPath(); ctx.arc(sx,sy,r*m*p*cam.zoom,0,Math.PI*2);
      ctx.fillStyle=og; ctx.fill();
    });

    // ── Raios de energia desestabilizadores (não são tentáculos suaves — são raios erráticos) ──
    const nT=8+(this.mode===3?6:0);
    for(let i=0;i<nT;i++){
      const baseAng=this._tentT+i*(Math.PI*2/nT);
      // Comprimento variável e errático por modo
      const modFlux=this.mode===3?2.2:1.0;
      const tLen=r*(2.2+modFlux*Math.abs(Math.sin(this._pulseT*2.4+i)))*cam.zoom;
      // Raio errático com múltiplos nós
      ctx.save();
      ctx.beginPath();
      ctx.moveTo(sx,sy);
      const segments=4;
      let cx_=sx, cy_=sy;
      for(let s=0;s<segments;s++){
        const segFrac=(s+1)/segments;
        const wig=(.45+this.mode*.1)*Math.sin(this._tentT*3.1+i*1.7+s*2.3);
        const nx_=sx+Math.cos(baseAng+wig)*tLen*segFrac;
        const ny_=sy+Math.sin(baseAng+wig)*tLen*segFrac;
        ctx.lineTo(nx_,ny_);
        cx_=nx_; cy_=ny_;
      }
      const tentAlpha=(.55+.22*Math.sin(this._pulseT*2+i));
      ctx.strokeStyle=rA+tentAlpha+')';
      ctx.lineWidth=(3.5-i*.2)*cam.zoom; ctx.lineCap='round'; ctx.stroke();
      // Nodo brilhante na ponta
      const ng=ctx.createRadialGradient(cx_,cy_,0,cx_,cy_,7*cam.zoom);
      ng.addColorStop(0,'#ffffff'); ng.addColorStop(.3,c1); ng.addColorStop(1,'transparent');
      ctx.beginPath(); ctx.arc(cx_,cy_,7*cam.zoom,0,Math.PI*2);
      ctx.fillStyle=ng; ctx.fill();
      ctx.restore();
    }

    // ── Cristais de energia radiando do núcleo ──
    const nCrystal=6;
    for(let i=0;i<nCrystal;i++){
      const ca=this._crystalA+i*(Math.PI*2/nCrystal)+this._rotA*.3;
      const cl=r*(1.3+.5*Math.sin(this._pulseT*1.8+i))*cam.zoom;
      const cw=r*.18*cam.zoom;
      ctx.save();ctx.translate(sx,sy);ctx.rotate(ca);
      ctx.beginPath();
      ctx.moveTo(0,0);
      ctx.lineTo(-cw,-cl*.35);
      ctx.lineTo(0,-cl);
      ctx.lineTo(cw,-cl*.35);
      ctx.closePath();
      const crystG=ctx.createLinearGradient(0,0,0,-cl);
      crystG.addColorStop(0,c2);
      crystG.addColorStop(.5,c1);
      crystG.addColorStop(1,'rgba(255,255,255,0.9)');
      ctx.fillStyle=crystG;ctx.globalAlpha=.6+.2*Math.sin(this._pulseT*3+i);ctx.fill();
      ctx.strokeStyle=c3;ctx.lineWidth=1*cam.zoom;ctx.globalAlpha=.8;ctx.stroke();
      ctx.globalAlpha=1;
      ctx.restore();
    }

    // ── Anéis orbitais inclinados e contrarrotantes (6 anéis) ──
    for(let i=0;i<6;i++){
      ctx.save(); ctx.translate(sx,sy);
      ctx.rotate(this._ringRot*(i%2===0?1:-1)+i*(Math.PI/3));
      ctx.scale(1,.15+i*.04);
      ctx.beginPath(); ctx.arc(0,0,r*(1.5+i*.55)*p*cam.zoom,0,Math.PI*2);
      const ringAlpha=['0.85)','0.70)','0.55)','0.38)','0.22)','0.10)'][i];
      ctx.strokeStyle=(i%2===0?rA:gA)+ringAlpha;
      ctx.lineWidth=(4-i*.55)*cam.zoom; ctx.stroke(); ctx.restore();
    }

    // ── Núcleo: forma irregular pulsante — polígono côncavo/convexo ──
    ctx.save(); ctx.translate(sx,sy); ctx.rotate(this._rotA*1.6);
    const nPoly=12;
    ctx.beginPath();
    for(let i=0;i<nPoly;i++){
      const a=i*Math.PI*2/nPoly;
      // Alterna entre pontas salientes e reentrâncias
      const rMod= i%2===0
        ? r*p*cam.zoom*(1+.22*Math.sin(this._crackT*2.5+i))
        : r*p*cam.zoom*(0.62+.08*Math.sin(this._crackT*1.8+i));
      const px_=Math.cos(a)*rMod, py_=Math.sin(a)*rMod;
      i===0?ctx.moveTo(px_,py_):ctx.lineTo(px_,py_);
    }
    ctx.closePath();
    const cg=ctx.createLinearGradient(-r*cam.zoom,-r*cam.zoom,r*cam.zoom,r*cam.zoom);
    cg.addColorStop(0,c1); cg.addColorStop(.25,'#040005');
    cg.addColorStop(.5,'#030003'); cg.addColorStop(.75,'#040005');
    cg.addColorStop(1,c2);
    ctx.fillStyle=cg; ctx.fill();
    // Borda brilhante do núcleo
    ctx.strokeStyle=c3; ctx.lineWidth=2*cam.zoom;
    ctx.shadowColor=c1; ctx.shadowBlur=12; ctx.stroke();
    ctx.shadowBlur=0;
    ctx.restore();

    // ── Camada interna rotacionada oposta ──
    ctx.save(); ctx.translate(sx,sy); ctx.rotate(-this._rotA*2.2);
    const s2=r*.5*p*cam.zoom;
    ctx.beginPath();
    for(let i=0;i<8;i++){
      const a=i*Math.PI*2/8;
      const rMod2=i%2===0?s2:s2*.55;
      i===0?ctx.moveTo(Math.cos(a)*rMod2,Math.sin(a)*rMod2):ctx.lineTo(Math.cos(a)*rMod2,Math.sin(a)*rMod2);
    }
    ctx.closePath();
    const cg2=ctx.createLinearGradient(-s2,-s2,s2,s2);
    cg2.addColorStop(0,'#010001'); cg2.addColorStop(.5,c2); cg2.addColorStop(1,'#010001');
    ctx.fillStyle=cg2; ctx.fill();
    ctx.restore();

    // ── "Olho" central maligno: fenda elíptica vertical com pupila que dilata ──
    ctx.save(); ctx.translate(sx,sy);
    // Esclera avermelhada
    const eW=r*.62*cam.zoom, eH=r*.24*cam.zoom*(1+.55*Math.abs(Math.sin(this._eyeT)));
    ctx.beginPath(); ctx.ellipse(0,0,eW,eH,this._rotA*.5,0,Math.PI*2);
    const eyeBg=ctx.createRadialGradient(0,0,0,0,0,eW);
    eyeBg.addColorStop(0,'rgba(255,255,255,0.95)');
    eyeBg.addColorStop(.25,c3);
    eyeBg.addColorStop(.65,c1);
    eyeBg.addColorStop(1,'rgba(0,0,0,0.92)');
    ctx.fillStyle=eyeBg; ctx.fill();
    // Pupila — fenda vertical escura que se contrai/dilata
    const pupW=eW*.28*(0.5+.5*Math.abs(Math.sin(this._eyeT*1.3)));
    const pupH=eH*1.2;
    ctx.beginPath(); ctx.ellipse(0,0,pupW,pupH,0,0,Math.PI*2);
    ctx.fillStyle='rgba(0,0,0,0.96)'; ctx.fill();
    // Brilho de destaque no olho
    ctx.beginPath(); ctx.ellipse(-eW*.22,-eH*.2,eW*.1,eH*.15,-.5,0,Math.PI*2);
    ctx.fillStyle='rgba(255,255,255,0.7)'; ctx.fill();
    ctx.restore();

    // ── Fendas de energia irradiando do centro (rachaduras) ──
    for(let i=0;i<4;i++){
      const ca=this._crackT+i*Math.PI*.5+this._rotA*.4;
      const cl2=r*(.85+.35*Math.sin(this._crackT*4+i))*cam.zoom;
      ctx.save();ctx.translate(sx,sy);ctx.rotate(ca);
      ctx.beginPath();ctx.moveTo(0,0);
      // Rachadura com jitter
      let cy2=0;
      for(let s=0;s<5;s++){
        cy2-=cl2/5;
        const jx=(Math.random()-.5)*r*.15*cam.zoom;
        ctx.lineTo(jx,cy2);
      }
      const crackG=ctx.createLinearGradient(0,0,0,-cl2);
      crackG.addColorStop(0,'rgba(255,255,255,0.9)');
      crackG.addColorStop(.3,c3);
      crackG.addColorStop(1,'transparent');
      ctx.strokeStyle=crackG;ctx.lineWidth=1.5*cam.zoom;ctx.stroke();
      ctx.restore();
    }

    // ── Label de modo ──
    ctx.font=`bold ${Math.max(9,r*.22)}px 'Courier New'`;
    ctx.fillStyle=c3; ctx.textAlign='center';
    ctx.fillText(label,sx,sy+r*p*cam.zoom+20); ctx.textAlign='left';
  }
}
// ═══════════════════════════════════════════════════════════════════
//  TWINSTAR — par binário de estrelas super-brilhantes orbitando
//  entre si. Astros próximos são forçados em órbita lemniscata (∞/8),
//  passando pelo ponto central entre as duas estrelas.
// ═══════════════════════════════════════════════════════════════════
class TwinStar extends CelestialObject{
  constructor(wx,wy){
    super(wx,wy,'twinstar');
    this.radius=rand(14,20); this.mass=this.radius*20;
    this.fixed=true; this.immune=false; // BH pode atrair Estrelas Gêmeas
    this.sep=rand(38,58);           // metade da separação entre as estrelas
    this._angle=rand(0,Math.PI*2);  // ângulo atual do par
    this._rotSpeed=rand(.28,.55);   // rad/s
    this.captureRange=this.sep*6.5;
    this._glowT=rand(0,Math.PI*2);
    this._trailPts=[];              // rastro da órbita em 8
    this._trailTimer=0;
    // Cores das duas estrelas (A=quente/amarela, B=azul-branca)
    this._hueA=rand(38,55);   // amarelo-laranja
    this._hueB=rand(195,230); // azul
  }
  draw(t){
    this._glowT+=.05;
    const sx=this.sx(),sy=this.sy(),r=this.sr();
    // Posições das duas estrelas
    const ax=sx+Math.cos(this._angle)*this.sep*cam.zoom;
    const ay=sy+Math.sin(this._angle)*this.sep*cam.zoom;
    const bx=sx-Math.cos(this._angle)*this.sep*cam.zoom;
    const by=sy-Math.sin(this._angle)*this.sep*cam.zoom;

    // ── Campo de captura (hint visual sutil) ──
    ctx.beginPath();ctx.arc(sx,sy,this.captureRange*cam.zoom,0,Math.PI*2);
    ctx.strokeStyle='rgba(255,230,120,0.035)';ctx.lineWidth=1;ctx.stroke();

    // ── Linha gravitacional de conexão com efeito de pulso ──
    const lineAlpha=.12+.06*Math.sin(this._glowT*2.5);
    const lg=ctx.createLinearGradient(ax,ay,bx,by);
    lg.addColorStop(0,`hsla(${this._hueA},100%,75%,${lineAlpha})`);
    lg.addColorStop(.5,`rgba(255,255,255,${lineAlpha*1.8})`);
    lg.addColorStop(1,`hsla(${this._hueB},100%,75%,${lineAlpha})`);
    ctx.save();ctx.beginPath();ctx.moveTo(ax,ay);ctx.lineTo(bx,by);
    ctx.strokeStyle=lg;ctx.lineWidth=1.5;ctx.stroke();ctx.restore();

    // ── Trajetória lemniscata (∞) desenhada como guia sutil ──
    ctx.save();ctx.globalAlpha=0.06;ctx.beginPath();
    const lSteps=80,lA=this.sep*cam.zoom,lB=this.sep*cam.zoom*.55;
    for(let i=0;i<=lSteps;i++){
      const theta=(i/lSteps)*Math.PI*2;
      // Curva de Bernoulli: x=a*cos(t)/(1+sin²t), y=a*sin(t)*cos(t)/(1+sin²t)
      const denom=1+Math.sin(theta)*Math.sin(theta);
      const lx=sx+(lA*Math.cos(theta)/denom)*Math.cos(this._angle)-(lB*Math.sin(theta)*Math.cos(theta)/denom)*Math.sin(this._angle);
      const ly=sy+(lA*Math.cos(theta)/denom)*Math.sin(this._angle)+(lB*Math.sin(theta)*Math.cos(theta)/denom)*Math.cos(this._angle);
      i===0?ctx.moveTo(lx,ly):ctx.lineTo(lx,ly);
    }
    ctx.closePath();
    ctx.strokeStyle=`rgba(255,240,160,0.7)`;ctx.lineWidth=1;ctx.stroke();
    ctx.restore();

    // ── Cada estrela — visual ultra-brilhante ──
    [[ax,ay,this._hueA,'#fff8e0'],[bx,by,this._hueB,'#e0f0ff']].forEach(([ex,ey,hue,inner],idx)=>{
      const pulse=1+.18*Math.sin(this._glowT*(idx===0?2.2:1.7)+idx*1.4);
      const rS=r*pulse*cam.zoom;

      // Halo difuso externo — 4 camadas de bloom
      for(let i=4;i>=1;i--){
        const hR=rS*(2.2+i*1.4);
        const hg=ctx.createRadialGradient(ex,ey,rS*.3,ex,ey,hR);
        hg.addColorStop(0,`hsla(${hue},100%,90%,${.18/i})`);
        hg.addColorStop(.5,`hsla(${hue},100%,70%,${.07/i})`);
        hg.addColorStop(1,'transparent');
        ctx.beginPath();ctx.arc(ex,ey,hR,0,Math.PI*2);
        ctx.fillStyle=hg;ctx.fill();
      }

      // Raios de difração (spikes de luz — 4 pontas como estrela real)
      for(let sp=0;sp<4;sp++){
        const spAngle=sp*Math.PI/2+this._glowT*(idx===0?.04:-.04);
        const spLen=rS*(3.8+1.4*Math.sin(this._glowT*3+sp));
        const spg=ctx.createLinearGradient(ex,ey,ex+Math.cos(spAngle)*spLen,ey+Math.sin(spAngle)*spLen);
        spg.addColorStop(0,`hsla(${hue},100%,95%,${.55*pulse})`);
        spg.addColorStop(.35,`hsla(${hue},100%,85%,${.22*pulse})`);
        spg.addColorStop(1,'transparent');
        ctx.save();ctx.beginPath();ctx.moveTo(ex,ey);
        ctx.lineTo(ex+Math.cos(spAngle)*spLen,ey+Math.sin(spAngle)*spLen);
        ctx.strokeStyle=spg;ctx.lineWidth=Math.max(1,(4-sp*.5)*cam.zoom);
        ctx.lineCap='round';ctx.stroke();
        // Spike oposto (mais curto)
        const spg2=ctx.createLinearGradient(ex,ey,ex-Math.cos(spAngle)*spLen*.5,ey-Math.sin(spAngle)*spLen*.5);
        spg2.addColorStop(0,`hsla(${hue},100%,95%,${.35*pulse})`);spg2.addColorStop(1,'transparent');
        ctx.beginPath();ctx.moveTo(ex,ey);
        ctx.lineTo(ex-Math.cos(spAngle)*spLen*.5,ey-Math.sin(spAngle)*spLen*.5);
        ctx.strokeStyle=spg2;ctx.lineWidth=Math.max(.5,(2.5-sp*.4)*cam.zoom);ctx.stroke();
        ctx.restore();
      }

      // Corpo da estrela — gradiente não-uniforme com núcleo branco
      const sg=ctx.createRadialGradient(ex-rS*.25,ey-rS*.25,rS*.04,ex,ey,rS);
      sg.addColorStop(0,'#ffffff');
      sg.addColorStop(.18,inner);
      sg.addColorStop(.55,`hsla(${hue},100%,72%,0.95)`);
      sg.addColorStop(.85,`hsla(${hue},100%,52%,0.55)`);
      sg.addColorStop(1,`hsla(${hue},100%,40%,0.20)`);
      ctx.beginPath();ctx.arc(ex,ey,rS,0,Math.PI*2);ctx.fillStyle=sg;ctx.fill();

      // Corona brilhante na borda
      const cg=ctx.createRadialGradient(ex,ey,rS*.8,ex,ey,rS*1.7);
      cg.addColorStop(0,`rgba(255,255,255,${.45+.15*Math.sin(this._glowT*4+idx)})`);
      cg.addColorStop(.6,`hsla(${hue},100%,80%,0.08)`);
      cg.addColorStop(1,'transparent');
      ctx.beginPath();ctx.arc(ex,ey,rS*1.7,0,Math.PI*2);ctx.fillStyle=cg;ctx.fill();
    });

    // Label em sandbox
    if(sandboxMode){
      ctx.font=`${Math.max(7,r*.38)}px 'Courier New'`;
      ctx.fillStyle='rgba(255,240,160,.38)';ctx.textAlign='center';
      ctx.fillText('★ GÊMEAS ★',sx,sy+this.sep*cam.zoom+r*cam.zoom+14);
      ctx.textAlign='left';
    }
  }
}

// ═══════════════════════════════════════════════════════════════════
//  TRIPLE STAR — 3 estrelas em triângulo com órbita mútua
//  Desbloqueado pela conquista "Sucção Tripla"
//  Planetas orbitam cada estrela dando volta em todas as 3
// ═══════════════════════════════════════════════════════════════════
class TripleStar extends CelestialObject{
  constructor(wx,wy){
    super(wx,wy,'triplestar');
    this.radius=rand(12,18);this.mass=this.radius*25;
    this.fixed=true;this.immune=false;
    this._angle=rand(0,Math.PI*2);
    this._rotSpeed=rand(.18,.32);
    this.sep=rand(55,80); // distância de cada estrela ao centro
    this.captureRange=this.sep*7;
    this._glowT=rand(0,Math.PI*2);
    // 3 estrelas com cores distintas
    this._hues=[rand(30,55), rand(195,230), rand(280,320)];
    this._trailPts=[];this._trailTimer=0;
  }
  draw(t){
    this._glowT+=.04;this._angle+=this._rotSpeed*(1/60);
    const sx=this.sx(),sy=this.sy(),r=this.sr();
    const z=cam.zoom;

    // ── Campo de captura sutil ──
    ctx.beginPath();ctx.arc(sx,sy,this.captureRange*z,0,Math.PI*2);
    ctx.strokeStyle='rgba(255,200,100,0.025)';ctx.lineWidth=1;ctx.stroke();

    // ── Guia orbital triangular (elipse ao redor das 3 estrelas) ──
    ctx.save();ctx.globalAlpha=0.07;
    ctx.beginPath();
    const triR=this.sep*z*1.15;
    ctx.ellipse(sx,sy,triR,triR*.55,this._angle,0,Math.PI*2);
    ctx.strokeStyle='rgba(255,240,180,.7)';ctx.lineWidth=1.2;ctx.setLineDash([6,10]);ctx.stroke();
    ctx.setLineDash([]);ctx.restore();

    // ── Halos internos do sistema (3 anéis pulsantes) ──
    for(let ring=0;ring<3;ring++){
      const rR=this.sep*z*(0.35+ring*0.28);
      const rA=0.06+0.03*Math.sin(this._glowT*1.8+ring*1.2);
      ctx.beginPath();ctx.arc(sx,sy,rR,0,Math.PI*2);
      ctx.strokeStyle=`rgba(255,230,160,${rA})`;ctx.lineWidth=1;ctx.stroke();
    }

    // ── Linhas de conexão gravitacional entre as 3 estrelas ──
    for(let i=0;i<3;i++){
      const a1=this._angle+i*(Math.PI*2/3);
      const a2=this._angle+((i+1)%3)*(Math.PI*2/3);
      const x1=sx+Math.cos(a1)*this.sep*z, y1=sy+Math.sin(a1)*this.sep*z;
      const x2=sx+Math.cos(a2)*this.sep*z, y2=sy+Math.sin(a2)*this.sep*z;
      const hue1=this._hues[i], hue2=this._hues[(i+1)%3];
      const lineAlpha=.12+.06*Math.sin(this._glowT*2.5+i);
      const lg=ctx.createLinearGradient(x1,y1,x2,y2);
      lg.addColorStop(0,`hsla(${hue1},100%,75%,${lineAlpha})`);
      lg.addColorStop(.5,`rgba(255,255,255,${lineAlpha*1.5})`);
      lg.addColorStop(1,`hsla(${hue2},100%,75%,${lineAlpha})`);
      ctx.save();ctx.beginPath();ctx.moveTo(x1,y1);ctx.lineTo(x2,y2);
      ctx.strokeStyle=lg;ctx.lineWidth=1.5;ctx.stroke();ctx.restore();
    }

    // ── 3 estrelas no triângulo equilátero girando ──
    for(let i=0;i<3;i++){
      const a=this._angle+i*(Math.PI*2/3);
      const ax=sx+Math.cos(a)*this.sep*z;
      const ay=sy+Math.sin(a)*this.sep*z;
      const hue=this._hues[i];
      const pulse=1+.15*Math.sin(this._glowT*(1.8+i*.4)+i*1.1);
      const rS=r*pulse;

      // Halo difuso externo — 3 camadas de bloom
      for(let bl=3;bl>=1;bl--){
        const hR=rS*(1.8+bl*1.2);
        const hg=ctx.createRadialGradient(ax,ay,rS*.2,ax,ay,hR);
        hg.addColorStop(0,`hsla(${hue},100%,85%,${.16/bl})`);
        hg.addColorStop(.5,`hsla(${hue},100%,65%,${.06/bl})`);
        hg.addColorStop(1,'transparent');
        ctx.beginPath();ctx.arc(ax,ay,hR,0,Math.PI*2);
        ctx.fillStyle=hg;ctx.fill();
      }

      // Raios de difração (4 spikes de luz)
      for(let sp=0;sp<4;sp++){
        const spAngle=sp*Math.PI/2+this._glowT*(i===0?.035:i===1?-.028:.042);
        const spLen=rS*(2.8+.8*Math.sin(this._glowT*3+sp+i));
        const spg=ctx.createLinearGradient(ax,ay,ax+Math.cos(spAngle)*spLen,ay+Math.sin(spAngle)*spLen);
        spg.addColorStop(0,`hsla(${hue},100%,95%,${.5*pulse})`);
        spg.addColorStop(.4,`hsla(${hue},100%,80%,${.18*pulse})`);
        spg.addColorStop(1,'transparent');
        ctx.save();ctx.beginPath();ctx.moveTo(ax,ay);
        ctx.lineTo(ax+Math.cos(spAngle)*spLen,ay+Math.sin(spAngle)*spLen);
        ctx.strokeStyle=spg;ctx.lineWidth=Math.max(.8,(3-sp*.5)*z);
        ctx.lineCap='round';ctx.stroke();ctx.restore();
      }

      // Corpo da estrela — gradiente não-uniforme com núcleo branco
      const innerColors=['#fff8e0','#e0f8ff','#ffe0f0'];
      const sg=ctx.createRadialGradient(ax-rS*.25,ay-rS*.25,rS*.04,ax,ay,rS);
      sg.addColorStop(0,'#ffffff');
      sg.addColorStop(.18,innerColors[i]);
      sg.addColorStop(.55,`hsla(${hue},100%,70%,0.95)`);
      sg.addColorStop(.88,`hsla(${hue},100%,45%,0.5)`);
      sg.addColorStop(1,`hsla(${hue},100%,35%,0.18)`);
      ctx.beginPath();ctx.arc(ax,ay,rS,0,Math.PI*2);ctx.fillStyle=sg;ctx.fill();

      // Corona brilhante na borda
      const cg=ctx.createRadialGradient(ax,ay,rS*.75,ax,ay,rS*1.65);
      cg.addColorStop(0,`rgba(255,255,255,${.4+.12*Math.sin(this._glowT*4+i)})`);
      cg.addColorStop(.6,`hsla(${hue},100%,75%,0.07)`);
      cg.addColorStop(1,'transparent');
      ctx.beginPath();ctx.arc(ax,ay,rS*1.65,0,Math.PI*2);ctx.fillStyle=cg;ctx.fill();
    }

    // ── Núcleo central — ponto de equilíbrio gravitacional brilhante ──
    const coreR=r*.32;
    const cg=ctx.createRadialGradient(sx,sy,0,sx,sy,coreR*3.5);
    cg.addColorStop(0,'rgba(255,255,255,0.9)');
    cg.addColorStop(.3,'rgba(255,240,160,.45)');
    cg.addColorStop(.7,'rgba(255,200,80,.1)');
    cg.addColorStop(1,'transparent');
    ctx.beginPath();ctx.arc(sx,sy,coreR*3.5,0,Math.PI*2);ctx.fillStyle=cg;ctx.fill();
    ctx.beginPath();ctx.arc(sx,sy,coreR,0,Math.PI*2);
    ctx.fillStyle='rgba(255,255,255,.85)';ctx.fill();

    // Label em sandbox
    if(sandboxMode){
      ctx.font=`${Math.max(7,r*.36)}px 'Courier New'`;
      ctx.fillStyle='rgba(255,240,160,.35)';ctx.textAlign='center';
      ctx.fillText('★ TRIPLO ★',sx,sy+this.sep*z+r*z+14);
      ctx.textAlign='left';
    }
  }
}

function spawnTripleStar(wx,wy){
  const ts=new TripleStar(wx,wy);
  objects.push(ts);
  showTooltip('🌠 Sistema Triplo criado!');
}

// ═══════════════════════════════════════════════════════════════════
//  BOSON STAR — estrela de bósons invisível: sem corpo físico visível.
//  Distorce e curva tudo que passa perto (visual de lente gravitacional).
//  Anéis neon opacos e brilhantes ao redor do vazio central.
//  Atrai lentamente até o centro e depois deixa o astro sair.
// ═══════════════════════════════════════════════════════════════════
class BosonStar extends CelestialObject{
  constructor(wx,wy){
    super(wx,wy,'bosonstar');
    this.radius=rand(12,18); this.mass=this.radius*8;
    this.fixed=true; this.immune=true; this.pullRange=this.radius*10;
    this._phase=rand(0,Math.PI*2);
    this._ringT=rand(0,Math.PI*2);
    this._waveTimer=0;
    this._waves=[];
    // Anéis com cores neon ligeiramente diferentes
    this._ringHues=[185,210,260,300]; // ciano, azul, roxo, magenta
  }
  draw(t){
    this._phase+=.025;
    this._ringT+=.018;
    const sx=this.sx(),sy=this.sy(),r=this.sr();
    const p=1+.12*Math.sin(this._phase*1.4);

    // ── Ondas de distorção que emanam do centro ──
    this._waveTimer+=.04;
    if(this._waveTimer>1.6){this._waveTimer=0;this._waves.push({r:r*0.4,alpha:.38});}
    this._waves=this._waves.filter(w=>w.alpha>.005);
    this._waves.forEach(w=>{
      ctx.beginPath();ctx.arc(sx,sy,w.r*cam.zoom,0,Math.PI*2);
      ctx.strokeStyle=`rgba(140,200,255,${w.alpha})`;ctx.lineWidth=1.2;ctx.stroke();
      w.r+=2.8;w.alpha*=.91;
    });

    // ── Efeito de lente gravitacional: arcos curvos ao redor do centro ──
    // Simulamos distorção com arcos concêntricos levemente elípticos e deformados
    for(let arc=0;arc<6;arc++){
      const arcR=r*(0.55+arc*0.38)*p*cam.zoom;
      const tilt=.12+arc*.05;
      const deform=.06*Math.sin(this._ringT*2.3+arc*1.1);
      ctx.save();ctx.translate(sx,sy);
      ctx.rotate(this._ringT*(.3+arc*.07));
      ctx.scale(1+deform, tilt+deform*.5);
      ctx.beginPath();ctx.arc(0,0,arcR,0,Math.PI*2);
      const arcAlpha=(.09-.012*arc)*(.7+.3*Math.sin(this._phase+arc));
      ctx.strokeStyle=`rgba(100,200,255,${arcAlpha})`;
      ctx.lineWidth=(.9+arc*.15)*cam.zoom;ctx.stroke();
      ctx.restore();
    }

    // ── Anéis neon opacos e brilhantes (mas com opacidade moderada) ──
    const ringRadii=[1.0, 1.55, 2.1, 2.75];
    ringRadii.forEach((rm,i)=>{
      const hue=this._ringHues[i];
      const ringR=r*rm*p*cam.zoom;
      const brightness=.55+.18*Math.sin(this._ringT*2.1+i*.9);
      const width=(2.8-i*.4)*cam.zoom;

      // Brilho externo do anel (glow)
      ctx.save();ctx.translate(sx,sy);
      ctx.rotate(this._ringT*(i%2===0?.12:-.09)+i*.4);
      ctx.scale(1,.22+i*.06);
      ctx.beginPath();ctx.arc(0,0,ringR,0,Math.PI*2);
      ctx.strokeStyle=`hsla(${hue},100%,70%,${brightness*.28})`;
      ctx.lineWidth=width*3;ctx.stroke();
      // Núcleo neon do anel
      ctx.beginPath();ctx.arc(0,0,ringR,0,Math.PI*2);
      ctx.strokeStyle=`hsla(${hue},100%,88%,${brightness*.55})`;
      ctx.lineWidth=width;ctx.stroke();
      ctx.restore();
    });

    // ── Buraco central: ausência absoluta de luz (invisível = escuro se hover algo) ──
    // Apenas uma leve sombra indica que "algo" existe ali
    const voidG=ctx.createRadialGradient(sx,sy,0,sx,sy,r*.45*cam.zoom);
    voidG.addColorStop(0,'rgba(0,0,0,0.22)');
    voidG.addColorStop(1,'transparent');
    ctx.beginPath();ctx.arc(sx,sy,r*.45*cam.zoom,0,Math.PI*2);
    ctx.fillStyle=voidG;ctx.fill();

    // Label apenas em sandbox
    if(sandboxMode){
      ctx.font=`${Math.max(6,r*.38)}px 'Courier New'`;
      ctx.fillStyle='rgba(140,200,255,.22)';ctx.textAlign='center';
      ctx.fillText('BÓSON',sx,sy+r*2.9*cam.zoom+10);ctx.textAlign='left';
    }
    // ── Revelação pela Cefeida ─────────────────────────────────────
    const _bsRev=(this._revealTimer||0)>0;
    if(_bsRev){
      const _bsA=Math.min(1,this._revealTimer/0.6);
      // Halo quente dourado-ciano que "materializa" a estrela de bósons
      const _bsG=ctx.createRadialGradient(sx,sy,r*.3,sx,sy,r*4.5*p);
      _bsG.addColorStop(0,`rgba(255,230,100,${_bsA*.6})`);
      _bsG.addColorStop(.4,`rgba(100,255,220,${_bsA*.28})`);
      _bsG.addColorStop(1,'transparent');
      ctx.beginPath();ctx.arc(sx,sy,r*4.5*p,0,Math.PI*2);ctx.fillStyle=_bsG;ctx.fill();
      // Núcleo visível temporariamente
      const _bsC=ctx.createRadialGradient(sx,sy,0,sx,sy,r*.55);
      _bsC.addColorStop(0,`rgba(255,255,200,${_bsA*.8})`);
      _bsC.addColorStop(1,`rgba(100,220,255,${_bsA*.45})`);
      ctx.beginPath();ctx.arc(sx,sy,r*.55,0,Math.PI*2);ctx.fillStyle=_bsC;ctx.fill();
      ctx.font=`${Math.max(6,r*.38)}px 'Courier New'`;
      ctx.fillStyle=`rgba(255,230,100,${_bsA*.7})`;ctx.textAlign='center';
      ctx.fillText('BÓSON',sx,sy+r*2.9*cam.zoom+10);ctx.textAlign='left';
    }
  }
}

// ═══════════════════════════════════════════════════════════════════
//  GREAT ATTRACTOR — colossal, amarelo e preto borrado.
//  Atrai de distâncias extremas. Opaca e borra o fundo ao redor.
//  NUNCA gerado automaticamente por galáxias.
// ═══════════════════════════════════════════════════════════════════
class GreatAttractor extends CelestialObject{
  constructor(wx,wy){
    super(wx,wy,'greatattractor');
    this.radius=rand(70,100);      // colossal — maior que tudo
    this.mass=this.radius*300;
    this.fixed=true; this.immune=true;
    this.pullRange=this.radius*60; // atrai de distâncias imensas
    this._phase=rand(0,Math.PI*2);
    this._rotA=rand(0,Math.PI*2);
    this._blurR=this.radius*9;    // raio de distorção/opacificação do fundo
  }
  draw(t){
    this._phase+=.004;
    this._rotA+=.0018;
    const sx=this.sx(),sy=this.sy(),r=this.sr();
    const p=1+.018*Math.sin(this._phase*1.3);
    const T=this._phase; // tempo acumulado

    // ══════════════════════════════════════════════════
    //  CAMADA 0 — Escurecimento do espaço ao redor
    //  O espaço parece "sugar" a luz: fundo fica opaco
    // ══════════════════════════════════════════════════
    const darkR=this._blurR*cam.zoom;
    const darkG=ctx.createRadialGradient(sx,sy,r*.6*cam.zoom,sx,sy,darkR*1.1);
    darkG.addColorStop(0,'rgba(0,0,0,0.96)');
    darkG.addColorStop(.12,'rgba(0,0,0,0.88)');
    darkG.addColorStop(.28,'rgba(2,1,0,0.72)');
    darkG.addColorStop(.50,'rgba(4,3,0,0.48)');
    darkG.addColorStop(.72,'rgba(6,4,0,0.22)');
    darkG.addColorStop(.90,'rgba(8,5,0,0.08)');
    darkG.addColorStop(1,'transparent');
    ctx.beginPath();ctx.arc(sx,sy,darkR*1.1,0,Math.PI*2);
    ctx.fillStyle=darkG;ctx.fill();

    // ══════════════════════════════════════════════════
    //  CAMADA 1 — Fibras de espaço-tempo distorcidas
    //  Linhas curvas amarelo-ouro convergindo ao centro,
    //  com partes que somem (invisíveis) e reaparecem.
    // ══════════════════════════════════════════════════
    const nFibers=24;
    for(let i=0;i<nFibers;i++){
      const baseAng=(i/nFibers)*Math.PI*2+this._rotA*.4;
      const fiberLen=r*(3.5+1.5*Math.sin(T*0.8+i*.6))*cam.zoom;
      // Fibras pulsam em opacidade — algumas ficam invisíveis
      const visibility=Math.sin(T*1.2+i*0.9+Math.sin(T*.3+i*.4)*1.5);
      if(visibility<-0.3)continue; // fibra invisível neste momento
      const alpha=Math.max(0,(visibility+0.3)/1.3)*(.35+.15*Math.sin(T*2+i));

      // Cada fibra é uma curva cúbica convergindo ao centro
      const startX=sx+Math.cos(baseAng)*fiberLen;
      const startY=sy+Math.sin(baseAng)*fiberLen;
      // Ponto de controle: desviado lateralmente para curvar
      const cpDist=fiberLen*.55;
      const cpAng=baseAng+Math.PI*.28*Math.sin(T*.5+i*.7);
      const cp1x=sx+Math.cos(cpAng)*cpDist;
      const cp1y=sy+Math.sin(cpAng)*cpDist;
      const cp2x=sx+Math.cos(baseAng+.12)*r*.8*cam.zoom;
      const cp2y=sy+Math.sin(baseAng+.12)*r*.8*cam.zoom;

      // Cor: amarelo ouro nas bordas, branco no centro
      const fg=ctx.createLinearGradient(startX,startY,sx,sy);
      fg.addColorStop(0,`rgba(180,110,0,${alpha*.5})`);
      fg.addColorStop(.3,`rgba(220,160,0,${alpha*.75})`);
      fg.addColorStop(.65,`rgba(255,210,40,${alpha})`);
      fg.addColorStop(.85,`rgba(255,240,180,${alpha*1.2})`);
      fg.addColorStop(1,'rgba(255,255,255,0)');

      ctx.save();ctx.beginPath();ctx.moveTo(startX,startY);
      ctx.bezierCurveTo(cp1x,cp1y,cp2x,cp2y,sx,sy);
      ctx.strokeStyle=fg;
      ctx.lineWidth=(1.2+.8*(1-i/nFibers))*cam.zoom;ctx.stroke();
      ctx.restore();
    }

    // ══════════════════════════════════════════════════
    //  CAMADA 2 — Anéis de Einstein: elipses inclinadas
    //  distorcendo a luz ao redor do rasgo central.
    //  Algumas são invisíveis (alpha=0) por design.
    // ══════════════════════════════════════════════════
    const einsteinRings=[
      {rx:1.25,ry:.08, rot:0,      vis:true,  col:[255,200,20],  aw:.9},
      {rx:1.65,ry:.06, rot:.52,    vis:true,  col:[200,130,0],   aw:.65},
      {rx:2.1, ry:.045,rot:1.05,   vis:true,  col:[255,220,60],  aw:.45},
      {rx:2.6, ry:.035,rot:1.65,   vis:false, col:[255,200,0],   aw:.3},  // invisível
      {rx:0.9, ry:.13, rot:-.7,    vis:true,  col:[255,240,100], aw:.7},
      {rx:3.2, ry:.028,rot:2.2,    vis:false, col:[180,100,0],   aw:.2},  // invisível
    ];
    einsteinRings.forEach((er,i)=>{
      if(!er.vis)return; // completamente invisível
      const pulse=.7+.3*Math.sin(T*1.8+i*.9);
      const gA=er.aw*pulse;
      if(gA<.04)return;
      ctx.save();ctx.translate(sx,sy);
      ctx.rotate(er.rot+this._rotA*(i%2===0?.5:-.35));
      ctx.scale(1,er.ry*(1+.2*Math.sin(T*2.2+i)));
      const rR=er.rx*r*p*cam.zoom;
      // Glow externo
      ctx.beginPath();ctx.arc(0,0,rR,0,Math.PI*2);
      ctx.strokeStyle=`rgba(${er.col[0]},${er.col[1]},${er.col[2]},${gA*.3})`;
      ctx.lineWidth=8*cam.zoom;ctx.stroke();
      // Anel nítido
      ctx.beginPath();ctx.arc(0,0,rR,0,Math.PI*2);
      ctx.strokeStyle=`rgba(${er.col[0]},${er.col[1]},${er.col[2]},${gA})`;
      ctx.lineWidth=1.8*cam.zoom;ctx.stroke();
      ctx.restore();
    });

    // ══════════════════════════════════════════════════
    //  CAMADA 3 — Rasgo central: fenda irregular preta
    //  com bordas amarelas brilhantes e partes que
    //  desaparecem (buracos dentro do buraco).
    // ══════════════════════════════════════════════════
    // Forma do rasgo: polígono irregular giratório
    const nRift=18;
    ctx.save();ctx.translate(sx,sy);ctx.rotate(this._rotA*1.2);
    ctx.beginPath();
    for(let i=0;i<nRift;i++){
      const a=(i/nRift)*Math.PI*2;
      // Raio oscila irregularmente — cria forma de rasgo e não de círculo
      const rMod=r*cam.zoom*(
        0.62
        +0.22*Math.sin(a*3+T*0.6)
        +0.14*Math.sin(a*5.3+T*1.1)
        +0.08*Math.sin(a*7.7+T*0.4)
      );
      i===0?ctx.moveTo(Math.cos(a)*rMod,Math.sin(a)*rMod)
           :ctx.lineTo(Math.cos(a)*rMod,Math.sin(a)*rMod);
    }
    ctx.closePath();
    // Interior: preto absoluto (buraco no espaço-tempo)
    ctx.fillStyle='rgba(0,0,0,0.98)';ctx.fill();
    // Borda interna: amarelo dourado brilhante (horizonte de eventos)
    const edgeG=ctx.createLinearGradient(-r*cam.zoom,-r*cam.zoom,r*cam.zoom,r*cam.zoom);
    edgeG.addColorStop(0,`rgba(255,230,0,${.7+.2*Math.sin(T*3)})`);
    edgeG.addColorStop(.3,`rgba(255,160,0,${.5+.15*Math.sin(T*2.5+1)})`);
    edgeG.addColorStop(.6,`rgba(255,200,20,${.6+.18*Math.sin(T*3.2+2)})`);
    edgeG.addColorStop(1,`rgba(200,120,0,${.45+.12*Math.sin(T*2.8+3)})`);
    ctx.strokeStyle=edgeG;ctx.lineWidth=3.5*cam.zoom;ctx.stroke();
    ctx.restore();

    // ══════════════════════════════════════════════════
    //  CAMADA 4 — "Fantasmas" de luz: fragmentos do
    //  espaço que foram dobrados e reaparecem como
    //  arcos semi-transparentes em posições aleatórias
    // ══════════════════════════════════════════════════
    const ghostArcs=[
      {ang:.3,  r:1.9, sweep:.8, rot:T*.18,  alpha:.18},
      {ang:2.1, r:2.4, sweep:.55,rot:-T*.12, alpha:.12},
      {ang:4.5, r:1.6, sweep:1.1,rot:T*.22,  alpha:.22},
      {ang:1.0, r:3.1, sweep:.4, rot:-T*.08, alpha:.08},
      {ang:3.4, r:2.7, sweep:.7, rot:T*.15,  alpha:.14},
    ];
    ghostArcs.forEach(ga=>{
      // Pisca lentamente
      const blink=.5+.5*Math.sin(T*0.9+ga.ang*2.3);
      const a=ga.alpha*blink;
      if(a<.02)return;
      ctx.save();ctx.translate(sx,sy);ctx.rotate(ga.rot+ga.ang);
      ctx.scale(1,.15+.05*Math.sin(T+ga.ang));
      const aR=ga.r*r*cam.zoom;
      const ghostG=ctx.createLinearGradient(-aR,0,aR,0);
      ghostG.addColorStop(0,'transparent');
      ghostG.addColorStop(.3,`rgba(255,200,0,${a})`);
      ghostG.addColorStop(.7,`rgba(255,230,80,${a*1.3})`);
      ghostG.addColorStop(1,'transparent');
      ctx.beginPath();ctx.arc(0,0,aR,ga.rot,ga.rot+ga.sweep);
      ctx.strokeStyle=ghostG;ctx.lineWidth=4*cam.zoom;ctx.stroke();
      ctx.restore();
    });

    // ══════════════════════════════════════════════════
    //  CAMADA 5 — Partículas de Hawking:
    //  pontos dourados minúsculos emanando do rasgo
    // ══════════════════════════════════════════════════
    if(!this._hawkingPts){this._hawkingPts=[];}
    if(Math.random()<.18){
      const ha=rand(0,Math.PI*2);
      const hr=r*(.65+rand(0,.35));
      this._hawkingPts.push({
        x:Math.cos(ha)*hr,y:Math.sin(ha)*hr,
        vx:Math.cos(ha)*rand(.4,1.2),vy:Math.sin(ha)*rand(.4,1.2),
        life:1,r:rand(.8,2.2)
      });
    }
    this._hawkingPts=this._hawkingPts.filter(hp=>hp.life>0.01);
    this._hawkingPts.forEach(hp=>{
      hp.x+=hp.vx;hp.y+=hp.vy;hp.life*=.96;
      const hue=40+rand(-10,10);
      ctx.beginPath();
      ctx.arc(sx+hp.x*cam.zoom,sy+hp.y*cam.zoom,hp.r*cam.zoom,0,Math.PI*2);
      ctx.fillStyle=`hsla(${hue},100%,75%,${hp.life*.7})`;ctx.fill();
    });

    // ── Pull range ring (muito tênue) ──
    ctx.beginPath();ctx.arc(sx,sy,this.pullRange*cam.zoom,0,Math.PI*2);
    ctx.strokeStyle='rgba(180,110,0,0.018)';ctx.lineWidth=1;ctx.stroke();

    if(sandboxMode){
      ctx.font=`bold ${Math.max(9,r*.14)}px 'Courier New'`;
      ctx.fillStyle='rgba(220,160,0,0.40)';ctx.textAlign='center';
      ctx.fillText('▲ GRANDE ATRATOR ▲',sx,sy+r*p*cam.zoom+28);ctx.textAlign='left';
    }
  }
}

// ═══════════════════════════════════════════════════════════════════
//  GIGANTE AZUL COLOSSAL — feature especial, spawnada em um ponto
//  distante do mapa. Visual: bola de luz simples e otimizada (poucos
//  gradientes, sem partículas/camadas complexas), cor ciano/branco.
//  Mais de 800x o raio de uma estrela comum. Tudo que estiver perto
//  orbita ao redor dela; quanto mais perto, mais quente (mais branco);
//  quanto mais longe, mais frio (mais ciano/azul escuro) — por enquanto
//  isso é só um efeito visual de cor, sem lógica de jogo (gravidade,
//  dano, temperatura real etc.) ainda; isso vem depois.
// ═══════════════════════════════════════════════════════════════════
class ColossalBlueGiant extends CelestialObject{
  constructor(wx,wy){
    super(wx,wy,'colossalBlueGiant');
    this.radius=rand(15000,18000); // >800x uma Star comum (raio ~14-22)
    this.mass=this.radius*40;
    this.fixed=true; // colossal demais para se mover
    this.color='#8fe8ff';
    this._t=rand(0,Math.PI*2);
    // órbita de referência: qualquer objeto dentro desse raio é
    // considerado "no sistema" da Gigante Azul (uso futuro, guardado
    // aqui desde já para a lógica que vem depois).
    this.orbitSystemRange=this.radius*22;
  }
  update(dt){
    this._t+=dt; // só anima o pulso de luz, sem física ainda
  }
  draw(){
    const sx=this.sx(),sy=this.sy();
    const r=this.sr();
    // Culling: se a estrela nem aparece na tela (nem parcialmente),
    // não desenha nada — essencial para um raio desse tamanho.
    if(sx+r<-50||sx-r>canvas.width+50||sy+r<-50||sy-r>canvas.height+50)return;

    const pulse=1+0.015*Math.sin(this._t*0.6); // pulso bem sutil, é colossal

    // Halo externo — um único gradiente radial grande, barato de desenhar
    const haloR=r*1.35*pulse;
    const halo=ctx.createRadialGradient(sx,sy,r*0.85,sx,sy,haloR);
    halo.addColorStop(0,'rgba(160,240,255,.55)');
    halo.addColorStop(0.6,'rgba(90,200,255,.18)');
    halo.addColorStop(1,'rgba(90,200,255,0)');
    ctx.beginPath();ctx.arc(sx,sy,haloR,0,Math.PI*2);ctx.fillStyle=halo;ctx.fill();

    // Corpo da estrela — gradiente único ciano→branco no centro
    const body=ctx.createRadialGradient(sx-r*.15,sy-r*.15,r*.05,sx,sy,r*pulse);
    body.addColorStop(0,'#ffffff');
    body.addColorStop(0.35,'#eafcff');
    body.addColorStop(0.65,'#8fe8ff');
    body.addColorStop(1,'#2a9fc4');
    ctx.beginPath();ctx.arc(sx,sy,r*pulse,0,Math.PI*2);ctx.fillStyle=body;ctx.fill();

    if(sandboxMode){
      ctx.font=`${Math.max(10,r*.02*cam.zoom)}px 'Courier New'`;
      ctx.fillStyle='rgba(200,245,255,.5)';ctx.textAlign='center';
      ctx.fillText(this.name||'GIGANTE AZUL',sx,sy+r*pulse+22);ctx.textAlign='left';
    }
  }
}

// ═══════════════════════════════════════════════════════════════════
//  ZONA DE INSTABILIDADE DO NÚCLEO DIMENSIONAL — quando a câmera
//  (posição do jogador) se aproxima demais do centro do Núcleo, a tela
//  passa a exibir erros/glitches visuais e a câmera é impedida de
//  avançar além de um raio mínimo de segurança. Apenas limita a
//  POSIÇÃO da câmera — nunca mexe no desenho do Núcleo em si, então
//  ele nunca desaparece por causa disso.
// ═══════════════════════════════════════════════════════════════════
let _coreGlitchLevel=0; // 0..1, usado por draw() para intensidade do glitch
function _coreProximityUpdate(){
  const core=objects.find(o=>o.type==='colossalBlueGiant'&&!o.dead);
  if(!core){ _coreGlitchLevel=0; return; }
  // Raio de bloqueio: um pouco ACIMA da superfície visual (radius*1.0)
  // para o jogador conseguir ver a borda real do Núcleo, mas sem deixar
  // a câmera passar por cima/dentro dela. Ainda bem abaixo do raio de
  // culling do desenho da estrela, então ela nunca some da tela.
  const blockRadius=core.radius*1.05;
  // Raio onde o glitch começa a aparecer (um pouco mais externo).
  const warnRadius=core.radius*1.6;
  const dx=cam.x-core.x, dy=cam.y-core.y;
  const dist=Math.hypot(dx,dy);
  if(dist<blockRadius){
    // Empurra a câmera de volta para a borda exata da zona bloqueada.
    if(dist<0.0001){
      cam.x=core.x+blockRadius;cam.y=core.y;
    } else {
      const k=blockRadius/dist;
      cam.x=core.x+dx*k;
      cam.y=core.y+dy*k;
    }
  }
  // Intensidade do glitch: 0 fora do warnRadius, 1 na borda do bloqueio.
  const clampedDist=Math.max(dist,blockRadius);
  if(clampedDist>=warnRadius){ _coreGlitchLevel=0; }
  else{
    _coreGlitchLevel=1-((clampedDist-blockRadius)/(warnRadius-blockRadius));
    _coreGlitchLevel=Math.max(0,Math.min(1,_coreGlitchLevel));
  }
}

// ═══════════════════════════════════════════════════════════════════
//  PLANETA GIGANTE — orbita a Gigante Azul Colossal. Representado
//  como um círculo do tamanho da própria estrela (gigante mesmo).
//  Visual simples/otimizado, cor muda pela distância orbital: mais
//  perto do centro = mais quente (tons alaranjados/brancos), mais
//  longe = mais frio (tons azulados/acinzentados). Efeito só visual
//  por enquanto — sem lógica de jogo.
// ═══════════════════════════════════════════════════════════════════
class ColossalGiantPlanet extends CelestialObject{
  constructor(wx,wy,parentStar){
    super(wx,wy,'colossalGiantPlanet');
    this.parentStar=parentStar||null;
    this.radius=parentStar?parentStar.radius*0.9:rand(12000,16000);
    this.mass=this.radius*8;
    this.fixed=false;
    this.orbitAngle=rand(0,Math.PI*2);
    this.orbitDist=parentStar?parentStar.radius*rand(3.2,7):rand(40000,90000);
    // Posição inicial já na órbita real — sem isso o planeta nascia
    // sobreposto ao centro do núcleo até o primeiro update().
    if(parentStar){
      this.x=parentStar.x+Math.cos(this.orbitAngle)*this.orbitDist;
      this.y=parentStar.y+Math.sin(this.orbitAngle)*this.orbitDist;
    }
    this.orbitSpeed=rand(0.002,0.006); // órbita bem lenta, é colossal
    this._t=rand(0,Math.PI*2);
  }
  update(dt){
    this._t+=dt;
    if(this.parentStar&&!this.parentStar.dead){
      this.orbitAngle+=this.orbitSpeed*dt;
      this.x=this.parentStar.x+Math.cos(this.orbitAngle)*this.orbitDist;
      this.y=this.parentStar.y+Math.sin(this.orbitAngle)*this.orbitDist;
    }
  }
  draw(){
    const sx=this.sx(),sy=this.sy();
    const r=this.sr();
    if(sx+r<-50||sx-r>canvas.width+50||sy+r<-50||sy-r>canvas.height+50)return;

    // Cor fixa: marrom escuro quase preto, conforme referência visual do
    // Núcleo Dimensional (azul ciano) + seu planeta (marrom quase preto).
    const dark=[26,17,12];
    const baseColor=`rgb(${dark[0]},${dark[1]},${dark[2]})`;

    const body=ctx.createRadialGradient(sx-r*.25,sy-r*.25,r*.08,sx,sy,r);
    body.addColorStop(0,`rgba(${Math.min(255,dark[0]+22)},${Math.min(255,dark[1]+15)},${Math.min(255,dark[2]+10)},1)`);
    body.addColorStop(0.6,baseColor);
    body.addColorStop(1,`rgba(${Math.round(dark[0]*.4)},${Math.round(dark[1]*.4)},${Math.round(dark[2]*.4)},1)`);
    ctx.beginPath();ctx.arc(sx,sy,r,0,Math.PI*2);ctx.fillStyle=body;ctx.fill();

    if(sandboxMode){
      ctx.font=`${Math.max(10,r*.02*cam.zoom)}px 'Courier New'`;
      ctx.fillStyle='rgba(255,255,255,.4)';ctx.textAlign='center';
      ctx.fillText(this.name||'Planeta Gigante',sx,sy+r+22);ctx.textAlign='left';
    }
  }
}

// ═══════════════════════════════════════════════════════════════════
//  AUTO-GENERATE GALAXY WITH FULL SOLAR SYSTEM (sandbox)
// ═══════════════════════════════════════════════════════════════════
function spawnSandboxGalaxy(){
  const angle=rand(0,Math.PI*2);
  const d=rand(800,2200);
  const wx=cam.x+Math.cos(angle)*d;
  const wy=cam.y+Math.sin(angle)*d;
  const g=new Galaxy(wx,wy);
  g._autoSpawn=true; // não conta para missão
  pendingObjects.push(g);

  // ── MANDATORY: one star with planets+moons ──
  const sa=rand(0,Math.PI*2),sd=rand(20,g.radius*.25);
  const stx=wx+Math.cos(sa)*sd,sty=wy+Math.sin(sa)*sd;
  const star=new Star(stx,sty);star.radius=rand(10,18);star.mass=star.radius*12;
  star._autoSpawn=true;
  pendingObjects.push(star);

  const numPl=randInt(2,4);
  for(let j=0;j<numPl;j++){
    const pd=rand(45,130),pa=rand(0,Math.PI*2);
    const pl=new Planet(stx+Math.cos(pa)*pd,sty+Math.sin(pa)*pd,star);
    pl.orbitDist=pd;pl.orbitAngle=pa;pl.orbitSpeed=(0.38+rand(0,.28))/Math.sqrt(pd/50);
    pl._autoSpawn=true;
    pendingObjects.push(pl);
    // Moons around each planet
    const numM=randInt(0,2);
    for(let m=0;m<numM;m++){
      const md=rand(18,32),ma=rand(0,Math.PI*2);
      const mn=new Moon(pl.x+Math.cos(ma)*md,pl.y+Math.sin(ma)*md,pl);
      mn.orbitDist=md;mn.orbitAngle=ma;mn.orbitSpeed=rand(1.4,2.6);
      mn._autoSpawn=true;
      pendingObjects.push(mn);
    }
  }

  // ── MANDATORY: one distant black hole (far from star so it can't suck planets) ──
  const bhAngle=rand(0,Math.PI*2);
  const bhDist=rand(g.radius*.8,g.radius*1.2);
  const bh=new BlackHole(wx+Math.cos(bhAngle)*bhDist,wy+Math.sin(bhAngle)*bhDist);
  bh.radius=rand(14,20);bh.mass=bh.radius*60;bh.pullRange=bh.radius*7; // smaller pull range
  bh._autoSpawn=true;
  pendingObjects.push(bh);

  // ── OPTIONAL: spawn an unlocked special astro occasionally ──
  // NOTA: vetocrinazar e greatattractor são exclusivos do jogador — nunca auto-gerados
  if(sandboxMode){
    const unlockableTypes=['polarstar','riftfissure'];
    const eligible=unlockableTypes.filter(t=>unlockedTypes.has(t));
    if(eligible.length>0&&Math.random()<0.45){
      const pick=eligible[Math.floor(Math.random()*eligible.length)];
      const oa=rand(0,Math.PI*2),od=rand(g.radius*.5,g.radius*.9);
      const ox=wx+Math.cos(oa)*od,oy=wy+Math.sin(oa)*od;
      let ao;
      if(pick==='polarstar') ao=new PolarStar(ox,oy);
      else if(pick==='riftfissure') ao=new RiftFissure(ox,oy);
      if(ao){ao._autoSpawn=true;pendingObjects.push(ao);}
    }
  }

  showTooltip('🌌 Nova galáxia com sistema solar surgiu!');
}

// ═══════════════════════════════════════════════════════════════════
//  AUTO-GENERATE GALÁXIA DA FASE CÓSMICA (pós-derrota do Quasord)
//  Escala ~5x maior que a galáxia comum do Sandbox, mais próxima de uma
//  escala real. Obrigatório: 1 Buraco Negro central + vários sistemas
//  estelares (estrela+planetas+luas). Magnetar é raro. Pulsar, quando
//  aparece, fica sempre isolado bem longe do resto (não interfere).
//  Astros perigosos/massivos do Início do Universo (Quase-Estrela) têm
//  chance de aparecer, reaproveitando a classe QuasiStar já existente.
// ═══════════════════════════════════════════════════════════════════
function spawnCosmicPhaseGalaxy(){
  const angle=rand(0,Math.PI*2);
  const d=rand(1200,2800); // aparece um pouco mais longe, já que é bem maior
  const wx=cam.x+Math.cos(angle)*d;
  const wy=cam.y+Math.sin(angle)*d;

  // Galáxia ~5x maior que a comum (rand(200,360) → rand(1000,1800))
  const g=new Galaxy(wx,wy);
  g.radius=rand(1000,1800);
  g._autoSpawn=true;
  pendingObjects.push(g);

  // ── OBRIGATÓRIO: Buraco Negro central (verdadeiro centro galáctico) ──
  const bh=new BlackHole(wx,wy);
  bh.radius=rand(30,46); // maior que o BH comum de sandbox, condizente com o centro de uma galáxia
  bh.mass=bh.radius*60;
  bh.pullRange=bh.radius*7; // contido, para não sugar sistemas ao redor
  bh._autoSpawn=true;
  pendingObjects.push(bh);

  // ── VÁRIOS SISTEMAS ESTELARES espalhados pela galáxia (não colados no BH) ──
  const numSystems=randInt(4,7);
  for(let s=0;s<numSystems;s++){
    const sysAngle=rand(0,Math.PI*2);
    const sysDist=rand(g.radius*.18,g.radius*.85); // longe o bastante do centro
    const stx=wx+Math.cos(sysAngle)*sysDist;
    const sty=wy+Math.sin(sysAngle)*sysDist;

    const star=new Star(stx,sty);
    star.radius=rand(10,20);
    star.mass=star.radius*12;
    star._autoSpawn=true;
    pendingObjects.push(star);

    const numPl=randInt(2,5);
    for(let j=0;j<numPl;j++){
      const pd=rand(45,150),pa=rand(0,Math.PI*2);
      const pl=new Planet(stx+Math.cos(pa)*pd,sty+Math.sin(pa)*pd,star);
      pl.orbitDist=pd;pl.orbitAngle=pa;pl.orbitSpeed=(0.38+rand(0,.28))/Math.sqrt(pd/50);
      pl._autoSpawn=true;
      pendingObjects.push(pl);
      const numM=randInt(0,2);
      for(let m=0;m<numM;m++){
        const md=rand(18,32),ma=rand(0,Math.PI*2);
        const mn=new Moon(pl.x+Math.cos(ma)*md,pl.y+Math.sin(ma)*md,pl);
        mn.orbitDist=md;mn.orbitAngle=ma;mn.orbitSpeed=rand(1.4,2.6);
        mn._autoSpawn=true;
        pendingObjects.push(mn);
      }
    }
  }

  // ── RARO: Magnetar (perigoso, mas mantido perto dos sistemas — campo contido) ──
  if(Math.random()<0.22){
    const maAngle=rand(0,Math.PI*2);
    const maDist=rand(g.radius*.25,g.radius*.7);
    const mag=new Magnetar(wx+Math.cos(maAngle)*maDist,wy+Math.sin(maAngle)*maDist);
    mag._autoSpawn=true;
    pendingObjects.push(mag);
  }

  // ── Pulsar: quando aparece, fica bem afastado do resto da galáxia,
  // sozinho, para não interferir nos sistemas nem no Buraco Negro. ──
  if(Math.random()<0.35){
    const puAngle=rand(0,Math.PI*2);
    const puDist=rand(g.radius*1.15,g.radius*1.45); // fora do "miolo" da galáxia
    const pulsar=new Pulsar(wx+Math.cos(puAngle)*puDist,wy+Math.sin(puAngle)*puDist);
    pulsar._autoSpawn=true;
    pendingObjects.push(pulsar);
  }

  // ── Astros perigosos/massivos do Início do Universo: Quase-Estrela ──
  // Rara, colocada afastada do miolo de sistemas, como um remanescente antigo.
  if(Math.random()<0.16){
    const qsAngle=rand(0,Math.PI*2);
    const qsDist=rand(g.radius*.5,g.radius*.95);
    const qs=new QuasiStar(wx+Math.cos(qsAngle)*qsDist,wy+Math.sin(qsAngle)*qsDist);
    qs._autoSpawn=true;
    pendingObjects.push(qs);
  }

  showTooltip('🌌 Uma galáxia colossal surgiu na Fase Cósmica!');
}

// ═══════════════════════════════════════════════════════════════════
//  AUTO-GENERATE DARK GALAXY (sandbox, Pacote Exótico, muito rara)
//  Spawn: ~7.5% de chance cada vez que uma galáxia normal surgiria,
//  se o Pacote Exótico estiver ativo. Contém pouquíssimos astros.
// ═══════════════════════════════════════════════════════════════════
function spawnDarkGalaxy(){
  const angle=rand(0,Math.PI*2);
  const d=rand(1400,3400); // aparece mais longe que as galáxias normais
  const wx=cam.x+Math.cos(angle)*d;
  const wy=cam.y+Math.sin(angle)*d;
  const g=new DarkGalaxy(wx,wy);
  g._autoSpawn=true;
  pendingObjects.push(g);

  // Pouquíssimos astros: apenas 1 estrela + 0–1 planetas + 1 buraco negro distante
  const sa=rand(0,Math.PI*2),sd=rand(30,g.radius*.15);
  const stx=wx+Math.cos(sa)*sd,sty=wy+Math.sin(sa)*sd;
  const star=new Star(stx,sty);
  star.radius=rand(8,14);star.mass=star.radius*10;
  star._autoSpawn=true;
  pendingObjects.push(star);

  // 0–1 planetas (50% de chance)
  if(Math.random()<.5){
    const pd=rand(40,100),pa=rand(0,Math.PI*2);
    const pl=new Planet(stx+Math.cos(pa)*pd,sty+Math.sin(pa)*pd,star);
    pl.orbitDist=pd;pl.orbitAngle=pa;pl.orbitSpeed=(0.3+rand(0,.2))/Math.sqrt(pd/50);
    pl._autoSpawn=true;
    pendingObjects.push(pl);
  }

  // Buraco negro distante — inevitável numa galáxia escura
  const bhAngle=rand(0,Math.PI*2);
  const bhDist=rand(g.radius*.7,g.radius*1.1);
  const bh=new BlackHole(wx+Math.cos(bhAngle)*bhDist,wy+Math.sin(bhAngle)*bhDist);
  bh.radius=rand(18,28);bh.mass=bh.radius*80;bh.pullRange=bh.radius*6;
  bh._autoSpawn=true;
  pendingObjects.push(bh);

  showTooltip('🥽 Galáxia Escura detectada nas proximidades…');
}

// ── Exploration: spawn galaxy when player pans far enough ──
let _lastExplorePt={x:0,y:0};
function checkExploreSpawn(){
  if(!sandboxMode)return;
  const dd=Math.hypot(cam.x-_lastExplorePt.x,cam.y-_lastExplorePt.y);
  if(dd>700){_lastExplorePt={x:cam.x,y:cam.y};spawnSandboxGalaxy();sbGalaxyTimer=0;}
}

// ═══════════════════════════════════════════════════════════════════
//  PHYSICS CONSTANTS
// ═══════════════════════════════════════════════════════════════════
const G_BLACK=30000,G_WHITE=24000,SOFT=55;

// ═══════════════════════════════════════════════════════════════════
//  HELPERS
// ═══════════════════════════════════════════════════════════════════
function spawnExplosion(wx,wy,scale,isMega){
  const n=isMega?200:80;
  for(let i=0;i<n;i++){const ang=rand(0,Math.PI*2),spd=rand(2,isMega?22:12)*scale;particles.push({x:wx,y:wy,vx:Math.cos(ang)*spd,vy:Math.sin(ang)*spd,r:rand(2,isMega?8:5)*scale,alpha:1,color:`hsl(${rand(isMega?0:20,isMega?60:55)},100%,${rand(60,90)}%)`});}
  for(let i=0;i<(isMega?6:3);i++)particles.push({x:wx,y:wy,vx:0,vy:0,r:(i+1)*(isMega?40:20),alpha:isMega?.9:.7,color:isMega?'rgba(255,200,80,1)':'rgba(255,150,50,1)',ring:true,grow:isMega?18:10});
  triggerFlash(isMega?.95:.5,isMega?600:300);
  showTooltip(isMega?'💥 MEGA EXPLOSÃO — Buraco Negro Supermassivo!':'💥 Fusão — Buraco Negro maior!');
}
function triggerFlash(alpha,duration){flashEl.style.transition='opacity .05s';flashEl.style.opacity=alpha;setTimeout(()=>{flashEl.style.transition=`opacity ${duration}ms`;flashEl.style.opacity=0;},60);}
function spawnAbsorbParticles(obj){for(let i=0;i<14;i++){const ang=rand(0,Math.PI*2);particles.push({x:obj.x,y:obj.y,vx:Math.cos(ang)*rand(1,6),vy:Math.sin(ang)*rand(1,6),r:rand(1,3.5),alpha:.9,color:`hsl(${rand(20,60)},100%,70%)`});}}
function spawnTeleportParticles(worm){for(let i=0;i<18;i++){const ang=rand(0,Math.PI*2);particles.push({x:worm.x,y:worm.y,vx:Math.cos(ang)*rand(2,8),vy:Math.sin(ang)*rand(2,8),r:rand(1.5,4),alpha:1,color:worm.colorSet?worm.colorSet[0]:'#a29bfe'});}}
function triggerSupernova(obj){
  if(!obj||obj.dead)return;
  obj._snAnim=true;
  const baseR=obj.radius;
  // Phase 1 — swell up (1.2s)
  const phase1=setTimeout(()=>{
    if(obj.dead)return;
    obj.radius=baseR*2.8;obj.mass=obj.radius*12;
    // emit glow particles while growing
    for(let i=0;i<30;i++){const a=rand(0,Math.PI*2);particles.push({x:obj.x,y:obj.y,vx:Math.cos(a)*rand(1,4),vy:Math.sin(a)*rand(1,4),r:rand(2,5),alpha:.8,color:`hsl(${rand(30,55)},100%,80%)`});}
  },400);
  // Phase 2 — collapse inward (0.8s after phase1)
  const phase2=setTimeout(()=>{
    if(obj.dead)return;
    obj.radius=baseR*0.4;obj.mass=obj.radius*12;
    triggerFlash(.3,200);
    for(let i=0;i<20;i++){const a=rand(0,Math.PI*2);particles.push({x:obj.x,y:obj.y,vx:Math.cos(a)*rand(.5,2),vy:Math.sin(a)*rand(.5,2),r:rand(1,3),alpha:.9,color:'#fff'});}
  },1200);
  // Phase 3 — triple size blast (0.6s after phase2)
  const phase3=setTimeout(()=>{
    if(obj.dead)return;
    obj.radius=baseR*3.2;obj.mass=obj.radius*12;
    triggerFlash(.7,300);
    for(let i=0;i<50;i++){const a=rand(0,Math.PI*2);particles.push({x:obj.x,y:obj.y,vx:Math.cos(a)*rand(2,8),vy:Math.sin(a)*rand(2,8),r:rand(2,6),alpha:1,color:`hsl(${rand(20,60)},100%,75%)`});}
  },2000);
  // Phase 4 — full explosion, destroy nearby, spawn remnant based on source type
  const phase4=setTimeout(()=>{
    if(obj.dead)return;
    const ox=obj.x,oy=obj.y,killRange=baseR*9;
    const srcType=obj.type; // capture before dead
    obj.dead=true;
    // Big explosion particles
    for(let i=0;i<160;i++){const a=rand(0,Math.PI*2),spd=rand(3,18);particles.push({x:ox,y:oy,vx:Math.cos(a)*spd,vy:Math.sin(a)*spd,r:rand(2,7),alpha:1,color:`hsl(${rand(0,55)},100%,${rand(60,92)}%)`});}
    for(let i=0;i<5;i++)particles.push({x:ox,y:oy,vx:0,vy:0,r:(i+1)*30,alpha:.9,color:'rgba(255,200,80,1)',ring:true,grow:16});
    triggerFlash(.9,500);
    // Destroy objects in kill range
    objects.forEach(o=>{
      if(o===obj||o.dead||o.immune)return;
      if(dist({x:ox,y:oy},o)<killRange){spawnAbsorbParticles(o);o.dead=true;}
    });
    // ── Remnant: chance-based by source type ──
    const roll=Math.random();
    let remnant=null,label='';
    if(srcType==='cepheid'){
      // Cepheid: Nebula 35% | Pulsar 30% | BlackHole 20% | Magnetar 15%
      if(roll<.35){remnant=new Nebula(ox,oy);label='🌌 Nebulosa formada pela Cefeida!';}
      else if(roll<.65){remnant=new Pulsar(ox,oy);remnant.radius=rand(5,9);remnant.mass=remnant.radius*20;label='💫 Pulsar remanescente da Cefeida!';}
      else if(roll<.85){remnant=new BlackHole(ox,oy);remnant.radius=rand(14,20);remnant.mass=remnant.radius*60;label='⚫ Buraco Negro — Cefeida colapsa!';}
      else{remnant=new Magnetar(ox,oy);label='🧲 Magnetar formado pela Cefeida!';}
    } else {
      // Star: Nebula 30% | WhiteDwarf(star visual small) 35% | Pulsar 25% | (rare) BlackHole 10%
      if(roll<.30){remnant=new Nebula(ox,oy);label='🌌 Nebulosa formada pela Supernova!';}
      else if(roll<.65){// white dwarf — small cool star
        remnant=new Star(ox,oy);remnant.radius=rand(4,7);remnant.mass=remnant.radius*30;
        remnant.color='#ddeeff';remnant.temp=80000;label='🤍 Anã Branca — estrela morreu!';}
      else if(roll<.90){remnant=new Pulsar(ox,oy);remnant.radius=rand(5,9);remnant.mass=remnant.radius*20;label='💫 Pulsar — remanescente estelar!';}
      else{remnant=new BlackHole(ox,oy);remnant.radius=rand(14,18);remnant.mass=remnant.radius*60;label='⚫ Buraco Negro massivo — estrela gigante!';}
    }
    if(remnant)pendingObjects.push(remnant);
    showTooltip(label);
    // Só conta missão se a estrela/cefeida foi colocada pelo jogador (não spawn de galáxia)
    if(sandboxMode&&!obj._autoSpawn) incrementStat('supernovas');
    // Remnant herda _autoSpawn da fonte — não "limpa" a origem do objeto
    if(obj._autoSpawn&&remnant) remnant._autoSpawn=true;
  },2600);
}
function findNearest(obj,type){let best=null,bestD=Infinity;objects.forEach(o=>{if(o.type!==type||o===obj||o.dead)return;const d=dist(obj,o);if(d<bestD){bestD=d;best=o;}});return best;}
function isNearBlackhole(obj){return objects.some(bh=>bh.type==='blackhole'&&!bh.dead&&dist(obj,bh)<=bh.pullRange);}

// ═══════════════════════════════════════════════════════════════════
//  NEBULA — remnant cloud left by supernova/cepheid
// ═══════════════════════════════════════════════════════════════════
class Nebula extends CelestialObject{
  constructor(wx,wy){
    super(wx,wy,'nebula');
    this.radius=rand(60,110);this.mass=0;this.fixed=true;
    this.age=0;this.cloudPts=[];
    const h1=randInt(180,300),h2=h1+randInt(30,80);
    this.c1=`hsl(${h1},70%,55%)`;this.c2=`hsl(${h2},80%,65%)`;
    for(let i=0;i<55;i++)this.cloudPts.push({a:rand(0,Math.PI*2),d:rand(.2,1),sp:rand(.0005,.002),r:rand(4,16),al:rand(.08,.28)});
  }
  draw(t){
    const sx=this.sx(),sy=this.sy(),r=this.sr();
    this.cloudPts.forEach(p=>{
      p.a+=p.sp;
      const px=sx+Math.cos(p.a)*r*p.d,py=sy+Math.sin(p.a)*r*p.d;
      const g=ctx.createRadialGradient(px,py,0,px,py,p.r*cam.zoom*2.5);
      g.addColorStop(0,this.c1.replace('hsl','hsla').replace(')',`,${p.al+.06})`));
      g.addColorStop(.5,this.c2.replace('hsl','hsla').replace(')',`,${p.al*.5})`));
      g.addColorStop(1,'transparent');
      ctx.beginPath();ctx.arc(px,py,p.r*cam.zoom*2.5,0,Math.PI*2);ctx.fillStyle=g;ctx.fill();
    });
    // Faint outer glow
    const go=ctx.createRadialGradient(sx,sy,r*.3,sx,sy,r*1.5);
    go.addColorStop(0,this.c1.replace('hsl','hsla').replace(')',',0.06)'));
    go.addColorStop(1,'transparent');
    ctx.beginPath();ctx.arc(sx,sy,r*1.5,0,Math.PI*2);ctx.fillStyle=go;ctx.fill();
  }
}

// ═══════════════════════════════════════════════════════════════════
//  FROZEN CORE — anomalia termodinâmica que congela tudo ao redor
// ═══════════════════════════════════════════════════════════════════
class FrozenCore extends CelestialObject{
  constructor(wx,wy){
    super(wx,wy,'frozencore');
    this.radius=rand(14,22);this.mass=0;this.fixed=true;this.immune=true;
    this.temp=2; // quase zero absoluto
    this.coldRange=this.radius*14; // raio de influência do frio
    this._pulseT=rand(0,Math.PI*2);
    this._crystalAngle=rand(0,Math.PI*2);
    this._snowflakes=[];
    // Partículas de neve orbitando
    for(let i=0;i<18;i++){
      this._snowflakes.push({
        a:rand(0,Math.PI*2),
        dist:rand(0.55,1.35),
        speed:rand(0.008,0.022)*(Math.random()<.5?1:-1),
        size:rand(0.8,2.2),
        al:rand(0.3,0.85),
        phase:rand(0,Math.PI*2)
      });
    }
    // Braços de cristal (6 eixos)
    this._crystals=Array.from({length:6},(_,i)=>({
      angle:i*(Math.PI/3)+rand(-0.12,0.12),
      len:rand(0.75,1.15),
      branches:randInt(2,4),
      col:`hsl(${190+randInt(0,30)},${85+randInt(0,10)}%,${72+randInt(0,18)}%)`
    }));
  }

  draw(t){
    const sx=this.sx(),sy=this.sy(),r=this.sr();
    this._pulseT+=0.022;
    this._crystalAngle+=0.0035;
    const pulse=1+0.09*Math.sin(this._pulseT);

    // ── 1. Aura de frio externa — gradiente azul-branca difusa ──────
    const aura=ctx.createRadialGradient(sx,sy,r*0.8,sx,sy,r*5.8*pulse);
    aura.addColorStop(0,'rgba(140,220,255,0.22)');
    aura.addColorStop(0.3,'rgba(100,190,255,0.10)');
    aura.addColorStop(0.65,'rgba(60,140,230,0.04)');
    aura.addColorStop(1,'transparent');
    ctx.beginPath();ctx.arc(sx,sy,r*5.8*pulse,0,Math.PI*2);ctx.fillStyle=aura;ctx.fill();

    // ── 2. Anel de gelo pulsante (3 anéis concêntricos) ─────────────
    for(let i=0;i<3;i++){
      const ringR=r*(1.9+i*0.7)*pulse;
      const alpha=(0.28-i*0.07)*(0.7+0.3*Math.sin(this._pulseT*1.4+i));
      ctx.beginPath();ctx.arc(sx,sy,ringR,0,Math.PI*2);
      ctx.strokeStyle=`rgba(180,235,255,${alpha})`;
      ctx.lineWidth=(2.2-i*0.5)*cam.zoom;ctx.stroke();
    }

    // ── 3. Braços de cristal (rotação lenta) ───────────────────────
    ctx.save();ctx.translate(sx,sy);ctx.rotate(this._crystalAngle);
    this._crystals.forEach(cr=>{
      const len=r*cr.len*1.15;
      for(let s=-1;s<=1;s+=2){
        const ax=Math.cos(cr.angle)*s,ay=Math.sin(cr.angle)*s;
        ctx.beginPath();ctx.moveTo(0,0);ctx.lineTo(ax*len,ay*len);
        ctx.strokeStyle=cr.col.replace('hsl','hsla').replace(')',',0.72)');
        ctx.lineWidth=1.6*cam.zoom;ctx.stroke();
        // sub-ramos
        for(let b=1;b<=cr.branches;b++){
          const bd=len*(0.28+b*0.18);
          const blen=len*(0.18-b*0.03);
          for(let bs=-1;bs<=1;bs+=2){
            const bAngle=cr.angle+bs*Math.PI*0.32;
            ctx.beginPath();
            ctx.moveTo(ax*bd,ay*bd);
            ctx.lineTo(ax*bd+Math.cos(bAngle*s)*blen,ay*bd+Math.sin(bAngle*s)*blen);
            ctx.strokeStyle=cr.col.replace('hsl','hsla').replace(')',',0.45)');
            ctx.lineWidth=0.9*cam.zoom;ctx.stroke();
          }
        }
      }
    });
    ctx.restore();

    // ── 4. Névoa interna de gelo (círculos sobrepostos) ─────────────
    for(let i=0;i<5;i++){
      const ang=this._crystalAngle*0.7+i*(Math.PI*2/5);
      const dx=Math.cos(ang)*r*0.38,dy=Math.sin(ang)*r*0.38;
      const g=ctx.createRadialGradient(sx+dx,sy+dy,0,sx+dx,sy+dy,r*0.72);
      g.addColorStop(0,`rgba(200,240,255,${0.18+0.07*Math.sin(this._pulseT+i)})`);
      g.addColorStop(0.5,`rgba(150,210,255,0.06)`);
      g.addColorStop(1,'transparent');
      ctx.beginPath();ctx.arc(sx+dx,sy+dy,r*0.72,0,Math.PI*2);ctx.fillStyle=g;ctx.fill();
    }

    // ── 5. Núcleo — cristal sólido hexagonal ────────────────────────
    const gc=ctx.createRadialGradient(sx-r*0.28,sy-r*0.28,r*0.05,sx,sy,r*1.0);
    gc.addColorStop(0,'#ffffff');
    gc.addColorStop(0.25,'#d8f4ff');
    gc.addColorStop(0.6,'#7eceff');
    gc.addColorStop(1,'#2a80c0');
    // Hexágono estilizado
    ctx.save();ctx.translate(sx,sy);ctx.rotate(this._crystalAngle*1.5);
    ctx.beginPath();
    for(let i=0;i<6;i++){
      const hx=Math.cos(i*Math.PI/3)*r,hy=Math.sin(i*Math.PI/3)*r;
      i===0?ctx.moveTo(hx,hy):ctx.lineTo(hx,hy);
    }
    ctx.closePath();ctx.fillStyle=gc;ctx.fill();
    ctx.strokeStyle='rgba(200,240,255,0.9)';ctx.lineWidth=1.4*cam.zoom;ctx.stroke();
    ctx.restore();

    // ── 6. Brilho central (reflexo de luz interior) ──────────────────
    const flash=ctx.createRadialGradient(sx-r*0.22,sy-r*0.22,0,sx,sy,r*0.55);
    flash.addColorStop(0,'rgba(255,255,255,0.85)');
    flash.addColorStop(0.4,'rgba(210,245,255,0.3)');
    flash.addColorStop(1,'transparent');
    ctx.beginPath();ctx.arc(sx,sy,r*0.55,0,Math.PI*2);ctx.fillStyle=flash;ctx.fill();

    // ── 7. Flocos de neve orbitando ─────────────────────────────────
    this._snowflakes.forEach(sf=>{
      sf.a+=sf.speed;
      const fx=sx+Math.cos(sf.a)*r*sf.dist*(1+0.12*Math.sin(this._pulseT+sf.phase));
      const fy=sy+Math.sin(sf.a)*r*sf.dist*(1+0.12*Math.sin(this._pulseT+sf.phase));
      ctx.beginPath();ctx.arc(fx,fy,sf.size*cam.zoom,0,Math.PI*2);
      ctx.fillStyle=`rgba(220,245,255,${sf.al*(0.7+0.3*Math.sin(this._pulseT*2+sf.phase))})`;
      ctx.fill();
    });

    // ── 8. Indicador de alcance frio (anel tênue) ───────────────────
    ctx.beginPath();ctx.arc(sx,sy,this.coldRange*cam.zoom,0,Math.PI*2);
    ctx.strokeStyle='rgba(140,210,255,0.055)';ctx.lineWidth=1;ctx.setLineDash([4,8]);ctx.stroke();ctx.setLineDash([]);

    // ── 9. Label ─────────────────────────────────────────────────────
    if(sandboxMode){
      ctx.font=`${Math.max(6,r*0.44)}px 'Courier New'`;
      ctx.fillStyle='rgba(180,240,255,0.45)';
      ctx.textAlign='center';ctx.fillText(this.name,sx,sy+r+9*cam.zoom);ctx.textAlign='left';
    }
  }
}

// ═══════════════════════════════════════════════════════════════════
//  PACOTE PLANETAS — 10 variantes planetárias desbloqueadas no Rank 7
// ═══════════════════════════════════════════════════════════════════

// Helper compartilhado: desenha planeta base com gradiente
function _drawPlanetBase(ctx,sx,sy,r,c1,c2,c3,rings,ringTilt,ringCol){
  if(rings){
    ctx.save();ctx.translate(sx,sy);ctx.scale(1,ringTilt||0.35);
    ctx.beginPath();ctx.arc(0,0,r*2.1,0,Math.PI*2);
    ctx.strokeStyle=ringCol||c2+'55';ctx.lineWidth=r*.65;ctx.stroke();ctx.restore();
  }
  const g=ctx.createRadialGradient(sx-r*.3,sy-r*.3,r*.08,sx,sy,r);
  g.addColorStop(0,c1);g.addColorStop(.5,c2);g.addColorStop(1,c3);
  ctx.beginPath();ctx.arc(sx,sy,r,0,Math.PI*2);ctx.fillStyle=g;ctx.fill();
}

// ════════════════════════════════════════════════════════════════════
//  PACOTE PLANETAS — 10 tipos, cada um com função única e visual animado
//  Todos orbitam Estrelas e Cefeidas; Luas podem orbitá-los.
// ════════════════════════════════════════════════════════════════════

// Helpers compartilhados
const PP_ORBIT_TYPES = ['gasgiant','icegiant','superearth','minineptune','dwarfplanet',
                        'lavaplt','oceanplt','desertplt','carbonplt','ironplt'];

function _ppFindHost(wx,wy){
  // Retorna a estrela ou cefeida mais próxima dentro de 300u
  const star  = findNearest({x:wx,y:wy},'star');
  const ceph  = findNearest({x:wx,y:wy},'cepheid');
  const dS    = star ? dist({x:wx,y:wy},star) : Infinity;
  const dC    = ceph ? dist({x:wx,y:wy},ceph) : Infinity;
  if(dS<300&&dS<=dC) return star;
  if(dC<300)         return ceph;
  return null;
}

function _ppAttach(obj, host){
  if(!host) return;
  obj.parent     = host;
  obj.orbitDist  = Math.max(host.radius + obj.radius + 20, dist(obj,host));
  obj.orbitAngle = Math.atan2(obj.y-host.y, obj.x-host.x);
  obj.orbitSpeed = (0.3+rand(0,.25)) / Math.sqrt(obj.orbitDist/50);
}

// Update de órbita — chamado pelo loop principal via tipo
function _ppUpdateOrbit(obj, dt){
  if(obj._noGravity){ obj.parent=null; return; }
  // Se tem pai vivo, orbita
  if(obj.parent && !obj.parent.dead){
    let spd = obj.orbitSpeed;
    if(obj.parent.type==='cepheid'){
      const raw   = Math.sin((performance.now()*.001)*obj.parent.pulseFreq + obj.parent.glowPhase);
      const pulse = (raw+1)*.5;
      spd = obj.orbitSpeed*(0.15+0.85*pulse);
    }
    obj.orbitAngle += spd*dt;
    obj.x = obj.parent.x + Math.cos(obj.orbitAngle)*obj.orbitDist;
    obj.y = obj.parent.y + Math.sin(obj.orbitAngle)*obj.orbitDist;
    return;
  }
  // Sem pai — tenta ancorar em estrela ou cefeida próxima
  const star = findNearest(obj,'star');
  const ceph = findNearest(obj,'cepheid');
  const dS   = star ? dist(obj,star) : Infinity;
  const dC   = ceph ? dist(obj,ceph) : Infinity;
  const host = (dC<dS&&dC<280)?ceph:(dS<280?star:null);
  if(host && !isNearBlackhole(obj)) _ppAttach(obj, host);
}

// ─── 1. GIGANTE GASOSO ───────────────────────────────────────────
// Função única: Tempestade Perpétua — a grande mancha gira e periodicamente
// expele uma onda de choque que empurra objetos próximos levemente para fora.
class GasGiant extends CelestialObject{
  constructor(wx,wy){
    super(wx,wy,'gasgiant');
    this.radius=rand(20,42);this.mass=this.radius*5;
    const h=randInt(20,55);
    this.color=`hsl(${h},90%,62%)`;this._bandH=h;
    this._bands=Array.from({length:6},()=>rand(0,1));
    this.hasRings=Math.random()<.6;this.ringTilt=rand(.15,.4);
    this.parent=null;this.orbitAngle=rand(0,Math.PI*2);
    this.orbitDist=rand(80,200);
    this.orbitSpeed=rand(.15,.5)/Math.sqrt(this.orbitDist/50);
    this.temp=rand(80,200);this._pT=rand(0,Math.PI*2);
    // Tempestade
    this._stormAngle=rand(0,Math.PI*2);
    this._shockTimer=0;this._shockMax=rand(6,12);
    this._shockWaveR=0;this._shockAlpha=0;
  }
  update(dt){
    this._pT+=dt;
    this._stormAngle+=dt*0.4;
    this._shockTimer+=dt;
    if(this._shockTimer>=this._shockMax){
      this._shockTimer=0;this._shockWaveR=this.radius*1.1;this._shockAlpha=0.7;
      // Empurra objetos próximos suavemente
      objects.forEach(o=>{
        if(o===this||o.dead)return;
        const d=dist(o,this);const range=this.radius*6;
        if(d<range&&d>this.radius){
          const f=18*(1-d/range),nx=(o.x-this.x)/d,ny=(o.y-this.y)/d;
          o.vx=(o.vx||0)+nx*f; o.vy=(o.vy||0)+ny*f;
          if(PP_ORBIT_TYPES.includes(o.type)||o.type==='planet'||o.type==='moon') o.parent=null;
        }
      });
    }
    if(this._shockWaveR>0){
      this._shockWaveR+=dt*60;this._shockAlpha=Math.max(0,this._shockAlpha-dt*0.55);
      if(this._shockAlpha<=0) this._shockWaveR=0;
    }
    _ppUpdateOrbit(this,dt);
  }
  draw(){
    const sx=this.sx(),sy=this.sy(),r=this.sr();
    // Onda de choque
    if(this._shockWaveR>0){
      ctx.beginPath();ctx.arc(sx,sy,this._shockWaveR*cam.zoom,0,Math.PI*2);
      ctx.strokeStyle=`hsla(${this._bandH+10},90%,70%,${this._shockAlpha})`;
      ctx.lineWidth=2;ctx.stroke();
    }
    // Anéis atrás
    if(this.hasRings){
      ctx.save();ctx.translate(sx,sy);ctx.scale(1,this.ringTilt);
      ctx.beginPath();ctx.arc(0,0,r*2.2,0,Math.PI*2);
      ctx.strokeStyle=`hsla(${this._bandH},70%,65%,0.5)`;ctx.lineWidth=r*.7;ctx.stroke();ctx.restore();
    }
    const g=ctx.createRadialGradient(sx-r*.3,sy-r*.3,r*.1,sx,sy,r);
    g.addColorStop(0,'#fff8');g.addColorStop(.4,this.color);g.addColorStop(1,`hsl(${this._bandH+20},70%,30%)`);
    ctx.beginPath();ctx.arc(sx,sy,r,0,Math.PI*2);ctx.fillStyle=g;ctx.fill();
    ctx.save();ctx.beginPath();ctx.arc(sx,sy,r,0,Math.PI*2);ctx.clip();
    this._bands.forEach((f,i)=>{
      const by=sy-r+r*.3+i*(r*2/this._bands.length);
      const bh=r*.18+f*r*.14;
      ctx.fillStyle=`hsla(${this._bandH+(i%2===0?-18:22)},80%,${45+f*18}%,${0.32+f*.18})`;
      ctx.fillRect(sx-r,by-bh/2,r*2,bh);
    });
    // Grande mancha girando
    const mx=sx+Math.cos(this._stormAngle)*r*.3,my=sy+Math.sin(this._stormAngle)*r*.18;
    const mg=ctx.createRadialGradient(mx,my,0,mx,my,r*.32);
    mg.addColorStop(0,`hsla(${this._bandH-15},90%,55%,0.7)`);mg.addColorStop(1,'transparent');
    ctx.beginPath();ctx.ellipse(mx,my,r*.32,r*.18,this._stormAngle,0,Math.PI*2);ctx.fillStyle=mg;ctx.fill();
    ctx.restore();
    if(sandboxMode){ctx.font=`${Math.max(6,r*.3)}px 'Courier New'`;ctx.fillStyle='rgba(255,220,150,.28)';ctx.textAlign='center';ctx.fillText(this.name,sx,sy+r+8*cam.zoom);ctx.textAlign='left';}
  }
}

// ─── 2. GIGANTE DE GELO ──────────────────────────────────────────
// Função única: Cristalização — quando outro objeto passa perto,
// o Gigante de Gelo libera fragmentos de gelo que se tornam luas temporárias.
class IceGiant extends CelestialObject{
  constructor(wx,wy){
    super(wx,wy,'icegiant');
    this.radius=rand(16,32);this.mass=this.radius*4;
    const h=randInt(185,225);
    this.color=`hsl(${h},75%,60%)`;this._hue=h;
    this.hasRings=Math.random()<.45;this.ringTilt=rand(.2,.5);
    this.parent=null;this.orbitAngle=rand(0,Math.PI*2);
    this.orbitDist=rand(80,180);
    this.orbitSpeed=rand(.2,.6)/Math.sqrt(this.orbitDist/50);
    this.temp=rand(50,120);this._pT=rand(0,Math.PI*2);
    this._crystalTimer=0;this._crystalMax=rand(8,15);
    this._shards=[];// partículas de gelo visuais
  }
  update(dt){
    this._pT+=dt;
    this._crystalTimer+=dt;
    // Shard animation
    this._shards=this._shards.filter(s=>{s.life-=dt;s.r+=dt*12;s.alpha=s.life/s.maxLife;return s.life>0;});
    // A cada ciclo: lança fragmentos visuais se houver objeto próximo
    if(this._crystalTimer>=this._crystalMax){
      this._crystalTimer=0;
      const near=objects.find(o=>o!==this&&!o.dead&&dist(o,this)<this.radius*5&&(PP_ORBIT_TYPES.includes(o.type)||o.type==='planet'||o.type==='meteor'||o.type==='comet'));
      if(near){
        for(let i=0;i<5;i++){
          const a=rand(0,Math.PI*2);
          this._shards.push({x:this.x+Math.cos(a)*this.radius,y:this.y+Math.sin(a)*this.radius,a,r:2,alpha:1,life:rand(1.2,2.5),maxLife:2.5});
        }
        // Congela levemente o objeto próximo (efeito visual de cor)
        if(!near._iceFrozen){near._iceFrozen=true;near._iceTimer=4;near._origColor=near.color;near.color=`hsl(${this._hue},55%,72%)`;}
      }
    }
    // Descongela objetos
    objects.forEach(o=>{if(o._iceFrozen){o._iceTimer-=dt;if(o._iceTimer<=0){o._iceFrozen=false;if(o._origColor)o.color=o._origColor;}}});
    _ppUpdateOrbit(this,dt);
  }
  draw(){
    const sx=this.sx(),sy=this.sy(),r=this.sr();
    // Fragmentos de gelo
    this._shards.forEach(s=>{
      const {x:px,y:py}=worldToScreen(s.x,s.y);
      ctx.beginPath();ctx.arc(px,py,s.r*cam.zoom,0,Math.PI*2);
      ctx.fillStyle=`hsla(${this._hue},80%,85%,${s.alpha})`;ctx.fill();
    });
    if(this.hasRings){
      ctx.save();ctx.translate(sx,sy);ctx.scale(1,this.ringTilt);
      ctx.beginPath();ctx.arc(0,0,r*2.0,0,Math.PI*2);
      ctx.strokeStyle=`hsla(${this._hue},60%,75%,0.4)`;ctx.lineWidth=r*.55;ctx.stroke();ctx.restore();
    }
    const g=ctx.createRadialGradient(sx-r*.25,sy-r*.25,r*.08,sx,sy,r);
    g.addColorStop(0,'rgba(220,245,255,.9)');g.addColorStop(.35,this.color);
    g.addColorStop(.75,`hsl(${this._hue+15},60%,38%)`);g.addColorStop(1,`hsl(${this._hue+25},50%,22%)`);
    ctx.beginPath();ctx.arc(sx,sy,r,0,Math.PI*2);ctx.fillStyle=g;ctx.fill();
    ctx.save();ctx.beginPath();ctx.arc(sx,sy,r,0,Math.PI*2);ctx.clip();
    ctx.fillStyle=`hsla(${this._hue-15},100%,75%,${0.22+0.08*Math.sin(this._pT)})`;
    ctx.fillRect(sx-r,sy-r*.14,r*2,r*.28);
    const cp=ctx.createRadialGradient(sx,sy-r*.68,0,sx,sy-r*.5,r*.4);
    cp.addColorStop(0,'rgba(240,252,255,.72)');cp.addColorStop(1,'transparent');
    ctx.beginPath();ctx.arc(sx,sy-r*.5,r*.4,0,Math.PI*2);ctx.fillStyle=cp;ctx.fill();
    ctx.restore();
    if(sandboxMode){ctx.font=`${Math.max(6,r*.3)}px 'Courier New'`;ctx.fillStyle='rgba(160,230,255,.28)';ctx.textAlign='center';ctx.fillText(this.name,sx,sy+r+8*cam.zoom);ctx.textAlign='left';}
  }
}

// ─── 3. SUPER TERRA ──────────────────────────────────────────────
// Função única: Campo Magnético Protetor — emite um escudo que desvia
// meteoros e cometas que se aproximam, refletindo-os.
class SuperEarth extends CelestialObject{
  constructor(wx,wy){
    super(wx,wy,'superearth');
    this.radius=rand(14,24);this.mass=this.radius*3.5;
    const h=randInt(90,160);
    this.color=`hsl(${h},65%,45%)`;this._hue=h;
    this.parent=null;this.orbitAngle=rand(0,Math.PI*2);
    this.orbitDist=rand(70,180);
    this.orbitSpeed=rand(.25,.7)/Math.sqrt(this.orbitDist/50);
    this.temp=rand(200,500);this._pT=rand(0,Math.PI*2);
    this._shieldRange=this.radius*4.5;
    this._shieldPulse=rand(0,Math.PI*2);
  }
  update(dt){
    this._pT+=dt;this._shieldPulse+=dt*1.2;
    // Desvia meteoros e cometas
    objects.forEach(o=>{
      if(o===this||o.dead)return;
      if(o.type!=='meteor'&&o.type!=='comet')return;
      const d=dist(o,this);
      if(d<this._shieldRange&&d>this.radius+o.radius){
        // Reflete a velocidade radialmente
        const nx=(o.x-this.x)/d,ny=(o.y-this.y)/d;
        const dot=(o.vx||0)*nx+(o.vy||0)*ny;
        if(dot<0){// só reflete se vindo em direção ao planeta
          o.vx=(o.vx||0)-2*dot*nx;o.vy=(o.vy||0)-2*dot*ny;
          o.vx*=0.85;o.vy*=0.85;
        }
      }
    });
    _ppUpdateOrbit(this,dt);
  }
  draw(){
    const sx=this.sx(),sy=this.sy(),r=this.sr();
    // Escudo magnético pulsante
    const shR=this._shieldRange*cam.zoom;
    const pulse=0.12+0.06*Math.sin(this._shieldPulse);
    ctx.beginPath();ctx.arc(sx,sy,shR,0,Math.PI*2);
    ctx.strokeStyle=`hsla(${this._hue+40},80%,65%,${pulse})`;ctx.lineWidth=2.5;ctx.stroke();
    // Linhas de campo magnético
    for(let i=0;i<4;i++){
      const a=(i/4)*Math.PI*2+this._pT*.05;
      ctx.beginPath();
      ctx.ellipse(sx,sy,shR*.85,shR*.35,a,0,Math.PI*2);
      ctx.strokeStyle=`hsla(${this._hue+50},70%,60%,${0.08+0.04*Math.sin(this._shieldPulse+i)})`;
      ctx.lineWidth=1.2;ctx.stroke();
    }
    const g=ctx.createRadialGradient(sx-r*.28,sy-r*.28,r*.08,sx,sy,r);
    g.addColorStop(0,'rgba(255,255,255,.8)');
    g.addColorStop(.3,`hsl(${this._hue+10},70%,60%)`);
    g.addColorStop(.65,this.color);g.addColorStop(1,`hsl(${this._hue-10},55%,22%)`);
    ctx.beginPath();ctx.arc(sx,sy,r,0,Math.PI*2);ctx.fillStyle=g;ctx.fill();
    ctx.save();ctx.beginPath();ctx.arc(sx,sy,r,0,Math.PI*2);ctx.clip();
    [[-.25,-.18,.38,.26],[.3,.1,.28,.22],[-.15,.32,.32,.18]].forEach(([ox,oy,rw,rh])=>{
      ctx.fillStyle=`hsla(${this._hue-40},55%,38%,0.55)`;
      ctx.beginPath();ctx.ellipse(sx+r*ox,sy+r*oy,r*rw,r*rh,this._pT*.05,0,Math.PI*2);ctx.fill();
    });
    ctx.restore();
    if(sandboxMode){ctx.font=`${Math.max(6,r*.3)}px 'Courier New'`;ctx.fillStyle='rgba(160,220,140,.28)';ctx.textAlign='center';ctx.fillText(this.name,sx,sy+r+8*cam.zoom);ctx.textAlign='left';}
  }
}

// ─── 4. MINI-NETUNO ──────────────────────────────────────────────
// Função única: Vórtice de Hidrogênio — aspira detritos leves (meteoros
// e cometas pequenos) para seu interior como um aspirador cósmico.
class MiniNeptune extends CelestialObject{
  constructor(wx,wy){
    super(wx,wy,'minineptune');
    this.radius=rand(10,18);this.mass=this.radius*3;
    const h=randInt(200,240);
    this.color=`hsl(${h},80%,55%)`;this._hue=h;
    this.hasRings=Math.random()<.3;this.ringTilt=rand(.2,.55);
    this.parent=null;this.orbitAngle=rand(0,Math.PI*2);
    this.orbitDist=rand(60,160);
    this.orbitSpeed=rand(.3,.8)/Math.sqrt(this.orbitDist/50);
    this.temp=rand(60,160);this._pT=rand(0,Math.PI*2);
    this._pullRange=this.radius*5.5;
  }
  update(dt){
    this._pT+=dt;
    // Aspira meteoros e cometas pequenos
    objects.forEach(o=>{
      if(o===this||o.dead)return;
      if((o.type!=='meteor'&&o.type!=='comet')||o.radius>8)return;
      const d=dist(o,this);
      if(d<this._pullRange&&d>this.radius+o.radius){
        const f=40*(1-d/this._pullRange),nx=(this.x-o.x)/d,ny=(this.y-o.y)/d;
        o.vx=(o.vx||0)+nx*f*dt;o.vy=(o.vy||0)+ny*f*dt;
      }
    });
    _ppUpdateOrbit(this,dt);
  }
  draw(){
    const sx=this.sx(),sy=this.sy(),r=this.sr();
    // Halo de aspiração giratório
    const pullR=this._pullRange*cam.zoom;
    for(let i=0;i<3;i++){
      const a=this._pT*0.8+i*(Math.PI*2/3);
      ctx.beginPath();
      ctx.arc(sx,sy,pullR*(0.7+i*.12),a,a+Math.PI*1.3);
      ctx.strokeStyle=`hsla(${this._hue-10},80%,70%,${0.06+i*.03})`;
      ctx.lineWidth=1.5;ctx.stroke();
    }
    if(this.hasRings){
      ctx.save();ctx.translate(sx,sy);ctx.scale(1,this.ringTilt);
      ctx.beginPath();ctx.arc(0,0,r*1.9,0,Math.PI*2);
      ctx.strokeStyle=`hsla(${this._hue},60%,70%,0.38)`;ctx.lineWidth=r*.5;ctx.stroke();ctx.restore();
    }
    const g=ctx.createRadialGradient(sx-r*.22,sy-r*.22,r*.06,sx,sy,r);
    g.addColorStop(0,'rgba(200,230,255,.9)');g.addColorStop(.4,this.color);
    g.addColorStop(.8,`hsl(${this._hue+20},65%,30%)`);g.addColorStop(1,'#0a1830');
    ctx.beginPath();ctx.arc(sx,sy,r,0,Math.PI*2);ctx.fillStyle=g;ctx.fill();
    ctx.save();ctx.beginPath();ctx.arc(sx,sy,r,0,Math.PI*2);ctx.clip();
    ctx.strokeStyle=`hsla(${this._hue-20},90%,75%,${0.28+0.1*Math.sin(this._pT)})`;ctx.lineWidth=r*.18;
    ctx.beginPath();ctx.arc(sx,sy-r*.45,r*.3,0,Math.PI*2);ctx.stroke();
    ctx.restore();
    if(sandboxMode){ctx.font=`${Math.max(6,r*.35)}px 'Courier New'`;ctx.fillStyle='rgba(140,200,255,.28)';ctx.textAlign='center';ctx.fillText(this.name,sx,sy+r+8*cam.zoom);ctx.textAlign='left';}
  }
}

// ─── 5. PLANETA ANÃO ─────────────────────────────────────────────
// Função única: Errante Caótico — orbita de forma instável com excentricidade
// variável, alternando entre órbitas apertadas e elípticas dramaticamente.
class DwarfPlanet extends CelestialObject{
  constructor(wx,wy){
    super(wx,wy,'dwarfplanet');
    this.radius=rand(4,9);this.mass=this.radius*1.5;
    const h=randInt(20,60);
    this.color=`hsl(${h},22%,48%)`;this._hue=h;
    this.parent=null;this.orbitAngle=rand(0,Math.PI*2);
    this.orbitDist=rand(50,300);
    this.orbitSpeed=rand(.2,.9)/Math.sqrt(this.orbitDist/50);
    this.temp=rand(30,100);this._ang=rand(0,Math.PI*2);
    // Excentricidade caótica
    this._eccPhase=rand(0,Math.PI*2);this._eccSpeed=rand(0.08,0.2);
    this._baseOrbitDist=this.orbitDist;
    this._eccTrail=[];
  }
  update(dt){
    this._ang+=dt;this._eccPhase+=dt*this._eccSpeed;
    // Modula a distância orbital de forma senoidal — órbita excêntrica
    if(this.parent&&!this.parent.dead){
      const ecc=0.35+0.3*Math.sin(this._eccPhase);
      this.orbitDist=this._baseOrbitDist*(1+ecc*Math.cos(this.orbitAngle));
    }
    // Rastro curto
    this._eccTrail.unshift({x:this.x,y:this.y});
    if(this._eccTrail.length>18) this._eccTrail.length=18;
    _ppUpdateOrbit(this,dt);
  }
  draw(){
    const sx=this.sx(),sy=this.sy(),r=this.sr();
    // Rastro elíptico
    for(let i=1;i<this._eccTrail.length;i++){
      const pa=worldToScreen(this._eccTrail[i-1].x,this._eccTrail[i-1].y);
      const pb=worldToScreen(this._eccTrail[i].x,this._eccTrail[i].y);
      const a=(1-i/this._eccTrail.length)*0.35;
      ctx.beginPath();ctx.moveTo(pa.x,pa.y);ctx.lineTo(pb.x,pb.y);
      ctx.strokeStyle=`hsla(${this._hue},30%,60%,${a})`;ctx.lineWidth=1.2;ctx.stroke();
    }
    const g=ctx.createRadialGradient(sx-r*.3,sy-r*.3,r*.05,sx,sy,r);
    g.addColorStop(0,'rgba(200,190,160,.9)');g.addColorStop(.5,this.color);g.addColorStop(1,`hsl(${this._hue+10},15%,25%)`);
    ctx.beginPath();ctx.arc(sx,sy,r,0,Math.PI*2);ctx.fillStyle=g;ctx.fill();
    // Cratera
    ctx.save();ctx.beginPath();ctx.arc(sx,sy,r,0,Math.PI*2);ctx.clip();
    ctx.beginPath();ctx.arc(sx-r*.25,sy+r*.2,r*.32,0,Math.PI*2);
    ctx.fillStyle='rgba(0,0,0,0.22)';ctx.fill();
    ctx.restore();
    if(sandboxMode){ctx.font=`${Math.max(6,r*.55)}px 'Courier New'`;ctx.fillStyle='rgba(200,180,140,.28)';ctx.textAlign='center';ctx.fillText(this.name,sx,sy+r+8*cam.zoom);ctx.textAlign='left';}
  }
}

// ─── 6. PLANETA DE LAVA ──────────────────────────────────────────
// Função única: Erupção Vulcânica — periodicamente espalha projéteis de lava
// que viajam radialmente e se transformam em meteoros ao pousar longe.
class LavaPlanet extends CelestialObject{
  constructor(wx,wy){
    super(wx,wy,'lavaplt');
    this.radius=rand(10,20);this.mass=this.radius*3;
    this.parent=null;this.orbitAngle=rand(0,Math.PI*2);
    this.orbitDist=rand(50,150);
    this.orbitSpeed=rand(.3,.8)/Math.sqrt(this.orbitDist/50);
    this.temp=rand(1200,2800);this._pT=rand(0,Math.PI*2);
    this._eruptTimer=0;this._eruptMax=rand(4,9);
    this._blobs=[];// projéteis visuais
  }
  update(dt){
    this._pT+=dt;
    this._eruptTimer+=dt;
    // Atualiza blobs
    this._blobs=this._blobs.filter(b=>{
      b.life-=dt;b.x+=b.vx*dt;b.y+=b.vy*dt;
      b.vx*=0.97;b.vy*=0.97;
      return b.life>0;
    });
    if(this._eruptTimer>=this._eruptMax){
      this._eruptTimer=0;
      // Lança 6 projéteis de lava em leque
      const count=6+randInt(0,4);
      for(let i=0;i<count;i++){
        const a=rand(0,Math.PI*2);
        const spd=rand(40,100);
        this._blobs.push({
          x:this.x+Math.cos(a)*this.radius,y:this.y+Math.sin(a)*this.radius,
          vx:Math.cos(a)*spd,vy:Math.sin(a)*spd,
          life:rand(1.5,3.5),maxLife:3.5,r:rand(1.5,3.5)
        });
      }
    }
    _ppUpdateOrbit(this,dt);
  }
  draw(){
    const sx=this.sx(),sy=this.sy(),r=this.sr();
    // Projéteis de lava
    this._blobs.forEach(b=>{
      const {x:bx,y:by}=worldToScreen(b.x,b.y);
      const life=b.life/b.maxLife;
      const col=life>0.5?`rgba(255,${~~(80+120*life)},0,${life})`:`rgba(180,${~~(30+60*life)},0,${life*0.7})`;
      ctx.beginPath();ctx.arc(bx,by,b.r*cam.zoom,0,Math.PI*2);ctx.fillStyle=col;ctx.fill();
    });
    // Brilho de erupção iminente
    const eruptFrac=this._eruptTimer/this._eruptMax;
    if(eruptFrac>0.7){
      const glow=ctx.createRadialGradient(sx,sy,r*.8,sx,sy,r*1.8);
      glow.addColorStop(0,`rgba(255,120,0,${(eruptFrac-.7)*0.6})`);glow.addColorStop(1,'transparent');
      ctx.beginPath();ctx.arc(sx,sy,r*1.8,0,Math.PI*2);ctx.fillStyle=glow;ctx.fill();
    }
    const g=ctx.createRadialGradient(sx-r*.2,sy-r*.2,r*.05,sx,sy,r);
    g.addColorStop(0,'rgba(255,230,80,.9)');g.addColorStop(.3,'#ff6600');g.addColorStop(.7,'#cc2200');g.addColorStop(1,'#550000');
    ctx.beginPath();ctx.arc(sx,sy,r,0,Math.PI*2);ctx.fillStyle=g;ctx.fill();
    ctx.save();ctx.beginPath();ctx.arc(sx,sy,r,0,Math.PI*2);ctx.clip();
    for(let i=0;i<4;i++){
      const a=(i/4)*Math.PI*2+this._pT*.15;
      ctx.strokeStyle=`rgba(255,${140+~~(80*Math.sin(this._pT+i))},0,0.55)`;
      ctx.lineWidth=r*.14;ctx.beginPath();ctx.moveTo(sx,sy);ctx.lineTo(sx+Math.cos(a)*r,sy+Math.sin(a)*r);ctx.stroke();
    }
    ctx.restore();
    if(sandboxMode){ctx.font=`${Math.max(6,r*.3)}px 'Courier New'`;ctx.fillStyle='rgba(255,140,60,.3)';ctx.textAlign='center';ctx.fillText(this.name,sx,sy+r+8*cam.zoom);ctx.textAlign='left';}
  }
}

// ─── 7. PLANETA OCEÂNICO ─────────────────────────────────────────
// Função única: Maré Gravitacional — cria ondas de pressão no espaço ao
// redor que alteram a velocidade orbital de planetas vizinhos cadencialmente.
class OceanPlanet extends CelestialObject{
  constructor(wx,wy){
    super(wx,wy,'oceanplt');
    this.radius=rand(12,22);this.mass=this.radius*3.2;
    this.color='#1a8cd8';this._pT=rand(0,Math.PI*2);
    this.parent=null;this.orbitAngle=rand(0,Math.PI*2);
    this.orbitDist=rand(70,180);
    this.orbitSpeed=rand(.25,.65)/Math.sqrt(this.orbitDist/50);
    this.temp=rand(280,360);
    this._tideRange=this.radius*7;this._tidePhase=rand(0,Math.PI*2);
  }
  update(dt){
    this._pT+=dt;this._tidePhase+=dt*0.55;
    // Maré: oscila a velocidade orbital de planetas vizinhos
    const tideForce=Math.sin(this._tidePhase)*0.004;
    objects.forEach(o=>{
      if(o===this||o.dead||!o.parent)return;
      if(!PP_ORBIT_TYPES.includes(o.type)&&o.type!=='planet')return;
      if(dist(o,this)<this._tideRange){
        o.orbitSpeed=Math.max(0.02, (o.orbitSpeed||0.3)+tideForce);
      }
    });
    _ppUpdateOrbit(this,dt);
  }
  draw(){
    const sx=this.sx(),sy=this.sy(),r=this.sr();
    // Ondas de maré
    for(let i=1;i<=3;i++){
      const tR=this._tideRange*cam.zoom*(0.4+i*.2);
      const a=0.04+0.025*Math.sin(this._tidePhase+i);
      ctx.beginPath();ctx.arc(sx,sy,tR,0,Math.PI*2);
      ctx.strokeStyle=`rgba(50,160,240,${a})`;ctx.lineWidth=1.5;ctx.stroke();
    }
    const g=ctx.createRadialGradient(sx-r*.25,sy-r*.25,r*.08,sx,sy,r);
    g.addColorStop(0,'rgba(160,220,255,.9)');g.addColorStop(.35,'#2299ee');g.addColorStop(.75,'#1155aa');g.addColorStop(1,'#061830');
    ctx.beginPath();ctx.arc(sx,sy,r,0,Math.PI*2);ctx.fillStyle=g;ctx.fill();
    ctx.save();ctx.beginPath();ctx.arc(sx,sy,r,0,Math.PI*2);ctx.clip();
    for(let i=0;i<5;i++){
      const wy2=sy-r+r*.2+i*(r*2/5);
      ctx.strokeStyle=`rgba(100,200,255,${0.18+0.1*Math.sin(this._pT+i)})`;
      ctx.lineWidth=r*.08;ctx.beginPath();
      ctx.moveTo(sx-r,wy2);ctx.bezierCurveTo(sx-r*.5,wy2-r*.06*Math.sin(this._pT+i),sx+r*.5,wy2+r*.06*Math.sin(this._pT+i+1),sx+r,wy2);ctx.stroke();
    }
    const cp=ctx.createRadialGradient(sx,sy-r*.72,0,sx,sy-r*.55,r*.35);
    cp.addColorStop(0,'rgba(240,252,255,.75)');cp.addColorStop(1,'transparent');
    ctx.beginPath();ctx.arc(sx,sy-r*.55,r*.35,0,Math.PI*2);ctx.fillStyle=cp;ctx.fill();
    ctx.restore();
    if(sandboxMode){ctx.font=`${Math.max(6,r*.3)}px 'Courier New'`;ctx.fillStyle='rgba(100,200,255,.28)';ctx.textAlign='center';ctx.fillText(this.name,sx,sy+r+8*cam.zoom);ctx.textAlign='left';}
  }
}

// ─── 8. PLANETA DESERTO ──────────────────────────────────────────
// Função única: Tempestade de Areia Solar — libera nuvens de poeira que
// reduzem temporariamente o brilho de estrelas próximas.
class DesertPlanet extends CelestialObject{
  constructor(wx,wy){
    super(wx,wy,'desertplt');
    this.radius=rand(10,20);this.mass=this.radius*2.8;
    const h=randInt(25,45);
    this.color=`hsl(${h},70%,52%)`;this._hue=h;this._pT=rand(0,Math.PI*2);
    this.parent=null;this.orbitAngle=rand(0,Math.PI*2);
    this.orbitDist=rand(60,180);
    this.orbitSpeed=rand(.25,.7)/Math.sqrt(this.orbitDist/50);
    this.temp=rand(350,700);
    this._dustTimer=0;this._dustMax=rand(7,14);
    this._dustClouds=[];
  }
  update(dt){
    this._pT+=dt;this._dustTimer+=dt;
    this._dustClouds=this._dustClouds.filter(d=>{d.life-=dt;d.r+=dt*15;d.alpha=0.15*(d.life/d.maxLife);return d.life>0;});
    if(this._dustTimer>=this._dustMax){
      this._dustTimer=0;
      for(let i=0;i<4;i++){
        const a=rand(0,Math.PI*2);
        const dist2=rand(this.radius,this.radius*2.5);
        this._dustClouds.push({x:this.x+Math.cos(a)*dist2,y:this.y+Math.sin(a)*dist2,r:this.radius*.5,alpha:.15,life:rand(2,4),maxLife:4});
      }
      // Reduz levemente o brilho da estrela hospedeira
      if(this.parent&&!this.parent.dead&&this.parent.type==='star'){
        if(!this.parent._dustened){
          this.parent._dustened=true;this.parent._origRadius=this.parent.radius;
          this.parent._dustTimer=3;
        }
      }
    }
    if(this.parent&&this.parent._dustened){
      this.parent._dustTimer-=dt;
      if(this.parent._dustTimer<=0){this.parent._dustened=false;}
    }
    _ppUpdateOrbit(this,dt);
  }
  draw(){
    const sx=this.sx(),sy=this.sy(),r=this.sr();
    this._dustClouds.forEach(d=>{
      const {x:dx,y:dy}=worldToScreen(d.x,d.y);
      ctx.beginPath();ctx.arc(dx,dy,d.r*cam.zoom,0,Math.PI*2);
      ctx.fillStyle=`hsla(${this._hue+10},55%,68%,${d.alpha})`;ctx.fill();
    });
    const g=ctx.createRadialGradient(sx-r*.25,sy-r*.25,r*.08,sx,sy,r);
    g.addColorStop(0,'rgba(255,240,180,.9)');g.addColorStop(.4,this.color);
    g.addColorStop(.75,`hsl(${this._hue-5},60%,35%)`);g.addColorStop(1,'#1a0800');
    ctx.beginPath();ctx.arc(sx,sy,r,0,Math.PI*2);ctx.fillStyle=g;ctx.fill();
    ctx.save();ctx.beginPath();ctx.arc(sx,sy,r,0,Math.PI*2);ctx.clip();
    for(let i=0;i<4;i++){
      const dy=sy-r*.6+i*(r*1.2/4);
      ctx.strokeStyle=`hsla(${this._hue-10},65%,${30+i*5}%,0.35)`;
      ctx.lineWidth=r*.22;ctx.beginPath();
      ctx.moveTo(sx-r,dy);ctx.bezierCurveTo(sx-r*.4,dy-r*.12,sx+r*.4,dy+r*.12,sx+r,dy);ctx.stroke();
    }
    ctx.fillStyle=`hsla(${this._hue+10},60%,72%,${0.1+0.06*Math.sin(this._pT)})`;
    ctx.beginPath();ctx.ellipse(sx,sy+r*.2,r*.85,r*.22,0,0,Math.PI*2);ctx.fill();
    ctx.restore();
    if(sandboxMode){ctx.font=`${Math.max(6,r*.3)}px 'Courier New'`;ctx.fillStyle='rgba(255,200,100,.28)';ctx.textAlign='center';ctx.fillText(this.name,sx,sy+r+8*cam.zoom);ctx.textAlign='left';}
  }
}

// ─── 9. PLANETA DE CARBONO ───────────────────────────────────────
// Função única: Pressão de Diamante — absorve qualquer meteoro que encoste,
// convertendo-o em massa própria (aumenta de tamanho levemente).
class CarbonPlanet extends CelestialObject{
  constructor(wx,wy){
    super(wx,wy,'carbonplt');
    this.radius=rand(10,19);this.mass=this.radius*4;
    this.color='#1a1a2e';this._pT=rand(0,Math.PI*2);
    this.parent=null;this.orbitAngle=rand(0,Math.PI*2);
    this.orbitDist=rand(60,200);
    this.orbitSpeed=rand(.2,.65)/Math.sqrt(this.orbitDist/50);
    this.temp=rand(500,2000);
    this._absorbs=0;// quantos meteoros absorveu
    this._flashTimer=0;
  }
  update(dt){
    this._pT+=dt;if(this._flashTimer>0)this._flashTimer-=dt;
    // Absorve meteoros que encostam
    objects.forEach(o=>{
      if(o===this||o.dead||o.type!=='meteor')return;
      if(dist(o,this)<this.radius+o.radius+2){
        o.dead=true;this._absorbs++;
        // Cresce levemente, máximo 35u
        this.radius=Math.min(35, this.radius+0.8);
        this.mass=this.radius*4;this._flashTimer=0.5;
      }
    });
    _ppUpdateOrbit(this,dt);
  }
  draw(){
    const sx=this.sx(),sy=this.sy(),r=this.sr();
    const flash=this._flashTimer>0?0.6:0;
    if(flash>0){
      const gl=ctx.createRadialGradient(sx,sy,r*.5,sx,sy,r*2.2);
      gl.addColorStop(0,`rgba(200,190,255,${flash})`);gl.addColorStop(1,'transparent');
      ctx.beginPath();ctx.arc(sx,sy,r*2.2,0,Math.PI*2);ctx.fillStyle=gl;ctx.fill();
    }
    const g=ctx.createRadialGradient(sx-r*.22,sy-r*.22,r*.06,sx,sy,r);
    g.addColorStop(0,'rgba(120,120,160,.9)');g.addColorStop(.35,'#2a2a4a');g.addColorStop(.7,'#0d0d1a');g.addColorStop(1,'#000000');
    ctx.beginPath();ctx.arc(sx,sy,r,0,Math.PI*2);ctx.fillStyle=g;ctx.fill();
    ctx.save();ctx.beginPath();ctx.arc(sx,sy,r,0,Math.PI*2);ctx.clip();
    for(let i=0;i<6;i++){
      const a=(i/6)*Math.PI*2+this._pT*.03;
      const bx=sx+Math.cos(a)*r*.55,by=sy+Math.sin(a)*r*.55;
      ctx.strokeStyle=`rgba(160,140,255,${0.22+0.12*Math.sin(this._pT*2+i)})`;
      ctx.lineWidth=r*.08;ctx.beginPath();ctx.moveTo(sx,sy);ctx.lineTo(bx,by);ctx.stroke();
      ctx.fillStyle=`rgba(220,210,255,${0.55+0.35*Math.sin(this._pT*3+i)})`;
      ctx.beginPath();ctx.arc(bx,by,r*.07,0,Math.PI*2);ctx.fill();
    }
    ctx.restore();
    const sp=ctx.createRadialGradient(sx-r*.3,sy-r*.3,0,sx-r*.15,sy-r*.15,r*.4);
    sp.addColorStop(0,'rgba(200,190,255,0.55)');sp.addColorStop(1,'transparent');
    ctx.beginPath();ctx.arc(sx-r*.15,sy-r*.15,r*.4,0,Math.PI*2);ctx.fillStyle=sp;ctx.fill();
    if(this._absorbs>0&&sandboxMode){
      ctx.font=`${Math.max(5,r*.28)}px 'Courier New'`;ctx.fillStyle='rgba(180,170,255,.45)';
      ctx.textAlign='center';ctx.fillText(`+${this._absorbs}☄`,sx+r*.6,sy-r*.6);ctx.textAlign='left';
    }
    if(sandboxMode){ctx.font=`${Math.max(6,r*.3)}px 'Courier New'`;ctx.fillStyle='rgba(150,140,220,.28)';ctx.textAlign='center';ctx.fillText(this.name,sx,sy+r+8*cam.zoom);ctx.textAlign='left';}
  }
}

// ─── 10. PLANETA DE FERRO ────────────────────────────────────────
// Função única: Núcleo Magnético Caótico — inverte periodicamente a
// polaridade, atraindo e depois repelindo outros planetas próximos num ciclo.
class IronPlanet extends CelestialObject{
  constructor(wx,wy){
    super(wx,wy,'ironplt');
    this.radius=rand(8,16);this.mass=this.radius*5;
    this.color='#8b2500';this._pT=rand(0,Math.PI*2);
    this.parent=null;this.orbitAngle=rand(0,Math.PI*2);
    this.orbitDist=rand(40,130);
    this.orbitSpeed=rand(.35,.9)/Math.sqrt(this.orbitDist/50);
    this.temp=rand(600,1800);
    this._polarity=1;// +1 = atrai, -1 = repele
    this._polTimer=0;this._polMax=rand(5,10);
    this._fieldRange=this.radius*5.5;
    this._flipFlash=0;
  }
  update(dt){
    this._pT+=dt;this._polTimer+=dt;if(this._flipFlash>0)this._flipFlash-=dt;
    if(this._polTimer>=this._polMax){
      this._polTimer=0;this._polarity*=-1;this._flipFlash=0.6;
      // Aplica impulso nos vizinhos ao flipar
      objects.forEach(o=>{
        if(o===this||o.dead)return;
        if(!PP_ORBIT_TYPES.includes(o.type)&&o.type!=='planet')return;
        const d=dist(o,this);if(d>this._fieldRange||d<1)return;
        const f=this._polarity*28*(1-d/this._fieldRange);
        const nx=(o.x-this.x)/d,ny=(o.y-this.y)/d;
        o.vx=(o.vx||0)+nx*f;o.vy=(o.vy||0)+ny*f;
        if(PP_ORBIT_TYPES.includes(o.type)||o.type==='planet') o.parent=null;
      });
    }
    _ppUpdateOrbit(this,dt);
  }
  draw(){
    const sx=this.sx(),sy=this.sy(),r=this.sr();
    const fR=this._fieldRange*cam.zoom;
    // Linhas de campo magnético
    const col=this._polarity>0?'rgba(255,100,60,':'rgba(80,140,255,';
    for(let i=0;i<4;i++){
      const a=this._pT*0.5+i*(Math.PI/2);
      ctx.beginPath();ctx.ellipse(sx,sy,fR*.8,fR*.35,a,0,Math.PI*2);
      ctx.strokeStyle=`${col}${0.06+0.03*Math.sin(this._pT+i)})`;ctx.lineWidth=1.4;ctx.stroke();
    }
    if(this._flipFlash>0){
      const fl=ctx.createRadialGradient(sx,sy,r*.5,sx,sy,fR*.6);
      fl.addColorStop(0,`${col}${this._flipFlash*.5})`);fl.addColorStop(1,'transparent');
      ctx.beginPath();ctx.arc(sx,sy,fR*.6,0,Math.PI*2);ctx.fillStyle=fl;ctx.fill();
    }
    const g=ctx.createRadialGradient(sx-r*.25,sy-r*.25,r*.07,sx,sy,r);
    g.addColorStop(0,'rgba(255,140,60,.85)');g.addColorStop(.3,'#cc4400');g.addColorStop(.65,'#7a1500');g.addColorStop(1,'#1a0000');
    ctx.beginPath();ctx.arc(sx,sy,r,0,Math.PI*2);ctx.fillStyle=g;ctx.fill();
    ctx.save();ctx.beginPath();ctx.arc(sx,sy,r,0,Math.PI*2);ctx.clip();
    for(let i=0;i<5;i++){
      const ox=sx+(Math.sin(i*2.1+this._pT*.05)*r*.5);
      const oy=sy+(Math.cos(i*1.7+this._pT*.05)*r*.4);
      ctx.fillStyle=`rgba(180,${50+i*12},0,0.38)`;
      ctx.beginPath();ctx.arc(ox,oy,r*(0.12+Math.sin(i)*0.08),0,Math.PI*2);ctx.fill();
    }
    const spec=ctx.createRadialGradient(sx-r*.28,sy-r*.28,0,sx-r*.15,sy-r*.15,r*.38);
    spec.addColorStop(0,'rgba(255,180,100,0.75)');spec.addColorStop(1,'transparent');
    ctx.beginPath();ctx.arc(sx-r*.15,sy-r*.15,r*.38,0,Math.PI*2);ctx.fillStyle=spec;ctx.fill();
    ctx.restore();
    // Indicador de polaridade
    if(sandboxMode){
      ctx.font=`${Math.max(5,r*.35)}px 'Courier New'`;
      ctx.fillStyle=this._polarity>0?'rgba(255,120,60,.55)':'rgba(100,160,255,.55)';
      ctx.textAlign='center';ctx.fillText(this._polarity>0?'▲':'▼',sx,sy+r*.35);ctx.textAlign='left';
    }
    if(sandboxMode){ctx.font=`${Math.max(6,r*.35)}px 'Courier New'`;ctx.fillStyle='rgba(220,100,50,.28)';ctx.textAlign='center';ctx.fillText(this.name,sx,sy+r+8*cam.zoom);ctx.textAlign='left';}
  }
}


// ═══════════════════════════════════════════════════════════════════
//  PACOTE ESTRELAS — 20 tipos estelares desbloqueados no Rank 18
//  Cada estrela tem função única, física e visual animado.
// ═══════════════════════════════════════════════════════════════════

const SP_TYPES = ['redDwarf','yellowDwarf','blueStar','redGiant','supergiant',
  'whiteDwarf','hypergiant','vampireStar','quarkStar','thorneZytkow',
  'ironStar','strangeStar','electroweakStar','planckStar','wolfRayet',
  'przybylski','janusStar','cosmicString','gravastar','quasiStar'];

// ─── 1. ANÃ VERMELHA ─────────────────────────────────────────────
// Flare Solar: jato periódico que empurra objetos próximos
// ═══════════════════════════════════════════════════════════════════
//  PACOTE ESTRELAS — Rank 18 — 20 tipos com visuais animados únicos
// ═══════════════════════════════════════════════════════════════════

// ─── 1. ANÃ VERMELHA ─────────────────────────────────────────────
// Flare Solar: jato periódico que empurra objetos
class RedDwarf extends CelestialObject{
  constructor(wx,wy){
    super(wx,wy,'redDwarf');
    this.radius=rand(6,11);this.mass=this.radius*8;
    this._t=rand(0,Math.PI*2);
    this._flareTimer=0;this._flareMax=rand(5,10);
    this._flareAngle=rand(0,Math.PI*2);this._flareAlpha=0;this._flareLen=0;
    this._spots=Array.from({length:5},()=>({a:rand(0,Math.PI*2),d:rand(.28,.7),s:rand(.1,.2),spd:rand(.015,.05),ph:rand(0,6)}));
    this.color='#ff4422';
  }
  update(dt){
    this._t+=dt;this._flareTimer+=dt;
    this._spots.forEach(s=>s.a+=s.spd*dt);
    if(this._flareAlpha>0){this._flareAlpha=Math.max(0,this._flareAlpha-dt*1.1);this._flareLen*=0.94;}
    if(this._flareTimer>=this._flareMax){
      this._flareTimer=0;this._flareAngle=rand(0,Math.PI*2);
      this._flareAlpha=1;this._flareLen=this.radius*7;
    if(window._invasionActive)return; // bloqueia interações durante invasão
      objects.forEach(o=>{
        if(o===this||o.dead)return;
        const d=dist(o,this);if(d>this.radius*8||d<1)return;
        const ang=Math.atan2(o.y-this.y,o.x-this.x);
        if(Math.abs(((ang-this._flareAngle+Math.PI*3)%(Math.PI*2))-Math.PI)<1.1){
          const f=30*(1-d/(this.radius*8)),nx=(o.x-this.x)/d,ny=(o.y-this.y)/d;
          o.vx=(o.vx||0)+nx*f;o.vy=(o.vy||0)+ny*f;o._heatFlash=2;
        }
      });
    }
  }
  draw(){
    const sx=this.sx(),sy=this.sy();
    const rBase=this.sr();
    const r=rBase*(1+0.06*Math.sin(this._t*2.8));
    const aura=ctx.createRadialGradient(sx,sy,r*.8,sx,sy,r*3.5);
    const aPulse=0.18+0.07*Math.sin(this._t*1.3);
    aura.addColorStop(0,`rgba(255,60,20,${aPulse})`);aura.addColorStop(.5,'rgba(180,20,0,.04)');aura.addColorStop(1,'transparent');
    ctx.beginPath();ctx.arc(sx,sy,r*3.5,0,Math.PI*2);ctx.fillStyle=aura;ctx.fill();
    if(this._flareAlpha>0){
      for(let i=-2;i<=2;i++){
        const a=this._flareAngle+i*0.22;
        const fl=this._flareLen*cam.zoom*(1-Math.abs(i)*.16);
        const lg=ctx.createLinearGradient(sx,sy,sx+Math.cos(a)*fl,sy+Math.sin(a)*fl);
        const fa=this._flareAlpha*(1-Math.abs(i)*.32);
        lg.addColorStop(0,`rgba(255,210,80,${fa})`);lg.addColorStop(.45,`rgba(255,80,20,${fa*.5})`);lg.addColorStop(1,'transparent');
        ctx.beginPath();ctx.moveTo(sx,sy);ctx.lineTo(sx+Math.cos(a)*fl,sy+Math.sin(a)*fl);
        ctx.strokeStyle=lg;ctx.lineWidth=(r*(0.65-Math.abs(i)*.15));ctx.stroke();
      }
      const flash=ctx.createRadialGradient(sx,sy,0,sx,sy,r*1.8);
      flash.addColorStop(0,`rgba(255,240,180,${this._flareAlpha*.65})`);flash.addColorStop(1,'transparent');
      ctx.beginPath();ctx.arc(sx,sy,r*1.8,0,Math.PI*2);ctx.fillStyle=flash;ctx.fill();
    }
    const g=ctx.createRadialGradient(sx-r*.35,sy-r*.35,r*.04,sx,sy,r);
    g.addColorStop(0,'#ffcc88');g.addColorStop(.3,'#ff6633');g.addColorStop(.72,'#cc1100');g.addColorStop(1,'#330000');
    ctx.beginPath();ctx.arc(sx,sy,r,0,Math.PI*2);ctx.fillStyle=g;ctx.fill();
    ctx.save();ctx.beginPath();ctx.arc(sx,sy,r,0,Math.PI*2);ctx.clip();
    this._spots.forEach(s=>{
      const bx=sx+Math.cos(s.a)*r*s.d,by=sy+Math.sin(s.a)*r*s.d;
      const al=0.35+0.18*Math.sin(this._t*2.2+s.ph);
      ctx.beginPath();ctx.arc(bx,by,r*s.s,0,Math.PI*2);ctx.fillStyle=`rgba(50,0,0,${al})`;ctx.fill();
      ctx.beginPath();ctx.arc(bx,by,r*s.s*1.6,0,Math.PI*2);ctx.strokeStyle=`rgba(255,110,40,${al*.4})`;ctx.lineWidth=1;ctx.stroke();
    });
    ctx.restore();
    ctx.beginPath();ctx.arc(sx,sy,r,0,Math.PI*2);ctx.strokeStyle='rgba(255,130,50,0.5)';ctx.lineWidth=1.5;ctx.stroke();
  }
}

// ─── 2. ANÃ AMARELA ──────────────────────────────────────────────
// Zona Habitável: marca planetas com halo verde
class YellowDwarf extends CelestialObject{
  constructor(wx,wy){
    super(wx,wy,'yellowDwarf');
    this.radius=rand(9,16);this.mass=this.radius*9;
    this._t=rand(0,Math.PI*2);
    this._habInner=this.radius*6;this._habOuter=this.radius*11;
    this._rings=Array.from({length:3},(_,i)=>({ph:rand(0,6),spd:rand(.4,.9),i}));
    this._convAngle=rand(0,Math.PI*2);
    this.color='#ffdd44';
  }
  update(dt){
    this._t+=dt;this._convAngle+=dt*.8;
    if(window._invasionActive)return; // bloqueia interações durante invasão
    objects.forEach(o=>{
      if(o===this||o.dead)return;
      if(o.type!=='planet'&&o.type!=='moon'&&!PP_ORBIT_TYPES.includes(o.type))return;
      const d=dist(o,this);
      o._inHabZone=(d>this._habInner&&d<this._habOuter);
    });
  }
  draw(){
    const sx=this.sx(),sy=this.sy();
    const rBase=this.sr();
    const r=rBase*(1+0.07*Math.sin(this._t*2.1));
    const inner=this._habInner*cam.zoom,outer=this._habOuter*cam.zoom;
    const habG=ctx.createRadialGradient(sx,sy,inner,sx,sy,outer);
    const hp=0.06+0.03*Math.sin(this._t*.8);
    habG.addColorStop(0,`rgba(60,200,80,0)`);habG.addColorStop(.3,`rgba(60,220,80,${hp})`);habG.addColorStop(.7,`rgba(80,255,100,${hp*.7})`);habG.addColorStop(1,`rgba(60,200,80,0)`);
    ctx.beginPath();ctx.arc(sx,sy,outer,0,Math.PI*2);ctx.fillStyle=habG;ctx.fill();
    ctx.setLineDash([4,7]);
    ctx.beginPath();ctx.arc(sx,sy,inner,0,Math.PI*2);ctx.strokeStyle=`rgba(80,220,80,${0.12+0.06*Math.sin(this._t)})`;ctx.lineWidth=1.5;ctx.stroke();
    ctx.beginPath();ctx.arc(sx,sy,outer,0,Math.PI*2);ctx.strokeStyle=`rgba(80,220,80,${0.09+0.04*Math.sin(this._t+1)})`;ctx.lineWidth=1.5;ctx.stroke();
    ctx.setLineDash([]);
    this._rings.forEach(ring=>{
      const rr=r*(1.45+ring.i*.38+.1*Math.sin(this._t*ring.spd+ring.ph));
      const cg=ctx.createRadialGradient(sx,sy,r,sx,sy,rr*2.5);
      cg.addColorStop(0,`rgba(255,240,100,${0.1-ring.i*.028})`);cg.addColorStop(1,'transparent');
      ctx.beginPath();ctx.arc(sx,sy,rr*2.5,0,Math.PI*2);ctx.fillStyle=cg;ctx.fill();
    });
    const g=ctx.createRadialGradient(sx-r*.3,sy-r*.3,r*.04,sx,sy,r);
    g.addColorStop(0,'rgba(255,255,220,.99)');g.addColorStop(.35,'#ffee44');g.addColorStop(.65,'#ffaa00');g.addColorStop(1,'#664400');
    ctx.beginPath();ctx.arc(sx,sy,r,0,Math.PI*2);ctx.fillStyle=g;ctx.fill();
    ctx.save();ctx.beginPath();ctx.arc(sx,sy,r,0,Math.PI*2);ctx.clip();
    for(let i=0;i<6;i++){
      const a=i*1.047+this._convAngle;
      const bx=sx+Math.cos(a)*r*.5,by=sy+Math.sin(a)*r*.38;
      const cell=ctx.createRadialGradient(bx,by,0,bx,by,r*.22);
      cell.addColorStop(0,`rgba(255,255,160,${0.22+0.1*Math.sin(this._t*2.5+i)})`);cell.addColorStop(1,'transparent');
      ctx.beginPath();ctx.arc(bx,by,r*.22,0,Math.PI*2);ctx.fillStyle=cell;ctx.fill();
    }
    ctx.restore();
    ctx.beginPath();ctx.arc(sx,sy,r,0,Math.PI*2);ctx.strokeStyle='rgba(255,220,60,0.4)';ctx.lineWidth=1.5;ctx.stroke();
    objects.forEach(o=>{
      if(!o._inHabZone||o.dead)return;
      const {x:ox,y:oy}=worldToScreen(o.x,o.y);const or2=o.sr();
      const hg=ctx.createRadialGradient(ox,oy,or2,ox,oy,or2*2.6);
      hg.addColorStop(0,`rgba(60,220,80,${0.2+0.1*Math.sin(this._t*2)})`);hg.addColorStop(1,'transparent');
      ctx.beginPath();ctx.arc(ox,oy,or2*2.6,0,Math.PI*2);ctx.fillStyle=hg;ctx.fill();
      ctx.beginPath();ctx.arc(ox,oy,or2*1.2,0,Math.PI*2);ctx.strokeStyle=`rgba(80,255,100,${0.5+0.28*Math.sin(this._t*2)})`;ctx.lineWidth=1.5;ctx.stroke();
    });
  }
}

// ─── 3. ESTRELA AZUL ─────────────────────────────────────────────
// Vento Estelar: repele tudo continuamente
class BlueStar extends CelestialObject{
  constructor(wx,wy){
    super(wx,wy,'blueStar');
    this.radius=rand(14,24);this.mass=this.radius*12;
    this._t=rand(0,Math.PI*2);
    this._windRange=this.radius*14;
    this._wParts=[];this._wTimer=0;
    this.color='#44aaff';
  }
  update(dt){
    this._t+=dt;this._wTimer+=dt;
    if(window._invasionActive)return; // bloqueia interações durante invasão
    objects.forEach(o=>{
      if(o===this||o.dead||o.immune||o.fixed)return;
      const d=dist(o,this);if(d>this._windRange||d<1)return;
      const f=18*(1-d/this._windRange)/(d*.08+1);
      const nx=(o.x-this.x)/d,ny=(o.y-this.y)/d;
      o.vx=(o.vx||0)+nx*f*dt*60;o.vy=(o.vy||0)+ny*f*dt*60;
      if((PP_ORBIT_TYPES.includes(o.type)||o.type==='planet'||o.type==='moon')&&Math.random()<.006)o.parent=null;
      // Rastro de fogo + enrubescimento vulcânico em objetos próximos
      if(d<this._windRange*0.45){
        const heat=(1-d/(this._windRange*0.45));
        o._blueWindHeat=Math.min(1,(o._blueWindHeat||0)+dt*heat*0.55);
        // Partículas de fogo saindo do objeto
        if(Math.random()<heat*0.22*dt*60){
          this._wParts.push({
            x:o.x+rand(-o.radius,o.radius),y:o.y+rand(-o.radius,o.radius),
            vx:nx*rand(30,80)+rand(-20,20),vy:ny*rand(30,80)+rand(-20,20),
            life:rand(0.3,0.9),maxLife:0.9,hue:rand(0,40)// laranja→vermelho
          });
        }
      } else {
        if(o._blueWindHeat)o._blueWindHeat=Math.max(0,(o._blueWindHeat||0)-dt*0.12);
      }
    });
    if(this._wTimer>0.07){
      this._wTimer=0;
      const a=rand(0,Math.PI*2),spd=rand(70,160);
      this._wParts.push({x:this.x,y:this.y,vx:Math.cos(a)*spd,vy:Math.sin(a)*spd,life:rand(.8,2),maxLife:2,hue:rand(180,230)});
    }
    this._wParts=this._wParts.filter(p=>{p.life-=dt;p.x+=p.vx*dt;p.y+=p.vy*dt;return p.life>0;});
    // Decrement heat on all objects
    objects.forEach(o=>{if(o._blueWindHeat&&o._blueWindHeat>0&&dist(o,this)>=this._windRange*0.45)o._blueWindHeat=Math.max(0,(o._blueWindHeat||0)-dt*0.08);});
  }
  draw(){
    const sx=this.sx(),sy=this.sy();
    const rBase=this.sr();
    const r=rBase*(1+0.08*Math.sin(this._t*3.1));
    // Partículas de vento e fogo
    this._wParts.forEach(p=>{
      const {x:px,y:py}=worldToScreen(p.x,p.y);const lf=p.life/p.maxLife;
      ctx.beginPath();ctx.arc(px,py,2.2*cam.zoom*lf,0,Math.PI*2);
      ctx.fillStyle=`hsla(${p.hue},95%,${~~(60+30*lf)}%,${lf*.6})`;ctx.fill();
    });
    // Overlay vulcânico em objetos aquecidos
    objects.forEach(o=>{
      if(!o._blueWindHeat||o._blueWindHeat<=0||o.dead)return;
      const{x:ox,y:oy}=worldToScreen(o.x,o.y);const or2=o.sr();const h=o._blueWindHeat;
      // Tinge de vermelho/laranja vulcânico proporcional ao calor
      const vg=ctx.createRadialGradient(ox,oy,0,ox,oy,or2);
      vg.addColorStop(0,`rgba(255,${~~(60-h*50)},0,${h*0.75})`);
      vg.addColorStop(0.6,`rgba(200,${~~(30-h*20)},0,${h*0.4})`);
      vg.addColorStop(1,'transparent');
      ctx.beginPath();ctx.arc(ox,oy,or2,0,Math.PI*2);ctx.fillStyle=vg;ctx.fill();
      // Cratera/fissura vulcânica quando muito quente
      if(h>0.6){
        ctx.beginPath();ctx.arc(ox,oy,or2*(1.1+0.1*Math.sin(this._t*8)),0,Math.PI*2);
        ctx.strokeStyle=`rgba(255,80,0,${(h-0.6)*1.5*0.6})`;ctx.lineWidth=2;ctx.stroke();
      }
    });
    for(let i=0;i<6;i++){
      const a=this._t*.22+i*(Math.PI/3);
      const len=r*(2.6+.7*Math.sin(this._t*1.5+i*1.1));
      const jg=ctx.createLinearGradient(sx,sy,sx+Math.cos(a)*len,sy+Math.sin(a)*len);
      jg.addColorStop(0,`rgba(120,200,255,${0.13+0.06*Math.sin(this._t+i)})`);jg.addColorStop(1,'transparent');
      ctx.beginPath();ctx.moveTo(sx,sy);ctx.lineTo(sx+Math.cos(a)*len,sy+Math.sin(a)*len);
      ctx.strokeStyle=jg;ctx.lineWidth=r*.32;ctx.stroke();
    }
    for(let i=3;i>=0;i--){
      const gg=ctx.createRadialGradient(sx,sy,r,sx,sy,r*(1.6+i*.65));
      gg.addColorStop(0,`rgba(60,140,255,${0.13/(i+1)})`);gg.addColorStop(1,'transparent');
      ctx.beginPath();ctx.arc(sx,sy,r*(1.6+i*.65),0,Math.PI*2);ctx.fillStyle=gg;ctx.fill();
    }
    ctx.beginPath();ctx.arc(sx,sy,r*1.1,0,Math.PI*2);
    ctx.strokeStyle=`rgba(180,220,255,${0.32+0.14*Math.sin(this._t*2)})`;ctx.lineWidth=2;ctx.stroke();
    const g=ctx.createRadialGradient(sx-r*.3,sy-r*.3,r*.05,sx,sy,r);
    g.addColorStop(0,'rgba(240,248,255,1)');g.addColorStop(.25,'#88ccff');g.addColorStop(.55,'#2266ee');g.addColorStop(.88,'#001133');g.addColorStop(1,'#000a1a');
    ctx.beginPath();ctx.arc(sx,sy,r,0,Math.PI*2);ctx.fillStyle=g;ctx.fill();
    ctx.save();ctx.beginPath();ctx.arc(sx,sy,r,0,Math.PI*2);ctx.clip();
    const sh=ctx.createRadialGradient(sx-r*.4,sy-r*.4,0,sx-r*.4,sy-r*.4,r*.55);
    sh.addColorStop(0,'rgba(255,255,255,0.32)');sh.addColorStop(1,'transparent');
    ctx.beginPath();ctx.arc(sx-r*.4,sy-r*.4,r*.55,0,Math.PI*2);ctx.fillStyle=sh;ctx.fill();
    ctx.restore();
  }
}

// ─── 4. GIGANTE VERMELHA ─────────────────────────────────────────
// Expansão Terminal: cresce até engolir objetos, solta pulsos de calor
class RedGiant extends CelestialObject{
  constructor(wx,wy){
    super(wx,wy,'redGiant');
    this.radius=rand(28,48);this.mass=this.radius*6;
    this._t=rand(0,Math.PI*2);
    this._baseR=this.radius;this._growTimer=0;this._growMax=rand(6,14);
    this._pulseTimer=0;this._pulseMax=rand(2.5,5);this._pulseRings=[];
    this._cells=Array.from({length:8},()=>({a:rand(0,Math.PI*2),d:rand(.32,.72),s:rand(.18,.3),spd:rand(.008,.035),ph:rand(0,6)}));
    this.color='#ff6633';
  }
  update(dt){
    this._t+=dt;this._growTimer+=dt;this._pulseTimer+=dt;
    this._cells.forEach(c=>c.a+=c.spd*dt);
    this._pulseRings=this._pulseRings.filter(r2=>{r2.r+=dt*90;r2.alpha=Math.max(0,r2.alpha-dt*.45);return r2.alpha>0;});
    // Crescimento gradual
    if(this._growTimer>=this._growMax&&this.radius<this._baseR*2.1){
      this._growTimer=0;this.radius=Math.min(this._baseR*2.1,this.radius+0.7);this.mass=this.radius*6;
    }
    // Pulsos periódicos de calor
    if(this._pulseTimer>=this._pulseMax){
      this._pulseTimer=0;this._pulseRings.push({r:this.radius*1.05,alpha:1});
      const pulseRange=this.radius*9;
    if(window._invasionActive)return; // bloqueia interações durante invasão
      objects.forEach(o=>{
        if(o===this||o.dead||o.immune)return;
        const d=dist(o,this);if(d>pulseRange||d<1)return;
        const heat=(1-d/pulseRange);
        o._rgHeat=Math.min(1,(o._rgHeat||0)+heat*0.45);
        o._heatFlash=1.2;
      });
    }
    // Decrement calor nos objetos
    objects.forEach(o=>{if(o._rgHeat&&o._rgHeat>0)o._rgHeat=Math.max(0,(o._rgHeat||0)-dt*0.06);});
    // Absorção por engolimento
    objects.forEach(o=>{
      if(o===this||o.dead||o.immune)return;
      if(dist(o,this)<this.radius+o.radius&&o.type!=='blackhole'&&o.type!=='whitehole'&&o.type!=='wormhole'){
        o.dead=true;
        for(let i=0;i<10;i++)particles.push({x:o.x,y:o.y,vx:rand(-4,4),vy:rand(-4,4),r:rand(2,5),alpha:1,color:'#ff9944'});
      }
    });
  }
  draw(){
    const sx=this.sx(),sy=this.sy();
    const rBase=this.sr();
    const r=rBase*(1+0.09*Math.sin(this._t*1.8));
    const pct=Math.min(1,(this.radius-this._baseR)/(this._baseR*1.1));
    // Anéis de pulso de calor
    this._pulseRings.forEach(ring=>{
      ctx.beginPath();ctx.arc(sx,sy,ring.r*cam.zoom,0,Math.PI*2);
      ctx.strokeStyle=`rgba(255,${~~(120-pct*80)},30,${ring.alpha*0.8})`;ctx.lineWidth=3;ctx.stroke();
      const rg=ctx.createRadialGradient(sx,sy,ring.r*cam.zoom*.85,sx,sy,ring.r*cam.zoom*1.2);
      rg.addColorStop(0,`rgba(255,80,10,${ring.alpha*0.12})`);rg.addColorStop(1,'transparent');
      ctx.beginPath();ctx.arc(sx,sy,ring.r*cam.zoom*1.2,0,Math.PI*2);ctx.fillStyle=rg;ctx.fill();
    });
    // Overlay de calor nos objetos afetados
    objects.forEach(o=>{
      if(!o._rgHeat||o._rgHeat<=0||o.dead)return;
      const{x:ox,y:oy}=worldToScreen(o.x,o.y);const or2=o.sr();const h=o._rgHeat;
      const hg=ctx.createRadialGradient(ox,oy,0,ox,oy,or2*(1.4+h*.5));
      hg.addColorStop(0,`rgba(255,${~~(100-h*80)},0,${h*0.5})`);hg.addColorStop(1,'transparent');
      ctx.beginPath();ctx.arc(ox,oy,or2*(1.4+h*.5),0,Math.PI*2);ctx.fillStyle=hg;ctx.fill();
    });
    for(let i=3;i>=0;i--){
      const ag=ctx.createRadialGradient(sx,sy,r*.8,sx,sy,r*(1.5+i*.5));
      ag.addColorStop(0,`rgba(255,${~~(80-pct*60)},${~~(20-pct*15)},${(0.13+pct*.08)/(i+1)})`);ag.addColorStop(1,'transparent');
      ctx.beginPath();ctx.arc(sx,sy,r*(1.5+i*.5),0,Math.PI*2);ctx.fillStyle=ag;ctx.fill();
    }
    const g=ctx.createRadialGradient(sx-r*.28,sy-r*.28,r*.05,sx,sy,r);
    g.addColorStop(0,`rgba(255,${~~(210-pct*80)},${~~(120-pct*100)},.96)`);
    g.addColorStop(.35,'#ff6633');g.addColorStop(.7,'#cc1100');g.addColorStop(1,'#220000');
    ctx.beginPath();ctx.arc(sx,sy,r,0,Math.PI*2);ctx.fillStyle=g;ctx.fill();
    ctx.save();ctx.beginPath();ctx.arc(sx,sy,r,0,Math.PI*2);ctx.clip();
    this._cells.forEach(c=>{
      const bx=sx+Math.cos(c.a)*r*c.d,by=sy+Math.sin(c.a)*r*c.d;
      const hot=ctx.createRadialGradient(bx,by,0,bx,by,r*c.s);
      hot.addColorStop(0,`rgba(255,${~~(180-pct*80)},60,${0.28+0.12*Math.sin(this._t*2+c.ph)})`);hot.addColorStop(1,'transparent');
      ctx.beginPath();ctx.arc(bx,by,r*c.s,0,Math.PI*2);ctx.fillStyle=hot;ctx.fill();
    });
    ctx.restore();
    ctx.beginPath();ctx.arc(sx,sy,r,0,Math.PI*2);ctx.strokeStyle=`rgba(255,100,30,${0.3+pct*.4})`;ctx.lineWidth=2;ctx.stroke();
    if(pct>.05&&sandboxMode){
      ctx.font=`bold ${Math.max(7,r*.16)}px 'Courier New'`;ctx.fillStyle=`rgba(255,160,60,${0.6+pct*.3})`;
      ctx.textAlign='center';ctx.fillText(`▲${(pct*100).toFixed(0)}%`,sx,sy-r*.65);ctx.textAlign='left';
    }
  }
}

// ─── 5. SUPERGIGANTE ─────────────────────────────────────────────
// Instabilidade Pulsante: ondas de choque massivas periódicas que evaporam objetos
class Supergiant extends CelestialObject{
  constructor(wx,wy){
    super(wx,wy,'supergiant');
    this.radius=rand(38,65);this.mass=this.radius*10;
    this._t=rand(0,Math.PI*2);
    this._baseR=this.radius;this._pulsePhase=0;
    this._shockTimer=0;this._shockMax=rand(4,8);
    this._shockRings=[];
    this._hue=randInt(20,50);
    this.color=`hsl(${this._hue},90%,60%)`;
  }
  update(dt){
    this._t+=dt;this._pulsePhase+=dt*.5;this._shockTimer+=dt;
    this.radius=this._baseR*(1+Math.sin(this._pulsePhase)*.14);this.mass=this.radius*10;
    if(this._shockTimer>=this._shockMax){
      this._shockTimer=0;this._shockRings.push({r:this.radius*1.1,alpha:1});
    if(window._invasionActive)return; // bloqueia interações durante invasão
      objects.forEach(o=>{
        if(o===this||o.dead||o.immune||o.fixed)return;
        const d=dist(o,this);const range=this.radius*11;if(d>range||d<1)return;
        const f=65*(1-d/range),nx=(o.x-this.x)/d,ny=(o.y-this.y)/d;
        o.vx=(o.vx||0)+nx*f;o.vy=(o.vy||0)+ny*f;
        if(PP_ORBIT_TYPES.includes(o.type)||o.type==='planet'||o.type==='moon')o.parent=null;
        // Evaporação: objetos na zona de impacto imediata são destruídos
        if(d<this.radius*3.5&&o.type!=='blackhole'&&o.type!=='whitehole'&&o.type!=='wormhole'&&o.type!=='hypergiant'&&o.type!=='quasiStar'){
          o.dead=true;
          for(let i=0;i<16;i++)particles.push({x:o.x,y:o.y,vx:rand(-8,8),vy:rand(-8,8),r:rand(2,6),alpha:1,color:`hsl(${this._hue},90%,75%)`});
        }
      });
    }
    this._shockRings=this._shockRings.filter(ring=>{ring.r+=dt*120;ring.alpha=Math.max(0,ring.alpha-dt*.55);return ring.alpha>0;});
  }
  draw(){
    const sx=this.sx(),sy=this.sy(),r=this.sr();
    const hue=this._hue;
    this._shockRings.forEach(ring=>{
      ctx.beginPath();ctx.arc(sx,sy,ring.r*cam.zoom,0,Math.PI*2);
      ctx.strokeStyle=`hsla(${hue+20},95%,75%,${ring.alpha})`;ctx.lineWidth=3;ctx.stroke();
      // Zona interna de evaporação visível
      ctx.beginPath();ctx.arc(sx,sy,this.radius*3.5*cam.zoom,0,Math.PI*2);
      ctx.strokeStyle=`hsla(${hue},100%,90%,${ring.alpha*0.25})`;ctx.lineWidth=2;ctx.setLineDash([6,4]);ctx.stroke();ctx.setLineDash([]);
      const rg=ctx.createRadialGradient(sx,sy,ring.r*cam.zoom*.85,sx,sy,ring.r*cam.zoom*1.15);
      rg.addColorStop(0,`hsla(${hue},90%,70%,${ring.alpha*.2})`);rg.addColorStop(1,'transparent');
      ctx.beginPath();ctx.arc(sx,sy,ring.r*cam.zoom*1.15,0,Math.PI*2);ctx.fillStyle=rg;ctx.fill();
    });
    for(let i=3;i>=0;i--){
      const gg=ctx.createRadialGradient(sx,sy,r*.9,sx,sy,r*(2+i*.6));
      gg.addColorStop(0,`hsla(${hue},90%,65%,${0.14/(i+1)})`);gg.addColorStop(1,'transparent');
      ctx.beginPath();ctx.arc(sx,sy,r*(2+i*.6),0,Math.PI*2);ctx.fillStyle=gg;ctx.fill();
    }
    const g=ctx.createRadialGradient(sx-r*.25,sy-r*.25,r*.06,sx,sy,r);
    g.addColorStop(0,'rgba(255,255,210,.97)');g.addColorStop(.28,`hsl(${hue},95%,68%)`);g.addColorStop(.6,`hsl(${hue+15},85%,38%)`);g.addColorStop(.88,`hsl(${hue+25},70%,14%)`);g.addColorStop(1,'#0a0000');
    ctx.beginPath();ctx.arc(sx,sy,r,0,Math.PI*2);ctx.fillStyle=g;ctx.fill();
    ctx.save();ctx.beginPath();ctx.arc(sx,sy,r,0,Math.PI*2);ctx.clip();
    for(let i=0;i<10;i++){
      const a=i*.628+this._t*.022;const bx=sx+Math.cos(a)*r*.55,by=sy+Math.sin(a)*r*.5;
      const gr=ctx.createRadialGradient(bx,by,0,bx,by,r*.2);
      gr.addColorStop(0,`hsla(${hue-10},90%,75%,${0.25+0.12*Math.sin(this._t*2+i)})`);gr.addColorStop(1,'transparent');
      ctx.beginPath();ctx.arc(bx,by,r*.2,0,Math.PI*2);ctx.fillStyle=gr;ctx.fill();
    }
    ctx.restore();
    ctx.beginPath();ctx.arc(sx,sy,r,0,Math.PI*2);ctx.strokeStyle=`hsla(${hue},85%,70%,0.4)`;ctx.lineWidth=2;ctx.stroke();
  }
}

// ─── 6. ANÃ BRANCA ───────────────────────────────────────────────
// Acreção Explosiva: drena estrelas vizinhas, dispara mini-nova, cresce e transforma
class WhiteDwarf extends CelestialObject{
  constructor(wx,wy){
    super(wx,wy,'whiteDwarf');
    this.radius=rand(4,8);this.mass=this.radius*20;
    this._t=rand(0,Math.PI*2);
    this._accreted=0;this._accrMax=rand(6,10);
    this._totalAccreted=0;// acúmulo total para transformação
    this._novaFlash=0;this._novaRings=[];
    this._diskAngle=0;this._dParts=[];
    this.color='#eeeeff';
  }
  update(dt){
    this._t+=dt;this._diskAngle+=dt*1.6;
    if(this._novaFlash>0)this._novaFlash-=dt;
    this._novaRings=this._novaRings.filter(r2=>{r2.r+=dt*100;r2.alpha=Math.max(0,r2.alpha-dt*.6);return r2.alpha>0;});
    this._dParts=this._dParts.filter(p=>{p.life-=dt;p.x+=p.vx*dt;p.y+=p.vy*dt;return p.life>0;});
    if(window._invasionActive)return; // bloqueia interações durante invasão
    objects.forEach(o=>{
      if(o===this||o.dead)return;
      if(o.type!=='star'&&!SP_TYPES.includes(o.type))return;
      const d=dist(o,this);if(d>this.radius*14||d<1)return;
      const drain=dt*.55;
      this._accreted+=drain;this._totalAccreted+=drain;
      // Cresce com a drenagem
      this.radius=Math.min(80,this.radius+drain*0.08);
      this.mass=this.radius*20;
      const nx=(this.x-o.x)/d,ny=(this.y-o.y)/d;
      o.vx=(o.vx||0)+nx*.9*dt;o.vy=(o.vy||0)+ny*.9*dt;
      // Encolhe a estrela drenada
      if(o.radius>2)o.radius=Math.max(2,o.radius-drain*0.04);
      if(Math.random()<.06)this._dParts.push({x:o.x,y:o.y,vx:nx*rand(20,60),vy:ny*rand(20,60),life:.7,maxLife:.7,hue:randInt(180,240)});
    });
    // Mini-nova periódica
    if(this._accreted>=this._accrMax){
      this._accreted=0;this._novaFlash=1.5;this._novaRings.push({r:this.radius*1.2,alpha:1});
      objects.forEach(o=>{
        if(o===this||o.dead||o.immune)return;
        const d=dist(o,this);if(d>this.radius*22||d<1)return;
        const f=120*(1-d/(this.radius*22)),nx=(o.x-this.x)/d,ny=(o.y-this.y)/d;
        o.vx=(o.vx||0)+nx*f;o.vy=(o.vy||0)+ny*f;
      });
    }
    // Transformação ao atingir tamanhos críticos
    if(!this.dead){
      let evolve=null;
      if(this.radius>=28&&this.radius<45)evolve='yellowDwarf';
      else if(this.radius>=45&&this.radius<65)evolve='redGiant';
      else if(this.radius>=65)evolve='supergiant';
      if(evolve){
        this.dead=true;
        const _evClasses={yellowDwarf:YellowDwarf,redGiant:RedGiant,supergiant:Supergiant};
        const Cls=_evClasses[evolve];
        if(Cls){
          const neo=new Cls(this.x,this.y);
          neo.radius=this.radius;neo.mass=neo.radius*10;
          pendingObjects.push(neo);
          for(let i=0;i<24;i++)particles.push({x:this.x,y:this.y,vx:rand(-12,12),vy:rand(-12,12),r:rand(3,8),alpha:1,color:'#ffffff'});
        }
      }
    }
  }
  draw(){
    const sx=this.sx(),sy=this.sy();
    const rBase=this.sr();
    const r=rBase*(1+0.08*Math.sin(this._t*4.5));
    const pct=Math.min(1,this._accreted/this._accrMax);
    // Indicador de fase de transformação
    const evolPct=Math.min(1,this.radius/65);
    this._dParts.forEach(p=>{
      const {x:px,y:py}=worldToScreen(p.x,p.y);const lf=p.life/p.maxLife;
      ctx.beginPath();ctx.arc(px,py,1.8*cam.zoom,0,Math.PI*2);ctx.fillStyle=`hsla(${p.hue},90%,80%,${lf*.7})`;ctx.fill();
    });
    this._novaRings.forEach(ring=>{
      ctx.beginPath();ctx.arc(sx,sy,ring.r*cam.zoom,0,Math.PI*2);ctx.strokeStyle=`rgba(200,220,255,${ring.alpha})`;ctx.lineWidth=3;ctx.stroke();
    });
    if(this._novaFlash>0){
      const nf=ctx.createRadialGradient(sx,sy,r,sx,sy,r*8);
      nf.addColorStop(0,`rgba(255,255,240,${this._novaFlash*.7})`);nf.addColorStop(1,'transparent');
      ctx.beginPath();ctx.arc(sx,sy,r*8,0,Math.PI*2);ctx.fillStyle=nf;ctx.fill();
    }
    if(pct>0.05){
      ctx.save();ctx.translate(sx,sy);ctx.rotate(this._diskAngle);ctx.scale(1,.28);
      for(let i=0;i<3;i++){
        ctx.beginPath();ctx.arc(0,0,r*(1.9+i*.75),0,Math.PI*2);
        ctx.strokeStyle=`rgba(${~~(180-i*30)},${~~(200-i*20)},255,${pct*.35-i*.08})`;ctx.lineWidth=(3-i)*1.5;ctx.stroke();
      }
      ctx.restore();
    }
    // Aura de evolução (cresce com o raio)
    if(evolPct>0.2){
      const evC=evolPct<0.5?`rgba(255,240,180,${evolPct*.3})`:evolPct<0.8?`rgba(255,160,60,${evolPct*.35})`:`rgba(255,80,20,${evolPct*.4})`;
      const evG=ctx.createRadialGradient(sx,sy,r,sx,sy,r*4.5);
      evG.addColorStop(0,evC);evG.addColorStop(1,'transparent');
      ctx.beginPath();ctx.arc(sx,sy,r*4.5,0,Math.PI*2);ctx.fillStyle=evG;ctx.fill();
    }
    const glow=ctx.createRadialGradient(sx,sy,r*.3,sx,sy,r*5);
    glow.addColorStop(0,'rgba(200,220,255,.4)');glow.addColorStop(1,'transparent');
    ctx.beginPath();ctx.arc(sx,sy,r*5,0,Math.PI*2);ctx.fillStyle=glow;ctx.fill();
    const g=ctx.createRadialGradient(sx-r*.3,sy-r*.3,0,sx,sy,r);
    g.addColorStop(0,'#ffffff');g.addColorStop(.4,'#ddeeff');g.addColorStop(.75,'#7799cc');g.addColorStop(1,'#112244');
    ctx.beginPath();ctx.arc(sx,sy,r,0,Math.PI*2);ctx.fillStyle=g;ctx.fill();
    ctx.beginPath();ctx.arc(sx,sy,r,0,Math.PI*2);ctx.strokeStyle=`rgba(180,210,255,${0.6+pct*.3})`;ctx.lineWidth=2;ctx.stroke();
    if(sandboxMode&&this.radius>10){
      ctx.font=`bold ${Math.max(5,r*.28)}px 'Courier New'`;ctx.textAlign='center';
      const nextLabel=this.radius<28?`→ ${(((28-this.radius)/28)*100).toFixed(0)}% p/ Anã Amarela`:this.radius<45?`→ ${(((45-this.radius)/17)*100).toFixed(0)}% p/ Gigante`:this.radius<65?`→ ${(((65-this.radius)/20)*100).toFixed(0)}% p/ Supergigante`:'';
      if(nextLabel){ctx.fillStyle='rgba(180,210,255,0.65)';ctx.fillText(nextLabel,sx,sy-r*1.3);}
      ctx.textAlign='left';
    }
  }
}

// ─── 7. HIPERGIGANTE ─────────────────────────────────────────────
// Campo Gravitacional Colossal: atrai tudo com força brutal
class Hypergiant extends CelestialObject{
  constructor(wx,wy){
    super(wx,wy,'hypergiant');
    this.radius=rand(55,90);this.mass=this.radius*18;
    this._t=rand(0,Math.PI*2);
    this._pullRange=this.radius*10;
    this._streamers=Array.from({length:8},(_,i)=>({a:i*(Math.PI/4)+rand(-.2,.2),spd:rand(.005,.02),stretch:rand(.8,1.4),ph:rand(0,6)}));
    this.color='#ffaa22';
    this._rayTimer=0;this._rayMax=rand(5,9);
    this._activeRays=[];
    this._heatMap=new Map();
  }
  update(dt){
    this._t+=dt;this._streamers.forEach(s=>s.a+=s.spd*dt);
    this._rayTimer+=dt;
    if(window._invasionActive)return; // bloqueia interações durante invasão
    objects.forEach(o=>{
      if(o===this||o.dead||o.immune||o.fixed)return;
      const d=dist(o,this);if(d>this._pullRange||d<1)return;
      const f=5500/(d*d+50),nx=(this.x-o.x)/d,ny=(this.y-o.y)/d;
      o.vx=(o.vx||0)+nx*f*dt;o.vy=(o.vy||0)+ny*f*dt;
    });
    if(this._rayTimer>=this._rayMax){
      this._rayTimer=0;
      const numRays=randInt(2,4);
      for(let r=0;r<numRays;r++)this._activeRays.push({angle:rand(0,Math.PI*2),alpha:1,len:this._pullRange*1.1});
      objects.forEach(o=>{
        if(o===this||o.dead||o.immune)return;
        const d=dist(o,this);if(d>this._pullRange*1.1||d<1)return;
        const ang=Math.atan2(o.y-this.y,o.x-this.x);
        const hit=this._activeRays.some(ray=>Math.abs(((ang-ray.angle+Math.PI*3)%(Math.PI*2))-Math.PI)<0.35);
        if(hit){
          o._heatFlash=2.5;
          const id=objects.indexOf(o);
          const heat=(this._heatMap.get(id)||0)+1;
          this._heatMap.set(id,heat);
          if(heat>=3&&o.type!=='blackhole'&&o.type!=='whitehole'&&o.type!=='wormhole'&&o.type!=='hypergiant'){
            this._heatMap.delete(id);
            o.dead=true;
            for(let i=0;i<20;i++)particles.push({x:o.x,y:o.y,vx:rand(-8,8),vy:rand(-8,8),r:rand(3,7),alpha:1,color:'#ffdd44'});
          }
        }
      });
    }
    this._activeRays=this._activeRays.filter(ray=>{ray.alpha=Math.max(0,ray.alpha-dt*1.8);return ray.alpha>0;});
  }
  draw(){
    const sx=this.sx(),sy=this.sy();
    const r=this.sr()*(1+0.07*Math.sin(this._t*1.4));
    // Raios colossais ativos
    this._activeRays.forEach(ray=>{
      const rLen=ray.len*cam.zoom;
      for(let w=-1;w<=1;w++){
        const a=ray.angle+w*0.12;
        const rg=ctx.createLinearGradient(sx,sy,sx+Math.cos(a)*rLen,sy+Math.sin(a)*rLen);
        rg.addColorStop(0,`rgba(255,255,180,${ray.alpha*(1-Math.abs(w)*.5)})`);
        rg.addColorStop(0.3,`rgba(255,200,40,${ray.alpha*.7*(1-Math.abs(w)*.5)})`);
        rg.addColorStop(1,'transparent');
        ctx.beginPath();ctx.moveTo(sx,sy);ctx.lineTo(sx+Math.cos(a)*rLen,sy+Math.sin(a)*rLen);
        ctx.strokeStyle=rg;ctx.lineWidth=(w===0?r*.28:r*.12);ctx.stroke();
      }
      const cg=ctx.createRadialGradient(sx,sy,0,sx,sy,r*1.6);
      cg.addColorStop(0,`rgba(255,255,220,${ray.alpha*.6})`);cg.addColorStop(1,'transparent');
      ctx.beginPath();ctx.arc(sx,sy,r*1.6,0,Math.PI*2);ctx.fillStyle=cg;ctx.fill();
    });
    // Linhas de campo gravitacional
    const pullR=this._pullRange*cam.zoom;
    for(let i=0;i<10;i++){
      const a=(i/10)*Math.PI*2+this._t*.008;
      for(let j=1;j<5;j++){
        const dr=pullR*(0.3+j*.16);
        ctx.beginPath();ctx.arc(sx+Math.cos(a)*dr,sy+Math.sin(a)*dr,2*cam.zoom,0,Math.PI*2);
        ctx.fillStyle=`rgba(255,180,40,${0.12-j*.022})`;ctx.fill();
      }
    }
    // Streamers de plasma
    this._streamers.forEach(s=>{
      const len=r*(3.5+s.stretch*1.2+.6*Math.sin(this._t+s.ph));
      const jg=ctx.createLinearGradient(sx,sy,sx+Math.cos(s.a)*len,sy+Math.sin(s.a)*len);
      jg.addColorStop(0,`rgba(255,200,60,${0.14+0.06*Math.sin(this._t*1.2+s.ph)})`);jg.addColorStop(.6,'rgba(255,120,20,.05)');jg.addColorStop(1,'transparent');
      ctx.beginPath();ctx.moveTo(sx,sy);ctx.lineTo(sx+Math.cos(s.a)*len,sy+Math.sin(s.a)*len);
      ctx.strokeStyle=jg;ctx.lineWidth=r*.4;ctx.stroke();
    });
    for(let i=5;i>=0;i--){
      const gg=ctx.createRadialGradient(sx,sy,r,sx,sy,r*(1.6+i*.45));
      gg.addColorStop(0,`rgba(255,180,40,${0.16/(i+1)})`);gg.addColorStop(1,'transparent');
      ctx.beginPath();ctx.arc(sx,sy,r*(1.6+i*.45),0,Math.PI*2);ctx.fillStyle=gg;ctx.fill();
    }
    const g=ctx.createRadialGradient(sx-r*.22,sy-r*.22,r*.05,sx,sy,r);
    g.addColorStop(0,'rgba(255,255,230,.99)');g.addColorStop(.22,'#ffee88');g.addColorStop(.48,'#ffaa00');g.addColorStop(.75,'#cc5500');g.addColorStop(1,'#1a0000');
    ctx.beginPath();ctx.arc(sx,sy,r,0,Math.PI*2);ctx.fillStyle=g;ctx.fill();
    ctx.save();ctx.beginPath();ctx.arc(sx,sy,r,0,Math.PI*2);ctx.clip();
    for(let i=0;i<14;i++){
      const a=i*.449+this._t*.014;const bx=sx+Math.cos(a)*r*.56,by=sy+Math.sin(a)*r*.52;
      ctx.fillStyle=`rgba(220,80,0,${0.14+0.08*Math.sin(this._t+i)})`;ctx.beginPath();ctx.arc(bx,by,r*.14,0,Math.PI*2);ctx.fill();
    }
    ctx.restore();
    ctx.beginPath();ctx.arc(sx,sy,r,0,Math.PI*2);ctx.strokeStyle='rgba(255,200,60,0.35)';ctx.lineWidth=3;ctx.stroke();
  }
}

// ─── 8. VAMPIRA ESTELAR ──────────────────────────────────────────
// Drenagem de Massa: suga e encolhe estrelas companheiras
class VampireStar extends CelestialObject{
  constructor(wx,wy){
    super(wx,wy,'vampireStar');
    this.radius=rand(8,15);this.mass=this.radius*7;
    this._t=rand(0,Math.PI*2);
    this._drainRange=this.radius*12;
    this._beams=[];this._bParts=[];
    this._veinAngle=rand(0,Math.PI*2);
    this.color='#cc2244';
  }
  update(dt){
    this._t+=dt;this._veinAngle+=dt*.06;
    this._beams=[];
    this._bParts=this._bParts.filter(p=>{p.life-=dt;p.x+=p.vx*dt;p.y+=p.vy*dt;p.vx*=.94;p.vy*=.94;return p.life>0;});
    if(window._invasionActive)return; // bloqueia drenagem durante invasão
    objects.forEach(o=>{
      if(o===this||o.dead)return;
      if(o.type!=='star'&&!SP_TYPES.includes(o.type))return;
      const d=dist(o,this);if(d>this._drainRange||d<1)return;
      const drain=dt*.14;
      if(o.radius>4){o.radius=Math.max(4,o.radius-drain);o.mass=o.radius*(o.mass/Math.max(1,o.radius+drain));}
      this.radius=Math.min(45,this.radius+drain*.55);this.mass=this.radius*7;
      this._beams.push({x:o.x,y:o.y,alpha:0.3+0.2*Math.sin(this._t*4)});
      if(Math.random()<.12){
        const dx=(this.x-o.x)/d,dy=(this.y-o.y)/d;
        this._bParts.push({x:o.x+dx*rand(5,15),y:o.y+dy*rand(5,15),vx:dx*rand(20,50)+rand(-8,8),vy:dy*rand(20,50)+rand(-8,8),life:rand(.5,1.2),maxLife:1.2});
      }
    });
  }
  draw(){
    const sx=this.sx(),sy=this.sy();
    const r=this.sr()*(1+0.10*Math.abs(Math.sin(this._t*2.5)));
    // Partículas de sangue
    this._bParts.forEach(p=>{
      const {x:px,y:py}=worldToScreen(p.x,p.y);const lf=p.life/p.maxLife;
      ctx.beginPath();ctx.arc(px,py,2.5*cam.zoom,0,Math.PI*2);ctx.fillStyle=`rgba(200,20,50,${lf*.75})`;ctx.fill();
    });
    // Feixes de drenagem
    this._beams.forEach(b=>{
      const {x:bx,y:by}=worldToScreen(b.x,b.y);
      ctx.beginPath();ctx.moveTo(bx,by);ctx.lineTo(sx,sy);
      ctx.strokeStyle=`rgba(200,20,50,${b.alpha})`;ctx.lineWidth=2.5*cam.zoom;ctx.setLineDash([6,5]);ctx.stroke();ctx.setLineDash([]);
      ctx.beginPath();ctx.moveTo(bx,by);ctx.lineTo(sx,sy);
      ctx.strokeStyle=`rgba(255,100,140,${b.alpha*.5})`;ctx.lineWidth=1*cam.zoom;ctx.stroke();
    });
    // Aura vampírica (cor fixa válida)
    const auraAlpha=0.22+0.08*Math.sin(this._t);
    const aura=ctx.createRadialGradient(sx,sy,r*.5,sx,sy,r*4.5);
    aura.addColorStop(0,`rgba(180,0,50,${auraAlpha})`);aura.addColorStop(.5,'rgba(100,0,30,.08)');aura.addColorStop(1,'transparent');
    ctx.beginPath();ctx.arc(sx,sy,r*4.5,0,Math.PI*2);ctx.fillStyle=aura;ctx.fill();
    // Corpo
    const g=ctx.createRadialGradient(sx-r*.32,sy-r*.32,r*.06,sx,sy,r);
    g.addColorStop(0,'rgba(255,160,190,.92)');g.addColorStop(.35,'#cc2244');g.addColorStop(.68,'#660011');g.addColorStop(1,'#100005');
    ctx.beginPath();ctx.arc(sx,sy,r,0,Math.PI*2);ctx.fillStyle=g;ctx.fill();
    // Veias pulsantes na superfície
    ctx.save();ctx.beginPath();ctx.arc(sx,sy,r,0,Math.PI*2);ctx.clip();
    for(let i=0;i<5;i++){
      const a=this._veinAngle+i*(Math.PI*2/5);
      ctx.beginPath();ctx.moveTo(sx,sy);ctx.lineTo(sx+Math.cos(a)*r*.9,sy+Math.sin(a)*r*.9);
      ctx.strokeStyle=`rgba(255,60,100,${0.35+0.22*Math.sin(this._t*3+i)})`;ctx.lineWidth=r*.08;ctx.stroke();
    }
    ctx.restore();
    ctx.beginPath();ctx.arc(sx,sy,r,0,Math.PI*2);ctx.strokeStyle=`rgba(220,40,80,${0.45+0.2*Math.sin(this._t*2)})`;ctx.lineWidth=2;ctx.stroke();
  }
}

// ─── 9. ESTRELA DE QUARKS ────────────────────────────────────────
// Emissão de Quarks: rajadas que dão impulso randômico
class QuarkStar extends CelestialObject{
  constructor(wx,wy){
    super(wx,wy,'quarkStar');
    this.radius=rand(4,8);this.mass=this.radius*18;
    this._t=rand(0,Math.PI*2);
    this._emitTimer=0;this._emitMax=rand(3,6);
    this._quarks=[];
    this._surface=Array.from({length:8},()=>({a:rand(0,Math.PI*2),spd:rand(.8,2.5),r:rand(.6,.95),ph:rand(0,6)}));
    this.color='#aa44ff';
  }
  update(dt){
    this._t+=dt;this._emitTimer+=dt;
    this._surface.forEach(s=>s.a+=s.spd*dt);
    this._quarks=this._quarks.filter(q=>{q.life-=dt;q.x+=q.vx*dt;q.y+=q.vy*dt;return q.life>0;});
    if(!window._invasionActive&&this._emitTimer>=this._emitMax){
      this._emitTimer=0;
      for(let i=0;i<16;i++){
        const a=rand(0,Math.PI*2),spd=rand(100,280);
        this._quarks.push({x:this.x,y:this.y,vx:Math.cos(a)*spd,vy:Math.sin(a)*spd,life:rand(.6,1.8),maxLife:1.8,hue:rand(250,320),px:this.x,py:this.y});
      }
      objects.forEach(o=>{if(o===this||o.dead||o.immune)return;if(dist(o,this)>this.radius*22)return;o.vx=(o.vx||0)+rand(-10,10);o.vy=(o.vy||0)+rand(-10,10);});
    }
  }
  draw(){
    const sx=this.sx(),sy=this.sy();
    const r=this.sr()*(1+0.06*Math.sin(this._t*5.2)+0.04*Math.sin(this._t*8.7));
    // Quarks com traço (usando posição anterior salva)
    this._quarks.forEach(q=>{
      const {x:qx,y:qy}=worldToScreen(q.x,q.y);const lf=q.life/q.maxLife;
      // Traço até posição anterior
      const {x:tx,y:ty}=worldToScreen(q.x-q.vx*.06,q.y-q.vy*.06);
      ctx.beginPath();ctx.moveTo(tx,ty);ctx.lineTo(qx,qy);
      ctx.strokeStyle=`hsla(${q.hue},90%,70%,${lf*.35})`;ctx.lineWidth=1.5;ctx.stroke();
      ctx.beginPath();ctx.arc(qx,qy,2.5*cam.zoom,0,Math.PI*2);ctx.fillStyle=`hsla(${q.hue},95%,78%,${lf*.7})`;ctx.fill();
    });
    // Aura
    const aura=ctx.createRadialGradient(sx,sy,r*.4,sx,sy,r*5);
    aura.addColorStop(0,`rgba(160,60,255,${0.28+0.12*Math.sin(this._t*2)})`);aura.addColorStop(.5,'rgba(100,20,200,.07)');aura.addColorStop(1,'transparent');
    ctx.beginPath();ctx.arc(sx,sy,r*5,0,Math.PI*2);ctx.fillStyle=aura;ctx.fill();
    // Corpo
    const g=ctx.createRadialGradient(sx,sy,0,sx,sy,r);
    g.addColorStop(0,'rgba(240,200,255,1)');g.addColorStop(.4,'#aa44ff');g.addColorStop(.78,'#3a006a');g.addColorStop(1,'#080015');
    ctx.beginPath();ctx.arc(sx,sy,r,0,Math.PI*2);ctx.fillStyle=g;ctx.fill();
    // Fracturas
    ctx.save();ctx.beginPath();ctx.arc(sx,sy,r,0,Math.PI*2);ctx.clip();
    this._surface.forEach(s=>{
      const bx=sx+Math.cos(s.a)*r*s.r,by=sy+Math.sin(s.a)*r*s.r;
      ctx.beginPath();ctx.moveTo(sx,sy);ctx.lineTo(bx,by);
      ctx.strokeStyle=`rgba(200,140,255,${0.4+0.25*Math.sin(this._t*4+s.ph)})`;ctx.lineWidth=r*.1;ctx.stroke();
    });
    ctx.restore();
    ctx.beginPath();ctx.arc(sx,sy,r,0,Math.PI*2);ctx.strokeStyle=`rgba(180,80,255,${0.5+0.25*Math.sin(this._t*3)})`;ctx.lineWidth=2;ctx.stroke();
  }
}

// ─── 10. OBJETO THORNE-ŻYTKOW ────────────────────────────────────
// Núcleo Duplo: alterna entre nêutron (senoide horizontal) e gigante (órbita vai-e-volta)
class ThorneZytkow extends CelestialObject{
  constructor(wx,wy){
    super(wx,wy,'thorneZytkow');
    this.radius=rand(22,38);this.mass=this.radius*14;
    this._t=rand(0,Math.PI*2);
    this._phaseTimer=0;this._phaseMax=rand(5,9);
    this._phaseMode=0;this._switchFlash=0;this._innerT=0;
    this._sineT=0;// timer para onda senoidal no modo nêutron
    this.color='#ff8833';
  }
  update(dt){
    this._t+=dt;this._innerT+=dt*(this._phaseMode===0?3:1.5);this._phaseTimer+=dt;
    this._sineT+=dt;
    if(this._switchFlash>0)this._switchFlash-=dt;
    if(this._phaseTimer>=this._phaseMax){this._phaseTimer=0;this._phaseMode=1-this._phaseMode;this._switchFlash=0.8;}
    if(window._invasionActive)return; // bloqueia interações durante invasão
    objects.forEach(o=>{
      if(o===this||o.dead||o.immune||o.fixed)return;
      const d=dist(o,this);if(d>this.radius*11||d<1)return;
      const nx=(this.x-o.x)/d,ny=(this.y-o.y)/d;
      if(this._phaseMode===0){
        // MODO NÊUTRON: atrai + empurrão lateral senoidal (ondas horizontais)
        const f=2800/(d*d+60);
        o.vx=(o.vx||0)+nx*f*dt;o.vy=(o.vy||0)+ny*f*dt;
        // Componente senoidal perpendicular ao vetor radial
        const sineForce=Math.sin(this._sineT*2.2+d*0.04)*18*(1-d/(this.radius*11));
        const px=-ny,py=nx;// perpendicular
        o.vx=(o.vx||0)+px*sineForce*dt;o.vy=(o.vy||0)+py*sineForce*dt;
      } else {
        // MODO GIGANTE: empurra + puxa para o centro em ondas (vai-e-volta)
        const wave=Math.sin(this._sineT*1.4)*1.5+0.5;// oscila entre repulsão e atração
        const f=600/(d*d+30)*wave;
        const dir=wave>0?-1:1;// negativo=empurra, positivo=atrai
        o.vx=(o.vx||0)+nx*f*dir*dt;o.vy=(o.vy||0)+ny*f*dir*dt;
      }
    });
  }
  draw(){
    const sx=this.sx(),sy=this.sy();
    const r=this.sr()*(1+(this._phaseMode===0?0.12:0.05)*Math.sin(this._t*(this._phaseMode===0?3.5:1.6)));
    const isN=this._phaseMode===0;const mHue=isN?200:30;
    if(this._switchFlash>0){
      const fl=ctx.createRadialGradient(sx,sy,r*.6,sx,sy,r*5);
      fl.addColorStop(0,`hsla(${mHue},90%,75%,${this._switchFlash*.5})`);fl.addColorStop(1,'transparent');
      ctx.beginPath();ctx.arc(sx,sy,r*5,0,Math.PI*2);ctx.fillStyle=fl;ctx.fill();
    }
    const aura=ctx.createRadialGradient(sx,sy,r*.8,sx,sy,r*3);
    aura.addColorStop(0,`hsla(${mHue},80%,60%,0.2)`);aura.addColorStop(1,'transparent');
    ctx.beginPath();ctx.arc(sx,sy,r*3,0,Math.PI*2);ctx.fillStyle=aura;ctx.fill();
    const g=ctx.createRadialGradient(sx-r*.28,sy-r*.28,r*.08,sx,sy,r);
    if(isN){g.addColorStop(0,'rgba(210,240,255,.95)');g.addColorStop(.35,'#88bbff');g.addColorStop(.68,'#2244aa');g.addColorStop(1,'#050a1a');}
    else{g.addColorStop(0,'rgba(255,240,180,.95)');g.addColorStop(.35,'#ff8833');g.addColorStop(.68,'#aa3300');g.addColorStop(1,'#1a0500');}
    ctx.beginPath();ctx.arc(sx,sy,r,0,Math.PI*2);ctx.fillStyle=g;ctx.fill();
    // Dois núcleos internos
    const iR=r*(.2+.1*Math.abs(Math.sin(this._innerT)));
    const c1=ctx.createRadialGradient(sx-r*.12,sy,0,sx-r*.12,sy,iR*.8);
    c1.addColorStop(0,isN?'rgba(200,230,255,1)':'rgba(255,120,40,1)');c1.addColorStop(1,'transparent');
    ctx.beginPath();ctx.arc(sx-r*.12,sy,iR*.8,0,Math.PI*2);ctx.fillStyle=c1;ctx.fill();
    const c2=ctx.createRadialGradient(sx+r*.12,sy,0,sx+r*.12,sy,iR*.6);
    c2.addColorStop(0,isN?'rgba(180,210,255,.8)':'rgba(255,80,0,.8)');c2.addColorStop(1,'transparent');
    ctx.beginPath();ctx.arc(sx+r*.12,sy,iR*.6,0,Math.PI*2);ctx.fillStyle=c2;ctx.fill();
    ctx.beginPath();ctx.arc(sx,sy,r,0,Math.PI*2);ctx.strokeStyle=`hsla(${mHue},80%,65%,0.5)`;ctx.lineWidth=2.5;ctx.stroke();
    if(sandboxMode){ctx.font=`bold ${Math.max(7,r*.2)}px 'Courier New'`;ctx.fillStyle=`hsla(${mHue},80%,75%,0.7)`;ctx.textAlign='center';ctx.fillText(isN?'⬤ NÊUTRON':'◎ GIGANTE',sx,sy-r*.75);ctx.textAlign='left';}
  }
}

// ─── 11. ESTRELA DE FERRO ────────────────────────────────────────
// Colapso Lento: encolhe até virar Buraco Negro
class IronStar extends CelestialObject{
  constructor(wx,wy){
    super(wx,wy,'ironStar');
    this.radius=rand(10,18);this.mass=this.radius*12;
    this._t=rand(0,Math.PI*2);
    this._baseR=this.radius;this._collapseTimer=0;this._shakeT=0;
    this._cracks=Array.from({length:6},()=>({a:rand(0,Math.PI*2),len:rand(.4,.9),w:rand(.04,.1)}));
    this.color='#888899';
  }
  update(dt){
    this._t+=dt;this._collapseTimer+=dt;this._shakeT+=dt;
    // Colapso mais rápido e perceptível — encolhe a cada 0.8s
    if(this._collapseTimer>=0.8){
      this._collapseTimer=0;
      const shrink=this.radius*0.055;// 5.5% por tick — visível
      this.radius=Math.max(2,this.radius-shrink);
      this.mass=this.radius*12;
      // Tremor e atração de objetos próximos ao colapsar
    if(window._invasionActive)return; // bloqueia interações durante invasão
      objects.forEach(o=>{
        if(o===this||o.dead||o.immune)return;
        const d=dist(o,this);if(d>this.radius*8||d<1)return;
        const pct=1-(this.radius/this._baseR);
        const f=800*pct/(d*d+20),nx=(this.x-o.x)/d,ny=(this.y-o.y)/d;
        o.vx=(o.vx||0)+nx*f*dt;o.vy=(o.vy||0)+ny*f*dt;
      });
      // Rachaduras se expandem — atualiza ângulos
      this._cracks.forEach(c=>{c.a+=rand(-0.2,0.2);c.len=Math.min(1.2,c.len+0.04);});
    }
    if(this.radius<=2&&!this.dead){
      this.dead=true;
      pendingObjects.push(new BlackHole(this.x,this.y,10));
      spawnExplosion(this.x,this.y,2,true);
    }
  }
  draw(){
    const sx=this.sx(),sy=this.sy();
    const pct=Math.min(1,1-(this.radius/this._baseR));
    // Tremor visual proporcional ao colapso
    const shakeAmp=pct*3*cam.zoom;
    const shx=Math.sin(this._shakeT*28)*shakeAmp,shy=Math.cos(this._shakeT*21)*shakeAmp;
    const dsx=sx+shx,dsy=sy+shy;
    const r=this.sr()*(1+0.05*Math.sin(this._t*7)+0.03*Math.sin(this._t*13.3));
    const aura=ctx.createRadialGradient(dsx,dsy,r*.5,dsx,dsy,r*(2+pct*2));
    aura.addColorStop(0,`rgba(${~~(80+pct*120)},${~~(60+pct*40)},${~~(160+pct*80)},${0.12+pct*.25})`);aura.addColorStop(1,'transparent');
    ctx.beginPath();ctx.arc(dsx,dsy,r*(2+pct*2),0,Math.PI*2);ctx.fillStyle=aura;ctx.fill();
    const g=ctx.createRadialGradient(dsx-r*.22,dsy-r*.22,r*.04,dsx,dsy,r);
    g.addColorStop(0,`rgba(${~~(200+pct*55)},${~~(190+pct*30)},${~~(220+pct*35)},.95)`);
    g.addColorStop(.4,`rgb(${~~(90+pct*40)},${~~(80+pct*20)},${~~(110+pct*60)})`);
    g.addColorStop(.75,'#2a2a3a');g.addColorStop(1,'#06060f');
    ctx.beginPath();ctx.arc(dsx,dsy,r,0,Math.PI*2);ctx.fillStyle=g;ctx.fill();
    if(pct>0.05){
      ctx.save();ctx.beginPath();ctx.arc(dsx,dsy,r,0,Math.PI*2);ctx.clip();
      this._cracks.forEach(c=>{
        ctx.beginPath();ctx.moveTo(dsx,dsy);
        ctx.lineTo(dsx+Math.cos(c.a)*r*Math.min(1,c.len*pct),dsy+Math.sin(c.a)*r*Math.min(1,c.len*pct));
        ctx.strokeStyle=`rgba(${~~(150+pct*105)},100,255,${pct*.7})`;ctx.lineWidth=r*c.w*pct;ctx.stroke();
        // Brilho nas pontas das rachaduras
        const cx2=dsx+Math.cos(c.a)*r*Math.min(1,c.len*pct),cy2=dsy+Math.sin(c.a)*r*Math.min(1,c.len*pct);
        ctx.beginPath();ctx.arc(cx2,cy2,r*c.w*2*pct,0,Math.PI*2);
        ctx.fillStyle=`rgba(200,150,255,${pct*.5})`;ctx.fill();
      });
      ctx.restore();
    }
    ctx.beginPath();ctx.arc(dsx,dsy,r,0,Math.PI*2);ctx.strokeStyle=`rgba(${~~(100+pct*155)},80,200,${0.3+pct*.5})`;ctx.lineWidth=2;ctx.stroke();
    if(pct>0.08&&sandboxMode){
      ctx.font=`bold ${Math.max(6,r*.35)}px 'Courier New'`;
      ctx.fillStyle=`rgba(180,120,255,${0.5+pct*.4})`;ctx.textAlign='center';
      ctx.fillText(`☠ ${(pct*100).toFixed(0)}%`,dsx,dsy-r*.7);ctx.textAlign='left';
    }
  }
}

// ─── 12. ESTRELA ESTRANHA ────────────────────────────────────────
// Contaminação: converte estrelas vizinhas em Estranhas
class StrangeStar extends CelestialObject{
  constructor(wx,wy){
    super(wx,wy,'strangeStar');
    this.radius=rand(5,10);this.mass=this.radius*16;
    this._t=rand(0,Math.PI*2);
    this._contamRange=this.radius*13;
    this._orbs=Array.from({length:5},(_,i)=>({a:i*(Math.PI*2/5)+rand(0,.5),spd:rand(.35,.8),r:rand(.06,.1)}));
    this.color='#6600aa';
  }
  update(dt){
    this._t+=dt;this._orbs.forEach(o=>o.a+=o.spd*dt);
    if(window._invasionActive)return; // bloqueia contaminação durante invasão
    objects.forEach(o=>{
      if(o===this||o.dead)return;
      if(o.type!=='star'&&!SP_TYPES.includes(o.type))return;
      const d=dist(o,this);if(d>this._contamRange||d<1)return;
      if(!o._strangeContam)o._strangeContam=0;
      o._strangeContam=Math.min(1,o._strangeContam+dt*.045*(1-d/this._contamRange));
      o.color=`hsl(${~~(270+o._strangeContam*35)},${~~(65+o._strangeContam*30)}%,${~~(45-o._strangeContam*15)}%)`;
      if(o._strangeContam>=1&&o.type!=='strangeStar'){o.dead=true;pendingObjects.push(new StrangeStar(o.x,o.y));spawnExplosion(o.x,o.y,0.9,false);}
    });
  }
  draw(){
    const sx=this.sx(),sy=this.sy();
    const r=this.sr()*(1+0.08*Math.sin(this._t*1.9));
    const cR=this._contamRange*cam.zoom;
    const cg=ctx.createRadialGradient(sx,sy,r,sx,sy,cR);
    cg.addColorStop(0,`rgba(100,0,180,${0.09+0.04*Math.sin(this._t)})`);cg.addColorStop(.5,'rgba(80,0,140,.03)');cg.addColorStop(1,'transparent');
    ctx.beginPath();ctx.arc(sx,sy,cR,0,Math.PI*2);ctx.fillStyle=cg;ctx.fill();
    this._orbs.forEach(orb=>{
      const ox=sx+Math.cos(orb.a)*r*2.8,oy=sy+Math.sin(orb.a)*r*2.8;
      const og=ctx.createRadialGradient(ox,oy,0,ox,oy,r*orb.r*2.5);
      og.addColorStop(0,`rgba(190,80,255,${0.55+0.3*Math.sin(this._t*3+orb.a)})`);og.addColorStop(1,'transparent');
      ctx.beginPath();ctx.arc(ox,oy,r*orb.r*2.5,0,Math.PI*2);ctx.fillStyle=og;ctx.fill();
      ctx.beginPath();ctx.moveTo(sx,sy);ctx.lineTo(ox,oy);ctx.strokeStyle='rgba(160,40,255,0.1)';ctx.lineWidth=1;ctx.stroke();
    });
    const aura=ctx.createRadialGradient(sx,sy,r*.4,sx,sy,r*4);
    aura.addColorStop(0,`rgba(140,0,220,${0.32+0.12*Math.sin(this._t*1.5)})`);aura.addColorStop(1,'transparent');
    ctx.beginPath();ctx.arc(sx,sy,r*4,0,Math.PI*2);ctx.fillStyle=aura;ctx.fill();
    const g=ctx.createRadialGradient(sx,sy,0,sx,sy,r);
    g.addColorStop(0,'rgba(220,120,255,.99)');g.addColorStop(.45,'#6600aa');g.addColorStop(.8,'#1a0030');g.addColorStop(1,'#040008');
    ctx.beginPath();ctx.arc(sx,sy,r,0,Math.PI*2);ctx.fillStyle=g;ctx.fill();
    ctx.beginPath();ctx.arc(sx,sy,r,0,Math.PI*2);ctx.strokeStyle='rgba(180,60,255,0.55)';ctx.lineWidth=2;ctx.stroke();
    objects.forEach(o=>{
      if(!o._strangeContam||o._strangeContam<0.05||o.dead)return;
      const {x:ox,y:oy}=worldToScreen(o.x,o.y);const or2=o.sr();
      const hg=ctx.createRadialGradient(ox,oy,or2*.8,ox,oy,or2*2.2);
      hg.addColorStop(0,`rgba(140,0,220,${o._strangeContam*.35})`);hg.addColorStop(1,'transparent');
      ctx.beginPath();ctx.arc(ox,oy,or2*2.2,0,Math.PI*2);ctx.fillStyle=hg;ctx.fill();
      ctx.beginPath();ctx.arc(ox,oy,or2*1.15,0,Math.PI*2);ctx.strokeStyle=`rgba(160,40,255,${o._strangeContam*.6})`;ctx.lineWidth=2;ctx.stroke();
    });
  }
}

// ─── 13. ESTRELA ELETROFRACA ─────────────────────────────────────
// Campo Eletrofraco: desativa forças de objetos próximos por 3s
class ElectroweakStar extends CelestialObject{
  constructor(wx,wy){
    super(wx,wy,'electroweakStar');
    this.radius=rand(6,12);this.mass=this.radius*14;
    this._t=rand(0,Math.PI*2);
    this._pulseTimer=0;this._pulseMax=rand(4,7);this._pulseFlash=0;
    this._arcs=[];
    this.color='#22eecc';
  }
  update(dt){
    this._t+=dt;this._pulseTimer+=dt;if(this._pulseFlash>0)this._pulseFlash-=dt;
    this._arcs=this._arcs.filter(a=>{a.life-=dt;return a.life>0;});
    if(this._pulseTimer>=this._pulseMax){
      this._pulseTimer=0;this._pulseFlash=1.0;
    if(window._invasionActive)return; // bloqueia interações durante invasão
      objects.forEach(o=>{
        if(o===this||o.dead)return;
        const d=dist(o,this);if(d>this.radius*16||d<1)return;
        o._ewDisabled=true;o._ewTimer=3.5;this._arcs.push({x:o.x,y:o.y,life:.6,maxLife:.6});
      });
    }
    objects.forEach(o=>{if(o._ewDisabled){o._ewTimer-=dt;if(o._ewTimer<=0){o._ewDisabled=false;}else{// Congela velocidade gradualmente (campo eletrofraco neutraliza forças)
      o.vx=(o.vx||0)*Math.pow(0.06,dt);o.vy=(o.vy||0)*Math.pow(0.06,dt);}}});
  }
  draw(){
    const sx=this.sx(),sy=this.sy();
    const r=this.sr()*(1+0.07*Math.sin(this._t*4.1)+0.04*Math.sin(this._t*9.3));
    this._arcs.forEach(a=>{
      const {x:ax,y:ay}=worldToScreen(a.x,a.y);const lf=a.life/a.maxLife;
      ctx.beginPath();ctx.moveTo(sx,sy);ctx.lineTo(ax,ay);ctx.strokeStyle=`rgba(0,255,200,${lf*.5})`;ctx.lineWidth=2*cam.zoom;ctx.stroke();
      ctx.beginPath();ctx.arc(ax,ay,5*cam.zoom,0,Math.PI*2);ctx.strokeStyle=`rgba(0,255,200,${lf*.7})`;ctx.lineWidth=2;ctx.stroke();
    });
    if(this._pulseFlash>0){
      const pf=ctx.createRadialGradient(sx,sy,r,sx,sy,r*7);
      pf.addColorStop(0,`rgba(0,255,200,${this._pulseFlash*.45})`);pf.addColorStop(.4,'rgba(0,200,160,.1)');pf.addColorStop(1,'transparent');
      ctx.beginPath();ctx.arc(sx,sy,r*7,0,Math.PI*2);ctx.fillStyle=pf;ctx.fill();
    }
    for(let i=0;i<3;i++){
      const rr=r*(1.6+i*.7+.15*Math.sin(this._t*2+i));
      ctx.beginPath();ctx.arc(sx,sy,rr,0,Math.PI*2);ctx.strokeStyle=`rgba(0,220,180,${0.14-i*.04+0.05*Math.sin(this._t+i)})`;ctx.lineWidth=1.5;ctx.stroke();
    }
    const aura=ctx.createRadialGradient(sx,sy,r*.4,sx,sy,r*3.5);
    aura.addColorStop(0,`rgba(0,220,180,${0.28+0.1*Math.sin(this._t*1.8)})`);aura.addColorStop(1,'transparent');
    ctx.beginPath();ctx.arc(sx,sy,r*3.5,0,Math.PI*2);ctx.fillStyle=aura;ctx.fill();
    const g=ctx.createRadialGradient(sx-r*.25,sy-r*.25,r*.06,sx,sy,r);
    g.addColorStop(0,'rgba(200,255,245,.97)');g.addColorStop(.38,'#22eecc');g.addColorStop(.72,'#006655');g.addColorStop(1,'#000e0c');
    ctx.beginPath();ctx.arc(sx,sy,r,0,Math.PI*2);ctx.fillStyle=g;ctx.fill();
    ctx.save();ctx.beginPath();ctx.arc(sx,sy,r,0,Math.PI*2);ctx.clip();
    for(let i=0;i<4;i++){
      const a=i*1.57+this._t*.15;ctx.beginPath();ctx.arc(sx+Math.cos(a)*r*.38,sy+Math.sin(a)*r*.38,r*.28,0,Math.PI*2);
      ctx.strokeStyle=`rgba(0,255,200,${0.3+0.18*Math.sin(this._t*3+i)})`;ctx.lineWidth=r*.09;ctx.stroke();
    }
    ctx.restore();
    ctx.beginPath();ctx.arc(sx,sy,r,0,Math.PI*2);ctx.strokeStyle='rgba(0,240,180,0.55)';ctx.lineWidth=2;ctx.stroke();
    objects.forEach(o=>{
      if(!o._ewDisabled||o.dead)return;const {x:ox,y:oy}=worldToScreen(o.x,o.y);const or2=o.sr();
      ctx.font=`${Math.max(8,or2*.6)}px sans-serif`;ctx.textAlign='center';ctx.fillStyle='rgba(0,255,180,0.7)';ctx.fillText('⚡',ox,oy-or2*1.4);ctx.textAlign='left';
    });
  }
}

// ─── 14. ESTRELA DE PLANCK ───────────────────────────────────────
// Rebote Quântico: explode ao ser comprimida demais — com contador visível
class PlanckStar extends CelestialObject{
  constructor(wx,wy){
    super(wx,wy,'planckStar');
    this.radius=rand(3,5);this.mass=this.radius*40;
    this._t=rand(0,Math.PI*2);
    this._compressed=0;this._rebooted=false;this._shockRings=[];
    this._compBlink=0;
    this.color='#ffffff';
  }
  update(dt){
    this._t+=dt;if(this._compBlink>0)this._compBlink-=dt;
    // Acumula compressão com qualquer objeto próximo (raio*6, mais fácil de ativar)
    let sq=0;
    objects.forEach(o=>{if(o===this||o.dead)return;if(dist(o,this)<this.radius*6)sq+=1.2;});
    this._compressed=Math.min(1,Math.max(0,this._compressed+sq*dt*.18-dt*.03));
    this._shockRings=this._shockRings.filter(ring=>{ring.r+=dt*180;ring.alpha=Math.max(0,ring.alpha-dt*.55);return ring.alpha>0;});
    if(this._compressed>=0.7&&!this._compBlink)this._compBlink=0.1;// aviso piscante
    if(this._compressed>=1&&!this._rebooted){
      this._rebooted=true;this._compressed=0;
      for(let i=0;i<5;i++)this._shockRings.push({r:this.radius*1.2+i*this.radius*.3,alpha:1});
    if(window._invasionActive)return; // bloqueia interações durante invasão
      objects.forEach(o=>{
        if(o===this||o.dead||o.immune)return;
        const d=dist(o,this);if(d>this.radius*30||d<1)return;
        const f=320*(1-d/(this.radius*30)),nx=(o.x-this.x)/d,ny=(o.y-this.y)/d;
        o.vx=(o.vx||0)+nx*f;o.vy=(o.vy||0)+ny*f;
        if(d<this.radius*7)o.dead=true;// zona letal expandida
      });
      spawnExplosion(this.x,this.y,5,true);
      setTimeout(()=>{this._rebooted=false;},4000);
    }
  }
  draw(){
    const sx=this.sx(),sy=this.sy();
    const comp=this._compressed;
    const r=this.sr()*(1-comp*.25)*(1+0.10*Math.sin(this._t*6)+0.06*Math.sin(this._t*17.3));
    this._shockRings.forEach(ring=>{
      ctx.beginPath();ctx.arc(sx,sy,ring.r*cam.zoom,0,Math.PI*2);
      ctx.strokeStyle=`rgba(255,255,255,${ring.alpha})`;ctx.lineWidth=3;ctx.stroke();
    });
    for(let i=4;i>=0;i--){
      const lR=r*(2.5+i*.9*(1-comp*.6));
      const gg=ctx.createRadialGradient(sx,sy,r*.3,sx,sy,lR);
      gg.addColorStop(0,`rgba(${~~(200+comp*55)},${~~(200+comp*55)},255,${(0.18+comp*.22)/(i+1)})`);gg.addColorStop(1,'transparent');
      ctx.beginPath();ctx.arc(sx,sy,lR,0,Math.PI*2);ctx.fillStyle=gg;ctx.fill();
    }
    const bR=r*(1-comp*.25);
    const g=ctx.createRadialGradient(sx,sy,0,sx,sy,bR);
    g.addColorStop(0,'#ffffff');g.addColorStop(.38,`rgba(${~~(200+comp*55)},${~~(200+comp*55)},255,.99)`);
    g.addColorStop(.8,`rgba(${~~(80+comp*100)},${~~(80+comp*80)},220,1)`);g.addColorStop(1,`rgba(${~~(40+comp*80)},${~~(40+comp*60)},180,1)`);
    ctx.beginPath();ctx.arc(sx,sy,bR,0,Math.PI*2);ctx.fillStyle=g;ctx.fill();
    // Anel de alerta piscante quando quase cheio
    if(comp>0.6){
      const blinkAlpha=(comp-0.6)*2.5*(this._compBlink>0?1:0.4);
      ctx.beginPath();ctx.arc(sx,sy,r*1.8,0,Math.PI*2);
      ctx.strokeStyle=`rgba(255,100,100,${blinkAlpha*.7})`;ctx.lineWidth=3;ctx.stroke();
    }
    if(comp>0.05){ctx.beginPath();ctx.arc(sx,sy,r*1.6,0,Math.PI*2);ctx.strokeStyle=`rgba(200,220,255,${comp*.6})`;ctx.lineWidth=2;ctx.stroke();}
    ctx.beginPath();ctx.arc(sx,sy,bR,0,Math.PI*2);ctx.strokeStyle=`rgba(255,255,255,${0.4+comp*.5})`;ctx.lineWidth=2;ctx.stroke();
    // Barra de compressão sempre visível
    {
      const bw=r*2.5*cam.zoom,bh=4,bx=sx-bw/2,by=sy-r*cam.zoom*2.2-bh;
      ctx.fillStyle='rgba(0,0,20,0.6)';ctx.fillRect(bx,by,bw,bh);
      const barColor=comp<0.5?`rgba(100,180,255,0.85)`:comp<0.8?`rgba(255,200,60,0.9)`:`rgba(255,60,60,${0.8+0.2*Math.sin(this._t*12)})`;
      ctx.fillStyle=barColor;ctx.fillRect(bx,by,bw*comp,bh);
      ctx.strokeStyle='rgba(200,220,255,0.4)';ctx.lineWidth=1;ctx.strokeRect(bx,by,bw,bh);
      ctx.font=`bold ${Math.max(5,r*.6)}px 'Courier New'`;ctx.fillStyle=`rgba(200,220,255,0.8)`;
      ctx.textAlign='center';ctx.fillText(`⚛ ${(comp*100).toFixed(0)}%`,sx,by-2);ctx.textAlign='left';
    }
  }
}

// ─── 15. ESTRELA WOLF-RAYET ──────────────────────────────────────
// Nebulosa Pessoal: cria bolha de vento ao redor
class WolfRayet extends CelestialObject{
  constructor(wx,wy){
    super(wx,wy,'wolfRayet');
    this.radius=rand(12,22);this.mass=this.radius*10;
    this._t=rand(0,Math.PI*2);
    this._nebulaR=this.radius*3;this._nebulaMax=this.radius*18;
    this._hue=randInt(255,320);this._twist=rand(0,Math.PI*2);
    this._fils=Array.from({length:7},(_,i)=>({a:i*(Math.PI*2/7),spd:rand(.02,.06),len:rand(.6,1)}));
    this.color=`hsl(${this._hue},90%,60%)`;
  }
  update(dt){
    this._t+=dt;this._twist+=dt*.08;this._fils.forEach(f=>f.a+=f.spd*dt);
    this._nebulaR=Math.min(this._nebulaMax,this._nebulaR+dt*10);
    if(window._invasionActive)return; // bloqueia interações durante invasão
    objects.forEach(o=>{
      if(o===this||o.dead||o.immune||o.fixed)return;
      const d=dist(o,this);if(d>this._nebulaR||d<1)return;
      const f=8*(1-d/this._nebulaR),nx=(o.x-this.x)/d,ny=(o.y-this.y)/d;
      o.vx=(o.vx||0)+nx*f*dt*60;o.vy=(o.vy||0)+ny*f*dt*60;
      // Bolha de vento: drena massa e desativa força gravitacional do objeto
      const massDrain=dt*0.08*(1-d/this._nebulaR);
      if(o.radius>1.5){o.radius=Math.max(1.5,o.radius-massDrain);o.mass=Math.max(0.1,o.mass-massDrain*3);}
      o._wrNebula=true;o._wrTimer=0.4;// flag: sem gravidade por 0.4s
    });
    objects.forEach(o=>{if(o._wrNebula){o._wrTimer-=dt;if(o._wrTimer<=0)o._wrNebula=false;}});
  }
  draw(){
    const sx=this.sx(),sy=this.sy();
    const r=this.sr()*(1+0.07*Math.sin(this._t*1.2));
    const hue=this._hue;const nr=this._nebulaR*cam.zoom;
    ctx.save();ctx.translate(sx,sy);ctx.rotate(this._twist);
    for(let i=0;i<5;i++){
      const frac=i/4;const lR=nr*(0.4+frac*.65);
      const ng=ctx.createRadialGradient(0,0,r*(1.2+frac*.4),0,0,lR);
      ng.addColorStop(0,`hsla(${hue+i*15},90%,60%,${0.07-frac*.012})`);ng.addColorStop(1,'transparent');
      ctx.beginPath();ctx.arc(0,0,lR,0,Math.PI*2);ctx.fillStyle=ng;ctx.fill();
    }
    ctx.restore();
    this._fils.forEach(f=>{
      const len=nr*f.len;
      const jg=ctx.createLinearGradient(sx,sy,sx+Math.cos(f.a)*len,sy+Math.sin(f.a)*len);
      jg.addColorStop(0,`hsla(${hue+20},90%,70%,0.12)`);jg.addColorStop(.5,`hsla(${hue},85%,60%,0.06)`);jg.addColorStop(1,'transparent');
      ctx.beginPath();ctx.moveTo(sx,sy);ctx.lineTo(sx+Math.cos(f.a)*len,sy+Math.sin(f.a)*len);
      ctx.strokeStyle=jg;ctx.lineWidth=r*.5;ctx.stroke();
    });
    ctx.beginPath();ctx.arc(sx,sy,nr,0,Math.PI*2);ctx.strokeStyle=`hsla(${hue},80%,70%,${0.1+0.05*Math.sin(this._t)})`;ctx.lineWidth=2;ctx.stroke();
    const aura=ctx.createRadialGradient(sx,sy,r*.5,sx,sy,r*3);
    aura.addColorStop(0,`hsla(${hue},90%,65%,.32)`);aura.addColorStop(1,'transparent');
    ctx.beginPath();ctx.arc(sx,sy,r*3,0,Math.PI*2);ctx.fillStyle=aura;ctx.fill();
    const g=ctx.createRadialGradient(sx-r*.28,sy-r*.28,r*.06,sx,sy,r);
    g.addColorStop(0,'rgba(255,240,255,.97)');g.addColorStop(.3,`hsl(${hue},95%,75%)`);g.addColorStop(.62,`hsl(${hue+20},80%,40%)`);g.addColorStop(1,'#050005');
    ctx.beginPath();ctx.arc(sx,sy,r,0,Math.PI*2);ctx.fillStyle=g;ctx.fill();
    ctx.beginPath();ctx.arc(sx,sy,r,0,Math.PI*2);ctx.strokeStyle=`hsla(${hue},80%,75%,0.5)`;ctx.lineWidth=2;ctx.stroke();
  }
}

// ─── 16. ESTRELA DE PRZYBYLSKI ───────────────────────────────────
// Elementos Exóticos: contamina planetas com halo dourado
class PrzybylskiStar extends CelestialObject{
  constructor(wx,wy){
    super(wx,wy,'przybylski');
    this.radius=rand(10,18);this.mass=this.radius*8;
    this._t=rand(0,Math.PI*2);
    this._contRange=this.radius*11;this._sparkTimer=0;this._sparks=[];
    this._lattice=Array.from({length:5},()=>({a:rand(0,Math.PI*2),d:rand(.4,.8),spd:rand(.03,.09)}));
    this.color='#ddbb33';
  }
  update(dt){
    this._t+=dt;this._sparkTimer+=dt;this._lattice.forEach(l=>l.a+=l.spd*dt);
    this._sparks=this._sparks.filter(s=>{s.life-=dt;s.x+=s.vx*dt;s.y+=s.vy*dt;return s.life>0;});
    if(this._sparkTimer>.15){this._sparkTimer=0;const a=rand(0,Math.PI*2),spd=rand(15,40);this._sparks.push({x:this.x,y:this.y,vx:Math.cos(a)*spd,vy:Math.sin(a)*spd,life:rand(.5,1.5),maxLife:1.5});}
    objects.forEach(o=>{
      if(o===this||o.dead)return;
      const d=dist(o,this);
      if(d<this._contRange){
        if(o.type==='planet'||PP_ORBIT_TYPES.includes(o.type)){
          // Contamina planetas com halo dourado e rastro de ouro
          o._przybContam=true;o._przybTimer=6;
          // Rastro de partículas douradas
          if(Math.random()<0.04*dt*60)this._sparks.push({x:o.x+rand(-o.radius,o.radius),y:o.y+rand(-o.radius,o.radius),vx:rand(-12,12),vy:rand(-12,12),life:rand(.8,2),maxLife:2});
        } else if(o.type!=='strangeStar'&&o.type!=='blackhole'&&o.type!=='whitehole'&&o.type!=='wormhole'){
          // Colapso em outros astros: encolhe gradualmente
          if(!o._przybCollapse)o._przybCollapse=0;
          o._przybCollapse+=dt*0.06*(1-d/this._contRange);
          o.radius=Math.max(1.5,o.radius-dt*0.04*(1-d/this._contRange));
          o.mass=o.radius*10;
          if(o.radius<=1.5&&!o.dead){o.dead=true;for(let i=0;i<12;i++)this._sparks.push({x:o.x,y:o.y,vx:rand(-30,30),vy:rand(-30,30),life:rand(1,2),maxLife:2});}
        }
      }
    });
    objects.forEach(o=>{if(o._przybContam){o._przybTimer-=dt;if(o._przybTimer<=0)o._przybContam=false;}});
  }
  draw(){
    const sx=this.sx(),sy=this.sy();
    const r=this.sr()*(1+0.08*Math.sin(this._t*2.0));
    this._sparks.forEach(s=>{
      const {x:px,y:py}=worldToScreen(s.x,s.y);const lf=s.life/s.maxLife;
      ctx.beginPath();ctx.arc(px,py,2.5*cam.zoom,0,Math.PI*2);ctx.fillStyle=`rgba(255,${~~(200+55*lf)},60,${lf*.65})`;ctx.fill();
    });
    const aura=ctx.createRadialGradient(sx,sy,r*.5,sx,sy,r*3.5);
    aura.addColorStop(0,`rgba(255,210,40,${0.28+0.12*Math.sin(this._t*1.2)})`);aura.addColorStop(1,'transparent');
    ctx.beginPath();ctx.arc(sx,sy,r*3.5,0,Math.PI*2);ctx.fillStyle=aura;ctx.fill();
    const g=ctx.createRadialGradient(sx-r*.3,sy-r*.3,r*.06,sx,sy,r);
    g.addColorStop(0,'rgba(255,255,210,.99)');g.addColorStop(.38,'#eebb22');g.addColorStop(.72,'#886600');g.addColorStop(1,'#100c00');
    ctx.beginPath();ctx.arc(sx,sy,r,0,Math.PI*2);ctx.fillStyle=g;ctx.fill();
    ctx.save();ctx.beginPath();ctx.arc(sx,sy,r,0,Math.PI*2);ctx.clip();
    this._lattice.forEach(l=>{
      const bx=sx+Math.cos(l.a)*r*l.d,by=sy+Math.sin(l.a)*r*l.d;
      ctx.beginPath();ctx.arc(bx,by,r*.13,0,Math.PI*2);ctx.fillStyle=`rgba(255,240,100,${0.3+0.18*Math.sin(this._t*3+l.a)})`;ctx.fill();
      ctx.beginPath();ctx.moveTo(sx,sy);ctx.lineTo(bx,by);ctx.strokeStyle='rgba(255,200,40,0.2)';ctx.lineWidth=r*.06;ctx.stroke();
    });
    ctx.restore();
    ctx.beginPath();ctx.arc(sx,sy,r,0,Math.PI*2);ctx.strokeStyle='rgba(255,220,60,0.5)';ctx.lineWidth=2;ctx.stroke();
    objects.forEach(o=>{
      if(!o._przybContam||o.dead)return;const {x:ox,y:oy}=worldToScreen(o.x,o.y);const or2=o.sr();
      for(let ring=0;ring<3;ring++){
        ctx.beginPath();ctx.arc(ox,oy,or2*(1.2+ring*.4),0,Math.PI*2);
        ctx.strokeStyle=`rgba(255,${~~(200+ring*18)},40,${(0.35-ring*.1)+0.15*Math.sin(this._t*3+ring)})`;ctx.lineWidth=2-ring*.5;ctx.stroke();
      }
    });
  }
}

// ─── 17. JANUS ───────────────────────────────────────────────────
// Dupla Natureza: face vermelha atrai, face azul repele — giram continuamente
class JanusStar extends CelestialObject{
  constructor(wx,wy){
    super(wx,wy,'janusStar');
    this.radius=rand(10,18);this.mass=this.radius*9;
    this._t=rand(0,Math.PI*2);
    this._splitAngle=rand(0,Math.PI*2);// ângulo de rotação do eixo
    this.color='#ff8833';
  }
  update(dt){
    this._t+=dt;
    // Rotação contínua do eixo
    this._splitAngle+=dt*0.55;
    if(window._invasionActive)return; // bloqueia interações durante invasão
    objects.forEach(o=>{
      if(o===this||o.dead||o.immune||o.fixed)return;
      const d=dist(o,this);if(d>this.radius*10||d<1)return;
      // Ângulo do objeto em relação à estrela
      const ang=Math.atan2(o.y-this.y,o.x-this.x);
      // Determina em qual metade o objeto está (relativo ao eixo rotativo)
      const relAng=((ang-this._splitAngle+Math.PI*3)%(Math.PI*2));
      const isRedFace=relAng<Math.PI;// metade vermelha = atrai
      const nx=(this.x-o.x)/d,ny=(this.y-o.y)/d;
      if(isRedFace){
        // Face vermelha: atrai
        const f=2200/(d*d+80);
        o.vx=(o.vx||0)+nx*f*dt;o.vy=(o.vy||0)+ny*f*dt;
      } else {
        // Face azul: repele
        const f=32*(1-d/(this.radius*10));
        o.vx=(o.vx||0)-nx*f*dt*3;o.vy=(o.vy||0)-ny*f*dt*3;
      }
    });
  }
  draw(){
    const sx=this.sx(),sy=this.sy();
    const r=this.sr()*(1+0.07*Math.sin(this._t*2.2));
    // Auras laterais
    const redX=sx+Math.cos(this._splitAngle)*r*2.2,redY=sy+Math.sin(this._splitAngle)*r*2.2;
    const blueX=sx-Math.cos(this._splitAngle)*r*2.2,blueY=sy-Math.sin(this._splitAngle)*r*2.2;
    const ra=ctx.createRadialGradient(redX,redY,0,redX,redY,r*3);
    ra.addColorStop(0,`rgba(255,80,20,${0.18+0.08*Math.sin(this._t*2)})`);ra.addColorStop(1,'transparent');
    ctx.beginPath();ctx.arc(redX,redY,r*3,0,Math.PI*2);ctx.fillStyle=ra;ctx.fill();
    const ba=ctx.createRadialGradient(blueX,blueY,0,blueX,blueY,r*3);
    ba.addColorStop(0,`rgba(40,100,255,${0.18+0.08*Math.sin(this._t*2+1)})`);ba.addColorStop(1,'transparent');
    ctx.beginPath();ctx.arc(blueX,blueY,r*3,0,Math.PI*2);ctx.fillStyle=ba;ctx.fill();
    // Corpo dividido
    ctx.save();ctx.translate(sx,sy);ctx.rotate(this._splitAngle);
    // Metade vermelha (atrai)
    ctx.beginPath();ctx.moveTo(0,0);ctx.arc(0,0,r,0,Math.PI);ctx.closePath();
    const gH=ctx.createRadialGradient(-r*.3,-r*.3,r*.05,0,0,r);
    gH.addColorStop(0,'rgba(255,255,200,.98)');gH.addColorStop(.35,'#ff5522');gH.addColorStop(.75,'#aa2200');gH.addColorStop(1,'#0d0000');
    ctx.fillStyle=gH;ctx.fill();
    // Metade azul (repele)
    ctx.beginPath();ctx.moveTo(0,0);ctx.arc(0,0,r,Math.PI,Math.PI*2);ctx.closePath();
    const gC=ctx.createRadialGradient(r*.3,r*.3,r*.05,0,0,r);
    gC.addColorStop(0,'rgba(220,240,255,.98)');gC.addColorStop(.35,'#4488ff');gC.addColorStop(.75,'#001155');gC.addColorStop(1,'#00040d');
    ctx.fillStyle=gC;ctx.fill();
    // Linha divisória
    ctx.beginPath();ctx.moveTo(0,-r);ctx.lineTo(0,r);ctx.strokeStyle='rgba(255,255,255,0.8)';ctx.lineWidth=2.5;ctx.stroke();
    ctx.restore();
    ctx.beginPath();ctx.arc(sx,sy,r,0,Math.PI*2);ctx.strokeStyle='rgba(200,180,255,0.4)';ctx.lineWidth=2;ctx.stroke();
    if(sandboxMode){ctx.font=`bold ${Math.max(6,r*.28)}px 'Courier New'`;ctx.textAlign='center';
      ctx.fillStyle='rgba(255,100,60,0.8)';ctx.fillText('🔴atrai',sx+Math.cos(this._splitAngle)*r*1.6,sy+Math.sin(this._splitAngle)*r*1.6+4);
      ctx.fillStyle='rgba(80,140,255,0.8)';ctx.fillText('🔵repele',sx-Math.cos(this._splitAngle)*r*1.6,sy-Math.sin(this._splitAngle)*r*1.6+4);
      ctx.textAlign='left';}
  }
}

// ─── 18. ESTRELA DE CORDAS CÓSMICAS ─────────────────────────────
// Teia: conecta objetos com filamentos, divide os que tocam, teletransporta com fade
class CosmicString extends CelestialObject{
  constructor(wx,wy){
    super(wx,wy,'cosmicString');
    this.radius=rand(5,10);this.mass=this.radius*11;
    this._t=rand(0,Math.PI*2);
    this._webRange=this.radius*16;this._strum=0;
    this._teleportCooldown=0;
    this._fadeGhosts=[];// objetos em fade de teletransporte
    this.color='#88ffcc';
  }
  update(dt){
    this._t+=dt;this._strum+=dt*1.2;this._teleportCooldown=Math.max(0,this._teleportCooldown-dt);
    // Atualizar fantasmas de fade
    this._fadeGhosts=this._fadeGhosts.filter(g=>{g.alpha-=dt*1.2;return g.alpha>0;});
    if(window._invasionActive)return; // bloqueia interações durante invasão
    const near=objects.filter(o=>o!==this&&!o.dead&&dist(o,this)<this._webRange);
    // Filamentos elásticos entre vizinhos
    for(let i=0;i<near.length;i++)for(let j=i+1;j<near.length;j++){
      const a=near[i],b=near[j];if(a.dead||b.dead||a.immune||b.immune)continue;
      const d=dist(a,b);if(d<1||d>this._webRange*.55)continue;
      const f=1.0*(1-d/(this._webRange*.55));const nx=(b.x-a.x)/d,ny=(b.y-a.y)/d;
      a.vx=(a.vx||0)+nx*f*dt;a.vy=(a.vy||0)+ny*f*dt;b.vx=(b.vx||0)-nx*f*dt;b.vy=(b.vy||0)-ny*f*dt;
    }
    near.forEach(o=>{
      if(o.immune||o.fixed)return;const d=dist(o,this);if(d<1)return;
      const f=.4*(1-d/this._webRange),nx=(this.x-o.x)/d,ny=(this.y-o.y)/d;
      o.vx=(o.vx||0)+nx*f*dt*20;o.vy=(o.vy||0)+ny*f*dt*20;
      // Toca na estrela: divide em 2 objetos menores + teletransporta com fade
      if(d<this.radius*1.8&&!o.dead&&!o.immune&&o.radius>3&&this._teleportCooldown<=0){
        this._teleportCooldown=1.2;
        // Registra ghost para fade no local de origem
        this._fadeGhosts.push({x:o.x,y:o.y,r:o.radius,type:o.type,alpha:0.9});
        // Teletransporta para outro lado perto da estrela
        const teleAng=Math.atan2(o.y-this.y,o.x-this.x)+Math.PI+rand(-0.5,0.5);
        const teleDist=this.radius*3.5+rand(0,this._webRange*0.4);
        o.x=this.x+Math.cos(teleAng)*teleDist;o.y=this.y+Math.sin(teleAng)*teleDist;
        o._csAppear=0.8;// flag de fade-in no destino
        // Divide em objeto menor do mesmo tipo
        if(o.radius>5){
          const halfR=o.radius*0.55;o.radius=halfR;o.mass=halfR*6;
          const spawnAng=rand(0,Math.PI*2);
          const spawnX=o.x+Math.cos(spawnAng)*halfR*3,spawnY=o.y+Math.sin(spawnAng)*halfR*3;
          // Mapa de classes SP disponível globalmente após definição
          const _csClasses={redDwarf:RedDwarf,yellowDwarf:YellowDwarf,blueStar:BlueStar,redGiant:RedGiant,
            supergiant:Supergiant,whiteDwarf:WhiteDwarf,hypergiant:Hypergiant,vampireStar:VampireStar,
            quarkStar:QuarkStar,thorneZytkow:ThorneZytkow,ironStar:IronStar,strangeStar:StrangeStar,
            electroweakStar:ElectroweakStar,planckStar:PlanckStar,wolfRayet:WolfRayet,
            przybylski:PrzybylskiStar,janusStar:JanusStar,cosmicString:CosmicString,
            gravastar:Gravastar,quasiStar:QuasiStar,
            planet:Planet,star:Star,meteor:Meteor,comet:Comet,moon:Moon};
          const Cls=_csClasses[o.type];
          if(Cls){
            try{
              const newObj=new Cls(spawnX,spawnY);
              newObj.radius=Math.max(2,halfR*0.65);newObj.mass=newObj.radius*6;
              newObj.vx=(o.vx||0)+Math.cos(spawnAng)*15;newObj.vy=(o.vy||0)+Math.sin(spawnAng)*15;
              newObj._csAppear=0.8;
              pendingObjects.push(newObj);
            }catch(e){}
          }
        }
      }
    });
    // Decrement fade-in
    objects.forEach(o=>{if(o._csAppear>0)o._csAppear=Math.max(0,o._csAppear-dt*2);});
  }
  draw(){
    const sx=this.sx(),sy=this.sy();
    const r=this.sr()*(1+0.07*Math.sin(this._t*2.8));
    const near=objects.filter(o=>o!==this&&!o.dead&&dist(o,this)<this._webRange);
    // Efeito fundo espelhado — duplica o fundo local com inversão de cor
    ctx.save();ctx.globalCompositeOperation='screen';
    const mirrorG=ctx.createRadialGradient(sx,sy,r,sx,sy,this._webRange*cam.zoom);
    mirrorG.addColorStop(0,`rgba(60,255,180,${0.06+0.03*Math.sin(this._t)})`);
    mirrorG.addColorStop(0.5,`rgba(30,120,80,0.03)`);mirrorG.addColorStop(1,'transparent');
    ctx.beginPath();ctx.arc(sx,sy,this._webRange*cam.zoom,0,Math.PI*2);ctx.fillStyle=mirrorG;ctx.fill();
    // Grade de teia duplicadora
    for(let i=0;i<6;i++){
      const a=i*(Math.PI/3)+this._t*0.04;
      const len=this._webRange*cam.zoom*(0.5+0.5*Math.sin(this._strum*0.7+i));
      ctx.beginPath();ctx.moveTo(sx,sy);ctx.lineTo(sx+Math.cos(a)*len,sy+Math.sin(a)*len);
      ctx.strokeStyle=`rgba(60,255,180,${0.04+0.02*Math.sin(this._t+i)})`;ctx.lineWidth=1;ctx.stroke();
    }
    ctx.restore();
    // Fantasmas de teletransporte (fade-out no local de origem)
    this._fadeGhosts.forEach(g=>{
      const{x:gx,y:gy}=worldToScreen(g.x,g.y);
      ctx.save();ctx.globalAlpha=g.alpha*0.6;
      ctx.beginPath();ctx.arc(gx,gy,g.r*cam.zoom,0,Math.PI*2);
      ctx.fillStyle='rgba(80,255,190,0.4)';ctx.fill();
      ctx.strokeStyle='rgba(80,255,190,0.8)';ctx.lineWidth=2;ctx.stroke();
      ctx.restore();
    });
    // Fade-in em objetos recém teletransportados
    objects.forEach(o=>{
      if(!o._csAppear||o._csAppear<=0)return;
      const{x:ox,y:oy}=worldToScreen(o.x,o.y);
      ctx.save();ctx.globalAlpha=o._csAppear*0.7;
      ctx.beginPath();ctx.arc(ox,oy,o.sr()*1.5,0,Math.PI*2);
      ctx.fillStyle='rgba(80,255,190,0.5)';ctx.fill();ctx.restore();
    });
    // Filamentos da teia
    near.slice(0,10).forEach((o,i)=>{
      const {x:ox,y:oy}=worldToScreen(o.x,o.y);
      const d=dist(o,this);const al=(0.18*(1-d/this._webRange))+0.05*Math.sin(this._strum+i);
      const mid={x:(sx+ox)/2+Math.sin(this._strum+i)*10*cam.zoom,y:(sy+oy)/2+Math.cos(this._strum+i*.7)*10*cam.zoom};
      ctx.beginPath();ctx.moveTo(sx,sy);ctx.quadraticCurveTo(mid.x,mid.y,ox,oy);
      ctx.strokeStyle=`rgba(80,255,190,${al})`;ctx.lineWidth=1.5;ctx.stroke();
    });
    for(let i=0;i<near.length&&i<8;i++)for(let j=i+1;j<near.length&&j<i+4;j++){
      const {x:ax,y:ay}=worldToScreen(near[i].x,near[i].y);const {x:bx,y:by}=worldToScreen(near[j].x,near[j].y);
      const dd=dist(near[i],near[j]);if(dd>this._webRange*.5)continue;
      ctx.beginPath();ctx.moveTo(ax,ay);ctx.lineTo(bx,by);ctx.strokeStyle=`rgba(80,255,190,${0.07*(1-dd/(this._webRange*.5))})`;ctx.lineWidth=1;ctx.stroke();
    }
    const aura=ctx.createRadialGradient(sx,sy,r*.5,sx,sy,r*4.5);
    aura.addColorStop(0,`rgba(60,255,170,${0.22+0.1*Math.sin(this._t*1.5)})`);aura.addColorStop(1,'transparent');
    ctx.beginPath();ctx.arc(sx,sy,r*4.5,0,Math.PI*2);ctx.fillStyle=aura;ctx.fill();
    const g=ctx.createRadialGradient(sx,sy,0,sx,sy,r);
    g.addColorStop(0,'rgba(200,255,235,.99)');g.addColorStop(.45,'#44cc99');g.addColorStop(.8,'#003322');g.addColorStop(1,'#000a06');
    ctx.beginPath();ctx.arc(sx,sy,r,0,Math.PI*2);ctx.fillStyle=g;ctx.fill();
    ctx.save();ctx.beginPath();ctx.arc(sx,sy,r,0,Math.PI*2);ctx.clip();
    for(let i=0;i<4;i++){
      const a=i*1.57+this._t*.06;
      ctx.beginPath();ctx.moveTo(sx-Math.cos(a)*r,sy-Math.sin(a)*r);
      ctx.quadraticCurveTo(sx+Math.cos(a+1.57)*r*.3*Math.sin(this._strum+i),sy+Math.sin(a+1.57)*r*.3*Math.sin(this._strum+i),sx+Math.cos(a)*r,sy+Math.sin(a)*r);
      ctx.strokeStyle=`rgba(80,255,190,${0.3+0.18*Math.sin(this._t*2+i)})`;ctx.lineWidth=r*.1;ctx.stroke();
    }
    ctx.restore();
    ctx.beginPath();ctx.arc(sx,sy,r,0,Math.PI*2);ctx.strokeStyle='rgba(60,255,180,0.55)';ctx.lineWidth=2;ctx.stroke();
  }
}

// ─── 19. GRAVASTAR ───────────────────────────────────────────────
// Casca de Energia: escudo impenetrável que repele tudo
class Gravastar extends CelestialObject{
  constructor(wx,wy){
    super(wx,wy,'gravastar');
    this.radius=rand(10,18);this.mass=this.radius*12;
    this._t=rand(0,Math.PI*2);
    this._shellR=this.radius*2.4;this._shellAlpha=0.6;
    this._impactRings=[];this._hexPhase=0;
    this.color='#33ccff';
  }
  update(dt){
    this._t+=dt;this._hexPhase+=dt*.3;
    this._impactRings=this._impactRings.filter(ring=>{ring.r+=dt*80;ring.alpha=Math.max(0,ring.alpha-dt*1.8);return ring.alpha>0;});
    let hit=false;
    if(window._invasionActive)return; // bloqueia interações durante invasão
    objects.forEach(o=>{
      if(o===this||o.dead||o.immune||o.fixed)return;
      const d=dist(o,this);
      if(d<this._shellR&&d>this.radius+o.radius){
        const f=80*(1-(d-this.radius)/(this._shellR-this.radius));
        const nx=(o.x-this.x)/d,ny=(o.y-this.y)/d;
        o.vx=(o.vx||0)+nx*f;o.vy=(o.vy||0)+ny*f;
        if(!hit){hit=true;this._impactRings.push({r:d*.8,alpha:.9});}
        this._shellAlpha=1;
        // Ativa efeito de ricochete: velocidade aleatória por 5s
        if(!o._gvRicochet){
          o._gvRicochet=5.0;
          o._gvRicVx=(Math.random()-0.5)*180;
          o._gvRicVy=(Math.random()-0.5)*180;
        }
      }
    });
    this._shellAlpha=Math.max(0.35,this._shellAlpha-dt*1.2);
    // Aplicar ricochete nos objetos marcados
    objects.forEach(o=>{
      if(!o._gvRicochet||o.dead)return;
      o._gvRicochet-=dt;
      if(o._gvRicochet<=0){o._gvRicochet=0;return;}
      // Ricochete: adiciona impulso aleatório oscilante (como bater em coisas inexistentes)
      o.vx=(o.vx||0)+Math.sin(o._gvRicochet*7.3)*o._gvRicVx*dt;
      o.vy=(o.vy||0)+Math.cos(o._gvRicochet*6.1)*o._gvRicVy*dt;
      // Quica contra bordas imaginárias (ricochete aleatório)
      if(Math.random()<0.04){o._gvRicVx*=-1;}
      if(Math.random()<0.04){o._gvRicVy*=-1;}
    });
  }
  draw(){
    const sx=this.sx(),sy=this.sy();
    const r=this.sr()*(1+0.06*Math.sin(this._t*1.8));
    const shR=this._shellR*cam.zoom;
    this._impactRings.forEach(ring=>{
      ctx.beginPath();ctx.arc(sx,sy,ring.r*cam.zoom,0,Math.PI*2);ctx.strokeStyle=`rgba(80,220,255,${ring.alpha*.7})`;ctx.lineWidth=2;ctx.stroke();
    });
    ctx.save();ctx.translate(sx,sy);ctx.rotate(this._hexPhase);
    ctx.beginPath();ctx.arc(0,0,shR,0,Math.PI*2);ctx.strokeStyle=`rgba(80,220,255,${this._shellAlpha})`;ctx.lineWidth=3;ctx.stroke();
    for(let i=0;i<6;i++){const a=i*(Math.PI/3);ctx.beginPath();ctx.moveTo(0,0);ctx.lineTo(Math.cos(a)*shR,Math.sin(a)*shR);ctx.strokeStyle=`rgba(80,220,255,${this._shellAlpha*.2})`;ctx.lineWidth=1;ctx.stroke();}
    ctx.restore();
    const shGlow=ctx.createRadialGradient(sx,sy,shR*.88,sx,sy,shR*1.25);
    shGlow.addColorStop(0,`rgba(60,200,255,${this._shellAlpha*.22})`);shGlow.addColorStop(1,'transparent');
    ctx.beginPath();ctx.arc(sx,sy,shR*1.25,0,Math.PI*2);ctx.fillStyle=shGlow;ctx.fill();
    const vac=ctx.createRadialGradient(sx,sy,r,sx,sy,shR*.9);
    vac.addColorStop(0,'rgba(0,10,20,0.6)');vac.addColorStop(1,'transparent');
    ctx.beginPath();ctx.arc(sx,sy,shR*.9,0,Math.PI*2);ctx.fillStyle=vac;ctx.fill();
    const g=ctx.createRadialGradient(sx,sy,0,sx,sy,r);
    g.addColorStop(0,'rgba(230,250,255,.99)');g.addColorStop(.4,'#33ccff');g.addColorStop(.78,'#004466');g.addColorStop(1,'#000811');
    ctx.beginPath();ctx.arc(sx,sy,r,0,Math.PI*2);ctx.fillStyle=g;ctx.fill();
    ctx.save();ctx.beginPath();ctx.arc(sx,sy,r,0,Math.PI*2);ctx.clip();
    for(let i=0;i<4;i++){const a=i*1.57+this._t*.07;ctx.beginPath();ctx.arc(sx+Math.cos(a)*r*.36,sy+Math.sin(a)*r*.36,r*.28,0,Math.PI*2);ctx.strokeStyle=`rgba(100,240,255,${0.28+0.18*Math.sin(this._t*2+i)})`;ctx.lineWidth=r*.1;ctx.stroke();}
    ctx.restore();
    ctx.beginPath();ctx.arc(sx,sy,r,0,Math.PI*2);ctx.strokeStyle='rgba(80,220,255,0.6)';ctx.lineWidth=2.5;ctx.stroke();
    // Indicador visual de ricochete em objetos afetados
    objects.forEach(o=>{
      if(!o._gvRicochet||o._gvRicochet<=0||o.dead)return;
      const{x:ox,y:oy}=worldToScreen(o.x,o.y);const or2=o.sr();
      const prog=o._gvRicochet/5.0;
      ctx.beginPath();ctx.arc(ox,oy,or2*(1.3+0.2*Math.sin(o._gvRicochet*15)),0,Math.PI*2);
      ctx.strokeStyle=`rgba(80,220,255,${prog*0.7})`;ctx.lineWidth=2;ctx.stroke();
      const rg=ctx.createRadialGradient(ox,oy,or2,ox,oy,or2*2);
      rg.addColorStop(0,`rgba(60,200,255,${prog*0.25})`);rg.addColorStop(1,'transparent');
      ctx.beginPath();ctx.arc(ox,oy,or2*2,0,Math.PI*2);ctx.fillStyle=rg;ctx.fill();
    });
  }
}
// ─── 20. QUASI-STAR ──────────────────────────────────────────────
// Buraco Negro Interno: atrai planetas de longe, aquece e arrasta objetos ao centro
class QuasiStar extends CelestialObject{
  constructor(wx,wy){
    super(wx,wy,'quasiStar');
    this.radius=rand(55,95);this.mass=this.radius*15;
    this._t=rand(0,Math.PI*2);
    this._absorbRange=this.radius*1.5;this._absorbs=0;
    this._bhPulse=0;this._armTimer=0;this._arms=[];
    this._conv=Array.from({length:14},(_,i)=>({a:i*.449,spd:rand(.012,.03),r:rand(.15,.2)}));
    this._fireTrails=[];
    this.color='#ff9922';
  }
  update(dt){
    this._t+=dt;this._bhPulse+=dt*2.5;this._armTimer+=dt;
    if(this._armTimer>.12){
      this._armTimer=0;const a=rand(0,Math.PI*2);const d=rand(this.radius*1.5,this.radius*3.5);
      this._arms.push({x:this.x+Math.cos(a)*d,y:this.y+Math.sin(a)*d,angle:a,dist:d,life:rand(1,2.5),maxLife:2.5,spd:rand(1.5,3)});
    }
    this._arms=this._arms.filter(arm=>{
      arm.life-=dt;arm.angle+=arm.spd*dt*(1-arm.life/arm.maxLife+.3);
      arm.dist=Math.max(this.radius*.8,arm.dist-dt*arm.dist*.8);
      arm.x=this.x+Math.cos(arm.angle)*arm.dist;arm.y=this.y+Math.sin(arm.angle)*arm.dist;
      return arm.life>0&&arm.dist>this.radius*.85;
    });
    this._conv.forEach(c=>c.a+=c.spd*dt);
    this._fireTrails=this._fireTrails.filter(p=>{p.life-=dt;p.x+=p.vx*dt;p.y+=p.vy*dt;p.vx*=0.9;p.vy*=0.9;return p.life>0;});
    if(!window._invasionActive){
      // Absorção no raio interno
      objects.forEach(o=>{
        if(o===this||o.dead||o.immune)return;
        const d=dist(o,this);if(d>this._absorbRange+o.radius)return;
        if(o.type==='blackhole'||o.type==='whitehole'||o.type==='wormhole')return;
        o.dead=true;this._absorbs++;this.radius=Math.min(180,this.radius+0.5);this._absorbRange=this.radius*1.5;
        for(let i=0;i<8;i++)particles.push({x:o.x,y:o.y,vx:rand(-3,3),vy:rand(-3,3),r:rand(2,5),alpha:1,color:'#ffaa44'});
      });
      objects.forEach(o=>{
        if(o===this||o.dead||o.immune||o.fixed)return;
        const d=dist(o,this);
        // Planetas e luas atraídos de LONGAS distâncias
        const isOrbitType=o.type==='planet'||o.type==='moon'||PP_ORBIT_TYPES.includes(o.type);
        const pullRange=isOrbitType?this.radius*22:this.radius*8;
        if(d>pullRange||d<1)return;
        const fBase=isOrbitType?18000:11000;
        const f=fBase/(d*d+150),nx=(this.x-o.x)/d,ny=(this.y-o.y)/d;
        o.vx=(o.vx||0)+nx*f*dt;o.vy=(o.vy||0)+ny*f*dt;
        if(isOrbitType)o.parent=null;
        // Aquece objetos próximos: rastro de fogo indo ao centro
        if(d<this.radius*6){
          const heat=(1-d/(this.radius*6));
          o._quasiHeat=Math.min(1,(o._quasiHeat||0)+dt*heat*0.6);
          if(Math.random()<heat*0.18*dt*60){
            this._fireTrails.push({
              x:o.x+rand(-o.radius,o.radius),y:o.y+rand(-o.radius,o.radius),
              vx:nx*rand(25,65)+rand(-12,12),vy:ny*rand(25,65)+rand(-12,12),
              life:rand(0.4,1.2),maxLife:1.2,hue:rand(18,45)
            });
          }
        } else {
          if(o._quasiHeat)o._quasiHeat=Math.max(0,(o._quasiHeat||0)-dt*0.3);
        }
      });
    }
  }
  draw(){
    const sx=this.sx(),sy=this.sy();
    const r=this.sr()*(1+0.08*Math.sin(this._t*1.1));
    // Rastros de fogo indo ao centro
    this._fireTrails.forEach(p=>{
      const{x:px,y:py}=worldToScreen(p.x,p.y);const lf=p.life/p.maxLife;
      ctx.beginPath();ctx.arc(px,py,3*cam.zoom*lf,0,Math.PI*2);
      ctx.fillStyle=`hsla(${p.hue},100%,${~~(60+40*lf)}%,${lf*.8})`;ctx.fill();
    });
    // Halo de calor em objetos próximos
    objects.forEach(o=>{
      if(!o._quasiHeat||o._quasiHeat<=0||o.dead)return;
      const{x:ox,y:oy}=worldToScreen(o.x,o.y);const or2=o.sr();const h=o._quasiHeat;
      const hg=ctx.createRadialGradient(ox,oy,or2*.8,ox,oy,or2*(1.5+h*.8));
      hg.addColorStop(0,`rgba(255,${~~(120-h*80)},0,${h*0.55})`);hg.addColorStop(1,'transparent');
      ctx.beginPath();ctx.arc(ox,oy,or2*(1.5+h*.8),0,Math.PI*2);ctx.fillStyle=hg;ctx.fill();
    });
    // Braços de acreção
    this._arms.forEach(arm=>{
      const {x:ax,y:ay}=worldToScreen(arm.x,arm.y);const lf=arm.life/arm.maxLife;const age=1-lf;
      ctx.beginPath();ctx.arc(ax,ay,3.5*cam.zoom*lf,0,Math.PI*2);ctx.fillStyle=`rgba(255,${~~(160+age*60)},40,${lf*.65})`;ctx.fill();
    });
    for(let i=4;i>=0;i--){
      const gg=ctx.createRadialGradient(sx,sy,r*.8,sx,sy,r*(1.5+i*.45));
      gg.addColorStop(0,`rgba(255,155,40,${0.16/(i+1)})`);gg.addColorStop(1,'transparent');
      ctx.beginPath();ctx.arc(sx,sy,r*(1.5+i*.45),0,Math.PI*2);ctx.fillStyle=gg;ctx.fill();
    }
    const g=ctx.createRadialGradient(sx-r*.18,sy-r*.18,r*.05,sx,sy,r);
    g.addColorStop(0,'rgba(255,255,190,.97)');g.addColorStop(.22,'#ffcc44');g.addColorStop(.50,'#ff8800');g.addColorStop(.78,'#771100');g.addColorStop(1,'#0a0000');
    ctx.beginPath();ctx.arc(sx,sy,r,0,Math.PI*2);ctx.fillStyle=g;ctx.fill();
    ctx.save();ctx.beginPath();ctx.arc(sx,sy,r,0,Math.PI*2);ctx.clip();
    this._conv.forEach(c=>{
      const bx=sx+Math.cos(c.a)*r*.56,by=sy+Math.sin(c.a)*r*.52;
      const cg=ctx.createRadialGradient(bx,by,0,bx,by,r*c.r);
      cg.addColorStop(0,`rgba(255,${~~(160+Math.sin(this._t+c.a)*60)},20,${0.18+0.1*Math.sin(this._t*1.5+c.a)})`);cg.addColorStop(1,'transparent');
      ctx.beginPath();ctx.arc(bx,by,r*c.r,0,Math.PI*2);ctx.fillStyle=cg;ctx.fill();
    });
    // BH interno
    const bhR=r*(.16+.05*Math.sin(this._bhPulse));
    ctx.beginPath();ctx.arc(sx,sy,bhR*1.8,0,Math.PI*2);
    const bhA=ctx.createRadialGradient(sx,sy,bhR*.6,sx,sy,bhR*1.8);
    bhA.addColorStop(0,'rgba(0,0,0,.95)');bhA.addColorStop(.7,'rgba(0,0,0,.7)');bhA.addColorStop(1,'transparent');
    ctx.fillStyle=bhA;ctx.fill();
    ctx.beginPath();ctx.arc(sx,sy,bhR,0,Math.PI*2);ctx.fillStyle='#000000';ctx.fill();
    ctx.save();ctx.translate(sx,sy);ctx.scale(1,.28);ctx.rotate(this._bhPulse*.15);
    ctx.beginPath();ctx.arc(0,0,bhR*2.2,0,Math.PI*2);
    ctx.strokeStyle=`rgba(255,160,40,${0.5+0.2*Math.sin(this._bhPulse)})`;ctx.lineWidth=bhR*.8;ctx.stroke();
    ctx.restore();
    ctx.restore();
    ctx.beginPath();ctx.arc(sx,sy,r,0,Math.PI*2);ctx.strokeStyle='rgba(255,180,60,0.3)';ctx.lineWidth=3;ctx.stroke();
    if(this._absorbs>0&&sandboxMode){ctx.font=`bold ${Math.max(6,r*.1)}px 'Courier New'`;ctx.fillStyle='rgba(255,200,80,.65)';ctx.textAlign='center';ctx.fillText(`⬛+${this._absorbs}`,sx+r*.75,sy-r*.65);ctx.textAlign='left';}
  }
}

// ═══════════════════════════════════════════════════════════════════
//  PACOTE EXÓTICO — 20 astros desbloqueados no Rank 28
//  Cada um tem função, física e visual psicodélico únicos.
//  (Parte 1/2 — primeiros 10 tipos)
// ═══════════════════════════════════════════════════════════════════

const EX_TYPES = ['exDarkStar','exLittleRedDot','exMonsterStar','exIronStar','exCosmicString',
  'exBlitzar','exBeStar','exBinaryNeutronStar','exHoagObject','exDarkGalaxy',
  'exRedHole','exNakedSingularity','exBlanet','exBrownSubdwarf','exQBall','exGeon',
  'exDomainWall','exSpacetimeCrystal','exKugelblitz','exDarkEnergyStar'];

// ─── 1. ESTRELA ESCURA ───────────────────────────────────────────
// Halo de matéria escura: puxa objetos próximos e os "contamina" com tinta violeta
// ─── 1. ESTRELA ESCURA ───────────────────────────────────────────
// Halo de matéria escura: puxa objetos próximos e os "contamina" com tinta violeta.
// LÓGICA: quanto mais tempo um objeto fica no halo, maior o _darkTint.
// Com tint >=0.8 e massa >=5, o objeto fica "corrompido" e passa a empurrar
// outros objetos menores (comportamento parasita).
class DarkStar extends CelestialObject{
  constructor(wx,wy){
    super(wx,wy,'exDarkStar');
    this.radius=rand(10,18);this.mass=this.radius*22;
    this._t=rand(0,Math.PI*2);
    this._haloR=this.radius*9;
    this._ripples=[];this._rippleTimer=0;
    this._lensRings=Array.from({length:4},(_,i)=>({rMul:1.4+i*.5,spd:rand(.2,.5)*(i%2===0?1:-1),ph:rand(0,6)}));
    this._orbiters=Array.from({length:6},(_,i)=>({a:i*(Math.PI*2/6)+rand(0,.4),d:rand(2.2,4.5),spd:rand(.15,.4)*(i%2===0?1:-1),s:rand(.05,.12)}));
    this.color='#2a0a40';
  }
  update(dt){
    this._t+=dt;this._rippleTimer+=dt;
    this._lensRings.forEach(r=>r.ph+=r.spd*dt);
    this._orbiters.forEach(o=>o.a+=o.spd*dt);
    if(this._rippleTimer>2.4){this._rippleTimer=0;this._ripples.push({r:this.radius,a:.4});}
    this._ripples=this._ripples.filter(rp=>{rp.r+=dt*this._haloR*.18;rp.a-=dt*.12;return rp.a>0;});
    objects.forEach(o=>{
      if(o===this||o.dead||o.fixed)return;
      const d=dist(o,this);if(d>this._haloR||d<1)return;
      // atrai suavemente para dentro do halo
      const f=(this.mass*.00018)*(1-d/this._haloR);
      const nx=(this.x-o.x)/d,ny=(this.y-o.y)/d;
      o.vx=(o.vx||0)+nx*f*dt*30;o.vy=(o.vy||0)+ny*f*dt*30;
      o._darkTint=Math.min(1,(o._darkTint||0)+dt*.25);
    });
    objects.forEach(o=>{ if(o._darkTint>0&&dist(o,this)>this._haloR) o._darkTint=Math.max(0,o._darkTint-dt*.3); });
    // LÓGICA: objetos corrompidos (tint>=0.8 e massa>=5) empurram vizinhos menores
    objects.forEach(o=>{
      if(!o._darkTint||o._darkTint<.8||o.dead||(o.mass||0)<5)return;
      objects.forEach(t2=>{
        if(t2===o||t2===this||t2.dead||(t2.mass||0)>=(o.mass||0))return;
        const d2=dist(o,t2);if(d2>o.radius*5||d2<1)return;
        const f2=4*(1-d2/(o.radius*5));
        t2.vx=(t2.vx||0)+(t2.x-o.x)/d2*f2;
        t2.vy=(t2.vy||0)+(t2.y-o.y)/d2*f2;
      });
    });
  }
  draw(){
    const sx=this.sx(),sy=this.sy(),r=this.sr();
    const haloR=this._haloR*cam.zoom;
    const halo=ctx.createRadialGradient(sx,sy,r*.5,sx,sy,haloR);
    halo.addColorStop(0,'rgba(80,20,120,.16)');halo.addColorStop(.4,'rgba(40,0,70,.06)');halo.addColorStop(1,'transparent');
    ctx.beginPath();ctx.arc(sx,sy,haloR,0,Math.PI*2);ctx.fillStyle=halo;ctx.fill();
    this._ripples.forEach(rp=>{
      ctx.beginPath();ctx.arc(sx,sy,rp.r*cam.zoom,0,Math.PI*2);
      ctx.strokeStyle=`rgba(160,80,255,${rp.a})`;ctx.lineWidth=1.5;ctx.stroke();
    });
    this._lensRings.forEach(ring=>{
      const rr=r*ring.rMul;
      ctx.save();ctx.translate(sx,sy);ctx.rotate(ring.ph);
      ctx.beginPath();ctx.ellipse(0,0,rr,rr*.32,0,0,Math.PI*2);
      const al=0.12+0.08*Math.sin(this._t*1.3+ring.ph);
      ctx.strokeStyle=`rgba(${170+Math.sin(ring.ph)*40},${100+Math.cos(ring.ph)*40},255,${al})`;
      ctx.lineWidth=1.2;ctx.stroke();ctx.restore();
    });
    const pulse=0.5+0.5*Math.sin(this._t*1.4);
    const g=ctx.createRadialGradient(sx,sy,0,sx,sy,r);
    g.addColorStop(0,`rgba(${60+pulse*40},${10+pulse*20},${100+pulse*60},.9)`);
    g.addColorStop(.6,'rgba(20,0,30,.85)');g.addColorStop(1,'rgba(0,0,0,.95)');
    ctx.beginPath();ctx.arc(sx,sy,r,0,Math.PI*2);ctx.fillStyle=g;ctx.fill();
    ctx.beginPath();ctx.arc(sx,sy,r*(1+0.05*Math.sin(this._t*3)),0,Math.PI*2);
    ctx.strokeStyle=`rgba(170,90,255,${0.25+0.15*pulse})`;ctx.lineWidth=1.5;ctx.stroke();
    this._orbiters.forEach(o=>{
      const rr=r*o.d;
      const bx=sx+Math.cos(o.a)*rr,by=sy+Math.sin(o.a)*rr*.4;
      const al=0.18+0.12*Math.sin(this._t*2+o.a);
      const og=ctx.createRadialGradient(bx,by,0,bx,by,r*o.s*3);
      og.addColorStop(0,`rgba(140,80,220,${al})`);og.addColorStop(1,'transparent');
      ctx.beginPath();ctx.arc(bx,by,r*o.s*3,0,Math.PI*2);ctx.fillStyle=og;ctx.fill();
    });
    objects.forEach(o=>{
      if(!o._darkTint||o.dead||o===this)return;
      const {x:ox,y:oy}=worldToScreen(o.x,o.y);const orr=o.sr();
      ctx.beginPath();ctx.arc(ox,oy,orr*1.25,0,Math.PI*2);
      ctx.strokeStyle=`rgba(150,60,255,${o._darkTint*.5})`;ctx.lineWidth=1;ctx.stroke();
      if(o._darkTint>.5){
        const midx=(sx+ox)/2+Math.sin(this._t*6+(o.id||0))*10,midy=(sy+oy)/2+Math.cos(this._t*6+(o.id||0))*10;
        ctx.beginPath();ctx.moveTo(sx,sy);ctx.quadraticCurveTo(midx,midy,ox,oy);
        ctx.strokeStyle=`rgba(180,100,255,${(o._darkTint-.5)*0.6*(0.6+0.4*Math.sin(this._t*10))})`;
        ctx.lineWidth=1;ctx.stroke();
      }
      // ícone de "corrompido"
      if(o._darkTint>=.8&&sandboxMode){
        ctx.font=`${Math.max(8,orr*.8)}px 'Courier New'`;ctx.fillStyle='rgba(200,100,255,.7)';
        ctx.textAlign='center';ctx.fillText('☠',ox,oy-orr-4);ctx.textAlign='left';
      }
    });
  }
}

// ─── 2. PEQUENO PONTO VERMELHO ───────────────────────────────────
// LÓGICA: acumula "energia" absorvendo calor de objetos quentes próximos
// (estrelas, pulsares). Quanto mais energia acumulada, mais frequentes e
// violentos os flashes — e ao atingir carga máxima, dispara um mega-pulso
// que converte objetos muito pequenos (meteoros, cometas) em poeira.
class LittleRedDot extends CelestialObject{
  constructor(wx,wy){
    super(wx,wy,'exLittleRedDot');
    this.radius=rand(3,5);this.mass=this.radius*40;
    this._t=rand(0,Math.PI*2);
    this._energy=0;this._maxEnergy=100;
    this._flashTimer=rand(0,1.5);this._flashAlpha=0;
    this._megaReady=false;
    this.color='#ff1133';
  }
  update(dt){
    this._t+=dt;this._flashTimer-=dt;
    if(this._flashAlpha>0)this._flashAlpha=Math.max(0,this._flashAlpha-dt*2.2);
    // absorve calor de estrelas e pulsares próximos
    objects.forEach(o=>{
      if(o===this||o.dead)return;
      const hotTypes=['star','cepheid','protostar','blazar','pulsar','exBeStar','exMonsterStar'];
      if(!hotTypes.includes(o.type))return;
      const d=dist(o,this);if(d>this.radius*40||d<1)return;
      this._energy=Math.min(this._maxEnergy,this._energy+(1-d/(this.radius*40))*dt*8);
    });
    const chargeRatio=this._energy/this._maxEnergy;
    const interval=Math.max(.25,1.8-chargeRatio*1.4);
    if(this._flashTimer<=0){
      this._flashTimer=interval;this._flashAlpha=1;
      if(this._energy>=this._maxEnergy&&!this._megaReady){
        this._megaReady=true;
      }
      if(this._megaReady){
        // mega-pulso: converte meteoros/cometas muito próximos em poeira
        objects.forEach(o=>{
          if(o===this||o.dead)return;
          const d=dist(o,this);if(d>this.radius*40||d<1)return;
          const f=(22+chargeRatio*30)*(1-d/(this.radius*40));
          const nx=(o.x-this.x)/d,ny=(o.y-this.y)/d;
          o.vx=(o.vx||0)+nx*f;o.vy=(o.vy||0)+ny*f;
          if((o.type==='meteor'||o.type==='comet')&&d<this.radius*15){
            spawnExplosion(o.x,o.y,.4,false);o.dead=true;
          }
        });
        this._energy=0;this._megaReady=false;
      } else {
        objects.forEach(o=>{
          if(o===this||o.dead||o.radius>6)return;
          const d=dist(o,this);if(d>this.radius*25||d<1)return;
          const f=22*(1-d/(this.radius*25));
          o.vx=(o.vx||0)+(o.x-this.x)/d*f;o.vy=(o.vy||0)+(o.y-this.y)/d*f;
        });
      }
    }
  }
  draw(){
    const sx=this.sx(),sy=this.sy(),r=this.sr();
    const chargeRatio=this._energy/this._maxEnergy;
    const flashR=r*(3+this._flashAlpha*9*(1+chargeRatio*2));
    if(this._flashAlpha>0){
      const fg=ctx.createRadialGradient(sx,sy,0,sx,sy,flashR);
      const col=this._megaReady?'255,200,50':'255,60,40';
      fg.addColorStop(0,`rgba(${col},${this._flashAlpha*.65})`);
      fg.addColorStop(.5,`rgba(${col},${this._flashAlpha*.22})`);
      fg.addColorStop(1,'transparent');
      ctx.beginPath();ctx.arc(sx,sy,flashR,0,Math.PI*2);ctx.fillStyle=fg;ctx.fill();
    }
    const aura=ctx.createRadialGradient(sx,sy,0,sx,sy,r*6);
    aura.addColorStop(0,`rgba(${255},${Math.round(30+chargeRatio*80)},30,.5)`);
    aura.addColorStop(.3,'rgba(200,0,30,.15)');aura.addColorStop(1,'transparent');
    ctx.beginPath();ctx.arc(sx,sy,r*6,0,Math.PI*2);ctx.fillStyle=aura;ctx.fill();
    // barra de carga visual (anel de energia)
    if(chargeRatio>0.05){
      ctx.beginPath();ctx.arc(sx,sy,r*2.2,-.5*Math.PI,-.5*Math.PI+Math.PI*2*chargeRatio);
      ctx.strokeStyle=`rgba(255,${Math.round(200*chargeRatio)},0,${.5+chargeRatio*.4})`;
      ctx.lineWidth=Math.max(1,r*.5);ctx.stroke();
    }
    const g=ctx.createRadialGradient(sx,sy,0,sx,sy,r);
    g.addColorStop(0,'#ffe0c0');g.addColorStop(.3,'#ff4422');g.addColorStop(1,'#660000');
    ctx.beginPath();ctx.arc(sx,sy,Math.max(1.2,r),0,Math.PI*2);ctx.fillStyle=g;ctx.fill();
    if(sandboxMode&&chargeRatio>0){
      ctx.font=`${Math.max(7,r*1.2)}px 'Courier New'`;ctx.fillStyle='rgba(255,160,30,.8)';
      ctx.textAlign='center';ctx.fillText(`${Math.round(chargeRatio*100)}%`,sx,sy-r*3);ctx.textAlign='left';
    }
  }
}

// ─── 3. ESTRELA MONSTRO ──────────────────────────────────────────
// LÓGICA: "come" objetos que chegam perto (pequenos absorvidos, grandes empurrados).
// Cada absorção aumenta radius e mass. Se crescer demais, implode numa supernova
// gigante e renasce como um Buraco Negro.
class MonsterStar extends CelestialObject{
  constructor(wx,wy){
    super(wx,wy,'exMonsterStar');
    this.radius=rand(34,52);this.mass=this.radius*30;
    this._t=rand(0,Math.PI*2);
    this._cells=Array.from({length:9},()=>({a:rand(0,Math.PI*2),d:rand(.2,.85),s:rand(.08,.22),spd:rand(.3,1.1),ph:rand(0,6),hue:rand(0,360)}));
    this._shockTimer=rand(4,7);this._shockwaves=[];
    this._absorbCount=0;this._maxRadius=120;
    this.color='#ff66cc';
  }
  update(dt){
    this._t+=dt;this._shockTimer-=dt;
    this._cells.forEach(c=>c.a+=c.spd*dt*.2);
    this._shockwaves=this._shockwaves.filter(s=>{s.r+=dt*this.radius*4;s.a-=dt*.5;return s.a>0;});
    // pulso periódico empurrando objetos grandes
    if(this._shockTimer<=0){
      this._shockTimer=rand(5,9);this._shockwaves.push({r:this.radius,a:.8});
      objects.forEach(o=>{
        if(o===this||o.dead||o.fixed)return;
        const d=dist(o,this);if(d>this.radius*10||d<1)return;
        if(o.radius>=this.radius*.3){
          // grande: empurra
          const f=60*(1-d/(this.radius*10)),nx=(o.x-this.x)/d,ny=(o.y-this.y)/d;
          o.vx=(o.vx||0)+nx*f;o.vy=(o.vy||0)+ny*f;
        } else {
          // pequeno: absorve se tocar
          if(d<this.radius*1.3){
            spawnExplosion(o.x,o.y,.3,false);o.dead=true;
            this.radius=Math.min(this._maxRadius,this.radius+o.radius*.12);
            this.mass=this.radius*30;this._absorbCount++;
          }
        }
      });
    }
    // quando cresce demais: supernova + Buraco Negro
    if(this.radius>=this._maxRadius&&!this._dying){
      this._dying=true;
      spawnExplosion(this.x,this.y,2.2,true);
      try{
        const bh=new BlackHole(this.x,this.y);
        bh.radius=rand(22,30);bh.mass=bh.radius*70;
        pendingObjects.push(bh);
      }catch(e){}
      this.dead=true;
    }
  }
  draw(){
    const sx=this.sx(),sy=this.sy(),r=this.sr()*(1+0.04*Math.sin(this._t*1.1));
    this._shockwaves.forEach(s=>{
      ctx.beginPath();ctx.arc(sx,sy,s.r*cam.zoom,0,Math.PI*2);
      ctx.strokeStyle=`rgba(255,120,220,${s.a})`;ctx.lineWidth=2.5;ctx.stroke();
    });
    const aura=ctx.createRadialGradient(sx,sy,r*.9,sx,sy,r*2.4);
    aura.addColorStop(0,`hsla(${(this._t*30)%360},100%,65%,.22)`);aura.addColorStop(1,'transparent');
    ctx.beginPath();ctx.arc(sx,sy,r*2.4,0,Math.PI*2);ctx.fillStyle=aura;ctx.fill();
    const g=ctx.createRadialGradient(sx-r*.3,sy-r*.3,r*.05,sx,sy,r);
    g.addColorStop(0,'#fff0ff');g.addColorStop(.35,`hsl(${(this._t*40)%360},100%,70%)`);
    g.addColorStop(.7,`hsl(${(this._t*40+80)%360},90%,45%)`);g.addColorStop(1,'#330033');
    ctx.beginPath();ctx.arc(sx,sy,r,0,Math.PI*2);ctx.fillStyle=g;ctx.fill();
    ctx.save();ctx.beginPath();ctx.arc(sx,sy,r,0,Math.PI*2);ctx.clip();
    this._cells.forEach(c=>{
      const bx=sx+Math.cos(c.a)*r*c.d,by=sy+Math.sin(c.a)*r*c.d;
      const al=0.35+0.2*Math.sin(this._t*2+c.ph);
      ctx.beginPath();ctx.arc(bx,by,r*c.s,0,Math.PI*2);
      ctx.fillStyle=`hsla(${(c.hue+this._t*50)%360},100%,65%,${al})`;ctx.fill();
    });
    ctx.restore();
    ctx.beginPath();ctx.arc(sx,sy,r,0,Math.PI*2);
    ctx.strokeStyle=`hsla(${(this._t*40)%360},100%,75%,.5)`;ctx.lineWidth=2;ctx.stroke();
    // barra de tamanho ("fome")
    if(sandboxMode&&this._absorbCount>0){
      const pct=this.radius/this._maxRadius;
      ctx.font=`${Math.max(7,r*.1)}px 'Courier New'`;ctx.fillStyle='rgba(255,180,255,.8)';
      ctx.textAlign='center';ctx.fillText(`👾 ${this._absorbCount} absorções`,sx,sy-r*1.4);ctx.textAlign='left';
    }
  }
}

// ─── 4. ESTRELA DE FERRO (EXÓTICA) ───────────────────────────────
// LÓGICA: "envelhece" ao longo do tempo (tunelamento quântico lentíssimo).
// Emite um flash azul a cada tunelamento. Se outro objeto tocar a superfície,
// transfere um fragmento de ferro (cria um Meteoro de alta velocidade) e
// encolhe um pouco. Ao atingir raio mínimo, desintegra-se silenciosamente.
class ExoticIronStar extends CelestialObject{
  constructor(wx,wy){
    super(wx,wy,'exIronStar');
    this.radius=rand(16,26);this._birthRadius=this.radius;this.mass=this.radius*18;
    this._t=rand(0,Math.PI*2);
    this._cracks=Array.from({length:7},()=>({a:rand(0,Math.PI*2),len:rand(.3,.9),w:rand(.01,.03)}));
    this._sparks=[];this._tunnelTimer=rand(3,6);
    this._fragmentCooldown=0;
    this.color='#888899';
  }
  update(dt){
    this._t+=dt;this._tunnelTimer-=dt;this._fragmentCooldown=Math.max(0,this._fragmentCooldown-dt);
    this._sparks=this._sparks.filter(s=>{s.life-=dt;return s.life>0;});
    if(this._tunnelTimer<=0){
      this._tunnelTimer=rand(4,9);
      this._sparks.push({a:rand(0,Math.PI*2),life:.6,maxLife:.6});
      this.radius=Math.max(5,this.radius-0.02);
      this.mass=this.radius*18;
    }
    // fragmentação ao contato
    if(this._fragmentCooldown<=0){
      objects.forEach(o=>{
        if(o===this||o.dead||o.fixed)return;
        if(dist(o,this)<this.radius+o.radius){
          this._fragmentCooldown=2;
          try{
            const m=new Meteor(this.x+rand(-this.radius,this.radius),this.y+rand(-this.radius,this.radius));
            const ej=rand(30,55),ea=rand(0,Math.PI*2);
            m.vx=Math.cos(ea)*ej;m.vy=Math.sin(ea)*ej;
            m.color='#aabbcc';
            pendingObjects.push(m);
          }catch(e){}
          this.radius=Math.max(5,this.radius-.8);
          this.mass=this.radius*18;
        }
      });
    }
    if(this.radius<=5&&!this._dead){this._dead=true;spawnExplosion(this.x,this.y,.4,false);this.dead=true;}
  }
  draw(){
    const sx=this.sx(),sy=this.sy(),r=this.sr();
    const sheenShift=this._t*40;
    const ageFrac=1-(this.radius/this._birthRadius);
    const g=ctx.createRadialGradient(sx-r*.35,sy-r*.35,r*.05,sx,sy,r);
    g.addColorStop(0,`hsl(${sheenShift%360},${Math.round(40-ageFrac*20)}%,${Math.round(70-ageFrac*30)}%)`);
    g.addColorStop(.35,`hsl(${(sheenShift+90)%360},35%,45%)`);
    g.addColorStop(.7,`hsl(${(sheenShift+200)%360},30%,28%)`);
    g.addColorStop(1,'#15151c');
    ctx.beginPath();ctx.arc(sx,sy,r,0,Math.PI*2);ctx.fillStyle=g;ctx.fill();
    ctx.save();ctx.beginPath();ctx.arc(sx,sy,r,0,Math.PI*2);ctx.clip();
    this._cracks.forEach(c=>{
      ctx.beginPath();ctx.moveTo(sx,sy);
      ctx.lineTo(sx+Math.cos(c.a)*r*c.len,sy+Math.sin(c.a)*r*c.len);
      ctx.strokeStyle=`hsla(${(sheenShift+180)%360},60%,60%,${.25+ageFrac*.4})`;
      ctx.lineWidth=Math.max(.5,r*c.w);ctx.stroke();
    });
    this._sparks.forEach(s=>{
      const al=s.life/s.maxLife;
      const bx=sx+Math.cos(s.a)*r*.85,by=sy+Math.sin(s.a)*r*.85;
      const sg=ctx.createRadialGradient(bx,by,0,bx,by,r*.4);
      sg.addColorStop(0,`rgba(140,200,255,${al})`);sg.addColorStop(1,'transparent');
      ctx.beginPath();ctx.arc(bx,by,r*.4,0,Math.PI*2);ctx.fillStyle=sg;ctx.fill();
    });
    ctx.restore();
    ctx.beginPath();ctx.arc(sx,sy,r,0,Math.PI*2);
    ctx.strokeStyle=`rgba(200,200,220,${.15+ageFrac*.3})`;ctx.lineWidth=1.5;ctx.stroke();
    if(sandboxMode){
      ctx.font=`${Math.max(7,r*.35)}px 'Courier New'`;ctx.fillStyle='rgba(180,200,230,.6)';
      ctx.textAlign='center';ctx.fillText(`${Math.round(ageFrac*100)}% decaído`,sx,sy+r+9*cam.zoom);ctx.textAlign='left';
    }
  }
}

// ─── 5. CORDA CÓSMICA (EXÓTICA) ──────────────────────────────────
// LÓGICA: A corda vibra e, quando dois objetos de lados opostos dela ficam
// alinhados na perpendicular ao mesmo tempo, ela cria um "salto" — teletransporta
// ambos para posições invertidas (efeito de "espelho cósmico").
class ExoticCosmicString extends CelestialObject{
  constructor(wx,wy){
    super(wx,wy,'exCosmicString');
    this.radius=8;this.mass=4000;
    this._t=rand(0,Math.PI*2);
    this._len=rand(300,500);
    this._angle=rand(0,Math.PI);
    this._segs=14;
    this._warpCooldown=0;
    this._warpFlash=0;
    this.color='#88ffee';
  }
  update(dt){
    this._t+=dt;
    this._warpCooldown=Math.max(0,this._warpCooldown-dt);
    this._warpFlash=Math.max(0,this._warpFlash-dt*2);
    const dx=Math.cos(this._angle),dy=Math.sin(this._angle);
    // atração perpendicular padrão
    objects.forEach(o=>{
      if(o===this||o.dead||o.fixed)return;
      const relX=o.x-this.x,relY=o.y-this.y;
      const proj=relX*dx+relY*dy;
      if(Math.abs(proj)>this._len/2)return;
      const px=this.x+dx*proj,py=this.y+dy*proj;
      const d=Math.hypot(o.x-px,o.y-py);if(d<1||d>140)return;
      const f=2.4*(1-d/140);
      const nx=(px-o.x)/d,ny=(py-o.y)/d;
      o.vx=(o.vx||0)+nx*f*dt*30;o.vy=(o.vy||0)+ny*f*dt*30;
    });
    // LÓGICA DE ESPELHO: encontra pares opostos próximos da corda e teletransporta
    if(this._warpCooldown<=0){
      const near=objects.filter(o=>{
        if(o===this||o.dead||o.fixed)return false;
        const relX=o.x-this.x,relY=o.y-this.y;
        const proj=relX*dx+relY*dy;
        if(Math.abs(proj)>this._len/2)return false;
        const px=this.x+dx*proj,py=this.y+dy*proj;
        return Math.hypot(o.x-px,o.y-py)<60;
      });
      // pares de lados opostos
      for(let i=0;i<near.length;i++){
        for(let j=i+1;j<near.length;j++){
          const a=near[i],b=near[j];
          const sideA=(a.x-this.x)*(-dy)+(a.y-this.y)*dx;
          const sideB=(b.x-this.x)*(-dy)+(b.y-this.y)*dx;
          if(Math.sign(sideA)!==Math.sign(sideB)&&dist(a,b)<200){
            // teletransporta: troca posições refletidas na corda
            const [ax,ay,bx2,by]=[a.x,a.y,b.x,b.y];
            const relAx=ax-this.x,relAy=ay-this.y;
            const projA=relAx*dx+relAy*dy;
            const perpA=relAx*(-dy)+relAy*dx;
            a.x=this.x+dx*projA+(-dy)*(-perpA);
            a.y=this.y+dy*projA+dx*(-perpA);
            const relBx=bx2-this.x,relBy=by-this.y;
            const projB=relBx*dx+relBy*dy;
            const perpB=relBx*(-dy)+relBy*dx;
            b.x=this.x+dx*projB+(-dy)*(-perpB);
            b.y=this.y+dy*projB+dx*(-perpB);
            // inverte velocidades perpendiculares
            const avp=a.vx*(-dy)+a.vy*dx;
            a.vx-=2*(-dy)*avp;a.vy-=2*dx*avp;
            const bvp=b.vx*(-dy)+b.vy*dx;
            b.vx-=2*(-dy)*bvp;b.vy-=2*dx*bvp;
            this._warpFlash=1;this._warpCooldown=rand(3,6);
            break;
          }
        }
      }
    }
  }
  draw(){
    const dx=Math.cos(this._angle),dy=Math.sin(this._angle);
    const x1=this.x-dx*this._len/2,y1=this.y-dy*this._len/2;
    const x2=this.x+dx*this._len/2,y2=this.y+dy*this._len/2;
    // flash de warp
    if(this._warpFlash>0){
      const p1=worldToScreen(x1,y1),p2=worldToScreen(x2,y2);
      ctx.beginPath();ctx.moveTo(p1.x,p1.y);ctx.lineTo(p2.x,p2.y);
      ctx.strokeStyle=`rgba(255,255,255,${this._warpFlash})`;ctx.lineWidth=6;ctx.stroke();
    }
    ctx.beginPath();
    for(let i=0;i<=this._segs;i++){
      const t=i/this._segs;
      const bx=x1+(x2-x1)*t,by=y1+(y2-y1)*t;
      const wob=Math.sin(this._t*3+t*Math.PI*4)*8;
      const px=bx-dy*wob,py=by+dx*wob;
      const sp=worldToScreen(px,py);
      if(i===0)ctx.moveTo(sp.x,sp.y);else ctx.lineTo(sp.x,sp.y);
    }
    const p1=worldToScreen(x1,y1),p2=worldToScreen(x2,y2);
    const grad=ctx.createLinearGradient(p1.x,p1.y,p2.x,p2.y);
    for(let i=0;i<=6;i++){grad.addColorStop(i/6,`hsl(${(this._t*60+i*60)%360},100%,65%)`);}
    ctx.strokeStyle=grad;ctx.lineWidth=2.5;ctx.shadowColor='rgba(120,255,255,.6)';ctx.shadowBlur=10;ctx.stroke();ctx.shadowBlur=0;
    [p1,p2].forEach(p=>{
      const hg=ctx.createRadialGradient(p.x,p.y,0,p.x,p.y,18);
      hg.addColorStop(0,'rgba(150,255,255,.5)');hg.addColorStop(1,'transparent');
      ctx.beginPath();ctx.arc(p.x,p.y,18,0,Math.PI*2);ctx.fillStyle=hg;ctx.fill();
    });
  }
}

// ─── 6. BLITZAR ───────────────────────────────────────────────────
// Pulsar supramassivo: gira cada vez mais devagar até colapsar num pulso de rádio.
// LÓGICA: cada burst cumulativo deixa o Blitzar ligeiramente mais massivo.
// Após 5 bursts, o próximo burst é um MEGA-BURST: cria um Buraco de Minhoca
// temporário no ponto de impacto do objeto mais próximo.
class Blitzar extends CelestialObject{
  constructor(wx,wy){
    super(wx,wy,'exBlitzar');
    this.radius=rand(5,8);this.mass=this.radius*20;
    this._t=rand(0,Math.PI*2);
    this._spin=rand(8,14);this._spinMax=this._spin;
    this._burstAlpha=0;this._burstR=0;
    this._burstCount=0;
    this._diskParts=Array.from({length:18},(_,i)=>({a:i*(Math.PI*2/18),d:rand(2.2,4)}));
    this._bands=Array.from({length:4},(_,i)=>({off:i*(Math.PI*2/4),w:rand(.1,.2)}));
    this.color='#aaddff';
  }
  update(dt){
    this._t+=dt*this._spin;
    this._spin=Math.max(0,this._spin-dt*.35);
    if(this._burstAlpha>0){this._burstAlpha-=dt*.5;this._burstR+=dt*this.radius*60;}
    if(this._spin<=0.4&&this._burstAlpha<=0){
      this._burstAlpha=1;this._burstR=this.radius;
      this._burstCount++;
      this.mass+=this.radius*2; // fica mais massivo a cada burst
      const isMega=(this._burstCount%5===0);
      let closest=null,closestD=Infinity;
      objects.forEach(o=>{
        if(o===this||o.dead)return;
        const d=dist(o,this);
        if(d>this.radius*30||d<1)return;
        const f=10*(1-d/(this.radius*30)),nx=(o.x-this.x)/d,ny=(o.y-this.y)/d;
        o.vx=(o.vx||0)+nx*f;o.vy=(o.vy||0)+ny*f;
        if(d<closestD){closestD=d;closest=o;}
      });
      // MEGA-BURST: cria buraco de minhoca perto do objeto mais próximo
      if(isMega&&closest&&typeof WormHole!=='undefined'){
        try{
          const w=new WormHole(closest.x+rand(-40,40),closest.y+rand(-40,40));
          w._autoSpawn=true;pendingObjects.push(w);
        }catch(e){}
      }
      this._spin=this._spinMax;
    }
  }
  draw(){
    const sx=this.sx(),sy=this.sy(),r=this.sr();
    const spinFrac=this._spin/this._spinMax;
    const isMegaNext=(this._burstCount%5===4);
    if(this._burstAlpha>0){
      ctx.beginPath();ctx.arc(sx,sy,this._burstR*cam.zoom,0,Math.PI*2);
      ctx.strokeStyle=isMegaNext?`rgba(255,220,80,${this._burstAlpha})`:`rgba(180,220,255,${this._burstAlpha})`;
      ctx.lineWidth=isMegaNext?5:3;ctx.stroke();
    }
    ctx.save();ctx.translate(sx,sy);ctx.rotate(this._t*.3);
    ctx.beginPath();ctx.ellipse(0,0,r*3.4,r*1,0,0,Math.PI*2);
    ctx.strokeStyle='rgba(150,200,255,.15)';ctx.lineWidth=1;ctx.stroke();
    this._diskParts.forEach(p=>{
      const rr=r*p.d;
      ctx.beginPath();ctx.arc(Math.cos(p.a)*rr,Math.sin(p.a)*rr*.3,Math.max(.6,r*.06),0,Math.PI*2);
      ctx.fillStyle=`hsla(${(this._t*30)%360},80%,75%,.4)`;ctx.fill();
    });
    ctx.restore();
    const beamLen=r*16*(0.4+spinFrac);
    for(let i=0;i<2;i++){
      const a=this._t+i*Math.PI;
      const lg=ctx.createLinearGradient(sx,sy,sx+Math.cos(a)*beamLen,sy+Math.sin(a)*beamLen);
      const beamCol=isMegaNext?'255,220,80':'180,230,255';
      lg.addColorStop(0,`rgba(${beamCol},.5)`);lg.addColorStop(1,'transparent');
      ctx.beginPath();ctx.moveTo(sx,sy);
      ctx.lineTo(sx+Math.cos(a-.06)*beamLen,sy+Math.sin(a-.06)*beamLen);
      ctx.lineTo(sx+Math.cos(a+.06)*beamLen,sy+Math.sin(a+.06)*beamLen);
      ctx.closePath();ctx.fillStyle=lg;ctx.fill();
    }
    const g=ctx.createRadialGradient(sx,sy,0,sx,sy,r);
    g.addColorStop(0,'#ffffff');g.addColorStop(.4,'#aaddff');g.addColorStop(1,'#224466');
    ctx.beginPath();ctx.arc(sx,sy,r,0,Math.PI*2);ctx.fillStyle=g;ctx.fill();
    ctx.save();ctx.beginPath();ctx.arc(sx,sy,r,0,Math.PI*2);ctx.clip();
    this._bands.forEach(b=>{
      const a=b.off+this._t*1.2;
      ctx.beginPath();ctx.ellipse(sx,sy,r,r*b.w,a,0,Math.PI*2);
      ctx.strokeStyle='rgba(220,240,255,.3)';ctx.lineWidth=1;ctx.stroke();
    });
    ctx.restore();
    for(let i=0;i<2;i++){
      const pa=this._t*.4+i*Math.PI;
      ctx.beginPath();
      ctx.moveTo(sx+Math.cos(pa)*r,sy+Math.sin(pa)*r);
      ctx.quadraticCurveTo(sx+Math.cos(pa)*r*5,sy+Math.sin(pa)*r*5,sx-Math.cos(pa)*r,sy-Math.sin(pa)*r);
      ctx.strokeStyle='rgba(140,200,255,.12)';ctx.lineWidth=1;ctx.stroke();
    }
    if(sandboxMode){
      ctx.font=`${Math.max(7,r*.9)}px 'Courier New'`;
      ctx.fillStyle=isMegaNext?'rgba(255,220,80,.9)':'rgba(160,210,255,.6)';
      ctx.textAlign='center';ctx.fillText(isMegaNext?'⚡MEGA⚡':`burst #${this._burstCount+1}`,sx,sy-r*2.8);ctx.textAlign='left';
    }
  }
}

// ─── 7. ESTRELA Be ────────────────────────────────────────────────
// Rotação rápida cria disco equatorial. LÓGICA: objetos que entram no disco
// ficam presos em órbita ("capturados"). Capturados em excesso (≥3) fazem
// a estrela ejetar um jato polar. O jato polar empurra violentamente
// tudo acima/abaixo e destrói cometas e meteoros no caminho.
class BeStar extends CelestialObject{
  constructor(wx,wy){
    super(wx,wy,'exBeStar');
    this.radius=rand(12,20);this.mass=this.radius*11;
    this._t=rand(0,Math.PI*2);
    this._rot=rand(0,Math.PI*2);  // rotação contínua do disco
    this._tilt=rand(0,Math.PI);
    this._shells=[];this._ejTimer=rand(3,6);
    this._captured=[];           // objetos em órbita forçada
    this._jetTimer=0;this._jets=[];
    this._surfaceSpots=Array.from({length:6},()=>({a:rand(0,Math.PI*2),d:rand(.35,.8),s:rand(.06,.14),spd:rand(.4,.9)*(Math.random()<.5?1:-1),ph:rand(0,6)}));
    this.color='#bbddff';
  }
  update(dt){
    this._t+=dt;this._rot+=dt*2.8;this._ejTimer-=dt;
    this._shells=this._shells.filter(s=>{s.r+=dt*this.radius*1.6;s.a-=dt*.18;return s.a>0;});
    this._jets=this._jets.filter(j=>{j.life-=dt;return j.life>0;});
    this._surfaceSpots.forEach(sp=>sp.a+=sp.spd*dt*.15);
    if(this._ejTimer<=0){this._ejTimer=rand(4,8);this._shells.push({r:this.radius*1.4,a:.5});}
    // captura objetos que cruzam o disco
    const diskW=this.radius*2.8,diskH=this.radius*.7;
    objects.forEach(o=>{
      if(o===this||o.dead||o.fixed||this._captured.includes(o))return;
      if(o.radius>this.radius*.6)return; // só captura objetos menores
      // transforma para frame do disco (tilted)
      const relX=o.x-this.x,relY=o.y-this.y;
      const rx= relX*Math.cos(-this._tilt)+relY*Math.sin(-this._tilt);
      const ry=-relX*Math.sin(-this._tilt)+relY*Math.cos(-this._tilt);
      if(Math.abs(rx)<diskW&&Math.abs(ry)<diskH&&dist(o,this)<this.radius*3.2){
        this._captured.push(o);
        o._beOrbitAngle=Math.atan2(relY,relX);
        o._beOrbitDist=Math.hypot(relX,relY);
        o._beOrbitSpd=rand(.8,1.8)*(Math.random()<.5?1:-1);
      }
    });
    // move capturados em órbita no disco
    this._captured=this._captured.filter(o=>{
      if(o.dead)return false;
      o._beOrbitAngle=(o._beOrbitAngle||0)+o._beOrbitSpd*dt;
      const lx=Math.cos(o._beOrbitAngle)*o._beOrbitDist;
      const ly=Math.sin(o._beOrbitAngle)*o._beOrbitDist*.28;
      const wx2= lx*Math.cos(this._tilt)-ly*Math.sin(this._tilt);
      const wy2= lx*Math.sin(this._tilt)+ly*Math.cos(this._tilt);
      o.x=this.x+wx2;o.y=this.y+wy2;
      o.vx=0;o.vy=0;
      return true;
    });
    // jato polar quando há ≥3 capturados
    if(this._captured.length>=3&&this._jetTimer<=0){
      this._jetTimer=rand(5,9);
      this._jets.push({life:1.2,maxLife:1.2});
      // empurra tudo acima/abaixo do plano do disco (perpendicular ao tilt)
      const jx=-Math.sin(this._tilt),jy=Math.cos(this._tilt);
      objects.forEach(o=>{
        if(o===this||o.dead||this._captured.includes(o))return;
        const dot=(o.x-this.x)*jx+(o.y-this.y)*jy;
        const d=dist(o,this);if(d>this.radius*14||d<1)return;
        const side=Math.sign(dot)||1;
        const f=50*(1-d/(this.radius*14));
        o.vx=(o.vx||0)+jx*side*f;o.vy=(o.vy||0)+jy*side*f;
        if((o.type==='comet'||o.type==='meteor')&&d<this.radius*6){
          spawnExplosion(o.x,o.y,.35,false);o.dead=true;
        }
      });
      // libera capturados após jato
      this._captured.forEach(o=>{o.vx=rand(-15,15);o.vy=rand(-15,15);});
      this._captured=[];
    }
    if(this._jetTimer>0)this._jetTimer-=dt;
  }
  draw(){
    const sx=this.sx(),sy=this.sy(),r=this.sr();
    ctx.save();ctx.translate(sx,sy);ctx.rotate(this._tilt);
    // cascas de gás ejetadas
    this._shells.forEach(s=>{
      ctx.beginPath();ctx.ellipse(0,0,s.r*cam.zoom*1.8,s.r*cam.zoom*.5,0,0,Math.PI*2);
      ctx.strokeStyle=`hsla(${(this._t*40)%360},90%,75%,${s.a})`;ctx.lineWidth=2;ctx.stroke();
    });
    // disco equatorial com gradiente rotativo
    const diskG=ctx.createRadialGradient(0,0,r*1.1,0,0,r*2.8);
    diskG.addColorStop(0,`hsla(${(this._rot*20)%360},80%,70%,.4)`);diskG.addColorStop(1,'transparent');
    ctx.beginPath();ctx.ellipse(0,0,r*2.8,r*.65,0,0,Math.PI*2);ctx.fillStyle=diskG;ctx.fill();
    // partículas no disco girando
    for(let i=0;i<12;i++){
      const a=this._rot+i*(Math.PI*2/12);
      const rr=r*(1.4+.6*(i%3)/3);
      const px=Math.cos(a)*rr,py=Math.sin(a)*rr*.28;
      ctx.beginPath();ctx.arc(px,py,Math.max(.4,r*.045),0,Math.PI*2);
      ctx.fillStyle=`hsla(${(this._rot*30+i*40)%360},90%,75%,.55)`;ctx.fill();
    }
    ctx.restore();
    // jatos polares
    this._jets.forEach(j=>{
      const al=j.life/j.maxLife;
      const jl=r*12*al;
      const jx=sx-Math.sin(this._tilt)*jl,jy=sy+Math.cos(this._tilt)*jl;
      const jx2=sx+Math.sin(this._tilt)*jl,jy2=sy-Math.cos(this._tilt)*jl;
      [jx,jy,jx2,jy2].forEach((tx,idx)=>{
        const bx=idx<2?jx:jx2,by=idx<2?jy:jy2;
        const lg=ctx.createLinearGradient(sx,sy,bx,by);
        lg.addColorStop(0,`rgba(200,240,255,${al*.7})`);lg.addColorStop(1,'transparent');
        ctx.beginPath();ctx.moveTo(sx,sy);ctx.lineTo(bx,by);ctx.strokeStyle=lg;ctx.lineWidth=r*.35*al;ctx.stroke();
      });
    });
    // corpo oblato com spots de superfície animados
    const g=ctx.createRadialGradient(-r*.3,-r*.3,r*.05,0,0,r);
    g.addColorStop(0,'#ffffff');g.addColorStop(.4,'#bcd8ff');g.addColorStop(1,'#3355aa');
    ctx.save();ctx.translate(sx,sy);ctx.rotate(this._tilt);
    ctx.beginPath();ctx.ellipse(0,0,r*1.18,r*.92,0,0,Math.PI*2);ctx.fillStyle=g;ctx.fill();
    // spots de superfície (manchas de rotação rápida)
    ctx.beginPath();ctx.ellipse(0,0,r*1.18,r*.92,0,0,Math.PI*2);ctx.clip();
    this._surfaceSpots.forEach(sp=>{
      const bx=Math.cos(sp.a)*r*sp.d*1.1,by=Math.sin(sp.a)*r*sp.d*.85;
      const al=0.2+0.15*Math.sin(this._t*2.5+sp.ph);
      ctx.beginPath();ctx.arc(bx,by,r*sp.s,0,Math.PI*2);
      ctx.fillStyle=`rgba(120,180,255,${al})`;ctx.fill();
    });
    ctx.restore();
    if(sandboxMode&&this._captured.length>0){
      ctx.font=`${Math.max(7,r*.5)}px 'Courier New'`;ctx.fillStyle='rgba(180,230,255,.75)';
      ctx.textAlign='center';ctx.fillText(`💫 ${this._captured.length} em órbita`,sx,sy-r*2);ctx.textAlign='left';
    }
  }
}

// ─── 8. ESTRELAS DE NÊUTRONS BINÁRIAS ────────────────────────────
// Par em espiral que emite ondas gravitacionais. LÓGICA: ao fundir,
// gera kilonova + Magnetar (já existia). Adicional: durante a espiral,
// emite "jatos de síncrotron" laterais que deflectem objetos de passagem.
// Objetos atingidos pelos jatos ficam com _syncBoost ativo (brilham azul por 3s).
class BinaryNeutronStar extends CelestialObject{
  constructor(wx,wy){
    super(wx,wy,'exBinaryNeutronStar');
    this.radius=rand(4,6);this.mass=this.radius*50;
    this._t=rand(0,Math.PI*2);
    this._sep=rand(26,40);this._sepStart=this._sep;this._orbAngle=rand(0,Math.PI*2);
    this._spin1=rand(6,10);this._spin2=rand(6,10);
    this._ripples=[];this._rippleTimer=0;
    this._streamParts=[];
    this._syncTimer=rand(2,4);
    this._merged=false;
    this.color='#ddeeff';
  }
  update(dt){
    if(this._merged)return;
    this._t+=dt;this._rippleTimer+=dt;this._syncTimer-=dt;
    this._orbAngle+=dt*(3.5+(40-this._sep)*.15);
    this._sep=Math.max(2,this._sep-dt*.5);
    if(this._rippleTimer>0.3){this._rippleTimer=0;this._ripples.push({r:this._sep,a:.6});}
    this._ripples=this._ripples.filter(r2=>{r2.r+=dt*60;r2.a-=dt*.4;return r2.a>0;});
    const transferRate=Math.max(0,(this._sepStart*.4-this._sep)/this._sepStart);
    if(transferRate>0&&Math.random()<transferRate*.6){this._streamParts.push({t:0,life:rand(.5,1)});}
    this._streamParts=this._streamParts.filter(p=>{p.t+=dt;return p.t<p.life;});
    // jatos de síncrotron perpendiculares à órbita
    if(this._syncTimer<=0){
      this._syncTimer=rand(3,5);
      const jDir=this._orbAngle+Math.PI*.5;
      const jx=Math.cos(jDir),jy=Math.sin(jDir);
      objects.forEach(o=>{
        if(o===this||o.dead)return;
        const d=dist(o,this);if(d>this.radius*20||d<1)return;
        const align=Math.abs((o.x-this.x)*jx+(o.y-this.y)*jy)/d;
        if(align>.65){
          const f=35*align*(1-d/(this.radius*20));
          const side=Math.sign((o.x-this.x)*jx+(o.y-this.y)*jy);
          o.vx=(o.vx||0)+jx*side*f;o.vy=(o.vy||0)+jy*side*f;
          o._syncBoost=3; // brilha azul por 3s
        }
      });
    }
    // limpa syncBoost
    objects.forEach(o=>{if(o._syncBoost>0)o._syncBoost=Math.max(0,o._syncBoost-dt);});
    if(this._sep<=3&&!this._merged){
      this._merged=true;
      spawnExplosion(this.x,this.y,1.1,false);
      try{ pendingObjects.push(new Magnetar(this.x,this.y)); }catch(e){}
      this.dead=true;
    }
  }
  draw(){
    if(this._merged)return;
    const sx=this.sx(),sy=this.sy();
    const sepPx=this._sep*cam.zoom;
    const r=this.sr();
    const stretch=1+Math.max(0,(this._sepStart*.5-this._sep)/this._sepStart)*1.4;
    this._ripples.forEach((r2,i)=>{
      ctx.beginPath();ctx.arc(sx,sy,r2.r*cam.zoom,0,Math.PI*2);
      ctx.strokeStyle=`hsla(${(this._t*60+i*30)%360},90%,75%,${r2.a*.3})`;ctx.lineWidth=1;ctx.stroke();
    });
    this._streamParts.forEach(p=>{
      const f=p.t/p.life;
      const a1=this._orbAngle,a2=this._orbAngle+Math.PI;
      const x1=sx+Math.cos(a1)*sepPx*.5,y1=sy+Math.sin(a1)*sepPx*.5;
      const x2=sx+Math.cos(a2)*sepPx*.5,y2=sy+Math.sin(a2)*sepPx*.5;
      const bx=x1+(x2-x1)*f,by=y1+(y2-y1)*f;
      ctx.beginPath();ctx.arc(bx,by,Math.max(.8,r*.3),0,Math.PI*2);
      ctx.fillStyle=`rgba(255,220,180,${1-f})`;ctx.fill();
    });
    // brilho azul em objetos com syncBoost
    objects.forEach(o=>{
      if(!o._syncBoost||o.dead||o===this)return;
      const {x:ox,y:oy}=worldToScreen(o.x,o.y);const orr=o.sr();
      const bl=ctx.createRadialGradient(ox,oy,0,ox,oy,orr*2);
      bl.addColorStop(0,`rgba(100,180,255,${Math.min(.5,o._syncBoost*.2)})`);bl.addColorStop(1,'transparent');
      ctx.beginPath();ctx.arc(ox,oy,orr*2,0,Math.PI*2);ctx.fillStyle=bl;ctx.fill();
    });
    for(let i=0;i<2;i++){
      const a=this._orbAngle+i*Math.PI;
      const bx=sx+Math.cos(a)*sepPx*.5,by=sy+Math.sin(a)*sepPx*.5;
      const spin=i===0?this._spin1:this._spin2;
      const beamA=this._t*spin+i*Math.PI*.5;
      for(let j=0;j<2;j++){
        const ba=beamA+j*Math.PI;
        const bl2=r*10;
        const lg=ctx.createLinearGradient(bx,by,bx+Math.cos(ba)*bl2,by+Math.sin(ba)*bl2);
        lg.addColorStop(0,'rgba(180,220,255,.4)');lg.addColorStop(1,'transparent');
        ctx.beginPath();ctx.moveTo(bx,by);
        ctx.lineTo(bx+Math.cos(ba-.04)*bl2,by+Math.sin(ba-.04)*bl2);
        ctx.lineTo(bx+Math.cos(ba+.04)*bl2,by+Math.sin(ba+.04)*bl2);
        ctx.closePath();ctx.fillStyle=lg;ctx.fill();
      }
      ctx.save();ctx.translate(bx,by);ctx.rotate(a);
      const g2=ctx.createRadialGradient(0,0,0,0,0,r*stretch);
      g2.addColorStop(0,'#ffffff');g2.addColorStop(.5,`hsl(${(this._t*80+i*180)%360},90%,75%)`);g2.addColorStop(1,'#224488');
      ctx.beginPath();ctx.ellipse(0,0,r*stretch,r,0,0,Math.PI*2);ctx.fillStyle=g2;ctx.fill();
      ctx.restore();
    }
    ctx.beginPath();ctx.moveTo(sx+Math.cos(this._orbAngle)*sepPx*.5,sy+Math.sin(this._orbAngle)*sepPx*.5);
    ctx.lineTo(sx+Math.cos(this._orbAngle+Math.PI)*sepPx*.5,sy+Math.sin(this._orbAngle+Math.PI)*sepPx*.5);
    ctx.strokeStyle='rgba(150,180,255,.15)';ctx.lineWidth=1;ctx.stroke();
  }
}

// ─── 9. OBJETO DE HOAG ────────────────────────────────────────────
// Galáxia anelar. LÓGICA: objetos orbitando o anel acumulam "energia de anel".
// Ao atingir energia suficiente, o anel pulsa e "copia" o objeto — cria uma
// versão especular (mesmo tipo, posição refletida no anel). O original é ejetado.
class HoagObject extends CelestialObject{
  constructor(wx,wy){
    super(wx,wy,'exHoagObject');
    this.radius=rand(20,30);this.mass=this.radius*16;
    this._t=rand(0,Math.PI*2);
    this._ringR=this.radius*3.2;this._ringRot=rand(0,Math.PI*2);
    this._stars=Array.from({length:70},()=>({a:rand(0,Math.PI*2),d:rand(.85,1.15),tw:rand(0,6),armOff:rand(0,1)}));
    this._coreCells=Array.from({length:5},(_,i)=>({a:i*(Math.PI*2/5)+rand(0,.5),d:rand(.3,.6),s:rand(.15,.25)}));
    this._bridgeParts=Array.from({length:10},(_,i)=>({t:i/10,spd:rand(.05,.1)}));
    this._ringEnergy=0;this._ringPulse=0;
    this._copyTimer=0;
    this.color='#ffdd88';
  }
  update(dt){
    this._t+=dt;this._ringRot+=dt*.12;this._ringPulse=Math.max(0,this._ringPulse-dt*1.5);
    this._bridgeParts.forEach(p=>{p.t=(p.t+p.spd*dt)%1;});
    objects.forEach(o=>{
      if(o===this||o.dead||o.radius>this.radius*.5)return;
      const d=dist(o,this);
      const onRing=Math.abs(d-this._ringR)<this.radius*.6;
      if(onRing&&d>1){
        // guia no anel
        const f=.6*(1-Math.abs(d-this._ringR)/(this.radius*.6));
        const targetAng=Math.atan2(o.y-this.y,o.x-this.x)+0.02;
        const tx=this.x+Math.cos(targetAng)*this._ringR,ty=this.y+Math.sin(targetAng)*this._ringR;
        o.vx=(o.vx||0)+(tx-o.x)*f*dt*.6;o.vy=(o.vy||0)+(ty-o.y)*f*dt*.6;
        this._ringEnergy=Math.min(100,this._ringEnergy+dt*3);
      }
    });
    // quando energia cheia: pulsa e copia um objeto do anel
    if(this._ringEnergy>=100&&this._copyTimer<=0){
      this._copyTimer=rand(5,9);this._ringPulse=1;this._ringEnergy=0;
      const onRing=objects.filter(o=>{
        if(o===this||o.dead)return false;
        return Math.abs(dist(o,this)-this._ringR)<this.radius*.6;
      });
      if(onRing.length>0){
        const src=onRing[Math.floor(Math.random()*onRing.length)];
        try{
          const mirrorA=Math.atan2(src.y-this.y,src.x-this.x)+Math.PI;
          const copy=new src.constructor(this.x+Math.cos(mirrorA)*this._ringR,this.y+Math.sin(mirrorA)*this._ringR);
          copy._autoSpawn=true;pendingObjects.push(copy);
        }catch(e){}
        // ejeta o original
        const ej=35,ea=Math.atan2(src.y-this.y,src.x-this.x);
        src.vx=(src.vx||0)+Math.cos(ea)*ej;src.vy=(src.vy||0)+Math.sin(ea)*ej;
      }
    }
    if(this._copyTimer>0)this._copyTimer-=dt;
  }
  draw(){
    const sx=this.sx(),sy=this.sy(),r=this.sr();
    const ringR=this._ringR*cam.zoom;
    // pulso do anel ao copiar
    if(this._ringPulse>0){
      ctx.beginPath();ctx.arc(sx,sy,ringR*(1+this._ringPulse*.3),0,Math.PI*2);
      ctx.strokeStyle=`rgba(255,240,160,${this._ringPulse*.7})`;ctx.lineWidth=4;ctx.stroke();
    }
    this._stars.forEach(st=>{
      const armPhase=Math.floor(st.armOff*3)*(Math.PI*2/3);
      const a=st.a+this._ringRot+armPhase*.15;
      const rr=ringR*st.d;
      const bx=sx+Math.cos(a)*rr,by=sy+Math.sin(a)*rr*.92;
      const tw=0.4+0.4*Math.sin(this._t*2+st.tw);
      ctx.beginPath();ctx.arc(bx,by,Math.max(.6,r*.04),0,Math.PI*2);
      ctx.fillStyle=`hsla(${(this._t*20+st.tw*40)%360},80%,80%,${Math.max(0,tw)})`;ctx.fill();
    });
    ctx.beginPath();ctx.ellipse(sx,sy,ringR*.78,ringR*.78*.92,0,0,Math.PI*2);
    ctx.fillStyle='rgba(5,2,15,.55)';ctx.fill();
    this._bridgeParts.forEach(p=>{
      const a=this._ringRot*1.5+p.t*Math.PI*2;
      const rr2=r+(ringR-r)*p.t;
      const bx=sx+Math.cos(a)*rr2,by=sy+Math.sin(a)*rr2*.92;
      ctx.beginPath();ctx.arc(bx,by,Math.max(.5,r*.025),0,Math.PI*2);
      ctx.fillStyle=`rgba(255,220,160,${0.3*(1-p.t)})`;ctx.fill();
    });
    const g=ctx.createRadialGradient(sx,sy,0,sx,sy,r);
    g.addColorStop(0,'#fff8e0');g.addColorStop(.5,'#ffdd88');g.addColorStop(1,'#aa6600');
    ctx.beginPath();ctx.arc(sx,sy,r,0,Math.PI*2);ctx.fillStyle=g;ctx.fill();
    ctx.save();ctx.beginPath();ctx.arc(sx,sy,r,0,Math.PI*2);ctx.clip();
    this._coreCells.forEach(c=>{
      const a=c.a+this._t*.5;
      const bx=sx+Math.cos(a)*r*c.d,by=sy+Math.sin(a)*r*c.d;
      const al=0.25+0.15*Math.sin(this._t*2+c.a);
      const cg=ctx.createRadialGradient(bx,by,0,bx,by,r*c.s);
      cg.addColorStop(0,`rgba(255,255,200,${al})`);cg.addColorStop(1,'transparent');
      ctx.beginPath();ctx.arc(bx,by,r*c.s,0,Math.PI*2);ctx.fillStyle=cg;ctx.fill();
    });
    ctx.restore();
    // barra de energia do anel
    if(sandboxMode&&this._ringEnergy>0){
      const pct=this._ringEnergy/100;
      ctx.beginPath();ctx.arc(sx,sy,ringR+8*cam.zoom,-.5*Math.PI,-.5*Math.PI+Math.PI*2*pct);
      ctx.strokeStyle=`rgba(255,220,80,${.4+pct*.4})`;ctx.lineWidth=2;ctx.stroke();
    }
  }
}

// ═══════════════════════════════════════════════════════════════════
//  DARK GALAXY — Pacote Exótico, galáxia quase invisível dominada por
//  matéria escura: halo difuso pulsante, núcleo de "vazio" e
//  pouquíssima poeira estelar visível. Usada tanto pelo botão do
//  Pacote Exótico quanto pelo spawn automático raro em Sandbox.
// ═══════════════════════════════════════════════════════════════════
class DarkGalaxy extends CelestialObject{
  constructor(wx,wy){
    super(wx,wy,'exDarkGalaxy');
    this.galaxyType=randInt(0,3);
    this.radius=rand(220,380);this.mass=0;this.fixed=true;
    this.angle=0;this.rotSpeed=rand(.0006,.0022);
    this.sizeScale=rand(.8,1.3);
    this.haloPulse=rand(0,Math.PI*2);
    this.dustPts=this._generateDust();
    this.haloColor=`hsl(${rand(255,290)},${rand(35,55)}%,${rand(8,16)}%)`;
    this.coreColor=`hsl(${rand(255,290)},${rand(30,50)}%,${rand(4,10)}%)`;
  }
  _generateDust(){
    const pts=[];const n=randInt(60,110); // muito menos poeira que uma galáxia normal
    for(let i=0;i<n;i++){
      let a,d,arm;
      switch(this.galaxyType){
        case 0: // Espiral
          arm=Math.floor(rand(0,3));d=rand(.15,.98);
          a=rand(0,Math.PI*2)+arm*(Math.PI*2/3)+d*1.8;
          break;
        case 1: // Elíptica
          a=rand(0,Math.PI*2);d=Math.sqrt(rand(0,1))*.95;
          break;
        case 2: // Irregular
          a=rand(0,Math.PI*2);d=rand(0,.9);a+=Math.sin(a*3)*0.6;
          break;
        case 3: // Barrada
          arm=Math.floor(rand(0,2));d=rand(.05,.98);
          if(d<.3){a=rand(-Math.PI*.1,Math.PI*.1)+arm*Math.PI;}
          else{a=rand(0,Math.PI*2)+arm*Math.PI+d*1.5;}
          break;
        default:a=rand(0,Math.PI*2);d=rand(.1,.95);
      }
      pts.push({
        a,d,r:rand(.6,2.4),
        hue:rand(220,290),
        al:rand(.05,.22),
        sp:this.rotSpeed*(0.6+rand(0,.8)),
        scaleY:this.galaxyType===1?rand(.5,.95):rand(.38,.7)
      });
    }
    return pts;
  }
  update(dt){
    this.haloPulse+=dt*.6;
  }
  draw(){
    const sx=this.sx(),sy=this.sy(),r=this.sr()*this.sizeScale;
    this.angle+=this.rotSpeed;
    const pulse=0.5+0.5*Math.sin(this.haloPulse);
    // Halo de matéria escura — quase imperceptível, pulsa lentamente
    const gh=ctx.createRadialGradient(sx,sy,0,sx,sy,r*1.15);
    gh.addColorStop(0,'transparent');
    gh.addColorStop(.55,this.haloColor.replace('hsl','hsla').replace(')',`,${(0.10+0.08*pulse).toFixed(3)})`));
    gh.addColorStop(1,'transparent');
    ctx.beginPath();ctx.arc(sx,sy,r*1.15,0,Math.PI*2);ctx.fillStyle=gh;ctx.fill();
    // Núcleo — vazio, levemente mais escuro que o espaço ao redor
    const gc=ctx.createRadialGradient(sx,sy,0,sx,sy,r*.4);
    gc.addColorStop(0,this.coreColor);
    gc.addColorStop(1,'transparent');
    ctx.beginPath();ctx.arc(sx,sy,r*.4,0,Math.PI*2);ctx.fillStyle=gc;ctx.fill();
    // Poeira estelar escassa
    this.dustPts.forEach(p=>{
      p.a+=p.sp;
      const a=p.a+this.angle;
      const px=sx+Math.cos(a)*r*p.d;
      const py=sy+Math.sin(a)*r*p.d*p.scaleY;
      const pr=Math.max(.3,p.r);
      ctx.beginPath();ctx.arc(px,py,pr,0,Math.PI*2);
      ctx.fillStyle=`hsla(${p.hue},40%,55%,${p.al})`;ctx.fill();
    });
    // Anel de distorção sutil — só perceptível de perto
    if(cam.zoom>0.6){
      ctx.beginPath();ctx.arc(sx,sy,r*0.98,0,Math.PI*2);
      ctx.strokeStyle=`rgba(120,80,200,${(0.08+0.05*pulse).toFixed(3)})`;ctx.lineWidth=1;ctx.stroke();
    }
    if(sandboxMode){
      ctx.font=`${Math.max(8,r*.06)}px 'Courier New'`;ctx.fillStyle='rgba(180,140,255,.22)';
      ctx.textAlign='center';ctx.fillText(`${this.name} [G. Escura]`,sx,sy+r+12*cam.zoom);ctx.textAlign='left';
    }
  }
}

// ─── 11. BURACO VERMELHO ──────────────────────────────────────────
// Horizonte extremamente "redshiftado". LÓGICA: objetos pequenos que se
// aproximam acumulam _redshift (0→1) e perdem velocidade gradualmente
// (dilatação temporal extrema). Ao atingir redshift máximo, ficam quase
// "congelados" até o próximo Flash de Hawking, que os ejeta de volta
// com brilho vermelho intenso.
class RedHole extends CelestialObject{
  constructor(wx,wy){
    super(wx,wy,'exRedHole');
    this.radius=rand(9,14);this.mass=this.radius*55;
    this._t=rand(0,Math.PI*2);
    this._diskRot=rand(0,Math.PI*2);
    this.color='#ff2222';
    // Ciclo: SUCK(atraindo) → DIGEST(processando) → BELCH(ejetando)
    this._phase='suck'; // 'suck'|'digest'|'belch'
    this._phaseTimer=rand(4,7);
    this._stomach=[]; // objetos absorvidos (cor salva)
    this._jetAngle=rand(0,Math.PI*2);
    this._jetAlpha=0;
    this._pulseR=0;
    this._digestColors=[];
  }
  update(dt){
    this._t+=dt;this._diskRot+=dt*1.4;
    this._phaseTimer-=dt;
    if(this._jetAlpha>0)this._jetAlpha=Math.max(0,this._jetAlpha-dt*1.8);
    if(this._pulseR>0)this._pulseR=Math.max(0,this._pulseR-dt*this.radius*3);

    if(this._phase==='suck'){
      // Atrai objetos e absorve os que chegam muito perto
      objects.forEach(o=>{
        if(o===this||o.dead||o.fixed)return;
        const d=dist(o,this);if(d>this.radius*10||d<1)return;
        const f=18*(1-d/(this.radius*10));
        o.vx=(o.vx||0)+(this.x-o.x)/d*f*dt;
        o.vy=(o.vy||0)+(this.y-o.y)/d*f*dt;
        if(d<this.radius*1.4&&!o.fixed&&o.radius<this.radius*1.2){
          // absorve — guarda cor para escupir depois
          this._stomach.push({color:o.color||'#ff4444',radius:o.radius});
          for(let i=0;i<5;i++)particles.push({x:o.x,y:o.y,vx:rand(-2,2),vy:rand(-2,2),r:rand(1,2.5),alpha:.8,color:o.color||'#ff6644'});
          o.dead=true;
        }
      });
      if(this._phaseTimer<=0){
        this._phase=this._stomach.length>0?'digest':'suck';
        this._phaseTimer=rand(2,3.5);
        this._digestColors=this._stomach.map(s=>s.color);
      }
    } else if(this._phase==='digest'){
      // Apenas anima internamente, sem interação física
      if(this._phaseTimer<=0){
        this._phase='belch';
        this._phaseTimer=rand(1,2);
        this._jetAngle=rand(0,Math.PI*2);
        this._jetAlpha=1;this._pulseR=this.radius;
      }
    } else if(this._phase==='belch'){
      // Ejeção: dois jatos opostos com fragmentos coloridos
      if(this._jetAlpha>0.5){
        const numColors=Math.max(1,this._digestColors.length);
        for(let j=0;j<2;j++){
          const ja=this._jetAngle+(j===0?0:Math.PI);
          const speed=rand(18,32);
          const col=this._digestColors[Math.floor(rand(0,numColors))]||'#ff4400';
          for(let i=0;i<3;i++){
            const spread=rand(-0.25,0.25);
            particles.push({
              x:this.x+Math.cos(ja)*this.radius,
              y:this.y+Math.sin(ja)*this.radius,
              vx:Math.cos(ja+spread)*speed,
              vy:Math.sin(ja+spread)*speed,
              r:rand(1.5,3.5),alpha:.95,color:col
            });
          }
        }
      }
      if(this._phaseTimer<=0){
        this._phase='suck';
        this._phaseTimer=rand(5,8);
        this._stomach=[];this._digestColors=[];
      }
    }
  }
  draw(){
    const sx=this.sx(),sy=this.sy(),r=this.sr();
    // Anel de disco
    ctx.save();ctx.translate(sx,sy);ctx.rotate(this._diskRot);ctx.scale(1,.32);
    ctx.beginPath();ctx.arc(0,0,r*2.6,0,Math.PI*2);
    const diskAlpha=this._phase==='digest'?0.7:0.4;
    ctx.strokeStyle=`rgba(255,60,30,${diskAlpha+.15*Math.sin(this._t*3)})`;ctx.lineWidth=Math.max(1,r*.35);ctx.stroke();
    ctx.restore();
    // Halo
    const g2=ctx.createRadialGradient(sx,sy,r*.8,sx,sy,r*4);
    g2.addColorStop(0,'rgba(255,40,20,.3)');g2.addColorStop(1,'transparent');
    ctx.beginPath();ctx.arc(sx,sy,r*4,0,Math.PI*2);ctx.fillStyle=g2;ctx.fill();
    // Pulso de ejeção
    if(this._pulseR>0){
      ctx.beginPath();ctx.arc(sx,sy,this._pulseR*cam.zoom,0,Math.PI*2);
      ctx.strokeStyle=`rgba(255,120,40,${this._jetAlpha*.6})`;ctx.lineWidth=2;ctx.stroke();
    }
    // Jatos visíveis
    if(this._phase==='belch'&&this._jetAlpha>0.1){
      for(let j=0;j<2;j++){
        const ja=this._jetAngle+(j===0?0:Math.PI);
        const jetLen=r*(3+4*this._jetAlpha);
        const gj=ctx.createLinearGradient(sx+Math.cos(ja)*r,sy+Math.sin(ja)*r,
          sx+Math.cos(ja)*jetLen,sy+Math.sin(ja)*jetLen);
        gj.addColorStop(0,`rgba(255,160,80,${this._jetAlpha*.9})`);
        gj.addColorStop(1,'transparent');
        ctx.beginPath();
        ctx.moveTo(sx+Math.cos(ja)*r,sy+Math.sin(ja)*r);
        ctx.lineTo(sx+Math.cos(ja)*jetLen,sy+Math.sin(ja)*jetLen);
        ctx.strokeStyle=gj;ctx.lineWidth=r*.45;ctx.stroke();
      }
    }
    // Estômago cheio: brilho interno pulsante com as cores absorvidas
    if(this._phase==='digest'&&this._stomach.length>0){
      const col=this._digestColors[Math.floor(this._t*4)%Math.max(1,this._digestColors.length)]||'#ff8844';
      const gi=ctx.createRadialGradient(sx,sy,0,sx,sy,r*.8);
      gi.addColorStop(0,`${col}cc`);gi.addColorStop(1,'transparent');
      ctx.beginPath();ctx.arc(sx,sy,r*.8,0,Math.PI*2);ctx.fillStyle=gi;ctx.fill();
    }
    // Horizonte
    const g=ctx.createRadialGradient(sx,sy,0,sx,sy,r);
    g.addColorStop(0,'#3a0000');g.addColorStop(.7,'#150000');g.addColorStop(1,'#000');
    ctx.beginPath();ctx.arc(sx,sy,r,0,Math.PI*2);ctx.fillStyle=g;ctx.fill();
    ctx.beginPath();ctx.arc(sx,sy,r,0,Math.PI*2);
    ctx.strokeStyle=`rgba(255,60,40,${.3+.2*Math.sin(this._t*2)})`;ctx.lineWidth=1.5;ctx.stroke();
    // Badge de fase no sandbox
    if(sandboxMode){
      const label=this._phase==='suck'?'⬇️ absorvendo':this._phase==='digest'?`🔄 digerindo(${this._stomach.length})`: '💥 ejetando';
      ctx.font=`${Math.max(6,r*.28)}px 'Courier New'`;ctx.fillStyle='rgba(255,120,80,.5)';
      ctx.textAlign='center';ctx.fillText(label,sx,sy+r+8*cam.zoom);ctx.textAlign='left';
    }
  }
}

// ─── 12. SINGULARIDADE DESNUDA ─────────────────────────────────────
// Ponto de curvatura infinita sem horizonte. LÓGICA: "congela" objetos
// próximos drenando sua velocidade (dilatação temporal extrema) e
// acumulando energia congelada. Quando a energia atinge pico, dispara
// um "ressalto temporal" — todos os objetos congelados recebem de volta
// a velocidade acumulada multiplicada, disparados em direções aleatórias
// como se o tempo voltasse rápido demais de uma vez.
class NakedSingularity extends CelestialObject{
  constructor(wx,wy){
    super(wx,wy,'exNakedSingularity');
    this.radius=rand(2,4);this.mass=this.radius*220;
    this._t=rand(0,Math.PI*2);
    this._cracks=Array.from({length:9},()=>({a:rand(0,Math.PI*2),len:rand(.6,1.6),sp:rand(-1,1)}));
    this._frozenEnergy=0; // energia acumulada dos objetos congelados
    this._rewindTimer=rand(5,9);
    this._rewindFlash=0;
    this._frozenObjs=new Set(); // rastreia objetos sendo congelados
    this.color='#eaccff';
  }
  update(dt){
    this._t+=dt;this._rewindTimer-=dt;
    if(this._rewindFlash>0)this._rewindFlash=Math.max(0,this._rewindFlash-dt*2.5);
    this._cracks.forEach(c=>c.a+=c.sp*dt*1.5);
    const range=this.radius*60;
    const frozenNow=new Set();
    objects.forEach(o=>{
      if(o===this||o.dead||o.fixed)return;
      const d=dist(o,this);if(d>range||d<1)return;
      // gravidade nua — puxa sem suavização
      const f=this.mass*0.018/d;
      o.vx=(o.vx||0)+(this.x-o.x)/d*f*dt;o.vy=(o.vy||0)+(this.y-o.y)/d*f*dt;
      // zona de congelamento: raio interno
      if(d<range*.35){
        const speed=Math.hypot(o.vx||0,o.vy||0);
        // drena velocidade e acumula energia congelada
        const drain=Math.min(speed,speed*2.2*dt);
        if(speed>0.05){
          o.vx=(o.vx||0)*Math.max(0,1-2.2*dt);
          o.vy=(o.vy||0)*Math.max(0,1-2.2*dt);
          this._frozenEnergy+=drain*0.4;
          frozenNow.add(o);
          // efeito visual: partículas roxas ao redor
          if(Math.random()<0.04)particles.push({x:o.x+rand(-2,2),y:o.y+rand(-2,2),vx:rand(-.5,.5),vy:rand(-.5,.5),r:rand(.5,1.4),alpha:.7,color:'hsl(280,90%,75%)'});
        }
      }
    });
    this._frozenObjs=frozenNow;
    // Ressalto temporal: dispara quando energia alta ou timer zera
    if(this._rewindTimer<=0||this._frozenEnergy>60){
      this._rewindTimer=rand(6,10);
      this._rewindFlash=1;
      const multiplier=1.8+this._frozenEnergy*0.04;
      objects.forEach(o=>{
        if(o===this||o.dead||o.fixed)return;
        const d=dist(o,this);if(d>range||d<1)return;
        const speed=Math.hypot(o.vx||0,o.vy||0);
        const a=rand(0,Math.PI*2); // direção aleatória (o passado era caótico)
        const burst=Math.max(6,speed*multiplier);
        o.vx=Math.cos(a)*burst;o.vy=Math.sin(a)*burst;
        for(let i=0;i<4;i++)particles.push({x:o.x,y:o.y,vx:rand(-3,3),vy:rand(-3,3),r:rand(1,2.5),alpha:.9,color:'hsl(280,90%,82%)'});
      });
      this._frozenEnergy=0;
    }
  }
  draw(){
    const sx=this.sx()+rand(-.5,.5),sy=this.sy()+rand(-.5,.5),r=Math.max(1.5,this.sr());
    // Flash do ressalto
    if(this._rewindFlash>0){
      const rf=this.radius*60*cam.zoom*this._rewindFlash;
      const fg=ctx.createRadialGradient(sx,sy,0,sx,sy,rf);
      fg.addColorStop(0,`rgba(230,180,255,${this._rewindFlash*.35})`);fg.addColorStop(1,'transparent');
      ctx.beginPath();ctx.arc(sx,sy,rf,0,Math.PI*2);ctx.fillStyle=fg;ctx.fill();
      // Anel de ressalto
      ctx.beginPath();ctx.arc(sx,sy,rf*.6,0,Math.PI*2);
      ctx.strokeStyle=`rgba(255,220,255,${this._rewindFlash*.6})`;ctx.lineWidth=2;ctx.stroke();
    }
    // Fissuras do espaço-tempo
    this._cracks.forEach(c=>{
      const len=r*6*c.len*(0.7+0.3*Math.sin(this._t*3+c.a));
      ctx.beginPath();ctx.moveTo(sx,sy);
      ctx.lineTo(sx+Math.cos(c.a)*len,sy+Math.sin(c.a)*len);
      // cor mais intensa quanto mais energia congelada
      const eAlpha=Math.min(.5,.18+this._frozenEnergy*0.004);
      ctx.strokeStyle=`rgba(230,190,255,${eAlpha+.12*Math.sin(this._t*4+c.a*2)})`;ctx.lineWidth=1;ctx.stroke();
    });
    // Zona de congelamento — anel tracejado
    const freezeR=this.radius*60*.35*cam.zoom;
    ctx.beginPath();ctx.arc(sx,sy,freezeR,0,Math.PI*2);
    ctx.strokeStyle=`rgba(200,160,255,${.08+.06*Math.sin(this._t*2)})`;
    ctx.setLineDash([4,8]);ctx.lineWidth=1;ctx.stroke();ctx.setLineDash([]);
    // Núcleo
    const g=ctx.createRadialGradient(sx,sy,0,sx,sy,r*4);
    g.addColorStop(0,'#ffffff');g.addColorStop(.25,'#eaccff');g.addColorStop(1,'transparent');
    ctx.beginPath();ctx.arc(sx,sy,r*4,0,Math.PI*2);ctx.fillStyle=g;ctx.fill();
    ctx.beginPath();ctx.arc(sx,sy,r,0,Math.PI*2);ctx.fillStyle='#fff';ctx.fill();
    // Barra de energia congelada no sandbox
    if(sandboxMode&&this._frozenEnergy>2){
      const pct=Math.min(1,this._frozenEnergy/60);
      ctx.font=`${Math.max(6,r*1.2)}px 'Courier New'`;ctx.fillStyle=`rgba(200,160,255,${.4+.3*pct})`;
      ctx.textAlign='center';ctx.fillText(`❄️${Math.round(pct*100)}%`,sx,sy-r*5-4*cam.zoom);ctx.textAlign='left';
    }
  }
}

// ─── 13. BLANETA ───────────────────────────────────────────────────
// Planeta nascido em ambiente extremo. LÓGICA: procura ativamente a
// estrela/cefeida mais próxima para orbitá-la (pai preferido). Se não
// achar estrela, aceita um Buraco Negro. Ao perder o pai, deriva e
// esfria, mas nunca para de buscar — fica acelerando em direção ao
// astro-pai mais próximo. Com estrela: aquecida e vibrante. Com BH:
// calcinada e vermelha. Órfã: fria e escura à deriva.
class Blanet extends CelestialObject{
  constructor(wx,wy){
    super(wx,wy,'exBlanet');
    this.radius=rand(8,13);this.mass=this.radius*5;
    this._t=rand(0,Math.PI*2);
    this._glow=0;
    this._warmth=0; // 0=fria(órfã) 1=aquecida(estrela) 0.5=calcinada(BH)
    this._parentType='none'; // 'star'|'blackhole'|'none'
    this._terrain=Array.from({length:6},()=>({a:rand(0,Math.PI*2),d:rand(.3,.8),s:rand(.08,.18)}));
    this.parent=null;this.orbitAngle=rand(0,Math.PI*2);this.orbitDist=0;this.orbitSpeed=0;
    this.color='#553344';
    this._seekTimer=0; // busca periódica por novo pai
    this._trailAlpha=0;
    this._adoptParent(true);
  }
  _adoptParent(initial){
    // Prioridade: Estrela > Cefeida > Buraco Negro
    const starTypes=['star','cepheid'];
    let bestStar=null,bestStarD=Infinity;
    starTypes.forEach(t=>{
      const s=findNearest(this,t);
      if(s){const d=dist(this,s);if(d<bestStarD){bestStarD=d;bestStar=s;}}
    });
    const bh=findNearest(this,'blackhole');
    const bhD=bh?dist(this,bh):Infinity;
    const adoptRange=initial?Infinity:this.radius*60;
    if(bestStar&&bestStarD<adoptRange&&(bestStarD<bhD*0.8||!bh)){
      this.parent=bestStar;
      this.orbitDist=Math.max(bestStar.radius*2.8,bestStarD);
      this.orbitAngle=Math.atan2(this.y-bestStar.y,this.x-bestStar.x);
      this.orbitSpeed=(0.6+rand(0,.3))/Math.sqrt(this.orbitDist/40);
      this._parentType='star';
    } else if(bh&&bhD<adoptRange){
      this.parent=bh;
      this.orbitDist=Math.max(bh.radius*2.5,bhD);
      this.orbitAngle=Math.atan2(this.y-bh.y,this.x-bh.x);
      this.orbitSpeed=(1.2+rand(0,.6))/Math.sqrt(this.orbitDist/30);
      this._parentType='blackhole';
    }
  }
  update(dt){
    this._t+=dt;this._seekTimer-=dt;
    if(this.parent&&!this.parent.dead){
      this.orbitAngle+=this.orbitSpeed*dt;
      this.x=this.parent.x+Math.cos(this.orbitAngle)*this.orbitDist;
      this.y=this.parent.y+Math.sin(this.orbitAngle)*this.orbitDist;
      const targetGlow=this._parentType==='star'?1.0:0.55;
      this._glow=Math.min(targetGlow,this._glow+dt*.5);
      this._warmth=this._parentType==='star'?
        Math.min(1,this._warmth+dt*.4):
        Math.max(0,Math.min(0.5,this._warmth+dt*.3-(this._warmth>0.5?dt*.2:0)));
    } else {
      if(this.parent&&this.parent.dead){
        // ejetada com velocidade tangencial
        const tx=-Math.sin(this.orbitAngle),ty=Math.cos(this.orbitAngle);
        this.vx=(tx*this.orbitSpeed*this.orbitDist*.05)||0;
        this.vy=(ty*this.orbitSpeed*this.orbitDist*.05)||0;
        this.parent=null;this._parentType='none';
      }
      // Deriva e resfria
      this._glow=Math.max(0,this._glow-dt*.04);
      this._warmth=Math.max(0,this._warmth-dt*.06);
      // Busca ativa por novo pai: acelera em direção ao mais próximo
      if(this._seekTimer<=0){
        this._seekTimer=1.5;
        this._adoptParent(false);
        if(!this.parent){
          // sem pai encontrado — vai em direção ao mais próximo de longe
          let best=null,bestD=Infinity;
          ['star','cepheid','blackhole'].forEach(t=>{
            const o=findNearest(this,t);
            if(o){const d=dist(this,o);if(d<bestD){bestD=d;best=o;}}
          });
          if(best){
            const d=dist(this,best)||1;
            const pull=4.5/d;
            this.vx=(this.vx||0)+(best.x-this.x)/d*pull;
            this.vy=(this.vy||0)+(best.y-this.y)/d*pull;
            this._trailAlpha=0.7;
          }
        }
      }
      if(this._trailAlpha>0)this._trailAlpha=Math.max(0,this._trailAlpha-dt*.8);
    }
  }
  draw(){
    const sx=this.sx(),sy=this.sy(),r=this.sr();
    const litAngle=this.parent?Math.atan2(this.parent.y-this.y,this.parent.x-this.x):this._t*.05;
    // Rastro de busca (órfã em movimento)
    if(this._trailAlpha>0){
      const tvx=-(this.vx||0),tvy=-(this.vy||0);
      const tlen=Math.hypot(tvx,tvy)||1;
      const gt=ctx.createLinearGradient(sx,sy,sx+tvx/tlen*r*3,sy+tvy/tlen*r*3);
      gt.addColorStop(0,`rgba(150,100,180,${this._trailAlpha*.5})`);gt.addColorStop(1,'transparent');
      ctx.beginPath();ctx.moveTo(sx,sy);ctx.lineTo(sx+tvx/tlen*r*4,sy+tvy/tlen*r*4);
      ctx.strokeStyle=gt;ctx.lineWidth=r*.4;ctx.stroke();
    }
    // Halo de calor
    if(this._glow>0.02){
      const gx=sx+Math.cos(litAngle)*r*.4,gy=sy+Math.sin(litAngle)*r*.4;
      const warmColor=this._parentType==='star'?`255,200,100`:this._parentType==='blackhole'?`255,80,30`:`180,100,80`;
      const gg=ctx.createRadialGradient(gx,gy,0,gx,gy,r*1.8);
      gg.addColorStop(0,`rgba(${warmColor},${this._glow*.5})`);gg.addColorStop(1,'transparent');
      ctx.beginPath();ctx.arc(gx,gy,r*1.8,0,Math.PI*2);ctx.fillStyle=gg;ctx.fill();
    }
    // Corpo
    const hue=this._parentType==='star'?30:this._parentType==='blackhole'?5:320;
    const sat=this._parentType==='none'?15:50;
    const light=this._parentType==='none'?Math.max(6,12-this._warmth*5):18+this._warmth*18;
    const g=ctx.createRadialGradient(sx-r*.3,sy-r*.3,r*.1,sx,sy,r);
    g.addColorStop(0,`hsl(${hue},${sat+20}%,${light+12}%)`);
    g.addColorStop(.6,`hsl(${hue},${sat}%,${light}%)`);
    g.addColorStop(1,`hsl(${hue-10},${Math.max(5,sat-15)}%,${Math.max(4,light-10)}%)`);
    ctx.beginPath();ctx.arc(sx,sy,r,0,Math.PI*2);ctx.fillStyle=g;ctx.fill();
    ctx.save();ctx.beginPath();ctx.arc(sx,sy,r,0,Math.PI*2);ctx.clip();
    this._terrain.forEach(t=>{
      const bx=sx+Math.cos(t.a)*r*t.d,by=sy+Math.sin(t.a)*r*t.d;
      ctx.beginPath();ctx.arc(bx,by,r*t.s,0,Math.PI*2);ctx.fillStyle='rgba(20,10,20,.3)';ctx.fill();
    });
    ctx.restore();
    if(sandboxMode){
      const label=this.parent?
        (this._parentType==='star'?`⭐ ${this.parent.name||'estrela'}`:`⚫ ${this.parent.name||'BH'}`):
        '🔍 buscando...';
      ctx.font=`${Math.max(6,r*.28)}px 'Courier New'`;
      ctx.fillStyle=this.parent?'rgba(255,190,100,.4)':'rgba(180,140,220,.45)';
      ctx.textAlign='center';ctx.fillText(label,sx,sy+r+8*cam.zoom);ctx.textAlign='left';
    }
  }
}

// ─── 14. SUB-ANÃ MARROM ────────────────────────────────────────────
// Massa intermediária que não sustenta fusão estável. LÓGICA: esfria
// lentamente emitindo pulsos de calor infravermelho que temporariamente
// aquecem planetas próximos (deixando-os com halo laranja). Ocasionalmente
// tenta "acender" — um sub-flare que aumenta o calor mas rapidamente cede.
// Ao resfriar completamente (cool=1), colapsa e se transforma numa
// Blaneta órfã que sai à busca de uma estrela.
class BrownSubdwarf extends CelestialObject{
  constructor(wx,wy){
    super(wx,wy,'exBrownSubdwarf');
    this.radius=rand(6,10);this.mass=this.radius*9;
    this._t=rand(0,Math.PI*2);
    this._cool=0; // 0=quente → 1=totalmente fria (morph)
    this._flareTimer=rand(6,12);this._flareAlpha=0;
    this._flareBoost=0; // aquecimento temporário por sub-flare
    this._irPulseTimer=rand(3,6);this._irPulseR=0;this._irPulseAlpha=0;
    this._bands=Array.from({length:4},()=>({a:rand(0,Math.PI*2),d:rand(.3,.75),s:rand(.1,.2)}));
    this.color='#aa6644';
  }
  update(dt){
    this._t+=dt;
    // Sub-flares: tentam acender mas cedem rapidamente
    this._flareTimer-=dt;
    if(this._flareAlpha>0)this._flareAlpha=Math.max(0,this._flareAlpha-dt*.5);
    if(this._flareBoost>0)this._flareBoost=Math.max(0,this._flareBoost-dt*0.12);
    if(this._flareTimer<=0){
      this._flareTimer=rand(8,16);
      this._flareAlpha=0.7;
      this._flareBoost=0.25; // aquecimento temporário
      // Sub-flare: emite pulso IR
      this._irPulseR=this.radius;this._irPulseAlpha=0.8;
    }
    // Pulso infravermelho — aquece planetas próximos com halo
    this._irPulseTimer-=dt;
    if(this._irPulseAlpha>0){
      this._irPulseR+=dt*this.radius*4;
      this._irPulseAlpha=Math.max(0,this._irPulseAlpha-dt*.45);
      // ao passar por planetas, deixa halo temporário
      objects.forEach(o=>{
        if(o===this||o.dead)return;
        if(!['planet','moon','dwarfplanet','exBlanet'].includes(o.type))return;
        const d=dist(o,this);
        if(Math.abs(d-this._irPulseR)<this.radius*1.5){
          o._irHeat=(o._irHeat||0)+0.4*this._irPulseAlpha;
          o._irHeat=Math.min(1,o._irHeat);
        }
      });
    }
    if(this._irPulseTimer<=0){
      this._irPulseTimer=rand(4,7);
      this._irPulseR=this.radius;this._irPulseAlpha=0.45;
    }
    // Resfria lentamente (sub-flare atrasa ligeiramente)
    const coolRate=0.0012*(1-this._flareBoost*.4);
    this._cool=Math.min(1,this._cool+dt*coolRate);
    // Decai halos IR dos planetas
    objects.forEach(o=>{if((o._irHeat||0)>0)o._irHeat=Math.max(0,o._irHeat-dt*.08);});
    // Morph: ao resfriar completamente, vira Blaneta órfã
    if(this._cool>=1){
      const bl=new Blanet(this.x,this.y);
      bl.vx=(this.vx||0);bl.vy=(this.vy||0);
      bl._glow=0;bl._warmth=0;bl._parentType='none';
      bl._autoSpawn=this._autoSpawn;
      for(let i=0;i<10;i++)particles.push({x:this.x+rand(-this.radius,this.radius),y:this.y+rand(-this.radius,this.radius),vx:rand(-2,2),vy:rand(-2,2),r:rand(1,2.5),alpha:.8,color:'#885533'});
      pendingObjects.push(bl);
      this.dead=true;return;
    }
  }
  draw(){
    const sx=this.sx(),sy=this.sy(),r=this.sr();
    const effectiveCool=Math.max(0,this._cool-this._flareBoost);
    const hue=18-effectiveCool*8,sat=55-effectiveCool*25,light=32-effectiveCool*16;
    // Pulso IR visível
    if(this._irPulseAlpha>0){
      ctx.beginPath();ctx.arc(sx,sy,this._irPulseR*cam.zoom,0,Math.PI*2);
      ctx.strokeStyle=`rgba(255,120,40,${this._irPulseAlpha*.4})`;ctx.lineWidth=2;ctx.stroke();
    }
    if(this._flareAlpha>0){
      const fg=ctx.createRadialGradient(sx,sy,0,sx,sy,r*2.6);
      fg.addColorStop(0,`rgba(255,140,90,${this._flareAlpha*.35})`);fg.addColorStop(1,'transparent');
      ctx.beginPath();ctx.arc(sx,sy,r*2.6,0,Math.PI*2);ctx.fillStyle=fg;ctx.fill();
    }
    const g=ctx.createRadialGradient(sx-r*.3,sy-r*.3,r*.1,sx,sy,r);
    g.addColorStop(0,`hsl(${hue},${sat}%,${light+10}%)`);
    g.addColorStop(.6,`hsl(${hue},${sat-10}%,${light}%)`);
    g.addColorStop(1,`hsl(${hue-6},${sat-20}%,${Math.max(6,light-18)}%)`);
    ctx.beginPath();ctx.arc(sx,sy,r,0,Math.PI*2);ctx.fillStyle=g;ctx.fill();
    ctx.save();ctx.beginPath();ctx.arc(sx,sy,r,0,Math.PI*2);ctx.clip();
    this._bands.forEach(b=>{
      const bx=sx+Math.cos(b.a)*r*b.d,by=sy+Math.sin(b.a)*r*b.d*.6;
      ctx.beginPath();ctx.ellipse(bx,by,r*b.s*1.6,r*b.s,b.a,0,Math.PI*2);
      ctx.fillStyle=`hsla(${hue-4},${sat}%,${Math.max(8,light-10)}%,.4)`;ctx.fill();
    });
    ctx.restore();
    if(sandboxMode){
      const pct=Math.round(this._cool*100);
      const label=pct>=95?'💀 colapsando...':pct>=70?`❄️ ${pct}% fria`:`🔥 ${100-pct}% ativa`;
      ctx.font=`${Math.max(6,r*.35)}px 'Courier New'`;ctx.fillStyle='rgba(255,180,140,.35)';
      ctx.textAlign='center';ctx.fillText(label,sx,sy-r-6*cam.zoom);ctx.textAlign='left';
    }
  }
}

// ─── 15. Q-BALL ─────────────────────────────────────────────────────
// Sóliton não-topológico — bolha de campo coesa e "infecciosa". LÓGICA:
// absorve pequenos detritos crescendo. Contamina planetas próximos com
// "carga Q" — ao acumular carga suficiente, o planeta inteiro se converte
// numa Q-Ball menor. Ao atingir raio máximo, fissão em duas. Cada Q-Ball
// tem uma "frequência" (hue) que ressoa com outras Q-Balls próximas,
// fazendo-as oscilar em sincronia quando se aproximam.
class QBall extends CelestialObject{
  constructor(wx,wy){
    super(wx,wy,'exQBall');
    this.radius=rand(9,14);this.mass=this.radius*9;
    this._t=rand(0,Math.PI*2);
    this._maxRadius=34;
    this._wob=Array.from({length:10},(_,i)=>({a:i*(Math.PI*2/10),ph:rand(0,6),amp:rand(.08,.18)}));
    this._hue=rand(0,360);
    this._resonancePhase=0; // fase de ressonância com Q-Balls próximas
    this._contamRange=this.radius*8;
    this.color='#bb88ff';
  }
  update(dt){
    this._t+=dt;this._hue=(this._hue+dt*18)%360;
    this._contamRange=this.radius*8;
    // Ressonância com outras Q-Balls
    let resonance=0;
    objects.forEach(o=>{
      if(o===this||o.dead||o.type!=='exQBall')return;
      const d=dist(o,this);if(d>this.radius*20)return;
      resonance+=Math.sin(o._t*2)*0.5/(d/this.radius);
    });
    this._resonancePhase=resonance;
    this._wob.forEach(w=>w.ph+=dt*(1.5+resonance*.8));
    // Fissão ao atingir tamanho máximo
    if(this.radius>=this._maxRadius){
      for(let i=0;i<2;i++){
        const a=rand(0,Math.PI*2),nr=this.radius*.62;
        const q=new QBall(this.x+Math.cos(a)*nr,this.y+Math.sin(a)*nr);
        q.radius=nr;q.mass=q.radius*9;
        q.vx=(this.vx||0)+Math.cos(a)*8;q.vy=(this.vy||0)+Math.sin(a)*8;
        q._autoSpawn=this._autoSpawn;
        pendingObjects.push(q);
      }
      this.dead=true;return;
    }
    // Absorção de detritos
    objects.forEach(o=>{
      if(o===this||o.dead)return;
      if(['meteor','comet'].includes(o.type)&&o.radius<=5){
        const d=dist(o,this);if(d>this.radius+o.radius*.6)return;
        this.radius=Math.min(this._maxRadius,this.radius+o.radius*.18);
        this.mass=this.radius*9;
        spawnExplosion(o.x,o.y,.2,false);o.dead=true;
      }
    });
    // Contaminação de planetas: acumula carga Q
    objects.forEach(o=>{
      if(o===this||o.dead||o.fixed)return;
      if(!['planet','moon','dwarfplanet','exBlanet'].includes(o.type))return;
      const d=dist(o,this);if(d>this._contamRange)return;
      // acumula carga Q proporcionalmente à proximidade
      o._qCharge=(o._qCharge||0)+dt*0.04*(1-d/this._contamRange);
      // efeito visual de contaminação: partículas coloridas
      if(Math.random()<0.03){
        const a=Math.atan2(o.y-this.y,o.x-this.x);
        particles.push({x:this.x+Math.cos(a)*this.radius,y:this.y+Math.sin(a)*this.radius,
          vx:(o.x-this.x)/d*3+rand(-1,1),vy:(o.y-this.y)/d*3+rand(-1,1),
          r:rand(.8,2),alpha:.7,color:`hsl(${this._hue},90%,70%)`});
      }
      // Conversão: ao atingir carga suficiente, vira Q-Ball
      if((o._qCharge||0)>=1){
        const q=new QBall(o.x,o.y);
        q.radius=Math.min(16,o.radius*.9);q.mass=q.radius*9;
        q.vx=(o.vx||0);q.vy=(o.vy||0);q._hue=this._hue;
        q._autoSpawn=this._autoSpawn;
        for(let i=0;i<8;i++)particles.push({x:o.x,y:o.y,vx:rand(-3,3),vy:rand(-3,3),r:rand(1,3),alpha:.9,color:`hsl(${this._hue},90%,75%)`});
        pendingObjects.push(q);
        o.dead=true;
      }
    });
  }
  draw(){
    const sx=this.sx(),sy=this.sy(),r=this.sr();
    const resAmp=Math.abs(this._resonancePhase);
    // Anel de ressonância entre Q-Balls
    if(resAmp>0.1){
      ctx.beginPath();ctx.arc(sx,sy,r*(1.6+resAmp*.5),0,Math.PI*2);
      ctx.strokeStyle=`hsla(${this._hue},80%,70%,${Math.min(.35,resAmp*.2)})`;ctx.lineWidth=1.5;ctx.stroke();
    }
    // Corpo wobbly
    ctx.beginPath();
    this._wob.forEach((w,i)=>{
      const wobAmp=w.amp*(1+resAmp*.4);
      const rr=r*(1+wobAmp*Math.sin(this._t*2+w.ph));
      const px=sx+Math.cos(w.a)*rr,py=sy+Math.sin(w.a)*rr;
      if(i===0)ctx.moveTo(px,py);else ctx.lineTo(px,py);
    });
    ctx.closePath();
    const g=ctx.createRadialGradient(sx,sy,0,sx,sy,r*1.1);
    g.addColorStop(0,`hsla(${this._hue},90%,80%,.85)`);
    g.addColorStop(.6,`hsla(${(this._hue+60)%360},85%,60%,.55)`);
    g.addColorStop(1,`hsla(${(this._hue+120)%360},80%,40%,.25)`);
    ctx.fillStyle=g;ctx.fill();
    ctx.strokeStyle=`hsla(${this._hue},90%,85%,.5)`;ctx.lineWidth=1.5;ctx.stroke();
    if(sandboxMode){
      const pct=Math.round((this.radius/this._maxRadius)*100);
      ctx.font=`${Math.max(6,r*.25)}px 'Courier New'`;ctx.fillStyle='rgba(220,200,255,.4)';
      ctx.textAlign='center';ctx.fillText(`⚡${pct}%`,sx,sy+r+8*cam.zoom);ctx.textAlign='left';
    }
  }
}

// ─── 16. GEON ───────────────────────────────────────────────────────
// Anel de energia auto-confinado. LÓGICA: puxa objetos até o anel e os
// faz orbitá-lo como satélites. Periodicamente, o anel "pulsa" —
// acelerando todos os satélites orbitantes como um estilingue em cadeia.
// É instável: a vida útil encurta a cada pulso. Ao colapsar, libera
// todos os satélites em rajada centrífuga + uma explosão de fótons.
class Geon extends CelestialObject{
  constructor(wx,wy){
    super(wx,wy,'exGeon');
    this.radius=rand(16,24);this.mass=this.radius*6;
    this._t=rand(0,Math.PI*2);
    this._ringRot=rand(0,Math.PI*2);
    this._photons=Array.from({length:5},(_,i)=>({ph:i*(Math.PI*2/5)}));
    this._life=rand(50,80);this._maxLife=this._life;
    this._slingTimer=rand(6,10); // timer para pulso do estilingue
    this._slingFlash=0;
    this._captured=[]; // objetos recrutados para órbita
    this.color='#88ffcc';
  }
  update(dt){
    this._t+=dt;this._ringRot+=dt*4;
    this._life-=dt;
    if(this._slingFlash>0)this._slingFlash=Math.max(0,this._slingFlash-dt*3);
    if(this._life<=0){
      // Colapso: libera todos os capturados em rajada
      this._captured.forEach(o=>{
        if(o.dead)return;
        const a=rand(0,Math.PI*2);
        const burst=12+Math.random()*18;
        o.vx=Math.cos(a)*burst;o.vy=Math.sin(a)*burst;
        o._geonCapture=false;
      });
      // Explosão de fótons
      for(let i=0;i<20;i++){
        const a=rand(0,Math.PI*2);const sp=rand(8,25);
        particles.push({x:this.x,y:this.y,vx:Math.cos(a)*sp,vy:Math.sin(a)*sp,r:rand(1,3),alpha:1,color:'#aaffd8'});
      }
      spawnExplosion(this.x,this.y,.6,false);
      this.dead=true;return;
    }
    // Captura de objetos próximos: puxa em direção ao anel e recruta
    this._captured=this._captured.filter(o=>!o.dead);
    objects.forEach(o=>{
      if(o===this||o.dead||o.fixed)return;
      const d=dist(o,this);if(d>this.radius*3||d<1)return;
      const diff=d-this.radius;
      if(Math.abs(diff)<this.radius*.3){
        // No anel: força tangencial (orbita)
        const tx=-(o.y-this.y)/d,ty=(o.x-this.x)/d;
        o.vx=(o.vx||0)+tx*5*dt;o.vy=(o.vy||0)+ty*5*dt;
        o._geonCapture=true;
        if(!this._captured.includes(o))this._captured.push(o);
      } else if(diff>0){
        // Fora do anel: puxa para dentro
        const f=6*(diff/this.radius);
        o.vx=(o.vx||0)+(this.x-o.x)/d*f*dt;o.vy=(o.vy||0)+(this.y-o.y)/d*f*dt;
      } else {
        // Dentro do anel: empurra para fora
        const f=5*(Math.abs(diff)/this.radius);
        o.vx=(o.vx||0)+(o.x-this.x)/d*f*dt;o.vy=(o.vy||0)+(o.y-this.y)/d*f*dt;
      }
    });
    // Pulso do estilingue: acelera todos os capturados
    this._slingTimer-=dt;
    if(this._slingTimer<=0){
      this._slingTimer=rand(5,9);
      this._slingFlash=1;
      this._life-=4; // cada pulso consome vida
      this._captured.forEach(o=>{
        if(o.dead)return;
        const d=dist(o,this)||1;
        const tx=-(o.y-this.y)/d,ty=(o.x-this.x)/d;
        const boost=10+Math.random()*14;
        o.vx=(o.vx||0)+tx*boost;o.vy=(o.vy||0)+ty*boost;
        for(let i=0;i<4;i++)particles.push({x:o.x,y:o.y,vx:rand(-2,2),vy:rand(-2,2),r:rand(.8,2),alpha:.8,color:'#88ffd0'});
      });
    }
  }
  draw(){
    const sx=this.sx(),sy=this.sy(),r=this.sr();
    const lifeFrac=Math.max(0,this._life/this._maxLife);
    const shrink=lifeFrac<.15?(lifeFrac/.15):1;
    // Flash do estilingue
    if(this._slingFlash>0){
      ctx.beginPath();ctx.arc(sx,sy,r*shrink*(1+this._slingFlash*.4),0,Math.PI*2);
      ctx.strokeStyle=`rgba(150,255,200,${this._slingFlash*.6})`;ctx.lineWidth=3;ctx.stroke();
    }
    // Halo central
    const gc=ctx.createRadialGradient(sx,sy,0,sx,sy,r*.6);
    gc.addColorStop(0,'rgba(150,255,220,.18)');gc.addColorStop(1,'transparent');
    ctx.beginPath();ctx.arc(sx,sy,r*.6,0,Math.PI*2);ctx.fillStyle=gc;ctx.fill();
    // Anel principal
    const ringR=r*shrink;
    ctx.beginPath();ctx.arc(sx,sy,ringR,0,Math.PI*2);
    ctx.strokeStyle=`rgba(120,255,210,${.35*shrink+.15*Math.abs(Math.sin(this._t*3))})`;
    ctx.lineWidth=Math.max(1,r*(this._slingFlash>.2?.2:.12));ctx.stroke();
    // Fótons orbitantes
    this._photons.forEach(p=>{
      const a=this._ringRot+p.ph;
      const px=sx+Math.cos(a)*ringR,py=sy+Math.sin(a)*ringR;
      ctx.beginPath();ctx.arc(px,py,Math.max(.8,r*.1),0,Math.PI*2);
      ctx.fillStyle='rgba(220,255,245,.95)';ctx.fill();
    });
    // Contador de capturados + aviso
    if(sandboxMode){
      const label=lifeFrac<.25?`⚠️ ${Math.round(lifeFrac*100)}% vida`:`🌀 ${this._captured.filter(o=>!o.dead).length} capturados`;
      ctx.font=`${Math.max(6,r*.18)}px 'Courier New'`;ctx.fillStyle='rgba(150,255,220,.5)';
      ctx.textAlign='center';ctx.fillText(label,sx,sy-r*shrink-6*cam.zoom);ctx.textAlign='left';
    }
  }
}

// ─── 17. MURALHA DE DOMÍNIO ──────────────────────────────────────────
// Defeito topológico que age como uma válvula de fase. LÓGICA: objetos
// LENTOS (abaixo do limiar) atravessam e mudam de "vácuo" — ficam com
// cor tingida pela outra fase. Objetos RÁPIDOS são refletidos com brilho.
// A muralha CRESCE lentamente até dobrar de tamanho e então encolhe
// ciclicamente, como um defeito topológico respirando.
class DomainWall extends CelestialObject{
  constructor(wx,wy){
    super(wx,wy,'exDomainWall');
    this.radius=10;this.mass=6000;
    this._t=rand(0,Math.PI*2);
    this._baseLen=rand(280,420);
    this._len=this._baseLen;
    this._angle=rand(0,Math.PI);
    this._segs=16;
    this._hueA=rand(180,240);this._hueB=rand(280,340);
    this._speedThreshold=5; // abaixo disso, atravessa; acima, reflete
    this._breathPhase=rand(0,Math.PI*2);
    this._tingedObjs=new Map(); // objetos tingidos pela fase
    this.color='#88aaff';
  }
  update(dt){
    this._t+=dt;this._breathPhase+=dt*.2;
    // Respiração: len oscila entre baseLen e baseLen*1.8
    this._len=this._baseLen*(1+0.8*(.5+.5*Math.sin(this._breathPhase)));
    const dx=Math.cos(this._angle),dy=Math.sin(this._angle);
    const sideKey='_dwSide_'+this.id;
    objects.forEach(o=>{
      if(o===this||o.dead||o.fixed)return;
      const relX=o.x-this.x,relY=o.y-this.y;
      const proj=relX*dx+relY*dy;
      if(Math.abs(proj)>this._len/2)return;
      const perp=relX*(-dy)+relY*dx;
      const side=Math.sign(perp)||1;
      if(o[sideKey]===undefined)o[sideKey]=side;
      if(side!==o[sideKey]&&Math.abs(perp)<o.radius+8){
        const speed=Math.hypot(o.vx||0,o.vy||0);
        if(speed<this._speedThreshold){
          // Objeto lento: ATRAVESSA — muda de fase e fica tingido
          o[sideKey]=side;
          const hue=side>0?this._hueB:this._hueA;
          o._domainTint={hue,alpha:0.8,timer:8};
          for(let i=0;i<4;i++)particles.push({x:o.x,y:o.y,vx:rand(-1.5,1.5),vy:rand(-1.5,1.5),r:rand(.8,2),alpha:.7,color:`hsl(${hue},80%,72%)`});
        } else {
          // Objeto rápido: REFLETIDO com brilho
          const vp=((o.vx||0)*(-dy)+(o.vy||0)*dx);
          o.vx=(o.vx||0)-2*(-dy)*vp*.92;o.vy=(o.vy||0)-2*dx*vp*.92;
          o[sideKey]=side; // não muda de fase — foi rejeitado
          const hue=side>0?this._hueA:this._hueB;
          for(let i=0;i<7;i++)particles.push({x:o.x,y:o.y,vx:rand(-3,3),vy:rand(-3,3),r:rand(1,2.8),alpha:.9,color:`hsl(${hue},90%,78%)`});
        }
      }
    });
    // Decai tingimento ao longo do tempo
    objects.forEach(o=>{
      if(!o._domainTint)return;
      o._domainTint.timer-=dt;
      o._domainTint.alpha=Math.max(0,o._domainTint.alpha-dt*.06);
      if(o._domainTint.timer<=0||o._domainTint.alpha<=0)delete o._domainTint;
    });
  }
  draw(){
    const dx=Math.cos(this._angle),dy=Math.sin(this._angle);
    const x1=this.x-dx*this._len/2,y1=this.y-dy*this._len/2;
    const x2=this.x+dx*this._len/2,y2=this.y+dy*this._len/2;
    const p1=worldToScreen(x1,y1),p2=worldToScreen(x2,y2);
    const w=14*cam.zoom;
    ctx.save();ctx.translate(p1.x,p1.y);
    const ang=Math.atan2(p2.y-p1.y,p2.x-p1.x);
    ctx.rotate(ang);
    const len=Math.hypot(p2.x-p1.x,p2.y-p1.y);
    // Intensidade varia com respiração
    const breathAmt=.5+.5*Math.sin(this._breathPhase);
    const grad=ctx.createLinearGradient(0,-w,0,w);
    grad.addColorStop(0,`hsla(${this._hueA},80%,60%,${.18+.14*breathAmt})`);
    grad.addColorStop(.5,`hsla(${(this._hueA+this._hueB)/2},90%,80%,${.4+.2*breathAmt})`);
    grad.addColorStop(1,`hsla(${this._hueB},80%,60%,${.18+.14*breathAmt})`);
    ctx.fillStyle=grad;
    ctx.beginPath();
    for(let i=0;i<=this._segs;i++){
      const t=i/this._segs;const wob=Math.sin(this._t*2+t*Math.PI*6)*4*cam.zoom;
      if(i===0)ctx.moveTo(t*len+wob,-w);else ctx.lineTo(t*len+wob,-w);
    }
    for(let i=this._segs;i>=0;i--){
      const t=i/this._segs;const wob=Math.sin(this._t*2+t*Math.PI*6)*4*cam.zoom;
      ctx.lineTo(t*len+wob,w);
    }
    ctx.closePath();ctx.fill();
    // Linha central com threshold indicado
    ctx.beginPath();ctx.moveTo(0,0);ctx.lineTo(len,0);
    ctx.strokeStyle=`rgba(255,255,255,${.3+.2*Math.sin(this._t*3)})`;ctx.lineWidth=1.5;ctx.stroke();
    // Seta indicando "lento passa, rápido reflete"
    if(cam.zoom>0.4){
      const mx=len/2;
      ctx.fillStyle=`rgba(255,255,255,${.4+.15*breathAmt})`;
      ctx.font=`${Math.max(8,10*cam.zoom)}px monospace`;
      ctx.textAlign='center';ctx.fillText(`v<${this._speedThreshold}→`,mx,-w-3*cam.zoom);
      ctx.textAlign='left';
    }
    ctx.restore();
    // Renderiza tingimento nos objetos na cena principal (feito pelo próprio objeto tingido via _domainTint)
  }
}

// ─── 18. CRISTAL DE ESPAÇO-TEMPO CRÍTICO ─────────────────────────────
// Cristal de tempo com periodicidade própria. LÓGICA: emite "batidas"
// rítmicas que sincronizam as velocidades angulares de planetas orbitantes
// próximos (ressonância de fase). Na fase negativa do ciclo, pulsa uma
// onda de "compressão temporal" que freia todos os objetos próximos —
// como se o tempo engasgasse. Na fase positiva, os solta com boost.
// Acumula "facetas" — a cada sincronização, ganha mais complexidade visual.
class SpacetimeCrystal extends CelestialObject{
  constructor(wx,wy){
    super(wx,wy,'exSpacetimeCrystal');
    this.radius=rand(11,16);this.mass=this.radius*10;
    this._t=rand(0,Math.PI*2);
    this._period=rand(3,5);
    this._facets=8;
    this._maxFacets=24;
    this._rot=rand(0,Math.PI*2);
    this._syncCount=0; // quantos objetos sincronizados
    this._compressFlash=0;
    this._boostFlash=0;
    this._frozenVels=new Map(); // guarda velocidades comprimidas
    this.color='#aef0ff';
  }
  update(dt){
    this._t+=dt;this._rot+=dt*.3;
    if(this._compressFlash>0)this._compressFlash=Math.max(0,this._compressFlash-dt*2);
    if(this._boostFlash>0)this._boostFlash=Math.max(0,this._boostFlash-dt*2);
    const phase=Math.sin((this._t/this._period)*Math.PI*2);
    const range=this.radius*10;
    const prevPhaseNeg=Math.sin(((this._t-dt)/this._period)*Math.PI*2);
    // Detecta transição para fase negativa (compressão) ou positiva (release)
    const crossNeg=prevPhaseNeg>=0&&phase<0;
    const crossPos=prevPhaseNeg<0&&phase>=0;
    if(crossNeg){
      // COMPRESSÃO: freia todos os objetos próximos e armazena velocidade
      this._compressFlash=1;this._frozenVels.clear();
      objects.forEach(o=>{
        if(o===this||o.dead||o.fixed)return;
        const d=dist(o,this);if(d>range)return;
        const frac=Math.max(0,1-d/range);
        this._frozenVels.set(o,{vx:(o.vx||0)*frac*.6,vy:(o.vy||0)*frac*.6});
        o.vx=(o.vx||0)*(1-frac*.7);o.vy=(o.vy||0)*(1-frac*.7);
        for(let i=0;i<2;i++)particles.push({x:o.x,y:o.y,vx:rand(-.5,.5),vy:rand(-.5,.5),r:rand(.5,1.5),alpha:.6,color:'#c0f0ff'});
      });
    } else if(crossPos){
      // RELEASE: devolve velocidades armazenadas com boost (1.5x)
      this._boostFlash=1;
      this._frozenVels.forEach((vel,o)=>{
        if(o.dead)return;
        o.vx=(o.vx||0)+vel.vx*1.5;o.vy=(o.vy||0)+vel.vy*1.5;
        for(let i=0;i<3;i++)particles.push({x:o.x,y:o.y,vx:rand(-2,2),vy:rand(-2,2),r:rand(1,2.5),alpha:.8,color:'#aafcff'});
      });
      // Sincroniza objetos com órbitas: alinha fases orbitais
      let synced=0;
      objects.forEach(o=>{
        if(o===this||o.dead||!o.orbitAngle||!o.parent)return;
        const d=dist(o,this);if(d>range)return;
        // Pequeno ajuste de fase — puxa orbitAngle em direção a múltiplos do período
        const snap=Math.PI*2/4; // snaps para quadrantes
        const target=Math.round(o.orbitAngle/snap)*snap;
        o.orbitAngle+=(target-o.orbitAngle)*0.08;
        synced++;
      });
      this._syncCount=synced;
      // A cada sincronização, ganha facetas (até o máximo)
      if(synced>0)this._facets=Math.min(this._maxFacets,this._facets+1);
    } else {
      // Durante o ciclo: força suave de ressonância
      objects.forEach(o=>{
        if(o===this||o.dead||o.fixed)return;
        const d=dist(o,this);if(d>range||d<1)return;
        const f=phase*7*(1-d/range);
        o.vx=(o.vx||0)+(o.x-this.x)/d*f*dt;o.vy=(o.vy||0)+(o.y-this.y)/d*f*dt;
      });
    }
  }
  draw(){
    const sx=this.sx(),sy=this.sy(),r=this.sr();
    const phase=Math.sin((this._t/this._period)*Math.PI*2);
    const scale=1+phase*.12;
    // Flash de compressão (azul-gelo)
    if(this._compressFlash>0){
      const cr=this.radius*10*cam.zoom;
      const gc=ctx.createRadialGradient(sx,sy,0,sx,sy,cr);
      gc.addColorStop(0,`rgba(160,240,255,${this._compressFlash*.25})`);gc.addColorStop(1,'transparent');
      ctx.beginPath();ctx.arc(sx,sy,cr,0,Math.PI*2);ctx.fillStyle=gc;ctx.fill();
    }
    // Flash de release (branco-energético)
    if(this._boostFlash>0){
      ctx.beginPath();ctx.arc(sx,sy,this.radius*10*cam.zoom*this._boostFlash,0,Math.PI*2);
      ctx.strokeStyle=`rgba(255,255,255,${this._boostFlash*.4})`;ctx.lineWidth=2;ctx.stroke();
    }
    // Halo geral
    const ga=ctx.createRadialGradient(sx,sy,0,sx,sy,r*2.4*scale);
    ga.addColorStop(0,`rgba(170,240,255,${.15+.1*phase})`);ga.addColorStop(1,'transparent');
    ctx.beginPath();ctx.arc(sx,sy,r*2.4*scale,0,Math.PI*2);ctx.fillStyle=ga;ctx.fill();
    // Cristal facetado (facets cresce com sincronizações)
    ctx.save();ctx.translate(sx,sy);ctx.rotate(this._rot);
    ctx.beginPath();
    for(let i=0;i<this._facets;i++){
      const a=i*(Math.PI*2/this._facets);
      const rr=r*scale*(i%2===0?1:.72);
      const px=Math.cos(a)*rr,py=Math.sin(a)*rr;
      if(i===0)ctx.moveTo(px,py);else ctx.lineTo(px,py);
    }
    ctx.closePath();
    const g=ctx.createLinearGradient(-r,-r,r,r);
    g.addColorStop(0,'#eafcff');g.addColorStop(.5,'#7fd8ff');g.addColorStop(1,'#2a6f99');
    ctx.fillStyle=g;ctx.fill();
    ctx.strokeStyle=`rgba(255,255,255,${.4+.3*Math.abs(phase)})`;ctx.lineWidth=1.5;ctx.stroke();
    for(let i=0;i<this._facets;i++){
      const a=i*(Math.PI*2/this._facets);
      ctx.beginPath();ctx.moveTo(0,0);ctx.lineTo(Math.cos(a)*r*scale*.9,Math.sin(a)*r*scale*.9);
      ctx.strokeStyle=`rgba(255,255,255,${.12+.22*Math.abs(phase)})`;ctx.lineWidth=1;ctx.stroke();
    }
    ctx.restore();
    if(sandboxMode&&this._syncCount>0){
      ctx.font=`${Math.max(6,r*.22)}px 'Courier New'`;ctx.fillStyle='rgba(180,240,255,.4)';
      ctx.textAlign='center';ctx.fillText(`🔮 ${this._syncCount} em sinc`,sx,sy+r*scale+8*cam.zoom);ctx.textAlign='left';
    }
  }
}

// ─── 19. KUGELBLITZ ───────────────────────────────────────────────
// "Buraco negro de luz" formado por radiação pura. LÓGICA: periodicamente
// dispara raios de luz em direções aleatórias — objetos atingidos ficam
// "marcados" (brilho ciano residual) e passam a ser atraídos de volta
// pelo Kugelblitz como se fossem reféns da luz. Objetos na casca de luz
// (zona estável) orbitam e ocasionalmente são "ejetados" como lasers.
class Kugelblitz extends CelestialObject{
  constructor(wx,wy){
    super(wx,wy,'exKugelblitz');
    this.radius=rand(6,9);this.mass=this.radius*38;
    this._t=rand(0,Math.PI*2);
    this._shellR=this.radius*rand(3.2,4.4);
    this._flicker=0;
    this._rayTimer=rand(1.5,3);
    this._rays=[]; // raios ativos {a, len, alpha}
    this._markedObjs=new Set();
    this.color='#eaffff';
  }
  update(dt){
    this._t+=dt;this._flicker=Math.sin(this._t*9)*.5+.5;
    this._rayTimer-=dt;
    // Decai raios
    this._rays=this._rays.filter(r=>{r.alpha-=dt*1.5;r.len+=dt*this._shellR*2;return r.alpha>0;});
    // Dispara novo raio
    if(this._rayTimer<=0){
      this._rayTimer=rand(1,2.5);
      const numRays=randInt(1,3);
      for(let i=0;i<numRays;i++){
        const a=rand(0,Math.PI*2);
        this._rays.push({a,len:this.radius,alpha:1});
        // Verifica objetos na trajetória do raio
        objects.forEach(o=>{
          if(o===this||o.dead||o.fixed)return;
          const ao=Math.atan2(o.y-this.y,o.x-this.x);
          const angDiff=Math.abs(((ao-a)+Math.PI*3)%(Math.PI*2)-Math.PI);
          const d=dist(o,this);
          if(angDiff<0.25&&d<this._shellR*2.5){
            // Marcado pelo raio
            o._kgMark={alpha:1,timer:12,src:this};
            this._markedObjs.add(o);
            for(let j=0;j<4;j++)particles.push({x:o.x,y:o.y,vx:rand(-2,2),vy:rand(-2,2),r:rand(.8,2),alpha:.85,color:'#80f8ff'});
          }
        });
      }
    }
    // Atrai objetos marcados de volta
    this._markedObjs=new Set([...this._markedObjs].filter(o=>!o.dead));
    this._markedObjs.forEach(o=>{
      if(o.dead){return;}
      if(!o._kgMark){this._markedObjs.delete(o);return;}
      o._kgMark.timer-=dt;
      o._kgMark.alpha=Math.max(0,o._kgMark.alpha-dt*.05);
      if(o._kgMark.timer<=0||o._kgMark.alpha<=0){delete o._kgMark;this._markedObjs.delete(o);return;}
      const d=dist(o,this)||1;
      // Atração ao Kugelblitz proporcional ao mark alpha
      const pull=5*o._kgMark.alpha*(1-Math.min(1,d/(this._shellR*3)));
      o.vx=(o.vx||0)+(this.x-o.x)/d*pull*dt;o.vy=(o.vy||0)+(this.y-o.y)/d*pull*dt;
    });
    // Física da casca: objetos na casca ficam em órbita
    objects.forEach(o=>{
      if(o===this||o.dead||o.fixed)return;
      const d=dist(o,this);if(d>this.radius*8||d<1)return;
      const nx=(o.x-this.x)/d,ny=(o.y-this.y)/d;
      const diff=d-this._shellR;
      const f=8*Math.tanh(diff/this.radius);
      o.vx=(o.vx||0)-nx*f*dt;o.vy=(o.vy||0)-ny*f*dt;
      if(Math.abs(diff)<this._shellR*.5){
        const tx=-ny,ty=nx;
        o.vx+=tx*3*dt;o.vy+=ty*3*dt;
      }
    });
  }
  draw(){
    const sx=this.sx(),sy=this.sy(),r=this.sr();
    const shellPx=this._shellR*cam.zoom;
    // Raios de luz
    this._rays.forEach(ray=>{
      const ex=sx+Math.cos(ray.a)*ray.len*cam.zoom;
      const ey=sy+Math.sin(ray.a)*ray.len*cam.zoom;
      const gr=ctx.createLinearGradient(sx,sy,ex,ey);
      gr.addColorStop(0,`rgba(255,255,255,${ray.alpha*.9})`);
      gr.addColorStop(.6,`rgba(160,245,255,${ray.alpha*.5})`);
      gr.addColorStop(1,'transparent');
      ctx.beginPath();ctx.moveTo(sx,sy);ctx.lineTo(ex,ey);
      ctx.strokeStyle=gr;ctx.lineWidth=Math.max(1,r*.2);ctx.stroke();
    });
    // Casca de luz
    const go=ctx.createRadialGradient(sx,sy,0,sx,sy,shellPx*1.6);
    go.addColorStop(0,'transparent');go.addColorStop(.7,'rgba(140,220,255,.12)');go.addColorStop(1,'transparent');
    ctx.beginPath();ctx.arc(sx,sy,shellPx*1.6,0,Math.PI*2);ctx.fillStyle=go;ctx.fill();
    ctx.beginPath();ctx.arc(sx,sy,shellPx,0,Math.PI*2);
    ctx.strokeStyle='rgba(10,20,30,.55)';ctx.lineWidth=Math.max(1,r*.6);ctx.stroke();
    // Núcleo
    const g=ctx.createRadialGradient(sx,sy,0,sx,sy,r*(1+.2*this._flicker));
    g.addColorStop(0,'#ffffff');g.addColorStop(.4,'#cdf6ff');g.addColorStop(1,'#5fb8ff');
    ctx.beginPath();ctx.arc(sx,sy,r*(1+.2*this._flicker),0,Math.PI*2);ctx.fillStyle=g;ctx.fill();
    for(let i=0;i<8;i++){
      const a=this._t*.5+i*(Math.PI*2/8);
      ctx.beginPath();ctx.moveTo(sx+Math.cos(a)*r,sy+Math.sin(a)*r);
      ctx.lineTo(sx+Math.cos(a)*r*2.4,sy+Math.sin(a)*r*2.4);
      ctx.strokeStyle=`rgba(220,250,255,${.25*this._flicker})`;ctx.lineWidth=1;ctx.stroke();
    }
    // Objetos marcados (halo ciano nos próprios objetos — renderizado aqui)
    objects.forEach(o=>{
      if(!o._kgMark||o.dead)return;
      const ox=o.sx(),oy=o.sy(),or=o.sr();
      ctx.beginPath();ctx.arc(ox,oy,or*(1.3+.1*Math.sin(this._t*5)),0,Math.PI*2);
      ctx.strokeStyle=`rgba(100,245,255,${o._kgMark.alpha*.6})`;ctx.lineWidth=1.5;ctx.stroke();
    });
    if(sandboxMode&&this._markedObjs.size>0){
      ctx.font=`${Math.max(6,r*.3)}px 'Courier New'`;ctx.fillStyle='rgba(140,240,255,.4)';
      ctx.textAlign='center';ctx.fillText(`💡 ${this._markedObjs.size} marcados`,sx,sy-r*1.2-6*cam.zoom);ctx.textAlign='left';
    }
  }
}

// ─── 20. ESTRELA DE ENERGIA ESCURA ────────────────────────────────
// Interior com pressão negativa imitando a energia escura cósmica.
// LÓGICA: empurra objetos com força PROPORCIONAL À DISTÂNCIA (Hubble
// local) — quanto mais longe, maior o empurrão. Isso cria um "vácuo"
// crescente: objetos próximos conseguem resistir à gravidade, mas os
// distantes são inexoravelmente acelerados para fora. Periodicamente
// emite uma "onda de expansão" que redefine o patamar de velocidade de
// fuga local, criando um pico de ejeção dramático.
class DarkEnergyStar extends CelestialObject{
  constructor(wx,wy){
    super(wx,wy,'exDarkEnergyStar');
    this.radius=rand(14,20);this.mass=this.radius*6;
    this._t=rand(0,Math.PI*2);
    this._rings=[];this._ringTimer=rand(1,2);
    this._hubbleK=0.008; // constante de expansão local
    this._vacuumR=this.radius*2; // raio do vácuo central (cresce lentamente)
    this._expansionTimer=rand(8,14); // timer para onda de expansão
    this._expansionFlash=0;
    this._ejectCount=0; // total de objetos ejetados
    this.color='#cc55ff';
  }
  update(dt){
    this._t+=dt;this._ringTimer-=dt;this._expansionTimer-=dt;
    if(this._expansionFlash>0)this._expansionFlash=Math.max(0,this._expansionFlash-dt*1.2);
    // Cresce vácuo central lentamente
    this._vacuumR=Math.min(this.radius*5,this._vacuumR+dt*this.radius*.03);
    // Anéis visuais contínuos
    if(this._ringTimer<=0){this._ringTimer=rand(1.4,2.2);this._rings.push({r:this._vacuumR,a:.7});}
    this._rings=this._rings.filter(s=>{s.r+=dt*this.radius*2.6;s.a-=dt*.28;return s.a>0;});
    const maxR=this.radius*14;
    objects.forEach(o=>{
      if(o===this||o.dead||o.fixed)return;
      const d=dist(o,this);if(d<1)return;
      if(d<this._vacuumR){
        // Dentro do vácuo: repulsão forte de curto alcance
        const f=25*(1-d/this._vacuumR);
        o.vx=(o.vx||0)+(o.x-this.x)/d*f*dt;o.vy=(o.vy||0)+(o.y-this.y)/d*f*dt;
      } else if(d<maxR){
        // Fora do vácuo: força proporcional à distância (Hubble local)
        const fHubble=this._hubbleK*d;
        o.vx=(o.vx||0)+(o.x-this.x)/d*fHubble*dt*60;
        o.vy=(o.vy||0)+(o.y-this.y)/d*fHubble*dt*60;
      }
    });
    // Onda de expansão periódica: impulso extra em todos os objetos no alcance
    if(this._expansionTimer<=0){
      this._expansionTimer=rand(10,16);
      this._expansionFlash=1;
      this._rings.push({r:this._vacuumR,a:1.2}); // anel especial
      objects.forEach(o=>{
        if(o===this||o.dead||o.fixed)return;
        const d=dist(o,this)||1;if(d>maxR)return;
        // Impulso extra — mais forte para objetos mais distantes
        const frac=d/maxR;
        const burst=18*frac+4;
        o.vx=(o.vx||0)+(o.x-this.x)/d*burst;o.vy=(o.vy||0)+(o.y-this.y)/d*burst;
        if(frac>0.5)this._ejectCount++;
        for(let i=0;i<2;i++)particles.push({x:o.x,y:o.y,vx:rand(-2,2),vy:rand(-2,2),r:rand(.8,2),alpha:.7,color:'#cc66ff'});
      });
    }
  }
  draw(){
    const sx=this.sx(),sy=this.sy(),r=this.sr();
    // Anéis de expansão
    this._rings.forEach(s=>{
      ctx.beginPath();ctx.arc(sx,sy,s.r*cam.zoom,0,Math.PI*2);
      ctx.strokeStyle=`rgba(220,120,255,${s.a})`;ctx.lineWidth=s.a>1?2.5:2;ctx.stroke();
    });
    // Onda de expansão especial
    if(this._expansionFlash>0){
      const ef=this.radius*14*cam.zoom*this._expansionFlash;
      const ge=ctx.createRadialGradient(sx,sy,this._vacuumR*cam.zoom,sx,sy,ef);
      ge.addColorStop(0,`rgba(200,100,255,${this._expansionFlash*.2})`);ge.addColorStop(1,'transparent');
      ctx.beginPath();ctx.arc(sx,sy,ef,0,Math.PI*2);ctx.fillStyle=ge;ctx.fill();
    }
    // Vácuo central visível
    ctx.beginPath();ctx.arc(sx,sy,this._vacuumR*cam.zoom,0,Math.PI*2);
    ctx.strokeStyle=`rgba(180,80,255,${.15+.1*Math.sin(this._t*2)})`;
    ctx.setLineDash([4,6]);ctx.lineWidth=1;ctx.stroke();ctx.setLineDash([]);
    // Núcleo
    const g=ctx.createRadialGradient(sx,sy,0,sx,sy,r);
    g.addColorStop(0,'#1a0026');g.addColorStop(.7,'#3d0a55');g.addColorStop(1,'#cc66ff');
    ctx.beginPath();ctx.arc(sx,sy,r,0,Math.PI*2);ctx.fillStyle=g;ctx.fill();
    ctx.beginPath();ctx.arc(sx,sy,r,0,Math.PI*2);
    ctx.strokeStyle=`rgba(255,170,255,${.5+.3*Math.sin(this._t*2)})`;ctx.lineWidth=2;ctx.stroke();
    if(sandboxMode){
      ctx.font=`${Math.max(6,r*.25)}px 'Courier New'`;ctx.fillStyle='rgba(200,140,255,.4)';
      ctx.textAlign='center';
      ctx.fillText(`💜 vácuo ${Math.round(this._vacuumR)}u`,sx,sy+r+8*cam.zoom);
      ctx.textAlign='left';
    }
  }
}

class NeutronStar extends CelestialObject{
  constructor(wx,wy){
    this.radius=rand(4,7);this.mass=this.radius*15;
    this.spinAngle=0;this.spinSpeed=rand(14,22);this.pullRange=this.radius*8;
    this.fixed=false;
  }
  draw(t){
    const sx=this.sx(),sy=this.sy(),r=this.sr();
    this.spinAngle+=.04;
    // Faint pull range
    ctx.beginPath();ctx.arc(sx,sy,this.pullRange*cam.zoom,0,Math.PI*2);
    ctx.strokeStyle='rgba(200,220,255,0.04)';ctx.lineWidth=1;ctx.stroke();
    // Glow
    const g=ctx.createRadialGradient(sx,sy,0,sx,sy,r*3);
    g.addColorStop(0,'rgba(200,230,255,.35)');g.addColorStop(1,'transparent');
    ctx.beginPath();ctx.arc(sx,sy,r*3,0,Math.PI*2);ctx.fillStyle=g;ctx.fill();
    // Core
    const gc=ctx.createRadialGradient(sx,sy,0,sx,sy,r);
    gc.addColorStop(0,'#ffffff');gc.addColorStop(.4,'#aad4ff');gc.addColorStop(1,'#2040a0');
    ctx.beginPath();ctx.arc(sx,sy,r,0,Math.PI*2);ctx.fillStyle=gc;ctx.fill();
    // Fast spin rings
    ctx.save();ctx.translate(sx,sy);ctx.rotate(this.spinAngle);ctx.scale(1,.25);
    ctx.beginPath();ctx.arc(0,0,r*1.6,0,Math.PI*2);
    ctx.strokeStyle='rgba(150,200,255,.5)';ctx.lineWidth=1.5;ctx.stroke();ctx.restore();
  }
}

// ═══════════════════════════════════════════════════════════════════
//  PULSAR PLANET — exotic planet orbiting a pulsar remnant
// ═══════════════════════════════════════════════════════════════════
class PulsarPlanet extends CelestialObject{
  constructor(wx,wy){
    super(wx,wy,'pulsarplanet');
    this.radius=rand(8,14);this.mass=this.radius*3;
    this.glowHue=randInt(160,300);this.ringAngle=rand(0,Math.PI);
    this.fixed=false;this.vx=rand(-2,2);this.vy=rand(-2,2);
  }
  draw(t){
    const sx=this.sx(),sy=this.sy(),r=this.sr();
    // Exotic outer glow
    const g=ctx.createRadialGradient(sx,sy,r*.4,sx,sy,r*3.2);
    g.addColorStop(0,`hsla(${this.glowHue},100%,70%,.22)`);
    g.addColorStop(1,'transparent');
    ctx.beginPath();ctx.arc(sx,sy,r*3.2,0,Math.PI*2);ctx.fillStyle=g;ctx.fill();
    // Body — dark with colored band
    const gc=ctx.createRadialGradient(sx-r*.3,sy-r*.3,r*.1,sx,sy,r);
    gc.addColorStop(0,`hsl(${this.glowHue},80%,75%)`);
    gc.addColorStop(.45,`hsl(${this.glowHue},60%,30%)`);
    gc.addColorStop(1,'#050010');
    ctx.beginPath();ctx.arc(sx,sy,r,0,Math.PI*2);ctx.fillStyle=gc;ctx.fill();
    // Ring
    this.ringAngle+=.018;
    ctx.save();ctx.translate(sx,sy);ctx.rotate(this.ringAngle);ctx.scale(1,.28);
    ctx.beginPath();ctx.arc(0,0,r*1.8,0,Math.PI*2);
    ctx.strokeStyle=`hsla(${this.glowHue},100%,75%,.55)`;ctx.lineWidth=2.2;ctx.stroke();
    ctx.restore();
  }
}

// ═══════════════════════════════════════════════════════════════════
//  PACOTE TECNOLÓGICO — 10 megaestruturas  (Rank 38)
//  Mecânica de alvo: ao colocar, o jogador toca num astro existente
//  para "ancorar" a estrutura nele. _techPendingTarget guarda qual
//  tipo está aguardando seleção de alvo.
// ═══════════════════════════════════════════════════════════════════

let _techPendingTarget = null; // {type, resolve}
let _techAnchorToast   = null; // ID do tooltip de instrução

function _techRequestAnchor(typeName, onAnchor){
  _techPendingTarget = {type:typeName, cb:onAnchor};
  showTooltip(`🔧 Toque em um astro para ancorar: ${TYPE_LABELS[typeName]||typeName}`);
}
function _techCancelAnchor(){
  _techPendingTarget = null;
}

// Helper: tipos com pulso/radiação (Esfera detecta pulsação)
const _PULSING_TYPES = ['star','cepheid','pulsar','magnetar','blazar','quasar','redDwarf',
  'yellowDwarf','blueStar','redGiant','supergiant','hypergiant','vampireStar','wolfRayet',
  'quasiStar','planckStar'];

const TECH_TYPES = [
  'techDysonSphere','techDysonSwarm','techShkadovThruster','techMatrioshkaBrain',
  'techSpaceElevator','techAlcubierreDrive','techMassExtractor','techAldersonDisk',
  'techNicollDyson','techGravityProjector',
  'entityStarDevourer','entityInvasionFleet','entityMarcianFleet','entityReptilianFleet','entityCosmicParasite',
  'entityVoidSerpent','entityMechaWorld',
  'techProbe','techLaboratory','techStation','techTelescope',
  'entityAlien','entityMarcian','entityReptilian'
];

// ─── Helpers visuais compartilhados: cascas geodésicas de Dyson ──
// Malha hexagonal que cobre o disco visível de uma "esfera de Dyson":
// gera células numa grade hexagonal normalizada (-1..1), ordenadas do
// centro para fora, permitindo um efeito de "montagem" progressiva.
const _DYSON_HEX_CELLS=(()=>{
  const cells=[];const s=0.165;const range=Math.ceil(1/s)+1;
  for(let q=-range;q<=range;q++){
    for(let r=-range;r<=range;r++){
      const x=s*1.5*q, y=s*Math.sqrt(3)*(r+q/2);
      const d=Math.hypot(x,y);
      if(d<=1.05) cells.push({x,y,d});
    }
  }
  cells.sort((a,b)=>a.d-b.d);
  cells.forEach((c,i)=>c.order=i/cells.length);
  return cells;
})();
// Desenha uma casca de painéis hexagonais perfeitamente encaixados ao
// redor de (sx,sy), raio shellR, rotação `rot` e cor `rgb` ("r,g,b").
// `progress` (0..1) controla quantos painéis já "encaixaram" (montagem).
function _drawDysonShell(sx,sy,shellR,rot,rgb,baseAlpha,progress){
  const cosR=Math.cos(rot),sinR=Math.sin(rot);
  for(let i=0;i<_DYSON_HEX_CELLS.length;i++){
    const c=_DYSON_HEX_CELLS[i];
    if(c.order>progress)continue;
    const rx=c.x*cosR-c.y*sinR, ry=c.x*sinR+c.y*cosR;
    const d2=rx*rx+ry*ry;
    if(d2>1)continue;
    const depth=Math.sqrt(Math.max(0,1-d2)); // curvatura aparente da esfera
    const px=sx+rx*shellR, py=sy+ry*shellR;
    const cellR=shellR*0.088*(0.45+0.55*depth);
    const alpha=baseAlpha*(0.35+0.65*depth);
    ctx.beginPath();
    for(let k=0;k<6;k++){
      const a=rot+k*(Math.PI/3);
      const vx=px+Math.cos(a)*cellR, vy=py+Math.sin(a)*cellR;
      if(k===0)ctx.moveTo(vx,vy);else ctx.lineTo(vx,vy);
    }
    ctx.closePath();
    ctx.fillStyle=`rgba(${rgb},${(alpha*.5).toFixed(3)})`;ctx.fill();
    ctx.strokeStyle=`rgba(${rgb},${alpha.toFixed(3)})`;ctx.lineWidth=Math.max(.6,shellR*.012);ctx.stroke();
  }
}
// Desenha um pequeno pentágono preenchido centrado em (cx,cy), raio r,
// rotacionado por `rot` (radianos).
function _drawPentagon(cx,cy,r,rot,fillStyle,strokeStyle){
  ctx.beginPath();
  for(let k=0;k<5;k++){
    const a=rot+k*(Math.PI*2/5)-Math.PI/2;
    const vx=cx+Math.cos(a)*r, vy=cy+Math.sin(a)*r;
    if(k===0)ctx.moveTo(vx,vy);else ctx.lineTo(vx,vy);
  }
  ctx.closePath();
  ctx.fillStyle=fillStyle;ctx.fill();
  if(strokeStyle){ctx.strokeStyle=strokeStyle;ctx.lineWidth=Math.max(.4,r*.12);ctx.stroke();}
}

// ─── 1. ESFERA DE DYSON ──────────────────────────────────────────
// Casca sólida ao redor de uma estrela. MECÂNICA: robôs/partículas
// constroem a esfera por 20s. Ao concluir, começa a coletar energia.
// Se o host pulsar, o pulso é captado multiplicando a coleta x3 por 2s.
// BLACKOUT ESTELAR: a luz da estrela fica presa dentro da casca.
// A cada 1000 GW → PULSO DE ILUMINAÇÃO (flash).
// A cada 2000 GW → RAIO DE TRANSFERÊNCIA: emite energia para o astro
//   mais próximo (planetas crescem; estrelas expandem; órbitas aceleram).
// A cada 5000 GW → ONDA DE SOBRECARGA: repele todos os objetos num
//   raio de 200u com grande força por 4s, depois aspira de volta por 2s.
class DysonSphere extends CelestialObject{
  constructor(wx,wy){
    super(wx,wy,'techDysonSphere');
    this.radius=2;this.mass=0;
    this.fixed=true;
    this.host=null;
    this._build=0;
    this._built=false;
    this._energy=0;
    this._robots=Array.from({length:16},(_,i)=>({a:i*(Math.PI*2/16)+rand(-.2,.2),r:rand(.5,1.2),speed:rand(.3,.7)*(Math.random()<.5?1:-1)}));
    this._pulseBoost=0;
    this._rot=0;
    this._panelEnergy=0;
    this._shellGlow=0;
    this._illumPulse=0;
    this._illumPulses=0;
    this._nextIllumAt=1000;
    // ── Raio de transferência (a cada 2000 GW)
    this._nextTransferAt=2000;
    this._transfers=0;
    this._transferBeam=null; // {tx,ty,alpha,timer}
    // ── Onda de sobrecarga (a cada 5000 GW)
    this._nextSurgeAt=5000;
    this._surgeTimer=0;
    this._surgeWave=0;
    this._surges=0;
    this.color='#44aaff';
  }
  attachTo(host){
    this.host=host;
    this.x=host.x;this.y=host.y;
  }
  update(dt){
    if(!this.host||this.host.dead){this.dead=true;return;}
    this.x=this.host.x;this.y=this.host.y;
    this._rot+=dt*.18;
    if(this._pulseBoost>0)this._pulseBoost=Math.max(0,this._pulseBoost-dt);
    if(this._transferBeam){
      this._transferBeam.timer-=dt;
      this._transferBeam.alpha=Math.max(0,this._transferBeam.timer/1.2);
      if(this._transferBeam.timer<=0)this._transferBeam=null;
    }
    if(this._surgeWave>0)this._surgeWave=Math.max(0,this._surgeWave-dt*.4);
    if(!this._built){
      this._build=Math.min(1,this._build+dt/20);
      this._robots.forEach(rb=>{rb.a+=rb.speed*dt;});
      if(this._build>=1){
        this._built=true;
        showTooltip('⚙️ Esfera de Dyson concluída! Coletando energia...');
      }
    } else {
      const isPulsing=_PULSING_TYPES.includes(this.host.type);
      const hostPulse=isPulsing&&(Math.sin((this.host._t||0)*2.5)>0.85);
      if(hostPulse&&this._pulseBoost<=0){this._pulseBoost=2;}
      const rate=this._pulseBoost>0?3:1;
      this._energy+=rate*dt;
      this._panelEnergy=Math.round(this._energy);
      this._shellGlow=Math.min(1,this._shellGlow+dt*.01);
      // Pulso de iluminação (1000 GW)
      if(this._illumPulse>0)this._illumPulse=Math.max(0,this._illumPulse-dt*.6);
      if(this._energy>=this._nextIllumAt){
        this._illumPulse=1;this._illumPulses++;
        this._nextIllumAt+=1000;
        showTooltip('💡 Esfera de Dyson liberou um pulso de luz armazenada!');
      }
      // ── RAIO DE TRANSFERÊNCIA (2000 GW)
      if(this._energy>=this._nextTransferAt){
        this._nextTransferAt+=2000;
        this._transfers++;
        let best=null,bestD=Infinity;
        objects.forEach(o=>{
          if(o===this||o===this.host||o.dead||TECH_TYPES.includes(o.type))return;
          const d=dist(o,this.host);
          if(d<bestD){bestD=d;best=o;}
        });
        if(best){
          const isStarType=_PULSING_TYPES.includes(best.type)||best.type==='protostar';
          const isPlanetType=['planet','moon','dwarfplanet','gasgiant','icegiant','superearth',
            'minineptune','lavaplt','oceanplt','desertplt','carbonplt','ironplt','exBlanet'].includes(best.type);
          if(isPlanetType){
            best.radius=Math.min((best.radius||5)+1.2,(best.radius||5)*1.18+1.2);
            best.mass=(best.mass||10)*1.15;
            showTooltip(`⚡ Esfera de Dyson transferiu energia para ${best.name}! Planeta cresceu.`);
          } else if(isStarType){
            if(best.orbitSpeed)best.orbitSpeed*=1.25;
            best.radius=Math.min((best.radius||14)+0.8,(best.radius||14)*1.08+0.8);
            showTooltip(`⚡ Esfera de Dyson energizou ${best.name}! Estrela expandiu.`);
          } else {
            if(best.mass!==undefined)best.mass=(best.mass||10)*1.2;
            showTooltip(`⚡ Esfera de Dyson transferiu energia para ${best.name}!`);
          }
          for(let i=0;i<14;i++)particles.push({
            x:best.x+rand(-4,4),y:best.y+rand(-4,4),
            vx:rand(-3,3),vy:rand(-3,3),r:rand(1,3),
            alpha:.9,color:'#88ddff'
          });
          this._transferBeam={tx:best.x,ty:best.y,alpha:1,timer:1.2};
        }
      }
      // ── ONDA DE SOBRECARGA (5000 GW)
      if(this._energy>=this._nextSurgeAt&&this._surgeTimer<=0){
        this._nextSurgeAt+=5000;
        this._surges++;
        this._surgeTimer=6;
        this._surgeWave=1;
        showTooltip('🌊 Esfera de Dyson em SOBRECARGA! Onda de energia liberada!');
      }
      if(this._surgeTimer>0){
        this._surgeTimer=Math.max(0,this._surgeTimer-dt);
        const repelling=this._surgeTimer>2;
        objects.forEach(o=>{
          if(o===this||o===this.host||o.dead||o.fixed)return;
          const d=dist(o,this.host);if(d<1||d>200)return;
          const nx=(o.x-this.host.x)/d,ny=(o.y-this.host.y)/d;
          const force=repelling?18:-10;
          o.vx=(o.vx||0)+nx*force*dt;
          o.vy=(o.vy||0)+ny*force*dt;
        });
      }
    }
  }
  draw(){
    if(!this.host||this.host.dead)return;
    const sx=this.host.sx(),sy=this.host.sy();
    const hr=this.host.sr();
    const shellR=hr*2.4;
    const isSurging=this._surgeTimer>0;
    const boostAlpha=this._pulseBoost>0?.95:isSurging?.88:.62;
    const boostColor=isSurging?'255,120,40':this._pulseBoost>0?'255,240,80':'80,180,255';
    if(!this._built){
      const prog=this._build;
      _drawDysonShell(sx,sy,shellR,this._rot,boostColor,boostAlpha*.85,prog);
      this._robots.forEach((rb,i)=>{
        if(i/this._robots.length>prog*1.3)return;
        const rx=sx+Math.cos(rb.a)*(shellR*rb.r*.85),ry=sy+Math.sin(rb.a)*(shellR*rb.r*.85);
        ctx.beginPath();ctx.arc(rx,ry,Math.max(1.5,hr*.07),0,Math.PI*2);
        ctx.fillStyle='#aaddff';ctx.fill();
        if(Math.random()<.04){
          particles.push({x:rx+rand(-2,2),y:ry+rand(-2,2),vx:rand(-1,1),vy:rand(-1,1),r:rand(.5,1.5),alpha:.8,color:'#88ccff'});
        }
      });
      if(sandboxMode){
        ctx.font=`${Math.max(7,hr*.3)}px 'Courier New'`;ctx.fillStyle='rgba(100,200,255,.6)';
        ctx.textAlign='center';ctx.fillText(`⚙️ ${Math.round(prog*100)}%`,sx,sy+shellR+10*cam.zoom);ctx.textAlign='left';
      }
    } else {
      _drawDysonShell(sx,sy,shellR,this._rot,boostColor,boostAlpha,1);
      const ga=ctx.createRadialGradient(sx,sy,shellR*.92,sx,sy,shellR*1.12);
      ga.addColorStop(0,`rgba(${boostColor},${boostAlpha*.22})`);ga.addColorStop(1,'transparent');
      ctx.beginPath();ctx.arc(sx,sy,shellR*1.12,0,Math.PI*2);ctx.fillStyle=ga;ctx.fill();
      // Blackout estelar
      if(this._shellGlow>0){
        const bo=ctx.createRadialGradient(sx,sy,0,sx,sy,hr*1.05);
        bo.addColorStop(0,`rgba(0,0,5,${this._shellGlow*.7})`);
        bo.addColorStop(1,`rgba(0,0,5,${this._shellGlow*.15})`);
        ctx.beginPath();ctx.arc(sx,sy,hr*1.05,0,Math.PI*2);ctx.fillStyle=bo;ctx.fill();
      }
      // Pulso de iluminação
      if(this._illumPulse>0){
        const pr=shellR*(1+3*(1-this._illumPulse));
        const pg=ctx.createRadialGradient(sx,sy,0,sx,sy,pr);
        pg.addColorStop(0,`rgba(255,250,220,${this._illumPulse*.5})`);
        pg.addColorStop(.6,`rgba(255,240,150,${this._illumPulse*.18})`);
        pg.addColorStop(1,'transparent');
        ctx.beginPath();ctx.arc(sx,sy,pr,0,Math.PI*2);ctx.fillStyle=pg;ctx.fill();
      }
      // ── Raio de transferência de energia
      if(this._transferBeam&&this._transferBeam.alpha>0){
        const tb=this._transferBeam;
        const ts=worldToScreen(tb.tx,tb.ty);
        const grad=ctx.createLinearGradient(sx,sy,ts.x,ts.y);
        grad.addColorStop(0,`rgba(100,220,255,${tb.alpha*.9})`);
        grad.addColorStop(.5,`rgba(200,240,255,${tb.alpha*.6})`);
        grad.addColorStop(1,`rgba(100,220,255,0)`);
        ctx.beginPath();ctx.moveTo(sx,sy);ctx.lineTo(ts.x,ts.y);
        ctx.strokeStyle=grad;ctx.lineWidth=Math.max(1.5,hr*.08);ctx.stroke();
        ctx.beginPath();ctx.arc(ts.x,ts.y,Math.max(4,hr*.4),0,Math.PI*2);
        ctx.strokeStyle=`rgba(150,240,255,${tb.alpha*.7})`;ctx.lineWidth=1.5;ctx.stroke();
      }
      // ── Onda de sobrecarga expansiva
      if(this._surgeWave>0){
        const wr=shellR*(1+5*(1-this._surgeWave));
        const wg=ctx.createRadialGradient(sx,sy,wr*.7,sx,sy,wr);
        wg.addColorStop(0,`rgba(255,140,40,${this._surgeWave*.45})`);
        wg.addColorStop(1,'transparent');
        ctx.beginPath();ctx.arc(sx,sy,wr,0,Math.PI*2);ctx.fillStyle=wg;ctx.fill();
        ctx.beginPath();ctx.arc(sx,sy,wr,0,Math.PI*2);
        ctx.strokeStyle=`rgba(255,180,60,${this._surgeWave*.7})`;
        ctx.lineWidth=Math.max(1,hr*.1);ctx.stroke();
      }
      // Anel tracejado de alcance durante sobrecarga
      if(isSurging){
        const surgeR=200*cam.zoom;
        const repelling=this._surgeTimer>2;
        ctx.beginPath();ctx.arc(sx,sy,surgeR,0,Math.PI*2);
        ctx.strokeStyle=repelling?'rgba(255,120,40,.25)':'rgba(100,180,255,.2)';
        ctx.setLineDash([8,6]);ctx.lineWidth=1;ctx.stroke();ctx.setLineDash([]);
      }
      if(sandboxMode){
        ctx.font=`${Math.max(7,hr*.28)}px 'Courier New'`;
        ctx.fillStyle=isSurging?'rgba(255,160,60,.85)':this._pulseBoost>0?'rgba(255,240,60,.75)':'rgba(100,200,255,.55)';
        ctx.textAlign='center';
        let lbl=`⚡ ${Math.round(this._energy)} GW`;
        if(this._illumPulses)lbl+=` | 💡×${this._illumPulses}`;
        if(this._transfers)lbl+=` | 🔗×${this._transfers}`;
        if(isSurging)lbl+=` | 🌊`;
        ctx.fillText(lbl,sx,sy+shellR+10*cam.zoom);
        ctx.textAlign='left';
      }
    }
  }
}

// ─── MEGAESTRUTURA PLASMÍCEA ──────────────────────────────────────
// Anel coletor de plasma neon que a Raça Plasmícea constrói ao redor
// de uma Estrela ou Cefeide colonizada. Visual: anel duplo giratório
// em tons neon-laranja com "veias" de energia pulsante ligando o anel
// ao núcleo da estrela — tematicamente distinto da Esfera de Dyson
// (Alien), que é uma casca sólida fechada.
class PlasmicMegastructure extends CelestialObject{
  constructor(wx,wy){
    super(wx,wy,'plasmicMegastructure');
    this.radius=2;this.mass=0;this.fixed=true;
    this.host=null;
    this._build=0;this._built=false;
    this._rot=0;
    this._veins=Array.from({length:10},(_,i)=>({a:i*(Math.PI*2/10)+rand(-.15,.15),pulse:rand(0,Math.PI*2)}));
    this._energy=0;
    this.color='#ff8a3d';
  }
  attachTo(host){ this.host=host; this.x=host.x; this.y=host.y; }
  update(dt){
    if(!this.host||this.host.dead){this.dead=true;return;}
    this.x=this.host.x;this.y=this.host.y;
    this._rot+=dt*.28;
    this._veins.forEach(v=>v.pulse+=dt*3);
    if(!this._built){
      this._build=Math.min(1,this._build+dt/14);
      if(this._build>=1){this._built=true;showTooltip('🛸 Coletor Plasmícea concluído! Absorvendo energia estelar...');}
    } else {
      this._energy+=dt*1.2;
    }
  }
  draw(){
    if(!this.host||this.host.dead)return;
    const sx=this.host.sx(),sy=this.host.sy();
    const hr=this.host.sr();
    const ringR=hr*2.1;
    const prog=this._built?1:this._build;
    ctx.save();
    // Anel externo (neon, tracejado, gira devagar)
    ctx.beginPath();ctx.arc(sx,sy,ringR*prog,0,Math.PI*2*prog);
    ctx.strokeStyle=`rgba(255,150,60,${.75})`;ctx.lineWidth=Math.max(1.5,hr*.09);
    ctx.setLineDash([hr*.35,hr*.22]);ctx.lineDashOffset=-this._rot*ringR;
    ctx.stroke();ctx.setLineDash([]);
    // Anel interno (giro oposto)
    ctx.beginPath();ctx.arc(sx,sy,ringR*.72*prog,0,Math.PI*2*prog);
    ctx.strokeStyle='rgba(255,200,120,.5)';ctx.lineWidth=Math.max(1,hr*.05);
    ctx.setLineDash([hr*.2,hr*.28]);ctx.lineDashOffset=this._rot*ringR*1.4;
    ctx.stroke();ctx.setLineDash([]);
    // Glow neon do anel
    const gg=ctx.createRadialGradient(sx,sy,ringR*.6,sx,sy,ringR*1.15);
    gg.addColorStop(0,'rgba(255,140,50,0.05)');gg.addColorStop(.85,'rgba(255,140,50,0.16)');gg.addColorStop(1,'transparent');
    ctx.beginPath();ctx.arc(sx,sy,ringR*1.15,0,Math.PI*2);ctx.fillStyle=gg;ctx.fill();
    // Veias de energia ligando o anel ao núcleo
    if(this._built){
      this._veins.forEach(v=>{
        const bright=.35+.35*Math.max(0,Math.sin(v.pulse));
        const vx=sx+Math.cos(v.a+this._rot*.4)*ringR;
        const vy=sy+Math.sin(v.a+this._rot*.4)*ringR;
        ctx.beginPath();ctx.moveTo(sx,sy);ctx.lineTo(vx,vy);
        ctx.strokeStyle=`rgba(255,170,70,${bright})`;ctx.lineWidth=Math.max(.6,hr*.025);ctx.stroke();
      });
    }
    ctx.restore();
    if(sandboxMode){
      ctx.font=`${Math.max(7,hr*.28)}px 'Courier New'`;
      ctx.fillStyle='rgba(255,160,70,.7)';ctx.textAlign='center';
      const lbl=this._built?`🛸 Coletor Plasmícea | ⚡${Math.round(this._energy)}`:`🛸 ${Math.round(this._build*100)}%`;
      ctx.fillText(lbl,sx,sy+ringR+10*cam.zoom);ctx.textAlign='left';
    }
  }
}

// ─── 2. ENXAME DE DYSON ──────────────────────────────────────────
// Nuvem de satélites/espelhos orbitando uma estrela. MECÂNICA:
// coleta energia (0.8 GW/s). Ao atingir 500 GW → spawna Blaneta
// habitável. EXPANSÃO: a cada 300 GW, +5 satélites (até 80 máx).
// DEFESA ATIVA: se meteoro/cometa se aproximar do host (<150u), um
// satélite intercepta — o projétil é destruído com faísca e o enxame
// marca uma "interceptação". Brilho do host filtrado conforme energia.
class DysonSwarm extends CelestialObject{
  constructor(wx,wy){
    super(wx,wy,'techDysonSwarm');
    this.radius=2;this.mass=0;
    this.fixed=true;
    this.host=null;
    this._sats=Array.from({length:40},(_,i)=>({
      a:rand(0,Math.PI*2),
      r:rand(1.6,2.8),
      speed:rand(.2,.6)*(Math.random()<.5?1:-1),
      size:rand(.045,.085),
      bright:rand(.4,1),
      rot:rand(0,Math.PI*2),
      rotSpeed:rand(-1.2,1.2)
    }));
    this._energy=0;
    this._habitableSpawned=false;
    this._filterAmount=0;
    this._t=0;
    // ── Expansão do enxame (a cada 300 GW)
    this._nextExpandAt=300;
    this._expansions=0;
    // ── Defesa ativa
    this._intercepts=0;
    this._interceptFlashes=[];  // [{sx,sy,alpha,timer}] faíscas de intercepção
    this._interceptCooldown=0;  // evita spam de intercepções
    this.color='#ffcc44';
  }
  attachTo(host){this.host=host;this.x=host.x;this.y=host.y;}
  update(dt){
    if(!this.host||this.host.dead){this.dead=true;return;}
    this.x=this.host.x;this.y=this.host.y;
    this._t+=dt;
    this._sats.forEach(s=>{s.a+=s.speed*dt;s.rot+=s.rotSpeed*dt;});
    // Coleta: 0.8 GW/s base
    this._energy+=0.8*dt;
    this._filterAmount=Math.min(.7,this._energy/700);
    this.host._dysonFilter=this._filterAmount;
    // Blaneta habitável (500 GW)
    if(this._energy>=500&&!this._habitableSpawned){
      this._habitableSpawned=true;
      const bl=new Blanet(this.host.x+rand(-30,30),this.host.y+rand(-30,30));
      bl.parent=this.host;
      bl.orbitDist=this.host.radius*3.5;
      bl.orbitAngle=rand(0,Math.PI*2);
      bl.orbitSpeed=0.35/Math.sqrt(bl.orbitDist/50);
      bl._parentType='star';bl._glow=1;bl._warmth=1;
      pendingObjects.push(bl);
      showTooltip('🏠 Enxame de Dyson habitável! Uma Blaneta foi colonizada.');
    }
    // ── EXPANSÃO DO ENXAME (300 GW)
    if(this._energy>=this._nextExpandAt&&this._sats.length<80){
      this._nextExpandAt+=300;
      this._expansions++;
      const toAdd=Math.min(5,80-this._sats.length);
      for(let i=0;i<toAdd;i++){
        this._sats.push({
          a:rand(0,Math.PI*2),
          r:rand(1.6,3.2),
          speed:rand(.15,.55)*(Math.random()<.5?1:-1),
          size:rand(.04,.08),
          bright:rand(.4,1),
          rot:rand(0,Math.PI*2),
          rotSpeed:rand(-1.2,1.2)
        });
      }
      showTooltip(`🛞 Enxame de Dyson expandiu! ${this._sats.length} satélites em órbita.`);
    }
    // ── DEFESA ATIVA: intercepta meteoros e cometas
    if(this._interceptCooldown>0)this._interceptCooldown=Math.max(0,this._interceptCooldown-dt);
    if(this._interceptCooldown<=0){
      const threatTypes=['meteor','comet'];
      for(let i=0;i<objects.length;i++){
        const o=objects[i];
        if(o.dead||!threatTypes.includes(o.type))continue;
        const d=dist(o,this.host);
        if(d<150){
          // Intercepta!
          const isx=o.sx(),isy=o.sy();
          o.dead=true;
          this._intercepts++;
          this._interceptCooldown=1.5;
          // Faísca visual no ponto de interceptação
          this._interceptFlashes.push({
            wx:o.x,wy:o.y,alpha:1,timer:1.0
          });
          for(let j=0;j<10;j++)particles.push({
            x:o.x+rand(-6,6),y:o.y+rand(-6,6),
            vx:rand(-5,5),vy:rand(-5,5),
            r:rand(1.5,3),alpha:.95,
            color:`hsl(${rand(40,60)},100%,${rand(65,90)}%)`
          });
          showTooltip(`🛡️ Satélite interceptou ${o.name}! (×${this._intercepts})`);
          break;
        }
      }
    }
    // Decai flashes de interceptação
    this._interceptFlashes=this._interceptFlashes.filter(f=>{
      f.timer-=dt;f.alpha=Math.max(0,f.timer);return f.timer>0;
    });
  }
  draw(){
    if(!this.host||this.host.dead)return;
    const sx=this.host.sx(),sy=this.host.sy();
    const hr=this.host.sr();
    this._sats.forEach(s=>{
      const rx=sx+Math.cos(s.a)*hr*s.r,ry=sy+Math.sin(s.a)*hr*s.r;
      const pr=Math.max(.9,hr*s.size);
      const bAlpha=Math.max(0,Math.min(1,s.bright*.75+.18*Math.sin(this._t*3+s.a)));
      _drawPentagon(rx,ry,pr,s.rot,`rgba(255,220,100,${bAlpha.toFixed(3)})`,`rgba(255,235,180,${Math.min(1,bAlpha+.25).toFixed(3)})`);
      // Linhas de transmissão entre satélites próximos
      this._sats.forEach(s2=>{
        const dx=Math.cos(s.a)*hr*s.r-Math.cos(s2.a)*hr*s2.r;
        const dy=Math.sin(s.a)*hr*s.r-Math.sin(s2.a)*hr*s2.r;
        if(Math.hypot(dx,dy)<hr*.7&&Math.random()<.006){
          ctx.beginPath();
          ctx.moveTo(rx,ry);
          ctx.lineTo(sx+Math.cos(s2.a)*hr*s2.r,sy+Math.sin(s2.a)*hr*s2.r);
          ctx.strokeStyle='rgba(255,200,60,.18)';ctx.lineWidth=.7;ctx.stroke();
        }
      });
    });
    // ── Flashes de interceptação
    this._interceptFlashes.forEach(f=>{
      const fs=worldToScreen(f.wx,f.wy);
      const fg=ctx.createRadialGradient(fs.x,fs.y,0,fs.x,fs.y,Math.max(8,hr*.6)*cam.zoom);
      fg.addColorStop(0,`rgba(255,240,100,${f.alpha*.9})`);
      fg.addColorStop(.5,`rgba(255,160,40,${f.alpha*.5})`);
      fg.addColorStop(1,'transparent');
      ctx.beginPath();ctx.arc(fs.x,fs.y,Math.max(8,hr*.6)*cam.zoom,0,Math.PI*2);
      ctx.fillStyle=fg;ctx.fill();
      // Cruz de intercepção
      const cr=Math.max(4,hr*.4)*cam.zoom;
      ctx.beginPath();
      ctx.moveTo(fs.x-cr,fs.y);ctx.lineTo(fs.x+cr,fs.y);
      ctx.moveTo(fs.x,fs.y-cr);ctx.lineTo(fs.x,fs.y+cr);
      ctx.strokeStyle=`rgba(255,255,180,${f.alpha*.8})`;ctx.lineWidth=1.5;ctx.stroke();
    });
    if(sandboxMode){
      ctx.font=`${Math.max(7,hr*.28)}px 'Courier New'`;ctx.fillStyle='rgba(255,210,80,.55)';
      ctx.textAlign='center';
      let lbl=`🌞 ${Math.round(this._energy)} GW | 🛰️×${this._sats.length}`;
      if(this._habitableSpawned)lbl+=' · 🏠';
      if(this._intercepts)lbl+=` · 🛡️×${this._intercepts}`;
      ctx.fillText(lbl,sx,sy+hr*3.4+10*cam.zoom);
      ctx.textAlign='left';
    }
  }
}

// ─── 3. MOTOR ESTELAR SHKADOV ────────────────────────────────────
// Espelho curvo que empurra a estrela pelo espaço. MECÂNICA: o motor
// aplica força constante ao host numa direção fixa. O host começa a
// derivar pelo mapa arrastando planetas orbitantes junto. O jogador
// pode ver a direção de empuxo. Ao colidir com outro astro, gera uma
// explosão de grande escala ("colisão estelar").
class ShkadovThruster extends CelestialObject{
  constructor(wx,wy){
    super(wx,wy,'techShkadovThruster');
    this.radius=2;this.mass=0;
    this.fixed=true;
    this.host=null;
    this._thrustAngle=rand(0,Math.PI*2); // direção de empuxo
    this._thrustForce=0.006;
    this._t=0;
    this._exhaustParticleTimer=0;
    this.color='#ff8844';
  }
  attachTo(host){
    this.host=host;
    this.x=host.x;this.y=host.y;
    this._thrustAngle=rand(0,Math.PI*2);
    // Destrava o host da posição fixa
    host.fixed=false;
    host.vx=(host.vx||0);host.vy=(host.vy||0);
  }
  update(dt){
    if(!this.host||this.host.dead){this.dead=true;return;}
    this._t+=dt;
    this.x=this.host.x;this.y=this.host.y;
    // Aplica empuxo
    this.host.vx=(this.host.vx||0)+Math.cos(this._thrustAngle)*this._thrustForce*dt*60;
    this.host.vy=(this.host.vy||0)+Math.sin(this._thrustAngle)*this._thrustForce*dt*60;
    // Partículas de exaustão na direção OPOSTA ao empuxo
    this._exhaustParticleTimer-=dt;
    if(this._exhaustParticleTimer<=0){
      this._exhaustParticleTimer=0.08;
      const ea=this._thrustAngle+Math.PI;
      const ex=this.host.x+Math.cos(ea)*this.host.radius*1.5;
      const ey=this.host.y+Math.sin(ea)*this.host.radius*1.5;
      for(let i=0;i<2;i++){
        particles.push({x:ex+rand(-4,4),y:ey+rand(-4,4),
          vx:Math.cos(ea)*rand(6,14)+rand(-2,2),
          vy:Math.sin(ea)*rand(6,14)+rand(-2,2),
          r:rand(1.5,3.5),alpha:.9,
          color:`hsl(${rand(20,50)},100%,${rand(60,90)}%)`});
      }
    }
    // Detecta colisão com outros astros grandes
    objects.forEach(o=>{
      if(o===this||o===this.host||o.dead||o.radius<5)return;
      if(dist(this.host,o)<(this.host.radius+o.radius)*1.1){
        spawnExplosion(this.host.x,this.host.y,2.5,true);
        this.host.dead=true;o.dead=true;this.dead=true;
      }
    });
  }
  draw(){
    if(!this.host||this.host.dead)return;
    const sx=this.host.sx(),sy=this.host.sy();
    const hr=this.host.sr();
    // Espelho curvo no lado oposto ao empuxo
    const mirrorA=this._thrustAngle+Math.PI;
    ctx.save();ctx.translate(sx,sy);ctx.rotate(mirrorA);
    const mR=hr*1.8;
    ctx.beginPath();ctx.arc(0,0,mR,-Math.PI*.45,Math.PI*.45);
    ctx.strokeStyle=`rgba(255,160,60,${.65+.2*Math.sin(this._t*3)})`;
    ctx.lineWidth=Math.max(2,hr*.12);ctx.stroke();
    // Eixo de empuxo
    ctx.beginPath();ctx.moveTo(-hr*.2,0);ctx.lineTo(-hr*2.6,0);
    ctx.strokeStyle='rgba(255,130,40,.3)';ctx.lineWidth=Math.max(1,hr*.04);ctx.stroke();
    // Seta de direção
    ctx.beginPath();ctx.moveTo(hr*1.4,0);ctx.lineTo(hr*2.2,0);
    ctx.strokeStyle='rgba(255,255,100,.7)';ctx.lineWidth=Math.max(1.5,hr*.06);ctx.stroke();
    ctx.beginPath();ctx.moveTo(hr*2.2,0);ctx.lineTo(hr*1.9,-hr*.15);ctx.moveTo(hr*2.2,0);ctx.lineTo(hr*1.9,hr*.15);
    ctx.strokeStyle='rgba(255,255,100,.7)';ctx.lineWidth=Math.max(1.5,hr*.05);ctx.stroke();
    ctx.restore();
    if(sandboxMode){
      const spd=Math.round(Math.hypot(this.host.vx||0,this.host.vy||0)*100)/100;
      ctx.font=`${Math.max(7,hr*.28)}px 'Courier New'`;ctx.fillStyle='rgba(255,160,60,.55)';
      ctx.textAlign='center';ctx.fillText(`🚀 ${spd} u/s`,sx,sy+hr*2.4+10*cam.zoom);ctx.textAlign='left';
    }
  }
}

// ─── 4. CÉREBRO DE MATRIOSHKA ───────────────────────────────────
// Esferas de Dyson concêntricas dedicadas a computação. MECÂNICA:
// acumula "Ciclos de Computação" com base na energia do host. Ao
// atingir 1000 ciclos → COMPILAÇÃO INTELIGENTE: escolhe um astro
// próximo e aplica um efeito direcionado por TIPO:
//   • Planeta/Lua → muda mineral para raro + aumenta bioLevel
//   • Estrela/Quasar → aumenta radius + muda cor para mais quente
//   • Buraco Negro/Quasar/Blazar → aumenta massa (mais absorção)
//   • Qualquer outro → dá boost de velocidade orbital x1.4
// Cada compilação emite ONDAS DE RÁDIO visíveis (anéis coloridos
// que se expandem). Exibe contador de compilações e log do último
// efeito no label. Camadas giram em direções opostas.
class MatrioshkaBrain extends CelestialObject{
  constructor(wx,wy){
    super(wx,wy,'techMatrioshkaBrain');
    this.radius=2;this.mass=0;
    this.fixed=true;
    this.host=null;
    this._layers=[
      {r:1.5,speed:.07,rot:0,rgb:'100,200,255'},
      {r:2.35,speed:-.05,rot:1.3,rgb:'170,130,255'},
      {r:3.2,speed:.035,rot:2.6,rgb:'120,255,190'},
    ];
    this._cycles=0;
    this._compilations=0;
    this._compileFlash=0;
    this._t=0;
    // ── Ondas de rádio
    this._radioWaves=[];  // [{r, alpha, color}]
    // ── Log do último efeito
    this._lastEffect='';
    this._lastEffectTimer=0;
    this.color='#88ffcc';
  }
  attachTo(host){this.host=host;this.x=host.x;this.y=host.y;}
  update(dt){
    if(!this.host||this.host.dead){this.dead=true;return;}
    this.x=this.host.x;this.y=this.host.y;
    this._t+=dt;
    if(this._compileFlash>0)this._compileFlash=Math.max(0,this._compileFlash-dt*2);
    if(this._lastEffectTimer>0)this._lastEffectTimer=Math.max(0,this._lastEffectTimer-dt);
    this._layers.forEach(l=>l.rot+=l.speed*dt);
    // Atualiza ondas de rádio
    this._radioWaves=this._radioWaves.filter(w=>{
      w.r+=dt*this.host.radius*3.8;
      w.alpha=Math.max(0,w.alpha-dt*.35);
      return w.alpha>0;
    });
    // Acumula ciclos
    const isHighEnergy=['star','quasar','blazar','cepheid','yellowDwarf','blueStar',
      'hypergiant','quasiStar'].includes(this.host.type);
    this._cycles+=dt*(isHighEnergy?2.5:0.8);
    // ── COMPILAÇÃO INTELIGENTE (1000 ciclos)
    if(this._cycles>=1000){
      this._cycles=0;this._compilations++;
      this._compileFlash=1;
      // Emite ondas de rádio com cores distintas por compilação
      const wColors=['200,120,255','120,220,255','180,255,140','255,200,80'];
      const wc=wColors[this._compilations%wColors.length];
      for(let i=0;i<3;i++){
        this._radioWaves.push({r:this.host.radius*(this._layers[2].r+0.5)+i*8,alpha:.9-i*.2,color:wc});
      }
      // Encontra astro próximo não-tech
      const candidates=objects.filter(o=>
        o!==this&&o!==this.host&&!o.dead&&!TECH_TYPES.includes(o.type)&&dist(o,this.host)<350
      );
      if(candidates.length){
        const tgt=candidates[randInt(0,candidates.length-1)];
        // Efeito inteligente por tipo
        const isPlanetLike=['planet','moon','dwarfplanet','gasgiant','icegiant','superearth',
          'minineptune','lavaplt','oceanplt','desertplt','carbonplt','ironplt','exBlanet'].includes(tgt.type);
        const isStarLike=['star','cepheid','protostar','redDwarf','yellowDwarf','blueStar',
          'redGiant','supergiant','whiteDwarf','hypergiant','wolfRayet','przybylski',
          'janusStar','quasiStar','planckStar','vampireStar'].includes(tgt.type);
        const isMassive=['blackhole','quasar','blazar','microquasar','greatattractor',
          'magnetar','pulsar','neutronstar'].includes(tgt.type);
        if(isPlanetLike){
          const rareMin=['Ouro','Diamante','Iridium','Platina','Osmium'];
          tgt.mineral=rareMin[randInt(0,rareMin.length-1)];
          tgt.bioLevel=Math.min(100,(tgt.bioLevel||0)+25);
          tgt.color=PLANET_COLORS[randInt(0,PLANET_COLORS.length-1)];
          this._lastEffect=`mineral→${tgt.mineral}`;
          showTooltip(`🧠 Matrioshka otimizou ${tgt.name}: mineral raro detectado! (${tgt.mineral})`);
        } else if(isStarLike){
          tgt.radius=Math.min((tgt.radius||14)*1.12+0.6,(tgt.radius||14)*1.12+0.6);
          // Aquece a cor da estrela (mais azulada = mais quente)
          if(tgt.color&&tgt.color.startsWith('hsl')){
            const match=tgt.color.match(/hsl\((\d+),(\d+)%,(\d+)%\)/);
            if(match){
              const newH=Math.max(200,parseInt(match[1])-15);
              tgt.color=`hsl(${newH},${match[2]}%,${Math.min(95,parseInt(match[3])+5)}%)`;
            }
          }
          this._lastEffect='estrela aquecida';
          showTooltip(`🧠 Matrioshka compilou: ${tgt.name} aquecida e expandida!`);
        } else if(isMassive){
          tgt.mass=(tgt.mass||50)*1.4;
          this._lastEffect='massa amplificada';
          showTooltip(`🧠 Matrioshka amplificou massa de ${tgt.name}!`);
        } else {
          if(tgt.orbitSpeed)tgt.orbitSpeed*=1.4;
          this._lastEffect='órbita acelerada';
          showTooltip(`🧠 Matrioshka compilou: órbita de ${tgt.name} acelerada!`);
        }
        this._lastEffectTimer=8;
        for(let i=0;i<16;i++)particles.push({
          x:tgt.x+rand(-5,5),y:tgt.y+rand(-5,5),
          vx:rand(-4,4),vy:rand(-4,4),
          r:rand(1,3),alpha:.9,color:`hsl(${parseInt(wc.split(',')[0])+30},100%,75%)`
        });
      }
    }
  }
  draw(){
    if(!this.host||this.host.dead)return;
    const sx=this.host.sx(),sy=this.host.sy();
    const hr=this.host.sr();
    // Camadas de Dyson concêntricas
    this._layers.forEach(l=>{
      _drawDysonShell(sx,sy,hr*l.r,l.rot,l.rgb,.5,1);
    });
    // Flash de compilação
    if(this._compileFlash>0){
      const cf=hr*4*cam.zoom;
      const gc=ctx.createRadialGradient(sx,sy,0,sx,sy,cf);
      gc.addColorStop(0,`rgba(100,255,200,${this._compileFlash*.35})`);gc.addColorStop(1,'transparent');
      ctx.beginPath();ctx.arc(sx,sy,cf,0,Math.PI*2);ctx.fillStyle=gc;ctx.fill();
    }
    // ── Ondas de rádio expansivas
    this._radioWaves.forEach(w=>{
      const wr=w.r*cam.zoom;
      ctx.beginPath();ctx.arc(sx,sy,wr,0,Math.PI*2);
      ctx.strokeStyle=`rgba(${w.color},${w.alpha*.7})`;
      ctx.lineWidth=Math.max(1,cam.zoom*.8);
      ctx.setLineDash([6,4]);ctx.stroke();ctx.setLineDash([]);
      // Halo suave
      const wg=ctx.createRadialGradient(sx,sy,wr*.9,sx,sy,wr*1.08);
      wg.addColorStop(0,`rgba(${w.color},${w.alpha*.12})`);
      wg.addColorStop(1,'transparent');
      ctx.beginPath();ctx.arc(sx,sy,wr*1.08,0,Math.PI*2);ctx.fillStyle=wg;ctx.fill();
    });
    if(sandboxMode){
      ctx.font=`${Math.max(7,hr*.26)}px 'Courier New'`;ctx.fillStyle='rgba(120,255,200,.55)';
      ctx.textAlign='center';
      let lbl=`🧠 ${Math.round(this._cycles)}/1000 | ×${this._compilations}`;
      if(this._lastEffect&&this._lastEffectTimer>0)lbl+=` | ${this._lastEffect}`;
      ctx.fillText(lbl,sx,sy+hr*3.8+10*cam.zoom);
      ctx.textAlign='left';
    }
  }
}

// ─── 5. ELEVADOR ESPACIAL ────────────────────────────────────────
// Cabo de um planeta até uma estação orbital. MECÂNICA: conecta um
// planeta a um ponto-âncora estacionário no espaço. O planeta continua
// orbitando mas o cabo "o prende" — se a órbita tentar afastar demais,
// o cabo puxa de volta (efeito elástico). Cápsulas transportam seres
// vivos pelo cabo: a cada ~4.5s uma cápsula sobe até a estação, embarca
// de volta e desce ao planeta — completando o ciclo soma recursos.
class SpaceElevator extends CelestialObject{
  constructor(wx,wy){
    super(wx,wy,'techSpaceElevator');
    this.radius=3;this.mass=0;
    this.fixed=true;
    this.host=null;         // planeta âncora
    this._anchorX=0;this._anchorY=0; // ponto estacionário no espaço
    this._cableLen=120;
    this._cargo=[];        // {t:0..1, dir:1|-1} pacotes em trânsito
    this._cargoTimer=0;
    this._t=0;
    this._resources=0;
    this.color='#aaffaa';
  }
  attachTo(host){
    this.host=host;
    this.x=host.x;this.y=host.y;
    // Âncora a 120u acima do planeta
    const angle=host.orbitAngle||0;
    this._anchorX=host.x+Math.cos(angle+Math.PI/2)*this._cableLen;
    this._anchorY=host.y+Math.sin(angle+Math.PI/2)*this._cableLen;
  }
  update(dt){
    if(!this.host||this.host.dead){this.dead=true;return;}
    this._t+=dt;
    this.x=this.host.x;this.y=this.host.y;
    // Efeito elástico: se o planeta se afastar demais do ponto âncora
    const d=Math.hypot(this.host.x-this._anchorX,this.host.y-this._anchorY);
    if(d>this._cableLen*1.1){
      const nx=(this._anchorX-this.host.x)/d,ny=(this._anchorY-this.host.y)/d;
      const excess=d-this._cableLen;
      this.host.vx=(this.host.vx||0)+nx*excess*.035;
      this.host.vy=(this.host.vy||0)+ny*excess*.035;
    }
    // Âncora segue lentamente o planeta (lag) — dá efeito de cabo tenso
    this._anchorX+=(this.host.x-this._anchorX)*0.002;
    this._anchorY+=(this.host.y-this._anchorY)*0.002;
    // Cápsulas com seres vivos sobem e descem o cabo (ida e volta)
    this._cargoTimer-=dt;
    if(this._cargoTimer<=0&&this._cargo.length<6){this._cargoTimer=4.5;this._cargo.push({t:0,dir:1});}
    this._cargo.forEach(c=>{
      c.t+=c.dir*dt*.15;
      if(c.t>=1&&c.dir===1){
        // Chegou na estação orbital — desembarca e inicia a volta ao planeta
        c.t=1;c.dir=-1;
        particles.push({x:this._anchorX,y:this._anchorY,vx:rand(-2,2),vy:rand(-1,1),r:rand(1,2),alpha:.9,color:'#ccffe0'});
      } else if(c.t<=0&&c.dir===-1){
        c.t=0;c._done=true;
      }
    });
    // Remove cápsulas que completaram a viagem de ida e volta
    this._cargo=this._cargo.filter(c=>{
      if(c._done){
        this._resources++;
        particles.push({x:this.host.x,y:this.host.y,vx:rand(-2,2),vy:rand(-2,2),r:rand(1,2),alpha:.9,color:'#aaffaa'});
        return false;
      }
      return true;
    });
  }
  draw(){
    if(!this.host||this.host.dead)return;
    const hx=this.host.sx(),hy=this.host.sy();
    const ax=(this._anchorX-cam.x)*cam.zoom+canvas.width*.5;
    const ay=(this._anchorY-cam.y)*cam.zoom+canvas.height*.5;
    // Cabo
    const cg=ctx.createLinearGradient(hx,hy,ax,ay);
    cg.addColorStop(0,'rgba(100,255,120,.7)');cg.addColorStop(1,'rgba(180,255,180,.3)');
    ctx.beginPath();ctx.moveTo(hx,hy);ctx.lineTo(ax,ay);
    ctx.strokeStyle=cg;ctx.lineWidth=Math.max(1.5,this.host.sr()*.06);ctx.stroke();
    // Estação orbital no topo
    ctx.beginPath();ctx.arc(ax,ay,Math.max(4,this.host.sr()*.35),0,Math.PI*2);
    ctx.fillStyle='rgba(150,255,160,.6)';ctx.fill();
    ctx.strokeStyle='rgba(200,255,200,.8)';ctx.lineWidth=1.5;ctx.stroke();
    // Cápsulas em trânsito — transportam seres vivos entre o planeta
    // e a estação orbital, indo e voltando pelo cabo
    const cableAngle=Math.atan2(ay-hy,ax-hx);
    const hrr=this.host.sr();
    this._cargo.forEach(c=>{
      const px=hx+(ax-hx)*c.t,py=hy+(ay-hy)*c.t;
      const w=Math.max(3,hrr*.26),h=Math.max(2,hrr*.15);
      ctx.save();ctx.translate(px,py);ctx.rotate(cableAngle);
      ctx.beginPath();
      if(ctx.roundRect)ctx.roundRect(-w/2,-h/2,w,h,h*.45);else ctx.rect(-w/2,-h/2,w,h);
      ctx.fillStyle=c.dir>0?'rgba(180,255,200,.92)':'rgba(170,220,255,.92)';
      ctx.fill();
      ctx.strokeStyle='rgba(255,255,255,.5)';ctx.lineWidth=Math.max(.5,hrr*.02);ctx.stroke();
      // Passageiros (seres vivos) visíveis dentro da cápsula
      ctx.fillStyle='rgba(255,255,150,.95)';
      ctx.beginPath();ctx.arc(-w*.2,0,Math.max(.6,h*.22),0,Math.PI*2);ctx.fill();
      ctx.beginPath();ctx.arc(w*.2,0,Math.max(.6,h*.22),0,Math.PI*2);ctx.fill();
      ctx.restore();
    });
    if(sandboxMode){
      const hr=this.host.sr();
      ctx.font=`${Math.max(7,hr*.28)}px 'Courier New'`;ctx.fillStyle='rgba(160,255,160,.55)';
      ctx.textAlign='center';ctx.fillText(`📦 ${this._resources} rec.`,ax,ay-8*cam.zoom);ctx.textAlign='left';
    }
  }
}

// ─── 6. MOTOR DE ALCUBIERRE ─────────────────────────────────────
// Distorce espaço-tempo, encolhendo à frente e expandindo atrás.
// MECÂNICA: cria uma "bolha" — astros QUE ENTRAM na frente são
// acelerados na direção do motor. Astros na zona traseira são
// freados/repelidos. O motor MOVE-SE pelo mapa em sua própria
// direção, deixando uma ESTEIRA DE DISTORÇÃO: "rugas" no espaço-tempo
// que se expandem e, ao cruzarem pequenos astros, causam turbulência
// caótica (impulso aleatório) e um brilho de distorção temporário —
// um efeito diferente de simplesmente atrair/repelir.
// Astros capturados dentro da bolha viajam junto como passageiros.
class AlcubierreDrive extends CelestialObject{
  constructor(wx,wy){
    super(wx,wy,'techAlcubierreDrive');
    this.radius=12;this.mass=0;
    this.fixed=false;
    this._direction=rand(0,Math.PI*2);
    this._speed=1.2;
    this._bubbleR=55;
    this._passengers=new Set();
    this._distortRing=0;
    this._t=0;
    this._wakeTimer=0;
    this._wakeRipples=[];   // {x,y,t} rugas deixadas no espaço-tempo
    this._shimmer=new Map(); // astro → tempo restante de distorção
    this.vx=Math.cos(this._direction)*this._speed;
    this.vy=Math.sin(this._direction)*this._speed;
    this.color='#ff44cc';
  }
  update(dt){
    this._t+=dt;
    this._distortRing=(this._distortRing+dt*2.5)%(Math.PI*2);
    // Move-se pela própria propulsão
    this.x+=this.vx*dt*60*0.016;this.y+=this.vy*dt*60*0.016;
    const frontA=this._direction;
    const backA=this._direction+Math.PI;
    objects.forEach(o=>{
      if(o===this||o.dead||o.fixed)return;
      const d=dist(o,this);
      // Zona dianteira: acelera na direção do motor
      if(d<this._bubbleR){
        const ao=Math.atan2(o.y-this.y,o.x-this.x);
        const relA=((ao-frontA+Math.PI*3)%(Math.PI*2))-Math.PI;
        if(Math.abs(relA)<Math.PI*.45){
          // Frente da bolha — propulsão
          o.vx=(o.vx||0)+Math.cos(frontA)*18*dt;
          o.vy=(o.vy||0)+Math.sin(frontA)*18*dt;
          this._passengers.add(o);
        } else if(Math.abs(relA)>Math.PI*.55){
          // Traseira — freada/repulsão suave
          o.vx=(o.vx||0)+(o.x-this.x)/d*8*dt;
          o.vy=(o.vy||0)+(o.y-this.y)/d*8*dt;
        }
      } else {
        this._passengers.delete(o);
      }
    });
    // Esteira de distorção: a bolha deixa "rugas" no espaço-tempo
    // que se expandem com o tempo
    this._wakeTimer-=dt;
    if(this._wakeTimer<=0){
      this._wakeTimer=0.35;
      this._wakeRipples.push({x:this.x,y:this.y,t:0});
    }
    this._wakeRipples.forEach(rp=>rp.t+=dt);
    this._wakeRipples=this._wakeRipples.filter(rp=>rp.t<2.2);
    // Turbulência: pequenos astros cruzados por uma ruga recebem um
    // impulso caótico (não direcional) e brilham com distorção
    this._wakeRipples.forEach(rp=>{
      const ringR=rp.t*40;
      objects.forEach(o=>{
        if(o===this||o.dead||o.fixed||o.radius>6)return;
        if(this._shimmer.has(o))return;
        const d=Math.hypot(o.x-rp.x,o.y-rp.y);
        if(Math.abs(d-ringR)<6){
          o.vx=(o.vx||0)+rand(-3,3);
          o.vy=(o.vy||0)+rand(-3,3);
          this._shimmer.set(o,1.6);
        }
      });
    });
    // Decai o brilho de distorção dos astros afetados
    this._shimmer.forEach((v,o)=>{
      v-=dt;
      if(v<=0||o.dead)this._shimmer.delete(o);else this._shimmer.set(o,v);
    });
  }
  draw(){
    const sx=this.sx(),sy=this.sy();
    const br=this._bubbleR*cam.zoom;
    // Esteira de distorção — rugas no espaço-tempo se expandindo
    this._wakeRipples.forEach(rp=>{
      const rx=(rp.x-cam.x)*cam.zoom+canvas.width*.5;
      const ry=(rp.y-cam.y)*cam.zoom+canvas.height*.5;
      const ringR=rp.t*40*cam.zoom;
      const a=Math.max(0,1-rp.t/2.2)*.3;
      ctx.beginPath();ctx.arc(rx,ry,ringR,0,Math.PI*2);
      ctx.strokeStyle=`rgba(255,120,240,${a.toFixed(3)})`;ctx.lineWidth=Math.max(.6,1.2*cam.zoom);ctx.stroke();
    });
    // Astros atravessados pela esteira brilham com distorção temporária
    this._shimmer.forEach((v,o)=>{
      if(o.dead)return;
      const ox=o.sx(),oy=o.sy(),orr=Math.max(4,o.sr()*1.5);
      ctx.beginPath();ctx.arc(ox,oy,orr,0,Math.PI*2);
      ctx.strokeStyle=`rgba(255,150,255,${(Math.min(1,v)*.6).toFixed(3)})`;ctx.lineWidth=1.5;ctx.stroke();
    });
    // Lente gravitacional — distorção de anel
    for(let i=0;i<3;i++){
      const rr=br*(0.6+i*.2);
      ctx.beginPath();ctx.arc(sx,sy,rr,0,Math.PI*2);
      ctx.strokeStyle=`rgba(255,80,220,${(.18-.05*i)+.06*Math.sin(this._distortRing+i)})`;
      ctx.lineWidth=Math.max(1,1.5-i*.4);ctx.stroke();
    }
    // Bolha principal
    const gb=ctx.createRadialGradient(sx,sy,br*.3,sx,sy,br);
    gb.addColorStop(0,'transparent');gb.addColorStop(.75,'rgba(220,60,200,.08)');gb.addColorStop(1,'rgba(255,80,255,.22)');
    ctx.beginPath();ctx.arc(sx,sy,br,0,Math.PI*2);ctx.fillStyle=gb;ctx.fill();
    // Núcleo
    ctx.save();ctx.translate(sx,sy);ctx.rotate(this._direction);
    const gc=ctx.createRadialGradient(0,0,0,0,0,this.radius*cam.zoom);
    gc.addColorStop(0,'#ffffff');gc.addColorStop(.5,'#ff66ee');gc.addColorStop(1,'#440033');
    ctx.beginPath();ctx.arc(0,0,this.radius*cam.zoom,0,Math.PI*2);ctx.fillStyle=gc;ctx.fill();
    // Seta de direção
    ctx.beginPath();ctx.moveTo(this.radius*cam.zoom,0);ctx.lineTo(br*.4,0);
    ctx.strokeStyle='rgba(255,150,255,.6)';ctx.lineWidth=Math.max(1,this.radius*cam.zoom*.12);ctx.stroke();
    ctx.restore();
    if(sandboxMode){
      const p=this._passengers.size;
      ctx.font=`${Math.max(7,this.radius*cam.zoom*.4)}px 'Courier New'`;ctx.fillStyle='rgba(255,120,255,.5)';
      ctx.textAlign='center';ctx.fillText(`🌀 ${p} passag.`,sx,sy+br+10);ctx.textAlign='left';
    }
  }
}

// ─── 7. EXTRATOR DE MASSA ────────────────────────────────────────
// Suga matéria da atmosfera de uma estrela. MECÂNICA: conectado a
// uma estrela por feixe de plasma, diminui gradualmente a massa e o
// raio do host (estrela "encolhe"). A massa sugada vira detritos
// (meteoros) que são ejetados pelo extrator. Ao encolher demais, o
// host colapsa (morre) e o extrator libera todos os detritos de uma vez.
class MassExtractor extends CelestialObject{
  constructor(wx,wy){
    super(wx,wy,'techMassExtractor');
    this.radius=7;this.mass=50;
    this.fixed=true;
    this.host=null;
    this._extractRate=0.012; // raio/s
    this._beamAlpha=0;
    this._debrisTimer=0;
    this._totalExtracted=0;
    this._t=0;
    this.color='#ffaa00';
  }
  attachTo(host){
    this.host=host;
    this.x=host.x+host.radius*2.5;this.y=host.y;
  }
  update(dt){
    if(!this.host||this.host.dead){this.dead=true;return;}
    this._t+=dt;
    this._beamAlpha=.6+.3*Math.sin(this._t*4);
    // Extrai massa do host
    const extract=this._extractRate*dt;
    this.host.radius=Math.max(2,this.host.radius-extract);
    this.host.mass=Math.max(10,(this.host.mass||100)-extract*8);
    this._totalExtracted+=extract;
    // Ejeta meteoro a cada 3s
    this._debrisTimer-=dt;
    if(this._debrisTimer<=0){
      this._debrisTimer=3;
      const a=Math.atan2(this.y-this.host.y,this.x-this.host.x)+rand(-.5,.5);
      const m=new Meteor(this.x+Math.cos(a)*10,this.y+Math.sin(a)*10);
      m.vx=Math.cos(a)*rand(8,18);m.vy=Math.sin(a)*rand(8,18);
      m._autoSpawn=true;
      pendingObjects.push(m);
    }
    // Colapso do host
    if(this.host.radius<=3){
      spawnExplosion(this.host.x,this.host.y,1.6,false);
      // Libera 8 meteoros
      for(let i=0;i<8;i++){
        const a=rand(0,Math.PI*2);
        const m=new Meteor(this.host.x,this.host.y);
        m.vx=Math.cos(a)*rand(12,24);m.vy=Math.sin(a)*rand(12,24);
        m._autoSpawn=true;pendingObjects.push(m);
      }
      this.host.dead=true;this.dead=true;
    }
  }
  draw(){
    if(!this.host||this.host.dead)return;
    const sx=this.sx(),sy=this.sy();
    const hx=this.host.sx(),hy=this.host.sy();
    const hr=this.host.sr();
    // Feixe de plasma entre extrator e host
    const bg=ctx.createLinearGradient(hx,hy,sx,sy);
    bg.addColorStop(0,`rgba(255,180,40,${this._beamAlpha*.8})`);
    bg.addColorStop(.5,`rgba(255,120,20,${this._beamAlpha*.5})`);
    bg.addColorStop(1,`rgba(255,200,80,${this._beamAlpha*.3})`);
    ctx.beginPath();ctx.moveTo(hx,hy);ctx.lineTo(sx,sy);
    ctx.strokeStyle=bg;ctx.lineWidth=Math.max(2,hr*.14);ctx.stroke();
    // Estrutura do extrator
    const r=this.radius*cam.zoom;
    ctx.save();ctx.translate(sx,sy);ctx.rotate(this._t*.4);
    for(let i=0;i<6;i++){
      const a=i*(Math.PI*2/6);
      ctx.beginPath();ctx.moveTo(Math.cos(a)*r*.5,Math.sin(a)*r*.5);
      ctx.lineTo(Math.cos(a)*r,Math.sin(a)*r);
      ctx.strokeStyle='rgba(255,160,40,.8)';ctx.lineWidth=Math.max(1,r*.15);ctx.stroke();
    }
    ctx.restore();
    ctx.beginPath();ctx.arc(sx,sy,r*.55,0,Math.PI*2);
    ctx.fillStyle='rgba(255,140,20,.7)';ctx.fill();
    if(sandboxMode){
      ctx.font=`${Math.max(7,r*.7)}px 'Courier New'`;ctx.fillStyle='rgba(255,160,40,.55)';
      ctx.textAlign='center';ctx.fillText(`⛏ ${Math.round(this._totalExtracted)} mass.`,sx,sy+r+10);ctx.textAlign='left';
    }
  }
}

// ─── 8. DISCO DE ALDERSON ───────────────────────────────────────
// Disco plano enorme com a estrela no centro. MECÂNICA: cria um campo
// gravitacional "plano" — planetas ao redor não conseguem sair do plano
// do disco (são puxados de volta para o eixo), e a gravidade é uniforme
// ao longo do disco (não cai com a distância como numa estrela normal).
// Força planetas em órbitas estranhas: elípticas extremas ao invés de
// circulares. SINCRONIZAÇÃO ORBITAL: astros que permanecem no disco
// por tempo suficiente ficam gradualmente "tidally locked" — sua
// velocidade é puxada para acompanhar a rotação do próprio disco,
// até passarem a girar junto com ele (carrossel), e não apenas
// serem atraídos para o centro.
class AldersonDisk extends CelestialObject{
  constructor(wx,wy){
    super(wx,wy,'techAldersonDisk');
    this.radius=2;this.mass=18000;
    this.fixed=true;
    this.host=null;
    this._diskAngle=rand(0,Math.PI); // inclinação do disco
    this._diskR=180;
    this._rotSpeed=0.01;
    this._lockedCount=0;
    this._t=0;
    this._rot=0;
    this.color='#cc99ff';
  }
  attachTo(host){
    this.host=host;
    this.x=host.x;this.y=host.y;
    this._diskAngle=rand(0,Math.PI);
  }
  update(dt){
    if(!this.host||this.host.dead){this.dead=true;return;}
    this.x=this.host.x;this.y=this.host.y;
    this._t+=dt;this._rot+=dt*this._rotSpeed;
    const dx=Math.cos(this._diskAngle),dy=Math.sin(this._diskAngle);
    let locked=0;
    objects.forEach(o=>{
      if(o===this||o===this.host||o.dead||o.fixed)return;
      const d=dist(o,this);
      if(d>this._diskR*1.2||d<1){
        // Fora do alcance do disco: perde sincronia gradualmente
        if(o._aldersonLock>0)o._aldersonLock=Math.max(0,o._aldersonLock-dt/8);
        return;
      }
      // Gravidade uniforme ao longo do disco (não cai com d^2)
      const unifG=0.06;
      o.vx=(o.vx||0)+(this.x-o.x)/d*unifG*dt*60;
      o.vy=(o.vy||0)+(this.y-o.y)/d*unifG*dt*60;
      // Componente perpendicular ao disco — puxa para o plano
      const perp=((o.x-this.x)*(-dy)+(o.y-this.y)*dx);
      const perpF=0.12;
      o.vx=(o.vx||0)-(-dy)*perp*perpF*dt;
      o.vy=(o.vy||0)-dx*perp*perpF*dt;
      // Deforma órbitas para elípticas extremas: adiciona componente radial variável
      const ao=Math.atan2(o.y-this.y,o.x-this.x);
      const ecc=0.9*Math.cos(ao*2);
      o.vx=(o.vx||0)+(this.x-o.x)/d*ecc*.04*dt*60;
      o.vy=(o.vy||0)+(this.y-o.y)/d*ecc*.04*dt*60;
      // Sincronização orbital (tidal lock): o tempo dentro do disco
      // gradualmente "trava" o astro na rotação do próprio disco —
      // um carrossel, não apenas atração para o centro
      o._aldersonLock=Math.min(1,(o._aldersonLock||0)+dt/14);
      if(o._aldersonLock>0){
        const tx=-Math.sin(ao),ty=Math.cos(ao);
        const targetVx=tx*d*this._rotSpeed,targetVy=ty*d*this._rotSpeed;
        const blend=o._aldersonLock*.6*dt;
        o.vx=(o.vx||0)*(1-blend)+targetVx*blend;
        o.vy=(o.vy||0)*(1-blend)+targetVy*blend;
      }
      if(o._aldersonLock>=1)locked++;
    });
    this._lockedCount=locked;
  }
  draw(){
    if(!this.host||this.host.dead)return;
    const sx=this.host.sx(),sy=this.host.sy();
    const hr=this.host.sr();
    const diskPx=this._diskR*cam.zoom;
    // Disco elíptico inclinado
    ctx.save();ctx.translate(sx,sy);ctx.rotate(this._diskAngle+this._rot);
    const gd=ctx.createLinearGradient(-diskPx,0,diskPx,0);
    gd.addColorStop(0,'rgba(180,120,255,.0)');
    gd.addColorStop(.2,'rgba(180,120,255,.22)');
    gd.addColorStop(.5,'rgba(200,150,255,.32)');
    gd.addColorStop(.8,'rgba(180,120,255,.22)');
    gd.addColorStop(1,'rgba(180,120,255,.0)');
    ctx.beginPath();ctx.ellipse(0,0,diskPx,diskPx*.1,0,0,Math.PI*2);
    ctx.fillStyle=gd;ctx.fill();
    ctx.beginPath();ctx.ellipse(0,0,diskPx,diskPx*.1,0,0,Math.PI*2);
    ctx.strokeStyle='rgba(200,140,255,.4)';ctx.lineWidth=Math.max(1,hr*.05);ctx.stroke();
    // Buraco central (onde fica a estrela)
    ctx.beginPath();ctx.ellipse(0,0,hr*1.5,hr*.15,0,0,Math.PI*2);
    ctx.fillStyle='rgba(0,0,0,.5)';ctx.fill();
    ctx.restore();
    // Astros "tidally locked" — sincronizados com a rotação do disco —
    // recebem um anel de sincronia
    objects.forEach(o=>{
      if(o===this||o===this.host||o.dead)return;
      if((o._aldersonLock||0)>=1){
        const ox=o.sx(),oy=o.sy(),orr=Math.max(3,o.sr()*1.3);
        ctx.beginPath();ctx.arc(ox,oy,orr,0,Math.PI*2);
        ctx.strokeStyle=`rgba(200,150,255,${(.4+.15*Math.sin(this._t*3)).toFixed(3)})`;ctx.lineWidth=1.2;ctx.stroke();
      }
    });
    if(sandboxMode){
      const lbl='💿 Disco de Alderson'+(this._lockedCount?` | 🔗${this._lockedCount} sincr.`:'');
      ctx.font=`${Math.max(7,hr*.28)}px 'Courier New'`;ctx.fillStyle='rgba(180,130,255,.5)';
      ctx.textAlign='center';ctx.fillText(lbl,sx,sy+diskPx*.15+12*cam.zoom);ctx.textAlign='left';
    }
  }
}

// ─── 9. MUNDO NICOLL-DYSON ──────────────────────────────────────
// Esfera de Dyson modificada para arma. MECÂNICA: após 15s de carga,
// dispara um raio laser gigante em direção ao objeto mais próximo —
// destrói meteoros/cometas instantaneamente, remove metade da massa de
// astros médios, e destrói astros pequenos. Pode ser redirecionado
// clicando com a ferramenta Nicoll-Dyson ativa antes de disparar.
// Recarrega por 20s entre disparos.
class NicollDysonBeam extends CelestialObject{
  constructor(wx,wy){
    super(wx,wy,'techNicollDyson');
    this.radius=2;this.mass=0;
    this.fixed=true;
    this.host=null;
    this._charge=0;    // 0..15 s
    this._maxCharge=15;
    this._cooldown=0;
    this._firing=false;
    this._fireTimer=0;
    this._fireAngle=0;
    this._fireTarget=null;
    this._t=0;
    this.color='#ffff44';
  }
  attachTo(host){this.host=host;this.x=host.x;this.y=host.y;}
  update(dt){
    if(!this.host||this.host.dead){this.dead=true;return;}
    this.x=this.host.x;this.y=this.host.y;
    this._t+=dt;
    if(this._firing){
      this._fireTimer-=dt;
      if(this._fireTimer<=0){this._firing=false;this._cooldown=20;}
      // Dano ao alvo
      if(this._fireTarget&&!this._fireTarget.dead){
        const dmg=dt*12;
        if(this._fireTarget.radius){
          this._fireTarget.radius=Math.max(0,this._fireTarget.radius-dmg);
          if(this._fireTarget.radius<2){
            spawnExplosion(this._fireTarget.x,this._fireTarget.y,1.8,true);
            this._fireTarget.dead=true;
          }
        }
        // Partículas de impacto
        if(Math.random()<.15){
          particles.push({x:this._fireTarget.x+rand(-5,5),y:this._fireTarget.y+rand(-5,5),
            vx:rand(-6,6),vy:rand(-6,6),r:rand(2,5),alpha:1,color:'#ffffaa'});
        }
      }
      return;
    }
    if(this._cooldown>0){this._cooldown-=dt;return;}
    this._charge=Math.min(this._maxCharge,this._charge+dt);
    if(this._charge>=this._maxCharge){
      // Dispara no astro mais próximo (exceto host)
      let best=null,bestD=Infinity;
      objects.forEach(o=>{
        if(o===this||o===this.host||o.dead||o.fixed)return;
        const d=dist(o,this.host);
        if(d<bestD){bestD=d;best=o;}
      });
      if(best){
        this._fireTarget=best;
        this._fireAngle=Math.atan2(best.y-this.host.y,best.x-this.host.x);
        this._firing=true;
        this._fireTimer=2;
        this._charge=0;
        showTooltip('🔅 Nicoll-Dyson disparou!');
        for(let i=0;i<8;i++)particles.push({
          x:this.host.x+rand(-this.host.radius,this.host.radius),
          y:this.host.y+rand(-this.host.radius,this.host.radius),
          vx:Math.cos(this._fireAngle)*rand(10,20)+rand(-3,3),
          vy:Math.sin(this._fireAngle)*rand(10,20)+rand(-3,3),
          r:rand(2,5),alpha:1,color:'#fffff0'});
      }
    }
  }
  draw(){
    if(!this.host||this.host.dead)return;
    const sx=this.host.sx(),sy=this.host.sy();
    const hr=this.host.sr();
    // Esferas concêntricas de acumulação de energia
    const cPct=this._cooldown>0?0:this._charge/this._maxCharge;
    for(let i=0;i<3;i++){
      ctx.beginPath();ctx.arc(sx,sy,hr*(1.6+i*.4),0,Math.PI*2*cPct);
      ctx.strokeStyle=`rgba(255,255,80,${(.7-i*.2)*cPct})`;
      ctx.lineWidth=Math.max(1,hr*.06);ctx.stroke();
    }
    // Raio laser em disparo
    if(this._firing&&this._fireTarget&&!this._fireTarget.dead){
      const tx=this._fireTarget.sx(),ty=this._fireTarget.sy();
      const fl=this._fireTimer/2;
      for(let i=0;i<3;i++){
        const w=Math.max(1,(5-i*1.5)*cam.zoom*fl);
        const lg=ctx.createLinearGradient(sx,sy,tx,ty);
        lg.addColorStop(0,`rgba(255,255,150,${fl*.9})`);
        lg.addColorStop(.5,`rgba(255,255,80,${fl*.6})`);
        lg.addColorStop(1,`rgba(255,200,0,${fl*.3})`);
        ctx.beginPath();ctx.moveTo(sx,sy);ctx.lineTo(tx,ty);
        ctx.strokeStyle=lg;ctx.lineWidth=w;ctx.stroke();
      }
    }
    if(sandboxMode){
      const label=this._cooldown>0?`🔄 ${Math.ceil(this._cooldown)}s`:
        this._firing?'☀️ DISPARANDO!':
        `⚡ ${Math.round(cPct*100)}%`;
      ctx.font=`${Math.max(7,hr*.28)}px 'Courier New'`;
      ctx.fillStyle=this._firing?'rgba(255,255,80,.85)':'rgba(255,240,80,.55)';
      ctx.textAlign='center';ctx.fillText(label,sx,sy+hr*2.8+10*cam.zoom);ctx.textAlign='left';
    }
  }
}

// ─── 10. PROJETOR DE GRAVIDADE ARTIFICIAL ───────────────────────
// Cria mini-singularidades de gravidade pura. MECÂNICA: não precisa
// de astro-âncora — é posicionado livremente. Gera um VÓRTICE
// gravitacional: além da força radial (atração/repulsão ajustável),
// aplica uma componente tangencial que faz astros ao redor entrarem
// em espiral — um disco de acreção em miniatura. No modo atração,
// meteoros que espiralam até o núcleo podem se FUNDIR em corpos
// maiores (acreção real). Ao atingir sobrecarga (>8 objetos em órbita
// simultânea), pulsa e reinicia o ciclo.
class GravityProjector extends CelestialObject{
  constructor(wx,wy){
    super(wx,wy,'techGravityProjector');
    this.radius=6;this.mass=500;
    this.fixed=true;
    this._intensity=1; // 1|2|3
    this._polarity=1;  // 1=atração | -1=repulsão
    this._t=0;
    this._orbitCount=0;
    this._accreted=0;   // nº de fusões de meteoros realizadas
    this._overloadFlash=0;
    this._fieldRings=Array.from({length:3},(_,i)=>({r:40+i*30,alpha:.3-i*.08,rot:i*Math.PI/3}));
    this.color='#00ffff';
  }
  update(dt){
    this._t+=dt;
    if(this._overloadFlash>0)this._overloadFlash=Math.max(0,this._overloadFlash-dt*2);
    this._fieldRings.forEach((r,i)=>r.rot+=dt*(.25-i*.06)*this._polarity);
    const range=this.radius*(8+this._intensity*6);
    const G=this._intensity*0.05*this._polarity;
    let inOrbit=0;
    const meteorCores=[];
    objects.forEach(o=>{
      if(o===this||o.dead||o.fixed)return;
      const d=dist(o,this);if(d>range||d<1)return;
      const radX=(this.x-o.x)/d,radY=(this.y-o.y)/d;
      // Força radial: atração ou repulsão conforme a polaridade
      const f=G*(1-d/range)*60;
      // Força tangencial: faz o astro entrar em espiral em torno do
      // projetor — o vórtice gravitacional, não apenas puxar/empurrar
      const tangX=-radY*this._polarity,tangY=radX*this._polarity;
      const spiralF=this._intensity*0.04*(1-d/range)*60;
      o.vx=(o.vx||0)+radX*f*dt+tangX*spiralF*dt;
      o.vy=(o.vy||0)+radY*f*dt+tangY*spiralF*dt;
      if(d<range*.5) inOrbit++;
      // Candidatos a acreção: meteoros que espiralaram até o núcleo
      if(this._polarity>0&&o.type==='meteor'&&d<range*.22) meteorCores.push(o);
    });
    this._orbitCount=inOrbit;
    // Acreção: meteoros que se aproximam demais no núcleo do vórtice
    // se fundem em um corpo maior — um disco de acreção em miniatura
    for(let i=0;i<meteorCores.length;i++){
      const a=meteorCores[i];if(a.dead)continue;
      for(let j=i+1;j<meteorCores.length;j++){
        const b=meteorCores[j];if(b.dead)continue;
        if(dist(a,b)<(a.radius+b.radius)*.9){
          a.radius=Math.min(14,a.radius+b.radius*.5);
          a.mass=(a.mass||5)+(b.mass||5)*.5;
          b.dead=true;this._accreted++;
          for(let k=0;k<6;k++)particles.push({x:a.x,y:a.y,vx:rand(-3,3),vy:rand(-3,3),r:rand(1,2.5),alpha:.9,color:'#00ffff'});
        }
      }
    }
    // Sobrecarga
    if(inOrbit>=8&&this._overloadFlash<=0){
      this._overloadFlash=1;
      // Pulso: ejecta todos
      objects.forEach(o=>{
        if(o===this||o.dead||o.fixed)return;
        const d=dist(o,this)||1;if(d>range)return;
        const burst=25;
        o.vx=(o.vx||0)+(o.x-this.x)/d*burst;
        o.vy=(o.vy||0)+(o.y-this.y)/d*burst;
      });
      showTooltip('⚡ Projetor sobrecarregado! Pulso liberado.');
    }
  }
  draw(){
    const sx=this.sx(),sy=this.sy(),r=this.sr();
    // Flash de sobrecarga
    if(this._overloadFlash>0){
      const of=r*8*this._overloadFlash;
      const go=ctx.createRadialGradient(sx,sy,0,sx,sy,of);
      go.addColorStop(0,`rgba(0,255,255,${this._overloadFlash*.4})`);go.addColorStop(1,'transparent');
      ctx.beginPath();ctx.arc(sx,sy,of,0,Math.PI*2);ctx.fillStyle=go;ctx.fill();
    }
    // Anéis de campo gravitacional
    this._fieldRings.forEach(fr=>{
      const rr=(fr.r+this._intensity*15)*cam.zoom;
      ctx.save();ctx.translate(sx,sy);ctx.rotate(fr.rot);
      ctx.beginPath();
      for(let i=0;i<8;i++){
        const a=i*(Math.PI*2/8);
        const px=Math.cos(a)*rr,py=Math.sin(a)*rr;
        if(i===0)ctx.moveTo(px,py);else ctx.lineTo(px,py);
      }
      ctx.closePath();
      ctx.strokeStyle=this._polarity>0?
        `rgba(0,255,200,${fr.alpha+.1*Math.sin(this._t*2)})`:
        `rgba(255,100,0,${fr.alpha+.1*Math.sin(this._t*2)})`;
      ctx.lineWidth=Math.max(.8,r*.1);ctx.stroke();
      ctx.restore();
    });
    // Braços em espiral do vórtice — partículas de poeira gravitacional
    // girando em torno do projetor, formando um pequeno disco de acreção
    const range=this.radius*(8+this._intensity*6)*cam.zoom;
    const vc=this._polarity>0?'0,255,200':'255,120,0';
    for(let i=0;i<28;i++){
      const t=i/28;
      const a=this._t*1.4*this._polarity+t*Math.PI*4;
      const rr=(r*1.3)+(t*range*.8);
      const px=sx+Math.cos(a)*rr,py=sy+Math.sin(a)*rr;
      ctx.beginPath();ctx.arc(px,py,Math.max(.5,1.6*cam.zoom*(1-t*.6)),0,Math.PI*2);
      ctx.fillStyle=`rgba(${vc},${(1-t)*.4})`;ctx.fill();
    }
    // Núcleo
    const gc=ctx.createRadialGradient(sx,sy,0,sx,sy,r);
    const cc=this._polarity>0?'0,255,220':'255,120,0';
    gc.addColorStop(0,`rgba(${cc},1)`);gc.addColorStop(.5,`rgba(${cc},.4)`);gc.addColorStop(1,'transparent');
    ctx.beginPath();ctx.arc(sx,sy,r,0,Math.PI*2);ctx.fillStyle=gc;ctx.fill();
    // Símbolo de polaridade
    ctx.font=`${Math.max(8,r*.8)}px monospace`;ctx.fillStyle='rgba(255,255,255,.8)';
    ctx.textAlign='center';ctx.textBaseline='middle';
    ctx.fillText(this._polarity>0?'+':'−',sx,sy);ctx.textBaseline='alphabetic';ctx.textAlign='left';
    if(sandboxMode){
      const lbl=`Nv.${this._intensity} | ${this._polarity>0?'↓ VÓRTICE':'↑ EJEÇÃO'} | ${this._orbitCount} orb.${this._accreted?` | ⊕${this._accreted}`:''}`;
      ctx.font=`${Math.max(7,r*.5)}px 'Courier New'`;ctx.fillStyle='rgba(0,255,220,.5)';
      ctx.textAlign='center';ctx.fillText(lbl,sx,sy+r+10*cam.zoom);ctx.textAlign='left';
    }
  }
}

// ═══════════════════════════════════════════════════════════════════
//  ENTIDADES VIVAS — Pacote Tecnológico
//  Não morrem sozinhas. Só removidas por delete/reset do usuário.
// ═══════════════════════════════════════════════════════════════════

// ── A. DEVORADOR DE ESTRELAS ────────────────────────────────────────
// Criatura de plasma/energia escura que vaga atraída pelo calor.
// Atraca em estrelas e suga a massa delas lentamente até apagá-las
// ou forçar uma supernova prematura. Corpo escuro com tentáculos de
// energia que pulsam conforme a digestão avança.
class StarDevourerEntity extends CelestialObject{
  constructor(wx,wy){
    super(wx,wy,'entityStarDevourer');
    this.radius=18;this.mass=0;
    this.fixed=false;
    this._t=0;
    this._target=null;    // estrela-alvo atual
    this._docked=false;   // atracado e sugando
    this._sucked=0;       // massa total absorvida
    this._tentacles=Array.from({length:8},(_,i)=>({
      a:i*(Math.PI*2/8)+rand(-.3,.3),
      len:rand(.6,.95),
      speed:rand(.4,.9)*(Math.random()<.5?1:-1),
      phase:rand(0,Math.PI*2)
    }));
    this._hungerGlow=0;   // 0..1 — pulsa ao perseguir
    this._feedFlash=0;
    this.color='#330022';
    this.vx=rand(-1.5,1.5);this.vy=rand(-1.5,1.5);
    this.immune=false;
  }
  _findTarget(){
    const starTypes=_PULSING_TYPES.concat(['protostar','exMonsterStar','exBlitzar']);
    let best=null,bestScore=-Infinity;
    objects.forEach(o=>{
      if(o===this||o.dead||!starTypes.includes(o.type))return;
      // Prefere estrelas maiores e mais próximas
      const d=dist(o,this);
      const score=(o.radius||10)*2 - d*.02;
      if(score>bestScore){bestScore=score;best=o;}
    });
    return best;
  }
  update(dt){
    this._t+=dt;
    if(this._feedFlash>0)this._feedFlash=Math.max(0,this._feedFlash-dt*1.5);
    this._tentacles.forEach(t=>{t.a+=t.speed*dt*.4;});
    // Reavalia alvo a cada 3s ou se o atual morreu
    if(!this._target||this._target.dead){
      this._target=this._findTarget();
      this._docked=false;
    }
    if(!this._target){
      // Vaga aleatoriamente
      this.vx+=rand(-.05,.05);this.vy+=rand(-.05,.05);
      const spd=Math.hypot(this.vx,this.vy);
      if(spd>2){this.vx*=2/spd;this.vy*=2/spd;}
      this.x+=this.vx*dt*60;this.y+=this.vy*dt*60;
      this._docked=false;
      return;
    }
    const d=dist(this,this._target);
    const dockR=(this._target.radius||14)*2.2+this.radius;
    if(d>dockR){
      // Voa em direção à estrela
      const nx=(this._target.x-this.x)/d,ny=(this._target.y-this.y)/d;
      const spd=Math.min(4,d*.04+1.5);
      this.vx=this.vx*.9+nx*spd*.1;this.vy=this.vy*.9+ny*spd*.1;
      this.x+=this.vx*dt*60;this.y+=this.vy*dt*60;
      this._docked=false;
      this._hungerGlow=Math.min(1,this._hungerGlow+dt*.5);
    } else {
      // Atracado — suga massa
      this._docked=true;
      this._hungerGlow=Math.max(0,this._hungerGlow-dt*.3);
      // Ancora perto da estrela
      this.x+=(this._target.x+Math.cos(this._t*.3)*dockR*.9-this.x)*dt*2;
      this.y+=(this._target.y+Math.sin(this._t*.3)*dockR*.9-this.y)*dt*2;
      const drainRate=0.04*dt;
      this._target.radius=Math.max(0,(this._target.radius||14)-drainRate);
      this._target.mass=Math.max(0,(this._target.mass||100)-drainRate*15);
      this._sucked+=drainRate;
      this._feedFlash=Math.min(1,this._feedFlash+dt*.8);
      // Partículas de sucção fluindo do alvo para a entidade
      if(Math.random()<.25){
        const ang=Math.atan2(this.y-this._target.y,this.x-this._target.x)+rand(-.4,.4);
        const d2=dist(this,this._target);
        particles.push({
          x:this._target.x+Math.cos(ang)*this._target.radius*.8,
          y:this._target.y+Math.sin(ang)*this._target.radius*.8,
          vx:Math.cos(ang)*rand(3,7),vy:Math.sin(ang)*rand(3,7),
          r:rand(.8,2.2),alpha:.9,color:`hsl(${rand(280,340)},100%,${rand(55,80)}%)`
        });
      }
      // Estrela apagada ou muito pequena → supernova prematura
      if(this._target.radius<3||this._target.mass<=0){
        spawnExplosion(this._target.x,this._target.y,3.5,true);
        this._target.dead=true;
        this._target=null;this._docked=false;
        showTooltip('🔥 Devorador de Estrelas extinguiu uma estrela! Supernova prematura.');
        this._sucked=0;
      }
    }
  }
  draw(){
    const sx=this.sx(),sy=this.sy(),r=this.sr();
    const T=this._t;
    // Aura de fome pulsante
    if(this._hungerGlow>0){
      const ag=ctx.createRadialGradient(sx,sy,r*.5,sx,sy,r*3.5);
      ag.addColorStop(0,`rgba(180,0,80,${this._hungerGlow*.35})`);
      ag.addColorStop(1,'transparent');
      ctx.beginPath();ctx.arc(sx,sy,r*3.5,0,Math.PI*2);ctx.fillStyle=ag;ctx.fill();
    }
    // Tentáculos de energia
    this._tentacles.forEach(t=>{
      const wriggle=0.18*Math.sin(T*2.5+t.phase);
      const len=r*t.len*(this._docked?1.6:1.1)*(1+.08*Math.sin(T*3+t.phase));
      const a1=t.a+wriggle;
      const mx=sx+Math.cos(a1)*len*.5,my=sy+Math.sin(a1)*len*.5;
      const ex=sx+Math.cos(a1+wriggle)*len,ey=sy+Math.sin(a1+wriggle)*len;
      ctx.beginPath();ctx.moveTo(sx,sy);
      ctx.quadraticCurveTo(mx,my,ex,ey);
      const alpha=this._docked?(.55+.25*Math.sin(T*4+t.phase)):(.3+.15*Math.sin(T*2+t.phase));
      ctx.strokeStyle=`rgba(${this._docked?'255,80,160':'180,0,100'},${alpha})`;
      ctx.lineWidth=Math.max(1,r*.18);ctx.stroke();
      // Extremidades brilhantes
      ctx.beginPath();ctx.arc(ex,ey,Math.max(1.5,r*.12),0,Math.PI*2);
      ctx.fillStyle=`rgba(255,120,200,${alpha*.8})`;ctx.fill();
    });
    // Corpo central escuro
    const gc=ctx.createRadialGradient(sx,sy,0,sx,sy,r);
    const feedA=this._feedFlash;
    gc.addColorStop(0,`rgba(80,0,40,${.7+feedA*.3})`);
    gc.addColorStop(.5,`rgba(40,0,20,.9)`);
    gc.addColorStop(1,`rgba(20,0,10,.95)`);
    ctx.beginPath();ctx.arc(sx,sy,r,0,Math.PI*2);ctx.fillStyle=gc;ctx.fill();
    // Olho central pulsante
    const eyeR=r*.32*(1+.12*Math.sin(T*4));
    const eg=ctx.createRadialGradient(sx,sy,0,sx,sy,eyeR);
    eg.addColorStop(0,`rgba(255,${this._docked?80:40},${this._docked?160:80},${.8+feedA*.2})`);
    eg.addColorStop(1,'transparent');
    ctx.beginPath();ctx.arc(sx,sy,eyeR,0,Math.PI*2);ctx.fillStyle=eg;ctx.fill();
    // Flash de alimentação
    if(this._feedFlash>0){
      const ff=r*2.5;
      const fg=ctx.createRadialGradient(sx,sy,r,sx,sy,ff);
      fg.addColorStop(0,`rgba(255,100,180,${this._feedFlash*.25})`);
      fg.addColorStop(1,'transparent');
      ctx.beginPath();ctx.arc(sx,sy,ff,0,Math.PI*2);ctx.fillStyle=fg;ctx.fill();
    }
    if(sandboxMode){
      ctx.font=`${Math.max(7,r*.45)}px 'Courier New'`;
      ctx.fillStyle=this._docked?'rgba(255,100,180,.7)':'rgba(180,60,120,.5)';
      ctx.textAlign='center';
      ctx.fillText(`🔴 ${this._docked?'SUGANDO':'CAÇANDO'} | ⬇${Math.round(this._sucked*10)/10}`,sx,sy+r+10*cam.zoom);
      ctx.textAlign='left';
    }
  }
}

// ── B. FROTA ALIENÍGENA MILITAR ───────────────────────────────────
// Nave-mãe alienígena de guerra: maior e mais robusta que uma nave
// alienígena comum, com blindagem militar. Captura planetas próximos
// (que passam a orbitá-la e servem como munição), e usa esses
// planetas como projéteis contra as Unidades Reptilianas. Quando não
// tem planetas para lançar, mira a base num Reptiliano e dispara um
// laser de abdução que NÃO abduz — apenas causa dano. Protege astros
// e território Alienígena/Marciano defendendo a área. Pode existir em
// até 3 frotas simultâneas, limitado pela quantidade de Reptilianos
// presentes em campo.
const ALIEN_FLEET_MAX_COUNT=3;
function _alienFleetActiveCount(){
  return objects.filter(o=>o instanceof InvasionFleetEntity && !o.dead).length;
}
function _alienFleetAllowedCount(){
  let reptCount=0;
  if(typeof ReptilianInvasion!=='undefined'&&ReptilianInvasion.isActive()){
    reptCount=ReptilianInvasion.getGroundUnits().length+ReptilianInvasion.getShips().length;
  }
  return Math.min(ALIEN_FLEET_MAX_COUNT,1+Math.floor(reptCount/6));
}
class InvasionFleetEntity extends CelestialObject{
  constructor(wx,wy){
    super(wx,wy,'entityInvasionFleet');
    this.radius=22;this.mass=0;
    this.fixed=false;
    this._t=0;
    this._target=null;
    this._colonizing=false;
    this._colonizeProgress=0;
    this._colonized=[];
    this._captured=[];
    this._miningBeams=[];
    this._bellyLaser=null;
    this._aiming=null; // {target,timer,maxT} — fase de mira antes de disparar
    this._launchBeams=[];
    this.color='#44ffaa';
    this.vx=rand(-.6,.6);this.vy=rand(-.6,.6);
    this.hp=45000;this.maxHP=45000;
    this._hitFlashT=0;
    this._atkTimer=rand(1,2);
    this._reinforceTimer=8+rand(0,4);
    this._thrusterFlare=0;
    this._scanPulse=0;
    this._rings=[
      {a:0,speed:.55,tilt:.22,r:1.55},
      {a:1.1,speed:-.4,tilt:.55,r:1.9},
      {a:2.4,speed:.3,tilt:.85,r:2.25},
    ];
    this._pods=Array.from({length:8},(_,i)=>({phase:i*(Math.PI*2/8),bright:rand(.6,1)}));
    this._searchRadius=560;
  }
  _planetTypes(){
    return ['planet','gasgiant','icegiant','superearth','minineptune','dwarfplanet',
      'lavaplt','oceanplt','desertplt','carbonplt','ironplt','exBlanet'];
  }
  _findTarget(){
    let best=null,bestD=Infinity;
    objects.forEach(o=>{
      if(o===this||o.dead||!this._planetTypes().includes(o.type))return;
      if(this._colonized.includes(o.id))return;
      if(o._alienColonized||o._alienCaptured)return;
      const d=dist(o,this);
      if(d>this._searchRadius)return;
      if(d<bestD){bestD=d;best=o;}
    });
    return best;
  }
  _hasPlanetInRange(){
    return objects.some(o=>!o.dead&&this._planetTypes().includes(o.type)&&
      !o._alienColonized&&!o._alienCaptured&&dist(o,this)<=this._searchRadius);
  }
  _findReptTarget(){
    // ── Alvo principal: Naves Reptilianas COMUNS e a Frota Militar Reptiliana ──
    // Essas ficam soltas em `objects`, já em coordenadas de MUNDO (mesmo
    // sistema da frota), então a comparação de distância é direta.
    let best=null,bestD=Infinity;
    objects.forEach(o=>{
      if(o===this||o.dead)return;
      if(o.type!==RACE_REPTILIAN&&!(o instanceof ReptilianFleetEntity))return;
      const d=dist(o,this);
      if(d<bestD){bestD=d;best=o;}
    });
    if(best)return {kind:best instanceof ReptilianFleetEntity?'reptFleet':'reptShip',unit:best};

    // ── Alvo secundário: unidades da Invasão Reptiliana (evento especial) ──
    // Essas guardam x/y em coordenadas de TELA; convertem-se para MUNDO.
    if(typeof ReptilianInvasion==='undefined'||!ReptilianInvasion.isActive())return null;
    const units=ReptilianInvasion.getGroundUnits();
    bestD=Infinity;best=null;
    units.forEach(u=>{
      const uw=screenToWorld(u.x,u.y);
      const d=Math.hypot(uw.x-this.x,uw.y-this.y);
      if(d<bestD){bestD=d;best=u;}
    });
    if(best)return {kind:'ground',unit:best};
    const ships=ReptilianInvasion.getShips();
    ships.forEach(s=>{
      const sw=screenToWorld(s.x,s.y);
      const d=Math.hypot(sw.x-this.x,sw.y-this.y);
      if(d<bestD){bestD=d;best=s;}
    });
    if(best)return {kind:'ship',unit:best};
    return null;
  }
  _damageReptShip(ship,dmg){
    // Naves Reptilianas comuns não têm HP — têm um escudo (0..3) que
    // normalmente só é reduzido pelas outras raças de forma passiva.
    // A Frota Militar consegue perfurá-lo diretamente em golpes discretos.
    ship._shield=Math.max(0,(ship._shield||3)-dmg);
    ship._strikeFlash=1;
    if(ship._shield<=0){
      ship.dead=true;
      showTooltip('💥 A Frota Alienígena Militar destruiu uma Nave Reptiliana!');
    }
  }
  takeDamage(dmg){
    // Bônus de defesa: se há uma Frota Militar Marciana aliada conectada
    // a esta frota (linha de aliança), reduz o dano recebido.
    const marcianAlly=objects.find(o=>!o.dead&&o instanceof MarcianFleetEntity&&o._allyLink===this);
    const finalDmg=marcianAlly?dmg*0.7:dmg;
    this.hp=Math.max(0,this.hp-finalDmg);
    this._hitFlashT=0.35;
    if(this.hp<=0){
      this.dead=true;
      showTooltip('💥 Frota Alienígena Militar foi destruída pelos Reptilianos!');
    }
  }
  update(dt){
    this._t+=dt;
    this._rings.forEach(rg=>rg.a+=rg.speed*dt);
    this._thrusterFlare=Math.max(0,this._thrusterFlare-dt*2);
    this._scanPulse=Math.max(0,this._scanPulse-dt*.8);
    if(this._hitFlashT>0)this._hitFlashT=Math.max(0,this._hitFlashT-dt);
    this._captured.forEach(cp=>{cp.a+=cp.speed*dt;});
    this._miningBeams=this._miningBeams.filter(b=>{b.timer-=dt;b.alpha=Math.max(0,b.timer/1.5);return b.timer>0;});
    this._launchBeams=this._launchBeams.filter(b=>{b.timer-=dt;b.alpha=Math.max(0,b.timer/0.6);return b.timer>0;});
    if(this._bellyLaser){this._bellyLaser.timer-=dt;this._bellyLaser.alpha=Math.max(0,this._bellyLaser.timer/this._bellyLaser.maxT);if(this._bellyLaser.timer<=0)this._bellyLaser=null;}

    this._captured=this._captured.filter(cp=>cp.obj&&!cp.obj.dead);

    const reptInvasionOn=typeof ReptilianInvasion!=='undefined'&&ReptilianInvasion.isActive();
    // Prioridade #1: se há qualquer Reptiliano (nave comum do jogo normal
    // OU unidade da Invasão) por perto, o combate manda — a frota só volta
    // a caçar planetas quando não há ameaça nenhuma.
    const reptThreat=this._findReptTarget();
    // Helper: converte a posição do alvo para MUNDO, pois unidades da
    // Invasão guardam x/y em coordenadas de TELA, enquanto Naves
    // Reptilianas comuns (RACE_REPTILIAN) já estão em coordenadas de MUNDO.
    const _threatWorldPos=(t)=>(t.kind==='reptShip'||t.kind==='reptFleet')?{x:t.unit.x,y:t.unit.y}:screenToWorld(t.unit.x,t.unit.y);

    // Cancela a mira se o alvo travado morreu, sumiu ou ficou fora de alcance
    if(this._aiming){
      const u=this._aiming.target;
      const gone=!u||u.dead||(u.hp!==undefined&&u.hp<=0)||(u._shield!==undefined&&u._shield<=0);
      const pos=gone?null:((u.type===RACE_REPTILIAN||u instanceof ReptilianFleetEntity)?{x:u.x,y:u.y}:screenToWorld(u.x,u.y));
      const dNow=gone?Infinity:Math.hypot(pos.x-this.x,pos.y-this.y);
      if(gone||dNow>720)this._aiming=null;
    }

    if(reptThreat){
      // Combate ativo: se aproxima do alvo Reptiliano e, ao chegar perto,
      // orbita ao redor dele (em vez de recuar) — fica sempre próxima e em
      // movimento, como uma nave de combate real, não fugindo do inimigo.
      const uw=_threatWorldPos(reptThreat);
      const dToUnit=Math.hypot(uw.x-this.x,uw.y-this.y)||0.001;
      const orbitRange=this._captured.length>0?260:320;
      if(dToUnit>orbitRange){
        // Ainda longe: aproxima direto
        const nx=(uw.x-this.x)/dToUnit,ny=(uw.y-this.y)/dToUnit;
        const spd=Math.min(4.2,dToUnit*.03+1.4);
        this.vx=this.vx*.88+nx*spd*.12;this.vy=this.vy*.88+ny*spd*.12;
        this.x+=this.vx*dt*60;this.y+=this.vy*dt*60;
        this._thrusterFlare=Math.min(1,this._thrusterFlare+dt*1.5);
      } else {
        // Perto o suficiente: orbita o alvo mantendo distância de combate,
        // combinando um componente tangencial (círculo) com um leve puxão
        // radial para não deixar a distância variar demais.
        const nx=(uw.x-this.x)/dToUnit,ny=(uw.y-this.y)/dToUnit; // radial (aponta pro alvo)
        const tx=-ny,ty=nx; // tangencial (perpendicular)
        const radialErr=dToUnit-orbitRange*.75; // quanto está acima/abaixo do raio ideal
        const orbitSpd=2.6;
        const vxTarget=tx*orbitSpd+nx*radialErr*.03;
        const vyTarget=ty*orbitSpd+ny*radialErr*.03;
        this.vx=this.vx*.9+vxTarget*.1;this.vy=this.vy*.9+vyTarget*.1;
        this.x+=this.vx*dt*60;this.y+=this.vy*dt*60;
        this._thrusterFlare=Math.min(1,this._thrusterFlare+dt*0.8);
      }
      this._colonizing=false;
    } else if(this._captured.length<5){
      // Sem ameaça reptiliana por perto: retoma a busca por planetas
      if(!this._target||this._target.dead||this._target._alienColonized||this._target._alienCaptured){
        this._target=this._findTarget();
        this._colonizing=false;
        this._colonizeProgress=0;
      }
      if(this._target){
        const d=dist(this,this._target);
        const engageR=(this._target.radius||8)*3+this.radius;
        if(d>engageR){
          const nx=(this._target.x-this.x)/d,ny=(this._target.y-this.y)/d;
          const spd=Math.min(4,d*.04+1.2);
          this.vx=this.vx*.88+nx*spd*.12;this.vy=this.vy*.88+ny*spd*.12;
          this.x+=this.vx*dt*60;this.y+=this.vy*dt*60;
          this._colonizing=false;
          this._thrusterFlare=Math.min(1,this._thrusterFlare+dt*1.5);
        } else {
          this._colonizing=true;
          this.x+=(this._target.x-this.x)*dt*.6;
          this.y+=(this._target.y-this.y)*dt*.6;
          this._colonizeProgress=Math.min(1,this._colonizeProgress+dt/9);
          if(Math.random()<.05){
            this._miningBeams.push({
              tx:this._target.x+rand(-this._target.radius*.5,this._target.radius*.5),
              ty:this._target.y+rand(-this._target.radius*.5,this._target.radius*.5),
              alpha:1,timer:1.2
            });
          }
          if(this._colonizeProgress>=1){
            this._target._alienCaptured=true;
            this._colonized.push(this._target.id);
            this._captured.push({obj:this._target,a:rand(0,Math.PI*2),r:rand(2.0,2.9),speed:rand(.4,.8)*(Math.random()<.5?1:-1)});
            showTooltip(`🛸 Frota Alienígena Militar capturou ${this._target.name} para usar como munição!`);
            this._target=null;this._colonizing=false;this._colonizeProgress=0;
          }
        }
      } else {
        this.vx+=rand(-.03,.03);this.vy+=rand(-.03,.03);
        const spd=Math.hypot(this.vx,this.vy);
        if(spd>2){this.vx*=2/spd;this.vy*=2/spd;}
        this.x+=this.vx*dt*60;this.y+=this.vy*dt*60;
        this._thrusterFlare=Math.min(1,this._thrusterFlare+dt);
      }
    } else {
      // Estoque de munição cheio e sem ameaça — patrulha
      this.vx+=rand(-.03,.03);this.vy+=rand(-.03,.03);
      const spd=Math.hypot(this.vx,this.vy);
      if(spd>2){this.vx*=2/spd;this.vy*=2/spd;}
      this.x+=this.vx*dt*60;this.y+=this.vy*dt*60;
      this._thrusterFlare=Math.min(1,this._thrusterFlare+dt);
    }

    // ── Ataque: funciona no jogo normal (contra Naves Reptilianas comuns)
    // e também durante a Invasão Reptiliana (contra suas unidades). ──────
    this._atkTimer-=dt;
    if(reptThreat&&this._atkTimer<=0){
      const uw=_threatWorldPos(reptThreat);
      const planetNearby=this._hasPlanetInRange()||this._captured.length>0;
      const dToUnit=Math.hypot(uw.x-this.x,uw.y-this.y);
      const _applyDmg=(dmg)=>{
        if(reptThreat.kind==='reptShip')this._damageReptShip(reptThreat.unit,dmg*0.00035); // converte dano em fração de escudo (0..3)
        else if(reptThreat.kind==='reptFleet')reptThreat.unit.takeDamage(dmg);
        else ReptilianInvasion.damageGroundUnit(reptThreat.unit,dmg);
      };
      if(this._captured.length>0 && dToUnit<520){
        // Planeta em estoque: lançamento é instantâneo (arremesso físico,
        // não precisa de mira fina como o laser).
        const cp=this._captured.shift();
        const dmg=1800+Math.random()*900;
        _applyDmg(dmg);
        this._launchBeams.push({tx:uw.x,ty:uw.y,alpha:1,timer:0.6,color:'rgba(90,255,170,',world:true});
        showTooltip(`🪐 A Frota Alienígena arremessou ${cp.obj.name||'um planeta'} contra uma Nave Reptiliana!`);
        cp.obj.dead=true;
        this._aiming=null;
        this._atkTimer=2.2+Math.random()*1.4;
      } else if(!planetNearby && dToUnit<680){
        // Sem planetas no raio de busca: precisa mirar antes de disparar
        // o laser ventral. Enquanto mira, o feixe fica fraco/instável;
        // só causa dano quando o tempo de mira se esgota.
        if(!this._aiming||this._aiming.target!==reptThreat.unit){
          this._aiming={target:reptThreat.unit,timer:0,maxT:0.85};
        } else {
          this._aiming.timer+=dt;
          if(this._aiming.timer>=this._aiming.maxT){
            const dmg=900+Math.random()*450;
            _applyDmg(dmg);
            this._bellyLaser={target:reptThreat.unit,alpha:1,timer:0.4,maxT:0.4,world:(reptThreat.kind==='reptShip'||reptThreat.kind==='reptFleet')};
            this._aiming=null;
            this._atkTimer=1.7+Math.random()*0.9;
          }
        }
      } else {
        this._aiming=null;
      }
    } else if(!reptThreat){
      this._aiming=null;
    }

    if(reptInvasionOn){
      this._reinforceTimer-=dt;
      if(this._reinforceTimer<=0){
        this._reinforceTimer=14+rand(0,8);
        if(_alienFleetActiveCount()<_alienFleetAllowedCount()){
          const ang=rand(0,Math.PI*2),rr=rand(80,160);
          const nf=new InvasionFleetEntity(this.x+Math.cos(ang)*rr,this.y+Math.sin(ang)*rr);
          objects.push(nf);
          showTooltip('🛸 A Frota Alienígena Militar chamou reforços!');
        }
      }
    }
  }
  draw(){
    const sx=this.sx(),sy=this.sy(),r=this.sr();
    const T=this._t;

    this._captured.forEach(cp=>{
      const rx=sx+Math.cos(cp.a)*r*cp.r,ry=sy+Math.sin(cp.a)*r*cp.r*0.32;
      const pr=Math.max(3,(cp.obj.radius||8)*cam.zoom*0.6);
      ctx.beginPath();ctx.arc(rx,ry,pr,0,Math.PI*2);
      ctx.fillStyle=cp.obj.color||'#88ffcc';ctx.fill();
      ctx.strokeStyle='rgba(120,255,200,.8)';ctx.lineWidth=1;ctx.stroke();
    });

    this._miningBeams.forEach(b=>{
      const ts=worldToScreen(b.tx,b.ty);
      const bg=ctx.createLinearGradient(sx,sy,ts.x,ts.y);
      bg.addColorStop(0,`rgba(100,255,180,${b.alpha*.8})`);
      bg.addColorStop(1,`rgba(60,220,150,0)`);
      ctx.beginPath();ctx.moveTo(sx,sy);ctx.lineTo(ts.x,ts.y);
      ctx.strokeStyle=bg;ctx.lineWidth=Math.max(1,r*.07);ctx.stroke();
    });

    this._launchBeams.forEach(b=>{
      const bp=b.world?worldToScreen(b.tx,b.ty):{x:b.tx,y:b.ty};
      ctx.beginPath();ctx.arc(bp.x,bp.y,18*(1-b.alpha)+6,0,Math.PI*2);
      ctx.strokeStyle=b.color+(b.alpha*.9)+')';ctx.lineWidth=2;ctx.stroke();
    });

    ctx.save();ctx.translate(sx,sy);
    if(this._thrusterFlare>0){
      for(let i=0;i<4;i++){
        const fa=Math.PI*.5+i*(Math.PI*2/4);
        const fx=Math.cos(fa)*r*.8,fy=Math.sin(fa)*r*.8;
        const fg=ctx.createRadialGradient(fx,fy,0,fx,fy,r*.5*this._thrusterFlare);
        fg.addColorStop(0,'rgba(120,255,200,.9)');fg.addColorStop(.5,'rgba(40,200,120,.4)');fg.addColorStop(1,'transparent');
        ctx.beginPath();ctx.arc(fx,fy,r*.5*this._thrusterFlare,0,Math.PI*2);ctx.fillStyle=fg;ctx.fill();
      }
    }

    const aura=ctx.createRadialGradient(0,0,r*.8,0,0,r*2.2);
    aura.addColorStop(0,`rgba(60,255,160,${.12+.06*Math.sin(T*2)})`);aura.addColorStop(1,'transparent');
    ctx.beginPath();ctx.ellipse(0,0,r*2.2,r*2.2*.28,0,0,Math.PI*2);ctx.fillStyle=aura;ctx.fill();

    ctx.beginPath();ctx.ellipse(0,0,r*1.85,r*1.85*.24,0,0,Math.PI*2);
    ctx.strokeStyle=`rgba(60,220,150,${.5+.15*Math.sin(T*3)})`;ctx.lineWidth=Math.max(1.5,r*.12);ctx.stroke();

    const dg=ctx.createRadialGradient(-r*.2,-r*.06,0,0,0,r*1.15);
    dg.addColorStop(0,'rgba(180,255,220,.95)');dg.addColorStop(.35,'rgba(40,180,110,.9)');
    dg.addColorStop(.7,'rgba(15,100,60,.85)');dg.addColorStop(1,'rgba(6,45,28,.6)');
    ctx.beginPath();ctx.ellipse(0,0,r*1.15,r*1.15*.32,0,0,Math.PI*2);
    ctx.fillStyle=this._hitFlashT>0?`rgba(255,255,255,${.5+this._hitFlashT})`:dg;
    ctx.fill();
    ctx.strokeStyle='rgba(120,255,190,.75)';ctx.lineWidth=Math.max(1,r*.08);ctx.stroke();

    ctx.strokeStyle='rgba(10,50,32,.55)';ctx.lineWidth=Math.max(.8,r*.045);
    for(let i=0;i<8;i++){
      const a=i*(Math.PI/4);
      ctx.beginPath();
      ctx.moveTo(Math.cos(a)*r*.4,Math.sin(a)*r*.4*.32);
      ctx.lineTo(Math.cos(a)*r*1.1,Math.sin(a)*r*1.1*.32);
      ctx.stroke();
    }

    const domeGrad=ctx.createRadialGradient(-r*.15,-r*.35,0,0,-r*.18,r*.68);
    domeGrad.addColorStop(0,'rgba(230,255,240,.95)');domeGrad.addColorStop(.4,'rgba(90,220,160,.6)');domeGrad.addColorStop(1,'rgba(15,110,70,.18)');
    ctx.beginPath();ctx.ellipse(0,-r*.12,r*.68,r*.5,0,Math.PI,Math.PI*2);ctx.fillStyle=domeGrad;ctx.fill();
    ctx.beginPath();ctx.ellipse(0,-r*.12,r*.68,r*.5,0,Math.PI,Math.PI*2);
    ctx.strokeStyle='rgba(150,255,200,.55)';ctx.lineWidth=Math.max(.8,r*.06);ctx.stroke();
    ctx.beginPath();ctx.ellipse(-r*.18,-r*.38,r*.16,r*.07,-.5,0,Math.PI*2);
    ctx.fillStyle='rgba(255,255,255,.5)';ctx.fill();

    this._pods.forEach((p,i)=>{
      const pa=p.phase+T*.1;
      const px=Math.cos(pa)*r*1.0,py=Math.sin(pa)*r*1.0*.3;
      const pr=Math.max(2,r*.15);
      ctx.beginPath();ctx.ellipse(px,py,pr,pr*.55,pa,0,Math.PI*2);
      ctx.fillStyle=`rgba(30,90,55,${p.bright*.9})`;ctx.fill();
      ctx.strokeStyle=`rgba(140,255,200,${p.bright*.6})`;ctx.lineWidth=1;ctx.stroke();
      ctx.beginPath();ctx.arc(px,py,pr*.4,0,Math.PI*2);
      ctx.fillStyle=`rgba(180,255,220,${.5+.3*Math.sin(T*4+i)})`;ctx.fill();
    });

    this._rings.forEach(rg=>{
      const scale=Math.abs(Math.cos(rg.tilt))*0.3+0.05;
      ctx.beginPath();ctx.ellipse(0,0,r*rg.r,r*rg.r*scale,rg.a,0,Math.PI*2);
      ctx.strokeStyle=`rgba(70,255,180,${.28+.1*Math.sin(T*2+rg.a)})`;
      ctx.lineWidth=Math.max(1,r*.06);ctx.setLineDash([r*.2,r*.16]);ctx.stroke();ctx.setLineDash([]);
    });

    const coreAlpha=this._scanPulse>0?.9:.6+.15*Math.sin(T*4);
    const cg=ctx.createRadialGradient(0,0,0,0,0,r*.26);
    cg.addColorStop(0,`rgba(140,255,210,${coreAlpha})`);cg.addColorStop(1,'rgba(140,255,210,.1)');
    ctx.beginPath();ctx.arc(0,0,r*.26,0,Math.PI*2);ctx.fillStyle=cg;ctx.fill();

    ctx.beginPath();ctx.ellipse(0,r*.42,r*.22,r*.12,0,0,Math.PI*2);
    ctx.fillStyle=`rgba(20,70,45,.9)`;ctx.fill();
    ctx.strokeStyle='rgba(140,255,210,.6)';ctx.lineWidth=1;ctx.stroke();
    ctx.beginPath();ctx.arc(0,r*.42,r*.1,0,Math.PI*2);
    ctx.fillStyle=this._bellyLaser?`rgba(220,255,235,${.6+.4*Math.sin(T*20)})`:'rgba(120,255,190,.55)';
    ctx.fill();

    ctx.restore();

    // ── Feixe de mira (fraco, tremido) enquanto trava o alvo ──
    if(this._aiming&&this._aiming.target){
      const u=this._aiming.target;
      const up=u.type===RACE_REPTILIAN?worldToScreen(u.x,u.y):{x:u.x,y:u.y};
      const emitX=sx,emitY=sy+r*.42;
      const jitter=(Math.random()-.5)*4;
      const aimProg=this._aiming.timer/this._aiming.maxT;
      ctx.beginPath();ctx.moveTo(emitX,emitY);ctx.lineTo(up.x+jitter,up.y+jitter);
      ctx.strokeStyle=`rgba(140,255,210,${.25+.35*aimProg})`;ctx.lineWidth=1.5;ctx.setLineDash([4,5]);ctx.stroke();ctx.setLineDash([]);
      ctx.beginPath();ctx.arc(up.x,up.y,6+3*Math.sin(T*15),0,Math.PI*2);
      ctx.strokeStyle=`rgba(180,255,220,${.4+.4*aimProg})`;ctx.lineWidth=1.5;ctx.stroke();
    }

    if(this._bellyLaser&&this._bellyLaser.target){
      const u=this._bellyLaser.target;
      const up=u.type===RACE_REPTILIAN?worldToScreen(u.x,u.y):{x:u.x,y:u.y};
      const emitX=sx,emitY=sy+r*.42;
      const bg=ctx.createLinearGradient(emitX,emitY,up.x,up.y);
      bg.addColorStop(0,`rgba(140,255,210,${this._bellyLaser.alpha*.95})`);
      bg.addColorStop(1,`rgba(60,220,150,0)`);
      ctx.beginPath();ctx.moveTo(emitX,emitY);ctx.lineTo(up.x,up.y);
      ctx.strokeStyle=bg;ctx.lineWidth=Math.max(3,r*.22);ctx.stroke();
      ctx.beginPath();ctx.moveTo(emitX,emitY);ctx.lineTo(up.x,up.y);
      ctx.strokeStyle=`rgba(255,255,255,${this._bellyLaser.alpha*.6})`;ctx.lineWidth=Math.max(1,r*.08);ctx.stroke();
      ctx.beginPath();ctx.arc(up.x,up.y,Math.max(3,8*this._bellyLaser.alpha),0,Math.PI*2);
      ctx.fillStyle=`rgba(180,255,220,${this._bellyLaser.alpha*.8})`;ctx.fill();
    }

    const hpPct=this.hp/this.maxHP;
    ctx.fillStyle='rgba(0,0,0,.5)';ctx.fillRect(sx-r*1.5,sy-r*1.7,r*3,4);
    ctx.fillStyle=hpPct>.5?'rgba(80,255,180,.9)':hpPct>.2?'rgba(255,200,60,.9)':'rgba(255,70,70,.9)';
    ctx.fillRect(sx-r*1.5,sy-r*1.7,r*3*hpPct,4);

    if(this._colonizing&&this._target&&!this._target.dead){
      const tsp=worldToScreen(this._target.x,this._target.y);
      ctx.beginPath();ctx.moveTo(sx,sy);ctx.lineTo(tsp.x,tsp.y);
      ctx.strokeStyle=`rgba(100,255,180,.2)`;ctx.setLineDash([6,5]);ctx.lineWidth=1;ctx.stroke();
      ctx.setLineDash([]);
      const pr=this._target.sr();
      ctx.beginPath();ctx.arc(tsp.x,tsp.y,pr*1.5,-Math.PI*.5,-Math.PI*.5+Math.PI*2*this._colonizeProgress);
      ctx.strokeStyle=`rgba(100,255,180,.7)`;ctx.lineWidth=Math.max(1.5,pr*.1);ctx.stroke();
    }
    if(sandboxMode){
      ctx.font=`${Math.max(7,r*.4)}px 'Courier New'`;
      ctx.fillStyle='rgba(100,255,180,.65)';
      ctx.textAlign='center';
      const status=this._aiming?'MIRANDO':this._colonizing?`CAPTURANDO ${Math.round(this._colonizeProgress*100)}%`:(this._captured.length>0||this._bellyLaser?'EM COMBATE':'PATRULHANDO');
      ctx.fillText(`🛸 ${status} | 🪐${this._captured.length} | ❤${Math.round(this.hp)}`,sx,sy+r*2.4+10*cam.zoom);
      ctx.textAlign='left';
    }
  }
}

// ── B2. FROTA MILITAR MARCIANA ──────────────────────────────────────
// Aliada total da Frota Alienígena Militar. Visual inspirado na Nave
// Marciana comum (casco industrial steampunk, cúpula de vidro, engre-
// nagens, pernas retráteis), mas em paleta aço-azulado/cobre para se
// diferenciar como unidade militar. Ataque baixo, porém defesa (HP)
// superior à da Frota Alienígena. Busca a Frota Alienígena mais
// próxima e se conecta a ela com uma linha de aliança: enquanto
// conectada, a Marciana ganha bônus de ataque e a Alienígena ganha
// bônus de defesa (redução de dano recebido). Ataca exclusivamente
// Naves Reptilianas comuns (RACE_REPTILIAN) do jogo normal.
function _marcianFleetActiveCount(){
  return objects.filter(o=>o instanceof MarcianFleetEntity && !o.dead).length;
}
class MarcianFleetEntity extends CelestialObject{
  constructor(wx,wy){
    super(wx,wy,'entityMarcianFleet');
    this.radius=20;this.mass=0;
    this.fixed=false;
    this._t=0;
    this.color='#ffb347';
    this.vx=rand(-.5,.5);this.vy=rand(-.5,.5);
    // Defesa superior à Frota Alienígena (45000), ataque bem mais baixo
    this.hp=64000;this.maxHP=64000;
    this._hitFlashT=0;
    this._atkTimer=rand(1.5,2.5);
    this._thrusterFlare=0;
    this._legAngle=0;
    this._allyLink=null;       // Frota Alienígena aliada conectada
    this._allySearchTimer=0;
    this._laser=null;          // feixe visual de ataque
    this._pistonPhase=rand(0,Math.PI*2);
    this._gearRot=0;
    this._searchRadius=620;
    this._linkRange=520;       // alcance máximo pra manter a aliança
    this._atkBonus=0;          // bônus de ataque recebido da aliança (visual/lógico)
  }
  _findReptShip(){
    let best=null,bestD=Infinity;
    objects.forEach(o=>{
      if(o===this||o.dead)return;
      if(o.type!==RACE_REPTILIAN&&!(o instanceof ReptilianFleetEntity))return;
      const d=dist(o,this);
      if(d>this._searchRadius)return;
      if(d<bestD){bestD=d;best=o;}
    });
    return best;
  }
  _findAllyFleet(){
    let best=null,bestD=Infinity;
    objects.forEach(o=>{
      if(o.dead||!(o instanceof InvasionFleetEntity))return;
      const d=dist(o,this);
      if(d<bestD){bestD=d;best=o;}
    });
    return best;
  }
  takeDamage(dmg){
    // Defesa superior: reduz uma fração do dano recebido (armadura extra)
    const mitigated=dmg*0.72;
    this.hp=Math.max(0,this.hp-mitigated);
    this._hitFlashT=0.35;
    if(this.hp<=0){
      this.dead=true;
      showTooltip('💥 Frota Militar Marciana foi destruída pelos Reptilianos!');
    }
  }
  update(dt){
    this._t+=dt;
    this._gearRot+=dt*.5;
    this._thrusterFlare=Math.max(0,this._thrusterFlare-dt*2);
    if(this._hitFlashT>0)this._hitFlashT=Math.max(0,this._hitFlashT-dt);
    if(this._laser){this._laser.t+=dt;if(this._laser.t>=this._laser.maxT)this._laser=null;}

    // ── Mantém/renova o vínculo de aliança com a Frota Alienígena ──
    this._allySearchTimer-=dt;
    if(this._allyLink&&(this._allyLink.dead||dist(this,this._allyLink)>this._linkRange)){
      this._allyLink=null;
    }
    if(!this._allyLink&&this._allySearchTimer<=0){
      this._allySearchTimer=1.5;
      this._allyLink=this._findAllyFleet();
    }
    this._atkBonus=this._allyLink?0.35:0; // +35% de ataque quando aliada conectada

    const reptShip=this._findReptShip();
    if(reptShip){
      // Combate: aproxima e orbita a Nave Reptiliana, como uma escolta
      const dToUnit=dist(this,reptShip)||0.001;
      const orbitRange=300;
      if(dToUnit>orbitRange){
        const nx=(reptShip.x-this.x)/dToUnit,ny=(reptShip.y-this.y)/dToUnit;
        const spd=Math.min(3.6,dToUnit*.03+1.2);
        this.vx=this.vx*.88+nx*spd*.12;this.vy=this.vy*.88+ny*spd*.12;
        this.x+=this.vx*dt*60;this.y+=this.vy*dt*60;
        this._thrusterFlare=Math.min(1,this._thrusterFlare+dt*1.4);
      } else {
        const nx=(reptShip.x-this.x)/dToUnit,ny=(reptShip.y-this.y)/dToUnit;
        const tx=-ny,ty=nx;
        const radialErr=dToUnit-orbitRange*.78;
        const orbitSpd=2.1;
        const vxTarget=tx*orbitSpd+nx*radialErr*.03;
        const vyTarget=ty*orbitSpd+ny*radialErr*.03;
        this.vx=this.vx*.9+vxTarget*.1;this.vy=this.vy*.9+vyTarget*.1;
        this.x+=this.vx*dt*60;this.y+=this.vy*dt*60;
        this._thrusterFlare=Math.min(1,this._thrusterFlare+dt*.7);
      }
    } else if(this._allyLink){
      // Sem ameaça: acompanha a Frota Alienígena aliada, mantendo distância de escolta
      const d=dist(this,this._allyLink)||0.001;
      if(d>180){
        const nx=(this._allyLink.x-this.x)/d,ny=(this._allyLink.y-this.y)/d;
        const spd=Math.min(2.6,d*.02+.8);
        this.vx=this.vx*.9+nx*spd*.1;this.vy=this.vy*.9+ny*spd*.1;
        this.x+=this.vx*dt*60;this.y+=this.vy*dt*60;
      } else {
        this.vx*=.95;this.vy*=.95;
        this.x+=this.vx*dt*60;this.y+=this.vy*dt*60;
      }
    } else {
      // Patrulha livre em busca de aliados ou ameaças
      this.vx+=rand(-.03,.03);this.vy+=rand(-.03,.03);
      const spd=Math.hypot(this.vx,this.vy);
      if(spd>1.8){this.vx*=1.8/spd;this.vy*=1.8/spd;}
      this.x+=this.vx*dt*60;this.y+=this.vy*dt*60;
      this._thrusterFlare=Math.min(1,this._thrusterFlare+dt*.5);
    }

    // ── Ataque: baixo dano, porém reforçado pelo bônus de aliança ──
    this._atkTimer-=dt;
    if(reptShip&&this._atkTimer<=0){
      const dToUnit=dist(this,reptShip);
      if(dToUnit<560){
        this._laser={target:reptShip,t:0,maxT:0.35};
        if(reptShip instanceof ReptilianFleetEntity){
          const dmg=(180+Math.random()*90)*(1+this._atkBonus);
          reptShip.takeDamage(dmg);
        } else {
          const baseDmg=0.00018; // fração de escudo (0..3) — bem menor que a Alienígena
          const dmg=baseDmg*(1+this._atkBonus);
          reptShip._shield=Math.max(0,(reptShip._shield||3)-dmg);
          reptShip._strikeFlash=1;
          if(reptShip._shield<=0){
            reptShip.dead=true;
            showTooltip('💥 A Frota Militar Marciana destruiu uma Nave Reptiliana!');
          }
        }
        this._atkTimer=2.4+Math.random()*1.2;
      }
    }
  }
  draw(){
    const sx=this.sx(),sy=this.sy(),r=this.sr();
    const T=this._t;

    // ── Linha de aliança com a Frota Alienígena ──
    if(this._allyLink&&!this._allyLink.dead){
      const asx=this._allyLink.sx(),asy=this._allyLink.sy();
      const pulse=.4+.25*Math.sin(T*3);
      const lg=ctx.createLinearGradient(sx,sy,asx,asy);
      lg.addColorStop(0,`rgba(255,180,80,${pulse})`);
      lg.addColorStop(.5,`rgba(150,255,200,${pulse*.8})`);
      lg.addColorStop(1,`rgba(70,255,160,${pulse})`);
      ctx.beginPath();ctx.moveTo(sx,sy);ctx.lineTo(asx,asy);
      ctx.strokeStyle=lg;ctx.lineWidth=Math.max(1,r*.09);ctx.setLineDash([8,6]);ctx.stroke();ctx.setLineDash([]);
      // pequenos pulsos de energia percorrendo a linha
      const travelT=(T*.6)%1;
      const px=sx+(asx-sx)*travelT,py=sy+(asy-sy)*travelT;
      ctx.beginPath();ctx.arc(px,py,Math.max(1.5,r*.12),0,Math.PI*2);
      ctx.fillStyle=`rgba(255,220,150,.9)`;ctx.fill();
    }

    // ── Feixe de ataque ──
    if(this._laser&&this._laser.target&&!this._laser.target.dead){
      const u=this._laser.target;
      const alpha=1-this._laser.t/this._laser.maxT;
      const lg=ctx.createLinearGradient(sx,sy,u.x?this._laser.target.sx?this._laser.target.sx():sx:sx,sy);
      ctx.beginPath();ctx.moveTo(sx,sy);ctx.lineTo(u.sx?u.sx():sx,u.sy?u.sy():sy);
      ctx.strokeStyle=`rgba(255,190,90,${alpha*.85})`;ctx.lineWidth=Math.max(1.5,r*.12);ctx.stroke();
    }

    ctx.save();ctx.translate(sx,sy);
    if(this._thrusterFlare>0){
      for(let i=0;i<4;i++){
        const fa=Math.PI*.5+i*(Math.PI*2/4);
        const fx=Math.cos(fa)*r*.75,fy=Math.sin(fa)*r*.75;
        const fg=ctx.createRadialGradient(fx,fy,0,fx,fy,r*.45*this._thrusterFlare);
        fg.addColorStop(0,'rgba(255,200,120,.85)');fg.addColorStop(.5,'rgba(200,110,40,.4)');fg.addColorStop(1,'transparent');
        ctx.beginPath();ctx.arc(fx,fy,r*.45*this._thrusterFlare,0,Math.PI*2);ctx.fillStyle=fg;ctx.fill();
      }
    }

    // Sombra
    const shadowG=ctx.createRadialGradient(r*.1,r*.3,0,r*.1,r*.3,r*1.5);
    shadowG.addColorStop(0,'rgba(0,0,0,.3)');shadowG.addColorStop(1,'transparent');
    ctx.beginPath();ctx.ellipse(r*.1,r*.4,r*1.4,r*.38,0,0,Math.PI*2);ctx.fillStyle=shadowG;ctx.fill();

    // 4 braços mecânicos radiais (herdados do design Marciano), tom aço/cobre
    for(let i=0;i<4;i++){
      const aa=i*(Math.PI/2)+this._gearRot*.36;
      const ax1=Math.cos(aa)*r*.5,ay1=Math.sin(aa)*r*.2;
      const ax2=Math.cos(aa)*r*1.15,ay2=Math.sin(aa)*r*.44;
      ctx.beginPath();ctx.moveTo(ax1,ay1);ctx.lineTo(ax2,ay2);
      ctx.strokeStyle='rgba(160,180,210,.85)';ctx.lineWidth=Math.max(2,r*.1);ctx.stroke();
      ctx.beginPath();ctx.moveTo(ax1,ay1);ctx.lineTo(ax2,ay2);
      ctx.strokeStyle='rgba(255,180,90,.35)';ctx.lineWidth=Math.max(.8,r*.04);ctx.stroke();
    }

    // 3 engrenagens giratórias no anel externo
    for(let g=0;g<3;g++){
      const ga=g*(Math.PI*2/3)+this._gearRot;
      const gx=Math.cos(ga)*r*.82,gy=Math.sin(ga)*r*.35;
      const gr=Math.max(2,r*.13);
      ctx.save();ctx.translate(gx,gy);ctx.rotate(T*(g%2===0?1:-.85));
      ctx.beginPath();ctx.arc(0,0,gr,0,Math.PI*2);
      ctx.fillStyle='rgba(90,105,130,.95)';ctx.fill();
      ctx.strokeStyle='rgba(255,190,100,.75)';ctx.lineWidth=Math.max(.5,r*.03);ctx.stroke();
      for(let d=0;d<8;d++){
        const da=d*(Math.PI/4);
        const dx1=Math.cos(da)*(gr-.5),dy1=Math.sin(da)*(gr-.5);
        const dx2=Math.cos(da)*(gr+Math.max(1,r*.05)),dy2=Math.sin(da)*(gr+Math.max(1,r*.05));
        ctx.beginPath();ctx.moveTo(dx1,dy1);ctx.lineTo(dx2,dy2);
        ctx.strokeStyle='rgba(200,150,80,.85)';ctx.lineWidth=Math.max(1,r*.045);ctx.stroke();
      }
      ctx.restore();
    }

    // Casco principal — octógono industrial, paleta aço-azulado com friso cobre
    const bodyG=ctx.createRadialGradient(-r*.25,-r*.15,0,0,0,r*.9);
    bodyG.addColorStop(0,'rgba(210,220,235,1)');
    bodyG.addColorStop(.35,'rgba(140,160,190,.95)');
    bodyG.addColorStop(.7,'rgba(70,85,110,.9)');
    bodyG.addColorStop(1,'rgba(35,42,58,.7)');
    ctx.beginPath();
    for(let i=0;i<8;i++){
      const oa=i*(Math.PI/4)+Math.PI/8;
      const ox=Math.cos(oa)*r*.85*(i%2===0?1:.8);
      const oy=Math.sin(oa)*r*.4*(i%2===0?1:.8);
      i===0?ctx.moveTo(ox,oy):ctx.lineTo(ox,oy);
    }
    ctx.closePath();
    ctx.fillStyle=this._hitFlashT>0?`rgba(255,255,255,${.5+this._hitFlashT})`:bodyG;
    ctx.fill();
    ctx.strokeStyle='rgba(255,190,100,.8)';ctx.lineWidth=Math.max(1,r*.06);ctx.stroke();

    // Rebites
    for(let b=0;b<8;b++){
      const ba=b*(Math.PI/4)+Math.PI/8;
      const bx=Math.cos(ba)*r*.68*(b%2===0?1:.82);
      const by=Math.sin(ba)*r*.31*(b%2===0?1:.82);
      ctx.beginPath();ctx.arc(bx,by,Math.max(.8,r*.035),0,Math.PI*2);
      ctx.fillStyle='rgba(255,210,140,1)';ctx.fill();
      ctx.strokeStyle='rgba(120,90,40,.7)';ctx.lineWidth=Math.max(.3,r*.018);ctx.stroke();
    }

    // Cúpula superior — vidro azul-aço com friso âmbar (contraste com a Marciana comum)
    const dG=ctx.createRadialGradient(-r*.15,-r*.4,0,0,-r*.2,r*.55);
    dG.addColorStop(0,'rgba(210,235,255,.92)');
    dG.addColorStop(.4,'rgba(120,170,220,.6)');
    dG.addColorStop(1,'rgba(30,60,90,.2)');
    ctx.beginPath();ctx.ellipse(0,-r*.2,r*.55,r*.4,0,Math.PI,Math.PI*2);ctx.fillStyle=dG;ctx.fill();
    ctx.beginPath();ctx.ellipse(0,-r*.2,r*.55,r*.4,0,Math.PI,Math.PI*2);
    ctx.strokeStyle='rgba(255,190,100,.7)';ctx.lineWidth=Math.max(.7,r*.045);ctx.stroke();
    ctx.beginPath();ctx.ellipse(-r*.13,-r*.42,r*.12,r*.055,-.35,0,Math.PI*2);
    ctx.fillStyle='rgba(255,255,255,.4)';ctx.fill();

    // Engrenagem central (emblema militar)
    const cgr=Math.max(2,r*.18);
    ctx.save();ctx.rotate(T*.35);
    ctx.beginPath();ctx.arc(0,0,cgr,0,Math.PI*2);
    ctx.fillStyle='rgba(60,75,100,.95)';ctx.fill();
    for(let d=0;d<10;d++){
      const da=d*(Math.PI/5);
      ctx.beginPath();
      ctx.moveTo(Math.cos(da)*(cgr-.5),Math.sin(da)*(cgr-.5));
      ctx.lineTo(Math.cos(da)*(cgr+Math.max(1,r*.045)),Math.sin(da)*(cgr+Math.max(1,r*.045)));
      ctx.strokeStyle='rgba(255,190,100,.85)';ctx.lineWidth=Math.max(1,r*.05);ctx.stroke();
    }
    ctx.beginPath();ctx.arc(0,0,Math.max(.5,cgr*.4),0,Math.PI*2);
    ctx.fillStyle='rgba(200,220,240,.9)';ctx.fill();
    ctx.restore();

    // Pernas retráteis (design marciano clássico) — sempre semi-abertas (frota móvel)
    for(let l=0;l<3;l++){
      const la=Math.PI*.5+l*(Math.PI*2/3);
      const lx1=Math.cos(la)*r*.5,ly1=Math.sin(la)*r*.35+r*.15;
      const lx2=Math.cos(la)*r*.85,ly2=Math.sin(la)*r*.7+r*.15;
      ctx.beginPath();ctx.moveTo(lx1,ly1);ctx.lineTo(lx2,ly2);
      ctx.strokeStyle='rgba(150,165,190,.7)';ctx.lineWidth=Math.max(1.5,r*.07);ctx.stroke();
      ctx.beginPath();ctx.arc(lx2,ly2,Math.max(1,r*.05),0,Math.PI*2);
      ctx.fillStyle='rgba(255,190,100,.8)';ctx.fill();
    }

    ctx.restore();

    const hpPct=this.hp/this.maxHP;
    ctx.fillStyle='rgba(0,0,0,.5)';ctx.fillRect(sx-r*1.5,sy-r*1.7,r*3,4);
    ctx.fillStyle=hpPct>.5?'rgba(140,200,255,.9)':hpPct>.2?'rgba(255,200,60,.9)':'rgba(255,70,70,.9)';
    ctx.fillRect(sx-r*1.5,sy-r*1.7,r*3*hpPct,4);

    if(sandboxMode){
      ctx.font=`${Math.max(7,r*.4)}px 'Courier New'`;
      ctx.fillStyle='rgba(200,220,255,.65)';
      ctx.textAlign='center';
      const status=this._allyLink?'ALIADA':'PATRULHANDO';
      ctx.fillText(`🛰️ ${status} | ⚔${(this._atkBonus*100).toFixed(0)}% | ❤${Math.round(this.hp)}`,sx,sy+r*2.2+10*cam.zoom);
      ctx.textAlign='left';
    }
  }
}

// ── B3. FROTA MILITAR REPTILIANA ────────────────────────────────────
// Nave-mãe de guerra reptiliana: MUITO maior que qualquer outra frota
// ou nave comum, mesmo estilo visual da Nave Reptiliana comum (casco
// triangular cinza-aço, listra vermelha central, torre de comando),
// porém em escala colossal e com múltiplos canhões/lasers pesados.
// Só se alia a outras Frotas Reptilianas e Naves Reptilianas comuns —
// nunca a Alienígenas ou Marcianos. Ataca Naves Alienígenas e
// Marcianas comuns, mas prioriza fortemente as Frotas Militares
// (Alienígena e Marciana). Ataque alto e a maior defesa (HP) entre
// todas as frotas do jogo.
function _reptilianFleetActiveCount(){
  return objects.filter(o=>o instanceof ReptilianFleetEntity && !o.dead).length;
}
class ReptilianFleetEntity extends CelestialObject{
  constructor(wx,wy){
    super(wx,wy,'entityReptilianFleet');
    this.radius=46;this.mass=0; // MUITO maior que a Alienígena (22) e a Marciana (20)
    this.fixed=false;
    this._t=0;
    this.color='#dd2200';
    this.vx=rand(-.4,.4);this.vy=rand(-.4,.4);
    // Maior defesa entre todas as frotas
    this.hp=95000;this.maxHP=95000;
    this._hitFlashT=0;
    this._angle=rand(0,Math.PI*2);
    this._angleVel=0;
    this._huntTarget=null;
    this._huntKind=null; // 'reptFleetTarget'|'alienFleet'|'marcianFleet'|'alien'|'marcian'
    this._atkTimer=rand(.8,1.6);
    this._cannonStrikes=[]; // múltiplos canhões disparando em sequência
    this._chargeRing=0;
    this._strikeFlash=0;
    this._thrusterFlare=0;
    this._searchRadius=900;
    this._allyReptShips=[]; // Naves Reptilianas comuns escoltando
    this._escortTimer=0;
  }
  _findTarget(){
    // Prioridade máxima: Frotas Militares (Alienígena e Marciana).
    // Depois, Naves Alienígenas/Marcianas comuns.
    let bestFleet=null,bestFleetD=Infinity;
    objects.forEach(o=>{
      if(o.dead)return;
      if(o instanceof InvasionFleetEntity||o instanceof MarcianFleetEntity){
        const d=dist(o,this);
        if(d<=this._searchRadius&&d<bestFleetD){bestFleetD=d;bestFleet=o;}
      }
    });
    if(bestFleet)return {unit:bestFleet,kind:bestFleet instanceof InvasionFleetEntity?'alienFleet':'marcianFleet'};

    let best=null,bestD=Infinity,bestKind=null;
    objects.forEach(o=>{
      if(o===this||o.dead)return;
      if(o.type!==RACE_ALIEN&&o.type!==RACE_MARCIAN)return;
      if(o._enslaved)return;
      const d=dist(o,this);
      if(d>this._searchRadius)return;
      if(d<bestD){bestD=d;best=o;bestKind=o.type===RACE_ALIEN?'alien':'marcian';}
    });
    if(best)return {unit:best,kind:bestKind};
    return null;
  }
  takeDamage(dmg){
    // A maior defesa entre todas as frotas: mitiga fortemente o dano recebido
    const mitigated=dmg*0.55;
    this.hp=Math.max(0,this.hp-mitigated);
    this._hitFlashT=0.35;
    if(this.hp<=0){
      this.dead=true;
      showTooltip('💥 A Frota Militar Reptiliana foi destruída!');
    }
  }
  update(dt){
    this._t+=dt;
    this._thrusterFlare=Math.max(0,this._thrusterFlare-dt*2);
    if(this._hitFlashT>0)this._hitFlashT=Math.max(0,this._hitFlashT-dt);
    this._strikeFlash=Math.max(0,this._strikeFlash-dt*2);
    this._cannonStrikes=this._cannonStrikes.filter(s=>{s.t+=dt;return s.t<s.maxT;});

    // Escolta: Naves Reptilianas comuns próximas se juntam visualmente à frota
    this._escortTimer-=dt;
    if(this._escortTimer<=0){
      this._escortTimer=2;
      this._allyReptShips=objects.filter(o=>!o.dead&&o.type===RACE_REPTILIAN&&dist(this,o)<420);
    }

    if(!this._huntTarget||this._huntTarget.dead||
       (this._huntTarget.hp!==undefined&&this._huntTarget.hp<=0)||
       this._huntTarget._enslaved){
      const found=this._findTarget();
      this._huntTarget=found?found.unit:null;
      this._huntKind=found?found.kind:null;
    }

    this._chargeRing=this._huntTarget?Math.min(1,this._chargeRing+dt*.7):Math.max(0,this._chargeRing-dt*1.4);

    if(this._huntTarget){
      const d=dist(this,this._huntTarget)||0.001;
      const orbitRange=this._huntKind==='alienFleet'||this._huntKind==='marcianFleet'?420:280;
      const nx=(this._huntTarget.x-this.x)/d,ny=(this._huntTarget.y-this.y)/d;
      if(d>orbitRange){
        const spd=Math.min(3.2,d*.025+1);
        this.vx=this.vx*.9+nx*spd*.1;this.vy=this.vy*.9+ny*spd*.1;
        this.x+=this.vx*dt*60;this.y+=this.vy*dt*60;
        this._thrusterFlare=Math.min(1,this._thrusterFlare+dt*1.3);
      } else {
        const tx=-ny,ty=nx;
        const radialErr=d-orbitRange*.8;
        const orbitSpd=1.6;
        const vxTarget=tx*orbitSpd+nx*radialErr*.025;
        const vyTarget=ty*orbitSpd+ny*radialErr*.025;
        this.vx=this.vx*.92+vxTarget*.08;this.vy=this.vy*.92+vyTarget*.08;
        this.x+=this.vx*dt*60;this.y+=this.vy*dt*60;
        this._thrusterFlare=Math.min(1,this._thrusterFlare+dt*.6);
      }
      const targetAngle=Math.atan2(this._huntTarget.y-this.y,this._huntTarget.x-this.x)+Math.PI*.5;
      let diff=targetAngle-this._angle;
      while(diff>Math.PI)diff-=Math.PI*2;
      while(diff<-Math.PI)diff+=Math.PI*2;
      this._angleVel+=(diff*2.2-this._angleVel)*Math.min(1,dt*2);
      this._angle+=this._angleVel*dt;
    } else {
      // Patrulha lenta e imponente sem alvo — spin orgânico contínuo,
      // igual ao comportamento da Nave Reptiliana comum
      this._angleVel*=(1-dt*.18);
      if(Math.abs(this._angleVel)<.2) this._angleVel+=rand(.1,.35)*(Math.random()<.5?1:-1)*dt*4;
      this._angle+=this._angleVel*dt;
      this.vx+=rand(-.02,.02);this.vy+=rand(-.02,.02);
      const spd=Math.hypot(this.vx,this.vy);
      if(spd>1.2){this.vx*=1.2/spd;this.vy*=1.2/spd;}
      this.x+=this.vx*dt*60;this.y+=this.vy*dt*60;
    }

    // ── Ataque: alto dano, múltiplos canhões disparando em sequência ──
    this._atkTimer-=dt;
    if(this._huntTarget&&this._atkTimer<=0){
      const d=dist(this,this._huntTarget);
      if(d<620){
        const isFleet=this._huntKind==='alienFleet'||this._huntKind==='marcianFleet';
        // Dispara 3 canhões em sequência curta — dano alto
        for(let i=0;i<3;i++){
          this._cannonStrikes.push({t:-i*0.12,maxT:0.4,cannonIdx:i,target:this._huntTarget});
        }
        if(isFleet){
          const dmg=3200+Math.random()*1600; // dano alto contra Frotas Militares — alvo prioritário
          this._huntTarget.takeDamage(dmg);
          this._strikeFlash=1;
          showTooltip(`🔻 A Frota Militar Reptiliana atingiu em cheio a ${this._huntKind==='alienFleet'?'Frota Alienígena':'Frota Marciana'}!`);
        } else {
          this._huntTarget._enslaved=true;this._huntTarget._masterRep=this;this._huntTarget._warMode=false;
          this._huntTarget.color='#553300';
          this._strikeFlash=1;
          showTooltip(`🔻 A Frota Militar Reptiliana escravizou um ${this._huntKind==='alien'?'Alien':'Marciano'}!`);
        }
        this._atkTimer=2.6+Math.random()*1.1;
      }
    }
  }
  draw(){
    const sx=this.sx(),sy=this.sy(),r=this.sr();
    const T=this._t;

    // ── Anel de carga pré-ataque (maior, mais ameaçador) ──
    if(this._chargeRing>0){
      const cr=this._chargeRing;
      for(let i=0;i<3;i++){
        const ringR=r*(1.5+i*.45)*cr;
        ctx.beginPath();ctx.arc(sx,sy,ringR,0,Math.PI*2);
        ctx.strokeStyle=`rgba(220,20,0,${cr*(.3-i*.07)})`;
        ctx.lineWidth=Math.max(1,r*.045*(1-i*.2));ctx.stroke();
      }
    }

    // ══════════════════════════════════════════════
    //  NAVE-MÃE REPTILIANA — Casco em Hexagrama
    //  (baseado no rascunho): um triângulo apontando pra
    //  cima sobreposto a um triângulo invertido, formando
    //  uma estrela de 6 pontas. Nas 6 pontas de encontro
    //  saem os canhões. Nas laterais saem duas cabeças de
    //  Dragão que disparam raios pela boca. Embaixo, jatos
    //  de propulsão. Mesmo estilo cinza-aço + listra
    //  vermelha da Nave Reptiliana comum.
    // ══════════════════════════════════════════════

    const hullG=ctx.createLinearGradient(-r,-r,r,r);
    hullG.addColorStop(0,'rgba(190,193,200,1)');
    hullG.addColorStop(.3,'rgba(150,153,160,1)');
    hullG.addColorStop(.6,'rgba(110,113,120,1)');
    hullG.addColorStop(1,'rgba(60,62,68,1)');
    const strokeMain='rgba(200,202,210,.9)',strokeDark='rgba(50,52,58,.6)';

    // Vértices dos dois triângulos (aponta-cima / aponta-baixo) que formam o hexagrama
    const triUp=[[0,-r],[r*.866,r*.5],[-r*.866,r*.5]];
    const triDown=[[0,r],[r*.866,-r*.5],[-r*.866,-r*.5]];

    // ── Sombra profunda (em coords de tela) ──
    ctx.save();ctx.translate(sx,sy);
    const shadowG=ctx.createRadialGradient(r*.08,r*.5,0,r*.08,r*.5,r*2.2);
    shadowG.addColorStop(0,'rgba(0,0,0,.4)');shadowG.addColorStop(1,'transparent');
    ctx.beginPath();ctx.ellipse(r*.08,r*.55,r*1.9,r*.5,0,0,Math.PI*2);
    ctx.fillStyle=shadowG;ctx.fill();
    ctx.restore();
    ctx.save();ctx.translate(sx,sy);ctx.rotate(this._angle);

    // ── Triângulo invertido (desenhado primeiro, ligeiramente atrás) ──
    ctx.beginPath();ctx.moveTo(...triDown[0]);ctx.lineTo(...triDown[1]);ctx.lineTo(...triDown[2]);ctx.closePath();
    ctx.fillStyle=this._hitFlashT>0?`rgba(255,255,255,${.4+this._hitFlashT})`:hullG;ctx.fill();
    ctx.strokeStyle=strokeMain;ctx.lineWidth=Math.max(1.5,r*.05);ctx.stroke();
    ctx.strokeStyle=strokeDark;ctx.lineWidth=Math.max(.5,r*.02);ctx.stroke();

    // ── Triângulo para-cima (por cima, define o "nariz" da nave) ──
    ctx.beginPath();ctx.moveTo(...triUp[0]);ctx.lineTo(...triUp[1]);ctx.lineTo(...triUp[2]);ctx.closePath();
    ctx.fillStyle=this._hitFlashT>0?`rgba(255,255,255,${.5+this._hitFlashT})`:hullG;ctx.fill();
    ctx.strokeStyle=strokeMain;ctx.lineWidth=Math.max(1.5,r*.05);ctx.stroke();
    ctx.strokeStyle=strokeDark;ctx.lineWidth=Math.max(.5,r*.02);ctx.stroke();

    // ── Linhas internas do hexagrama (as diagonais que cruzam no meio, como no rascunho) ──
    ctx.beginPath();ctx.moveTo(...triUp[0]);ctx.lineTo(...triDown[1]);
    ctx.moveTo(...triUp[1]);ctx.lineTo(...triDown[0]);
    ctx.moveTo(...triUp[1]);ctx.lineTo(...triDown[2]);
    ctx.moveTo(...triUp[2]);ctx.lineTo(...triDown[0]);
    ctx.moveTo(...triUp[2]);ctx.lineTo(...triDown[1]);
    ctx.moveTo(...triUp[0]);ctx.lineTo(...triDown[2]);
    ctx.strokeStyle='rgba(90,93,100,.5)';ctx.lineWidth=Math.max(.5,r*.018);ctx.stroke();

    // ── Hexágono central (interseção da estrela) — núcleo estrutural ──
    const hexR=r*.42;
    ctx.beginPath();
    for(let h=0;h<6;h++){
      const ha=h*(Math.PI/3)+Math.PI/6;
      const hx=Math.cos(ha)*hexR,hy=Math.sin(ha)*hexR;
      h===0?ctx.moveTo(hx,hy):ctx.lineTo(hx,hy);
    }
    ctx.closePath();
    ctx.fillStyle='rgba(80,83,90,.9)';ctx.fill();
    ctx.strokeStyle=strokeMain;ctx.lineWidth=Math.max(.8,r*.03);ctx.stroke();

    // ── Listra vermelha central vertical (identidade reptiliana) ──
    ctx.save();
    ctx.beginPath();ctx.moveTo(...triUp[0]);ctx.lineTo(...triUp[1]);ctx.lineTo(...triUp[2]);ctx.closePath();
    ctx.moveTo(...triDown[0]);ctx.lineTo(...triDown[1]);ctx.lineTo(...triDown[2]);ctx.closePath();
    ctx.clip();
    const stripeW=Math.max(4,r*.13);
    const stripeG=ctx.createLinearGradient(-stripeW,0,stripeW,0);
    stripeG.addColorStop(0,'rgba(180,0,0,0)');
    stripeG.addColorStop(.2,'rgba(220,10,10,.85)');
    stripeG.addColorStop(.5,'rgba(255,30,30,1)');
    stripeG.addColorStop(.8,'rgba(220,10,10,.85)');
    stripeG.addColorStop(1,'rgba(180,0,0,0)');
    ctx.fillStyle=stripeG;ctx.fillRect(-stripeW,-r,stripeW*2,r*2);
    ctx.restore();

    // ── CANHÕES nas 6 PONTAS da estrela (onde os triângulos se cruzam/terminam) ──
    const starPoints=[triUp[0],triUp[1],triUp[2],triDown[0],triDown[1],triDown[2]];
    starPoints.forEach((pt,pi)=>{
      const [px,py]=pt;
      const outAngle=Math.atan2(py,px); // direção radial pra fora, onde o canhão aponta
      ctx.beginPath();ctx.arc(px,py,Math.max(2.5,r*.09),0,Math.PI*2);
      ctx.fillStyle='rgba(75,78,85,1)';ctx.fill();
      ctx.strokeStyle='rgba(140,143,150,.8)';ctx.lineWidth=Math.max(.6,r*.02);ctx.stroke();
      ctx.save();ctx.translate(px,py);ctx.rotate(outAngle);
      const cLen=Math.max(4,r*.24),cW=Math.max(1.8,r*.06);
      ctx.fillStyle='rgba(50,52,58,1)';ctx.fillRect(0,-cW*.5,cLen,cW);
      ctx.strokeStyle='rgba(120,123,130,.7)';ctx.lineWidth=Math.max(.3,r*.014);ctx.strokeRect(0,-cW*.5,cLen,cW);
      ctx.beginPath();ctx.ellipse(cLen,0,cW*.3,cW*.65,0,0,Math.PI*2);
      ctx.fillStyle='rgba(20,20,22,1)';ctx.fill();
      const cPulse=.3+.35*Math.abs(Math.sin(T*3+pi*.6));
      ctx.beginPath();ctx.arc(cLen-cW*.18,0,Math.max(.6,cW*.26),0,Math.PI*2);
      ctx.fillStyle=`rgba(255,50,50,${cPulse})`;ctx.fill();
      ctx.restore();
    });

    // ── CABEÇAS DE DRAGÃO — nascem coladas nas pontas laterais do
    // hexagrama (esquerda/direita), como no rascunho, sem espaço entre
    // o pescoço e o casco. Disparam raios gigantes pela boca. ──
    const sideVX=r*.866,sideVY=r*.5; // ponta lateral do triângulo pra baixo (mesmo ponto onde termina o casco)
    [-1,1].forEach(side=>{
      const headX=side*sideVX,headY=sideVY*.25; // encosta bem próximo à ponta lateral do casco
      ctx.save();ctx.translate(headX,headY);ctx.scale(side,1);
      // Pescoço grosso soldado diretamente ao casco (sem lacuna)
      ctx.beginPath();
      ctx.moveTo(-r*.05,-r*.14);ctx.lineTo(r*.22,-r*.11);ctx.lineTo(r*.22,r*.13);ctx.lineTo(-r*.05,r*.16);
      ctx.closePath();
      const neckG=ctx.createLinearGradient(-r*.05,0,r*.22,0);
      neckG.addColorStop(0,'rgba(110,113,120,1)');neckG.addColorStop(1,'rgba(160,163,170,1)');
      ctx.fillStyle=neckG;ctx.fill();
      ctx.strokeStyle='rgba(140,143,150,.7)';ctx.lineWidth=Math.max(1,r*.03);ctx.stroke();
      // Crânio alongado (forma triangular pontiaguda, como a cabeça do rascunho) — encostado no pescoço
      const skullG=ctx.createLinearGradient(r*.15,-r*.2,r*.7,r*.15);
      skullG.addColorStop(0,'rgba(185,188,195,1)');
      skullG.addColorStop(.5,'rgba(140,143,150,1)');
      skullG.addColorStop(1,'rgba(80,83,90,1)');
      ctx.beginPath();
      ctx.moveTo(r*.15,-r*.16);
      ctx.lineTo(r*.55,-r*.1);
      ctx.lineTo(r*.72,0);
      ctx.lineTo(r*.55,r*.09);
      ctx.lineTo(r*.15,r*.14);
      ctx.closePath();
      ctx.fillStyle=skullG;ctx.fill();
      ctx.strokeStyle='rgba(200,202,210,.85)';ctx.lineWidth=Math.max(.8,r*.03);ctx.stroke();
      // Mandíbula inferior (boca aberta)
      const jawOpen=this._laser&&this._laser.t<this._laser.maxT?1:.35+.15*Math.sin(T*3);
      ctx.beginPath();
      ctx.moveTo(r*.35,r*.06);
      ctx.lineTo(r*.68,r*.05+jawOpen*r*.12);
      ctx.lineTo(r*.54,r*.14+jawOpen*r*.1);
      ctx.lineTo(r*.3,r*.13);
      ctx.closePath();
      ctx.fillStyle='rgba(70,73,80,1)';ctx.fill();
      ctx.strokeStyle='rgba(150,153,160,.7)';ctx.lineWidth=Math.max(.5,r*.02);ctx.stroke();
      // Dentes
      for(let td=0;td<3;td++){
        const tdx=r*.42+td*r*.09;
        ctx.beginPath();ctx.moveTo(tdx,r*.07);ctx.lineTo(tdx+r*.02,r*.07+jawOpen*r*.08);ctx.lineTo(tdx+r*.04,r*.07);
        ctx.closePath();ctx.fillStyle='rgba(230,230,225,.9)';ctx.fill();
      }
      // Olho (viseira vermelha, mesma identidade)
      const eyeG=ctx.createRadialGradient(r*.42,-r*.04,0,r*.42,-r*.04,r*.07);
      eyeG.addColorStop(0,'rgba(255,80,60,.95)');eyeG.addColorStop(1,'rgba(180,10,10,.6)');
      ctx.beginPath();ctx.ellipse(r*.42,-r*.04,Math.max(1.2,r*.06),Math.max(.8,r*.04),0,0,Math.PI*2);
      ctx.fillStyle=eyeG;ctx.fill();
      // Chifres/crista atrás da cabeça
      for(let hn=0;hn<2;hn++){
        ctx.beginPath();ctx.moveTo(r*.06+hn*r*.12,-r*.14);ctx.lineTo(-r*.06+hn*r*.14,-r*.32);
        ctx.strokeStyle='rgba(160,163,170,.8)';ctx.lineWidth=Math.max(1,r*.03);ctx.stroke();
      }
      // Brilho da garganta antes/durante o disparo
      const throatGlow=jawOpen;
      const tg=ctx.createRadialGradient(r*.54,r*.09,0,r*.54,r*.09,r*.15*throatGlow+.01);
      tg.addColorStop(0,`rgba(255,200,80,${throatGlow*.9})`);tg.addColorStop(1,'transparent');
      ctx.beginPath();ctx.arc(r*.54,r*.09,r*.15*throatGlow,0,Math.PI*2);ctx.fillStyle=tg;ctx.fill();
      ctx.restore();
    });

    // ── JATOS DE PROPULSÃO — soldados na base do casco (ponta inferior
    // do triângulo invertido), sem lacuna entre o jato e o casco ──
    const jetTopY=r*.75; // encosta na região inferior do triângulo invertido
    const jetPositions=[-r*.42,0,r*.42];
    jetPositions.forEach((jx,ji)=>{
      const jw=Math.max(3,r*.14),jh=Math.max(5,r*.2);
      // Colar soldado ao casco (trapézio conectando o casco ao jato)
      ctx.beginPath();
      ctx.moveTo(jx-jw*.6,jetTopY);ctx.lineTo(jx+jw*.6,jetTopY);
      ctx.lineTo(jx+jw,jetTopY+jh*.3);ctx.lineTo(jx-jw,jetTopY+jh*.3);
      ctx.closePath();
      ctx.fillStyle='rgba(95,98,105,1)';ctx.fill();
      ctx.strokeStyle='rgba(150,153,160,.6)';ctx.lineWidth=Math.max(.4,r*.016);ctx.stroke();
      const jy=jetTopY+jh*.3;
      const jG=ctx.createLinearGradient(jx-jw,jy,jx+jw,jy);
      jG.addColorStop(0,'rgba(40,40,45,1)');jG.addColorStop(.5,'rgba(85,88,95,1)');jG.addColorStop(1,'rgba(40,40,45,1)');
      ctx.fillStyle=jG;ctx.fillRect(jx-jw,jy,jw*2,jh);
      ctx.strokeStyle='rgba(130,130,140,.8)';ctx.lineWidth=Math.max(.5,r*.02);ctx.strokeRect(jx-jw,jy,jw*2,jh);
      const flamePulse=.6+.4*Math.abs(Math.sin(T*6+ji*1.1));
      const flameLen=r*(.4+.22*flamePulse);
      const flameG=ctx.createLinearGradient(jx,jy+jh,jx,jy+jh+flameLen);
      flameG.addColorStop(0,'rgba(255,220,180,.95)');
      flameG.addColorStop(.25,'rgba(255,120,40,.8)');
      flameG.addColorStop(.65,'rgba(180,50,200,.5)');
      flameG.addColorStop(1,'rgba(80,10,120,0)');
      ctx.beginPath();ctx.ellipse(jx,jy+jh+flameLen*.4,jw*.42*flamePulse,flameLen*.6,0,0,Math.PI*2);
      ctx.fillStyle=flameG;ctx.fill();
    });

    // ── Sensor/olho central no vértice de cima (mesma identidade da nave comum) ──
    ctx.beginPath();ctx.arc(0,-r*.86,Math.max(1.2,r*.05),0,Math.PI*2);
    ctx.fillStyle='rgba(255,40,40,.85)';ctx.fill();
    const sensPulse=.4+.4*Math.abs(Math.sin(T*2.5));
    ctx.beginPath();ctx.arc(0,-r*.86,Math.max(1.8,r*.08),0,Math.PI*2);
    ctx.strokeStyle=`rgba(255,40,40,${sensPulse*.5})`;ctx.lineWidth=Math.max(.5,r*.02);ctx.stroke();

    // ── Núcleo energético no centro exato da estrela (losango vermelho pulsante) ──
    const nPulse=.7+.3*Math.sin(T*5);
    const ncol=this._strikeFlash>0?'255,255,100':'220,20,20';
    ctx.save();ctx.rotate(Math.PI*.25+T*.2);
    ctx.beginPath();ctx.moveTo(0,-r*.14);ctx.lineTo(r*.09,0);ctx.lineTo(0,r*.14);ctx.lineTo(-r*.09,0);ctx.closePath();
    const nucG=ctx.createRadialGradient(0,0,0,0,0,r*.14);
    nucG.addColorStop(0,`rgba(${ncol},${nPulse})`);nucG.addColorStop(.6,`rgba(${ncol},.4)`);nucG.addColorStop(1,'rgba(0,0,0,0)');
    ctx.fillStyle=nucG;ctx.fill();
    ctx.restore();

    if(this._strikeFlash>0){
      const fg=ctx.createRadialGradient(0,0,0,0,0,r*4*this._strikeFlash);
      fg.addColorStop(0,`rgba(255,60,0,${this._strikeFlash*.4})`);fg.addColorStop(1,'transparent');
      ctx.beginPath();ctx.arc(0,0,r*4*this._strikeFlash,0,Math.PI*2);ctx.fillStyle=fg;ctx.fill();
    }

    ctx.restore();

    // ── RAIOS GIGANTES das cabeças de Dragão contra o alvo travado ──
    if(this._laser&&this._laser.target&&!this._laser.target.dead){
      const u=this._laser.target;
      const alpha=1-this._laser.t/this._laser.maxT;
      const tx=u.sx?u.sx():sx,ty=u.sy?u.sy():sy;
      [-1,1].forEach(side=>{
        // Origem da cabeça (colada na ponta lateral do casco) + deslocamento até a boca
        const headLocalX=side*r*.866,headLocalY=r*.5*.25;
        const mouthLocalX=headLocalX+side*r*.54,mouthLocalY=headLocalY+r*.09;
        const mouthX=sx+mouthLocalX*Math.cos(this._angle)-mouthLocalY*Math.sin(this._angle),
              mouthY=sy+mouthLocalX*Math.sin(this._angle)+mouthLocalY*Math.cos(this._angle);
        const bg=ctx.createLinearGradient(mouthX,mouthY,tx,ty);
        bg.addColorStop(0,`rgba(255,220,120,${alpha*.95})`);
        bg.addColorStop(.4,`rgba(255,80,30,${alpha*.85})`);
        bg.addColorStop(1,'rgba(180,10,10,0)');
        ctx.beginPath();ctx.moveTo(mouthX,mouthY);ctx.lineTo(tx,ty);
        ctx.strokeStyle=bg;ctx.lineWidth=Math.max(2.5,r*.16);ctx.stroke();
        ctx.beginPath();ctx.moveTo(mouthX,mouthY);ctx.lineTo(tx,ty);
        ctx.strokeStyle=`rgba(255,255,220,${alpha*.7})`;ctx.lineWidth=Math.max(1,r*.06);ctx.stroke();
      });
    }

    const hpPct=this.hp/this.maxHP;
    ctx.fillStyle='rgba(0,0,0,.5)';ctx.fillRect(sx-r*1.5,sy-r*1.8,r*3,5);
    ctx.fillStyle=hpPct>.5?'rgba(255,80,60,.9)':hpPct>.2?'rgba(255,200,60,.9)':'rgba(255,255,255,.9)';
    ctx.fillRect(sx-r*1.5,sy-r*1.8,r*3*hpPct,5);

    if(sandboxMode){
      ctx.font=`${Math.max(8,r*.32)}px 'Courier New'`;
      ctx.fillStyle='rgba(255,90,70,.85)';
      ctx.textAlign='center';
      const status=this._huntTarget?(this._huntKind==='alienFleet'||this._huntKind==='marcianFleet'?'CAÇANDO FROTA':'CAÇANDO'):'PATRULHANDO';
      ctx.fillText(`🔻 ${status} | ❤${Math.round(this.hp)}`,sx,sy+r*2.2+10*cam.zoom);
      ctx.textAlign='left';
    }
  }
}

// ── C. PARASITA CÓSMICO ────────────────────────────────────────────
// Bolha de matéria orgânica que infecta cometas e meteoros. Quando
// o portador infectado colide com um planeta, a infecção se espalha:
// o planeta vira um "Planeta Vivo" que periodicamente lança fragmentos
// de si mesmo (novos meteoros) em direção a outros astros.
class CosmicParasiteEntity extends CelestialObject{
  constructor(wx,wy){
    super(wx,wy,'entityCosmicParasite');
    this.radius=9;this.mass=0;
    this.fixed=false;
    this._t=0;
    this._target=null;     // cometa ou meteoro alvo
    this._infected=false;  // está carregado dentro de um host
    this._hostId=null;     // id do host infectado
    this._infectedPlanets=[]; // IDs de planetas transformados
    this._pulseBubbles=Array.from({length:6},(_,i)=>({
      a:i*(Math.PI/3)+rand(-.2,.2),
      r:rand(.7,1.1),phase:rand(0,Math.PI*2)
    }));
    this._spreadFlash=0;
    this.color='#88ff44';
    this.vx=rand(-2,2);this.vy=rand(-2,2);
  }
  _findHost(){
    let best=null,bestD=Infinity;
    objects.forEach(o=>{
      if(o===this||o.dead||!['meteor','comet'].includes(o.type))return;
      if(o._parasiteInfected)return;
      const d=dist(o,this);
      if(d<bestD){bestD=d;best=o;}
    });
    return best;
  }
  update(dt){
    this._t+=dt;
    if(this._spreadFlash>0)this._spreadFlash=Math.max(0,this._spreadFlash-dt*1.5);
    this._pulseBubbles.forEach(b=>{b.a+=dt*.3;});
    // Se está infectado dentro de um host
    if(this._infected&&this._hostId!==null){
      const host=objects.find(o=>o.id===this._hostId&&!o.dead);
      if(!host){
        // Host morreu — volta a vagar
        this._infected=false;this._hostId=null;
        this._target=null;
        return;
      }
      // Segue o host
      this.x=host.x;this.y=host.y;
      // Verifica colisão do host com planetas
      const planetTypes=['planet','gasgiant','icegiant','superearth','minineptune',
        'dwarfplanet','lavaplt','oceanplt','desertplt','carbonplt','ironplt','exBlanet'];
      objects.forEach(p=>{
        if(p===host||p.dead||!planetTypes.includes(p.type))return;
        if(this._infectedPlanets.includes(p.id))return;
        const cd=dist(host,p);
        if(cd<(host.radius||3)+(p.radius||8)){
          // Infecção!
          this._infectedPlanets.push(p.id);
          p._parasiteInfected=true;
          p._parasiteTimer=0;
          p._parasitePulseTimer=rand(4,7);
          p._originalColor=p.color;
          p.color=`hsl(${rand(80,130)},100%,${rand(35,55)}%)`;
          this._spreadFlash=1;
          host._parasiteInfected=true; // host ejetou a carga
          host.dead=true;              // o host some na colisão
          this._infected=false;this._hostId=null;
          this._target=null;
          showTooltip(`🦠 Parasita Cósmico infectou ${p.name}! Planeta Vivo gerado.`);
        }
      });
      return;
    }
    // Procura host (meteoro/cometa)
    if(!this._target||this._target.dead||this._target._parasiteInfected){
      this._target=this._findHost();
    }
    if(!this._target){
      // Vaga lentamente
      this.vx+=rand(-.04,.04);this.vy+=rand(-.04,.04);
      const spd=Math.hypot(this.vx,this.vy);
      if(spd>2){this.vx*=2/spd;this.vy*=2/spd;}
      this.x+=this.vx*dt*60;this.y+=this.vy*dt*60;
      return;
    }
    // Persegue o host
    const d=dist(this,this._target);
    if(d>this._target.radius*1.5+this.radius){
      const nx=(this._target.x-this.x)/d,ny=(this._target.y-this.y)/d;
      const spd=Math.min(5,d*.06+1.5);
      this.vx=this.vx*.9+nx*spd*.1;this.vy=this.vy*.9+ny*spd*.1;
      this.x+=this.vx*dt*60;this.y+=this.vy*dt*60;
    } else {
      // Infecta o host
      this._target._parasiteInfected=true;
      this._target._parasiteGlow=`rgba(${rand(80,150)},${rand(180,255)},${rand(40,80)},.55)`;
      this._hostId=this._target.id;
      this._infected=true;
      this._target=null;
      showTooltip('🦠 Parasita infectou um portador! Aguardando colisão com planeta...');
    }
    // Planetas vivos: lançam fragmentos periodicamente
    objects.forEach(p=>{
      if(!p._parasiteInfected||!p._parasitePulseTimer||p.dead)return;
      p._parasiteTimer=(p._parasiteTimer||0)+dt;
      p._parasitePulseTimer-=dt;
      if(p._parasitePulseTimer<=0){
        p._parasitePulseTimer=rand(4,7);
        // Lança um meteoro em direção ao astro mais próximo
        const nearObj=objects.reduce((best,o)=>{
          if(o===p||o.dead||o._parasiteInfected||TECH_TYPES.includes(o.type))return best;
          const dd=dist(o,p);
          return(!best||dd<dist(best,p))?o:best;
        },null);
        const ang=nearObj?Math.atan2(nearObj.y-p.y,nearObj.x-p.x):rand(0,Math.PI*2);
        const frag=new Meteor(p.x+Math.cos(ang)*p.radius*1.2,p.y+Math.sin(ang)*p.radius*1.2);
        frag.vx=Math.cos(ang)*rand(3,6);frag.vy=Math.sin(ang)*rand(3,6);
        frag.color=`hsl(${rand(90,140)},90%,55%)`;
        frag._parasiteInfected=true;
        pendingObjects.push(frag);
        // Planeta perde massa ao lançar fragmento
        p.radius=Math.max(2,(p.radius||8)-.4);
        p.mass=Math.max(0,(p.mass||20)-2);
        for(let i=0;i<8;i++)particles.push({
          x:p.x+rand(-p.radius,p.radius),y:p.y+rand(-p.radius,p.radius),
          vx:Math.cos(ang)*rand(2,5)+rand(-1,1),vy:Math.sin(ang)*rand(2,5)+rand(-1,1),
          r:rand(1,2.5),alpha:.85,color:'#aaff44'
        });
      }
    });
  }
  draw(){
    const sx=this.sx(),sy=this.sy(),r=this.sr();
    const T=this._t;
    if(this._infected){
      // Pequena bolha pulsante sobre o host
      const pulse=.7+.3*Math.sin(T*5);
      ctx.beginPath();ctx.arc(sx,sy,r*pulse,0,Math.PI*2);
      ctx.fillStyle=`rgba(150,255,80,${.3+.15*pulse})`;ctx.fill();
      ctx.strokeStyle=`rgba(180,255,100,.5)`;ctx.lineWidth=1.5;ctx.stroke();
      return;
    }
    // Flash de espalhamento
    if(this._spreadFlash>0){
      const sf=r*5;
      const sg=ctx.createRadialGradient(sx,sy,0,sx,sy,sf);
      sg.addColorStop(0,`rgba(120,255,60,${this._spreadFlash*.4})`);
      sg.addColorStop(1,'transparent');
      ctx.beginPath();ctx.arc(sx,sy,sf,0,Math.PI*2);ctx.fillStyle=sg;ctx.fill();
    }
    // Bolhas satélite
    this._pulseBubbles.forEach(b=>{
      const pulse=1+.18*Math.sin(T*3+b.phase);
      const bx=sx+Math.cos(b.a)*r*b.r,by=sy+Math.sin(b.a)*r*b.r;
      ctx.beginPath();ctx.arc(bx,by,r*.28*pulse,0,Math.PI*2);
      ctx.fillStyle=`rgba(120,255,60,${.35+.2*Math.sin(T*4+b.phase)})`;ctx.fill();
      // Filamentos entre bolha e centro
      ctx.beginPath();ctx.moveTo(sx,sy);ctx.lineTo(bx,by);
      ctx.strokeStyle=`rgba(100,220,50,.2)`;ctx.lineWidth=1;ctx.stroke();
    });
    // Corpo central — bolha pulsante orgânica
    const pulse=1+.12*Math.sin(T*3.5);
    const cg=ctx.createRadialGradient(sx,sy,0,sx,sy,r*pulse);
    cg.addColorStop(0,'rgba(180,255,80,.95)');
    cg.addColorStop(.5,'rgba(100,220,40,.7)');
    cg.addColorStop(1,'rgba(50,160,20,.5)');
    ctx.beginPath();ctx.arc(sx,sy,r*pulse,0,Math.PI*2);ctx.fillStyle=cg;ctx.fill();
    // "Célula" interna
    ctx.beginPath();ctx.arc(sx,sy,r*.4,0,Math.PI*2);
    ctx.fillStyle=`rgba(220,255,100,${.6+.2*Math.sin(T*6)})`;ctx.fill();
    if(sandboxMode){
      ctx.font=`${Math.max(7,r*.55)}px 'Courier New'`;
      ctx.fillStyle='rgba(140,255,80,.55)';
      ctx.textAlign='center';
      ctx.fillText(`🦠 ${this._infected?'INFECTANDO':'CAÇANDO'} | 🪐×${this._infectedPlanets.length}`,sx,sy+r*1.6+10*cam.zoom);
      ctx.textAlign='left';
    }
  }
}

// ── D. SERPENTE DO VÁCUO ───────────────────────────────────────────
// Criatura colossal em forma de serpente que distorce as órbitas
// com sua massa absurda conforme serpenteia pelo mapa. Planetas
// e luas saem de suas órbitas originais ao ser arrastados pela
// gravidade bizarra do corpo serpentiforme.
class VoidSerpentEntity extends CelestialObject{
  constructor(wx,wy){
    super(wx,wy,'entityVoidSerpent');
    this.radius=20;this.mass=800;
    this.fixed=false;
    this._t=0;
    // Corpo: série de segmentos
    const N=14;
    this._segments=Array.from({length:N},(_,i)=>({
      x:wx-i*22,y:wy,vx:0,vy:0
    }));
    this._headAngle=0;
    this._turnTimer=rand(4,8);
    this._turnTarget=rand(0,Math.PI*2);
    this._speed=1.8;
    this._baseSpeed=1.8;
    this._chaosCount=0; // planetas/luas que saíram de órbita
    this._devourCount=0; // pequenos astros engolidos
    this._roarTimer=rand(6,12);
    this.color='#6600ff';
    this.vx=Math.cos(rand(0,Math.PI*2))*this._speed;
    this.vy=Math.sin(rand(0,Math.PI*2))*this._speed;
    // ── Novas mecânicas ──
    this._devourCD=rand(1.5,3);      // cooldown de detecção de presas
    this._devourFlash=0;             // flash visual ao engolir
    this._vacuumTimer=rand(9,14);    // buraco de vácuo periódico na cauda
    this._vacuumActive=0;            // duração ativa do vácuo
    this._vacuumPos=null;
    this._furyTimer=0;               // duração da fase de fúria
    this._furyThreshold=5;           // engolir 5 astros ativa a fúria
    this._segGrowQueue=0;             // segmentos pendentes a adicionar (cresce ao engolir)
    this._maxSegments=34;
    this._eyeGlow=0;
  }
  get _inFury(){return this._furyTimer>0;}
  update(dt){
    this._t+=dt;
    this._devourFlash=Math.max(0,this._devourFlash-dt*2);
    this._eyeGlow=Math.max(0,this._eyeGlow-dt*1.5);

    // ── FASE DE FÚRIA: acelera, gira mais rápido e distorce com força dobrada
    if(this._furyTimer>0){
      this._furyTimer-=dt;
      this._speed=this._baseSpeed*2.1;
    } else {
      this._speed=this._baseSpeed;
    }

    // Muda de direção periodicamente
    this._turnTimer-=dt;
    if(this._turnTimer<=0){
      this._turnTimer=this._inFury?rand(1.5,3):rand(4,8);
      this._turnTarget=rand(0,Math.PI*2);
    }
    // Gira suavemente em direção ao alvo (mais ágil em fúria)
    let da=this._turnTarget-this._headAngle;
    while(da>Math.PI)da-=Math.PI*2;while(da<-Math.PI)da+=Math.PI*2;
    this._headAngle+=da*(this._inFury?.04:.015);
    this.vx=Math.cos(this._headAngle)*this._speed;
    this.vy=Math.sin(this._headAngle)*this._speed;
    // Move a cabeça
    this._segments[0].x+=this.vx*dt*60;
    this._segments[0].y+=this.vy*dt*60;
    this.x=this._segments[0].x;this.y=this._segments[0].y;
    // Cada segmento segue o anterior (snake physics)
    for(let i=1;i<this._segments.length;i++){
      const a=this._segments[i-1],b=this._segments[i];
      const d=Math.hypot(a.x-b.x,a.y-b.y);
      const target=22;
      if(d>target){
        const nx=(a.x-b.x)/d,ny=(a.y-b.y)/d;
        const excess=d-target;
        b.x+=nx*excess*.35;b.y+=ny*excess*.35;
      }
    }
    // ── Cresce suavemente: adiciona segmentos na cauda quando há fila pendente
    if(this._segGrowQueue>0&&this._segments.length<this._maxSegments){
      this._segGrowQueue--;
      const tail=this._segments[this._segments.length-1];
      this._segments.push({x:tail.x,y:tail.y,vx:0,vy:0});
    }

    // ── DISTORÇÃO GRAVITACIONAL: cada segmento distorce órbitas ao redor
    const segR=this.radius*.75;
    const distortRange=segR*5;
    const furyMult=this._inFury?2.2:1;
    this._segments.forEach((seg,si)=>{
      const segMass=this.mass*(1-si*.03); // cauda tem menos massa
      objects.forEach(o=>{
        if(o===this||o.dead||o.fixed||TECH_TYPES.includes(o.type))return;
        const d=Math.hypot(o.x-seg.x,o.y-seg.y);
        if(d<1||d>distortRange)return;
        // Força gravitacional bizarra: oscila entre atração e repulsão ao longo do corpo
        const phase=si*(Math.PI*.4);
        const dir=Math.sin(this._t*1.5+phase); // alterna sinal
        const nx=(seg.x-o.x)/d,ny=(seg.y-o.y)/d;
        const f=segMass*0.0004*(1-d/distortRange)*dir*furyMult;
        o.vx=(o.vx||0)+nx*f*dt*60;
        o.vy=(o.vy||0)+ny*f*dt*60;
        // Quebra a órbita parental — acumula "estresse orbital" em vez de
        // depender de um pico instantâneo, então funciona de forma confiável
        if((o.type==='planet'||o.type==='moon')&&o.parent&&!o._serpentBroke){
          o._serpentStress=(o._serpentStress||0)+Math.abs(f)*dt*8;
          if(o._serpentStress>0.35){
            o.parent=null;
            o._serpentBroke=true;
            this._chaosCount++;
            showTooltip(`🐍 Serpente do Vácuo quebrou a órbita de ${o.name}!`);
          }
        }
      });
    });

    // ── DEVORAÇÃO: a cabeça engole meteoros, cometas e luas pequenas que
    // cruzarem seu caminho, crescendo em tamanho e ganhando fúria ──
    this._devourCD-=dt;
    if(this._devourCD<=0){
      this._devourCD=0.4;
      const head=this._segments[0];
      const preyTypes=['meteor','comet','moon','dwarfplanet'];
      let prey=null,preyD=Infinity;
      objects.forEach(o=>{
        if(o===this||o.dead||!preyTypes.includes(o.type))return;
        const d=Math.hypot(o.x-head.x,o.y-head.y);
        if(d<this.radius*1.6&&d<preyD){preyD=d;prey=o;}
      });
      if(prey){
        prey.dead=true;
        this._devourCount++;
        this._devourFlash=1;
        this._eyeGlow=1;
        this._segGrowQueue+=2; // cresce 2 segmentos por presa engolida
        this.mass+=40;
        showTooltip(`🐍 A Serpente do Vácuo engoliu ${prey.name||'um astro'}! (${this._devourCount})`);
        if(this._devourCount>0&&this._devourCount%this._furyThreshold===0&&this._furyTimer<=0){
          this._furyTimer=6;
          showTooltip('🐍💢 A Serpente entrou em FÚRIA DO VÁCUO! Mais rápida e destrutiva!');
        }
      }
    }

    // ── BURACO DE VÁCUO NA CAUDA: periodicamente, a ponta da cauda abre um
    // vórtice que puxa astros próximos por alguns segundos — nova mecânica
    // de "armadilha gravitacional" que o jogador pode observar e reagir ──
    if(this._vacuumActive>0){
      this._vacuumActive-=dt;
      const tail=this._segments[this._segments.length-1];
      this._vacuumPos={x:tail.x,y:tail.y};
      objects.forEach(o=>{
        if(o===this||o.dead||o.fixed||TECH_TYPES.includes(o.type))return;
        const d=Math.hypot(o.x-tail.x,o.y-tail.y);
        if(d<1||d>650)return;
        const nx=(tail.x-o.x)/d,ny=(tail.y-o.y)/d;
        const pull=(1-d/650)*9;
        o.vx=(o.vx||0)+nx*pull*dt*60;
        o.vy=(o.vy||0)+ny*pull*dt*60;
      });
      if(this._vacuumActive<=0){
        this._vacuumPos=null;
      }
    } else {
      this._vacuumTimer-=dt;
      if(this._vacuumTimer<=0){
        this._vacuumTimer=rand(8,13);
        this._vacuumActive=5.5;
        showTooltip('🐍🌀 A Serpente abriu um BURACO NEGRO DE VÁCUO na cauda!');
      }
    }

    // Rugido periódico: pulso de força caótica em área grande
    this._roarTimer-=dt;
    if(this._roarTimer<=0){
      this._roarTimer=this._inFury?rand(3,5):rand(6,12);
      showTooltip('🐍 A Serpente do Vácuo ruge! Caos gravitacional se espalhando...');
      objects.forEach(o=>{
        if(o===this||o.dead||o.fixed||TECH_TYPES.includes(o.type))return;
        const d=dist(o,this);if(d>300)return;
        const ang=rand(0,Math.PI*2);
        const force=rand(5,15)*(this._inFury?1.6:1);
        o.vx=(o.vx||0)+Math.cos(ang)*force;
        o.vy=(o.vy||0)+Math.sin(ang)*force;
        if((o.type==='planet'||o.type==='moon')&&o.parent){
          o.parent=null;o._serpentBroke=true;this._chaosCount++;
        }
      });
    }
  }
  draw(){
    const T=this._t;
    const N=this._segments.length;

    // ── Buraco Negro de Vácuo na cauda (nova mecânica visível) ──
    if(this._vacuumActive>0&&this._vacuumPos){
      const vs=worldToScreen(this._vacuumPos.x,this._vacuumPos.y);
      const growIn=Math.min(1,(5.5-this._vacuumActive)*2); // aparece rápido, encolhe no final
      const shrinkOut=Math.min(1,this._vacuumActive*1.5);
      const growth=Math.min(growIn,shrinkOut);
      const vr=Math.max(14,this.radius*2.2)*cam.zoom*growth;
      // Anéis de acreção girando
      for(let ring=0;ring<4;ring++){
        const rp=(T*1.8+ring*.25)%1;
        const ringR=vr*(1.1+rp*2.2);
        ctx.beginPath();ctx.arc(vs.x,vs.y,ringR,0,Math.PI*2);
        ctx.strokeStyle=`rgba(160,60,255,${(1-rp)*.55*growth})`;
        ctx.lineWidth=Math.max(1.5,vr*.12*(1-rp));ctx.stroke();
      }
      // Disco de acreção brilhante
      const diskG=ctx.createRadialGradient(vs.x,vs.y,vr*.3,vs.x,vs.y,vr*2.4);
      diskG.addColorStop(0,'rgba(0,0,0,0)');
      diskG.addColorStop(.45,`rgba(180,80,255,${.5*growth})`);
      diskG.addColorStop(.7,`rgba(120,20,220,${.35*growth})`);
      diskG.addColorStop(1,'transparent');
      ctx.beginPath();ctx.arc(vs.x,vs.y,vr*2.4,0,Math.PI*2);ctx.fillStyle=diskG;ctx.fill();
      // Núcleo escuro (horizonte de eventos)
      const coreG=ctx.createRadialGradient(vs.x,vs.y,0,vs.x,vs.y,vr);
      coreG.addColorStop(0,'rgba(5,0,10,1)');
      coreG.addColorStop(.7,'rgba(25,0,45,.95)');
      coreG.addColorStop(1,'rgba(90,0,160,.6)');
      ctx.beginPath();ctx.arc(vs.x,vs.y,vr,0,Math.PI*2);ctx.fillStyle=coreG;ctx.fill();
      ctx.beginPath();ctx.arc(vs.x,vs.y,vr,0,Math.PI*2);
      ctx.strokeStyle=`rgba(200,120,255,${.7*growth})`;ctx.lineWidth=Math.max(1,vr*.06);ctx.stroke();
    }

    // Brilho do rastro gravitacional (mais intenso em fúria)
    const furyGlow=this._inFury?1.6:1;
    this._segments.forEach((seg,i)=>{
      const t=i/N;
      const ss=worldToScreen(seg.x,seg.y);
      const segR=(this.radius*(1-t*.45))*cam.zoom;
      const aura=ctx.createRadialGradient(ss.x,ss.y,segR*.3,ss.x,ss.y,segR*2.5);
      aura.addColorStop(0,`rgba(${this._inFury?'255,40,60':'120,0,255'},${(.18-t*.12)*(1+.3*Math.sin(T*2+i))*furyGlow})`);
      aura.addColorStop(1,'transparent');
      ctx.beginPath();ctx.arc(ss.x,ss.y,segR*2.5,0,Math.PI*2);ctx.fillStyle=aura;ctx.fill();
    });
    // Corpo serpentiforme — linha curva por todos os segmentos
    if(this._segments.length>1){
      ctx.save();ctx.lineJoin='round';ctx.lineCap='round';
      for(let i=0;i<N-1;i++){
        const t=i/N;
        const a=this._segments[i],b=this._segments[i+1];
        const as=worldToScreen(a.x,a.y),bs=worldToScreen(b.x,b.y);
        const segW=Math.max(1,(this.radius*(1-t*.5))*cam.zoom*1.8);
        const pulse=1+.08*Math.sin(T*3+i*.5);
        const bodyCol=this._inFury?(i===0?'255,80,60':'200,20,40'):(i===0?'160,60,255':'100,0,200');
        ctx.beginPath();ctx.moveTo(as.x,as.y);ctx.lineTo(bs.x,bs.y);
        ctx.strokeStyle=`rgba(${bodyCol},${.85-t*.35})`;
        ctx.lineWidth=segW*pulse;ctx.stroke();
        // Escamas
        if(i%2===0){
          const mx=(as.x+bs.x)*.5,my=(as.y+bs.y)*.5;
          const ang=Math.atan2(bs.y-as.y,bs.x-as.x)+Math.PI*.5;
          ctx.beginPath();ctx.moveTo(mx,my);
          ctx.lineTo(mx+Math.cos(ang)*segW*.6,my+Math.sin(ang)*segW*.6);
          ctx.lineTo(mx+Math.cos(ang)*segW*.6*(1+.2*Math.sin(T*4+i)),my+Math.sin(ang)*segW*.6*(1+.2*Math.sin(T*4+i)));
          ctx.strokeStyle=`rgba(${this._inFury?'255,150,150':'200,100,255'},${.35-t*.25})`;ctx.lineWidth=Math.max(.5,segW*.15);ctx.stroke();
        }
      }
      ctx.restore();
    }
    // Cabeça
    const hs=worldToScreen(this._segments[0].x,this._segments[0].y);
    const hr=this.radius*cam.zoom*(1+this._devourFlash*.3);
    const hg=ctx.createRadialGradient(hs.x,hs.y,0,hs.x,hs.y,hr);
    if(this._inFury){
      hg.addColorStop(0,'rgba(255,140,120,1)');
      hg.addColorStop(.5,'rgba(200,20,40,.85)');
      hg.addColorStop(1,'rgba(120,0,20,.6)');
    } else {
      hg.addColorStop(0,'rgba(200,100,255,1)');
      hg.addColorStop(.5,'rgba(120,0,220,.8)');
      hg.addColorStop(1,'rgba(60,0,140,.6)');
    }
    ctx.beginPath();ctx.arc(hs.x,hs.y,hr,0,Math.PI*2);ctx.fillStyle=hg;ctx.fill();
    // Flash de devoração
    if(this._devourFlash>0){
      ctx.beginPath();ctx.arc(hs.x,hs.y,hr*(1+this._devourFlash),0,Math.PI*2);
      ctx.strokeStyle=`rgba(255,255,150,${this._devourFlash*.7})`;ctx.lineWidth=Math.max(1,hr*.15);ctx.stroke();
    }
    // Olhos
    const eyeOff=hr*.35;
    const eyeAngle=this._headAngle+Math.PI*.5;
    [-1,1].forEach(side=>{
      const ex=hs.x+Math.cos(eyeAngle)*eyeOff*side-Math.sin(eyeAngle)*hr*.2;
      const ey=hs.y+Math.sin(eyeAngle)*eyeOff*side+Math.cos(eyeAngle)*hr*.2;
      ctx.beginPath();ctx.arc(ex,ey,Math.max(2,hr*.22)*(1+this._eyeGlow*.4),0,Math.PI*2);
      ctx.fillStyle=this._inFury?`rgba(255,60,40,${.8+.2*Math.sin(T*8)})`:`rgba(255,220,0,${.7+.2*Math.sin(T*6)})`;ctx.fill();
      ctx.beginPath();ctx.arc(ex,ey,Math.max(.8,hr*.1),0,Math.PI*2);
      ctx.fillStyle='rgba(0,0,0,.9)';ctx.fill();
    });
    if(sandboxMode){
      ctx.font=`${Math.max(7,hr*.45)}px 'Courier New'`;
      ctx.fillStyle=this._inFury?'rgba(255,90,80,.75)':'rgba(160,80,255,.55)';
      ctx.textAlign='center';
      const status=this._inFury?'FÚRIA DO VÁCUO':'CAÇANDO';
      ctx.fillText(`🐍 ${status} | 🌀×${this._chaosCount} | 🍴×${this._devourCount}`,hs.x,hs.y+hr+10*cam.zoom);
      ctx.textAlign='left';
    }
  }
}

// ── E. MECHA-MUNDO ─────────────────────────────────────────────────
// Entidade mecânica do tamanho de um planeta. Mira no planeta mais
// próximo, viaja até ele e o fragmenta em dezenas de meteoros e
// poeira cósmica. Os fragmentos podem colidir com outros astros
// ou ser usados para criar novos sistemas planetários.
class MechaWorldEntity extends CelestialObject{
  constructor(wx,wy){
    super(wx,wy,'entityMechaWorld');
    this.radius=16;this.mass=0;
    this.fixed=false;
    this._t=0;
    this._target=null;
    this._charging=false;   // está carregando o destruidor
    this._chargeTimer=0;    // 0..8 s de carga
    this._chargePulse=0;
    this._destroyed=0;      // planetas destruídos
    this._cooldown=0;       // espera após destruição
    this._gears=Array.from({length:6},(_,i)=>({
      a:i*(Math.PI/3),speed:(i%2===0?.4:-.4),r:rand(.55,.75)
    }));
    this._cannons=Array.from({length:4},(_,i)=>({a:i*(Math.PI*.5)+Math.PI*.25}));
    this.color='#aa8800';
    this.vx=rand(-1,1);this.vy=rand(-1,1);
  }
  _findTarget(){
    const planetTypes=['planet','gasgiant','icegiant','superearth','minineptune',
      'dwarfplanet','lavaplt','oceanplt','desertplt','carbonplt','ironplt','exBlanet'];
    let best=null,bestD=Infinity;
    objects.forEach(o=>{
      if(o===this||o.dead||!planetTypes.includes(o.type))return;
      const d=dist(o,this);
      if(d<bestD){bestD=d;best=o;}
    });
    return best;
  }
  update(dt){
    this._t+=dt;
    this._gears.forEach(g=>g.a+=g.speed*dt*(this._charging?3:1));
    if(this._chargePulse>0)this._chargePulse=Math.max(0,this._chargePulse-dt*1.2);
    if(this._cooldown>0){
      this._cooldown=Math.max(0,this._cooldown-dt);
      return;
    }
    if(!this._target||this._target.dead){
      this._target=this._findTarget();
      this._charging=false;this._chargeTimer=0;
    }
    if(!this._target){
      this.vx+=rand(-.04,.04);this.vy+=rand(-.04,.04);
      const spd=Math.hypot(this.vx,this.vy);
      if(spd>2){this.vx*=2/spd;this.vy*=2/spd;}
      this.x+=this.vx*dt*60;this.y+=this.vy*dt*60;
      return;
    }
    const d=dist(this,this._target);
    const engageR=this._target.radius*2+this.radius+10;
    if(d>engageR){
      // Viaja ao planeta
      const nx=(this._target.x-this.x)/d,ny=(this._target.y-this.y)/d;
      const spd=Math.min(4.5,d*.05+2);
      this.vx=this.vx*.88+nx*spd*.12;this.vy=this.vy*.88+ny*spd*.12;
      this.x+=this.vx*dt*60;this.y+=this.vy*dt*60;
      this._charging=false;this._chargeTimer=0;
    } else {
      // Em alcance — carrega e dispara
      this.vx*=.95;this.vy*=.95;
      this._charging=true;
      this._chargeTimer=Math.min(8,this._chargeTimer+dt);
      this._chargePulse=1;
      // Raios de carga para o planeta
      if(Math.random()<.06){
        particles.push({
          x:this._target.x+rand(-this._target.radius*.7,this._target.radius*.7),
          y:this._target.y+rand(-this._target.radius*.7,this._target.radius*.7),
          vx:rand(-2,2),vy:rand(-2,2),r:rand(1,3),alpha:.85,
          color:`hsl(${rand(30,60)},100%,${rand(60,90)}%)`
        });
      }
      if(this._chargeTimer>=8){
        // DISPARO: fragmenta o planeta
        const tgt=this._target;
        const fragCount=Math.floor(rand(8,18));
        const pr=tgt.radius||8;
        for(let i=0;i<fragCount;i++){
          const ang=rand(0,Math.PI*2);
          const spd=rand(4,12);
          const m=new Meteor(tgt.x+Math.cos(ang)*pr*.5,tgt.y+Math.sin(ang)*pr*.5);
          m.vx=Math.cos(ang)*spd+(tgt.vx||0);
          m.vy=Math.sin(ang)*spd+(tgt.vy||0);
          m.radius=Math.max(1.5,pr*.18+rand(-1,1));
          m.color=tgt.color||'#888';
          pendingObjects.push(m);
        }
        spawnExplosion(tgt.x,tgt.y,2.5,false);
        tgt.dead=true;
        this._destroyed++;
        this._target=null;this._charging=false;this._chargeTimer=0;
        this._cooldown=5; // pausa de 5s após destruição
        showTooltip(`💥 Mecha-Mundo fragmentou um planeta! ${fragCount} fragmentos liberados.`);
      }
    }
  }
  draw(){
    const sx=this.sx(),sy=this.sy(),r=this.sr();
    const T=this._t;
    // Aura de carga
    if(this._charging){
      const cf=this._chargeTimer/8;
      const ag=ctx.createRadialGradient(sx,sy,r,sx,sy,r*(2+cf*3));
      ag.addColorStop(0,`rgba(255,180,0,${cf*.45})`);
      ag.addColorStop(1,'transparent');
      ctx.beginPath();ctx.arc(sx,sy,r*(2+cf*3),0,Math.PI*2);ctx.fillStyle=ag;ctx.fill();
      // Anel de carga
      ctx.beginPath();ctx.arc(sx,sy,r*(1.5+cf),0,Math.PI*2);
      ctx.strokeStyle=`rgba(255,${Math.floor(200-cf*150)},0,${.5+cf*.4})`;
      ctx.lineWidth=Math.max(1,r*.12);ctx.stroke();
    }
    // Corpo esférico metálico
    const bg=ctx.createRadialGradient(sx-r*.25,sy-r*.25,r*.1,sx,sy,r);
    bg.addColorStop(0,'rgba(220,190,80,1)');
    bg.addColorStop(.4,'rgba(160,130,40,.95)');
    bg.addColorStop(.8,'rgba(80,60,10,.9)');
    bg.addColorStop(1,'rgba(40,30,5,.95)');
    ctx.beginPath();ctx.arc(sx,sy,r,0,Math.PI*2);ctx.fillStyle=bg;ctx.fill();
    // Engrenagens sobre o corpo
    this._gears.forEach(g=>{
      const gx=sx+Math.cos(g.a)*r*g.r,gy=sy+Math.sin(g.a)*r*g.r;
      const gr2=Math.max(2,r*.22);
      ctx.save();ctx.translate(gx,gy);ctx.rotate(g.a+T*(g.speed>0?.8:-.8));
      ctx.beginPath();
      for(let t=0;t<8;t++){
        const ta=t*(Math.PI/4);
        const ro=t%2===0?gr2:gr2*.65;
        const px=Math.cos(ta)*ro,py=Math.sin(ta)*ro;
        if(t===0)ctx.moveTo(px,py);else ctx.lineTo(px,py);
      }
      ctx.closePath();
      ctx.fillStyle=`rgba(${this._charging?'255,200,40':'180,150,30'},.85)`;ctx.fill();
      ctx.strokeStyle='rgba(255,220,60,.5)';ctx.lineWidth=.8;ctx.stroke();
      ctx.restore();
    });
    // Canhões
    this._cannons.forEach(c=>{
      const ca=c.a+T*.2;
      const cx=sx+Math.cos(ca)*r*.85,cy=sy+Math.sin(ca)*r*.85;
      ctx.beginPath();ctx.moveTo(cx,cy);
      ctx.lineTo(cx+Math.cos(ca)*r*.6,cy+Math.sin(ca)*r*.6);
      ctx.strokeStyle=`rgba(${this._charging?'255,180,0':'120,100,20'},.9)`;
      ctx.lineWidth=Math.max(2,r*.14);ctx.lineCap='round';ctx.stroke();ctx.lineCap='butt';
      // Brilho da boca do canhão quando carregando
      if(this._charging){
        ctx.beginPath();ctx.arc(cx+Math.cos(ca)*r*.65,cy+Math.sin(ca)*r*.65,Math.max(1.5,r*.1),0,Math.PI*2);
        ctx.fillStyle=`rgba(255,220,60,${.4+.3*Math.sin(T*8)})`;ctx.fill();
      }
    });
    // Janela central
    ctx.beginPath();ctx.arc(sx,sy,r*.28,0,Math.PI*2);
    ctx.fillStyle=`rgba(${this._charging?'255,160,0':'60,140,255'},.85)`;ctx.fill();
    ctx.strokeStyle='rgba(255,255,255,.3)';ctx.lineWidth=1;ctx.stroke();
    // Barra de carga
    if(this._charging&&this._target&&!this._target.dead){
      const bw=r*2.5,bh=Math.max(4,r*.18);
      const bx=sx-bw*.5,by=sy+r+8*cam.zoom;
      ctx.fillStyle='rgba(40,30,5,.7)';ctx.fillRect(bx,by,bw,bh);
      const cf=this._chargeTimer/8;
      const barColor=cf>.8?'rgba(255,80,0,1)':cf>.5?'rgba(255,180,0,1)':'rgba(255,220,60,1)';
      ctx.fillStyle=barColor;ctx.fillRect(bx,by,bw*cf,bh);
      ctx.strokeStyle='rgba(200,150,20,.5)';ctx.lineWidth=1;ctx.strokeRect(bx,by,bw,bh);
    }
    if(sandboxMode){
      const bh2=this._charging?r*.18*cam.zoom+8*cam.zoom:0;
      ctx.font=`${Math.max(7,r*.45)}px 'Courier New'`;
      ctx.fillStyle='rgba(220,180,40,.55)';
      ctx.textAlign='center';
      ctx.fillText(`⚙️ ${this._charging?`CARREGANDO ${Math.round(this._chargeTimer/8*100)}%`:'CAÇANDO'} | 💥×${this._destroyed}`,sx,sy+r+14*cam.zoom+bh2);
      ctx.textAlign='left';
    }
  }
}

// ── F. SONDA ESPACIAL ─────────────────────────────────────────────
// Viaja autonomamente de astro em astro, "escaneando" cada um ao
// chegar perto. Cada escaneamento gera um pequeno pulso de dados e
// contribui para um contador de "Catálogo Estelar". Ao escanear
// astros muito raros (buracos negros, quasares, exóticos), a sonda
// entra em "Modo Descoberta": brilha intensamente e transmite um
// sinal de longo alcance que acelera o crescimento de estrelas
// próximas por alguns segundos (mini-boost de nucleossíntese).
class ProbeEntity extends CelestialObject{
  constructor(wx,wy){
    super(wx,wy,'techProbe');
    this.radius=13;this.mass=0;
    this.fixed=false;
    this._t=0;
    this.color='#88ddff';
    this.vx=rand(-1,1);this.vy=rand(-1,1);
    this._target=null;
    this._scanned=new Set();
    this._scanCount=0;
    this._rareCount=0;
    this._scanFlash=0;
    this._discoveryMode=0; // duração do modo descoberta
    this._retargetTimer=rand(1,2);
    this._trail=[];
  }
  _rarityOf(o){
    const rareTypes=['blackhole','whitehole','wormhole','quasar','magnetar','pulsar',
      'darkmatter','greatattractor','gravastar','planckStar','strangeStar'];
    const exotic=typeof o.type==='string'&&o.type.startsWith('ex');
    return exotic||rareTypes.includes(o.type)?2:1;
  }
  _findTarget(){
    let best=null,bestD=Infinity;
    objects.forEach(o=>{
      if(o===this||o.dead||TECH_TYPES.includes(o.type)||this._scanned.has(o))return;
      if(o.type==='meteor'||o.type==='comet')return; // ignora detritos pequenos
      const d=dist(o,this);
      if(d<bestD){bestD=d;best=o;}
    });
    return best;
  }
  update(dt){
    this._t+=dt;
    this._scanFlash=Math.max(0,this._scanFlash-dt*1.5);
    this._discoveryMode=Math.max(0,this._discoveryMode-dt);
    // Rastro visual
    this._trail.push({x:this.x,y:this.y});
    if(this._trail.length>18)this._trail.shift();

    this._retargetTimer-=dt;
    if((!this._target||this._target.dead||this._scanned.has(this._target))&&this._retargetTimer<=0){
      this._retargetTimer=1.5;
      this._target=this._findTarget();
      if(!this._target){this._scanned.clear();} // catálogo completo: recomeça a rota
    }
    if(this._target&&!this._target.dead){
      const d=dist(this,this._target)||0.001;
      if(d>this._target.radius+30){
        const nx=(this._target.x-this.x)/d,ny=(this._target.y-this.y)/d;
        const spd=2.6;
        this.vx=this.vx*.92+nx*spd*.08;this.vy=this.vy*.92+ny*spd*.08;
        this.x+=this.vx*dt*60;this.y+=this.vy*dt*60;
      } else if(!this._scanned.has(this._target)){
        this._scanned.add(this._target);
        this._scanCount++;
        this._scanFlash=1;
        const rarity=this._rarityOf(this._target);
        if(rarity>1){
          this._rareCount++;
          this._discoveryMode=4;
          showTooltip(`🛰️ Sonda descobriu algo raro: ${this._target.name||this._target.type}! Modo Descoberta ativado.`);
          // Sinal de longo alcance: acelera levemente estrelas próximas
          objects.forEach(o=>{
            if(o===this||o.dead)return;
            if(typeof o.type==='string'&&/star|cepheid|protostar|dwarf|giant/i.test(o.type)){
              const dd=dist(o,this);if(dd<500){o._probeBoost=(o._probeBoost||0)+dt;}
            }
          });
        } else {
          showTooltip(`🛰️ Sonda escaneou ${this._target.name||this._target.type}. (${this._scanCount} no catálogo)`);
        }
      }
    } else {
      // Sem alvo: deriva lenta
      this.vx*=.98;this.vy*=.98;
      this.x+=this.vx*dt*60;this.y+=this.vy*dt*60;
    }
  }
  draw(){
    const sx=this.sx(),sy=this.sy(),r=this.sr();
    const T=this._t;
    // Rastro
    this._trail.forEach((p,i)=>{
      const ps=worldToScreen(p.x,p.y);
      const a=(i/this._trail.length)*.4;
      ctx.beginPath();ctx.arc(ps.x,ps.y,Math.max(.5,r*.3*(i/this._trail.length)),0,Math.PI*2);
      ctx.fillStyle=`rgba(120,220,255,${a})`;ctx.fill();
    });
    // Modo descoberta: auréola pulsante
    if(this._discoveryMode>0){
      const dg=ctx.createRadialGradient(sx,sy,0,sx,sy,r*4);
      dg.addColorStop(0,`rgba(255,255,180,${.3*(this._discoveryMode/4)})`);
      dg.addColorStop(1,'transparent');
      ctx.beginPath();ctx.arc(sx,sy,r*4,0,Math.PI*2);ctx.fillStyle=dg;ctx.fill();
    }
    ctx.save();ctx.translate(sx,sy);ctx.rotate(T*.15);
    // ── 4 PAINÉIS SOLARES em cruz (estilo sonda real: Voyager/Cassini) ──
    for(let p=0;p<4;p++){
      const pa=p*(Math.PI/2)+Math.PI/4;
      ctx.save();ctx.rotate(pa);
      const pw=r*.62,pl=r*1.55;
      // Braço de sustentação
      ctx.beginPath();ctx.moveTo(0,r*.28);ctx.lineTo(0,r*.5);
      ctx.strokeStyle='rgba(150,150,160,.85)';ctx.lineWidth=Math.max(.6,r*.045);ctx.stroke();
      // Painel solar (retângulo com grade de células)
      const panelG=ctx.createLinearGradient(-pw*.5,r*.5,pw*.5,r*.5+pl);
      panelG.addColorStop(0,'rgba(30,50,110,.95)');
      panelG.addColorStop(.5,'rgba(55,85,165,.95)');
      panelG.addColorStop(1,'rgba(25,40,90,.95)');
      ctx.fillStyle=panelG;
      ctx.fillRect(-pw*.5,r*.5,pw,pl);
      ctx.strokeStyle='rgba(170,200,255,.8)';ctx.lineWidth=Math.max(.5,r*.03);
      ctx.strokeRect(-pw*.5,r*.5,pw,pl);
      // Grade de células fotovoltaicas
      for(let cx=1;cx<3;cx++){
        ctx.beginPath();ctx.moveTo(-pw*.5+pw*cx/3,r*.5);ctx.lineTo(-pw*.5+pw*cx/3,r*.5+pl);
        ctx.strokeStyle='rgba(150,180,230,.5)';ctx.lineWidth=Math.max(.3,r*.015);ctx.stroke();
      }
      for(let cy=1;cy<5;cy++){
        ctx.beginPath();ctx.moveTo(-pw*.5,r*.5+pl*cy/5);ctx.lineTo(pw*.5,r*.5+pl*cy/5);
        ctx.strokeStyle='rgba(150,180,230,.5)';ctx.lineWidth=Math.max(.3,r*.015);ctx.stroke();
      }
      // Brilho sutil de reflexo solar
      ctx.beginPath();ctx.moveTo(-pw*.3,r*.5+pl*.1);ctx.lineTo(-pw*.1,r*.5+pl*.1);ctx.lineTo(-pw*.2,r*.5+pl*.9);ctx.lineTo(-pw*.4,r*.5+pl*.9);ctx.closePath();
      ctx.fillStyle='rgba(255,255,255,.12)';ctx.fill();
      ctx.restore();
    }
    // ── CORPO CENTRAL — cilindro/octógono realista com detalhes técnicos ──
    const bodyR=r*.62;
    const bodyG=ctx.createRadialGradient(-bodyR*.3,-bodyR*.3,0,0,0,bodyR);
    bodyG.addColorStop(0,'rgba(235,240,245,1)');
    bodyG.addColorStop(.55,'rgba(190,198,208,1)');
    bodyG.addColorStop(1,'rgba(130,138,148,1)');
    ctx.beginPath();
    for(let i=0;i<8;i++){
      const oa=i*(Math.PI/4);
      const ox=Math.cos(oa)*bodyR,oy=Math.sin(oa)*bodyR;
      i===0?ctx.moveTo(ox,oy):ctx.lineTo(ox,oy);
    }
    ctx.closePath();
    ctx.fillStyle=this._scanFlash>0?`rgba(255,255,255,${.6+this._scanFlash})`:bodyG;ctx.fill();
    ctx.strokeStyle='rgba(210,215,225,.9)';ctx.lineWidth=Math.max(.6,r*.035);ctx.stroke();
    // Painéis técnicos dourados (isolamento térmico, como em sondas reais)
    for(let g=0;g<3;g++){
      const gy=-bodyR*.5+g*bodyR*.5;
      ctx.beginPath();ctx.moveTo(-bodyR*.75,gy);ctx.lineTo(bodyR*.75,gy);
      ctx.strokeStyle='rgba(220,180,90,.5)';ctx.lineWidth=Math.max(.4,r*.02);ctx.stroke();
    }
    // Faixa dourada de proteção térmica na base
    ctx.beginPath();ctx.arc(0,0,bodyR*.98,Math.PI*.15,Math.PI*.85);
    ctx.strokeStyle='rgba(230,190,90,.7)';ctx.lineWidth=Math.max(1,r*.09);ctx.stroke();

    // ── CÚPULA/PRATO INVERTIDO na frente (antena parabólica voltada pra trás) ──
    const dishR=r*.85;
    ctx.save();ctx.translate(0,-bodyR*.55);
    // Prato parabólico (elipse "invertida" — concavidade voltada pro topo)
    const dishG=ctx.createRadialGradient(0,dishR*.15,dishR*.1,0,0,dishR);
    dishG.addColorStop(0,'rgba(255,255,255,.95)');
    dishG.addColorStop(.5,'rgba(215,220,228,.92)');
    dishG.addColorStop(1,'rgba(150,155,165,.85)');
    ctx.beginPath();ctx.ellipse(0,0,dishR,dishR*.62,0,Math.PI,Math.PI*2);
    ctx.fillStyle=dishG;ctx.fill();
    ctx.strokeStyle='rgba(180,185,195,.9)';ctx.lineWidth=Math.max(.6,r*.035);ctx.stroke();
    // Anéis concêntricos do prato (efeito parabólico)
    for(let ring=1;ring<=2;ring++){
      ctx.beginPath();ctx.ellipse(0,dishR*.62*(1-ring/3.2),dishR*(1-ring/3.2),dishR*.62*(1-ring/3.2),0,Math.PI,Math.PI*2);
      ctx.strokeStyle='rgba(170,175,185,.5)';ctx.lineWidth=Math.max(.3,r*.02);ctx.stroke();
    }
    // Haste central do receptor (subreflector), típica de antena parabólica
    ctx.beginPath();ctx.moveTo(0,0);ctx.lineTo(0,-dishR*.55);
    ctx.strokeStyle='rgba(200,205,215,.85)';ctx.lineWidth=Math.max(.5,r*.03);ctx.stroke();
    ctx.beginPath();ctx.arc(0,-dishR*.55,Math.max(.8,r*.06),0,Math.PI*2);
    ctx.fillStyle='rgba(180,185,195,.9)';ctx.fill();
    ctx.restore();

    // Antena secundária de comunicação
    ctx.beginPath();ctx.moveTo(bodyR*.5,bodyR*.4);ctx.lineTo(bodyR*.95,bodyR*.85);
    ctx.strokeStyle='rgba(190,195,205,.8)';ctx.lineWidth=Math.max(.4,r*.025);ctx.stroke();
    ctx.beginPath();ctx.arc(bodyR*.95,bodyR*.85,Math.max(.6,r*.06),0,Math.PI*2);
    ctx.fillStyle=`rgba(255,220,100,${.5+.5*Math.sin(T*5)})`;ctx.fill();
    ctx.restore();
    if(sandboxMode){
      ctx.font=`${Math.max(7,r*.6)}px 'Courier New'`;ctx.fillStyle='rgba(140,210,255,.6)';
      ctx.textAlign='center';
      ctx.fillText(`🛰️ ${this._scanCount} catalogados | ✨${this._rareCount} raros`,sx,sy+r+10*cam.zoom);
      ctx.textAlign='left';
    }
  }
}

// ── G. LABORATÓRIO ORBITAL ────────────────────────────────────────
// Ancora-se a uma estrela e realiza pesquisa passiva ao longo do
// tempo, acumulando "Pontos de Pesquisa". Ao atingir marcos de
// pesquisa, sintetiza um pequeno astro aleatório (meteoro exótico
// carregado de energia) ejetado da estrela — um "experimento" que
// pode colidir com outros objetos. Se a estrela hospedeira morre,
// o laboratório entra em modo de emergência e se autodestrói.
class LabEntity extends CelestialObject{
  constructor(wx,wy){
    super(wx,wy,'techLaboratory');
    this.radius=15;this.mass=20;
    this.fixed=true;
    this.host=null;
    this._t=0;
    this.color='#66ffcc';
    this._research=0;
    this._nextMilestone=100;
    this._pulseTimer=0;
    this._synthCount=0;
    this._orbitAngle=rand(0,Math.PI*2);
  }
  attachTo(host){
    this.host=host;
    this._orbitAngle=Math.atan2(0,1);
    this.x=host.x+host.radius*2.2;this.y=host.y;
  }
  update(dt){
    if(!this.host||this.host.dead){
      if(!this._dying){this._dying=true;spawnExplosion(this.x,this.y,0.5,false);}
      this.dead=true;return;
    }
    this._t+=dt;
    // Órbita ao redor do host
    this._orbitAngle+=dt*.5;
    const orbR=this.host.radius*2.2+10;
    this.x=this.host.x+Math.cos(this._orbitAngle)*orbR;
    this.y=this.host.y+Math.sin(this._orbitAngle)*orbR;

    // Pesquisa passiva: taxa proporcional ao "brilho" do hospedeiro
    const isStarlike=typeof this.host.type==='string'&&/star|cepheid|protostar|dwarf|giant|quasar|pulsar|magnetar/i.test(this.host.type);
    this._research+=dt*(isStarlike?3.2:1.1);
    this._pulseTimer=Math.max(0,this._pulseTimer-dt);

    if(this._research>=this._nextMilestone){
      this._research=0;
      this._nextMilestone*=1.35;
      this._synthCount++;
      this._pulseTimer=1;
      // Sintetiza um meteoro exótico carregado de energia
      const a=rand(0,Math.PI*2);
      const m=new Meteor(this.x+Math.cos(a)*14,this.y+Math.sin(a)*14);
      m.vx=Math.cos(a)*rand(6,14);m.vy=Math.sin(a)*rand(6,14);
      m.color='#66ffcc';m._labSynthesized=true;m._autoSpawn=true;
      pendingObjects.push(m);
      showTooltip(`🔬 Laboratório sintetizou um Experimento Orbital! (${this._synthCount} realizados)`);
    }
  }
  draw(){
    if(!this.host||this.host.dead)return;
    const sx=this.sx(),sy=this.sy(),r=this.sr();
    const hx=this.host.sx(),hy=this.host.sy();
    const T=this._t;
    // Linha de conexão de dados com o host
    ctx.beginPath();ctx.moveTo(hx,hy);ctx.lineTo(sx,sy);
    ctx.strokeStyle=`rgba(100,255,200,${.25+.15*Math.sin(T*3)})`;ctx.lineWidth=Math.max(.5,r*.06);
    ctx.setLineDash([4,4]);ctx.stroke();ctx.setLineDash([]);

    ctx.save();ctx.translate(sx,sy);ctx.rotate(this._orbitAngle*.3);
    // ── 2 PAINÉIS SOLARES grandes (um de cada lado do cilindro) ──
    [-1,1].forEach(side=>{
      const px=side*r*.95,pw=r*.85,pl=r*2.3;
      ctx.save();ctx.translate(px,0);
      // Braço de sustentação
      ctx.beginPath();ctx.moveTo(-side*r*.15,0);ctx.lineTo(0,0);
      ctx.strokeStyle='rgba(150,150,160,.8)';ctx.lineWidth=Math.max(.6,r*.05);ctx.stroke();
      const panelG=ctx.createLinearGradient(0,-pl*.5,0,pl*.5);
      panelG.addColorStop(0,'rgba(30,60,110,.95)');
      panelG.addColorStop(.5,'rgba(60,100,170,.95)');
      panelG.addColorStop(1,'rgba(25,50,95,.95)');
      ctx.fillStyle=panelG;
      ctx.fillRect(side>0?0:-pw,-pl*.5,pw,pl);
      ctx.strokeStyle='rgba(170,205,255,.85)';ctx.lineWidth=Math.max(.5,r*.03);
      ctx.strokeRect(side>0?0:-pw,-pl*.5,pw,pl);
      // Grade de células
      for(let cy=1;cy<7;cy++){
        ctx.beginPath();ctx.moveTo(side>0?0:-pw,-pl*.5+pl*cy/7);ctx.lineTo(side>0?pw:0,-pl*.5+pl*cy/7);
        ctx.strokeStyle='rgba(150,185,235,.5)';ctx.lineWidth=Math.max(.3,r*.014);ctx.stroke();
      }
      ctx.beginPath();ctx.moveTo(side>0?pw*.5:-pw*.5,-pl*.5);ctx.lineTo(side>0?pw*.5:-pw*.5,pl*.5);
      ctx.strokeStyle='rgba(150,185,235,.5)';ctx.lineWidth=Math.max(.3,r*.014);ctx.stroke();
      ctx.restore();
    });
    // ── CORPO CILÍNDRICO GRANDE (módulo de laboratório, estilo ISS) ──
    const cylW=r*.62,cylH=r*2.1;
    const cylG=ctx.createLinearGradient(-cylW,0,cylW,0);
    cylG.addColorStop(0,'rgba(150,160,170,1)');
    cylG.addColorStop(.35,'rgba(225,232,240,1)');
    cylG.addColorStop(.6,'rgba(180,190,200,1)');
    cylG.addColorStop(1,'rgba(110,118,128,1)');
    const pulse=this._pulseTimer>0?1+this._pulseTimer*.15:1;
    ctx.save();ctx.scale(1,pulse);
    // Corpo principal (retângulo com pontas arredondadas simuladas)
    ctx.beginPath();
    ctx.moveTo(-cylW,-cylH*.5+cylW*.3);
    ctx.quadraticCurveTo(-cylW,-cylH*.5,-cylW*.3,-cylH*.5);
    ctx.lineTo(cylW*.3,-cylH*.5);
    ctx.quadraticCurveTo(cylW,-cylH*.5,cylW,-cylH*.5+cylW*.3);
    ctx.lineTo(cylW,cylH*.5-cylW*.3);
    ctx.quadraticCurveTo(cylW,cylH*.5,cylW*.3,cylH*.5);
    ctx.lineTo(-cylW*.3,cylH*.5);
    ctx.quadraticCurveTo(-cylW,cylH*.5,-cylW,cylH*.5-cylW*.3);
    ctx.closePath();
    ctx.fillStyle=this._pulseTimer>0?`rgba(230,255,245,${.9+this._pulseTimer*.1})`:cylG;ctx.fill();
    ctx.strokeStyle='rgba(200,255,230,.85)';ctx.lineWidth=Math.max(.6,r*.035);ctx.stroke();
    // Anéis estruturais (segmentos do módulo, como painéis da ISS)
    for(let seg=1;seg<5;seg++){
      const segY=-cylH*.5+cylH*seg/5;
      ctx.beginPath();ctx.moveTo(-cylW*.95,segY);ctx.lineTo(cylW*.95,segY);
      ctx.strokeStyle='rgba(90,140,130,.55)';ctx.lineWidth=Math.max(.4,r*.02);ctx.stroke();
    }
    // Janelas/portais verdes (bioluminescência de pesquisa)
    for(let w=0;w<3;w++){
      const wy=-cylH*.28+w*cylH*.28;
      ctx.beginPath();ctx.arc(0,wy,Math.max(1.2,cylW*.22),0,Math.PI*2);
      ctx.fillStyle=`rgba(120,255,210,${.55+.25*Math.sin(T*2.5+w)})`;ctx.fill();
      ctx.strokeStyle='rgba(200,255,230,.7)';ctx.lineWidth=Math.max(.3,r*.014);ctx.stroke();
    }
    ctx.restore();
    // Cúpula sensora no topo (antena de dados)
    ctx.beginPath();ctx.moveTo(0,-cylH*.5*pulse);ctx.lineTo(0,-cylH*.5*pulse-r*.35);
    ctx.strokeStyle='rgba(180,230,215,.8)';ctx.lineWidth=Math.max(.5,r*.03);ctx.stroke();
    ctx.beginPath();ctx.arc(0,-cylH*.5*pulse-r*.35,Math.max(.8,r*.08),0,Math.PI*2);
    ctx.fillStyle=`rgba(140,255,220,${.6+.4*Math.sin(T*4)})`;ctx.fill();
    ctx.restore();
    if(sandboxMode){
      const pct=Math.min(100,Math.round(this._research/this._nextMilestone*100));
      ctx.font=`${Math.max(7,r*.7)}px 'Courier New'`;ctx.fillStyle='rgba(100,230,200,.6)';
      ctx.textAlign='center';
      ctx.fillText(`🔬 Pesquisa ${pct}% | 🧪×${this._synthCount}`,sx,sy+r*1.6+10*cam.zoom);
      ctx.textAlign='left';
    }
  }
}

// ── H. ESTAÇÃO ESPACIAL ───────────────────────────────────────────
// Ancora-se a um planeta e simula crescimento populacional/civil ao
// longo do tempo: acumula "Habitantes". Quanto mais habitantes, mais
// forte seu "escudo orbital" (reduz o dano recebido de invasões).
// Se destruída, o planeta hospedeiro sofre uma pequena onda de
// choque (perde raio) representando a perda da colônia orbital.
class StationEntity extends CelestialObject{
  constructor(wx,wy){
    super(wx,wy,'techStation');
    this.radius=9;this.mass=15;
    this.fixed=true;
    this.host=null;
    this._t=0;
    this.color='#ffcc66';
    this.hp=1200;this.maxHP=1200;
    this._population=0;
    this._growthRate=2.4;
    this._orbitAngle=rand(0,Math.PI*2);
    this._lightBlink=0;
    this._hitFlash=0;
  }
  attachTo(host){
    this.host=host;
    this._orbitAngle=0;
    this.x=host.x+host.radius*1.8;this.y=host.y;
  }
  takeDamage(dmg){
    const shieldReduction=Math.min(.6,this._population/50000);
    this.hp=Math.max(0,this.hp-dmg*(1-shieldReduction));
    this._hitFlash=0.4;
    if(this.hp<=0){
      this.dead=true;
      if(this.host&&!this.host.dead){
        this.host.radius=Math.max(2,this.host.radius-this.host.radius*.08);
        spawnExplosion(this.x,this.y,1,false);
      }
      showTooltip('💥 A Estação Espacial foi destruída! A colônia orbital foi perdida.');
    }
  }
  update(dt){
    if(!this.host||this.host.dead){this.dead=true;return;}
    this._t+=dt;
    this._hitFlash=Math.max(0,this._hitFlash-dt*2);
    this._lightBlink=(this._lightBlink+dt*2)%(Math.PI*2);
    this._orbitAngle+=dt*.3;
    const orbR=this.host.radius*1.8+8;
    this.x=this.host.x+Math.cos(this._orbitAngle)*orbR;
    this.y=this.host.y+Math.sin(this._orbitAngle)*orbR;
    // Crescimento populacional (satura em 100k)
    if(this._population<100000){
      this._population=Math.min(100000,this._population+this._growthRate*dt*60*.05);
    }
  }
  draw(){
    if(!this.host||this.host.dead)return;
    const sx=this.sx(),sy=this.sy(),r=this.sr();
    const hx=this.host.sx(),hy=this.host.sy();
    const T=this._t;
    // Escudo orbital visível quando a população é alta
    const shieldPct=Math.min(.6,this._population/50000);
    if(shieldPct>0.05){
      ctx.beginPath();ctx.arc(sx,sy,r*3.4,0,Math.PI*2);
      ctx.strokeStyle=`rgba(255,210,120,${shieldPct*.5})`;ctx.lineWidth=Math.max(1,r*.1);ctx.stroke();
    }
    const hullColor=this._hitFlash>0?`rgba(255,255,255,${.6+this._hitFlash})`:'rgba(215,175,110,.95)';
    const panelBlue=`rgba(90,140,210,${.85})`;
    const panelBlueDark='rgba(50,90,150,.9)';
    ctx.save();ctx.translate(sx,sy);ctx.rotate(T*.06);
    // ── Módulo central: corpo retangular principal ──
    const bw=r*1.5,bh=r*.68;
    ctx.fillStyle='rgba(70,65,60,.95)';
    ctx.fillRect(-bw/2,-bh/2,bw,bh);
    ctx.strokeStyle=hullColor;ctx.lineWidth=Math.max(1,r*.08);
    ctx.strokeRect(-bw/2,-bh/2,bw,bh);
    // Linhas de painel/segmentação do casco
    ctx.strokeStyle='rgba(30,28,25,.8)';ctx.lineWidth=Math.max(.5,r*.03);
    for(let i=1;i<4;i++){
      const lx=-bw/2+bw*(i/4);
      ctx.beginPath();ctx.moveTo(lx,-bh/2);ctx.lineTo(lx,bh/2);ctx.stroke();
    }
    // Módulos secundários acoplados (cubos menores nas pontas, tipo add-on)
    const modR=r*.32;
    ctx.fillStyle='rgba(90,84,76,.95)';
    ctx.fillRect(-bw/2-modR*1.4,-modR*.55,modR*1.4,modR*1.1);
    ctx.fillRect(bw/2,-modR*.55,modR*1.4,modR*1.1);
    ctx.strokeStyle=hullColor;ctx.lineWidth=Math.max(.7,r*.05);
    ctx.strokeRect(-bw/2-modR*1.4,-modR*.55,modR*1.4,modR*1.1);
    ctx.strokeRect(bw/2,-modR*.55,modR*1.4,modR*1.1);
    // Cúpula/observatório central saliente
    ctx.beginPath();ctx.arc(0,-bh/2-r*.1,r*.16,Math.PI,0);
    ctx.fillStyle='rgba(255,230,180,.9)';ctx.fill();
    ctx.strokeStyle=hullColor;ctx.lineWidth=Math.max(.6,r*.04);ctx.stroke();
    // ── Treliças (trusses) conectando aos painéis solares ──
    const trussLen=r*1.35;
    ctx.strokeStyle='rgba(180,175,165,.85)';ctx.lineWidth=Math.max(.8,r*.06);
    [1,-1].forEach(side=>{
      ctx.beginPath();ctx.moveTo(side*bw/2*.3,0);ctx.lineTo(side*(bw/2*.3+trussLen),0);ctx.stroke();
      // Reforços diagonais estilo treliça (truss segments)
      const segN=4;
      for(let i=0;i<segN;i++){
        const x0=side*(bw/2*.3+trussLen*(i/segN));
        const x1=side*(bw/2*.3+trussLen*((i+1)/segN));
        ctx.beginPath();ctx.moveTo(x0,-r*.06);ctx.lineTo(x1,r*.06);ctx.stroke();
        ctx.beginPath();ctx.moveTo(x0,r*.06);ctx.lineTo(x1,-r*.06);ctx.stroke();
      }
    });
    // ── Diversas placas solares (arrays retangulares em ambos os lados) ──
    [1,-1].forEach(side=>{
      const baseX=side*(bw/2*.3+trussLen);
      const panelW=r*.34,panelH=r*1.15;
      for(let p=0;p<2;p++){
        const px=baseX+side*p*(panelW*1.08);
        ctx.save();ctx.translate(px,0);
        ctx.fillStyle=panelBlue;
        ctx.fillRect(-panelW/2,-panelH/2,panelW,panelH);
        ctx.strokeStyle=hullColor;ctx.lineWidth=Math.max(.6,r*.04);
        ctx.strokeRect(-panelW/2,-panelH/2,panelW,panelH);
        // Grade de células fotovoltaicas
        ctx.strokeStyle=panelBlueDark;ctx.lineWidth=Math.max(.4,r*.02);
        const cellRows=5,cellCols=2;
        for(let cr=1;cr<cellRows;cr++){
          const cy=-panelH/2+panelH*(cr/cellRows);
          ctx.beginPath();ctx.moveTo(-panelW/2,cy);ctx.lineTo(panelW/2,cy);ctx.stroke();
        }
        for(let cc=1;cc<cellCols;cc++){
          const cx=-panelW/2+panelW*(cc/cellCols);
          ctx.beginPath();ctx.moveTo(cx,-panelH/2);ctx.lineTo(cx,panelH/2);ctx.stroke();
        }
        // Brilho sutil de reflexo solar
        ctx.fillStyle=`rgba(200,225,255,${.15+.1*Math.sin(T*.8+side*2+p)})`;
        ctx.fillRect(-panelW/2,-panelH/2,panelW,panelH*.3);
        ctx.restore();
      }
    });
    ctx.restore();
    // Luzes piscando na órbita
    for(let i=0;i<3;i++){
      const la=this._lightBlink+i*(Math.PI*2/3);
      const lx=sx+Math.cos(la)*r*2,ly=sy+Math.sin(la)*r*2;
      ctx.beginPath();ctx.arc(lx,ly,Math.max(.6,r*.08),0,Math.PI*2);
      ctx.fillStyle=`rgba(255,240,200,${.5+.5*Math.sin(this._lightBlink*3+i)})`;ctx.fill();
    }
    const hpPct=this.hp/this.maxHP;
    ctx.fillStyle='rgba(0,0,0,.5)';ctx.fillRect(sx-r*2.4,sy-r*2.9,r*4.8,3);
    ctx.fillStyle=hpPct>.5?'rgba(255,210,120,.9)':hpPct>.2?'rgba(255,150,60,.9)':'rgba(255,60,60,.9)';
    ctx.fillRect(sx-r*2.4,sy-r*2.9,r*4.8*hpPct,3);
    if(sandboxMode){
      ctx.font=`${Math.max(7,r*.65)}px 'Courier New'`;ctx.fillStyle='rgba(255,210,140,.6)';
      ctx.textAlign='center';
      ctx.fillText(`🏗️ ${Math.round(this._population).toLocaleString()} hab. | 🛡️${Math.round(shieldPct*100)}%`,sx,sy+r*3+10*cam.zoom);
      ctx.textAlign='left';
    }
  }
}

// ── I. TELESCÓPIO ESPACIAL ────────────────────────────────────────
// Objeto livre e estacionário (deriva muito devagar) que continua-
// mente varre a região ao redor em busca de ameaças e curiosidades.
// MECÂNICA ÚNICA: detecta Frotas Militares Reptilianas e Naves
// Reptilianas dentro de um raio grande e emite um Alerta Antecipado
// (visível mesmo fora da tela via aviso), dando ao jogador tempo de
// reagir. Também ocasionalmente "revela" um astro próximo com um
// destaque visual temporário (like um scanner astronômico).
class TelescopeEntity extends CelestialObject{
  constructor(wx,wy){
    super(wx,wy,'techTelescope');
    this.radius=15;this.mass=0;
    this.fixed=false;
    this._t=0;
    this.color='#cc99ff';
    this.vx=rand(-.15,.15);this.vy=rand(-.15,.15);
    this._scanAngle=rand(0,Math.PI*2);
    this._scanRadius=900;
    this._alertCD=0;
    this._revealCD=rand(4,7);
    this._revealTarget=null;
    this._revealT=0;
    this._detectedThreats=0;
    // ── Skin visual: 50% chance de nascer como Hubble ou James Webb ──
    this._skin=Math.random()<0.5?'hubble':'jwst';
  }
  update(dt){
    this._t+=dt;
    this.x+=this.vx*dt*60;this.y+=this.vy*dt*60;
    this._scanAngle+=dt*.4;
    this._alertCD=Math.max(0,this._alertCD-dt);
    this._revealT=Math.max(0,this._revealT-dt);

    // ── Alerta antecipado de ameaças reptilianas ──
    if(this._alertCD<=0){
      const threat=objects.find(o=>!o.dead&&(o instanceof ReptilianFleetEntity||o.type===RACE_REPTILIAN)&&dist(this,o)<this._scanRadius);
      if(threat){
        this._alertCD=8;
        this._detectedThreats++;
        const kind=threat instanceof ReptilianFleetEntity?'uma Frota Militar Reptiliana':'uma Nave Reptiliana';
        showTooltip(`🔭 Telescópio detectou ${kind} se aproximando! Alerta antecipado.`);
      }
    }

    // ── Revelação periódica de um astro próximo (destaque visual) ──
    this._revealCD-=dt;
    if(this._revealCD<=0){
      this._revealCD=rand(5,9);
      let best=null,bestD=Infinity;
      objects.forEach(o=>{
        if(o===this||o.dead||TECH_TYPES.includes(o.type))return;
        const d=dist(o,this);
        if(d<this._scanRadius&&d<bestD){bestD=d;best=o;}
      });
      if(best){this._revealTarget=best;this._revealT=2.5;}
    }
  }
  draw(){
    const sx=this.sx(),sy=this.sy(),r=this.sr();
    const T=this._t;
    // Cone de varredura giratório
    const coneLen=this._scanRadius*cam.zoom;
    const coneSpread=.35;
    ctx.save();
    const cg=ctx.createLinearGradient(sx,sy,sx+Math.cos(this._scanAngle)*coneLen,sy+Math.sin(this._scanAngle)*coneLen);
    cg.addColorStop(0,'rgba(200,150,255,.12)');cg.addColorStop(1,'transparent');
    ctx.beginPath();ctx.moveTo(sx,sy);
    ctx.arc(sx,sy,coneLen,this._scanAngle-coneSpread,this._scanAngle+coneSpread);
    ctx.closePath();ctx.fillStyle=cg;ctx.fill();
    ctx.restore();

    // Destaque de revelação num astro próximo
    if(this._revealT>0&&this._revealTarget&&!this._revealTarget.dead){
      const rs=this._revealTarget.sx?this._revealTarget.sx():sx;
      const rsy=this._revealTarget.sy?this._revealTarget.sy():sy;
      const rr=(this._revealTarget.sr?this._revealTarget.sr():10)*1.6;
      const alpha=Math.min(1,this._revealT);
      ctx.beginPath();ctx.arc(rs,rsy,rr,0,Math.PI*2);
      ctx.strokeStyle=`rgba(210,160,255,${alpha*.8})`;ctx.lineWidth=Math.max(1,r*.1);ctx.stroke();
      ctx.beginPath();ctx.moveTo(sx,sy);ctx.lineTo(rs,rsy);
      ctx.strokeStyle=`rgba(180,130,255,${alpha*.3})`;ctx.lineWidth=Math.max(.5,r*.04);ctx.setLineDash([3,5]);ctx.stroke();ctx.setLineDash([]);
    }

    ctx.save();ctx.translate(sx,sy);ctx.rotate(this._scanAngle*.15);
    if(this._skin==='hubble'){
      this._drawHubble(r,T);
    } else {
      this._drawJWST(r,T);
    }
    ctx.restore();

    if(sandboxMode){
      ctx.font=`${Math.max(7,r*.55)}px 'Courier New'`;ctx.fillStyle='rgba(200,160,240,.6)';
      ctx.textAlign='center';
      ctx.fillText(`🔭 Vigiando | ⚠️×${this._detectedThreats} ameaças`,sx,sy+r*1.6+10*cam.zoom);
      ctx.textAlign='left';
    }
  }

  // ── SKIN 1: HUBBLE — cilindro metálico dourado/prateado + 2 painéis solares retangulares ──
  _drawHubble(r,T){
    const bodyLen=r*1.9,bodyW=r*.62;
    // Corpo cilíndrico principal
    const hullG=ctx.createLinearGradient(0,-bodyW,0,bodyW);
    hullG.addColorStop(0,'rgba(235,225,200,1)');
    hullG.addColorStop(.35,'rgba(190,175,140,1)');
    hullG.addColorStop(.5,'rgba(220,205,175,1)');
    hullG.addColorStop(.75,'rgba(160,145,115,1)');
    hullG.addColorStop(1,'rgba(210,195,165,1)');
    ctx.beginPath();
    ctx.moveTo(-bodyLen/2,-bodyW/2);ctx.lineTo(bodyLen/2,-bodyW/2);
    ctx.lineTo(bodyLen/2,bodyW/2);ctx.lineTo(-bodyLen/2,bodyW/2);
    ctx.closePath();ctx.fillStyle=hullG;ctx.fill();
    ctx.strokeStyle='rgba(255,245,220,.9)';ctx.lineWidth=Math.max(.7,r*.04);ctx.stroke();
    // Segmentação do casco (anéis do tubo, estilo Hubble)
    ctx.strokeStyle='rgba(120,105,80,.55)';ctx.lineWidth=Math.max(.4,r*.02);
    for(let i=1;i<6;i++){
      const lx=-bodyLen/2+bodyLen*(i/6);
      ctx.beginPath();ctx.moveTo(lx,-bodyW/2);ctx.lineTo(lx,bodyW/2);ctx.stroke();
    }
    // Ponta frontal (tampa da abertura óptica, levemente angulada)
    ctx.beginPath();
    ctx.moveTo(bodyLen/2,-bodyW/2);ctx.lineTo(bodyLen/2+r*.22,-bodyW*.32);
    ctx.lineTo(bodyLen/2+r*.22,bodyW*.32);ctx.lineTo(bodyLen/2,bodyW/2);
    ctx.closePath();ctx.fillStyle='rgba(60,55,50,.95)';ctx.fill();
    ctx.strokeStyle='rgba(200,190,160,.8)';ctx.lineWidth=Math.max(.5,r*.03);ctx.stroke();
    // Lente/abertura óptica escura no bico
    ctx.beginPath();ctx.ellipse(bodyLen/2+r*.2,0,r*.14,bodyW*.28,0,0,Math.PI*2);
    const lensG=ctx.createRadialGradient(bodyLen/2+r*.15,0,1,bodyLen/2+r*.2,0,r*.16);
    lensG.addColorStop(0,`rgba(180,210,255,${.6+.3*Math.sin(T*3)})`);
    lensG.addColorStop(1,'rgba(10,10,15,.95)');
    ctx.fillStyle=lensG;ctx.fill();
    // Antena de comunicação traseira (dish pequena)
    ctx.beginPath();ctx.moveTo(-bodyLen/2,-bodyW*.1);ctx.lineTo(-bodyLen/2-r*.3,-bodyW*.55);
    ctx.strokeStyle='rgba(200,190,160,.75)';ctx.lineWidth=Math.max(.4,r*.025);ctx.stroke();
    ctx.beginPath();ctx.ellipse(-bodyLen/2-r*.3,-bodyW*.55,r*.13,r*.09,.3,0,Math.PI*2);
    ctx.fillStyle='rgba(210,210,215,.85)';ctx.fill();
    ctx.strokeStyle='rgba(150,150,155,.8)';ctx.lineWidth=Math.max(.3,r*.015);ctx.stroke();
    // ── Dois painéis solares retangulares (um de cada lado, perpendiculares ao corpo) ──
    [-1,1].forEach(side=>{
      const px=0,py=side*(bodyW*.5+r*.12);
      const panelW=r*1.55,panelH=r*.42;
      ctx.save();ctx.translate(px,py+side*panelH*.5);
      // Haste de conexão
      ctx.beginPath();ctx.moveTo(0,-side*panelH*.5);ctx.lineTo(0,0);
      ctx.strokeStyle='rgba(180,170,150,.8)';ctx.lineWidth=Math.max(.5,r*.03);ctx.stroke();
      ctx.fillStyle='rgba(40,60,110,.95)';
      ctx.fillRect(-panelW/2,0,panelW,side*panelH);
      ctx.strokeStyle='rgba(220,210,190,.85)';ctx.lineWidth=Math.max(.5,r*.03);
      ctx.strokeRect(-panelW/2,0,panelW,side*panelH);
      // Grade de células solares
      ctx.strokeStyle='rgba(90,110,170,.7)';ctx.lineWidth=Math.max(.3,r*.015);
      for(let c=1;c<7;c++){
        const cx=-panelW/2+panelW*(c/7);
        ctx.beginPath();ctx.moveTo(cx,0);ctx.lineTo(cx,side*panelH);ctx.stroke();
      }
      ctx.beginPath();ctx.moveTo(-panelW/2,side*panelH*.5);ctx.lineTo(panelW/2,side*panelH*.5);ctx.stroke();
      // Brilho de reflexo solar animado
      ctx.fillStyle=`rgba(170,200,255,${.12+.1*Math.sin(T*.9+side*3)})`;
      ctx.fillRect(-panelW/2,0,panelW*.3,side*panelH);
      ctx.restore();
    });
  }

  // ── SKIN 2: JAMES WEBB — espelho hexagonal dourado segmentado + escudo solar em camadas ──
  _drawJWST(r,T){
    // Escudo solar (camadas romboides atrás do espelho, tom prateado/metálico)
    ctx.save();ctx.translate(0,r*.35);
    for(let layer=0;layer<3;layer++){
      const lw=r*(1.7-layer*.18),lh=r*(1.0-layer*.1);
      ctx.beginPath();
      ctx.moveTo(0,-lh/2);ctx.lineTo(lw/2,0);ctx.lineTo(0,lh/2);ctx.lineTo(-lw/2,0);ctx.closePath();
      ctx.fillStyle=`rgba(${190-layer*18},${185-layer*18},${170-layer*15},.9)`;
      ctx.fill();
      ctx.strokeStyle='rgba(140,135,120,.6)';ctx.lineWidth=Math.max(.3,r*.015);ctx.stroke();
    }
    ctx.restore();
    // Treliça de suporte conectando o espelho ao escudo solar
    ctx.strokeStyle='rgba(160,155,145,.8)';ctx.lineWidth=Math.max(.5,r*.03);
    [-1,0,1].forEach(off=>{
      ctx.beginPath();ctx.moveTo(off*r*.3,-r*.15);ctx.lineTo(off*r*.15,r*.35);ctx.stroke();
    });
    // ── Espelho primário hexagonal segmentado (dourado), voltado para frente ──
    const hexR=r*.82;
    ctx.save();ctx.translate(0,-r*.35);
    // 7 hexágonos menores compondo o espelho grande (1 central + 6 ao redor)
    const cellR=hexR*.36;
    const centers=[[0,0]];
    for(let i=0;i<6;i++){
      const a=i*(Math.PI/3);
      centers.push([Math.cos(a)*cellR*1.75,Math.sin(a)*cellR*1.75]);
    }
    centers.forEach(([cx,cy],idx)=>{
      ctx.save();ctx.translate(cx,cy);
      ctx.beginPath();
      for(let i=0;i<6;i++){
        const a=Math.PI/6+i*(Math.PI/3);
        const px=Math.cos(a)*cellR,py=Math.sin(a)*cellR;
        i===0?ctx.moveTo(px,py):ctx.lineTo(px,py);
      }
      ctx.closePath();
      const goldG=ctx.createRadialGradient(-cellR*.3,-cellR*.3,cellR*.1,0,0,cellR);
      goldG.addColorStop(0,`rgba(255,225,140,${.85+.15*Math.sin(T*2+idx)})`);
      goldG.addColorStop(.6,'rgba(230,180,70,.95)');
      goldG.addColorStop(1,'rgba(170,125,35,.95)');
      ctx.fillStyle=goldG;ctx.fill();
      ctx.strokeStyle='rgba(255,235,180,.8)';ctx.lineWidth=Math.max(.3,r*.014);ctx.stroke();
      ctx.restore();
    });
    ctx.restore();
    // Sensor/instrumento central sob o espelho
    ctx.beginPath();ctx.arc(0,r*.05,Math.max(.8,r*.09),0,Math.PI*2);
    ctx.fillStyle=`rgba(255,220,140,${.5+.4*Math.sin(T*4)})`;ctx.fill();
  }
}

// ═══════════════════════════════════════════════════════════════════
//  RAÇAS INTELIGENTES — Aliens, Marcianos, Reptilianos
// ═══════════════════════════════════════════════════════════════════

// ─── ALIEN ───────────────────────────────────────────────────────
// Coloniza estrelas construindo Esferas de Dyson. Atira laser em
// meteoros e cometas que se aproximam. É pacífico com Marcianos
// até que os Marcianos se rebelem — então entra em guerra.
const RACE_ALIEN   = 'entityAlien';
const RACE_MARCIAN = 'entityMarcian';
const RACE_REPTILIAN = 'entityReptilian';

class AlienEntity extends CelestialObject{
  constructor(wx,wy){
    super(wx,wy,RACE_ALIEN);
    this.radius=11;this.mass=0;this.fixed=true;
    this._t=0;
    this._colony=null;
    this._dyson=null;
    this._laser=null;
    this._laserCooldown=0;
    this._kills=0;
    this._warTarget=null;
    this._warMode=false;
    this._shield=1;
    // Visuais: 3 anéis orbitais independentes + 6 pods luminosos + núcleo pulsante
    this._rings=[
      {a:0,speed:.7,tilt:.22,r:1.7},
      {a:1.1,speed:-.5,tilt:.55,r:2.1},
      {a:2.4,speed:.35,tilt:.85,r:2.55},
    ];
    this._pods=Array.from({length:6},(_,i)=>({phase:i*(Math.PI*2/6),bright:rand(.6,1)}));
    this._thrusterFlare=0;
    this._scanPulse=0;
    // Perambulação livre
    this._vx=rand(-12,12);this._vy=rand(-12,12);
    this._steerAngle=Math.random()*Math.PI*2;
    this._steerNoise=0;
    this._wanderTimer=0;
    // Rastro verde
    this._trail=[];this._trailTimer=0;
    this.color='#44ffaa';
  }
  update(dt){
    this._t+=dt;
    this._thrusterFlare=Math.max(0,this._thrusterFlare-dt*2);
    this._scanPulse=Math.max(0,this._scanPulse-dt*.8);
    this._laserCooldown=Math.max(0,this._laserCooldown-dt);
    this._rings.forEach(r=>r.a+=r.speed*dt);
    // ── Perambulação orgânica Alien ── roda sempre, mesmo já colonizado:
    // depois de erguer a Esfera de Dyson, a nave não fica mais parada — ela
    // continua vagando sem rumo pelo mapa (a Esfera de Dyson fica ancorada
    // na estrela por conta própria, não precisa da nave por perto).
    {
      this._steerNoise+=dt*(0.55+Math.sin(this._t*0.13)*0.3);
      this._steerAngle+=Math.sin(this._steerNoise*1.7)*dt*0.9+Math.cos(this._steerNoise*0.8)*dt*0.4;
      const spd=16;
      const ax=Math.cos(this._steerAngle)*spd,ay=Math.sin(this._steerAngle)*spd;
      this._vx+=(ax-this._vx)*Math.min(1,dt*1.1);
      this._vy+=(ay-this._vy)*Math.min(1,dt*1.1);
      this.x+=this._vx*dt;this.y+=this._vy*dt;
      this._thrusterFlare=Math.min(1,this._thrusterFlare+dt*1.5);
    }
    // Rastro verde
    this._trailTimer+=dt;
    if(this._trailTimer>0.045){
      this._trailTimer=0;
      this._trail.push({x:this.x,y:this.y,a:1});
      if(this._trail.length>38) this._trail.shift();
    }
    this._trail.forEach(p=>{p.a=Math.max(0,p.a-dt*0.55);});
    if(this._laser){
      this._laser.t+=dt;
      if(this._laser.t>=this._laser.maxT){
        const tgt=this._laser.target;
        if(tgt&&!tgt.dead){
          tgt.dead=true;this._kills++;
          for(let k=0;k<10;k++) particles.push({x:tgt.x,y:tgt.y,vx:rand(-5,5),vy:rand(-5,5),r:rand(1,3),alpha:1,color:'#44ffcc'});
        }
        this._laser=null;
      }
    }
    if(this._warMode&&this._warTarget&&!this._warTarget.dead&&this._laserCooldown<=0){
      const d=dist(this,this._warTarget);
      if(d<400){
        this._laser={target:this._warTarget,t:0,maxT:1.4,
          x1:this.x,y1:this.y,x2:this._warTarget.x,y2:this._warTarget.y,war:true};
        this._laserCooldown=3;
        this._warTarget._shield=Math.max(0,(this._warTarget._shield||1)-.25);
        if(this._warTarget._shield<=0) this._warTarget.dead=true;
      }
      return;
    }
    if(!this._colony||this._colony.dead){
      this._colony=null;this._dyson=null;
      const star=objects.find(o=>!o.dead&&_PULSING_TYPES.includes(o.type)&&dist(this,o)<300&&
        !objects.some(d=>d.type==='techDysonSphere'&&d.host===o));
      if(star){
        this._colony=star;
        const ds=new DysonSphere(star.x,star.y);
        ds.attachTo(star);objects.push(ds);
        this._dyson=ds;
        this._thrusterFlare=1;
        showTooltip('👽 Alien colonizou uma estrela! Construindo Esfera de Dyson...');
      }
    }
    if(!this._warMode&&this._laserCooldown<=0){
      const threat=objects.find(o=>!o.dead&&(o.type==='meteor'||o.type==='comet')&&dist(this,o)<340);
      if(threat){
        this._laser={target:threat,t:0,maxT:.7,
          x1:this.x,y1:this.y,x2:threat.x,y2:threat.y,war:false};
        this._laserCooldown=1.8;
        this._scanPulse=1;
      }
    }
    if(!this._colony){
      const star=objects.find(o=>!o.dead&&_PULSING_TYPES.includes(o.type)&&dist(this,o)<600);
      if(star){const d=dist(this,star)||1;this.x+=(star.x-this.x)/d*20*dt;this.y+=(star.y-this.y)/d*20*dt;this._thrusterFlare=Math.min(1,this._thrusterFlare+dt);}
    }
    const rep=objects.find(o=>!o.dead&&o.type===RACE_REPTILIAN&&dist(this,o)<130);
    if(rep){this._shield=Math.max(0,this._shield-.45*dt);if(this._shield<=0)this.dead=true;}
  }
  draw(){
    const sx=this.sx(),sy=this.sy(),r=Math.max(7,this.radius*cam.zoom);
    const T=this._t;
    // ── Rastro verde Alien
    if(this._trail&&this._trail.length>1){
      for(let i=1;i<this._trail.length;i++){
        const p0=this._trail[i-1],p1=this._trail[i];
        const frac=i/this._trail.length;
        const tx0=(p0.x-cam.x)*cam.zoom+canvas.width*.5;
        const ty0=(p0.y-cam.y)*cam.zoom+canvas.height*.5;
        const tx1=(p1.x-cam.x)*cam.zoom+canvas.width*.5;
        const ty1=(p1.y-cam.y)*cam.zoom+canvas.height*.5;
        ctx.beginPath();ctx.moveTo(tx0,ty0);ctx.lineTo(tx1,ty1);
        ctx.strokeStyle=`rgba(60,255,140,${frac*p1.a*0.55})`;
        ctx.lineWidth=Math.max(0.5,r*0.18*frac);ctx.stroke();
      }
    }
    ctx.save();ctx.translate(sx,sy);

    // ── Propulsores traseiros (chama antes do corpo)
    if(this._thrusterFlare>0){
      for(let i=0;i<4;i++){
        const fa=Math.PI*.5+i*(Math.PI*2/4);
        const fx=Math.cos(fa)*r*.7,fy=Math.sin(fa)*r*.7;
        const fg=ctx.createRadialGradient(fx,fy,0,fx,fy,r*.55*this._thrusterFlare);
        fg.addColorStop(0,'rgba(120,255,200,.9)');fg.addColorStop(.5,'rgba(40,200,120,.4)');fg.addColorStop(1,'transparent');
        ctx.beginPath();ctx.arc(fx,fy,r*.55*this._thrusterFlare,0,Math.PI*2);ctx.fillStyle=fg;ctx.fill();
      }
    }

    // ── Disco principal — multicamadas com perspectiva
    // Sombra/aura exterior
    const aura=ctx.createRadialGradient(0,0,r*.8,0,0,r*2.4);
    aura.addColorStop(0,`rgba(60,255,160,${.12+.06*Math.sin(T*2)})`);aura.addColorStop(1,'transparent');
    ctx.beginPath();ctx.ellipse(0,0,r*2.4,r*2.4*.28,0,0,Math.PI*2);ctx.fillStyle=aura;ctx.fill();

    // Anel de força externo
    ctx.beginPath();ctx.ellipse(0,0,r*1.92,r*1.92*.22,0,0,Math.PI*2);
    ctx.strokeStyle=`rgba(80,255,180,${.35+.15*Math.sin(T*3)})`;ctx.lineWidth=Math.max(1,r*.08);ctx.stroke();

    // Corpo principal — disco achatado em 3 gradientes para dar volume
    const dg=ctx.createRadialGradient(-r*.2,-r*.06,0,0,0,r*1.18);
    dg.addColorStop(0,'rgba(200,255,230,.95)');dg.addColorStop(.35,'rgba(60,210,140,.88)');
    dg.addColorStop(.7,'rgba(20,140,90,.75)');dg.addColorStop(1,'rgba(10,60,40,.5)');
    ctx.beginPath();ctx.ellipse(0,0,r*1.18,r*1.18*.32,0,0,Math.PI*2);ctx.fillStyle=dg;ctx.fill();
    // Borda metálica
    ctx.beginPath();ctx.ellipse(0,0,r*1.18,r*1.18*.32,0,0,Math.PI*2);
    ctx.strokeStyle='rgba(160,255,210,.7)';ctx.lineWidth=Math.max(.8,r*.07);ctx.stroke();

    // Cúpula superior — semiesfera de cristal
    const domeGrad=ctx.createRadialGradient(-r*.15,-r*.35,0,0,-r*.18,r*.72);
    domeGrad.addColorStop(0,'rgba(240,255,248,.95)');domeGrad.addColorStop(.4,'rgba(120,230,190,.6)');domeGrad.addColorStop(1,'rgba(20,120,90,.15)');
    ctx.beginPath();ctx.ellipse(0,-r*.12,r*.72,r*.52,0,Math.PI,Math.PI*2);ctx.fillStyle=domeGrad;ctx.fill();
    // Aresta da cúpula
    ctx.beginPath();ctx.ellipse(0,-r*.12,r*.72,r*.52,0,Math.PI,Math.PI*2);
    ctx.strokeStyle='rgba(180,255,220,.5)';ctx.lineWidth=Math.max(.6,r*.05);ctx.stroke();
    // Reflexo especular na cúpula
    ctx.beginPath();ctx.ellipse(-r*.18,-r*.38,r*.18,r*.08,-.5,0,Math.PI*2);
    ctx.fillStyle='rgba(255,255,255,.55)';ctx.fill();

    // Pods de propulsão — 6 cápsulas ao redor do disco
    this._pods.forEach((p,i)=>{
      const pa=p.phase+T*.18;
      const px=Math.cos(pa)*r*1.05,py=Math.sin(pa)*r*1.05*.3;
      const pr=Math.max(1.5,r*.13);
      ctx.beginPath();ctx.ellipse(px,py,pr,pr*.55,pa,0,Math.PI*2);
      ctx.fillStyle=`rgba(100,255,180,${p.bright*(.55+.2*Math.sin(T*4+i))})`;ctx.fill();
      ctx.strokeStyle='rgba(180,255,210,.5)';ctx.lineWidth=.8;ctx.stroke();
    });

    // Anéis orbitais — giram em planos diferentes (simulação 3D)
    this._rings.forEach(rg=>{
      const scale=Math.abs(Math.cos(rg.tilt))*0.32+0.05;
      ctx.beginPath();ctx.ellipse(0,0,r*rg.r,r*rg.r*scale,rg.a,0,Math.PI*2);
      ctx.strokeStyle=`rgba(80,255,200,${.25+.1*Math.sin(T*2+rg.a)})`;
      ctx.lineWidth=Math.max(.8,r*.055);ctx.setLineDash([r*.22,r*.18]);ctx.stroke();ctx.setLineDash([]);
    });

    // Núcleo — pulsa com scan ativo
    const coreAlpha=this._scanPulse>0?.9:.6+.15*Math.sin(T*4);
    const coreColor=this._warMode?'255,80,60':(this._scanPulse>0?'255,255,120':'100,255,200');
    const cg=ctx.createRadialGradient(0,0,0,0,0,r*.28);
    cg.addColorStop(0,`rgba(${coreColor},${coreAlpha})`);cg.addColorStop(1,`rgba(${coreColor},.1)`);
    ctx.beginPath();ctx.arc(0,0,r*.28,0,Math.PI*2);ctx.fillStyle=cg;ctx.fill();

    ctx.restore();

    // ── Pulso de scan — anel expansivo ao detectar ameaça
    if(this._scanPulse>0){
      const sp=1-this._scanPulse;
      ctx.beginPath();ctx.arc(sx,sy,r*(1+sp*3),0,Math.PI*2);
      ctx.strokeStyle=`rgba(100,255,200,${this._scanPulse*.5})`;ctx.lineWidth=1.5;ctx.stroke();
    }

    // ── Laser ativo
    if(this._laser){
      const prog=this._laser.t/this._laser.maxT;
      const lx1=(this._laser.x1-cam.x)*cam.zoom+canvas.width*.5;
      const ly1=(this._laser.y1-cam.y)*cam.zoom+canvas.height*.5;
      const lx2=(this._laser.x2-cam.x)*cam.zoom+canvas.width*.5;
      const ly2=(this._laser.y2-cam.y)*cam.zoom+canvas.height*.5;
      const lc=this._laser.war?'255,60,60':'80,255,160';
      // Feixe principal
      ctx.beginPath();ctx.moveTo(lx1,ly1);ctx.lineTo(lx2,ly2);
      ctx.strokeStyle=`rgba(${lc},${.95-prog*.2})`;ctx.lineWidth=Math.max(2,3*cam.zoom);ctx.stroke();
      // Brilho do feixe
      ctx.beginPath();ctx.moveTo(lx1,ly1);ctx.lineTo(lx2,ly2);
      ctx.strokeStyle=`rgba(255,255,255,${(.4-prog*.3)})`;ctx.lineWidth=Math.max(.6,1*cam.zoom);ctx.stroke();
      // Flash na ponta
      ctx.beginPath();ctx.arc(lx2,ly2,Math.max(2,4*cam.zoom*(1-prog)),0,Math.PI*2);
      ctx.fillStyle=`rgba(${lc},.8)`;ctx.fill();
    }

    // ── Escudo de vida
    if(this._shield<1){
      ctx.beginPath();ctx.arc(sx,sy,r*2,0,Math.PI*2*this._shield);
      ctx.strokeStyle='rgba(60,255,160,.5)';ctx.lineWidth=2.5;ctx.stroke();
    }

    if(sandboxMode){
      ctx.font=`${Math.max(7,r*.48)}px 'Courier New'`;ctx.fillStyle='rgba(100,255,170,.65)';
      ctx.textAlign='center';
      ctx.fillText(`👽 ${this._warMode?'⚔️ GUERRA':'ALIEN'} | 💥${this._kills}${this._colony?' | 🌐 COLÔNIA':' | 🔍 BUSCA'}`,sx,sy+r*2.2+6*cam.zoom);
      ctx.textAlign='left';
    }
  }
}

// ─── MARCIANO ────────────────────────────────────────────────────
class MarcianEntity extends CelestialObject{
  constructor(wx,wy){
    super(wx,wy,RACE_MARCIAN);
    this.radius=10;this.mass=0;this.fixed=true;
    this._t=0;
    this._colony=null;
    this._matrioshka=null;
    this._elevator=null;
    this._rebelCooldown=rand(45,90);
    this._warMode=false;
    this._warTarget=null;
    this._shield=1;
    this._morale=0;
    this._rebelled=false;
    this._laserCooldown=0;
    this._laser=null;
    this._kills=0;
    // Visuais: nave marciana clássica em forma de pires invertido com 3 pernas,
    // antena, luzes pulsantes e trem de pouso retrátil
    this._legAngle=0;       // 0=recolhido, 1=aberto (pousando)
    this._legTimer=0;
    this._lights=Array.from({length:8},(_,i)=>({phase:i*(Math.PI*2/8),on:true}));
    this._rebelFlash=0;
    this._shockwave=[];     // ondas de choque ao se rebelar
    // Perambulação livre
    this._vx=rand(-10,10);this._vy=rand(-10,10);
    this._steerAngle=Math.random()*Math.PI*2;
    this._steerNoise=0;
    // Rastro marrom/laranja queimado
    this._trail=[];this._trailTimer=0;
    this.color='#66ff22';
  }
  update(dt){
    this._t+=dt;
    this._laserCooldown=Math.max(0,this._laserCooldown-dt);
    this._rebelFlash=Math.max(0,this._rebelFlash-dt*.7);
    this._shockwave=this._shockwave.filter(s=>(s.t+=dt)<1.2);
    if(this._laser){
      this._laser.t+=dt;
      if(this._laser.t>=this._laser.maxT){
        const tgt=this._laser.target;
        if(tgt&&!tgt.dead){
          tgt._shield=Math.max(0,(tgt._shield||1)-.3);
          if(tgt._shield<=0){tgt.dead=true;this._kills++;}
        }
        this._laser=null;
      }
    }
    const rep=objects.find(o=>!o.dead&&o.type===RACE_REPTILIAN&&dist(this,o)<130);
    if(rep){this._shield=Math.max(0,this._shield-.4*dt);if(this._shield<=0)this.dead=true;}
    const PLANET_TYPES=['planet','gasgiant','superearth','minineptune','dwarfplanet','lavaplt','oceanplt','desertplt','carbonplt','ironplt'];
    if(!this._colony||this._colony.dead){
      this._colony=null;this._matrioshka=null;this._elevator=null;
      this._legAngle=0;
      const pl=objects.find(o=>!o.dead&&PLANET_TYPES.includes(o.type)&&dist(this,o)<340&&
        !objects.some(m=>m.type==='techMatrioshkaBrain'&&m.host===o));
      if(pl){
        this._colony=pl;
        const mb=new MatrioshkaBrain(pl.x,pl.y);mb.attachTo(pl);objects.push(mb);this._matrioshka=mb;
        const ev=new SpaceElevator(pl.x,pl.y);ev.attachTo(pl);objects.push(ev);this._elevator=ev;
        showTooltip('🟢 Marciano colonizou um planeta! Construindo Matrioshka + Elevador...');
      } else {
        // Perambulação orgânica Marciana (busca planetas mas deriva enquanto não acha)
        this._steerNoise+=dt*(0.45+Math.cos(this._t*0.17)*0.25);
        this._steerAngle+=Math.sin(this._steerNoise*1.4)*dt*0.75+Math.cos(this._steerNoise*0.6)*dt*0.35;
        const nearest=objects.filter(o=>!o.dead&&PLANET_TYPES.includes(o.type))
          .sort((a,b)=>dist(this,a)-dist(this,b))[0];
        let tx=Math.cos(this._steerAngle),ty=Math.sin(this._steerAngle);
        if(nearest){
          const nd=dist(this,nearest)||1;
          const bx=(nearest.x-this.x)/nd,by=(nearest.y-this.y)/nd;
          // Mistura direção orgânica (40%) com atração ao planeta (60%)
          tx=tx*0.4+bx*0.6;ty=ty*0.4+by*0.6;
        }
        const spd=15;
        this._vx+=(tx*spd-this._vx)*Math.min(1,dt*1.0);
        this._vy+=(ty*spd-this._vy)*Math.min(1,dt*1.0);
        this.x+=this._vx*dt;this.y+=this._vy*dt;
      }
    } else {
      // Pernas de pouso abertas ao colonizar — nave freia
      this._legAngle=Math.min(1,this._legAngle+dt*1.5);
      this._vx*=(1-dt*2);this._vy*=(1-dt*2);
    }
    // Rastro marrom/laranja queimado
    this._trailTimer+=dt;
    if(this._trailTimer>0.05){
      this._trailTimer=0;
      this._trail.push({x:this.x,y:this.y,a:1});
      if(this._trail.length>34) this._trail.shift();
    }
    this._trail.forEach(p=>{p.a=Math.max(0,p.a-dt*0.5);});
    const alienNear=objects.some(o=>!o.dead&&o.type===RACE_ALIEN&&dist(this,o)<450);
    this._morale=Math.min(1,this._morale+dt*(alienNear?.009:.003));
    this._rebelCooldown=Math.max(0,this._rebelCooldown-dt);
    if(!this._rebelled&&this._rebelCooldown<=0&&this._morale>.7&&this._colony){
      this._rebelled=true;this._warMode=true;
      this._rebelFlash=1;
      this._shockwave.push({t:0});
      const alien=objects.find(o=>!o.dead&&o.type===RACE_ALIEN);
      if(alien){this._warTarget=alien;alien._warMode=true;alien._warTarget=this;}
      showTooltip('🟢💥 Marciano se rebelou! Guerra contra os Aliens declarada!');
    }
    if(this._warMode&&this._warTarget&&!this._warTarget.dead&&this._laserCooldown<=0){
      const d=dist(this,this._warTarget);
      if(d<380){
        this._laser={target:this._warTarget,t:0,maxT:1.1,x1:this.x,y1:this.y,x2:this._warTarget.x,y2:this._warTarget.y};
        this._laserCooldown=3.2;
      }
    }
  }
  draw(){
    const sx=this.sx(),sy=this.sy(),r=Math.max(7,this.radius*cam.zoom);
    const T=this._t;
    const war=this._warMode;
    // ── Rastro marrom/laranja queimado Marciano
    if(this._trail&&this._trail.length>1){
      for(let i=1;i<this._trail.length;i++){
        const p0=this._trail[i-1],p1=this._trail[i];
        const frac=i/this._trail.length;
        const tx0=(p0.x-cam.x)*cam.zoom+canvas.width*.5;
        const ty0=(p0.y-cam.y)*cam.zoom+canvas.height*.5;
        const tx1=(p1.x-cam.x)*cam.zoom+canvas.width*.5;
        const ty1=(p1.y-cam.y)*cam.zoom+canvas.height*.5;
        ctx.beginPath();ctx.moveTo(tx0,ty0);ctx.lineTo(tx1,ty1);
        const r0=war?220:180,g0=war?80:90,b0=10;
        ctx.strokeStyle=`rgba(${r0},${g0},${b0},${frac*p1.a*0.52})`;
        ctx.lineWidth=Math.max(0.5,r*0.17*frac);ctx.stroke();
      }
    }

    // ── Ondas de choque da rebelião
    this._shockwave.forEach(s=>{
      const sr=r*(1+s.t*6);
      ctx.beginPath();ctx.arc(sx,sy,sr,0,Math.PI*2);
      ctx.strokeStyle=`rgba(255,160,40,${(1-s.t/1.2)*.7})`;ctx.lineWidth=Math.max(1.5,r*.1*(1-s.t));ctx.stroke();
    });

    ctx.save();ctx.translate(sx,sy);

    // ══════════════════════════════════════════════
    //  NAVE MARCIANA — Máquina Industrial Steampunk
    //  Cores: âmbar, laranja queimado, marrom ferrugem
    // ══════════════════════════════════════════════

    // ── Sombra projetada no chão
    const shadowG=ctx.createRadialGradient(r*.1,r*.3,0,r*.1,r*.3,r*1.6);
    shadowG.addColorStop(0,'rgba(0,0,0,.35)');shadowG.addColorStop(1,'transparent');
    ctx.beginPath();ctx.ellipse(r*.1,r*.4,r*1.5,r*.4,0,0,Math.PI*2);ctx.fillStyle=shadowG;ctx.fill();

    // ── 4 BRAÇOS MECÂNICOS radiais (implantados no casco) que giram lentamente
    const armRot=T*.18;
    for(let i=0;i<4;i++){
      const aa=i*(Math.PI/2)+armRot;
      const ax1=Math.cos(aa)*r*.55, ay1=Math.sin(aa)*r*.22;
      const ax2=Math.cos(aa)*r*1.3, ay2=Math.sin(aa)*r*.5;
      // Braço principal
      ctx.beginPath();ctx.moveTo(ax1,ay1);ctx.lineTo(ax2,ay2);
      ctx.strokeStyle=`rgba(${war?'200,80,20':'160,90,30'},.85)`;ctx.lineWidth=Math.max(2,r*.11);ctx.stroke();
      // Revestimento metálico do braço
      ctx.beginPath();ctx.moveTo(ax1,ay1);ctx.lineTo(ax2,ay2);
      ctx.strokeStyle=`rgba(${war?'255,140,40':'210,130,50'},.4)`;ctx.lineWidth=Math.max(.8,r*.04);ctx.stroke();
      // Caixa de mecanismo na extremidade
      ctx.save();ctx.translate(ax2,ay2);ctx.rotate(aa);
      const bw=Math.max(2,r*.18),bh=Math.max(1.5,r*.1);
      ctx.fillStyle=`rgba(${war?'180,70,10':'130,70,20'},.9)`;
      ctx.fillRect(-bw*.5,-bh*.5,bw,bh);
      ctx.strokeStyle=`rgba(${war?'255,160,60':'220,150,60'},.7)`;ctx.lineWidth=Math.max(.5,r*.03);
      ctx.strokeRect(-bw*.5,-bh*.5,bw,bh);
      ctx.restore();
    }

    // ── 3 ENGRENAGENS GIRATÓRIAS no anel externo
    const gearRot=T*.55;
    for(let g=0;g<3;g++){
      const ga=g*(Math.PI*2/3)+gearRot;
      const gx=Math.cos(ga)*r*.88, gy=Math.sin(ga)*r*.38;
      const gr=Math.max(2,r*.15);
      ctx.save();ctx.translate(gx,gy);ctx.rotate(T*(g%2===0?1.1:-0.9));
      // Corpo da engrenagem
      ctx.beginPath();ctx.arc(0,0,gr,0,Math.PI*2);
      ctx.fillStyle=`rgba(${war?'160,60,10':'110,60,15'},.95)`;ctx.fill();
      ctx.strokeStyle=`rgba(${war?'255,140,50':'200,140,50'},.8)`;ctx.lineWidth=Math.max(.5,r*.03);ctx.stroke();
      // Dentes da engrenagem (8 dentes)
      for(let d=0;d<8;d++){
        const da=d*(Math.PI/4);
        const dx1=Math.cos(da)*(gr-.5),dy1=Math.sin(da)*(gr-.5);
        const dx2=Math.cos(da)*(gr+Math.max(1,r*.06)),dy2=Math.sin(da)*(gr+Math.max(1,r*.06));
        ctx.beginPath();ctx.moveTo(dx1,dy1);ctx.lineTo(dx2,dy2);
        ctx.strokeStyle=`rgba(${war?'220,110,30':'180,110,30'},.9)`;ctx.lineWidth=Math.max(1,r*.05);ctx.stroke();
      }
      // Furo central da engrenagem
      ctx.beginPath();ctx.arc(0,0,Math.max(.8,gr*.35),0,Math.PI*2);
      ctx.fillStyle=`rgba(${war?'80,20,5':'50,25,5'},.95)`;ctx.fill();
      ctx.restore();
    }

    // ── CASCO PRINCIPAL — octógono industrial achatado
    const bodyG=ctx.createRadialGradient(-r*.25,-r*.15,0,0,0,r*.95);
    bodyG.addColorStop(0,`rgba(${war?'255,180,60':'230,150,50'},1)`);
    bodyG.addColorStop(.35,`rgba(${war?'200,100,20':'170,100,25'},.95)`);
    bodyG.addColorStop(.7,`rgba(${war?'120,50,8':'100,55,12'},.9)`);
    bodyG.addColorStop(1,`rgba(${war?'60,20,3':'55,28,5'},.7)`);
    ctx.beginPath();
    for(let i=0;i<8;i++){
      const oa=i*(Math.PI/4)+Math.PI/8;
      const ox=Math.cos(oa)*r*.9*(i%2===0?1:.82);
      const oy=Math.sin(oa)*r*.42*(i%2===0?1:.82);
      i===0?ctx.moveTo(ox,oy):ctx.lineTo(ox,oy);
    }
    ctx.closePath();ctx.fillStyle=bodyG;ctx.fill();
    // Borda do casco com rebites
    ctx.beginPath();
    for(let i=0;i<8;i++){
      const oa=i*(Math.PI/4)+Math.PI/8;
      const ox=Math.cos(oa)*r*.9*(i%2===0?1:.82);
      const oy=Math.sin(oa)*r*.42*(i%2===0?1:.82);
      i===0?ctx.moveTo(ox,oy):ctx.lineTo(ox,oy);
    }
    ctx.closePath();
    ctx.strokeStyle=`rgba(${war?'255,150,40':'210,140,50'},.85)`;ctx.lineWidth=Math.max(1,r*.07);ctx.stroke();

    // ── REBITES no casco (12 rebites circulares)
    for(let b=0;b<8;b++){
      const ba=b*(Math.PI/4)+Math.PI/8;
      const bx=Math.cos(ba)*r*.72*(b%2===0?1:.84);
      const by=Math.sin(ba)*r*.33*(b%2===0?1:.84);
      ctx.beginPath();ctx.arc(bx,by,Math.max(.8,r*.04),0,Math.PI*2);
      ctx.fillStyle=`rgba(${war?'255,200,80':'240,190,80'},1)`;ctx.fill();
      ctx.strokeStyle=`rgba(${war?'180,80,10':'120,70,10'},.8)`;ctx.lineWidth=Math.max(.3,r*.02);ctx.stroke();
    }

    // ── PLATAFORMA INFERIOR — disco de emissão de calor
    ctx.beginPath();ctx.ellipse(0,r*.12,r*.75,r*.2,0,0,Math.PI*2);
    const heatG=ctx.createRadialGradient(0,r*.12,0,0,r*.12,r*.75);
    heatG.addColorStop(0,`rgba(${war?'255,120,20':'255,140,30'},.7)`);
    heatG.addColorStop(.6,`rgba(${war?'160,50,5':'140,70,10'},.4)`);
    heatG.addColorStop(1,'transparent');
    ctx.fillStyle=heatG;ctx.fill();
    ctx.beginPath();ctx.ellipse(0,r*.12,r*.75,r*.2,0,0,Math.PI*2);
    ctx.strokeStyle=`rgba(${war?'255,140,40':'200,130,40'},.5)`;ctx.lineWidth=Math.max(.6,r*.04);ctx.stroke();
    // Calor pulsante saindo embaixo
    const heatPulse=.4+.3*Math.sin(T*4);
    ctx.beginPath();ctx.ellipse(0,r*.25,r*.4,r*.1,0,0,Math.PI*2);
    ctx.fillStyle=`rgba(255,${war?80:120},10,${heatPulse*.5})`;ctx.fill();

    // ── DUTO CENTRAL de vapor — tubo vertical no meio
    ctx.fillStyle=`rgba(${war?'140,55,8':'90,50,12'},.9)`;
    ctx.fillRect(-Math.max(1.5,r*.07),-r*.55,Math.max(3,r*.14),r*.55);
    ctx.strokeStyle=`rgba(${war?'220,120,40':'170,110,40'},.7)`;ctx.lineWidth=Math.max(.5,r*.03);
    ctx.strokeRect(-Math.max(1.5,r*.07),-r*.55,Math.max(3,r*.14),r*.55);
    // Emissão de vapor no topo do duto
    for(let v=0;v<3;v++){
      const vpha=Math.sin(T*3+v*1.3);
      ctx.beginPath();ctx.arc(rand(-r*.06,r*.06),-r*.58-v*r*.08,Math.max(.5,r*.04*(1+v*.3)),0,Math.PI*2);
      ctx.fillStyle=`rgba(220,180,120,${(.25-.07*v)*(.5+.5*vpha)})`;ctx.fill();
    }

    // ── CÚPULA SUPERIOR — vidro âmbar reforçado com frisos
    const dG=ctx.createRadialGradient(-r*.15,-r*.45,0,0,-r*.25,r*.58);
    dG.addColorStop(0,`rgba(${war?'255,220,120':'250,210,120'},.9)`);
    dG.addColorStop(.4,`rgba(${war?'200,120,30':'180,120,40'},.6)`);
    dG.addColorStop(1,`rgba(${war?'80,30,5':'60,30,8'},.2)`);
    ctx.beginPath();ctx.ellipse(0,-r*.22,r*.58,r*.44,0,Math.PI,Math.PI*2);ctx.fillStyle=dG;ctx.fill();
    // Friso da cúpula (anéis concêntricos de reforço)
    for(let fr=0;fr<3;fr++){
      const fsc=.55-.12*fr;
      ctx.beginPath();ctx.ellipse(0,-r*.22,r*fsc,r*.44*fsc,0,Math.PI,Math.PI*2);
      ctx.strokeStyle=`rgba(${war?'255,150,50':'200,140,50'},${.4-.1*fr})`;ctx.lineWidth=Math.max(.4,r*.025);ctx.stroke();
    }
    // Borda da cúpula
    ctx.beginPath();ctx.ellipse(0,-r*.22,r*.58,r*.44,0,Math.PI,Math.PI*2);
    ctx.strokeStyle=`rgba(${war?'255,130,30':'190,130,40'},.8)`;ctx.lineWidth=Math.max(.7,r*.05);ctx.stroke();
    // Reflexo na cúpula
    ctx.beginPath();ctx.ellipse(-r*.14,-r*.46,r*.13,r*.06,-.35,0,Math.PI*2);
    ctx.fillStyle='rgba(255,240,200,.45)';ctx.fill();

    // ── ENGRENAGEM CENTRAL grande (no centro do casco) — decorativa/funcional
    const cgr=Math.max(2,r*.2);
    ctx.save();ctx.rotate(T*.4);
    ctx.beginPath();ctx.arc(0,0,cgr,0,Math.PI*2);
    ctx.fillStyle=`rgba(${war?'100,40,5':'75,40,8'},.95)`;ctx.fill();
    for(let d=0;d<10;d++){
      const da=d*(Math.PI/5);
      ctx.beginPath();
      ctx.moveTo(Math.cos(da)*(cgr-.5),Math.sin(da)*(cgr-.5));
      ctx.lineTo(Math.cos(da)*(cgr+Math.max(1,r*.05)),Math.sin(da)*(cgr+Math.max(1,r*.05)));
      ctx.strokeStyle=`rgba(${war?'255,150,50':'200,140,50'},.9)`;ctx.lineWidth=Math.max(1,r*.055);ctx.stroke();
    }
    ctx.beginPath();ctx.arc(0,0,Math.max(.5,cgr*.4),0,Math.PI*2);
    ctx.fillStyle=`rgba(${war?'255,180,60':'230,170,60'},.9)`;ctx.fill();
    ctx.restore();

    // ── PISTÕES laterais (2 pistões comprimindo/expandindo)
    for(let p=0;p<2;p++){
      const ps=p===0?-1:1;
      const pistonY=Math.sin(T*2.5+p*Math.PI)*.12;
      const px=ps*r*.65, py=-r*.05+pistonY*r*.15;
      // Cilindro
      ctx.fillStyle=`rgba(${war?'120,50,8':'80,45,10'},.9)`;
      ctx.fillRect(px-Math.max(1,r*.04),py-Math.max(2,r*.12),Math.max(2,r*.08),Math.max(4,r*.24));
      // Haste do pistão
      ctx.fillStyle=`rgba(${war?'230,140,50':'190,140,50'},.85)`;
      ctx.fillRect(px-Math.max(.5,r*.025),py+pistonY*r*.2,Math.max(1,r*.05),Math.max(2,r*.14));
      // Anel vedante
      ctx.beginPath();ctx.arc(px,py,Math.max(1,r*.05),0,Math.PI*2);
      ctx.fillStyle=`rgba(${war?'255,160,50':'220,160,50'},.9)`;ctx.fill();
    }

    // ── LUZES PISCANTES — lanternas industriais âmbar
    this._lights.forEach((l,i)=>{
      const la=i*(Math.PI*2/8)+T*.05;
      const lx=Math.cos(la)*r*.88,ly=Math.sin(la)*r*.38;
      const blink=Math.sin(T*4.5+i*1.2)>.15;
      if(blink){
        const lc=war?`rgba(255,${60+i*12},0,.95)`:`rgba(255,${160+i*8},40,.95)`;
        ctx.shadowColor=lc;ctx.shadowBlur=4;
        ctx.beginPath();ctx.arc(lx,ly,Math.max(1,r*.07),0,Math.PI*2);
        ctx.fillStyle=lc;ctx.fill();
        ctx.shadowBlur=0;
      }
    });

    // ── Flash de rebelião
    if(this._rebelFlash>0){
      const fg=ctx.createRadialGradient(0,0,0,0,0,r*3*this._rebelFlash);
      fg.addColorStop(0,`rgba(255,140,0,${this._rebelFlash*.5})`);fg.addColorStop(1,'transparent');
      ctx.beginPath();ctx.arc(0,0,r*3*this._rebelFlash,0,Math.PI*2);ctx.fillStyle=fg;ctx.fill();
    }

    ctx.restore();

    // ── BRAÇOS DE MECANISMO sobre astros (elevador em planeta, extrator em estrela)
    if(this._colony&&!this._colony.dead){
      const cx=(this._colony.x-cam.x)*cam.zoom+canvas.width*.5;
      const cy=(this._colony.y-cam.y)*cam.zoom+canvas.height*.5;
      const cr=Math.max(4,this._colony.radius*cam.zoom);
      // Cabo do elevador
      ctx.beginPath();ctx.moveTo(sx,sy);ctx.lineTo(cx,cy-cr);
      ctx.strokeStyle='rgba(210,150,50,.45)';ctx.lineWidth=Math.max(.8,cam.zoom*.7);
      ctx.setLineDash([Math.max(2,r*.15),Math.max(2,r*.1)]);ctx.stroke();ctx.setLineDash([]);
      // Gôndola do mecanismo descendo
      const gondT=((T*.15)%1);
      const gx=sx+(cx-sx)*gondT;
      const gy=sy+(cy-cr-sy)*gondT;
      ctx.beginPath();ctx.rect(gx-Math.max(2,r*.1),gy-Math.max(1.5,r*.08),Math.max(4,r*.2),Math.max(3,r*.16));
      ctx.fillStyle='rgba(200,140,40,.85)';ctx.fill();
      ctx.strokeStyle='rgba(255,200,80,.7)';ctx.lineWidth=Math.max(.5,r*.03);ctx.stroke();
    }

    // ── Laser de guerra (plasma âmbar)
    if(this._laser){
      const prog=this._laser.t/this._laser.maxT;
      const lx1=(this._laser.x1-cam.x)*cam.zoom+canvas.width*.5;
      const ly1=(this._laser.y1-cam.y)*cam.zoom+canvas.height*.5;
      const lx2=(this._laser.x2-cam.x)*cam.zoom+canvas.width*.5;
      const ly2=(this._laser.y2-cam.y)*cam.zoom+canvas.height*.5;
      // Raio principal âmbar
      ctx.beginPath();ctx.moveTo(lx1,ly1);ctx.lineTo(lx2,ly2);
      ctx.strokeStyle=`rgba(255,180,40,${.95-prog*.3})`;ctx.lineWidth=Math.max(2,3*cam.zoom);ctx.stroke();
      // Núcleo branco quente
      ctx.beginPath();ctx.moveTo(lx1,ly1);ctx.lineTo(lx2,ly2);
      ctx.strokeStyle=`rgba(255,240,180,${.5-prog*.3})`;ctx.lineWidth=Math.max(.6,cam.zoom*.8);ctx.stroke();
      // Partículas de faísca na ponta
      const fx=(lx2-lx1)*prog+lx1, fy=(ly2-ly1)*prog+ly1;
      ctx.beginPath();ctx.arc(fx,fy,Math.max(2,r*.15*cam.zoom*(1-prog)),0,Math.PI*2);
      ctx.fillStyle=`rgba(255,220,80,${.8-prog*.5})`;ctx.fill();
    }

    // ── Barra de moral (âmbar/laranja industrial)
    if(!this._rebelled){
      const bw=r*2.8,bh=Math.max(3,r*.2);
      const bx=sx-bw*.5,by=sy+r*1.6+4*cam.zoom;
      ctx.fillStyle='rgba(30,18,5,.8)';ctx.fillRect(bx,by,bw,bh);
      const mc=this._morale>.8?'rgba(255,60,0,.9)':this._morale>.5?'rgba(255,150,20,.85)':'rgba(210,140,30,.8)';
      ctx.fillStyle=mc;ctx.fillRect(bx,by,bw*this._morale,bh);
      ctx.strokeStyle='rgba(200,130,40,.5)';ctx.lineWidth=.8;ctx.strokeRect(bx,by,bw,bh);
    }
    if(this._shield<1){
      ctx.beginPath();ctx.arc(sx,sy,r*1.8,0,Math.PI*2*this._shield);
      ctx.strokeStyle='rgba(255,180,40,.5)';ctx.lineWidth=2.5;ctx.stroke();
    }
    if(sandboxMode){
      ctx.font=`${Math.max(7,r*.46)}px 'Courier New'`;
      ctx.fillStyle=war?'rgba(255,120,30,.8)':'rgba(220,160,50,.75)';
      ctx.textAlign='center';
      ctx.fillText(`⚙️ ${war?'⚔️ REBELIÃO':'MARCIANO'}${this._colony?' | 🏗️ COLÔNIA':' | 🔍 BUSCA'} | ${Math.round(this._morale*100)}%`,sx,sy+r*2+6*cam.zoom);
      ctx.textAlign='left';
    }
  }
}

// ─── REPTILIANO ──────────────────────────────────────────────────
let _reptilianEverCreated=false;
let _escamaDropped=false;
let _escamaActive=false;

class ReptilianEntity extends CelestialObject{
  constructor(wx,wy){
    super(wx,wy,RACE_REPTILIAN);
    this.radius=14;this.mass=0;this.fixed=true;
    this._t=0;
    this._slaves=[];
    this._huntTarget=null;
    this._strike=null;
    this._strikeCD=0;
    this._enslaved=0;
    this._shield=3;
    // Visuais: serpente/dragão espacial — corpo segmentado hexagonal
    // com espinhos, crista dorsal, cauda e olhos compostos
    this._segments=Array.from({length:7},(_,i)=>({
      ox:rand(-2,2),oy:rand(-2,2),
      phase:i*.55,
      scaleX:1-i*.07,
      spineH:1-i*.1
    }));
    this._eyePulse=0;
    this._chargeRing=0;   // 0..1 — anel de energia antes do ataque
    this._strikeFlash=0;
    this._tailSway=0;
    this._auraRot=0;
    this._angle=rand(0,Math.PI*2);           // ângulo atual da nave
    this._angleVel=rand(.4,.9)*(Math.random()<.5?1:-1); // spin livre inicial
    this._vx=rand(-14,14);this._vy=rand(-14,14);
    this._steerNoise=0;
    // Rastro vermelho
    this._trail=[];this._trailTimer=0;
    this.color='#cc3300';
    _reptilianEverCreated=true;
  }
  update(dt){
    this._t+=dt;
    this._strikeCD=Math.max(0,this._strikeCD-dt);
    this._eyePulse=Math.max(0,this._eyePulse-dt*1.5);
    this._strikeFlash=Math.max(0,this._strikeFlash-dt*2);
    this._auraRot+=dt*.4;
    this._tailSway=Math.sin(this._t*1.8)*.35;
    // Pré-ataque: anel de carga cresce quando alvo detectado
    if(this._huntTarget&&!this._huntTarget.dead&&!this._huntTarget._enslaved&&this._strikeCD<2){
      this._chargeRing=Math.min(1,this._chargeRing+dt*.8);
    } else {
      this._chargeRing=Math.max(0,this._chargeRing-dt*1.5);
    }
    if(this._strike){
      this._strike.t+=dt;
      if(this._strike.t>=this._strike.maxT){
        const tgt=this._strike.target;
        if(tgt&&!tgt.dead){
          if(tgt instanceof InvasionFleetEntity){
            // Contra a Frota Militar não há escravização — é combate direto.
            tgt.takeDamage(1400+Math.random()*700);
            this._strikeFlash=1;this._eyePulse=1;
            showTooltip('🦎 Uma Nave Reptiliana atacou a Frota Alienígena Militar!');
          } else {
            tgt._enslaved=true;tgt._masterRep=this;tgt._warMode=false;
            tgt.color='#553300';this._slaves.push(tgt);this._enslaved++;
            this._strikeFlash=1;this._eyePulse=1;
            showTooltip(`🦎 Reptiliano escravizou um ${tgt.type===RACE_ALIEN?'Alien':'Marciano'}!`);
            // 40% de chance de dropar Escama Robótica ao escravizar
            if(!_escamaActive&&Math.random()<0.40) _triggerEscamaDrop();
          }
        }
        this._strike=null;
      }
    }
    this._slaves=this._slaves.filter(s=>!s.dead);
    if(!this._huntTarget||this._huntTarget.dead||this._huntTarget._enslaved||(this._huntTarget instanceof InvasionFleetEntity&&this._huntTarget.hp<=0)){
      // Prioriza a Frota Militar quando ela está por perto — é o alvo mais
      // ameaçador; senão, caça Alienígenas/Marcianos comuns para escravizar.
      this._huntTarget=objects.find(o=>!o.dead&&o instanceof InvasionFleetEntity&&dist(this,o)<650)||
        objects.find(o=>!o.dead&&!o._enslaved&&
        (o.type===RACE_ALIEN||o.type===RACE_MARCIAN)&&dist(this,o)<550);
    }
    if(this._huntTarget&&!this._huntTarget.dead&&!this._huntTarget._enslaved){
      const d=dist(this,this._huntTarget)||1;
      if(d>70){/* movimento gerenciado por _vx/_vy abaixo */}
      else if(this._strikeCD<=0){
        this._strike={target:this._huntTarget,t:0,maxT:.6,x1:this.x,y1:this.y,x2:this._huntTarget.x,y2:this._huntTarget.y};
        this._strikeCD=4.5;this._chargeRing=0;
      }
      // Aponta o nariz (vértice topo) suavemente para o alvo
      const targetAngle=Math.atan2(this._huntTarget.y-this.y,this._huntTarget.x-this.x)+Math.PI*.5;
      let diff=targetAngle-this._angle;
      while(diff>Math.PI)diff-=Math.PI*2;
      while(diff<-Math.PI)diff+=Math.PI*2;
      this._angleVel+=(diff*3.5-this._angleVel)*Math.min(1,dt*2.8);
      this._angle+=this._angleVel*dt;
    } else {
      // Sem alvo: spin livre com variação orgânica
      this._angleVel*=(1-dt*.18);
      if(Math.abs(this._angleVel)<.25) this._angleVel+=rand(.15,.5)*(Math.random()<.5?1:-1)*dt*4;
      this._angle+=this._angleVel*dt;
    }
    this._slaves.forEach((s,i)=>{
      if(s.dead)return;
      const oa=this._t*.5+i*(Math.PI*2/Math.max(1,this._slaves.length));
      s.x+=(this.x+Math.cos(oa)*90-s.x)*.06;
      s.y+=(this.y+Math.sin(oa)*90-s.y)*.06;
    });
    // ── Perambulação translacional Reptiliana
    if(!this._huntTarget||this._huntTarget.dead||this._huntTarget._enslaved){
      // Sem alvo: deriva orgânica usando o ângulo atual da nave como direção base
      this._steerNoise+=dt*(0.6+Math.sin(this._t*0.19)*0.28);
      const drift=Math.sin(this._steerNoise*1.9)*0.85+Math.cos(this._steerNoise*0.7)*0.4;
      const moveAngle=this._angle-Math.PI*0.5+drift*dt*0.5;
      const spd=18;
      this._vx+=(Math.cos(moveAngle)*spd-this._vx)*Math.min(1,dt*0.95);
      this._vy+=(Math.sin(moveAngle)*spd-this._vy)*Math.min(1,dt*0.95);
    } else {
      // Com alvo: avança em direção a ele (movimento já existe no bloco acima)
      const spd=24;
      const dx=this._huntTarget.x-this.x,dy=this._huntTarget.y-this.y;
      const nd=Math.sqrt(dx*dx+dy*dy)||1;
      this._vx+=(dx/nd*spd-this._vx)*Math.min(1,dt*1.2);
      this._vy+=(dy/nd*spd-this._vy)*Math.min(1,dt*1.2);
    }
    this.x+=this._vx*dt;this.y+=this._vy*dt;
    // Rastro vermelho
    this._trailTimer+=dt;
    if(this._trailTimer>0.042){
      this._trailTimer=0;
      this._trail.push({x:this.x,y:this.y,a:1});
      if(this._trail.length>40) this._trail.shift();
    }
    this._trail.forEach(p=>{p.a=Math.max(0,p.a-dt*0.5);});
  }
  draw(){
    const sx=this.sx(),sy=this.sy(),r=Math.max(9,this.radius*cam.zoom);
    const T=this._t;
    // ── Rastro vermelho Reptiliano
    if(this._trail&&this._trail.length>1){
      for(let i=1;i<this._trail.length;i++){
        const p0=this._trail[i-1],p1=this._trail[i];
        const frac=i/this._trail.length;
        const tx0=(p0.x-cam.x)*cam.zoom+canvas.width*.5;
        const ty0=(p0.y-cam.y)*cam.zoom+canvas.height*.5;
        const tx1=(p1.x-cam.x)*cam.zoom+canvas.width*.5;
        const ty1=(p1.y-cam.y)*cam.zoom+canvas.height*.5;
        ctx.beginPath();ctx.moveTo(tx0,ty0);ctx.lineTo(tx1,ty1);
        ctx.strokeStyle=`rgba(220,20,20,${frac*p1.a*0.58})`;
        ctx.lineWidth=Math.max(0.5,r*0.19*frac);ctx.stroke();
      }
    }

    // ══════════════════════════════════════════════
    //  NAVE REPTILIANA — Destruidor Triangular Militar
    //  Cinza aço, jatos na base, canhões laterais,
    //  listra vermelha central, altamente detalhada
    // ══════════════════════════════════════════════

    // ── Anel de carga pré-ataque
    if(this._chargeRing>0){
      const cr=this._chargeRing;
      for(let i=0;i<3;i++){
        const ringR=r*(1.6+i*.5)*cr;
        ctx.beginPath();ctx.arc(sx,sy,ringR,0,Math.PI*2);
        ctx.strokeStyle=`rgba(220,20,0,${cr*(.35-i*.08)})`;
        ctx.lineWidth=Math.max(.8,r*.06*(1-i*.2));ctx.stroke();
      }
    }

    ctx.save();ctx.translate(sx,sy);ctx.rotate(this._angle);

    // ── Sombra profunda sob a nave
    const shadowG=ctx.createRadialGradient(r*.08,r*.5,0,r*.08,r*.5,r*1.8);
    shadowG.addColorStop(0,'rgba(0,0,0,.45)');shadowG.addColorStop(1,'transparent');
    ctx.beginPath();ctx.ellipse(r*.08,r*.55,r*1.5,r*.38,0,0,Math.PI*2);
    ctx.fillStyle=shadowG;ctx.fill();

    // ── JATOS TRASEIROS — 3 propulsores na base larga do triângulo
    // A nave aponta para CIMA (vértice topo), base larga embaixo
    const jetY=r*.72;
    const jetPositions=[-r*.55,0,r*.55];
    jetPositions.forEach((jx,ji)=>{
      // Câmara do propulsor
      const jw=Math.max(2,r*.16), jh=Math.max(3,r*.18);
      const jG=ctx.createLinearGradient(jx-jw,jetY,jx+jw,jetY);
      jG.addColorStop(0,'rgba(40,40,45,1)');jG.addColorStop(.5,'rgba(80,82,88,1)');jG.addColorStop(1,'rgba(40,40,45,1)');
      ctx.fillStyle=jG;ctx.fillRect(jx-jw,jetY,jw*2,jh);
      ctx.strokeStyle='rgba(120,120,130,.8)';ctx.lineWidth=Math.max(.5,r*.03);
      ctx.strokeRect(jx-jw,jetY,jw*2,jh);
      // Anel interno do bocal
      ctx.beginPath();ctx.ellipse(jx,jetY+jh*.3,jw*.65,jw*.3,0,0,Math.PI*2);
      ctx.fillStyle='rgba(20,20,22,1)';ctx.fill();
      ctx.strokeStyle='rgba(150,150,160,.7)';ctx.lineWidth=Math.max(.4,r*.025);ctx.stroke();
      // Chama do jato (animada)
      const flamePulse=.6+.4*Math.abs(Math.sin(T*6+ji*1.1));
      const flameLen=r*(.45+.25*flamePulse);
      const flameG=ctx.createLinearGradient(jx,jetY+jh,jx,jetY+jh+flameLen);
      flameG.addColorStop(0,'rgba(255,220,180,.95)');
      flameG.addColorStop(.25,'rgba(255,120,40,.8)');
      flameG.addColorStop(.65,'rgba(180,50,200,.5)');
      flameG.addColorStop(1,'rgba(80,10,120,0)');
      ctx.beginPath();ctx.ellipse(jx,jetY+jh+flameLen*.4,jw*.5*flamePulse,flameLen*.6,0,0,Math.PI*2);
      ctx.fillStyle=flameG;ctx.fill();
      // Anel de calor na saída
      ctx.beginPath();ctx.ellipse(jx,jetY+jh,jw*.7,jw*.25,0,0,Math.PI*2);
      ctx.fillStyle=`rgba(255,200,100,${.4*flamePulse})`;ctx.fill();
    });

    // ── CASCO TRIANGULAR PRINCIPAL
    // Vértice no topo, base larga em baixo — triângulo com ângulos abaulados
    const tipX=0, tipY=-r*.92;
    const baseLX=-r*.98, baseRX=r*.98, baseY=r*.68;
    // Painel de sombra traseiro (profundidade)
    ctx.beginPath();
    ctx.moveTo(tipX+r*.04,tipY+r*.06);
    ctx.lineTo(baseRX+r*.04,baseY+r*.06);
    ctx.lineTo(baseLX+r*.04,baseY+r*.06);
    ctx.closePath();
    ctx.fillStyle='rgba(0,0,0,.3)';ctx.fill();

    // Gradiente do casco — cinza aço com reflexo de luz lateral esquerda
    const hullG=ctx.createLinearGradient(-r*.9,-r*.8,r*.9,r*.6);
    hullG.addColorStop(0,'rgba(165,168,175,1)');
    hullG.addColorStop(.22,'rgba(195,198,205,1)');
    hullG.addColorStop(.45,'rgba(145,148,155,1)');
    hullG.addColorStop(.72,'rgba(90,93,100,1)');
    hullG.addColorStop(1,'rgba(55,57,62,1)');
    ctx.beginPath();
    ctx.moveTo(tipX,tipY);
    ctx.lineTo(baseRX,baseY);
    ctx.lineTo(baseLX,baseY);
    ctx.closePath();
    ctx.fillStyle=hullG;ctx.fill();

    // Borda principal do casco — dupla linha para profundidade
    ctx.beginPath();ctx.moveTo(tipX,tipY);ctx.lineTo(baseRX,baseY);ctx.lineTo(baseLX,baseY);ctx.closePath();
    ctx.strokeStyle='rgba(200,202,210,.9)';ctx.lineWidth=Math.max(1.2,r*.07);ctx.stroke();
    ctx.beginPath();ctx.moveTo(tipX,tipY);ctx.lineTo(baseRX,baseY);ctx.lineTo(baseLX,baseY);ctx.closePath();
    ctx.strokeStyle='rgba(50,52,58,.6)';ctx.lineWidth=Math.max(.4,r*.025);ctx.stroke();

    // ── PAINÉIS DE BLINDAGEM — subdivisão interna do triângulo em placas
    // Linha de divisão central vertical
    ctx.beginPath();ctx.moveTo(0,tipY+r*.15);ctx.lineTo(0,baseY-r*.05);
    ctx.strokeStyle='rgba(100,103,112,.7)';ctx.lineWidth=Math.max(.5,r*.03);ctx.stroke();
    // Divisão horizontal intermediária
    const midY=-r*.08;
    ctx.beginPath();ctx.moveTo(-r*.55,midY);ctx.lineTo(r*.55,midY);
    ctx.strokeStyle='rgba(100,103,112,.6)';ctx.lineWidth=Math.max(.4,r*.025);ctx.stroke();
    // Segunda divisão horizontal (mais embaixo)
    const mid2Y=r*.32;
    ctx.beginPath();ctx.moveTo(-r*.82,mid2Y);ctx.lineTo(r*.82,mid2Y);
    ctx.strokeStyle='rgba(100,103,112,.55)';ctx.lineWidth=Math.max(.4,r*.025);ctx.stroke();
    // Nervuras diagonais internas — reforços estruturais
    ctx.beginPath();ctx.moveTo(-r*.3,tipY+r*.18);ctx.lineTo(-r*.7,mid2Y);
    ctx.strokeStyle='rgba(80,83,90,.5)';ctx.lineWidth=Math.max(.3,r*.02);ctx.stroke();
    ctx.beginPath();ctx.moveTo(r*.3,tipY+r*.18);ctx.lineTo(r*.7,mid2Y);
    ctx.strokeStyle='rgba(80,83,90,.5)';ctx.lineWidth=Math.max(.3,r*.02);ctx.stroke();

    // ── LISTRA VERMELHA CENTRAL — faixa diagonal do topo ao centro
    ctx.save();
    // Clipa dentro do triângulo
    ctx.beginPath();ctx.moveTo(tipX,tipY);ctx.lineTo(baseRX,baseY);ctx.lineTo(baseLX,baseY);ctx.closePath();
    ctx.clip();
    const stripeW=Math.max(3,r*.18);
    const stripeG=ctx.createLinearGradient(-stripeW,0,stripeW,0);
    stripeG.addColorStop(0,'rgba(180,0,0,0)');
    stripeG.addColorStop(.2,'rgba(220,10,10,.85)');
    stripeG.addColorStop(.5,'rgba(255,30,30,1)');
    stripeG.addColorStop(.8,'rgba(220,10,10,.85)');
    stripeG.addColorStop(1,'rgba(180,0,0,0)');
    ctx.fillStyle=stripeG;
    ctx.fillRect(-stripeW,tipY,stripeW*2,baseY-tipY);
    // Borda luminosa da listra
    ctx.strokeStyle='rgba(255,80,80,.6)';ctx.lineWidth=Math.max(.5,r*.03);
    ctx.beginPath();ctx.moveTo(-stripeW*.5,tipY+r*.08);ctx.lineTo(-stripeW*.5,baseY-r*.06);ctx.stroke();
    ctx.beginPath();ctx.moveTo(stripeW*.5,tipY+r*.08);ctx.lineTo(stripeW*.5,baseY-r*.06);ctx.stroke();
    ctx.restore();

    // ── CANHÕES LATERAIS — 2 de cada lado, montados nas bordas do triângulo
    const cannonPairs=[[-.72,.0],[-.88,.38],[.72,.0],[.88,.38]];
    cannonPairs.forEach(([cx2,cy2],ci)=>{
      const cx3=cx2*r, cy3=cy2*r;
      const cAngle=ci<2?-Math.PI*.35:Math.PI*.35+Math.PI; // apontam para frente
      const cLen=Math.max(3,r*(ci%2===0?.28:.22));
      const cW=Math.max(1.5,r*.07);
      // Suporte do canhão
      ctx.beginPath();ctx.arc(cx3,cy3,Math.max(2,r*.09),0,Math.PI*2);
      ctx.fillStyle='rgba(75,78,85,1)';ctx.fill();
      ctx.strokeStyle='rgba(140,143,150,.8)';ctx.lineWidth=Math.max(.5,r*.03);ctx.stroke();
      // Cano do canhão
      ctx.save();ctx.translate(cx3,cy3);ctx.rotate(ci<2?-Math.PI*.5:Math.PI*.5);
      ctx.fillStyle='rgba(50,52,58,1)';
      ctx.fillRect(-cW*.5,-cLen,cW,cLen);
      ctx.strokeStyle='rgba(120,123,130,.7)';ctx.lineWidth=Math.max(.3,r*.02);ctx.strokeRect(-cW*.5,-cLen,cW,cLen);
      // Boca do canhão
      ctx.beginPath();ctx.ellipse(0,-cLen,cW*.65,cW*.3,0,0,Math.PI*2);
      ctx.fillStyle='rgba(20,20,22,1)';ctx.fill();
      ctx.strokeStyle='rgba(160,163,170,.7)';ctx.lineWidth=Math.max(.3,r*.02);ctx.stroke();
      // Brilho pulsante (energia acumulada)
      const cPulse=.3+.3*Math.abs(Math.sin(T*3+ci*.8));
      ctx.beginPath();ctx.arc(0,-cLen+cW*.2,Math.max(.5,cW*.3),0,Math.PI*2);
      ctx.fillStyle=`rgba(255,50,50,${cPulse})`;ctx.fill();
      ctx.restore();
    });

    // ── TORRE DE COMANDO — módulo no terço superior central
    const towerY=-r*.28;
    // Base da torre
    ctx.fillStyle='rgba(68,70,78,1)';
    ctx.fillRect(-Math.max(2,r*.15),towerY-Math.max(2,r*.18),Math.max(4,r*.3),Math.max(4,r*.18));
    ctx.strokeStyle='rgba(140,143,150,.8)';ctx.lineWidth=Math.max(.4,r*.025);
    ctx.strokeRect(-Math.max(2,r*.15),towerY-Math.max(2,r*.18),Math.max(4,r*.3),Math.max(4,r*.18));
    // Janela da torre (viseira vermelha)
    const visG=ctx.createLinearGradient(-r*.1,towerY-r*.16,r*.1,towerY-r*.04);
    visG.addColorStop(0,'rgba(180,10,10,.9)');visG.addColorStop(.4,'rgba(255,60,60,.95)');visG.addColorStop(1,'rgba(120,5,5,.8)');
    ctx.beginPath();ctx.ellipse(0,towerY-r*.1,Math.max(1.5,r*.1),Math.max(1,r*.07),0,0,Math.PI*2);
    ctx.fillStyle=visG;ctx.fill();
    // Reflexo na viseira
    ctx.beginPath();ctx.ellipse(-r*.04,towerY-r*.13,Math.max(.5,r*.04),Math.max(.3,r*.025),-.3,0,Math.PI*2);
    ctx.fillStyle='rgba(255,180,180,.4)';ctx.fill();
    // Antenas laterais da torre
    for(let at=0;at<2;at++){
      const atx=(at===0?-1:1)*Math.max(1.5,r*.16);
      ctx.beginPath();ctx.moveTo(atx,towerY-r*.18);ctx.lineTo(atx+(at===0?-1:1)*r*.12,towerY-r*.38);
      ctx.strokeStyle='rgba(170,173,180,.8)';ctx.lineWidth=Math.max(.5,r*.025);ctx.stroke();
      ctx.beginPath();ctx.arc(atx+(at===0?-1:1)*r*.12,towerY-r*.38,Math.max(.5,r*.03),0,Math.PI*2);
      ctx.fillStyle='rgba(255,50,50,.9)';ctx.fill();
    }

    // ── DETALHES DE SUPERFÍCIE — painéis, escotilhas e sensores
    // Escotilha esquerda (painel hexagonal)
    ctx.beginPath();
    for(let h=0;h<6;h++){const ha=h*(Math.PI/3);ctx.lineTo(Math.cos(ha)*r*.1-r*.42,Math.sin(ha)*r*.08+r*.18);}
    ctx.closePath();ctx.fillStyle='rgba(55,58,65,.9)';ctx.fill();
    ctx.strokeStyle='rgba(130,133,140,.6)';ctx.lineWidth=Math.max(.3,r*.02);ctx.stroke();
    // Escotilha direita
    ctx.beginPath();
    for(let h=0;h<6;h++){const ha=h*(Math.PI/3);ctx.lineTo(Math.cos(ha)*r*.1+r*.42,Math.sin(ha)*r*.08+r*.18);}
    ctx.closePath();ctx.fillStyle='rgba(55,58,65,.9)';ctx.fill();
    ctx.strokeStyle='rgba(130,133,140,.6)';ctx.lineWidth=Math.max(.3,r*.02);ctx.stroke();
    // Sensor frontal — pequeno domo no nariz
    ctx.beginPath();ctx.arc(0,tipY+r*.12,Math.max(1,r*.06),0,Math.PI*2);
    ctx.fillStyle='rgba(255,40,40,.85)';ctx.fill();
    ctx.strokeStyle='rgba(200,200,210,.5)';ctx.lineWidth=Math.max(.3,r*.02);ctx.stroke();
    // Pulso do sensor
    const sensPulse=.4+.4*Math.abs(Math.sin(T*2.5));
    ctx.beginPath();ctx.arc(0,tipY+r*.12,Math.max(1.5,r*.1),0,Math.PI*2);
    ctx.strokeStyle=`rgba(255,40,40,${sensPulse*.5})`;ctx.lineWidth=Math.max(.4,r*.025);ctx.stroke();

    // Rebites e parafusos no casco — pontos metálicos nos painéis
    const rivetPts=[[-r*.22,midY-r*.06],[r*.22,midY-r*.06],[-r*.45,mid2Y-r*.06],[r*.45,mid2Y-r*.06],
                    [-r*.18,r*.5],[r*.18,r*.5],[0,midY+r*.1]];
    rivetPts.forEach(([rx,ry])=>{
      ctx.beginPath();ctx.arc(rx,ry,Math.max(.5,r*.025),0,Math.PI*2);
      ctx.fillStyle='rgba(200,203,210,.8)';ctx.fill();
    });

    // ── ESCUDO DE ENERGIA (anel translúcido girando ao redor quando escravizando)
    if(this._slaves.length>0){
      const auraRot=T*.6;
      ctx.save();ctx.rotate(auraRot);
      for(let i=0;i<6;i++){
        const aa=i*(Math.PI/3);
        const ax=Math.cos(aa)*r*1.35,ay=Math.sin(aa)*r*1.35*.7;
        ctx.beginPath();ctx.arc(ax,ay,Math.max(1,r*.06),0,Math.PI*2);
        ctx.fillStyle=`rgba(220,20,20,${.25+.12*Math.sin(T*3+i)})`;ctx.fill();
      }
      ctx.restore();
    }

    // ── NÚCLEO ENERGÉTICO — losango vermelho pulsante no centro
    const nPulse=.7+.3*Math.sin(T*5);
    const ncol=this._strikeFlash>0?'255,255,100':'220,20,20';
    ctx.save();ctx.rotate(Math.PI*.25+T*.3);
    ctx.beginPath();ctx.moveTo(0,-r*.14);ctx.lineTo(r*.09,0);ctx.lineTo(0,r*.14);ctx.lineTo(-r*.09,0);ctx.closePath();
    const nucG=ctx.createRadialGradient(0,0,0,0,0,r*.14);
    nucG.addColorStop(0,`rgba(${ncol},${nPulse})`);nucG.addColorStop(.6,`rgba(${ncol},.4)`);nucG.addColorStop(1,'rgba(0,0,0,0)');
    ctx.fillStyle=nucG;ctx.fill();
    ctx.restore();

    // ── Flash de escravização
    if(this._strikeFlash>0){
      const fg=ctx.createRadialGradient(0,0,0,0,0,r*4*this._strikeFlash);
      fg.addColorStop(0,`rgba(255,60,0,${this._strikeFlash*.4})`);fg.addColorStop(1,'transparent');
      ctx.beginPath();ctx.arc(0,0,r*4*this._strikeFlash,0,Math.PI*2);ctx.fillStyle=fg;ctx.fill();
    }

    ctx.restore();

    // ── STRIKE DE SUBYUGAÇÃO — raio de escravização
    if(this._strike){
      const prog=this._strike.t/this._strike.maxT;
      const lx1=(this._strike.x1-cam.x)*cam.zoom+canvas.width*.5;
      const ly1=(this._strike.y1-cam.y)*cam.zoom+canvas.height*.5;
      const lx2=(this._strike.x2-cam.x)*cam.zoom+canvas.width*.5;
      const ly2=(this._strike.y2-cam.y)*cam.zoom+canvas.height*.5;
      ctx.beginPath();ctx.moveTo(lx1,ly1);ctx.lineTo(lx2,ly2);
      ctx.strokeStyle=`rgba(220,20,0,${.95-prog*.2})`;ctx.lineWidth=Math.max(2.5,4*cam.zoom*(1-prog*.5));ctx.stroke();
      ctx.beginPath();ctx.moveTo(lx1,ly1);ctx.lineTo(lx2,ly2);
      ctx.strokeStyle=`rgba(255,140,80,${.5-prog*.3})`;ctx.lineWidth=Math.max(1,1.5*cam.zoom);ctx.stroke();
      for(let k=0;k<3;k++){
        const pr=prog*r*(k+1)*2;
        ctx.beginPath();ctx.arc(lx2,ly2,pr,0,Math.PI*2);
        ctx.strokeStyle=`rgba(220,30,10,${(1-prog)*.4})`;ctx.lineWidth=1.5;ctx.stroke();
      }
    }

    // ── Anel de escravos
    if(this._slaves.length>0){
      ctx.beginPath();ctx.arc(sx,sy,(90+this._slaves.length*12)*cam.zoom,0,Math.PI*2);
      ctx.strokeStyle=`rgba(180,20,0,${.18+.06*Math.sin(T*2)})`;ctx.lineWidth=1.5;ctx.stroke();
    }

    if(sandboxMode){
      ctx.font=`${Math.max(7,r*.44)}px 'Courier New'`;ctx.fillStyle='rgba(220,60,40,.85)';
      ctx.textAlign='center';
      ctx.fillText(`🔺 REPTILIANO | ⛓️${this._enslaved} escrav. | 🛡️×${Math.ceil(this._shield)}`,sx,sy+r*1.8+6*cam.zoom);
      ctx.textAlign='left';
    }
  }
}

// ─── Escama Robótica ─────────────────────────────────────────────
function _triggerEscamaDrop(){
  _escamaActive=true;
  const prevPause=typeof gamePaused!=='undefined'?gamePaused:false;
  if(typeof gamePaused!=='undefined') gamePaused=true;
  let overlay=document.getElementById('escama-overlay');
  if(overlay) return;
  overlay=document.createElement('div');
  overlay.id='escama-overlay';
  Object.assign(overlay.style,{
    position:'fixed',inset:'0',zIndex:'19999',
    display:'flex',flexDirection:'column',alignItems:'center',justifyContent:'center',
    background:'rgba(0,0,0,0)',backdropFilter:'blur(0px)',transition:'background .6s ease, backdrop-filter .6s ease'
  });
  overlay.innerHTML=`
    <style>
      @keyframes escama-bg-in{from{background:rgba(0,0,0,0)}to{background:rgba(0,0,0,.9)}}
      @keyframes escama-card-in{from{opacity:0;transform:scale(.7) translateY(40px)}to{opacity:1;transform:scale(1) translateY(0)}}
      @keyframes escama-pulse{0%,100%{box-shadow:0 0 40px rgba(255,20,20,.32),0 0 80px rgba(0,220,255,.12)}50%{box-shadow:0 0 70px rgba(255,30,30,.55),0 0 120px rgba(0,220,255,.28)}}
      @keyframes escama-shake{0%,100%{transform:rotate(0deg)}20%{transform:rotate(-2deg)}40%{transform:rotate(2.5deg)}60%{transform:rotate(-1.5deg)}80%{transform:rotate(1deg)}}
      @keyframes escama-float{0%,100%{transform:translateY(0) scale(1)}50%{transform:translateY(-8px) scale(1.04)}}
      @keyframes escama-ring{from{transform:scale(.6);opacity:.8}to{transform:scale(2.2);opacity:0}}
      @keyframes escama-eye-blink{0%,90%,100%{transform:scaleY(1)}95%{transform:scaleY(.05)}}
      #escama-card{
        max-width:440px;padding:42px 36px;
        background:linear-gradient(160deg,rgba(20,4,4,.97),rgba(4,4,6,.99),rgba(10,18,20,.97));
        border:1.5px solid rgba(0,220,255,.4);border-radius:22px;text-align:center;
        animation:escama-card-in .65s cubic-bezier(.22,1,.36,1) both,escama-pulse 2.5s ease-in-out .7s infinite;
        position:relative;overflow:hidden;
      }
      #escama-card::before{
        content:'';position:absolute;inset:0;
        background:repeating-linear-gradient(45deg,rgba(255,20,20,.035) 0px,rgba(255,20,20,.035) 1px,transparent 1px,transparent 8px);
        border-radius:22px;pointer-events:none;
      }
      #escama-card::after{
        content:'';position:absolute;inset:0;border-radius:22px;pointer-events:none;
        box-shadow:inset 0 0 60px rgba(0,220,255,.08);
      }
      #escama-icon{width:76px;height:76px;object-fit:contain;display:block;margin:0 auto;
        filter:drop-shadow(0 0 14px rgba(255,20,20,.65)) drop-shadow(0 0 22px rgba(0,220,255,.35));
        animation:escama-float 2.2s ease-in-out infinite,escama-shake 1.1s ease-in-out .3s 1;}
      #escama-rings{position:absolute;top:42px;left:50%;transform:translateX(-50%);pointer-events:none;}
      .escama-ring{position:absolute;width:60px;height:60px;border:2px solid rgba(0,220,255,.5);border-radius:50%;left:-30px;top:-10px;}
      .escama-ring:nth-child(1){animation:escama-ring 1.8s ease-out .4s infinite;}
      .escama-ring:nth-child(2){animation:escama-ring 1.8s ease-out .9s infinite;border-color:rgba(255,20,20,.45);}
      .escama-ring:nth-child(3){animation:escama-ring 1.8s ease-out 1.4s infinite;}
      #escama-title{font-size:1.4rem;font-weight:800;color:#ff2020;letter-spacing:.06em;margin:14px 0 8px;
        text-shadow:0 0 20px rgba(255,20,20,.65),0 0 30px rgba(0,220,255,.25);}
      #escama-sub{font-size:.82rem;color:rgba(0,220,255,.75);letter-spacing:.12em;text-transform:uppercase;margin-bottom:18px;}
      #escama-body{font-size:.93rem;color:rgba(210,235,240,.9);line-height:1.72;margin-bottom:28px;}
      #escama-warn{display:inline-block;background:rgba(255,10,10,.14);border:1px solid rgba(0,220,255,.3);
        border-radius:8px;padding:10px 16px;margin-bottom:22px;font-size:.88rem;color:rgba(190,235,240,.95);}
      #escama-btns{display:flex;gap:16px;justify-content:center;}
      #escama-yes{padding:13px 30px;background:linear-gradient(135deg,rgba(255,20,20,.92),rgba(120,0,0,.97));
        border:1px solid rgba(0,220,255,.45);border-radius:11px;color:#fff;font-size:1rem;font-weight:800;
        cursor:pointer;letter-spacing:.03em;transition:all .2s;text-shadow:0 1px 4px rgba(0,0,0,.6);}
      #escama-yes:hover{background:linear-gradient(135deg,rgba(255,40,40,1),rgba(150,0,0,1));transform:scale(1.04);
        box-shadow:0 0 18px rgba(0,220,255,.4);}
      #escama-no{padding:13px 26px;background:rgba(6,20,22,.75);border:1px solid rgba(0,220,255,.28);
        border-radius:11px;color:rgba(200,235,240,.85);font-size:.96rem;cursor:pointer;transition:all .2s;}
      #escama-no:hover{background:rgba(10,30,33,.9);transform:scale(1.02);border-color:rgba(0,220,255,.5);}
      #escama-eye{width:28px;height:20px;background:#000;border-radius:50%;display:inline-block;
        position:relative;overflow:hidden;vertical-align:middle;margin:0 4px;
        border:1px solid rgba(0,220,255,.3);
        animation:escama-eye-blink 3.5s ease-in-out infinite;}
      #escama-eye::after{content:'';position:absolute;left:50%;top:50%;transform:translate(-50%,-50%);
        width:8px;height:16px;background:rgba(255,20,20,.9);border-radius:50%;box-shadow:0 0 6px rgba(0,220,255,.6);}
    </style>
    <div id="escama-card">
      <div id="escama-rings"><div class="escama-ring"></div><div class="escama-ring"></div><div class="escama-ring"></div></div>
      <img id="escama-icon" src="images/items/Robotic.png" alt="Escama Robótica">
      <div id="escama-title">ESCAMA ROBÓTICA</div>
      <div id="escama-sub">Item Único — Classe Extinção</div>
      <div id="escama-body">
        Um Reptiliano derrubou uma <strong style="color:#ff3030">Escama Robótica</strong> ao ser criado.<br><br>
        Este fragmento de tecnologia reptiliana contém conhecimento proibido acumulado por eons de conquista galáctica.
      </div>
      <div id="escama-warn">
        ⚠️ &nbsp;<span id="escama-eye"></span>&nbsp; Usar este item é um
        <strong style="color:#ff2020">caminho sem volta</strong>.<br>
        As consequências serão <em>permanentes</em> e alterarão o universo para sempre.
      </div>
      <div id="escama-btns">
        <button id="escama-yes">🔥 Usar a Escama</button>
        <button id="escama-no">Guardar por agora</button>
      </div>
    </div>`;
  document.body.appendChild(overlay);
  requestAnimationFrame(()=>{
    overlay.style.background='rgba(0,0,0,.88)';
    overlay.style.backdropFilter='blur(5px)';
  });
  document.getElementById('escama-yes').addEventListener('click',()=>{
    overlay.style.transition='opacity .4s';overlay.style.opacity='0';
    setTimeout(()=>{overlay.remove();_escamaActive=false;if(typeof gamePaused!=='undefined')gamePaused=prevPause;_useEscamaRobotica();},400);
  });
  document.getElementById('escama-no').addEventListener('click',()=>{
    overlay.style.transition='opacity .35s';overlay.style.opacity='0';
    setTimeout(()=>{overlay.remove();_escamaActive=false;if(typeof gamePaused!=='undefined')gamePaused=prevPause;
      if(typeof addBackpackItem==='function'){
        addBackpackItem({
          id:'escama-robotica',
          name:'Escama Robótica',
          desc:'Item Único — Classe Extinção. Um caminho sem volta.',
          icon:'images/items/Robotic.png',
          useLabel:'🔥 Usar',
          onUse:()=>{ if(typeof _useEscamaRobotica==='function')_useEscamaRobotica(); },
        });
      }
      showTooltip('🦎 Escama Robótica guardada na mochila. Use quando estiver pronto...');},350);
  });
}

function _useEscamaRobotica(){
  if(typeof ReptilianInvasion==='undefined')return;
  const block=_invasionProgressionBlock('reptilian');
  if(block){ showTooltip(block); return; }
  // Spawn natural exige Pacote Estrelas desbloqueado (Rank 18).
  if(typeof _isStarPackUnlocked==='function'&&!_isStarPackUnlocked()){
    showTooltip('🔒 Pacote Estrelas (Rank 18) necessário para enfrentar a Invasão Reptiliana.');
    return;
  }
  if(typeof ReptilianInvasion.showBlackholyWarning==='function'){
    if(typeof gamePaused!=='undefined')gamePaused=true;
    ReptilianInvasion.showBlackholyWarning(()=>{
      if(typeof gamePaused!=='undefined')gamePaused=false;
      ReptilianInvasion.startInvasion();
    });
  } else {
    ReptilianInvasion.startInvasion();
  }
}


// ═══════════════════════════════════════════════════════════════════
//  PROGRESSÃO DE INVASÕES — Alien → Marciana → Reptiliana
//  Cada invasão só pode ser disparada se a anterior já tiver sido
//  vencida (derrotada) ao menos uma vez. Flags persistem via localStorage.
// ═══════════════════════════════════════════════════════════════════
const INVASION_VICTORY_KEYS={alien:'cosmos_sim_alien_victory_v1',marsian:'cosmos_sim_marsian_victory_v1',reptilian:'cosmos_sim_reptilian_victory_v1'};
function _hasWonInvasion(key){
  try{ return !!localStorage.getItem(INVASION_VICTORY_KEYS[key]); }catch(e){ return false; }
}
function _markInvasionWon(key){
  try{ localStorage.setItem(INVASION_VICTORY_KEYS[key],'1'); }catch(e){}
}
// Retorna null se liberado, ou uma mensagem de bloqueio caso a invasão
// anterior na progressão ainda não tenha sido vencida.
function _invasionProgressionBlock(key){
  if(key==='marsian'&&!_hasWonInvasion('alien')){
    return '🔒 Derrote a Invasão Alienígena antes de enfrentar a Invasão Marciana.';
  }
  if(key==='reptilian'&&!_hasWonInvasion('marsian')){
    return '🔒 Derrote a Invasão Marciana antes de enfrentar a Invasão Reptiliana.';
  }
  return null;
}

// ═══════════════════════════════════════════════════════════════════
//  INVASÃO REPTILIANA
//  Gatilho: Escama Robótica (drop ao escravizar)
//  Sem Boss por enquanto.
// ═══════════════════════════════════════════════════════════════════
const ReptilianInvasion=(()=>{
  let _active=false;
  let _t=0;
  let _portals=[];
  let _ships=[];
  let _reptilians=[];
  let _preStash=[];
  let _arenaRect=null;
  let _worldBounds=null;
  let _savedZoom=1;
  let _playerZoomBeforeBattle=1;
  let _camLocked=false;
  let _animFrame=null;
  let _riftCanvas=null;
  let _riftCtx=null;
  let _fxParticles=[];
  const _MARGIN=16;
  // ── Timeout GLOBAL da invasão Reptiliana: 20 minutos + 1 minuto de aviso ──
  const GLOBAL_WARN_AT=1200;   // 20 minutos — dispara o toast de aviso
  const GLOBAL_HARD_END=1260;  // +1 minuto (20min+1min) — força o fim da invasão
  let _globalWarnShown=false;  // já mostrou o toast "1 MINUTO SOBRANDO!"
  function rand(a,b){return a+Math.random()*(b-a);}
  function randInt(a,b){return Math.floor(rand(a,b+1));}

  // ── Classes ───────────────────────────────────────────────────────
  const REP_CLASSES=[
    {cls:'Soldado Reptiliano', maxHP:30000,  speed:58, atk:120,  color:'#cc2200', scale:1.0},
    {cls:'Caçador Reptiliano', maxHP:72000,  speed:46, atk:280,  color:'#9922bb', scale:1.18},
    {cls:'Berserker Reptiliano', maxHP:150000, speed:34, atk:550,  color:'#dd1100', scale:1.38},
    {cls:'Comandante Dragão',maxHP:320000, speed:22, atk:1100, color:'#ff6600', scale:1.65},
  ];
  const REP_WAVE_CONFIG=[
    {portals:[2,3], weights:[0.55,0.30,0.12,0.03]},
    {portals:[3,5], weights:[0.25,0.40,0.25,0.10]},
    {portals:[5,7], weights:[0.05,0.20,0.40,0.35]},
  ];
  let _wave=1;
  let _waveTimer=0;
  const WAVE_INTERVAL=5;

  // ── Câmera lock ───────────────────────────────────────────────────
  // Trava zoom E posição (x/y): o jogador não pode mover a câmera
  // durante a batalha — só o Galaximy permite pan (arena maior que
  // a tela). Mesmo padrão robusto via Object.defineProperty (setter
  // noop ignora qualquer tentativa externa de alterar).
  let _savedCamX=0,_savedCamY=0;
  function _lockCam(){
    if(_camLocked)return;
    // Zoom fixo para todas as batalhas — não depende do zoom do jogador
    // antes de entrar, evita arena/astros minúsculos ou gigantes.
    _playerZoomBeforeBattle=cam.zoom; // guarda o zoom do jogador para restaurar depois
    _savedZoom=BATTLE_FIXED_ZOOM;
    _savedCamX=cam.x;_savedCamY=cam.y;
    try{
      Object.defineProperty(cam,'zoom',{get(){return _savedZoom;},set(){},configurable:true});
      Object.defineProperty(cam,'x',{get(){return _savedCamX;},set(){},configurable:true});
      Object.defineProperty(cam,'y',{get(){return _savedCamY;},set(){},configurable:true});
    }catch(e){}
    _camLocked=true;
  }
  function _unlockCam(){
    if(!_camLocked)return;
    try{
      Object.defineProperty(cam,'zoom',{value:_playerZoomBeforeBattle,writable:true,configurable:true});
      Object.defineProperty(cam,'x',{value:_savedCamX,writable:true,configurable:true});
      Object.defineProperty(cam,'y',{value:_savedCamY,writable:true,configurable:true});
    }catch(e){}
    _camLocked=false;
  }

  // ── Arena (coordenadas de tela) ───────────────────────────────────
  function _buildArena(){
    const cw=canvas.width,ch=canvas.height;
    _arenaRect={x:_MARGIN,y:_MARGIN,w:cw-_MARGIN*2,h:ch-_MARGIN*2};
  }

  // ── Portais e Naves ───────────────────────────────────────────────
  function _spawnPortalsAndShips(){
    const ar=_arenaRect||{x:0,y:0,w:canvas.width,h:canvas.height};
    const x1=ar.x,y1=ar.y,x2=ar.x+ar.w,y2=ar.y+ar.h;
    const cfg=REP_WAVE_CONFIG[Math.min(_wave,REP_WAVE_CONFIG.length)-1];
    const n=cfg.portals[0]+Math.floor(Math.random()*(cfg.portals[1]-cfg.portals[0]+1));
    for(let i=0;i<n;i++){
      const side=i%4;
      let sx,sy;
      if(side===0){sx=rand(x1+60,x2-60);sy=rand(y1+16,y1+50);}
      else if(side===1){sx=rand(x2-55,x2-16);sy=rand(y1+60,y2-60);}
      else if(side===2){sx=rand(x1+60,x2-60);sy=rand(y2-55,y2-16);}
      else{sx=rand(x1+16,x1+55);sy=rand(y1+60,y2-60);}
      const cx=(x1+x2)/2,cy=(y1+y2)/2;
      _portals.push({sx,sy,age:0,shipSpawned:false,cracksAngle:rand(0,Math.PI*2),
        vx:(cx-sx)*0.0015,vy:(cy-sy)*0.0015});
    }
  }

  // ── DRAW: Portal (rasgo dimensional vermelho/roxo) ────────────────
  function _drawPortal(c,p,t){
    const pulse=0.6+0.4*Math.sin(t*4.5+p.sx);
    const r=20+18*Math.min(1,p.age*0.55)*pulse;
    const alpha=Math.min(0.92,p.age);
    c.save();c.translate(p.sx,p.sy);
    // Rasgo elíptico
    c.beginPath();c.ellipse(0,0,r,r*0.55,p.cracksAngle,0,Math.PI*2);
    c.strokeStyle=`rgba(200,0,80,${alpha*0.9})`;c.lineWidth=3;c.stroke();
    c.beginPath();c.ellipse(0,0,r*0.6,r*0.3,p.cracksAngle,0,Math.PI*2);
    c.strokeStyle=`rgba(255,100,200,${alpha*0.5})`;c.lineWidth=1.5;c.stroke();
    // Núcleo escuro com brilho roxo
    const g=c.createRadialGradient(0,0,0,0,0,r*0.5);
    g.addColorStop(0,`rgba(60,0,30,${alpha*0.85})`);
    g.addColorStop(0.5,`rgba(140,0,60,${alpha*0.35})`);
    g.addColorStop(1,'transparent');
    c.beginPath();c.ellipse(0,0,r*0.5,r*0.28,p.cracksAngle,0,Math.PI*2);
    c.fillStyle=g;c.fill();
    // Raios de energia saindo do rasgo
    for(let i=0;i<4;i++){
      const a=p.cracksAngle+i*(Math.PI*0.5)+t*(1.5+i*0.3);
      const len=r*(0.7+0.3*Math.sin(t*5+i));
      c.beginPath();c.moveTo(0,0);c.lineTo(Math.cos(a)*len,Math.sin(a)*len);
      c.strokeStyle=`rgba(220,0,100,${alpha*(0.3-i*0.06)*pulse})`;c.lineWidth=1.5;c.stroke();
    }
    c.restore();
  }

  // ── DRAW: Nave Reptiliana (dragão voador mecânico) ────────────────
  function _drawShip(c,s,t){
    c.save();c.translate(s.x,s.y);c.rotate(s.rot);
    const sc=1+0.04*Math.sin(t*7+s.phase);c.scale(sc,sc);
    // Fuselagem triangular escura (corpo principal)
    c.beginPath();
    c.moveTo(22,0);c.lineTo(-10,9);c.lineTo(-6,0);c.lineTo(-10,-9);
    c.closePath();
    c.fillStyle='rgba(25,5,5,0.93)';c.fill();
    c.strokeStyle='rgba(180,0,60,0.85)';c.lineWidth=1.6;c.stroke();
    // Asas laterais
    c.beginPath();c.moveTo(0,3);c.lineTo(-14,18);c.lineTo(-16,12);c.lineTo(-4,3);
    c.closePath();
    c.fillStyle='rgba(40,0,15,0.88)';c.fill();
    c.strokeStyle='rgba(160,0,50,0.7)';c.lineWidth=1.1;c.stroke();
    c.beginPath();c.moveTo(0,-3);c.lineTo(-14,-18);c.lineTo(-16,-12);c.lineTo(-4,-3);
    c.closePath();
    c.fillStyle='rgba(40,0,15,0.88)';c.fill();
    c.strokeStyle='rgba(160,0,50,0.7)';c.lineWidth=1.1;c.stroke();
    // Janela/olho frontal vermelho pulsante
    c.beginPath();c.ellipse(10,0,4,2.5,0,0,Math.PI*2);
    c.fillStyle=`rgba(255,30,30,${0.55+0.4*Math.sin(t*6)})`;c.fill();
    c.beginPath();c.ellipse(10,0,2,1.2,0,0,Math.PI*2);
    c.fillStyle=`rgba(255,200,200,${0.4+0.3*Math.sin(t*9)})`;c.fill();
    // Motor traseiro
    c.beginPath();c.moveTo(-10,3);c.lineTo(-22,1.5);c.lineTo(-22,-1.5);c.lineTo(-10,-3);
    c.closePath();
    c.fillStyle=`rgba(180,0,80,${0.45+0.4*Math.sin(t*8)})`;c.fill();
    // Detalhe: escamas na fuselagem
    c.strokeStyle='rgba(200,0,60,0.35)';c.lineWidth=0.6;
    for(let i=0;i<3;i++){
      c.beginPath();c.arc(-2+i*6,0,4-i,0.4,Math.PI-0.4);c.stroke();
    }
    c.restore();
  }

  // ── DRAW: Reptiliano (redesenho — criatura militar alienígena) ────
  function _drawReptilian(c,r,t){
    if(r.flashT>0)r.flashT-=1/60;
    const bc=r.flashT>0?r.flashColor:r.color;
    const isCmd=r.cls==='Comandante Dragão';
    const isBsk=r.cls==='Berserker Reptiliano';
    const isCac=r.cls==='Caçador Reptiliano';
    const sz=r.scale*Math.max(0.45,Math.min(1.7,cam.zoom));
    const pulse=Math.sin(t*5+r.x*0.02);

    c.save();c.translate(r.x,r.y);
    const hy=-4*Math.sin(t*2.3+r.y*0.013);
    c.translate(0,hy);c.scale(sz,sz);
    if(r.paralyzed>0)c.translate(rand(-2,2),rand(-1.5,1.5));

    // ── Aura de classe ──
    if(isCmd){
      const aura=c.createRadialGradient(0,0,4,0,0,40);
      aura.addColorStop(0,`rgba(255,140,0,${0.18+0.08*pulse})`);
      aura.addColorStop(0.5,`rgba(200,60,0,${0.10+0.05*pulse})`);
      aura.addColorStop(1,'transparent');
      c.beginPath();c.arc(0,0,40,0,Math.PI*2);c.fillStyle=aura;c.fill();
    } else if(isBsk){
      const aura=c.createRadialGradient(0,0,3,0,0,30);
      aura.addColorStop(0,`rgba(255,0,0,${0.22+0.1*Math.abs(pulse)})`);
      aura.addColorStop(1,'transparent');
      c.beginPath();c.arc(0,0,30,0,Math.PI*2);c.fillStyle=aura;c.fill();
    } else if(isCac){
      const aura=c.createRadialGradient(0,0,2,0,0,22);
      aura.addColorStop(0,'rgba(160,0,200,0.12)');aura.addColorStop(1,'transparent');
      c.beginPath();c.arc(0,0,22,0,Math.PI*2);c.fillStyle=aura;c.fill();
    }

    c.shadowColor=bc;c.shadowBlur=0;
    c.lineCap='round';c.lineJoin='round';

    // ── Cauda segmentada com placas (desenhada primeiro, atrás do corpo) ──
    {
      const segments=isCmd?6:isBsk?5:4;
      for(let i=segments;i>=0;i--){
        const tf=i/segments;
        const tx=-9-tf*18,ty=4+tf*12+Math.sin(t*3+i*0.8+r.x*0.02)*3*tf;
        const tr=4.5*(1-tf*0.65);
        c.beginPath();c.ellipse(tx,ty,tr,tr*0.7,0,0,Math.PI*2);
        c.fillStyle=`rgba(${isCmd?'18,6,0':'10,2,4'},${0.92-tf*0.15})`;c.fill();
        const hexAlpha=Math.floor((0.7-tf*0.3)*255).toString(16).padStart(2,'0');
        c.strokeStyle=`${bc}${hexAlpha}`;
        c.lineWidth=0.8;c.stroke();
        if(i>0&&i<segments){
          const sa=isCmd?0.16:0.12;
          const spH=isCmd?5+i*0.4:3+i*0.3;
          c.beginPath();c.moveTo(tx,ty-tr*0.6);c.lineTo(tx+spH*0.3,ty-tr-spH);c.lineTo(tx-spH*0.3,ty-tr-spH*0.2);c.closePath();
          c.fillStyle=isCmd?`rgba(255,140,0,${sa})`:isBsk?`rgba(220,0,0,${sa})`:`rgba(160,0,60,${sa})`;c.fill();
        }
      }
    }

    // Cor de placa (armadura) e cor de escama (junta orgânica) por classe
    const plateBase = isCmd?'rgba(50,20,4,0.98)':isBsk?'rgba(38,6,6,0.98)':'rgba(22,6,14,0.98)';
    const plateDark  = 'rgba(6,1,2,0.99)';
    const plateEdge  = isCmd?'rgba(255,170,40,0.9)':isBsk?'rgba(255,30,10,0.9)':isCac?'rgba(190,20,220,0.85)':'rgba(200,10,90,0.85)';
    const scaleCol   = `${bc}55`;
    function armorPlate(pts,edgeW){
      c.beginPath();
      pts.forEach(([px,py],idx)=>idx===0?c.moveTo(px,py):c.lineTo(px,py));
      c.closePath();
      c.fillStyle=plateBase;c.fill();
      c.strokeStyle=plateEdge;c.lineWidth=edgeW||1.1;c.stroke();
    }

    // ── Pernas: perneiras de exoesqueleto (placas) sobre stub de escama ──
    {
      const legBob=1.8*Math.sin(t*4.5+r.y*0.02);
      [-1,1].forEach(side=>{
        const hx=5*side,hy=6,kx=7*side+legBob*side*0.3,ky=13+legBob*0.5,fx=8*side,fy=19;
        // coxa (placa grossa)
        armorPlate([[hx-1.6*side,hy],[hx+2.4*side,hy+1],[kx+2*side,ky-1],[kx-2.2*side,ky+1]]);
        // canela (placa fina exoesqueleto)
        armorPlate([[kx-1.6*side,ky],[kx+1.8*side,ky],[fx+1.4*side,fy],[fx-1.4*side,fy]],0.9);
        // articulação do joelho — escama orgânica exposta
        c.beginPath();c.arc(kx,ky,1.6,0,Math.PI*2);c.fillStyle=scaleCol;c.fill();
        // garra do pé (3 dedos)
        c.strokeStyle=plateEdge;c.lineWidth=1.3;
        [[fx-2*side,fy+3],[fx,fy+3.5],[fx+2*side,fy+3]].forEach(([gx,gy])=>{
          c.beginPath();c.moveTo(fx,fy);c.lineTo(gx,gy);c.stroke();
        });
      });
    }

    // ── Torso: peitoral de placas grossas (samurai/tribal) sobre exoesqueleto ──
    c.shadowColor=bc;c.shadowBlur=0;
    // Base do exoesqueleto (mais escura, some sob as placas)
    c.beginPath();
    c.moveTo(0,-8);c.lineTo(9,-5);c.lineTo(10,2);c.lineTo(7,8);
    c.lineTo(0,10);c.lineTo(-7,8);c.lineTo(-10,2);c.lineTo(-9,-5);
    c.closePath();
    c.fillStyle=plateDark;c.fill();
    c.strokeStyle=`${bc}88`;c.lineWidth=1;c.stroke();

    // Placa peitoral central grossa (tipo couraça samurai, sobreposta em camadas)
    armorPlate([[0,-9],[6,-6],[6,0],[0,3],[-6,0],[-6,-6]],1.6);
    armorPlate([[0,-1],[5,1.5],[4,6],[0,8.5],[-4,6],[-5,1.5]],1.4);
    // Linha central de reforço (costura de placas)
    c.strokeStyle=plateEdge;c.lineWidth=0.9;
    c.beginPath();c.moveTo(0,-9);c.lineTo(0,8.5);c.stroke();

    // Escamas orgânicas visíveis nas frestas entre placas (fileira lateral)
    c.strokeStyle=scaleCol;c.lineWidth=0.7;
    for(let row=0;row<3;row++){
      const ry=-3+row*4.5;
      [[-8,ry],[8,ry]].forEach(([cx2,cy2])=>{
        c.beginPath();c.moveTo(cx2-1.6,cy2);c.lineTo(cx2,cy2+2);c.lineTo(cx2+1.6,cy2);c.stroke();
      });
    }

    // Ombreiras: placas grandes tribais com espigão
    [-1,1].forEach(side=>{
      armorPlate([[7*side,-6],[13*side,-4],[14*side,1],[10*side,3],[8*side,-2]],1.3);
      // espigão da ombreira
      c.beginPath();c.moveTo(11*side,-4);c.lineTo(15*side,-9);c.lineTo(12*side,-2);c.closePath();
      c.fillStyle=plateEdge;c.fill();
    });

    // Cristal de energia pulsante (losango), embutido no peitoral
    {
      const cPulse=0.55+0.4*Math.abs(pulse);
      c.beginPath();c.moveTo(0,-5.5);c.lineTo(5,0);c.lineTo(0,5.5);c.lineTo(-5,0);c.closePath();
      c.fillStyle=isCmd?`rgba(255,160,0,${cPulse*0.25})`:`rgba(255,40,60,${cPulse*0.25})`;c.fill();
      c.beginPath();c.moveTo(0,-3.5);c.lineTo(3.2,0);c.lineTo(0,3.5);c.lineTo(-3.2,0);c.closePath();
      c.fillStyle=isCmd?`rgba(255,160,0,${cPulse*0.75})`:`rgba(255,40,60,${cPulse*0.75})`;c.fill();
      c.strokeStyle=isCmd?'rgba(255,220,100,0.9)':'rgba(255,150,150,0.9)';c.lineWidth=0.8;c.stroke();
      c.beginPath();c.arc(0,0,1.6,0,Math.PI*2);
      c.fillStyle=isCmd?`rgba(255,240,180,${cPulse})`:`rgba(255,240,255,${cPulse})`;c.fill();
    }

    // ── Braços: braçadeiras de placa + antebraço exoesqueleto + garras ──
    {
      const armAngle=0.22*Math.sin(t*2.8+r.y*0.02);
      [-1,1].forEach(side=>{
        const sx=9*side,sy=-2;
        const ex=(15+armAngle*8*side*(side>0?-1:1))*side,ey=4;
        const wx=(17)*side,wy=10;
        // braçadeira superior (placa grossa)
        armorPlate([[sx-1.4*side,sy],[sx+2*side,sy-1],[ex+1.8*side,ey-1.5],[ex-1.6*side,ey+1]],1.1);
        // articulação do cotovelo — escama exposta
        c.beginPath();c.arc(ex,ey,1.3,0,Math.PI*2);c.fillStyle=scaleCol;c.fill();
        // antebraço (placa fina exoesqueleto)
        armorPlate([[ex-1.3*side,ey],[ex+1.5*side,ey],[wx+1.2*side,wy],[wx-1.2*side,wy]],0.9);
        // garras longas (3 por mão)
        c.strokeStyle=plateEdge;c.lineWidth=1.4;
        [[wx-2*side,wy+5],[wx,wy+6],[wx+2*side,wy+5]].forEach(([gx,gy])=>{
          c.beginPath();c.moveTo(wx,wy);c.lineTo(gx,gy);c.stroke();
        });
      });
    }

    // ── Cabeça de dinossauro (perspectiva frontal) ──
    // Crânio largo
    c.beginPath();c.ellipse(0,-16,8.5,6.5,0,0,Math.PI*2);
    const headGrad=c.createRadialGradient(-1,-17,1,-1,-16,10);
    headGrad.addColorStop(0,isCmd?'rgba(30,10,0,0.97)':'rgba(16,4,6,0.97)');
    headGrad.addColorStop(1,'rgba(5,0,2,0.99)');
    c.fillStyle=headGrad;c.fill();
    c.strokeStyle=bc;c.lineWidth=1.4;c.stroke();

    // Maxilar
    c.beginPath();c.ellipse(0,-13,9,4,0,0,Math.PI*2);
    c.fillStyle='rgba(12,3,5,0.95)';c.fill();
    c.strokeStyle=`${bc}66`;c.lineWidth=0.8;c.stroke();

    // Focinho (frontal, boca voltada para baixo)
    c.beginPath();
    c.moveTo(-5,-13);c.lineTo(5,-13);c.lineTo(7,-11);c.lineTo(6,-8);c.lineTo(-6,-8);c.lineTo(-7,-11);
    c.closePath();
    c.fillStyle='rgba(14,3,5,0.96)';c.fill();
    c.strokeStyle=bc;c.lineWidth=1.1;c.stroke();

    // Mandíbula inferior animada
    const jawOpen=0.5+0.5*Math.abs(Math.sin(t*1.8+r.x*0.02));
    c.beginPath();
    c.moveTo(-5,-8);c.lineTo(5,-8);c.lineTo(6,-8+jawOpen*3);c.lineTo(-6,-8+jawOpen*3);
    c.closePath();
    c.fillStyle='rgba(35,5,8,0.96)';c.fill();
    c.strokeStyle=`${bc}88`;c.lineWidth=0.9;c.stroke();

    // Dentes superiores
    c.fillStyle='rgba(240,235,230,0.92)';
    for(let i=0;i<5;i++){
      const tx=-4+i*2;
      c.beginPath();c.moveTo(tx,-8.5);c.lineTo(tx+0.7,-8.5+2.5);c.lineTo(tx+1.4,-8.5);c.fill();
    }
    // Dentes inferiores
    c.fillStyle='rgba(210,200,195,0.75)';
    for(let i=0;i<4;i++){
      const tx=-3+i*2;
      c.beginPath();c.moveTo(tx,-8+jawOpen*3);c.lineTo(tx+0.6,-8+jawOpen*3-1.8);c.lineTo(tx+1.2,-8+jawOpen*3);c.fill();
    }
    // Língua bífida
    if(jawOpen>0.4){
      const la=(jawOpen-0.4)*2;
      c.strokeStyle=`rgba(200,30,50,${la})`;c.lineWidth=1.2;
      c.beginPath();c.moveTo(0,-8+jawOpen*2.5);c.quadraticCurveTo(-1.5,-6+jawOpen*3,-2,-5+jawOpen*3);c.stroke();
      c.beginPath();c.moveTo(0,-8+jawOpen*2.5);c.quadraticCurveTo(1.5,-6+jawOpen*3,2,-5+jawOpen*3);c.stroke();
    }

    // Dois olhos com pupila em fenda vertical
    [[-4,-17],[4,-17]].forEach(([ex,ey])=>{
      c.beginPath();c.ellipse(ex,ey,2.8,2.2,0,0,Math.PI*2);
      c.fillStyle=isCmd?'rgba(255,180,20,0.95)':isBsk?'rgba(255,80,0,0.9)':'rgba(200,220,0,0.88)';c.fill();
      c.strokeStyle=`${bc}99`;c.lineWidth=0.7;c.stroke();
      c.beginPath();c.ellipse(ex,ey,0.75,2.0,0,0,Math.PI*2);
      c.fillStyle='rgba(0,0,0,0.98)';c.fill();
      c.beginPath();c.arc(ex-0.6,ey-0.5,0.5,0,Math.PI*2);
      c.fillStyle=`rgba(255,255,220,${0.6+0.3*Math.abs(pulse)})`;c.fill();
    });

    // Narinas
    c.fillStyle=`${bc}44`;
    c.beginPath();c.ellipse(-1.8,-12,1,0.6,0,0,Math.PI*2);c.fill();
    c.beginPath();c.ellipse(1.8,-12,1,0.6,0,0,Math.PI*2);c.fill();

    // Crista dorsal animada
    {
      const spineCol=isCmd?'#ff9900':isBsk?'#ff1100':isCac?'#bb00ff':'#bb0044';
      const spineGlow=isCmd?'rgba(255,180,0,0.7)':isBsk?'rgba(255,40,0,0.7)':'rgba(200,0,80,0.6)';
      const spines=isCmd?
        [[-6,-20],[-3.5,-23],[-0.5,-25],[2.5,-24],[5.5,-21],[7,-18]]:
        isBsk?[[-5,-19],[-2,-22],[1,-23],[4,-21],[6,-18]]:
              [[-4,-19],[-1.5,-21],[2,-22],[5,-20]];
      spines.forEach(([sx,sy],si)=>{
        const sway=Math.sin(t*3.5+si*0.9+r.y*0.02)*(isCmd?2.5:1.8);
        c.beginPath();
        c.moveTo(sx-2,-14);
        c.quadraticCurveTo(sx+sway*0.5,(sy+(-14))*0.5,sx+sway,sy);
        c.lineTo(sx+sway+1.5,-14);
        c.closePath();
        c.fillStyle=spineCol;c.fill();
        c.strokeStyle=`${spineCol}88`;c.lineWidth=0.6;c.stroke();
      });
    }

    // Chifres do Comandante
    if(isCmd){
      c.fillStyle='rgba(255,190,0,0.92)';
      c.beginPath();c.moveTo(-5,-22);c.quadraticCurveTo(-8,-28,-6,-32);c.lineTo(-4,-22);c.closePath();c.fill();
      c.beginPath();c.moveTo(5,-22);c.quadraticCurveTo(8,-28,6,-32);c.lineTo(4,-22);c.closePath();c.fill();
      c.fillStyle='rgba(255,220,80,0.7)';
      c.beginPath();c.moveTo(-1.5,-24);c.lineTo(0,-29);c.lineTo(1.5,-24);c.fill();
    }

    // Visor tecnológico do Caçador
    if(isCac){
      c.strokeStyle='rgba(180,0,255,0.6)';c.lineWidth=1.2;
      c.beginPath();c.ellipse(-4,-17,3.5,2.5,0,0,Math.PI*2);c.stroke();
      c.beginPath();c.ellipse(4,-17,3.5,2.5,0,0,Math.PI*2);c.stroke();
      c.strokeStyle='rgba(180,0,255,0.3)';c.lineWidth=0.7;
      c.beginPath();c.moveTo(-0.5,-17);c.lineTo(0.5,-17);c.stroke();
    }

    // ── HP bar ──
    c.shadowBlur=0;
    const bw=34,bh=3.8,bx=-17,by=27;
    c.fillStyle='rgba(0,0,0,0.7)';c.fillRect(bx,by,bw,bh);
    const hpFrac=Math.max(0,r.hp/r.maxHP);
    const barCol=hpFrac>0.6?'#bb1100':hpFrac>0.3?'#dd3300':'#ff5500';
    c.fillStyle=barCol;c.fillRect(bx,by,bw*hpFrac,bh);
    c.fillStyle=`rgba(255,180,120,${0.15+0.1*Math.abs(pulse)})`;
    c.fillRect(bx,by,bw*hpFrac,bh*0.45);
    if(sz>=0.65){
      c.fillStyle='rgba(255,170,110,0.88)';c.font=`${8*sz}px monospace`;
      c.textAlign='center';c.fillText(r.cls,0,41*sz);
    }

    c.restore();
  }

  // ── Áudio ─────────────────────────────────────────────────────────
  let _audio=null;
  let _audioFadeInt=null;
  let _audioVol=0;
  let _audioStopping=false;
  function _startAudio(){
    if(_audio)return;
    _audioVol=0;_audioStopping=false;
    _audio=new Audio('songs/Invasions/Reptilian.ogg');
    _audio.loop=false;
    _audio.addEventListener('ended',()=>{if(_audio&&!_audioStopping){_audio.currentTime=0;_audio.play().catch(()=>{});}});
    _audio.volume=0;_audio.play().catch(()=>{});
    if(_audioFadeInt){clearInterval(_audioFadeInt);_audioFadeInt=null;}
    _audioFadeInt=setInterval(()=>{
      _audioVol=Math.min(0.55,_audioVol+0.025);
      if(_audio)_audio.volume=_audioVol;
      if(_audioVol>=0.55){clearInterval(_audioFadeInt);_audioFadeInt=null;}
    },80);
  }
  function _stopAudio(){
    _audioStopping=true;
    if(_audioFadeInt){clearInterval(_audioFadeInt);_audioFadeInt=null;}
    if(!_audio)return;
    _audioFadeInt=setInterval(()=>{
      _audioVol=Math.max(0,_audioVol-0.035);
      if(_audio)_audio.volume=_audioVol;
      if(_audioVol<=0){if(_audio){_audio.pause();_audio=null;}_audioStopping=false;clearInterval(_audioFadeInt);_audioFadeInt=null;}
    },80);
  }

  // ── Música do trio de Guardiões (Serpente/Camaleão/Dragão) ──────────
  // Cada forma tem sua própria faixa; troca com crossfade sequencial
  // (para a atual, sobe a nova) ao transformar.
  let _bossAudio=null;
  let _bossAudioFadeInt=null;
  let _bossAudioForm=null;
  const RFF_TRIPLE_BOSS_TRACKS={
    serpente:'songs/Invasions/Bosses/Galaxy_Annihilator/Triple_bosses/snake.ogg',
    camaleao:'songs/Invasions/Bosses/Galaxy_Annihilator/Triple_bosses/chameleon.ogg',
    dragao:'songs/Invasions/Bosses/Galaxy_Annihilator/Triple_bosses/dragon.ogg',
  };
  function _startTripleBossAudio(form){
    if(_bossAudio&&_bossAudioForm===form)return; // já tocando a faixa certa
    _stopTripleBossAudio();
    _bossAudioForm=form;
    const src=RFF_TRIPLE_BOSS_TRACKS[form];
    if(!src)return;
    _bossAudio=new Audio(src);
    _bossAudio.loop=false;
    _bossAudio._stopped=false;
    _bossAudio.addEventListener('ended',function(){
      if(this._stopped)return;
      this.currentTime=0;
      this.play().catch(()=>{});
    });
    let vol=0;
    _bossAudio.volume=0;
    _bossAudio.play().catch(()=>{});
    if(_bossAudioFadeInt){clearInterval(_bossAudioFadeInt);_bossAudioFadeInt=null;}
    const thisAudio=_bossAudio;
    _bossAudioFadeInt=setInterval(()=>{
      vol=Math.min(0.58,vol+0.03);
      if(_bossAudio===thisAudio)thisAudio.volume=vol;
      if(vol>=0.58){clearInterval(_bossAudioFadeInt);_bossAudioFadeInt=null;}
    },80);
  }
  function _stopTripleBossAudio(){
    _bossAudioForm=null;
    if(!_bossAudio)return;
    const dyingAudio=_bossAudio;
    dyingAudio._stopped=true; // impede o listener 'ended' de reviver esta faixa
    let vol=dyingAudio.volume;
    _bossAudio=null;
    const dyingFadeInt=setInterval(()=>{
      vol=Math.max(0,vol-0.035);
      dyingAudio.volume=vol;
      if(vol<=0){dyingAudio.pause();clearInterval(dyingFadeInt);}
    },80);
  }

  // ── Música do Quasord (Forma Final) — uma faixa por bloco de fases ──
  // Fases 1-3 compartilham a mesma faixa; Fase 4 e Fase 5 têm faixa própria.
  let _rffAudio=null;
  let _rffAudioFadeInt=null;
  let _rffAudioBlock=null; // '123' | '4' | '5'
  const RFF_PHASE_TRACKS={
    '123':'songs/Invasions/Bosses/Galaxy_Annihilator/Fase_123.ogg',
    '4':'songs/Invasions/Bosses/Galaxy_Annihilator/Fase_4.ogg',
    '5':'songs/Invasions/Bosses/Galaxy_Annihilator/Fase_5.ogg',
  };
  function _rffBlockForPhase(phase){
    return phase>=5?'5':phase>=4?'4':'123';
  }
  function _startRffAudio(phase){
    const block=_rffBlockForPhase(phase);
    if(_rffAudio&&_rffAudioBlock===block)return; // já tocando a faixa certa
    _stopRffAudio();
    _rffAudioBlock=block;
    const src=RFF_PHASE_TRACKS[block];
    if(!src)return;
    _rffAudio=new Audio(src);
    _rffAudio.loop=false;
    _rffAudio._stopped=false;
    _rffAudio.addEventListener('ended',function(){
      if(this._stopped)return;
      this.currentTime=0;
      this.play().catch(()=>{});
    });
    let vol=0;
    _rffAudio.volume=0;
    _rffAudio.play().catch(()=>{});
    if(_rffAudioFadeInt){clearInterval(_rffAudioFadeInt);_rffAudioFadeInt=null;}
    const thisAudio=_rffAudio;
    _rffAudioFadeInt=setInterval(()=>{
      vol=Math.min(0.6,vol+0.03);
      if(_rffAudio===thisAudio)thisAudio.volume=vol;
      if(vol>=0.6){clearInterval(_rffAudioFadeInt);_rffAudioFadeInt=null;}
    },80);
  }
  function _stopRffAudio(){
    _rffAudioBlock=null;
    if(!_rffAudio)return;
    const dyingAudio=_rffAudio;
    dyingAudio._stopped=true; // impede o listener 'ended' de reviver esta faixa
    let vol=dyingAudio.volume;
    _rffAudio=null;
    const dyingFadeInt=setInterval(()=>{
      vol=Math.max(0,vol-0.035);
      dyingAudio.volume=vol;
      if(vol<=0){dyingAudio.pause();clearInterval(dyingFadeInt);}
    },80);
  }

  // ── HUD ───────────────────────────────────────────────────────────
  function _updateHUD(){
    const alive=_reptilians.filter(r=>!r.dead).length;
    const fill=document.getElementById('reptilian-hp-fill');
    const lbl=document.getElementById('reptilian-hp-label');
    if(fill)fill.style.width=(alive>0?Math.round(alive/Math.max(1,alive+_reptilians.filter(r=>r.dead).length)*100):0)+'%';
    if(lbl)lbl.textContent=`🦎 INVASÃO REPTILIANA — Onda ${_wave}/${REP_WAVE_CONFIG.length} — ${alive} reptilianos`;
  }

  // ── Fim ───────────────────────────────────────────────────────────
  function _endInvasion(victory,customMsg){
    if(!_active)return;
    _active=false;
    if(_animFrame){cancelAnimationFrame(_animFrame);_animFrame=null;}
    if(_riftCtx&&_riftCanvas)_riftCtx.clearRect(0,0,_riftCanvas.width,_riftCanvas.height);
    _bgReptShips=[];
    _unlockCam();
    window._invasionActive=false;
    window._reptTripleBossForm=null;
    window._reptQuasordOnScreen=false;
    _stopAudio();
    _stopTripleBossAudio();
    _stopRffAudio();
    _setInvasionAstroLockUI(false,REPTILIAN_BLOCKED_ASTRO_TYPES);
    window._reptilianAstroCaps=null;
    const rac=document.getElementById('reptilian-astro-counters');
    if(rac)rac.style.display='none';
    const bar=document.getElementById('reptilian-invasion-bar');
    if(bar)bar.classList.remove('active');
    if(_riftCanvas)_riftCanvas.classList.remove('active');
    objects.length=0;
    _preStash.forEach(o=>{o._invasionDead=false;o.dead=false;objects.push(o);});
    _preStash=[];_reptilians=[];_portals=[];_ships=[];
    _reptBossActive=false;
    if(_reptBoss){_reptBoss=null;}
    _reptBossLasers=[];_reptBossClones=[];_reptBossGrabbed=[];
    _reptFinalForm=null; _rffBgStreaks=null;
    const reptBBar=document.getElementById('rept-boss-hp-bar');
    if(reptBBar)reptBBar.classList.remove('active');
    showTooltip(customMsg?customMsg:(victory?'🦎🏆 Invasão Reptiliana repelida!':'🦎💀 Os Reptilianos dominaram o universo.'));
    if(victory){
      _markInvasionWon('reptilian');
      // Recompensa de Logs por vitória — repetível a cada invasão vencida.
      if(typeof addLogs==='function'){
        addLogs(1200);
        setTimeout(()=>showTooltip('📊 +1200 LOGS pela vitória!'),1400);
      }
      // Recompensa de Quantiks por vitória — repetível a cada invasão vencida.
      if(typeof addQuantiks==='function'){
        addQuantiks(80);
        setTimeout(()=>showTooltip('⚛️ +80 Quantiks pela vitória!'),1900);
      }
      if(typeof rollInvasionMusicBoxDrops==='function')rollInvasionMusicBoxDrops('reptilian');
    }
  }

  // ── Timeout GLOBAL (20min+1min): força o recuo dos Reptilianos ──────
  // Reptilianos normais e Trio de Bosses: recuam com flash vermelho rápido.
  // Quasord: solta uma fala de zombaria e recua ignorando as 3 barreiras
  // (fases), encerrando a invasão de qualquer jeito.
  function _forceGlobalTimeoutEnd(){
    const isQuasord=!!_reptFinalForm;
    const isTrioBoss=!isQuasord&&(_reptBossActive||!!_reptBoss);
    if(isQuasord){
      _showRffTaunt('Era de se esperar seu fracasso, tente, mas você não é suficiente, lhe falta poder. Que você não vai ter de forma alguma',()=>{
        _endInvasion(false,'☠️ Quasord voltou para o abismo cósmico, a sorte não estava com você…');
      });
    } else {
      // Reptilianos normais ou Trio de Bosses: flash vermelho rápido e recuo imediato
      const flash=document.getElementById('reptilian-emergency-flash');
      if(flash){flash.style.opacity='1';setTimeout(()=>{flash.style.opacity='0';},350);}
      _endInvasion(false,isTrioBoss?'🦎 Os Guardiões Antigos recuaram...':'🦎 Os Reptilianos recuaram...');
    }
  }

  // ── Sequência da morte do Drexcy: DK-910 detecta algo colossal se
  // aproximando, perde o sinal no meio da fala (efeito de interferência,
  // reaproveitando o broken-theme já usado no cutscene do Quasord), e então
  // o próprio Quasord assume o balão (vermelho, sem retrato) para se revelar.
  function _showDrexcyDefeatSequence(cb){
    const overlay=document.getElementById('cosmy-overlay');
    const bubble=document.getElementById('cosmy-bubble');
    const msgEl=document.getElementById('cosmy-msg');
    const stepLbl=document.getElementById('cosmy-step-label');
    const nextBtn=document.getElementById('cosmy-next');
    const skipBtn=document.getElementById('cosmy-skip');
    const progressFill=document.getElementById('cosmy-progress-fill');
    const imgEl=document.getElementById('cosmy-img');
    const spotEl=document.getElementById('cosmy-spotlight');
    const arrowEl=document.getElementById('cosmy-arrow');
    if(!overlay||!bubble||!msgEl){_showQuasordReveal('As raças fracas... Alienígenas, Marcianos... me chamam de "Aniquilador de Galáxias". Um apelido de covardes para o que não compreendem. Meu nome real é Quasord. E você, pequeno Cosmonauta, não é digno de pronunciá-lo duas vezes.',cb);return;}
    // Ato 1: DK-910 alerta normalmente (balão padrão, tema dk910)
    bubble.classList.remove('blackholy-theme','dk910-theme','broken-theme');
    imgEl.classList.remove('blackholy-img','dk910-img');
    imgEl.src=DK910_IMAGES['assustado']||DK910_IMAGES['normal'];
    imgEl.classList.add('dk910-img');bubble.classList.add('dk910-theme');
    stepLbl.style.color='';stepLbl.textContent='DK-910 · ALERTA';
    progressFill.style.width='100%';
    skipBtn.style.display='none';nextBtn.style.display='none'; // sequência automática, sem interação
    spotEl.classList.remove('visible');arrowEl.classList.remove('visible');
    msgEl.classList.remove('cosmy-text-anim');void msgEl.offsetWidth;
    msgEl.innerHTML='Cosmonauta... estou captando uma <strong>assinatura energética colossal</strong> se aproximando. Os valores estão fora de qualquer escala conhe—';
    msgEl.classList.add('cosmy-text-anim');
    imgEl.classList.remove('cosmy-entrance');void imgEl.offsetWidth;imgEl.classList.add('cosmy-entrance');
    requestAnimationFrame(()=>overlay.classList.add('active'));
    // Ato 2: perde o sinal — glitch (broken-theme) com texto cortado
    setTimeout(()=>{
      bubble.classList.add('broken-theme');
      msgEl.classList.remove('cosmy-text-anim');void msgEl.offsetWidth;
      msgEl.innerHTML='--%$#@... SI-SINAL PERD%&#O...<br>DK-9-9<em>10 fora de a</em>#ance...';
      msgEl.classList.add('cosmy-text-anim');
      stepLbl.textContent='DK-910 · SEM SINAL';
    },2600);
    // Ato 3: balão do DK-910 some, balão vermelho do Quasord assume
    setTimeout(()=>{
      overlay.classList.remove('active');
      bubble.classList.remove('dk910-theme','broken-theme');
      imgEl.classList.remove('dk910-img');
      skipBtn.style.display='';nextBtn.style.display='';
      _showQuasordReveal('As raças fracas... Alienígenas, Marcianos... me chamam de "Aniquilador de Galáxias". Um apelido de covardes para o que não compreendem. Meu nome real é Quasord. E você, pequeno Cosmonauta, não é digno de pronunciá-lo duas vezes.',cb);
    },4600);
  }

  // ── Balão de revelação do Quasord — dispara uma única vez, quando o
  // Drexcy (última forma do Trio de Guardiões) morre. Pausa o jogo
  // (pointer-events bloqueados atrás do balão) até o jogador clicar em
  // "Continuar", só então a Forma Final é spawnada.
  function _showQuasordReveal(text,cb){
    const overlay=document.getElementById('quasord-overlay');
    const msg=document.getElementById('quasord-msg');
    if(!overlay||!msg){if(cb)cb();return;}
    msg.textContent=text;
    requestAnimationFrame(()=>overlay.classList.add('active'));
    const btn=document.getElementById('quasord-next');
    const onClick=()=>{
      overlay.classList.remove('active');
      btn.removeEventListener('click',onClick);
      setTimeout(()=>{if(cb)cb();},450);
    };
    if(btn)btn.addEventListener('click',onClick);
  }

  // ── Caixa de texto de zombaria do Quasord ───────────────────────────
  function _showRffTaunt(text,cb){
    const box=document.getElementById('rff-taunt-box');
    const txt=document.getElementById('rff-taunt-text');
    if(!box||!txt){if(cb)cb();return;}
    txt.textContent=text;
    requestAnimationFrame(()=>box.classList.add('show'));
    setTimeout(()=>{
      box.classList.remove('show');
      setTimeout(()=>{if(cb)cb();},450);
    },3600);
  }

  // ── Cenário de fundo: naves reptilianas cruzando + planetas reptilianos
  // (SVG) + detalhe extra (R.png) subindo de baixo pra cima, decorativos.
  // O visual da nave é o MESMO da Nave Reptiliana criável no mapa
  // (ReptilianEntity — destruidor triangular militar cinza aço, listra
  // vermelha, jatos, canhões, torre de comando), NÃO simplificado.
  let _bgReptShips=[];
  const _BG_REPT_SHIP_COUNT=[5,8];
  const _reptilianPlanetImg=new Image();
  _reptilianPlanetImg.src='images/Backelements/Rept/ReptilianPlanet.svg';
  const _reptilianExtraImg=new Image();
  _reptilianExtraImg.src='images/Backelements/Rept/R.png';
  function _bgDrawReptilianShipFull(ctx2,o,t){
    // Réplica do draw() de ReptilianEntity (casco triangular/jatos/canhões/
    // torre de comando/listra vermelha), sem estado de gameplay (strike,
    // escravização, escudo de escravos).
    // OTIMIZAÇÃO: gradientes trocados por cores sólidas (mesmo motivo do
    // fundo Alien/Marciano) — inclui remover o clip() que só existia para
    // a listra em gradiente, também caro por nave/frame.
    const r=Math.max(9,o.radius);
    const T=t+o.phase;
    ctx2.save();ctx2.translate(o.x,o.y);ctx2.rotate(o.rot);
    // Jatos traseiros
    const jetY=r*.72;
    [-r*.55,0,r*.55].forEach((jx,ji)=>{
      const jw=Math.max(2,r*.16), jh=Math.max(3,r*.18);
      ctx2.fillStyle='rgba(80,82,88,1)';ctx2.fillRect(jx-jw,jetY,jw*2,jh);
      ctx2.strokeStyle='rgba(120,120,130,.8)';ctx2.lineWidth=Math.max(.5,r*.03);
      ctx2.strokeRect(jx-jw,jetY,jw*2,jh);
      const flamePulse=.6+.4*Math.abs(Math.sin(T*6+ji*1.1));
      const flameLen=r*(.45+.25*flamePulse);
      ctx2.beginPath();ctx2.ellipse(jx,jetY+jh+flameLen*.4,jw*.5*flamePulse,flameLen*.6,0,0,Math.PI*2);
      ctx2.fillStyle='rgba(230,110,60,.65)';ctx2.fill();
    });
    // Casco triangular (cor sólida)
    const tipX=0, tipY=-r*.92;
    const baseLX=-r*.98, baseRX=r*.98, baseY=r*.68;
    ctx2.beginPath();
    ctx2.moveTo(tipX,tipY);ctx2.lineTo(baseRX,baseY);ctx2.lineTo(baseLX,baseY);
    ctx2.closePath();ctx2.fillStyle='rgba(150,153,160,1)';ctx2.fill();
    ctx2.strokeStyle='rgba(200,202,210,.9)';ctx2.lineWidth=Math.max(1.2,r*.07);ctx2.stroke();
    // Listra vermelha central (cor sólida, sem clip)
    const stripeW=Math.max(3,r*.18);
    ctx2.fillStyle='rgba(230,20,20,.8)';
    ctx2.fillRect(-stripeW,tipY,stripeW*2,baseY-tipY);
    // Canhões laterais
    [[-.72,.0],[-.88,.38],[.72,.0],[.88,.38]].forEach(([cx2,cy2],ci)=>{
      const cx3=cx2*r, cy3=cy2*r;
      const cLen=Math.max(3,r*(ci%2===0?.28:.22));
      const cW=Math.max(1.5,r*.07);
      ctx2.beginPath();ctx2.arc(cx3,cy3,Math.max(2,r*.09),0,Math.PI*2);
      ctx2.fillStyle='rgba(75,78,85,1)';ctx2.fill();
      ctx2.strokeStyle='rgba(140,143,150,.8)';ctx2.lineWidth=Math.max(.5,r*.03);ctx2.stroke();
      ctx2.save();ctx2.translate(cx3,cy3);ctx2.rotate(ci<2?-Math.PI*.5:Math.PI*.5);
      ctx2.fillStyle='rgba(50,52,58,1)';
      ctx2.fillRect(-cW*.5,-cLen,cW,cLen);
      ctx2.restore();
    });
    // Torre de comando (cor sólida)
    const towerY=-r*.28;
    ctx2.fillStyle='rgba(68,70,78,1)';
    ctx2.fillRect(-Math.max(2,r*.15),towerY-Math.max(2,r*.18),Math.max(4,r*.3),Math.max(4,r*.18));
    ctx2.beginPath();ctx2.ellipse(0,towerY-r*.1,Math.max(1.5,r*.1),Math.max(1,r*.07),0,0,Math.PI*2);
    ctx2.fillStyle='rgba(220,40,40,.9)';ctx2.fill();
    // Núcleo energético (cor sólida)
    const nPulse=.7+.3*Math.sin(T*5);
    ctx2.save();ctx2.rotate(Math.PI*.25+T*.3);
    ctx2.beginPath();ctx2.moveTo(0,-r*.14);ctx2.lineTo(r*.09,0);ctx2.lineTo(0,r*.14);ctx2.lineTo(-r*.09,0);ctx2.closePath();
    ctx2.fillStyle=`rgba(220,20,20,${nPulse})`;ctx2.fill();
    ctx2.restore();
    ctx2.restore();
  }
  function _bgSpawnReptShip(){
    const fromLeft=Math.random()<0.5;
    const y=rand(20,canvas.height-20);
    const speed=rand(150,280); // rápido — cenário de guerra
    _bgReptShips.push({
      kind:'ship',
      x:fromLeft?-60:canvas.width+60,
      y,
      vx:fromLeft?speed:-speed,
      vy:0,
      rot:fromLeft?Math.PI*.5:-Math.PI*.5,
      phase:rand(0,10),
      radius:rand(16,26),
    });
  }
  function _bgSpawnReptPlanet(){
    const fromLeft=Math.random()<0.5;
    const y=rand(canvas.height*0.1,canvas.height*0.9);
    const speed=rand(30,60);
    const r=rand(60,140);
    _bgReptShips.push({
      kind:'planet',
      x:fromLeft?-r*2:canvas.width+r*2,
      y,
      vx:fromLeft?speed:-speed,
      vy:0,
      r,
      phase:rand(0,10),
    });
  }
  function _bgSpawnReptExtra(){
    // Detalhe extra (R.png) — sobe de BAIXO pra CIMA (oposto do M.png marciano)
    const x=rand(20,canvas.width-20);
    const speed=rand(110,220);
    _bgReptShips.push({
      kind:'extra',
      x,
      y:canvas.height+60,
      vy:-speed,
      size:rand(28,52),
      rot:rand(0,Math.PI*2),
      rotSpeed:rand(-1.2,1.2),
    });
  }
  function _bgReptUpdateAndDraw(ctx2,dt,t){
    const targetCount=Math.round(rand(_BG_REPT_SHIP_COUNT[0],_BG_REPT_SHIP_COUNT[1]));
    if(_bgReptShips.length<targetCount&&Math.random()<0.06){
      const roll=Math.random();
      if(roll<0.2)_bgSpawnReptPlanet();
      else if(roll<0.45)_bgSpawnReptExtra(); // "nem tão raro", mas menos que naves
      else _bgSpawnReptShip();
    }
    _bgReptShips.forEach(o=>{
      if(o.vx)o.x+=o.vx*dt;
      if(o.vy)o.y+=o.vy*dt;
      if(o.kind==='extra')o.rot+=o.rotSpeed*dt;
    });
    _bgReptShips=_bgReptShips.filter(o=>
      o.y>-260 && o.y<canvas.height+260 && o.x>-260 && o.x<canvas.width+260);
    ctx2.save();
    ctx2.globalAlpha=0.32; // baixa opacidade, decorativo — visual completo do astro
    _bgReptShips.forEach(o=>{
      if(o.kind==='planet'){
        if(_reptilianPlanetImg.complete&&_reptilianPlanetImg.naturalWidth>0){
          ctx2.save();
          ctx2.translate(o.x,o.y);
          ctx2.drawImage(_reptilianPlanetImg,-o.r,-o.r,o.r*2,o.r*2);
          ctx2.restore();
        }
      } else if(o.kind==='extra'){
        if(_reptilianExtraImg.complete&&_reptilianExtraImg.naturalWidth>0){
          ctx2.save();
          ctx2.translate(o.x,o.y);
          ctx2.rotate(o.rot||0);
          ctx2.drawImage(_reptilianExtraImg,-o.size/2,-o.size/2,o.size,o.size);
          ctx2.restore();
        }
      } else {
        _bgDrawReptilianShipFull(ctx2,o,t);
      }
    });
    ctx2.restore();
  }

  // ── Tick ──────────────────────────────────────────────────────────
  let _lastTick=0;
  function _tick(ts){
    if(!_active)return;
    const dt=Math.min(0.05,(ts-_lastTick)/1000);
    _lastTick=ts;
    // Travar tempo (Mod Menu)
    if(!window._reptFreezeTime) _t+=dt;

    // ── Timeout GLOBAL: aos 20 minutos, avisa com toast; 1 minuto depois, força o fim ──
    if(!_globalWarnShown&&_t>=GLOBAL_WARN_AT){
      _globalWarnShown=true;
      showTooltip('⏰ 1 MINUTO SOBRANDO!');
    }
    if(_t>=GLOBAL_HARD_END){
      _forceGlobalTimeoutEnd();
      return;
    }

    // ── isQuasord: true assim que a Forma Final (Leviatã/Quasord) existe ──
    // Quando true, BLOQUEIA o every-tick de progressão/spawn/dano dos
    // Reptilianos comuns e do Boss Trio (Serpente/Camaleão/Dragão) — o
    // Quasord assume sozinho a tela. Isso é necessário além de zerar os
    // arrays uma vez, porque tanto os Reptilianos comuns quanto o Boss
    // Trio são DESENHADOS A CADA FRAME por este mesmo tick: só esvaziar o
    // array uma vez não impede que uma onda nova seja spawnada, nem que o
    // Boss Trio (se ainda instanciado) continue sendo tickado/desenhado
    // nos frames seguintes, competindo visualmente com o Quasord.
    const isQuasord=!!_reptFinalForm;
    if(isQuasord){
      // Reptilianos comuns: desativados por completo enquanto o Quasord existe.
      if(_reptilians.length){_reptilians.forEach(r=>{r.dead=true;});_reptilians=[];}
      if(_ships.length)_ships=[];
      if(_portals.length)_portals=[];
      // Boss Trio (Serpente/Camaleão/Dragão): parado e removido — nunca mais
      // tickado/desenhado enquanto isQuasord for true.
      if(_reptBossActive||_reptBoss){
        _reptBossActive=false;_reptBoss=null;
        _reptBossLasers=[];_reptBossClones=[];_reptBossGrabbed=[];
      }
    }

    // Pular para boss (Mod Menu) — sem efeito se o Quasord já estiver em campo
    if(window._reptSkipBoss&&!isQuasord){
      window._reptSkipBoss=false;
      _reptilians.forEach(r=>{r.dead=true;}); _reptilians=[];
      _ships=[]; _portals=[];
      _wave=REP_WAVE_CONFIG.length;
    }

    // ── Tick cooldown dos astros estelares de combate (limite justo) ──
    if(window._reptilianAstroCaps){
      Object.keys(window._reptilianAstroCaps).forEach(t=>{
        const cap=window._reptilianAstroCaps[t];
        if(cap.cooldown>0){
          cap.cooldown=Math.max(0,cap.cooldown-dt);
          _refreshReptilianAstroCounterUI(t,cap);
          if(cap.cooldown===0){
            cap.used=0;
            _refreshReptilianAstroCounterUI(t,cap);
            showTooltip(`✅ ${TYPE_LABELS[t]||t}: recarga completa! ${cap.max} uso(s) disponíveis.`);
          }
        } else {
          // Recontar objetos vivos para evitar valores negativos (astros destruídos)
          const alive=objects.filter(o=>!o.dead&&o.type===t).length;
          cap.used=Math.min(alive,cap.max);
          _refreshReptilianAstroCounterUI(t,cap);
        }
      });
    }

    // Progressão de ondas — bloqueada por completo enquanto isQuasord (Quasord assume a tela sozinho)
    if(!isQuasord){
      _waveTimer+=dt;
      if(_wave<REP_WAVE_CONFIG.length&&_waveTimer>=WAVE_INTERVAL&&_reptilians.filter(r=>!r.dead).length===0){
        _waveTimer=0;_wave++;
        _portals=[];_ships=[];
        _spawnPortalsAndShips();
        showTooltip(`🦎 Onda ${_wave} de Reptilianos chegou!`);
      }
    }

    const ar=_arenaRect||{x:0,y:0,w:canvas.width,h:canvas.height};
    const cx=ar.x+ar.w/2,cy=ar.y+ar.h/2;
    const cfg=REP_WAVE_CONFIG[Math.min(_wave,REP_WAVE_CONFIG.length)-1];

    // ── Tudo abaixo (Portais, Naves, Reptilianos comuns, spawn do Boss Trio)
    // é bloqueado por completo enquanto isQuasord for true — o Quasord já
    // zera esses arrays no topo do tick, mas o guard aqui impede também que
    // o spawn do Boss Trio (_spawnReptBoss) seja disparado de novo. ──────
    if(!isQuasord){
    // ── Portais ──
    _portals.forEach(p=>{
      p.age+=dt*0.6;
      p.sx+=p.vx;p.sy+=p.vy;
      p.vx*=0.985;p.vy*=0.985;
      // Spawna a nave depois do portal se abrir
      if(!p.shipSpawned&&p.age>1.2){
        p.shipSpawned=true;
        const ang=Math.atan2(cy-p.sy,cx-p.sx);
        _ships.push({
          x:p.sx,y:p.sy,
          rot:ang,
          vx:Math.cos(ang)*220,vy:Math.sin(ang)*220,
          t:0,phase:Math.random()*Math.PI*2,
          dead:false,unloaded:false,
          classWeights:cfg.weights,
        });
      }
    });

    // ── Naves ──
    _ships.forEach(s=>{
      if(s.dead)return;
      s.t+=dt;
      s.x+=s.vx*dt;s.y+=s.vy*dt;
      s.vx*=0.992;s.vy*=0.992;
      s.rot=Math.atan2(cy-s.y,cx-s.x);
      // Desembarca reptilianos quando chega perto do centro
      if(!s.unloaded&&Math.hypot(s.x-cx,s.y-cy)<Math.min(ar.w,ar.h)*0.35){
        s.unloaded=true;
        const n=3+Math.floor(Math.random()*3);
        for(let i=0;i<n;i++){
          let wi=0,rr=Math.random(),acc=0;
          for(let j=0;j<s.classWeights.length;j++){acc+=s.classWeights[j];if(rr<acc){wi=j;break;}}
          const cls=REP_CLASSES[wi];
          _reptilians.push({
            x:s.x+rand(-20,20),y:s.y+rand(-20,20),
            vx:rand(-30,30),vy:rand(-30,30),
            hp:cls.maxHP,maxHP:cls.maxHP,
            atk:cls.atk,speed:cls.speed,
            cls:cls.cls,color:cls.color,scale:cls.scale,
            dead:false,t:0,
            _atkTimer:1+Math.random()*1.5,
            _hitFlashT:0,flashColor:'#ffffff',
            paralyzed:0,
            // Animação de queda da nave
            _dropT:0,
          });
        }
        // Nave sai da arena depois de desembarcar
        s.vx=-Math.cos(s.rot)*200;s.vy=-Math.sin(s.rot)*200;
        setTimeout(()=>{s.dead=true;},2500);
      }
    });
    _ships=_ships.filter(s=>!s.dead);

    // ── Reptilianos ──
    _reptilians.forEach(r=>{
      if(r.dead)return;
      r.t+=dt;
      r._hitFlashT=Math.max(0,r._hitFlashT-dt*3);
      if(r.paralyzed>0)r.paralyzed=Math.max(0,r.paralyzed-dt);

      // Alvo: astro mais próximo — usa coordenadas de tela (sx/sy) igual aos aliens
      let target=null,bestD=Infinity;
      objects.forEach(o=>{
        if(o.dead)return;
        const dx=o.sx()-r.x,dy=o.sy()-r.y,d2=dx*dx+dy*dy;
        if(d2<bestD){bestD=d2;target=o;}
      });

      if(r.paralyzed<=0){
        if(target){
          const dx=target.sx()-r.x,dy=target.sy()-r.y,d=Math.sqrt(dx*dx+dy*dy)||1;
          r.vx+=dx/d*r.speed*1.1*dt;
          r.vy+=dy/d*r.speed*1.1*dt;
        } else {
          r.vx+=(Math.random()-.5)*r.speed*dt;
          r.vy+=(Math.random()-.5)*r.speed*dt;
        }
      }
      const spd=Math.sqrt(r.vx*r.vx+r.vy*r.vy)||1;
      if(spd>r.speed){r.vx=r.vx/spd*r.speed;r.vy=r.vy/spd*r.speed;}
      r.x+=r.vx*dt;r.y+=r.vy*dt;

      // Bounce nas bordas
      if(r.x<ar.x){r.x=ar.x;r.vx=Math.abs(r.vx)*.5;}
      if(r.x>ar.x+ar.w){r.x=ar.x+ar.w;r.vx=-Math.abs(r.vx)*.5;}
      if(r.y<ar.y){r.y=ar.y;r.vy=Math.abs(r.vy)*.5;}
      if(r.y>ar.y+ar.h){r.y=ar.y+ar.h;r.vy=-Math.abs(r.vy)*.5;}

      // Ataque a astros
      r._atkTimer=Math.max(0,r._atkTimer-dt);
      if(target&&r._atkTimer<=0){
        const tsx=target.sx(),tsy=target.sy();
        const dx=tsx-r.x,dy=tsy-r.y,d=Math.sqrt(dx*dx+dy*dy);
        const hitR=Math.max(target.sr()*1.2,55);
        if(d<hitR){
          if(target instanceof InvasionFleetEntity){
            target.takeDamage(r.atk);
          } else if(target.hp!==undefined){
            target.hp=Math.max(0,target.hp-r.atk);
            if(target.hp<=0)target.dead=true;
          } else if(Math.random()<0.15){
            target._invasionDead=true;target.dead=true;
            if(typeof spawnExplosion==='function')spawnExplosion(tsx,tsy,0.5,false);
            showTooltip(`🦎 Reptiliano destruiu ${target.name||target.type}!`);
          }
          r._atkTimer=0.7+Math.random()*1.0;
          r._hitFlashT=0.25;
        }
      }

      // Dano de astros ao reptiliano — coordenadas de tela
      objects.forEach(o=>{
        if(o.dead)return;
        const osx=o.sx(),osy=o.sy(),osr=o.sr();
        const dx=osx-r.x,dy=osy-r.y,d=Math.sqrt(dx*dx+dy*dy)||1;
        const key='_reptHit_'+o.type;
        if(r[key]>0){r[key]-=dt;return;}
        let dmg=0,cd=0,effect=null;
        // Astros base
        if(o.type==='quasar'&&d<osr*4)     {dmg=r.maxHP*.04;cd=4.5;effect='#ff44ff';}
        if(o.type==='pulsar'&&d<osr*10)    {dmg=r.maxHP*.03;cd=3.5;r.paralyzed=1.5;effect='#44ffff';}
        if(o.type==='blazar'&&d<osr*8)     {dmg=r.maxHP*.025;cd=3.0;effect='#ff8844';}
        if(o.type==='blackhole'&&d<osr*5)  {r.vx+=(osx-r.x)/d*1400*dt;r.vy+=(osy-r.y)/d*1400*dt;}
        if(o.type==='magnetar'&&d<osr*12)  {dmg=r.maxHP*.02;cd=5.0;r.paralyzed=2.5;effect='#cc44ff';}
        if((o.type==='star'||o.type==='cepheid')&&d<osr*3&&Math.random()<.009){dmg=r.maxHP*.01;cd=0;}
        // 10 astros do Pacote Estrelas (combate reptiliano)
        if(o.type==='quasiStar'&&d<osr*5)      {dmg=r.maxHP*.06;cd=2.5;effect='#ff8800';}
        if(o.type==='wolfRayet'&&d<osr*6)      {dmg=r.maxHP*.045;cd=2.0;effect='#44ffaa';}
        if(o.type==='hypergiant'&&d<osr*4)     {dmg=r.maxHP*.05;cd=2.5;effect='#ffcc00';}
        if(o.type==='gravastar'&&d<osr*3)      {dmg=r.maxHP*.02;cd=1.5;effect='#44aaff';}
        if(o.type==='ironStar'&&d<osr*3)       {dmg=r.maxHP*.025;cd=2.0;effect='#aa8855';}
        if(o.type==='whiteDwarf'&&d<osr*3)     {dmg=r.maxHP*.015;cd=1.0;effect='#ffffff';}
        if(o.type==='strangeStar'&&d<osr*4)    {dmg=r.maxHP*.055;cd=3.0;r.paralyzed=Math.max(r.paralyzed,1.2);effect='#aa44ff';}
        if(o.type==='vampireStar'&&d<osr*4)    {dmg=r.maxHP*.05;cd=3.0;r.paralyzed=Math.max(r.paralyzed,0.8);effect='#ff0044';}
        if(o.type==='janusStar'&&d<osr*5)      {dmg=r.maxHP*.03;cd=2.0;effect='#00ffff';}
        if(o.type==='electroweakStar'&&d<osr*5){dmg=r.maxHP*.04;cd=2.5;r.paralyzed=Math.max(r.paralyzed,2.0);effect='#ffff00';}
        if(dmg>0){
          r.hp=Math.max(0,r.hp-dmg);
          r._hitFlashT=0.35;r.flashColor=effect||'#ffffff';
          if(cd>0)r[key]=cd;
          // partícula de impacto
          if(typeof spawnExplosion==='function'&&Math.random()<0.3)
            spawnExplosion(r.x,r.y,0.18,false);
        }
      });

      if(r.hp<=0&&!r.dead)r.dead=true;
    });

    _reptilians=_reptilians.filter(r=>!r.dead);

    // Onda final limpa → spawn do boss (se ainda não ativo)
    if(_wave>=REP_WAVE_CONFIG.length&&_reptilians.length===0&&_ships.length===0&&_portals.every(p=>p.shipSpawned)){
      if(!_reptBossActive&&!_reptBoss&&!_reptFinalForm){
        _spawnReptBoss();
      }
    }
    } // fim if(!isQuasord)

    // ── Render ──
    const c=_riftCtx;
    c.clearRect(0,0,_riftCanvas.width,_riftCanvas.height);

    // ── Cenário de fundo: naves/planetas reptilianos + detalhe extra (R.png) ──
    _bgReptUpdateAndDraw(c,dt,_t);

    // ── Atmosfera de batalha da Forma Final: vinheta avermelhada sutil
    // + cometas/meteoros de fundo caindo, discretos, só durante o boss.
    if(_reptFinalForm) _tickRffBattleFx(dt,c);

    // Borda da arena
    const ar2=_arenaRect;
    if(ar2){
      const {x,y,w,h}=ar2; const x2=x+w, y2=y+h;
      const pulse=.55+.45*Math.sin(_t*2.5);
      const alpha=.5+.35*Math.sin(_t*3.1);
      c.save();
      c.strokeStyle=`rgba(220,20,10,${alpha})`;
      c.lineWidth=2.5;
      c.strokeRect(x,y,w,h);
      c.strokeStyle=`rgba(255,120,100,${alpha*.35})`;
      c.lineWidth=1;
      c.strokeRect(x+4,y+4,w-8,h-8);
      const cs=22;
      const corners=[
        [[x,y+cs],[x,y],[x+cs,y]],
        [[x2-cs,y],[x2,y],[x2,y+cs]],
        [[x,y2-cs],[x,y2],[x+cs,y2]],
        [[x2-cs,y2],[x2,y2],[x2,y2-cs]],
      ];
      corners.forEach(pts=>{
        c.beginPath();
        c.moveTo(pts[0][0],pts[0][1]);c.lineTo(pts[1][0],pts[1][1]);c.lineTo(pts[2][0],pts[2][1]);
        c.strokeStyle=`rgba(255,20,0,${.18*(.8+.2*pulse)})`;c.lineWidth=8;c.stroke();
        c.strokeStyle=`rgba(255,20,0,${.8+.2*pulse})`;c.lineWidth=3.2;c.stroke();
      });
      if(Math.random()<0.18){
        const side=Math.floor(Math.random()*4);
        let px,py;
        if(side===0){px=rand(x,x2);py=y;}
        else if(side===1){px=x2;py=rand(y,y2);}
        else if(side===2){px=rand(x,x2);py=y2;}
        else{px=x;py=rand(y,y2);}
        c.beginPath();c.arc(px,py,rand(1.5,4),0,Math.PI*2);
        c.fillStyle=`rgba(255,80,50,${rand(.4,.9)})`;c.fill();
      }
      c.restore();
    }
    _portals.forEach(p=>_drawPortal(c,p,_t));
    _ships.forEach(s=>{if(!s.dead)_drawShip(c,s,_t);});
    _reptilians.forEach(r=>{if(!r.dead)_drawReptilian(c,r,_t);});

    // ── Boss tick + draw (após clearRect) — nunca roda se isQuasord (Quasord já em campo) ──
    if(!isQuasord&&_reptBossActive&&_reptBoss) _tickReptBoss(dt,c);
    // ── Forma Final do Aniquilador ──
    if(_reptFinalForm){
      try{
        _tickReptFinalForm(dt,c);
      }catch(err){
        console.error('[RFF] Erro no tick do Leviatã:',err);
        if(!window._rffLastErrShown||Date.now()-window._rffLastErrShown>4000){
          window._rffLastErrShown=Date.now();
          showTooltip('💥 ERRO no Leviatã: '+(err&&err.message?err.message:String(err)));
        }
      }
    }

    // ── FX Particles do boss reptiliano ──
    _fxParticles=_fxParticles.filter(p=>p.life>0);
    if(_fxParticles.length>120)_fxParticles.splice(0,_fxParticles.length-120);
    c.save();
    _fxParticles.forEach(p=>{
      p.life-=0.016; p.x+=p.vx*0.016; p.y+=p.vy*0.016;
      const a=Math.max(0,p.life/p.maxLife)*p.alpha;
      if(a<=0)return;
      c.globalAlpha=a;
      c.beginPath(); c.arc(p.x,p.y,p.r,0,Math.PI*2);
      c.fillStyle=p.color; c.fill();
    });
    c.restore();

    _updateHUD();
    _animFrame=requestAnimationFrame(_tick);
  }

  // ── Aviso do Dr. Blackholy — interrompe antes da Invasão Reptiliana ──
  // A Reptiliana é a mais perigosa das três raças (invulnerável nas
  // primeiras fases, escraviza outras raças, Boss com 5 fases). O Dr.
  // Blackholy interrompe para alertar isso especificamente, seguindo o
  // mesmo padrão visual/estrutural do aviso da Cosmy (Alien) e do
  // DK-910 (Marciana).
  let _blackholyReptWarningShown=false;
  function _showBlackholyReptWarning(cb){
    const overlay=document.getElementById('cosmy-overlay');
    const msgEl=document.getElementById('cosmy-msg');
    const stepLbl=document.getElementById('cosmy-step-label');
    const progressFill=document.getElementById('cosmy-progress-fill');
    const nextBtn=document.getElementById('cosmy-next');
    const skipBtn=document.getElementById('cosmy-skip');
    const imgEl=document.getElementById('cosmy-img');
    const bubble=document.getElementById('cosmy-bubble');
    if(!overlay||!msgEl){if(cb)cb();return;}
    // Aparência Dr. Blackholy
    bubble.classList.remove('dk910-theme');
    bubble.classList.add('blackholy-theme');
    imgEl.classList.remove('dk910-img','cosmy-entrance');
    imgEl.classList.add('blackholy-img');
    void imgEl.offsetWidth;
    imgEl.classList.add('cosmy-entrance');
    imgEl.src=DR_IMAGES['assustado'];
    imgEl.style.opacity='1';
    stepLbl.style.color='rgba(200,100,255,.6)';
    const STEPS=[
      {msg:'…Interrompendo. <em>Agora</em>.<br><br>Detectei uma assinatura de invasão se formando — mas essa é diferente de tudo que você já enfrentou.',mood:'assustado'},
      {msg:'🦎 Os <strong>Reptilianos</strong> estão vindo.<br><br>Eles são <em>muito mais perigosos</em> que Aliens ou Marcianos: agressivos, colonizadores, e praticamente <strong>invulneráveis</strong> em suas primeiras formas.',mood:'raiva'},
      {msg:'Eles escravizam Aliens e Marcianos para usar como recurso. Não fazem alianças. Não recuam.<br><br>E no fim… algo <em>muito maior</em> emerge das profundezas.',mood:'transe',last:true},
    ];
    window._blackholyReptWarningActive=true;
    window._blackholyReptWarningStep=0;
    window._blackholyReptWarningSteps=STEPS;
    window._blackholyReptWarningCb=cb;
    overlay.classList.add('active');
    document.getElementById('cosmy-spotlight').classList.remove('visible');
    document.getElementById('cosmy-arrow').classList.remove('visible');
    function showStep(i){
      const s=STEPS[i];
      imgEl.classList.remove('cosmy-entrance');
      void imgEl.offsetWidth;
      imgEl.classList.add('cosmy-entrance');
      imgEl.src=DR_IMAGES[s.mood]||DR_IMAGES['neutro'];
      msgEl.classList.remove('cosmy-text-anim');void msgEl.offsetWidth;
      msgEl.innerHTML=s.msg;msgEl.classList.add('cosmy-text-anim');
      stepLbl.textContent=`Dr. Blackholy · ALERTA ${i+1} DE ${STEPS.length}`;
      progressFill.style.width=((i+1)/STEPS.length*100)+'%';
      if(s.last){nextBtn.textContent='🦎 Estou pronto.';nextBtn.classList.add('finish');}
      else{nextBtn.textContent='Próximo →';nextBtn.classList.remove('finish');}
      skipBtn.textContent='Pular aviso';
      window._blackholyReptWarningStep=i;
    }
    showStep(0);
    window._blackholyReptWarningShowStep=showStep;
  }
  function _handleBlackholyReptWarningNext(){
    const steps=window._blackholyReptWarningSteps||[];
    const cur=window._blackholyReptWarningStep||0;
    const s=steps[cur];
    if(!s)return;
    if(s.last)_endBlackholyReptWarning(true);
    else window._blackholyReptWarningShowStep&&window._blackholyReptWarningShowStep(cur+1);
  }
  function _endBlackholyReptWarning(start){
    window._blackholyReptWarningActive=false;
    const overlay=document.getElementById('cosmy-overlay');
    const bubble=document.getElementById('cosmy-bubble');
    const imgEl=document.getElementById('cosmy-img');
    const stepLbl=document.getElementById('cosmy-step-label');
    bubble.classList.remove('blackholy-theme');
    imgEl.classList.remove('blackholy-img');
    stepLbl.style.color='';
    overlay.style.opacity='0';
    setTimeout(()=>{
      overlay.classList.remove('active');overlay.style.opacity='';
      document.getElementById('cosmy-spotlight').classList.remove('visible');
      document.getElementById('cosmy-arrow').classList.remove('visible');
    },400);
    const cb=window._blackholyReptWarningCb;window._blackholyReptWarningCb=null;
    if(start&&cb)setTimeout(cb,500);
  }
  // Expõe handler do aviso reptiliano para o dispatcher central
  window._handleBlackholyReptWarningEnd=function(start){_endBlackholyReptWarning(start);};

  // ── Iniciar ───────────────────────────────────────────────────────
  function startInvasion(){
    if(_active)return;
    if((typeof AlienInvasion!=='undefined'&&AlienInvasion.isActive())||
       (typeof MarsianInvasion!=='undefined'&&MarsianInvasion.isActive())){
      showTooltip('🦎 Outra invasão está em andamento!');return;
    }
    _active=true;_t=0;_wave=1;_waveTimer=0;_globalWarnShown=false;
    _reptilians=[];_portals=[];_ships=[];
    _preStash=objects.filter(o=>!o.dead);
    objects.length=0;
    window._invasionActive=true;
    _lockCam();
    _buildArena();
    _riftCanvas=document.getElementById('reptilian-rift-canvas');
    _riftCtx=_riftCanvas.getContext('2d');
    _riftCanvas.width=canvas.width;_riftCanvas.height=canvas.height;
    _riftCanvas.style.left=canvas.style.left||'0px';
    _riftCanvas.style.top=canvas.style.top||'0px';
    _riftCanvas.style.width=canvas.width+'px';
    _riftCanvas.style.height=canvas.height+'px';
    _riftCanvas.classList.add('active');
    const bar=document.getElementById('reptilian-invasion-bar');
    if(bar)bar.classList.add('active');
    _startAudio();
    _setInvasionAstroLockUI(true,REPTILIAN_BLOCKED_ASTRO_TYPES);
    // Limite justo de astros estelares de combate (max+cooldown+despawn por tipo)
    window._reptilianAstroCaps={};
    Object.keys(REPTILIAN_SP_CAP_CONFIG).forEach(t=>{
      const cfg=REPTILIAN_SP_CAP_CONFIG[t];
      window._reptilianAstroCaps[t]={max:cfg.max,used:0,cooldown:0,cooldownTime:cfg.cooldownTime,despawn:cfg.despawn||0};
    });
    const rac=document.getElementById('reptilian-astro-counters');
    if(rac)rac.style.display='flex';
    Object.keys(window._reptilianAstroCaps).forEach(t=>{
      const el=document.getElementById(`reptilian-${t}-counter`);
      if(el)el.classList.remove('depleted','cooldown');
      _refreshReptilianAstroCounterUI(t,window._reptilianAstroCaps[t]);
    });
    setTimeout(()=>{if(_active)_spawnPortalsAndShips();},1800);
    showTooltip('🦎🔥 INVASÃO REPTILIANA! Eles vieram cobrar a Escama!');
    _lastTick=performance.now();
    _animFrame=requestAnimationFrame(_tick);
  }


  // ══════════════════════════════════════════════════════════════════
  //  BOSS: ANIQUILADOR DE GALÁXIAS
  //  3 Transformações: Serpente → Camaleão → Dragão
  //  Cada transformação tem 3 Fases próprias
  // ══════════════════════════════════════════════════════════════════
  let _reptBossActive=false;
  let _reptBoss=null;
  let _reptBossLasers=[];
  let _reptBossClones=[];
  let _reptBossGrabbed=[];
  let _reptFinalForm=null;

  // HP total dividido em 3 transformações × 3 fases
  // Serpente: 120k | Camaleão: 160k | Dragão: 240k
  const REPT_BOSS_SERP_HP  = 120000;
  const REPT_BOSS_CAM_HP   = 160000;
  const REPT_BOSS_DRAG_HP  = 240000;
  // Thresholds de fase dentro de cada transformação (% do HP da transformação)
  const PHASE2_PCT=0.65;
  const PHASE3_PCT=0.30;

  function _spawnReptBoss(){
    if(_reptBossActive)return;
    _reptBossActive=true;
    window._reptTripleBossForm='serpente';
    _reptilians.forEach(r=>{r.dead=true;}); _reptilians=[];
    _ships=[]; _portals=[];
    _stopAudio();
    _startTripleBossAudio('serpente');
    const ar=_arenaRect||{x:0,y:0,w:_riftCanvas.width,h:_riftCanvas.height};
    const cx=ar.x+ar.w/2;
    _reptBoss={
      x:cx, y:ar.y-90,
      vx:0, vy:0,
      // Transformação actual: 'serpente' | 'camaleao' | 'dragao'
      form:'serpente',
      formHP:REPT_BOSS_SERP_HP, formMaxHP:REPT_BOSS_SERP_HP,
      phase:1, t:0, moveAngle:0,
      // --- Serpente ---
      claws:[
        {ext:0,maxExt:1,angle:Math.PI*0.25,grabbed:null,grabCd:0,retracting:false},
        {ext:0,maxExt:1,angle:Math.PI*0.75,grabbed:null,grabCd:0,retracting:false},
        {ext:0,maxExt:1,angle:Math.PI*1.25,grabbed:null,grabCd:0,retracting:false},
        {ext:0,maxExt:1,angle:Math.PI*1.75,grabbed:null,grabCd:0,retracting:false},
      ],
      vaporTimer:0,
      swallowCd:0,
      // --- Fase 1: Investida (mordida) ---
      strikeState:'idle', strikeCd:2.2, strikeT:0, strikeTarget:null,
      strikeFromX:0, strikeFromY:0,
      // --- Fase 2+: Cone de veneno (substitui lasers genéricos) ---
      laserTimer:0,
      venomTimer:0, venomCones:[],
      invis:false, invisTimer:0, invisCd:8,
      // --- Fase 3: Enxame + Constrição em espiral (substitui raios de confusão) ---
      cloneTimer:0,
      confuseTimer:0, confuseRays:[],
      constrictState:'idle', constrictCd:5, constrictT:0,
      // --- Camaleão ---
      camouflageAlpha:1,   // 1=visível 0=invisível
      camHiding:false, camTimer:0, camCd:0,
      ambushReady:false, ambushTimer:0, ambushTarget:null, _ambushBonus:false,
      toxicTimer:0, toxicClouds:[],
      mirrorTimer:0,
      // --- Dragão ---
      fireBreathTimer:0, fireBreaths:[],
      wingSpread:0,
      diveBomb:false, diveBombTimer:0, diveBombTarget:null,
      roarTimer:0, roarWave:0,
      meteorTimer:0,
      // --- Visuais gerais ---
      rot:0, flashT:0, flashColor:'#ff2200',
      glitchIntensity:0,
      dying:false, dyingT:0,
    };
    _reptBossLasers=[]; _reptBossClones=[]; _reptBossGrabbed=[];
    const bar=document.getElementById('rept-boss-hp-bar');
    if(bar)bar.classList.add('active');
  // ── Nomes próprios do Trio de Guardiões Antigos (chaves internas
  // 'serpente'/'camaleao'/'dragao' seguem inalteradas no código) ──────
  const TRIPLE_BOSS_NAMES={serpente:'Solaris',camaleao:'Nebulon',dragao:'Drexcy'};

    document.getElementById('rept-boss-hp-fill').style.width='100%';
    document.getElementById('rept-boss-hp-fill').className='';
    document.getElementById('rept-boss-hp-phase').textContent='FASE 1';
    document.getElementById('rept-boss-hp-subtitle').textContent='🐍 FORMA: SOLARIS';
    showTooltip('🦎☠️ ANIQUILADOR DE GALÁXIAS — SOLARIS EMERGIU!');
  }

  function _getReptBossPhase(){
    if(!_reptBoss)return 1;
    const pct=_reptBoss.formHP/_reptBoss.formMaxHP;
    if(pct>PHASE2_PCT)return 1;
    if(pct>PHASE3_PCT)return 2;
    return 3;
  }

  function _updateReptBossBar(){
    if(!_reptBoss)return;
    const fill=document.getElementById('rept-boss-hp-fill');
    const phaseLbl=document.getElementById('rept-boss-hp-phase');
    const sub=document.getElementById('rept-boss-hp-subtitle');
    const pct=Math.max(0,_reptBoss.formHP/_reptBoss.formMaxHP*100);
    if(fill){fill.style.width=pct+'%';}
    if(phaseLbl)phaseLbl.textContent='FASE '+_reptBoss.phase;
    const formLabel={serpente:'🐍 SOLARIS',camaleao:'🦎 NEBULON',dragao:'🐉 DREXCY'};
    if(sub)sub.textContent=formLabel[_reptBoss.form]||'';
  }

  function _flashReptBoss(color){
    if(!_reptBoss)return;
    _reptBoss.flashT=0.35; _reptBoss.flashColor=color||'#ffffff';
  }

  // ── Transforma o boss para a próxima forma ──
  function _transformReptBoss(){
    const b=_reptBoss; if(!b)return;
    const nextForm=b.form==='serpente'?'camaleao':b.form==='camaleao'?'dragao':null;
    if(!nextForm){b.dying=true;b.dyingT=0;return;}
    b.form=nextForm;
    window._reptTripleBossForm=nextForm;
    b.phase=1;
    _startTripleBossAudio(nextForm);
    b.formMaxHP=nextForm==='camaleao'?REPT_BOSS_CAM_HP:REPT_BOSS_DRAG_HP;
    b.formHP=b.formMaxHP;
    b.moveAngle=0; b.vx=0; b.vy=0;
    // Reset lasers/clones
    _reptBossLasers=[]; _reptBossClones=[];
    b.confuseRays=[];
    // Limpa estados específicos da Serpente (Solaris)
    b.strikeState='idle'; b.strikeT=0; b.strikeTarget=null;
    b.venomCones=[]; b.venomTimer=0;
    b.constrictState='idle'; b.constrictT=0;
    // Limpa estados específicos
    b.invis=false; b.invisTimer=0; b.invisCd=10;
    b.camouflageAlpha=1; b.camHiding=false; b.camTimer=0; b.camCd=0;
    b.toxicClouds=[]; b.fireBreaths=[];
    b.ambushReady=false; b.ambushTimer=0; b.ambushTarget=null; b._ambushBonus=false;
    b.mirrorTimer=0; b.toxicTimer=0;
    // Estado novo do camaleão
    b.tongueState=null; b.tongueTip={x:b.x,y:b.y};
    b.killParticles=[]; b.tailWhipCd=0; b.tailWhipT=0; b.laserTimer=0;
    // Estado do dragão
    b.dragState=null; b.screenBeams=[]; b.meteorWarnings=[]; b.glitchTraps=[];
    b.fireBreaths=[]; b.clawState='idle'; b.clawT=0; b.clawTarget=null;
    b.roarRings=[]; b.roarTimer=0;
    b.diveBomb=false;
    document.getElementById('rept-boss-hp-fill').className='';
    _updateReptBossBar();
    const msgs={camaleao:'🦎 TRANSFORMAÇÃO! ANIQUILADOR — FORMA NEBULON!',dragao:'🐉 TRANSFORMAÇÃO FINAL! ANIQUILADOR — FORMA DREXCY!'};
    showTooltip(msgs[nextForm]);
    document.getElementById('reptilian-emergency-flash').style.opacity='1';
    setTimeout(()=>{document.getElementById('reptilian-emergency-flash').style.opacity='0';},700);

    // ── Fase Camaleão: +1 no limite de TODOS os astros do Pacote Estrelas ──
    if(nextForm==='camaleao'&&window._reptilianAstroCaps){
      Object.keys(window._reptilianAstroCaps).forEach(t=>{
        window._reptilianAstroCaps[t].max+=1;
        _refreshReptilianAstroCounterUI(t,window._reptilianAstroCaps[t]);
      });
      setTimeout(()=>showTooltip('⬆️ Fase Nebulon: limite de todos os astros +1!'),1600);
    }
  }

  function _tickReptBoss(dt,ctx){
    if(!_reptBoss)return;
    const b=_reptBoss;
    b.t+=dt;
    const c2=ctx;
    const ar=_arenaRect||{x:0,y:0,w:_riftCanvas.width,h:_riftCanvas.height};
    const W=ar.w,H=ar.h,bx=ar.x,by=ar.y;

    // ══════════════════
    //  MORTE
    // ══════════════════
    if(b.dying){
      b.dyingT+=dt;
      const dg=Math.min(1,b.dyingT/5);
      if(Math.random()<dg*0.65){b.x+=rand(-dg*18,dg*18);b.y+=rand(-dg*14,dg*14);}
      if(Math.random()<dg*0.5){
        _fxParticles.push({x:b.x+rand(-70,70),y:b.y+rand(-70,70),
          vx:rand(-60,60),vy:rand(-60,60),r:rand(3,11),alpha:1,
          color:Math.random()<0.5?'#ff2200':'#ffaa00',life:0.9,maxLife:0.9});
      }
      b.glitchIntensity=dg;
      _drawReptBoss(c2,b,_t);
      if(b.dyingT>=5.5){
        for(let i=0;i<60;i++){
          c2.beginPath();c2.arc(b.x+rand(-100,100),b.y+rand(-100,100),rand(5,28),0,Math.PI*2);
          c2.fillStyle=`rgba(200,0,0,${Math.random()*0.9})`;c2.fill();
        }
        // Não encerrar invasão — spawnar Forma Final
        // Guard: só spawna se ainda não existir uma Forma Final ativa,
        // evitando duplo-spawn (que resetaria o progresso das ondas).
        if(!_reptFinalForm){
          console.log('[RFF] Dragão morreu — spawnando Forma Final (única vez).');
          _reptBoss=null;_reptBossActive=false;
          _reptBossLasers=[];_reptBossClones=[];_reptBossGrabbed=[];
          _stopTripleBossAudio();
          _startRffAudio(1);
          if(typeof _bossAchTrigger==='function')_bossAchTrigger('guardians');
          _showDrexcyDefeatSequence(()=>{
            _spawnReptFinalForm();
          });
        } else {
          console.warn('[RFF] Dragão morreu, mas Forma Final já existe — spawn ignorado.');
          _reptBoss=null;_reptBossActive=false;
          _reptBossLasers=[];_reptBossClones=[];_reptBossGrabbed=[];
        }
      }
      _updateReptBossBar();
      return;
    }

    // ══════════════════
    //  TRANSIÇÃO DE FASE dentro da transformação
    // ══════════════════
    const phase=_getReptBossPhase();
    if(phase!==b.phase){
      b.phase=phase;
      const phaseEl=document.getElementById('rept-boss-hp-phase');
      const fillEl=document.getElementById('rept-boss-hp-fill');
      if(phaseEl)phaseEl.textContent='FASE '+phase;
      if(fillEl)fillEl.className=phase===2?'phase2':phase===3?'phase3':'';
      document.getElementById('reptilian-emergency-flash').style.opacity='1';
      setTimeout(()=>{document.getElementById('reptilian-emergency-flash').style.opacity='0';},500);
      const msgs={
        serpente:{2:'🐍 SOLARIS — FASE 2 — Lasers e invisibilidade!',3:'🐍 SOLARIS — FASE FINAL — Clones e raios de confusão!'},
        camaleao:{2:'🦎 NEBULON — FASE 2 — Camuflagem total e emboscada!',3:'🦎 NEBULON — FASE FINAL — Espelhos e nuvens tóxicas!'},
        dragao:{2:'🐉 DREXCY — FASE 2 — Mergulho bomba e sopro de fogo!',3:'🐉 DREXCY — FASE FINAL — Chuva de meteoros e rugido cósmico!'},
      };
      showTooltip((msgs[b.form]||{})[phase]||'Nova fase!');
      if(b.form==='serpente'&&phase===2){b.invisCd=5;}
      if(b.form==='camaleao'&&phase===2){b.camCd=3;}
      if(b.form==='dragao'&&phase===2){b.wingSpread=0;}
      b.flashT=0.8;b.flashColor='#ff0000';
      _updateReptBossBar();
    }

    // ══════════════════
    //  TRANSIÇÃO DE TRANSFORMAÇÃO (HP zerou)
    // ══════════════════
    if(b.formHP<=0&&!b.dying){
      if(b.form==='dragao'){b.dying=true;b.dyingT=0;showTooltip('💥 Aniquilador colapsando!');}
      else{_transformReptBoss();}
      return;
    }

    // ══════════════════
    //  MOVIMENTO (igual para todas as formas, velocidade varia)
    // ══════════════════
    const formSpd={serpente:[130,210,330],camaleao:[210,320,470],dragao:[190,290,430]};
    const formTurn={serpente:[0.9,1.5,2.4],camaleao:[1.1,1.8,2.9],dragao:[1.3,2.1,3.5]};
    const spd=(formSpd[b.form]||formSpd.serpente)[phase-1];
    const turnSpd=(formTurn[b.form]||formTurn.serpente)[phase-1];
    if(b.form==='camaleao'){
      if(!b.camState){b.camState='pause';b.camStateT=1.2;b.camWalkT=0;b.camHeadAngle=0;}
      b.camStateT-=dt;
      if(b.camState==='pause'&&b.camStateT<=0){
        b.camState='move';
        const ang=Math.random()*Math.PI*2;
        const dist=80+Math.random()*(Math.min(W,H)*0.38);
        b._camTx=Math.max(bx+70,Math.min(bx+W-70,b.x+Math.cos(ang)*dist));
        b._camTy=Math.max(by+70,Math.min(by+H-90,b.y+Math.sin(ang)*dist));
        b.camStateT=1.5+Math.random()*2.0;
        b.camWalkT=0;
      } else if(b.camState==='move'&&b.camStateT<=0){
        b.camState='pause';
        b.camStateT=0.9+Math.random()*1.8;
        b.vx*=0.1;b.vy*=0.1;
      }
      if(b.camState==='move'&&b._camTx!==undefined){
        b.camWalkT=(b.camWalkT||0)+dt;
        const ddx2=b._camTx-b.x,ddy2=b._camTy-b.y,dd2=Math.max(1,Math.hypot(ddx2,ddy2));
        const slowF=Math.min(1,dd2/60);
        b.vx+=(ddx2/dd2*spd*slowF-b.vx)*dt*4.5;
        b.vy+=(ddy2/dd2*spd*slowF-b.vy)*dt*4.5;
        if(dd2<18){b.camState='pause';b.camStateT=0.9+Math.random()*1.8;b.vx*=0.15;b.vy*=0.15;}
        const ms=Math.hypot(b.vx,b.vy);
        if(ms>10)b.camHeadAngle=Math.atan2(b.vy,b.vx);
      } else {
        b.vx*=Math.pow(0.04,dt);b.vy*=Math.pow(0.04,dt);
        b.camWalkT=0;
      }
    } else {
      b.moveAngle+=dt*turnSpd;
      let tx,ty;
      if(phase===1){tx=bx+W*0.15+Math.abs(Math.cos(b.moveAngle))*W*0.70;ty=by+H*0.12+Math.abs(Math.sin(b.moveAngle*0.7))*H*0.76;}
      else if(phase===2){tx=bx+W/2+Math.cos(b.moveAngle)*W*0.38;ty=by+H/2+Math.sin(b.moveAngle*1.3)*H*0.34;}
      else{tx=bx+W/2+Math.cos(b.moveAngle)*W*0.44+Math.sin(b.t*2.1)*W*0.11;ty=by+H/2+Math.sin(b.moveAngle*1.6)*H*0.40+Math.cos(b.t*1.7)*H*0.09;}
      if(b.diveBomb&&b.diveBombTarget){tx=b.diveBombTarget.x;ty=b.diveBombTarget.y;}
      const ddx=tx-b.x,ddy=ty-b.y,dd=Math.max(1,Math.hypot(ddx,ddy));
      b.vx+=(ddx/dd*spd-b.vx)*dt*(phase===1?3.2:phase===2?4.2:5.8);
      b.vy+=(ddy/dd*spd-b.vy)*dt*(phase===1?3.2:phase===2?4.2:5.8);
    }
    b.x+=b.vx*dt;b.y+=b.vy*dt;
    b.x=Math.max(bx+70,Math.min(bx+W-70,b.x));
    b.y=Math.max(by+70,Math.min(by+H-90,b.y));

    // ══════════════════
    //  ── FORMA: SERPENTE ──
    // ══════════════════
    if(b.form==='serpente'){
      // FASE 1: 4 ganchos extensíveis que agarram astros + evaporação
      const S2=52;
      const clawMaxLen=S2*3.2;
      b.claws.forEach((cl,ci)=>{
        cl.grabCd=Math.max(0,cl.grabCd-dt);
        if(cl.grabbed&&cl.grabbed.dead){cl.grabbed=null;cl.retracting=true;}
        if(cl.grabbed){
          // Mantém o astro preso (move junto com o gancho)
          const hookX=b.x+Math.cos(cl.angle)*clawMaxLen*cl.ext;
          const hookY=b.y+Math.sin(cl.angle)*clawMaxLen*cl.ext;
          cl.grabbed.x=hookX; // coordenada mundo não faz sentido aqui — usa sx/sy
          // Dano contínuo ao astro preso
          if(cl.grabbed._invasionHP===undefined)cl.grabbed._invasionHP=100;
          cl.grabbed._invasionHP=Math.max(0,cl.grabbed._invasionHP-12*dt);
          if(cl.grabbed._invasionHP<=0){
            cl.grabbed._invasionDead=true;cl.grabbed.dead=true;
            showTooltip(`🐍 Gancho destruiu ${cl.grabbed.name||cl.grabbed.type}!`);
            cl.grabbed=null;cl.retracting=true;cl.grabCd=2.5;
          }
          // Recolhe gancho lentamente
          cl.ext=Math.max(cl.ext,0.9);
        } else if(cl.retracting){
          cl.ext=Math.max(0,cl.ext-dt*1.4);
          if(cl.ext<=0){cl.retracting=false;}
        } else {
          // Estende o gancho em busca de astros
          cl.ext=Math.min(1,cl.ext+dt*0.6);
          if(cl.ext>=0.9&&cl.grabCd<=0){
            const hookX=b.x+Math.cos(cl.angle)*clawMaxLen*cl.ext;
            const hookY=b.y+Math.sin(cl.angle)*clawMaxLen*cl.ext;
            let best=null,bestD=clawMaxLen*0.35;
            objects.forEach(o=>{
              if(o.dead)return;
              const d=Math.hypot(o.sx()-hookX,o.sy()-hookY);
              if(d<bestD){bestD=d;best=o;}
            });
            if(best){cl.grabbed=best;cl.retracting=false;showTooltip(`🐍 Gancho agarrou ${best.name||best.type}!`);}
          }
          // Rotaciona suavemente os ganchos
          cl.angle+=dt*(0.25+ci*0.08)*Math.sin(b.t*0.5+ci);
        }
      });

      // Evaporação de astros próximos
      b.vaporTimer+=dt;
      const vaporInterval=phase===1?0.55:phase===2?0.4:0.28;
      if(b.vaporTimer>=vaporInterval){
        b.vaporTimer=0;
        const vR=(phase===1?140:phase===2?180:230);
        objects.forEach(o=>{
          if(o.dead)return;
          const d=Math.hypot(o.sx()-b.x,o.sy()-b.y);
          if(d<vR){
            if(o._invasionHP===undefined)o._invasionHP=100;
            const dmg=phase===1?5:phase===2?9:15;
            o._invasionHP=Math.max(0,o._invasionHP-dmg);
            if(Math.random()<0.3)_fxParticles.push({x:o.sx()+rand(-8,8),y:o.sy()+rand(-8,8),
              vx:rand(-15,15),vy:rand(-25,-5),r:rand(2,5),alpha:0.7,color:'rgba(200,80,0,0.8)',life:0.5,maxLife:0.5});
            if(o._invasionHP<=0&&!o._invasionDead){
              o._invasionDead=true;o.dead=true;
              b.claws.forEach(cl=>{if(cl.grabbed===o){cl.grabbed=null;cl.ext=0;cl.grabCd=2;}});
              showTooltip(`⚠️ Solaris evaporou ${o.name||o.type}!`);
            }
          }
        });
      }

      // ════ FASE 1 (todas as fases): INVESTIDA DE MORDIDA ════
      // Ataque ativo — a serpente escolhe um alvo e dá um bote rápido
      // até ele, causando dano de impacto na chegada. Antes a Fase 1
      // era puramente passiva (só ganchos+evaporação); agora tem uma
      // ação de iniciativa própria, como as outras duas formas têm.
      b.strikeCd=Math.max(0,b.strikeCd-dt);
      if(b.strikeState==='idle'&&b.strikeCd<=0){
        const alive=objects.filter(o=>!o.dead);
        if(alive.length>0){
          b.strikeTarget=alive[~~(Math.random()*alive.length)];
          b.strikeState='coiling'; b.strikeT=0;
          b.strikeFromX=b.x; b.strikeFromY=b.y;
          showTooltip('🐍〰️ Solaris se enrosca para atacar!');
        }
      }
      if(b.strikeState==='coiling'){
        b.strikeT+=dt;
        // Trava a posição levemente vibrando (telegraph do bote)
        if(b.strikeT>=0.55){
          b.strikeState='striking'; b.strikeT=0;
          b.strikeFromX=b.x; b.strikeFromY=b.y;
        }
      }
      if(b.strikeState==='striking'){
        b.strikeT+=dt;
        const dur=phase===1?0.30:phase===2?0.22:0.16;
        const prog=Math.min(1,b.strikeT/dur);
        // Easing "explosivo": lento no início, muito rápido no fim
        const ease=prog*prog*prog;
        if(b.strikeTarget&&!b.strikeTarget.dead){
          b.x=b.strikeFromX+(b.strikeTarget.sx()-b.strikeFromX)*ease;
          b.y=b.strikeFromY+(b.strikeTarget.sy()-b.strikeFromY)*ease;
        }
        if(prog>=1){
          // Impacto: dano forte no alvo + em qualquer astro próximo
          const impR=phase===1?70:phase===2?85:100;
          const impDmg=phase===1?260:phase===2?420:650;
          objects.forEach(o=>{
            if(o.dead)return;
            if(Math.hypot(o.sx()-b.x,o.sy()-b.y)<impR){
              if(o._invasionHP===undefined)o._invasionHP=100;
              o._invasionHP=Math.max(0,o._invasionHP-impDmg);
              if(o._invasionHP<=0&&!o._invasionDead){
                o._invasionDead=true;o.dead=true;
                showTooltip(`🐍💥 Investida de Solaris destruiu ${o.name||o.type}!`);
              }
            }
          });
          for(let i=0;i<10;i++)_fxParticles.push({x:b.x+rand(-20,20),y:b.y+rand(-20,20),
            vx:rand(-70,70),vy:rand(-70,70),r:rand(3,8),alpha:1,color:'#ff2600',life:0.5,maxLife:0.5});
          b.flashT=0.4;b.flashColor='#ff2600';
          b.strikeState='recoil'; b.strikeT=0;
        }
      }
      if(b.strikeState==='recoil'){
        b.strikeT+=dt;
        if(b.strikeT>=0.4){
          b.strikeState='idle'; b.strikeTarget=null;
          b.strikeCd=(phase===1?3.2:phase===2?2.4:1.7)+Math.random()*0.8;
        }
      }

      // FASE 2+: CONE DE VENENO (substitui os lasers genéricos por um
      // sopro em leque na direção do bote, mais fiel a uma serpente)
      // + invisibilidade (mantida)
      if(phase>=2){
        b.venomTimer+=dt;
        const venomInterval=phase===2?1.7:0.95;
        if(b.venomTimer>=venomInterval){
          b.venomTimer=0;
          const alive=objects.filter(o=>!o.dead);
          if(alive.length>0){
            const tgt=alive[~~(Math.random()*alive.length)];
            const va=Math.atan2(tgt.sy()-b.y,tgt.sx()-b.x);
            b.venomCones.push({
              x:b.x,y:b.y,angle:va,
              spread:phase===2?0.5:0.72,
              range:phase===2?280:360,
              t:0,maxT:0.9,
              dmg:phase===2?9:16, // dano por tick enquanto o astro estiver dentro
              hitSet:new Set(),
            });
            showTooltip('🐍☠️ Solaris expele veneno!');
          }
        }
        if(b.invisCd>0)b.invisCd-=dt;
        if(!b.invis&&b.invisCd<=0){
          b.invis=true;b.invisTimer=phase===2?3.5:2.0;b.invisCd=phase===2?9:5.5;
          showTooltip('🐍👻 Solaris ficou invisível!');
        }
        if(b.invis){b.invisTimer-=dt;if(b.invisTimer<=0)b.invis=false;}
      }
      // Atualiza cones de veneno ativos (dano contínuo em quem estiver dentro)
      b.venomCones=(b.venomCones||[]).filter(vc=>{
        vc.t+=dt;
        objects.forEach(o=>{
          if(o.dead)return;
          const ox=o.sx()-vc.x, oy=o.sy()-vc.y;
          const dist=Math.hypot(ox,oy);
          if(dist<1||dist>vc.range)return;
          const ang=Math.atan2(oy,ox);
          let da=ang-vc.angle;
          while(da>Math.PI)da-=Math.PI*2;
          while(da<-Math.PI)da+=Math.PI*2;
          if(Math.abs(da)<vc.spread){
            if(o._invasionHP===undefined)o._invasionHP=100;
            o._invasionHP=Math.max(0,o._invasionHP-vc.dmg*dt*4);
            if(Math.random()<0.15)_fxParticles.push({x:o.sx()+rand(-6,6),y:o.sy()+rand(-6,6),
              vx:rand(-10,10),vy:rand(-10,10),r:rand(2,4),alpha:0.6,color:'rgba(120,255,80,0.7)',life:0.4,maxLife:0.4});
            if(o._invasionHP<=0&&!o._invasionDead&&!vc.hitSet.has(o)){
              vc.hitSet.add(o);o._invasionDead=true;o.dead=true;
              showTooltip(`☠️ Veneno de Solaris dissolveu ${o.name||o.type}!`);
            }
          }
        });
        return vc.t<vc.maxT;
      });

      // FASE 3: ENXAME (clones) + CONSTRIÇÃO EM ESPIRAL
      // Antes: raios de confusão aleatórios sem tema. Agora: a serpente
      // e seus clones periodicamente convergem formando um anel que se
      // fecha ao redor da arena, esmagando tudo que fica preso dentro —
      // reforça a ideia de "constrição", tema natural de serpente.
      if(phase>=3){
        b.cloneTimer+=dt;
        if(b.cloneTimer>=3.2&&_reptBossClones.length<4){
          b.cloneTimer=0;
          _reptBossClones.push({x:bx+rand(80,W-80),y:by+rand(80,H-100),moveAngle:rand(0,Math.PI*2),t:0,alpha:0,form:'serpente'});
        }

        b.constrictCd=Math.max(0,b.constrictCd-dt);
        if(b.constrictState==='idle'&&b.constrictCd<=0&&_reptBossClones.length>=2){
          b.constrictState='forming'; b.constrictT=0;
          showTooltip('🐍🌀 O Enxame Ancestral se enrosca em espiral!');
        }
        if(b.constrictState==='forming'){
          b.constrictT+=dt;
          // Anel se fecha ao redor do centro da arena, encolhendo
          const cxA=bx+W/2, cyA=by+H/2;
          const prog=Math.min(1,b.constrictT/1.6);
          const ringR=(Math.min(W,H)*0.42)*(1-prog*0.72);
          const pts=[{x:b.x,y:b.y}].concat(_reptBossClones.map(c=>({x:c.x,y:c.y})));
          const n=pts.length;
          pts.forEach((p,i)=>{
            const a=(i/n)*Math.PI*2+b.t*0.6;
            const tx=cxA+Math.cos(a)*ringR, ty=cyA+Math.sin(a)*ringR;
            if(i===0){b.x+=(tx-b.x)*Math.min(1,dt*4);b.y+=(ty-b.y)*Math.min(1,dt*4);}
            else{
              const cl=_reptBossClones[i-1];
              if(cl){cl.x+=(tx-cl.x)*Math.min(1,dt*4);cl.y+=(ty-cl.y)*Math.min(1,dt*4);}
            }
          });
          // Linhas de energia conectando os pontos do anel (visual)
          b.confuseRays=pts.map((p,i)=>{
            const nxt=pts[(i+1)%n];
            return {x1:p.x,y1:p.y,x2:nxt.x,y2:nxt.y,t:0,maxT:0.05,isConstrictLine:true};
          });
          if(prog>=1){
            b.constrictState='crushing'; b.constrictT=0;
          }
        }
        if(b.constrictState==='crushing'){
          b.constrictT+=dt;
          const cxA=bx+W/2, cyA=by+H/2;
          const crushR=Math.min(W,H)*0.42*0.28;
          objects.forEach(o=>{
            if(o.dead)return;
            if(Math.hypot(o.sx()-cxA,o.sy()-cyA)<crushR){
              if(o._invasionHP===undefined)o._invasionHP=100;
              o._invasionHP=Math.max(0,o._invasionHP-40*dt*4);
              if(o._invasionHP<=0&&!o._invasionDead){
                o._invasionDead=true;o.dead=true;
                showTooltip(`🐍🌀 Constrição esmagou ${o.name||o.type}!`);
              }
            }
          });
          if(b.constrictT>=0.9){
            b.constrictState='idle'; b.constrictCd=6+Math.random()*2;
            b.confuseRays=[];
          }
        }
      }
    }

    // ══════════════════
    //  ── FORMA: CAMALEÃO ──
    //  F1: Língua + Investida  |  F2: Clone Letal  |  F3: Caos Total
    // ══════════════════
    else if(b.form==='camaleao'){
      // ── Inicializa estado uma vez ──
      if(!b.tongueState){
        b.tongueState='ready';
        b.tongueCd=2.5; b.tongueT=0;
        b.tongueTarget=null; b.tongueX=0; b.tongueY=0;
        b.tongueTip={x:b.x,y:b.y};
        b.chargeDir={x:1,y:0}; b.chargeHit=false;
        b.camCloneCd=5;
        b.tailWhipCd=0; b.tailWhipT=0; b.tailWhipAngle=0;
        b.killParticles=[]; b.killParticlesTimer=0;
        b.laserTimer=0;
      }

      // ════ LÍNGUA + INVESTIDA (todas as fases) ════
      const tongueCdTime=phase===1?3.5:phase===2?2.2:1.0;
      const chargeSpd=phase===1?700:phase===2?900:1300;

      if(b.tongueState==='ready'){
        b.tongueCd=Math.max(0,b.tongueCd-dt);
        if(b.tongueCd<=0){
          const alive=objects.filter(o=>!o.dead);
          if(alive.length>0){
            b.tongueTarget=alive[~~(Math.random()*alive.length)];
            b.tongueX=b.tongueTarget.sx(); b.tongueY=b.tongueTarget.sy();
            b.tongueState='extending'; b.tongueT=0;
            showTooltip('🦎👅 Língua!');
          } else { b.tongueCd=1.5; }
        }
      }
      else if(b.tongueState==='extending'){
        b.tongueT+=dt;
        const prog=Math.min(1,b.tongueT/0.42);
        b.tongueTip={x:b.x+(b.tongueX-b.x)*prog,y:b.y+(b.tongueY-b.y)*prog};
        if(b.tongueT>=0.42){
          if(b.tongueTarget&&!b.tongueTarget.dead){
            b.tongueX=b.tongueTarget.sx(); b.tongueY=b.tongueTarget.sy();
          }
          const dx=b.tongueX-b.x,dy=b.tongueY-b.y,dd=Math.max(1,Math.hypot(dx,dy));
          b.chargeDir={x:dx/dd,y:dy/dd};
          b.tongueState='charging'; b.tongueT=0; b.chargeHit=false;
        }
      }
      else if(b.tongueState==='charging'){
        b.tongueT+=dt;
        b.vx=b.chargeDir.x*chargeSpd; b.vy=b.chargeDir.y*chargeSpd;
        if(!b.chargeHit){
          objects.forEach(o=>{
            if(o.dead)return;
            const d=Math.hypot(o.sx()-b.x,o.sy()-b.y);
            if(d<(o.radius||30)+50){
              if(o._invasionHP===undefined)o._invasionHP=100;
              let dmg=phase===1?80:phase===2?130:999;
              if(b._ambushBonus)dmg*=2.2; // bote de emboscada — dano bônus
              o._invasionHP=Math.max(0,o._invasionHP-dmg);
              if(o._invasionHP<=0&&!o._invasionDead){
                o._invasionDead=true;o.dead=true;
                showTooltip(b._ambushBonus?`🦎⚡ Emboscada aniquilou ${o.name||o.type}!`:`🦎💥 Investida destruiu ${o.name||o.type}!`);
              }
              b.chargeHit=true;
              for(let i=0;i<(b._ambushBonus?14:8);i++)_fxParticles.push({
                x:b.x+rand(-25,25),y:b.y+rand(-25,25),
                vx:rand(-120,120),vy:rand(-120,120),
                r:rand(3,9),alpha:1,color:b._ambushBonus?'#ff2600':'#ff5500',life:0.5,maxLife:0.5});
            }
          });
        }
        if(b.tongueT>=0.55){
          b.tongueState='recovering'; b.tongueT=0; b.vx*=0.08; b.vy*=0.08;
          b._ambushBonus=false;
        }
      }
      else if(b.tongueState==='recovering'){
        b.tongueT+=dt;
        if(b.tongueT>=0.55){
          b.tongueState='ready'; b.tongueCd=tongueCdTime; b.tongueTarget=null;
        }
      }

      // ════ FASE 2: CAMUFLAGEM TOTAL + EMBOSCADA ════
      // Antes: só um clone genérico com a mesma IA de língua. Agora usa
      // o tema real prometido na transição de fase — o Nebulon some
      // (camouflageAlpha cai a quase 0), se reposiciona perto de um
      // alvo desprevenido, e reaparece com um bote de emboscada que
      // causa dano bônus. Reutiliza b.camHiding/b.camouflageAlpha, que
      // já existiam só para o desenho mas nunca eram alterados.
      if(phase>=2){
        b.camCd=Math.max(0,(b.camCd||0)-dt);
        if(!b.camHiding&&b.camCd<=0&&b.tongueState==='ready'){
          b.camHiding=true; b.camTimer=0; b.ambushReady=false;
          showTooltip('🦎🫥 Nebulon desaparece na camuflagem...');
        }
        if(b.camHiding){
          b.camTimer+=dt;
          // Fade-out rápido, depois reposiciona enquanto invisível
          b.camouflageAlpha=Math.max(0.04,1-b.camTimer*3.2);
          const hideDur=phase===2?1.6:1.05;
          if(!b.ambushReady&&b.camTimer>=hideDur*0.4){
            // Escolhe uma vítima e se teleporta para perto dela, ainda oculto
            const alive=objects.filter(o=>!o.dead);
            if(alive.length>0){
              const victim=alive[~~(Math.random()*alive.length)];
              const apAngle=Math.random()*Math.PI*2;
              b.x=Math.max(bx+70,Math.min(bx+W-70,victim.sx()+Math.cos(apAngle)*90));
              b.y=Math.max(by+70,Math.min(by+H-90,victim.sy()+Math.sin(apAngle)*90));
              b.ambushTarget=victim;
            }
            b.ambushReady=true;
          }
          if(b.camTimer>=hideDur){
            // Reaparece com bote de emboscada — dano bônus por atacar
            // "desprevenido"
            b.camHiding=false; b.camouflageAlpha=1;
            b.camCd=phase===2?7:4.2;
            if(b.ambushTarget&&!b.ambushTarget.dead&&b.tongueState==='ready'){
              b.tongueTarget=b.ambushTarget;
              b.tongueX=b.ambushTarget.sx(); b.tongueY=b.ambushTarget.sy();
              b.tongueState='extending'; b.tongueT=0;
              b._ambushBonus=true; // sinaliza dano extra na próxima investida
              showTooltip('🦎⚡ EMBOSCADA! Nebulon reaparece atacando!');
              for(let i=0;i<10;i++)_fxParticles.push({x:b.x+rand(-20,20),y:b.y+rand(-20,20),
                vx:rand(-90,90),vy:rand(-90,90),r:rand(3,7),alpha:1,color:'#ff2600',life:0.4,maxLife:0.4});
            }
            b.ambushTarget=null; b.ambushReady=false;
          }
        }

        // Ainda mantém 1 clone auxiliar em fase 2+ (reduzido de 2→1 já
        // que a emboscada agora é a mecânica de destaque da fase)
        b.camCloneCd-=dt;
        const maxCl=phase===2?1:0; // Fase 3 não usa mais este tipo de clone (usa espelhos)
        const curCl=_reptBossClones.filter(cl=>cl.form==='camaleao'&&!cl.isMirror).length;
        if(phase===2&&b.camCloneCd<=0&&curCl<maxCl){
          b.camCloneCd=7;
          _reptBossClones.push({
            x:bx+rand(90,W-90),y:by+rand(90,H-110),
            form:'camaleao',t:0,alpha:0,vx:0,vy:0,dead:false,
            tongueState:'ready',tongueCd:2.5+Math.random()*2,tongueT:0,
            tongueTarget:null,tongueX:0,tongueY:0,
            tongueTip:{x:bx+W/2,y:by+H/2},
            chargeDir:{x:1,y:0},chargeHit:false,
            killOnHit:true,hitCount:0,
          });
          showTooltip('🦎🔀 Clone Nebulon invocado!');
        }
        // Tick dos clones camaleão — IA completa (apenas os que não são espelho)
        _reptBossClones.forEach(cl=>{
          if(cl.form!=='camaleao'||cl.dead||cl.isMirror)return;
          cl.t+=dt; cl.alpha=Math.min(0.9,cl.t*2.2);
          // Movimento: deriva em direção ao próximo alvo
          const alv=objects.filter(o=>!o.dead);
          if(alv.length>0&&cl.tongueState!=='charging'){
            const tgt2=alv[~~(cl.t*5)%alv.length];
            if(tgt2){
              const ddx=tgt2.sx()-cl.x,ddy=tgt2.sy()-cl.y,dd=Math.max(1,Math.hypot(ddx,ddy));
              cl.vx+=(ddx/dd*280-(cl.vx))*dt*2.5;
              cl.vy+=(ddy/dd*280-(cl.vy))*dt*2.5;
            }
          }
          if(cl.tongueState!=='charging'){
            cl.x+=cl.vx*dt; cl.y+=cl.vy*dt;
          }
          cl.x=Math.max(bx+60,Math.min(bx+W-60,cl.x));
          cl.y=Math.max(by+60,Math.min(by+H-80,cl.y));
          // IA língua clone
          cl.tongueCd=(cl.tongueCd||3)-dt;
          if(cl.tongueState==='ready'&&cl.tongueCd<=0){
            const av=objects.filter(o=>!o.dead);
            if(av.length>0){
              cl.tongueTarget=av[~~(Math.random()*av.length)];
              cl.tongueX=cl.tongueTarget.sx(); cl.tongueY=cl.tongueTarget.sy();
              cl.tongueState='extending'; cl.tongueT=0;
            } else cl.tongueCd=2;
          } else if(cl.tongueState==='extending'){
            cl.tongueT+=dt;
            const p2=Math.min(1,cl.tongueT/0.38);
            cl.tongueTip={x:cl.x+(cl.tongueX-cl.x)*p2,y:cl.y+(cl.tongueY-cl.y)*p2};
            if(cl.tongueT>=0.38){
              if(cl.tongueTarget&&!cl.tongueTarget.dead){
                cl.tongueX=cl.tongueTarget.sx(); cl.tongueY=cl.tongueTarget.sy();
              }
              const dx=cl.tongueX-cl.x,dy=cl.tongueY-cl.y,dd=Math.max(1,Math.hypot(dx,dy));
              cl.chargeDir={x:dx/dd,y:dy/dd};
              cl.tongueState='charging'; cl.tongueT=0; cl.chargeHit=false;
            }
          } else if(cl.tongueState==='charging'){
            cl.tongueT+=dt;
            cl.vx=cl.chargeDir.x*850; cl.vy=cl.chargeDir.y*850;
            cl.x+=cl.vx*dt; cl.y+=cl.vy*dt;
            if(!cl.chargeHit){
              objects.forEach(o=>{
                if(o.dead)return;
                const d=Math.hypot(o.sx()-cl.x,o.sy()-cl.y);
                if(d<(o.radius||30)+45){
                  o._invasionHP=0; o._invasionDead=true; o.dead=true;
                  cl.chargeHit=true; cl.hitCount=(cl.hitCount||0)+1;
                  showTooltip(`🦎🔀 Clone destruiu ${o.name||o.type} e evaporou!`);
                  for(let i=0;i<7;i++)_fxParticles.push({
                    x:cl.x+rand(-18,18),y:cl.y+rand(-18,18),
                    vx:rand(-100,100),vy:rand(-100,100),
                    r:rand(2,7),alpha:1,color:'#55ff77',life:0.45,maxLife:0.45});
                }
              });
            }
            if(cl.tongueT>=0.48||cl.chargeHit){
              cl.tongueState='recovering'; cl.tongueT=0; cl.vx*=0.05; cl.vy*=0.05;
            }
          } else if(cl.tongueState==='recovering'){
            cl.tongueT+=dt;
            if(cl.tongueT>=0.35){
              if(cl.killOnHit&&cl.hitCount>0){cl.dead=true;}
              else {cl.tongueState='ready'; cl.tongueCd=2.8+Math.random()*2;}
            }
          }
        });
      }

      // ════ FASE 3: ESPELHOS + NUVENS TÓXICAS ════
      // Antes: lasers genéricos + chicotada + partículas HITKILL — nada
      // temático. Agora usa mirrorTimer/toxicClouds (que já existiam no
      // estado inicial mas nunca eram usados): 2 clones-espelho que
      // reproduzem a posição do boss refletida (confundindo o jogador
      // sobre qual é o real) e nuvens tóxicas persistentes na arena.
      if(phase>=3){
        // ── Espelhos: 2 réplicas visuais sincronizadas com o boss,
        // refletidas pelo centro da arena — não têm IA própria, apenas
        // seguem a posição do Nebulon real espelhada (X, Y e diagonal),
        // reforçando a confusão de "qual é o de verdade". ──
        b.mirrorTimer+=dt;
        const mirrors=_reptBossClones.filter(cl=>cl.isMirror);
        if(mirrors.length<2){
          const cxA=bx+W/2, cyA=by+H/2;
          _reptBossClones.push({x:b.x,y:b.y,form:'camaleao',t:1,alpha:0.75,
            isMirror:true,mirrorAxis:'x',dead:false});
          _reptBossClones.push({x:b.x,y:b.y,form:'camaleao',t:1,alpha:0.75,
            isMirror:true,mirrorAxis:'y',dead:false});
          showTooltip('🦎🪞 Espelhos do Nebulon surgem!');
        }
        _reptBossClones.forEach(cl=>{
          if(!cl.isMirror||cl.dead)return;
          const cxA=bx+W/2, cyA=by+H/2;
          if(cl.mirrorAxis==='x'){cl.x=cxA-(b.x-cxA);cl.y=b.y;}
          else{cl.x=b.x;cl.y=cyA-(b.y-cyA);}
          cl.x=Math.max(bx+50,Math.min(bx+W-50,cl.x));
          cl.y=Math.max(by+50,Math.min(by+H-70,cl.y));
        });
        // Espelhos causam dano de contato leve (reforço de área, não
        // são o foco de dano principal — isso continua sendo a língua)
        if(Math.floor(b.mirrorTimer*2)%2===0){
          mirrors.forEach(m=>{
            objects.forEach(o=>{
              if(o.dead)return;
              if(Math.hypot(o.sx()-m.x,o.sy()-m.y)<(o.radius||30)+34){
                if(o._invasionHP===undefined)o._invasionHP=100;
                o._invasionHP=Math.max(0,o._invasionHP-7*dt*2);
                if(o._invasionHP<=0&&!o._invasionDead){
                  o._invasionDead=true;o.dead=true;
                  showTooltip(`🪞 Espelho do Nebulon destruiu ${o.name||o.type}!`);
                }
              }
            });
          });
        }

        // ── Nuvens tóxicas: spawnam periodicamente em pontos da arena
        // e persistem, causando dano contínuo a quem ficar dentro — dá
        // controle de área/zoneamento, mecânica ausente antes. ──
        b.toxicTimer+=dt;
        if(b.toxicTimer>=3.0&&b.toxicClouds.length<4){
          b.toxicTimer=0;
          b.toxicClouds.push({
            x:bx+rand(90,W-90),y:by+rand(90,H-110),
            r:0,maxR:70,life:6,maxLife:6,
          });
          showTooltip('🦎☁️ Nuvem tóxica liberada!');
        }
        b.toxicClouds=b.toxicClouds.filter(tc=>{
          tc.life-=dt;
          tc.r=Math.min(tc.maxR,tc.r+dt*60);
          objects.forEach(o=>{
            if(o.dead)return;
            if(Math.hypot(o.sx()-tc.x,o.sy()-tc.y)<tc.r+(o.radius||20)){
              if(o._invasionHP===undefined)o._invasionHP=100;
              o._invasionHP=Math.max(0,o._invasionHP-11*dt*2);
              if(Math.random()<0.1)_fxParticles.push({x:o.sx()+rand(-8,8),y:o.sy()+rand(-8,8),
                vx:rand(-12,12),vy:rand(-20,-4),r:rand(2,4),alpha:0.6,color:'rgba(140,220,60,0.7)',life:0.4,maxLife:0.4});
              if(o._invasionHP<=0&&!o._invasionDead){
                o._invasionDead=true;o.dead=true;
                showTooltip(`☁️ Nuvem tóxica dissolveu ${o.name||o.type}!`);
              }
            }
          });
          return tc.life>0;
        });

        // Chicotada de rabo — mantida (é uma mecânica física legítima
        // de camaleão/réptil, não genérica como os lasers/partículas)
        b.tailWhipCd-=dt;
        if(b.tailWhipCd<=0){
          b.tailWhipCd=2.8;
          b.tailWhipAngle=Math.atan2(b.vy||1,b.vx||0)+Math.PI;
          b.tailWhipT=0.65;
          objects.forEach(o=>{
            if(o.dead)return;
            const dx=o.sx()-b.x,dy=o.sy()-b.y;
            const d=Math.hypot(dx,dy);
            if(d<200){
              let diff=(Math.atan2(dy,dx)-b.tailWhipAngle+Math.PI*4)%(Math.PI*2);
              if(diff>Math.PI)diff=Math.PI*2-diff;
              if(diff<1.35){
                o._invasionHP=0; o._invasionDead=true; o.dead=true;
                showTooltip(`🦎💀 Chicotada destruiu ${o.name||o.type}!`);
                for(let i=0;i<6;i++)_fxParticles.push({
                  x:o.sx()+rand(-20,20),y:o.sy()+rand(-20,20),
                  vx:rand(-70,70),vy:rand(-70,70),
                  r:rand(3,8),alpha:1,color:'#cc3300',life:0.5,maxLife:0.5});
              }
            }
          });
          showTooltip('🦎🌀 Chicotada de rabo!');
        }
        if(b.tailWhipT>0)b.tailWhipT=Math.max(0,b.tailWhipT-dt);
      }
    }

    // ══════════════════
    //  ── FORMA: DRAGÃO ──
    //  F1: Flash+3 Raios tela inteira  |  F2: Asas HITKILL+Teleporte  |  F3: Meteoros+Armadilhas Glitch
    // ══════════════════
    else if(b.form==='dragao'){
      b.wingSpread=Math.min(1,b.wingSpread+dt*0.55);

      // ── Init de estado ──
      if(!b.dragState){
        b.dragState=true;
        b.flashState='idle'; b.flashCd=phase===1?5:phase===2?3.5:2.5; b.flashT=0;
        b.screenBeams=[]; 
        b.wingBlastCd=0; b.wingBlastT=0;
        b.teleportCd=phase===2?6:4; b.teleportTimer=0;
        b.teleportState='idle'; b.teleportTarget=null; b.teleportBlurT=0;
        b.meteorCd=phase===3?7:99; b.meteorTimer=0; b.meteorWarnings=[];
        b.roamCd=phase===3?4:99; b.roamTimer=0;
        // ── Novos estados temáticos: fogo, garras, rugido ──
        b.fireBreathTimer=0; b.fireBreaths=[];
        b.clawState='idle'; b.clawCd=phase===2?5:3.2; b.clawT=0; b.clawTarget=null;
        b.clawFromX=0; b.clawFromY=0;
        b.roarCd=phase===3?6:99; b.roarTimer=0; b.roarRings=[];
      }

      // ════ F1 TODAS AS FASES: Flash branco + 3 raios que cobrem a tela ════
      b.flashCd=Math.max(0,b.flashCd-dt);
      if(b.flashState==='idle'&&b.flashCd<=0){
        b.flashState='charging'; b.flashT=0;
        showTooltip('🐉⚡ Carga de energia!');
      }
      if(b.flashState==='charging'){
        b.flashT+=dt;
        if(b.flashT>=0.8){b.flashState='flashing';b.flashT=0;}
      }
      if(b.flashState==='flashing'){
        b.flashT+=dt;
        if(b.flashT>=0.22){
          b.flashState='beaming';b.flashT=0;
          // Cria 3 raios que atravessam toda a arena
          b.screenBeams=[];
          const baseAngles=[0, Math.PI/3, -Math.PI/3];
          baseAngles.forEach(a=>{
            const fullLen=Math.hypot(W,H)*1.1;
            b.screenBeams.push({
              x:b.x,y:b.y,angle:a,len:fullLen,life:0.7,maxLife:0.7,width:22
            });
          });
          showTooltip('🐉🌟 RAIOS DEVASTADORES!');
          // Dano imediato em todos os astros na linha de cada raio
          b.screenBeams.forEach(bm=>{
            objects.forEach(o=>{
              if(o.dead)return;
              const ox=o.sx()-bm.x,oy=o.sy()-bm.y;
              const proj=ox*Math.cos(bm.angle)+oy*Math.sin(bm.angle);
              const perp=Math.abs(-ox*Math.sin(bm.angle)+oy*Math.cos(bm.angle));
              if(proj>0&&proj<bm.len&&perp<(o.sr()||30)+bm.width){
                o._invasionHP=0;o._invasionDead=true;o.dead=true;
                showTooltip(`🐉 Raio evaporou ${o.name||o.type}!`);
                for(let i=0;i<6;i++)_fxParticles.push({x:o.sx(),y:o.sy(),
                  vx:rand(-50,50),vy:rand(-50,50),r:rand(3,9),alpha:1,
                  color:'#ffffff',life:0.5,maxLife:0.5});
              }
            });
          });
        }
      }
      if(b.flashState==='beaming'){
        b.flashT+=dt;
        b.screenBeams=(b.screenBeams||[]).filter(bm=>{bm.life-=dt;return bm.life>0;});
        if(b.flashT>=0.7){
          b.flashState='idle';
          b.flashCd=phase===1?6:phase===2?4:2.5;
        }
      }

      // ════ SOPRO DE FOGO (todas as fases) — substitui os lasers
      // genéricos do visor por um cone de fogo real, tema de dragão.
      // Reaproveita fireBreathTimer/fireBreaths, que existiam no estado
      // inicial mas nunca eram usados. ════
      b.fireBreathTimer+=dt;
      const fireInterval=phase===1?2.0:phase===2?1.2:0.6;
      if(b.fireBreathTimer>=fireInterval){
        b.fireBreathTimer=0;
        const alive=objects.filter(o=>!o.dead);
        if(alive.length>0){
          const tgt=alive[~~(Math.random()*alive.length)];
          const fa=Math.atan2(tgt.sy()-b.y,tgt.sx()-b.x);
          b.fireBreaths.push({
            x:b.x,y:b.y,angle:fa,
            spread:phase===1?0.34:phase===2?0.46:0.62,
            range:phase===1?260:phase===2?320:400,
            t:0,maxT:0.85,
            dmg:phase===1?70:phase===2?130:260,
            hitSet:new Set(),
          });
          showTooltip('🐉🔥 Sopro de fogo!');
        }
      }
      b.fireBreaths=(b.fireBreaths||[]).filter(fb=>{
        fb.t+=dt;
        objects.forEach(o=>{
          if(o.dead)return;
          const ox=o.sx()-fb.x, oy=o.sy()-fb.y;
          const dist=Math.hypot(ox,oy);
          if(dist<1||dist>fb.range)return;
          const ang=Math.atan2(oy,ox);
          let da=ang-fb.angle;
          while(da>Math.PI)da-=Math.PI*2;
          while(da<-Math.PI)da+=Math.PI*2;
          if(Math.abs(da)<fb.spread){
            if(o._invasionHP===undefined)o._invasionHP=100;
            o._invasionHP=Math.max(0,o._invasionHP-fb.dmg*dt*3);
            if(Math.random()<0.35)_fxParticles.push({x:o.sx()+rand(-8,8),y:o.sy()+rand(-8,8),
              vx:rand(-20,20),vy:rand(-40,-10),r:rand(3,7),alpha:0.85,
              color:Math.random()<0.5?'#ff5500':'#ffaa00',life:0.4,maxLife:0.4});
            if(o._invasionHP<=0&&!o._invasionDead&&!fb.hitSet.has(o)){
              fb.hitSet.add(o);o._invasionDead=true;o.dead=true;
              showTooltip(`🔥 Sopro de fogo carbonizou ${o.name||o.type}!`);
            }
          }
        });
        return fb.t<fb.maxT;
      });

      // ════ F2: INVESTIDA ALADA COM GARRAS ════
      // Antes: explosão de asas com HITKILL instantâneo em área + teleporte
      // cego sem propósito tático. Agora: o dragão abre as asas, escolhe
      // um alvo, voa em disparada até ele e crava as garras no impacto —
      // ação de dragão real (voo + garra), não só "área que mata".
      if(phase>=2){
        b.clawCd=Math.max(0,b.clawCd-dt);
        if(b.clawState==='idle'&&b.clawCd<=0){
          const alive=objects.filter(o=>!o.dead);
          if(alive.length>0){
            b.clawTarget=alive[~~(Math.random()*alive.length)];
            b.clawState='rearing'; b.clawT=0;
            showTooltip('🐉🪽 Drexcy abre as asas para o voo!');
          }
        }
        if(b.clawState==='rearing'){
          b.clawT+=dt;
          if(b.clawT>=0.5){
            // Reposiciona (era o "teleporte cego" — agora é o início
            // tático do voo, sempre a uma distância curta do alvo)
            const tgt=b.clawTarget;
            if(tgt&&!tgt.dead){
              const apAngle=Math.random()*Math.PI*2;
              const standoff=phase===2?220:170;
              b.x=Math.max(bx+70,Math.min(bx+W-70,tgt.sx()+Math.cos(apAngle)*standoff));
              b.y=Math.max(by+70,Math.min(by+H-90,tgt.sy()+Math.sin(apAngle)*standoff));
              b.clawFromX=b.x; b.clawFromY=b.y;
              b.clawState='diving'; b.clawT=0;
              for(let i=0;i<10;i++)_fxParticles.push({x:b.x+rand(-25,25),y:b.y+rand(-25,25),
                vx:rand(-70,70),vy:rand(-70,70),r:rand(3,7),alpha:0.8,color:'#ff6600',life:0.4,maxLife:0.4});
            } else { b.clawState='idle'; b.clawCd=1.5; }
          }
        }
        if(b.clawState==='diving'){
          b.clawT+=dt;
          const dur=phase===2?0.34:0.24;
          const prog=Math.min(1,b.clawT/dur);
          const ease=prog*prog;
          const tgt=b.clawTarget;
          if(tgt&&!tgt.dead){
            b.x=b.clawFromX+(tgt.sx()-b.clawFromX)*ease;
            b.y=b.clawFromY+(tgt.sy()-b.clawFromY)*ease;
          }
          if(prog>=1){
            const clawR=phase===2?95:120;
            const clawDmg=phase===2?450:750;
            objects.forEach(o=>{
              if(o.dead)return;
              if(Math.hypot(o.sx()-b.x,o.sy()-b.y)<clawR){
                if(o._invasionHP===undefined)o._invasionHP=100;
                o._invasionHP=Math.max(0,o._invasionHP-clawDmg);
                if(o._invasionHP<=0&&!o._invasionDead){
                  o._invasionDead=true;o.dead=true;
                  showTooltip(`🐉🦅 Garras de Drexcy dilaceraram ${o.name||o.type}!`);
                }
              }
            });
            for(let i=0;i<18;i++)_fxParticles.push({
              x:b.x+rand(-30,30),y:b.y+rand(-30,30),
              vx:rand(-140,140),vy:rand(-140,140),
              r:rand(3,10),alpha:1,color:Math.random()<0.5?'#ff2600':'#cc1400',
              life:0.55,maxLife:0.55});
            b.flashT=0.35;b.flashColor='#ff3300';
            b.clawState='recovering'; b.clawT=0;
          }
        }
        if(b.clawState==='recovering'){
          b.clawT+=dt;
          if(b.clawT>=0.5){
            b.clawState='idle'; b.clawTarget=null;
            b.clawCd=(phase===2?6:3.8)+Math.random()*1.2;
          }
        }
      }

      // ════ F3: METEOROS + ARMADILHAS GLITCH + ROAMING ════
      if(phase>=3){
        // Roaming para posições aleatórias
        b.roamTimer+=dt;
        if(b.roamTimer>=b.roamCd){
          b.roamTimer=0;b.roamCd=3.5+Math.random()*3;
          b._roamTx=bx+rand(80,W-80);b._roamTy=by+rand(80,H-100);
        }
        if(b._roamTx!==undefined){
          const dx=b._roamTx-b.x,dy=b._roamTy-b.y,dd=Math.max(1,Math.hypot(dx,dy));
          if(dd>60){b.vx+=(dx/dd*580-b.vx)*dt*4;b.vy+=(dy/dd*580-b.vy)*dt*4;}
          else{delete b._roamTx;delete b._roamTy;}
        }

        // Meteoros (não tão frequentes)
        b.meteorTimer+=dt;
        if(b.meteorTimer>=b.meteorCd){
          b.meteorTimer=0;b.meteorCd=6+Math.random()*4;
          const nMet=2+~~(Math.random()*2);
          for(let mi=0;mi<nMet;mi++){
            const mx=bx+rand(50,W-50),my=by-10;
            const warnT=1.6;
            b.meteorWarnings.push({x:mx,yStart:my,yEnd:by+H-40,t:0,maxT:warnT});
          }
          showTooltip('🐉☄️ Chuva de meteoros!');
        }
        b.meteorWarnings=(b.meteorWarnings||[]).filter(mw=>{
          mw.t+=dt;
          if(mw.t>=mw.maxT){
            // Impacto
            objects.forEach(o=>{
              if(o.dead)return;
              if(Math.hypot(o.sx()-mw.x,o.sy()-mw.yEnd)<110){
                o._invasionHP=0;o._invasionDead=true;o.dead=true;
                showTooltip(`☄️ Meteoro destruiu ${o.name||o.type}!`);
              }
            });
            for(let i=0;i<14;i++)_fxParticles.push({
              x:mw.x+rand(-55,55),y:mw.yEnd+rand(-25,25),
              vx:rand(-70,70),vy:rand(-50,10),
              r:rand(4,14),alpha:1,color:'#ff5500',life:0.85,maxLife:0.85});
            return false;
          }
          return true;
        });

        // ════ RUGIDO DEVASTADOR — substitui as armadilhas glitch
        // genéricas por ondas de choque sonoras em anéis crescentes,
        // tema real de dragão furioso (rugido físico, não "trap"). ════
        b.roarTimer+=dt;
        if(b.roarTimer>=b.roarCd){
          b.roarTimer=0;b.roarCd=5+Math.random()*2.5;
          b.roarRings.push({x:b.x,y:b.y,r:20,maxR:Math.max(W,H)*0.75,life:1.6,maxLife:1.6,hitSet:new Set()});
          showTooltip('🐉📢 RUGIDO DEVASTADOR!');
          b.flashT=0.3;b.flashColor='#ffcc00';
        }
        b.roarRings=(b.roarRings||[]).filter(rg=>{
          rg.life-=dt;
          rg.r=rg.maxR*(1-rg.life/rg.maxLife);
          const ringWidth=45;
          objects.forEach(o=>{
            if(o.dead||rg.hitSet.has(o))return;
            const d=Math.hypot(o.sx()-rg.x,o.sy()-rg.y);
            if(Math.abs(d-rg.r)<ringWidth){
              rg.hitSet.add(o);
              if(o._invasionHP===undefined)o._invasionHP=100;
              o._invasionHP=Math.max(0,o._invasionHP-190);
              if(o._invasionHP<=0&&!o._invasionDead){
                o._invasionDead=true;o.dead=true;
                showTooltip(`📢 Rugido de Drexcy despedaçou ${o.name||o.type}!`);
              } else if(typeof o.vx!=='undefined'){
                // Empurra astros sobreviventes para fora do centro (onda de choque)
                const pushA=Math.atan2(o.sy()-rg.y,o.sx()-rg.x);
                o.vx=(o.vx||0)+Math.cos(pushA)*140;
                o.vy=(o.vy||0)+Math.sin(pushA)*140;
              }
              for(let i=0;i<4;i++)_fxParticles.push({
                x:o.sx()+rand(-10,10),y:o.sy()+rand(-10,10),
                vx:rand(-50,50),vy:rand(-50,50),
                r:rand(2,5),alpha:0.8,color:'#ffcc00',life:0.35,maxLife:0.35});
            }
          });
          return rg.life>0;
        });
      }
    }

    // ══════════════════
    //  Lasers (comuns a todas as formas)
    // ══════════════════
    _reptBossLasers=_reptBossLasers.filter(l=>l.t<l.maxT&&!l.dead);
    _reptBossLasers.forEach(l=>{
      l.t+=dt;
      if(l.homing&&l.t<l.maxT*0.6&&l.tgtObj&&!l.tgtObj.dead){
        const lsx=l.tgtObj.sx(),lsy=l.tgtObj.sy();
        const ldx=lsx-l.x,ldy=lsy-l.y,ldd=Math.max(1,Math.hypot(ldx,ldy));
        const spd2=Math.hypot(l.vx,l.vy)||350;
        l.vx+=(ldx/ldd*spd2-l.vx)*dt*3.5;l.vy+=(ldy/ldd*spd2-l.vy)*dt*3.5;
      }
      l.trail=l.trail||[];l.trail.push({x:l.x,y:l.y});
      if(l.trail.length>22)l.trail.shift();
      l.x+=l.vx*dt;l.y+=l.vy*dt;
      if(!l.hitCd){
        objects.forEach(o=>{
          if(o.dead)return;
          const sx=o.sx(),sy=o.sy(),r=o.sr();
          if(Math.hypot(l.x-sx,l.y-sy)<r*1.3){
            if(o._invasionHP===undefined)o._invasionHP=100;
            o._invasionHP=Math.max(0,o._invasionHP-(l.dmg||200));
            l.hitCd=true;
            setTimeout(()=>{if(l)l.hitCd=false;},280);
            _fxParticles.push({x:l.x,y:l.y,vx:rand(-40,40),vy:rand(-40,40),
              r:rand(3,8),alpha:1,color:l.color||'#ff3300',life:0.4,maxLife:0.4});
            if(o._invasionHP<=0&&!o._invasionDead){o._invasionDead=true;o.dead=true;
              showTooltip(`⚠️ Laser do Aniquilador destruiu ${o.name||o.type}!`);}
          }
        });
      }
    });

    // Clones movem-se (camaleão clones gerenciados no próprio tick da forma)
    _reptBossClones=_reptBossClones.filter(cl=>!cl.dead);
    _reptBossClones.forEach(cl=>{
      if(cl.form==='camaleao')return; // já tratado no tick da forma
      cl.t+=dt;cl.alpha=Math.min(0.7,cl.alpha+dt*0.9);
      cl.moveAngle+=dt*1.4;
      cl.x+=Math.cos(cl.moveAngle)*120*dt;cl.y+=Math.sin(cl.moveAngle*0.9)*100*dt;
      cl.x=Math.max(bx+50,Math.min(bx+W-50,cl.x));cl.y=Math.max(by+50,Math.min(by+H-70,cl.y));
    });

    // Efeitos de astros no boss
    _applyReptAstroEffectsToBoss(dt);

    // Glitch por dano
    b.glitchIntensity=(1-b.formHP/b.formMaxHP)*0.7;

    // ── Draw ──
    _drawReptBoss(c2,b,_t);
    _reptBossClones.forEach(cl=>_drawReptBossClone(c2,cl,_t));
    _reptBossLasers.forEach(l=>_drawReptBossLaser(c2,l,_t));

    // Raios de confusão / avisos de meteoro / linhas de constrição (Solaris)
    b.confuseRays.forEach(ray=>{
      if(ray.isMeteorWarning){
        // Linha de aviso vermelha tracejada
        const alpha=(1-ray.t/ray.maxT)*0.65;
        c2.save();c2.globalAlpha=alpha;c2.setLineDash([6,4]);
        c2.beginPath();c2.moveTo(ray.x1,ray.y1);c2.lineTo(ray.x2,ray.y2);
        c2.strokeStyle='#ff4400';c2.lineWidth=1.5;c2.stroke();
        c2.setLineDash([]);c2.restore();
        return;
      }
      if(ray.isConstrictLine){
        // Elo de energia do anel de constrição — vermelho vivo, mais
        // grosso, sem fade (recriado a cada frame enquanto o anel existe)
        c2.save();c2.globalAlpha=0.8;
        c2.beginPath();c2.moveTo(ray.x1,ray.y1);c2.lineTo(ray.x2,ray.y2);
        c2.strokeStyle='#ff2600';c2.lineWidth=3.5;c2.stroke();
        c2.globalAlpha=0.35;c2.lineWidth=7;c2.stroke();
        c2.restore();
        return;
      }
      const alpha2=1-ray.t/ray.maxT;
      c2.save();c2.globalAlpha=alpha2*0.85;
      c2.beginPath();c2.moveTo(ray.x1,ray.y1);c2.lineTo(ray.x2,ray.y2);
      c2.strokeStyle=b.form==='dragao'?'#ff6600':'#ff6600';c2.lineWidth=2.5;
      c2.stroke();c2.restore();
    });

    // ── Cones de veneno do SOLARIS (Fase 2+) ──────────────────────────
    if(b.form==='serpente'&&b.venomCones&&b.venomCones.length>0){
      b.venomCones.forEach(vc=>{
        const alpha=Math.max(0,1-vc.t/vc.maxT);
        c2.save();c2.globalAlpha=alpha*0.5;
        c2.beginPath();
        c2.moveTo(vc.x,vc.y);
        c2.arc(vc.x,vc.y,vc.range,vc.angle-vc.spread,vc.angle+vc.spread);
        c2.closePath();
        const vg=c2.createRadialGradient(vc.x,vc.y,0,vc.x,vc.y,vc.range);
        vg.addColorStop(0,'rgba(140,255,90,0.55)');
        vg.addColorStop(0.6,'rgba(90,220,60,0.28)');
        vg.addColorStop(1,'rgba(60,180,40,0)');
        c2.fillStyle=vg;c2.fill();
        c2.restore();
        // Névoa/partículas dentro do cone (leve, dá textura sem custo alto)
        if(Math.random()<0.6){
          const rr=rand(20,vc.range*0.9), aa=vc.angle+rand(-vc.spread,vc.spread);
          _fxParticles.push({x:vc.x+Math.cos(aa)*rr,y:vc.y+Math.sin(aa)*rr,
            vx:Math.cos(aa)*20,vy:Math.sin(aa)*20-10,r:rand(2,5),alpha:0.5,
            color:'rgba(120,255,80,0.6)',life:0.4,maxLife:0.4});
        }
      });
    }

    // Constrição: aviso de "impacto" na fase crushing (pulso vermelho central)
    if(b.form==='serpente'&&b.constrictState==='crushing'){
      const cxA=bx+W/2, cyA=by+H/2;
      const crushR=Math.min(W,H)*0.42*0.28;
      const pulse=0.5+0.5*Math.sin(_t*14);
      c2.save();c2.globalAlpha=0.35+0.25*pulse;
      const cg=c2.createRadialGradient(cxA,cyA,0,cxA,cyA,crushR*1.4);
      cg.addColorStop(0,'rgba(255,40,0,0.7)');cg.addColorStop(1,'rgba(255,40,0,0)');
      c2.beginPath();c2.arc(cxA,cyA,crushR*1.4,0,Math.PI*2);
      c2.fillStyle=cg;c2.fill();
      c2.restore();
    }

    // ── Sopro de fogo do DREXCY (todas as fases) ──────────────────────
    if(b.form==='dragao'&&b.fireBreaths&&b.fireBreaths.length>0){
      b.fireBreaths.forEach(fb=>{
        const alpha=Math.max(0,1-fb.t/fb.maxT);
        c2.save();c2.globalAlpha=alpha*0.55;
        c2.beginPath();
        c2.moveTo(fb.x,fb.y);
        c2.arc(fb.x,fb.y,fb.range,fb.angle-fb.spread,fb.angle+fb.spread);
        c2.closePath();
        const fg=c2.createRadialGradient(fb.x,fb.y,0,fb.x,fb.y,fb.range);
        fg.addColorStop(0,'rgba(255,230,120,0.75)');
        fg.addColorStop(0.35,'rgba(255,120,20,0.55)');
        fg.addColorStop(0.7,'rgba(220,30,0,0.32)');
        fg.addColorStop(1,'rgba(180,10,0,0)');
        c2.fillStyle=fg;c2.fill();
        c2.restore();
        // Fagulhas dentro do cone
        if(Math.random()<0.7){
          const rr=rand(20,fb.range*0.9), aa=fb.angle+rand(-fb.spread,fb.spread);
          _fxParticles.push({x:fb.x+Math.cos(aa)*rr,y:fb.y+Math.sin(aa)*rr,
            vx:Math.cos(aa)*30,vy:Math.sin(aa)*30-15,r:rand(2,6),alpha:0.7,
            color:Math.random()<0.5?'rgba(255,150,30,0.8)':'rgba(255,220,100,0.8)',life:0.4,maxLife:0.4});
        }
      });
    }

    // ── Rugido Devastador do DREXCY (Fase 3) — anéis de onda de choque ──
    if(b.form==='dragao'&&b.roarRings&&b.roarRings.length>0){
      b.roarRings.forEach(rg=>{
        const alpha=Math.max(0,rg.life/rg.maxLife);
        c2.save();c2.globalAlpha=alpha*0.7;
        c2.beginPath();c2.arc(rg.x,rg.y,rg.r,0,Math.PI*2);
        c2.strokeStyle='#ffcc00';c2.lineWidth=8;c2.stroke();
        c2.globalAlpha=alpha*0.3;c2.lineWidth=18;c2.stroke();
        c2.restore();
      });
    }

    // ── Efeitos visuais do CAMALEÃO ──────────────────────────────────
    if(b.form==='camaleao'){
      // Língua (estado extending ou charging)
      if((b.tongueState==='extending'||b.tongueState==='charging')&&b.tongueTip){
        const tx=b.tongueState==='extending'?b.tongueTip.x:b.tongueX;
        const ty=b.tongueState==='extending'?b.tongueTip.y:b.tongueY;
        const tongueAlpha=b.tongueState==='charging'?Math.max(0,0.7-(b.tongueT/0.55)):0.9;
        c2.save();c2.globalAlpha=tongueAlpha;
        // Haste da língua
        c2.beginPath();c2.moveTo(b.x,b.y);c2.lineTo(tx,ty);
        c2.strokeStyle='#88ff44';c2.lineWidth=3;c2.stroke();
        // Bifurcação da ponta
        const ang=Math.atan2(ty-b.y,tx-b.x);
        const fl=14;
        [0.3,-0.3].forEach(da=>{
          c2.beginPath();c2.moveTo(tx,ty);
          c2.lineTo(tx+Math.cos(ang+da)*fl,ty+Math.sin(ang+da)*fl);
          c2.strokeStyle='#ccff66';c2.lineWidth=2;c2.stroke();
        });
        c2.restore();
      }
      // Render língua dos clones
      _reptBossClones.forEach(cl=>{
        if(cl.form!=='camaleao')return;
        if((cl.tongueState==='extending'||cl.tongueState==='charging')&&cl.tongueTip){
          const tx=cl.tongueState==='extending'?cl.tongueTip.x:cl.tongueX;
          const ty=cl.tongueState==='extending'?cl.tongueTip.y:cl.tongueY;
          c2.save();c2.globalAlpha=0.75*cl.alpha;
          c2.beginPath();c2.moveTo(cl.x,cl.y);c2.lineTo(tx,ty);
          c2.strokeStyle='#55ee33';c2.lineWidth=2.5;c2.stroke();
          const ang=Math.atan2(ty-cl.y,tx-cl.x);
          [0.3,-0.3].forEach(da=>{
            c2.beginPath();c2.moveTo(tx,ty);
            c2.lineTo(tx+Math.cos(ang+da)*10,ty+Math.sin(ang+da)*10);
            c2.strokeStyle='#aaffaa';c2.lineWidth=1.5;c2.stroke();
          });
          c2.restore();
        }
      });
      // Chicotada do rabo (fase 3)
      if(b.tailWhipT>0){
        const prog=1-(b.tailWhipT/0.65);
        const sweepArc=1.35*prog; // arco cresce com o progresso
        c2.save();c2.globalAlpha=b.tailWhipT/0.65*0.75;
        c2.beginPath();
        c2.moveTo(b.x,b.y);
        c2.arc(b.x,b.y,200,b.tailWhipAngle-sweepArc/2,b.tailWhipAngle+sweepArc/2);
        c2.closePath();
        const wg=c2.createRadialGradient(b.x,b.y,0,b.x,b.y,200);
        wg.addColorStop(0,'rgba(255,80,0,0.55)');wg.addColorStop(1,'rgba(200,0,0,0)');
        c2.fillStyle=wg;c2.fill();
        c2.strokeStyle='#ff4400';c2.lineWidth=2;c2.stroke();
        c2.restore();
      }
      // Partículas HITKILL (fase 3)
      if(b.killParticles&&b.killParticles.length>0){
        b.killParticles.forEach(kp=>{
          // Trail
          if(kp.trail.length>1){
            c2.save();
            for(let ti=1;ti<kp.trail.length;ti++){
              const a=ti/kp.trail.length*0.7*(kp.life/kp.maxLife);
              c2.globalAlpha=a;
              c2.beginPath();c2.moveTo(kp.trail[ti-1].x,kp.trail[ti-1].y);
              c2.lineTo(kp.trail[ti].x,kp.trail[ti].y);
              c2.strokeStyle='#ff0066';c2.lineWidth=2;c2.stroke();
            }
            c2.restore();
          }
          // Núcleo
          c2.save();c2.globalAlpha=0.9*(kp.life/kp.maxLife);
          c2.beginPath();c2.arc(kp.x,kp.y,kp.r,0,Math.PI*2);
          c2.fillStyle='#ff0044';c2.fill();
          c2.beginPath();c2.arc(kp.x,kp.y,kp.r*0.45,0,Math.PI*2);
          c2.fillStyle='rgba(255,200,200,0.9)';c2.fill();
          c2.restore();
        });
      }
    }

    // Sopros de fogo do Dragão
    if(b.form==='dragao'){
      // Flash branco que cobre a tela
      if(b.flashState==='flashing'||(b.flashState==='charging'&&b.flashT>0.5)){
        const fa=b.flashState==='flashing'?0.85:Math.min(0.5,(b.flashT-0.5)*3);
        c2.save();c2.globalAlpha=fa;
        c2.fillStyle='rgba(255,255,255,1)';
        c2.fillRect(bx,by,W,H);
        c2.restore();
      }
      // Raios que cobrem a tela inteira
      if(b.screenBeams&&b.screenBeams.length>0){
        b.screenBeams.forEach(bm=>{
          const prog=bm.life/bm.maxLife;
          const ex=bm.x+Math.cos(bm.angle)*bm.len;
          const ey=bm.y+Math.sin(bm.angle)*bm.len;
          c2.save();c2.globalAlpha=prog*0.95;
          // Núcleo branco
          c2.beginPath();c2.moveTo(bm.x,bm.y);c2.lineTo(ex,ey);
          c2.strokeStyle='rgba(255,255,255,1)';c2.lineWidth=bm.width*0.4;c2.stroke();
          // Aura laranja/vermelha
          c2.globalAlpha=prog*0.55;
          c2.strokeStyle='rgba(255,80,0,1)';c2.lineWidth=bm.width*1.6;c2.stroke();
          // Halo externo
          c2.globalAlpha=prog*0.2;
          c2.strokeStyle='rgba(255,200,100,1)';c2.lineWidth=bm.width*4;c2.stroke();
          c2.restore();
        });
      }
      // Avisos de meteoro
      if(b.meteorWarnings&&b.meteorWarnings.length>0){
        b.meteorWarnings.forEach(mw=>{
          const prog=mw.t/mw.maxT;
          const a=(1-prog)*0.7;
          c2.save();c2.globalAlpha=a;c2.setLineDash([8,5]);
          c2.beginPath();c2.moveTo(mw.x,mw.yStart);c2.lineTo(mw.x,mw.yEnd);
          c2.strokeStyle='#ff4400';c2.lineWidth=2;c2.stroke();
          c2.setLineDash([]);
          // Meteoro caindo
          const my=mw.yStart+(mw.yEnd-mw.yStart)*prog;
          c2.globalAlpha=(1-prog)*0.9;
          c2.beginPath();c2.arc(mw.x,my,14+prog*4,0,Math.PI*2);
          c2.fillStyle='#ff6600';c2.fill();
          c2.beginPath();c2.arc(mw.x,my,6,0,Math.PI*2);
          c2.fillStyle='rgba(255,255,255,0.9)';c2.fill();
          c2.restore();
        });
      }
    }

    _updateReptBossBar();
  }

  function _applyReptAstroEffectsToBoss(dt){
    if(!_reptBoss||_reptBoss.dying)return;
    const b=_reptBoss;
    objects.forEach(o=>{
      if(o.dead)return;
      const sx=o.sx(),sy=o.sy(),r=o.sr();
      const d=Math.hypot(b.x-sx,b.y-sy);
      const key='_rDmgCd_'+o.id;
      if(b[key]>0){b[key]-=dt;return;}
      let dmg=0,cd=0,effect=null;
      if(o.type==='quasiStar'&&d<r*5)         {dmg=0.06;cd=2.5;effect='#ff8800';}
      else if(o.type==='wolfRayet'&&d<r*6)     {dmg=0.045;cd=2;effect='#44ffaa';}
      else if(o.type==='hypergiant'&&d<r*4)    {dmg=0.05;cd=2.5;effect='#ffcc00';}
      else if(o.type==='gravastar'&&d<r*3)     {dmg=0.02;cd=1.5;effect='#44aaff';}
      else if(o.type==='ironStar'&&d<r*3)      {dmg=0.025;cd=2;effect='#aa8855';}
      else if(o.type==='whiteDwarf'&&d<r*3)    {dmg=0.015;cd=1;effect='#ffffff';}
      else if(o.type==='strangeStar'&&d<r*4)   {dmg=0.055;cd=3;effect='#aa44ff';b.vx*=0.7;b.vy*=0.7;}
      else if(o.type==='vampireStar'&&d<r*4)   {dmg=0.05;cd=3;effect='#ff0044';b.vx*=0.65;b.vy*=0.65;
        o._invasionHP=Math.min(100,(o._invasionHP||50)+10);}
      else if(o.type==='janusStar'&&d<r*5)     {dmg=0.03;cd=2;effect='#00ffff';}
      else if(o.type==='electroweakStar'&&d<r*5){dmg=0.04;cd=2.5;effect='#ffff00';b.vx=0;b.vy=0;}
      if(dmg>0){
        b.formHP=Math.max(0,b.formHP-b.formMaxHP*dmg);
        b[key]=cd;
        _flashReptBoss(effect);
        _fxParticles.push({x:b.x+rand(-20,20),y:b.y+rand(-20,20),
          vx:rand(-25,25),vy:rand(-35,-5),r:rand(2,6),alpha:0.85,
          color:effect||'#ffffff',life:0.5,maxLife:0.5});
      }
    });
  }

  // ── Draw: Aniquilador — despachante por forma ──────────────────────
  function _drawReptBoss(ctx,b,t){
    if(!b)return;
    if(b.form==='serpente') _drawBossSerpente(ctx,b,t);
    else if(b.form==='camaleao') _drawBossCamaleao(ctx,b,t);
    else if(b.form==='dragao') _drawBossDragao(ctx,b,t);
  }

  // ══════════════════════════════════════════════════════════════════
  //  FORMA FINAL: ANIQUILADOR DE GALÁXIAS — NAVE COLOSSAL
  //  A nave não cabe na tela. Cada parte (casco, asas, núcleo, canhões)
  //  aparece em diferentes bordas/regiões, criando a ilusão de uma
  //  estrutura gigantesca que envolve o campo de batalha.
  //  Metal escuro + neon vermelho. SEM shadowBlur.
  // ══════════════════════════════════════════════════════════════════

  // ══════════════════════════════════════════════════════════════════
  //  TABELA UNIFICADA DE DANO POR TIPO DE ASTRO
  //  Antes esta mesma tabela existia copiada 4 vezes (minions da Fase 1,
  //  mini-bosses da Fase 2, boss principal nas Fases 3/4/5) só variando
  //  o multiplicador base — qualquer ajuste de balanceamento exigia editar
  //  4 lugares e sempre corria o risco de ficar dessincronizado (como já
  //  ocorria: as proporções relativas variavam até 10% entre as cópias).
  //  Agora existe uma única fonte de verdade (proporção relativa ao
  //  quasar=1.0) e uma função genérica que aplica o dano a qualquer
  //  entidade (minion, mini-boss ou o próprio Leviatã).
  // ══════════════════════════════════════════════════════════════════
  const RFF_ASTRO_DAMAGE_TABLE=[
    {type:'quasar',        radiusMult:4,  relDmg:1.0,  cd:4.5, effect:'#ff44ff'},
    {type:'pulsar',        radiusMult:10, relDmg:0.786,cd:3.5, effect:'#44ffff', paralyze:1.5},
    {type:'blazar',        radiusMult:8,  relDmg:0.643,cd:3.0, effect:'#ff8844'},
    {type:'magnetar',      radiusMult:12, relDmg:0.571,cd:5.0, effect:'#cc44ff', paralyze:2.5},
    {type:'quasiStar',     radiusMult:5,  relDmg:1.429,cd:2.5, effect:'#ff8800'},
    {type:'wolfRayet',     radiusMult:6,  relDmg:1.071,cd:2.0, effect:'#44ffaa'},
    {type:'hypergiant',    radiusMult:4,  relDmg:1.25, cd:2.5, effect:'#ffcc00'},
    {type:'gravastar',     radiusMult:3,  relDmg:0.571,cd:1.5, effect:'#44aaff'},
    {type:'ironStar',      radiusMult:3,  relDmg:0.643,cd:2.0, effect:'#aa8855'},
    {type:'whiteDwarf',    radiusMult:3,  relDmg:0.357,cd:1.0, effect:'#ffffff'},
    {type:'strangeStar',   radiusMult:4,  relDmg:1.357,cd:3.0, effect:'#aa44ff', paralyze:1.2},
    {type:'vampireStar',   radiusMult:4,  relDmg:1.25, cd:3.0, effect:'#ff0044', paralyze:0.8},
    {type:'janusStar',     radiusMult:5,  relDmg:0.786,cd:2.0, effect:'#00ffff'},
    {type:'electroweakStar',radiusMult:5,relDmg:1.0,  cd:2.5, effect:'#ffff00', paralyze:2.0},
  ];
  // Blackhole e star/cepheid têm mecânica própria (puxão gravitacional /
  // chance rara), tratados fora da tabela dentro da função abaixo.
  //
  // ent: entidade que recebe dano (minion m / mini-boss mb / boss f) — precisa
  //      ter .x .y .maxHP .hp e (opcional) .paralyzed.
  // baseFrac: fração de maxHP causada pelo quasar (relDmg=1.0) por tick.
  // hitKeyPrefix: prefixo único da chave de cooldown por astro (evita que
  //      Fase 1/2/3 compartilhem cooldown indevidamente na mesma entidade).
  // opts.blackholePull: força do puxão do buraco negro (0 desativa).
  // opts.starChance/starFrac: chance e fração de dano de estrelas/cefeidas.
  // opts.explosionR: raio do spawnExplosion no impacto (0 desativa).
  function _rffApplyAstroDamage(ent,dt,baseFrac,hitKeyPrefix,opts){
    opts=opts||{};
    const blackholePull=opts.blackholePull!==undefined?opts.blackholePull:1400;
    const starChance=opts.starChance!==undefined?opts.starChance:0.02;
    const starFrac=opts.starFrac!==undefined?opts.starFrac:baseFrac*0.3;
    const explosionR=opts.explosionR!==undefined?opts.explosionR:0.14;
    const onHitFlash=opts.onHitFlash; // callback opcional (ex: HP bar update)
    objects.forEach(o=>{
      if(o.dead)return;
      const osx=o.sx(),osy=o.sy(),osr=o.sr();
      const dx=osx-ent.x,dy=osy-ent.y,d=Math.hypot(dx,dy)||1;
      const key=hitKeyPrefix+o.type;
      if(ent[key]>0){ent[key]-=dt;return;}
      let dmg=0,cd=0,effect=null;
      if(o.type==='blackhole'&&d<osr*5&&blackholePull>0){
        ent.vx+=(osx-ent.x)/d*blackholePull*dt;ent.vy+=(osy-ent.y)/d*blackholePull*dt;
      }
      if((o.type==='star'||o.type==='cepheid')&&d<osr*3&&Math.random()<starChance){
        dmg=ent.maxHP*starFrac;cd=0;
      }
      for(let i=0;i<RFF_ASTRO_DAMAGE_TABLE.length;i++){
        const row=RFF_ASTRO_DAMAGE_TABLE[i];
        if(o.type===row.type&&d<osr*row.radiusMult){
          dmg=ent.maxHP*baseFrac*row.relDmg;cd=row.cd;effect=row.effect;
          if(row.paralyze!==undefined&&ent.paralyzed!==undefined)ent.paralyzed=Math.max(ent.paralyzed,row.paralyze);
          break;
        }
      }
      if(dmg>0){
        ent.hp=Math.max(0,ent.hp-dmg);
        ent._hitFlashT=0.35;ent.flashT=0.35;ent.flashColor=effect||'#ffffff';
        if(cd>0)ent[key]=cd;
        if(explosionR>0&&typeof spawnExplosion==='function'&&Math.random()<0.3)
          spawnExplosion(ent.x,ent.y,explosionR,false);
        if(typeof onHitFlash==='function')onHitFlash();
      }
    });
  }

  // ── FASE 1 da Forma Final: Ondas de Minions ─────────────────────────
  // O Leviatã (Forma Final) NÃO toma dano na Fase 1 — só seus Minions.
  // 5 ondas, de 5 a 15 minions cada, escalando progressivamente.
  const RFF_WAVE_CONFIG=[
    {count:5},
    {count:8},
    {count:11},
    {count:13},
    {count:15},
  ];
  // 3 tipos de minions — visual CSS-simples (sem shadowBlur, formas geométricas
  // básicas), stats e defesa próprios, no padrão dos Reptilianos normais.
  const RFF_MINION_TYPES=[
    {cls:'viboide',  maxHP:2200, speed:70, atk:60,  color:'#22cc55', scale:1.6},
    {cls:'camaleao',  maxHP:2800, speed:55, atk:80,  color:'#cc8822', scale:1.8},
    {cls:'dragaozinho',maxHP:3600,speed:48, atk:110, color:'#dd3322', scale:2.0},
  ];

  // ── HP GLOBAL do Leviatã (Verdadeira Forma) — 800.000 no total ──
  // Dividido em 5 blocos IGUAIS de 160.000, um por fase (1 a 5).
  // O Leviatã está "conectado" às suas criações: nas Fases 1 e 2 ele é
  // invulnerável a dano direto, mas cada Minion (Fase 1) ou Mini-Boss
  // (Fase 2) morto desconta uma fatia proporcional do bloco de HP
  // daquela fase, como se fossem extensões dele. Nas Fases 3, 4 e 5 o
  // dano é direto no corpo. TUDO desconta do MESMO pool de 800.000 —
  // f.hp NUNCA é resetado ao trocar de fase, desce continuamente do
  // início ao fim das 5 fases.
  const RFF_PHASE_HP_BLOCK=160000;
  const RFF_GLOBAL_MAX_HP=RFF_PHASE_HP_BLOCK*5; // 800.000
  // ── FIX: estas 3 constantes eram usadas em várias partes do código
  // (barra de progresso por fase, condição de transição 3→4, 4→5, e
  // reinício de HP no Mod Menu) mas nunca haviam sido declaradas —
  // ficavam `undefined`, fazendo com que `f.hp<=RFF_PHASE4_START_HP`
  // (undefined) nunca fosse verdadeiro. Resultado: o Leviatã tomava
  // dano de verdade na Fase 3, mas a barra ficava incorreta (NaN%) e a
  // transição de fase nunca disparava — na prática parecia
  // invulnerável a partir da Fase 3. ──────────────────────────────────
  const RFF_PHASE3_START_HP=RFF_GLOBAL_MAX_HP-RFF_PHASE_HP_BLOCK*2; // 480.000
  const RFF_PHASE4_START_HP=RFF_GLOBAL_MAX_HP-RFF_PHASE_HP_BLOCK*3; // 320.000
  const RFF_PHASE5_START_HP=RFF_GLOBAL_MAX_HP-RFF_PHASE_HP_BLOCK*4; // 160.000
  // Total de minions/mini-bosses em todas as ondas (para dano por unidade)
  const RFF_P1_TOTAL_MINIONS=5+8+11+13+15;      // 52 (ver RFF_WAVE_CONFIG)
  const RFF_P2_TOTAL_MINIBOSSES=2+2+2;           // 6  (ver RFF_P2_WAVE_CONFIG)
  const RFF_P1_HP_PER_MINION=RFF_PHASE_HP_BLOCK/RFF_P1_TOTAL_MINIONS;
  const RFF_P2_HP_PER_MINIBOSS=RFF_PHASE_HP_BLOCK/RFF_P2_TOTAL_MINIBOSSES;

  function _rffSpawnWave(f,ar){
    ar=ar||_arenaRect||{x:0,y:0,w:_riftCanvas.width,h:_riftCanvas.height};
    const cfg=RFF_WAVE_CONFIG[f.p1Wave-1];
    if(!cfg)return;
    for(let i=0;i<cfg.count;i++){
      const mt=RFF_MINION_TYPES[Math.floor(Math.random()*RFF_MINION_TYPES.length)];
      f.minions.push({
        x:ar.x+rand(ar.w*0.1,ar.w*0.9),
        y:ar.y+rand(ar.h*0.1,ar.h*0.9),
        vx:rand(-20,20),vy:rand(-20,20),
        hp:mt.maxHP,maxHP:mt.maxHP,atk:mt.atk,speed:mt.speed,
        cls:mt.cls,color:mt.color,scale:mt.scale,
        dead:false,t:0,_atkTimer:1+Math.random()*1.5,
        _hitFlashT:0,flashColor:'#ffffff',paralyzed:0,
        _spawnT:0,
      });
    }
    showTooltip(`🦎 Onda ${f.p1Wave}/${RFF_WAVE_CONFIG.length} de Minions do Leviatã!`);
  }

  function _spawnReptFinalForm(){
    // ── Guard defensivo: nunca recriar a Forma Final se ela já existe ──
    // e não estiver morrendo. Isso evita que qualquer chamada acidental
    // ou duplicada (ex: dois gatilhos disparando no mesmo frame) resete
    // o progresso das ondas de Minions/Guardiões (bug relatado: "a onda
    // de minions reseta quando a Forma Final aparece").
    if(_reptFinalForm&&!_reptFinalForm.dying){
      console.warn('[RFF] _spawnReptFinalForm() chamado com Forma Final já ativa — ignorado para não resetar o progresso.');
      return;
    }
    // ── Limpa os Reptilianos normais (Soldado/Caçador/Berserker/Comandante),
    // naves e portais da invasão de base — o Quasord assume sozinho a tela,
    // sem inimigos concorrentes de fases anteriores ainda vivos. ──────────
    _reptilians.forEach(r=>{r.dead=true;}); _reptilians=[];
    _ships=[]; _portals=[];
    window._reptQuasordOnScreen=true;
    const bar=document.getElementById('rept-boss-hp-bar');
    if(bar){
      bar.classList.add('active');
      const sub  =document.getElementById('rept-boss-hp-subtitle');
      const fill =document.getElementById('rept-boss-hp-fill');
      const phase=document.getElementById('rept-boss-hp-phase');
      const nameEl=document.querySelector('#rept-boss-hp-name span');
      if(sub)   sub.textContent='☠️ QUASORD — LEVIATÃ MECÂNICO';
      if(fill){fill.style.width='100%';fill.className='phase3';}
      if(phase) phase.textContent='QUASORD';
      if(nameEl)nameEl.textContent='💀 ANIQUILADOR DE GALÁXIAS';
    }
    // Sistema de DUAS arenas alternantes: grande (longe) e pequena (perto).
    const _ffCw=_riftCanvas.width||window.innerWidth;
    const _ffCh=_riftCanvas.height||window.innerHeight;
    const N_SEGS=18, SEG_DIST=90;
    const pair=_rffComputeArenaPair(_ffCw,_ffCh,N_SEGS,SEG_DIST);
    const ar=pair.small; // começa contido na arena pequena
    const sx=ar.x+ar.w/2, sy=ar.y+ar.h/2; // começa no centro visível
    const chain=[];
    for(let i=0;i<N_SEGS;i++) chain.push({x:sx,y:sy,a:0});
    _reptFinalForm={
      t:0, x:sx, y:sy, vx:200, vy:0,
      chain,
      route:[], routeIdx:0,
      isBorder:true,
      borderCount:0,
      glitch:0,
      arenaMode:'small', // 'small' | 'big' — arena ativa no momento
      // ── HP GLOBAL — desde a Fase 1, nunca resetado (ver RFF_GLOBAL_MAX_HP) ──
      hp:RFF_GLOBAL_MAX_HP, maxHP:RFF_GLOBAL_MAX_HP,
      // ── Fase 1: Ondas de Minions (Leviatã invulnerável a dano direto) ──
      phase:1,
      invulnerable:true,
      p1Wave:1,
      p1WaveDelay:1.6, // pequeno intervalo antes da 1ª onda surgir
      minions:[],
      // ── Fase 2: Ondas de Mini-Bosses (Guardiões Antigos) ──
      p2Wave:1,
      p2WaveDelay:1.8,
      miniBosses:[],
      // ── Fase 3: Leviatã enlouquecido, vulnerável ──
      p3TransT:0, p3TransDone:false,
      eyeCracked:false, eyeCrackAmt:0,
      eyeLookAngle:0, eyeLookTarget:0, eyeLookTimer:0,
      fangTwitch:0,
      pulsarBeamTimer:0, pulsarBeams:[],
      hitkillTimer:0, hitkillTarget:null, hitkillAimT:0, hitkillState:'idle',
      trapExplTimer:0,
      speedMult:1,
      flashT:0, flashColor:'#ff2200',
      dying:false, dyingT:0,
      // ── Fase 4: transição, ordas de naves, feixes gigantes, buraco negro artificial ──
      p4TransT:0, p4TransDone:false,
      shipWaveTimer:0, ships:[],
      megaBeamTimer:0, megaBeams:[],
      artHoleTimer:0, artHole:null,
      // ── Fase 5: desespero extremo — olho perdido, jatos colossais, serras,
      // investidas borradas, garra que agarra e esmaga astros, singularidades ──
      p5TransT:0, p5TransDone:false,
      eyeGone:false, eyeFallT:0,
      jetTimer:0, jets:[],
      saws:[], sawSpawnTimer:0,
      dashTimer:0, dashState:'idle', dashT:0, dashTargetAngle:0, trail:[],
      grabTimer:0, grabState:'idle', grabTarget:null, grabT:0,
      singularityTimer:0, singularity:null,
    };
    _rffBorderRoute(_reptFinalForm, ar, 0);
    showTooltip('☠️ LEVIATÃ MECÂNICO — QUASORD!');
    const flash=document.getElementById('reptilian-emergency-flash');
    if(flash){flash.style.opacity='1';setTimeout(()=>{flash.style.opacity='0';},900);}
    // HUD: Fase 1 — boss invulnerável, dano vem dos Minions
    const phaseEl=document.getElementById('rept-boss-hp-phase');
    const subEl=document.getElementById('rept-boss-hp-subtitle');
    if(phaseEl)phaseEl.textContent='FASE 1';
    if(subEl)subEl.textContent='☠️ FASE 1 — DESTRUA OS MINIONS!';
    _startRffAudio(1);
    const fillEl=document.getElementById('rept-boss-hp-fill');
    if(fillEl){fillEl.style.width='100%';fillEl.className='phase3';}
    setTimeout(()=>showTooltip('🦎 O Leviatã está invulnerável! Destrua seus Minions!'),1200);
  }

  // ── Atmosfera de batalha da Forma Final ────────────────────────────
  // Vinheta vermelha sutil (cenário "mais avermelhado") + cometas e
  // meteoros de fundo caindo com frequência, mas discretos (baixa
  // opacidade, atrás de tudo, sem interagir com o jogo).
  let _rffBgStreaks=null;
  function _tickRffBattleFx(dt,ctx){
    const cw=_riftCanvas.width, ch=_riftCanvas.height;

    // Vinheta vermelha sutil nas bordas — reforça o clima de batalha
    // sem cobrir o centro nem atrapalhar a visibilidade do boss.
    ctx.save();
    const vg=ctx.createRadialGradient(cw/2,ch/2,Math.min(cw,ch)*0.35, cw/2,ch/2,Math.max(cw,ch)*0.72);
    vg.addColorStop(0,'rgba(120,0,10,0)');
    vg.addColorStop(1,'rgba(120,0,10,0.16)');
    ctx.fillStyle=vg;
    ctx.fillRect(0,0,cw,ch);
    ctx.restore();

    // Cometas/meteoros de fundo: riscos finos caindo em diagonal, baixa
    // opacidade, atrás de tudo (desenhados antes do resto da cena).
    if(!_rffBgStreaks) _rffBgStreaks=[];
    if(Math.random()<dt*1.8){ // frequência: comum, mas não excessiva
      const fromLeft=Math.random()<0.5;
      _rffBgStreaks.push({
        x: fromLeft? rand(-40,cw*0.5) : rand(cw*0.5,cw+40),
        y: -30,
        vx: fromLeft? rand(60,140) : rand(-140,-60),
        vy: rand(220,360),
        len: rand(40,90),
        life: 1,
      });
    }
    ctx.save();
    for(let i=_rffBgStreaks.length-1;i>=0;i--){
      const s=_rffBgStreaks[i];
      s.x+=s.vx*dt; s.y+=s.vy*dt;
      if(s.y>ch+60){ _rffBgStreaks.splice(i,1); continue; }
      const ang=Math.atan2(s.vy,s.vx);
      const tx=s.x-Math.cos(ang)*s.len, ty=s.y-Math.sin(ang)*s.len;
      const grad=ctx.createLinearGradient(s.x,s.y,tx,ty);
      grad.addColorStop(0,'rgba(255,210,180,0.22)');
      grad.addColorStop(1,'rgba(255,210,180,0)');
      ctx.strokeStyle=grad; ctx.lineWidth=1.6; ctx.lineCap='round';
      ctx.beginPath(); ctx.moveTo(s.x,s.y); ctx.lineTo(tx,ty); ctx.stroke();
    }
    ctx.restore();
  }

  // ── Arena do Leviatã: quadrado cujo PERÍMETRO = comprimento da cobra ──
  // tailLen = distância da cauda até a cabeça (cauda→cabeça, "fim do corpo").
  // perímetro do quadrado = 4*lado = tailLen  →  lado = tailLen/4.
  // Esta é a arena PADRÃO (base) usada para derivar as duas arenas reais.
  function _rffComputeArena(cw,ch,nSegs,segDist){
    const tailLen=(nSegs-1)*segDist;      // cauda → cabeça
    const side=tailLen/4;                  // lado do quadrado (perímetro=tailLen)
    const x=(cw-side)/2, y=(ch-side)/2;    // centralizado no canvas
    return {x,y,w:side,h:side,side,tailLen};
  }

  // ── Sistema de DUAS arenas alternantes ────────────────────────────
  // Arena GRANDE ("longe"): o dobro do lado da arena padrão.
  // Arena PEQUENA ("perto"): metade do lado da arena GRANDE (= padrão).
  // Ambas centralizadas no mesmo ponto. Quando a cabeça toca o limite
  // da arena ATIVA, a alternância acontece instantaneamente: a outra
  // arena passa a ser o novo limite. É esperado que o boss saia da
  // arena "padrão" original — ele agora alterna entre as duas extremas,
  // nunca ficando livre sem limite algum (sempre há uma arena ativa).
  function _rffComputeArenaPair(cw,ch,nSegs,segDist){
    const base=_rffComputeArena(cw,ch,nSegs,segDist);
    const cx=base.x+base.w/2, cy=base.y+base.h/2;
    const bigSide=base.side*2;      // arena grande: dobro da padrão
    const smallSide=bigSide/2;      // arena pequena: metade da grande (= padrão)
    const big  ={x:cx-bigSide/2,   y:cy-bigSide/2,   w:bigSide,   h:bigSide,   side:bigSide};
    const small={x:cx-smallSide/2, y:cy-smallSide/2, w:smallSide, h:smallSide, side:smallSide};
    return {big,small,cx,cy};
  }

  // Tamanho real, sem escala: o boss usa coordenadas brutas da arena.


  // em passos grandes — a cabeça percorre todo o contorno e o corpo segue.
  function _rffBorderRoute(f, ar, startCorner){
    const {x,y,w,h}=ar;
    // 8 pontos distribuídos pelo perímetro: TL, TM, TR, RM, BR, BM, BL, LM
    const C=[
      {x:x,       y:y      },  // 0 TL
      {x:x+w*0.5, y:y      },  // 1 TM
      {x:x+w,     y:y      },  // 2 TR
      {x:x+w,     y:y+h*0.5}, // 3 RM
      {x:x+w,     y:y+h    }, // 4 BR
      {x:x+w*0.5, y:y+h    }, // 5 BM
      {x:x,       y:y+h    }, // 6 BL
      {x:x,       y:y+h*0.5}, // 7 LM
    ];
    const pts=[];
    for(let i=1;i<=8;i++) pts.push(C[(startCorner+i)%8]);
    f.route=pts; f.routeIdx=0; f.isBorder=true;
  }

  // Rota aleatória: varreduras amplas que cruzam a tela de ponta a ponta,
  // garantindo que o corpo siga um caminho visível.
  function _rffRandomRoute(f, ar){
    const {x,y,w,h}=ar;
    const t=Math.floor(Math.random()*3);
    const pts=[];
    if(t===0){
      // Varredura diagonal completa com ponto intermediário
      const goRight=Math.random()<0.5;
      if(goRight){
        pts.push({x:x,       y:y+rand(h*0.1,h*0.4)});
        pts.push({x:x+w*0.5, y:y+rand(h*0.3,h*0.7)});
        pts.push({x:x+w,     y:y+rand(h*0.6,h*0.9)});
      } else {
        pts.push({x:x+w,     y:y+rand(h*0.1,h*0.4)});
        pts.push({x:x+w*0.5, y:y+rand(h*0.3,h*0.7)});
        pts.push({x:x,       y:y+rand(h*0.6,h*0.9)});
      }
    } else if(t===1){
      // Zigue-zague amplo de lado a lado
      const goTop=Math.random()<0.5;
      pts.push({x:x,         y:goTop?y+rand(h*0.1,h*0.35):y+rand(h*0.65,h*0.9)});
      pts.push({x:x+w*0.33,  y:goTop?y+rand(h*0.6,h*0.9):y+rand(h*0.1,h*0.4)});
      pts.push({x:x+w*0.66,  y:goTop?y+rand(h*0.1,h*0.4):y+rand(h*0.6,h*0.9)});
      pts.push({x:x+w,       y:goTop?y+rand(h*0.5,h*0.8):y+rand(h*0.2,h*0.5)});
    } else {
      // Varredura vertical de cima a baixo com desvio lateral
      const goDown=Math.random()<0.5;
      pts.push({x:x+rand(w*0.1,w*0.4), y:goDown?y:y+h});
      pts.push({x:x+rand(w*0.4,w*0.8), y:goDown?y+h*0.5:y+h*0.5});
      pts.push({x:x+rand(w*0.1,w*0.5), y:goDown?y+h:y});
    }
    f.route=pts; f.routeIdx=0; f.isBorder=false;
  }

  // Retorna o índice do ponto de borda mais próximo da posição atual (8 pontos)
  function _rffNearestCorner(f, ar){
    const {x,y,w,h}=ar;
    const C=[
      {x:x,       y:y,       c:0},
      {x:x+w*0.5, y:y,       c:1},
      {x:x+w,     y:y,       c:2},
      {x:x+w,     y:y+h*0.5, c:3},
      {x:x+w,     y:y+h,     c:4},
      {x:x+w*0.5, y:y+h,     c:5},
      {x:x,       y:y+h,     c:6},
      {x:x,       y:y+h*0.5, c:7},
    ];
    let best=0, bestD=Infinity;
    C.forEach(c=>{const d=Math.hypot(c.x-f.x,c.y-f.y);if(d<bestD){bestD=d;best=c.c;}});
    return best;
  }

  function _tickReptFinalForm(dt,ctx){
    const f=_reptFinalForm; if(!f)return;
    f.t+=dt;
    f.glitch=Math.random()<0.015?rand(0.3,0.9):Math.max(0,f.glitch-dt*4);

    // ── Sistema de DUAS arenas alternantes ────────────────────────────
    // Grande (longe) = 2x a arena padrão. Pequena (perto) = metade da
    // grande (= padrão). Ao tocar a borda da arena ATIVA, alterna
    // instantaneamente para a outra, que passa a ser o novo limite.
    // O boss sai da arena "padrão" original por design — mas nunca
    // ultrapassa a arena GRANDE (clamp final), evitando que suma de vez.
    const cw=_riftCanvas.width, ch=_riftCanvas.height;
    const SEG_DIST=90;
    const chain=f.chain;
    const N=chain.length;
    const pair=_rffComputeArenaPair(cw,ch,N,SEG_DIST);
    if(!f.arenaMode) f.arenaMode='small';
    let ar=f.arenaMode==='big'?pair.big:pair.small;

    if(!f.route||f.route.length===0) _rffBorderRoute(f,ar,0);

    // ── FASE 3/4/5 — Transição: OBRIGA a cabeça a buscar o centro da
    // arena PEQUENA FIXA (pair.small), garantindo que o olho/corpo fique
    // visível durante toda a animação de transição (em vez de seguir a
    // rota normal de patrulha, que poderia deixá-lo fora de vista).
    // IMPORTANTE: usa pair.small (fixo) em vez de `ar` (que alterna entre
    // big/small toda vez que o corpo toca uma borda) — usar `ar` fazia o
    // alvo do centro "pular" de posição no meio da rota sempre que o
    // corpo batesse numa borda durante a transição, travando a cabeça
    // num cabo-de-guerra entre dois centros diferentes (bug do
    // congelamento na Fase 3).
    const forcingCenterDuringTrans=((f.phase===3&&!f.p3TransDone)||(f.phase===4&&!f.p4TransDone)||(f.phase===5&&!f.p5TransDone))&&!f.dying;
    if(forcingCenterDuringTrans){
      const centerX=pair.small.x+pair.small.w/2, centerY=pair.small.y+pair.small.h/2;
      f.route=[{x:centerX,y:centerY}];
      f.routeIdx=0;
      f.isBorder=false;
    }

    // ── Movimento da cabeça com limite de curvatura ──────────────────
    // Ângulo atual de movimento
    const curAngle=Math.atan2(f.vy,f.vx);
    // Velocidade base progressiva por fase: Fase 2 > Fase 1, Fase 3 > Fase 2,
    // Fase 4 MUITO mais rápida que a Fase 3.
    let _phaseSpdMult=1;
    if(f.phase===1) _phaseSpdMult=1;
    else if(f.phase===2) _phaseSpdMult=1.18;
    else if(f.phase===3) _phaseSpdMult=1.4;
    else if(f.phase===4) _phaseSpdMult=2.3;
    else if(f.phase===5) _phaseSpdMult=3.6;
    const SPD=(forcingCenterDuringTrans?90:190)*_phaseSpdMult;
    const wp=f.route[Math.min(f.routeIdx,f.route.length-1)];
    const ddx=wp.x-f.x, ddy=wp.y-f.y, dd=Math.hypot(ddx,ddy)||1;
    const targetAngle=Math.atan2(ddy,ddx);

    // Aplica velocidade diretamente para o waypoint (sem limite de curvatura
    // na cabeça — o limite fica nos ângulos dos segmentos, não no trajeto).
    f.vx+=(ddx/dd*SPD-f.vx)*dt*8;
    f.vy+=(ddy/dd*SPD-f.vy)*dt*8;
    // Uma vez perto do centro durante a transição, freia quase totalmente
    // para manter a cabeça parada e o olho visível enquanto a animação ocorre.
    if(forcingCenterDuringTrans&&dd<60){
      f.vx*=Math.max(0,1-dt*4); f.vy*=Math.max(0,1-dt*4);
    }
    f.x+=f.vx*dt; f.y+=f.vy*dt;

    // ── Toque na borda da arena ATIVA → "espelho": reflete a direção ──
    // Como um espelho real: se bateu numa borda horizontal (topo/baixo),
    // inverte a componente vertical da velocidade (vy); se bateu numa
    // borda vertical (esquerda/direita), inverte a horizontal (vx).
    // Cantos invertem ambas. Junto com isso, alterna a arena ativa.
    // IMPORTANTE: só dispara uma vez por toque (flag f._onEdge) — sem
    // isso, a reflexão repetia todo frame enquanto a cabeça permanecesse
    // encostada na borda, brigando com a atração ao waypoint e travando
    // o movimento no lugar (tremor/trava).
    // ── FASE 5 — Investida (dash): ignora a barreira da arena pequena
    // ativa e usa a arena GRANDE (união das duas) como limite, para que
    // a investida seja livre e não fique presa refletindo na arena menor. ──
    const _rffIsDashing = f.phase===5 && f.dashState==='dashing';
    const arBorder = _rffIsDashing ? pair.big : ar;
    const hitLeft  = f.x<=arBorder.x;
    const hitRight = f.x>=arBorder.x+arBorder.w;
    const hitTop   = f.y<=arBorder.y;
    const hitBot   = f.y>=arBorder.y+arBorder.h;
    const touchedEdge = hitLeft||hitRight||hitTop||hitBot;
    if(touchedEdge && !f._onEdge){
      f._onEdge=true;
      if(hitLeft||hitRight) f.vx=-f.vx;   // reflexo no eixo X
      if(hitTop||hitBot)    f.vy=-f.vy;   // reflexo no eixo Y
      // Clampa a cabeça exatamente na borda tocada (evita atravessar)
      const preX=f.x, preY=f.y;
      if(hitLeft)  f.x=arBorder.x;
      if(hitRight) f.x=arBorder.x+arBorder.w;
      if(hitTop)   f.y=arBorder.y;
      if(hitBot)   f.y=arBorder.y+arBorder.h;
      // Desloca TODA a cadeia pela mesma correção aplicada à cabeça —
      // sem isso, só a cabeça "teleporta" para a borda e o corpo (que
      // depende da cadeia recalculada a partir dela) leva vários frames
      // para alcançar, criando o efeito de partes "ficando para trás".
      const corrX=f.x-preX, corrY=f.y-preY;
      if(corrX||corrY) for(let i=0;i<N;i++){ chain[i].x+=corrX; chain[i].y+=corrY; }

      if(_rffIsDashing){
        // Durante a investida, só reflete a velocidade (mantendo o dash
        // vivo até acabar); não alterna arena nem gera nova rota, pois
        // isso é tratado normalmente ao fim do dash pelo tick da Fase 5.
      } else {
        f.arenaMode = f.arenaMode==='big' ? 'small' : 'big';
        ar = f.arenaMode==='big'?pair.big:pair.small;
        // Nova rota a partir do canto mais próximo da nova arena, na direção
        // refletida — mantém a continuidade do "espelho" visualmente.
        // routeIdx começa do zero junto com a rota nova (consistente com o
        // sistema de "trocar só ao fim da rota").
        _rffBorderRoute(f,ar,_rffNearestCorner(f,ar));
      }
    } else if(!touchedEdge){
      f._onEdge=false; // libera para refletir de novo na próxima vez que tocar
    }

    // ── Clamp final de segurança na arena GRANDE ──────────────────────
    // Garante que o boss NUNCA suma de vez da existência (sempre dentro
    // de pelo menos a maior das duas arenas), mesmo em casos extremos.
    // Também desloca a cadeia inteira junto, pelo mesmo motivo acima.
    {
      const preX=f.x, preY=f.y;
      if(f.x<pair.big.x) f.x=pair.big.x;
      if(f.x>pair.big.x+pair.big.w) f.x=pair.big.x+pair.big.w;
      if(f.y<pair.big.y) f.y=pair.big.y;
      if(f.y>pair.big.y+pair.big.h) f.y=pair.big.y+pair.big.h;
      const corrX=f.x-preX, corrY=f.y-preY;
      if(corrX||corrY) for(let i=0;i<N;i++){ chain[i].x+=corrX; chain[i].y+=corrY; }
    }

    // ── Waypoint alcançado ───────────────────────────────────────────
    if(dd<32){
      f.routeIdx++;
      // Troca de rota só acontece quando a ROTA INTEIRA termina —
      // evita o boss parecer "perdido" mudando de direção a todo momento.
      if(f.routeIdx>=f.route.length){
        if(f.isBorder){
          f.borderCount=(f.borderCount||0)+1;
          if(Math.random()<0.5){
            _rffRandomRoute(f,ar);
          } else {
            _rffBorderRoute(f,ar,_rffNearestCorner(f,ar));
          }
        } else {
          // Aleatória terminou: volta à rota de borda pelo canto mais próximo
          _rffBorderRoute(f,ar,_rffNearestCorner(f,ar));
          f.borderCount=0;
        }
      }
    }

    // ── Cadeia física ────────────────────────────────────────────────
    chain[0].x=f.x; chain[0].y=f.y;
    for(let i=1;i<N;i++){
      const prev=chain[i-1], cur=chain[i];
      const dx=prev.x-cur.x, dy=prev.y-cur.y;
      const d=Math.hypot(dx,dy)||1;
      cur.x=prev.x-dx/d*SEG_DIST;
      cur.y=prev.y-dy/d*SEG_DIST;
    }
    // Ângulos: calcula geometricamente mas limita a diferença máxima
    // entre segmentos consecutivos (propagado da cabeça→cauda).
    // Evita que trapézios girem demais em curvas, mantendo a forma visual.
    const MAX_SEG_TURN=0.38; // ~22° por segmento
    const mv=Math.hypot(f.vx,f.vy);
    chain[0].a=mv>8?Math.atan2(f.vy,f.vx):(chain[0].a||0);
    for(let i=1;i<N;i++){
      const raw=Math.atan2(chain[i-1].y-chain[i].y, chain[i-1].x-chain[i].x);
      let diff=raw-chain[i-1].a;
      while(diff>Math.PI)diff-=Math.PI*2;
      while(diff<-Math.PI)diff+=Math.PI*2;
      chain[i].a=chain[i-1].a+Math.max(-MAX_SEG_TURN,Math.min(MAX_SEG_TURN,diff));
    }

    // ── Leviatã desenhado primeiro (camada de baixo) ──────────────────
    _drawReptFinalForm(ctx,f,ar,pair);

    // ── Arena de GAMEPLAY fixa (pair.small) ────────────────────────────
    // IMPORTANTE: `ar` acima é a arena do CORPO DECORATIVO do Leviatã,
    // que alterna entre pair.big/pair.small toda vez que a cabeça toca
    // uma borda (efeito visual de "espelhamento"). Usar essa `ar` volátil
    // para minions, mini-bosses e o combate direto causava bugs graves:
    // unidades "fugindo" da tela (a arena mudava de tamanho sob elas),
    // congelamentos na Fase 3 e movimento travado na Fase 5. As fases de
    // GAMEPLAY sempre usam a arena PEQUENA fixa (pair.small), nunca `ar`.
    const gameplayAr=pair.small;

    // ── FASE 1: Ondas de Minions (camada acima do Leviatã) ────────────
    if(f.phase===1) _rffTickPhase1(dt,ctx,f,gameplayAr);
    // ── FASE 2: Ondas de Mini-Bosses (camada acima do Leviatã) ────────
    if(f.phase===2) _rffTickPhase2(dt,ctx,f,gameplayAr);
    // ── FASE 3: Leviatã enlouquecido, vulnerável ───────────────────────
    if(f.phase===3) _rffTickPhase3(dt,ctx,f,gameplayAr,pair);
    // ── FASE 4: Naves capturadas, feixes gigantes, buraco negro artificial ──
    if(f.phase===4) _rffTickPhase4(dt,ctx,f,gameplayAr,pair);
    // ── FASE 5: Desespero extremo — jatos colossais, serras, investidas, garra ──
    if(f.phase===5) _rffTickPhase5(dt,ctx,f,gameplayAr,pair);
  }

  // ── Fase 1: lógica de ondas, IA dos minions e dano vindo de astros ──
  function _rffTickPhase1(dt,ctx,f,ar){
    // Delay antes da primeira onda / entre ondas
    if(f.minions.length===0){
      f.p1WaveDelay-=dt;
      if(f.p1WaveDelay<=0){
        _rffSpawnWave(f,ar);
        f.p1WaveDelay=999; // trava até a onda ser limpa de novo
      }
    }

    const cx=ar.x+ar.w/2, cy=ar.y+ar.h/2;

    f.minions.forEach(m=>{
      if(m.dead)return;
      m.t+=dt;
      m._spawnT+=dt;
      m._hitFlashT=Math.max(0,m._hitFlashT-dt*3);
      if(m.paralyzed>0)m.paralyzed=Math.max(0,m.paralyzed-dt);

      // Alvo: astro mais próximo (mesmo padrão dos Reptilianos normais)
      let target=null,bestD=Infinity;
      objects.forEach(o=>{
        if(o.dead)return;
        const dx=o.sx()-m.x,dy=o.sy()-m.y,d2=dx*dx+dy*dy;
        if(d2<bestD){bestD=d2;target=o;}
      });

      if(m.paralyzed<=0){
        if(target){
          const dx=target.sx()-m.x,dy=target.sy()-m.y,d=Math.sqrt(dx*dx+dy*dy)||1;
          m.vx+=dx/d*m.speed*1.1*dt;
          m.vy+=dy/d*m.speed*1.1*dt;
        } else {
          // ── Sem astro para perseguir: vai para perto do centro da arena
          // e perambula por ali, em vez de vagar aleatoriamente (o que
          // fazia os minions se escondendo/acumulando nas laterais). ──
          const distToCenter=Math.hypot(cx-m.x,cy-m.y);
          if(distToCenter>ar.w*0.18){
            const dxc=cx-m.x,dyc=cy-m.y,dc=distToCenter||1;
            m.vx+=dxc/dc*m.speed*1.1*dt;
            m.vy+=dyc/dc*m.speed*1.1*dt;
          } else {
            m.vx+=(Math.random()-.5)*m.speed*dt;
            m.vy+=(Math.random()-.5)*m.speed*dt;
          }
        }
      }
      const spd=Math.sqrt(m.vx*m.vx+m.vy*m.vy)||1;
      if(spd>m.speed){m.vx=m.vx/spd*m.speed;m.vy=m.vy/spd*m.speed;}
      m.x+=m.vx*dt;m.y+=m.vy*dt;

      // Bounce nas bordas da arena
      if(m.x<ar.x){m.x=ar.x;m.vx=Math.abs(m.vx)*.5;}
      if(m.x>ar.x+ar.w){m.x=ar.x+ar.w;m.vx=-Math.abs(m.vx)*.5;}
      if(m.y<ar.y){m.y=ar.y;m.vy=Math.abs(m.vy)*.5;}
      if(m.y>ar.y+ar.h){m.y=ar.y+ar.h;m.vy=-Math.abs(m.vy)*.5;}

      // Ataque a astros
      m._atkTimer=Math.max(0,m._atkTimer-dt);
      if(target&&m._atkTimer<=0){
        const tsx=target.sx(),tsy=target.sy();
        const dx=tsx-m.x,dy=tsy-m.y,d=Math.sqrt(dx*dx+dy*dy);
        const hitR=Math.max(target.sr()*1.2,45);
        if(d<hitR){
          if(target.hp!==undefined){
            target.hp=Math.max(0,target.hp-m.atk);
            if(target.hp<=0)target.dead=true;
          } else if(Math.random()<0.15){
            target._invasionDead=true;target.dead=true;
            if(typeof spawnExplosion==='function')spawnExplosion(tsx,tsy,0.4,false);
            showTooltip(`🦎 Minion do Leviatã destruiu ${target.name||target.type}!`);
          }
          m._atkTimer=0.7+Math.random()*1.0;
          m._hitFlashT=0.25;
        }
      }

      // Dano de astros ao minion — agora usa a tabela unificada (antes
      // era uma cópia local da mesma tabela repetida em 4 lugares).
      _rffApplyAstroDamage(m,dt,.10,'_rffMinionHit_',{explosionR:0.14});

      if(m.hp<=0&&!m.dead){
        m.dead=true;
        // Leviatã está "conectado" aos minions: cada um morto desconta
        // sua fatia proporcional do bloco de HP global da Fase 1.
        f.hp=Math.max(0,f.hp-RFF_P1_HP_PER_MINION);
        if(typeof spawnExplosion==='function')spawnExplosion(m.x,m.y,0.35,false);
      }
    });

    f.minions.forEach(m=>{if(!m.dead)_drawRffMinion(ctx,m,f.t);});
    f.minions=f.minions.filter(m=>!m.dead);

    // ── Barra de HP mostra o HP GLOBAL real do Leviatã (bloco da Fase 1) ──
    const cfg=RFF_WAVE_CONFIG[f.p1Wave-1];
    {
      const pct=Math.max(0,f.hp/f.maxHP*100);
      const fillEl=document.getElementById('rept-boss-hp-fill');
      if(fillEl)fillEl.style.width=pct+'%';
      const subEl=document.getElementById('rept-boss-hp-subtitle');
      if(subEl&&cfg)subEl.textContent=`☠️ ONDA ${f.p1Wave}/${RFF_WAVE_CONFIG.length} — Minions: ${f.minions.length}/${cfg.count} — HP: ${Math.ceil(pct)}%`;
    }

    // ── Onda limpa → próxima onda ou fim da Fase 1 ──
    if(f.minions.length===0&&f.p1WaveDelay>=999){
      if(f.p1Wave>=RFF_WAVE_CONFIG.length){
        // Fase 1 concluída — inicia Fase 2 (Leviatã segue invulnerável)
        f.phase=2;
        f.p2Wave=1;
        f.p2WaveDelay=1.8;
        f.miniBosses=[];
        showTooltip('☠️ Todas as ondas de Minions destruídas! O LEVIATÃ INVOCA SEUS ANTIGOS GUARDIÕES!');
        const phaseEl=document.getElementById('rept-boss-hp-phase');
        const subEl=document.getElementById('rept-boss-hp-subtitle');
        const fillEl=document.getElementById('rept-boss-hp-fill');
        if(phaseEl)phaseEl.textContent='FASE 2';
        if(subEl)subEl.textContent='☠️ FASE 2 — GUARDIÕES ANTIGOS!';
        _startRffAudio(2);
        // Barra NÃO reseta para 100% — HP é global e contínuo entre fases.
        const flash=document.getElementById('reptilian-emergency-flash');
        if(flash){flash.style.opacity='1';setTimeout(()=>{flash.style.opacity='0';},700);}
      } else {
        f.p1Wave++;
        f.p1WaveDelay=2.2;
      }
    }
  }

  // ── Visual CSS-simples dos Minions (sem shadowBlur, formas geométricas) ──
  function _drawRffMinion(c,m,t){
    const bc=m._hitFlashT>0?m.flashColor:m.color;
    const sz=m.scale*Math.max(0.7,Math.min(1.8,cam.zoom));
    const bob=Math.sin(t*4+m.x*0.02)*2;
    const spawnScale=Math.min(1,m._spawnT/0.35);

    c.save();
    c.translate(m.x,m.y+bob);
    c.scale(sz*spawnScale,sz*spawnScale);
    if(m.paralyzed>0)c.translate(rand(-2,2),rand(-1.5,1.5));
    c.lineCap='round';c.lineJoin='round';

    if(m.cls==='viboide'){
      // Corpo ondulado simples — elipses encadeadas
      for(let i=4;i>=0;i--){
        const tf=i/4;
        const sx=-tf*16*Math.cos(t*3+m.t), sy=Math.sin(t*5+i*0.9)*3;
        c.beginPath();c.ellipse(sx,sy,7-tf*3.5,5-tf*2.2,0,0,Math.PI*2);
        c.fillStyle=i===0?bc:'#0a1a0a';c.fill();
        c.strokeStyle=bc;c.lineWidth=1.2;c.stroke();
      }
      // Olhos
      c.fillStyle='#ffff00';
      c.beginPath();c.arc(3,-2,1.3,0,Math.PI*2);c.fill();
    } else if(m.cls==='camaleao'){
      // Corpo oval + cabeça triangular + crista
      c.beginPath();c.ellipse(0,2,9,6,0,0,Math.PI*2);
      c.fillStyle=bc;c.fill();c.strokeStyle='#5a3a10';c.lineWidth=1.4;c.stroke();
      c.beginPath();c.moveTo(8,-1);c.lineTo(15,1);c.lineTo(8,5);c.closePath();
      c.fillStyle=bc;c.fill();c.stroke();
      // Crista
      c.strokeStyle=bc;c.lineWidth=1.5;
      for(let i=0;i<3;i++){
        c.beginPath();c.moveTo(-4+i*4,-4);c.lineTo(-4+i*4,-9);c.stroke();
      }
      // Olho giratório
      c.fillStyle='#fff';c.beginPath();c.arc(10,-1,2,0,Math.PI*2);c.fill();
      c.fillStyle='#000';c.beginPath();c.arc(10+Math.cos(t*3)*0.8,-1+Math.sin(t*3)*0.8,1,0,Math.PI*2);c.fill();
    } else { // dragaozinho
      // Corpo pequeno + asas triangulares simples + cabeça
      const wingFlap=Math.sin(t*8)*0.4+0.6;
      c.strokeStyle=bc;c.lineWidth=1.4;c.fillStyle=`${bc}55`;
      c.beginPath();c.moveTo(-3,-2);c.lineTo(-14,-8*wingFlap);c.lineTo(-9,2);c.closePath();c.fill();c.stroke();
      c.beginPath();c.moveTo(3,-2);c.lineTo(14,-8*wingFlap);c.lineTo(9,2);c.closePath();c.fill();c.stroke();
      // Corpo
      c.beginPath();c.ellipse(0,2,7,5,0,0,Math.PI*2);
      c.fillStyle=bc;c.fill();c.strokeStyle='#5a0f0f';c.lineWidth=1.2;c.stroke();
      // Cabeça
      c.beginPath();c.moveTo(5,-1);c.lineTo(12,-2);c.lineTo(11,3);c.lineTo(5,4);c.closePath();
      c.fillStyle=bc;c.fill();c.stroke();
      // Olho
      c.fillStyle='#ffcc00';c.beginPath();c.arc(9,0,1.2,0,Math.PI*2);c.fill();
    }

    // Barra de HP mini acima do minion
    const hpPct=Math.max(0,m.hp/m.maxHP);
    c.globalAlpha=0.9;
    c.fillStyle='#220000';c.fillRect(-9,-14,18,2.4);
    c.fillStyle=hpPct>0.5?'#33ff55':hpPct>0.2?'#ffcc33':'#ff3322';
    c.fillRect(-9,-14,18*hpPct,2.4);
    c.globalAlpha=1;

    c.restore();
  }

  // ══════════════════════════════════════════════════════════════════
  //  FASE 2 da Forma Final: Ondas de Mini-Bosses (Guardiões Antigos)
  //  Versões fracas e sem fases da Serpente/Camaleão/Dragão originais.
  //  Atacam normalmente e podem "devorar" astros mordendo-os. O Leviatã
  //  segue invulnerável — só os mini-bosses recebem dano.
  // ══════════════════════════════════════════════════════════════════
  const RFF_P2_WAVE_CONFIG=[
    {count:2},
    {count:2},
    {count:2},
  ];
  // Guardiões fracos: HP de mini-boss de verdade, mas sem fases/lasers/clones.
  const RFF_MINIBOSS_TYPES=[
    {form:'serpente', maxHP:18000, speed:110, atk:180, scale:0.42},
    {form:'camaleao', maxHP:22000, speed:150, atk:220, scale:0.40},
    {form:'dragao',   maxHP:28000, speed:130, atk:280, scale:0.38},
  ];

  function _rffSpawnMiniBossWave(f,ar){
    const cfg=RFF_P2_WAVE_CONFIG[f.p2Wave-1];
    if(!cfg)return;
    for(let i=0;i<cfg.count;i++){
      const mt=RFF_MINIBOSS_TYPES[Math.floor(Math.random()*RFF_MINIBOSS_TYPES.length)];
      const sx=ar.x+rand(ar.w*0.15,ar.w*0.85), sy=ar.y+rand(ar.h*0.15,ar.h*0.85);
      f.miniBosses.push({
        form:mt.form,
        x:sx,y:sy,vx:rand(-40,40),vy:rand(-40,40),
        hp:mt.maxHP,maxHP:mt.maxHP,atk:mt.atk,speed:mt.speed,scale:mt.scale,
        dead:false,t:0,_atkTimer:1+Math.random()*1.5,
        flashT:0,flashColor:'#ffffff',glitchIntensity:0,
        _da:Math.random()*Math.PI*2,
        wingSpread:mt.form==='dragao'?1:0,
        camState:'move',camStateT:0,camHeadAngle:0,
        // Mordida ("devorar"): muda rota suavemente até um astro e o destrói
        biteTarget:null, biteCd:2+Math.random()*3, biteTimer:0,
        _spawnT:0,
        // ── NOVO: Elo de energia — mecânica exclusiva da Fase 2. Guardiões
        // convergem periodicamente e formam uma linha de energia entre si
        // que causa dano em área na linha, obrigando o jogador a reposicionar
        // astros para fora do "corredor" formado — diferente da Fase 1,
        // onde cada minion ataca isoladamente sem coordenação entre eles.
        linkCd:4+Math.random()*2, linking:false, linkT:0,
      });
    }
    showTooltip(`🦎 Guardião Antigo desperta! Onda ${f.p2Wave}/${RFF_P2_WAVE_CONFIG.length}`);
  }

  function _rffTickPhase2(dt,ctx,f,ar){
    if(f.miniBosses.length===0){
      f.p2WaveDelay-=dt;
      if(f.p2WaveDelay<=0){
        _rffSpawnMiniBossWave(f,ar);
        f.p2WaveDelay=999;
      }
    }

    // ── Elo de energia: quando 2+ Guardiões estão vivos, periodicamente
    // um par entra em modo "linking" — param de perseguir, se aproximam
    // um pouco e disparam uma linha de energia entre si por ~1.4s que
    // danifica qualquer astro que a atravessar. ─────────────────────────
    const aliveMb=f.miniBosses.filter(mb=>!mb.dead);
    if(aliveMb.length>=2&&!aliveMb.some(mb=>mb.linking)){
      aliveMb[0].linkCd-=dt;
      if(aliveMb[0].linkCd<=0){
        aliveMb[0].linking=true;aliveMb[1].linking=true;
        aliveMb[0].linkPartner=aliveMb[1];aliveMb[1].linkPartner=aliveMb[0];
        aliveMb[0].linkT=0;aliveMb[1].linkT=0;
        showTooltip('🦎⚡ Guardiões Antigos formam um elo de energia!');
      }
    }
    f.miniBosses.forEach(mb=>{
      if(mb.dead)return;
      if(mb.linking){
        mb.linkT+=dt;
        // Fase 1 do elo (0-0.6s): convergem para ficar a uma distância fixa
        if(mb.linkT<0.6&&mb.linkPartner&&!mb.linkPartner.dead){
          const dx=mb.linkPartner.x-mb.x,dy=mb.linkPartner.y-mb.y,d=Math.hypot(dx,dy)||1;
          const targetD=140;
          const pull=(d-targetD)/d;
          mb.vx+=dx*pull*dt*3;mb.vy+=dy*pull*dt*3;
        }
        // Fase 2 do elo (0.6-2.0s): linha de energia ativa, dano em área
        if(mb.linkT>=0.6&&mb.linkT<2.0&&mb.linkPartner&&!mb.linkPartner.dead){
          const p1x=mb.x,p1y=mb.y,p2x=mb.linkPartner.x,p2y=mb.linkPartner.y;
          objects.forEach(o=>{
            if(o.dead||o._rffLinkHit)return;
            const ox=o.sx(),oy=o.sy();
            const dxL=p2x-p1x,dyL=p2y-p1y,lenL=Math.hypot(dxL,dyL)||1;
            const t3=Math.max(0,Math.min(1,((ox-p1x)*dxL+(oy-p1y)*dyL)/(lenL*lenL)));
            const px=p1x+dxL*t3,py=p1y+dyL*t3;
            if(Math.hypot(ox-px,oy-py)<o.sr()+14){
              o._rffLinkHit=true;
              if(o.hp!==undefined){o.hp=Math.max(0,o.hp-mb.atk*2);if(o.hp<=0)o.dead=true;}
              else if(Math.random()<0.25){o._invasionDead=true;o.dead=true;
                if(typeof spawnExplosion==='function')spawnExplosion(ox,oy,0.35,false);}
            }
          });
        }
        if(mb.linkT>=2.0){
          mb.linking=false;mb.linkPartner=null;mb.linkCd=6+Math.random()*3;
          objects.forEach(o=>{o._rffLinkHit=false;});
        }
      }
    });

    f.miniBosses.forEach(mb=>{
      if(mb.dead)return;
      mb.t+=dt;
      mb._spawnT+=dt;
      if(mb.flashT>0)mb.flashT-=dt;

      // ── Durante o elo de energia, o Guardião ignora perseguição normal
      // (já é tratado pelo laço dedicado do elo, acima) ──────────────────
      if(mb.linking)return;

      // ── Escolhe alvo para "devorar" (morder) periodicamente ──
      mb.biteCd-=dt;
      if(!mb.biteTarget&&mb.biteCd<=0){
        let best=null,bestD=Infinity;
        objects.forEach(o=>{
          if(o.dead)return;
          const dx=o.sx()-mb.x,dy=o.sy()-mb.y,d2=dx*dx+dy*dy;
          if(d2<bestD){bestD=d2;best=o;}
        });
        if(best){mb.biteTarget=best;mb.biteTimer=0;}
      }

      let moveTx=null,moveTy=null;
      if(mb.biteTarget){
        if(mb.biteTarget.dead){
          mb.biteTarget=null; mb.biteCd=2+Math.random()*3;
        } else {
          moveTx=mb.biteTarget.sx(); moveTy=mb.biteTarget.sy();
          const dx=moveTx-mb.x,dy=moveTy-mb.y,d=Math.hypot(dx,dy)||1;
          // Mordida: perto o bastante → devora (destrói) o astro
          const biteR=Math.max(mb.biteTarget.sr()*1.15,50);
          if(d<biteR){
            mb.biteTimer+=dt;
            if(mb.biteTimer>0.4){
              const bt=mb.biteTarget;
              if(bt.hp!==undefined){
                bt.hp=Math.max(0,bt.hp-mb.atk*3);
                if(bt.hp<=0)bt.dead=true;
              } else {
                bt._invasionDead=true;bt.dead=true;
              }
              if(typeof spawnExplosion==='function')spawnExplosion(mb.x,mb.y,0.5,false);
              showTooltip(`🦎 Guardião Antigo devorou ${bt.name||bt.type}!`);
              mb.biteTarget=null; mb.biteCd=2+Math.random()*3;
            }
          }
        }
      }
      if(!moveTx){
        // Sem alvo de mordida: perseguir astro mais próximo como ataque normal
        let target=null,bestD=Infinity;
        objects.forEach(o=>{
          if(o.dead)return;
          const dx=o.sx()-mb.x,dy=o.sy()-mb.y,d2=dx*dx+dy*dy;
          if(d2<bestD){bestD=d2;target=o;}
        });
        if(target){moveTx=target.sx();moveTy=target.sy();mb._atkTarget=target;}
      }

      if(moveTx!==null){
        const dx=moveTx-mb.x,dy=moveTy-mb.y,d=Math.hypot(dx,dy)||1;
        // Curva suave em direção ao alvo (rota suave, não instantânea)
        mb.vx+=(dx/d*mb.speed-mb.vx)*dt*2.2;
        mb.vy+=(dy/d*mb.speed-mb.vy)*dt*2.2;
      } else {
        mb.vx+=(Math.random()-.5)*mb.speed*dt;
        mb.vy+=(Math.random()-.5)*mb.speed*dt;
      }
      const spd=Math.hypot(mb.vx,mb.vy)||1;
      if(spd>mb.speed){mb.vx=mb.vx/spd*mb.speed;mb.vy=mb.vy/spd*mb.speed;}
      mb.x+=mb.vx*dt; mb.y+=mb.vy*dt;

      // Bounce nas bordas da arena
      if(mb.x<ar.x){mb.x=ar.x;mb.vx=Math.abs(mb.vx)*.5;}
      if(mb.x>ar.x+ar.w){mb.x=ar.x+ar.w;mb.vx=-Math.abs(mb.vx)*.5;}
      if(mb.y<ar.y){mb.y=ar.y;mb.vy=Math.abs(mb.vy)*.5;}
      if(mb.y>ar.y+ar.h){mb.y=ar.y+ar.h;mb.vy=-Math.abs(mb.vy)*.5;}

      // Guardião Antigo (Camaleão): _drawBossCamaleao espera camHeadAngle
      // atualizado externamente (o boss grande tem uma state machine
      // pause/move inteira pra isso). Versão simplificada aqui — só aponta
      // a cabeça na direção da velocidade atual, sem custo extra (spd já
      // foi calculado acima) — suficiente pro visual deixar de ficar
      // sempre travado no ângulo padrão (-90°).
      if(mb.form==='camaleao'&&spd>10) mb.camHeadAngle=Math.atan2(mb.vy,mb.vx);

      // Ataque normal (fora de mordida) a astros próximos
      mb._atkTimer=Math.max(0,mb._atkTimer-dt);
      if(mb._atkTarget&&!mb._atkTarget.dead&&mb._atkTimer<=0){
        const tsx=mb._atkTarget.sx(),tsy=mb._atkTarget.sy();
        const dx=tsx-mb.x,dy=tsy-mb.y,d=Math.hypot(dx,dy);
        const hitR=Math.max(mb._atkTarget.sr()*1.2,55);
        if(d<hitR){
          const t2=mb._atkTarget;
          if(t2.hp!==undefined){
            t2.hp=Math.max(0,t2.hp-mb.atk);
            if(t2.hp<=0)t2.dead=true;
          } else if(Math.random()<0.15){
            t2._invasionDead=true;t2.dead=true;
            if(typeof spawnExplosion==='function')spawnExplosion(tsx,tsy,0.5,false);
            showTooltip(`🦎 Guardião Antigo destruiu ${t2.name||t2.type}!`);
          }
          mb._atkTimer=0.7+Math.random()*1.0;
          mb.flashT=0.25;
        }
      }

      // Dano de astros ao mini-boss — tabela unificada (era cópia local).
      _rffApplyAstroDamage(mb,dt,.045,'_rffMbHit_',{explosionR:0.18});

      if(mb.hp<=0&&!mb.dead){
        mb.dead=true;
        // Mesmo pool global — cada Guardião morto desconta sua fatia
        // proporcional do bloco de HP da Fase 2.
        f.hp=Math.max(0,f.hp-RFF_P2_HP_PER_MINIBOSS);
        if(typeof spawnExplosion==='function')spawnExplosion(mb.x,mb.y,0.7,false);
      }
    });

    // ── Draw dos mini-bosses (camada acima do Leviatã) ────────────────
    // ── Desenho do elo de energia (linha entre os 2 Guardiões vinculados) ──
    f.miniBosses.forEach(mb=>{
      if(mb.dead||!mb.linking||!mb.linkPartner||mb.linkPartner.dead||mb.linkT<0.6)return;
      // Evita desenhar a linha duas vezes (uma por cada parceiro)
      if(mb._linkDrawn)return;
      const partner=mb.linkPartner;
      partner._linkDrawn=true;
      const pulse=0.6+0.4*Math.sin(f.t*10);
      ctx.save();
      ctx.globalAlpha=0.5*pulse;
      ctx.strokeStyle='#ff2266';ctx.lineWidth=10;
      ctx.beginPath();ctx.moveTo(mb.x,mb.y);ctx.lineTo(partner.x,partner.y);ctx.stroke();
      ctx.globalAlpha=0.9*pulse;
      ctx.strokeStyle='#ffccdd';ctx.lineWidth=3;
      ctx.beginPath();ctx.moveTo(mb.x,mb.y);ctx.lineTo(partner.x,partner.y);ctx.stroke();
      ctx.restore();
    });
    f.miniBosses.forEach(mb=>{mb._linkDrawn=false;});
    f.miniBosses.forEach(mb=>{if(!mb.dead)_drawRffMiniBoss(ctx,mb,f.t);});
    f.miniBosses=f.miniBosses.filter(mb=>!mb.dead);

    // ── Barra de HP mostra o HP GLOBAL real do Leviatã (bloco da Fase 2) ──
    const cfg2=RFF_P2_WAVE_CONFIG[f.p2Wave-1];
    {
      const pct=Math.max(0,f.hp/f.maxHP*100);
      const fillEl=document.getElementById('rept-boss-hp-fill');
      if(fillEl)fillEl.style.width=pct+'%';
      const subEl=document.getElementById('rept-boss-hp-subtitle');
      if(subEl&&cfg2)subEl.textContent=`☠️ ONDA ${f.p2Wave}/${RFF_P2_WAVE_CONFIG.length} — Guardiões: ${f.miniBosses.length}/${cfg2.count} — HP: ${Math.ceil(pct)}%`;
    }

    // ── Onda limpa → próxima onda ou fim da Fase 2 ──
    if(f.miniBosses.length===0&&f.p2WaveDelay>=999){
      if(f.p2Wave>=RFF_P2_WAVE_CONFIG.length){
        f.phase=3;
        f.p3TransT=0; f.p3TransDone=false;
        showTooltip('☠️ Todos os Guardiões Antigos destruídos! O LEVIATÃ FICA DESORIENTADO... 🌀');
        const phaseEl=document.getElementById('rept-boss-hp-phase');
        const subEl=document.getElementById('rept-boss-hp-subtitle');
        if(phaseEl)phaseEl.textContent='FASE 3';
        if(subEl)subEl.textContent='🌀 DESORIENTADO...';
        _startRffAudio(3);
        // Barra NÃO reseta — HP é global e contínuo entre fases.
        const flash=document.getElementById('reptilian-emergency-flash');
        if(flash){flash.style.opacity='1';setTimeout(()=>{flash.style.opacity='0';},700);}
      } else {
        f.p2Wave++;
        f.p2WaveDelay=2.4;
      }
    }
  }

  // ── Draw: mini-boss reaproveitando os desenhos originais (escala reduzida) ──
  // ══════════════════════════════════════════════════════════════════
  //  FASE 3 da Forma Final: LEVIATÃ ENLOUQUECIDO — finalmente vulnerável
  //  Transição: desorientado (🌀), presas se mexem e furam o próprio
  //  olho ciano, que racha e fica nervoso/inquieto, olhando desesperado.
  //  Depois: feixes azuis tipo Pulsar, laser hitkill com telegraph em
  //  astro aleatório, velocidade aumentada, mini-explosões nos trapézios.
  // ══════════════════════════════════════════════════════════════════
  const RFF_P3_TRANS_DUR=3.2;      // duração da transição desorientada
  const RFF_P3_EYE_PIERCE_T=1.6;   // instante (dentro da transição) em que a presa fura o olho

  function _rffTickPhase3(dt,ctx,f,ar,pair){
    // ── Morte do Leviatã ──
    if(f.dying){
      f.dyingT+=dt;
      const dg=Math.min(1,f.dyingT/5);

      // ── Fase final: flash branco + trapézios do corpo se afastando ──
      // Aos 4.2s de agonia, dispara o flash branco de vitória (elemento
      // dedicado, z-index 9990, acima de tudo) e "quebra" a cadeia em
      // fragmentos trapezoidais independentes que voam para longe do
      // centro e evaporam (fade-out), no lugar do desenho normal.
      const WHITE_T=4.2;
      if(f.dyingT>=WHITE_T && !f._whiteFlashDone){
        f._whiteFlashDone=true;
        const flash=document.getElementById('rff-death-flash');
        if(flash){flash.style.opacity='1';
          setTimeout(()=>{flash.style.opacity='0';},900);}
        // Snapshot dos fragmentos: um por segmento da cadeia, herdando
        // posição/ângulo/tamanho atuais e ganhando velocidade radial
        // (para fora, a partir do centro do Leviatã) + rotação própria.
        f._deathFrags=f.chain.map((s,i)=>{
          const dx=s.x-f.x, dy=s.y-f.y;
          const dist=Math.hypot(dx,dy)||1;
          const nx=dx/dist, ny=dy/dist;
          const speed=rand(60,190);
          return {
            x:s.x, y:s.y, a:s.a,
            r:Math.max(12,62-i*1.8),
            vx:nx*speed+rand(-30,30),
            vy:ny*speed+rand(-30,30),
            va:rand(-2.5,2.5),
            alpha:1
          };
        });
      }

      if(f._deathFrags){
        // ── Corpo já fragmentado: desenha os trapézios voando/evaporando ──
        const ft=f.dyingT-WHITE_T;
        ctx.save();
        f._deathFrags.forEach(fr=>{
          fr.x+=fr.vx*dt; fr.y+=fr.vy*dt;
          fr.vx*=0.985; fr.vy*=0.985;
          fr.a+=fr.va*dt;
          fr.alpha=Math.max(0,1-ft/1.3);
          if(fr.alpha<=0)return;
          const wBack=fr.r*1.30, wFront=fr.r*0.80, len=90;
          ctx.save();
          ctx.translate(fr.x,fr.y);
          ctx.rotate(fr.a);
          ctx.globalAlpha=fr.alpha;
          ctx.beginPath();
          ctx.moveTo(-len/2,-wBack);
          ctx.lineTo( len/2,-wFront);
          ctx.lineTo( len/2, wFront);
          ctx.lineTo(-len/2, wBack);
          ctx.closePath();
          ctx.fillStyle='#070000';
          ctx.fill();
          ctx.lineWidth=2;
          ctx.strokeStyle=`rgba(200,0,0,${fr.alpha})`;
          ctx.stroke();
          ctx.restore();
        });
        ctx.restore();
        if(Math.random()<0.5){
          f._deathFrags.forEach(fr=>{
            if(fr.alpha>0 && Math.random()<0.1)
              _fxParticles.push({x:fr.x,y:fr.y,
                vx:rand(-70,70),vy:rand(-70,70),r:rand(3,10),alpha:1,
                color:Math.random()<0.5?'#ff2200':'#00e5ff',life:0.7,maxLife:0.7});
          });
        }
      } else {
        // ── Antes do flash: agonia normal (glitch + faíscas na cadeia) ──
        if(Math.random()<dg*0.6){
          f.chain.forEach(s=>{
            if(Math.random()<0.15)
              _fxParticles.push({x:s.x+rand(-30,30),y:s.y+rand(-30,30),
                vx:rand(-70,70),vy:rand(-70,70),r:rand(3,10),alpha:1,
                color:Math.random()<0.5?'#ff2200':'#00e5ff',life:0.9,maxLife:0.9});
          });
        }
        f.glitch=dg;
        _drawReptFinalForm(ctx,f,ar,pair);
      }

      if(f.dyingT>=5.5){
        for(let i=0;i<80;i++){
          ctx.beginPath();ctx.arc(f.x+rand(-140,140),f.y+rand(-140,140),rand(5,30),0,Math.PI*2);
          ctx.fillStyle=`rgba(200,0,0,${Math.random()*0.9})`;ctx.fill();
        }
        showTooltip('💥 ANIQUILADOR DE GALÁXIAS DESTRUÍDO!');
        _stopRffAudio();
        _reptFinalForm=null;
        if(typeof _bossAchTrigger==='function')_bossAchTrigger('aniquilador_de_aniquiladores');
        // ── Fix: a morte do Quasord nunca disparava a vitória da invasão ──
        // (não havia condição de derrota do boss final). Agora encerra a
        // invasão Reptiliana como vitória assim que a animação de morte termina.
        _endInvasion(true);
        setTimeout(()=>{ if(typeof _startQuasordVictory==='function') _startQuasordVictory(); },1200);
      }
      return;
    }


    // ── Transição desorientada (Fase 2 → 3) ──────────────────────────
    if(!f.p3TransDone){
      f.p3TransT+=dt;
      f.fangTwitch=Math.min(1,f.p3TransT/1.0);
      if(f.p3TransT>=RFF_P3_EYE_PIERCE_T&&!f.eyeCracked){
        f.eyeCracked=true;
        if(typeof spawnExplosion==='function')spawnExplosion(f.x,f.y,0.25,false);
        showTooltip('👁️💥 O LEVIATÃ FUROU O PRÓPRIO OLHO!');
      }
      if(f.eyeCracked) f.eyeCrackAmt=Math.min(1,(f.p3TransT-RFF_P3_EYE_PIERCE_T)/0.6);
      if(f.p3TransT>=RFF_P3_TRANS_DUR){
        f.p3TransDone=true;
        f.speedMult=1.55;
        showTooltip('☠️👁️‍🗨️ O LEVIATÃ ENLOUQUECEU! AGORA ELE PODE SER FERIDO!');
        const phaseEl=document.getElementById('rept-boss-hp-phase');
        const subEl=document.getElementById('rept-boss-hp-subtitle');
        const fillEl=document.getElementById('rept-boss-hp-fill');
        if(phaseEl)phaseEl.textContent='FASE 3';
        if(subEl)subEl.textContent='👁️‍🗨️ ENLOUQUECIDO — VULNERÁVEL!';
        _startRffAudio(3);
        if(fillEl){fillEl.style.width=(f.hp/RFF_GLOBAL_MAX_HP*100)+'%';fillEl.className='phase3';}
        const flash=document.getElementById('reptilian-emergency-flash');
        if(flash){flash.style.opacity='1';setTimeout(()=>{flash.style.opacity='0';},700);}
      }
    }

    // ── Olhar desesperado: muda de alvo com frequência, rápido e nervoso ──
    if(f.eyeCracked){
      f.eyeLookTimer-=dt;
      if(f.eyeLookTimer<=0){
        f.eyeLookTimer=0.15+Math.random()*0.35;
        f.eyeLookTarget=rand(-0.9,0.9);
      }
      f.eyeLookAngle+=(f.eyeLookTarget-f.eyeLookAngle)*Math.min(1,dt*14);
    }

    if(!f.p3TransDone){
      // Barra de HP em tempo real durante a transição, como % do HP
      // GLOBAL (800k) — nunca reseta/recalcula por bloco de fase.
      const p3PctT=Math.max(0,Math.min(100,f.hp/RFF_GLOBAL_MAX_HP*100));
      const fillElT=document.getElementById('rept-boss-hp-fill');
      if(fillElT)fillElT.style.width=p3PctT+'%';
      _drawReptFinalForm(ctx,f,ar,pair); return;
    }

    // ══════════════════════════════════════════════════════════════
    //  Fase 3 ativa: feixes de pulsar + laser hitkill + dano ao boss
    // ══════════════════════════════════════════════════════════════
    const headAngle=f.chain[0].a||0;
    const eyeDist=(62)*1.9; // aproximação da posição do olho à frente da cabeça
    const eyeX=f.x+Math.cos(headAngle)*eyeDist, eyeY=f.y+Math.sin(headAngle)*eyeDist;

    // ── Feixes azuis tipo Pulsar: disparos radiais periódicos ──────────
    f.pulsarBeamTimer-=dt;
    if(f.pulsarBeamTimer<=0){
      f.pulsarBeamTimer=1.8;
      const nBeams=6;
      for(let i=0;i<nBeams;i++){
        const a=(i/nBeams)*Math.PI*2+Math.random()*0.3;
        f.pulsarBeams.push({x:f.x,y:f.y,angle:a,life:0.55,maxLife:0.55});
      }
      if(typeof spawnExplosion==='function')spawnExplosion(f.x,f.y,0.3,false);
    }
    f.pulsarBeams=f.pulsarBeams.filter(pb=>{
      pb.life-=dt;
      if(pb.life<=0)return false;
      // Dano aos astros atingidos pelo feixe (linha a partir do centro)
      const len=Math.max(ar.w,ar.h)*1.4;
      const ex=pb.x+Math.cos(pb.angle)*len, ey=pb.y+Math.sin(pb.angle)*len;
      objects.forEach(o=>{
        if(o.dead||o._rffBeamHit===pb)return;
        const ox=o.sx(),oy=o.sy();
        // Distância ponto-linha
        const dxL=ex-pb.x,dyL=ey-pb.y,lenL=Math.hypot(dxL,dyL)||1;
        const t2=Math.max(0,Math.min(1,((ox-pb.x)*dxL+(oy-pb.y)*dyL)/(lenL*lenL)));
        const px=pb.x+dxL*t2, py=pb.y+dyL*t2;
        const dperp=Math.hypot(ox-px,oy-py);
        if(dperp<Math.max(o.sr(),18)+10){
          o._rffBeamHit=pb;
          if(o.hp!==undefined){
            o.hp=Math.max(0,o.hp-f.maxHP*0.02);
            if(o.hp<=0)o.dead=true;
          } else if(Math.random()<0.4){
            o._invasionDead=true;o.dead=true;
            if(typeof spawnExplosion==='function')spawnExplosion(ox,oy,0.35,false);
            showTooltip(`🌀 Feixe do Leviatã destruiu ${o.name||o.type}!`);
          }
        }
      });
      return true;
    });

    // ── Laser hitkill: mira em astro aleatório com telegraph, depois dispara ──
    if(f.hitkillState==='idle'){
      f.hitkillTimer-=dt;
      if(f.hitkillTimer<=0){
        const alive=objects.filter(o=>!o.dead);
        if(alive.length>0){
          f.hitkillTarget=alive[Math.floor(Math.random()*alive.length)];
          f.hitkillState='aiming';
          f.hitkillAimT=0;
          showTooltip('👁️🔴 O LEVIATÃ ESTÁ MIRANDO...');
        } else {
          f.hitkillTimer=1.5;
        }
      }
    } else if(f.hitkillState==='aiming'){
      f.hitkillAimT+=dt;
      if(!f.hitkillTarget||f.hitkillTarget.dead){
        f.hitkillState='idle'; f.hitkillTimer=2+Math.random()*1.5; f.hitkillTarget=null;
      } else if(f.hitkillAimT>=1.1){ // telegraph de ~1.1s antes de disparar
        f.hitkillState='firing';
        f.hitkillAimT=0;
      }
    } else if(f.hitkillState==='firing'){
      f.hitkillAimT+=dt;
      if(f.hitkillAimT<=0.12&&f.hitkillTarget&&!f.hitkillTarget.dead){
        const tgt=f.hitkillTarget;
        const tsx=tgt.sx(),tsy=tgt.sy();
        tgt._invasionDead=true;tgt.dead=true;
        if(typeof spawnExplosion==='function')spawnExplosion(tsx,tsy,0.7,false);
        showTooltip(`☠️🔴 LASER HITKILL destruiu ${tgt.name||tgt.type} instantaneamente!`);
      }
      if(f.hitkillAimT>=0.35){
        f.hitkillState='idle';
        f.hitkillTimer=2.5+Math.random()*2;
        f.hitkillTarget=null;
      }
    }

    // ── Mini-explosões nos trapézios do corpo ──────────────────────────
    f.trapExplTimer-=dt;
    if(f.trapExplTimer<=0){
      f.trapExplTimer=0.35+Math.random()*0.4;
      const seg=f.chain[Math.floor(Math.random()*f.chain.length)];
      if(typeof spawnExplosion==='function')spawnExplosion(seg.x+rand(-20,20),seg.y+rand(-20,20),0.22,false);
      f.flashT=0.15; f.flashColor='#ff6622';
    }
    if(f.flashT>0)f.flashT-=dt;

    // ── Dano de astros ao Leviatã — finalmente vulnerável ───────────────
    _rffApplyAstroDamage(f,dt,.028,'_rffP3Hit_',{blackholePull:300,starChance:.008,starFrac:.008/.028,explosionR:0.18});

    // ── Barra de HP mostra % do HP GLOBAL (800k), nunca reseta por bloco ──
    const p3Pct=Math.max(0,Math.min(100,f.hp/RFF_GLOBAL_MAX_HP*100));
    const fillEl=document.getElementById('rept-boss-hp-fill');
    if(fillEl)fillEl.style.width=p3Pct+'%';
    const subEl=document.getElementById('rept-boss-hp-subtitle');
    if(subEl)subEl.textContent=`👁️‍🗨️ ENLOUQUECIDO — HP: ${Math.ceil(p3Pct)}%`;

    if(f.hp<=RFF_PHASE4_START_HP&&f.phase===3){
      f.phase=4;
      // HP GLOBAL — NÃO reseta. Continua descendo do mesmo pool de 800k.
      f.p4TransT=0; f.p4TransDone=false;
      f.pulsarBeams=[]; f.hitkillState='idle'; f.hitkillTarget=null;
      showTooltip('☠️⚡ FASE 4!');
      const phaseEl=document.getElementById('rept-boss-hp-phase');
      const subEl=document.getElementById('rept-boss-hp-subtitle');
      const fillEl=document.getElementById('rept-boss-hp-fill');
      if(phaseEl)phaseEl.textContent='FASE 4';
      if(subEl)subEl.textContent='⚡ FASE 4...';
      _startRffAudio(4);
      if(fillEl){fillEl.style.width=(f.hp/RFF_GLOBAL_MAX_HP*100)+'%';fillEl.className='phase3';}
      const flash=document.getElementById('reptilian-emergency-flash');
      if(flash){flash.style.opacity='1';setTimeout(()=>{flash.style.opacity='0';},900);}
      return;
    }

    // ── Draw: corpo + feixes + telegraph do laser ──────────────────────
    _drawReptFinalForm(ctx,f,ar,pair);
    _rffDrawPulsarBeams(ctx,f);
    _rffDrawHitkillTelegraph(ctx,f,eyeX,eyeY);
  }

  function _rffDrawPulsarBeams(ctx,f){
    f.pulsarBeams.forEach(pb=>{
      const a2=Math.max(0,pb.life/pb.maxLife);
      const len=Math.max(canvas.width,canvas.height)*1.4;
      const ex=pb.x+Math.cos(pb.angle)*len, ey=pb.y+Math.sin(pb.angle)*len;
      ctx.save();
      ctx.globalAlpha=a2*0.75;
      ctx.strokeStyle='#00e5ff';
      ctx.lineWidth=8*a2+2;
      ctx.beginPath();ctx.moveTo(pb.x,pb.y);ctx.lineTo(ex,ey);ctx.stroke();
      ctx.globalAlpha=a2*0.95;
      ctx.strokeStyle='#e0ffff';
      ctx.lineWidth=2.5*a2+1;
      ctx.beginPath();ctx.moveTo(pb.x,pb.y);ctx.lineTo(ex,ey);ctx.stroke();
      ctx.restore();
    });
  }

  // ── Feixe giratório contínuo da Fase 4 — visual roxo/magenta para se
  // diferenciar do ciano (pulsar, Fase 3) e do azul (mega-feixe, Fase 4). ──
  function _rffDrawSpinBeam(ctx,f){
    if(f.spinBeamAngle===undefined)return;
    const len=Math.max(canvas.width,canvas.height)*1.4;
    const bx=f.x,by=f.y,ba=f.spinBeamAngle;
    const ex=bx+Math.cos(ba)*len, ey=by+Math.sin(ba)*len;
    ctx.save();
    ctx.globalAlpha=0.5;
    ctx.strokeStyle='#cc22ff';
    ctx.lineWidth=14;
    ctx.beginPath();ctx.moveTo(bx,by);ctx.lineTo(ex,ey);ctx.stroke();
    ctx.globalAlpha=0.85;
    ctx.strokeStyle='#f0ccff';
    ctx.lineWidth=4;
    ctx.beginPath();ctx.moveTo(bx,by);ctx.lineTo(ex,ey);ctx.stroke();
    ctx.restore();
  }


  function _rffDrawHitkillTelegraph(ctx,f,eyeX,eyeY){
    if(f.hitkillState==='idle'||!f.hitkillTarget||f.hitkillTarget.dead)return;
    const tx=f.hitkillTarget.sx(), ty=f.hitkillTarget.sy();
    if(f.hitkillState==='aiming'){
      const p=Math.min(1,f.hitkillAimT/1.1);
      ctx.save();
      ctx.globalAlpha=0.35+0.4*p;
      ctx.strokeStyle='#ff2222';
      ctx.setLineDash([10,8]);
      ctx.lineWidth=1.6+p*2;
      ctx.beginPath();ctx.moveTo(eyeX,eyeY);ctx.lineTo(tx,ty);ctx.stroke();
      ctx.setLineDash([]);
      // Alvo piscando
      ctx.globalAlpha=0.5+0.5*Math.sin(p*30);
      ctx.strokeStyle='#ff0000';ctx.lineWidth=2;
      ctx.beginPath();ctx.arc(tx,ty,14+6*p,0,Math.PI*2);ctx.stroke();
      ctx.restore();
    } else if(f.hitkillState==='firing'&&f.hitkillAimT<0.35){
      const a2=1-Math.min(1,f.hitkillAimT/0.35);
      ctx.save();
      ctx.globalAlpha=a2;
      ctx.strokeStyle='#ff3300';
      ctx.lineWidth=6*a2+3;
      ctx.beginPath();ctx.moveTo(eyeX,eyeY);ctx.lineTo(tx,ty);ctx.stroke();
      ctx.globalAlpha=a2*0.9;
      ctx.strokeStyle='#ffffff';
      ctx.lineWidth=2*a2+1;
      ctx.beginPath();ctx.moveTo(eyeX,eyeY);ctx.lineTo(tx,ty);ctx.stroke();
      ctx.restore();
    }
  }

  // ══════════════════════════════════════════════════════════════════
  //  FASE 4 da Forma Final: LEVIATÃ DESPEDAÇADO E DESESPERADO
  //  HP renovado (maior que a Fase 3), continua vulnerável. Soma novas
  //  ameaças à Fase 3 (feixes/laser hitkill continuam via reaproveito):
  //   • Ordas raras de naves Alienígenas/Marcianas capturadas que
  //     tentam abduzir astros; astro abduzido persegue outro astro
  //     aleatório até colidir, explodindo ambos. Sem alvo -> nave volta.
  //   • Feixes gigantescos azuis sem mira fixa, disparados do olho.
  //   • Buraco negro artificial (mecânico, vermelho/azul) raro,
  //     no máximo 1 por vez, some após alguns segundos.
  // ══════════════════════════════════════════════════════════════════
  const RFF_P4_TRANS_DUR=2.6;
  const RFF_P4_SHIP_TYPES=[
    {cls:'alien',   color:'#22ffaa', speed:130},
    {cls:'marciano',color:'#ff6633', speed:105},
  ];

  function _rffTickPhase4(dt,ctx,f,ar,pair){
    // ── Reaproveita a morte já tratada em _rffTickPhase3 (via phase 4) ──
    if(f.dying){
      _rffTickPhase3(dt,ctx,f,ar,pair);
      return;
    }

    // ── Transição de colapso nervoso — NÃO é uma reconstrução: o Leviatã
    // fica mais quebrado, instável e desesperado, com o olho ainda mais
    // rachado e o olhar disparando entre alvos com violência. ──────────
    if(!f.p4TransDone){
      f.p4TransT+=dt;
      f.glitch=Math.max(f.glitch,Math.min(1,f.p4TransT/1.2));
      // Rachadura do olho se intensifica ainda mais nesta fase
      f.eyeCrackAmt=Math.min(1,0.7+f.p4TransT*0.25);
      if(Math.random()<0.5){
        const seg=f.chain[Math.floor(Math.random()*f.chain.length)];
        _fxParticles.push({x:seg.x+rand(-25,25),y:seg.y+rand(-25,25),
          vx:rand(-50,50),vy:rand(-50,50),r:rand(2,7),alpha:1,
          color:Math.random()<0.6?'#ff2244':'#3388ff',life:0.5,maxLife:0.5});
      }
      if(f.p4TransT>=RFF_P4_TRANS_DUR){
        f.p4TransDone=true;
        showTooltip('☠️⚡ O LEVIATÃ ESTÁ AINDA MAIS QUEBRADO E NERVOSO! FASE 4!');
        const phaseEl=document.getElementById('rept-boss-hp-phase');
        const subEl=document.getElementById('rept-boss-hp-subtitle');
        if(phaseEl)phaseEl.textContent='FASE 4';
        if(subEl)subEl.textContent='⚡ DESESPERADO — HP: 100%';
        _startRffAudio(4);
      }
      {
        const p4PctT=Math.max(0,Math.min(100,f.hp/RFF_GLOBAL_MAX_HP*100));
        const fillElT=document.getElementById('rept-boss-hp-fill');
        if(fillElT)fillElT.style.width=p4PctT+'%';
      }
      _drawReptFinalForm(ctx,f,ar,pair);
      return;
    }

    const headAngle=f.chain[0].a||0;
    const eyeDist=(62)*1.9;
    const eyeX=f.x+Math.cos(headAngle)*eyeDist, eyeY=f.y+Math.sin(headAngle)*eyeDist;

    // ── Estado permanentemente quebrado e nervoso na Fase 4: olho mais
    // rachado que na Fase 3, glitch residual constante, olhar mais errático ──
    f.eyeCrackAmt=1;
    f.glitch=Math.max(f.glitch,0.25);
    if(f.eyeCracked){
      f.eyeLookTimer-=dt;
      if(f.eyeLookTimer<=0){
        f.eyeLookTimer=0.08+Math.random()*0.18; // mais rápido/nervoso que na Fase 3
        f.eyeLookTarget=rand(-1.1,1.1);
      }
      f.eyeLookAngle+=(f.eyeLookTarget-f.eyeLookAngle)*Math.min(1,dt*20);
    }

    // ── NOVO na Fase 4: feixe giratório contínuo (lighthouse) — em vez de
    // repetir os 6 raios pulsados da Fase 3, um único feixe gira sem parar
    // ao redor do Leviatã, obrigando o jogador a prever a trajetória e
    // reposicionar astros a tempo, em vez de reagir a disparos pontuais.
    // O laser hitkill com telegraph fica exclusivo da Fase 3 — aqui ele
    // dava a sensação de "fase 3 de novo com um efeito a mais". ──────────
    f.spinBeamAngle=(f.spinBeamAngle||0)+dt*1.15;
    {
      const len=Math.max(ar.w,ar.h)*1.4;
      const bx=f.x,by=f.y,ba=f.spinBeamAngle;
      const ex=bx+Math.cos(ba)*len, ey=by+Math.sin(ba)*len;
      objects.forEach(o=>{
        if(o.dead)return;
        const ox=o.sx(),oy=o.sy();
        const dxL=ex-bx,dyL=ey-by,lenL=Math.hypot(dxL,dyL)||1;
        const t2=Math.max(0,Math.min(1,((ox-bx)*dxL+(oy-by)*dyL)/(lenL*lenL)));
        const px=bx+dxL*t2, py=by+dyL*t2;
        const dperp=Math.hypot(ox-px,oy-py);
        const key='_rffSpinHit_'+o.type;
        if(o[key]>0){o[key]-=dt;return;}
        if(dperp<Math.max(o.sr(),18)+14){
          o[key]=0.4; // pequeno cooldown por astro pra não derreter em 1 frame
          if(o.hp!==undefined){
            o.hp=Math.max(0,o.hp-f.maxHP*0.008);
            if(o.hp<=0)o.dead=true;
          } else if(Math.random()<0.12){
            o._invasionDead=true;o.dead=true;
            if(typeof spawnExplosion==='function')spawnExplosion(ox,oy,0.3,false);
          }
        }
      });
    }

    // ── Feixes GIGANTESCOS azuis sem mira fixa, disparados do olho ────
    f.megaBeamTimer-=dt;
    if(f.megaBeamTimer<=0){
      f.megaBeamTimer=6+Math.random()*3.5; // pouco frequente
      const a=rand(0,Math.PI*2);
      f.megaBeams.push({x:eyeX,y:eyeY,angle:a,life:1.1,maxLife:1.1});
      showTooltip('👁️🔵 O LEVIATÃ DISPARA UM FEIXE GIGANTE!');
      if(typeof spawnExplosion==='function')spawnExplosion(eyeX,eyeY,0.4,false);
    }
    f.megaBeams=f.megaBeams.filter(mgb=>{
      mgb.life-=dt;
      if(mgb.life<=0)return false;
      const len=Math.max(ar.w,ar.h)*1.6;
      const ex=mgb.x+Math.cos(mgb.angle)*len, ey=mgb.y+Math.sin(mgb.angle)*len;
      objects.forEach(o=>{
        if(o.dead||o._rffMegaHit===mgb)return;
        const ox=o.sx(),oy=o.sy();
        const dxL=ex-mgb.x,dyL=ey-mgb.y,lenL=Math.hypot(dxL,dyL)||1;
        const t2=Math.max(0,Math.min(1,((ox-mgb.x)*dxL+(oy-mgb.y)*dyL)/(lenL*lenL)));
        const px=mgb.x+dxL*t2, py=mgb.y+dyL*t2;
        const dperp=Math.hypot(ox-px,oy-py);
        if(dperp<Math.max(o.sr(),18)+26){ // feixe bem mais grosso que o pulsar
          o._rffMegaHit=mgb;
          if(o.hp!==undefined){
            o.hp=Math.max(0,o.hp-f.maxHP*0.05);
            if(o.hp<=0)o.dead=true;
          } else {
            o._invasionDead=true;o.dead=true;
            if(typeof spawnExplosion==='function')spawnExplosion(ox,oy,0.45,false);
          }
        }
      });
      return true;
    });

    // ── Ordas raras de naves capturadas (Alienígena/Marciana) ─────────
    f.shipWaveTimer-=dt;
    if(f.shipWaveTimer<=0&&f.ships.length===0){
      f.shipWaveTimer=14+Math.random()*10; // raro
      const n=2+Math.floor(Math.random()*3); // 2 a 4 naves por orda
      for(let i=0;i<n;i++){
        const st=RFF_P4_SHIP_TYPES[Math.floor(Math.random()*RFF_P4_SHIP_TYPES.length)];
        f.ships.push({
          x:f.x+rand(-40,40),y:f.y+rand(-40,40),
          cls:st.cls,color:st.color,speed:st.speed,
          state:'seeking', // seeking -> capturing -> chasing -> done
          target:null,carrying:null,t:0,
        });
      }
      showTooltip('🛸 Naves capturadas foram lançadas pelo Leviatã!');
    }
    f.ships.forEach(sh=>{
      sh.t+=dt;
      if(sh.state==='seeking'){
        if(!sh.target||sh.target.dead){
          const free=objects.filter(o=>!o.dead&&!o._rffAbducted);
          sh.target=free.length>0?free[Math.floor(Math.random()*free.length)]:null;
        }
        if(!sh.target){
          sh.state='returning';
        } else {
          const tx=sh.target.sx(),ty=sh.target.sy();
          const dx=tx-sh.x,dy=ty-sh.y,d=Math.hypot(dx,dy)||1;
          sh.x+=dx/d*sh.speed*dt; sh.y+=dy/d*sh.speed*dt;
          if(d<sh.target.sr()+20){
            sh.state='capturing'; sh.carrying=sh.target;
            sh.target._rffAbducted=true;
            showTooltip(`🛸 Nave abduziu ${sh.target.name||sh.target.type}!`);
          }
        }
      } else if(sh.state==='capturing'){
        if(!sh.carrying||sh.carrying.dead){ sh.state='returning'; }
        else {
          // Escolhe um alvo aleatório diferente do abduzido para perseguir
          const free=objects.filter(o=>!o.dead&&o!==sh.carrying);
          sh.chaseTarget=free.length>0?free[Math.floor(Math.random()*free.length)]:null;
          sh.state='chasing';
        }
      } else if(sh.state==='chasing'){
        const c=sh.carrying;
        if(!c||c.dead){ sh.state='returning'; }
        else if(!sh.chaseTarget||sh.chaseTarget.dead){
          const free=objects.filter(o=>!o.dead&&o!==c);
          sh.chaseTarget=free.length>0?free[Math.floor(Math.random()*free.length)]:null;
          if(!sh.chaseTarget) sh.state='returning';
        } else {
          const tx=sh.chaseTarget.sx(),ty=sh.chaseTarget.sy();
          const cx=c.sx(),cy=c.sy();
          const dx=tx-cx,dy=ty-cy,d=Math.hypot(dx,dy)||1;
          const mv=sh.speed*1.3*dt;
          if(c.x!==undefined&&c.y!==undefined){ c.x+=dx/d*mv; c.y+=dy/d*mv; }
          sh.x=c.sx(); sh.y=c.sy();
          if(d<c.sr()+sh.chaseTarget.sr()+14){
            const ex=c.sx(),ey=c.sy();
            c._invasionDead=true;c.dead=true;
            sh.chaseTarget._invasionDead=true;sh.chaseTarget.dead=true;
            if(typeof spawnExplosion==='function')spawnExplosion(ex,ey,0.55,false);
            showTooltip('💥 Astro desorientado colidiu e explodiu!');
            sh.state='done';
          }
        }
      } else if(sh.state==='returning'){
        const dx=f.x-sh.x,dy=f.y-sh.y,d=Math.hypot(dx,dy)||1;
        sh.x+=dx/d*sh.speed*1.5*dt; sh.y+=dy/d*sh.speed*1.5*dt;
        if(d<40) sh.state='done';
      }
    });
    f.ships=f.ships.filter(sh=>sh.state!=='done');

    // ── Buraco negro artificial: raro, no máx. 1 por vez, temporário ──
    f.artHoleTimer-=dt;
    if(!f.artHole&&f.artHoleTimer<=0){
      f.artHoleTimer=18+Math.random()*14; // bem raro
      const ax=ar.x+rand(ar.w*0.25,ar.w*0.75);
      const ay=ar.y+rand(ar.h*0.25,ar.h*0.75);
      f.artHole={x:ax,y:ay,life:5.5,maxLife:5.5,rot:0};
      showTooltip('🕳️ O Leviatã abriu um Buraco Negro Artificial!');
    }
    if(f.artHole){
      const ah=f.artHole;
      ah.life-=dt; ah.rot+=dt*1.6;
      if(ah.life<=0){
        f.artHole=null;
      } else {
        objects.forEach(o=>{
          if(o.dead)return;
          const ox=o.sx(),oy=o.sy();
          const dx=ah.x-ox,dy=ah.y-oy,d=Math.hypot(dx,dy)||1;
          const pullR=140;
          if(d<pullR){
            const pull=(1-d/pullR)*260;
            if(o.x!==undefined&&o.y!==undefined){
              o.x+=dx/d*pull*dt; o.y+=dy/d*pull*dt;
            }
            if(d<26){
              o._invasionDead=true;o.dead=true;
              if(typeof spawnExplosion==='function')spawnExplosion(ox,oy,0.4,false);
            }
          }
        });
      }
    }

    // ── Mini-explosões nos trapézios (reaproveita Fase 3) ──────────────
    f.trapExplTimer-=dt;
    if(f.trapExplTimer<=0){
      f.trapExplTimer=0.35+Math.random()*0.4;
      const seg=f.chain[Math.floor(Math.random()*f.chain.length)];
      if(typeof spawnExplosion==='function')spawnExplosion(seg.x+rand(-20,20),seg.y+rand(-20,20),0.22,false);
      f.flashT=0.15; f.flashColor='#3388ff';
    }
    if(f.flashT>0)f.flashT-=dt;

    // ── Dano de astros ao Leviatã (mesma tabela unificada da Fase 3) ────
    _rffApplyAstroDamage(f,dt,.028,'_rffP4Hit_',{blackholePull:300,starChance:.008,starFrac:.008/.028,explosionR:0.18});

    // ── Barra de HP mostra % do HP GLOBAL (800k), nunca reseta por bloco ──
    const p4Pct=Math.max(0,Math.min(100,f.hp/RFF_GLOBAL_MAX_HP*100));
    const fillEl=document.getElementById('rept-boss-hp-fill');
    if(fillEl)fillEl.style.width=p4Pct+'%';
    const subEl=document.getElementById('rept-boss-hp-subtitle');
    if(subEl)subEl.textContent=`⚡ DESESPERADO — HP: ${Math.ceil(p4Pct)}%`;

    if(f.hp<=RFF_PHASE5_START_HP&&f.phase===4&&!f.eyeFalling){
      // ── Olho racha até o limite e CAI fisicamente até a altura dos
      // dentes/mandíbula antes de explodir — ainda dentro da Fase 4,
      // só troca para a Fase 5 depois que a queda+explosão terminam. ──
      f.eyeFalling=true; f.eyeFallT=0;
      f.glitch=Math.max(f.glitch,0.5);
    }
    if(f.eyeFalling){
      f.eyeFallT+=dt;
      const FALL_DUR=1.15;   // tempo de queda até tocar nos dentes/presas
      const fallP=Math.min(1,f.eyeFallT/FALL_DUR);
      // Ease-in: começa devagar (perdendo sustentação) e acelera na queda
      f.eyeFallDrop=fallP*fallP;
      if(Math.random()<0.4){
        const headAngle=f.chain[0].a||0;
        const eyeDist=(62)*1.9*(1-f.eyeFallDrop*0.3); // acompanha o avanço do olho em direção aos dentes
        const eyeX=f.x+Math.cos(headAngle)*eyeDist, eyeY=f.y+Math.sin(headAngle)*eyeDist;
        _fxParticles.push({x:eyeX+rand(-6,6),y:eyeY+rand(-4,4),
          vx:rand(-15,15),vy:rand(10,30),r:rand(1,3),alpha:1,
          color:Math.random()<0.5?'#00e5ff':'#ff2222',life:0.4,maxLife:0.4});
      }
      if(fallP>=1&&!f.eyeGone){
        // ── Tocou nas presas/dentes: explode de vez ──
        f.eyeGone=true;
        const headAngle=f.chain[0].a||0;
        const eyeDist=(62)*1.9*0.7; // posição avançada, próxima às presas
        const eyeX=f.x+Math.cos(headAngle)*eyeDist, eyeY=f.y+Math.sin(headAngle)*eyeDist;
        if(typeof spawnExplosion==='function')spawnExplosion(eyeX,eyeY,0.4,false);
        for(let i=0;i<18;i++){
          _fxParticles.push({x:eyeX+rand(-12,12),y:eyeY+rand(-8,8),
            vx:rand(-70,70),vy:rand(-40,40),r:rand(2,6),alpha:1,
            color:Math.random()<0.5?'#00e5ff':'#ff2222',life:0.75,maxLife:0.75});
        }
      }
      if(fallP>=1&&f.eyeFallT>=FALL_DUR+0.3){
        // ── Pequena pausa após a explosão, depois troca de fato pra Fase 5 ──
        f.phase=5;
        f.eyeFalling=false;
        // HP GLOBAL — NÃO reseta. Continua descendo do mesmo pool de 800k.
        f.p5TransT=RFF_P5_TRANS_DUR; f.p5TransDone=true; // pula a queda duplicada da Fase 5
        _rffApplyPhase5AstroBuff();
        f.pulsarBeams=[]; f.megaBeams=[]; f.hitkillState='idle'; f.hitkillTarget=null;
        f.ships=[]; f.artHole=null;
        const phaseEl=document.getElementById('rept-boss-hp-phase');
        const subEl=document.getElementById('rept-boss-hp-subtitle');
        const fillEl=document.getElementById('rept-boss-hp-fill');
        if(phaseEl)phaseEl.textContent='FASE 5';
        const p5PctNow=Math.max(0,Math.min(100,f.hp/RFF_GLOBAL_MAX_HP*100));
        if(subEl)subEl.textContent=`⚡ DESESPERO EXTREMO — HP: ${Math.ceil(p5PctNow)}%`;
        _startRffAudio(5);
        if(fillEl){fillEl.style.width=p5PctNow+'%';fillEl.className='phase3';}
        const flash=document.getElementById('reptilian-emergency-flash');
        if(flash){flash.style.opacity='1';setTimeout(()=>{flash.style.opacity='0';},900);}
      }
      _drawReptFinalForm(ctx,f,ar,pair);
      return;
    }

    // ── Draw: corpo + feixe giratório + naves + buraco negro ───────────
    _drawReptFinalForm(ctx,f,ar,pair);
    _rffDrawSpinBeam(ctx,f);
    _rffDrawMegaBeams(ctx,f);
    _rffDrawArtHole(ctx,f);
    f.ships.forEach(sh=>_rffDrawShip(ctx,sh));
  }

  function _rffDrawMegaBeams(ctx,f){
    f.megaBeams.forEach(mgb=>{
      const a2=Math.max(0,mgb.life/mgb.maxLife);
      const len=Math.max(canvas.width,canvas.height)*1.6;
      const ex=mgb.x+Math.cos(mgb.angle)*len, ey=mgb.y+Math.sin(mgb.angle)*len;
      ctx.save();
      ctx.globalAlpha=a2*0.55;
      ctx.strokeStyle='#0055ff';
      ctx.lineWidth=34*a2+8;
      ctx.beginPath();ctx.moveTo(mgb.x,mgb.y);ctx.lineTo(ex,ey);ctx.stroke();
      ctx.globalAlpha=a2*0.8;
      ctx.strokeStyle='#3399ff';
      ctx.lineWidth=16*a2+4;
      ctx.beginPath();ctx.moveTo(mgb.x,mgb.y);ctx.lineTo(ex,ey);ctx.stroke();
      ctx.globalAlpha=a2*0.95;
      ctx.strokeStyle='#cceeff';
      ctx.lineWidth=5*a2+1.5;
      ctx.beginPath();ctx.moveTo(mgb.x,mgb.y);ctx.lineTo(ex,ey);ctx.stroke();
      ctx.restore();
    });
  }

  function _rffDrawArtHole(ctx,f){
    const ah=f.artHole; if(!ah)return;
    const a2=Math.min(1,ah.life/1.0<1?ah.life/1.0:1)*Math.min(1,(ah.maxLife-ah.life)<0.6?(ah.maxLife-ah.life)/0.6:1);
    const alpha=Math.max(0.15,a2);
    ctx.save();
    ctx.translate(ah.x,ah.y);
    // Núcleo escuro
    const core=ctx.createRadialGradient(0,0,2,0,0,34);
    core.addColorStop(0,'#000000');
    core.addColorStop(0.55,'rgba(20,0,0,0.9)');
    core.addColorStop(1,'transparent');
    ctx.globalAlpha=alpha;
    ctx.beginPath();ctx.arc(0,0,34,0,Math.PI*2);ctx.fillStyle=core;ctx.fill();
    // Anéis metálicos girando (visual mecânico/artificial, não orgânico)
    for(let i=0;i<3;i++){
      ctx.save();
      ctx.rotate(ah.rot*(i%2===0?1:-1)*(1+i*0.3));
      ctx.beginPath();
      ctx.ellipse(0,0,44+i*14,14+i*4,0,0,Math.PI*2);
      ctx.strokeStyle=i%2===0?'#ff2244':'#2288ff';
      ctx.lineWidth=2.2;
      ctx.globalAlpha=alpha*0.8;
      ctx.stroke();
      // Dentes/segmentos no anel (aspecto mecânico)
      for(let s=0;s<8;s++){
        const sa=s/8*Math.PI*2;
        const rx=Math.cos(sa)*(44+i*14), ry=Math.sin(sa)*(14+i*4);
        ctx.beginPath();ctx.arc(rx,ry,2.2,0,Math.PI*2);
        ctx.fillStyle=i%2===0?'#ff2244':'#2288ff';ctx.fill();
      }
      ctx.restore();
    }
    ctx.restore();
  }

  function _rffDrawShip(ctx,sh){
    ctx.save();
    ctx.translate(sh.x,sh.y);
    const hover=Math.sin(sh.t*4)*2;
    ctx.translate(0,hover);
    // Disco/corpo
    ctx.beginPath();ctx.ellipse(0,0,13,5,0,0,Math.PI*2);
    ctx.fillStyle='#1a1a22';ctx.fill();
    ctx.strokeStyle=sh.color;ctx.lineWidth=1.4;ctx.stroke();
    // Cúpula
    ctx.beginPath();ctx.arc(0,-3,5,Math.PI,0);
    ctx.fillStyle=`${sh.color}55`;ctx.fill();
    ctx.strokeStyle=sh.color;ctx.lineWidth=1;ctx.stroke();
    // Luz inferior pulsante
    ctx.globalAlpha=0.5+0.4*Math.sin(sh.t*8);
    ctx.beginPath();ctx.arc(0,4,2.4,0,Math.PI*2);
    ctx.fillStyle=sh.color;ctx.fill();
    ctx.globalAlpha=1;
    ctx.restore();
    // Feixe de captura, se estiver carregando um astro
    if(sh.state==='chasing'&&sh.carrying&&!sh.carrying.dead){
      const cx=sh.carrying.sx(),cy=sh.carrying.sy();
      ctx.save();
      ctx.globalAlpha=0.4;
      ctx.strokeStyle=sh.color;
      ctx.lineWidth=2;
      ctx.setLineDash([4,3]);
      ctx.beginPath();ctx.moveTo(sh.x,sh.y+hover);ctx.lineTo(cx,cy);ctx.stroke();
      ctx.setLineDash([]);
      ctx.restore();
    }
  }

  // ══════════════════════════════════════════════════════════════════
  //  FASE 5 da Forma Final: DESESPERO EXTREMO
  //  Muito mais rápida que a Fase 4. Olho racha ainda mais até cair nos
  //  dentes por falta de energia e sumir permanentemente (dor real, sem
  //  reconstrução). Trapézios pulsam vermelho vazando faíscas (visual,
  //  já tratado em _drawReptFinalForm). Jatos laser colossais pela boca,
  //  serras circulares ao redor do corpo, investidas desesperadas
  //  borradas, garra que agarra e esmaga astros na hora, singularidades.
  //  Limite de astros triplica e cooldown reduz 40% ao entrar na fase.
  // ══════════════════════════════════════════════════════════════════
  const RFF_P5_TRANS_DUR=2.2;
  const RFF_P5_EYE_FALL_START=0.9; // instante em que o olho começa a cair por falta de energia
  const RFF_P5_EYE_FALL_DUR=0.85;  // duração da queda até tocar os dentes

  function _rffApplyPhase5AstroBuff(){
    if(!window._reptilianAstroCaps||window._rffP5BuffApplied)return;
    window._rffP5BuffApplied=true;
    Object.keys(window._reptilianAstroCaps).forEach(t=>{
      const cap=window._reptilianAstroCaps[t];
      cap.max=Math.max(1,Math.round(cap.max*3));
      cap.cooldownTime=Math.max(0.5,cap.cooldownTime*0.6);
      if(typeof _refreshReptilianAstroCounterUI==='function')
        _refreshReptilianAstroCounterUI(t,cap);
    });
    setTimeout(()=>showTooltip('⬆️ FASE 5: limite de astros TRIPLICADO e cooldown -40%!'),1400);
  }

  function _rffTickPhase5(dt,ctx,f,ar,pair){
    // ── Morte definitiva do Leviatã (reaproveita a lógica de _rffTickPhase3) ──
    if(f.dying){
      _rffTickPhase3(dt,ctx,f,ar,pair);
      return;
    }

    // ── Transição: o olho já rachado cai nos dentes por falta de
    // energia — ele sente a dor — e some permanentemente. ─────────────
    if(!f.p5TransDone){
      f.p5TransT+=dt;
      f.eyeCrackAmt=1;
      f.glitch=Math.max(f.glitch,0.4);
      // ── Queda física do olho até a altura dos dentes (mesmo padrão
      // usado na transição Fase 4→5 natural — antes só explodia parado). ──
      if(f.p5TransT>=RFF_P5_EYE_FALL_START&&!f.eyeGone){
        const fallP=Math.min(1,(f.p5TransT-RFF_P5_EYE_FALL_START)/RFF_P5_EYE_FALL_DUR);
        f.eyeFallDrop=fallP*fallP; // ease-in, mesmo formato da queda da Fase 4
        if(Math.random()<0.4){
          const headAngle=f.chain[0].a||0;
          const eyeDist=(62)*1.9*(1-f.eyeFallDrop*0.3);
          const eyeX=f.x+Math.cos(headAngle)*eyeDist, eyeY=f.y+Math.sin(headAngle)*eyeDist;
          _fxParticles.push({x:eyeX+rand(-6,6),y:eyeY+rand(-4,4),
            vx:rand(-15,15),vy:rand(10,30),r:rand(1,3),alpha:1,
            color:Math.random()<0.5?'#00e5ff':'#ff2222',life:0.4,maxLife:0.4});
        }
        if(fallP>=1){
          f.eyeGone=true;
          const headAngle=f.chain[0].a||0;
          const eyeDist=(62)*1.9*0.7;
          const eyeX=f.x+Math.cos(headAngle)*eyeDist, eyeY=f.y+Math.sin(headAngle)*eyeDist;
          if(typeof spawnExplosion==='function')spawnExplosion(eyeX,eyeY,0.35,false);
          for(let i=0;i<14;i++){
            _fxParticles.push({x:eyeX+rand(-10,10),y:eyeY+rand(-10,10),
              vx:rand(-60,60),vy:rand(20,90),r:rand(2,5),alpha:1,
              color:Math.random()<0.5?'#00e5ff':'#ff2222',life:0.7,maxLife:0.7});
          }
        }
      }
      if(f.p5TransT>=RFF_P5_TRANS_DUR){
        f.p5TransDone=true;
        _rffApplyPhase5AstroBuff();
        const phaseEl=document.getElementById('rept-boss-hp-phase');
        const subEl=document.getElementById('rept-boss-hp-subtitle');
        if(phaseEl)phaseEl.textContent='FASE 5';
        if(subEl)subEl.textContent=`⚡ DESESPERO EXTREMO — HP: 100%`;
        _startRffAudio(5);
      }
      {
        const p5PctT=Math.max(0,Math.min(100,f.hp/RFF_GLOBAL_MAX_HP*100));
        const fillElT=document.getElementById('rept-boss-hp-fill');
        if(fillElT)fillElT.style.width=p5PctT+'%';
      }
      _drawReptFinalForm(ctx,f,ar,pair);
      return;
    }

    const headAngle=f.chain[0].a||0;
    const mouthDist=62*1.5;
    const mouthX=f.x+Math.cos(headAngle)*mouthDist, mouthY=f.y+Math.sin(headAngle)*mouthDist;

    // ── Jatos laser colossais pela boca — sem mira, disparados à frente ──
    f.jetTimer-=dt;
    if(f.jetTimer<=0){
      f.jetTimer=3.2+Math.random()*2;
      f.jets.push({x:mouthX,y:mouthY,angle:headAngle+rand(-0.3,0.3),life:0.9,maxLife:0.9});
      if(typeof spawnExplosion==='function')spawnExplosion(mouthX,mouthY,0.45,false);
    }
    f.jets=f.jets.filter(jt=>{
      jt.life-=dt;
      if(jt.life<=0)return false;
      const len=Math.max(ar.w,ar.h)*1.6;
      const ex=jt.x+Math.cos(jt.angle)*len, ey=jt.y+Math.sin(jt.angle)*len;
      objects.forEach(o=>{
        if(o.dead||o._rffJetHit===jt)return;
        const ox=o.sx(),oy=o.sy();
        const dxL=ex-jt.x,dyL=ey-jt.y,lenL=Math.hypot(dxL,dyL)||1;
        const t2=Math.max(0,Math.min(1,((ox-jt.x)*dxL+(oy-jt.y)*dyL)/(lenL*lenL)));
        const px=jt.x+dxL*t2, py=jt.y+dyL*t2;
        const dperp=Math.hypot(ox-px,oy-py);
        if(dperp<Math.max(o.sr(),18)+32){
          o._rffJetHit=jt;
          if(o.hp!==undefined){
            o.hp=Math.max(0,o.hp-f.maxHP*0.06);
            if(o.hp<=0)o.dead=true;
          } else {
            o._invasionDead=true;o.dead=true;
            if(typeof spawnExplosion==='function')spawnExplosion(ox,oy,0.5,false);
          }
        }
      });
      return true;
    });

    // ── Serras circulares ao redor do corpo ────────────────────────────
    f.sawSpawnTimer-=dt;
    if(f.sawSpawnTimer<=0&&f.saws.length<4){
      f.sawSpawnTimer=2.5+Math.random()*1.5;
      f.saws.push({orbitIdx:Math.floor(Math.random()*f.chain.length),
        orbitDist:60+Math.random()*30,ang:rand(0,Math.PI*2),spin:0,life:8});
    }
    f.saws=f.saws.filter(sw=>{
      sw.life-=dt;
      if(sw.life<=0)return false;
      sw.ang+=dt*2.4;
      sw.spin+=dt*18;
      const seg=f.chain[Math.min(sw.orbitIdx,f.chain.length-1)];
      sw.x=seg.x+Math.cos(sw.ang)*sw.orbitDist;
      sw.y=seg.y+Math.sin(sw.ang)*sw.orbitDist;
      objects.forEach(o=>{
        if(o.dead)return;
        const ox=o.sx(),oy=o.sy(),osr=o.sr();
        const d=Math.hypot(ox-sw.x,oy-sw.y);
        if(d<osr+16){
          if(o.hp!==undefined){
            o.hp=Math.max(0,o.hp-f.maxHP*0.01*dt*10);
            if(o.hp<=0)o.dead=true;
          } else if(Math.random()<0.5){
            o._invasionDead=true;o.dead=true;
            if(typeof spawnExplosion==='function')spawnExplosion(ox,oy,0.3,false);
          }
        }
      });
      return true;
    });

    // ── Investidas desesperadas: dash rápido borrado, na direção que
    // ele já está seguindo (não trava — continua o movimento em curso) ──
    if(f.dashState==='idle'){
      f.dashTimer-=dt;
      if(f.dashTimer<=0){
        f.dashTimer=9+Math.random()*5; // bem menos frequente
        f.dashState='charging';
        f.dashT=0;
        // Direção da investida = ângulo de movimento atual do Leviatã
        f.dashTargetAngle=Math.atan2(f.vy,f.vx);
      }
    } else if(f.dashState==='charging'){
      f.dashT+=dt;
      if(f.dashT>=0.35){ f.dashState='dashing'; f.dashT=0; f.trail=[]; }
    } else if(f.dashState==='dashing'){
      f.dashT+=dt;
      const DASH_SPD=900;
      f.vx=Math.cos(f.dashTargetAngle)*DASH_SPD;
      f.vy=Math.sin(f.dashTargetAngle)*DASH_SPD;
      f.trail.push({x:f.x,y:f.y,a:1});
      if(f.trail.length>10)f.trail.shift();
      objects.forEach(o=>{
        if(o.dead)return;
        const ox=o.sx(),oy=o.sy(),osr=o.sr();
        const d=Math.hypot(ox-f.x,oy-f.y);
        if(d<osr+70){
          if(o.hp!==undefined){
            o.hp=Math.max(0,o.hp-f.maxHP*0.02);
            if(o.hp<=0)o.dead=true;
          } else if(Math.random()<0.35){
            o._invasionDead=true;o.dead=true;
            if(typeof spawnExplosion==='function')spawnExplosion(ox,oy,0.35,false);
          }
        }
      });
      if(f.dashT>=0.45){ f.dashState='idle'; f.trail=[]; }
    }

    // ── Garra: agarra um astro e o esmaga na hora ───────────────────────
    if(f.grabState==='idle'){
      f.grabTimer-=dt;
      if(f.grabTimer<=0){
        const alive=objects.filter(o=>!o.dead);
        if(alive.length>0){
          f.grabTarget=alive[Math.floor(Math.random()*alive.length)];
          f.grabState='reaching';
          f.grabT=0;
        } else {
          f.grabTimer=1.5;
        }
      }
    } else if(f.grabState==='reaching'){
      f.grabT+=dt;
      if(!f.grabTarget||f.grabTarget.dead){
        f.grabState='idle'; f.grabTimer=3+Math.random()*2; f.grabTarget=null;
      } else if(f.grabT>=0.8){
        const tgt=f.grabTarget;
        const tsx=tgt.sx(),tsy=tgt.sy();
        tgt._invasionDead=true;tgt.dead=true;
        if(typeof spawnExplosion==='function')spawnExplosion(tsx,tsy,0.6,false);
        f.grabState='idle';
        f.grabTimer=3.5+Math.random()*2.5;
        f.grabTarget=null;
      }
    }

    // ── Singularidade artificial (reaproveita visual do buraco negro
    // artificial da Fase 4, um pouco mais intensa) ─────────────────────
    f.singularityTimer-=dt;
    if(!f.singularity&&f.singularityTimer<=0){
      f.singularityTimer=14+Math.random()*10;
      const sx2=ar.x+rand(ar.w*0.25,ar.w*0.75);
      const sy2=ar.y+rand(ar.h*0.25,ar.h*0.75);
      f.singularity={x:sx2,y:sy2,life:6,maxLife:6,rot:0};
    }
    if(f.singularity){
      const sg=f.singularity;
      sg.life-=dt; sg.rot+=dt*2.0;
      if(sg.life<=0){
        f.singularity=null;
      } else {
        objects.forEach(o=>{
          if(o.dead)return;
          const ox=o.sx(),oy=o.sy();
          const dx=sg.x-ox,dy=sg.y-oy,d=Math.hypot(dx,dy)||1;
          const pullR=160;
          if(d<pullR){
            const pull=(1-d/pullR)*320;
            if(o.x!==undefined&&o.y!==undefined){
              o.x+=dx/d*pull*dt; o.y+=dy/d*pull*dt;
            }
            if(d<28){
              o._invasionDead=true;o.dead=true;
              if(typeof spawnExplosion==='function')spawnExplosion(ox,oy,0.4,false);
            }
          }
        });
      }
    }

    // ── Mini-explosões nos trapézios ────────────────────────────────────
    f.trapExplTimer-=dt;
    if(f.trapExplTimer<=0){
      f.trapExplTimer=0.25+Math.random()*0.3;
      const seg=f.chain[Math.floor(Math.random()*f.chain.length)];
      if(typeof spawnExplosion==='function')spawnExplosion(seg.x+rand(-20,20),seg.y+rand(-20,20),0.22,false);
      f.flashT=0.15; f.flashColor='#ff2222';
    }
    if(f.flashT>0)f.flashT-=dt;

    // ── Dano de astros ao Leviatã (mesma tabela unificada) ──────────────
    _rffApplyAstroDamage(f,dt,.028,'_rffP5Hit_',{blackholePull:300,starChance:.008,starFrac:.008/.028,explosionR:0.18});

    // ── Barra de HP mostra % do HP GLOBAL (800k), nunca reseta por bloco ──
    const p5Pct=Math.max(0,Math.min(100,f.hp/RFF_GLOBAL_MAX_HP*100));
    const fillEl=document.getElementById('rept-boss-hp-fill');
    if(fillEl)fillEl.style.width=p5Pct+'%';
    const subEl=document.getElementById('rept-boss-hp-subtitle');
    if(subEl)subEl.textContent=`⚡ DESESPERO EXTREMO — HP: ${Math.ceil(p5Pct)}%`;

    if(f.hp<=0&&!f.dying){f.dying=true;f.dyingT=0;showTooltip('💥 O LEVIATÃ FOI FINALMENTE DESTRUÍDO!');}

    // ── Draw ─────────────────────────────────────────────────────────
    _drawReptFinalForm(ctx,f,ar,pair);
    _rffDrawJets(ctx,f);
    _rffDrawSaws(ctx,f);
    _rffDrawDashTrail(ctx,f);
    _rffDrawSingularity(ctx,f);
  }

  function _rffDrawJets(ctx,f){
    f.jets.forEach(jt=>{
      const a2=Math.max(0,jt.life/jt.maxLife);
      const len=Math.max(canvas.width,canvas.height)*1.6;
      const ex=jt.x+Math.cos(jt.angle)*len, ey=jt.y+Math.sin(jt.angle)*len;
      ctx.save();
      ctx.globalAlpha=a2*0.6;
      ctx.strokeStyle='#ff5500';
      ctx.lineWidth=44*a2+10;
      ctx.beginPath();ctx.moveTo(jt.x,jt.y);ctx.lineTo(ex,ey);ctx.stroke();
      ctx.globalAlpha=a2*0.85;
      ctx.strokeStyle='#ffcc33';
      ctx.lineWidth=20*a2+5;
      ctx.beginPath();ctx.moveTo(jt.x,jt.y);ctx.lineTo(ex,ey);ctx.stroke();
      ctx.globalAlpha=a2*0.95;
      ctx.strokeStyle='#ffffee';
      ctx.lineWidth=6*a2+2;
      ctx.beginPath();ctx.moveTo(jt.x,jt.y);ctx.lineTo(ex,ey);ctx.stroke();
      ctx.restore();
    });
  }

  function _rffDrawSaws(ctx,f){
    f.saws.forEach(sw=>{
      if(sw.x===undefined)return;
      ctx.save();
      ctx.translate(sw.x,sw.y);
      ctx.rotate(sw.spin);
      const R=16;
      ctx.beginPath();
      for(let i=0;i<12;i++){
        const a=i/12*Math.PI*2;
        const rr=i%2===0?R:R*0.65;
        const px=Math.cos(a)*rr, py=Math.sin(a)*rr;
        if(i===0)ctx.moveTo(px,py); else ctx.lineTo(px,py);
      }
      ctx.closePath();
      ctx.fillStyle='#2a2a2e';ctx.fill();
      ctx.strokeStyle='#cccccc';ctx.lineWidth=1.6;ctx.stroke();
      ctx.beginPath();ctx.arc(0,0,4,0,Math.PI*2);
      ctx.fillStyle='#ff3300';ctx.fill();
      ctx.restore();
    });
  }

  function _rffDrawDashTrail(ctx,f){
    if(f.dashState==='charging'){
      const p=Math.min(1,f.dashT/0.5);
      ctx.save();
      ctx.globalAlpha=0.3+0.4*p;
      ctx.strokeStyle='#ff3300';
      ctx.lineWidth=3;
      const len=120*p;
      ctx.beginPath();
      ctx.moveTo(f.x,f.y);
      ctx.lineTo(f.x-Math.cos(f.dashTargetAngle)*len,f.y-Math.sin(f.dashTargetAngle)*len);
      ctx.stroke();
      ctx.restore();
    } else if(f.dashState==='dashing'&&f.trail.length>1){
      ctx.save();
      f.trail.forEach((tp,i)=>{
        const a2=(i/f.trail.length)*0.5;
        ctx.globalAlpha=a2;
        ctx.beginPath();ctx.arc(tp.x,tp.y,50,0,Math.PI*2);
        ctx.fillStyle='#ff4400';ctx.fill();
      });
      ctx.restore();
    }
  }

  function _rffDrawSingularity(ctx,f){
    const sg=f.singularity; if(!sg)return;
    ctx.save();
    ctx.translate(sg.x,sg.y);
    const core=ctx.createRadialGradient(0,0,2,0,0,40);
    core.addColorStop(0,'#000000');
    core.addColorStop(0.55,'rgba(30,0,0,0.9)');
    core.addColorStop(1,'transparent');
    ctx.beginPath();ctx.arc(0,0,40,0,Math.PI*2);ctx.fillStyle=core;ctx.fill();
    for(let i=0;i<3;i++){
      ctx.save();
      ctx.rotate(sg.rot*(i%2===0?1:-1)*(1+i*0.35));
      ctx.beginPath();
      ctx.ellipse(0,0,52+i*16,16+i*5,0,0,Math.PI*2);
      ctx.strokeStyle=i%2===0?'#ff2244':'#2288ff';
      ctx.lineWidth=2.4;
      ctx.globalAlpha=0.85;
      ctx.stroke();
      for(let s=0;s<9;s++){
        const sa=s/9*Math.PI*2;
        const rx=Math.cos(sa)*(52+i*16), ry=Math.sin(sa)*(16+i*5);
        ctx.beginPath();ctx.arc(rx,ry,2.4,0,Math.PI*2);
        ctx.fillStyle=i%2===0?'#ff2244':'#2288ff';ctx.fill();
      }
      ctx.restore();
    }
    ctx.restore();
  }

  // Canvas offscreen reutilizado para isolar o tint vermelho do mini-boss —
  // evita que 'source-atop' pinte por cima do Quasord (Leviatã) já desenhado
  // no canvas principal, já que essa operação afeta TODOS os pixels não-
  // transparentes do canvas em que é aplicada, não só os do mini-boss.
  let _rffMbTintCvs=null,_rffMbTintCtx=null;
  function _drawRffMiniBoss(ctx,mb,t){
    const boxR=60*mb.scale;
    const pad=boxR*1.3; // margem extra pro contorno/glow não cortarem
    const size=Math.ceil(pad*2);
    if(!_rffMbTintCvs){
      _rffMbTintCvs=document.createElement('canvas');
      _rffMbTintCtx=_rffMbTintCvs.getContext('2d');
    }
    if(_rffMbTintCvs.width!==size||_rffMbTintCvs.height!==size){
      _rffMbTintCvs.width=size;_rffMbTintCvs.height=size;
    }
    const oc=_rffMbTintCtx;
    oc.clearRect(0,0,size,size);
    // Desenha o mini-boss no offscreen, deslocado para que (mb.x,mb.y) caia
    // no centro do canvas pequeno (mesma matemática, só troca a origem).
    const dx=pad-mb.x, dy=pad-mb.y;
    oc.save();
    oc.translate(dx,dy);
    oc.save();
    oc.translate(mb.x,mb.y);
    oc.scale(mb.scale,mb.scale);
    oc.translate(-mb.x,-mb.y);
    if(mb.form==='serpente') _drawBossSerpente(oc,mb,t);
    else if(mb.form==='camaleao') _drawBossCamaleao(oc,mb,t);
    else if(mb.form==='dragao') _drawBossDragao(oc,mb,t);
    oc.restore();

    // Tint vermelho vivo: os desenhos originais dos bosses usam paleta
    // escura que, em escala reduzida (Guardião Antigo), fica quase
    // invisível contra o fundo do espaço. 'source-atop' pinta só os
    // pixels já desenhados (silhueta) DENTRO DESTE CANVAS ISOLADO —
    // não pode mais vazar sobre o Quasord.
    oc.save();
    oc.globalCompositeOperation='source-atop';
    oc.globalAlpha=0.55;
    oc.fillStyle='#ff1a1a';
    oc.fillRect(mb.x-boxR,mb.y-boxR,boxR*2,boxR*2);
    oc.restore();
    oc.restore();

    // Cola o resultado (corpo + tint, já isolados) no canvas principal.
    ctx.drawImage(_rffMbTintCvs,mb.x-pad,mb.y-pad);

    // Contorno vermelho vivo extra para reforçar leitura à distância
    ctx.save();
    ctx.globalAlpha=0.9;
    ctx.strokeStyle='#ff3333';
    ctx.lineWidth=2.5;
    ctx.beginPath();ctx.arc(mb.x,mb.y,boxR*0.7,0,Math.PI*2);ctx.stroke();
    ctx.restore();

    // Barra de HP mini acima do mini-boss (em coordenadas de mundo, sem escala)
    const hpPct=Math.max(0,mb.hp/mb.maxHP);
    ctx.save();
    ctx.globalAlpha=0.9;
    ctx.fillStyle='#220000';ctx.fillRect(mb.x-22,mb.y-46,44,4);
    ctx.fillStyle=hpPct>0.5?'#33ff55':hpPct>0.2?'#ffcc33':'#ff3322';
    ctx.fillRect(mb.x-22,mb.y-46,44*hpPct,4);
    ctx.globalAlpha=1;
    ctx.restore();
  }

    function _drawReptFinalForm(ctx,f,ar,pair){
    const t=f.t;
    const chain=f.chain;
    const N=chain.length;

    // ── Duas arenas alternantes: grande (longe) e pequena (perto) ─────
    // Arena ATIVA desenhada em destaque; a outra, sutil/tracejada fraca.
    // Tamanho real, sem escala — o boss PODE sair da área visível da tela
    // durante o movimento, mas a rota sempre o traz de volta para dentro
    // da arena ativa (ver _rffBorderRoute/_rffRandomRoute no tick), e o
    // clamp na arena grande garante que ele nunca suma de vez.
    // Arena inativa: desenho removido — em telas verticais (mobile) ela
    // aparecia sobreposta à arena ativa como uma segunda caixa "deitada",
    // confundindo com bug. Mantido apenas o cálculo de `pair` (usado na
    // lógica de alternância/clamp), sem desenhar o contorno da inativa.
    // Contorno desenhado: usa a arena da Invasão Reptiliana COMUM
    // (_arenaRect, já correta para a orientação da tela) em vez da arena
    // quadrada própria do Quasord (`ar`/pair) — essa última segue usada
    // só para movimento/clamp do boss, não para o desenho visual.
    {
      const arDraw=_arenaRect||ar;
      const {x,y,w,h}=arDraw; const x2=x+w, y2=y+h;
      const pulse=.55+.45*Math.sin(t*2.5);
      const alpha=.5+.35*Math.sin(t*3.1);
      ctx.save();
      // Borda principal sólida (substitui o tracejado + X central genéricos)
      ctx.strokeStyle=`rgba(220,20,10,${alpha})`;
      ctx.lineWidth=2.5;
      ctx.strokeRect(x,y,w,h);
      // Borda interna fina
      ctx.strokeStyle=`rgba(255,120,100,${alpha*.35})`;
      ctx.lineWidth=1;
      ctx.strokeRect(x+4,y+4,w-8,h-8);
      // Cantos reforçados em L — halo falso (2 passes, sem shadowBlur)
      const cs=22;
      const corners=[
        [[x,y+cs],[x,y],[x+cs,y]],
        [[x2-cs,y],[x2,y],[x2,y+cs]],
        [[x,y2-cs],[x,y2],[x+cs,y2]],
        [[x2-cs,y2],[x2,y2],[x2,y2-cs]],
      ];
      corners.forEach(pts=>{
        ctx.beginPath();
        ctx.moveTo(pts[0][0],pts[0][1]);ctx.lineTo(pts[1][0],pts[1][1]);ctx.lineTo(pts[2][0],pts[2][1]);
        ctx.strokeStyle=`rgba(255,20,0,${.18*(.8+.2*pulse)})`;ctx.lineWidth=8;ctx.stroke();
        ctx.strokeStyle=`rgba(255,20,0,${.8+.2*pulse})`;ctx.lineWidth=3.2;ctx.stroke();
      });
      // Partículas esporádicas na borda (glitch sutil)
      if(Math.random()<0.18){
        const side=Math.floor(Math.random()*4);
        let px,py;
        if(side===0){px=rand(x,x2);py=y;}
        else if(side===1){px=x2;py=rand(y,y2);}
        else if(side===2){px=rand(x,x2);py=y2;}
        else{px=x;py=rand(y,y2);}
        ctx.beginPath();ctx.arc(px,py,rand(1.5,4),0,Math.PI*2);
        ctx.fillStyle=`rgba(255,80,50,${rand(.4,.9)})`;ctx.fill();
      }
      ctx.restore();
    }
    ctx.save();

    // ── Paleta ───────────────────────────────────────────────────────
    const BLACK  ='#070000';
    const METAL  ='#110202';
    const EDGE   ='#2a0505';
    const NDIM   ='#550100';
    const NMID   ='#991100';
    const np     = 0.5+0.5*Math.sin(t*4.0);
    const NBRIGHT= `rgb(${Math.round(190+65*np)},${Math.round(4+5*np)},0)`;

    // Triple-stroke neon sem shadowBlur
    function neon(lw){
      ctx.lineWidth=lw*4.5; ctx.strokeStyle=NDIM;   ctx.stroke();
      ctx.lineWidth=lw*2.0; ctx.strokeStyle=NMID;   ctx.stroke();
      ctx.lineWidth=lw*0.7; ctx.strokeStyle=NBRIGHT; ctx.stroke();
    }

    // Glitch
    const gx=f.glitch>0.1?rand(-f.glitch*3,f.glitch*3):0;
    const gy=f.glitch>0.1?rand(-f.glitch*2,f.glitch*2):0;
    ctx.save(); ctx.translate(gx,gy);

    // Tamanho base do segmento — enorme
    // Raio decresce da cabeça (idx=0) até a cauda (idx=N-1)
    function segRadius(i){ return 62 - i*1.8; }

    // ── CORPO: cauda→cabeça (cabeça por cima no draw) ────────────────
    for(let i=N-1;i>=0;i--){
      const s=chain[i];
      const r=Math.max(12, segRadius(i));
      const isHead=(i===0);

      ctx.save();
      ctx.translate(s.x, s.y);
      ctx.rotate(s.a); // aponta para o segmento anterior (direção de avanço)

      if(!isHead){
        // ── Segmento de corpo: trapézio ──────────────────────────────
        // Eixo local: x = direção de avanço, y = perpendicular
        // Trapézio: base traseira (−x) mais larga, ponta frontal (+x) mais estreita
        // ── Respiração do corpo: onda sutil de "inspiração" que percorre
        // da cabeça até a cauda, com delay por índice de segmento — dá
        // sensação de organismo vivo, sem afetar a física/colisão. ──────
        const breathPhase=(t - i*0.09)*(Math.PI*2/3.6);
        const breathFactor=1+0.045*Math.sin(breathPhase);
        const wBack = r*1.30*breathFactor;   // meia-largura na traseira
        const wFront= r*0.80*breathFactor;   // meia-largura na frente
        const len   = 90;       // comprimento = distância entre segmentos, sem gap

        ctx.beginPath();
        ctx.moveTo(-len/2, -wBack);
        ctx.lineTo( len/2, -wFront);
        ctx.lineTo( len/2,  wFront);
        ctx.lineTo(-len/2,  wBack);
        ctx.closePath();
        ctx.fillStyle=BLACK; ctx.fill();

        // Borda neon
        ctx.beginPath();
        ctx.moveTo(-len/2, -wBack);
        ctx.lineTo( len/2, -wFront);
        ctx.lineTo( len/2,  wFront);
        ctx.lineTo(-len/2,  wBack);
        ctx.closePath();
        neon(1.3);

        // ── Fase 5: trapézios pulsam em vermelho e vazam faíscas pelas frestas ──
        if(f.phase===5){
          const pulseP=0.5+0.5*Math.sin(t*6+i*0.7);
          ctx.save();
          ctx.globalAlpha=0.35+0.35*pulseP;
          ctx.strokeStyle=`rgba(255,${Math.round(30+20*pulseP)},${Math.round(20+15*pulseP)},1)`;
          ctx.lineWidth=2.2+1.4*pulseP;
          ctx.beginPath();
          ctx.moveTo(-len/2, -wBack);
          ctx.lineTo( len/2, -wFront);
          ctx.lineTo( len/2,  wFront);
          ctx.lineTo(-len/2,  wBack);
          ctx.closePath();
          ctx.stroke();
          ctx.restore();
          if(Math.random()<0.05){
            _fxParticles.push({x:s.x+rand(-len*0.3,len*0.3),y:s.y+rand(-wBack*0.6,wBack*0.6),
              vx:rand(-25,25),vy:rand(-25,25),r:rand(1,3),alpha:1,
              color:Math.random()<0.5?'#ffaa22':'#ff2222',life:0.4,maxLife:0.4});
          }
        }

        // LEDs: só no segmento logo atrás da cabeça (i===1) e na cauda (i===N-1)
        // Acabamento no mesmo padrão do olho da cabeça: halo (glow radial),
        // núcleo brilhante com leve gradiente, e anel de contorno definido.
        if(i===1 || i===N-1){
          const nLeds=4;
          for(let l=0;l<nLeds;l++){
            const lx=-len*0.25 + (len*0.50/(nLeds-1))*l;
            // Pulso assíncrono por LED + leve defasagem por segmento (i),
            // simula atividade neural correndo pela "coluna" do corpo.
            const ledP=0.55+0.45*Math.sin(t*5+l*1.15+i*0.6);
            const ledR=r*0.115;

            // Halo externo (glow) — gradiente radial saindo do núcleo
            const glowR=ledR*2.4;
            const grad=ctx.createRadialGradient(lx,0,0, lx,0,glowR);
            grad.addColorStop(0, `rgba(255,255,255,${0.45+0.25*ledP})`);
            grad.addColorStop(1, 'rgba(255,255,255,0)');
            ctx.beginPath(); ctx.arc(lx, 0, glowR, 0, Math.PI*2);
            ctx.fillStyle=grad; ctx.fill();

            // Núcleo do LED
            ctx.beginPath(); ctx.arc(lx, 0, ledR, 0, Math.PI*2);
            ctx.fillStyle=`rgba(255,${Math.round(238+17*ledP)},${Math.round(238+17*ledP)},${0.85+0.15*ledP})`;
            ctx.fill();

            // Anel de contorno definido (mesmo espírito do stroke do olho)
            ctx.lineWidth=ledR*0.35; ctx.strokeStyle='rgba(160,40,40,0.65)'; ctx.stroke();

            // Brilho de destaque (specular) — pequeno ponto deslocado
            ctx.beginPath(); ctx.arc(lx-ledR*0.3, -ledR*0.3, ledR*0.35, 0, Math.PI*2);
            ctx.fillStyle=`rgba(255,255,255,${0.6+0.3*ledP})`;
            ctx.fill();
          }
        }

      } else {
        // ── CABEÇA: TRAPÉZIO INVERTIDO (base maior à frente) + 1 TRIÂNGULO
        // POR LADO, perto (não exatamente) dos vértices da base maior ────
        // Eixo local: +x = direção de avanço, y = lateral (−y esquerda,
        // +y direita). O trapézio da cabeça é IGUAL ao trapézio do corpo,
        // só que invertido: a base MAIOR fica na frente (+x) em vez de
        // atrás. Cada triângulo tem a BASE alinhada com a aresta da base
        // maior do trapézio (mesma reta x=hLen/2), posicionada perto do
        // vértice — não centrada exatamente nele — com a ponta apontando
        // para fora/frente.

        const hLen   = 70;        // comprimento do trapézio da cabeça
        const hWBack = r*0.78;    // meia-largura da base menor (junto ao pescoço)
        const hWFront= r*1.30;    // meia-largura da base maior (frente)

        // Trapézio invertido: estreito atrás (-x), largo na frente (+x)
        ctx.beginPath();
        ctx.moveTo(-hLen/2,-hWBack);
        ctx.lineTo( hLen/2,-hWFront);
        ctx.lineTo( hLen/2, hWFront);
        ctx.lineTo(-hLen/2, hWBack);
        ctx.closePath();
        ctx.fillStyle=BLACK; ctx.fill();
        neon(1.3);

        // Vértices da base maior (frente) do trapézio
        const baseR={x:hLen/2, y: hWFront};
        const baseL={x:hLen/2, y:-hWFront};

        function fillTri(a,b,c){
          ctx.beginPath();
          ctx.moveTo(a.x,a.y); ctx.lineTo(b.x,b.y); ctx.lineTo(c.x,c.y);
          ctx.closePath();
          ctx.fillStyle=BLACK; ctx.fill();
        }
        function strokeEdges(pts){ // pts = lista de pontos, desenha segmentos abertos (sem fechar)
          ctx.beginPath();
          ctx.moveTo(pts[0].x,pts[0].y);
          for(let i=1;i<pts.length;i++) ctx.lineTo(pts[i].x,pts[i].y);
          neon(1.6);
        }

        // ── ESPINHOS na base maior do trapézio — sem intervalo, lado a lado ──
        {
          const spineX = hLen/2;
          const sHW = r * 0.14;           // meia-largura de cada espinho
          const sL  = r * 0.20;           // comprimento
          const spanMin = -hWFront*0.72;
          const spanMax =  hWFront*0.72;
          const totalSpan = spanMax - spanMin;
          const spineCount = Math.floor(totalSpan / (sHW*2)); // preenche sem gaps

          for(let i=0;i<spineCount;i++){
            const sy  = spanMin + sHW + i*(sHW*2); // centros espaçados exatamente 2*sHW
            const sB1 = {x: spineX, y: sy - sHW};
            const sB2 = {x: spineX, y: sy + sHW};
            const sTip= {x: spineX + sL, y: sy};

            ctx.beginPath();
            ctx.moveTo(sB1.x,sB1.y); ctx.lineTo(sB2.x,sB2.y); ctx.lineTo(sTip.x,sTip.y);
            ctx.closePath();
            ctx.fillStyle=BLACK; ctx.fill();

            ctx.beginPath();
            ctx.moveTo(sB1.x,sB1.y); ctx.lineTo(sTip.x,sTip.y); ctx.lineTo(sB2.x,sB2.y);
            neon(1.4);
          }
        }

        // Âncora puxada para o centro do trapézio (em vez do vértice exato) —
        // evita o efeito "flutuando" fora da cabeça
        const ancR={x:baseR.x, y:baseR.y*0.78};
        const ancL={x:baseL.x, y:baseL.y*0.78};

        // ── Triângulo direito: base alinhada à aresta do trapézio (x=hLen/2),
        // posicionado perto do centro do trapézio — fino, torto e contido (−30% largura) ──
        const RB1={x:ancR.x-r*0.065, y:ancR.y-r*0.567};  // lado interno: era -0.81, agora 30% menor
        const RB2={x:ancR.x+r*0.065, y:ancR.y+r*0.161};  // lado externo: era +0.23, agora 30% menor
        const RTip={x:ancR.x+r*0.98, y:ancR.y+r*0.23};

        // ── Triângulo esquerdo (espelhado) ────────────────────────────
        const LB1={x:ancL.x-r*0.065, y:ancL.y+r*0.567};
        const LB2={x:ancL.x+r*0.065, y:ancL.y-r*0.161};
        const LTip={x:ancL.x+r*0.98, y:ancL.y-r*0.23};

        // Olho: pequeno, centralizado logo à frente das pontas dos triângulos
        const EYE_R = r*0.34;
        const EYE_X0 = Math.max(RTip.x,LTip.x)+r*0.30;
        // ── Durante a queda (eyeFalling ou transição da Fase 5), o olho desce
        // fisicamente ENTRE os dois suportes/presas (RTip e LTip) até tocar
        // exatamente no ponto de encontro entre elas, e só então explode. ──
        const fangMeetX=(RTip.x+LTip.x)/2, fangMeetY=(RTip.y+LTip.y)/2;
        const eyeFallP=f.eyeFallDrop||0;
        const EYE_X = EYE_X0+(fangMeetX-EYE_X0)*eyeFallP;
        const EYE_Y = 0+(fangMeetY-0)*eyeFallP;

        fillTri(RB1,RB2,RTip);
        strokeEdges([RB1,RTip,RB2]);

        fillTri(LB1,LB2,LTip);
        strokeEdges([LB1,LTip,LB2]);

        // ── 2º triângulo de cada lado: nasce perto da ponta do 1º (não
        // exatamente nela), do lado voltado para o centro/olho, e aponta
        // mais para frente/centro, continuando a "presa" ──────────────
        // Durante a transição da Fase 3, as presas TREMEM e a direita se
        // estica MIRANDO EXATAMENTE no olho (EYE_X,EYE_Y), até tocá-lo.
        const fangTw=f.fangTwitch||0;
        const twJit=fangTw>0?Math.sin(t*40)*fangTw*r*0.05:0;
        const piercePct=(fangTw>0&&!f.p3TransDone)?Math.min(1,Math.max(0,(fangTw-0.3)/0.7)):0;

        const R2B1={x:RTip.x-r*0.234, y:RTip.y-r*0.273+twJit}; // lado interno: era -0.39, 30% menor
        const R2B2={x:RTip.x+r*0.026, y:RTip.y+r*0.046+twJit}; // lado externo: era +0.065, 30% menor
        // Ponta de repouso da presa direita (sem furar)
        const R2TipRest={x:RTip.x+r*0.52, y:RTip.y-r*0.585};
        // Alvo: exatamente o centro do olho (com pequena folga para "tocar" a borda)
        const eyeTouchX=EYE_X, eyeTouchY=EYE_Y-r*0.34*0.15; // toca perto do centro/topo do olho
        const R2Tip={
          x: R2TipRest.x+(eyeTouchX-R2TipRest.x)*piercePct,
          y: R2TipRest.y+(eyeTouchY-R2TipRest.y)*piercePct,
        };

        const L2B1={x:LTip.x-r*0.234, y:LTip.y+r*0.273-twJit};
        const L2B2={x:LTip.x+r*0.026, y:LTip.y-r*0.046-twJit};
        const L2Tip={x:LTip.x+r*0.52, y:LTip.y+r*0.585};

        fillTri(R2B1,R2B2,R2Tip);
        strokeEdges([R2B1,R2Tip,R2B2]);

        fillTri(L2B1,L2B2,L2Tip);
        strokeEdges([L2B1,L2Tip,L2B2]);

        // ── OLHO, pequeno e centralizado ──────────────────────────────
        // Comportamento normal (Fases 1/2 ou antes da furada): pulsa suave.
        // Após furado (Fase 3): rachado, cor mais fria/instável, pupila
        // treme e desvia para qualquer direção — "olhar desesperado".
        const eyeP=0.5+0.5*Math.sin(t*3.5);
        const crackAmt=f.eyeCrackAmt||0;
        if(f.eyeGone){
          // ── Olho perdido (Fase 5): cavidade vazia e escura, faíscas
          // saindo esporadicamente da órbita — sem globo ocular. ──────
          ctx.beginPath(); ctx.arc(EYE_X, EYE_Y, EYE_R, 0, Math.PI*2);
          ctx.fillStyle='#0a0603'; ctx.fill();
          ctx.lineWidth=EYE_R*0.10; ctx.strokeStyle='#1a0a05'; ctx.stroke();
          if(Math.random()<0.12){
            _fxParticles.push({x:EYE_X,y:EYE_Y,vx:rand(-30,30),vy:rand(-30,30),
              r:rand(1,3),alpha:1,color:Math.random()<0.5?'#ffaa22':'#ff3300',life:0.35,maxLife:0.35});
          }
        } else if(crackAmt<=0){
          ctx.beginPath(); ctx.arc(EYE_X, EYE_Y, EYE_R, 0, Math.PI*2);
          ctx.fillStyle=`rgba(0,${Math.round(200+35*eyeP)},${Math.round(215+25*eyeP)},0.95)`;
          ctx.fill();
          ctx.lineWidth=EYE_R*0.10; ctx.strokeStyle='#002233'; ctx.stroke();

          // Pupila em fenda diagonal
          ctx.save();
          ctx.translate(EYE_X, EYE_Y);
          ctx.rotate(-Math.PI/4);
          ctx.beginPath();
          ctx.moveTo(-EYE_R*0.42, 0);
          ctx.lineTo( EYE_R*0.42, 0);
          ctx.strokeStyle='#001a22'; ctx.lineWidth=EYE_R*0.20; ctx.lineCap='round';
          ctx.stroke();
          ctx.restore();
        } else {
          // Olho furado/rachado — MANTÉM a cor ciano original, com veias
          // rachadas vermelhas por cima e leve tremor nervoso.
          const jitX=rand(-1,1)*crackAmt*EYE_R*0.08;
          const jitY=rand(-1,1)*crackAmt*EYE_R*0.08;
          ctx.beginPath(); ctx.arc(EYE_X+jitX, EYE_Y+jitY, EYE_R, 0, Math.PI*2);
          ctx.fillStyle=`rgba(0,${Math.round(200+35*eyeP)},${Math.round(215+25*eyeP)},0.95)`;
          ctx.fill();
          ctx.lineWidth=EYE_R*0.10; ctx.strokeStyle='#002233'; ctx.stroke();

          // Veias rachadas — linhas vermelhas irregulares saindo do centro,
          // sobrepostas ao ciano (não substituem a cor de base do olho)
          ctx.save();
          ctx.translate(EYE_X+jitX, EYE_Y+jitY);
          ctx.strokeStyle=`rgba(30,120,255,${0.55+0.4*crackAmt})`;
          ctx.lineWidth=EYE_R*0.06;
          const crackAngles=[0.3,1.1,2.0,2.8,3.7,4.6,5.4];
          crackAngles.forEach((ca,ci)=>{
            const len=EYE_R*(0.5+0.4*Math.sin(ci*2.1));
            ctx.beginPath();
            ctx.moveTo(0,0);
            ctx.lineTo(Math.cos(ca)*len, Math.sin(ca)*len);
            ctx.stroke();
          });
          ctx.restore();

          // Pupila desviando desesperadamente (olhar nervoso)
          const look=f.eyeLookAngle||0;
          ctx.save();
          ctx.translate(EYE_X+jitX, EYE_Y+jitY);
          ctx.rotate(look);
          ctx.beginPath();
          ctx.arc(EYE_R*0.30,0,EYE_R*0.30,0,Math.PI*2);
          ctx.fillStyle='#001a22';ctx.fill();
          ctx.restore();

          // Vazamento vermelho pingando do olho
          if(Math.random()<0.15*crackAmt){
            _fxParticles.push({x:EYE_X+jitX+f.x-f.x,y:EYE_Y+jitY,vx:rand(-8,8),vy:rand(20,50),
              r:rand(1.5,3),alpha:1,color:'#ff2222',life:0.6,maxLife:0.6});
          }
        }
      }

      ctx.restore();
    }

    // ── CAUDA: trapézio final que afunila até a ponta ─────────────────
    {
      const tail = chain[N-1];
      const rTail = Math.max(12, segRadius(N-1));
      const wBack  = rTail*1.30; // meia-largura da base (alinhada com a base traseira do último trapézio)
      const tailLen = 70;        // comprimento da cauda
      const lastLen = 90;        // comprimento do último trapézio do corpo (deve bater com 'len' no loop acima)

      ctx.save();
      ctx.translate(tail.x, tail.y);
      ctx.rotate(tail.a);
      // Desloca a origem para a borda TRASEIRA do último trapézio (-lastLen/2),
      // que é onde a base maior (wBack) dele realmente termina — em vez de
      // nascer do centro do segmento, o que fazia a cauda ficar "afundada"
      // dentro do corpo em vez de encaixada na ponta.
      ctx.translate(-lastLen/2, 0);

      // Forma: trapézio que afunila até ponta (triângulo alongado)
      // Base em +x/2 (encostada na traseira do último trapézio), ponta em -x
      ctx.beginPath();
      ctx.moveTo( tailLen*0.5,  -wBack);
      ctx.lineTo( tailLen*0.5,   wBack);
      ctx.lineTo(-tailLen*0.5,   0);    // ponta
      ctx.closePath();
      ctx.fillStyle=BLACK; ctx.fill();

      // Borda neon
      ctx.beginPath();
      ctx.moveTo( tailLen*0.5,  -wBack);
      ctx.lineTo( tailLen*0.5,   wBack);
      ctx.lineTo(-tailLen*0.5,   0);
      ctx.closePath();
      neon(1.3);

      // ── LEDs deitados ao longo da cauda (mesmo acabamento da cabeça) ──
      // Fileira de 4 LEDs do meio da base até perto da ponta, acompanhando
      // o afunilamento do triângulo (halo, núcleo, anel, brilho specular).
      const nLeds=4;
      for(let l=0;l<nLeds;l++){
        const tFrac = 0.15 + (0.65/(nLeds-1))*l; // 0=base, 1=ponta
        const lx = tailLen*0.5 - tailLen*tFrac;
        const lw = wBack*(1-tFrac); // largura do triângulo nesse ponto (afunilando)
        const ledP=0.55+0.45*Math.sin(t*5+l*1.15);
        const ledR=Math.min(rTail*0.115, lw*0.55);

        const glowR=ledR*2.4;
        const grad=ctx.createRadialGradient(lx,0,0, lx,0,glowR);
        grad.addColorStop(0, `rgba(255,255,255,${0.45+0.25*ledP})`);
        grad.addColorStop(1, 'rgba(255,255,255,0)');
        ctx.beginPath(); ctx.arc(lx, 0, glowR, 0, Math.PI*2);
        ctx.fillStyle=grad; ctx.fill();

        ctx.beginPath(); ctx.arc(lx, 0, ledR, 0, Math.PI*2);
        ctx.fillStyle=`rgba(255,${Math.round(238+17*ledP)},${Math.round(238+17*ledP)},${0.85+0.15*ledP})`;
        ctx.fill();
        ctx.lineWidth=ledR*0.35; ctx.strokeStyle='rgba(160,40,40,0.65)'; ctx.stroke();

        ctx.beginPath(); ctx.arc(lx-ledR*0.3, -ledR*0.3, ledR*0.35, 0, Math.PI*2);
        ctx.fillStyle=`rgba(255,255,255,${0.6+0.3*ledP})`;
        ctx.fill();
      }

      ctx.restore();
    }

    // ── 🌀 Emoji de desorientação flutuando sobre a cabeça (transição Fase 3) ──
    if(f.phase===3&&!f.p3TransDone&&!f.dying){
      const head=chain[0];
      const bob=Math.sin(t*6)*4;
      const spin=t*5;
      ctx.save();
      ctx.translate(head.x, head.y-90+bob);
      ctx.rotate(Math.sin(spin)*0.3);
      ctx.font='38px sans-serif';
      ctx.textAlign='center';ctx.textBaseline='middle';
      ctx.globalAlpha=0.92;
      ctx.fillText('🌀',0,0);
      ctx.restore();
    }

    ctx.restore(); // glitch
  }


  // ══════════════════════════════════════════════════════════════════
  //  FORMA 1: SERPENTE — Destruidor mecânico, corpo em cadeia física
  //  A cabeça é o pai de todos os segmentos. Cada segmento arrasta
  //  o seguinte via física de snake (posição + ângulo herdados).
  //  Design: neutro/industrial, sem emoção, sem sorriso, sem raiva.
  //  Apenas uma máquina de aniquilação.
  // ══════════════════════════════════════════════════════════════════
  function _drawBossSerpente(ctx,b,t){
    const gi=b.glitchIntensity;
    const phase=_getReptBossPhase();
    const bA=b.invis?(0.05+0.04*Math.sin(t*10)):1;

    // ── Paleta alinhada às demais formas (Nebulon/Drexcy): vermelho
    // vivo/saturado com veias brilhantes, em vez do vermelho escuro
    // industrial anterior. Mesma família de cores em todo o trio. ──
    const C_ARMOR ='#0e0101';  // placa de armadura (base escura, igual PLT do Drexcy)
    const C_SCALE ='#180303';  // escama/placa secundária (igual SCL)
    const C_EDGE  ='#cc1400';  // borda das placas (igual EDG)
    const C_VEIN  ='#ff2600';  // veia/núcleo brilhante (igual VNE)
    const C_CORE  ='#ff2600';  // núcleo de energia — agora vivo, não opaco
    const C_JOINT ='#080000';  // articulação (igual JNT)
    const C_SENSOR='#ff4400';  // sensor/scanner

    // ── Ângulo de voo suavizado ────────────────────────────────────
    const mv=Math.hypot(b.vx,b.vy);
    if(mv>8){
      const ta=Math.atan2(b.vy,b.vx);
      if(b._da===undefined)b._da=ta;
      let diff=ta-b._da;
      while(diff>Math.PI)diff-=Math.PI*2;
      while(diff<-Math.PI)diff+=Math.PI*2;
      b._da+=diff*0.22; // responsivo o suficiente para acompanhar curvas, mas ainda suave
    } else { if(b._da===undefined)b._da=0; }
    const headAngle=b._da;

    // ── Física de cadeia: atualiza posições dos segmentos ─────────
    // Cada segmento tem sua própria posição e ângulo.
    // O segmento 0 É a cabeça (b.x, b.y). Os demais arrastam.
    const SEG_COUNT=8;        // cabeça + 7 elos de corpo + ponta
    const SEG_DIST =[0,38,34,30,27,24,21,18]; // distância entre seg[i-1] e seg[i]

    if(!b._chain){
      // Inicializa a cadeia toda na posição da cabeça
      b._chain=[];
      for(let i=0;i<SEG_COUNT;i++)
        b._chain.push({x:b.x,y:b.y,a:headAngle});
    }
    // seg[0] = cabeça — sempre igual a b.x, b.y
    b._chain[0].x=b.x; b._chain[0].y=b.y; b._chain[0].a=headAngle;
    // Cada elo segue o anterior mantendo a distância fixa (correção SEMPRE
    // ativa, não só "se afastado demais" — isso evitava o corpo destravar
    // e ficar anguloso/fora de sincronia quando a cabeça virava rápido).
    for(let i=1;i<SEG_COUNT;i++){
      const prev=b._chain[i-1], cur=b._chain[i];
      const dx=cur.x-prev.x, dy=cur.y-prev.y;
      const d=Math.hypot(dx,dy)||0.001;
      const dist=SEG_DIST[i]??22;
      // Sempre reposiciona o elo exatamente a 'dist' do anterior, na
      // direção em que já estava (mantém a "memória" da curva percorrida
      // em vez de colapsar/esticar de forma brusca).
      cur.x=prev.x+dx/d*dist;
      cur.y=prev.y+dy/d*dist;
      // Ângulo suavizado: interpola em vez de saltar direto para o
      // atan2 bruto, o que eliminava os "trancos" visuais entre elos.
      const targetA=Math.atan2(prev.y-cur.y,prev.x-cur.x);
      if(cur.a===undefined)cur.a=targetA;
      let da=targetA-cur.a;
      while(da>Math.PI)da-=Math.PI*2;
      while(da<-Math.PI)da+=Math.PI*2;
      cur.a+=da*0.5;
    }

    // ── Raio visual por segmento (decrescente da cabeça à cauda) ──
    const SEG_R=[26,20,18,16,14,13,11,8];

    // ── Escala de detalhe por fase — mais espinhos/veias ativas
    // conforme o boss avança de fase, igual ao camaleão (nChev). ──
    const spineCount=phase===1?3:phase===2?4:5;

    // ── Função que desenha uma escama losangular individual (mesmo
    // motivo visual do Drexcy, para dar textura de réptil aos elos) ──
    function _scale(cctx,cx2,cy2,w,h,ang,lit){
      cctx.save();cctx.translate(cx2,cy2);cctx.rotate(ang);
      cctx.beginPath();
      cctx.moveTo(0,-h);cctx.lineTo(w,0);cctx.lineTo(0,h);cctx.lineTo(-w,0);
      cctx.closePath();
      const g=cctx.createLinearGradient(-w,0,w,0);
      g.addColorStop(0,C_JOINT);g.addColorStop(0.5,lit?C_SCALE:C_ARMOR);g.addColorStop(1,C_JOINT);
      cctx.fillStyle=g;cctx.fill();
      cctx.strokeStyle=C_EDGE+'aa';cctx.lineWidth=0.8;cctx.stroke();
      cctx.beginPath();cctx.moveTo(0,-h*.6);cctx.lineTo(0,h*.6);
      cctx.strokeStyle=C_VEIN+'44';cctx.lineWidth=0.4;cctx.stroke();
      cctx.restore();
    }

    // ── Função que desenha um elo de corpo no centro (0,0) ────────
    function _drawBodySeg(cx2,r,idx,totalIdx){
      // Placa hexagonal achatada (box de armadura)
      const w=r*1.55, h=r*0.78;
      cx2.beginPath();
      cx2.moveTo(-w*0.55,-h);cx2.lineTo(w*0.55,-h);
      cx2.lineTo(w,0);
      cx2.lineTo(w*0.55,h);cx2.lineTo(-w*0.55,h);
      cx2.lineTo(-w,0);
      cx2.closePath();
      // Fill gradiente: mais escuro nas bordas, mais vivo no meio
      const g=cx2.createLinearGradient(-w,0,w,0);
      g.addColorStop(0,C_JOINT);g.addColorStop(0.45,C_ARMOR);g.addColorStop(1,C_JOINT);
      cx2.fillStyle=g;cx2.fill();
      cx2.strokeStyle=C_EDGE;cx2.lineWidth=1.6;cx2.stroke();
      // Parafusos nos cantos
      const bolts=[[-w*0.45,-h*0.6],[w*0.45,-h*0.6],[-w*0.45,h*0.6],[w*0.45,h*0.6]];
      bolts.forEach(([bx2,by2])=>{
        cx2.beginPath();cx2.arc(bx2,by2,r*0.11,0,Math.PI*2);
        cx2.fillStyle=C_EDGE;cx2.fill();
        cx2.beginPath();cx2.arc(bx2,by2,r*0.05,0,Math.PI*2);
        cx2.fillStyle='#3a0808';cx2.fill();
      });
      // Escamas losangulares laterais (textura de réptil, ausente antes)
      _scale(cx2,-w*0.32,0,r*0.22,r*0.4,0,idx%2===0);
      _scale(cx2, w*0.32,0,r*0.22,r*0.4,0,idx%2===1);
      // Espinho dorsal em cada elo (variação por fase: mais visível em
      // fases avançadas — reforça a leitura de "boss ficando mais feroz")
      if(idx<spineCount+2){
        const sh=r*0.5*(0.75+0.25*Math.sin(t*3+idx*0.8));
        cx2.beginPath();
        cx2.moveTo(-r*0.22,-h*0.95);cx2.lineTo(0,-h*0.95-sh);cx2.lineTo(r*0.22,-h*0.95);
        cx2.closePath();
        cx2.fillStyle=C_SCALE;cx2.fill();cx2.strokeStyle=C_EDGE;cx2.lineWidth=0.9;cx2.stroke();
      }
      // Núcleo pulsante central (apenas elos pares — alternado), agora
      // com o vermelho vivo (C_VEIN) em vez do vermelho abafado anterior
      if(idx%2===0){
        const pulse=0.4+0.4*Math.sin(t*4+idx*0.9);
        cx2.beginPath();cx2.arc(0,0,r*0.28*pulse+r*0.1,0,Math.PI*2);
        cx2.fillStyle=`rgba(255,38,0,${0.5*pulse})`;cx2.fill();
        cx2.beginPath();cx2.arc(0,0,r*0.11,0,Math.PI*2);
        cx2.fillStyle=`rgba(255,90,20,${0.85*pulse})`;cx2.fill();
      }
      // Ranhuras mecânicas laterais com veia brilhante fina
      cx2.strokeStyle=C_EDGE+'88';cx2.lineWidth=0.7;
      cx2.beginPath();cx2.moveTo(-w*0.22,-h*0.95);cx2.lineTo(-w*0.22,h*0.95);cx2.stroke();
      cx2.beginPath();cx2.moveTo(w*0.22,-h*0.95);cx2.lineTo(w*0.22,h*0.95);cx2.stroke();
      cx2.strokeStyle=C_VEIN+'33';cx2.lineWidth=0.5;
      cx2.beginPath();cx2.moveTo(-w*0.9,0);cx2.lineTo(w*0.9,0);cx2.stroke();
    }

    // ── Função que desenha a articulação entre elos ────────────────
    function _drawJoint(cx2,r){
      cx2.beginPath();cx2.arc(0,0,r*0.62,0,Math.PI*2);
      cx2.fillStyle=C_JOINT;cx2.fill();
      cx2.strokeStyle=C_EDGE;cx2.lineWidth=1;cx2.stroke();
      cx2.beginPath();cx2.arc(0,0,r*0.32,0,Math.PI*2);
      cx2.fillStyle='#0c0404';cx2.fill();
      // Aro de veia fina — dá mais riqueza à articulação (antes era só
      // dois círculos planos)
      cx2.beginPath();cx2.arc(0,0,r*0.46,0,Math.PI*2);
      cx2.strokeStyle=C_VEIN+'55';cx2.lineWidth=0.6;cx2.stroke();
    }

    // ── Desenha cadeia de costas para frente (cauda primeiro) ──────
    // Assim a cabeça fica renderizada por cima
    ctx.save();
    ctx.globalAlpha=bA;

    // Invisibilidade: bolha ao redor da cabeça
    if(b.invis){
      ctx.save();ctx.globalAlpha=bA*(0.10+0.06*Math.sin(t*6));
      ctx.beginPath();ctx.arc(b.x,b.y,70,0,Math.PI*2);
      ctx.strokeStyle='rgba(120,160,255,0.8)';ctx.lineWidth=2;ctx.stroke();
      ctx.restore();
    }

    // Aura vermelha difusa ao redor da cabeça (mesmo tom vivo do trio)
    {
      const ag=ctx.createRadialGradient(b.x,b.y,10,b.x,b.y,90);
      ag.addColorStop(0,'rgba(200,0,0,0.24)');ag.addColorStop(1,'rgba(0,0,0,0)');
      ctx.save();ctx.globalAlpha=bA*0.8;
      ctx.beginPath();ctx.arc(b.x,b.y,90,0,Math.PI*2);
      ctx.fillStyle=ag;ctx.fill();ctx.restore();
    }

    // Elos de corpo (do último para o segundo — frente do corpo)
    for(let i=SEG_COUNT-1;i>=1;i--){
      const seg=b._chain[i];
      ctx.save();
      ctx.translate(seg.x,seg.y);
      ctx.rotate(seg.a);
      if(i===SEG_COUNT-1){
        // Ponta da cauda: triângulo afiado
        const tr=SEG_R[i]??8;
        ctx.beginPath();ctx.moveTo(tr*1.5,0);ctx.lineTo(-tr*0.5,tr*0.7);ctx.lineTo(-tr*0.5,-tr*0.7);ctx.closePath();
        ctx.fillStyle=C_ARMOR;ctx.fill();ctx.strokeStyle=C_EDGE;ctx.lineWidth=1.2;ctx.stroke();
        // Ponta de energia — agora com brilho vivo
        ctx.beginPath();ctx.moveTo(tr*1.5,0);ctx.lineTo(tr*0.8,tr*0.3);ctx.lineTo(tr*0.8,-tr*0.3);ctx.closePath();
        ctx.fillStyle=C_CORE;ctx.fill();
        ctx.beginPath();ctx.arc(tr*1.1,0,tr*0.22,0,Math.PI*2);
        ctx.fillStyle=`rgba(255,150,80,${0.6+0.3*Math.sin(t*6)})`;ctx.fill();
      } else {
        // Articulação entre elos
        _drawJoint(ctx,SEG_R[i]??12);
        _drawBodySeg(ctx,SEG_R[i]??12,i,SEG_COUNT);
      }
      ctx.restore();
    }

    // ── 4 ganchos extensíveis (partindo da cabeça) ─────────────────
    const clawMaxLen=110;
    const seg0=b._chain[0];
    (b.claws||[]).forEach((cl,ci)=>{
      // Ângulo do gancho relativo ao ângulo da cabeça
      const absAngle=headAngle+cl.angle;
      const hx=seg0.x+Math.cos(absAngle)*clawMaxLen*cl.ext;
      const hy=seg0.y+Math.sin(absAngle)*clawMaxLen*cl.ext;
      // Cabo: curva quadrática, dois passes
      const mx=seg0.x+(hx-seg0.x)*0.5+Math.sin(t*2.5+ci*1.3)*8*cl.ext;
      const my=seg0.y+(hy-seg0.y)*0.5;
      ctx.beginPath();ctx.moveTo(seg0.x,seg0.y);ctx.quadraticCurveTo(mx,my,hx,hy);
      ctx.strokeStyle='#3a0808cc';ctx.lineWidth=3;ctx.stroke();
      ctx.beginPath();ctx.moveTo(seg0.x,seg0.y);ctx.quadraticCurveTo(mx,my,hx,hy);
      ctx.strokeStyle=C_EDGE+'aa';ctx.lineWidth=1.2;ctx.stroke();
      // Ponta
      ctx.save();ctx.translate(hx,hy);ctx.rotate(absAngle-Math.PI/2);
      const tipC=cl.grabbed?'#ff8800':C_CORE;
      ctx.beginPath();ctx.moveTo(0,-9);ctx.lineTo(5,5);ctx.lineTo(-5,5);ctx.closePath();
      ctx.strokeStyle=tipC;ctx.lineWidth=3;ctx.stroke();
      ctx.fillStyle=tipC;ctx.fill();
      ctx.restore();
      if(cl.grabbed){
        ctx.beginPath();ctx.arc(hx,hy,12+3*Math.sin(t*7+ci),0,Math.PI*2);
        ctx.strokeStyle=`rgba(255,140,0,${0.4+0.3*Math.abs(Math.sin(t*6))})`;
        ctx.lineWidth=2;ctx.stroke();
      }
    });

    // ── Cabeça (desenhada por cima de tudo) ───────────────────────
    // Design: capacete industrial hexagonal, olhos-scanner horizontais
    // sem sobrancelhas, sem expressão — apenas sensores frios.
    ctx.save();
    ctx.translate(b.x,b.y);
    ctx.rotate(headAngle);
    if(gi>0.07)ctx.translate(rand(-gi*5,gi*5),rand(-gi*4,gi*4));

    const H=26; // half-size da cabeça

    // Articulação pescoço (elo zero da cadeia)
    _drawJoint(ctx,SEG_R[0]);

    // Casco hexagonal principal
    ctx.beginPath();
    ctx.moveTo(H*1.5,0);
    ctx.lineTo(H*0.9,-H*1.05);
    ctx.lineTo(-H*0.9,-H*1.05);
    ctx.lineTo(-H*1.5,0);
    ctx.lineTo(-H*0.9,H*1.05);
    ctx.lineTo(H*0.9,H*1.05);
    ctx.closePath();
    const hG=ctx.createLinearGradient(-H*1.5,0,H*1.5,0);
    hG.addColorStop(0,'#100404');hG.addColorStop(0.4,'#1e0808');hG.addColorStop(1,'#0d0303');
    ctx.fillStyle=hG;ctx.fill();
    ctx.strokeStyle=C_EDGE;ctx.lineWidth=2;ctx.stroke();

    // Escamas losangulares no casco (textura de réptil na cabeça,
    // reforça a identidade "serpente" — ausente na versão anterior)
    [[-H*0.55,-H*0.5],[H*0.15,-H*0.62],[-H*0.55,H*0.5],[H*0.15,H*0.62]].forEach(([sx,sy])=>{
      _scale(ctx,sx,sy,H*0.16,H*0.28,Math.atan2(sy,sx),true);
    });

    // Painel frontal (face agressiva plana — sem boca, sem nariz)
    ctx.beginPath();
    ctx.moveTo(H*1.2,-H*0.55);ctx.lineTo(H*1.2,H*0.55);
    ctx.lineTo(H*0.55,H*0.78);ctx.lineTo(H*0.55,-H*0.78);
    ctx.closePath();
    ctx.fillStyle='#150505';ctx.fill();
    ctx.strokeStyle='#3d0a0a';ctx.lineWidth=1;ctx.stroke();

    // Visor scanner: dois olhos horizontais idênticos (sem emoção)
    // Olhos = sensores de varredura, não têm forma emocional
    [[0,-H*0.28],[0,H*0.28]].forEach(([ey,ez])=>{
      // Socket
      ctx.beginPath();ctx.roundRect(H*0.5+ey-H*0.6,-H*0.10,H*1.1,H*0.20,3);
      // (note: o 'ey' aqui é 0 pois visor é frontal, usamos ez para y)
      ctx.beginPath();ctx.roundRect(H*0.52,-H*0.10+ez,H*0.58,H*0.20,2);
      ctx.fillStyle='#0a0202';ctx.fill();
      ctx.strokeStyle='#2a0606';ctx.lineWidth=0.8;ctx.stroke();
      // Scanner (linha vermelha que varre de lado a lado)
      const scanPos=0.5+0.5*Math.sin(t*3.5+ez*0.1);
      const scanX=H*0.54+scanPos*H*0.52;
      ctx.save();ctx.beginPath();ctx.rect(H*0.52,-H*0.09+ez,H*0.56,H*0.18);ctx.clip();
      ctx.fillStyle=`rgba(255,38,0,0.7)`;
      ctx.fillRect(scanX-2,-H*0.09+ez,3,H*0.18);
      // Grade do scanner
      ctx.strokeStyle='rgba(150,10,0,0.45)';ctx.lineWidth=0.5;
      for(let g2=0;g2<4;g2++){
        const gx=H*0.54+g2*H*0.14;
        ctx.beginPath();ctx.moveTo(gx,-H*0.09+ez);ctx.lineTo(gx,H*0.09+ez);ctx.stroke();
      }
      ctx.restore();
    });

    // Placa lateral esquerda (armadura de face)
    ctx.beginPath();
    ctx.moveTo(-H*0.6,-H*0.9);ctx.lineTo(-H*1.4,0);ctx.lineTo(-H*0.6,H*0.9);
    ctx.lineTo(-H*0.3,H*0.9);ctx.lineTo(-H*1.0,0);ctx.lineTo(-H*0.3,-H*0.9);
    ctx.closePath();
    ctx.fillStyle='#180606';ctx.fill();ctx.strokeStyle=C_EDGE;ctx.lineWidth=1.2;ctx.stroke();

    // Detalhe: 3 sulcos horizontais na placa lateral, agora com veia viva
    ctx.strokeStyle=C_VEIN+'55';ctx.lineWidth=0.7;
    for(let s2=0;s2<3;s2++){
      const sy=(-H*0.55+s2*H*0.55);
      ctx.beginPath();ctx.moveTo(-H*1.25,sy*0.7);ctx.lineTo(-H*0.5,sy);ctx.stroke();
    }

    // Núcleo central pulsante (não é boca — é reator exposto), agora
    // com o mesmo vermelho vivo do trio
    {
      const rp=0.45+0.45*Math.sin(t*5);
      // Halo externo
      ctx.beginPath();ctx.ellipse(H*0.15,0,H*0.3+rp*4,H*0.18+rp*2,0,0,Math.PI*2);
      ctx.fillStyle=`rgba(200,0,0,${0.28*rp})`;ctx.fill();
      // Core
      ctx.beginPath();ctx.ellipse(H*0.15,0,H*0.18,H*0.10,0,0,Math.PI*2);
      ctx.fillStyle=C_ARMOR;ctx.fill();ctx.strokeStyle=C_EDGE;ctx.lineWidth=0.8;ctx.stroke();
      ctx.beginPath();ctx.arc(H*0.15,0,H*0.06+rp*2,0,Math.PI*2);
      ctx.fillStyle=`rgba(255,60,20,${0.85*rp})`;ctx.fill();
      // Label técnico (pequeno, como código de máquina)
      ctx.fillStyle='rgba(120,15,10,0.8)';ctx.font='bold 4px monospace';
      ctx.textAlign='center';ctx.fillText('RX-00',H*0.15,H*0.45);
    }

    // Antenas/sensores no topo (sem chifres curvos — são barras retas)
    [[-H*0.42],[H*0.42]].forEach(([ax])=>{
      ctx.beginPath();ctx.moveTo(ax,-H*1.02);ctx.lineTo(ax,-H*1.55);
      ctx.strokeStyle=C_EDGE;ctx.lineWidth=2.2;ctx.lineCap='butt';ctx.stroke();
      // Indicador no topo
      const apulse=0.3+0.7*Math.sin(t*6+ax*0.05);
      ctx.beginPath();ctx.arc(ax,-H*1.55,3,0,Math.PI*2);
      ctx.fillStyle=`rgba(255,38,0,${apulse})`;ctx.fill();
    });
    // Antena central
    ctx.beginPath();ctx.moveTo(0,-H*1.02);ctx.lineTo(0,-H*1.72);
    ctx.strokeStyle='#4a0a0a';ctx.lineWidth=1.4;ctx.stroke();
    ctx.beginPath();ctx.rect(-H*0.12,-H*1.72,H*0.24,H*0.18);
    ctx.fillStyle=C_ARMOR;ctx.fill();ctx.strokeStyle=C_EDGE;ctx.lineWidth=0.8;ctx.stroke();

    // HP bar (posicionada embaixo da cabeça, eixo da cabeça)
    ctx.restore(); // sai da rotação da cabeça para HP bar ficar reta

    ctx.save();
    ctx.globalAlpha=Math.min(1,bA*1.5);
    const hpPct=Math.max(0,b.formHP/b.formMaxHP);
    const barW=100,barH=7;
    const barX=b.x-barW/2, barY=b.y+48;
    ctx.fillStyle='#0a0202';ctx.fillRect(barX,barY,barW,barH);
    ctx.fillStyle=hpPct>0.65?C_CORE:hpPct>0.30?'#ff6600':'#ff0000';
    ctx.fillRect(barX,barY,barW*hpPct,barH);
    ctx.strokeStyle='#3a0808';ctx.lineWidth=0.8;ctx.strokeRect(barX,barY,barW,barH);
    ctx.fillStyle='rgba(255,160,100,0.85)';ctx.font='bold 8px monospace';ctx.textAlign='center';
    ctx.fillText(`ANIQUILADOR [${Math.ceil(b.formHP)}]`,b.x,barY+barH+10);
    ctx.restore();

    // Flash de dano (fill com alpha — sem screen blend)
    if(b.flashT>0){
      b.flashT-=0.016;
      ctx.save();ctx.globalAlpha=b.flashT*0.5;
      ctx.beginPath();ctx.arc(b.x,b.y,80,0,Math.PI*2);
      ctx.fillStyle=b.flashColor||'#ffffff';ctx.fill();
      ctx.restore();
    }

    // Glitch
    if(gi>0.06){
      ctx.save();
      const bars=Math.ceil(gi*10);
      for(let i=0;i<bars;i++){
        const gy=b.y+rand(-90,90);
        ctx.beginPath();ctx.rect(b.x+rand(-60,0),gy,rand(30,120),rand(2,5));
        ctx.fillStyle=`rgba(220,0,0,${gi*0.4})`;ctx.fill();
      }
      ctx.restore();
    }

    // Morte
    if(b.dying){
      ctx.save();
      const dg=Math.min(1,b.dyingT/4.5);
      for(let i=0;i<Math.ceil(dg*14);i++){
        ctx.beginPath();
        const mx2=b.x+rand(-80,80),my2=b.y+rand(-80,80);
        ctx.moveTo(mx2,my2);ctx.lineTo(mx2+rand(-30,30),my2+rand(-30,30));
        ctx.strokeStyle=`rgba(255,60,0,${dg*0.8})`;ctx.lineWidth=2;ctx.stroke();
      }
      ctx.restore();
    }

    ctx.restore(); // restore do globalAlpha=bA
  }

  // ══════════════════════════════════════════════════════════════════
  //  FORMA 2: CAMALEÃO — corpo orgânico, olhos giratórios independentes
  // ══════════════════════════════════════════════════════════════════
  function _drawBossCamaleao(ctx,b,t){
    // ══ CAMALEÃO — TOP-DOWN — FIEL À REFERÊNCIA ══
    const gi=b.glitchIntensity;
    const phase=_getReptBossPhase();
    const camA=b.camouflageAlpha||1;
    ctx.save();ctx.translate(b.x,b.y);
    if(gi>0.08)ctx.translate(rand(-gi*5,gi*5),rand(-gi*4,gi*4));
    ctx.globalAlpha=camA;

    const S=58;
    const dark=b.camHiding?0.32:1;
    const pRed=`rgb(${Math.round(220*dark)},${Math.round(8*dark)},${Math.round(5*dark)})`;
    const pRedB=`rgb(${Math.round(255*dark)},${Math.round(30*dark)},${Math.round(10*dark)})`;
    const pBlack='rgb(4,0,0)';
    const stroke=(w,c)=>{ctx.strokeStyle=c;ctx.lineWidth=w;};

    // rotaciona tudo pelo ângulo de movimento
    const headA=b.camHeadAngle||(-Math.PI/2);
    ctx.rotate(headA+Math.PI/2);
    ctx.lineCap='round';ctx.lineJoin='round';

    // ═══ CAUDA ENROLADA EM ESPIRAL (sai da base do corpo, enrola pra baixo-esq) ═══
    // A cauda na imagem faz uma espiral/enrolamento com ~1.5 voltas
    ctx.save();
    const tailBase=[0, S*0.56];
    // desenhamos arcos concêntricos que simulam o enrolamento
    // raio diminui conforme enrola
    for(let loop=0;loop<8;loop++){
      const frac=loop/7;
      const r=S*(0.28-frac*0.22);
      const cx2=tailBase[0]-S*0.18+Math.sin(t*0.5)*S*0.04;
      const cy2=tailBase[1]+S*0.32;
      const startA=(-Math.PI*0.3)+(frac*Math.PI*1.6);
      const endA=startA+Math.PI*0.9;
      const lw=Math.max(1.2, 8-loop*0.9);
      ctx.beginPath();ctx.arc(cx2,cy2,r,startA,endA);
      stroke(lw+1.5,pRed);ctx.stroke();
      stroke(lw*0.35,pBlack);ctx.stroke();
    }
    // hastes conectando o corpo até a espiral
    ctx.beginPath();ctx.moveTo(0,S*0.52);ctx.lineTo(-S*0.1,S*0.72);ctx.lineTo(-S*0.18,S*0.88);
    stroke(7,pRed);ctx.stroke();stroke(2.2,pBlack);ctx.stroke();
    ctx.restore();

    // ═══ PERNAS — 4, abertas lateralmente, cada uma com fase independente ═══
    const isMoving=(b.camState==='move');
    const tL=t*2.2;
    // [ombro x, ombro y, joelho x, joelho y, pé x, pé y, fase]
    // Na imagem: pernas dianteiras abertas pro lado+frente; traseiras pro lado+trás
    const legDefs=[
      [-S*0.28,-S*0.12, -S*0.46,-S*0.26, -S*0.58,-S*0.14, 0.0],
      [ S*0.28,-S*0.12,  S*0.46,-S*0.26,  S*0.58,-S*0.14, Math.PI],
      [-S*0.28, S*0.18, -S*0.48, S*0.30, -S*0.60, S*0.18, Math.PI*0.7],
      [ S*0.28, S*0.18,  S*0.48, S*0.30,  S*0.60, S*0.18, Math.PI*1.7],
    ];
    ctx.save();
    legDefs.forEach(([ox,oy,kx,ky,fx,fy,ph])=>{
      const amp=isMoving?S*0.14:S*0.03;
      const osc=Math.sin(tL+ph)*amp;
      const osc2=Math.sin(tL+ph+0.8)*amp*0.6;
      const jx=kx+osc2, jy=ky+osc*0.5;
      const px=fx+osc*0.7, py=fy+osc;
      // coxa
      ctx.beginPath();ctx.moveTo(ox,oy);ctx.lineTo(jx,jy);
      stroke(6,pRed);ctx.stroke();stroke(2,pBlack);ctx.stroke();
      // canela
      ctx.beginPath();ctx.moveTo(jx,jy);ctx.lineTo(px,py);
      stroke(4.5,pRed);ctx.stroke();stroke(1.5,pBlack);ctx.stroke();
      // 4 garras em leque
      const clawDir=Math.atan2(py-jy,px-jx);
      [-0.55,-0.18,0.18,0.55].forEach(da=>{
        ctx.beginPath();ctx.moveTo(px,py);
        ctx.lineTo(px+Math.cos(clawDir+da)*S*0.13, py+Math.sin(clawDir+da)*S*0.13);
        stroke(1.5,pRedB);ctx.stroke();
      });
    });
    ctx.restore();

    // ═══ CORPO OVAL GRANDE — preto preenchido, contorno vermelho ═══
    ctx.save();
    // oval principal (bem grande como na imagem)
    ctx.beginPath();ctx.ellipse(0, S*0.08, S*0.38, S*0.56, 0, 0, Math.PI*2);
    ctx.fillStyle=pBlack;ctx.fill();
    stroke(2.2,pRed);ctx.stroke();

    // escamas chevron no centro (as marcas diagonais da imagem)
    const nChev=phase===1?4:phase===2?5:6;
    for(let i=0;i<nChev;i++){
      const cy=S*(-0.22+i*0.18);
      const w=S*(0.18-Math.abs(cy/S)*0.2)*0.9;
      const anim=Math.sin(t*1.8+i*0.7)*S*0.012;
      ctx.beginPath();
      ctx.moveTo(-w, cy+anim);
      ctx.lineTo(0, cy-S*0.07+anim);
      ctx.lineTo(w, cy+anim);
      stroke(1.6,pRed);ctx.stroke();
    }
    ctx.restore();

    // ═══ ESPINHOS NO PESCOÇO/OMBRO — pequenos, entre corpo e cabeça ═══
    ctx.save();
    const nSp=phase===1?5:phase===2?7:9;
    for(let i=0;i<nSp;i++){
      const sf=(i/(nSp-1))-0.5; // -0.5 a +0.5
      const spx=sf*S*0.52;
      const spy=-S*0.48;
      const spLen=S*(0.12+0.04*Math.abs(sf))*(0.8+0.2*Math.sin(t*3+i*1.3));
      // espinhos apontam pra cima e pra fora (leque)
      const spAng=-Math.PI/2 + sf*0.9;
      ctx.beginPath();
      ctx.moveTo(spx,spy);
      ctx.lineTo(spx+Math.cos(spAng)*spLen, spy+Math.sin(spAng)*spLen);
      stroke(1.8,pRedB);ctx.stroke();
    }
    ctx.restore();

    // ═══ CABEÇA TRIANGULAR — crista em leque no topo ═══
    ctx.save();
    ctx.translate(0,-S*0.64);

    // crista em leque (espinhos no alto da cabeça)
    const nCrest=phase===1?5:phase===2?6:8;
    for(let i=0;i<nCrest;i++){
      const sf=(i/(nCrest-1))-0.5;
      const cx2=sf*S*0.38;
      const cLen=S*(0.26+0.1*(1-Math.abs(sf*2)))*(0.82+0.18*Math.sin(t*2.2+i*0.8));
      const cAng=-Math.PI/2+sf*0.52;
      ctx.beginPath();ctx.moveTo(cx2,0);
      ctx.lineTo(cx2+Math.cos(cAng)*cLen, Math.sin(cAng)*cLen);
      stroke(2.2,pRed);ctx.stroke();
    }

    // crânio: triângulo com laterais suavemente curvadas (borda circular mas forma triangular)
    ctx.beginPath();
    ctx.moveTo(0, -S*0.36);                          // ponta do focinho
    ctx.quadraticCurveTo(-S*0.22,-S*0.10, -S*0.32, S*0.20); // lateral esq levemente curva
    ctx.lineTo( S*0.32, S*0.20);                     // base reta
    ctx.quadraticCurveTo( S*0.22,-S*0.10,  0,      -S*0.36); // lateral dir
    ctx.closePath();
    ctx.fillStyle=pBlack;ctx.fill();
    stroke(2,pRed);ctx.stroke();

    // sulco central
    ctx.beginPath();ctx.moveTo(0,-S*0.32);ctx.lineTo(0,S*0.16);
    stroke(1.4,pBlack);ctx.stroke();

    // narinas
    ctx.fillStyle=pRed;
    ctx.beginPath();ctx.arc(-S*0.05,-S*0.28,S*0.025,0,Math.PI*2);ctx.fill();
    ctx.beginPath();ctx.arc( S*0.05,-S*0.28,S*0.025,0,Math.PI*2);ctx.fill();

    // OLHOS — diretamente na lateral do triângulo, sem pedúnculo
    // posição nos cantos laterais do triângulo (onde a largura é maior)
    // varredura independente: o globo se desloca levemente sobre a superfície
    const eyeScanL=Math.sin(t*0.85)*0.18+Math.sin(t*1.9)*0.08;
    const eyeScanR=Math.sin(t*0.85+Math.PI)*0.18+Math.sin(t*1.6)*0.08;
    // olho esq: encaixado no lado esquerdo do triângulo, ~meio da altura
    [[-S*0.26, S*0.04, eyeScanL],
     [ S*0.26, S*0.04, eyeScanR]].forEach(([ex,ey,scan])=>{
      // pequeno deslocamento de varredura no eixo Y (olho se move pra cima/baixo)
      const eox=ex, eoy=ey+scan*S*0.12;
      // globo diretamente na cabeça — sem haste
      ctx.beginPath();ctx.arc(eox,eoy,S*0.115,0,Math.PI*2);
      ctx.fillStyle=pBlack;ctx.fill();stroke(1.8,pRedB);ctx.stroke();
      // íris vermelha
      ctx.beginPath();ctx.arc(eox,eoy,S*0.068,0,Math.PI*2);
      ctx.fillStyle=pRed;ctx.fill();
      // pupila vertical
      ctx.beginPath();ctx.ellipse(eox,eoy,S*0.024,S*0.055,0,0,Math.PI*2);
      ctx.fillStyle=pBlack;ctx.fill();
      // brilho
      ctx.beginPath();ctx.arc(eox-S*0.03,eoy-S*0.03,S*0.02,0,Math.PI*2);
      ctx.fillStyle=`rgba(255,80,40,0.7)`;ctx.fill();
    });

    // língua bifurcada
    if(!b.camHiding){
      const tExt=0.38+0.62*Math.abs(Math.sin(t*3.8));
      const tLen=S*0.38*tExt;
      ctx.beginPath();ctx.moveTo(0,-S*0.30);ctx.lineTo(0,-S*0.30-tLen*0.6);
      stroke(1.8,pRed);ctx.stroke();
      ctx.beginPath();ctx.moveTo(0,-S*0.30-tLen*0.6);ctx.lineTo(-S*0.08,-S*0.30-tLen);
      stroke(1.2,pRedB);ctx.stroke();
      ctx.beginPath();ctx.moveTo(0,-S*0.30-tLen*0.6);ctx.lineTo(S*0.08,-S*0.30-tLen);
      stroke(1.2,pRedB);ctx.stroke();
    }
    ctx.restore(); // fim cabeça

    // ═══ HP BAR ═══
    ctx.save();
    ctx.rotate(-(headA+Math.PI/2));
    const hpPct=b.formHP/b.formMaxHP;
    const barW=S*2.4,barH=6;
    ctx.globalAlpha=Math.min(1,camA*1.5);
    ctx.fillStyle='rgba(0,0,0,0.7)';ctx.fillRect(-barW/2,S*0.82,barW,barH);
    ctx.fillStyle=hpPct>0.5?'#cc1100':hpPct>0.25?'#881100':'#ff3300';
    ctx.fillRect(-barW/2,S*0.82,barW*hpPct,barH);
    ctx.strokeStyle='rgba(220,40,10,0.5)';ctx.lineWidth=0.8;ctx.strokeRect(-barW/2,S*0.82,barW,barH);
    ctx.font='bold 8px monospace';ctx.textAlign='center';ctx.fillStyle=pRedB;
    ctx.fillText(`🦎 ${Math.ceil(b.formHP)}/${b.formMaxHP}`,0,S*0.82+barH+10);
    ctx.restore();

    // ═══ FLASH + GLITCH ═══
    if(b.flashT>0){
      b.flashT-=0.016;
      ctx.save();ctx.globalCompositeOperation='screen';ctx.globalAlpha=b.flashT*1.4;
      ctx.beginPath();ctx.ellipse(0,0,S*0.95,S*1.15,0,0,Math.PI*2);
      ctx.fillStyle=b.flashColor||'#ff2200';ctx.fill();ctx.restore();
    }
    if(gi>0.07){
      const bars=Math.ceil(gi*7);
      for(let i=0;i<bars;i++){
        ctx.beginPath();ctx.rect(rand(-S,S),rand(-S*0.9,S*0.9),rand(S*0.3,S),rand(2,4));
        ctx.fillStyle=`rgba(200,10,5,${gi*0.28})`;ctx.fill();
      }
    }
    ctx.restore();
  }

  // ══════════════════════════════════════════════════════════════════
  //  FORMA 3: DRAGÃO — chefe final
  //  Cabeça triangular/focinho angular. Animações em todas as partes.
  //  Paleta preta/vermelho, escamas individuais estilo Serpente.
  // ══════════════════════════════════════════════════════════════════
  function _drawBossDragao(ctx,b,t){
    const gi=b.glitchIntensity||0;
    const phase=_getReptBossPhase();
    const ws=b.wingSpread||0;

    // ── Paleta ──────────────────────────────────────────────────────
    const BLK='#020000';
    const PLT='#0e0101';
    const EDG='#cc1400';
    const VNE='#ff2600';
    const SCL='#180303';
    const JNT='#080000';

    // ── Pulsos animados ──────────────────────────────────────────────
    const pulse  = 0.5+0.5*Math.sin(t*4.2);
    const pulse2 = 0.5+0.5*Math.sin(t*2.8+1.1);
    const sway   = Math.sin(t*1.1)*6;          // balanço lateral do corpo
    const breathe= Math.sin(t*2.2)*2;          // respiração do tronco

    ctx.save();
    ctx.translate(b.x,b.y);
    if(gi>0.07) ctx.translate(rand(-gi*5,gi*5),rand(-gi*4,gi*4));
    ctx.lineCap='round'; ctx.lineJoin='round';

    const stk=(w,c)=>{ctx.lineWidth=w;ctx.strokeStyle=c;};
    const fll=(c)=>{ctx.fillStyle=c;};

    // ── Escama individual: losango com gradiente e costela central ──
    function esc(cx,cy,w,h,ang,lit){
      ctx.save();ctx.translate(cx,cy);ctx.rotate(ang);
      ctx.beginPath();
      ctx.moveTo(0,-h);ctx.lineTo(w,0);ctx.lineTo(0,h);ctx.lineTo(-w,0);
      ctx.closePath();
      const g=ctx.createLinearGradient(-w,0,w,0);
      g.addColorStop(0,JNT);g.addColorStop(0.5,lit?PLT:SCL);g.addColorStop(1,JNT);
      ctx.fillStyle=g;ctx.fill();
      stk(0.8,EDG+'aa');ctx.stroke();
      ctx.beginPath();ctx.moveTo(0,-h*.65);ctx.lineTo(0,h*.65);
      stk(0.4,VNE+'44');ctx.stroke();
      ctx.restore();
    }

    // ── AURA ────────────────────────────────────────────────────────
    {
      const ag=ctx.createRadialGradient(sway*.3,0,10,sway*.3,0,105);
      ag.addColorStop(0,'rgba(130,0,0,0.18)');ag.addColorStop(1,'rgba(0,0,0,0)');
      ctx.save();ctx.beginPath();ctx.arc(sway*.3,0,105,0,Math.PI*2);
      ctx.fillStyle=ag;ctx.fill();ctx.restore();
    }

    // ════════════════════════════════════════════════════════════════
    // CAUDA — serpenteia com seno, 6 segmentos decrescentes
    // ════════════════════════════════════════════════════════════════
    {
      // Cada segmento tem posição calculada por seno com offset de fase
      const N=7;
      const tail=[];
      for(let i=0;i<N;i++){
        const prog=(i+1)/N;
        const swayT=Math.sin(t*1.8+i*0.7)*14*prog; // serpenteia mais na ponta
        tail.push({
          x: sway*0.4 + swayT,
          y: 55+i*14,
          r: Math.max(2,12-i*1.4),
        });
      }
      // Corpo da cauda
      for(let i=1;i<tail.length;i++){
        const a=tail[i-1],c2=tail[i];
        ctx.beginPath();ctx.moveTo(a.x,a.y);ctx.lineTo(c2.x,c2.y);
        stk(a.r*2+2,BLK);ctx.stroke();
        stk(a.r*2,PLT);ctx.stroke();
        stk(1,EDG);ctx.stroke();
      }
      // Espinhos dorsais da cauda
      for(let i=0;i<tail.length-1;i++){
        const a=tail[i],c2=tail[i+1];
        const mx=(a.x+c2.x)/2,my=(a.y+c2.y)/2;
        const ang=Math.atan2(c2.y-a.y,c2.x-a.x)-Math.PI/2;
        const sh=a.r*0.85*(0.82+0.18*Math.sin(t*3.1+i*0.9));
        ctx.beginPath();
        ctx.moveTo(mx-Math.cos(ang+Math.PI/2)*a.r*.5,my-Math.sin(ang+Math.PI/2)*a.r*.5);
        ctx.lineTo(mx+Math.cos(ang)*sh,my+Math.sin(ang)*sh);
        ctx.lineTo(mx+Math.cos(ang+Math.PI/2)*a.r*.5,my+Math.sin(ang+Math.PI/2)*a.r*.5);
        ctx.closePath();
        fll(SCL);ctx.fill();stk(0.8,EDG);ctx.stroke();
      }
      // Ferrão
      const tp=tail[tail.length-1];
      ctx.beginPath();ctx.moveTo(tp.x-3,tp.y);ctx.lineTo(tp.x+8,tp.y-6);ctx.lineTo(tp.x,tp.y+8);
      ctx.closePath();fll(EDG);ctx.fill();stk(0.8,VNE);ctx.stroke();
    }

    // ════════════════════════════════════════════════════════════════
    // ASAS — batem com seno, costelas e escamas nas membranas
    // ════════════════════════════════════════════════════════════════
    if(ws>0.02){
      const wFlap=Math.sin(t*3.2)*58*ws;   // batida expressiva forte
      const wFlap2=Math.sin(t*3.2+0.5)*34*ws;
      [-1,1].forEach(s=>{
        const WX=ws*(155+phase*18)*s;
        // Membrana principal
        ctx.beginPath();
        ctx.moveTo(s*16+sway*.2,-22);
        ctx.lineTo(WX*.48,-58+wFlap);
        ctx.lineTo(WX*.90,-6+wFlap2);
        ctx.lineTo(WX*.64,30+wFlap*.25);
        ctx.lineTo(s*14+sway*.2,14);
        ctx.closePath();
        fll(BLK);ctx.fill();stk(2,EDG);ctx.stroke();
        // Membrana translúcida interna
        ctx.save();ctx.globalAlpha=0.14+0.08*ws*pulse;
        ctx.beginPath();
        ctx.moveTo(s*16+sway*.2,-22);
        ctx.lineTo(WX*.48,-58+wFlap);
        ctx.lineTo(WX*.90,-6+wFlap2);
        ctx.lineTo(s*12,-4);
        ctx.closePath();
        fll(VNE);ctx.fill();ctx.restore();
        // 4 costelas com escamas
        const ribs=[
          [s*16+sway*.2,-22, WX*.48,-58+wFlap, 3.8],
          [s*13,-4,  WX*.90,-6+wFlap2, 3.0],
          [s*14, 6,  WX*.75,14+wFlap*.3, 2.2],
          [s*14,14,  WX*.64,30+wFlap*.25,1.6],
        ];
        ribs.forEach(([x1,y1,x2,y2,rw])=>{
          ctx.beginPath();ctx.moveTo(x1,y1);ctx.lineTo(x2,y2);
          stk(rw+2,BLK);ctx.stroke();stk(rw,PLT);ctx.stroke();stk(.9,EDG);ctx.stroke();
          for(let ri=1;ri<=3;ri++){
            const rf=ri/4;
            esc(x1+(x2-x1)*rf,y1+(y2-y1)*rf,rw*1.2,rw*.7,Math.atan2(y2-y1,x2-x1)+Math.PI/2,ri===2);
          }
        });
        // Garra na ponta superior
        const gx=WX*.48,gy=-58+wFlap;
        ctx.beginPath();ctx.moveTo(gx,gy);ctx.lineTo(gx+s*8,gy-20);
        stk(2.5,BLK);ctx.stroke();stk(1.2,EDG);ctx.stroke();
        ctx.beginPath();ctx.moveTo(gx+s*8,gy-20);ctx.lineTo(gx+s*14,gy-26);ctx.lineTo(gx+s*4,gy-22);
        ctx.closePath();fll(EDG);ctx.fill();
      });
    }

    // ════════════════════════════════════════════════════════════════
    // PERNAS — joelhos dobram com seno alternado
    // ════════════════════════════════════════════════════════════════
    [-1,1].forEach((s,li)=>{
      const step=Math.sin(t*2.1+li*Math.PI)*18;
      const shx=s*18+sway*.15, shy=32;
      const knx=s*(40+step*.3), kny=56+Math.abs(step)*.4;
      const ftx=s*(32-step*.2), fty=76+step*.3;
      // Coxa
      ctx.beginPath();ctx.moveTo(shx,shy);ctx.lineTo(knx,kny);
      stk(12,BLK);ctx.stroke();stk(8,PLT);ctx.stroke();stk(1.4,EDG);ctx.stroke();
      for(let si=1;si<=3;si++){
        const sf=si/4;
        esc(shx+(knx-shx)*sf,shy+(kny-shy)*sf,5,3,Math.atan2(kny-shy,knx-shx)+Math.PI/2,si===2);
      }
      // Joelho
      ctx.beginPath();ctx.arc(knx,kny,5.5,0,Math.PI*2);
      fll(JNT);ctx.fill();stk(1,EDG);ctx.stroke();
      // Canela
      ctx.beginPath();ctx.moveTo(knx,kny);ctx.lineTo(ftx,fty);
      stk(8,BLK);ctx.stroke();stk(5.5,PLT);ctx.stroke();stk(1,EDG);ctx.stroke();
      for(let si=1;si<=2;si++){
        const sf=si/3;
        esc(knx+(ftx-knx)*sf,kny+(fty-kny)*sf,3.8,2.2,Math.atan2(fty-kny,ftx-knx)+Math.PI/2,si===1);
      }
      // Pé + garras
      ctx.beginPath();ctx.arc(ftx,fty,4.5,0,Math.PI*2);fll(JNT);ctx.fill();stk(.9,EDG);ctx.stroke();
      const fd=Math.atan2(fty-kny,ftx-knx);
      [-0.5,-0.15,0.2,0.55].forEach((da,gi2)=>{
        const cl=12+gi2*1.5;
        ctx.beginPath();ctx.moveTo(ftx,fty);
        ctx.lineTo(ftx+Math.cos(fd+da)*cl,fty+Math.sin(fd+da)*cl);
        stk(2.5,BLK);ctx.stroke();stk(1.2,EDG);ctx.stroke();
        ctx.beginPath();ctx.arc(ftx+Math.cos(fd+da)*cl,fty+Math.sin(fd+da)*cl,1.8,0,Math.PI*2);
        fll(VNE);ctx.fill();
      });
    });

    // ════════════════════════════════════════════════════════════════
    // BRAÇOS — alcançam para frente com seno alternado
    // ════════════════════════════════════════════════════════════════
    [-1,1].forEach((s,ai)=>{
      const reach=Math.sin(t*1.9+ai*Math.PI+0.5)*18;
      const shx=s*16+sway*.1, shy=-10;
      const elx=s*(38+reach*.4)+sway*.05, ely=10+reach*.5;
      const hdx=s*(28+reach*.2), hdy=26+reach*.6;
      // Braço
      ctx.beginPath();ctx.moveTo(shx,shy);ctx.lineTo(elx,ely);
      stk(10,BLK);ctx.stroke();stk(7,PLT);ctx.stroke();stk(1.2,EDG);ctx.stroke();
      for(let si=1;si<=2;si++){
        const sf=si/3;
        esc(shx+(elx-shx)*sf,shy+(ely-shy)*sf,4,2.4,Math.atan2(ely-shy,elx-shx)+Math.PI/2,si===2);
      }
      // Cotovelo
      ctx.beginPath();ctx.arc(elx,ely,5,0,Math.PI*2);fll(JNT);ctx.fill();stk(1,EDG);ctx.stroke();
      // Antebraço
      ctx.beginPath();ctx.moveTo(elx,ely);ctx.lineTo(hdx,hdy);
      stk(7,BLK);ctx.stroke();stk(5,PLT);ctx.stroke();stk(1,EDG);ctx.stroke();
      esc((elx+hdx)/2,(ely+hdy)/2,3.5,2,Math.atan2(hdy-ely,hdx-elx)+Math.PI/2,true);
      // Pulso
      ctx.beginPath();ctx.arc(hdx,hdy,4,0,Math.PI*2);fll(JNT);ctx.fill();stk(.9,EDG);ctx.stroke();
      // 3 garras
      const hd=Math.atan2(hdy-ely,hdx-elx);
      [-0.4,0,0.4].forEach(da=>{
        ctx.beginPath();ctx.moveTo(hdx,hdy);
        ctx.lineTo(hdx+Math.cos(hd+da)*11,hdy+Math.sin(hd+da)*11);
        stk(2,BLK);ctx.stroke();stk(1,VNE);ctx.stroke();
        ctx.beginPath();ctx.arc(hdx+Math.cos(hd+da)*11,hdy+Math.sin(hd+da)*11,1.6,0,Math.PI*2);
        fll(VNE);ctx.fill();
      });
    });

    // ════════════════════════════════════════════════════════════════
    // CORPO — armadura de placas trapezoidais sobrepostas
    // 8 cinturões de trapézios, respiração modula larguras, núcleo central
    // ════════════════════════════════════════════════════════════════
    ctx.save();ctx.translate(sway*.3,0);

    // helper: desenha um trapézio de armadura entre duas alturas
    // wT=meia-largura do topo, wB=meia-largura da base
    function trap(y0,y1,wT,wB,fill,strokeW,strokeC,detail){
      ctx.beginPath();
      ctx.moveTo(-wT,y0);ctx.lineTo(wT,y0);
      ctx.lineTo(wB,y1);ctx.lineTo(-wB,y1);
      ctx.closePath();
      ctx.fillStyle=fill;ctx.fill();
      stk(strokeW,strokeC);ctx.stroke();
      if(detail){
        // linha de detalhe horizontal interna
        const my=(y0+y1)/2;
        ctx.beginPath();ctx.moveTo(-wT*.7,my);ctx.lineTo(wT*.7,my);
        stk(0.5,strokeC+'55');ctx.stroke();
      }
    }

    // helper: rebite em posição absoluta
    function rivet(x,y){
      ctx.beginPath();ctx.rect(x-1.8,y-1.8,3.6,3.6);
      ctx.fillStyle=EDG;ctx.fill();
    }

    const br=breathe; // ±2px respiração

    // ── Cinturão 0: OMBROS (topo, largo e baixo) ─────────────────
    trap(-38,-24, 10, 26+br, BLK, 2.0, EDG, false);
    // placas laterais dos ombros (triângulos)
    [-1,1].forEach(s=>{
      ctx.beginPath();ctx.moveTo(s*10,-38);ctx.lineTo(s*(26+br),-24);ctx.lineTo(s*(32+br),-32);ctx.closePath();
      ctx.fillStyle=PLT;ctx.fill();stk(1.4,EDG);ctx.stroke();
      rivet(s*20,-30); rivet(s*28,-26);
    });
    // sulco do ombro
    ctx.beginPath();ctx.moveTo(-(26+br),-24);ctx.lineTo(26+br,-24);stk(1.0,EDG+'66');ctx.stroke();

    // ── Cinturão 1: PEITO SUPERIOR ───────────────────────────────
    trap(-24,-10, 26+br, 30+br, BLK, 1.8, EDG, true);
    [-1,1].forEach(s=>{
      // placa de costela externa
      ctx.beginPath();ctx.moveTo(s*(26+br),-24);ctx.lineTo(s*(34+br),-18);ctx.lineTo(s*(32+br),-10);ctx.lineTo(s*(30+br),-10);ctx.closePath();
      ctx.fillStyle=SCL;ctx.fill();stk(1.2,EDG);ctx.stroke();
      rivet(s*28,-17); rivet(s*(26+br),-24);
    });

    // ── Cinturão 2: PEITO CENTRAL (mais largo — ponto de máx largura) ─
    trap(-10, 6, 30+br, 32+br, PLT, 1.8, EDG, false);
    // Núcleo de energia pulsante (no centro desta placa)
    {
      const ep=0.45+0.45*Math.sin(t*5.0);
      // Aura
      ctx.save();ctx.globalAlpha=0.22*ep;
      ctx.beginPath();ctx.ellipse(0,-2,18+ep*4,10+ep*2,0,0,Math.PI*2);
      ctx.fillStyle='rgba(200,0,0,1)';ctx.fill();ctx.restore();
      // Losango do núcleo
      ctx.beginPath();ctx.moveTo(0,-13+ep);ctx.lineTo(12+ep,0);ctx.lineTo(0,11+ep);ctx.lineTo(-12-ep,0);ctx.closePath();
      ctx.fillStyle=`rgba(${148+Math.floor(107*ep)},0,0,0.95)`;ctx.fill();stk(1.2,VNE);ctx.stroke();
      // Ponto central
      ctx.beginPath();ctx.arc(0,0,3.5+ep*1.5,0,Math.PI*2);
      ctx.fillStyle=`rgba(255,${12+Math.floor(25*ep)},0,${0.9+0.1*ep})`;ctx.fill();
      // Scan lines no núcleo
      ctx.save();ctx.globalAlpha=0.18+0.14*ep;
      [-8,-4,0,4,8].forEach(ly=>{
        ctx.beginPath();ctx.moveTo(-10,ly);ctx.lineTo(10,ly);stk(0.6,'#ff3300');ctx.stroke();
      });
      ctx.restore();
    }
    // costelas do peito central
    [-1,1].forEach(s=>{
      ctx.beginPath();ctx.moveTo(s*(30+br),-10);ctx.lineTo(s*(34+br),-4);ctx.lineTo(s*(34+br),6);ctx.lineTo(s*(32+br),6);ctx.closePath();
      ctx.fillStyle=SCL;ctx.fill();stk(1.2,EDG);ctx.stroke();
      rivet(s*32,-6);
    });

    // ── Cinturão 3: ABDÔMEN SUPERIOR ─────────────────────────────
    trap( 6, 20, 32+br, 28, BLK, 1.8, EDG, true);
    [-1,1].forEach(s=>{
      ctx.beginPath();ctx.moveTo(s*(32+br),6);ctx.lineTo(s*30,12);ctx.lineTo(s*28,20);ctx.lineTo(s*(28),20);ctx.closePath();
      ctx.fillStyle=PLT;ctx.fill();stk(1.1,EDG);ctx.stroke();
      rivet(s*29,13);
    });

    // ── Cinturão 4: ABDÔMEN CENTRAL ──────────────────────────────
    trap(20, 34, 28, 24, SCL, 1.6, EDG, true);
    [-1,1].forEach(s=>{ rivet(s*22,27); rivet(s*18,31); });

    // ── Cinturão 5: ABDÔMEN INFERIOR ─────────────────────────────
    trap(34, 46, 24, 18, PLT, 1.6, EDG, false);
    ctx.beginPath();ctx.moveTo(-18,40);ctx.lineTo(18,40);stk(0.8,EDG+'55');ctx.stroke();
    [-1,1].forEach(s=>{ rivet(s*14,37); rivet(s*10,43); });

    // ── Cinturão 6: QUADRIL ───────────────────────────────────────
    trap(46, 56, 18, 12, BLK, 1.4, EDG, false);
    [-1,1].forEach(s=>{ rivet(s*10,51); });

    // ── Cinturão 7: BASE (entrelaça com as pernas) ────────────────
    trap(56, 64, 12,  6, SCL, 1.2, EDG, false);

    ctx.restore(); // fim corpo translate

    // ════════════════════════════════════════════════════════════════
    // ESPINHOS DORSAIS — crista ao longo do corpo, pulsam individualmente
    // ════════════════════════════════════════════════════════════════
    ctx.save();ctx.translate(sway*.25,0);
    [{y:-35,h:15,w:4},{y:-24,h:11,w:3.2},{y:-13,h:9,w:2.8},
     {y:0,h:7.5,w:2.4},{y:12,h:6,w:2.1},{y:24,h:5,w:1.8},{y:36,h:3.5,w:1.5}]
    .forEach(({y,h,w},di)=>{
      const sp=0.86+0.14*Math.sin(t*2.8+di*0.85);
      ctx.beginPath();ctx.moveTo(-w*.7,y+h*.15);ctx.lineTo(0,y-h*sp);ctx.lineTo(w*.7,y+h*.15);
      ctx.closePath();fll(SCL);ctx.fill();stk(.8,EDG);ctx.stroke();
      ctx.beginPath();ctx.moveTo(0,y-h*.75*sp);ctx.lineTo(0,y+h*.1);stk(.4,VNE+'55');ctx.stroke();
    });
    ctx.restore();

    // ════════════════════════════════════════════════════════════════
    // PESCOÇO — trapézio estrutural desenhado antes da cabeça/ombros
    // Fica atrás da cabeça, visível apenas onde não coberto por ela
    // ════════════════════════════════════════════════════════════════
    ctx.save();ctx.translate(sway*.4,0);
    ctx.beginPath();
    ctx.moveTo(-9,-38);ctx.lineTo(9,-38);   // base (topo do tronco)
    ctx.lineTo(6,-52);ctx.lineTo(-6,-52);   // topo (sob a cabeça)
    ctx.closePath();
    ctx.fillStyle=BLK;ctx.fill();stk(1.6,EDG);ctx.stroke();
    ctx.restore();

    // ════════════════════════════════════════════════════════════════
    // CABEÇA — +20% escala, visor tecnológico destrutivo
    // Crânio em V + visor horizontal pulsante + painéis de armadura
    // Coords rel. a translate(sway*.4,-44) + scale(1.2,1.2)
    // ════════════════════════════════════════════════════════════════
    ctx.save();
    ctx.translate(sway*.4, -44);
    ctx.scale(1.2, 1.2);

    // ══ CHIFRES — espinhos retos, afastados nas extremidades da cabeça ──
    [-1,1].forEach(s=>{
      ctx.save(); ctx.translate(s*10, 0);
      // Chifre principal
      ctx.beginPath();
      ctx.moveTo(s*10,-28);
      ctx.lineTo(s*18,-38);
      ctx.lineTo(s*22,-58);
      ctx.lineTo(s*14,-72);
      ctx.lineTo(s*10,-70);
      ctx.lineTo(s*16,-56);
      ctx.lineTo(s*14,-36);
      ctx.lineTo(s*8,-28);
      ctx.closePath();
      const hg=ctx.createLinearGradient(s*10,-28,s*14,-72);
      hg.addColorStop(0,PLT);hg.addColorStop(0.7,'#0c0101');hg.addColorStop(1,EDG);
      ctx.fillStyle=hg;ctx.fill();stk(1.2,EDG);ctx.stroke();
      ctx.beginPath();ctx.moveTo(s*18,-44);ctx.lineTo(s*26,-50);ctx.lineTo(s*24,-53);ctx.lineTo(s*17,-46);ctx.closePath();
      fll(SCL);ctx.fill();stk(0.8,EDG);ctx.stroke();
      ctx.beginPath();ctx.moveTo(s*19,-54);ctx.lineTo(s*26,-58);ctx.lineTo(s*25,-61);ctx.lineTo(s*18,-56);ctx.closePath();
      fll(SCL);ctx.fill();stk(0.8,EDG);ctx.stroke();
      ctx.beginPath();
      ctx.moveTo(s*5,-26);ctx.lineTo(s*8,-34);ctx.lineTo(s*10,-48);ctx.lineTo(s*7,-50);
      ctx.lineTo(s*6,-36);ctx.lineTo(s*4,-28);ctx.closePath();
      const hg2=ctx.createLinearGradient(s*5,-26,s*8,-50);
      hg2.addColorStop(0,'#0e0101');hg2.addColorStop(1,EDG);
      ctx.fillStyle=hg2;ctx.fill();stk(0.9,EDG);ctx.stroke();
      ctx.restore();
    });

    // ══ PONTA CENTRAL (flecha no topo) ───────────────────────────────
    {
      const sp=0.82+0.18*Math.sin(t*2.4);
      ctx.beginPath();
      ctx.moveTo(-3,-38);ctx.lineTo(0,-38-15*sp);ctx.lineTo(3,-38);
      ctx.closePath();
      const sg=ctx.createLinearGradient(0,-38,0,-53);
      sg.addColorStop(0,PLT);sg.addColorStop(0.5,SCL);sg.addColorStop(1,EDG);
      ctx.fillStyle=sg;ctx.fill();stk(1,EDG);ctx.stroke();
    }

    // ══ CRÂNIO + FACE EM V — polígono base ───────────────────────────
    ctx.beginPath();
    ctx.moveTo(-6,-38);ctx.lineTo(6,-38);
    ctx.lineTo(22,-30);ctx.lineTo(24,-23);
    ctx.lineTo(18,-17);ctx.lineTo(0,-6);
    ctx.lineTo(-18,-17);ctx.lineTo(-24,-23);ctx.lineTo(-22,-30);
    ctx.closePath();
    fll(BLK);ctx.fill();stk(2.2,EDG);ctx.stroke();

    // Volume interno
    {
      const vg=ctx.createRadialGradient(0,-24,1,0,-24,24);
      vg.addColorStop(0,'rgba(22,1,1,0.9)');vg.addColorStop(0.65,'rgba(6,0,0,0.3)');vg.addColorStop(1,'rgba(0,0,0,0)');
      ctx.save();ctx.beginPath();
      ctx.moveTo(-6,-38);ctx.lineTo(6,-38);ctx.lineTo(22,-30);ctx.lineTo(24,-23);
      ctx.lineTo(18,-17);ctx.lineTo(0,-6);ctx.lineTo(-18,-17);ctx.lineTo(-24,-23);ctx.lineTo(-22,-30);
      ctx.closePath();ctx.fillStyle=vg;ctx.fill();ctx.restore();
    }

    // ══ PAINÉIS SUPERIORES (acima do visor) ──────────────────────────
    [-1,1].forEach(s=>{
      // Painel temporal: triângulo entre topo e borda do visor
      ctx.beginPath();ctx.moveTo(s*4,-38);ctx.lineTo(s*22,-30);ctx.lineTo(s*20,-29);ctx.lineTo(s*4,-34);ctx.closePath();
      fll(SCL);ctx.fill();stk(0.8,EDG+'99');ctx.stroke();
      // Detalhe angular no painel
      ctx.beginPath();ctx.moveTo(s*8,-37);ctx.lineTo(s*19,-31);stk(0.7,EDG+'55');ctx.stroke();
      ctx.beginPath();ctx.moveTo(s*12,-37);ctx.lineTo(s*21,-31);stk(0.5,EDG+'33');ctx.stroke();
      // Rebite de canto
      ctx.beginPath();ctx.rect(s*18-1.5,-32-1.5,3,3);fll(EDG);ctx.fill();
    });

    // ══ VISOR TECNOLÓGICO — banda horizontal pulsante ─────────────────
    // Cobre a faixa y=-29 a y=-21, de flanco a flanco, seguindo o crânio
    {
      const glow=0.5+0.5*pulse;
      const scan=0.5+0.5*Math.sin(t*5.2); // linha de varredura animada

      // Moldura do visor (trapézio seguindo paredes do crânio)
      ctx.beginPath();
      ctx.moveTo(-22,-29);ctx.lineTo(22,-29);  // borda superior
      ctx.lineTo(24,-21);ctx.lineTo(-24,-21);  // borda inferior
      ctx.closePath();
      ctx.fillStyle=JNT;ctx.fill();stk(1.8,EDG);ctx.stroke();

      // Interior do visor — gradiente vermelho profundo
      const vg=ctx.createLinearGradient(0,-29,0,-21);
      vg.addColorStop(0,`rgba(${Math.floor(60+40*glow)},0,0,1)`);
      vg.addColorStop(0.5,`rgba(${Math.floor(180+60*glow)},${Math.floor(8*glow)},0,1)`);
      vg.addColorStop(1,`rgba(${Math.floor(50+30*glow)},0,0,1)`);
      ctx.beginPath();
      ctx.moveTo(-20,-28);ctx.lineTo(20,-28);
      ctx.lineTo(22,-22);ctx.lineTo(-22,-22);
      ctx.closePath();
      ctx.fillStyle=vg;ctx.fill();

      // Linhas de varredura tech (scan lines horizontais)
      ctx.save();ctx.globalAlpha=0.22;
      for(let sl=0;sl<4;sl++){
        const sy=-28+sl*1.8;
        ctx.beginPath();ctx.moveTo(-20,sy);ctx.lineTo(20,sy);stk(0.6,'#ff2200');ctx.stroke();
      }
      ctx.restore();

      // Linha de scan animada (sweeper)
      const scanX=-20+40*scan;
      ctx.save();ctx.globalAlpha=0.55*glow;
      ctx.beginPath();ctx.moveTo(scanX,-28);ctx.lineTo(scanX+4,-28);ctx.lineTo(scanX+6,-22);ctx.lineTo(scanX+2,-22);ctx.closePath();
      ctx.fillStyle=`rgba(255,${Math.floor(60*glow)},0,1)`;ctx.fill();
      ctx.restore();

      // Divisor central vertical do visor (barra T)
      ctx.beginPath();ctx.moveTo(-1,-29);ctx.lineTo(1,-29);ctx.lineTo(1,-21);ctx.lineTo(-1,-21);ctx.closePath();
      ctx.fillStyle=BLK;ctx.fill();stk(0.6,EDG+'88');ctx.stroke();

      // Brilho superior (reflexo de armadura)
      ctx.save();ctx.globalAlpha=0.18+0.1*glow;
      ctx.beginPath();ctx.moveTo(-20,-28);ctx.lineTo(20,-28);ctx.lineTo(22,-26);ctx.lineTo(-22,-26);ctx.closePath();
      ctx.fillStyle='rgba(255,180,100,1)';ctx.fill();
      ctx.restore();

      // Glow externo do visor (screen blend)
      ctx.save();ctx.globalCompositeOperation='screen';ctx.globalAlpha=0.35*glow;
      const gg=ctx.createRadialGradient(0,-25,0,0,-25,28);
      gg.addColorStop(0,`rgba(255,30,0,1)`);gg.addColorStop(1,'rgba(100,0,0,0)');
      ctx.beginPath();
      ctx.moveTo(-22,-29);ctx.lineTo(22,-29);ctx.lineTo(24,-21);ctx.lineTo(-24,-21);
      ctx.closePath();ctx.fillStyle=gg;ctx.fill();
      ctx.restore();

      // Mira central no visor (targeting pip)
      ctx.save();ctx.globalAlpha=0.7+0.3*glow;
      // Cruz da mira
      ctx.beginPath();ctx.moveTo(-4,-25);ctx.lineTo(4,-25);stk(1.0,`rgba(255,${Math.floor(80+80*glow)},0,1)`);ctx.stroke();
      ctx.beginPath();ctx.moveTo(0,-28);ctx.lineTo(0,-22);stk(1.0,`rgba(255,${Math.floor(80+80*glow)},0,1)`);ctx.stroke();
      // Losango central
      ctx.beginPath();ctx.moveTo(0,-27);ctx.lineTo(2,-25);ctx.lineTo(0,-23);ctx.lineTo(-2,-25);ctx.closePath();
      stk(0.9,`rgba(255,200,0,${0.8+0.2*glow})`);ctx.stroke();
      ctx.restore();

      // Bordas laterais do visor (acabamento tech)
      [-1,1].forEach(s=>{
        ctx.beginPath();ctx.moveTo(s*22,-29);ctx.lineTo(s*24,-21);stk(2.4,EDG);ctx.stroke();
        // Entalhe angular no canto
        ctx.beginPath();ctx.moveTo(s*22,-29);ctx.lineTo(s*20,-29);ctx.lineTo(s*22,-26);ctx.closePath();
        fll(BLK);ctx.fill();
      });
    }

    // ══ VEIAS PULSANTES ──────────────────────────────────────────────
    ctx.save();ctx.globalAlpha=0.15+0.12*pulse;
    [[0,-38,0,-29],[-3,-29,-22,-30],[3,-29,22,-30],
     [-22,-21,-24,-23],[22,-21,24,-23],
     [-24,-23,-18,-17],[24,-23,18,-17],
     [-18,-17,0,-6],[18,-17,0,-6]].forEach(([x1,y1,x2,y2])=>{
      ctx.beginPath();ctx.moveTo(x1,y1);ctx.lineTo(x2,y2);stk(0.8,VNE);ctx.stroke();
    });
    ctx.restore();

    ctx.restore(); // fim cabeça


    // ════════════════════════════════════════════════════════════════
    // HP BAR, FLASH, GLITCH, RUGIDO (fora de qualquer transformação)
    // ════════════════════════════════════════════════════════════════
    ctx.restore(); // fim translate(b.x,b.y)

    // HP Bar
    ctx.save();
    const hpPct=Math.max(0,b.formHP/b.formMaxHP);
    const bW=114,bH=6,barX=b.x-bW/2,barY=b.y+100;
    ctx.fillStyle='#050000';ctx.fillRect(barX,barY,bW,bH);
    ctx.fillStyle=hpPct>.65?EDG:hpPct>.3?'#aa0000':'#ff0000';
    ctx.fillRect(barX,barY,bW*hpPct,bH);
    ctx.strokeStyle=VNE+'44';ctx.lineWidth=.8;ctx.strokeRect(barX,barY,bW,bH);
    ctx.font='bold 9px monospace';ctx.textAlign='center';ctx.fillStyle=VNE;
    ctx.fillText('🐉 '+Math.ceil(b.formHP)+'/'+b.formMaxHP,b.x,barY+bH+12);
    ctx.restore();
    // Flash de dano
    if(b.flashT>0){
      b.flashT-=0.016;
      ctx.save();ctx.globalCompositeOperation='screen';ctx.globalAlpha=b.flashT*1.1;
      ctx.beginPath();ctx.ellipse(b.x,b.y,54,72,0,0,Math.PI*2);
      ctx.fillStyle='#aa0000';ctx.fill();ctx.restore();
    }
    // Glitch
    if(gi>.06){
      for(let i=0;i<Math.ceil(gi*10);i++){
        ctx.beginPath();ctx.rect(b.x+rand(-62,44),b.y+rand(-92,92),rand(20,110),rand(2,5));
        ctx.fillStyle='rgba(155,0,0,'+(gi*.28)+')';ctx.fill();
      }
    }
    // Rugido
    if(b.roarWave>0){
      ctx.save();ctx.globalAlpha=b.roarWave*.18;
      ctx.beginPath();ctx.arc(b.x,b.y,62*(1.5+(1-b.roarWave)*2),0,Math.PI*2);
      ctx.strokeStyle=EDG;ctx.lineWidth=2;ctx.stroke();ctx.restore();
    }
  }

  // ── Draw: clone visual (adapta à forma) ──────────────────────────
  function _drawReptBossClone(ctx,cl,t){
    ctx.save();ctx.globalAlpha=cl.alpha*(cl.camouflageAlpha||1);
    ctx.translate(cl.x,cl.y);ctx.rotate(t*0.22);
    const form=cl.form||'serpente';
    const sz=form==='dragao'?50:form==='camaleao'?46:42;
    const cc=form==='dragao'?'rgba(255,80,0,0.65)':form==='camaleao'?'rgba(200,30,10,0.6)':'rgba(200,0,0,0.6)';
    // Silhueta simplificada por forma
    ctx.beginPath();
    if(form==='dragao'){
      // Diamante largo
      ctx.moveTo(0,-sz);ctx.lineTo(sz*0.8,-sz*0.3);ctx.lineTo(sz*0.6,sz*0.5);ctx.lineTo(0,sz*1.0);ctx.lineTo(-sz*0.6,sz*0.5);ctx.lineTo(-sz*0.8,-sz*0.3);
    } else if(form==='camaleao'){
      // Oval orgânico
      ctx.ellipse(0,0,sz*0.65,sz*0.88,0,0,Math.PI*2);
    } else {
      // Vertical serpentino
      ctx.moveTo(0,-sz);ctx.lineTo(sz*0.6,-sz*0.5);ctx.lineTo(sz*0.7,sz*0.2);ctx.lineTo(sz*0.35,sz*0.9);ctx.lineTo(0,sz*1.0);ctx.lineTo(-sz*0.35,sz*0.9);ctx.lineTo(-sz*0.7,sz*0.2);ctx.lineTo(-sz*0.6,-sz*0.5);
    }
    ctx.closePath();
    ctx.strokeStyle=cc;ctx.lineWidth=1.8;ctx.stroke();
    ctx.fillStyle=cc.replace('0.6','0.12').replace('0.65','0.14').replace('0.55','0.12');ctx.fill();
    // Olho do clone
    const eyeR=sz*0.13,eyePulse=0.5+0.4*Math.sin(t*4+cl.moveAngle);
    ctx.beginPath();ctx.ellipse(0,-sz*0.1,eyeR,eyeR*0.7,0,0,Math.PI*2);
    ctx.fillStyle=form==='dragao'?`rgba(255,120,0,${eyePulse})`:form==='camaleao'?`rgba(255,60,20,${eyePulse})`:`rgba(255,0,0,${eyePulse})`;ctx.fill();
    ctx.font='7px monospace';ctx.textAlign='center';ctx.fillStyle=cc;
    ctx.fillText('CLONE',0,sz*1.18);
    ctx.restore();
  }

  // ── Draw: laser reptiliano (com cor variável por forma) ──────────
  function _drawReptBossLaser(ctx,l,t){
    if(!l.trail||l.trail.length<2)return;
    const lc=l.color||'#ff2200';
    ctx.save();ctx.globalCompositeOperation='screen';
    for(let i=1;i<l.trail.length;i++){
      const frac=i/l.trail.length;
      ctx.beginPath();ctx.moveTo(l.trail[i-1].x,l.trail[i-1].y);ctx.lineTo(l.trail[i].x,l.trail[i].y);
      ctx.strokeStyle=lc.startsWith('#')?`${lc}${Math.floor(frac*0.65*255).toString(16).padStart(2,'0')}`:lc;
      ctx.lineWidth=frac*3.8;ctx.stroke();
    }
    ctx.beginPath();ctx.arc(l.x,l.y,5.5,0,Math.PI*2);
    ctx.fillStyle='rgba(255,240,200,0.96)';ctx.fill();ctx.restore();
  }

  let _reptBypassUntil=0;
  function skipToBoss(){
    if(!_active)return;
    _reptilians.forEach(r=>{r.dead=true;}); _reptilians=[];
    _ships=[]; _portals=[];
    _wave=REP_WAVE_CONFIG.length;
    if(!_reptBossActive&&!_reptBoss) _spawnReptBoss();
  }
  function setBossForm(forma){
    const b=_reptBoss; if(!b||b.dying)return false;
    if(b.form===forma)return false;
    const hpMap={serpente:REPT_BOSS_SERP_HP,camaleao:REPT_BOSS_CAM_HP,dragao:REPT_BOSS_DRAG_HP};
    _startTripleBossAudio(forma);
    b.form=forma;
    b.phase=1;
    b.formMaxHP=hpMap[forma]||b.formMaxHP;
    b.formHP=b.formMaxHP;
    b.moveAngle=0; b.vx=0; b.vy=0;
    _reptBossLasers=[]; _reptBossClones=[];
    b.confuseRays=[];
    b.strikeState='idle'; b.strikeT=0; b.strikeTarget=null; b.strikeCd=2.2;
    b.venomCones=[]; b.venomTimer=0;
    b.constrictState='idle'; b.constrictT=0; b.constrictCd=5;
    b.invis=false; b.invisTimer=0; b.invisCd=10;
    b.camouflageAlpha=1; b.camHiding=false; b.camTimer=0; b.camCd=0; b.camState=null;
    b.toxicClouds=[]; b.fireBreaths=[]; b.diveBomb=false;
    b.ambushReady=false; b.ambushTimer=0; b.ambushTarget=null; b._ambushBonus=false;
    b.mirrorTimer=0; b.toxicTimer=0;
    b.tongueState=null; b.tongueTip={x:b.x||0,y:b.y||0};
    b.killParticles=[]; b.tailWhipCd=0; b.tailWhipT=0; b.laserTimer=0;
    b.dragState=null; b.screenBeams=[]; b.meteorWarnings=[]; b.glitchTraps=[];
    b.fireBreaths=[]; b.clawState='idle'; b.clawT=0; b.clawTarget=null;
    b.roarRings=[]; b.roarTimer=0;
    b.wingSpread=forma==='dragao'?0:1;
    b._dda=undefined;
    b.segments=undefined;
    const fill=document.getElementById('rept-boss-hp-fill');
    if(fill)fill.className='';
    _updateReptBossBar();
    return true;
  }

  // ── Força a Forma Final para uma fase específica (uso do Mod Menu) ──
  function setFinalFormPhase(n){
    const f=_reptFinalForm;
    if(!f||f.dying)return false;
    if(f.phase===n)return false;
    n=Math.max(1,Math.min(5,n));
    // Limpa entidades de todas as fases ao trocar
    f.minions=[]; f.miniBosses=[];
    f.pulsarBeams=[];
    f.hitkillState='idle'; f.hitkillTarget=null; f.hitkillTimer=1.5;
    f.trapExplTimer=0.5;
    f.ships=[]; f.megaBeams=[]; f.artHole=null;
    f.shipWaveTimer=8; f.megaBeamTimer=4; f.artHoleTimer=6;
    f.saws=[]; f.jets=[]; f.singularity=null;
    f.dashState='idle'; f.grabState='idle';
    if(n===1){
      f.phase=1; f.invulnerable=true;
      f.p1Wave=1; f.p1WaveDelay=1.2;
      f.hp=RFF_GLOBAL_MAX_HP; f.maxHP=RFF_GLOBAL_MAX_HP; // reinicia o pool global inteiro
      const phaseEl=document.getElementById('rept-boss-hp-phase');
      const subEl=document.getElementById('rept-boss-hp-subtitle');
      const fillEl=document.getElementById('rept-boss-hp-fill');
      if(phaseEl)phaseEl.textContent='FASE 1';
      if(subEl)subEl.textContent='☠️ FASE 1 — DESTRUA OS MINIONS!';
      if(fillEl){fillEl.style.width=(f.hp/RFF_GLOBAL_MAX_HP*100)+'%';fillEl.className='phase3';}
    } else if(n===2){
      f.phase=2; f.invulnerable=true;
      f.p2Wave=1; f.p2WaveDelay=1.2;
      f.maxHP=RFF_GLOBAL_MAX_HP;
      f.hp=RFF_GLOBAL_MAX_HP-RFF_PHASE_HP_BLOCK; // teto do bloco da Fase 2 (640000)
      const phaseEl=document.getElementById('rept-boss-hp-phase');
      const subEl=document.getElementById('rept-boss-hp-subtitle');
      const fillEl=document.getElementById('rept-boss-hp-fill');
      if(phaseEl)phaseEl.textContent='FASE 2';
      if(subEl)subEl.textContent='☠️ FASE 2 — GUARDIÕES ANTIGOS!';
      if(fillEl){fillEl.style.width=(f.hp/RFF_GLOBAL_MAX_HP*100)+'%';fillEl.className='phase3';}
    } else if(n===3){
      f.phase=3; f.invulnerable=false;
      // Inicia a transição desorientada DE VERDADE — a cabeça precisa ir
      // até o centro da arena para a animação (furar o olho etc.) ser vista.
      f.p3TransT=0; f.p3TransDone=false;
      f.eyeCracked=false; f.eyeCrackAmt=0; f.fangTwitch=0;
      f.speedMult=1;
      f.maxHP=RFF_GLOBAL_MAX_HP;
      f.hp=RFF_PHASE3_START_HP; // teto do bloco da Fase 3 (480000)
      const phaseEl=document.getElementById('rept-boss-hp-phase');
      const subEl=document.getElementById('rept-boss-hp-subtitle');
      const fillEl=document.getElementById('rept-boss-hp-fill');
      if(phaseEl)phaseEl.textContent='FASE 3';
      if(subEl)subEl.textContent='🌀 DESORIENTADO...';
      if(fillEl){fillEl.style.width=(f.hp/RFF_GLOBAL_MAX_HP*100)+'%';fillEl.className='phase3';}
    } else if(n===4){
      f.phase=4; f.invulnerable=false;
      f.p4TransT=0; f.p4TransDone=false;
      f.speedMult=1;
      f.maxHP=RFF_GLOBAL_MAX_HP;
      f.hp=RFF_PHASE4_START_HP; // teto do bloco da Fase 4 (320000)
      const phaseEl=document.getElementById('rept-boss-hp-phase');
      const subEl=document.getElementById('rept-boss-hp-subtitle');
      const fillEl=document.getElementById('rept-boss-hp-fill');
      if(phaseEl)phaseEl.textContent='FASE 4';
      if(subEl)subEl.textContent='⚡ FASE 4...';
      if(fillEl){fillEl.style.width=(f.hp/RFF_GLOBAL_MAX_HP*100)+'%';fillEl.className='phase3';}
    } else if(n===5){
      f.phase=5; f.invulnerable=false;
      f.p5TransT=0; f.p5TransDone=false;
      f.eyeGone=false;
      f.saws=[]; f.jets=[]; f.singularity=null;
      f.dashState='idle'; f.dashTimer=3;
      f.grabState='idle'; f.grabTimer=2;
      f.speedMult=1;
      f.maxHP=RFF_GLOBAL_MAX_HP;
      f.hp=RFF_PHASE5_START_HP; // teto do bloco final da Fase 5 (160000)
      const phaseEl=document.getElementById('rept-boss-hp-phase');
      const subEl=document.getElementById('rept-boss-hp-subtitle');
      const fillEl=document.getElementById('rept-boss-hp-fill');
      if(phaseEl)phaseEl.textContent='FASE 5';
      if(subEl)subEl.textContent='⚡ FASE 5...';
      if(fillEl){fillEl.style.width=(f.hp/RFF_GLOBAL_MAX_HP*100)+'%';fillEl.className='phase3';}
    }
    _stopTripleBossAudio();
    _startRffAudio(n);
    const flash=document.getElementById('reptilian-emergency-flash');
    if(flash){flash.style.opacity='1';setTimeout(()=>{flash.style.opacity='0';},700);}
    return true;
  }

  // ── Recalcula arena após resize/orientação (Modo Desktop) ─────────
  // Remapeia reptilianos, boss trio e Forma Final (corrente de segmentos)
  // de coords de tela proporcionalmente da arena antiga para a nova;
  // recalcula _worldBounds e redimensiona o canvas overlay das fendas.
  function _recalcArena(){
    if(!_active||!_arenaRect)return;
    const oldAr=_arenaRect;

    // Nova arena em coords de tela (mesma margem usada na criação original)
    const newAr={
      x:_MARGIN,
      y:_MARGIN,
      w:canvas.width  - _MARGIN*2,
      h:canvas.height - _MARGIN*2,
    };

    const remap=(x,y)=>{
      const fx=(x - oldAr.x) / oldAr.w;  // fração 0‥1 na arena antiga
      const fy=(y - oldAr.y) / oldAr.h;
      return {x:newAr.x + fx * newAr.w, y:newAr.y + fy * newAr.h};
    };

    // Remapeia posição de cada reptiliano
    _reptilians.forEach(r=>{
      if(r.dead)return;
      const p=remap(r.x,r.y);
      r.x=p.x; r.y=p.y;
    });

    // Remapeia o Boss Trio (Serpente/Camaleão/Dragão), se ativo
    if(_reptBoss&&!_reptBoss.dying){
      const p=remap(_reptBoss.x,_reptBoss.y);
      _reptBoss.x=p.x; _reptBoss.y=p.y;
    }

    // Remapeia a Forma Final (Quasord) — corrente inteira de segmentos
    if(_reptFinalForm){
      const f=_reptFinalForm;
      const p=remap(f.x,f.y);
      f.x=p.x; f.y=p.y;
      if(f.chain&&f.chain.length){
        f.chain.forEach(seg=>{
          const ps=remap(seg.x,seg.y);
          seg.x=ps.x; seg.y=ps.y;
        });
      }
      if(f.route&&f.route.length){
        f.route=f.route.map(wp=>remap(wp.x,wp.y));
      }
    }

    // Aplica nova arena
    _arenaRect=newAr;

    // Recalcula worldBounds a partir da nova arena
    const s2w=(sx,sy)=>({
      x:(sx-canvas.width*0.5)/cam.zoom+cam.x,
      y:(sy-canvas.height*0.5)/cam.zoom+cam.y,
    });
    const tlW=s2w(newAr.x, newAr.y);
    const brW=s2w(newAr.x+newAr.w, newAr.y+newAr.h);
    _worldBounds={minX:tlW.x,maxX:brW.x,minY:tlW.y,maxY:brW.y};

    // Reposiciona e redimensiona o canvas overlay das fendas
    if(_riftCanvas){
      _riftCanvas.width=canvas.width;
      _riftCanvas.height=canvas.height;
      _riftCanvas.style.left=canvas.style.left||'0px';
      _riftCanvas.style.top=canvas.style.top||'0px';
      _riftCanvas.style.width=canvas.width+'px';
      _riftCanvas.style.height=canvas.height+'px';
    }
  }

  return{startInvasion,isActive:()=>_active,forceEnd:()=>{if(_active)_endInvasion(false);},skipToBoss,
    recalcArena:_recalcArena,
    showBlackholyWarning:_showBlackholyReptWarning,
    bypassAntiForce:(ms)=>{_reptBypassUntil=Date.now()+(ms||60000);},
    setBossForm,
    spawnFinalForm:()=>{
      // Para usar no mod menu: garante que invasão está ativa e spawna forma final
      if(!_active){showTooltip('🦎 Inicie a invasão Reptiliana primeiro!');return false;}
      // ── Limpeza completa do campo de batalha ──────────────────────
      // Ao forçar a Forma Final diretamente (sem deixar o boss normal
      // morrer naturalmente), é preciso limpar manualmente tudo que
      // ficaria pendente em campo: o boss normal (Serpente/Camaleão/
      // Dragão) com seus efeitos, e os Reptilianos comuns/naves/portais
      // da invasão — do contrário eles continuam vivos e visíveis junto
      // com o Leviatã, competindo na tela.
      if(_reptBoss){_reptBoss=null;_reptBossActive=false;_reptBossLasers=[];_reptBossClones=[];_reptBossGrabbed=[];}
      _reptilians.forEach(r=>{r.dead=true;}); _reptilians=[];
      _ships=[]; _portals=[];
      _reptFinalForm=null;
      _stopTripleBossAudio();
      _startRffAudio(1);
      _spawnReptFinalForm();
      return true;
    },
    setFinalFormPhase,
    hitkillFinalForm:()=>{
      // Mata instantaneamente o Leviatã, mas SÓ se ele já estiver na
      // Fase 5 (vulnerável) — nas fases 1/2 ele é invulnerável, e nas
      // 3/4 tem HP renovado por fase, então forçar hp=0 ali só dispararia
      // a transição para a fase seguinte em vez de matar de verdade.
      const f=_reptFinalForm;
      if(!f||f.dying)return false;
      if(f.phase!==5)return false;
      f.hp=0;
      f.dying=true; f.dyingT=0;
      showTooltip('💀 O LEVIATÃ FOI FINALMENTE DESTRUÍDO!');
      return true;
    },
    isFinalFormActive:()=>!!_reptFinalForm&&!_reptFinalForm.dying,
    isBossActive:()=>!!_reptBoss&&!_reptBoss.dying,
    // ── API usada pela Frota Alienígena Militar (entityInvasionFleet) ──
    // Expõe as unidades terrestres reptilianas (as que têm HP e ficam
    // em campo) para que a frota alienígena possa mirar e aplicar dano.
    getGroundUnits:()=>_active?_reptilians.filter(r=>!r.dead):[],
    getShips:()=>_active?_ships.filter(s=>!s.dead):[],
    damageGroundUnit:(unit,dmg)=>{
      if(!unit||unit.dead)return;
      unit.hp=Math.max(0,unit.hp-dmg);
      unit._hitFlashT=0.3;unit.flashColor='#66ffcc';
      if(unit.hp<=0)unit.dead=true;
    }};
})();

