// ── Explosão realista de rasgo espaço-temporal ───────────────────────
// Centrada na câmera atual (o Quasord já não existe mais como objeto).
// Reescrita para ser um evento de verdade: múltiplas ondas de choque
// crescentes, faíscas densas, fenda central que "respira", tremor de
// câmera crescente, e uma onda de vácuo final que puxa partículas pro
// centro antes da detonação definitiva. onDone só é chamado quando o
// evento visual termina — é o próprio sinal que dispara o balão do
// Cosmy (_startQuasordAftermath), então a explosão nunca "corta" antes
// dele: a duração real é controlada aqui, não estimada de fora.
let _tearShakeMag=0, _tearShakeT=0;
function _tearShake(){
  if(_tearShakeMag<=0.01)return{x:0,y:0};
  _tearShakeT+=1;
  const decay=_tearShakeMag;
  return{
    x:(Math.random()*2-1)*decay,
    y:(Math.random()*2-1)*decay,
  };
}
function _tearShakeSet(mag){_tearShakeMag=mag;}
function _tearShakeDecayTo(target,ms){
  const start=_tearShakeMag,startT=performance.now();
  function step(){
    const p=Math.min(1,(performance.now()-startT)/ms);
    _tearShakeMag=start+(target-start)*p;
    if(p<1)requestAnimationFrame(step);
  }
  requestAnimationFrame(step);
}

function _spawnSpacetimeTearExplosion(onDone){
  const cx=cam.x,cy=cam.y;

  // ── Fase 0: colapso — a fenda se fecha sobre si mesma antes de estourar ──
  _tearShakeSet(2);
  for(let i=0;i<70;i++){
    const ang=rand(0,Math.PI*2),dist=rand(80,420);
    particles.push({x:cx+Math.cos(ang)*dist,y:cy+Math.sin(ang)*dist,
      vx:-Math.cos(ang)*rand(6,14),vy:-Math.sin(ang)*rand(6,14),
      r:rand(1.5,4),alpha:.85,color:Math.random()<.5?'#a29bfe':'#7be8ff'});
  }
  particles.push({x:cx,y:cy,vx:0,vy:0,r:6,alpha:1,color:'rgba(255,255,255,1)',ring:true,grow:3});

  // ── Fase 1 (450ms): primeira ruptura — flash + núcleo estourando ──
  setTimeout(()=>{
    _tearShakeSet(9);
    triggerFlash(1,650);
    for(let i=0;i<260;i++){
      const ang=rand(0,Math.PI*2),spd=rand(5,32);
      particles.push({x:cx,y:cy,vx:Math.cos(ang)*spd,vy:Math.sin(ang)*spd,
        r:rand(2,10),alpha:1,color:`hsl(${rand(0,50)},100%,${rand(65,95)}%)`});
    }
    for(let i=0;i<10;i++){
      particles.push({x:cx,y:cy,vx:0,vy:0,r:(i+1)*42,alpha:.95,
        color:i%2===0?'rgba(255,255,255,1)':'rgba(255,60,60,.9)',ring:true,grow:26});
    }
    // Faíscas longas disparadas radialmente (fragmentos de energia)
    for(let i=0;i<24;i++){
      const ang=rand(0,Math.PI*2),spd=rand(24,48);
      particles.push({x:cx,y:cy,vx:Math.cos(ang)*spd,vy:Math.sin(ang)*spd,
        r:rand(1,2.2),alpha:1,color:'#ffffff'});
    }
  },450);

  // ── Fase 2 (1050ms): rachadura tipo fenda dimensional, cores de rift ──
  setTimeout(()=>{
    _tearShakeSet(12);
    triggerFlash(.8,550);
    for(let i=0;i<220;i++){
      const ang=rand(0,Math.PI*2),spd=rand(4,26);
      particles.push({x:cx,y:cy,vx:Math.cos(ang)*spd,vy:Math.sin(ang)*spd,
        r:rand(1.5,7),alpha:1,color:Math.random()<.5?'#a29bfe':'#ff2244'});
    }
    for(let i=0;i<7;i++){
      particles.push({x:cx,y:cy,vx:0,vy:0,r:(i+1)*65,alpha:.75,
        color:'rgba(160,120,255,.85)',ring:true,grow:34});
    }
    // Filamentos de energia roxa cruzando a tela
    for(let i=0;i<16;i++){
      const ang=rand(0,Math.PI*2);
      particles.push({x:cx,y:cy,vx:Math.cos(ang)*rand(30,60),vy:Math.sin(ang)*rand(30,60),
        r:rand(1,2),alpha:.95,color:'#c9a2ff'});
    }
  },1050);

  // ── Fase 3 (1650ms): onda de vácuo — puxa faíscas de volta pro centro ──
  // (dá a sensação de que o espaço "respira" antes do estouro final)
  setTimeout(()=>{
    _tearShakeSet(6);
    for(let i=0;i<90;i++){
      const ang=rand(0,Math.PI*2),dist=rand(150,520);
      particles.push({x:cx+Math.cos(ang)*dist,y:cy+Math.sin(ang)*dist,
        vx:-Math.cos(ang)*rand(14,30),vy:-Math.sin(ang)*rand(14,30),
        r:rand(2,5),alpha:.9,color:'#ffffff'});
    }
    particles.push({x:cx,y:cy,vx:0,vy:0,r:20,alpha:.6,color:'rgba(40,0,80,1)',ring:true,grow:4});
  },1650);

  // ── Fase 4 (2150ms): detonação final — a mais intensa de todas ──
  setTimeout(()=>{
    _tearShakeSet(18);
    triggerFlash(1,900);
    for(let i=0;i<340;i++){
      const ang=rand(0,Math.PI*2),spd=rand(6,40);
      particles.push({x:cx,y:cy,vx:Math.cos(ang)*spd,vy:Math.sin(ang)*spd,
        r:rand(2,11),alpha:1,color:Math.random()<.6?'#ffffff':'#ff3355'});
    }
    for(let i=0;i<14;i++){
      particles.push({x:cx,y:cy,vx:0,vy:0,r:(i+1)*55,alpha:1,
        color:'rgba(255,255,255,.95)',ring:true,grow:32});
    }
    _tearShakeDecayTo(0,1400);
  },2150);

  // O evento visual (incluindo o decay final do tremor) termina por volta
  // de 3550ms — só então o balão do Cosmy é chamado. Nada corta antes.
  if(typeof onDone==='function')setTimeout(onDone,3550);
}


// ═══════════════════════════════════════════════════════════════════
//  UPDATE
// ═══════════════════════════════════════════════════════════════════
// ═══════════════════════════════════════════════════════════════════
//  MÓDULO: RAÇAS CÓSMICAS — Fase Cósmica (Sandbox pós-derrota do Quasord)
// ═══════════════════════════════════════════════════════════════════
//  Ativo somente quando sandboxMode&&_sandboxPhase==='cosmic'. As 5
//  raças vagam sozinhas pelo universo sem precisar ser criadas pelo
//  jogador. Usam sua própria lista independente (_cosmicEntities) —
//  não interferem em `objects`, missões ou saves existentes.
// ═══════════════════════════════════════════════════════════════════

// Referência de "área visível" para a regra de despawn: usamos o MENOR
// zoom possível do jogo (maior campo de visão) como área de referência
// fixa — não o zoom atual da câmera. Assim, uma entidade só é
// considerada "fora da tela" quando sai da região que seria visível
// mesmo no zoom mais afastado (zoom mínimo = "visão máxima").
const COSMIC_REF_ZOOM = 0.08;

const COSMIC_DESPAWN_TIME = 12; // segundos fora da área de referência até desaparecer
const COSMIC_MAX_ENTITIES = 30; // teto de entidades simultâneas (performance)
const COSMIC_SPAWN_INTERVAL_MIN = 1.2; // intervalo mínimo entre spawns (segundos)
const COSMIC_SPAWN_INTERVAL_MAX = 3;   // intervalo máximo entre spawns (segundos)

// Raio (em unidades de mundo) além da borda de referência em que uma
// entidade pode nascer — nasce logo fora da visão, "entrando em cena".
const COSMIC_SPAWN_MARGIN = 260;

// ── Definição das 5 raças ────────────────────────────────────────────
const COSMIC_RACES = {
  plasmicea: {
    id: 'plasmicea',
    name: 'Raça Plasmícea',
    flavor: 'Feita de plasma puro. Vive em estrelas e adora o calor extremo.',
    color: '#ff8a3d',
    glow: 'rgba(255,150,60,0.55)',
    speed: 38,
    behavior: 'orbit-hot',
    hostTypes: ['star','cepheid','magnetar','protostar'],
  },
  fungica: {
    id: 'fungica',
    name: 'Raça Fúngica',
    flavor: 'Ama astros gelados, úmidos e oceânicos. Contamina o que está por perto com fungos.',
    color: '#9dff7a',
    glow: 'rgba(150,255,120,0.45)',
    speed: 16,
    behavior: 'cling-cold',
    hostTypes: ['planet','moon','coldcore','icecore','nucleogelido'],
  },
  necrida: {
    id: 'necrida',
    name: 'Raça Nécrida',
    flavor: 'Apodrece tudo ao redor. Agressiva, mas solene e triste — quase um ritual fúnebre.',
    color: '#6b6b7a',
    glow: 'rgba(110,110,125,0.4)',
    speed: 10,
    behavior: 'wander-decay',
    hostTypes: [],
  },
  viscera: {
    id: 'viscera',
    name: 'Raça Víscera',
    flavor: 'Feita de carne pura, sem ossos. Contamina astros densos e massivos, onde se adaptou a viver.',
    color: '#c94257',
    glow: 'rgba(220,60,90,0.5)',
    speed: 14,
    behavior: 'cling-dense',
    hostTypes: ['blackhole','neutronstar','magnetar','quasar'],
  },
  robotica: {
    id: 'robotica',
    name: 'Raça Robótica',
    flavor: 'Sem sentimentos. Vaga pelo espaço cumprindo missões que só ela entende.',
    color: '#7fd7ff',
    glow: 'rgba(120,210,255,0.5)',
    speed: 55,
    behavior: 'patrol-mission',
    hostTypes: ['pulsar', 'wormhole', 'microquasar'],
  },
};
const COSMIC_RACE_IDS = Object.keys(COSMIC_RACES);

// ── Estado interno ───────────────────────────────────────────────────
let _cosmicEntities = [];
let _cosmicSpawnTimer = 0;
let _cosmicNextSpawnAt = COSMIC_SPAWN_INTERVAL_MIN;
let _cosmicIdCounter = 1;

// ── Utilitários ───────────────────────────────────────────────────────
function _cosmicRefBox() {
  const halfW = (canvas.width * 0.5) / COSMIC_REF_ZOOM;
  const halfH = (canvas.height * 0.5) / COSMIC_REF_ZOOM;
  return {
    x0: cam.x - halfW, x1: cam.x + halfW,
    y0: cam.y - halfH, y1: cam.y + halfH,
  };
}

function _cosmicIsOutsideRef(ent) {
  const box = _cosmicRefBox();
  return (ent.x < box.x0 || ent.x > box.x1 || ent.y < box.y0 || ent.y > box.y1);
}

function _cosmicRollSpawnPos() {
  const box = _cosmicRefBox();
  const side = Math.floor(rand(0, 4)); // 0=topo,1=baixo,2=esquerda,3=direita
  const m = COSMIC_SPAWN_MARGIN;
  if (side === 0) return { x: rand(box.x0, box.x1), y: box.y0 - m };
  if (side === 1) return { x: rand(box.x0, box.x1), y: box.y1 + m };
  if (side === 2) return { x: box.x0 - m, y: rand(box.y0, box.y1) };
  return { x: box.x1 + m, y: rand(box.y0, box.y1) };
}

function _cosmicFindHost(hostTypes, biome) {
  if (!hostTypes || hostTypes.length === 0) return null;
  if (typeof objects === 'undefined' || !objects.length) return null;
  const candidates = objects.filter(o => !o.dead && hostTypes.includes((o.type || '').toLowerCase()));
  if (!candidates.length) return null;
  // Se a raça tem um bioma, prioriza hosts que estejam dentro dele —
  // cai para qualquer host compatível caso nenhum esteja no bioma.
  if (biome) {
    const inBiome = candidates.filter(o => _cosmicPointInBiome(biome, o.x, o.y));
    if (inBiome.length) return inBiome[Math.floor(rand(0, inBiome.length))];
  }
  return candidates[Math.floor(rand(0, candidates.length))];
}

// Sorteia um ponto aleatório dentro do contorno orgânico do bioma
// (usado como posição de nascimento preferencial de entidades da raça
// dona daquele bioma, quando não há host compatível).
function _cosmicRollPosInBiome(biome) {
  for (let tries = 0; tries < 12; tries++) {
    const ang = rand(0, Math.PI * 2);
    const dist = rand(0, biome.radius * 0.85); // margem de segurança do contorno irregular
    const x = biome.x + Math.cos(ang) * dist;
    const y = biome.y + Math.sin(ang) * dist;
    if (_cosmicPointInBiome(biome, x, y)) return { x, y };
  }
  return { x: biome.x, y: biome.y }; // fallback: centro do bioma
}

// ── Criação de entidade ──────────────────────────────────────────────
function _cosmicSpawnOne() {
  const raceId = COSMIC_RACE_IDS[Math.floor(rand(0, COSMIC_RACE_IDS.length))];
  const race = COSMIC_RACES[raceId];
  const biome = _cosmicBiomeForRace(raceId);
  // Robótica nunca nasce já com host: seu comportamento (patrol-mission)
  // é "sempre em missão" por padrão, só adota um host tecnológico se
  // achar um dentro do próprio bioma nos frames seguintes (ver
  // _cosmicBehaviorPatrolMission). Nascer com host pulava direto pra
  // órbita, sem nunca patrulhar.
  const host = race.behavior === 'patrol-mission' ? null : _cosmicFindHost(race.hostTypes, biome);

  // Posição de nascimento: host encontrado > perto da câmera dentro do
  // bioma da raça > borda visível da câmera (sem bioma). Sortear em
  // qualquer ponto do bioma inteiro (raio até 1600) quase nunca cai na
  // área visível da tela — é por isso que Nécrida, Víscera e Robótica
  // (que raramente acham host) praticamente nunca apareciam nos seus
  // próprios biomas: nasciam de verdade, só longe demais pra serem
  // vistas. Mesma correção já aplicada à fauna de bioma.
  let pos;
  if (host) {
    pos = { x: host.x + rand(-30, 30), y: host.y + rand(-30, 30) };
  } else if (biome) {
    pos = _cosmicRollPosNearCameraInBiome(biome);
  } else {
    pos = _cosmicRollSpawnPos();
  }

  const ent = {
    id: 'cosmic_' + (_cosmicIdCounter++),
    raceId,
    x: pos.x,
    y: pos.y,
    angle: rand(0, Math.PI * 2),
    orbitAngle: rand(0, Math.PI * 2),
    orbitRadius: host ? (host.radius || 20) + rand(24, 60) : 0,
    hostId: host ? (host.id ?? null) : null,
    hostRef: host || null,
    biomeId: biome ? biome.id : null,
    offscreenT: 0,
    patrolTarget: null,
    phase: rand(0, Math.PI * 2),
    scale: rand(0.85, 1.25),
    spawnT: 0,
  };
  _cosmicEntities.push(ent);
}

// Spawna uma entidade cósmica de uma raça específica bem no centro da
// câmera — usado pelo Mod Menu para testes, sem depender do sorteio
// automático nem de esperar um host/bioma aparecer perto o bastante.
function _cosmicSpawnRaceAtCenter(raceId) {
  const race = COSMIC_RACES[raceId];
  if (!race || typeof cam === 'undefined') return null;
  const biome = _cosmicBiomeForRace(raceId);
  // Tenta achar um host compatível (dentro do bioma ou não); se não
  // houver nenhum astro compatível no jogo, a entidade nasce sem host —
  // flag _modSpawn faz os comportamentos que dependem de host (orbitar,
  // grudar) pairarem estáveis perto do ponto de spawn em vez de vagar
  // pra sempre em busca de algo que não existe.
  const host = _cosmicFindHost(race.hostTypes, biome);
  const ent = {
    id: 'cosmic_' + (_cosmicIdCounter++),
    raceId,
    x: cam.x,
    y: cam.y,
    angle: rand(0, Math.PI * 2),
    orbitAngle: rand(0, Math.PI * 2),
    orbitRadius: host ? (host.radius || 20) + rand(24, 60) : 0,
    hostId: host ? host.id : null,
    hostRef: host || null,
    biomeId: biome ? biome.id : null,
    offscreenT: 0,
    patrolTarget: null,
    phase: rand(0, Math.PI * 2),
    scale: rand(0.85, 1.25),
    spawnT: 0,
    _modSpawn: !host,
    _modAnchorX: cam.x,
    _modAnchorY: cam.y,
  };
  _cosmicEntities.push(ent);
  return ent;
}

// ── Comportamentos por raça ──────────────────────────────────────────
// Arquitetura espelhada fielmente na ReptilianEntity (comprovadamente
// estável, nunca "anda de lado"): dois sistemas TOTALMENTE separados,
// cada um com sua própria inércia, ligados apenas por um offset fixo:
//
//   1) ent.angle     — pra onde o "nariz"/topo do sprite aponta.
//      ent._angleVel — velocidade angular própria, com sua própria
//                       inércia (lerp), nunca um salto direto de ângulo.
//   2) ent._vx/_vy   — velocidade real que move a posição.
//      Sempre resulta de um lerp em direção a uma velocidade-alvo —
//      nunca `ent.x += cos(ent.angle)*speed` direto.
//
// O ângulo NUNCA dita a posição diretamente, e a posição NUNCA dita o
// ângulo diretamente — cada correção brusca (mudar de alvo, perder
// host, puxão de bioma) entra por trás da respectiva camada de inércia
// antes de se tornar visível, exatamente como a Reptiliana já fazia.

// Gira ent.angle suavemente em direção a targetAngle, com inércia
// própria em _angleVel (mesmo padrão da ReptilianEntity.update, linhas
// "targetAngle... this._angleVel+=(diff*K-this._angleVel)*lerp").
function _cosmicSteerAngle(ent, dt, targetAngle, turnGain, angleLerpRate) {
  if (ent._angleVel === undefined) ent._angleVel = 0;
  let diff = targetAngle - ent.angle;
  diff = Math.atan2(Math.sin(diff), Math.cos(diff)); // normaliza p/ [-PI, PI]
  ent._angleVel += (diff * turnGain - ent._angleVel) * Math.min(1, dt * angleLerpRate);
  ent.angle += ent._angleVel * dt;
}

// Sem alvo/direção específica: spin livre orgânico (mesmo padrão da
// ReptilianEntity quando _huntTarget é nulo — decai e ocasionalmente
// recebe um novo impulso aleatório).
function _cosmicFreeSpin(ent, dt, maxSpin) {
  if (ent._angleVel === undefined) ent._angleVel = 0;
  ent._angleVel *= (1 - dt * 0.5);
  if (Math.abs(ent._angleVel) < maxSpin * 0.3) {
    ent._angleVel += rand(maxSpin * 0.3, maxSpin) * (Math.random() < 0.5 ? 1 : -1) * dt * 2;
  }
  ent.angle += ent._angleVel * dt;
}

// Lerp de velocidade real em direção a uma velocidade-alvo — o que de
// fato move ent.x/ent.y. Nunca aplica cos(angle)*speed direto na
// posição.
function _cosmicSteerVelocity(ent, dt, targetVx, targetVy, velLerpRate) {
  if (ent._vx === undefined) { ent._vx = 0; ent._vy = 0; }
  const k = Math.min(1, dt * velLerpRate);
  ent._vx += (targetVx - ent._vx) * k;
  ent._vy += (targetVy - ent._vy) * k;
  ent.x += ent._vx * dt;
  ent.y += ent._vy * dt;
}

function _cosmicBehaviorOrbitHot(ent, race, dt) {
  // Plasmícea: orbita a estrela/host quente. Sem host, vaga procurando um.
  if (ent.hostRef && !ent.hostRef.dead) {
    ent.orbitAngle += (race.speed / Math.max(40, ent.orbitRadius)) * dt;
    ent.x = ent.hostRef.x + Math.cos(ent.orbitAngle) * ent.orbitRadius;
    ent.y = ent.hostRef.y + Math.sin(ent.orbitAngle) * ent.orbitRadius;
    // O rosto/desenho acompanha a tangente da órbita suavemente — nunca
    // é atribuído direto, sempre gira por inércia própria.
    _cosmicSteerAngle(ent, dt, ent.orbitAngle + Math.PI * 0.5, 4, 3);
    if (!ent.hostRef._plasmicMega && (ent.hostRef.type === 'star' || ent.hostRef.type === 'cepheid')
        && typeof pendingObjects !== 'undefined') {
      const mega = new PlasmicMegastructure(ent.hostRef.x, ent.hostRef.y);
      mega.attachTo(ent.hostRef);
      ent.hostRef._plasmicMega = mega;
      pendingObjects.push(mega);
    }
  } else {
    ent.hostRef = null;
    const found = ent._modSpawn ? null : _cosmicFindHost(race.hostTypes, _cosmicBiomeById(ent.biomeId));
    if (found) {
      ent.hostRef = found;
      ent.orbitAngle = Math.atan2(ent.y - found.y, ent.x - found.x);
      ent.orbitRadius = Math.hypot(ent.x - found.x, ent.y - found.y)
        || (found.radius || 20) + rand(24, 60);
    } else {
      // Vaga livre: spin orgânico no rosto, movimento segue o rosto com
      // pequeno offset e ruído próprio — igual à deriva translacional
      // da Reptiliana sem alvo.
      _cosmicFreeSpin(ent, dt, 1.2);
      const spd = race.speed * 0.4;
      _cosmicSteerVelocity(ent, dt, Math.cos(ent.angle) * spd, Math.sin(ent.angle) * spd, 2.5);
    }
  }
}

function _cosmicBehaviorClingCold(ent, race, dt) {
  // Fúngica: gruda devagar em astros frios/oceânicos, quase parada,
  // "respirando" no lugar (leve oscilação).
  if (ent.hostRef && !ent.hostRef.dead) {
    ent.phase += dt;
    ent.orbitAngle = ent.phase * 0.3;
    const targetX = ent.hostRef.x + Math.cos(ent.orbitAngle) * ((ent.hostRef.radius || 20) + 14);
    const targetY = ent.hostRef.y + Math.sin(ent.orbitAngle) * ((ent.hostRef.radius || 20) + 14);
    // Movimento por velocidade-alvo (rumo ao ponto de "respiração"),
    // nunca ent.x atribuído direto.
    _cosmicSteerVelocity(ent, dt, (targetX - ent.x) * 3, (targetY - ent.y) * 3, 4);
    _cosmicSteerAngle(ent, dt, ent.orbitAngle + Math.PI * 0.5, 4, 3);
  } else {
    ent.hostRef = null;
    const found = ent._modSpawn ? null : _cosmicFindHost(race.hostTypes, _cosmicBiomeById(ent.biomeId));
    if (found) {
      ent.hostRef = found;
      ent.phase = 0;
    } else {
      const anchorX = ent._modSpawn ? ent._modAnchorX : null;
      if (anchorX !== null) {
        ent.phase += dt;
        ent.orbitAngle = ent.phase * 0.3;
        const targetX = ent._modAnchorX + Math.cos(ent.orbitAngle) * 30;
        const targetY = ent._modAnchorY + Math.sin(ent.orbitAngle) * 30;
        _cosmicSteerVelocity(ent, dt, (targetX - ent.x) * 3, (targetY - ent.y) * 3, 4);
        _cosmicSteerAngle(ent, dt, ent.orbitAngle + Math.PI * 0.5, 4, 3);
      } else {
        _cosmicFreeSpin(ent, dt, 1.0);
        const spd = race.speed * 0.3;
        _cosmicSteerVelocity(ent, dt, Math.cos(ent.angle) * spd, Math.sin(ent.angle) * spd, 2.2);
      }
    }
  }
}

function _cosmicBehaviorWanderDecay(ent, race, dt) {
  // Nécrida: vaga sozinha, devagar e errática, às vezes parando
  // (momento "solene") antes de seguir de novo.
  ent._pauseT = ent._pauseT || 0;
  if (ent._pauseT > 0) {
    ent._pauseT -= dt;
    // Freia suavemente rumo a velocidade zero durante a pausa.
    _cosmicSteerVelocity(ent, dt, 0, 0, 3);
    _cosmicFreeSpin(ent, dt, 0.3);
  } else {
    _cosmicFreeSpin(ent, dt, 1.0);
    const spd = race.speed;
    _cosmicSteerVelocity(ent, dt, Math.cos(ent.angle) * spd, Math.sin(ent.angle) * spd, 2.0);
    if (Math.random() < 0.002) ent._pauseT = rand(1.5, 4);
  }
}

function _cosmicBehaviorClingDense(ent, race, dt) {
  // Víscera: pulsa organicamente ao redor de um astro denso/massivo.
  if (ent.hostRef && !ent.hostRef.dead) {
    ent.orbitAngle += (race.speed / Math.max(50, ent.orbitRadius)) * dt * 0.5;
    ent.x = ent.hostRef.x + Math.cos(ent.orbitAngle) * ent.orbitRadius;
    ent.y = ent.hostRef.y + Math.sin(ent.orbitAngle) * ent.orbitRadius;
    _cosmicSteerAngle(ent, dt, ent.orbitAngle + Math.PI * 0.5, 4, 3);
  } else {
    ent.hostRef = null;
    const found = _cosmicFindHost(race.hostTypes, _cosmicBiomeById(ent.biomeId));
    if (found) {
      ent.hostRef = found;
      ent.orbitAngle = Math.atan2(ent.y - found.y, ent.x - found.x);
      ent.orbitRadius = Math.hypot(ent.x - found.x, ent.y - found.y)
        || (found.radius || 20) + rand(24, 60);
    } else {
      _cosmicFreeSpin(ent, dt, 1.2);
      const spd = race.speed * 0.35;
      _cosmicSteerVelocity(ent, dt, Math.cos(ent.angle) * spd, Math.sin(ent.angle) * spd, 2.5);
    }
  }
}

function _cosmicBehaviorPatrolMission(ent, race, dt) {
  // Robótica: procura um astro tecnológico/artificial (pulsar, buraco de
  // minhoca, microquasar) para orbitar, mas SOMENTE se ele estiver
  // dentro do próprio bioma dela (Nebulosa Ferrolume) — nunca sai do
  // bioma perseguindo um host distante. Sem candidato dentro do bioma,
  // continua patrulhando em linha reta entre pontos aleatórios, sem
  // emoção, sempre "em missão".
  //
  // Mesmo padrão de movimento das outras raças cósmicas (Reptiliana
  // inclusa): _vx/_vy via _cosmicSteerVelocity são o único driver de
  // posição, nunca ent.x/ent.y atribuídos direto — mesmo ao entrar em
  // órbita. Um MAX_HOST_DIST evita "grudar" via teleporte em um host
  // achado longe: a nave aproxima com inércia normal (como um
  // patrolTarget) até estar perto o bastante pra assumir a órbita.
  const MAX_HOST_DIST = 260;

  if (ent.hostRef && !ent.hostRef.dead) {
    ent.orbitAngle += (race.speed / Math.max(40, ent.orbitRadius)) * dt;
    const targetX = ent.hostRef.x + Math.cos(ent.orbitAngle) * ent.orbitRadius;
    const targetY = ent.hostRef.y + Math.sin(ent.orbitAngle) * ent.orbitRadius;
    _cosmicSteerVelocity(ent, dt, (targetX - ent.x) * 3, (targetY - ent.y) * 3, 4);
    _cosmicSteerAngle(ent, dt, ent.orbitAngle + Math.PI * 0.5, 4, 3);
    return;
  }
  ent.hostRef = null;

  const biome = _cosmicBiomeById(ent.biomeId);
  if (biome && typeof objects !== 'undefined' && objects.length && race.hostTypes.length) {
    const inBiomeHosts = objects.filter(o => !o.dead
      && race.hostTypes.includes((o.type || '').toLowerCase())
      && _cosmicPointInBiome(biome, o.x, o.y));
    if (inBiomeHosts.length) {
      // Candidato mais próximo dentro do limite de distância — se
      // nenhum estiver perto o bastante, segue na patrulha normal em
      // vez de fixar um host distante e teleportar até ele.
      let best = null, bestD = Infinity;
      for (const o of inBiomeHosts) {
        const d = Math.hypot(ent.x - o.x, ent.y - o.y);
        if (d < bestD) { bestD = d; best = o; }
      }
      if (best && bestD <= MAX_HOST_DIST) {
        ent.hostRef = best;
        ent.orbitAngle = Math.atan2(ent.y - best.y, ent.x - best.x);
        ent.orbitRadius = Math.hypot(ent.x - best.x, ent.y - best.y)
          || (best.radius || 16) + rand(20, 46);
        return;
      }
      // Host existe mas está longe: define como alvo de patrulha para
      // se aproximar com o movimento normal (sem pular direto pra
      // órbita); ao chegar perto, o próximo frame entra no ramo acima
      // e assume a órbita suavemente.
      ent.patrolTarget = { x: best.x, y: best.y };
    }
  }

  // Patrulha normal: sem astro tecnológico compatível dentro do bioma,
  // ou host encontrado mas ainda fora do alcance de aproximação direta.
  if (!ent.patrolTarget) {
    ent.patrolTarget = _cosmicRollSpawnPos();
  }
  const dx = ent.patrolTarget.x - ent.x;
  const dy = ent.patrolTarget.y - ent.y;
  const d = Math.hypot(dx, dy) || 1;
  // Rosto e movimento perseguem o alvo cada um com sua própria inércia
  // — igual à Reptiliana perseguindo _huntTarget.
  const targetAngle = Math.atan2(dy, dx);
  _cosmicSteerAngle(ent, dt, targetAngle, 3.5, 2.8);
  const spd = race.speed;
  _cosmicSteerVelocity(ent, dt, (dx / d) * spd, (dy / d) * spd, 3);
  if (d < 40) { ent.patrolTarget = null; ent._territoryRecall = false; }
}

const COSMIC_BEHAVIORS = {

  'orbit-hot': _cosmicBehaviorOrbitHot,
  'cling-cold': _cosmicBehaviorClingCold,
  'wander-decay': _cosmicBehaviorWanderDecay,
  'cling-dense': _cosmicBehaviorClingDense,
  'patrol-mission': _cosmicBehaviorPatrolMission,
};

// ── Update principal ──────────────────────────────────────────────────
function cosmicRacesUpdate(dt) {
  _cosmicSpawnTimer += dt;
  if (_cosmicSpawnTimer >= _cosmicNextSpawnAt && _cosmicEntities.length < COSMIC_MAX_ENTITIES) {
    _cosmicSpawnTimer = 0;
    _cosmicNextSpawnAt = rand(COSMIC_SPAWN_INTERVAL_MIN, COSMIC_SPAWN_INTERVAL_MAX);
    if (!_isBattle()) _cosmicSpawnOne();
  }
  // Durante batalha de boss: entidades já existentes ficam paradas
  // (sem IA/movimento) — só voltam a agir quando a batalha terminar.
  if (_isBattle()) return;

  for (let i = _cosmicEntities.length - 1; i >= 0; i--) {
    const ent = _cosmicEntities[i];
    const race = COSMIC_RACES[ent.raceId];
    ent.spawnT += dt;
    ent.phase += dt;

    const behavior = COSMIC_BEHAVIORS[race.behavior];
    if (behavior) behavior(ent, race, dt);

    // Preferência de território: entidades sem host (vagando livres)
    // recebem uma leve correção de rota de volta ao bioma da própria
    // raça quando se afastam demais dele. Usa o mesmo _cosmicSteerAngle
    // com inércia própria do resto do sistema — por já ter inércia
    // embutida, não precisa mais de histerese manual nem de um
    // acumulador de taxa de giro à parte: girar repetidamente na borda
    // do bioma não acumula nem "enrola" o ângulo, porque a própria
    // inércia do steer absorve naturalmente qualquer oscilação.
    if (!ent.hostRef && ent.biomeId) {
      const biome = _cosmicBiomeById(ent.biomeId);
      if (biome) {
        const d = Math.hypot(ent.x - biome.x, ent.y - biome.y);
        if (d > biome.radius * 1.4) {
          if (race.behavior === 'patrol-mission') {
            // Robótica: define um novo destino de patrulha dentro do
            // bioma uma única vez, e deixa o comportamento normal
            // guiá-la até lá (evita sortear um alvo novo todo frame).
            if (!ent._territoryRecall) {
              ent._territoryRecall = true;
              ent.patrolTarget = _cosmicRollPosInBiome(biome);
            }
          } else {
            const backAng = Math.atan2(biome.y - ent.y, biome.x - ent.x);
            _cosmicSteerAngle(ent, dt, backAng, 2, 1.5);
          }
        } else if (race.behavior === 'patrol-mission') {
          ent._territoryRecall = false;
        }
      }
    }

    // Regra de despawn: 12s contínuos fora da área de referência
    // (calculada sempre no zoom mínimo/máxima área visível, não no
    // zoom atual da câmera).
    if (_cosmicIsOutsideRef(ent)) {
      ent.offscreenT += dt;
      if (ent.offscreenT >= COSMIC_DESPAWN_TIME) {
        _cosmicEntities.splice(i, 1);
        continue;
      }
    } else {
      ent.offscreenT = 0;
    }
  }
}

// ── Desenho — nave neon grande da Raça Plasmícea ─────────────────────
// Corpo alongado tipo "lança" com núcleo de plasma pulsante, aletas
// neon triangulares e trilha de partículas incandescentes — bem maior
// e mais chamativa que a bolinha genérica das outras raças cósmicas,
// no mesmo espírito das naves de Alien/Marciana/Reptiliana.
function _cosmicDrawPlasmiceaShip(ent, sx, sy, cam_zoom) {
  const scale = ent.scale * cam_zoom;
  const r = Math.max(10 * cam_zoom, 15 * scale); // bem maior que o baseR genérico (6)
  const T = ent.phase;
  const moveAngle = ent.angle;

  // Trilha de plasma
  ctx.save();
  const trailLen = 5;
  for (let i = 0; i < trailLen; i++) {
    const back = (i + 1) * r * 0.55;
    const tx = sx - Math.cos(moveAngle) * back;
    const ty = sy - Math.sin(moveAngle) * back;
    const alpha = (1 - i / trailLen) * 0.35;
    ctx.beginPath();ctx.arc(tx, ty, Math.max(1, r * 0.32 * (1 - i / trailLen)), 0, Math.PI * 2);
    ctx.fillStyle = `rgba(255,140,50,${alpha})`;ctx.fill();
  }

  ctx.translate(sx, sy);ctx.rotate(moveAngle);

  // Aura neon externa
  const aura = ctx.createRadialGradient(0, 0, r * 0.5, 0, 0, r * 2.6);
  aura.addColorStop(0, `rgba(255,140,50,${0.18 + 0.08 * Math.sin(T * 2.5)})`);
  aura.addColorStop(1, 'transparent');
  ctx.beginPath();ctx.arc(0, 0, r * 2.6, 0, Math.PI * 2);ctx.fillStyle = aura;ctx.fill();

  // Corpo principal — lança alongada
  ctx.beginPath();
  ctx.moveTo(r * 1.8, 0);
  ctx.lineTo(r * 0.1, -r * 0.55);
  ctx.lineTo(-r * 1.3, -r * 0.32);
  ctx.lineTo(-r * 1.55, 0);
  ctx.lineTo(-r * 1.3, r * 0.32);
  ctx.lineTo(r * 0.1, r * 0.55);
  ctx.closePath();
  const bodyGrad = ctx.createLinearGradient(-r * 1.5, 0, r * 1.8, 0);
  bodyGrad.addColorStop(0, 'rgba(90,30,10,.92)');
  bodyGrad.addColorStop(0.5, 'rgba(200,70,20,.95)');
  bodyGrad.addColorStop(1, 'rgba(255,220,150,.98)');
  ctx.fillStyle = bodyGrad;ctx.fill();
  ctx.strokeStyle = `rgba(255,180,90,${0.7 + 0.25 * Math.sin(T * 4)})`;
  ctx.lineWidth = Math.max(1, r * 0.09);ctx.stroke();

  // Aletas neon triangulares
  [1, -1].forEach(side => {
    ctx.beginPath();
    ctx.moveTo(-r * 0.5, side * r * 0.35);
    ctx.lineTo(-r * 1.1, side * r * 1.15);
    ctx.lineTo(-r * 1.25, side * r * 0.4);
    ctx.closePath();
    ctx.fillStyle = 'rgba(255,110,40,.55)';ctx.fill();
    ctx.strokeStyle = `rgba(255,200,120,${0.6 + 0.3 * Math.sin(T * 3 + side)})`;
    ctx.lineWidth = Math.max(0.7, r * 0.05);ctx.stroke();
  });

  // Núcleo de plasma pulsante (centro do corpo)
  const coreR = r * (0.32 + 0.08 * Math.sin(T * 5));
  const coreGrad = ctx.createRadialGradient(0, 0, 0, 0, 0, coreR);
  coreGrad.addColorStop(0, 'rgba(255,255,220,.95)');
  coreGrad.addColorStop(0.5, 'rgba(255,150,50,.85)');
  coreGrad.addColorStop(1, 'rgba(255,90,20,.2)');
  ctx.beginPath();ctx.arc(0, 0, coreR, 0, Math.PI * 2);ctx.fillStyle = coreGrad;ctx.fill();

  // Linhas de energia ao longo do corpo (efeito "circuito neon")
  ctx.beginPath();
  ctx.moveTo(r * 1.7, 0);ctx.lineTo(-r * 1.45, 0);
  ctx.strokeStyle = `rgba(255,220,150,${0.5 + 0.4 * Math.sin(T * 6)})`;
  ctx.lineWidth = Math.max(0.6, r * 0.045);ctx.stroke();

  ctx.rotate(-moveAngle);ctx.restore();

  if (sandboxMode) {
    ctx.font = `${Math.max(7, r * 0.42)}px 'Courier New'`;
    ctx.fillStyle = 'rgba(255,170,80,.7)';ctx.textAlign = 'center';
    ctx.fillText('🔥 PLASMÍCEA', sx, sy + r * 2.4 + 6 * cam.zoom);
    ctx.textAlign = 'left';
  }
}

// ── Desenho — nave-cogumelo da Raça Fúngica ───────────────────────────
// Não é um cogumelo plantado no chão: é um casco orgânico achatado tipo
// carapaça/escudo (como o capuz de um cogumelo visto de cima, mas lido
// como um veículo), com uma cúpula bulbosa translúcida no centro (cabine/
// esporângio) e um feixe de raízes-propulsoras atrás que soltam um
// rastro de esporos — a versão fúngica de um "motor". Paleta sóbria
// cinza-esverdeada monocromática, com veios de bioluminescência rosa/
// roxo violeta "doentios" correndo pelo casco como destaque único.
function _cosmicDrawFungicaShip(ent, sx, sy, cam_zoom) {
  const scale = ent.scale * cam_zoom;
  const r = Math.max(10 * cam_zoom, 16 * scale);
  const T = ent.phase;
  const moveAngle = ent.angle;
  const pulse = 1 + Math.sin(T * 1.2) * 0.045;

  ctx.save();
  ctx.translate(sx, sy); ctx.rotate(moveAngle + Math.PI * 0.5); // chapéu "pra cima" na direção de movimento

  // Halo bioluminescente externo suave
  const aura = ctx.createRadialGradient(0, 0, r * 0.4, 0, 0, r * 3.1);
  aura.addColorStop(0, `rgba(140,90,200,${0.15 + 0.05 * Math.sin(T * 0.8)})`);
  aura.addColorStop(1, 'transparent');
  ctx.beginPath(); ctx.arc(0, 0, r * 3.1, 0, Math.PI * 2); ctx.fillStyle = aura; ctx.fill();

  // ── Tentáculos soltos e ondulantes — física de água-viva de verdade:
  // pendem para baixo, balançam com uma onda que viaja da base até a
  // ponta (delay por segmento, como um chicote), e cada um tem seu
  // próprio comprimento/fase pra não balançarem em uníssono. Nada de
  // espiral fechada tipo mola — é fluido, imprevisível, relaxado. ──────
  if (!ent._looseTentacles) {
    const n = 7;
    ent._looseTentacles = Array.from({length: n}, (_, i) => ({
      baseAngle: (i / n) * Math.PI * 2 + rand(-0.15, 0.15),
      lenMul: rand(0.8, 1.25),
      wob: rand(0, Math.PI * 2),
      wobSpeed: rand(0.6, 1.1),
      swayAmp: rand(0.18, 0.34),
      curl: rand(-0.4, 0.4), // leve tendência de encaracolar na ponta, não a vida toda
    }));
  }
  ent._looseTentacles.forEach(tc => {
    const steps = 12;
    const maxLen = r * 2.3 * tc.lenMul;
    const baseX = Math.cos(tc.baseAngle) * r * 0.55;
    const baseY = r * 0.85 + Math.sin(tc.baseAngle) * r * 0.2;
    const pts = [];
    for (let s = 0; s <= steps; s++) {
      const f = s / steps; // 0 na base, 1 na ponta — pendura pra baixo
      // Onda viajante: fase atrasa conforme desce, como um chicote solto
      const wave = Math.sin(T * tc.wobSpeed - f * 2.6 + tc.wob) * tc.swayAmp * f * f;
      // Leve encaracolamento só perto da ponta (não a espiral inteira)
      const curlAmt = tc.curl * Math.pow(f, 2.2);
      const x = baseX + Math.sin(f * Math.PI * 0.5) * r * 0.4 * Math.sign(tc.baseAngle - Math.PI) * 0.3
                + (wave + curlAmt) * maxLen * 0.5;
      const y = baseY + f * maxLen;
      pts.push({x, y});
    }
    // Corpo do tentáculo — curva suave (não linha reta segmentada)
    ctx.beginPath();
    ctx.moveTo(pts[0].x, pts[0].y);
    for (let i = 1; i < pts.length - 1; i++) {
      const mx = (pts[i].x + pts[i + 1].x) / 2;
      const my = (pts[i].y + pts[i + 1].y) / 2;
      ctx.quadraticCurveTo(pts[i].x, pts[i].y, mx, my);
    }
    const tcGrad = ctx.createLinearGradient(pts[0].x, pts[0].y, pts[pts.length - 1].x, pts[pts.length - 1].y);
    tcGrad.addColorStop(0, 'rgba(95,58,115,.7)');
    tcGrad.addColorStop(0.6, 'rgba(135,85,165,.55)');
    tcGrad.addColorStop(1, 'rgba(165,255,215,.45)');
    ctx.strokeStyle = tcGrad;
    ctx.lineWidth = Math.max(0.8, r * 0.11);
    ctx.lineCap = 'round';
    ctx.stroke();
    // Gotícula luminosa pulsante na ponta solta
    const tip = pts[pts.length - 1];
    const glow = 0.45 + 0.4 * Math.max(0, Math.sin(T * 2.1 + tc.wob));
    const tipGrad = ctx.createRadialGradient(tip.x, tip.y, 0, tip.x, tip.y, r * 0.28);
    tipGrad.addColorStop(0, `rgba(200,255,230,${glow})`);
    tipGrad.addColorStop(1, 'rgba(140,255,200,0)');
    ctx.beginPath(); ctx.arc(tip.x, tip.y, r * 0.28, 0, Math.PI * 2); ctx.fillStyle = tipGrad; ctx.fill();
  });

  // ── Corpo — cesto orgânico estriado entre o chapéu e os tentáculos ──
  const bodyTopW = r * 0.95, bodyBotW = r * 0.72, bodyH = r * 1.15;
  ctx.beginPath();
  ctx.moveTo(-bodyTopW, r * 0.15);
  ctx.quadraticCurveTo(-bodyTopW * 1.08, r * 0.15 + bodyH * 0.5, -bodyBotW, r * 0.15 + bodyH);
  ctx.lineTo(bodyBotW, r * 0.15 + bodyH);
  ctx.quadraticCurveTo(bodyTopW * 1.08, r * 0.15 + bodyH * 0.5, bodyTopW, r * 0.15);
  ctx.closePath();
  const bodyGrad = ctx.createLinearGradient(-bodyTopW, 0, bodyTopW, 0);
  bodyGrad.addColorStop(0, 'rgba(60,38,78,.92)');
  bodyGrad.addColorStop(0.5, 'rgba(105,68,130,.92)');
  bodyGrad.addColorStop(1, 'rgba(70,45,90,.92)');
  ctx.fillStyle = bodyGrad; ctx.fill();
  ctx.strokeStyle = 'rgba(190,150,220,.4)'; ctx.lineWidth = Math.max(0.8, r * 0.05); ctx.stroke();

  // Nervuras verticais no corpo com um pulso de luz subindo/descendo
  const ribCount = 5;
  for (let i = 0; i < ribCount; i++) {
    const f = i / (ribCount - 1);
    const rx = -bodyTopW * 0.85 + f * bodyTopW * 1.7;
    const rxBot = -bodyBotW * 0.85 + f * bodyBotW * 1.7;
    ctx.beginPath();
    ctx.moveTo(rx, r * 0.2);
    ctx.lineTo(rxBot, r * 0.15 + bodyH * 0.95);
    const travel = (T * 0.6 + f * 2) % 1;
    const ribGlow = Math.max(0, 1 - Math.abs(travel - 0.5) * 2.4);
    ctx.strokeStyle = `rgba(190,255,220,${0.15 + 0.4 * ribGlow})`;
    ctx.lineWidth = Math.max(0.6, r * 0.035);
    ctx.stroke();
  }

  // ── Chapéu — cúpula bulbosa por cima, com poros bioluminescentes
  // irregulares (elipses de tamanhos variados, não círculos uniformes) ──
  const capW = r * 1.9 * pulse, capH = r * 1.15 * pulse;
  ctx.beginPath();
  ctx.moveTo(-capW, 0);
  ctx.bezierCurveTo(-capW, -capH * 1.35, capW, -capH * 1.35, capW, 0);
  ctx.quadraticCurveTo(0, capH * 0.28, -capW, 0);
  ctx.closePath();
  const capGrad = ctx.createRadialGradient(-capW * 0.2, -capH * 0.7, r * 0.3, 0, -capH * 0.3, capW * 1.3);
  capGrad.addColorStop(0, 'rgba(150,95,180,.96)');
  capGrad.addColorStop(0.55, 'rgba(95,55,125,.95)');
  capGrad.addColorStop(1, 'rgba(55,30,75,.95)');
  ctx.fillStyle = capGrad; ctx.fill();
  ctx.strokeStyle = `rgba(210,170,235,${0.6 + 0.2 * Math.sin(T * 1.8)})`;
  ctx.lineWidth = Math.max(1, r * 0.06); ctx.stroke();

  // Poros luminosos irregulares no chapéu, cada um pisca no seu ritmo
  if (!ent._pores) {
    ent._pores = Array.from({length: 9}, () => ({
      x: rand(-0.82, 0.82), y: rand(-0.9, -0.05),
      w: rand(0.09, 0.16), h: rand(0.06, 0.11),
      rot: rand(0, Math.PI),
      blink: rand(0, Math.PI * 2),
      hue: Math.random() < 0.5 ? '170,255,210' : '210,255,170',
    }));
  }
  ent._pores.forEach(p => {
    const glow = 0.35 + 0.45 * Math.max(0, Math.sin(T * 1.6 + p.blink));
    ctx.save();
    ctx.translate(p.x * capW, p.y * capH);
    ctx.rotate(p.rot);
    ctx.beginPath();
    ctx.ellipse(0, 0, capW * p.w, capH * p.h, 0, 0, Math.PI * 2);
    ctx.fillStyle = `rgba(${p.hue},${glow})`;
    ctx.fill();
    ctx.restore();
  });

  ctx.rotate(-(moveAngle + Math.PI * 0.5)); ctx.restore();

  if (sandboxMode) {
    ctx.font = `${Math.max(7, r * 0.4)}px 'Courier New'`;
    ctx.fillStyle = 'rgba(180,120,180,.65)'; ctx.textAlign = 'center';
    ctx.fillText('🍄 FÚNGICA', sx, sy + r * 2.4 + 6 * cam.zoom);
    ctx.textAlign = 'left';
  }
}

function _cosmicDrawNecridaShip(ent, sx, sy, cam_zoom) {
  const scale = ent.scale * cam_zoom;
  const r = Math.max(10 * cam_zoom, 15.5 * scale);
  const T = ent.phase;
  const moveAngle = ent.angle;
  const listSway = Math.sin(T * 0.35) * 0.04; // navio à deriva, balanço lento

  // Névoa de decomposição flutuando ao redor, roxa/esverdeada
  if (!ent._fogBits) {
    ent._fogBits = Array.from({length: 7}, () => ({
      a: rand(0, Math.PI * 2), d: rand(0.85, 2.0),
      speed: rand(0.15, 0.4), size: rand(0.13, 0.24), pulse: rand(0, Math.PI * 2),
    }));
  }
  ctx.save();
  ent._fogBits.forEach(b => {
    const a = b.a + T * b.speed;
    const bx = sx + Math.cos(a) * r * b.d;
    const by = sy + Math.sin(a) * r * b.d * 0.6;
    const alpha = 0.06 + 0.03 * Math.sin(T * 0.6 + b.pulse);
    ctx.beginPath(); ctx.arc(bx, by, r * b.size, 0, Math.PI * 2);
    ctx.fillStyle = `rgba(110,75,135,${alpha})`; ctx.fill();
  });
  ctx.restore();

  ctx.save();
  ctx.translate(sx, sy); ctx.rotate(moveAngle + listSway);

  // Aura roxa discreta atrás de tudo
  const aura = ctx.createRadialGradient(0, 0, r * 0.5, 0, 0, r * 2.0);
  aura.addColorStop(0, `rgba(110,50,130,${0.1 + 0.03 * Math.sin(T * 0.7)})`);
  aura.addColorStop(1, 'transparent');
  ctx.beginPath(); ctx.arc(0, 0, r * 2.0, 0, Math.PI * 2); ctx.fillStyle = aura; ctx.fill();

  // ── CASCO: silhueta de navio angulosa (facetada, não bulbosa) —
  // proa em cunha reta, convés superior quebrado em degraus, popa
  // avariada com corte reto. Pontos fixos, gerados uma vez.
  if (!ent._hull) {
    ent._hull = {
      top: [
        {x: 1.55, y: -0.05}, {x: 1.15, y: -0.32}, {x: 0.75, y: -0.3},
        {x: 0.55, y: -0.52}, {x: 0.0, y: -0.5}, {x: -0.35, y: -0.62},
        {x: -0.8, y: -0.42}, {x: -1.1, y: -0.44},
      ],
      bottom: [
        {x: -1.25, y: -0.1}, {x: -1.15, y: 0.22}, {x: -0.7, y: 0.4},
        {x: -0.25, y: 0.34}, {x: 0.15, y: 0.5}, {x: 0.65, y: 0.4},
        {x: 1.0, y: 0.42}, {x: 1.3, y: 0.15}, {x: 1.55, y: -0.02},
      ],
    };
  }
  const hullPts = [...ent._hull.top, ...ent._hull.bottom];

  // Sombra roxa vazando por trás do casco
  ctx.beginPath();
  hullPts.forEach((p, i) => {
    const hx = p.x * r * 1.08, hy = p.y * r * 1.12;
    if (i === 0) ctx.moveTo(hx, hy); else ctx.lineTo(hx, hy);
  });
  ctx.closePath();
  ctx.fillStyle = 'rgba(85,38,102,.38)';
  ctx.fill();

  // Casco principal — cinza-arroxeado escuro, material de navio, não
  // carne. Gradiente mais sóbrio, roxo entra como sombreamento, não
  // como cor de pele orgânica
  ctx.beginPath();
  hullPts.forEach((p, i) => {
    const hx = p.x * r, hy = p.y * r;
    if (i === 0) ctx.moveTo(hx, hy); else ctx.lineTo(hx, hy);
  });
  ctx.closePath();
  const hullGrad = ctx.createLinearGradient(-r * 1.3, -r * 0.6, r * 1.55, r * 0.5);
  hullGrad.addColorStop(0,   'rgba(38,34,46,.95)');
  hullGrad.addColorStop(0.4, 'rgba(58,48,68,.93)');
  hullGrad.addColorStop(0.7, 'rgba(70,52,82,.92)');
  hullGrad.addColorStop(1,   'rgba(32,28,40,.95)');
  ctx.fillStyle = hullGrad; ctx.fill();
  ctx.strokeStyle = 'rgba(160,120,180,.5)';
  ctx.lineWidth = Math.max(0.8, r * 0.038); ctx.stroke();

  // Placas retangulares do casco — reforça "construído", quebra a
  // leitura orgânica de silhueta lisa
  const plateXs = [-1.0, -0.55, -0.1, 0.4, 0.9];
  plateXs.forEach((px, i) => {
    ctx.beginPath();
    ctx.moveTo(px * r, -0.5 * r * (1 - Math.abs(px)/1.7));
    ctx.lineTo(px * r, 0.45 * r * (1 - Math.abs(px)/1.7));
    ctx.strokeStyle = 'rgba(15,12,20,.4)';
    ctx.lineWidth = Math.max(0.5, r * 0.017);
    ctx.stroke();
  });
  // Faixa horizontal de convés (linha de junção casco/convés)
  ctx.beginPath();
  ctx.moveTo(-1.1 * r, -0.05 * r);
  ctx.lineTo(1.5 * r, -0.1 * r);
  ctx.strokeStyle = 'rgba(180,150,195,.3)';
  ctx.lineWidth = Math.max(0.6, r * 0.025);
  ctx.stroke();

  // ── AVARIAS: rombos retangulares (não elipses orgânicas) — parecem
  // buracos de impacto/estrutura rompida
  if (!ent._breaches) {
    ent._breaches = [
      { x: -0.6, y: -0.08, w: 0.22, h: 0.16, rot: 0.15 },
      { x: 0.65, y: 0.1, w: 0.15, h: 0.12, rot: -0.1 },
    ];
  }
  ent._breaches.forEach(b => {
    ctx.save(); ctx.translate(b.x * r, b.y * r); ctx.rotate(b.rot);
    ctx.beginPath(); ctx.rect(-b.w*r*0.5, -b.h*r*0.5, b.w*r, b.h*r);
    ctx.fillStyle = 'rgba(6,5,9,.88)'; ctx.fill();
    ctx.strokeStyle = 'rgba(140,110,155,.4)'; ctx.lineWidth = Math.max(0.5, r*0.018); ctx.stroke();
    ctx.restore();
  });

  // ── NÚCLEO DA PESTE: pequeno, deslocado do centro (não simétrico),
  // afundado numa das avarias — sugere infestação "achada" dentro do
  // navio, não um órgão central do corpo
  const coreX = -0.6 * r, coreY = -0.08 * r;
  const coreR = r * 0.1 * (0.6 + 0.2 * Math.sin(T * 1.4) * Math.sin(T * 0.5));
  const coreGrad = ctx.createRadialGradient(coreX, coreY, 0, coreX, coreY, coreR * 2.2);
  coreGrad.addColorStop(0, 'rgba(220,150,240,.9)');
  coreGrad.addColorStop(0.5, 'rgba(155,70,185,.55)');
  coreGrad.addColorStop(1, 'rgba(90,40,110,0)');
  ctx.beginPath(); ctx.arc(coreX, coreY, Math.max(0.6, coreR * 2.2), 0, Math.PI * 2);
  ctx.fillStyle = coreGrad; ctx.fill();

  // ── VEIAS DE PESTE: crescem a partir do núcleo deslocado, rastejando
  // pelas placas do casco em linhas retas/quebradas (como trincas
  // elétricas), não curvas orgânicas suaves — reforça "contaminação
  // de estrutura", não "sistema circulatório"
  if (!ent._veins) {
    ent._veins = Array.from({length: 6}, () => {
      const a = rand(-0.9, 2.4);
      return { a, len: rand(0.7, 1.5), kink: rand(-0.3, 0.3),
        birth: rand(0, 22), pulse: rand(0, Math.PI * 2) };
    });
  }
  ent._veins.forEach(v => {
    const grow = Math.max(0, Math.min(1, (T - v.birth * 0.1) / 3.5));
    if (grow <= 0) return;
    const bright = (0.4 + 0.35 * Math.max(0, Math.sin(T * 1.8 + v.pulse))) * grow;
    const midR = r * 0.45 * grow, endR = r * v.len * grow;
    const mx = coreX + Math.cos(v.a) * midR + v.kink * r * 0.2;
    const my = coreY + Math.sin(v.a) * midR * 0.7;
    const ex = coreX + Math.cos(v.a) * endR;
    const ey = coreY + Math.sin(v.a) * endR * 0.7;
    ctx.beginPath();
    ctx.moveTo(coreX, coreY);
    ctx.lineTo(mx, my);
    ctx.lineTo(ex, ey);
    ctx.strokeStyle = `rgba(200,120,225,${bright})`;
    ctx.lineWidth = Math.max(0.5, r * 0.026); ctx.stroke();
  });

  // ── MASTRO + FARRAPOS curtos, presos ao corpo
  if (!ent._tatters) {
    ent._tatters = Array.from({length: 3}, (_, i) => ({
      off: (i - 1) * 0.15, len: rand(0.5, 0.75), wob: rand(0, Math.PI * 2), spd: rand(0.8, 1.3),
    }));
  }
  ctx.beginPath();
  ctx.moveTo(-r * 0.4, -r * 0.62);
  ctx.lineTo(-r * 0.4, -r * 0.98);
  ctx.strokeStyle = 'rgba(105,100,95,.6)';
  ctx.lineWidth = Math.max(0.8, r * 0.032);
  ctx.stroke();
  ent._tatters.forEach(t => {
    const flap = Math.sin(T * t.spd + t.wob) * 0.18;
    const baseX = -r * 0.4, baseY = -r * 0.94 + t.off * r * 0.3;
    const endX = baseX - r * t.len * (0.9 + Math.sin(T * 0.5 + t.wob) * 0.07);
    const endY = baseY + r * flap * 0.45;
    ctx.beginPath();
    ctx.moveTo(baseX, baseY);
    ctx.quadraticCurveTo(baseX - r * t.len * 0.5, baseY + r * flap * 0.35, endX, endY);
    ctx.strokeStyle = 'rgba(120,75,140,.5)';
    ctx.lineWidth = Math.max(1.0, r * 0.065);
    ctx.stroke();
  });

  // ── VIGIAS em linha ao longo do convés — reforça leitura de "casco
  // de veículo", piscando fraco e irregular
  if (!ent._portholes) {
    ent._portholes = [-0.85, -0.4, 0.05, 0.5, 0.95].map(x => ({
      x, flicker: rand(0, Math.PI * 2), speed: rand(0.6, 1.8),
    }));
  }
  ent._portholes.forEach(p => {
    const on = Math.max(0, Math.sin(T * p.speed + p.flicker));
    const lit = on > 0.78 ? (on - 0.78) * 4.5 : 0;
    ctx.beginPath(); ctx.arc(p.x * r, 0.12 * r, r * 0.045, 0, Math.PI * 2);
    ctx.fillStyle = 'rgba(12,10,16,.8)'; ctx.fill();
    if (lit > 0) {
      ctx.beginPath(); ctx.arc(p.x * r, 0.12 * r, r * 0.045, 0, Math.PI * 2);
      ctx.fillStyle = `rgba(190,130,215,${lit * 0.6})`; ctx.fill();
    }
  });

  // ── COSTELAS DE CONVÉS expostas na popa
  if (!ent._deckRibs) {
    ent._deckRibs = [0.15, 0.42].map(t => ({ t, wob: rand(0, Math.PI * 2) }));
  }
  ent._deckRibs.forEach(rb => {
    const wobble = Math.sin(T * 0.9 + rb.wob) * 0.015;
    const x = -r * (0.95 + rb.t * 0.3);
    ctx.beginPath();
    ctx.arc(x, -0.05*r, r * (0.4 - rb.t * 0.08) * (1 + wobble), -0.7, 0.7);
    ctx.strokeStyle = 'rgba(165,140,175,.5)';
    ctx.lineWidth = Math.max(0.8, r * 0.036);
    ctx.stroke();
  });

  // ── MANCHAS DE PESTE (verde-doentio) crescendo pelas placas
  if (!ent._plague) {
    ent._plague = Array.from({length: 5}, () => ({
      x: rand(-1.0, 1.3), y: rand(-0.35, 0.32), rot: rand(0, Math.PI * 2),
      maxS: rand(0.06, 0.11), birth: rand(0, 35),
    }));
  }
  ent._plague.forEach(p => {
    const age = Math.max(0, Math.min(1, (T - p.birth * 0.1) / 3.5));
    if (age <= 0) return;
    const s = p.maxS * age * r;
    ctx.save(); ctx.translate(p.x * r, p.y * r); ctx.rotate(p.rot);
    ctx.beginPath();
    ctx.moveTo(s, 0); ctx.lineTo(s * 0.3, s * 0.65); ctx.lineTo(-s * 0.6, s * 0.5);
    ctx.lineTo(-s, -s * 0.1); ctx.lineTo(-s * 0.2, -s * 0.7); ctx.closePath();
    ctx.fillStyle = `rgba(100,145,78,${0.4 * age})`; ctx.fill();
    ctx.restore();
  });

  // ── FIGURA DE PROA: crânio anguloso entalhado na proa
  const skullFlicker = 0.4 + 0.35 * Math.max(0, Math.sin(T * 2.1));
  ctx.save();
  ctx.translate(r * 1.48, -0.06 * r);
  ctx.beginPath();
  ctx.moveTo(r*0.13,0); ctx.lineTo(r*0.05,-r*0.11); ctx.lineTo(-r*0.09,-r*0.08);
  ctx.lineTo(-r*0.12,0); ctx.lineTo(-r*0.06,r*0.1); ctx.lineTo(r*0.06,r*0.1);
  ctx.closePath();
  ctx.fillStyle = 'rgba(75,62,86,.88)'; ctx.fill();
  ctx.strokeStyle = 'rgba(195,165,210,.55)'; ctx.lineWidth = Math.max(0.5, r * 0.02); ctx.stroke();
  ctx.beginPath(); ctx.arc(-r*0.02, -r*0.02, r * 0.028, 0, Math.PI * 2);
  ctx.fillStyle = `rgba(215,145,235,${skullFlicker})`; ctx.fill();
  ctx.restore();

  ctx.rotate(-(moveAngle + listSway)); ctx.restore();

  if (sandboxMode) {
    ctx.font = `${Math.max(7, r * 0.4)}px 'Courier New'`;
    ctx.fillStyle = 'rgba(190,130,210,.7)'; ctx.textAlign = 'center';
    ctx.fillText('💀 NÉCRIDA', sx, sy + r * 1.2 + 6 * cam.zoom);
    ctx.textAlign = 'left';
  }
}

function _cosmicDrawVisceraShip(ent, sx, sy, cam_zoom) {
  const scale = ent.scale * cam_zoom;
  const r = Math.max(12 * cam_zoom, 17 * scale);
  const T = ent.phase;
  const moveAngle = ent.angle;
  const beat = 1 + Math.sin(T * 2.2) * 0.025 + Math.max(0, Math.sin(T * 2.2)) * 0.02;
  const facing = moveAngle + Math.PI / 2;

  ctx.save();
  ctx.translate(sx, sy); ctx.rotate(facing);

  const aura = ctx.createRadialGradient(0, 0, r * 0.4, 0, 0, r * 1.7);
  aura.addColorStop(0, `rgba(180,25,40,${0.13 + 0.05 * Math.max(0, Math.sin(T * 2.2))})`);
  aura.addColorStop(1, 'transparent');
  ctx.beginPath(); ctx.arc(0, 0, r * 1.7, 0, Math.PI * 2); ctx.fillStyle = aura; ctx.fill();

  // ── CASCO: contorno orgânico irregular (não polígono de ângulos
  // retos) — topo arredondado/dentado ao invés de ponta triangular
  // limpa, gerado com muitos pontos e variação de raio, como o
  // rascunho de referência (silhueta de "monte de carne")
  if (!ent._hull) {
    const n = 20;
    const pts = [];
    for (let i = 0; i < n; i++) {
      const a = (i / n) * Math.PI * 2 - Math.PI / 2;
      // topo (a perto de -PI/2) tem pequenas denteações; corpo mais cheio
      const bump = Math.sin(a * 5 + rand(0, 6)) * 0.06;
      const baseRad = a < -0.3 && a > -2.8 ? rand(0.78, 0.95) : rand(0.55, 0.75);
      pts.push({ a, rad: baseRad + bump, jag: rand(0, Math.PI * 2) });
    }
    ent._hull = pts;
  }

  ctx.beginPath();
  ent._hull.forEach((p, i) => {
    const jitter = 1 + Math.sin(T * 0.5 + p.jag) * 0.015;
    const rr = p.rad * r * beat * jitter;
    // achata levemente nas laterais e alonga para cima, dando silhueta
    // de "pico" sem ser um triângulo perfeito
    const hx = Math.cos(p.a) * rr * 0.68;
    const hy = Math.sin(p.a) * rr * (Math.sin(p.a) < 0 ? 1.15 : 0.85);
    if (i === 0) ctx.moveTo(hx, hy); else ctx.lineTo(hx, hy);
  });
  ctx.closePath();
  const hullGrad = ctx.createLinearGradient(-r * 0.5, -r, r * 0.5, r * 0.8);
  hullGrad.addColorStop(0, 'rgba(168,26,30,.96)');
  hullGrad.addColorStop(0.5, 'rgba(200,44,42,.97)');
  hullGrad.addColorStop(1, 'rgba(125,15,18,.96)');
  ctx.fillStyle = hullGrad; ctx.fill();
  ctx.strokeStyle = 'rgba(10,6,6,.9)';
  ctx.lineWidth = Math.max(1.3, r * 0.048);
  ctx.stroke();

  ctx.save();
  ctx.clip();
  const innerShade = ctx.createRadialGradient(-r*0.1, -r*0.3, r*0.15, 0, 0, r * 1.1);
  innerShade.addColorStop(0, 'rgba(0,0,0,0)');
  innerShade.addColorStop(1, 'rgba(55,4,6,.55)');
  ctx.beginPath(); ctx.arc(0, 0, r * 1.3, 0, Math.PI * 2);
  ctx.fillStyle = innerShade; ctx.fill();

  // ── TEXTURA DE FIBRA: rabiscos curvos densos e soltos cobrindo toda
  // a superfície — curvas em "C" e "S" de vários tamanhos e ângulos,
  // como garranchos de caneta, não linhas retas organizadas em grade
  if (!ent._scribbles) {
    ent._scribbles = Array.from({length: 22}, () => ({
      x: rand(-0.7, 0.7), y: rand(-1.0, 0.9),
      len: rand(0.18, 0.4), rot: rand(0, Math.PI * 2),
      curve: rand(-1, 1), dark: Math.random() < 0.55,
      w: rand(0.9, 1.6),
    }));
  }
  ent._scribbles.forEach(s => {
    ctx.save();
    ctx.translate(s.x * r, s.y * r);
    ctx.rotate(s.rot);
    ctx.beginPath();
    ctx.moveTo(-s.len * r * 0.5, 0);
    ctx.quadraticCurveTo(0, s.curve * s.len * r * 0.7, s.len * r * 0.5, 0);
    ctx.strokeStyle = s.dark ? 'rgba(95,10,14,.55)' : 'rgba(225,105,95,.42)';
    ctx.lineWidth = Math.max(0.5, s.w * r * 0.016);
    ctx.stroke();
    ctx.restore();
  });

  // veios mais grossos e longos por cima, poucos, para dar variação
  // de escala na textura (igual ao rascunho, que mistura riscos finos
  // e grossos)
  if (!ent._thickVeins) {
    ent._thickVeins = Array.from({length: 5}, () => ({
      x0: rand(-0.5, 0.5), y0: rand(-0.95, -0.3),
      x1: rand(-0.5, 0.5), y1: rand(0.1, 0.85),
      curve: rand(-0.3, 0.3),
    }));
  }
  ent._thickVeins.forEach(v => {
    ctx.beginPath();
    ctx.moveTo(v.x0 * r, v.y0 * r);
    ctx.quadraticCurveTo((v.x0+v.x1)*0.5*r + v.curve*r, (v.y0+v.y1)*0.5*r, v.x1 * r, v.y1 * r);
    ctx.strokeStyle = 'rgba(90,8,12,.4)';
    ctx.lineWidth = Math.max(0.7, r * 0.025);
    ctx.stroke();
  });
  ctx.restore(); // fim do clip

  // ── OLHOS: afundados na textura, coluna vertical central, formato
  // amendoado, piscando fora de sincronia
  if (!ent._eyes) {
    ent._eyes = [
      { x: 0.05, y: -0.5, w: 0.14, h: 0.07, rot: -0.05 },
      { x: -0.08, y: -0.1, w: 0.16, h: 0.075, rot: 0.04 },
      { x: 0.1, y: 0.3, w: 0.12, h: 0.06, rot: -0.08 },
    ].map(e => ({ ...e, blinkOffset: rand(0, 10), blinkSpeed: rand(0.3, 0.55) }));
  }
  ent._eyes.forEach(e => {
    const blinkCycle = (T * e.blinkSpeed + e.blinkOffset) % 6.5;
    const openness = blinkCycle < 6.0 ? 1 : Math.abs(Math.sin((blinkCycle - 6.0) * Math.PI / 0.5));
    ctx.save(); ctx.translate(e.x * r, e.y * r); ctx.rotate(e.rot);
    const ew = e.w * r, eh = Math.max(0.6, e.h * r * openness);
    ctx.beginPath();
    ctx.moveTo(-ew, 0);
    ctx.quadraticCurveTo(0, -eh, ew, 0);
    ctx.quadraticCurveTo(0, eh, -ew, 0);
    ctx.closePath();
    ctx.fillStyle = 'rgba(232,222,208,.95)'; ctx.fill();
    ctx.strokeStyle = 'rgba(20,6,6,.85)'; ctx.lineWidth = Math.max(0.6, r * 0.018); ctx.stroke();
    if (openness > 0.2) {
      ctx.beginPath(); ctx.arc(0, 0, eh * 0.65, 0, Math.PI * 2);
      ctx.fillStyle = '#120303'; ctx.fill();
    }
    ctx.restore();
  });

  // ── RASGO central abaixo dos olhos
  if (!ent._slit) {
    ent._slit = { x: 0.0, y: 0.58, w: 0.055, h: 0.2, rot: rand(-0.08, 0.08) };
  }
  {
    const s = ent._slit;
    ctx.save(); ctx.translate(s.x * r, s.y * r); ctx.rotate(s.rot);
    ctx.beginPath();
    ctx.moveTo(0, -s.h * r);
    ctx.quadraticCurveTo(s.w * r, 0, 0, s.h * r);
    ctx.quadraticCurveTo(-s.w * r, 0, 0, -s.h * r);
    ctx.closePath();
    ctx.fillStyle = 'rgba(16,3,5,.92)'; ctx.fill();
    ctx.strokeStyle = 'rgba(220,115,105,.4)';
    ctx.lineWidth = Math.max(0.5, r * 0.014);
    ctx.stroke();
    ctx.restore();
  }

  // ── FILAMENTOS/TENTÁCULOS curtos e grossos saindo de quase toda a
  // borda do casco (não só 3 pontos) — mais parecido com o rascunho,
  // onde tripas cercam quase todo o contorno
  if (!ent._strands) {
    ent._strands = ent._hull
      .filter((_, i) => i % 2 === 0)
      .map(p => ({
        a: p.a, rad: p.rad,
        len: rand(0.22, 0.55), wob: rand(0, Math.PI * 2), thick: rand(0.035, 0.06),
      }));
  }
  ent._strands.forEach(st => {
    const wob = Math.sin(T * 1.2 + st.wob) * 0.06;
    const rr = st.rad * r * beat;
    const bx = Math.cos(st.a) * rr * 0.68;
    const by = Math.sin(st.a) * rr * (Math.sin(st.a) < 0 ? 1.15 : 0.85);
    const outDirX = Math.cos(st.a), outDirY = Math.sin(st.a);
    const ex = bx + outDirX * st.len * r + wob * r * 0.3;
    const ey = by + outDirY * st.len * r;
    ctx.beginPath();
    ctx.moveTo(bx, by);
    ctx.quadraticCurveTo(bx + outDirX * st.len * r * 0.5, by + outDirY * st.len * r * 0.5 + wob * r, ex, ey);
    ctx.strokeStyle = 'rgba(40,17,19,.8)';
    ctx.lineWidth = Math.max(0.9, st.thick * r);
    ctx.lineCap = 'round';
    ctx.stroke();
  });

  ctx.rotate(-facing); ctx.restore();

  if (sandboxMode) {
    ctx.font = `${Math.max(7, r * 0.4)}px 'Courier New'`;
    ctx.fillStyle = 'rgba(220,80,95,.7)'; ctx.textAlign = 'center';
    ctx.fillText('🩸 VÍSCERA', sx, sy + r * 1.25 + 6 * cam.zoom);
    ctx.textAlign = 'left';
  }
}

function _cosmicDrawRoboticaShip(ent, sx, sy, cam_zoom) {
  const scale = ent.scale * cam_zoom;
  const r = Math.max(11 * cam_zoom, 16 * scale);
  const T = ent.phase;
  const moveAngle = ent.angle;
  // nave aponta "para cima" no design de origem (coroa no topo, jato
  // embaixo), alinhamos a proa com a direção de movimento
  const facing = moveAngle + Math.PI / 2;

  ctx.save();
  ctx.translate(sx, sy); ctx.rotate(facing);

  // Aura ciano-tecnológica discreta
  const aura = ctx.createRadialGradient(0, -r * 0.2, r * 0.4, 0, -r * 0.2, r * 1.8);
  aura.addColorStop(0, `rgba(110,200,255,${0.12 + 0.04 * Math.sin(T * 1.4)})`);
  aura.addColorStop(1, 'transparent');
  ctx.beginPath(); ctx.arc(0, -r * 0.2, r * 1.8, 0, Math.PI * 2); ctx.fillStyle = aura; ctx.fill();

  // ── JATO DE PROPULSÃO na base — chama ciano pulsante, atrás de tudo
  const jetPulse = 0.7 + 0.3 * Math.max(0, Math.sin(T * 5));
  const jetLen = r * (0.55 + 0.25 * jetPulse);
  const jetGrad = ctx.createLinearGradient(0, r * 0.85, 0, r * 0.85 + jetLen);
  jetGrad.addColorStop(0, `rgba(180,235,255,${0.8 * jetPulse})`);
  jetGrad.addColorStop(0.5, `rgba(100,190,255,${0.45 * jetPulse})`);
  jetGrad.addColorStop(1, 'rgba(80,160,255,0)');
  ctx.beginPath();
  ctx.moveTo(-r * 0.12, r * 0.85);
  ctx.lineTo(r * 0.12, r * 0.85);
  ctx.lineTo(r * 0.05, r * 0.85 + jetLen);
  ctx.lineTo(-r * 0.05, r * 0.85 + jetLen);
  ctx.closePath();
  ctx.fillStyle = jetGrad; ctx.fill();

  // ── MANTO/CASACO TECNOLÓGICO: painéis triangulares descendo do
  // pilar central, como uma "saia" de placas articuladas — fica logo
  // acima do jato
  if (!ent._coatPanels) {
    ent._coatPanels = [-0.42, -0.2, 0.02, 0.24, 0.44].map((x, i) => ({
      x, w: 0.22, len: rand(0.42, 0.58), wob: rand(0, Math.PI * 2),
    }));
  }
  ent._coatPanels.forEach(p => {
    const topY = r * 0.15;
    const botY = topY + r * p.len;
    ctx.beginPath();
    ctx.moveTo((p.x - p.w * 0.5) * r, topY);
    ctx.lineTo((p.x + p.w * 0.5) * r, topY);
    ctx.lineTo(p.x * r, botY);
    ctx.closePath();
    const coatGrad = ctx.createLinearGradient(0, topY, 0, botY);
    coatGrad.addColorStop(0, 'rgba(60,90,110,.92)');
    coatGrad.addColorStop(1, 'rgba(30,50,65,.88)');
    ctx.fillStyle = coatGrad; ctx.fill();
    ctx.strokeStyle = 'rgba(140,215,255,.4)';
    ctx.lineWidth = Math.max(0.6, r * 0.02);
    ctx.stroke();
  });
  // linha de luz ciano entre os painéis do manto (frestas tecnológicas)
  ent._coatPanels.forEach(p => {
    const glow = 0.3 + 0.25 * Math.max(0, Math.sin(T * 1.6 + p.wob));
    ctx.beginPath();
    ctx.moveTo(p.x * r, r * 0.15);
    ctx.lineTo(p.x * r, r * 0.15 + r * p.len * 0.9);
    ctx.strokeStyle = `rgba(150,220,255,${glow})`;
    ctx.lineWidth = Math.max(0.5, r * 0.014);
    ctx.stroke();
  });

  // ── PILAR CENTRAL: corpo estrutural entre a coroa e o manto,
  // painéis metálicos com detalhes técnicos (linhas, pequenos rebites)
  ctx.beginPath();
  ctx.moveTo(-r * 0.24, -r * 0.15);
  ctx.lineTo(r * 0.24, -r * 0.15);
  ctx.lineTo(r * 0.28, r * 0.2);
  ctx.lineTo(-r * 0.28, r * 0.2);
  ctx.closePath();
  const pillarGrad = ctx.createLinearGradient(-r * 0.28, 0, r * 0.28, 0);
  pillarGrad.addColorStop(0, 'rgba(70,95,110,.95)');
  pillarGrad.addColorStop(0.5, 'rgba(110,150,170,.95)');
  pillarGrad.addColorStop(1, 'rgba(60,85,100,.95)');
  ctx.fillStyle = pillarGrad; ctx.fill();
  ctx.strokeStyle = 'rgba(150,220,255,.5)';
  ctx.lineWidth = Math.max(0.6, r * 0.025);
  ctx.stroke();
  // detalhe: pequena linha de luz central no pilar
  ctx.beginPath();
  ctx.moveTo(0, -r * 0.12); ctx.lineTo(0, r * 0.16);
  ctx.strokeStyle = `rgba(160,225,255,${0.4 + 0.3 * Math.max(0, Math.sin(T * 2))})`;
  ctx.lineWidth = Math.max(0.5, r * 0.016);
  ctx.stroke();

  // ── COROA DE TRÊS PONTAS: braços de suporte assimétricos saindo do
  // topo do pilar em direção aos cantos superiores, curvando para
  // dentro no topo — como uma coroa segurando algo no centro
  if (!ent._crownArms) {
    ent._crownArms = [
      { baseA: Math.PI * 0.5 + 0.15, spanA: -1.15, len: 0.85 }, // esquerda
      { baseA: Math.PI * 0.5 - 0.15, spanA: 1.15, len: 0.85 },  // direita
      { baseA: Math.PI * 0.5, spanA: 0, len: 0.95, straight: true }, // central-traseiro (o "cabo" do rascunho)
    ];
  }
  const crownBaseY = -r * 0.15;
  ent._crownArms.forEach((arm, i) => {
    ctx.beginPath();
    if (arm.straight) {
      // braço reto inclinado para trás, como o cabo/antena do rascunho
      ctx.moveTo(-r * 0.05, crownBaseY);
      ctx.lineTo(-r * arm.len * 0.55, crownBaseY - r * arm.len);
    } else {
      const a0 = arm.baseA;
      const cx = Math.cos(a0) * r * 0.22, cy = -r * 0.15 - Math.sin(a0 - Math.PI*0.5) * 0;
      const endX = Math.sign(arm.spanA) * r * 0.65;
      const endY = crownBaseY - r * arm.len;
      ctx.moveTo(Math.sign(arm.spanA) * r * 0.22, crownBaseY);
      ctx.quadraticCurveTo(Math.sign(arm.spanA) * r * 0.55, crownBaseY - r * arm.len * 0.65, endX * 0.75, endY);
    }
    ctx.strokeStyle = 'rgba(130,175,195,.95)';
    ctx.lineWidth = Math.max(1.1, r * 0.045);
    ctx.lineCap = 'round';
    ctx.stroke();
    // núcleo de luz no meio do braço
    ctx.strokeStyle = `rgba(170,225,255,${0.5 + 0.3*Math.max(0,Math.sin(T*1.8+i))})`;
    ctx.lineWidth = Math.max(0.5, r * 0.015);
    ctx.stroke();
  });

  // pontas de apoio (pequenos suportes angulares nas extremidades dos
  // dois braços laterais, tipo "mãos" segurando o pulsar)
  [-1, 1].forEach(side => {
    const ex = side * r * 0.49, ey = crownBaseY - r * 0.85 * 0.65 - r * 0.85 * 0.0;
    const tipX = side * r * 0.49, tipY = crownBaseY - r * 0.85;
    ctx.save();
    ctx.translate(tipX, tipY);
    ctx.rotate(side * -0.5);
    ctx.beginPath();
    ctx.moveTo(0, 0);
    ctx.lineTo(side * r * 0.14, r * 0.06);
    ctx.lineTo(side * r * 0.08, -r * 0.08);
    ctx.closePath();
    ctx.fillStyle = 'rgba(90,130,150,.95)';
    ctx.fill();
    ctx.strokeStyle = 'rgba(160,225,255,.6)';
    ctx.lineWidth = Math.max(0.5, r * 0.018);
    ctx.stroke();
    ctx.restore();
  });

  // ── PULSAR FLUTUANTE: reaproveita o visual do astro Pulsar (núcleo
  // branco-ciano com halo em camadas e cintilação por dois senos),
  // levitando entre as pontas — treme/pulsa no lugar, NUNCA gira
  const pulsarY = crownBaseY - r * 0.78; // posição fixa, sem levitação
  const sh1 = Math.sin(T * 18 + 1.3);
  const sh2 = Math.sin(T * 25.4 + 0.8);
  const shimmer = Math.max(0.15, 0.55 + 0.28 * sh1 + 0.20 * sh2); // cintilação irregular, sem giro
  const coreR = r * 0.13;

  // Halo externo em camadas (igual ao Pulsar real, cores mais brancas/ciano)
  for (let i = 3; i >= 1; i--) {
    const hg = ctx.createRadialGradient(0, pulsarY, coreR * 0.9, 0, pulsarY, coreR * (1.1 + i * 0.9));
    hg.addColorStop(0, `rgba(200,245,255,${(0.22 - i * 0.04) * shimmer})`);
    hg.addColorStop(0.5, `rgba(140,220,255,${(0.1 - i * 0.02) * shimmer})`);
    hg.addColorStop(1, 'transparent');
    ctx.beginPath(); ctx.arc(0, pulsarY, coreR * (1.1 + i * 0.9), 0, Math.PI * 2);
    ctx.fillStyle = hg; ctx.fill();
  }
  // Núcleo — gradiente branco puro no centro, ciano nas bordas (mais
  // frio/branco que o Pulsar padrão, sem tender a azul-roxo)
  const coreGrad = ctx.createRadialGradient(-coreR * 0.2, pulsarY - coreR * 0.2, coreR * 0.04, 0, pulsarY, coreR);
  coreGrad.addColorStop(0, '#ffffff');
  coreGrad.addColorStop(0.3, 'rgba(225,250,255,1)');
  coreGrad.addColorStop(0.6, 'rgba(160,235,255,0.97)');
  coreGrad.addColorStop(0.88, `rgba(190,240,255,${0.7 + shimmer * 0.25})`);
  coreGrad.addColorStop(1, `rgba(140,220,255,${0.4 + shimmer * 0.35})`);
  ctx.beginPath(); ctx.arc(0, pulsarY, coreR, 0, Math.PI * 2);
  ctx.fillStyle = coreGrad; ctx.fill();

  // ── FEIXES BIPOLARES reais: o pulsar emite dois jatos opostos ao
  // longo de um eixo que gira lentamente (como o poleAngle do Pulsar
  // real), estendendo-se BEM além da coroa — não presos às pontas de
  // apoio. Cone bem estreito + linha central + espinha brilhante.
  if (ent._poleAngle === undefined) {
    ent._poleAngle = rand(0, Math.PI * 2);
    // direção aleatória (sentido horário ou anti-horário), mas
    // velocidade sempre visível — nunca sorteia algo perto de zero
    ent._poleDrift = (Math.random() < 0.5 ? -1 : 1) * rand(0.5, 0.9);
  }
  ent._poleAngle += ent._poleDrift * 0.016; // giro contínuo e sempre perceptível

  const beamLen = r * 3.4; // se estende bem além da nave inteira
  const coneHalf = 0.045;

  for (let pole = 0; pole < 2; pole++) {
    const beamAngle = ent._poleAngle + pole * Math.PI;
    const bx = Math.cos(beamAngle) * beamLen, by = Math.sin(beamAngle) * beamLen;

    const e1x = Math.cos(beamAngle + coneHalf), e1y = Math.sin(beamAngle + coneHalf);
    const e2x = Math.cos(beamAngle - coneHalf), e2y = Math.sin(beamAngle - coneHalf);
    ctx.beginPath();
    ctx.moveTo(0, pulsarY);
    ctx.lineTo(e1x * beamLen, pulsarY + e1y * beamLen);
    ctx.lineTo(e2x * beamLen, pulsarY + e2y * beamLen);
    ctx.closePath();
    const cg = ctx.createLinearGradient(0, pulsarY, bx, pulsarY + by);
    cg.addColorStop(0, `rgba(220,245,255,0)`);
    cg.addColorStop(0.04, `rgba(210,240,255,${0.4 * shimmer})`);
    cg.addColorStop(0.25, `rgba(150,220,255,${0.16 * shimmer})`);
    cg.addColorStop(0.6, `rgba(120,200,255,${0.06 * shimmer})`);
    cg.addColorStop(1, `rgba(100,180,255,0)`);
    ctx.fillStyle = cg; ctx.fill();

    // Linha central com gradiente longitudinal branco→ciano
    const bg = ctx.createLinearGradient(0, pulsarY, bx, pulsarY + by);
    bg.addColorStop(0, `rgba(255,255,255,0)`);
    bg.addColorStop(0.02, `rgba(255,255,255,${shimmer})`);
    bg.addColorStop(0.15, `rgba(190,235,255,${0.55 * shimmer})`);
    bg.addColorStop(0.5, `rgba(150,215,255,${0.22 * shimmer})`);
    bg.addColorStop(1, `rgba(140,220,255,0)`);
    ctx.beginPath(); ctx.moveTo(0, pulsarY); ctx.lineTo(bx, pulsarY + by);
    ctx.strokeStyle = bg;
    ctx.lineWidth = Math.max(0.5, r * 0.014);
    ctx.lineCap = 'round';
    ctx.stroke();

    // Espinha ultrabrilhante nos primeiros 25% do jato
    const spLen = beamLen * 0.25;
    const spX = Math.cos(beamAngle) * spLen, spY = Math.sin(beamAngle) * spLen;
    const sg = ctx.createLinearGradient(0, pulsarY, spX, pulsarY + spY);
    sg.addColorStop(0, `rgba(255,255,255,0)`);
    sg.addColorStop(0.08, `rgba(255,255,255,${shimmer})`);
    sg.addColorStop(1, `rgba(210,240,255,0)`);
    ctx.beginPath(); ctx.moveTo(0, pulsarY); ctx.lineTo(spX, pulsarY + spY);
    ctx.strokeStyle = sg;
    ctx.lineWidth = Math.max(0.35, r * 0.006);
    ctx.stroke();
  }


  ctx.restore();

  if (sandboxMode) {
    ctx.font = `${Math.max(7, r * 0.4)}px 'Courier New'`;
    ctx.fillStyle = 'rgba(140,210,255,.75)'; ctx.textAlign = 'center';
    ctx.fillText('🤖 ROBÓTICA', sx, sy + r * 1.15 + 6 * cam.zoom);
    ctx.textAlign = 'left';
  }
}


function cosmicRacesDraw(ctx) {
  if (_isBattle()) return; // some visualmente durante batalha de boss
  for (let i = 0; i < _cosmicEntities.length; i++) {
    const ent = _cosmicEntities[i];
    const race = COSMIC_RACES[ent.raceId];
    const sx = (ent.x - cam.x) * cam.zoom + canvas.width * 0.5;
    const sy = (ent.y - cam.y) * cam.zoom + canvas.height * 0.5;

    if (sx < -80 || sx > canvas.width + 80 || sy < -80 || sy > canvas.height + 80) continue;

    const entranceFade = Math.min(1, ent.spawnT / 1.2);
    ctx.save();
    ctx.globalAlpha = entranceFade;

    if (ent.raceId === 'plasmicea') {
      _cosmicDrawPlasmiceaShip(ent, sx, sy, cam.zoom);
      ctx.restore();
      continue;
    }
    if (ent.raceId === 'fungica') {
      _cosmicDrawFungicaShip(ent, sx, sy, cam.zoom);
      ctx.restore();
      continue;
    }
    if (ent.raceId === 'necrida') {
      _cosmicDrawNecridaShip(ent, sx, sy, cam.zoom);
      ctx.restore();
      continue;
    }
    if (ent.raceId === 'viscera') {
      _cosmicDrawVisceraShip(ent, sx, sy, cam.zoom);
      ctx.restore();
      continue;
    }
    if (ent.raceId === 'robotica') {
      _cosmicDrawRoboticaShip(ent, sx, sy, cam.zoom);
      ctx.restore();
      continue;
    }

    const baseR = 6 * ent.scale * cam.zoom;

    const grd = ctx.createRadialGradient(sx, sy, 0, sx, sy, baseR * 3);
    grd.addColorStop(0, race.glow);
    grd.addColorStop(1, 'rgba(0,0,0,0)');
    ctx.beginPath();
    ctx.arc(sx, sy, baseR * 3, 0, Math.PI * 2);
    ctx.fillStyle = grd;
    ctx.fill();

    let r = baseR;
    if (race.behavior === 'cling-dense') r *= 1 + Math.sin(ent.phase * 2) * 0.18;
    if (race.behavior === 'wander-decay') r *= 1 - 0.1 * Math.sin(ent.phase * 0.7);
    if (race.behavior === 'orbit-hot') r *= 1 + Math.sin(ent.phase * 4) * 0.12;

    ctx.beginPath();
    ctx.arc(sx, sy, Math.max(1.5, r), 0, Math.PI * 2);
    ctx.fillStyle = race.color;
    ctx.fill();

    if (race.behavior === 'patrol-mission') {
      ctx.beginPath();
      ctx.moveTo(sx, sy);
      ctx.lineTo(sx + Math.cos(ent.angle) * r * 2.4, sy + Math.sin(ent.angle) * r * 2.4);
      ctx.strokeStyle = race.color;
      ctx.lineWidth = 1.2;
      ctx.stroke();
    }

    ctx.restore();
  }
}

// ── Limpeza (opcional, ao sair da Fase Cósmica) ──────────────────────
function cosmicRacesReset() {
  _cosmicEntities = [];
  _cosmicSpawnTimer = 0;
  _cosmicNextSpawnAt = COSMIC_SPAWN_INTERVAL_MIN;
}

// ═══════════════════════════════════════════════════════════════════
//  MÓDULO: MONSTROS ERRANTES — hostis, vagam livres pelo mapa
// ═══════════════════════════════════════════════════════════════════
//  Diferente das 5 raças cósmicas (presas a bioma/host), estes vagam
//  livremente por toda a Fase Cósmica, perseguem e atacam astros do
//  jogador quando avistam um por perto. Nascem perto da câmera (mesmo
//  padrão de spawn/despawn das entidades cósmicas) e "atacam" alterando
//  os bio-campos do astro (bioTemp/bioO2/bioWater) e reduzindo
//  lentamente seu raio/massa — não existe HP formal em astros comuns,
//  então o dano é corrosão gradual da composição, não uma barra de vida.
// ═══════════════════════════════════════════════════════════════════

const COSMIC_MONSTER_MAX = 26;
const COSMIC_MONSTER_SPAWN_INTERVAL_MIN = 0.8;
const COSMIC_MONSTER_SPAWN_INTERVAL_MAX = 2.2;
const COSMIC_MONSTER_DESPAWN_TIME = 12; // mesmo prazo das entidades de raça
const COSMIC_MONSTER_AGGRO_RANGE = 900; // distância p/ notar um astro e perseguir

const COSMIC_MONSTER_TYPES = {
  sporeling: {
    id: 'sporeling',
    name: 'Esporo Errante',
    color: '#9dff7a',
    radius: () => rand(7, 11),
    speed: 130,
    turnGain: 6, angleLerp: 5, velLerp: 5,
    swarm: true,          // nasce em grupos
    swarmSize: () => randInt(5, 9),
    attackRange: 32,
    attackInterval: 0.7,
    attackPower: 'weak',  // altera bio-campos, sem corroer raio
  },
  voidmaw: {
    id: 'voidmaw',
    name: 'Devorador de Vazio',
    color: '#c98bff',
    radius: () => rand(24, 32),
    speed: 78,
    turnGain: 4, angleLerp: 3.2, velLerp: 3,
    swarm: false,
    attackRange: 48,
    attackInterval: 1.1,
    attackPower: 'medium', // corrói raio + altera bio-campos forte
  },
  crystalsentinel: {
    id: 'crystalsentinel',
    name: 'Sentinela Cristalina',
    color: '#7fd7ff',
    radius: () => rand(38, 48),
    speed: 34,
    turnGain: 2, angleLerp: 1.6, velLerp: 1.4,
    swarm: false,
    attackRange: 70,
    attackInterval: 1.6,
    attackPower: 'strong', // corrói raio rápido, alcance maior
  },
};
const COSMIC_MONSTER_TYPE_IDS = Object.keys(COSMIC_MONSTER_TYPES);

let _cosmicMonsters = [];
let _cosmicMonsterSpawnTimer = 0;
let _cosmicMonsterNextSpawnAt = COSMIC_MONSTER_SPAWN_INTERVAL_MIN;
let _cosmicMonsterIdCounter = 1;

function _cosmicMakeMonster(typeId, x, y) {
  const def = COSMIC_MONSTER_TYPES[typeId];
  const r = def.radius();
  return {
    id: 'monster_' + (_cosmicMonsterIdCounter++),
    typeId,
    x, y,
    angle: rand(0, Math.PI * 2),
    radius: r,
    phase: rand(0, Math.PI * 2),
    offscreenT: 0,
    targetId: null,
    attackCd: rand(0, def.attackInterval),
    // ── HP: usado apenas pelas unidades defensivas da Fase Cósmica
    // (Torre/Sentinela/Cavaleiro/Mago) para poder derrotar o monstro.
    // Não afeta nenhuma lógica de ataque/corrosão já existente contra
    // astros — é um sistema adicional, em paralelo. ────────────────────
    hp: r * (def.attackPower === 'strong' ? 9 : def.attackPower === 'medium' ? 6 : 4),
    maxHp: r * (def.attackPower === 'strong' ? 9 : def.attackPower === 'medium' ? 6 : 4),
  };
}

function _cosmicSpawnMonsterWave() {
  // Durante o Eclipse do Núcleo Dimensional, o teto de monstros é maior.
  const _max = _eclipseActive ? COSMIC_MONSTER_MAX*3 : COSMIC_MONSTER_MAX;
  // Chance de disparar 2 pontos de invasão simultâneos em vez de 1 —
  // simula "vários cantos do mapa ficando perigosos ao mesmo tempo",
  // no espírito do Hardmode (spawn agressivo, não pontual).
  const burstPoints = Math.random() < 0.4 ? 2 : 1;
  for (let b = 0; b < burstPoints; b++) {
    if (_cosmicMonsters.length >= _max) break;
    const typeId = COSMIC_MONSTER_TYPE_IDS[Math.floor(rand(0, COSMIC_MONSTER_TYPE_IDS.length))];
    const def = COSMIC_MONSTER_TYPES[typeId];
    const count = def.swarm ? def.swarmSize() : randInt(1, 2);
    const basePos = _cosmicRollSpawnPos();
    for (let i = 0; i < count; i++) {
      if (_cosmicMonsters.length >= _max) break;
      const ox = rand(-50, 50), oy = rand(-50, 50);
      _cosmicMonsters.push(_cosmicMakeMonster(typeId, basePos.x + ox, basePos.y + oy));
    }
  }
}

function _cosmicMonsterFindTarget(mon) {
  if (typeof objects === 'undefined' || !objects.length) return null;
  let best = null, bestD = COSMIC_MONSTER_AGGRO_RANGE;
  for (const o of objects) {
    if (o.dead || o.fixed === true) continue; // ignora astros fixos (estrelas-âncora etc.) e mortos
    if (['comet', 'meteor'].includes((o.type || '').toLowerCase())) continue;
    const d = Math.hypot(o.x - mon.x, o.y - mon.y);
    if (d < bestD) { bestD = d; best = o; }
  }
  return best;
}

function _cosmicMonsterAttack(mon, def, target, dt) {
  mon.attackCd -= dt;
  if (mon.attackCd > 0) return;
  mon.attackCd = def.attackInterval;
  if (def.attackPower === 'weak') {
    target.bioTemp = Math.max(0, Math.min(100, (target.bioTemp ?? 50) + rand(-14, 14)));
    target.bioO2 = Math.max(0, (target.bioO2 ?? 21) - rand(1.5, 4));
    target.bioWater = Math.max(0, (target.bioWater ?? 30) - rand(0.5, 2));
  } else if (def.attackPower === 'medium') {
    target.bioWater = Math.max(0, (target.bioWater ?? 30) - rand(4, 9));
    target.bioO2 = Math.max(0, (target.bioO2 ?? 21) - rand(2, 5));
    target.bioTemp = Math.max(0, Math.min(100, (target.bioTemp ?? 50) + rand(-22, 22)));
    if (typeof target.radius === 'number' && target.radius > 4) target.radius -= rand(0.12, 0.35);
    if (typeof target.mass === 'number') target.mass = Math.max(1, target.mass - rand(0.3, 1.2));
  } else if (def.attackPower === 'strong') {
    target.bioO2 = Math.max(0, (target.bioO2 ?? 21) - rand(4, 9));
    target.bioWater = Math.max(0, (target.bioWater ?? 30) - rand(4, 9));
    target.bioTemp = Math.max(0, Math.min(100, (target.bioTemp ?? 50) + rand(-30, 30)));
    if (typeof target.radius === 'number' && target.radius > 4) target.radius -= rand(0.3, 0.8);
    if (typeof target.mass === 'number') target.mass = Math.max(1, target.mass - rand(1, 3));
  }
  // Corrosão severa e contínua pode destruir o astro de vez — dá peso real
  // à ameaça (sem isso, o "ataque" nunca tinha consequência definitiva).
  if (def.attackPower !== 'weak' && typeof target.radius === 'number' && target.radius <= 4.2 && !target.fixed) {
    target.dead = true;
    if (typeof spawnExplosion === 'function') spawnExplosion(target.x, target.y, 1, false);
  }
  if (typeof particles !== 'undefined') {
    const burst = def.attackPower === 'weak' ? 3 : def.attackPower === 'medium' ? 6 : 10;
    for (let i = 0; i < burst; i++) {
      const ang = rand(0, Math.PI * 2);
      particles.push({ x: target.x, y: target.y, vx: Math.cos(ang) * rand(2, 7), vy: Math.sin(ang) * rand(2, 7), r: rand(1.5, 3.5), alpha: 0.9, color: def.color || '#fff' });
    }
  }
}

function cosmicMonstersUpdate(dt) {
  // Durante o Eclipse do Núcleo Dimensional: spawn de monstros MUITO mais
  // frequente e teto de população bem maior — fenômeno raro e perigoso.
  const _eclipseMax = _eclipseActive ? COSMIC_MONSTER_MAX*3 : COSMIC_MONSTER_MAX;
  _cosmicMonsterSpawnTimer += dt;
  if (_cosmicMonsterSpawnTimer >= _cosmicMonsterNextSpawnAt && _cosmicMonsters.length < _eclipseMax) {
    _cosmicMonsterSpawnTimer = 0;
    _cosmicMonsterNextSpawnAt = _eclipseActive
      ? rand(COSMIC_MONSTER_SPAWN_INTERVAL_MIN*0.12, COSMIC_MONSTER_SPAWN_INTERVAL_MAX*0.12)
      : rand(COSMIC_MONSTER_SPAWN_INTERVAL_MIN, COSMIC_MONSTER_SPAWN_INTERVAL_MAX);
    if (!_isBattle()) _cosmicSpawnMonsterWave();
  }
  // Durante batalha de boss: monstros existentes ficam parados, sem
  // atacar/perseguir, e projéteis deles também congelam.
  if (_isBattle()) return;

  cosmicProjectilesUpdate(dt);

  for (let i = _cosmicMonsters.length - 1; i >= 0; i--) {
    const mon = _cosmicMonsters[i];
    const def = COSMIC_MONSTER_TYPES[mon.typeId];
    // Morte por HP (dano recebido das unidades defensivas do jogador).
    // Checagem adicional, não interfere no despawn por offscreen já
    // existente logo abaixo.
    if (typeof mon.hp === 'number' && mon.hp <= 0) {
      if (typeof spawnExplosion === 'function') spawnExplosion(mon.x, mon.y, 0.8, false);
      _cosmicMonsters.splice(i, 1);
      continue;
    }
    mon.phase += dt;

    // Furtividade: Larva Fantasma passa a maior parte do tempo quase
    // invisível, "piscando" visível por instantes curtos — difícil de
    // acompanhar, reforça a tensão de "algo está vindo e eu não vejo".
    if (def.stealth) {
      mon._stealthCd = (mon._stealthCd ?? rand(1.5, 3)) - dt;
      mon._stealthVis = mon._stealthVis ?? 0.15;
      if (mon._stealthCd <= 0) {
        mon._stealthPeek = !mon._stealthPeek;
        mon._stealthCd = mon._stealthPeek ? rand(0.4, 0.7) : rand(1.5, 3);
      }
      mon._stealthVis += ((mon._stealthPeek ? 1 : 0.12) - mon._stealthVis) * Math.min(1, dt * 6);
    }

    let target = mon.targetId ? objects.find(o => o.id === mon.targetId && !o.dead) : null;
    if (!target) {
      target = _cosmicMonsterFindTarget(mon);
      mon.targetId = target ? target.id : null;
    }

    if (target) {
      const dx = target.x - mon.x, dy = target.y - mon.y;
      const d = Math.hypot(dx, dy) || 1;
      const targetAngle = Math.atan2(dy, dx);
      _cosmicSteerAngle(mon, dt, targetAngle, def.turnGain, def.angleLerp);

      if (def.attackPower === 'ranged') {
        // Kiting: mantém distância, atira sem precisar encostar.
        const desired = def.keepDistance || def.attackRange * 0.6;
        if (d < desired - 40) {
          _cosmicSteerVelocity(mon, dt, -(dx / d) * def.speed, -(dy / d) * def.speed, def.velLerp);
        } else if (d > desired + 40) {
          _cosmicSteerVelocity(mon, dt, (dx / d) * def.speed, (dy / d) * def.speed, def.velLerp);
        } else {
          _cosmicSteerVelocity(mon, dt, 0, 0, def.velLerp);
        }
        if (d <= def.attackRange) {
          mon.attackCd = (mon.attackCd ?? 0) - dt;
          if (mon.attackCd <= 0) {
            mon.attackCd = def.attackInterval;
            _cosmicFireProjectile(mon, def, target);
          }
        }
      } else if (d > def.attackRange * 0.7) {
        _cosmicSteerVelocity(mon, dt, (dx / d) * def.speed, (dy / d) * def.speed, def.velLerp);
      } else {
        _cosmicSteerVelocity(mon, dt, 0, 0, def.velLerp);
        const wasAlive = !target.dead;
        _cosmicMonsterAttack(mon, def, target, dt);
        if (wasAlive && target.dead && def.explodesOnDeath) {
          _cosmicMonsterExplode(mon, def);
        }
      }
    } else {
      // Sem alvo: vaga livre em direção sorteada, revisitada de tempos em tempos.
      if (!mon.wanderTarget || Math.hypot(mon.wanderTarget.x - mon.x, mon.wanderTarget.y - mon.y) < 60) {
        mon.wanderTarget = _cosmicRollSpawnPos();
      }
      const dx = mon.wanderTarget.x - mon.x, dy = mon.wanderTarget.y - mon.y;
      const d = Math.hypot(dx, dy) || 1;
      _cosmicSteerAngle(mon, dt, Math.atan2(dy, dx), def.turnGain, def.angleLerp);
      _cosmicSteerVelocity(mon, dt, (dx / d) * def.speed * 0.6, (dy / d) * def.speed * 0.6, def.velLerp);
    }

    if (_cosmicIsOutsideRef(mon)) {
      mon.offscreenT += dt;
      if (mon.offscreenT >= COSMIC_MONSTER_DESPAWN_TIME) { _cosmicMonsters.splice(i, 1); continue; }
    } else {
      mon.offscreenT = 0;
    }
  }
}

function _cosmicDrawSporeling(mon, sx, sy, r) {
  const pulse = 1 + 0.15 * Math.sin(mon.phase * 5);
  ctx.save(); ctx.translate(sx, sy); ctx.rotate(mon.angle);
  const g = ctx.createRadialGradient(0, 0, 0, 0, 0, r * 3 * pulse);
  g.addColorStop(0, 'rgba(140,255,110,0.5)'); g.addColorStop(1, 'transparent');
  ctx.beginPath(); ctx.arc(0, 0, r * 3 * pulse, 0, Math.PI * 2); ctx.fillStyle = g; ctx.fill();
  // Cluster de esporos orgânicos — vários blobs irregulares agrupados,
  // mais fiel a "esporo" do que a forma de estrela anterior.
  const blobs = [[0,0,1.0],[0.55,0.25,0.55],[-0.5,0.32,0.5],[0.15,-0.55,0.5],[-0.35,-0.4,0.45],[0.5,-0.18,0.4]];
  blobs.forEach(([bx,by,scale])=>{
    const px = bx*r*1.1*pulse, py = by*r*1.1*pulse, rr = r*0.55*scale*pulse;
    ctx.beginPath();
    for (let i=0;i<10;i++){
      const a=(i/10)*Math.PI*2;
      const wob=rr*(0.82+0.18*Math.sin(a*3+mon.phase*3+bx*5));
      const ppx=px+Math.cos(a)*wob, ppy=py+Math.sin(a)*wob;
      if(i===0) ctx.moveTo(ppx,ppy); else ctx.lineTo(ppx,ppy);
    }
    ctx.closePath();
    ctx.fillStyle='rgba(120,230,90,0.92)'; ctx.fill();
    ctx.strokeStyle='rgba(200,255,180,0.7)'; ctx.lineWidth=1.2; ctx.stroke();
    ctx.beginPath(); ctx.arc(px,py,rr*0.28,0,Math.PI*2); ctx.fillStyle='#2c5a1e'; ctx.fill();
  });
  // núcleo central brilhante, mais claro
  ctx.beginPath(); ctx.arc(0,0,r*0.26*pulse,0,Math.PI*2); ctx.fillStyle='#dcffc8'; ctx.fill();
  ctx.beginPath(); ctx.arc(0,0,r*0.11*pulse,0,Math.PI*2); ctx.fillStyle='#0d1a08'; ctx.fill();
  ctx.restore();
}

function _cosmicDrawVoidMaw(mon, sx, sy, r) {
  const pulse = 1 + 0.08 * Math.sin(mon.phase * 2.2);
  ctx.save(); ctx.translate(sx, sy); ctx.rotate(mon.angle);
  const g = ctx.createRadialGradient(0, 0, r * 0.3, 0, 0, r * 4 * pulse);
  g.addColorStop(0, 'rgba(90,0,140,0.35)'); g.addColorStop(0.6, 'rgba(40,0,70,0.18)'); g.addColorStop(1, 'transparent');
  ctx.beginPath(); ctx.arc(0, 0, r * 4 * pulse, 0, Math.PI * 2); ctx.fillStyle = g; ctx.fill();
  // Corpo — visto de cima como um disco irregular ao redor da boca central,
  // não mais um perfil lateral de "peixe".
  ctx.beginPath();
  for (let i=0;i<20;i++){
    const a=(i/20)*Math.PI*2;
    const wob=r*pulse*(1.05+0.06*Math.sin(a*6));
    const px=Math.cos(a)*wob, py=Math.sin(a)*wob;
    if(i===0) ctx.moveTo(px,py); else ctx.lineTo(px,py);
  }
  ctx.closePath();
  ctx.fillStyle='#37085a'; ctx.fill();
  ctx.strokeStyle='rgba(200,140,255,0.6)'; ctx.lineWidth=1.5; ctx.stroke();
  // Anel de dentes apontando pro centro — vórtice devorador visto de cima.
  const mouthOpen = 0.9 + 0.12 * Math.sin(mon.phase * 3);
  const toothOuter = r*0.78*pulse, toothInner = r*0.42*pulse*mouthOpen;
  const teeth = 14;
  for (let i=0;i<teeth;i++){
    const a=(i/teeth)*Math.PI*2, aw=(Math.PI*2/teeth)*0.38;
    const x1=Math.cos(a-aw)*toothOuter, y1=Math.sin(a-aw)*toothOuter;
    const x2=Math.cos(a+aw)*toothOuter, y2=Math.sin(a+aw)*toothOuter;
    const x3=Math.cos(a)*toothInner, y3=Math.sin(a)*toothInner;
    ctx.beginPath(); ctx.moveTo(x1,y1); ctx.lineTo(x2,y2); ctx.lineTo(x3,y3); ctx.closePath();
    ctx.fillStyle='#e8d9ff'; ctx.fill();
    ctx.strokeStyle='rgba(120,80,160,0.8)'; ctx.lineWidth=0.8; ctx.stroke();
  }
  // vórtice escuro no centro, com espirais girando
  ctx.beginPath(); ctx.arc(0,0,toothInner*0.95,0,Math.PI*2); ctx.fillStyle='#0a0012'; ctx.fill();
  for (let i=0;i<3;i++){
    const ang0=i*2.1+mon.phase;
    ctx.beginPath();
    for (let t=0;t<16;t++){
      const tt=t/15, a=ang0+tt*3.2, rr=toothInner*0.9*(1-tt*0.85);
      const px=Math.cos(a)*rr, py=Math.sin(a)*rr;
      if(t===0) ctx.moveTo(px,py); else ctx.lineTo(px,py);
    }
    ctx.strokeStyle='rgba(255,61,240,0.55)'; ctx.lineWidth=1.8; ctx.stroke();
  }
  // dois olhos rosa nas laterais do corpo — parte clara da criatura,
  // simétricos, não soltos no espaço.
  [[-0.62,-0.72],[0.62,-0.72]].forEach(([ex,ey])=>{
    const ex2=ex*r*pulse, ey2=ey*r*pulse;
    ctx.beginPath(); ctx.arc(ex2,ey2,r*0.18,0,Math.PI*2);
    ctx.fillStyle='#1e0030'; ctx.fill();
    ctx.strokeStyle='#ff3df0'; ctx.lineWidth=2; ctx.stroke();
    ctx.beginPath(); ctx.arc(ex2,ey2,r*0.09,0,Math.PI*2); ctx.fillStyle='#ff3df0'; ctx.fill();
    ctx.beginPath(); ctx.arc(ex2,ey2,r*0.035,0,Math.PI*2); ctx.fillStyle='#ffd9ff'; ctx.fill();
  });
  ctx.restore();
}

function _cosmicDrawCrystalSentinel(mon, sx, sy, r) {
  const pulse = 1 + 0.05 * Math.sin(mon.phase * 1.5);
  ctx.save(); ctx.translate(sx, sy);
  const g = ctx.createRadialGradient(0, 0, 0, 0, 0, r * 3.2 * pulse);
  g.addColorStop(0, 'rgba(90,200,255,0.3)'); g.addColorStop(1, 'transparent');
  ctx.beginPath(); ctx.arc(0, 0, r * 3.2 * pulse, 0, Math.PI * 2); ctx.fillStyle = g; ctx.fill();
  // anel externo de fragmentos cristalinos, girando devagar — sentinela.
  ctx.save(); ctx.rotate(mon.phase * 0.4);
  for (let i = 0; i < 6; i++) {
    const a = (i / 6) * Math.PI * 2;
    ctx.save(); ctx.rotate(a); ctx.translate(r * 1.15, 0);
    ctx.beginPath();
    ctx.moveTo(r * 0.5, 0); ctx.lineTo(0, -r * 0.22); ctx.lineTo(-r * 0.35, 0); ctx.lineTo(0, r * 0.22);
    ctx.closePath();
    const sg = ctx.createLinearGradient(-r * 0.3, 0, r * 0.5, 0);
    sg.addColorStop(0, '#0d4a66'); sg.addColorStop(1, '#7fd7ff');
    ctx.fillStyle = sg; ctx.fill();
    ctx.strokeStyle = 'rgba(220,250,255,0.7)'; ctx.lineWidth = 1; ctx.stroke();
    ctx.restore();
  }
  ctx.restore();
  // corpo hexagonal central com facetas internas nítidas — cristal de verdade.
  ctx.save(); ctx.rotate(mon.angle * 0.3);
  ctx.beginPath();
  for (let i = 0; i < 6; i++) {
    const a = (i / 6) * Math.PI * 2;
    const px = Math.cos(a) * r * pulse, py = Math.sin(a) * r * pulse;
    if (i === 0) ctx.moveTo(px, py); else ctx.lineTo(px, py);
  }
  ctx.closePath();
  const cg = ctx.createLinearGradient(-r, -r, r, r);
  cg.addColorStop(0, '#e6faff'); cg.addColorStop(0.5, '#7fd7ff'); cg.addColorStop(1, '#0d4a66');
  ctx.fillStyle = cg; ctx.fill();
  ctx.strokeStyle = '#fff'; ctx.lineWidth = 1.5; ctx.stroke();
  // linhas de facetamento saindo do centro pra cada vértice, com leve brilho.
  for (let i = 0; i < 6; i++) {
    const a = (i / 6) * Math.PI * 2;
    ctx.beginPath();
    ctx.moveTo(0, 0);
    ctx.lineTo(Math.cos(a) * r * pulse, Math.sin(a) * r * pulse);
    ctx.strokeStyle = 'rgba(255,255,255,0.45)'; ctx.lineWidth = 1;
    ctx.stroke();
  }
  const coreGlow = 0.7 + 0.3 * Math.sin(mon.phase * 2.5);
  ctx.beginPath(); ctx.arc(0, 0, r * 0.34, 0, Math.PI * 2); ctx.fillStyle = 'rgba(255,255,255,0.95)'; ctx.fill();
  ctx.beginPath(); ctx.arc(0, 0, r * 0.16, 0, Math.PI * 2); ctx.fillStyle = `rgba(120,220,255,${coreGlow})`; ctx.fill();
  ctx.restore();
  ctx.restore();
}

const COSMIC_MONSTER_DRAWERS = {
  sporeling: _cosmicDrawSporeling,
  voidmaw: _cosmicDrawVoidMaw,
  crystalsentinel: _cosmicDrawCrystalSentinel,
};

function cosmicMonstersDraw(ctxRef) {
  if (_isBattle()) return; // some visualmente durante batalha de boss
  _cosmicMonsters.forEach(mon => {
    const sx = (mon.x - cam.x) * cam.zoom + canvas.width * 0.5;
    const sy = (mon.y - cam.y) * cam.zoom + canvas.height * 0.5;
    if (sx < -80 || sx > canvas.width + 80 || sy < -80 || sy > canvas.height + 80) return;
    const r = mon.radius * cam.zoom;
    const drawer = COSMIC_MONSTER_DRAWERS[mon.typeId];
    if (drawer) drawer(mon, sx, sy, r);
  });
}

function cosmicMonstersReset() {
  _cosmicMonsters = [];
  _cosmicMonsterSpawnTimer = 0;
  _cosmicMonsterNextSpawnAt = COSMIC_MONSTER_SPAWN_INTERVAL_MIN;
}

// ═══════════════════════════════════════════════════════════════════
//  MÓDULO: SERPENTES GALÁCTICAS — gigantes (quase do tamanho da tela em
//  zoom normal), vagam pela Fase Cósmica caçando GALÁXIAS. Cada galáxia
//  perseguida tem 20% de chance de ser devorada (não devoram todas).
//  3 tipos, cada um com foco/ataque/defesa próprios:
//   - Roxa (Espaço):     equilibrada, foco em perseguição longa e
//                         distorção gravitacional na cauda (defesa: se
//                         teleporta/pisca curto quando atacada).
//   - Verde (Radioativa): agressiva, deixa rastro tóxico que dana astros
//                         vivos/naves que passarem perto (defesa: casca
//                         resistente, reduz dano recebido).
//   - Azul (Gelo):        lenta mas ataca congelando (paralisa) o que
//                         chega perto da cabeça (defesa: escudo de gelo
//                         que absorve o primeiro golpe e quebra).
// ═══════════════════════════════════════════════════════════════════
const GALAXY_SERPENT_TYPES = {
  purple: {
    name:'Serpente Cósmica Púrpura',
    icon:'🐍',
    core:'#7a1fff', glow:'#c9a3ff', accent:'#2a0a55',
    speedMult:1.0, segCount:22, headScale:1.0,
    devourChance:0.20,
    aggroRange:2600,
  },
  green: {
    name:'Serpente Radioativa',
    icon:'☢️',
    core:'#39ff6a', glow:'#c8ffb8', accent:'#0a3312',
    speedMult:1.25, segCount:20, headScale:0.95,
    devourChance:0.20,
    aggroRange:2200,
  },
  ice: {
    name:'Serpente de Gelo',
    icon:'❄️',
    core:'#3fd4ff', glow:'#dff7ff', accent:'#0a2a44',
    speedMult:0.72, segCount:26, headScale:1.15,
    devourChance:0.20,
    aggroRange:3000,
  }
};
const GALAXY_SERPENT_TYPE_IDS = Object.keys(GALAXY_SERPENT_TYPES);
const GALAXY_SERPENT_MAX = 6; // gigantes, mas o mapa cósmico é grande o bastante
let _galaxySerpents = [];
let _galaxySerpentSpawnTimer = 0;
let _galaxySerpentNextSpawnAt = rand(10,20);
let _galaxySerpentIdCounter = 1;

function _makeGalaxySerpent(typeId, wx, wy){
  const def = GALAXY_SERPENT_TYPES[typeId];
  const N = def.segCount;
  // Segmento gigante: a serpente inteira deve ocupar quase a tela toda
  // em zoom padrão (~1.0). segGap grande + segRadius grande fazem isso.
  const segGap = 260;
  const segments = Array.from({length:N},(_,i)=>({x:wx-i*segGap,y:wy}));
  return {
    id:'gserp_'+(_galaxySerpentIdCounter++),
    typeId, def,
    segments,
    headAngle: rand(0,Math.PI*2),
    turnTimer: rand(3,6),
    turnTarget: rand(0,Math.PI*2),
    speed: 2.6*def.speedMult,
    targetId: null,
    devourCd: rand(2,4),
    shieldHits: def === GALAXY_SERPENT_TYPES.ice ? 1 : 0, // Gelo: absorve 1 golpe
    flash: 0,
    t: rand(0,100),
    offscreenT: 0,
  };
}

function _galaxySerpentFindGalaxyTarget(serp){
  if (typeof objects === 'undefined' || !objects.length) return null;
  const head = serp.segments[0];
  let best=null, bestD=serp.def.aggroRange;
  for (const o of objects){
    if (o.dead || o.type!=='galaxy' || o._serpentClaimed) continue;
    const d = Math.hypot(o.x-head.x, o.y-head.y);
    if (d<bestD){ bestD=d; best=o; }
  }
  return best;
}

function galaxySerpentsUpdate(dt){
  if (_isBattle()) return; // não age durante batalhas de boss

  _galaxySerpentSpawnTimer += dt;
  if (_galaxySerpentSpawnTimer >= _galaxySerpentNextSpawnAt && _galaxySerpents.length < GALAXY_SERPENT_MAX){
    _galaxySerpentSpawnTimer = 0;
    _galaxySerpentNextSpawnAt = rand(15,28);
    const typeId = GALAXY_SERPENT_TYPE_IDS[Math.floor(rand(0,GALAXY_SERPENT_TYPE_IDS.length))];
    const pos = _cosmicRollSpawnPos();
    _galaxySerpents.push(_makeGalaxySerpent(typeId, pos.x, pos.y));
  }

  for (let si=_galaxySerpents.length-1; si>=0; si--){
    const serp = _galaxySerpents[si];
    serp.t += dt;
    serp.flash = Math.max(0, serp.flash - dt*1.5);

    // ── Alvo: busca uma galáxia próxima para caçar ──
    if (!serp.targetId || !objects.some(o=>o.id===serp.targetId && !o.dead && o.type==='galaxy')){
      const tgt = _galaxySerpentFindGalaxyTarget(serp);
      serp.targetId = tgt ? tgt.id : null;
      if (tgt) tgt._serpentClaimed = serp.id; // evita 2 serpentes mirarem na mesma galáxia
    }

    const head = serp.segments[0];
    let desiredAngle = null;
    const tgtObj = serp.targetId ? objects.find(o=>o.id===serp.targetId && !o.dead) : null;
    if (tgtObj){
      desiredAngle = Math.atan2(tgtObj.y-head.y, tgtObj.x-head.x);
    } else {
      // Sem alvo: vaga aleatoriamente
      serp.turnTimer -= dt;
      if (serp.turnTimer<=0){
        serp.turnTimer = rand(3,6);
        serp.turnTarget = rand(0,Math.PI*2);
      }
      desiredAngle = serp.turnTarget;
    }

    let da = desiredAngle - serp.headAngle;
    while(da>Math.PI) da-=Math.PI*2; while(da<-Math.PI) da+=Math.PI*2;
    serp.headAngle += da*0.02;
    const vx = Math.cos(serp.headAngle)*serp.speed;
    const vy = Math.sin(serp.headAngle)*serp.speed;
    head.x += vx*dt*60; head.y += vy*dt*60;

    // Corpo segue a cabeça (snake physics), gap proporcional ao tamanho gigante
    const segGap = 260;
    for (let i=1;i<serp.segments.length;i++){
      const a=serp.segments[i-1], b=serp.segments[i];
      const d=Math.hypot(a.x-b.x,a.y-b.y);
      if (d>segGap){
        const nx=(a.x-b.x)/d, ny=(a.y-b.y)/d;
        const excess=d-segGap;
        b.x += nx*excess*0.3; b.y += ny*excess*0.3;
      }
    }

    // ── Efeitos de foco por tipo, aplicados a astros próximos ao corpo ──
    if (serp.typeId==='green'){
      // Radioativa: rastro tóxico — dana levemente astros vivos próximos a qualquer segmento
      serp.segments.forEach(seg=>{
        objects.forEach(o=>{
          if (o.dead || o.fixed) return;
          if (!['entityStarDevourer','entityCosmicParasite','entityVoidSerpent','entityMechaWorld'].includes(o.type)) return;
          const d=Math.hypot(o.x-seg.x,o.y-seg.y);
          if (d<180 && typeof o.hp==='number'){ o.hp -= 6*dt; }
        });
      });
    } else if (serp.typeId==='ice'){
      // Gelo: paralisa levemente naves/astros vivos que cheguem perto da cabeça
      objects.forEach(o=>{
        if (o.dead || o.fixed) return;
        if (!['entityStarDevourer','entityCosmicParasite','entityVoidSerpent','entityMechaWorld'].includes(o.type)) return;
        const d=Math.hypot(o.x-head.x,o.y-head.y);
        if (d<220){ o.paralyzed = Math.max(o.paralyzed||0, 1.2); }
      });
    }
    // Roxa (Espaço): foco é perseguição/captura pura — sem efeito de área extra.

    // ── DEVORAÇÃO DE GALÁXIA: quando alcança o alvo, 20% de chance de
    // realmente devorar (as outras 80% ela "passa reto"/desiste e a
    // galáxia sobrevive, liberando-a para outra tentativa futura). ──
    serp.devourCd -= dt;
    if (tgtObj && serp.devourCd<=0){
      const d = Math.hypot(tgtObj.x-head.x, tgtObj.y-head.y);
      const reachDist = (tgtObj.radius||300)*0.5 + 200;
      if (d < reachDist){
        serp.devourCd = 3;
        if (Math.random() < serp.def.devourChance){
          tgtObj.dead = true;
          serp.flash = 1;
          showTooltip(`${serp.def.icon} ${serp.def.name} devorou uma galáxia inteira!`);
        } else {
          tgtObj._serpentClaimed = null; // desiste, libera a galáxia
          serp._serpentClaimed = null;
        }
        serp.targetId = null;
      }
    }

    // ── Despawn se ficar muito tempo fora da tela (mantém o mapa limpo) ──
    const sx=(head.x-cam.x)*cam.zoom+canvas.width*0.5;
    const sy=(head.y-cam.y)*cam.zoom+canvas.height*0.5;
    const margin=900;
    if (sx<-margin||sx>canvas.width+margin||sy<-margin||sy>canvas.height+margin){
      serp.offscreenT += dt;
      if (serp.offscreenT > 45) { _galaxySerpents.splice(si,1); continue; }
    } else {
      serp.offscreenT = 0;
    }
  }
}

function _drawGalaxySerpentSegment(ctx,x,y,r,def,isHead,flash){
  const glowR = r*1.6;
  const grad = ctx.createRadialGradient(x,y,r*0.2,x,y,glowR);
  grad.addColorStop(0, flash>0 ? '#ffffff' : def.core);
  grad.addColorStop(0.55, def.glow);
  grad.addColorStop(1, 'transparent');
  ctx.beginPath(); ctx.arc(x,y,glowR,0,Math.PI*2);
  ctx.fillStyle=grad; ctx.globalAlpha=0.55; ctx.fill(); ctx.globalAlpha=1;

  ctx.beginPath(); ctx.arc(x,y,r,0,Math.PI*2);
  ctx.fillStyle = flash>0 ? '#ffffff' : def.core;
  ctx.fill();
  ctx.lineWidth = Math.max(1.5, r*0.08);
  ctx.strokeStyle = def.accent;
  ctx.stroke();

  if (isHead){
    // Olhos simples, brilhantes
    const eyeR = r*0.18;
    [-0.5,0.5].forEach(sgn=>{
      ctx.beginPath();
      ctx.arc(x+sgn*r*0.4, y-r*0.15, eyeR, 0, Math.PI*2);
      ctx.fillStyle = def.glow;
      ctx.fill();
      ctx.beginPath();
      ctx.arc(x+sgn*r*0.4, y-r*0.15, eyeR*0.45, 0, Math.PI*2);
      ctx.fillStyle = '#000';
      ctx.fill();
    });
  }
}

function galaxySerpentsDraw(ctxRef){
  if (_isBattle()) return;
  _galaxySerpents.forEach(serp=>{
    const def = serp.def;
    // Raio gigante — em zoom ~1.0 a cabeça sozinha já cobre boa parte da tela
    const baseR = 210*def.headScale;
    for (let i=serp.segments.length-1;i>=0;i--){
      const seg = serp.segments[i];
      const sx=(seg.x-cam.x)*cam.zoom+canvas.width*0.5;
      const sy=(seg.y-cam.y)*cam.zoom+canvas.height*0.5;
      if (sx<-400||sx>canvas.width+400||sy<-400||sy>canvas.height+400) continue;
      const rFrac = 1 - (i/serp.segments.length)*0.55; // afunila para a cauda
      const r = baseR*rFrac*cam.zoom;
      _drawGalaxySerpentSegment(ctxRef, sx, sy, r, def, i===0, serp.flash);
    }
  });
}

function galaxySerpentsReset(){
  _galaxySerpents = [];
  _galaxySerpentSpawnTimer = 0;
  _galaxySerpentNextSpawnAt = rand(10,20);
  objects.forEach(o=>{ if(o.type==='galaxy') o._serpentClaimed=null; });
}

// ═══════════════════════════════════════════════════════════════════
//  MÓDULO: CARDUMES — grupos hostis que nadam em formação (corrente),
//  reaproveitando steering/ataque dos Monstros Errantes acima, mas com
//  uma camada extra de boid (coesão + alinhamento + separação) dentro
//  do próprio cardume, por cima da perseguição do alvo. Spawnam soltos
//  pelo mapa inteiro (não presos a bioma), bem comuns.
// ═══════════════════════════════════════════════════════════════════
const COSMIC_SHOAL_MAX = 160;             // teto total de indivíduos (soma de todos os cardumes) — bem mais alto, já que devem ser muito comuns
const COSMIC_SHOAL_SPAWN_INTERVAL_MIN = 6;
const COSMIC_SHOAL_SPAWN_INTERVAL_MAX = 11; // média ~8-9s entre novos cardumes = "um passando quase a cada 10s"
const COSMIC_SHOAL_DESPAWN_TIME = 12;
const COSMIC_SHOAL_AGGRO_RANGE = 820;
const COSMIC_SHOAL_NEIGHBOR_RANGE = 150;  // raio de percepção dos vizinhos do mesmo cardume
const COSMIC_SHOAL_SEPARATION_RANGE = 46; // distância mínima confortável entre indivíduos

const COSMIC_SHOAL_SPECIES = {
  // Cardume 1 — pequeno, numeroso, rápido: pressiona em número.
  agulhaz: {
    id: 'agulhaz',
    name: 'Agulhaz',
    color: '#7fe0ff',
    radius: () => rand(6, 9),
    speed: 150,
    turnGain: 7, angleLerp: 6, velLerp: 6,
    groupSize: () => randInt(7, 12),
    attackRange: 26,
    attackInterval: 0.6,
    attackPower: 'weak',
    cohesion: 0.9, alignment: 1.1, separation: 1.3,
  },
  // Cardume 2 — médio, formação mais organizada tipo "flecha".
  espinhal: {
    id: 'espinhal',
    name: 'Espinhal',
    color: '#ff9d5c',
    radius: () => rand(11, 15),
    speed: 105,
    turnGain: 5, angleLerp: 4, velLerp: 4,
    groupSize: () => randInt(5, 8),
    attackRange: 38,
    attackInterval: 0.9,
    attackPower: 'medium',
    cohesion: 1.2, alignment: 1.4, separation: 1.0,
  },
  // Cardume 3 — grande, poucos por grupo, mais lento e pesado, dano forte.
  carapax: {
    id: 'carapax',
    name: 'Carapax',
    color: '#c9527a',
    radius: () => rand(18, 24),
    speed: 68,
    turnGain: 3.2, angleLerp: 2.6, velLerp: 2.4,
    groupSize: () => randInt(3, 5),
    attackRange: 52,
    attackInterval: 1.3,
    attackPower: 'strong',
    cohesion: 1.4, alignment: 0.9, separation: 0.8,
  },
};
const COSMIC_SHOAL_SPECIES_IDS = Object.keys(COSMIC_SHOAL_SPECIES);

let _cosmicShoal = [];             // lista plana de indivíduos (cada um sabe seu shoalId)
let _cosmicShoalIdCounter = 1;
let _cosmicShoalSpawnTimer = 0;
let _cosmicShoalNextSpawnAt = COSMIC_SHOAL_SPAWN_INTERVAL_MIN;

function _cosmicMakeShoalFish(speciesId, shoalId, x, y) {
  const def = COSMIC_SHOAL_SPECIES[speciesId];
  return {
    id: 'shoal_' + (_cosmicShoalIdCounter++),
    shoalId, speciesId,
    x, y,
    angle: rand(0, Math.PI * 2),
    radius: def.radius(),
    phase: rand(0, Math.PI * 2),
    offscreenT: 0,
    targetId: null,
    attackCd: rand(0, def.attackInterval),
    vx: 0, vy: 0,
  };
}

function _cosmicSpawnShoal(forcedPos) {
  if (_cosmicShoal.length >= COSMIC_SHOAL_MAX) return;
  const speciesId = COSMIC_SHOAL_SPECIES_IDS[Math.floor(rand(0, COSMIC_SHOAL_SPECIES_IDS.length))];
  const def = COSMIC_SHOAL_SPECIES[speciesId];
  const count = def.groupSize();
  const basePos = forcedPos || _cosmicRollSpawnPos();
  const shoalId = 'shoalgrp_' + (_cosmicShoalIdCounter++);
  const baseAngle = rand(0, Math.PI * 2);
  for (let i = 0; i < count; i++) {
    if (_cosmicShoal.length >= COSMIC_SHOAL_MAX) break;
    // Nasce já em formação de "corrente" (linha/onda), não espalhado ao acaso —
    // reforça a leitura de grupo desde o primeiro frame.
    const along = (i - count / 2) * 34;
    const ox = Math.cos(baseAngle + Math.PI / 2) * along + rand(-14, 14);
    const oy = Math.sin(baseAngle + Math.PI / 2) * along + rand(-14, 14);
    const fish = _cosmicMakeShoalFish(speciesId, shoalId, basePos.x + ox, basePos.y + oy);
    fish.angle = baseAngle;
    _cosmicShoal.push(fish);
  }
}

function cosmicShoalUpdate(dt) {
  _cosmicShoalSpawnTimer += dt;
  if (_cosmicShoalSpawnTimer >= _cosmicShoalNextSpawnAt && _cosmicShoal.length < COSMIC_SHOAL_MAX) {
    _cosmicShoalSpawnTimer = 0;
    _cosmicShoalNextSpawnAt = rand(COSMIC_SHOAL_SPAWN_INTERVAL_MIN, COSMIC_SHOAL_SPAWN_INTERVAL_MAX);
    if (!_isBattle()) _cosmicSpawnShoal();
  }
  if (_isBattle()) return;

  for (let i = _cosmicShoal.length - 1; i >= 0; i--) {
    const fish = _cosmicShoal[i];
    const def = COSMIC_SHOAL_SPECIES[fish.speciesId];
    fish.phase += dt;

    // ── Boid: coesão (ir na direção do centro do grupo), alinhamento
    // (seguir a direção média dos vizinhos) e separação (não colidir),
    // calculados só entre membros do MESMO cardume (shoalId). ──────
    let cohX = 0, cohY = 0, cohN = 0;
    let alignX = 0, alignY = 0, alignN = 0;
    let sepX = 0, sepY = 0;
    for (let j = 0; j < _cosmicShoal.length; j++) {
      const other = _cosmicShoal[j];
      if (other === fish || other.shoalId !== fish.shoalId) continue;
      const dx = other.x - fish.x, dy = other.y - fish.y;
      const d = Math.hypot(dx, dy);
      if (d < COSMIC_SHOAL_NEIGHBOR_RANGE) {
        cohX += other.x; cohY += other.y; cohN++;
        alignX += Math.cos(other.angle); alignY += Math.sin(other.angle); alignN++;
        if (d < COSMIC_SHOAL_SEPARATION_RANGE && d > 0.01) {
          sepX -= (dx / d) / d; sepY -= (dy / d) / d;
        }
      }
    }

    let boidVx = 0, boidVy = 0;
    if (cohN > 0) {
      const dx = (cohX / cohN) - fish.x, dy = (cohY / cohN) - fish.y;
      const d = Math.hypot(dx, dy) || 1;
      boidVx += (dx / d) * def.cohesion;
      boidVy += (dy / d) * def.cohesion;
    }
    if (alignN > 0) {
      const d = Math.hypot(alignX, alignY) || 1;
      boidVx += (alignX / d) * def.alignment;
      boidVy += (alignY / d) * def.alignment;
    }
    const sepD = Math.hypot(sepX, sepY);
    if (sepD > 0.0001) {
      boidVx += (sepX / sepD) * def.separation;
      boidVy += (sepY / sepD) * def.separation;
    }

    // ── Alvo de ataque: qualquer membro do cardume pode "notar" um
    // astro sozinho, mas o impulso de perseguição é somado ao boid em
    // vez de substituí-lo — assim o grupo inteiro converge na presa
    // como uma corrente, sem quebrar a formação. ────────────────────
    let target = fish.targetId ? objects.find(o => o.id === fish.targetId && !o.dead) : null;
    if (!target) {
      target = _cosmicShoalFindTarget(fish);
      fish.targetId = target ? target.id : null;
    }

    let chaseVx = 0, chaseVy = 0, attacking = false;
    if (target) {
      const dx = target.x - fish.x, dy = target.y - fish.y;
      const d = Math.hypot(dx, dy) || 1;
      if (d > def.attackRange * 0.7) {
        chaseVx = (dx / d) * 1.6; chaseVy = (dy / d) * 1.6; // peso maior que o boid: puxa o cardume até a presa
      } else {
        attacking = true;
        _cosmicMonsterAttack(fish, def, target, dt);
      }
    }

    let finalVx, finalVy;
    if (attacking) {
      finalVx = 0; finalVy = 0;
    } else if (target) {
      finalVx = (boidVx + chaseVx), finalVy = (boidVy + chaseVy);
    } else {
      // Sem alvo: todo cardume (sozinho ou em grupo) sempre migra em
      // direção a um ponto de destino, como uma corrente real —
      // antes, um grupo com boid ativo (cohN/alignN>0) ficava girando
      // só em torno de si mesmo, sem nunca atravessar a tela; agora o
      // impulso de avanço é somado ao boid, não substituído por ele.
      if (!fish.wanderTarget || Math.hypot(fish.wanderTarget.x - fish.x, fish.wanderTarget.y - fish.y) < 80) {
        fish.wanderTarget = _cosmicRollSpawnPos();
      }
      const dx = fish.wanderTarget.x - fish.x, dy = fish.wanderTarget.y - fish.y;
      const d = Math.hypot(dx, dy) || 1;
      finalVx = boidVx + (dx / d) * 1.4;
      finalVy = boidVy + (dy / d) * 1.4;
    }

    const mag = Math.hypot(finalVx, finalVy);
    if (mag > 0.0001) {
      const targetAngle = Math.atan2(finalVy, finalVx);
      _cosmicSteerAngle(fish, dt, targetAngle, def.turnGain, def.angleLerp);
      _cosmicSteerVelocity(fish, dt, (finalVx / mag) * def.speed, (finalVy / mag) * def.speed, def.velLerp);
    } else {
      _cosmicSteerVelocity(fish, dt, 0, 0, def.velLerp);
    }

    if (_cosmicIsOutsideRef(fish)) {
      fish.offscreenT += dt;
      if (fish.offscreenT >= COSMIC_SHOAL_DESPAWN_TIME) { _cosmicShoal.splice(i, 1); continue; }
    } else {
      fish.offscreenT = 0;
    }
  }
}

// Mesma lógica de _cosmicMonsterFindTarget, mas com raio de agro
// próprio dos cardumes (chamada isolada pra evitar o cálculo duplicado
// estranho feito acima como fallback).
function _cosmicShoalFindTarget(fish) {
  if (typeof objects === 'undefined' || !objects.length) return null;
  let best = null, bestD = COSMIC_SHOAL_AGGRO_RANGE;
  for (const o of objects) {
    if (o.dead || o.fixed === true) continue;
    if (['comet', 'meteor'].includes((o.type || '').toLowerCase())) continue;
    const d = Math.hypot(o.x - fish.x, o.y - fish.y);
    if (d < bestD) { bestD = d; best = o; }
  }
  return best;
}

function _cosmicDrawAgulhaz(fish, sx, sy, r) {
  ctx.save(); ctx.translate(sx, sy); ctx.rotate(fish.angle);
  const g = ctx.createRadialGradient(0, 0, 0, 0, 0, r * 2.2);
  g.addColorStop(0, 'rgba(120,224,255,0.35)'); g.addColorStop(1, 'transparent');
  ctx.beginPath(); ctx.arc(0, 0, r * 2.2, 0, Math.PI * 2); ctx.fillStyle = g; ctx.fill();
  // corpo fino, alongado, tipo agulha
  ctx.beginPath();
  ctx.moveTo(r * 1.8, 0);
  ctx.lineTo(-r * 0.6, r * 0.45);
  ctx.lineTo(-r * 1.4, 0);
  ctx.lineTo(-r * 0.6, -r * 0.45);
  ctx.closePath();
  ctx.fillStyle = '#7fe0ff'; ctx.fill();
  ctx.strokeStyle = '#dffcff'; ctx.lineWidth = 1; ctx.stroke();
  ctx.beginPath(); ctx.arc(r * 1.1, 0, r * 0.16, 0, Math.PI * 2); ctx.fillStyle = '#0b2a33'; ctx.fill();
  ctx.restore();
}

function _cosmicDrawEspinhal(fish, sx, sy, r) {
  const pulse = 1 + 0.08 * Math.sin(fish.phase * 3);
  ctx.save(); ctx.translate(sx, sy); ctx.rotate(fish.angle);
  const g = ctx.createRadialGradient(0, 0, 0, 0, 0, r * 2.4 * pulse);
  g.addColorStop(0, 'rgba(255,157,92,0.3)'); g.addColorStop(1, 'transparent');
  ctx.beginPath(); ctx.arc(0, 0, r * 2.4 * pulse, 0, Math.PI * 2); ctx.fillStyle = g; ctx.fill();
  // corpo em losango com espinhos dorsais
  ctx.beginPath();
  ctx.moveTo(r * 1.3, 0);
  ctx.lineTo(0, r * 0.7);
  ctx.lineTo(-r * 1.1, 0);
  ctx.lineTo(0, -r * 0.7);
  ctx.closePath();
  ctx.fillStyle = '#ff9d5c'; ctx.fill();
  ctx.strokeStyle = '#7a3410'; ctx.lineWidth = 1.4; ctx.stroke();
  for (let i = -1; i <= 1; i++) {
    ctx.beginPath();
    ctx.moveTo(i * r * 0.3, -r * 0.55);
    ctx.lineTo(i * r * 0.3, -r * 1.05);
    ctx.strokeStyle = '#ffcf9e'; ctx.lineWidth = 1.6; ctx.stroke();
  }
  ctx.beginPath(); ctx.arc(r * 0.75, r * 0.12, r * 0.14, 0, Math.PI * 2); ctx.fillStyle = '#3a1704'; ctx.fill();
  ctx.restore();
}

function _cosmicDrawCarapax(fish, sx, sy, r) {
  const pulse = 1 + 0.06 * Math.sin(fish.phase * 1.8);
  ctx.save(); ctx.translate(sx, sy); ctx.rotate(fish.angle);
  const g = ctx.createRadialGradient(0, 0, r * 0.2, 0, 0, r * 2.6 * pulse);
  g.addColorStop(0, 'rgba(201,82,122,0.32)'); g.addColorStop(1, 'transparent');
  ctx.beginPath(); ctx.arc(0, 0, r * 2.6 * pulse, 0, Math.PI * 2); ctx.fillStyle = g; ctx.fill();
  // casco robusto, segmentado
  ctx.beginPath(); ctx.ellipse(0, 0, r * 1.2 * pulse, r * 0.85 * pulse, 0, 0, Math.PI * 2);
  ctx.fillStyle = '#c9527a'; ctx.fill();
  ctx.strokeStyle = '#5c1230'; ctx.lineWidth = 1.6; ctx.stroke();
  for (let i = -1; i <= 1; i++) {
    ctx.beginPath();
    ctx.moveTo(i * r * 0.4, -r * 0.75); ctx.lineTo(i * r * 0.4, r * 0.75);
    ctx.strokeStyle = 'rgba(92,18,48,0.6)'; ctx.lineWidth = 1.2; ctx.stroke();
  }
  ctx.beginPath(); ctx.arc(r * 0.95, 0, r * 0.18, 0, Math.PI * 2); ctx.fillStyle = '#2a0715'; ctx.fill();
  ctx.beginPath(); ctx.arc(r * 0.95, 0, r * 0.08, 0, Math.PI * 2); ctx.fillStyle = '#ff8fae'; ctx.fill();
  ctx.restore();
}

const COSMIC_SHOAL_DRAWERS = {
  agulhaz: _cosmicDrawAgulhaz,
  espinhal: _cosmicDrawEspinhal,
  carapax: _cosmicDrawCarapax,
};

function cosmicShoalDraw(ctxRef) {
  if (_isBattle()) return;
  _cosmicShoal.forEach(fish => {
    const sx = (fish.x - cam.x) * cam.zoom + canvas.width * 0.5;
    const sy = (fish.y - cam.y) * cam.zoom + canvas.height * 0.5;
    if (sx < -80 || sx > canvas.width + 80 || sy < -80 || sy > canvas.height + 80) return;
    const r = fish.radius * cam.zoom;
    const drawer = COSMIC_SHOAL_DRAWERS[fish.speciesId];
    if (drawer) drawer(fish, sx, sy, r);
  });
}

function cosmicShoalReset() {
  _cosmicShoal = [];
  _cosmicShoalSpawnTimer = 0;
  _cosmicShoalNextSpawnAt = COSMIC_SHOAL_SPAWN_INTERVAL_MIN;
}

// ═══════════════════════════════════════════════════════════════════
//  MÓDULO: ENTIDADES DO ECLIPSE — inimigos de terror/medo, existem
//  SOMENTE durante o Eclipse do Núcleo Dimensional (evento de 12min).
//  Reutilizam o mesmo padrão de perseguição/ataque dos monstros
//  errantes, mas com sua própria lista/spawn/despawn: quando o Eclipse
//  termina, todos são removidos imediatamente (não ficam vagando
//  depois que o fenômeno passa).
// ═══════════════════════════════════════════════════════════════════

const COSMIC_TERROR_MAX = 30;
const COSMIC_TERROR_SPAWN_INTERVAL_MIN = 0.5;
const COSMIC_TERROR_SPAWN_INTERVAL_MAX = 1.4;
const COSMIC_TERROR_AGGRO_RANGE = 950;

const COSMIC_TERROR_TYPES = {
  dreadwraith: {
    id: 'dreadwraith',
    name: 'Espectro do Pavor',
    color: '#8a1fff',
    radius: () => rand(18, 24),
    speed: 96,
    turnGain: 4.5, angleLerp: 3.6, velLerp: 3.2,
    swarm: false,
    attackRange: 40,
    attackInterval: 1.2,
    attackPower: 'medium',
  },
  hollowscream: {
    id: 'hollowscream',
    name: 'Grito Oco',
    color: '#e6e6e6',
    radius: () => rand(10, 14),
    speed: 150,
    turnGain: 7, angleLerp: 6, velLerp: 6,
    swarm: true,
    swarmSize: () => randInt(4, 7),
    attackRange: 30,
    attackInterval: 0.8,
    attackPower: 'weak',
  },
  nightmarelord: {
    id: 'nightmarelord',
    name: 'Senhor do Pesadelo',
    color: '#40031f',
    radius: () => rand(30, 38),
    speed: 44,
    turnGain: 2.4, angleLerp: 2, velLerp: 1.8,
    swarm: false,
    attackRange: 300,
    attackInterval: 1.6,
    attackPower: 'ranged',
    keepDistance: 200,
  },
};
const COSMIC_TERROR_TYPE_IDS = Object.keys(COSMIC_TERROR_TYPES);

let _cosmicTerrorMonsters = [];
let _cosmicTerrorSpawnTimer = 0;
let _cosmicTerrorNextSpawnAt = rand(COSMIC_TERROR_SPAWN_INTERVAL_MIN, COSMIC_TERROR_SPAWN_INTERVAL_MAX);
let _cosmicTerrorIdCounter = 1;

function _cosmicMakeTerrorMonster(typeId, x, y) {
  const def = COSMIC_TERROR_TYPES[typeId];
  const r = def.radius();
  return {
    id: 'terror_' + (_cosmicTerrorIdCounter++),
    typeId, x, y,
    angle: rand(0, Math.PI * 2),
    radius: r,
    phase: rand(0, Math.PI * 2),
    offscreenT: 0,
    targetId: null,
    attackCd: rand(0, def.attackInterval),
    // ── HP: mesma lógica adicional descrita em _cosmicMakeMonster.
    // Monstros de terror são mais fortes: multiplicador maior. ─────────
    hp: r * 10,
    maxHp: r * 10,
  };
}

function _cosmicSpawnTerrorWave() {
  if (_cosmicTerrorMonsters.length >= COSMIC_TERROR_MAX) return;
  const typeId = COSMIC_TERROR_TYPE_IDS[Math.floor(rand(0, COSMIC_TERROR_TYPE_IDS.length))];
  const def = COSMIC_TERROR_TYPES[typeId];
  const count = def.swarm ? def.swarmSize() : 1;
  const basePos = _cosmicRollSpawnPos();
  for (let i = 0; i < count; i++) {
    if (_cosmicTerrorMonsters.length >= COSMIC_TERROR_MAX) break;
    const ox = rand(-50, 50), oy = rand(-50, 50);
    _cosmicTerrorMonsters.push(_cosmicMakeTerrorMonster(typeId, basePos.x + ox, basePos.y + oy));
  }
}

function cosmicTerrorMonstersUpdate(dt) {
  if (!_eclipseActive) {
    if (_cosmicTerrorMonsters.length) cosmicTerrorMonstersReset();
    return;
  }
  _cosmicTerrorSpawnTimer += dt;
  if (_cosmicTerrorSpawnTimer >= _cosmicTerrorNextSpawnAt && _cosmicTerrorMonsters.length < COSMIC_TERROR_MAX) {
    _cosmicTerrorSpawnTimer = 0;
    _cosmicTerrorNextSpawnAt = rand(COSMIC_TERROR_SPAWN_INTERVAL_MIN, COSMIC_TERROR_SPAWN_INTERVAL_MAX);
    if (!_isBattle()) _cosmicSpawnTerrorWave();
  }
  if (_isBattle()) return;

  for (let i = _cosmicTerrorMonsters.length - 1; i >= 0; i--) {
    const mon = _cosmicTerrorMonsters[i];
    const def = COSMIC_TERROR_TYPES[mon.typeId];
    if (typeof mon.hp === 'number' && mon.hp <= 0) {
      if (typeof spawnExplosion === 'function') spawnExplosion(mon.x, mon.y, 1, false);
      _cosmicTerrorMonsters.splice(i, 1);
      continue;
    }
    mon.phase += dt;

    if (!mon.targetId || Math.random() < 0.01) {
      const t = _cosmicMonsterFindTarget(mon);
      mon.targetId = t ? t.id : null;
    }
    const target = mon.targetId && typeof objects !== 'undefined' ? objects.find(o => o.id === mon.targetId && !o.dead) : null;

    if (target) {
      const dx = target.x - mon.x, dy = target.y - mon.y;
      const d = Math.hypot(dx, dy) || 1;
      let desiredAngle = Math.atan2(dy, dx);
      if (def.keepDistance && d < def.keepDistance) desiredAngle += Math.PI; // foge pra manter distância (kiting)
      let da = desiredAngle - mon.angle;
      while (da > Math.PI) da -= Math.PI * 2;
      while (da < -Math.PI) da += Math.PI * 2;
      mon.angle += da * Math.min(1, dt * def.angleLerp);
      const moveSpeed = (def.keepDistance && d < def.keepDistance) ? def.speed : def.speed;
      mon.x += Math.cos(mon.angle) * moveSpeed * dt;
      mon.y += Math.sin(mon.angle) * moveSpeed * dt;

      if (def.attackPower === 'ranged') {
        mon.attackCd -= dt;
        if (mon.attackCd <= 0 && d < def.attackRange) {
          mon.attackCd = def.attackInterval;
          _cosmicFireProjectile(mon, def, target);
        }
      } else if (d < def.attackRange) {
        _cosmicMonsterAttack(mon, def, target, dt);
      }
    } else {
      mon.x += Math.cos(mon.angle) * def.speed * 0.4 * dt;
      mon.y += Math.sin(mon.angle) * def.speed * 0.4 * dt;
      if (Math.random() < 0.02) mon.angle += rand(-0.6, 0.6);
    }

    if (_cosmicIsOutsideRef(mon)) {
      mon.offscreenT += dt;
      if (mon.offscreenT >= COSMIC_MONSTER_DESPAWN_TIME) { _cosmicTerrorMonsters.splice(i, 1); continue; }
    } else {
      mon.offscreenT = 0;
    }
  }
}

function cosmicTerrorMonstersDraw(ctxRef) {
  if (!_eclipseActive || _isBattle()) return;
  _cosmicTerrorMonsters.forEach(mon => {
    const sx = (mon.x - cam.x) * cam.zoom + canvas.width * 0.5;
    const sy = (mon.y - cam.y) * cam.zoom + canvas.height * 0.5;
    if (sx < -80 || sx > canvas.width + 80 || sy < -80 || sy > canvas.height + 80) return;
    const r = mon.radius * cam.zoom;
    const drawer = COSMIC_TERROR_DRAWERS[mon.typeId];
    if (drawer) drawer(mon, sx, sy, r);
  });
}

function cosmicTerrorMonstersReset() {
  _cosmicTerrorMonsters = [];
  _cosmicTerrorSpawnTimer = 0;
  _cosmicTerrorNextSpawnAt = rand(COSMIC_TERROR_SPAWN_INTERVAL_MIN, COSMIC_TERROR_SPAWN_INTERVAL_MAX);
}

const COSMIC_TERROR_DRAWERS = {
  dreadwraith: function (mon, sx, sy, r) {
    const flicker = 0.75 + 0.25 * Math.sin(mon.phase * 5);
    ctx.save(); ctx.globalAlpha = flicker; ctx.translate(sx, sy); ctx.rotate(mon.angle);
    const g = ctx.createRadialGradient(0, 0, 0, 0, 0, r * 3);
    g.addColorStop(0, 'rgba(138,31,255,0.5)'); g.addColorStop(1, 'transparent');
    ctx.beginPath(); ctx.arc(0, 0, r * 3, 0, Math.PI * 2); ctx.fillStyle = g; ctx.fill();
    // Capa com borda inferior rasgada/irregular — mais dramática que a
    // curva lisa anterior, reforça o aspecto de "pavor" espectral.
    ctx.beginPath();
    ctx.moveTo(0, -r * 1.15);
    const teeth = 8;
    for (let i = 0; i <= teeth; i++) {
      const tt = i / teeth;
      const x = (tt - 0.5) * r * 1.7;
      const jag = r * 0.15 * (i % 2 === 0 ? 1 : 0.3) + Math.sin(mon.phase * 3 + i) * r * 0.05;
      const y = r * 0.5 + tt * r * 0.7 + jag;
      ctx.lineTo(x, y);
    }
    ctx.lineTo(-r * 0.9, -r * 0.15);
    ctx.closePath();
    ctx.fillStyle = '#26064a'; ctx.fill();
    ctx.strokeStyle = 'rgba(200,150,255,0.6)'; ctx.lineWidth = 1.2; ctx.stroke();
    // sombra interna do capuz, mais escura
    ctx.beginPath(); ctx.ellipse(0, -r * 0.4, r * 0.55, r * 0.35, 0, 0, Math.PI * 2);
    ctx.fillStyle = '#12021f'; ctx.fill();
    // dois olhos vazios com brilho rosa central
    ctx.fillStyle = '#ffdfff';
    ctx.beginPath(); ctx.arc(-r * 0.28, -r * 0.42, r * 0.1, 0, Math.PI * 2); ctx.fill();
    ctx.beginPath(); ctx.arc(r * 0.28, -r * 0.42, r * 0.1, 0, Math.PI * 2); ctx.fill();
    ctx.fillStyle = '#ff3cdc';
    ctx.beginPath(); ctx.arc(-r * 0.28, -r * 0.42, r * 0.04, 0, Math.PI * 2); ctx.fill();
    ctx.beginPath(); ctx.arc(r * 0.28, -r * 0.42, r * 0.04, 0, Math.PI * 2); ctx.fill();
    ctx.restore();
  },
  hollowscream: function (mon, sx, sy, r) {
    const stretch = 1 + 0.3 * Math.sin(mon.phase * 8); // vibra rápido, nervoso
    ctx.save(); ctx.translate(sx, sy); ctx.rotate(mon.angle);
    const g = ctx.createRadialGradient(0, 0, 0, 0, 0, r * 2.4);
    g.addColorStop(0, 'rgba(230,230,230,0.4)'); g.addColorStop(1, 'transparent');
    ctx.beginPath(); ctx.arc(0, 0, r * 2.4, 0, Math.PI * 2); ctx.fillStyle = g; ctx.fill();
    // ondas de distorção sonora ao redor — sugere o próprio grito ecoando
    ctx.strokeStyle = `rgba(230,230,230,${0.28 * stretch})`; ctx.lineWidth = 1;
    for (let i = 0; i < 3; i++) {
      const rr = r * (1.15 + i * 0.2);
      ctx.beginPath(); ctx.arc(0, 0, rr, Math.PI * 0.9, Math.PI * 1.9); ctx.stroke();
    }
    // rosto pálido alongado
    ctx.beginPath(); ctx.ellipse(0, -r * 0.05, r * 0.72, r * 1.0 * stretch, 0, 0, Math.PI * 2);
    ctx.fillStyle = '#e0e0e6'; ctx.fill();
    ctx.strokeStyle = 'rgba(150,150,160,0.6)'; ctx.lineWidth = 1; ctx.stroke();
    // boca escancarada, elemento dominante — foco central do "grito",
    // com borda denteada em vez de oval lisa genérica.
    const mw = r * 0.55, mh = r * 0.72 * stretch;
    ctx.beginPath(); ctx.ellipse(0, r * 0.22, mw, mh * 0.55, 0, 0, Math.PI * 2);
    ctx.fillStyle = '#0a0a0e'; ctx.fill();
    ctx.fillStyle = '#e0e0e6';
    for (let i = 0; i < 8; i++) {
      const tt = i / 7;
      const tx = -mw + tt * mw * 2;
      const ty = r * 0.22 - mh * 0.55 + (i % 2 === 0 ? 0 : r * 0.06);
      ctx.beginPath();
      ctx.moveTo(tx - r * 0.06, ty); ctx.lineTo(tx + r * 0.06, ty); ctx.lineTo(tx, ty + r * 0.1);
      ctx.closePath(); ctx.fill();
    }
    // olhos pequenos, próximos e levemente assimétricos — perturbador
    ctx.fillStyle = '#08080b';
    ctx.beginPath(); ctx.arc(-r * 0.3, -r * 0.32, r * 0.09, 0, Math.PI * 2); ctx.fill();
    ctx.beginPath(); ctx.arc(r * 0.16, -r * 0.36, r * 0.09, 0, Math.PI * 2); ctx.fill();
    ctx.restore();
  },
  nightmarelord: function (mon, sx, sy, r) {
    const pulse = 1 + 0.12 * Math.sin(mon.phase * 2);
    ctx.save(); ctx.translate(sx, sy);
    const g = ctx.createRadialGradient(0, 0, 0, 0, 0, r * 3.4 * pulse);
    g.addColorStop(0, 'rgba(64,3,31,0.55)'); g.addColorStop(1, 'transparent');
    ctx.beginPath(); ctx.arc(0, 0, r * 3.4 * pulse, 0, Math.PI * 2); ctx.fillStyle = g; ctx.fill();
    // Corpo em duas camadas de espinhos — coroa externa longa + base
    // interna irregular, mais imponente/ameaçador que um único anel.
    ctx.beginPath();
    const spikesOuter = 11;
    for (let i = 0; i < spikesOuter; i++) {
      const a = (i / spikesOuter) * Math.PI * 2 + mon.phase * 0.2;
      const rr = r * pulse * (i % 2 === 0 ? 1.15 : 0.5);
      const px = Math.cos(a) * rr, py = Math.sin(a) * rr;
      if (i === 0) ctx.moveTo(px, py); else ctx.lineTo(px, py);
    }
    ctx.closePath();
    ctx.fillStyle = '#5a0024'; ctx.fill();
    ctx.strokeStyle = 'rgba(255,80,120,0.7)'; ctx.lineWidth = 1.4; ctx.stroke();
    ctx.beginPath();
    const spikesInner = 9;
    for (let i = 0; i < spikesInner; i++) {
      const a = (i / spikesInner) * Math.PI * 2 + 0.3 - mon.phase * 0.15;
      const rr = r * pulse * 0.62 * (i % 2 === 0 ? 1 : 0.75);
      const px = Math.cos(a) * rr, py = Math.sin(a) * rr;
      if (i === 0) ctx.moveTo(px, py); else ctx.lineTo(px, py);
    }
    ctx.closePath();
    const cg = ctx.createRadialGradient(0, 0, 0, 0, 0, r * pulse * 0.62);
    cg.addColorStop(0, '#7a0030'); cg.addColorStop(1, '#1a0008');
    ctx.fillStyle = cg; ctx.fill();
    ctx.strokeStyle = 'rgba(200,40,90,0.6)'; ctx.lineWidth = 1; ctx.stroke();
    // olho único central, maior e mais imponente, com rachaduras radiando
    ctx.beginPath(); ctx.arc(0, 0, r * pulse * 0.32, 0, Math.PI * 2);
    ctx.fillStyle = '#ff2b6b'; ctx.fill();
    ctx.strokeStyle = 'rgba(255,180,200,0.8)'; ctx.lineWidth = 1.5; ctx.stroke();
    ctx.beginPath(); ctx.arc(0, 0, r * pulse * 0.12, 0, Math.PI * 2);
    ctx.fillStyle = '#fff'; ctx.fill();
    ctx.strokeStyle = 'rgba(255,43,107,0.5)'; ctx.lineWidth = 1;
    for (let i = 0; i < 6; i++) {
      const a = i * Math.PI / 3 + mon.phase * 0.1;
      ctx.beginPath();
      ctx.moveTo(Math.cos(a) * r * pulse * 0.32, Math.sin(a) * r * pulse * 0.32);
      ctx.lineTo(Math.cos(a) * r * pulse * 0.48, Math.sin(a) * r * pulse * 0.48);
      ctx.stroke();
    }
    ctx.restore();
  },
};

// ═══════════════════════════════════════════════════════════════════
//  MÓDULO: NUVENS DE GÁS — ambientais, com leve efeito de gameplay
// ═══════════════════════════════════════════════════════════════════
//  Nascem perto da câmera, vagam devagar e somem como as entidades
//  cósmicas. Astros que ficam dentro sofrem leve lentidão (gravMultiplier
//  reduzido) e têm a composição alterada aos poucos (bioTemp/bioO2/
//  bioWater puxados em direção ao "sabor" da nuvem, simulando ela
//  alimentando/contaminando o astro).
// ═══════════════════════════════════════════════════════════════════

const COSMIC_GASCLOUD_MAX = 10;
const COSMIC_GASCLOUD_SPAWN_INTERVAL_MIN = 5;
const COSMIC_GASCLOUD_SPAWN_INTERVAL_MAX = 12;
const COSMIC_GASCLOUD_DESPAWN_TIME = 12;

const COSMIC_GASCLOUD_FLAVORS = [
  { id: 'hydrogen', color: '150,180,255', tempPull: 20, o2Pull: -4, waterPull: 0 },
  { id: 'sulfur', color: '255,220,90', tempPull: 45, o2Pull: -8, waterPull: -6 },
  { id: 'cryo', color: '160,255,230', tempPull: -35, o2Pull: 2, waterPull: 10 },
];

let _cosmicGasClouds = [];
let _cosmicGasSpawnTimer = 0;
let _cosmicGasNextSpawnAt = rand(COSMIC_GASCLOUD_SPAWN_INTERVAL_MIN, COSMIC_GASCLOUD_SPAWN_INTERVAL_MAX);
let _cosmicGasIdCounter = 1;

function _cosmicSpawnGasCloud() {
  const pos = _cosmicRollSpawnPos();
  const flavor = COSMIC_GASCLOUD_FLAVORS[Math.floor(rand(0, COSMIC_GASCLOUD_FLAVORS.length))];
  const angle = rand(0, Math.PI * 2), speed = rand(6, 16);
  _cosmicGasClouds.push({
    id: 'gas_' + (_cosmicGasIdCounter++),
    x: pos.x, y: pos.y,
    vx: Math.cos(angle) * speed, vy: Math.sin(angle) * speed,
    radius: rand(140, 260),
    flavor,
    phase: rand(0, Math.PI * 2),
    offscreenT: 0,
    puffs: Array.from({ length: randInt(10, 16) }, () => ({
      a: rand(0, Math.PI * 2), d: rand(0.2, 0.95), r: rand(0.4, 1), sp: rand(0.02, 0.08),
    })),
  });
}

function cosmicGasCloudsUpdate(dt) {
  _cosmicGasSpawnTimer += dt;
  if (_cosmicGasSpawnTimer >= _cosmicGasNextSpawnAt && _cosmicGasClouds.length < COSMIC_GASCLOUD_MAX) {
    _cosmicGasSpawnTimer = 0;
    _cosmicGasNextSpawnAt = rand(COSMIC_GASCLOUD_SPAWN_INTERVAL_MIN, COSMIC_GASCLOUD_SPAWN_INTERVAL_MAX);
    _cosmicSpawnGasCloud();
  }

  for (let i = _cosmicGasClouds.length - 1; i >= 0; i--) {
    const cloud = _cosmicGasClouds[i];
    cloud.x += cloud.vx * dt; cloud.y += cloud.vy * dt;
    cloud.phase += dt;

    // Efeito em astros dentro da nuvem: leve lentidão + puxão de composição.
    if (typeof objects !== 'undefined') {
      for (const o of objects) {
        if (o.dead || o.fixed) continue;
        const d = Math.hypot(o.x - cloud.x, o.y - cloud.y);
        if (d < cloud.radius) {
          o.gravMultiplier = Math.max(0.4, (o.gravMultiplier ?? 1) * (1 - dt * 0.15));
          const k = dt * 0.05;
          if (typeof o.bioTemp === 'number') o.bioTemp += (cloud.flavor.tempPull - o.bioTemp) * k * 0.1;
          if (typeof o.bioO2 === 'number') o.bioO2 = Math.max(0, o.bioO2 + cloud.flavor.o2Pull * k * 0.1);
          if (typeof o.bioWater === 'number') o.bioWater = Math.max(0, o.bioWater + cloud.flavor.waterPull * k * 0.1);
        } else if (o.gravMultiplier !== undefined && o.gravMultiplier < 1) {
          o.gravMultiplier = Math.min(1, o.gravMultiplier + dt * 0.1); // recupera fora da nuvem
        }
      }
    }

    if (_cosmicIsOutsideRef(cloud)) {
      cloud.offscreenT += dt;
      if (cloud.offscreenT >= COSMIC_GASCLOUD_DESPAWN_TIME) { _cosmicGasClouds.splice(i, 1); continue; }
    } else {
      cloud.offscreenT = 0;
    }
  }
}

function cosmicGasCloudsDraw(ctxRef) {
  _cosmicGasClouds.forEach(cloud => {
    const sx = (cloud.x - cam.x) * cam.zoom + canvas.width * 0.5;
    const sy = (cloud.y - cam.y) * cam.zoom + canvas.height * 0.5;
    const r = cloud.radius * cam.zoom;
    if (sx < -r - 60 || sx > canvas.width + r + 60 || sy < -r - 60 || sy > canvas.height + r + 60) return;
    const c = cloud.flavor.color;
    cloud.puffs.forEach(p => {
      const a = p.a + cloud.phase * p.sp;
      const px = sx + Math.cos(a) * p.d * r;
      const py = sy + Math.sin(a) * p.d * r;
      const pr = r * 0.35 * p.r;
      const g = ctx.createRadialGradient(px, py, 0, px, py, pr);
      g.addColorStop(0, `rgba(${c},0.16)`); g.addColorStop(1, 'transparent');
      ctx.beginPath(); ctx.arc(px, py, pr, 0, Math.PI * 2); ctx.fillStyle = g; ctx.fill();
    });
  });
}

function cosmicGasCloudsReset() {
  _cosmicGasClouds = [];
  _cosmicGasSpawnTimer = 0;
  _cosmicGasNextSpawnAt = rand(COSMIC_GASCLOUD_SPAWN_INTERVAL_MIN, COSMIC_GASCLOUD_SPAWN_INTERVAL_MAX);
}

// ═══════════════════════════════════════════════════════════════════
//  MÓDULO: RUPTURAS CLIMÁTICAS — efeito atmosférico temporário
// ═══════════════════════════════════════════════════════════════════
//  Versão "clima" do RiftFissure (que hoje só existe como astro
//  colocado manualmente pelo jogador): nasce perto da câmera, existe
//  por um tempo limitado e some — sem acumular no mundo. Puramente
//  visual/de área por enquanto (a mecânica de sugar astros pra 4ª
//  dimensão fica fora de escopo por ora).
// ═══════════════════════════════════════════════════════════════════

const COSMIC_RUPTURE_MAX = 4;
const COSMIC_RUPTURE_SPAWN_INTERVAL_MIN = 8;
const COSMIC_RUPTURE_SPAWN_INTERVAL_MAX = 18;
const COSMIC_RUPTURE_LIFETIME = 18; // segundos de vida útil antes de fechar sozinha
const COSMIC_RUPTURE_DESPAWN_TIME = 12; // some se ficar longe da câmera por esse tempo

let _cosmicRuptures = [];
let _cosmicRuptureSpawnTimer = 0;
let _cosmicRuptureNextSpawnAt = rand(COSMIC_RUPTURE_SPAWN_INTERVAL_MIN, COSMIC_RUPTURE_SPAWN_INTERVAL_MAX);
let _cosmicRuptureIdCounter = 1;

function _cosmicGenCrackPts() {
  const pts = [{ x: 0, y: 0 }]; let cx = 0, cy = 0;
  for (let i = 0; i < 8; i++) {
    cx += rand(-12, 12); cy += rand(-12, 12);
    pts.push({ x: cx, y: cy });
    if (Math.random() < 0.4) {
      const bx = cx + rand(-8, 8), by = cy + rand(-8, 8);
      pts.push({ x: bx, y: by }, { x: cx, y: cy });
    }
  }
  return pts;
}

function _cosmicSpawnRupture() {
  const pos = _cosmicRollSpawnPos();
  _cosmicRuptures.push({
    id: 'rupture_' + (_cosmicRuptureIdCounter++),
    x: pos.x, y: pos.y,
    radius: rand(20, 34),
    angle: rand(0, Math.PI),
    age: 0,
    offscreenT: 0,
    glowT: rand(0, Math.PI * 2),
    crackPts: _cosmicGenCrackPts(),
  });
}

function cosmicRupturesUpdate(dt) {
  _cosmicRuptureSpawnTimer += dt;
  if (_cosmicRuptureSpawnTimer >= _cosmicRuptureNextSpawnAt && _cosmicRuptures.length < COSMIC_RUPTURE_MAX) {
    _cosmicRuptureSpawnTimer = 0;
    _cosmicRuptureNextSpawnAt = rand(COSMIC_RUPTURE_SPAWN_INTERVAL_MIN, COSMIC_RUPTURE_SPAWN_INTERVAL_MAX);
    _cosmicSpawnRupture();
  }

  for (let i = _cosmicRuptures.length - 1; i >= 0; i--) {
    const rift = _cosmicRuptures[i];
    rift.age += dt;
    rift.glowT += dt * 3;
    if (rift.age >= COSMIC_RUPTURE_LIFETIME) { _cosmicRuptures.splice(i, 1); continue; }

    if (_cosmicIsOutsideRef(rift)) {
      rift.offscreenT += dt;
      if (rift.offscreenT >= COSMIC_RUPTURE_DESPAWN_TIME) { _cosmicRuptures.splice(i, 1); continue; }
    } else {
      rift.offscreenT = 0;
    }
  }
}

function cosmicRupturesDraw(ctxRef) {
  _cosmicRuptures.forEach(rift => {
    const sx = (rift.x - cam.x) * cam.zoom + canvas.width * 0.5;
    const sy = (rift.y - cam.y) * cam.zoom + canvas.height * 0.5;
    const r = rift.radius * cam.zoom;
    if (sx < -r * 5 || sx > canvas.width + r * 5 || sy < -r * 5 || sy > canvas.height + r * 5) return;
    // Fade-in/fade-out suave no início e fim da vida.
    const fadeIn = Math.min(1, rift.age / 1.5);
    const fadeOut = Math.min(1, (COSMIC_RUPTURE_LIFETIME - rift.age) / 2);
    const alpha = Math.min(fadeIn, fadeOut);
    const bright = (0.7 + 0.3 * Math.sin(rift.glowT)) * alpha;

    const glow = ctx.createRadialGradient(sx, sy, 0, sx, sy, r * 4);
    glow.addColorStop(0, `rgba(200,0,255,${0.4 * bright})`);
    glow.addColorStop(0.5, `rgba(120,0,200,${0.1 * bright})`);
    glow.addColorStop(1, 'transparent');
    ctx.beginPath(); ctx.arc(sx, sy, r * 4, 0, Math.PI * 2); ctx.fillStyle = glow; ctx.fill();

    ctx.save(); ctx.translate(sx, sy); ctx.rotate(rift.angle); ctx.scale(cam.zoom, cam.zoom);
    ctx.lineJoin = 'round'; ctx.lineCap = 'round';
    ctx.beginPath();
    rift.crackPts.forEach((p, i) => i === 0 ? ctx.moveTo(p.x, p.y) : ctx.lineTo(p.x, p.y));
    ctx.strokeStyle = `rgba(220,100,255,${0.45 * bright})`; ctx.lineWidth = 7; ctx.stroke();
    ctx.beginPath();
    rift.crackPts.forEach((p, i) => i === 0 ? ctx.moveTo(p.x, p.y) : ctx.lineTo(p.x, p.y));
    ctx.strokeStyle = `rgba(200,0,255,${0.85 * bright})`; ctx.lineWidth = 3.5; ctx.stroke();
    ctx.beginPath();
    rift.crackPts.forEach((p, i) => i === 0 ? ctx.moveTo(p.x, p.y) : ctx.lineTo(p.x, p.y));
    ctx.strokeStyle = `rgba(255,255,255,${0.9 * bright})`; ctx.lineWidth = 1.2; ctx.stroke();
    ctx.restore();
  });
}

function cosmicRupturesReset() {
  _cosmicRuptures = [];
  _cosmicRuptureSpawnTimer = 0;
  _cosmicRuptureNextSpawnAt = rand(COSMIC_RUPTURE_SPAWN_INTERVAL_MIN, COSMIC_RUPTURE_SPAWN_INTERVAL_MAX);
}

// ═══════════════════════════════════════════════════════════════════
//  MÓDULO: FENÔMENO DO ECLIPSE — raios vermelhos tipo relâmpago,
//  ANCORADOS EM COORDENADAS DE MUNDO (não de tela/câmera), gerados
//  por chunk exatamente como o campo de estrelas de fundo. Cada
//  instância pisca rapidamente (ciclo curto de vida/apagado) baseado
//  em simTime, então respeita zoom e pan naturalmente ao desenhar via
//  worldToScreen — se o jogador se afasta, o fenômeno fica menor
//  junto, não fica "grudado" na tela.
// ═══════════════════════════════════════════════════════════════════
const ECLIPSE_CHUNK = 900;      // chunk maior que o de estrelas: fenômeno é raro
const ECLIPSE_PER_CHUNK = 1;    // no máx 1 ponto de fenômeno por chunk
const ECLIPSE_CYCLE_MIN = 0.6;  // segundos entre possíveis flashes no mesmo ponto
const ECLIPSE_CYCLE_MAX = 2.2;
const ECLIPSE_FLASH_LIFE_MIN = 0.12; // vida do flash em si: curtíssima
const ECLIPSE_FLASH_LIFE_MAX = 0.28;

const eclipseChunkCache = new Map();
function _eclipseChunkHash(cx, cy) {
  let s = (cx * 374761393) ^ (cy * 668265263);
  s = ((s >>> 16) ^ s) * 0x45d9f3b | 0; s = ((s >>> 16) ^ s) * 0x45d9f3b | 0;
  return (s >>> 16) ^ s;
}
function _eclipseGenRoots(seedFn, n) {
  // Raízes sempre apontando pra BAIXO (fenômeno "caindo do céu"),
  // geradas de forma determinística a partir do seed do chunk.
  const roots = [];
  for (let i = 0; i < n; i++) {
    const baseAngle = Math.PI / 2 + (seedFn() * 2 - 1) * 0.5;
    const len = 50 + seedFn() * 90;
    const segs = 3 + Math.floor(seedFn() * 3);
    const pts = [{ x: 0, y: 0 }];
    let cx = 0, cy = 0, ang = baseAngle;
    for (let s = 0; s < segs; s++) {
      ang += (seedFn() * 2 - 1) * 0.28;
      cx += Math.cos(ang) * (len / segs);
      cy += Math.abs(Math.sin(ang)) * (len / segs);
      pts.push({ x: cx, y: cy });
    }
    roots.push(pts);
  }
  return roots;
}
function _eclipseGetChunkPoints(cx, cy) {
  const key = `${cx},${cy}`;
  if (eclipseChunkCache.has(key)) return eclipseChunkCache.get(key);
  let seed = _eclipseChunkHash(cx, cy);
  const lcg = () => { seed = (seed * 1664525 + 1013904223) & 0xffffffff; return (seed >>> 0) / 0xffffffff; };
  const points = [];
  for (let i = 0; i < ECLIPSE_PER_CHUNK; i++) {
    points.push({
      wx: cx * ECLIPSE_CHUNK + lcg() * ECLIPSE_CHUNK,
      wy: cy * ECLIPSE_CHUNK + lcg() * ECLIPSE_CHUNK,
      scale: 0.7 + lcg() * 0.8,
      cyclePhase: lcg() * 10,
      cycleLen: ECLIPSE_CYCLE_MIN + lcg() * (ECLIPSE_CYCLE_MAX - ECLIPSE_CYCLE_MIN),
      flashLife: ECLIPSE_FLASH_LIFE_MIN + lcg() * (ECLIPSE_FLASH_LIFE_MAX - ECLIPSE_FLASH_LIFE_MIN),
      roots: _eclipseGenRoots(lcg, 5 + Math.floor(lcg() * 4)),
    });
  }
  eclipseChunkCache.set(key, points);
  if (eclipseChunkCache.size > 400) { const k = [...eclipseChunkCache.keys()]; for (let i = 0; i < 60; i++) eclipseChunkCache.delete(k[i]); }
  return points;
}

function cosmicEclipseSpritesUpdate(dt) {
  // Puramente visual/determinístico por simTime — nada a atualizar
  // aqui além de existir; o estado de "piscando ou não" é calculado
  // no draw a partir de simTime, igual ao brilho pulsante das estrelas.
}

function cosmicEclipseSpritesDraw(ctxRef) {
  if (!_eclipseActive) return;
  const iz = 1 / cam.zoom, pad = ECLIPSE_CHUNK;
  const x0 = cam.x - (canvas.width * .5) * iz - pad, y0 = cam.y - (canvas.height * .5) * iz - pad;
  const x1 = cam.x + (canvas.width * .5) * iz + pad, y1 = cam.y + (canvas.height * .5) * iz + pad;
  for (let cy = Math.floor(y0 / ECLIPSE_CHUNK); cy <= Math.ceil(y1 / ECLIPSE_CHUNK); cy++) {
    for (let cx = Math.floor(x0 / ECLIPSE_CHUNK); cx <= Math.ceil(x1 / ECLIPSE_CHUNK); cx++) {
      _eclipseGetChunkPoints(cx, cy).forEach(pt => {
        // Ciclo determinístico: dentro de cada período `cycleLen`, o
        // ponto fica "aceso" só durante `flashLife` — um flash curto
        // e frequente, repetindo pra sempre enquanto o eclipse durar.
        const cyclePos = (simTime + pt.cyclePhase) % pt.cycleLen;
        if (cyclePos > pt.flashLife) return; // apagado agora
        const t = cyclePos / pt.flashLife;
        const bright = t < 0.65 ? 1 : Math.max(0, 1 - (t - 0.65) / 0.35);

        const sc = worldToScreen(pt.wx, pt.wy);
        const scale = pt.scale * cam.zoom;
        if (sc.x < -200 || sc.x > canvas.width + 200 || sc.y < -200 || sc.y > canvas.height + 200) return;

        const glow = ctx.createRadialGradient(sc.x, sc.y, 0, sc.x, sc.y, 16 * scale);
        glow.addColorStop(0, `rgba(255,140,110,${0.95 * bright})`);
        glow.addColorStop(0.5, `rgba(255,40,20,${0.55 * bright})`);
        glow.addColorStop(1, 'transparent');
        ctx.beginPath(); ctx.arc(sc.x, sc.y, 16 * scale, 0, Math.PI * 2); ctx.fillStyle = glow; ctx.fill();

        ctx.save(); ctx.translate(sc.x, sc.y); ctx.scale(scale, scale);
        ctx.lineJoin = 'round'; ctx.lineCap = 'round';
        pt.roots.forEach(pts => {
          ctx.beginPath();
          pts.forEach((p, i) => i === 0 ? ctx.moveTo(p.x, p.y) : ctx.lineTo(p.x, p.y));
          ctx.strokeStyle = `rgba(255,60,30,${0.6 * bright})`; ctx.lineWidth = 3.5; ctx.stroke();
          ctx.beginPath();
          pts.forEach((p, i) => i === 0 ? ctx.moveTo(p.x, p.y) : ctx.lineTo(p.x, p.y));
          ctx.strokeStyle = `rgba(255,180,150,${bright})`; ctx.lineWidth = 1.3; ctx.stroke();
        });
        ctx.restore();
      });
    }
  }
}

function cosmicEclipseSpritesReset() {
  eclipseChunkCache.clear();
}

// ═══════════════════════════════════════════════════════════════════
//  MÓDULO: ATMOSFERA HOSTIL — a "cara" da Fase Cósmica agressiva
// ═══════════════════════════════════════════════════════════════════
//  O problema de só adicionar mais spawn é que o cenário continua
//  parecendo o Sandbox normal. Aqui a tela inteira muda de linguagem
//  visual: tingimento vermelho/brasa pulsante (não a paleta calma de
//  roxo/azul do espaço comum), vinheta que aperta nas bordas, cinzas e
//  fagulhas flutuando, e tremor de câmera quando muitos monstros estão
//  por perto — o "isso aqui não é mais seguro" que faltava.
// ═══════════════════════════════════════════════════════════════════

let _cosmicAtmoT = 0;
let _cosmicAtmoEmbers = [];
// FPS fix: menos partículas (eram 60 arcos+fillStyle novos por frame)
const COSMIC_ATMO_EMBER_COUNT = 26;

// FPS fix: caches de gradiente — createRadialGradient() é caro; antes era
// recriado 2x TODO frame (fundo + vinheta). Agora só recria quando o
// canvas muda de tamanho OU a cada N frames (a pulsação é lenta, então
// reaproveitar o gradiente por alguns frames é visualmente imperceptível).
let _cosmicAtmoBgGradCache = null, _cosmicAtmoBgGradW = 0, _cosmicAtmoBgGradH = 0, _cosmicAtmoBgGradFrame = -999;
let _cosmicAtmoVgGradCache = null, _cosmicAtmoVgGradW = 0, _cosmicAtmoVgGradH = 0, _cosmicAtmoVgGradFrame = -999;
let _cosmicAtmoFrameCounter = 0;
const COSMIC_ATMO_GRAD_REFRESH_EVERY = 4; // frames entre recriações de gradiente

// FPS fix: agrupa as fagulhas em poucos "buckets" de cor (em vez de uma
// string hsla() única por partícula) pra reduzir trocas de fillStyle,
// que forçam o parser de cor do Canvas a cada partícula.
const COSMIC_ATMO_EMBER_BUCKETS = 4;

function _cosmicAtmoInitEmbers() {
  _cosmicAtmoEmbers = Array.from({ length: COSMIC_ATMO_EMBER_COUNT }, () => {
    const bucket = Math.floor(rand(0, COSMIC_ATMO_EMBER_BUCKETS));
    return {
      x: rand(0, 1), y: rand(0, 1), // posição relativa à tela (0..1), re-sorteia ao sair
      vy: rand(6, 18), vx: rand(-4, 4),
      r: rand(0.6, 2.2),
      alpha: rand(0.25, 0.7),
      bucket,
    };
  });
}

function cosmicAtmosphereUpdate(dt) {
  _cosmicAtmoT += dt;
  if (_cosmicAtmoEmbers.length === 0) _cosmicAtmoInitEmbers();
  _cosmicAtmoEmbers.forEach(e => {
    e.x += (e.vx * dt) / canvas.width * 40;
    e.y += (e.vy * dt) / canvas.height * 40;
    if (e.y > 1.05) { e.y = -0.05; e.x = rand(0, 1); }
    if (e.x < -0.05) e.x = 1.05; else if (e.x > 1.05) e.x = -0.05;
  });
}

function cosmicAtmosphereDrawBg(ctxRef) {
  // Tingimento geral: substitui a sensação "roxo tranquilo" por um
  // vermelho/brasa que pulsa lentamente, como se o espaço "respirasse" perigo.
  const pulse = 0.5 + 0.5 * Math.sin(_cosmicAtmoT * 0.6);
  const intensity = 0.16 + 0.09 * pulse;

  // FPS fix: só recria o gradiente radial a cada COSMIC_ATMO_GRAD_REFRESH_EVERY
  // frames ou quando o canvas muda de tamanho — antes era criado 100% dos frames.
  const needsNewBg = !_cosmicAtmoBgGradCache
    || canvas.width !== _cosmicAtmoBgGradW || canvas.height !== _cosmicAtmoBgGradH
    || (_cosmicAtmoFrameCounter - _cosmicAtmoBgGradFrame) >= COSMIC_ATMO_GRAD_REFRESH_EVERY;
  if (needsNewBg) {
    const tint = ctx.createRadialGradient(canvas.width * .5, canvas.height * .5, 0, canvas.width * .5, canvas.height * .5, canvas.width * .75);
    tint.addColorStop(0, `rgba(120,10,10,${intensity * 0.5})`);
    tint.addColorStop(0.6, `rgba(80,0,20,${intensity})`);
    tint.addColorStop(1, `rgba(40,0,10,${intensity * 1.6})`);
    _cosmicAtmoBgGradCache = tint;
    _cosmicAtmoBgGradW = canvas.width; _cosmicAtmoBgGradH = canvas.height;
    _cosmicAtmoBgGradFrame = _cosmicAtmoFrameCounter;
  }
  ctx.fillStyle = _cosmicAtmoBgGradCache;
  ctx.fillRect(0, 0, canvas.width, canvas.height);

  // Cinzas/fagulhas flutuando por toda a tela (não presas ao mundo,
  // presas à tela — dá a sensação de "está caindo cinza do céu").
  // FPS fix: desenha por bucket de cor (um fillStyle set por bucket, não
  // por partícula) acumulando os arcos num único path por bucket.
  for (let b = 0; b < COSMIC_ATMO_EMBER_BUCKETS; b++) {
    let first = true;
    for (let i = 0; i < _cosmicAtmoEmbers.length; i++) {
      const e = _cosmicAtmoEmbers[i];
      if (e.bucket !== b) continue;
      if (first) { ctx.beginPath(); first = false; }
      const sx = e.x * canvas.width, sy = e.y * canvas.height;
      ctx.moveTo(sx + e.r, sy);
      ctx.arc(sx, sy, e.r, 0, Math.PI * 2);
    }
    if (!first) {
      ctx.fillStyle = `hsla(${4 + (b / (COSMIC_ATMO_EMBER_BUCKETS - 1)) * 24},90%,55%,0.45)`;
      ctx.fill();
    }
  }
  _cosmicAtmoFrameCounter++;
}

function cosmicAtmosphereDrawVignette(ctxRef) {
  // Vinheta vermelha nas bordas — aperta mais quando há muitos monstros por perto.
  const nearbyThreat = Math.min(1, (_cosmicMonsters ? _cosmicMonsters.length : 0) / COSMIC_MONSTER_MAX);
  const pulse = 0.5 + 0.5 * Math.sin(_cosmicAtmoT * 1.4);
  const strength = 0.25 + 0.35 * nearbyThreat + 0.08 * pulse;

  // FPS fix: mesmo tratamento de cache do fundo — vinheta antes recriava
  // outro createRadialGradient TODO frame.
  const needsNewVg = !_cosmicAtmoVgGradCache
    || canvas.width !== _cosmicAtmoVgGradW || canvas.height !== _cosmicAtmoVgGradH
    || (_cosmicAtmoFrameCounter - _cosmicAtmoVgGradFrame) >= COSMIC_ATMO_GRAD_REFRESH_EVERY;
  if (needsNewVg) {
    // Raios baseados na diagonal da tela (não só na altura) — em telas
    // largas (paisagem/desktop), usar canvas.height sozinho fazia o raio
    // ficar pequeno demais relativo à largura, cobrindo quase tudo.
    const diag = Math.hypot(canvas.width, canvas.height);
    const vg = ctx.createRadialGradient(
      canvas.width * .5, canvas.height * .5, diag * .32,
      canvas.width * .5, canvas.height * .5, diag * .62
    );
    vg.addColorStop(0, 'rgba(0,0,0,0)');
    vg.addColorStop(1, `rgba(140,0,0,${strength})`);
    _cosmicAtmoVgGradCache = vg;
    _cosmicAtmoVgGradW = canvas.width; _cosmicAtmoVgGradH = canvas.height;
    _cosmicAtmoVgGradFrame = _cosmicAtmoFrameCounter;
  }
  ctx.fillStyle = _cosmicAtmoVgGradCache;
  ctx.fillRect(0, 0, canvas.width, canvas.height);
}

// Tremor de câmera leve quando há ameaça densa perto do jogador —
// retorna um offset {x,y} pra somar na câmera de renderização.
function cosmicAtmosphereShake() {
  const threatNearby = (_cosmicMonsters || []).filter(m => {
    const d = Math.hypot(m.x - cam.x, m.y - cam.y);
    return d < 700;
  }).length;
  if (threatNearby < 4) return { x: 0, y: 0 };
  const mag = Math.min(4, (threatNearby - 3) * 0.8);
  return { x: (Math.random() - 0.5) * mag, y: (Math.random() - 0.5) * mag };
}

// ═══════════════════════════════════════════════════════════════════
//  MÓDULO: MONSTROS ERRANTES — segunda leva (padrões de ataque novos)
// ═══════════════════════════════════════════════════════════════════
//  Os 3 primeiros (Esporo/Devorador/Sentinela) só perseguem e mordem de
//  perto. Esta leva traz comportamentos categoricamente diferentes:
//  - Ceifador Sombrio: dispara projéteis à distância (não precisa encostar)
//  - Larva Fantasma: furtiva, invisível a maior parte do tempo, muito rápida
//  - Núcleo Instável: lento, mas EXPLODE ao morrer causando dano em área
// ═══════════════════════════════════════════════════════════════════

COSMIC_MONSTER_TYPES.reaper = {
  id: 'reaper',
  name: 'Ceifador Sombrio',
  color: '#ff2b4d',
  radius: () => rand(20, 26),
  speed: 58,
  turnGain: 3.2, angleLerp: 2.6, velLerp: 2.4,
  swarm: false,
  attackRange: 340,     // ataca à distância — não precisa se aproximar
  attackInterval: 1.8,
  attackPower: 'ranged',
  keepDistance: 220,    // tenta manter essa distância do alvo (kiting)
};

COSMIC_MONSTER_TYPES.ghostlarva = {
  id: 'ghostlarva',
  name: 'Larva Fantasma',
  color: '#ffe14d',
  radius: () => rand(9, 13),
  speed: 190,           // muito rápida
  turnGain: 8, angleLerp: 7, velLerp: 7,
  swarm: false,
  attackRange: 22,
  attackInterval: 0.9,
  attackPower: 'weak',
  stealth: true,         // maior parte do tempo quase invisível
};

COSMIC_MONSTER_TYPES.unstablecore = {
  id: 'unstablecore',
  name: 'Núcleo Instável',
  color: '#ff8a1f',
  radius: () => rand(16, 20),
  speed: 26,
  turnGain: 1.8, angleLerp: 1.4, velLerp: 1.2,
  swarm: false,
  attackRange: 34,
  attackInterval: 2.6,
  attackPower: 'medium',
  explodesOnDeath: true,
  explosionRadius: 130,
};
COSMIC_MONSTER_TYPE_IDS.push('reaper', 'ghostlarva', 'unstablecore');

let _cosmicProjectiles = [];

function _cosmicFireProjectile(mon, def, target) {
  const dx = target.x - mon.x, dy = target.y - mon.y;
  const d = Math.hypot(dx, dy) || 1;
  const speed = 210;
  _cosmicProjectiles.push({
    x: mon.x, y: mon.y,
    vx: (dx / d) * speed, vy: (dy / d) * speed,
    life: 2.5, color: def.color, targetId: target.id,
  });
}

function cosmicProjectilesUpdate(dt) {
  for (let i = _cosmicProjectiles.length - 1; i >= 0; i--) {
    const pr = _cosmicProjectiles[i];
    pr.x += pr.vx * dt; pr.y += pr.vy * dt; pr.life -= dt;
    if (pr.life <= 0) { _cosmicProjectiles.splice(i, 1); continue; }
    // ── Torres bloqueiam ataques à distância: se o projétil cruzar o
    // raio de uma Torre ou o "corredor" de conexão entre duas Torres
    // ligadas, ele é destruído ali — nunca alcança o alvo original.
    // Checagem adicional, não interfere no restante da lógica abaixo. ──
    if (typeof _cosmicTowerBlocksProjectile === 'function' && _cosmicTowerBlocksProjectile(pr.x, pr.y)) {
      if (typeof particles !== 'undefined') {
        for (let k = 0; k < 5; k++) {
          const ang = rand(0, Math.PI * 2);
          particles.push({ x: pr.x, y: pr.y, vx: Math.cos(ang) * rand(2, 5), vy: Math.sin(ang) * rand(2, 5), r: rand(1, 2), alpha: 0.9, color: '#8fe0ff' });
        }
      }
      _cosmicProjectiles.splice(i, 1);
      continue;
    }
    if (typeof objects !== 'undefined') {
      const tgt = objects.find(o => o.id === pr.targetId && !o.dead);
      if (tgt) {
        const d = Math.hypot(tgt.x - pr.x, tgt.y - pr.y);
        if (d < (tgt.radius || 10) + 6) {
          tgt.bioTemp = Math.max(0, Math.min(100, (tgt.bioTemp ?? 50) + rand(-18, 18)));
          tgt.bioO2 = Math.max(0, (tgt.bioO2 ?? 21) - rand(2, 5));
          if (typeof tgt.radius === 'number' && tgt.radius > 4) tgt.radius -= rand(0.15, 0.4);
          if (typeof particles !== 'undefined') {
            for (let k = 0; k < 5; k++) {
              const ang = rand(0, Math.PI * 2);
              particles.push({ x: tgt.x, y: tgt.y, vx: Math.cos(ang) * rand(2, 6), vy: Math.sin(ang) * rand(2, 6), r: rand(1, 2.5), alpha: 0.9, color: pr.color });
            }
          }
          _cosmicProjectiles.splice(i, 1);
        }
      }
    }
  }
}

function cosmicProjectilesDraw(ctxRef) {
  _cosmicProjectiles.forEach(pr => {
    const sx = (pr.x - cam.x) * cam.zoom + canvas.width * 0.5;
    const sy = (pr.y - cam.y) * cam.zoom + canvas.height * 0.5;
    if (sx < -30 || sx > canvas.width + 30 || sy < -30 || sy > canvas.height + 30) return;
    const g = ctx.createRadialGradient(sx, sy, 0, sx, sy, 8);
    g.addColorStop(0, pr.color); g.addColorStop(1, 'transparent');
    ctx.beginPath(); ctx.arc(sx, sy, 8, 0, Math.PI * 2); ctx.fillStyle = g; ctx.fill();
    ctx.beginPath(); ctx.arc(sx, sy, 2.5, 0, Math.PI * 2); ctx.fillStyle = '#fff'; ctx.fill();
  });
}

function _cosmicMonsterExplode(mon, def) {
  if (typeof objects !== 'undefined') {
    objects.forEach(o => {
      if (o.dead || o.fixed) return;
      const d = Math.hypot(o.x - mon.x, o.y - mon.y);
      if (d < def.explosionRadius) {
        const falloff = 1 - d / def.explosionRadius;
        o.bioO2 = Math.max(0, (o.bioO2 ?? 21) - 8 * falloff);
        o.bioWater = Math.max(0, (o.bioWater ?? 30) - 8 * falloff);
        if (typeof o.radius === 'number' && o.radius > 4) o.radius -= 1.2 * falloff;
      }
    });
  }
  if (typeof spawnExplosion === 'function') spawnExplosion(mon.x, mon.y, 1.4, false);
}

// ═══════════════════════════════════════════════════════════════════
//  UNIDADES DEFENSIVAS DA FASE CÓSMICA — Torre, Sentinela, Cavaleiro
//  e Mago. Criadas manualmente pelo jogador (gastando Quantiks/Staris,
//  igual outros astros), atacam apenas monstros cósmicos e monstros de
//  terror (_cosmicMonsters / _cosmicTerrorMonsters) — nunca as 3 raças
//  cósmicas. Cada tipo tem HP/ataque/movimento próprios e limite de
//  população individual (mesmo padrão de _cosmicProbeLimit).
// ═══════════════════════════════════════════════════════════════════
const COSMIC_DEFENDER_TYPES = {
  tower: {
    id: 'tower',
    name: 'Torre',
    color: '#66d9ff',
    radius: 26,
    maxHp: 420,
    attack: 26,
    attackRange: 260,
    attackInterval: 1.1,
    moveSpeed: 0,           // fixa, não se move
    canRotate: false,
    limit: 6,
    linkRange: 420,          // alcance de conexão entre Torres (estilo Estrela de Cordas)
  },
  sentinel: {
    id: 'sentinel',
    name: 'Sentinela',
    color: '#ffd166',
    radius: 14,
    maxHp: 90,
    attack: 34,
    attackRange: 320,
    attackInterval: 0.6,
    moveSpeed: 0,           // fixa no local onde foi criada, só gira pra mirar
    canRotate: true,
    limit: 10,
  },
  knight: {
    id: 'knight',
    name: 'Cavaleiro',
    color: '#ff8a5c',
    radius: 18,
    maxHp: 260,
    attack: 22,
    attackRange: 46,          // ataque corpo a corpo
    attackInterval: 0.9,
    moveSpeed: 60,             // lento
    canRotate: true,
    limit: 6,
  },
  mage: {
    id: 'mage',
    name: 'Mago',
    color: '#c98bff',
    radius: 13,
    maxHp: 55,
    attack: 48,
    attackRange: 380,
    attackInterval: 0.85,
    moveSpeed: 150,            // bem mais rápido
    canRotate: true,
    limit: 5,
  },
};
const COSMIC_DEFENDER_TYPE_IDS = Object.keys(COSMIC_DEFENDER_TYPES);

let _cosmicDefenders = [];
let _cosmicDefenderIdCounter = 1;

function cosmicDefenderCount(typeId) {
  return _cosmicDefenders.filter(d => !d.dead && d.typeId === typeId).length;
}
function cosmicDefenderLimit(typeId) {
  return COSMIC_DEFENDER_TYPES[typeId] ? COSMIC_DEFENDER_TYPES[typeId].limit : 0;
}

// Tenta criar uma unidade defensiva no ponto (wx,wy). Cobra o custo em
// Quantiks/Staris, respeita o limite individual do tipo e só funciona
// na Fase Cósmica (fora de batalha de boss). Retorna true se criou.
function trySpawnCosmicDefender(typeId, wx, wy) {
  const def = COSMIC_DEFENDER_TYPES[typeId];
  if (!def) return false;
  if (!(sandboxMode && _sandboxPhase === 'cosmic')) {
    showTooltip(`${_cosmicDefenderIcon(typeId)} ${def.name} disponível apenas na Fase Cósmica`);
    return false;
  }
  if (typeof _isBattle === 'function' && _isBattle()) {
    showTooltip('🚫 Não é possível invocar unidades durante uma batalha de boss!');
    return false;
  }
  if (cosmicDefenderCount(typeId) >= cosmicDefenderLimit(typeId)) {
    showTooltip(`🚫 Limite de ${cosmicDefenderLimit(typeId)} ${def.name}(s) já atingido!`);
    return false;
  }
  // Sem custo em Quantiks/Staris — unidades defensivas são gratuitas,
  // limitadas apenas pelo limite individual de população de cada tipo.
  _cosmicDefenders.push({
    id: 'defender_' + (_cosmicDefenderIdCounter++),
    typeId, x: wx, y: wy,
    angle: rand(0, Math.PI * 2),
    hp: def.maxHp, maxHp: def.maxHp,
    phase: rand(0, Math.PI * 2),
    attackCd: rand(0, def.attackInterval),
    targetId: null,
    dead: false,
  });
  if (typeof scheduleSave === 'function') scheduleSave();
  showTooltip(`${_cosmicDefenderIcon(typeId)} ${def.name} invocado! (${cosmicDefenderCount(typeId)}/${cosmicDefenderLimit(typeId)})`);
  return true;
}

function _cosmicDefenderIcon(typeId) {
  return { tower: '🗼', sentinel: '🛡️', knight: '⚔️', mage: '🔮' }[typeId] || '✨';
}

// Encontra o monstro (comum ou de terror) mais próximo dentro do
// alcance — unidades defensivas nunca miram astros nem raças cósmicas.
function _cosmicDefenderFindTarget(unit, range) {
  let best = null, bestD = range;
  for (const mon of _cosmicMonsters) {
    if (typeof mon.hp === 'number' && mon.hp <= 0) continue;
    const d = Math.hypot(mon.x - unit.x, mon.y - unit.y);
    if (d < bestD) { bestD = d; best = mon; best._src = '_cosmicMonsters'; }
  }
  for (const mon of _cosmicTerrorMonsters) {
    if (typeof mon.hp === 'number' && mon.hp <= 0) continue;
    const d = Math.hypot(mon.x - unit.x, mon.y - unit.y);
    if (d < bestD) { bestD = d; best = mon; best._src = '_cosmicTerrorMonsters'; }
  }
  return best;
}

function _cosmicDefenderDamage(mon, amount) {
  if (typeof mon.hp !== 'number') return;
  mon.hp -= amount;
  if (typeof particles !== 'undefined') {
    for (let k = 0; k < 3; k++) {
      const ang = rand(0, Math.PI * 2);
      particles.push({ x: mon.x, y: mon.y, vx: Math.cos(ang) * rand(1.5, 4), vy: Math.sin(ang) * rand(1.5, 4), r: rand(1, 2), alpha: 0.9, color: '#ffffff' });
    }
  }
}

// Torres: verifica pares mutuamente dentro de linkRange e, se um
// monstro cruzar essa linha, ele é barrado (empurrado de volta) —
// simula o "bloqueio" de inimigos entre Torres conectadas.
function _cosmicTowerLinksBlock(dt) {
  const towers = _cosmicDefenders.filter(d => !d.dead && d.typeId === 'tower');
  const def = COSMIC_DEFENDER_TYPES.tower;
  for (let i = 0; i < towers.length; i++) {
    for (let j = i + 1; j < towers.length; j++) {
      const a = towers[i], b = towers[j];
      const d = Math.hypot(b.x - a.x, b.y - a.y);
      if (d > def.linkRange) continue;
      a._linked = true; b._linked = true;
      // Bloqueia monstros que tentem cruzar o segmento a→b: projeta a
      // posição do monstro na linha e, se estiver perto o bastante do
      // segmento (dentro de um "corredor" fino), empurra para fora.
      const segX = b.x - a.x, segY = b.y - a.y;
      const segLenSq = segX * segX + segY * segY || 1;
      const corridor = 24; // meia-largura do bloqueio, em unidades de mundo
      const checkList = [_cosmicMonsters, _cosmicTerrorMonsters];
      for (const list of checkList) {
        for (const mon of list) {
          if (typeof mon.hp === 'number' && mon.hp <= 0) continue;
          const t = Math.max(0, Math.min(1, ((mon.x - a.x) * segX + (mon.y - a.y) * segY) / segLenSq));
          const px = a.x + segX * t, py = a.y + segY * t;
          const dd = Math.hypot(mon.x - px, mon.y - py);
          if (t > 0.03 && t < 0.97 && dd < corridor + (mon.radius || 10)) {
            const nx = (mon.x - px) / (dd || 1), ny = (mon.y - py) / (dd || 1);
            const push = (corridor + (mon.radius || 10) - dd);
            mon.x += nx * push;
            mon.y += ny * push;
          }
        }
      }
    }
  }
}

// Verifica se um ponto (ex: posição atual de um projétil inimigo) está
// dentro do raio de bloqueio de uma Torre, ou dentro do "corredor" de
// conexão entre duas Torres ligadas — usado para interceptar ataques
// à distância dos monstros (ver cosmicProjectilesUpdate).
function _cosmicTowerBlocksProjectile(px, py) {
  const towers = _cosmicDefenders.filter(d => !d.dead && d.typeId === 'tower');
  if (!towers.length) return false;
  const towerDef = COSMIC_DEFENDER_TYPES.tower;
  const blockRadius = towerDef.radius * 1.6; // um pouco além do corpo visual da Torre
  for (const t of towers) {
    if (Math.hypot(px - t.x, py - t.y) < blockRadius) return true;
  }
  const corridor = 24;
  for (let i = 0; i < towers.length; i++) {
    for (let j = i + 1; j < towers.length; j++) {
      const a = towers[i], b = towers[j];
      const d = Math.hypot(b.x - a.x, b.y - a.y);
      if (d > towerDef.linkRange) continue;
      const segX = b.x - a.x, segY = b.y - a.y;
      const segLenSq = segX * segX + segY * segY || 1;
      const t = Math.max(0, Math.min(1, ((px - a.x) * segX + (py - a.y) * segY) / segLenSq));
      const projX = a.x + segX * t, projY = a.y + segY * t;
      const dd = Math.hypot(px - projX, py - projY);
      if (t > 0.03 && t < 0.97 && dd < corridor) return true;
    }
  }
  return false;
}

function cosmicDefendersUpdate(dt) {
  if (!(sandboxMode && _sandboxPhase === 'cosmic')) {
    if (_cosmicDefenders.length) _cosmicDefenders = [];
    return;
  }
  if (typeof _isBattle === 'function' && _isBattle()) return;

  // Reset da flag de conexão visual (recalculada a cada frame em _cosmicTowerLinksBlock)
  _cosmicDefenders.forEach(d => { d._linked = false; });
  _cosmicTowerLinksBlock(dt);

  for (let i = _cosmicDefenders.length - 1; i >= 0; i--) {
    const unit = _cosmicDefenders[i];
    if (unit.dead) { _cosmicDefenders.splice(i, 1); continue; }
    const def = COSMIC_DEFENDER_TYPES[unit.typeId];
    unit.phase += dt;

    if (unit.hp <= 0) {
      if (typeof spawnExplosion === 'function') spawnExplosion(unit.x, unit.y, 0.9, false);
      _cosmicDefenders.splice(i, 1);
      continue;
    }

    // ── Alvo ──
    let target = unit.targetId
      ? (_cosmicMonsters.find(m => m.id === unit.targetId && m.hp > 0) ||
         _cosmicTerrorMonsters.find(m => m.id === unit.targetId && m.hp > 0))
      : null;
    if (!target || Math.random() < 0.02) {
      const t = _cosmicDefenderFindTarget(unit, def.attackRange * (unit.typeId === 'knight' ? 3.2 : 1.6));
      unit.targetId = t ? t.id : null;
      target = t;
    }

    // ── Movimento (Cavaleiro e Mago se movem/giram; Torre e Sentinela ficam fixas) ──
    if (def.moveSpeed > 0 && target) {
      const dx = target.x - unit.x, dy = target.y - unit.y;
      const d = Math.hypot(dx, dy) || 1;
      const desiredAngle = Math.atan2(dy, dx);
      let da = desiredAngle - unit.angle;
      while (da > Math.PI) da -= Math.PI * 2;
      while (da < -Math.PI) da += Math.PI * 2;
      unit.angle += da * Math.min(1, dt * 5);
      if (d > def.attackRange * 0.75) {
        unit.x += Math.cos(unit.angle) * def.moveSpeed * dt;
        unit.y += Math.sin(unit.angle) * def.moveSpeed * dt;
      }
    } else if (def.canRotate && target) {
      // Sentinela: não anda, só gira para mirar.
      const desiredAngle = Math.atan2(target.y - unit.y, target.x - unit.x);
      let da = desiredAngle - unit.angle;
      while (da > Math.PI) da -= Math.PI * 2;
      while (da < -Math.PI) da += Math.PI * 2;
      unit.angle += da * Math.min(1, dt * 6);
    } else if (target) {
      unit.angle = Math.atan2(target.y - unit.y, target.x - unit.x);
    }

    // ── Ataque ──
    unit.attackCd -= dt;
    if (target && unit.attackCd <= 0) {
      const d = Math.hypot(target.x - unit.x, target.y - unit.y);
      if (d < def.attackRange) {
        unit.attackCd = def.attackInterval;
        _cosmicDefenderDamage(target, def.attack);
        if (unit.typeId !== 'knight') {
          // Ataques à distância deixam um projétil visual simples.
          _cosmicDefenderProjectiles.push({
            x: unit.x, y: unit.y, tx: target.x, ty: target.y,
            life: 0.18, color: def.color,
          });
        } else if (typeof particles !== 'undefined') {
          for (let k = 0; k < 4; k++) {
            const ang = rand(0, Math.PI * 2);
            particles.push({ x: target.x, y: target.y, vx: Math.cos(ang) * rand(2, 5), vy: Math.sin(ang) * rand(2, 5), r: rand(1, 2.5), alpha: 0.9, color: def.color });
          }
        }
      }
    }
  }

  // Projéteis visuais das unidades defensivas
  for (let i = _cosmicDefenderProjectiles.length - 1; i >= 0; i--) {
    _cosmicDefenderProjectiles[i].life -= dt;
    if (_cosmicDefenderProjectiles[i].life <= 0) _cosmicDefenderProjectiles.splice(i, 1);
  }
}

let _cosmicDefenderProjectiles = [];

function cosmicDefendersDraw(ctxRef) {
  if (!(sandboxMode && _sandboxPhase === 'cosmic') || (typeof _isBattle === 'function' && _isBattle())) return;

  // ── Muro/barreira de energia entre Torres conectadas — campo de força
  // sólido translúcido (faixa reta preenchida) em vez de linha tracejada,
  // com leve pulso de opacidade e textura de "veios" de energia por cima. ──
  const towers = _cosmicDefenders.filter(d => !d.dead && d.typeId === 'tower');
  const linkRange = COSMIC_DEFENDER_TYPES.tower.linkRange;
  const wallT = (typeof performance !== 'undefined' ? performance.now() : Date.now()) / 1000;
  for (let i = 0; i < towers.length; i++) {
    for (let j = i + 1; j < towers.length; j++) {
      const a = towers[i], b = towers[j];
      const d = Math.hypot(b.x - a.x, b.y - a.y);
      if (d > linkRange) continue;
      const asx = (a.x - cam.x) * cam.zoom + canvas.width * 0.5, asy = (a.y - cam.y) * cam.zoom + canvas.height * 0.5;
      const bsx = (b.x - cam.x) * cam.zoom + canvas.width * 0.5, bsy = (b.y - cam.y) * cam.zoom + canvas.height * 0.5;
      const dx = bsx - asx, dy = bsy - asy;
      const segLen = Math.hypot(dx, dy) || 1;
      const nx = -dy / segLen, ny = dx / segLen; // normal perpendicular ao segmento
      const halfW = Math.max(6, 10 * cam.zoom); // meia-largura visual do muro
      const pulse = 0.28 + 0.14 * Math.sin(wallT * 1.6 + i * 0.7 + j * 0.3);

      // Corpo sólido translúcido da barreira (quad preenchido)
      ctx.beginPath();
      ctx.moveTo(asx + nx * halfW, asy + ny * halfW);
      ctx.lineTo(bsx + nx * halfW, bsy + ny * halfW);
      ctx.lineTo(bsx - nx * halfW, bsy - ny * halfW);
      ctx.lineTo(asx - nx * halfW, asy - ny * halfW);
      ctx.closePath();
      const wallGrad = ctx.createLinearGradient(asx, asy, bsx, bsy);
      wallGrad.addColorStop(0, `rgba(102,217,255,${pulse * 0.4})`);
      wallGrad.addColorStop(0.5, `rgba(150,235,255,${pulse})`);
      wallGrad.addColorStop(1, `rgba(102,217,255,${pulse * 0.4})`);
      ctx.fillStyle = wallGrad;
      ctx.fill();

      // Bordas mais nítidas (contorno do campo de força)
      ctx.strokeStyle = `rgba(200,245,255,${Math.min(0.85, pulse + 0.35)})`;
      ctx.lineWidth = Math.max(1, 1.4 * cam.zoom);
      ctx.beginPath();
      ctx.moveTo(asx + nx * halfW, asy + ny * halfW); ctx.lineTo(bsx + nx * halfW, bsy + ny * halfW);
      ctx.stroke();
      ctx.beginPath();
      ctx.moveTo(asx - nx * halfW, asy - ny * halfW); ctx.lineTo(bsx - nx * halfW, bsy - ny * halfW);
      ctx.stroke();

      // Veios de energia: pequenas linhas transversais deslizando ao
      // longo do muro, reforçando leitura de "campo ativo" em movimento.
      const segCount = Math.max(2, Math.floor(segLen / 40));
      ctx.strokeStyle = `rgba(230,255,255,${pulse * 0.9})`;
      ctx.lineWidth = Math.max(1, cam.zoom);
      for (let k = 0; k < segCount; k++) {
        let t = (k / segCount + (wallT * 0.15) % 1) % 1;
        const px = asx + dx * t, py = asy + dy * t;
        ctx.beginPath();
        ctx.moveTo(px + nx * halfW * 0.7, py + ny * halfW * 0.7);
        ctx.lineTo(px - nx * halfW * 0.7, py - ny * halfW * 0.7);
        ctx.stroke();
      }
    }
  }

  // ── Projéteis das unidades ──
  _cosmicDefenderProjectiles.forEach(pr => {
    const t = 1 - Math.max(0, pr.life / 0.18);
    const px = pr.x + (pr.tx - pr.x) * t, py = pr.y + (pr.ty - pr.y) * t;
    const sx = (px - cam.x) * cam.zoom + canvas.width * 0.5, sy = (py - cam.y) * cam.zoom + canvas.height * 0.5;
    if (sx < -30 || sx > canvas.width + 30 || sy < -30 || sy > canvas.height + 30) return;
    ctx.beginPath(); ctx.arc(sx, sy, 3.5, 0, Math.PI * 2); ctx.fillStyle = pr.color; ctx.fill();
  });

  // ── Unidades ──
  _cosmicDefenders.forEach(unit => {
    const def = COSMIC_DEFENDER_TYPES[unit.typeId];
    const sx = (unit.x - cam.x) * cam.zoom + canvas.width * 0.5;
    const sy = (unit.y - cam.y) * cam.zoom + canvas.height * 0.5;
    const r = def.radius * cam.zoom;
    if (sx + r < -60 || sx - r > canvas.width + 60 || sy + r < -60 || sy - r > canvas.height + 60) return;

    ctx.save();
    ctx.translate(sx, sy);
    if (def.canRotate) ctx.rotate(unit.angle);

    if (unit.typeId === 'tower') {
      // ── Torre: cristal hexagonal facetado, com pontas nas 6 arestas
      // e núcleo em camadas concêntricas — mesma linguagem visual dos
      // astros (gradientes em camadas + brilho central), mas em formato
      // tecnológico/cristalino, reforçando "estrutura defensiva fixa".
      const rot = Math.PI / 6;
      const outer = [];
      for (let k = 0; k < 6; k++) { const a = rot + (k / 6) * Math.PI * 2; outer.push([Math.cos(a) * r, Math.sin(a) * r]); }
      // Halo externo mais forte quando conectada a outra Torre.
      const linkGlow = (unit._linked ? 1.4 : 1.0) * (1 + 0.05 * Math.sin(unit.phase * 2.2));
      const gOuter = ctx.createRadialGradient(0, 0, r * 0.3, 0, 0, r * 2.4 * linkGlow);
      gOuter.addColorStop(0, 'rgba(140,230,255,0.35)'); gOuter.addColorStop(1, 'transparent');
      ctx.beginPath(); ctx.arc(0, 0, r * 2.4 * linkGlow, 0, Math.PI * 2); ctx.fillStyle = gOuter; ctx.fill();
      // Casca hexagonal
      ctx.beginPath(); outer.forEach((p, i) => i === 0 ? ctx.moveTo(p[0], p[1]) : ctx.lineTo(p[0], p[1])); ctx.closePath();
      ctx.fillStyle = '#123048'; ctx.fill();
      ctx.strokeStyle = unit._linked ? '#eaffff' : 'rgba(180,235,255,0.7)'; ctx.lineWidth = 2; ctx.stroke();
      // Núcleo em anéis hexagonais concêntricos, cor esquentando pro centro —
      // pulso de energia sutil (escala respirando no ritmo de unit.phase).
      const towerPulse = 1 + 0.08 * Math.sin(unit.phase * 2.2);
      const ringCols = ['#1f6b93', '#3fa9d6', '#8fe0ff', '#ffffff'];
      for (let i = 0; i < 4; i++) {
        const rr = r * (0.62 - i * 0.15) * towerPulse;
        const pts = []; for (let k = 0; k < 6; k++) { const a = rot + 0.15 * i + (k / 6) * Math.PI * 2; pts.push([Math.cos(a) * rr, Math.sin(a) * rr]); }
        ctx.beginPath(); pts.forEach((p, k) => k === 0 ? ctx.moveTo(p[0], p[1]) : ctx.lineTo(p[0], p[1])); ctx.closePath();
        ctx.fillStyle = ringCols[i]; ctx.fill();
      }
      // Pontas nas 6 arestas (silhueta de torre cravejada)
      for (let k = 0; k < 6; k++) {
        const a = rot + (k / 6) * Math.PI * 2;
        const bx = Math.cos(a) * r, by = Math.sin(a) * r;
        const tx = Math.cos(a) * r * 1.32, ty = Math.sin(a) * r * 1.32;
        const perp = a + Math.PI / 2, w = r * 0.12;
        ctx.beginPath();
        ctx.moveTo(bx + Math.cos(perp) * w, by + Math.sin(perp) * w);
        ctx.lineTo(bx - Math.cos(perp) * w, by - Math.sin(perp) * w);
        ctx.lineTo(tx, ty);
        ctx.closePath();
        ctx.fillStyle = '#a8ecff'; ctx.fill();
      }
    } else if (unit.typeId === 'sentinel') {
      // ── Sentinela: corpo hexagonal compacto com lente/canhão central
      // em camadas (imita a leitura de "olho mirando"), canhão saliente
      // e nadadeiras laterais — leitura clara de unidade de ataque leve.
      const body = [];
      for (let k = 0; k < 6; k++) { const a = (k / 6) * Math.PI * 2; body.push([Math.cos(a) * r * 0.9, Math.sin(a) * r * 0.9]); }
      const gS = ctx.createRadialGradient(0, 0, 0, 0, 0, r * 2.6);
      gS.addColorStop(0, 'rgba(255,214,102,0.35)'); gS.addColorStop(1, 'transparent');
      ctx.beginPath(); ctx.arc(0, 0, r * 2.6, 0, Math.PI * 2); ctx.fillStyle = gS; ctx.fill();
      ctx.beginPath(); body.forEach((p, i) => i === 0 ? ctx.moveTo(p[0], p[1]) : ctx.lineTo(p[0], p[1])); ctx.closePath();
      ctx.fillStyle = '#4a2f0a'; ctx.fill();
      ctx.strokeStyle = 'rgba(255,225,150,0.8)'; ctx.lineWidth = 1.6; ctx.stroke();
      // Lente: pisca (brilho pulsante) e o anel externo gira devagar,
      // reforçando a leitura de "olho mirando" sempre ativo.
      const lensBlink = 0.75 + 0.25 * Math.sin(unit.phase * 3.4);
      const lensCols = ['#c9852a', '#ffb84d', '#ffe9b0'];
      for (let i = 0; i < 3; i++) {
        const rr = r * (0.56 - i * 0.16) * (i === 2 ? lensBlink : 1);
        ctx.beginPath(); ctx.arc(0, 0, rr, 0, Math.PI * 2); ctx.fillStyle = lensCols[i]; ctx.fill();
      }
      ctx.save();
      ctx.rotate(unit.phase * 0.8);
      ctx.strokeStyle = `rgba(255,225,150,${0.35 + 0.25 * lensBlink})`;
      ctx.lineWidth = 1.2;
      ctx.setLineDash([r * 0.25, r * 0.3]);
      ctx.beginPath(); ctx.arc(0, 0, r * 0.72, 0, Math.PI * 2); ctx.stroke();
      ctx.setLineDash([]);
      ctx.restore();
      // canhão apontando na direção do alvo
      ctx.fillStyle = '#ffd166';
      ctx.beginPath();
      ctx.moveTo(r * 0.5, -r * 0.16); ctx.lineTo(r * 1.5, -r * 0.1); ctx.lineTo(r * 1.5, r * 0.1); ctx.lineTo(r * 0.5, r * 0.16);
      ctx.closePath(); ctx.fill();
      ctx.strokeStyle = 'rgba(255,255,255,0.6)'; ctx.lineWidth = 1; ctx.stroke();
      // nadadeiras laterais
      for (const sgn of [-1, 1]) {
        ctx.beginPath();
        ctx.moveTo(0, sgn * r * 0.7); ctx.lineTo(-r * 0.35, sgn * r * 1.15); ctx.lineTo(r * 0.15, sgn * r * 0.85);
        ctx.closePath(); ctx.fillStyle = '#e0a83c'; ctx.fill();
      }
    } else if (unit.typeId === 'knight') {
      // ── Cavaleiro: corpo blindado angular com peitoral facetado e
      // lâmina alongada + cravos nos ombros — silhueta de combatente
      // corpo a corpo pesado, mas com o mesmo acabamento em camadas.
      const gK = ctx.createRadialGradient(0, 0, 0, 0, 0, r * 2.3);
      gK.addColorStop(0, 'rgba(255,138,92,0.32)'); gK.addColorStop(1, 'transparent');
      ctx.beginPath(); ctx.arc(0, 0, r * 2.3, 0, Math.PI * 2); ctx.fillStyle = gK; ctx.fill();
      const body = [[r * 1.15, 0], [r * 0.25, -r * 0.85], [-r * 0.85, -r * 0.55], [-r * 0.85, r * 0.55], [r * 0.25, r * 0.85]];
      ctx.beginPath(); body.forEach((p, i) => i === 0 ? ctx.moveTo(p[0], p[1]) : ctx.lineTo(p[0], p[1])); ctx.closePath();
      ctx.fillStyle = '#4d190a'; ctx.fill();
      ctx.strokeStyle = 'rgba(255,180,130,0.8)'; ctx.lineWidth = 2; ctx.stroke();
      // peitoral facetado (hex pequeno deslocado pro centro do corpo)
      const chestCols = ['#a84a1e', '#ff8a5c', '#ffd2b0'];
      for (let i = 0; i < 3; i++) {
        const rr = r * (0.4 - i * 0.11);
        const pts = []; for (let k = 0; k < 6; k++) { const a = 0.4 + (k / 6) * Math.PI * 2; pts.push([-r * 0.05 + Math.cos(a) * rr, Math.sin(a) * rr]); }
        ctx.beginPath(); pts.forEach((p, k) => k === 0 ? ctx.moveTo(p[0], p[1]) : ctx.lineTo(p[0], p[1])); ctx.closePath();
        ctx.fillStyle = chestCols[i]; ctx.fill();
      }
      // lâmina — leve balanço angular (empunhadura "respirando", pronta
      // pra golpear) em vez de ficar travada na direção do alvo.
      const bladeSway = Math.sin(unit.phase * 2.6) * 0.09;
      ctx.save();
      ctx.rotate(bladeSway);
      ctx.beginPath();
      ctx.moveTo(r * 1.15, 0); ctx.lineTo(r * 2.15, -r * 0.15); ctx.lineTo(r * 2.35, 0); ctx.lineTo(r * 2.15, r * 0.15);
      ctx.closePath(); ctx.fillStyle = '#e6e6f0'; ctx.fill();
      ctx.strokeStyle = 'rgba(255,255,255,0.7)'; ctx.lineWidth = 1; ctx.stroke();
      ctx.restore();
      // cravos de ombro
      for (const sgn of [-1, 1]) {
        ctx.beginPath();
        ctx.moveTo(-r * 0.85, sgn * r * 0.55); ctx.lineTo(-r * 1.35, sgn * r * 0.85); ctx.lineTo(-r * 0.55, sgn * r * 0.75);
        ctx.closePath(); ctx.fillStyle = '#c85028'; ctx.fill();
      }
    } else if (unit.typeId === 'mage') {
      // ── Mago: núcleo pequeno e denso com anel arcano orbital tilted
      // (3 fragmentos girando) e coroa de pontas — leitura de
      // "conjurador rápido e frágil", ecoando o visual das Cefeidas/
      // pulsares (núcleo + anel) só que numa escala compacta.
      const gM = ctx.createRadialGradient(0, 0, 0, 0, 0, r * 3);
      gM.addColorStop(0, 'rgba(201,139,255,0.4)'); gM.addColorStop(1, 'transparent');
      ctx.beginPath(); ctx.arc(0, 0, r * 3, 0, Math.PI * 2); ctx.fillStyle = gM; ctx.fill();
      const coreCols = ['#5a1f8f', '#9a4fd6', '#e6c9ff'];
      for (let i = 0; i < 3; i++) {
        const rr = r * (0.58 - i * 0.19);
        ctx.beginPath(); ctx.arc(0, 0, rr, 0, Math.PI * 2); ctx.fillStyle = coreCols[i]; ctx.fill();
      }
      // coroa de pontas no topo
      for (let k = 0; k < 5; k++) {
        const a = Math.PI + (k - 2) * 0.35;
        const tx = Math.cos(a) * r * 0.95, ty = Math.sin(a) * r * 0.95 - r * 0.35;
        ctx.beginPath();
        ctx.moveTo(Math.cos(a) * r * 0.3, Math.sin(a) * r * 0.3 - r * 0.1);
        ctx.lineTo(tx, ty);
        ctx.lineTo(Math.cos(a + 0.15) * r * 0.3, Math.sin(a + 0.15) * r * 0.3 - r * 0.1);
        ctx.closePath(); ctx.fillStyle = '#7a35b8'; ctx.fill();
      }
      // anel arcano orbital tilted com 3 fragmentos
      const pulse = 1 + 0.12 * Math.sin(unit.phase * 5);
      ctx.beginPath(); ctx.ellipse(0, 0, r * 1.35 * pulse, r * 0.5 * pulse, unit.phase * 0.3, 0, Math.PI * 2);
      ctx.strokeStyle = 'rgba(230,190,255,0.75)'; ctx.lineWidth = 1.6; ctx.stroke();
      for (let i = 0; i < 3; i++) {
        const a = unit.phase * 1.4 + i * (Math.PI * 2 / 3);
        const fx = Math.cos(a) * r * 1.35 * pulse, fy = Math.sin(a) * r * 0.5 * pulse;
        const sz = r * 0.14;
        ctx.beginPath();
        ctx.moveTo(fx, fy - sz); ctx.lineTo(fx + sz * 0.7, fy); ctx.lineTo(fx, fy + sz); ctx.lineTo(fx - sz * 0.7, fy);
        ctx.closePath(); ctx.fillStyle = '#dcaaff'; ctx.fill();
        ctx.strokeStyle = 'rgba(255,255,255,0.7)'; ctx.lineWidth = 1; ctx.stroke();
      }
    }
    ctx.restore();

    // Barra de HP acima da unidade
    const hpPct = Math.max(0, unit.hp / unit.maxHp);
    const bw = Math.max(20, r * 2.2), bh = 3.5;
    const bx = sx - bw / 2, by = sy - r - 12;
    ctx.fillStyle = 'rgba(0,0,0,0.5)'; ctx.fillRect(bx, by, bw, bh);
    ctx.fillStyle = hpPct > 0.5 ? '#4dff88' : hpPct > 0.22 ? '#ffcc33' : '#ff4455';
    ctx.fillRect(bx, by, bw * hpPct, bh);
  });
}

const COSMIC_MONSTER_DRAWERS_EXT = {
  reaper: function (mon, sx, sy, r) {

    const pulse = 1 + 0.1 * Math.sin(mon.phase * 3);
    ctx.save(); ctx.translate(sx, sy); ctx.rotate(mon.angle);
    const g = ctx.createRadialGradient(0, 0, 0, 0, 0, r * 2.6 * pulse);
    g.addColorStop(0, 'rgba(255,20,60,0.35)'); g.addColorStop(1, 'transparent');
    ctx.beginPath(); ctx.arc(0, 0, r * 2.6 * pulse, 0, Math.PI * 2); ctx.fillStyle = g; ctx.fill();
    // Duas lâminas de foice em crescente, simétricas, saindo do núcleo —
    // silhueta clara de "foice" vista de cima, não mais um blob genérico.
    const drawBlade = (angOffset, flip) => {
      const n = 16;
      const outer = [], inner = [];
      for (let t = 0; t < n; t++) {
        const tt = t / (n - 1);
        const a = angOffset + flip * tt * 1.7;
        const rr = r * pulse * (0.35 + tt * 0.95);
        const w = r * pulse * 0.16 * Math.sin(tt * Math.PI);
        const nx = -Math.sin(a) * flip, ny = Math.cos(a) * flip;
        outer.push([Math.cos(a) * rr + nx * w, Math.sin(a) * rr + ny * w]);
        inner.push([Math.cos(a) * rr - nx * w * 0.4, Math.sin(a) * rr - ny * w * 0.4]);
      }
      ctx.beginPath();
      outer.forEach((p, i) => i === 0 ? ctx.moveTo(p[0], p[1]) : ctx.lineTo(p[0], p[1]));
      for (let i = inner.length - 1; i >= 0; i--) ctx.lineTo(inner[i][0], inner[i][1]);
      ctx.closePath();
      ctx.fillStyle = '#aa0a1c'; ctx.fill();
      ctx.strokeStyle = 'rgba(255,170,180,0.75)'; ctx.lineWidth = 1.2; ctx.stroke();
    };
    drawBlade(Math.PI * 0.15, 1);
    drawBlade(Math.PI * 1.15, -1);
    // núcleo central em diamante, aponta pra direção de movimento
    ctx.beginPath();
    ctx.moveTo(r * 0.55, 0); ctx.lineTo(r * 0.1, -r * 0.32); ctx.lineTo(-r * 0.35, 0); ctx.lineTo(r * 0.1, r * 0.32);
    ctx.closePath();
    ctx.fillStyle = '#28000a'; ctx.fill();
    ctx.strokeStyle = 'rgba(255,150,160,0.85)'; ctx.lineWidth = 1.3; ctx.stroke();
    ctx.beginPath(); ctx.arc(r * 0.15, 0, r * 0.11, 0, Math.PI * 2); ctx.fillStyle = '#fff'; ctx.fill();
    ctx.restore();
  },
  ghostlarva: function (mon, sx, sy, r) {
    // Visibilidade oscila — furtiva a maior parte do tempo
    const visibility = mon._stealthVis ?? 1;
    if (visibility < 0.05) return;
    ctx.save(); ctx.globalAlpha = visibility;
    ctx.translate(sx, sy); ctx.rotate(mon.angle);
    const g = ctx.createRadialGradient(0, 0, 0, 0, 0, r * 2.2);
    g.addColorStop(0, 'rgba(255,225,77,0.5)'); g.addColorStop(1, 'transparent');
    ctx.beginPath(); ctx.arc(0, 0, r * 2.2, 0, Math.PI * 2); ctx.fillStyle = g; ctx.fill();
    // Corpo alongado tipo "girino/espectro" — cauda ondulante atrás,
    // cabeça luminosa na frente. Mais fiel a "larva" que o losango anterior.
    const segs = 6;
    const top = [], bot = [];
    for (let i = 0; i < segs; i++) {
      const tt = i / (segs - 1);
      const px = -tt * r * 2.6;
      const py = Math.sin(tt * 6 + mon.phase * 4) * r * 0.25;
      const w = r * 0.55 * (1 - tt * 0.85);
      top.push([px, py - w]); bot.push([px, py + w]);
    }
    ctx.beginPath();
    top.forEach((p, i) => i === 0 ? ctx.moveTo(p[0], p[1]) : ctx.lineTo(p[0], p[1]));
    for (let i = bot.length - 1; i >= 0; i--) ctx.lineTo(bot[i][0], bot[i][1]);
    ctx.closePath();
    ctx.fillStyle = 'rgba(255,225,90,0.75)'; ctx.fill();
    ctx.strokeStyle = 'rgba(255,250,200,0.75)'; ctx.lineWidth = 1; ctx.stroke();
    // cabeça — bulbo brilhante à frente
    ctx.beginPath(); ctx.ellipse(0, 0, r * 0.7, r * 0.5, 0, 0, Math.PI * 2);
    ctx.fillStyle = 'rgba(255,240,150,0.9)'; ctx.fill();
    ctx.beginPath(); ctx.ellipse(r * 0.15, 0, r * 0.3, r * 0.2, 0, 0, Math.PI * 2);
    ctx.fillStyle = '#fffce6'; ctx.fill();
    ctx.restore();
  },
  unstablecore: function (mon, sx, sy, r) {
    const pulse = 1 + 0.25 * Math.sin(mon.phase * 6); // pulsa rápido — parece prestes a explodir
    ctx.save(); ctx.translate(sx, sy);
    const g = ctx.createRadialGradient(0, 0, 0, 0, 0, r * 3 * pulse);
    g.addColorStop(0, 'rgba(255,138,31,0.5)'); g.addColorStop(1, 'transparent');
    ctx.beginPath(); ctx.arc(0, 0, r * 3 * pulse, 0, Math.PI * 2); ctx.fillStyle = g; ctx.fill();
    ctx.beginPath(); ctx.arc(0, 0, r * pulse, 0, Math.PI * 2);
    const cg = ctx.createRadialGradient(0, 0, 0, 0, 0, r * pulse);
    cg.addColorStop(0, '#fff3d0'); cg.addColorStop(0.5, '#ff8a1f'); cg.addColorStop(1, '#5c1a00');
    ctx.fillStyle = cg; ctx.fill();
    // rachaduras ramificadas e irregulares — núcleo instável rachando de
    // verdade, não linhas retas simétricas.
    ctx.strokeStyle = 'rgba(60,10,0,0.85)'; ctx.lineWidth = 1.4;
    for (let i = 0; i < 6; i++) {
      let a = (i / 6) * Math.PI * 2 + mon.phase * 0.3;
      let x = 0, y = 0;
      for (let seg = 0; seg < 4; seg++) {
        const nx = x + Math.cos(a) * r * pulse * 0.28;
        const ny = y + Math.sin(a) * r * pulse * 0.28;
        ctx.beginPath(); ctx.moveTo(x, y); ctx.lineTo(nx, ny); ctx.stroke();
        x = nx; y = ny;
        a += Math.sin(mon.phase * 2 + i * 3 + seg) * 0.35;
      }
    }
    ctx.restore();
  },
};
Object.assign(COSMIC_MONSTER_DRAWERS, COSMIC_MONSTER_DRAWERS_EXT);

// ═══════════════════════════════════════════════════════════════════
//  MÓDULO: CRIATURAS DE BIOMA — fauna nativa territorial (ambientação)
// ═══════════════════════════════════════════════════════════════════
//  Pequenas formas de vida nativas de cada bioma cósmico, sem função de
//  gameplay (não dão recurso, não atacam) — só densidade e imersão
//  visual, como a fauna ambiente de Terraria/Minecraft. Nascem e vagam
//  livremente DENTRO do contorno do próprio bioma (nunca saem dele) e
//  desviam pacificamente quando uma nave da raça cósmica (dona daquele
//  bioma) passa perto. Cada raça tem seu próprio conjunto de espécies
//  temáticas com desenho e movimento distintos; o sistema é orientado a
//  dados (COSMIC_CRITTER_SPECIES por raceId), pra ser fácil estender
//  pras outras 4 raças depois de aprovado o padrão da Plasmícea.
// ═══════════════════════════════════════════════════════════════════

const COSMIC_CRITTER_MAX_PER_BIOME = 10; // teto por bioma individual (não global)
const COSMIC_CRITTER_FLEE_RANGE = 90;   // distância da nave em que a criatura começa a desviar
const COSMIC_CRITTER_FLEE_RANGE_SQ = COSMIC_CRITTER_FLEE_RANGE * COSMIC_CRITTER_FLEE_RANGE;
const COSMIC_CRITTER_DESPAWN_TIME = 6; // segundos fora da referência até remover (dá tempo do jogador ir e voltar sem perder a fauna toda)

// Espécies nativas da Nebulosa Incandara (Plasmícea) — todas no mesmo
// tema de plasma/fogo estelar, mas com silhueta e movimento próprios:
//   larva-solar   — pequena, orbita devagar em círculos preguiçosos.
//   peixe-chama   — nada em cardume ondulante, o mais numeroso.
//   faisca-vagante— partícula rápida e errática, tipo inseto de luz.
//   medusa-plasma — grande, lenta, pulsa como uma água-viva de fogo.
//
// Espécies nativas da Nebulosa Ossuária (Nécrida) — tema funéreo/
// decadente, cinza-arroxeado, sempre lento e "triste", nunca vivo ou
// vibrante como a Plasmícea:
//   vaga-lume-osseo — luz pálida pequena, flutua e pisca fraco.
//   verme-necrofago — rasteja serpenteando devagar, corpo segmentado.
//   corvo-eterio    — voa sozinho em círculos largos e preguiçosos.
//   sudario-errante — grande, tecido fantasmagórico ondulante à deriva.
const COSMIC_CRITTER_SPECIES = {
  plasmicea: [
    { id: 'larva-solar', weight: 3, baseSpeed: 10, baseR: 3.2, schooling: false },
    { id: 'peixe-chama', weight: 4, baseSpeed: 26, baseR: 3.6, schooling: true },
    { id: 'faisca-vagante', weight: 2, baseSpeed: 46, baseR: 2.0, schooling: false },
    { id: 'medusa-plasma', weight: 1, baseSpeed: 8, baseR: 7.5, schooling: false },
  ],
  necrida: [
    { id: 'vaga-lume-osseo', weight: 4, baseSpeed: 7, baseR: 2.4, schooling: false },
    { id: 'verme-necrofago', weight: 3, baseSpeed: 9, baseR: 4.2, schooling: false },
    { id: 'corvo-eterio', weight: 2, baseSpeed: 20, baseR: 3.4, schooling: false },
    { id: 'sudario-errante', weight: 1, baseSpeed: 6, baseR: 8.0, schooling: false },
  ],
};

let _cosmicCritters = [];
let _cosmicCritterIdCounter = 1;
let _cosmicCritterSpawnTimer = 0;
const COSMIC_CRITTER_SPAWN_INTERVAL = 0.8; // tenta popular biomas com essa cadência

function _cosmicPickCritterSpecies(list) {
  const total = list.reduce((s, sp) => s + sp.weight, 0);
  let roll = rand(0, total);
  for (const sp of list) {
    roll -= sp.weight;
    if (roll <= 0) return sp;
  }
  return list[list.length - 1];
}

// Sorteia um ponto dentro do bioma só que priorizando a região perto da
// câmera — sortear em qualquer lugar do bioma inteiro (raio até 1600)
// quase nunca cai na área visível da tela, já que o bioma é bem maior
// que o viewport. Tenta primeiro pontos próximos da câmera (dentro do
// bioma); se a câmera estiver fora do bioma, cai para um ponto qualquer
// dentro dele (a entidade continua existindo, só não nasce já visível).
// Usada tanto pelo spawn de naves cósmicas (_cosmicSpawnOne) quanto
// pela fauna de bioma.
function _cosmicRollPosNearCameraInBiome(biome) {
  if (typeof cam !== 'undefined' && typeof canvas !== 'undefined') {
    const viewHalfW = (canvas.width * 0.5) / Math.max(0.05, cam.zoom);
    const viewHalfH = (canvas.height * 0.5) / Math.max(0.05, cam.zoom);
    for (let tries = 0; tries < 14; tries++) {
      const x = cam.x + rand(-viewHalfW * 1.3, viewHalfW * 1.3);
      const y = cam.y + rand(-viewHalfH * 1.3, viewHalfH * 1.3);
      if (_cosmicPointInBiome(biome, x, y)) return { x, y };
    }
  }
  // Câmera longe do bioma (ou câmera indisponível): fauna nasce em
  // algum ponto do bioma mesmo assim, só não necessariamente visível.
  return _cosmicRollPosInBiome(biome);
}

function _cosmicSpawnCritterInBiome(biome, species) {
  const pos = _cosmicRollPosNearCameraInBiome(biome);
  _cosmicCritters.push({
    id: 'critter_' + (_cosmicCritterIdCounter++),
    speciesId: species.id,
    raceId: biome.raceId,
    biomeId: biome.id,
    x: pos.x, y: pos.y,
    angle: rand(0, Math.PI * 2),
    _angleVel: 0,
    _vx: 0, _vy: 0,
    wanderTarget: null,
    phase: rand(0, Math.PI * 2),
    scale: rand(0.8, 1.3),
    spawnT: 0,
  });
}

// Mantém cada bioma populado até o teto, sorteando espécies pelo peso
// de cada raça — chamado periodicamente, não todo frame. Spawna até 2
// por chamada (não só 1) pra encher o teto num ritmo perceptível assim
// que o jogador entra num bioma, em vez de só uma criatura a cada ~1s.
const COSMIC_CRITTER_SPAWN_BATCH = 2;

function _cosmicPopulateCritters() {
  if (typeof _cosmicBiomes === 'undefined' || !_cosmicBiomes.length) return;
  _cosmicBiomes.forEach(biome => {
    const species = COSMIC_CRITTER_SPECIES[biome.raceId];
    if (!species || !species.length) return; // raça ainda sem fauna definida
    let countInBiome = _cosmicCritters.reduce((n, c) => n + (c.biomeId === biome.id ? 1 : 0), 0);
    let spawned = 0;
    while (countInBiome < COSMIC_CRITTER_MAX_PER_BIOME && spawned < COSMIC_CRITTER_SPAWN_BATCH) {
      _cosmicSpawnCritterInBiome(biome, _cosmicPickCritterSpecies(species));
      countInBiome++;
      spawned++;
    }
  });
}

function cosmicCrittersUpdate(dt) {
  _cosmicCritterSpawnTimer += dt;
  if (_cosmicCritterSpawnTimer >= COSMIC_CRITTER_SPAWN_INTERVAL) {
    _cosmicCritterSpawnTimer = 0;
    _cosmicPopulateCritters();
  }

  for (let i = _cosmicCritters.length - 1; i >= 0; i--) {
    const c = _cosmicCritters[i];
    const biome = _cosmicBiomeById(c.biomeId);
    // Bioma sumiu (não deveria acontecer em uso normal, mas por
    // segurança) — remove a criatura órfã.
    if (!biome) { _cosmicCritters.splice(i, 1); continue; }

    // Despawna criaturas que ficam muito tempo fora da área de
    // referência da câmera — sem isso, o teto por bioma
    // (COSMIC_CRITTER_MAX_PER_BIOME) fica ocupado por criaturas presas
    // longe de onde o jogador está agora, e novas nunca nascem perto o
    // bastante pra serem vistas. Usa uma tolerância (COSMIC_CRITTER_
    // DESPAWN_TIME) em vez de remover na hora, pra um desvio rápido de
    // câmera não esvaziar o bioma inteiro de uma vez.
    if (_cosmicIsOutsideRef(c)) {
      c._offscreenT = (c._offscreenT || 0) + dt;
      if (c._offscreenT >= COSMIC_CRITTER_DESPAWN_TIME) { _cosmicCritters.splice(i, 1); continue; }
    } else {
      c._offscreenT = 0;
    }

    c.phase += dt;
    c.spawnT += dt;

    // Desvio pacífico: se alguma nave da MESMA raça dona do bioma está
    // perto, foge dela em vez de seguir o wander normal deste frame.
    let fleeVx = 0, fleeVy = 0, fleeing = false;
    for (let j = 0; j < _cosmicEntities.length; j++) {
      const ent = _cosmicEntities[j];
      if (ent.raceId !== c.raceId) continue;
      const dx = c.x - ent.x, dy = c.y - ent.y;
      const dSq = dx * dx + dy * dy;
      if (dSq < COSMIC_CRITTER_FLEE_RANGE_SQ) {
        const d = Math.sqrt(dSq) || 1;
        // Quanto mais perto a nave, mais forte o impulso de fuga.
        const strength = 1 - (d / COSMIC_CRITTER_FLEE_RANGE);
        fleeVx += (dx / d) * strength;
        fleeVy += (dy / d) * strength;
        fleeing = true;
      }
    }

    if (fleeing) {
      const fleeAngle = Math.atan2(fleeVy, fleeVx);
      _cosmicSteerAngle(c, dt, fleeAngle, 5, 4);
      const spd = _cosmicCritterSpeciesSpeed(c) * 2.2; // foge mais rápido que o wander normal
      _cosmicSteerVelocity(c, dt, Math.cos(c.angle) * spd, Math.sin(c.angle) * spd, 5);
      c.wanderTarget = null; // recalcula um novo destino de vagar após a fuga
    } else {
      _cosmicCritterWander(c, biome, dt);
    }

    // Nunca deixa a criatura escapar do contorno do bioma — se o
    // movimento (inclusive de fuga) a levou pra fora, empurra de volta
    // suavemente com a mesma camada de inércia, sem teleporte.
    if (!_cosmicPointInBiome(biome, c.x, c.y)) {
      const backAngle = Math.atan2(biome.y - c.y, biome.x - c.x);
      _cosmicSteerAngle(c, dt, backAngle, 6, 5);
      const spd = _cosmicCritterSpeciesSpeed(c) * 1.6;
      _cosmicSteerVelocity(c, dt, Math.cos(c.angle) * spd, Math.sin(c.angle) * spd, 5);
    }
  }
}

function _cosmicCritterSpeciesSpeed(c) {
  const list = COSMIC_CRITTER_SPECIES[c.raceId];
  const sp = list && list.find(s => s.id === c.speciesId);
  return sp ? sp.baseSpeed : 16;
}

// Vagar tranquilo dentro do bioma: pontos aleatórios internos, exceto
// peixe-chama, que segue um leve impulso de coesão de cardume (nada
// junto de outros peixe-chama próximos, tipo boid simplificado).
function _cosmicCritterWander(c, biome, dt) {
  const spd = _cosmicCritterSpeciesSpeed(c);

  if (c.speciesId === 'peixe-chama') {
    let cohX = 0, cohY = 0, count = 0;
    for (let j = 0; j < _cosmicCritters.length; j++) {
      const other = _cosmicCritters[j];
      if (other === c || other.speciesId !== 'peixe-chama' || other.biomeId !== c.biomeId) continue;
      const d = Math.hypot(other.x - c.x, other.y - c.y);
      if (d < 140) { cohX += other.x; cohY += other.y; count++; }
    }
    if (count > 0) {
      cohX /= count; cohY /= count;
      const dx = cohX - c.x, dy = cohY - c.y;
      const d = Math.hypot(dx, dy) || 1;
      const targetAngle = Math.atan2(dy, dx);
      _cosmicSteerAngle(c, dt, targetAngle, 2, 1.8);
      _cosmicSteerVelocity(c, dt, (dx / d) * spd, (dy / d) * spd, 2);
      return;
    }
  }

  if (c.speciesId === 'faisca-vagante') {
    // Movimento errático tipo inseto de luz: sem alvo fixo, muda de
    // direção com frequência via spin livre mais agressivo.
    _cosmicFreeSpin(c, dt, 2.2);
    _cosmicSteerVelocity(c, dt, Math.cos(c.angle) * spd, Math.sin(c.angle) * spd, 3.2);
    return;
  }

  if (c.speciesId === 'medusa-plasma') {
    // Grande e lenta, "pulsa" no lugar com deslocamento mínimo.
    if (!c.wanderTarget || Math.hypot(c.wanderTarget.x - c.x, c.wanderTarget.y - c.y) < 20) {
      c.wanderTarget = _cosmicRollPosInBiome(biome);
    }
    const dx = c.wanderTarget.x - c.x, dy = c.wanderTarget.y - c.y;
    const d = Math.hypot(dx, dy) || 1;
    const targetAngle = Math.atan2(dy, dx);
    _cosmicSteerAngle(c, dt, targetAngle, 1.5, 1.2);
    _cosmicSteerVelocity(c, dt, (dx / d) * spd, (dy / d) * spd, 1.5);
    return;
  }

  if (c.speciesId === 'larva-solar') {
    // Órbita preguiçosa ao redor do próprio ponto de nascimento, sem
    // host — puro comportamento decorativo.
    if (!c.wanderTarget) c.wanderTarget = { x: c.x, y: c.y };
    const orbR = 30 * c.scale;
    const targetX = c.wanderTarget.x + Math.cos(c.phase * 0.5) * orbR;
    const targetY = c.wanderTarget.y + Math.sin(c.phase * 0.5) * orbR;
    const dx = targetX - c.x, dy = targetY - c.y;
    const d = Math.hypot(dx, dy) || 1;
    const targetAngle = Math.atan2(dy, dx);
    _cosmicSteerAngle(c, dt, targetAngle, 2.5, 2);
    _cosmicSteerVelocity(c, dt, (dx / d) * spd, (dy / d) * spd, 2.5);
    return;
  }

  if (c.speciesId === 'vaga-lume-osseo') {
    // Flutua devagar e erraticamente, quase parado — pequena luz pálida
    // à deriva, sem pressa nenhuma (spin bem mais fraco que a faísca).
    _cosmicFreeSpin(c, dt, 0.6);
    _cosmicSteerVelocity(c, dt, Math.cos(c.angle) * spd, Math.sin(c.angle) * spd, 1.6);
    return;
  }

  if (c.speciesId === 'verme-necrofago') {
    // Rasteja: vai devagar até um ponto próximo dentro do bioma e para
    // por um instante antes de escolher outro — nunca em linha reta
    // contínua como as outras, movimento mais "arrastado".
    c._crawlPauseT = c._crawlPauseT || 0;
    if (c._crawlPauseT > 0) {
      c._crawlPauseT -= dt;
      _cosmicSteerVelocity(c, dt, 0, 0, 2);
      return;
    }
    if (!c.wanderTarget || Math.hypot(c.wanderTarget.x - c.x, c.wanderTarget.y - c.y) < 15) {
      c.wanderTarget = _cosmicRollPosInBiome(biome);
      if (Math.random() < 0.4) c._crawlPauseT = rand(1, 3);
    }
    const dx = c.wanderTarget.x - c.x, dy = c.wanderTarget.y - c.y;
    const d = Math.hypot(dx, dy) || 1;
    const targetAngle = Math.atan2(dy, dx);
    _cosmicSteerAngle(c, dt, targetAngle, 1.8, 1.4);
    _cosmicSteerVelocity(c, dt, (dx / d) * spd, (dy / d) * spd, 1.8);
    return;
  }

  if (c.speciesId === 'corvo-eterio') {
    // Voa sozinho em círculos largos e preguiçosos ao redor de um
    // centro próprio — silhueta solitária cruzando o bioma no alto.
    if (!c.wanderTarget) c.wanderTarget = { x: c.x, y: c.y };
    const orbR = 90 * c.scale;
    const targetX = c.wanderTarget.x + Math.cos(c.phase * 0.22) * orbR;
    const targetY = c.wanderTarget.y + Math.sin(c.phase * 0.22) * orbR;
    const dx = targetX - c.x, dy = targetY - c.y;
    const d = Math.hypot(dx, dy) || 1;
    const targetAngle = Math.atan2(dy, dx);
    _cosmicSteerAngle(c, dt, targetAngle, 2, 1.6);
    _cosmicSteerVelocity(c, dt, (dx / d) * spd, (dy / d) * spd, 2);
    return;
  }

  // sudario-errante (padrão da Nécrida): à deriva bem lenta, quase sem
  // direção própria, como um tecido fantasmagórico boiando no vazio.
  _cosmicFreeSpin(c, dt, 0.35);
  _cosmicSteerVelocity(c, dt, Math.cos(c.angle) * spd, Math.sin(c.angle) * spd, 1.2);
}

// ── Desenho — fauna da Plasmícea (Nebulosa Incandara) ────────────────
// Mesma paleta laranja/vermelho-fogo da nave Plasmícea, silhuetas bem
// menores e simples — sem shadowBlur, sem gradiente novo além do
// estritamente necessário para leitura de "criatura de plasma".
function _cosmicDrawLarvaSolar(c, sx, sy, zoom) {
  const r = Math.max(1.5, c.scale * 3.2 * zoom);
  const pulse = 1 + Math.sin(c.phase * 3) * 0.2;
  ctx.save();
  ctx.beginPath();
  ctx.arc(sx, sy, r * pulse, 0, Math.PI * 2);
  ctx.fillStyle = 'rgba(255,150,60,0.85)';
  ctx.fill();
  ctx.beginPath();
  ctx.arc(sx, sy, r * 0.5, 0, Math.PI * 2);
  ctx.fillStyle = 'rgba(255,235,180,0.9)';
  ctx.fill();
  ctx.restore();
}

function _cosmicDrawPeixeChama(c, sx, sy, zoom) {
  const r = Math.max(1.8, c.scale * 3.6 * zoom);
  ctx.save();
  ctx.translate(sx, sy);
  ctx.rotate(c.angle);
  const tailWag = Math.sin(c.phase * 8) * 0.35;
  ctx.beginPath();
  ctx.moveTo(r * 1.4, 0);
  ctx.lineTo(-r * 0.6, -r * 0.7);
  ctx.lineTo(-r * 1.6, -r * 0.9 * tailWag - r * 0.2);
  ctx.lineTo(-r * 0.9, 0);
  ctx.lineTo(-r * 1.6, r * 0.9 * tailWag + r * 0.2);
  ctx.lineTo(-r * 0.6, r * 0.7);
  ctx.closePath();
  ctx.fillStyle = 'rgba(255,110,40,0.8)';
  ctx.fill();
  ctx.strokeStyle = 'rgba(255,210,140,0.7)';
  ctx.lineWidth = Math.max(0.5, r * 0.1);
  ctx.stroke();
  ctx.restore();
}

function _cosmicDrawFaiscaVagante(c, sx, sy, zoom) {
  const r = Math.max(1, c.scale * 2 * zoom);
  const flick = 0.6 + 0.4 * Math.sin(c.phase * 10);
  ctx.save();
  const g = ctx.createRadialGradient(sx, sy, 0, sx, sy, r * 3);
  g.addColorStop(0, `rgba(255,240,180,${0.8 * flick})`);
  g.addColorStop(1, 'rgba(255,150,60,0)');
  ctx.beginPath();
  ctx.arc(sx, sy, r * 3, 0, Math.PI * 2);
  ctx.fillStyle = g;
  ctx.fill();
  ctx.beginPath();
  ctx.arc(sx, sy, r * 0.6, 0, Math.PI * 2);
  ctx.fillStyle = `rgba(255,255,220,${flick})`;
  ctx.fill();
  ctx.restore();
}

function _cosmicDrawMedusaPlasma(c, sx, sy, zoom) {
  const r = Math.max(3, c.scale * 7.5 * zoom);
  const pulse = 1 + Math.sin(c.phase * 1.6) * 0.15;
  ctx.save();
  ctx.translate(sx, sy);
  ctx.beginPath();
  ctx.arc(0, 0, r * pulse, Math.PI, 0);
  ctx.closePath();
  const g = ctx.createRadialGradient(0, -r * 0.2, 0, 0, 0, r * 1.2);
  g.addColorStop(0, 'rgba(255,200,120,0.55)');
  g.addColorStop(1, 'rgba(255,90,30,0.25)');
  ctx.fillStyle = g;
  ctx.fill();
  ctx.strokeStyle = 'rgba(255,180,100,0.5)';
  ctx.lineWidth = Math.max(0.6, r * 0.08);
  ctx.stroke();
  const tentCount = 4;
  for (let i = 0; i < tentCount; i++) {
    const baseX = -r * 0.6 + (i / (tentCount - 1)) * r * 1.2;
    const wag = Math.sin(c.phase * 2.4 + i) * r * 0.35;
    ctx.beginPath();
    ctx.moveTo(baseX, 0);
    ctx.quadraticCurveTo(baseX + wag * 0.5, r * 0.9, baseX + wag, r * 1.7);
    ctx.strokeStyle = 'rgba(255,140,60,0.45)';
    ctx.lineWidth = Math.max(0.6, r * 0.07);
    ctx.stroke();
  }
  ctx.restore();
}

// ── Desenho — fauna da Nécrida (Nebulosa Ossuária) ───────────────────
// Paleta cinza-arroxeada funérea (mesma família de cor da nave Nécrida:
// roxo apagado, cinza-ósseo), sempre discreta e "triste" — nunca cores
// vivas ou saturadas como a Plasmícea.
function _cosmicDrawVagaLumeOsseo(c, sx, sy, zoom) {
  const r = Math.max(1.3, c.scale * 2.4 * zoom);
  const flick = 0.35 + 0.3 * Math.sin(c.phase * 1.4);
  ctx.save();
  const g = ctx.createRadialGradient(sx, sy, 0, sx, sy, r * 2.6);
  g.addColorStop(0, `rgba(200,190,210,${0.55 * flick})`);
  g.addColorStop(1, 'rgba(140,110,160,0)');
  ctx.beginPath();
  ctx.arc(sx, sy, r * 2.6, 0, Math.PI * 2);
  ctx.fillStyle = g;
  ctx.fill();
  ctx.beginPath();
  ctx.arc(sx, sy, r * 0.5, 0, Math.PI * 2);
  ctx.fillStyle = `rgba(220,215,230,${0.5 + flick * 0.4})`;
  ctx.fill();
  ctx.restore();
}

function _cosmicDrawVermeNecrofago(c, sx, sy, zoom) {
  const r = Math.max(1.6, c.scale * 4.2 * zoom);
  ctx.save();
  ctx.translate(sx, sy);
  ctx.rotate(c.angle);
  // Corpo segmentado — série de círculos decrescentes, movimento de
  // "rastejar" sugerido pela leve ondulação lateral de cada segmento.
  const segCount = 5;
  for (let i = 0; i < segCount; i++) {
    const t = i / (segCount - 1);
    const segR = r * (0.5 - t * 0.32);
    const wob = Math.sin(c.phase * 3 - i * 0.8) * r * 0.12;
    const segX = -t * r * 1.6;
    ctx.beginPath();
    ctx.arc(segX, wob, Math.max(0.6, segR), 0, Math.PI * 2);
    ctx.fillStyle = i === 0 ? 'rgba(150,120,140,0.85)' : 'rgba(95,80,100,0.8)';
    ctx.fill();
  }
  ctx.restore();
}

function _cosmicDrawCorvoEterio(c, sx, sy, zoom) {
  const r = Math.max(1.8, c.scale * 3.4 * zoom);
  const flap = Math.sin(c.phase * 4) * 0.5;
  ctx.save();
  ctx.translate(sx, sy);
  ctx.rotate(c.angle);
  // Silhueta simples de ave em V, asas batendo devagar.
  ctx.beginPath();
  ctx.moveTo(0, 0);
  ctx.lineTo(-r * 1.3, -r * (0.7 + flap * 0.5));
  ctx.lineTo(-r * 0.6, -r * 0.15);
  ctx.lineTo(-r * 1.3, r * (0.7 - flap * 0.5));
  ctx.closePath();
  ctx.fillStyle = 'rgba(60,55,68,0.85)';
  ctx.fill();
  ctx.restore();
}

function _cosmicDrawSudarioErrante(c, sx, sy, zoom) {
  const r = Math.max(3.2, c.scale * 8 * zoom);
  ctx.save();
  ctx.translate(sx, sy);
  // Tecido ondulante — forma alongada com borda irregular via
  // quadraticCurveTo, balançando lento como um pano boiando no vazio.
  ctx.beginPath();
  const waveA = Math.sin(c.phase * 0.8) * r * 0.25;
  const waveB = Math.sin(c.phase * 0.8 + 1.4) * r * 0.25;
  ctx.moveTo(-r * 1.4, -r * 0.3);
  ctx.quadraticCurveTo(-r * 0.3, -r * 0.6 + waveA, r * 1.3, -r * 0.25);
  ctx.quadraticCurveTo(r * 0.9, r * 0.1, r * 1.1, r * 0.5 + waveB);
  ctx.quadraticCurveTo(0, r * 0.75, -r * 1.4, r * 0.35);
  ctx.closePath();
  const g = ctx.createLinearGradient(-r * 1.4, 0, r * 1.3, 0);
  g.addColorStop(0, 'rgba(70,62,84,0.55)');
  g.addColorStop(0.5, 'rgba(110,95,128,0.4)');
  g.addColorStop(1, 'rgba(70,62,84,0.2)');
  ctx.fillStyle = g;
  ctx.fill();
  ctx.strokeStyle = 'rgba(190,180,205,0.3)';
  ctx.lineWidth = Math.max(0.5, r * 0.05);
  ctx.stroke();
  ctx.restore();
}

const COSMIC_CRITTER_DRAWERS = {
  'larva-solar': _cosmicDrawLarvaSolar,
  'peixe-chama': _cosmicDrawPeixeChama,
  'faisca-vagante': _cosmicDrawFaiscaVagante,
  'medusa-plasma': _cosmicDrawMedusaPlasma,
  'vaga-lume-osseo': _cosmicDrawVagaLumeOsseo,
  'verme-necrofago': _cosmicDrawVermeNecrofago,
  'corvo-eterio': _cosmicDrawCorvoEterio,
  'sudario-errante': _cosmicDrawSudarioErrante,
};

function cosmicCrittersDraw(ctx) {
  for (let i = 0; i < _cosmicCritters.length; i++) {
    const c = _cosmicCritters[i];
    const sx = (c.x - cam.x) * cam.zoom + canvas.width * 0.5;
    const sy = (c.y - cam.y) * cam.zoom + canvas.height * 0.5;
    if (sx < -40 || sx > canvas.width + 40 || sy < -40 || sy > canvas.height + 40) continue;

    const drawer = COSMIC_CRITTER_DRAWERS[c.speciesId];
    if (!drawer) continue;

    const entranceFade = Math.min(1, c.spawnT / 1.2);
    ctx.save();
    ctx.globalAlpha = entranceFade;
    drawer(c, sx, sy, cam.zoom);
    ctx.restore();
  }
}

function cosmicCrittersReset() {
  _cosmicCritters = [];
  _cosmicCritterSpawnTimer = 0;
}

// ═══════════════════════════════════════════════════════════════════
//  MÓDULO: BIOMAS CÓSMICOS — territórios das raças
// ═══════════════════════════════════════════════════════════════════
//  Cada bioma é uma região territorial fixa (não um "borrão" de
//  nebulosa comum): tem contorno orgânico irregular próprio, cor e
//  nome exclusivos, e nasce já com alguns astros "colonizados" pela
//  raça dona do território dentro dela. As entidades daquela raça
//  preferem nascer e permanecer dentro do bioma correspondente.
// ═══════════════════════════════════════════════════════════════════

const COSMIC_BIOME_DEFS = {
  plasmicea: {
    name: 'Nebulosa Incandara', color: 'rgba(255,130,40,0.10)', edge: 'rgba(255,150,60,0.35)',
    // Fendas de magma incandescente saindo da borda + faíscas flutuantes.
    veinColor: 'rgba(255,140,50,0.55)', glowColors: ['#ff8a3d', '#ffd23d', '#ff3d3d'],
  },
  fungica: {
    name: 'Nebulosa Miceliar', color: 'rgba(200,90,230,0.10)', edge: 'rgba(230,110,220,0.32)',
    // Veias miceliais na borda + cogumelos bioluminescentes rosa/azul/roxo.
    veinColor: 'rgba(210,110,255,0.6)', glowColors: ['#ff5fd1', '#5fd7ff', '#b05fff'],
  },
  necrida: {
    name: 'Nebulosa Ossuária', color: 'rgba(100,100,115,0.10)', edge: 'rgba(120,120,135,0.30)',
    // Rachaduras ósseas esbranquiçadas + lampejos pálidos e frios.
    veinColor: 'rgba(190,190,205,0.4)', glowColors: ['#c9c9d8', '#8fa0b5', '#e8e8f0'],
  },
  viscera: {
    name: 'Nebulosa Sanguária', color: 'rgba(210,50,80,0.10)', edge: 'rgba(220,60,90,0.32)',
    // Veias pulsantes vermelho-vivas + pústulas bioluminescentes.
    veinColor: 'rgba(255,70,100,0.55)', glowColors: ['#ff3d5f', '#ff8a3d', '#c9257a'],
  },
  robotica: {
    name: 'Nebulosa Ferrolume', color: 'rgba(90,190,255,0.10)', edge: 'rgba(120,210,255,0.32)',
    // Circuitos de energia geométricos na borda + luzes de terminal azul/ciano.
    veinColor: 'rgba(140,220,255,0.55)', glowColors: ['#7fd7ff', '#3dfff0', '#5f9fff'],
  },
};

const COSMIC_BIOME_MIN_RADIUS = 900;
const COSMIC_BIOME_MAX_RADIUS = 1600;
const COSMIC_BIOME_TARGET_COUNT = 5; // um bioma por raça, no máximo, por vez
const COSMIC_BIOME_MIN_SEPARATION = 2600; // distância mínima entre centros de biomas

let _cosmicBiomes = [];
let _cosmicBiomesInited = false;

// Gera um contorno orgânico (não-circular) para o bioma, usando ruído
// simples em N pontos ao redor de um centro — evita o visual de
// "borrão" redondo idêntico ao das Nebulosas comuns do jogo.
function _cosmicMakeBiomeShape(radius) {
  const points = 10 + Math.floor(rand(0, 5));
  const shape = [];
  for (let i = 0; i < points; i++) {
    const a = (i / points) * Math.PI * 2;
    const wobble = 0.65 + rand(0, 0.55); // 0.65–1.2x do raio, formato irregular
    shape.push({ a, r: radius * wobble });
  }
  return shape;
}

function _cosmicInitBiomes() {
  if (_cosmicBiomesInited) return;
  _cosmicBiomesInited = true;
  const raceIds = COSMIC_RACE_IDS.slice();
  for (let i = 0; i < raceIds.length && i < COSMIC_BIOME_TARGET_COUNT; i++) {
    _cosmicSpawnBiome(raceIds[i]);
  }
}

const COSMIC_BIOME_PLAYER_CLEARANCE = 1400; // distância mínima de qualquer astro do jogador
const COSMIC_BIOME_NATIVE_TYPES = ['star', 'moon', 'planet', 'blackhole']; // tipos-base usados para povoar biomas vazios
const COSMIC_BIOME_NATIVE_MIN = 4;
const COSMIC_BIOME_NATIVE_MAX = 8;

// Verifica se um centro candidato está livre o bastante de astros já
// existentes no universo (colocados pelo jogador ou por outros sistemas),
// para o bioma não nascer "em cima" de algo que já está lá.
function _cosmicBiomeSiteIsClear(cx, cy, radius) {
  if (typeof objects === 'undefined' || !objects.length) return true;
  const clearance = radius + COSMIC_BIOME_PLAYER_CLEARANCE;
  return objects.every(o => o.dead || Math.hypot(o.x - cx, o.y - cy) >= clearance);
}

// Gera "veias" saindo da borda do bioma — pequenos ramos orgânicos
// (ou, na Robótica, segmentos retos de circuito) que crescem pra fora
// do contorno em pontos aleatórios, reforçando a sensação de fronteira
// viva/barreira em vez de um simples traço de contorno.
function _cosmicMakeBiomeVeins(biome) {
  const veins = [];
  const count = 14 + Math.floor(rand(0, 10));
  const isRobotica = biome.raceId === 'robotica';
  for (let i = 0; i < count; i++) {
    const a = rand(0, Math.PI * 2);
    // Usa o mesmo perfil de "wobble" do contorno pra a veia nascer
    // exatamente em cima da borda irregular, não num círculo perfeito.
    const shapeR = _cosmicRadiusAtAngle(biome, a);
    const len = shapeR * rand(0.12, 0.32);
    const branches = [];
    const branchCount = isRobotica ? 1 : (1 + Math.floor(rand(0, 3)));
    for (let b = 0; b < branchCount; b++) {
      branches.push({
        aOff: isRobotica ? 0 : rand(-0.5, 0.5),
        lenMul: rand(0.4, 0.85),
        atPos: rand(0.3, 0.85), // onde ao longo da veia principal o galho nasce
      });
    }
    veins.push({
      a, len, branches,
      jitter: isRobotica ? 0 : rand(0.15, 0.4), // curvatura orgânica (0 = reta, p/ circuitos)
      pulseOffset: rand(0, Math.PI * 2),
      segments: isRobotica ? (2 + Math.floor(rand(0, 3))) : 0, // circuitos: nº de "cotovelos" retos
    });
  }
  return veins;
}

// Elementos decorativos espalhados no INTERIOR do bioma — cogumelos
// bioluminescentes (Fúngica), pústulas pulsantes (Víscera), rachaduras
// ósseas (Nécrida), fendas de magma (Plasmícea) ou nós de circuito
// (Robótica). Todos compartilham a mesma estrutura de dados básica
// (posição relativa ao centro, tamanho, cor, fase de pulso) e cada
// raça só muda como são desenhados.
function _cosmicMakeBiomeDecor(biome) {
  const decor = [];
  const count = 22 + Math.floor(rand(0, 14));
  const colors = biome.glowColors || ['#ffffff'];
  for (let i = 0; i < count; i++) {
    // Distribuição concentrada mais perto do centro (raiz quadrada),
    // evitando aglomeração exagerada bem na borda onde já tem veias.
    const a = rand(0, Math.PI * 2);
    const rr = Math.sqrt(rand(0, 1)) * 0.72;
    const shapeR = _cosmicRadiusAtAngle(biome, a);
    decor.push({
      ox: Math.cos(a) * shapeR * rr,
      oy: Math.sin(a) * shapeR * rr,
      scale: rand(0.5, 1.35),
      color: colors[Math.floor(rand(0, colors.length))],
      pulsePhase: rand(0, Math.PI * 2),
      pulseSpeed: rand(0.6, 1.4),
      rot: rand(0, Math.PI * 2),
      variant: Math.floor(rand(0, 3)), // pequena variação de forma dentro do mesmo tema
    });
  }
  return decor;
}

// Raio do contorno irregular do bioma numa direção angular arbitrária,
// interpolando entre os dois pontos do shape mais próximos — usado
// pra nascer veias/decorações exatamente rente à borda real (que não é
// um círculo perfeito).
function _cosmicRadiusAtAngle(biome, angle) {
  const shape = biome.shape;
  const n = shape.length;
  let a = angle % (Math.PI * 2);
  if (a < 0) a += Math.PI * 2;
  for (let i = 0; i < n; i++) {
    const p0 = shape[i], p1 = shape[(i + 1) % n];
    let a0 = p0.a, a1 = p1.a;
    if (a1 < a0) a1 += Math.PI * 2;
    let aa = a;
    if (aa < a0) aa += Math.PI * 2;
    if (aa >= a0 && aa <= a1) {
      const t = (a1 === a0) ? 0 : (aa - a0) / (a1 - a0);
      return p0.r + (p1.r - p0.r) * t;
    }
  }
  return biome.radius;
}

const COSMIC_BIOME_ROCKS_MIN = 3;
const COSMIC_BIOME_ROCKS_MAX = 5;

// Povoa o bioma com seu próprio estoque de rochas espaciais, usando o
// pool de minérios EXCLUSIVO da raça dona (COSMIC_BIOME_MINERAL_TIERS).
// Essas rochas não contam para o teto global COSMIC_ROCKS_MAX_TOTAL nem
// dependem de chunk — nascem de uma vez, espalhadas dentro do território
// do bioma, e seguem as mesmas regras de descoberta/coleta por Sonda.
function _cosmicPopulateBiomeRocks(biome) {
  const count = Math.floor(rand(COSMIC_BIOME_ROCKS_MIN, COSMIC_BIOME_ROCKS_MAX + 1));
  let placed = 0, tries = 0;
  while (placed < count && tries < count * 12) {
    tries++;
    const a = rand(0, Math.PI * 2);
    const rr = Math.sqrt(rand(0, 1)) * 0.88;
    const shapeR = _cosmicRadiusAtAngle(biome, a);
    const x = biome.x + Math.cos(a) * shapeR * rr;
    const y = biome.y + Math.sin(a) * shapeR * rr;
    const tooClose = _cosmicRocks.some(r => Math.hypot(r.x - x, r.y - y) < COSMIC_ROCK_MIN_SEPARATION * 0.6);
    if (tooClose) continue;
    _cosmicSpawnRock(x, y, biome.id);
    placed++;
  }
}

function _cosmicSpawnBiome(raceId) {
  const def = COSMIC_BIOME_DEFS[raceId];
  if (!def) return null;
  const radius = rand(COSMIC_BIOME_MIN_RADIUS, COSMIC_BIOME_MAX_RADIUS);
  let cx, cy, tries = 0, ok = false;
  do {
    cx = rand(-6000, 6000);
    cy = rand(-6000, 6000);
    ok = _cosmicBiomes.every(b => Math.hypot(b.x - cx, b.y - cy) >= COSMIC_BIOME_MIN_SEPARATION)
      && _cosmicBiomeSiteIsClear(cx, cy, radius);
    tries++;
  } while (!ok && tries < 40);

  const biome = {
    id: 'biome_' + raceId + '_' + Date.now(),
    raceId,
    name: def.name,
    color: def.color,
    edge: def.edge,
    veinColor: def.veinColor,
    glowColors: def.glowColors,
    x: cx, y: cy,
    radius,
    shape: _cosmicMakeBiomeShape(radius),
    phase: rand(0, Math.PI * 2),
    // ── Fundação do sistema de Bosses Adormecidos ──
    // Índice de Perturbação: sobe com a atividade do jogador dentro
    // deste bioma (minerar rochas nativas, permanecer no território).
    // Combinado com o nível da Sonda Global, decide quando a
    // nave-relíquia do próximo boss da fila deste bioma aparece.
    // Ver COSMIC_BOSS_TRIGGER e cosmicPerturbationUpdate().
    perturbation: 0,
    bossQueueIndex: 0,  // próximo boss da fila deste bioma ainda não liberado
    relicSpawned: false, // já existe uma relíquia pendente pra este bioma?
  };
  biome.veins = _cosmicMakeBiomeVeins(biome);
  biome.decor = _cosmicMakeBiomeDecor(biome);
  _cosmicBiomes.push(biome);

  // Todo bioma nasce com seu próprio estoque de rochas espaciais,
  // carregando minérios exclusivos temáticos da raça dona.
  _cosmicPopulateBiomeRocks(biome);

  // Coloniza astros existentes que já estejam dentro do bioma, se
  // compatíveis com o hostType da raça (astros "colonizados" ganham
  // uma flag visual leve, sem alterar sua lógica original).
  const race = COSMIC_RACES[raceId];
  let colonizedCount = 0;
  if (race && race.hostTypes.length && typeof objects !== 'undefined') {
    objects.forEach(o => {
      if (o.dead) return;
      if (!race.hostTypes.includes((o.type || '').toLowerCase())) return;
      if (Math.hypot(o.x - cx, o.y - cy) <= radius) {
        o._cosmicColonizedBy = raceId;
        colonizedCount++;
      }
    });
  }

  // Bioma nasceu numa área vazia (sem astros suficientes pra colonizar):
  // gera astros próprios dentro do território pra ele não ficar "oco".
  if (colonizedCount < COSMIC_BIOME_NATIVE_MIN) {
    _cosmicPopulateBiome(biome, race);
  }

  return biome;
}

// Preenche um bioma recém-criado com astros nativos (estrela, planeta,
// lua, buraco negro), priorizando os hostTypes da própria raça quando
// ela tiver algum definido. Astros nascem já marcados como colonizados
// pela raça dona do bioma.
// Cria um mini-sistema temático completo dentro do bioma: 1 estrela
// central + de 1 a 3 planetas orbitando ela + ao menos 1 lua orbitando
// um desses planetas. Usado como "âncora" de cada bioma povoado, pra
// ele sempre parecer uma pequena galáxia coerente, não um amontoado
// solto de astros soltos.
function _cosmicMakeThematicSystem(biome, sx, sy) {
  const spawned = [];
  const star = new Star(sx, sy);
  star._cosmicColonizedBy = biome.raceId;
  star._cosmicNative = true;
  spawned.push(star);

  const planetCount = 1 + Math.floor(rand(0, 3)); // 1 a 3 planetas
  const usedDist = [];
  for (let i = 0; i < planetCount; i++) {
    let orbitDist;
    let tries = 0;
    do {
      orbitDist = rand(70, 220);
      tries++;
    } while (usedDist.some(d => Math.abs(d - orbitDist) < 35) && tries < 10);
    usedDist.push(orbitDist);

    const orbitAngle = rand(0, Math.PI * 2);
    const px = sx + Math.cos(orbitAngle) * orbitDist;
    const py = sy + Math.sin(orbitAngle) * orbitDist;
    const planet = new Planet(px, py, star);
    planet.orbitDist = orbitDist;
    planet.orbitAngle = orbitAngle;
    planet.orbitSpeed = (0.4 + rand(0, 0.3)) / Math.sqrt(orbitDist / 50);
    planet._cosmicColonizedBy = biome.raceId;
    planet._cosmicNative = true;
    spawned.push(planet);

    // Garante pelo menos 1 lua no sistema todo: sempre no primeiro
    // planeta; nos demais, chance de ganhar uma lua também.
    if (i === 0 || Math.random() < 0.5) {
      const moonAngle = rand(0, Math.PI * 2);
      const moonDist = rand(18, 34);
      const mx = px + Math.cos(moonAngle) * moonDist;
      const my = py + Math.sin(moonAngle) * moonDist;
      const moon = new Moon(mx, my, planet);
      moon.orbitDist = moonDist;
      moon.orbitAngle = moonAngle;
      moon._cosmicColonizedBy = biome.raceId;
      moon._cosmicNative = true;
      spawned.push(moon);
    }
  }
  return spawned;
}

function _cosmicPopulateBiome(biome, race) {
  if (typeof objects === 'undefined') return;
  const count = Math.floor(rand(COSMIC_BIOME_NATIVE_MIN, COSMIC_BIOME_NATIVE_MAX + 1));
  const pool = (race && race.hostTypes && race.hostTypes.length)
    ? race.hostTypes.slice()
    : COSMIC_BIOME_NATIVE_TYPES.slice();

  const allSpawned = [];

  // Âncora temática: garante estrela + planeta(s) + lua sempre presentes,
  // formando uma "mini-galáxia" reconhecível no centro do bioma.
  const anchorSystem = _cosmicMakeThematicSystem(biome, biome.x, biome.y);
  allSpawned.push(...anchorSystem);

  const newStars = anchorSystem.filter(o => o.type === 'star');
  const extraCount = Math.max(0, count - anchorSystem.length);
  for (let i = 0; i < extraCount; i++) {
    const ang = rand(0, Math.PI * 2);
    const r = rand(biome.radius * 0.3, biome.radius * 0.85);
    const px = biome.x + Math.cos(ang) * r;
    const py = biome.y + Math.sin(ang) * r;
    let type = pool[Math.floor(rand(0, pool.length))];

    let obj = null;
    if (type === 'star' || type === 'cepheid' || type === 'protostar' || type === 'magnetar') {
      obj = new Star(px, py);
      newStars.push(obj);
    } else if (type === 'planet') {
      const nearStar = newStars.length ? newStars[newStars.length - 1] : null;
      obj = new Planet(px, py, nearStar);
      if (nearStar) {
        obj.orbitDist = dist(obj, nearStar);
        obj.orbitAngle = Math.atan2(py - nearStar.y, px - nearStar.x);
        obj.orbitSpeed = (0.4 + rand(0, 0.3)) / Math.sqrt(obj.orbitDist / 50);
      }
    } else if (type === 'moon' || type === 'coldcore' || type === 'icecore' || type === 'nucleogelido') {
      obj = new Moon(px, py, null);
    } else if (type === 'blackhole' || type === 'neutronstar' || type === 'quasar') {
      obj = new BlackHole(px, py);
    } else if (type === 'pulsar') {
      obj = new Pulsar(px, py);
    } else if (type === 'wormhole') {
      obj = new Wormhole(px, py);
    } else if (type === 'microquasar') {
      obj = new Microquasar(px, py);
    } else {
      // Tipo sem construtor nativo conhecido: cai para um tipo-base
      // (estrela/planeta/lua/buraco negro) só neste caso residual.
      type = COSMIC_BIOME_NATIVE_TYPES[Math.floor(rand(0, COSMIC_BIOME_NATIVE_TYPES.length))];
      obj = new Planet(px, py, null);
    }

    if (obj) {
      obj._cosmicColonizedBy = biome.raceId;
      obj._cosmicNative = true;
      allSpawned.push(obj);
    }
  }

  // _cosmicPopulateBiome roda durante o update loop (via cosmicBiomesUpdate),
  // então precisa entrar na fila pendingObjects, igual todo outro spawn
  // in-tick do jogo — objects.push() direto aqui é descartado no próximo
  // flush (`objects=objects.filter(...);objects.push(...pendingObjects)`).
  allSpawned.forEach(obj => {
    if (typeof pendingObjects !== 'undefined') pendingObjects.push(obj);
    else objects.push(obj);
  });
}

// Retorna true se o ponto (x,y) está dentro do bioma (checagem
// aproximada usando o raio irregular médio na direção do ponto).
function _cosmicPointInBiome(biome, x, y) {
  const dx = x - biome.x, dy = y - biome.y;
  const d = Math.hypot(dx, dy);
  if (d > biome.radius * 1.25) return false; // corte rápido
  const ang = Math.atan2(dy, dx);
  // Acha o segmento do contorno mais próximo desse ângulo
  let closestR = biome.radius;
  let bestDiff = Infinity;
  biome.shape.forEach(p => {
    let diff = Math.abs(p.a - ((ang + Math.PI * 2) % (Math.PI * 2)));
    if (diff > Math.PI) diff = Math.PI * 2 - diff;
    if (diff < bestDiff) { bestDiff = diff; closestR = p.r; }
  });
  return d <= closestR;
}

function _cosmicBiomeForRace(raceId) {
  const candidates = _cosmicBiomes.filter(b => b.raceId === raceId);
  if (!candidates.length) return null;
  return candidates[Math.floor(rand(0, candidates.length))];
}

function _cosmicBiomeById(biomeId) {
  if (!biomeId) return null;
  return _cosmicBiomes.find(b => b.id === biomeId) || null;
}

function cosmicBiomesUpdate(dt) {
  _cosmicInitBiomes();
  _cosmicBiomes.forEach(b => { b.phase += dt; });
}

// ── Desenho de veias na borda (barreira orgânica/circuito) ──────────
function _cosmicDrawBiomeVeins(ctx, biome, pulse) {
  const T = biome.phase;
  ctx.strokeStyle = biome.veinColor || biome.edge;
  ctx.lineCap = 'round';
  (biome.veins || []).forEach(v => {
    const glowPulse = 0.5 + 0.5 * Math.sin(T * 1.6 + v.pulseOffset);
    const baseR = _cosmicRadiusAtAngle(biome, v.a) * pulse;
    const bx = biome.x + Math.cos(v.a) * baseR;
    const by = biome.y + Math.sin(v.a) * baseR;
    const tipR = baseR + v.len;
    const isCircuit = v.segments > 0;

    ctx.globalAlpha = 0.55 + 0.4 * glowPulse;
    ctx.lineWidth = Math.max(1.4, 2.8 * cam.zoom);
    ctx.shadowColor = biome.veinColor;
    ctx.shadowBlur = Math.max(3, 8 * cam.zoom * glowPulse);

    if (isCircuit) {
      // Robótica: segmentos retos em ângulo reto ("cotovelos"), como
      // trilhas de placa de circuito, crescendo pra fora da borda.
      let px = bx, py = by;
      const stepLen = v.len / v.segments;
      let ang = v.a;
      const p0 = worldToScreen(px, py);
      ctx.beginPath();
      ctx.moveTo(p0.x, p0.y);
      for (let s = 0; s < v.segments; s++) {
        ang += (s % 2 === 0 ? 1 : -1) * 0.5;
        px += Math.cos(ang) * stepLen;
        py += Math.sin(ang) * stepLen;
        const ps = worldToScreen(px, py);
        ctx.lineTo(ps.x, ps.y);
      }
      ctx.stroke();
      // Nó luminoso na ponta
      const tipS = worldToScreen(px, py);
      ctx.beginPath();
      ctx.arc(tipS.x, tipS.y, Math.max(1.2, 2.5 * cam.zoom), 0, Math.PI * 2);
      ctx.fillStyle = biome.veinColor;
      ctx.globalAlpha = 0.55 + 0.35 * glowPulse;
      ctx.fill();
    } else {
      // Demais raças: ramo orgânico curvo (curva quadrática) crescendo
      // pra fora, com pequenos galhos secundários — como uma veia ou
      // rachadura real, não uma linha reta.
      const midR = baseR + v.len * 0.5;
      const jitterA = v.a + Math.sin(T * 0.5 + v.pulseOffset) * v.jitter * 0.15;
      const midX = biome.x + Math.cos(jitterA) * midR;
      const midY = biome.y + Math.sin(jitterA) * midR;
      const tipX = biome.x + Math.cos(v.a) * tipR;
      const tipY = biome.y + Math.sin(v.a) * tipR;
      const b0 = worldToScreen(bx, by), bm = worldToScreen(midX, midY), bt = worldToScreen(tipX, tipY);
      ctx.beginPath();
      ctx.moveTo(b0.x, b0.y);
      ctx.quadraticCurveTo(bm.x, bm.y, bt.x, bt.y);
      ctx.stroke();

      // Galhos secundários saindo do ramo principal
      v.branches.forEach(br => {
        const atR = baseR + v.len * br.atPos;
        const atA = v.a + (v.jitter * 0.15) * br.atPos;
        const startX = biome.x + Math.cos(atA) * atR;
        const startY = biome.y + Math.sin(atA) * atR;
        const branchA = v.a + br.aOff;
        const branchLen = v.len * br.lenMul * 0.6;
        const endX = startX + Math.cos(branchA) * branchLen;
        const endY = startY + Math.sin(branchA) * branchLen;
        const s0 = worldToScreen(startX, startY), s1 = worldToScreen(endX, endY);
        ctx.lineWidth = Math.max(0.6, 1.3 * cam.zoom);
        ctx.beginPath();
        ctx.moveTo(s0.x, s0.y);
        ctx.lineTo(s1.x, s1.y);
        ctx.stroke();
      });
    }
  });
  ctx.globalAlpha = 1;
  ctx.shadowBlur = 0;
}

// ── Decoração interna temática por raça ──────────────────────────────
function _cosmicDrawBiomeDecor(ctx, biome, pulse) {
  const T = biome.phase;
  (biome.decor || []).forEach(d => {
    const wx = biome.x + d.ox * pulse;
    const wy = biome.y + d.oy * pulse;
    const s = worldToScreen(wx, wy);
    if (s.x < -80 || s.x > canvas.width + 80 || s.y < -80 || s.y > canvas.height + 80) return;
    const glow = 0.45 + 0.55 * Math.max(0, Math.sin(T * d.pulseSpeed + d.pulsePhase));
    // Escala em unidades de MUNDO (não pixels fixos) — um elemento
    // decorativo precisa ser visível proporcionalmente ao bioma
    // (raio de 900-1600), não uns poucos pixels de tela. worldToScreen
    // já aplica cam.zoom internamente para os pontos; aqui só
    // precisamos do fator de zoom para desenhar formas centradas em s.
    const scale = d.scale * biome.radius * 0.0025 * cam.zoom;
    ctx.save();
    ctx.translate(s.x, s.y);
    ctx.rotate(d.rot);
    ctx.shadowColor = d.color;
    ctx.shadowBlur = Math.max(4, 14 * scale * glow);

    switch (biome.raceId) {
      case 'fungica': {
        // Cogumelo bioluminescente: haste + chapéu, brilho rosa/azul/roxo.
        const capR = Math.max(3, 9 * scale);
        const stemH = capR * 1.8;
        ctx.shadowBlur = 0;
        ctx.strokeStyle = 'rgba(210,255,220,0.65)';
        ctx.lineWidth = Math.max(0.8, 1.4 * scale);
        ctx.beginPath(); ctx.moveTo(0, capR * 0.3); ctx.lineTo(0, stemH); ctx.stroke();
        ctx.shadowBlur = Math.max(4, 16 * scale * glow);
        ctx.beginPath();
        ctx.ellipse(0, 0, capR, capR * (d.variant === 1 ? 0.55 : 0.7), 0, Math.PI, Math.PI * 2);
        const cg = ctx.createRadialGradient(0, -capR * 0.2, 0, 0, 0, capR);
        cg.addColorStop(0, d.color);
        cg.addColorStop(0.7, d.color);
        cg.addColorStop(1, 'rgba(0,0,0,0)');
        ctx.fillStyle = cg;
        ctx.globalAlpha = Math.min(1, glow + 0.25);
        ctx.fill();
        ctx.beginPath(); ctx.arc(0, -capR * 0.1, Math.max(1.2, capR * 0.24), 0, Math.PI * 2);
        ctx.fillStyle = '#ffffff'; ctx.globalAlpha = glow * 0.85; ctx.fill();
        break;
      }
      case 'viscera': {
        // Pústula orgânica pulsante, veias finas saindo dela.
        const r = Math.max(3, 7 * scale) * (0.85 + 0.15 * glow);
        const pg = ctx.createRadialGradient(0, 0, 0, 0, 0, r);
        pg.addColorStop(0, d.color); pg.addColorStop(0.7, d.color); pg.addColorStop(1, 'rgba(0,0,0,0)');
        ctx.fillStyle = pg; ctx.globalAlpha = Math.min(1, glow + 0.2);
        ctx.beginPath(); ctx.arc(0, 0, r, 0, Math.PI * 2); ctx.fill();
        ctx.shadowBlur = 0;
        ctx.strokeStyle = d.color; ctx.lineWidth = Math.max(0.7, 1.2 * scale); ctx.globalAlpha = glow * 0.7;
        for (let k = 0; k < 3; k++) {
          const va = k * (Math.PI * 2 / 3) + d.variant;
          ctx.beginPath(); ctx.moveTo(0, 0);
          ctx.lineTo(Math.cos(va) * r * 1.8, Math.sin(va) * r * 1.8);
          ctx.stroke();
        }
        break;
      }
      case 'necrida': {
        // Fragmento ósseo/rachadura pálida, geométrica e angular.
        const r = Math.max(3, 8 * scale);
        ctx.shadowBlur = Math.max(2, 6 * scale * glow);
        ctx.strokeStyle = d.color; ctx.globalAlpha = 0.4 + 0.35 * glow;
        ctx.lineWidth = Math.max(0.8, 1.3 * scale);
        ctx.beginPath();
        ctx.moveTo(-r, 0); ctx.lineTo(-r * 0.2, -r * 0.5); ctx.lineTo(r * 0.3, -r * 0.15);
        ctx.lineTo(r, 0); ctx.lineTo(r * 0.25, r * 0.2); ctx.lineTo(-r * 0.3, r * 0.55); ctx.closePath();
        ctx.stroke();
        if (d.variant === 2) { ctx.fillStyle = d.color; ctx.globalAlpha = glow * 0.3; ctx.fill(); }
        break;
      }
      case 'plasmicea': {
        // Fenda de magma incandescente com gradiente quente pulsante.
        const len = Math.max(4, 11 * scale);
        const grad = ctx.createLinearGradient(-len, 0, len, 0);
        grad.addColorStop(0, 'rgba(255,60,20,0)');
        grad.addColorStop(0.5, d.color);
        grad.addColorStop(1, 'rgba(255,60,20,0)');
        ctx.strokeStyle = grad;
        ctx.lineWidth = Math.max(1.4, 3 * scale) * (0.7 + 0.5 * glow);
        ctx.globalAlpha = Math.min(1, glow + 0.15);
        ctx.beginPath();
        ctx.moveTo(-len, Math.sin(d.variant) * len * 0.3);
        ctx.quadraticCurveTo(0, -len * 0.4, len, Math.sin(d.variant + 1) * len * 0.3);
        ctx.stroke();
        break;
      }
      case 'robotica': {
        // Nó de circuito: quadrado pequeno + linhas ortogonais curtas.
        const r = Math.max(3, 6.5 * scale);
        ctx.strokeStyle = d.color; ctx.globalAlpha = 0.45 + 0.4 * glow;
        ctx.lineWidth = Math.max(0.8, 1.3 * scale);
        ctx.strokeRect(-r * 0.5, -r * 0.5, r, r);
        [[1,0],[-1,0],[0,1],[0,-1]].forEach(([dx,dy], k) => {
          if (d.variant === 0 && k >= 2) return; // variação: nem todo nó tem 4 pernas
          ctx.beginPath();
          ctx.moveTo(dx * r * 0.5, dy * r * 0.5);
          ctx.lineTo(dx * r * 1.4, dy * r * 1.4);
          ctx.stroke();
        });
        ctx.fillStyle = d.color; ctx.globalAlpha = glow;
        ctx.beginPath(); ctx.arc(0, 0, Math.max(0.8, r * 0.22), 0, Math.PI * 2); ctx.fill();
        break;
      }
    }
    ctx.restore();
  });
  ctx.globalAlpha = 1;
}

function cosmicBiomesDraw(ctx) {
  _cosmicBiomes.forEach(biome => {
    const pulse = 1 + Math.sin(biome.phase * 0.4) * 0.02; // respiração bem sutil
    ctx.save();
    ctx.beginPath();
    biome.shape.forEach((p, i) => {
      const wx = biome.x + Math.cos(p.a) * p.r * pulse;
      const wy = biome.y + Math.sin(p.a) * p.r * pulse;
      const s = worldToScreen(wx, wy);
      if (i === 0) ctx.moveTo(s.x, s.y); else ctx.lineTo(s.x, s.y);
    });
    ctx.closePath();
    ctx.fillStyle = biome.color;
    ctx.fill();
    ctx.strokeStyle = biome.edge;
    ctx.lineWidth = 1.5;
    ctx.stroke();

    // Veias/circuitos crescendo pra fora da borda — reforça a sensação
    // de fronteira viva/barreira, em vez de um traço de contorno inerte.
    if (!biome.veins) biome.veins = _cosmicMakeBiomeVeins(biome);
    _cosmicDrawBiomeVeins(ctx, biome, pulse);

    // Elementos internos temáticos (cogumelos, pústulas, rachaduras,
    // fendas de magma, nós de circuito — variam por raça).
    if (!biome.decor) biome.decor = _cosmicMakeBiomeDecor(biome);
    _cosmicDrawBiomeDecor(ctx, biome, pulse);

    // Nome do bioma no topo da região (só quando razoavelmente em tela)
    const center = worldToScreen(biome.x, biome.y - biome.radius * 0.95);
    if (center.x > -200 && center.x < canvas.width + 200 && center.y > -50 && center.y < canvas.height + 50) {
      ctx.font = `${Math.max(11, 13 * cam.zoom)}px sans-serif`;
      ctx.textAlign = 'center';
      ctx.fillStyle = biome.edge;
      ctx.globalAlpha = 0.85;
      ctx.fillText(biome.name, center.x, center.y);
      ctx.globalAlpha = 1;
    }
    ctx.restore();
  });
}

function cosmicBiomesReset() {
  _cosmicBiomes = [];
  _cosmicBiomesInited = false;
}

// ═══════════════════════════════════════════════════════════════════
//  MÓDULO: PREDADORES CÓSMICOS ADORMECIDOS — fundação (sem boss ainda)
// ═══════════════════════════════════════════════════════════════════
//  Cada bioma acumula seu próprio Índice de Perturbação, gerado pela
//  atividade do jogador ali dentro: minerar rochas nativas do bioma, e
//  permanecer no território com o tempo. A Sonda, agora com um upgrade
//  de alcance GLOBAL (em vez de só Local), soma-se a esse índice: só
//  quando os dois — perturbação do bioma específico E nível global da
//  Sonda — batem o limiar da fila daquele bioma, uma NAVE-RELÍQUIA
//  abandonada e completamente invisível aparece lá dentro, detectável
//  apenas por uma Sonda em nível Global. Tocar nela a destrói e libera
//  um item "Invocador" na mochila do jogador — guardável indefinidamente,
//  usado quando o jogador quiser para convocar o boss correspondente.
//
//  Esta etapa é só a FUNDAÇÃO: perturbação, upgrade Global da Sonda,
//  nave-relíquia e Invocador. Os próprios bosses (fases de combate) são
//  implementados depois, um de cada vez.
// ═══════════════════════════════════════════════════════════════════

// ── Fontes de perturbação (ajustáveis sem tocar na lógica) ───────────
const COSMIC_PERTURBATION_PER_MINERAL = 4;     // por minério coletado de rocha nativa do bioma
const COSMIC_PERTURBATION_PER_SEC_PRESENCE = 0.6; // por segundo que a câmera passa dentro do bioma

// ── Fila de bosses por bioma (raceId → lista, em ordem de liberação) ──
// Só o primeiro boss de cada fila está definido por enquanto (mais
// detalhes/2º boss de cada fila entram quando o Polvicullus e os
// próximos forem fechados). O campo `threshold` é o nível de
// perturbação necessário SOMADO ao nível global da Sonda multiplicado
// por um peso — ver cosmicBossTriggerReady().
const COSMIC_BOSS_QUEUE = {
  plasmicea: [
    { bossId: 'polvicullus-estelarus', name: 'Polvicullus Estelarus', threshold: 260 },
  ],
  fungica: [],
  necrida: [],
  viscera: [],
  robotica: [
    { bossId: 'galaximy', name: 'Galaximy', threshold: 260 },
  ],
};

// Peso de quanto 1 nível da Sonda Global "ajuda" a atingir o limiar de
// um bioma — nível 0 de Sonda Global não ajuda em nada (perturbação
// pura ainda não é suficiente sozinha, precisa da Sonda pra revelar).
const COSMIC_PROBE_GLOBAL_TRIGGER_WEIGHT = 40;

function cosmicAddBiomePerturbation(biomeId, amount) {
  const biome = _cosmicBiomeById(biomeId);
  if (!biome) return;
  biome.perturbation = (biome.perturbation || 0) + amount;
}

// Nível global mais alto entre todas as Sondas Globais ativas do
// jogador — usado como "quão fundo" o escaneamento coletivo alcança.
function _cosmicHighestGlobalProbeLevel() {
  if (typeof objects === 'undefined') return 0;
  let best = 0;
  objects.forEach(o => {
    if (!o.dead && o.type === 'cosmicProbe' && o.isGlobal) {
      best = Math.max(best, o.globalLevel || 1);
    }
  });
  return best;
}

function cosmicBossTriggerReady(biome) {
  const queue = COSMIC_BOSS_QUEUE[biome.raceId];
  if (!queue || biome.bossQueueIndex >= queue.length) return null; // fila vazia ou já esgotada
  if (biome.relicSpawned) return null; // já tem relíquia pendente pra este bioma
  const nextBoss = queue[biome.bossQueueIndex];
  const probeBonus = _cosmicHighestGlobalProbeLevel() * COSMIC_PROBE_GLOBAL_TRIGGER_WEIGHT;
  if ((biome.perturbation || 0) + probeBonus >= nextBoss.threshold) return nextBoss;
  return null;
}

// ── Atualização de perturbação por presença + checagem de gatilho ────
function cosmicPerturbationUpdate(dt) {
  if (typeof _cosmicBiomes === 'undefined' || !_cosmicBiomes.length) return;
  if (typeof cam === 'undefined') return;

  _cosmicBiomes.forEach(biome => {
    // Perturbação por permanência: só conta se a câmera (posição de
    // referência do jogador) estiver de fato dentro do contorno do bioma.
    if (_cosmicPointInBiome(biome, cam.x, cam.y)) {
      cosmicAddBiomePerturbation(biome.id, COSMIC_PERTURBATION_PER_SEC_PRESENCE * dt);
    }

    if (biome.relicSpawned) return; // já tem relíquia pendente, não checa de novo

    const readyBoss = cosmicBossTriggerReady(biome);
    if (readyBoss) {
      _cosmicSpawnBossRelic(biome, readyBoss);
    }
  });
}

// ═══════════════════════════════════════════════════════════════════
//  NAVE-RELÍQUIA — abandonada, invisível, só detectável por Sonda Global
// ═══════════════════════════════════════════════════════════════════
let _cosmicBossRelics = [];
const COSMIC_RELIC_COLLECT_RANGE = 40;

function _cosmicSpawnBossRelic(biome, bossDef) {
  const pos = _cosmicRollPosNearCameraInBiome(biome);
  _cosmicBossRelics.push({
    id: 'relic_' + biome.id + '_' + bossDef.bossId,
    biomeId: biome.id,
    bossId: bossDef.bossId,
    bossName: bossDef.name,
    x: pos.x, y: pos.y,
    phase: rand(0, Math.PI * 2),
    scale: 1,
  });
  biome.relicSpawned = true;
  // Sem notificação de texto: a relíquia é INVISÍVEL a olho nu — só
  // aparece marcada no radar/tela de uma Sonda Global (implementado
  // junto do draw). Anunciar por tooltip aqui entregaria a posição sem
  // precisar da Sonda, quebrando a própria mecânica.
}

// Chamado pelo clique/toque do jogador no mundo (mesmo fluxo de
// cosmicTryCollectRockAt) — só "acerta" a relíquia se uma Sonda Global
// já tiver revelado a posição (ver _cosmicRelicIsRevealed).
function cosmicTryCollectRelicAt(wx, wy) {
  for (let i = 0; i < _cosmicBossRelics.length; i++) {
    const relic = _cosmicBossRelics[i];
    if (!_cosmicRelicIsRevealed(relic)) continue; // ainda invisível: não pode ser tocada
    if (Math.hypot(relic.x - wx, relic.y - wy) <= COSMIC_RELIC_COLLECT_RANGE) {
      _cosmicBossRelics.splice(i, 1);
      const biome = _cosmicBiomeById(relic.biomeId);
      if (biome) { biome.relicSpawned = false; biome.bossQueueIndex++; }
      _cosmicGrantBossInvoker(relic);
      return relic;
    }
  }
  return null;
}

// Uma relíquia só fica "revelada" (visível/tocável) se existir uma
// Sonda Global cujo território cubra a posição dela — reaproveita a
// própria lógica de território da sonda, sem duplicar regras novas.
function _cosmicRelicIsRevealed(relic) {
  if (typeof objects === 'undefined') return false;
  for (let i = 0; i < objects.length; i++) {
    const o = objects[i];
    if (o.dead || o.type !== 'cosmicProbe' || !o.isGlobal) continue;
    if (Math.hypot(o.x - relic.x, o.y - relic.y) <= o.territoryRadius) return true;
  }
  return false;
}

function _cosmicGrantBossInvoker(relic) {
  if (typeof addBackpackItem !== 'function') return;
  const BOSS_INVOKER_ICONS = {
    'polvicullus-estelarus': 'images/CosmicPhase/Bosses/Tentáculo Solar.svg',
    'galaximy': 'images/CosmicPhase/Bosses/Molécula Galáctica.png',
  };
  addBackpackItem({
    id: 'boss-invoker-' + relic.bossId,
    name: 'Invocador — ' + relic.bossName,
    desc: 'Relíquia recuperada de uma nave abandonada. Use quando estiver pronto para enfrentar ' + relic.bossName + '.',
    icon: BOSS_INVOKER_ICONS[relic.bossId] || '👁️',
    useLabel: '⚡ Convocar',
    onUse: () => {
      if (relic.bossId === 'polvicullus-estelarus') {
        // Spawn natural exige Pacote Exótico desbloqueado (Rank 28).
        if (typeof _isExoticPackUnlocked === 'function' && !_isExoticPackUnlocked()) {
          if (typeof showTooltip === 'function') showTooltip('🔒 Pacote Exótico (Rank 28) necessário para convocar ' + relic.bossName + '.');
          return;
        }
        if (typeof PolvicullusBoss !== 'undefined' && !PolvicullusBoss.isActive()) {
          PolvicullusBoss.start({ biomeId: relic.biomeId });
        }
        return;
      }
      if (relic.bossId === 'galaximy') {
        // Spawn natural exige Pacote Tecnológico desbloqueado (Rank 38)
        // — o próprio Galaximy usa astros do Tech Pack como combatentes.
        if (typeof _isTechPackUnlocked === 'function' && !_isTechPackUnlocked()) {
          if (typeof showTooltip === 'function') showTooltip('🔒 Pacote Tecnológico (Rank 38) necessário para convocar ' + relic.bossName + '.');
          return;
        }
        if (typeof GalaximyBoss !== 'undefined' && !GalaximyBoss.isActive()) {
          GalaximyBoss.start({ biomeId: relic.biomeId });
        } else if (typeof showTooltip === 'function') {
          showTooltip('⚡ ' + relic.bossName + ' ainda não está implementado — em breve.');
        }
        return;
      }
      // Sem implementação de combate ainda (fundação apenas) — o
      // próprio boss entra numa etapa futura. Por ora, só confirma que
      // o item funciona e será plugado ao spawn real do boss depois.
      if (typeof showTooltip === 'function') {
        showTooltip('⚡ ' + relic.bossName + ' ainda não está implementado — em breve.');
      }
    },
  });
  if (typeof showTooltip === 'function') {
    showTooltip('👁️ Nave abandonada destruída — Invocador de ' + relic.bossName + ' guardado na mochila!');
  }
}

// ── Desenho — a relíquia só é visualmente perceptível quando revelada
// por uma Sonda Global; fora disso, permanece 100% invisível no mundo,
// coerente com a própria fundação da mecânica. ────────────────────────
function cosmicBossRelicsDraw(ctx) {
  for (let i = 0; i < _cosmicBossRelics.length; i++) {
    const relic = _cosmicBossRelics[i];
    if (!_cosmicRelicIsRevealed(relic)) continue;
    relic.phase += 0.016;
    const sx = (relic.x - cam.x) * cam.zoom + canvas.width * 0.5;
    const sy = (relic.y - cam.y) * cam.zoom + canvas.height * 0.5;
    if (sx < -60 || sx > canvas.width + 60 || sy < -60 || sy > canvas.height + 60) continue;

    const r = Math.max(6, 14 * cam.zoom);
    const pulse = 1 + Math.sin(relic.phase * 2) * 0.15;
    ctx.save();
    ctx.translate(sx, sy);
    // Silhueta de casco abandonado, cinza-esverdeado translúcido —
    // "meio detectado" pela Sonda, nunca sólido/opaco como uma nave viva.
    ctx.beginPath();
    ctx.moveTo(r * 1.4, 0);
    ctx.lineTo(-r * 0.8, -r * 0.6);
    ctx.lineTo(-r * 1.3, 0);
    ctx.lineTo(-r * 0.8, r * 0.6);
    ctx.closePath();
    ctx.fillStyle = 'rgba(120,220,180,0.28)';
    ctx.fill();
    ctx.strokeStyle = `rgba(150,255,210,${0.4 * pulse})`;
    ctx.lineWidth = Math.max(0.8, r * 0.08);
    ctx.stroke();
    // Marcador de radar por cima — anel pulsante, deixa claro que é a
    // Sonda revelando algo, não a nave "aparecendo" por si.
    ctx.beginPath();
    ctx.arc(0, 0, r * 1.8 * pulse, 0, Math.PI * 2);
    ctx.strokeStyle = `rgba(150,255,210,${0.25 * (2 - pulse)})`;
    ctx.lineWidth = 1;
    ctx.stroke();
    ctx.restore();
  }
}

function cosmicBossRelicsReset() {
  _cosmicBossRelics = [];
}

// ═══════════════════════════════════════════════════════════════════
//  BOSS CÓSMICO PLASMÍCEA: POLVICULLUS ESTELARUS
//  Arena dedicada (mesmo padrão das invasões: canvas de rift próprio +
//  HP bar fixa no topo). Combate FRONTAL: o boss fica de frente para o
//  jogador, corpo central de polvo comum (branco/amarelo) e tentáculos
//  INDEPENDENTES — cada um com sua própria física de movimento/ataque,
//  não presos a uma pose única do corpo.
//  Disparado pelo Invocador (item da mochila, ver _cosmicGrantBossInvoker).
// ═══════════════════════════════════════════════════════════════════
// ═══════════════════════════════════════════════════════════════════
//  BOSS CÓSMICO PLASMÍCEA: POLVICULLUS ESTELARUS
//  Arena dedicada GRANDE (mesmo padrão das invasões: canvas de rift
//  próprio + HP bar fixa no topo). Combate FRONTAL: boss de frente pro
//  jogador, corpo de polvo comum brilhante em branco/amarelo, manto
//  oval alongado (referência de silhueta clássica de polvo), 8
//  tentáculos INDEPENDENTES, cada um com física/estado próprios.
//
//  FASE 1 (100%–62% HP): lasers pelos olhos + chicotadas de tentáculo
//  que destroem astros próximos automaticamente.
//  FASE 2 (62%–28% HP): mais rápido, +dano, +defesa; invoca mini-polvos
//  que nascem ao redor do boss e avançam até um astro-alvo, explodindo
//  ao chegar perto; lasers mais frequentes.
//  FASE 3 (28%–0% HP): cresce um pouco; pode ficar COMPLETAMENTE
//  invisível (corpo + tentáculos) por 5s; +vida (bônus único ao
//  entrar na fase) e +muito ataque.
//
//  Disparado pelo Invocador (item da mochila) ou pelo Mod Menu.
// ═══════════════════════════════════════════════════════════════════
const PolvicullusBoss = (function(){
  let _active=false;
  let _boss=null;
  let _preInvasionStash=[]; // astros antigos guardados durante a batalha
  // ── Câmera: zoom E posição fixos durante o combate — o jogador não
  // pode mover a câmera nesta batalha (mesmo padrão robusto via
  // Object.defineProperty com setter noop). Só o Galaximy permite pan.
  let _savedZoom=1;
  let _playerZoomBeforeBattle=1;
  let _savedCamX=0,_savedCamY=0;
  let _camLocked=false;
  function _lockCam(){
    if(_camLocked)return;
    _playerZoomBeforeBattle=cam.zoom;
    _savedZoom=BATTLE_FIXED_ZOOM;
    _savedCamX=cam.x;_savedCamY=cam.y;
    try{
      Object.defineProperty(cam,'zoom',{get(){return _savedZoom;},set(){},configurable:true});
      Object.defineProperty(cam,'x',{get(){return _savedCamX;},set(){},configurable:true});
      Object.defineProperty(cam,'y',{get(){return _savedCamY;},set(){},configurable:true});
    }catch(e){}
    _camLocked=true;
  }
  function _unlockCam(){
    if(!_camLocked)return;
    try{
      Object.defineProperty(cam,'zoom',{value:_playerZoomBeforeBattle,writable:true,configurable:true});
      Object.defineProperty(cam,'x',{value:_savedCamX,writable:true,configurable:true});
      Object.defineProperty(cam,'y',{value:_savedCamY,writable:true,configurable:true});
    }catch(e){}
    _camLocked=false;
  }
  // ── Música do BOSS (Polvicullus Estelarus) — loop garantido via 'ended',
  // mesmo padrão usado pelos outros bosses/invasões (fade-in/out + reinício
  // manual do currentTime em vez de loop nativo) ──
  let _pvBossAudio=null;
  let _pvBossAudioStopping=false;
  let _pvBossAudioFadeInterval=null;
  let _pvBossAudioVol=0;
  function _startPolvicullusAudio(){
    if(_pvBossAudio)return;
    _pvBossAudioStopping=false;
    if(typeof _stopAudio==='function')_stopAudio();
    _pvBossAudio=new Audio('songs/Invasions/Bosses/Polvicullus_Estellarus.ogg');
    _pvBossAudio.loop=false;
    _pvBossAudio.addEventListener('ended',function(){
      if(!_pvBossAudio||_pvBossAudioStopping)return;
      _pvBossAudio.currentTime=0;
      _pvBossAudio.play().catch(()=>{});
    });
    _pvBossAudioVol=0;
    _pvBossAudio.volume=0;
    _pvBossAudio.play().catch(()=>{});
    if(_pvBossAudioFadeInterval){clearInterval(_pvBossAudioFadeInterval);_pvBossAudioFadeInterval=null;}
    _pvBossAudioFadeInterval=setInterval(()=>{
      _pvBossAudioVol=Math.min(0.58,_pvBossAudioVol+0.03);
      if(_pvBossAudio)_pvBossAudio.volume=_pvBossAudioVol;
      if(_pvBossAudioVol>=0.58){clearInterval(_pvBossAudioFadeInterval);_pvBossAudioFadeInterval=null;}
    },80);
  }
  function _stopPolvicullusAudio(){
    if(!_pvBossAudio)return;
    _pvBossAudioStopping=true;
    if(_pvBossAudioFadeInterval){clearInterval(_pvBossAudioFadeInterval);_pvBossAudioFadeInterval=null;}
    _pvBossAudioFadeInterval=setInterval(()=>{
      _pvBossAudioVol=Math.max(0,_pvBossAudioVol-0.035);
      if(_pvBossAudio)_pvBossAudio.volume=_pvBossAudioVol;
      if(_pvBossAudioVol<=0){
        if(_pvBossAudio){_pvBossAudio.pause();_pvBossAudio=null;}
        _pvBossAudioStopping=false;
        clearInterval(_pvBossAudioFadeInterval);_pvBossAudioFadeInterval=null;
      }
    },80);
  }
  let _riftCanvas=null, _riftCtx=null;
  let _arenaRect=null;
  let _animFrame=null;
  let _lastTick=0;
  let _t=0;
  // Cache dos 2 gradientes do CORPO (sombra + manto) que só dependem
  // do tamanho (scale) do boss, não da posição nem de nada animado
  // quadro a quadro. Evita recriar createRadialGradient() 2x por
  // frame (bem mais caro no celular do que reaproveitar). O brilho
  // externo (outerGlow) NÃO entra aqui pois pulsa em opacidade a
  // cada frame — precisa continuar sendo recriado. Tentáculos também
  // não são afetados: continuam com sua curva bezier própria por
  // frame, sem nenhuma mudança.
  let _shadowGradCache=null, _shadowGradScale=null;
  let _mantleGradCache=null, _mantleGradScale=null;
  let _lasers=[];       // feixes disparados pelos olhos
  let _miniOctopi=[];   // mini-polvos da Fase 2
  let _inkClouds=[];    // jatos de tinta da Fase 2+
  let _fxParticles=[];
  let _onDefeatCb=null;

  const _MARGIN=10; // arena BEM GRANDE: margem mínima, ocupa quase a tela toda

  const BOSS_MAX_HP=520000;
  const PHASE2_PCT=0.62;
  const PHASE3_PCT=0.28;
  // Bônus de vida concedido UMA VEZ ao entrar na Fase 3 (vida "aumenta
  // muito" como pedido, sem re-disparar a cada tick de fase 3).
  const PHASE3_HP_BONUS_MULT=1.35;

  const TENTACLE_COUNT=8;

  function rand(a,b){return a+Math.random()*(b-a);}
  function randInt(a,b){return Math.floor(rand(a,b+1));}
  function clamp(v,a,b){return Math.max(a,Math.min(b,v));}

  function isActive(){return _active;}

  // ── Início do combate ──────────────────────────────────────────────
  function start(opts){
    if(_active)return;
    opts=opts||{};
    _onDefeatCb=opts.onDefeat||null;
    _active=true;
    _lockCam(); // zoom fixo ANTES de calcular a arena/canvas

    _riftCanvas=document.getElementById('polvicullus-rift-canvas');
    _riftCtx=_riftCanvas.getContext('2d');
    _riftCanvas.width=canvas.width;
    _riftCanvas.height=canvas.height;
    _riftCanvas.style.left=canvas.style.left||'0px';
    _riftCanvas.style.top=canvas.style.top||'0px';
    _riftCanvas.style.width=canvas.width+'px';
    _riftCanvas.style.height=canvas.height+'px';
    _riftCanvas.classList.add('active');

    // Arena BEM GRANDE: margem mínima fixa, ocupa quase toda a tela
    // disponível (bem maior que as arenas de invasão padrão).
    const cw=_riftCanvas.width, ch=_riftCanvas.height;
    _arenaRect={x:_MARGIN,y:_MARGIN,w:cw-_MARGIN*2,h:ch-_MARGIN*2};

    _spawnBoss();
    _lasers=[];_miniOctopi=[];_inkClouds=[];_fxParticles=[];
    _t=0;_lastTick=performance.now();
    const bar=document.getElementById('polv-boss-hp-bar');
    if(bar)bar.classList.add('active');
    // Apenas os 10 astros exóticos de combate ficam disponíveis: todo o
    // resto (incluindo os outros 10 do Pacote Exótico) vira 🚫.
    _setInvasionAstroLockUI(true,POLVICULLUS_BLOCKED_ASTRO_TYPES);
    window._polvicullusAstroCaps={};
    Object.keys(POLVICULLUS_SP_CAP_CONFIG).forEach(t=>{
      const cfg=POLVICULLUS_SP_CAP_CONFIG[t];
      window._polvicullusAstroCaps[t]={max:cfg.max,used:0,cooldown:0,cooldownTime:cfg.cooldownTime};
    });
    const pvac=document.getElementById('polvicullus-astro-counters');
    if(pvac)pvac.style.display='flex';
    Object.keys(window._polvicullusAstroCaps).forEach(t=>{
      const el=document.getElementById(`polvicullus-${t}-counter`);
      if(el)el.classList.remove('depleted','cooldown');
      _refreshPolvicullusAstroCounterUI(t,window._polvicullusAstroCaps[t]);
    });
    showTooltip('🐙🌟 POLVICULLUS ESTELARUS emergiu das profundezas cósmicas! Use os astros do Pacote Exótico para atacá-lo.');
    // ── Guarda TODOS os astros antigos e limpa a tela para a batalha,
    // mesmo padrão do Alien/Marsian (evita astros antigos soltos/colidindo
    // dentro da arena do Polvicullus). Restaurados em _finish(). ──
    _preInvasionStash=objects.filter(o=>!o.dead);
    objects.length=0;
    window._invasionActive=true;
    // ── Limites de Reset (2) e Mover (3) — mesmo padrão do Marsian ──
    window._polvicullusResetUses=2;
    window._polvicullusMoveUses=3;
    {
      const pru=document.getElementById('polvicullus-reset-uses');
      const pmu=document.getElementById('polvicullus-move-uses');
      const prc=document.getElementById('polvicullus-reset-counter');
      const pmc=document.getElementById('polvicullus-move-counter');
      if(pru)pru.textContent='2';if(pmu)pmu.textContent='3';
      if(prc)prc.classList.remove('depleted');if(pmc)pmc.classList.remove('depleted');
    }
    _startPolvicullusAudio();
    _animFrame=requestAnimationFrame(_tick);
  }

  function _spawnBoss(){
    _shadowGradCache=null;_shadowGradScale=null;
    _mantleGradCache=null;_mantleGradScale=null;
    const ar=_arenaRect;
    const cx=ar.x+ar.w/2, cy=ar.y+ar.h*0.36;
    const tentacles=[];
    // Ângulo restrito ao arco INFERIOR (de 0.12π a 0.88π, medido a
    // partir do eixo +X, sentido horário em coords de tela) — antes
    // usava o círculo completo (0 a 2π), o que espalhava as bases dos
    // tentáculos ao REDOR do boss inteiro em vez de só embaixo dele.
    const TENT_ARC_START=Math.PI*0.12, TENT_ARC_END=Math.PI*0.88;
    for(let i=0;i<TENTACLE_COUNT;i++){
      const baseAngle=TENT_ARC_START+(i/(TENTACLE_COUNT-1))*(TENT_ARC_END-TENT_ARC_START);
      tentacles.push({
        idx:i,
        baseAngle,
        tipX:Math.cos(baseAngle)*150, tipY:Math.abs(Math.sin(baseAngle))*80+70,
        restX:Math.cos(baseAngle)*150, restY:Math.abs(Math.sin(baseAngle))*80+70,
        phase:rand(0,Math.PI*2),
        speed:rand(0.7,1.3),
        state:'idle', // idle | telegraph | whipping | retracting
        stateT:0,
        cooldown:rand(0.6,2.4),
        curl:rand(0.4,0.85),
        hue:Math.random()<0.5?'#fffdf0':'#ffe680',
      });
    }
    _boss={
      x:cx,y:cy,
      baseX:cx,baseY:cy,
      hp:BOSS_MAX_HP,maxHP:BOSS_MAX_HP,
      phase:1,
      t:0,
      bobPhase:0,
      mantleRX:66,mantleRY:96, // manto OVAL alongado, tamanho médio
      sizeScale:1, // cresce um pouco na fase 3
      tentacles,
      laserTimer:rand(1.6,2.4),
      laserCd:{1:[2.6,3.6],2:[1.5,2.3],3:[1.1,1.7]}, // intervalo por fase
      miniSpawnTimer:rand(3,5),
      invisTimer:rand(6,9), // tempo até a próxima invisibilidade (fase 3)
      invisible:false, invisibleT:0, invisibleDur:5,
      ambushPending:false,
      inkTimer:rand(5,8),
      glowPulse:0,
      eyeBlink:0,
      flashT:0,flashColor:'#ffffff',
      atkMult:1, defMult:1, speedMult:1,
      dying:false, dyingT:0,
    };
    _updateBar();
  }

  // ── HP bar ────────────────────────────────────────────────────────
  function _getPhase(hp,maxHP){
    const pct=hp/maxHP;
    if(pct>PHASE2_PCT)return 1;
    if(pct>PHASE3_PCT)return 2;
    return 3;
  }
  function _updateBar(){
    if(!_boss)return;
    const fill=document.getElementById('polv-boss-hp-fill');
    const phaseLbl=document.getElementById('polv-boss-hp-phase');
    const pct=Math.max(0,_boss.hp/_boss.maxHP*100);
    if(fill){
      fill.style.width=pct+'%';
      fill.className=_boss.phase===2?'phase2':_boss.phase===3?'phase3':'';
    }
    if(phaseLbl)phaseLbl.textContent='FASE '+_boss.phase;
  }
  function _flash(color){ if(_boss){_boss.flashT=0.3;_boss.flashColor=color||'#ffffff';} }

  function _applyPhaseStats(b){
    if(b.phase===1){ b.atkMult=1; b.defMult=1; b.speedMult=1; }
    else if(b.phase===2){ b.atkMult=1.4; b.defMult=1.3; b.speedMult=1.35; }
    else { b.atkMult=2.1; b.defMult=1.5; b.speedMult=1.5; }
  }

  function _damageBoss(rawAmount){
    if(!_boss||_boss.dying)return;
    // Invisível na fase 3: intocável (some completamente, inclusive
    // pra dano direto).
    if(_boss.invisible)return;
    const amount=rawAmount/(_boss.defMult||1);
    _boss.hp=Math.max(0,_boss.hp-amount);
    _flash('#ff5555');
    const newPhase=_getPhase(_boss.hp,_boss.maxHP);
    if(newPhase!==_boss.phase){
      const enteringPhase3=newPhase===3&&_boss.phase!==3;
      _boss.phase=newPhase;
      _applyPhaseStats(_boss);
      if(enteringPhase3){
        // "Aumenta um pouco de tamanho" + "aumenta vida" — bônus ÚNICO,
        // aplicado sobre o HP atual (não reseta pra máximo cheio).
        const bonus=_boss.hp*(PHASE3_HP_BONUS_MULT-1);
        _boss.maxHP=_boss.maxHP*PHASE3_HP_BONUS_MULT;
        _boss.hp=Math.min(_boss.maxHP,_boss.hp+bonus);
        _boss.sizeScale=1.22;
        _boss.invisTimer=rand(4,6);
      }
      const msgs={2:'🐙⚡ Polvicullus está mais rápido e forte — mini-polvos incoming!',3:'🐙🔥 Polvicullus cresceu e fica INVISÍVEL periodicamente — cuidado!'};
      if(msgs[newPhase])showTooltip(msgs[newPhase]);
      const flashEl=document.getElementById('polvicullus-emergency-flash');
      if(flashEl){flashEl.style.opacity='1';setTimeout(()=>{flashEl.style.opacity='0';},600);}
    }
    _updateBar();
    if(_boss.hp<=0&&!_boss.dying){
      _boss.dying=true;_boss.dyingT=0;
    }
  }

  // ── Loop principal ───────────────────────────────────────────────
  function _tick(ts){
    if(!_active)return;
    const dt=Math.min(0.05,(ts-_lastTick)/1000);
    _lastTick=ts;
    _t+=dt;

    // ── Limite de tempo total da batalha: 2min30s (150s) ──
    if(_t>=150&&_boss&&!_boss.dying){
      _finish(false,'timeout');
      return;
    }

    _riftCtx.clearRect(0,0,_riftCanvas.width,_riftCanvas.height);
    _drawArenaBorder(_riftCtx,_t);

    if(_boss){
      if(_boss.dying) _tickDeath(dt);
      else { _tickBoss(dt); _tickPlayerAstroDamage(dt); }
      _drawBoss(_riftCtx,_boss,_t);
    }

    // ── Tick cooldown dos astros exóticos de combate (limite justo) ──
    if(window._polvicullusAstroCaps&&typeof objects!=='undefined'){
      Object.keys(window._polvicullusAstroCaps).forEach(t=>{
        const cap=window._polvicullusAstroCaps[t];
        if(cap.cooldown>0){
          cap.cooldown=Math.max(0,cap.cooldown-dt);
          _refreshPolvicullusAstroCounterUI(t,cap);
          if(cap.cooldown===0){
            cap.used=0;
            _refreshPolvicullusAstroCounterUI(t,cap);
            showTooltip(`✅ ${TYPE_LABELS[t]||t}: recarga completa! ${cap.max} uso(s) disponíveis.`);
          }
        } else {
          const alive=objects.filter(o=>!o.dead&&o.type===t).length;
          cap.used=Math.min(alive,cap.max);
          _refreshPolvicullusAstroCounterUI(t,cap);
        }
      });
    }

    _tickLasers(dt); _drawLasers(_riftCtx);
    _tickMiniOctopi(dt); _drawMiniOctopi(_riftCtx);
    _tickFx(dt); _drawFx(_riftCtx);

    _animFrame=requestAnimationFrame(_tick);
  }

  function _tickDeath(dt){
    const b=_boss;
    b.dyingT+=dt;
    // Mantém os tentáculos "vivos"/balançando (mais rápido conforme a
    // morte avança) em vez de congelar — o balanço extra é aplicado
    // em _drawTentacle via swingBoost.
    b.tentacles.forEach(tn=>{tn.phase+=dt*tn.speed*(1+Math.min(1,b.dyingT/4.5)*1.5);});
    const T=4.5; // duração total da sequência de morte
    const p=Math.min(1,b.dyingT/T);

    // ── Fase 1 (0–40%): tremores crescentes + fumaça escura subindo ──
    if(p<0.4){
      const shake=p/0.4;
      if(Math.random()<0.5+shake*0.4){
        _fxParticles.push({
          x:b.x+rand(-b.mantleRX,b.mantleRX)*b.sizeScale,y:b.y+rand(-b.mantleRY,b.mantleRY)*b.sizeScale,
          vx:rand(-30,30),vy:rand(-40,-5),r:rand(3,8),alpha:1,
          color:Math.random()<0.6?'#4a2a10':'#2a1608',life:1.1,maxLife:1.1,
        });
      }
    }
    // ── Fase 2 (40–75%): rachaduras de luz + faíscas âmbar intensas,
    // corpo já visivelmente encolhendo/escurecendo (ver _drawBoss) ──
    else if(p<0.75){
      if(Math.random()<0.75){
        const ang=rand(0,Math.PI*2), dist=rand(0,1)*b.mantleRX*b.sizeScale;
        _fxParticles.push({
          x:b.x+Math.cos(ang)*dist,y:b.y+Math.sin(ang)*dist*0.7,
          vx:Math.cos(ang)*rand(30,90),vy:Math.sin(ang)*rand(30,90)-20,r:rand(2,6),alpha:1,
          color:Math.random()<0.5?'#fffde0':'#ff9922',life:0.7,maxLife:0.7,
        });
      }
    }
    // ── Fase 3 (75–100%): colapso final — onda de partículas crescente
    // culminando na explosão de luz ──
    else{
      if(Math.random()<0.9){
        _fxParticles.push({
          x:b.x+rand(-b.mantleRX,b.mantleRX)*b.sizeScale,y:b.y+rand(-b.mantleRY,b.mantleRY)*b.sizeScale,
          vx:rand(-90,90),vy:rand(-110,-20),r:rand(4,11),alpha:1,
          color:Math.random()<0.5?'#fffde0':'#ffe066',life:0.9,maxLife:0.9,
        });
      }
    }

    if(b.dyingT>=T){
      // Explosão final: múltiplos anéis de luz expandindo, mais
      // dramática que o simples burst de círculos aleatórios de antes.
      for(let ring=0;ring<3;ring++){
        const rr=40+ring*55;
        _riftCtx.beginPath();
        _riftCtx.arc(b.x,b.y,rr,0,Math.PI*2);
        _riftCtx.strokeStyle=`rgba(255,240,190,${0.8-ring*0.22})`;
        _riftCtx.lineWidth=6-ring*1.5;
        _riftCtx.stroke();
      }
      for(let i=0;i<60;i++){
        _riftCtx.beginPath();
        _riftCtx.arc(b.x+rand(-140,140),b.y+rand(-140,140),rand(3,20),0,Math.PI*2);
        _riftCtx.fillStyle=`rgba(255,240,180,${Math.random()*0.85})`;
        _riftCtx.fill();
      }
      _finish(true);
    }
  }

  function _tickBoss(dt){
    const b=_boss;
    b.t+=dt;
    b.bobPhase+=dt*1.1*b.speedMult;
    b.glowPulse+=dt*1.6;
    b.eyeBlink=Math.max(0,b.eyeBlink-dt);
    if(Math.random()<0.003)b.eyeBlink=0.15;

    // Corpo frontal: flutuação vertical/leve, mantendo leitura "sempre
    // de frente" pro jogador — nunca vira de lado.
    b.x=b.baseX+Math.sin(b.bobPhase*0.6)*10;
    b.y=b.baseY+Math.sin(b.bobPhase)*8;

    // ── Invisibilidade total (Fase 3) ─────────────────────────────
    if(b.phase>=3){
      if(b.invisible){
        b.invisibleT+=dt;
        if(b.invisibleT>=b.invisibleDur){
          b.invisible=false;
          b.invisTimer=rand(7,10);
          showTooltip('🐙👁️💥 Polvicullus reaparece em EMBOSCADA!');
          const flashEl=document.getElementById('polvicullus-emergency-flash');
          if(flashEl){flashEl.style.opacity='1';setTimeout(()=>{flashEl.style.opacity='0';},400);}
          // Emboscada: 3 tentáculos aleatórios entram em telegraph
          // simultâneo assim que o boss reaparece — pune quem ficou
          // parado esperando o retorno em vez de reposicionar.
          const idxs=[...Array(b.tentacles.length).keys()].sort(()=>Math.random()-0.5).slice(0,3);
          idxs.forEach(idx=>{
            const tn=b.tentacles[idx];
            tn.state='telegraph';tn.stateT=0;tn.cooldown=rand(1.4,3.2)/b.speedMult;
          });
        }
      } else {
        b.invisTimer-=dt;
        if(b.invisTimer<=0){
          b.invisible=true; b.invisibleT=0;
          showTooltip('🐙💨 Polvicullus desaparece por completo!');
        }
      }
    }

    // Enquanto invisível, tentáculos e corpo ficam ociosos/parados —
    // nenhum ataque visível é disparado (tudo some junto, como pedido).
    if(!b.invisible){
      // ── Tentáculos independentes: chicotadas automáticas em astros ──
      b.tentacles.forEach(tn=>{
        tn.stateT+=dt;
        tn.phase+=dt*tn.speed*b.speedMult;
        switch(tn.state){
          case 'idle':{
            tn.tipX=tn.restX+Math.sin(tn.phase*1.3)*10;
            tn.tipY=tn.restY+Math.cos(tn.phase*1.1)*6;
            tn.cooldown-=dt;
            if(tn.cooldown<=0){
              tn.cooldown=rand(1.4,3.2)/b.speedMult;
              tn.state='telegraph'; tn.stateT=0;
            }
            break;
          }
          case 'telegraph':{
            // Tentáculo se retrai e treme antes de chicotear —
            // dá ao jogador uma janela real pra reagir/afastar o astro.
            const dur=0.42/b.speedMult;
            const p=clamp(tn.stateT/dur,0,1);
            const shake=Math.sin(tn.stateT*40)*4*(1-p*0.3);
            tn.tipX=tn.restX*(1-0.35*p)+shake;
            tn.tipY=tn.restY*(1-0.35*p);
            if(p>=1){ tn.state='whipping'; tn.stateT=0; tn._hit=false; }
            break;
          }
          case 'whipping':{
            // Chicotada rápida pra frente/baixo — destrói astros
            // próximos automaticamente ao acertar (sem precisar mirar).
            const dur=0.32/b.speedMult;
            const p=clamp(tn.stateT/dur,0,1);
            if(p<0.35){
              const back=p/0.35;
              tn.tipX=tn.restX*(1-0.4*back);
              tn.tipY=tn.restY*(1-0.4*back);
            } else {
              const fwd=(p-0.35)/0.65;
              tn.tipX=tn.restX*(0.6+1.5*fwd);
              tn.tipY=tn.restY*(0.6+1.9*fwd);
              if(fwd>0.8&&!tn._hit){ tn._hit=true; _tentacleWhipImpact(tn); }
            }
            if(p>=1){ tn.state='retracting'; tn.stateT=0; }
            break;
          }
          case 'retracting':{
            const dur=0.35/b.speedMult;
            const p=clamp(tn.stateT/dur,0,1);
            const ease=p*p*(3-2*p);
            tn.tipX=tn.tipX+(tn.restX-tn.tipX)*ease*0.4;
            tn.tipY=tn.tipY+(tn.restY-tn.tipY)*ease*0.4;
            if(p>=1){ tn.state='idle'; tn.stateT=0; tn.tipX=tn.restX; tn.tipY=tn.restY; }
            break;
          }
        }
      });

      // ── Lasers pelos olhos (todas as fases, mais frequentes depois) ──
      b.laserTimer-=dt;
      if(b.laserTimer<=0){
        const [lo,hi]=b.laserCd[b.phase]||b.laserCd[1];
        b.laserTimer=rand(lo,hi);
        _fireEyeLasers();
      }

      // ── Mini-polvos (Fase 2+) ─────────────────────────────────────
      if(b.phase>=2){
        b.miniSpawnTimer-=dt;
        if(b.miniSpawnTimer<=0){
          b.miniSpawnTimer=rand(4,6.5)/(b.phase>=3?1.15:1);
          _spawnMiniOctopusWave();
        }
        // ── Jato de tinta: nuvem que se expande sobre uma área e
        // atrapalha astros dentro dela (lentidão), tensão diferente
        // dos ataques diretos — obriga o jogador a reposicionar. ──
        b.inkTimer-=dt;
        if(b.inkTimer<=0){
          b.inkTimer=rand(6,9)/(b.phase>=3?1.2:1);
          _fireInkJet();
        }
      }
    }

    // ── Nuvens de tinta ativas: expandem, atrasam astros, dissipam ──
    _inkClouds=_inkClouds.filter(ic=>{
      ic.age+=dt;
      const grow=Math.min(1,ic.age/0.6);
      ic.r=ic.maxR*grow;
      if(typeof objects!=='undefined'&&typeof screenToWorld==='function'){
        const wc=screenToWorld(ic.x,ic.y);
        objects.forEach(o=>{
          if(o.dead)return;
          if(Math.hypot(o.x-wc.x,o.y-wc.y)<=ic.r){
            o._pvInkSlow=0.35; // atrasa (não paralisa) — reduz velocidade por 0.35s a cada contato
            if(o.vx!==undefined)o.vx*=0.92;
            if(o.vy!==undefined)o.vy*=0.92;
          }
        });
      }
      return ic.age<ic.maxAge;
    });

    if(b.flashT>0)b.flashT=Math.max(0,b.flashT-dt);
  }

  // ── Chicotada de tentáculo: destrói astros próximos automaticamente ──
  function _tentacleWhipImpact(tn){
    const b=_boss;
    const wx=b.x+tn.tipX, wy=b.y+tn.tipY;
    for(let i=0;i<12;i++){
      _fxParticles.push({
        x:wx,y:wy,vx:rand(-100,100),vy:rand(-100,100),r:rand(2,5),alpha:1,
        color:'#fff6cc',life:0.5,maxLife:0.5,
      });
    }
    // Dano aos astros do MUNDO próximos ao ponto de impacto (chicotada
    // automática, sem precisar acertar o jogador). Usa o mesmo padrão
    // _invasionHP das outras Invasões em vez de matar na hora — dá
    // uma chance do jogador reagir antes do astro ser destruído.
    // IMPORTANTE: varre apenas `objects` (astros do jogador) — nunca
    // `_miniOctopi` (os próprios minions do Polvicullus), que morrem
    // apenas em _explodeMiniOctopus (ao chegar no alvo ou expirar).
    if(typeof objects!=='undefined'){
      const worldPt=typeof screenToWorld==='function'?screenToWorld(wx,wy):null;
      if(worldPt){
        const range=70;
        objects.forEach(o=>{
          if(o.dead)return;
          if(Math.hypot(o.x-worldPt.x,o.y-worldPt.y)<=range){
            if(o._invasionHP===undefined)o._invasionHP=100;
            o._invasionHP=Math.max(0,o._invasionHP-rand(35,55)*_boss.atkMult);
            if(o._invasionHP<=0){
              o.dead=true;
              if(typeof spawnExplosion==='function')spawnExplosion(o.x,o.y,0.35,false);
            }
          }
        });
      }
    }
    if(typeof _cosmicDamagePlayerAt==='function'){
      _cosmicDamagePlayerAt(wx,wy,55,70*_boss.atkMult);
    }
  }

  // ── Lasers pelos olhos ──────────────────────────────────────────
  function _fireEyeLasers(){
    const b=_boss;
    const eyeOffsets=[-1,1];
    // Posição alinhada exatamente com os olhos desenhados em _drawBoss:
    // ex = side*baseHalfW*0.78 (baseHalfW = mantleRX*0.5)
    // ey = baseY*0.72 (baseY = mantleRY*0.92) — perto da base do manto,
    // não do topo/testa.
    eyeOffsets.forEach(side=>{
      const ex=b.x+side*(b.mantleRX*0.5)*0.78*b.sizeScale;
      const ey=b.y+(b.mantleRY*0.92)*0.72*b.sizeScale;
      const targetAngle=Math.PI/2+rand(-0.35,0.35);
      _lasers.push({
        x:ex,y:ey,
        angle:targetAngle,
        len:0,maxLen:Math.max(_arenaRect.h,_arenaRect.w),
        life:0.5,maxLife:0.5,
        dmg:50*b.atkMult,
        width:4+2*(b.phase-1),
      });
    });
    showTooltip('🐙👁️ Lasers oculares disparados!');
  }

  // ── Jato de tinta: nuvem que se expande sobre um ponto do campo,
  // atrasando (não destruindo) astros que fiquem dentro dela — ataque
  // de controle de área, diferente dos ataques diretos de dano. ──
  function _fireInkJet(){
    const b=_boss;
    const ar=_arenaRect;
    const tx=rand(ar.x+ar.w*0.15,ar.x+ar.w*0.85);
    const ty=rand(ar.y+ar.h*0.15,ar.y+ar.h*0.85);
    _inkClouds.push({x:tx,y:ty,r:0,maxR:rand(70,100)*b.sizeScale,age:0,maxAge:3.2});
    showTooltip('🐙🖤 Polvicullus dispara um jato de tinta!');
  }

  function _tickLasers(dt){
    for(let i=_lasers.length-1;i>=0;i--){
      const l=_lasers[i];
      l.life-=dt;
      l.len=Math.min(l.maxLen,l.len+l.maxLen*dt/0.15);
      if(l.life<=0){ _lasers.splice(i,1); continue; }
      if(typeof _cosmicDamagePlayerAt==='function'){
        const midX=l.x+Math.cos(l.angle)*l.len*0.5;
        const midY=l.y+Math.sin(l.angle)*l.len*0.5;
        if(_cosmicPointNearPlayer(midX,midY,40)){
          _cosmicDamagePlayerAt(midX,midY,40,l.dmg*dt*4);
        }
      }
    }
  }

  // ── Mini-polvos: spawnam ao redor do boss, avançam até um astro-alvo ──
  function _spawnMiniOctopusWave(){
    const b=_boss;
    const count=b.phase>=3?4:2;
    const ar=_arenaRect;
    for(let i=0;i<count;i++){
      // Ângulo restrito à metade SUPERIOR (longe do arco inferior onde
      // os tentáculos vivem e chicoteiam) — evita que o mini-polvo
      // nasça/passe bem em cima da área de ataque do tentáculo e pareça
      // ter sido "chicoteado" pelo próprio Polvicullus sem motivo.
      const a=Math.PI*1.08+rand(0,Math.PI*0.84); // arco superior, sentido tela (Y+ pra baixo)
      const dist=rand(110,170)*b.sizeScale;
      const sx=b.x+Math.cos(a)*dist, sy=b.y+Math.sin(a)*dist;
      // Alvo: astro real do mundo mais PRÓXIMO do ponto de nascimento
      // (antes era um astro aleatório qualquer, o que fazia o mini-polvo
      // ir pro canto/longe atrás de um alvo distante). Sem astro vivo
      // por perto, mira o centro da arena como fallback.
      let targetWorld=null;
      if(typeof objects!=='undefined'&&objects.length&&typeof worldToScreen==='function'){
        let bestD=Infinity;
        for(let k=0;k<objects.length;k++){
          const o=objects[k];
          if(o.dead)continue;
          const s=worldToScreen(o.x,o.y);
          const d=Math.hypot(s.x-sx,s.y-sy);
          if(d<bestD){bestD=d;targetWorld=o;}
        }
      }
      _miniOctopi.push({
        x:sx,y:sy,
        targetObj:targetWorld,
        // Sem astro-alvo: mira o CENTRO da arena (antes era um ponto
        // aleatório qualquer dentro dela).
        targetX:ar.x+ar.w/2,
        targetY:ar.y+ar.h/2,
        speed:rand(70,110)*b.speedMult,
        r:10,
        phase:rand(0,Math.PI*2),
        life:9,
        exploded:false,
      });
    }
  }

  function _tickMiniOctopi(dt){
    for(let i=_miniOctopi.length-1;i>=0;i--){
      const m=_miniOctopi[i];
      m.life-=dt; m.phase+=dt*5;
      // Se o alvo morreu/sumiu, procura outro astro vivo mais próximo
      // em vez de simplesmente cair pro centro fixo da arena (o que
      // fazia o mini-polvo "grudar" num canto sem atacar mais nada).
      if((!m.targetObj||m.targetObj.dead)&&typeof objects!=='undefined'&&objects.length&&typeof worldToScreen==='function'){
        let bestD=Infinity,best=null;
        for(let k=0;k<objects.length;k++){
          const o=objects[k];
          if(o.dead)continue;
          const s=worldToScreen(o.x,o.y);
          const d=Math.hypot(s.x-m.x,s.y-m.y);
          if(d<bestD){bestD=d;best=o;}
        }
        m.targetObj=best;
      }
      let tx=m.targetX, ty=m.targetY;
      if(m.targetObj&&!m.targetObj.dead&&typeof worldToScreen==='function'){
        const s=worldToScreen(m.targetObj.x,m.targetObj.y);
        tx=s.x; ty=s.y;
      }
      const dx=tx-m.x, dy=ty-m.y, dist=Math.hypot(dx,dy)||1;
      m.x+=dx/dist*m.speed*dt;
      m.y+=dy/dist*m.speed*dt;
      // Trava o mini-polvo dentro da arena — nunca deixa sair da tela.
      if(_arenaRect){
        const ar2=_arenaRect, pad=m.r;
        if(m.x<ar2.x+pad)m.x=ar2.x+pad;
        if(m.x>ar2.x+ar2.w-pad)m.x=ar2.x+ar2.w-pad;
        if(m.y<ar2.y+pad)m.y=ar2.y+pad;
        if(m.y>ar2.y+ar2.h-pad)m.y=ar2.y+ar2.h-pad;
      }
      const closeEnough=dist<24;
      if((closeEnough||m.life<=0)&&!m.exploded){
        m.exploded=true;
        _explodeMiniOctopus(m);
        _miniOctopi.splice(i,1);
      }
    }
  }

  function _explodeMiniOctopus(m){
    for(let i=0;i<14;i++){
      _fxParticles.push({
        x:m.x,y:m.y,vx:rand(-120,120),vy:rand(-120,120),r:rand(2,6),alpha:1,
        color:Math.random()<0.5?'#fff3b0':'#ffd23f',life:0.6,maxLife:0.6,
      });
    }
    if(m.targetObj&&!m.targetObj.dead){ m.targetObj.dead=true; }
    if(typeof _cosmicDamagePlayerAt==='function'){
      _cosmicDamagePlayerAt(m.x,m.y,30,40*(_boss?_boss.atkMult:1));
    }
  }

  function _cosmicPointNearPlayer(x,y,range){
    const ar=_arenaRect; if(!ar)return false;
    const px=ar.x+ar.w/2, py=ar.y+ar.h*0.92;
    return Math.hypot(x-px,y-py)<=range;
  }

  function _tickFx(dt){
    for(let i=_fxParticles.length-1;i>=0;i--){
      const p=_fxParticles[i];
      p.life-=dt; p.x+=p.vx*dt; p.y+=p.vy*dt; p.vy+=40*dt;
      p.alpha=Math.max(0,p.life/p.maxLife);
      if(p.life<=0)_fxParticles.splice(i,1);
    }
  }

  // ── Desenho ──────────────────────────────────────────────────────
  function _drawArenaBorder(c,t){
    if(!_arenaRect)return;
    const ar=_arenaRect;
    const {x,y,w,h}=ar; const x2=x+w, y2=y+h;
    const pulse=.55+.45*Math.sin(t*2.5);
    const alpha=.5+.35*Math.sin(t*3.1);
    c.save();
    // Borda principal sólida (substitui o tracejado genérico)
    c.strokeStyle=`rgba(255,210,60,${alpha})`;
    c.lineWidth=2.5;
    c.strokeRect(x,y,w,h);
    // Borda interna fina
    c.strokeStyle=`rgba(255,235,150,${alpha*.35})`;
    c.lineWidth=1;
    c.strokeRect(x+4,y+4,w-8,h-8);
    // Cantos reforçados em L — halo falso (2 passes, sem shadowBlur)
    const cs=22;
    const corners=[
      [[x,y+cs],[x,y],[x+cs,y]],
      [[x2-cs,y],[x2,y],[x2,y+cs]],
      [[x,y2-cs],[x,y2],[x+cs,y2]],
      [[x2-cs,y2],[x2,y2],[x2,y2-cs]],
    ];
    corners.forEach(pts=>{
      c.beginPath();
      c.moveTo(pts[0][0],pts[0][1]);c.lineTo(pts[1][0],pts[1][1]);c.lineTo(pts[2][0],pts[2][1]);
      c.strokeStyle=`rgba(255,200,40,${.18*(.8+.2*pulse)})`;c.lineWidth=8;c.stroke();
      c.strokeStyle=`rgba(255,200,40,${.8+.2*pulse})`;c.lineWidth=3.2;c.stroke();
    });
    // Partículas esporádicas na borda (glitch sutil)
    if(Math.random()<0.18){
      const side=Math.floor(Math.random()*4);
      let px,py;
      if(side===0){px=rand(x,x2);py=y;}
      else if(side===1){px=x2;py=rand(y,y2);}
      else if(side===2){px=rand(x,x2);py=y2;}
      else{px=x;py=rand(y,y2);}
      c.beginPath();c.arc(px,py,rand(1.5,4),0,Math.PI*2);
      c.fillStyle=`rgba(255,220,100,${rand(.4,.9)})`;c.fill();
    }
    c.restore();
  }

  function _drawTentacle(ctx,b,tn){
    const scale=b.sizeScale;
    // Ponto de ancoragem alinhado com a base REAL do manto (onde o
    // corpo termina visualmente, baseY=mantleRY*0.92 em _drawBoss),
    // e mais concentrado perto do centro horizontal — antes as bases
    // nasciam bem abaixo e espalhadas, soltas do corpo.
    const mantleBottomY=b.mantleRY*scale*0.92;
    const bx=Math.cos(tn.baseAngle)*b.mantleRX*scale*0.22;
    const by=mantleBottomY-b.mantleRY*scale*0.06;
    const reach=1.55;
    const tx=tn.tipX*scale*reach, ty=tn.tipY*scale*reach;
    // ── Durante a morte, os tentáculos balançam com amplitude maior
    // (mais "vida"/agitação visual), em vez de encolher/murchar. ──
    const swingBoost=b.dying?1+Math.min(1,b.dyingT/4.5)*1.8:1;
    const elbowX=bx+(tx-bx)*0.4+Math.sin(tn.phase*1.6)*22*tn.curl*swingBoost;
    const elbowY=by+(ty-by)*0.4+Math.cos(tn.phase*1.3)*14*tn.curl*swingBoost;
    const wristX=bx+(tx-bx)*0.75+Math.cos(tn.phase*1.9)*26*tn.curl*swingBoost;
    const wristY=by+(ty-by)*0.75+Math.sin(tn.phase*1.9)*16*tn.curl*swingBoost;
    const curlX=tx+Math.cos(tn.phase*2.3)*14*tn.curl*swingBoost;
    const curlY=ty+Math.sin(tn.phase*2.3)*14*tn.curl*swingBoost;

    // Base mais grossa afunilando pra ponta — mas como UMA ÚNICA
    // curva bezier contínua passando pelos 4 pontos de controle do
    // movimento, sem segmentos retos entre eles. Isso elimina a
    // leitura de "cotovelos"/juntas de inseto e passa a impressão de
    // um músculo único se curvando, como um tentáculo real.
    const widthBase=(Math.max(9,17-tn.idx%3))*scale;

    ctx.save();
    ctx.translate(b.x,b.y);
    ctx.lineCap='round';
    ctx.lineJoin='round';

    // Curva-guia única (Catmull-Rom simplificado via bezier encadeado)
    // usada tanto pro contorno quanto pro preenchimento gradual —
    // um só traçado do início ao fim, sem pontas quebradas.
    const drawSpine=(w0,w1,color,glow)=>{
      const steps=24;
      const pts=[];
      for(let i=0;i<=steps;i++){
        const p=i/steps;
        // interpolação suave em cadeia (bx->elbow->wrist->curl) via
        // De Casteljau cúbico, gerando UMA curva sem quinas
        const ax=(1-p)*(1-p)*(1-p)*bx+3*(1-p)*(1-p)*p*elbowX+3*(1-p)*p*p*wristX+p*p*p*curlX;
        const ay=(1-p)*(1-p)*(1-p)*by+3*(1-p)*(1-p)*p*elbowY+3*(1-p)*p*p*wristY+p*p*p*curlY;
        pts.push([ax,ay,w0+(w1-w0)*p]);
      }
      if(glow){ctx.shadowColor=glow;ctx.shadowBlur=6;}
      for(let i=0;i<pts.length-1;i++){
        const p=i/(pts.length-1);
        ctx.beginPath();
        ctx.moveTo(pts[i][0],pts[i][1]);
        ctx.lineTo(pts[i+1][0],pts[i+1][1]);
        ctx.lineWidth=pts[i][2];
        ctx.strokeStyle=color;
        ctx.stroke();
      }
      ctx.shadowBlur=0;
      return pts;
    };

    // Flash de dano: quando o manto pisca (b.flashT>0), os tentáculos
    // acompanham a mesma cor de flash, em vez de ficarem só dourados.
    const _hit=b.flashT>0;
    const _fc=b.flashColor||'#ff0000';

    // Contorno externo suave (leve sombra por baixo do corpo do braço)
    drawSpine(widthBase+3,widthBase*0.14,_hit?_fc:'rgba(150,110,30,0.4)',null);

    // Corpo principal: dourado claro e vivo, combinando com o manto —
    // um só traçado contínuo, sem quebra de cor abrupta entre segmentos.
    const pts=drawSpine(widthBase,widthBase*0.22,_hit?_fc:'#f2c94c',null);
    // reforço de brilho na metade final, mais claro ainda, sem
    // reiniciar a curva (evita a leitura de "novo segmento")
    ctx.save();
    ctx.beginPath();
    for(let i=Math.floor(pts.length*0.45);i<pts.length;i++){
      const[px,py]=pts[i];
      if(i===Math.floor(pts.length*0.45))ctx.moveTo(px,py);else ctx.lineTo(px,py);
    }
    ctx.lineWidth=widthBase*0.32;
    ctx.strokeStyle=_hit?_fc:'#fbe38a';
    ctx.shadowColor=_hit?_fc:'rgba(255,230,150,0.6)';
    ctx.shadowBlur=6;
    ctx.stroke();
    ctx.shadowBlur=0;
    ctx.restore();
    // Veia central laranja removida a pedido — corpo do tentáculo
    // (contorno + preenchimento + brilho) e ventosas permanecem.

    // Ventosas — pequenas e sutis, acompanhando a curva única.
    for(let s=1;s<=8;s++){
      const p=s/9;
      const idx=Math.round(p*(pts.length-1));
      const[qx,qy,qw]=pts[idx];
      const sr=Math.max(1.2,qw*0.32);
      ctx.beginPath();
      ctx.arc(qx,qy,sr,0,Math.PI*2);
      ctx.strokeStyle=_hit?_fc:'rgba(150,105,30,0.55)';
      ctx.lineWidth=1;
      ctx.stroke();
      ctx.beginPath();
      ctx.arc(qx,qy,sr*0.4,0,Math.PI*2);
      ctx.fillStyle=_hit?_fc:'rgba(180,120,30,0.6)';
      ctx.fill();
    }
    // Aviso de telegraph: anel pulsante vermelho na ponta, avisando
    // a chicotada iminente — dá ao jogador uma referência visual clara
    // de onde e quando o impacto vai acontecer.
    if(tn.state==='telegraph'){
      const pulse=0.5+0.5*Math.sin(tn.stateT*30);
      ctx.beginPath();
      ctx.arc(curlX,curlY,10+4*pulse,0,Math.PI*2);
      ctx.strokeStyle=`rgba(255,60,40,${0.5+0.4*pulse})`;
      ctx.lineWidth=2;
      ctx.stroke();
    }
    ctx.restore();
  }

  function _drawBoss(ctx,b,t){
    // Nuvens de tinta: desenhadas antes de tudo (fundo), mesmo se o
    // boss estiver invisível — o ataque de área continua ativo.
    _inkClouds.forEach(ic=>{
      const a=Math.min(1,ic.age/0.4)*(1-Math.max(0,ic.age-ic.maxAge+0.8)/0.8);
      ctx.save();
      ctx.beginPath();ctx.arc(ic.x,ic.y,ic.r,0,Math.PI*2);
      ctx.fillStyle=`rgba(20,10,30,${a*0.5})`;ctx.fill();
      ctx.strokeStyle=`rgba(120,60,160,${a*0.4})`;ctx.lineWidth=2;ctx.stroke();
      ctx.restore();
    });

    // Fase 3 invisível: nada é desenhado — corpo E tentáculos somem
    // completamente juntos.
    if(b.invisible)return;

    // ── Sequência de morte: o corpo NÃO encolhe/murcha (mantém a
    // presença de boss); só um leve tremor de posição, olhos viram um
    // "X" no final e os tentáculos balançam mais forte (ver
    // _drawTentacle, que já lê b.dying/b.dyingT para isso). ──
    let shakeX=0, shakeY=0, dyingDark=0;
    if(b.dying){
      const p=Math.min(1,b.dyingT/4.5);
      const shakeAmt=p<0.75?(p/0.75)*4:4*(1-((p-0.75)/0.25));
      shakeX=rand(-shakeAmt,shakeAmt); shakeY=rand(-shakeAmt,shakeAmt);
      dyingDark=p; // escurece levemente conforme perde energia
    }

    const scale=b.sizeScale;

    // Sombra de contato escura embaixo — dá peso/presença ameaçadora
    // em vez do boss "flutuar leve" sem massa.
    ctx.save();
    ctx.translate(b.x+shakeX,b.y+shakeY+b.mantleRY*scale*0.92);
    ctx.scale(1,0.28);
    if(_shadowGradCache===null||_shadowGradScale!==scale){
      _shadowGradCache=ctx.createRadialGradient(0,0,0,0,0,b.mantleRX*scale*1.3);
      _shadowGradCache.addColorStop(0,'rgba(0,0,0,0.45)');
      _shadowGradCache.addColorStop(1,'rgba(0,0,0,0)');
      _shadowGradScale=scale;
    }
    ctx.beginPath();ctx.arc(0,0,b.mantleRX*scale*1.3,0,Math.PI*2);
    ctx.fillStyle=_shadowGradCache;ctx.fill();
    ctx.restore();

    ctx.save();
    ctx.translate(shakeX,shakeY);
    b.tentacles.forEach(tn=>_drawTentacle(ctx,b,tn));
    ctx.restore();

    ctx.save();
    if(b.dying&&dyingDark>0){
      // Leve perda de brilho conforme a morte avança — sem encolher,
      // só uma redução sutil de opacidade para reforçar "perdendo energia".
      ctx.globalAlpha=1-dyingDark*0.2;
    }
    ctx.translate(b.x+shakeX,b.y+shakeY);
    const squish=1+Math.sin(b.bobPhase)*0.03;
    ctx.scale(scale,scale*squish);

    // Brilho externo: mais estreito e "quente" (âmbar), não um halo
    // suave difuso — reforça sensação de calor/energia hostil.
    const glow=0.5+0.35*Math.sin(b.glowPulse);
    ctx.save();
    const outerGlow=ctx.createRadialGradient(0,0,b.mantleRX*0.6,0,0,b.mantleRX*1.7);
    outerGlow.addColorStop(0,`rgba(255,200,80,${0.3*glow})`);
    outerGlow.addColorStop(1,'rgba(255,200,80,0)');
    ctx.beginPath();ctx.ellipse(0,0,b.mantleRX*1.7,b.mantleRY*1.7,0,0,Math.PI*2);
    ctx.fillStyle=outerGlow;ctx.fill();
    ctx.restore();

    // Cabeça: DOIS POLÍGONOS SIMPLES, de lados retos, unidos numa
    // aresta horizontal comum — losango comum embaixo unido a um
    // trapézio comum acima dele... não, ao contrário: TRAPÉZIO comum
    // (base, onde os tentáculos se conectam) embaixo, LOSANGO comum
    // (2x mais alto que o trapézio) em cima. Vértices retos, cantos
    // só com raio pequeno pra não ficar 100% angular. Olhos na
    // aresta de junção (vértices laterais do losango = topo do
    // trapézio). Baseado no traçado de referência do usuário.
    const rx=b.mantleRX, ry=b.mantleRY;
    // Cabeça: UMA ÚNICA forma contínua tipo ovo — sem trapézio e
    // oval separados, sem costura visível. Mais largo na metade
    // inferior (bojo), afinando suave e arredondado até o topo,
    // e afinando de leve na base onde os tentáculos se conectam.
    // Geometria verificada visualmente por render próprio antes de
    // aplicar aqui (comparada às referências do usuário).
    const topY=-ry*1.0;
    const bulgeY=ry*0.02;
    const baseY=ry*0.92;
    const bulgeHalfW=rx*0.88;
    const baseHalfW=rx*0.5;

    const mantlePath=new Path2D();
    mantlePath.moveTo(0,topY);
    mantlePath.bezierCurveTo(bulgeHalfW*0.65,topY+ry*0.12, bulgeHalfW*0.98,bulgeY-ry*0.4, bulgeHalfW,bulgeY);
    mantlePath.bezierCurveTo(bulgeHalfW*0.9,bulgeY+ry*0.4, baseHalfW*0.92,baseY-ry*0.3, baseHalfW,baseY);
    mantlePath.quadraticCurveTo(baseHalfW*0.5,baseY+ry*0.06, 0,baseY+ry*0.06);
    mantlePath.quadraticCurveTo(-baseHalfW*0.5,baseY+ry*0.06, -baseHalfW,baseY);
    mantlePath.bezierCurveTo(-baseHalfW*0.92,baseY-ry*0.3, -bulgeHalfW*0.9,bulgeY+ry*0.4, -bulgeHalfW,bulgeY);
    mantlePath.bezierCurveTo(-bulgeHalfW*0.98,bulgeY-ry*0.4, -bulgeHalfW*0.65,topY+ry*0.12, 0,topY);
    mantlePath.closePath();

    if(_mantleGradCache===null||_mantleGradScale!==scale){
      _mantleGradCache=ctx.createRadialGradient(-rx*0.08,-ry*0.4,rx*0.1,0,0,ry*1.1);
      _mantleGradCache.addColorStop(0,'#ffe94a');
      _mantleGradCache.addColorStop(0.6,'#f5c520');
      _mantleGradCache.addColorStop(1,'#d99a08');
      _mantleGradScale=scale;
    }
    ctx.fillStyle=b.flashT>0?b.flashColor:_mantleGradCache;
    ctx.shadowColor='rgba(255,220,90,0.6)';
    ctx.shadowBlur=14;
    ctx.fill(mantlePath);
    ctx.shadowBlur=0;
    ctx.strokeStyle='rgba(130,90,15,0.5)';
    ctx.lineWidth=2;
    ctx.stroke(mantlePath);

    // Estrelinhas decorativas no terço superior do manto.
    ctx.save();
    ctx.clip(mantlePath);
    const stars=[[-0.16,-0.55,0.02],[0.18,-0.68,0.015],[0.02,-0.42,0.017],[-0.03,-0.8,0.012]];
    ctx.strokeStyle='rgba(255,250,225,0.75)';
    ctx.lineWidth=1.6;
    ctx.lineCap='round';
    stars.forEach(([sx,sy,sr])=>{
      const cx=sx*rx, cy=sy*ry, s=sr*rx*2.2;
      ctx.beginPath();
      ctx.moveTo(cx-s,cy);ctx.lineTo(cx+s,cy);
      ctx.moveTo(cx,cy-s);ctx.lineTo(cx,cy+s);
      ctx.stroke();
    });

    // No último instante da sequência de morte (dyingT/4.5 >= 0.8):
    // os olhos somem e são substituídos por um "X" branco, de uma vez
    // (teleporta) — sem fade-in nem crescimento gradual.
    const deathTriggered=b.dying&&(Math.min(1,b.dyingT/4.5)>=0.8);

    // Olhos normais: só desenhados enquanto o X ainda não apareceu.
    if(!deathTriggered){
      const eyeLen=rx*0.13;
      [-1,1].forEach(side=>{
        const ex=side*baseHalfW*0.78, ey=baseY*0.72;
        ctx.save();
        ctx.translate(ex,ey);
        ctx.rotate(side*0.22);
        ctx.beginPath();
        ctx.moveTo(0,-eyeLen*0.9);
        ctx.quadraticCurveTo(eyeLen*0.42,-eyeLen*0.1,eyeLen*0.3,eyeLen*0.55);
        ctx.quadraticCurveTo(eyeLen*0.16,eyeLen*0.95,0,eyeLen*0.95);
        ctx.quadraticCurveTo(-eyeLen*0.16,eyeLen*0.95,-eyeLen*0.3,eyeLen*0.55);
        ctx.quadraticCurveTo(-eyeLen*0.42,-eyeLen*0.1,0,-eyeLen*0.9);
        ctx.closePath();
        ctx.fillStyle='rgba(235,140,25,0.95)';
        ctx.fill();
        ctx.beginPath();
        ctx.arc(0,eyeLen*0.2,eyeLen*0.22,0,Math.PI*2);
        ctx.fillStyle='rgba(30,15,5,0.95)';
        ctx.fill();
        ctx.restore();
      });
    }

    let _deathXParams=null;
    if(deathTriggered){
      // X esticado HORIZONTALMENTE, centralizado na mesma altura e
      // posição dos olhos (ex=±baseHalfW*0.78) — só minimamente maior
      // que a distância dos olhos até as bordas. Aparece de uma vez
      // (teleporta), sem fade-in gradual nem crescimento.
      const eyeX=baseHalfW*0.78;
      _deathXParams={
        cy:baseY*0.72, xw:eyeX*1.12, xh:rx*0.09,
        lineW:Math.max(2,rx*0.06),
      };
    }

    ctx.restore(); // clip

    if(_deathXParams){
      const{cy,xw,xh,lineW}=_deathXParams;
      ctx.save();
      ctx.strokeStyle='#ffffff';
      ctx.lineWidth=lineW;
      ctx.lineCap='round';
      ctx.beginPath();
      ctx.moveTo(-xw,cy-xh);ctx.lineTo(xw,cy+xh);
      ctx.moveTo(-xw,cy+xh);ctx.lineTo(xw,cy-xh);
      ctx.stroke();
      ctx.restore();
    }

    ctx.restore(); // manto
  }

  function _drawLasers(ctx){
    _lasers.forEach(l=>{
      const ex=l.x+Math.cos(l.angle)*l.len;
      const ey=l.y+Math.sin(l.angle)*l.len;
      ctx.save();
      ctx.globalAlpha=Math.min(1,l.life/0.15);
      const grad=ctx.createLinearGradient(l.x,l.y,ex,ey);
      grad.addColorStop(0,'#fffde0');
      grad.addColorStop(1,'#ffde5c');
      ctx.strokeStyle=grad;
      ctx.lineWidth=l.width;
      ctx.beginPath();ctx.moveTo(l.x,l.y);ctx.lineTo(ex,ey);ctx.stroke();
      ctx.restore();
    });
  }

  function _drawMiniOctopi(ctx){
    _miniOctopi.forEach(m=>{
      ctx.save();
      ctx.translate(m.x,m.y);
      const wob=Math.sin(m.phase)*2;
      const r=m.r;

      // Mesmo estilo do boss adulto, em miniatura: manto ovalado
      // âmbar/dourado com gradiente radial, 6 tentáculos afunilados
      // em leque saindo da base (bezier simples, não mais palitos
      // retos), e olhos em gota âmbar — lembrando um polvo de verdade
      // em vez do oval genérico com 4 pernas da versão anterior.
      ctx.save();
      ctx.translate(0,wob*0.3);
      ctx.rotate(wob*0.02);

      const tentCount=6;
      for(let i=0;i<tentCount;i++){
        const a=(i/(tentCount-1))*Math.PI*0.72-Math.PI*0.36;
        const spread=Math.sin(m.phase*1.4+i)*0.12;
        const baseX=Math.sin(a)*r*0.5, baseY=r*0.55;
        const midX=Math.sin(a+spread)*r*1.15, midY=r*1.35+Math.cos(m.phase+i)*r*0.15;
        const tipX=Math.sin(a+spread*1.6)*r*1.5, tipY=r*2.05+Math.sin(m.phase*1.2+i)*r*0.18;
        ctx.beginPath();
        ctx.moveTo(baseX,baseY);
        ctx.quadraticCurveTo(midX,midY,tipX,tipY);
        ctx.lineWidth=Math.max(1.2,r*0.26);
        ctx.lineCap='round';
        ctx.strokeStyle='#f2c94c';
        ctx.stroke();
      }

      const grad=ctx.createRadialGradient(-r*0.2,-r*0.35,r*0.1,0,0,r*1.05);
      grad.addColorStop(0,'#ffe94a');
      grad.addColorStop(0.6,'#f5c520');
      grad.addColorStop(1,'#d99a08');
      ctx.beginPath();ctx.ellipse(0,0,r*0.85,r*1.05,0,0,Math.PI*2);
      ctx.fillStyle=grad;ctx.shadowColor='rgba(255,220,120,0.7)';ctx.shadowBlur=6;ctx.fill();ctx.shadowBlur=0;
      ctx.strokeStyle='rgba(130,90,15,0.5)';ctx.lineWidth=1;ctx.stroke();

      // Olhinhos em gota âmbar (mesma linguagem visual do boss).
      [-1,1].forEach(s=>{
        ctx.save();
        ctx.translate(s*r*0.32,r*0.12);
        ctx.rotate(s*0.2);
        const el=r*0.22;
        ctx.beginPath();
        ctx.moveTo(0,-el*0.9);
        ctx.quadraticCurveTo(el*0.42,-el*0.1,el*0.3,el*0.55);
        ctx.quadraticCurveTo(el*0.16,el*0.95,0,el*0.95);
        ctx.quadraticCurveTo(-el*0.16,el*0.95,-el*0.3,el*0.55);
        ctx.quadraticCurveTo(-el*0.42,-el*0.1,0,-el*0.9);
        ctx.closePath();
        ctx.fillStyle='rgba(235,140,25,0.95)';ctx.fill();
        ctx.beginPath();ctx.arc(0,el*0.2,el*0.28,0,Math.PI*2);
        ctx.fillStyle='rgba(30,15,5,0.95)';ctx.fill();
        ctx.restore();
      });

      ctx.restore();
      ctx.restore();
    });
  }

  function _drawFx(ctx){
    _fxParticles.forEach(p=>{
      ctx.beginPath();ctx.arc(p.x,p.y,Math.max(0.5,p.r),0,Math.PI*2);
      ctx.globalAlpha=p.alpha;ctx.fillStyle=p.color;ctx.fill();ctx.globalAlpha=1;
    });
  }

  // ── Dano ao boss por astros do Pacote Exótico colocados na arena ────
  // Substitui o antigo combate por toque direto (tryHitAt). Enquanto o
  // combate estiver ativo, apenas os 10 astros exóticos liberados em
  // POLVICULLUS_BLOCKED_ASTRO_TYPES (o resto é bloqueado) causam dano.
  // Mesmo modelo de _applyReptAstroEffectsToBoss (Invasão Reptiliana):
  // dano PERCENTUAL do HP máximo do boss por acerto + cooldown próprio
  // por astro (evita "evaporar" o HP em segundos). Cada acerto também
  // consome o _invasionHP do astro (padrão universal das Invasões) —
  // ele tem vida própria e um tempo de vida limitado
  // (_invasionVanishTimer), dissolvendo sozinho se não for destruído
  // antes pelos tentáculos/lasers do boss.
  function _tickPlayerAstroDamage(dt){
    if(!_boss||_boss.dying||_boss.invisible)return;
    if(typeof objects==='undefined')return;
    const b=_boss;
    const worldCenter=typeof screenToWorld==='function'?screenToWorld(b.x,b.y):null;
    if(!worldCenter)return;
    const hitRange=(b.mantleRX*1.6)*b.sizeScale/(typeof cam!=='undefined'&&cam.zoom?cam.zoom:1);
    objects.forEach(o=>{
      if(o.dead)return;
      const cfg=POLVICULLUS_SP_DAMAGE_CONFIG[o.type];
      if(!cfg)return;
      // Tempo de vida: dissolve sozinho ao expirar (mesmo padrão
      // _invasionVanishTimer usado nas outras Invasões).
      if(o._invasionVanishTimer===undefined)o._invasionVanishTimer=POLVICULLUS_ASTRO_LIFESPAN;
      o._invasionVanishTimer-=dt;
      if(o._invasionVanishTimer<=0){
        o.dead=true;
        if(typeof spawnExplosion==='function')spawnExplosion(o.x,o.y,0.3,false);
        return;
      }
      if(o._invasionHP===undefined)o._invasionHP=100;
      const d=Math.hypot(o.x-worldCenter.x,o.y-worldCenter.y);
      if(d>hitRange)return;
      const key='_pvDmgCd_'+o.id;
      if(o[key]>0){o[key]-=dt;return;}
      _damageBoss(_boss.maxHP*cfg.dmgPct);
      o[key]=cfg.cd;
      o._invasionHP=Math.max(0,o._invasionHP-cfg.selfDmg);
      if(o._invasionHP<=0&&!o.dead){
        o.dead=true;
        if(typeof spawnExplosion==='function')spawnExplosion(o.x,o.y,0.35,false);
      }
      if(Math.random()<0.5){
        _fxParticles.push({
          x:b.x+rand(-b.mantleRX*0.5,b.mantleRX*0.5),y:b.y+rand(-b.mantleRY*0.5,b.mantleRY*0.5),
          vx:rand(-40,40),vy:rand(-60,-10),r:rand(2,5),alpha:1,
          color:cfg.fxColor||'#fff6cc',life:0.4,maxLife:0.4,
        });
      }
    });
  }

  function _finish(victory,reason){
    _active=false;
    window._invasionActive=false;
    _stopPolvicullusAudio();
    _unlockCam(); // restaura o zoom original do jogador
    if(_animFrame){cancelAnimationFrame(_animFrame);_animFrame=null;}
    if(_riftCanvas)_riftCanvas.classList.remove('active');
    const bar=document.getElementById('polv-boss-hp-bar');
    if(bar)bar.classList.remove('active');
    _setInvasionAstroLockUI(false,POLVICULLUS_BLOCKED_ASTRO_TYPES);
    window._polvicullusAstroCaps=null;
    window._polvicullusResetUses=0;
    window._polvicullusMoveUses=0;
    if(typeof objects!=='undefined'){
      objects.forEach(o=>{
        if(POLVICULLUS_SP_DAMAGE_CONFIG[o.type]){
          delete o._invasionHP;delete o._invasionVanishTimer;
          Object.keys(o).forEach(k=>{if(k.indexOf('_pvDmgCd_')===0)delete o[k];});
        }
      });
    }
    // ── Restaura TODOS os astros antigos guardados no início da batalha ──
    objects.length=0;
    objects.push(..._preInvasionStash);
    _preInvasionStash=[];
    selectedObj=null;
    _lasers=[];_miniOctopi=[];_inkClouds=[];_fxParticles=[];
    if(victory){
      showTooltip('🐙🏆 Polvicullus Estelarus derrotado! O bioma Plasmícea se acalma...');
      if(typeof _markInvasionWon==='function')_markInvasionWon('polvicullus');
      if(typeof _cosmonarioDiscover==='function')_cosmonarioDiscover('bossPolvicullus');
      if(typeof _bossAchTrigger==='function')_bossAchTrigger('rei_estelar');
      // Recompensa de Logs por vitória — repetível a cada combate vencido.
      if(typeof addLogs==='function'){
        addLogs(1800);
        setTimeout(()=>showTooltip('📊 +1800 LOGS pela vitória!'),1400);
      }
      // Recompensa de Quantiks por vitória — repetível a cada combate vencido.
      if(typeof addQuantiks==='function'){
        addQuantiks(100);
        setTimeout(()=>showTooltip('⚛️ +100 Quantiks pela vitória!'),1900);
      }
    } else if(reason==='timeout'){
      // ── Tempo esgotado: recuo com flash vermelho, mesmo padrão das
      // outras Invasões (Alien/Reptiliana) ──
      const ef=document.getElementById('polvicullus-emergency-flash');
      if(ef){
        ef.style.background='radial-gradient(circle,rgba(255,30,30,.45) 0%,rgba(180,0,0,.18) 50%,transparent 80%)';
        ef.style.transition='opacity .3s';
        ef.style.opacity='1';
        setTimeout(()=>{
          ef.style.opacity='0';
          setTimeout(()=>{ef.style.background='radial-gradient(circle,rgba(255,220,80,.24) 0%,rgba(180,150,20,.09) 50%,transparent 80%)';},400);
        },900);
      }
      showTooltip('⏱️🐙 Tempo esgotado! Polvicullus Estelarus recuou para as profundezas...');
    }
    const cb=_onDefeatCb;_onDefeatCb=null;
    _boss=null;
    if(cb)cb(victory);
  }

  function forceEnd(){ if(_active)_finish(false); }

  // ── Utilitários de Mod Menu / testes ───────────────────────────────
  function forcePhase(n){
    if(!_active||!_boss||_boss.dying)return false;
    const target=n>=3?PHASE3_PCT*0.6:n===2?(PHASE2_PCT+PHASE3_PCT)/2:1;
    _boss.hp=Math.max(1,Math.round(_boss.maxHP*Math.min(target,0.999)));
    const newPhase=_getPhase(_boss.hp,_boss.maxHP);
    const enteringPhase3=newPhase===3&&_boss.phase!==3;
    _boss.phase=newPhase;
    _applyPhaseStats(_boss);
    if(enteringPhase3){
      _boss.sizeScale=1.22;
      _boss.invisTimer=rand(2,4);
    }
    _updateBar();
    return true;
  }
  function hitkill(){
    if(!_active||!_boss)return false;
    _boss.invisible=false; // garante que hitkill funcione mesmo invisível
    _damageBoss(_boss.hp+9999999);
    return true;
  }

  return { start, isActive, forceEnd, forcePhase, hitkill };
})();

// ═══════════════════════════════════════════════════════════════════
//  MÓDULO: BOSS CÓSMICO ROBÓTICA — Galaximy
// ═══════════════════════════════════════════════════════════════════
//  Etapa atual: visual + esqueleto de fases/HP, controlável via Mod
//  Menu (mesmo padrão do Polvicullus). Ataques/mecânicas de combate
//  entram numa etapa futura — por enquanto o boss só existe em tela,
//  se move levemente e reage a hitkill/forcePhase para testes visuais.
// ═══════════════════════════════════════════════════════════════════
const GalaximyBoss = (function(){
  let _active=false;
  let _boss=null;
  let _preInvasionStash=[]; // astros antigos guardados durante a batalha
  let _riftCanvas=null,_riftCtx=null;
  let _worldBounds=null;    // coords de MUNDO — arena real, maior que a câmera
  let _fxParticles=[];      // partículas de explosão (astro destruído pela lua)
  let _animFrame=null;
  let _lastTick=0;
  let _t=0;
  // ── Câmera: zoom fixo durante o combate — mesmo padrão robusto usado
  // nas invasões (Object.defineProperty com setter noop), evita que o
  // zoom do jogador antes da batalha deixe tudo minúsculo ou gigante.
  let _savedZoom=1;
  let _playerZoomBeforeBattle=1;
  let _camLocked=false;
  function _lockCam(){
    if(_camLocked)return;
    _playerZoomBeforeBattle=cam.zoom;
    _savedZoom=BATTLE_FIXED_ZOOM;
    try{Object.defineProperty(cam,'zoom',{get(){return _savedZoom;},set(){},configurable:true});}catch(e){}
    _camLocked=true;
  }
  function _unlockCam(){
    if(!_camLocked)return;
    try{Object.defineProperty(cam,'zoom',{value:_playerZoomBeforeBattle,writable:true,configurable:true});}catch(e){}
    _camLocked=false;
  }
  const _MARGIN=10;
  const ARENA_WORLD_SCALE=2.6; // arena bem maior que o viewport da câmera

  // ── Áudio do boss: songs/Invasions/Bosses/Galaximy.ogg em loop com
  // fade in/out, mesmo padrão do Polvicullus. ──
  let _galxBossAudio=null;
  let _galxBossAudioStopping=false;
  let _galxBossAudioFadeInterval=null;
  let _galxBossAudioVol=0;
  function _startGalaximyAudio(){
    if(_galxBossAudio)return;
    _galxBossAudioStopping=false;
    if(typeof _stopAudio==='function')_stopAudio();
    _galxBossAudio=new Audio('songs/Invasions/Bosses/Galaximy.ogg');
    _galxBossAudio.loop=false;
    _galxBossAudio.addEventListener('ended',function(){
      if(!_galxBossAudio||_galxBossAudioStopping)return;
      _galxBossAudio.currentTime=0;
      _galxBossAudio.play().catch(()=>{});
    });
    _galxBossAudioVol=0;
    _galxBossAudio.volume=0;
    _galxBossAudio.play().catch(()=>{});
    if(_galxBossAudioFadeInterval){clearInterval(_galxBossAudioFadeInterval);_galxBossAudioFadeInterval=null;}
    _galxBossAudioFadeInterval=setInterval(()=>{
      _galxBossAudioVol=Math.min(0.58,_galxBossAudioVol+0.03);
      if(_galxBossAudio)_galxBossAudio.volume=_galxBossAudioVol;
      if(_galxBossAudioVol>=0.58){clearInterval(_galxBossAudioFadeInterval);_galxBossAudioFadeInterval=null;}
    },80);
  }
  function _stopGalaximyAudio(){
    if(!_galxBossAudio)return;
    _galxBossAudioStopping=true;
    if(_galxBossAudioFadeInterval){clearInterval(_galxBossAudioFadeInterval);_galxBossAudioFadeInterval=null;}
    _galxBossAudioFadeInterval=setInterval(()=>{
      _galxBossAudioVol=Math.max(0,_galxBossAudioVol-0.035);
      if(_galxBossAudio)_galxBossAudio.volume=_galxBossAudioVol;
      if(_galxBossAudioVol<=0){
        if(_galxBossAudio){_galxBossAudio.pause();_galxBossAudio=null;}
        _galxBossAudioStopping=false;
        clearInterval(_galxBossAudioFadeInterval);_galxBossAudioFadeInterval=null;
      }
    },80);
  }

  const BOSS_MAX_HP=600000;
  const PHASE2_PCT=0.65;
  const PHASE3_PCT=0.30;
  const PHASE3_HP_BONUS_MULT=1.20; // "regeneração cósmica" ao entrar na fase 3

  // ── Astros do Pacote Tecnológico permitidos nesta batalha ──
  // 8 delas exigem astro-hospedeiro (`.host` vivo) para lutar — reflete
  // a regra "megaestruturas não recomendadas, a menos que tenham astro
  // por perto". As 2 marcadas freeStanding não precisam de host.
  const TECH_COMBATANTS={
    techDysonSphere:     {name:'Esfera de Dyson',      hp:14000, atk:520, def:0.30, freeStanding:false},
    techDysonSwarm:      {name:'Enxame de Dyson',      hp:8000,  atk:640, def:0.12, freeStanding:false},
    techShkadovThruster: {name:'Motor Shkadov',        hp:20000, atk:760, def:0.42, freeStanding:false},
    techMatrioshkaBrain: {name:'Cérebro de Matrioshka',hp:16000, atk:480, def:0.55, freeStanding:false},
    techMassExtractor:   {name:'Extrator de Massa',    hp:9000,  atk:560, def:0.28, freeStanding:false},
    techAldersonDisk:    {name:'Disco de Alderson',    hp:26000, atk:360, def:0.60, freeStanding:false},
    techNicollDyson:     {name:'Feixe Nicoll-Dyson',   hp:5000,  atk:980, def:0.10, freeStanding:false},
    techSpaceElevator:   {name:'Elevador Espacial',    hp:10000, atk:340, def:0.48, freeStanding:false},
    techAlcubierreDrive: {name:'Motor de Alcubierre',  hp:6000,  atk:600, def:0.16, freeStanding:true},
    techGravityProjector:{name:'Projetor de Gravidade',hp:9500,  atk:500, def:0.32, freeStanding:true},
  };
  const TECH_COMBATANT_TYPES=Object.keys(TECH_COMBATANTS);

  // ── Astros-hospedeiro (Estrela/Lua/Planeta) auto-spawnados dentro da
  // arena — necessários porque as megaestruturas do Tech Pack exigem um
  // `.host` vivo para existir/lutar. Limite de 5 por tipo (15 no total),
  // com respawn automático quando um hospedeiro morre ou é destruído. ──
  const HOST_TYPES=['star','moon','planet'];
  const HOST_CAP_PER_TYPE=5;
  const HOST_SPAWN_INTERVAL=2.2; // segundos entre tentativas de spawn
  let _hostSpawnCooldown=0;
  const HOST_CLASS={star:()=>Star, moon:()=>Moon, planet:()=>Planet};
  let _hosts=[]; // referências aos astros hospedeiros vivos criados pelo Galaximy

  function _countHostsOfType(type){
    let n=0;
    for(let i=0;i<_hosts.length;i++){
      if(!_hosts[i].dead&&_hosts[i].type===type)n++;
    }
    return n;
  }
  function _randomPointInArena(){
    if(!_worldBounds)return{wx:0,wy:0};
    const pad=0.12; // não nasce colado na borda da arena
    const w=_worldBounds.maxX-_worldBounds.minX, h=_worldBounds.maxY-_worldBounds.minY;
    return{
      wx:_worldBounds.minX+w*(pad+Math.random()*(1-2*pad)),
      wy:_worldBounds.minY+h*(pad+Math.random()*(1-2*pad)),
    };
  }
  function _spawnHost(type){
    const ClsGetter=HOST_CLASS[type];
    if(!ClsGetter||typeof objects==='undefined')return;
    const Cls=ClsGetter();
    const{wx,wy}=_randomPointInArena();
    const o=new Cls(wx,wy);
    o.fixed=true; // hospedeiros da arena não derivam por gravidade/órbita
    o._galxHost=true;
    o._galxMegaOccupant=null; // referência à megaestrutura anexada (1 por vez)
    objects.push(o);
    _hosts.push(o);
  }
  function _updateHostSpawns(dt){
    if(!_worldBounds)return;
    _hostSpawnCooldown-=dt;
    if(_hostSpawnCooldown>0)return;
    _hostSpawnCooldown=HOST_SPAWN_INTERVAL;
    // limpa referências mortas da lista de controle
    _hosts=_hosts.filter(o=>!o.dead);
    for(let i=0;i<HOST_TYPES.length;i++){
      const type=HOST_TYPES[i];
      if(_countHostsOfType(type)<HOST_CAP_PER_TYPE){
        _spawnHost(type);
        break; // um spawn por tick de intervalo, evita "pop" simultâneo de vários
      }
    }
  }
  // Se o hospedeiro morrer/for destruído, a megaestrutura ancorada nele
  // morre junto (ela já morre sozinha via seu próprio update, que checa
  // `!this.host||this.host.dead` — aqui só garantimos que a flag de
  // ocupação seja liberada e a Mega marcada como morta imediatamente,
  // sem esperar o próximo frame dela).
  function _updateHostDeaths(){
    for(let i=0;i<_hosts.length;i++){
      const h=_hosts[i];
      if(h.dead&&h._galxMegaOccupant&&!h._galxMegaOccupant.dead){
        h._galxMegaOccupant.dead=true;
        h._galxMegaOccupant=null;
      }
    }
  }

  function isActive(){return _active;}

  // Um astro do Tech Pack só é elegível para lutar se: for um dos 10
  // tipos escolhidos, estiver vivo, e (se não for freeStanding) tiver
  // um host vivo — megaestruturas "soltas" sem astro não combatem.
  function _isEligibleCombatant(o){
    if(!o||o.dead)return false;
    const cfg=TECH_COMBATANTS[o.type];
    if(!cfg)return false;
    if(!cfg.freeStanding&&(!o.host||o.host.dead))return false;
    return true;
  }
  function _registerCombatant(o){
    if(o._galxHp!==undefined)return; // já registrado
    const cfg=TECH_COMBATANTS[o.type];
    o._galxMaxHp=cfg.hp;
    o._galxHp=cfg.hp;
    o._galxAtk=cfg.atk;
    o._galxDef=cfg.def;
    o._galxAtkCooldown=rand(1.5,3.5);
  }
  function _scanCombatants(){
    if(typeof objects==='undefined')return;
    for(let i=0;i<objects.length;i++){
      const o=objects[i];
      if(_isEligibleCombatant(o))_registerCombatant(o);
    }
  }
  // Dano do Galaximy (ou luas) contra um combatente do Tech Pack,
  // já aplicando a defesa dele (redução percentual).
  function _damageCombatant(o,rawAmount){
    if(!o||o._galxHp===undefined)return;
    const def=o._galxDef||0;
    const dmg=Math.max(1,rawAmount*(1-def));
    o._galxHp-=dmg;
    if(o._galxHp<=0){
      o._galxHp=0;
      o.dead=true;
    }
  }

  function _w2s(wx,wy){
    return{
      sx:(wx-cam.x)*cam.zoom+canvas.width*.5,
      sy:(wy-cam.y)*cam.zoom+canvas.height*.5,
    };
  }
  function _s2w(sx,sy){
    return{
      wx:(sx-canvas.width*.5)/cam.zoom+cam.x,
      wy:(sy-canvas.height*.5)/cam.zoom+cam.y,
    };
  }

  // ── Constrói a arena em coordenadas de MUNDO, centrada na posição
  // atual da câmera, maior que o viewport (ARENA_WORLD_SCALE). Chamada
  // uma vez no start — a arena não se move depois disso. ──
  function _buildArena(){
    const viewHalfW=(canvas.width*.5)/cam.zoom;
    const viewHalfH=(canvas.height*.5)/cam.zoom;
    const halfW=viewHalfW*ARENA_WORLD_SCALE;
    const halfH=viewHalfH*ARENA_WORLD_SCALE;
    _worldBounds={
      minX:cam.x-halfW, maxX:cam.x+halfW,
      minY:cam.y-halfH, maxY:cam.y+halfH,
    };
  }

  // ── Câmera pode se mover livremente e dar zoom dentro da arena, mas
  // nunca ultrapassa a barreira (clamp em coordenadas de MUNDO) ──
  function _enforceCameraBounds(){
    if(!_worldBounds)return;
    const b=_worldBounds;
    const hw=(canvas.width*.5)/cam.zoom;
    const hh=(canvas.height*.5)/cam.zoom;
    cam.x=Math.max(b.minX+hw,Math.min(b.maxX-hw,cam.x));
    cam.y=Math.max(b.minY+hh,Math.min(b.maxY-hh,cam.y));
    if(hw>=(b.maxX-b.minX)/2)cam.x=(b.minX+b.maxX)/2;
    if(hh>=(b.maxY-b.minY)/2)cam.y=(b.minY+b.maxY)/2;
  }

  function _getPhase(hp,maxHP){
    const pct=hp/maxHP;
    if(pct<=PHASE3_PCT)return 3;
    if(pct<=PHASE2_PCT)return 2;
    return 1;
  }

  function start(opts){
    if(_active)return;
    opts=opts||{};
    _active=true;
    // Sem trava de zoom aqui: a arena do Galaximy é world-space e MAIOR
    // que o viewport (ARENA_WORLD_SCALE), então o jogador pode dar zoom
    // livremente sem quebrar a batalha — diferente dos outros bosses.

    // ── Guarda TODOS os astros antigos e limpa a tela para a batalha,
    // mesmo padrão do Alien/Marsian/Polvicullus (evita astros antigos
    // soltos/colidindo dentro da arena do Galaximy). Restaurados em
    // _finish(). ──
    _preInvasionStash=objects.filter(o=>!o.dead);
    objects.length=0;

    _riftCanvas=document.getElementById('galaximy-rift-canvas');
    _riftCtx=_riftCanvas.getContext('2d');
    _riftCanvas.width=canvas.width;
    _riftCanvas.height=canvas.height;
    _riftCanvas.style.left=canvas.style.left||'0px';
    _riftCanvas.style.top=canvas.style.top||'0px';
    _riftCanvas.style.width=canvas.width+'px';
    _riftCanvas.style.height=canvas.height+'px';
    _riftCanvas.classList.add('active');

    _buildArena();
    const cx=(_worldBounds.minX+_worldBounds.maxX)/2;
    const cy=(_worldBounds.minY+_worldBounds.maxY)/2;

    _hosts=[];
    _hostSpawnCooldown=0.4; // primeiro hospedeiro nasce rápido

    const BIG_MOON_COUNT=8;
    _boss={
      wx:cx,wy:cy,
      vx:0,vy:0,
      hp:BOSS_MAX_HP,maxHP:BOSS_MAX_HP,
      phase:1,
      sizeScale:1,
      ringAngle:0,ringAngle2:0,ringAngle3:0,
      invisible:false,invisTimer:0,
      dying:false,dyingT:0,
      beamAngle:0,beamActive:false,beamTimer:rand(3,4.5),beamDur:0,
      collapseTimer:rand(9,12),collapsePulse:0,
      // ── Emaranhamento Quântico (Fase 1+): 2 astros da arena ficam
      // ligados por um vínculo — dano em um ecoa parcialmente no outro.
      entangleTimer:rand(6,9),entangleA:null,entangleB:null,entangleDur:0,
      // ── Salto Quântico (Fase 2+): núcleo pisca e reaparece em outro
      // ponto da arena, quebrando a mira do jogador.
      blinkTimer:rand(8,11),blinkState:'idle', // 'idle'|'fadeOut'|'fadeIn'
      blinkT:0,blinkAlpha:1,
      // ── Superposição (Fase 3): núcleo se divide em estados-fantasma;
      // só um é real e recebe dano.
      superposActive:false,superposTimer:rand(10,14),superposDur:0,
      superposGhosts:[], // {ox,oy} offsets em MUNDO relativos ao núcleo real
      superposRealIdx:0,
      // ── Luas grandes (bolinhas amarelas externas) — a partir da
      // Fase 2, uma de cada vez se destaca da órbita, voa até um astro
      // próximo (bumerangue), causa dano, e retorna à órbita. ──
      moons:Array.from({length:BIG_MOON_COUNT},(_,i)=>({
        idx:i, state:'orbit', // 'orbit' | 'circling' | 'flying' | 'returning'
        wx:0,wy:0, // posição em MUNDO quando não está em órbita
        targetObj:null,
        circleT:0,
      })),
      moonAtkCooldown:3.5, // primeiro ataque logo após entrar na fase 2
    };
    _t=0;_lastTick=performance.now();
    const bar=document.getElementById('galx-boss-hp-bar');
    if(bar)bar.classList.add('active');
    _updateBar();
    _startGalaximyAudio();
    // Apenas os 10 astros do Pacote Tecnológico usados como combatentes
    // ficam disponíveis: todo o resto vira 🚫 (Estrela/Lua/Planeta também,
    // já que nascem sozinhos como hospedeiros dentro da arena).
    _setInvasionAstroLockUI(true,GALAXIMY_BLOCKED_ASTRO_TYPES);
    window._galaximyAstroCaps={};
    Object.keys(GALAXIMY_SP_CAP_CONFIG).forEach(t=>{
      const cfg=GALAXIMY_SP_CAP_CONFIG[t];
      window._galaximyAstroCaps[t]={max:cfg.max,used:0,cooldown:0,cooldownTime:cfg.cooldownTime};
    });
    const galxacBar=document.getElementById('galaximy-astro-counters-bar');
    if(galxacBar)galxacBar.classList.add('active');
    Object.keys(window._galaximyAstroCaps).forEach(t=>{
      const el=document.getElementById(`galaximy-${t}-counter`);
      if(el)el.classList.remove('depleted','cooldown');
      _refreshGalaximyAstroCounterUI(t,window._galaximyAstroCaps[t]);
    });
    showTooltip('🌌🤖 GALAXIMY emergiu das profundezas do vórtice! Guardião Robótica desperto.');
    window._invasionActive=true;
    // ── Limites de Reset (2) e Mover (3) — mesmo padrão do Marsian ──
    window._galaximyResetUses=2;
    window._galaximyMoveUses=3;
    {
      const gru=document.getElementById('galaximy-reset-uses');
      const gmu=document.getElementById('galaximy-move-uses');
      const grc=document.getElementById('galaximy-reset-counter');
      const gmc=document.getElementById('galaximy-move-counter');
      if(gru)gru.textContent='2';if(gmu)gmu.textContent='3';
      if(grc)grc.classList.remove('depleted');if(gmc)gmc.classList.remove('depleted');
    }
    _animFrame=requestAnimationFrame(_tick);
  }

  function _updateBar(){
    const fill=document.getElementById('galx-boss-hp-fill');
    const phaseEl=document.getElementById('galx-boss-hp-phase');
    if(!_boss)return;
    const pct=Math.max(0,_boss.hp/_boss.maxHP);
    if(fill){
      fill.style.width=(pct*100)+'%';
      fill.className=_boss.phase===3?'phase3':_boss.phase===2?'phase2':'';
    }
    if(phaseEl)phaseEl.textContent='FASE '+_boss.phase;
  }

  function _applyPhaseTransition(newPhase){
    if(!_boss||newPhase===_boss.phase)return;
    const entering3=newPhase===3&&_boss.phase!==3;
    _boss.phase=newPhase;
    if(entering3){
      _boss.hp=Math.min(_boss.maxHP,_boss.hp*PHASE3_HP_BONUS_MULT);
      _boss.maxHP=Math.max(_boss.maxHP,_boss.hp);
      _boss.sizeScale=1.25;
      const msgs={};
      showTooltip('🌌🔥 Galaximy entra em colapso instável — o vórtice cresce e fica caótico!');
    } else if(newPhase===2){
      showTooltip('🌌⚡ Galaximy acelera a rotação dos anéis — mais raios, mais sondas!');
    }
    _updateBar();
  }

  function _tick(now){
    if(!_active){_animFrame=null;return;}
    const dt=Math.min(0.05,(now-_lastTick)/1000);
    _lastTick=now;
    _t+=dt;
    // Câmera livre (posição + zoom) mas travada dentro da arena
    _enforceCameraBounds();
    if(_boss&&_boss.dying){
      _tickDeath(dt);
    }
    if(_boss&&!_boss.dying){
      // Movimento lento com inércia pesada — mantém-se perto do centro
      // da arena (em coordenadas de MUNDO), como descrito.
      const cx=(_worldBounds.minX+_worldBounds.maxX)/2;
      const cy=(_worldBounds.minY+_worldBounds.maxY)/2;
      const driftScale=(_worldBounds.maxX-_worldBounds.minX)*0.06;
      const driftX=Math.sin(_t*0.12)*driftScale, driftY=Math.cos(_t*0.09)*driftScale*0.7;
      const tx=cx+driftX, ty=cy+driftY;
      _boss.vx+=(tx-_boss.wx)*0.0006;
      _boss.vy+=(ty-_boss.wy)*0.0006;
      _boss.vx*=0.98;_boss.vy*=0.98;
      _boss.wx+=_boss.vx;_boss.wy+=_boss.vy;

      // Rotação dos anéis — velocidade cresce por fase
      const spinMult=_boss.phase===1?1:_boss.phase===2?1.5:2.2;
      _boss.ringAngle+=dt*2.2*spinMult;
      _boss.ringAngle2-=dt*2.8*spinMult;
      _boss.ringAngle3+=dt*3.4*spinMult;

      const newPhase=_getPhase(_boss.hp,_boss.maxHP);
      if(newPhase!==_boss.phase)_applyPhaseTransition(newPhase);

      // ── Raio central giratório — ameaça própria do boss desde a
      // Fase 1 (antes ele era puramente passivo, só reagia via hosts).
      // Um feixe fixo gira lentamente ao redor do núcleo, obrigando o
      // jogador a se manter em movimento constante. ──
      _boss.beamTimer-=dt;
      if(!_boss.beamActive&&_boss.beamTimer<=0){
        _boss.beamActive=true;
        _boss.beamDur=_boss.phase>=3?4.5:_boss.phase===2?3.5:2.8;
        _boss.beamAngle=Math.random()*Math.PI*2;
        showTooltip('🌌📡 Galaximy dispara um raio giratório do núcleo!');
      }
      if(_boss.beamActive){
        const beamSpin=_boss.phase>=3?1.6:_boss.phase===2?1.15:0.85;
        _boss.beamAngle+=dt*beamSpin;
        _boss.beamDur-=dt;
        _tickCentralBeamDamage();
        if(_boss.beamDur<=0){
          _boss.beamActive=false;
          _boss.beamTimer=rand(_boss.phase>=3?4:5,_boss.phase>=3?6:7.5);
        }
      }

      // ── Colapso Gravitacional — Fase 3: pulso periódico que puxa
      // astros próximos em direção ao núcleo, reforçando o tema de
      // "vórtice instável" com uma ameaça real em vez de decoração. ──
      if(_boss.phase>=3){
        _boss.collapseTimer-=dt;
        if(_boss.collapseTimer<=0){
          _boss.collapseTimer=rand(10,13);
          _boss.collapsePulse=1.4;
          showTooltip('🌌🕳️ COLAPSO GRAVITACIONAL! O vórtice puxa tudo para o centro!');
        }
        if(_boss.collapsePulse>0){
          _boss.collapsePulse=Math.max(0,_boss.collapsePulse-dt);
          _tickGravitationalCollapse(dt);
        }
      }

      // ── Ataque bumerangue das luas — Fase 2 em diante ──
      if(_boss.phase>=2){
        _boss.moonAtkCooldown-=dt;
        if(_boss.moonAtkCooldown<=0){
          _boss.moonAtkCooldown=_boss.phase>=3?2.0:3.2; // mais rápido na fase 3
          _fireMoonAttack();
        }
      }
      // ── Mecânicas quânticas: Emaranhamento desde a Fase 1, Salto
      // Quântico a partir da Fase 2, Superposição só na Fase 3. ──
      _tickEntanglement(dt);
      _tickQuantumBlink(dt);
      _tickSuperposition(dt);
      _updateMoons(dt);
      _updateFx(dt);
      _scanCombatants();
      _updateCombatantAttacks(dt);
      _updateHostSpawns(dt);
      _updateHostDeaths();
      // ── Tick cooldown dos 10 astros tecnológicos de combate (limite justo) ──
      if(window._galaximyAstroCaps&&typeof objects!=='undefined'){
        Object.keys(window._galaximyAstroCaps).forEach(t=>{
          const cap=window._galaximyAstroCaps[t];
          if(cap.cooldown>0){
            cap.cooldown=Math.max(0,cap.cooldown-dt);
            _refreshGalaximyAstroCounterUI(t,cap);
            if(cap.cooldown===0){
              cap.used=0;
              _refreshGalaximyAstroCounterUI(t,cap);
              showTooltip(`✅ ${TYPE_LABELS[t]||t}: recarga completa! ${cap.max} uso(s) disponíveis.`);
            }
          } else {
            const alive=objects.filter(o=>!o.dead&&o.type===t).length;
            cap.used=Math.min(alive,cap.max);
            _refreshGalaximyAstroCounterUI(t,cap);
          }
        });
      }
    }
    _draw();
    _animFrame=requestAnimationFrame(_tick);
  }

  // ── Astros do Tech Pack revidam: cada combatente elegível ataca o
  // Galaximy periodicamente (dano aplicado direto no HP do boss,
  // reduzido pela defesa dele — mesmo conceito das outras batalhas). ──
  const BOSS_DEF=0.15; // defesa base do Galaximy contra ataques dos astros
  function _updateCombatantAttacks(dt){
    if(typeof objects==='undefined'||!_boss||_boss.dying)return;
    for(let i=0;i<objects.length;i++){
      const o=objects[i];
      if(o.dead||o._galxHp===undefined||o._galxHp<=0)continue;
      o._galxAtkCooldown-=dt;
      if(o._galxAtkCooldown<=0){
        o._galxAtkCooldown=rand(2.2,4.0);
        const dmg=Math.max(1,o._galxAtk*(1-BOSS_DEF));
        _boss.hp=Math.max(0,_boss.hp-dmg);
        _updateBar();
        _spawnMoonImpactFx(_boss.wx+rand(-20,20),_boss.wy+rand(-20,20));
        if(_boss.hp<=0&&!_boss.dying){
          _boss.dying=true;_boss.dyingT=0;
          showTooltip('🌌💥 Galaximy entra em colapso final!');
        }
      }
    }
  }

  // Raio "base" do núcleo em coordenadas de MUNDO (independe do zoom da
  // câmera) — usado para calcular a órbita real das luas no mundo.
  function _baseRWorld(){
    if(!_worldBounds)return 40;
    return Math.min(_worldBounds.maxX-_worldBounds.minX,_worldBounds.maxY-_worldBounds.minY)*0.021*(_boss?_boss.sizeScale:1);
  }

  // Posição orbital (MUNDO) de uma lua, mesma fórmula usada no desenho.
  function _moonOrbitWorldPos(idx){
    const baseR=_baseRWorld();
    const bigMoonCount=_boss.moons.length;
    const bigOrbitR=baseR*11.5;
    const a=(idx/bigMoonCount)*Math.PI*2+_boss.ringAngle3*0.4;
    return{ wx:_boss.wx+Math.cos(a)*bigOrbitR, wy:_boss.wy+Math.sin(a)*bigOrbitR };
  }

  // Escolhe uma lua livre (em órbita) e um astro vivo próximo do boss
  // para lançar em bumerangue: vai até o astro, causa dano, e volta.
  // ── Raio central: dano contínuo em linha reta a partir do núcleo,
  // na direção atual de beamAngle. Throttled a cada 0.25s. ──
  let _beamDmgTick=0;
  function _tickCentralBeamDamage(){
    if(typeof objects==='undefined')return;
    _beamDmgTick+=0.016;
    if(_beamDmgTick<0.25)return;
    _beamDmgTick=0;
    const b=_boss;
    const dx=Math.cos(b.beamAngle),dy=Math.sin(b.beamAngle);
    const beamLen=(_worldBounds?Math.max(_worldBounds.maxX-_worldBounds.minX,_worldBounds.maxY-_worldBounds.minY):3000);
    objects.forEach(o=>{
      if(o.dead)return;
      const rx=o.x-b.wx,ry=o.y-b.wy;
      const proj=rx*dx+ry*dy;
      if(proj<0||proj>beamLen)return;
      const perp=Math.abs(rx*dy-ry*dx);
      if(perp<(o.radius||10)+22){
        if(o._galxHp!==undefined){_damageCombatant(o,180);_echoEntangledDamage(o,180);}
        else{
          if(o._invasionHP===undefined)o._invasionHP=100;
          o._invasionHP=Math.max(0,o._invasionHP-30);
          _echoEntangledDamage(o,30);
          if(o._invasionHP<=0){o.dead=true;if(typeof spawnExplosion==='function')spawnExplosion(o.x,o.y,0.35,false);}
        }
      }
    });
  }

  // ── Colapso Gravitacional: puxa astros próximos em direção ao
  // núcleo enquanto o pulso está ativo; dano leve se chegarem perto
  // demais do centro. ──
  function _tickGravitationalCollapse(dt){
    if(typeof objects==='undefined')return;
    const b=_boss;
    const pullR=(_worldBounds?(_worldBounds.maxX-_worldBounds.minX):2000)*0.4;
    objects.forEach(o=>{
      if(o.dead)return;
      const dx=b.wx-o.x,dy=b.wy-o.y;
      const dist=Math.hypot(dx,dy);
      if(dist<pullR&&dist>1){
        const pull=(1-dist/pullR)*260*dt;
        o.x+=dx/dist*pull;o.y+=dy/dist*pull;
        if(dist<60){
          if(o._galxHp!==undefined){_damageCombatant(o,40*dt);_echoEntangledDamage(o,40*dt);}
          else{
            if(o._invasionHP===undefined)o._invasionHP=100;
            o._invasionHP=Math.max(0,o._invasionHP-25*dt);
            _echoEntangledDamage(o,25*dt);
            if(o._invasionHP<=0){o.dead=true;if(typeof spawnExplosion==='function')spawnExplosion(o.x,o.y,0.35,false);}
          }
        }
      }
    });
  }

  // ── Emaranhamento Quântico (Fase 1+): a cada intervalo, dois astros
  // vivos da arena são escolhidos e "emaranhados" — um vínculo visual
  // os liga, e dano causado a um ecoa uma fração no outro. Ensina o
  // jogador a prestar atenção no campo inteiro, não só no núcleo. ──
  const ENTANGLE_ECHO_PCT=0.35; // fração do dano que ecoa no par
  function _pickEntangleTargets(){
    if(typeof objects==='undefined')return null;
    const pool=objects.filter(o=>!o.dead&&(o._galxHp!==undefined||o._invasionHP!==undefined||o.type==='star'||o.type==='planet'||o.type==='moon'));
    if(pool.length<2)return null;
    const a=pool[Math.floor(Math.random()*pool.length)];
    let b=pool[Math.floor(Math.random()*pool.length)],tries=0;
    while(b===a&&tries<8){b=pool[Math.floor(Math.random()*pool.length)];tries++;}
    if(b===a)return null;
    return{a,b};
  }
  function _tickEntanglement(dt){
    if(!_boss)return;
    if(_boss.entangleA&&(_boss.entangleA.dead||_boss.entangleB.dead)){
      _boss.entangleA=null;_boss.entangleB=null;_boss.entangleDur=0;
    }
    if(_boss.entangleA){
      _boss.entangleDur-=dt;
      if(_boss.entangleDur<=0){_boss.entangleA=null;_boss.entangleB=null;}
      return;
    }
    _boss.entangleTimer-=dt;
    if(_boss.entangleTimer<=0){
      _boss.entangleTimer=rand(9,13);
      const pair=_pickEntangleTargets();
      if(pair){
        _boss.entangleA=pair.a;_boss.entangleB=pair.b;
        _boss.entangleDur=rand(9,13);
        showTooltip('⚛️ Emaranhamento Quântico! Dois astros estão ligados — dano em um ecoa no outro.');
      }
    }
  }
  // Chamada sempre que um astro sofre dano em batalha (combatente do
  // Tech Pack ou astro comum via _invasionHP) — espelha uma fração no
  // par emaranhado, se ele for um dos dois vinculados no momento.
  function _echoEntangledDamage(o,rawDmg){
    if(!_boss||!_boss.entangleA||rawDmg<=0)return;
    let other=null;
    if(o===_boss.entangleA)other=_boss.entangleB;
    else if(o===_boss.entangleB)other=_boss.entangleA;
    if(!other||other.dead)return;
    const echo=rawDmg*ENTANGLE_ECHO_PCT;
    if(other._galxHp!==undefined){_damageCombatant(other,echo);}
    else{
      if(other._invasionHP===undefined)other._invasionHP=100;
      other._invasionHP=Math.max(0,other._invasionHP-echo);
      if(other._invasionHP<=0&&!other.dead){other.dead=true;if(typeof spawnExplosion==='function')spawnExplosion(other.x,other.y,0.3,false);}
    }
  }

  // ── Salto Quântico (Fase 2+): o núcleo periodicamente "pisca" —
  // fade out, reaparece em outro ponto da arena, fade in — quebrando
  // o padrão de mira do jogador sem dano direto. ──
  const BLINK_FADE_TIME=0.5;
  function _tickQuantumBlink(dt){
    if(!_boss||_boss.phase<2||_boss.dying)return;
    if(_boss.blinkState==='idle'){
      _boss.blinkTimer-=dt;
      if(_boss.blinkTimer<=0){
        _boss.blinkState='fadeOut';_boss.blinkT=0;
        showTooltip('⚛️🌀 Galaximy inicia um salto quântico...');
      }
      return;
    }
    _boss.blinkT+=dt;
    if(_boss.blinkState==='fadeOut'){
      _boss.blinkAlpha=Math.max(0,1-_boss.blinkT/BLINK_FADE_TIME);
      if(_boss.blinkT>=BLINK_FADE_TIME){
        // Reposiciona o núcleo em outro ponto aleatório da arena
        const p=_randomPointInArena();
        _boss.wx=p.wx;_boss.wy=p.wy;
        _boss.vx=0;_boss.vy=0;
        _boss.blinkState='fadeIn';_boss.blinkT=0;
        _spawnMoonImpactFx(_boss.wx,_boss.wy);
      }
    } else if(_boss.blinkState==='fadeIn'){
      _boss.blinkAlpha=Math.min(1,_boss.blinkT/BLINK_FADE_TIME);
      if(_boss.blinkT>=BLINK_FADE_TIME){
        _boss.blinkAlpha=1;
        _boss.blinkState='idle';
        _boss.blinkTimer=rand(_boss.phase>=3?7:10,_boss.phase>=3?10:14);
      }
    }
  }

  // ── Superposição (Fase 3): o núcleo se divide em 2 estados-fantasma
  // adicionais que se movem em espelho ao real — só o real recebe
  // dano; os fantasmas têm um brilho sutil levemente diferente como
  // pista para o jogador. ──
  function _tickSuperposition(dt){
    if(!_boss||_boss.phase<3||_boss.dying)return;
    if(!_boss.superposActive){
      _boss.superposTimer-=dt;
      if(_boss.superposTimer<=0){
        _boss.superposActive=true;
        _boss.superposDur=rand(7,9);
        _boss.superposRealIdx=Math.floor(Math.random()*3);
        const baseR=_baseRWorld();
        _boss.superposGhosts=[
          {ox:-baseR*7,oy:baseR*2.5,phase:rand(0,Math.PI*2)},
          {ox:baseR*7, oy:baseR*2.5,phase:rand(0,Math.PI*2)},
        ];
        showTooltip('⚛️👻 Superposição! Apenas um núcleo é real — identifique-o pelo brilho.');
      }
      return;
    }
    _boss.superposDur-=dt;
    if(_boss.superposDur<=0){
      _boss.superposActive=false;
      _boss.superposGhosts=[];
      _boss.superposTimer=rand(11,15);
    }
  }

  function _fireMoonAttack(){
    if(!_boss||typeof objects==='undefined'||!objects.length)return;
    const freeMoon=_boss.moons.find(m=>m.state==='orbit');
    if(!freeMoon)return;
    // Prioriza astros combatentes do Tech Pack (elegíveis); só mira em
    // outro tipo de astro se não houver nenhum combatente em campo.
    let best=null,bestD=Infinity;
    for(let k=0;k<objects.length;k++){
      const o=objects[k];
      if(o.dead||o._galxHp===undefined)continue;
      const d=Math.hypot(o.x-_boss.wx,o.y-_boss.wy);
      if(d<bestD){bestD=d;best=o;}
    }
    if(!best){
      for(let k=0;k<objects.length;k++){
        const o=objects[k];
        if(o.dead)continue;
        const d=Math.hypot(o.x-_boss.wx,o.y-_boss.wy);
        if(d<bestD){bestD=d;best=o;}
      }
    }
    if(!best)return;
    const origin=_moonOrbitWorldPos(freeMoon.idx);
    freeMoon.state='circling';
    freeMoon.wx=origin.wx;freeMoon.wy=origin.wy;
    freeMoon.targetObj=best;
    freeMoon.circleT=0;
  }

  // Partículas de impacto (mundo) quando uma lua destrói um astro.
  function _spawnMoonImpactFx(wx,wy){
    for(let i=0;i<14;i++){
      _fxParticles.push({
        wx,wy,vwx:rand(-90,90),vwy:rand(-90,90),r:rand(2,6),
        color:Math.random()<0.5?'#fff3b0':'#ffd23f',life:0.6,maxLife:0.6,
      });
    }
  }

  // ── Sequência de morte: EXPLOSÃO ATÔMICA ─────────────────────────
  // Tema escolhido por ser fiel ao design do Galaximy (núcleo central +
  // elétrons em órbita = molécula/átomo): o núcleo entra em fissão,
  // os elétrons/luas são arremessados para longe, e tudo culmina num
  // clarão branco ofuscante seguido de onda de choque expansiva e um
  // "cogumelo" estilizado de partículas subindo — mesma duração total
  // (4.5s) e estrutura em 3 fases do padrão usado no Polvicullus/Quasord.
  const GALX_DEATH_DURATION=4.5;
  function _tickDeath(dt){
    const b=_boss;
    if(!b)return;
    b.dyingT+=dt;
    // Mantém os anéis girando (mais rápido conforme a instabilidade cresce)
    // em vez de congelar tudo de uma vez — reforça a leitura de "reator
    // perdendo controle" antes da fissão final.
    const spinBoost=1+Math.min(1,b.dyingT/GALX_DEATH_DURATION)*3;
    b.ringAngle+=dt*2.2*spinBoost;
    b.ringAngle2-=dt*2.8*spinBoost;
    b.ringAngle3+=dt*3.4*spinBoost;
    const p=Math.min(1,b.dyingT/GALX_DEATH_DURATION);

    // ── Fase 1 (0–35%): núcleo pulsa cada vez mais rápido e forte —
    // "pré-fissão", crepitação de energia escapando pelas rachaduras ──
    if(p<0.35){
      b.sizeScale=Math.max(0.15,1-p*0.15); // leve encolhimento, tensão acumulando
      if(Math.random()<0.5+p*0.5){
        const ang=rand(0,Math.PI*2),r=rand(0,1)*_baseRWorld()*1.3;
        _fxParticles.push({
          wx:b.wx+Math.cos(ang)*r,wy:b.wy+Math.sin(ang)*r,
          vwx:Math.cos(ang)*rand(20,50),vwy:Math.sin(ang)*rand(20,50),
          r:rand(2,5),color:Math.random()<0.5?'#c9a0ff':'#8a4fe0',life:0.5,maxLife:0.5,
        });
      }
    }
    // ── Fase 2 (35–70%): elétrons/luas são ARREMESSADOS para fora em
    // linha reta (fissão em cadeia) + faíscas roxas/brancas intensas ──
    else if(p<0.70){
      b.sizeScale=Math.max(0.1,0.85-((p-0.35)/0.35)*0.35);
      // Dispara cada lua que ainda está em órbita para fora, uma vez
      if(b.moons&&!b._deathMoonsFlung){
        b.moons.forEach(m=>{
          const origin=_moonOrbitWorldPos(m.idx);
          const ang=Math.atan2(origin.wy-b.wy,origin.wx-b.wx)+rand(-0.3,0.3);
          m.state='flung';
          m.wx=origin.wx;m.wy=origin.wy;
          m._fvwx=Math.cos(ang)*rand(280,420);
          m._fvwy=Math.sin(ang)*rand(280,420);
        });
        b._deathMoonsFlung=true;
      }
      if(b.moons){
        b.moons.forEach(m=>{
          if(m.state!=='flung')return;
          m.wx+=m._fvwx*dt; m.wy+=m._fvwy*dt;
          m._fvwx*=0.99; m._fvwy*=0.99;
        });
      }
      if(Math.random()<0.85){
        const ang=rand(0,Math.PI*2),r=rand(0,1)*_baseRWorld()*2;
        _fxParticles.push({
          wx:b.wx+Math.cos(ang)*r,wy:b.wy+Math.sin(ang)*r,
          vwx:Math.cos(ang)*rand(60,140),vwy:Math.sin(ang)*rand(60,140),
          r:rand(2,6),color:Math.random()<0.5?'#ffffff':'#d9baff',life:0.55,maxLife:0.55,
        });
      }
    }
    // ── Fase 3 (70–100%): colapso final do núcleo — implosão rápida
    // seguida do clarão branco ofuscante que domina a tela ──
    else{
      b.sizeScale=Math.max(0.02,0.5*(1-((p-0.70)/0.30)));
      if(Math.random()<0.9){
        const ang=rand(0,Math.PI*2),r=rand(0,1)*_baseRWorld()*3;
        _fxParticles.push({
          wx:b.wx+Math.cos(ang)*r,wy:b.wy+Math.sin(ang)*r,
          vwx:Math.cos(ang)*rand(100,220),vwy:Math.sin(ang)*rand(100,220),
          r:rand(3,9),color:Math.random()<0.5?'#ffffff':'#fff3d0',life:0.7,maxLife:0.7,
        });
      }
    }

    if(b.dyingT>=GALX_DEATH_DURATION){
      const{sx,sy}=_w2s(b.wx,b.wy);
      // ── CLARÃO BRANCO OFUSCANTE cobrindo toda a arena (característico
      // de explosão atômica) ──
      _riftCtx.save();
      _riftCtx.fillStyle='rgba(255,255,255,0.95)';
      _riftCtx.fillRect(0,0,_riftCanvas.width,_riftCanvas.height);
      _riftCtx.restore();
      // ── Onda de choque: múltiplos anéis expandindo rapidamente ──
      for(let ring=0;ring<5;ring++){
        const rr=50+ring*70;
        _riftCtx.beginPath();
        _riftCtx.arc(sx,sy,rr,0,Math.PI*2);
        _riftCtx.strokeStyle=`rgba(255,245,220,${0.85-ring*0.15})`;
        _riftCtx.lineWidth=7-ring*1.1;
        _riftCtx.stroke();
      }
      // ── "Cogumelo" estilizado — corpo central + calota, feito de
      // partículas douradas/brancas, remetendo a uma explosão nuclear ──
      for(let i=0;i<50;i++){
        const cx2=sx+rand(-30,30),cy2=sy-rand(0,140);
        _riftCtx.beginPath();
        _riftCtx.arc(cx2,cy2,rand(4,22),0,Math.PI*2);
        _riftCtx.fillStyle=`rgba(255,230,160,${Math.random()*0.8})`;
        _riftCtx.fill();
      }
      for(let i=0;i<40;i++){
        const ang=rand(0,Math.PI*2),dist=rand(60,260);
        _riftCtx.beginPath();
        _riftCtx.arc(sx+Math.cos(ang)*dist,sy+Math.sin(ang)*dist,rand(3,14),0,Math.PI*2);
        _riftCtx.fillStyle=`rgba(255,255,255,${Math.random()*0.85})`;
        _riftCtx.fill();
      }
      _finish(true);
    }
  }
  function _updateFx(dt){
    for(let i=_fxParticles.length-1;i>=0;i--){
      const p=_fxParticles[i];
      p.wx+=p.vwx*dt; p.wy+=p.vwy*dt;
      p.life-=dt;
      if(p.life<=0)_fxParticles.splice(i,1);
    }
  }
  function _drawFx(c){
    _fxParticles.forEach(p=>{
      const{sx,sy}=_w2s(p.wx,p.wy);
      const alpha=Math.max(0,p.life/p.maxLife);
      c.beginPath();c.arc(sx,sy,p.r*cam.zoom,0,Math.PI*2);
      c.fillStyle=p.color;c.globalAlpha=alpha;c.fill();c.globalAlpha=1;
    });
  }

  function _updateMoons(dt){
    if(!_boss)return;
    const speed=(_worldBounds?(_worldBounds.maxX-_worldBounds.minX):2000)*0.55; // world units/s
    _boss.moons.forEach(m=>{
      if(m.state==='circling'){
        if(!m.targetObj||m.targetObj.dead){
          m.state='returning';
          return;
        }
        const cx=m.targetObj.x,cy=m.targetObj.y;
        const dx=cx-m.wx,dy=cy-m.wy;
        const dist=Math.hypot(dx,dy)||1;
        const orbitR=90;
        if(dist>orbitR+30){
          // Ainda se aproximando do alvo
          const step=speed*dt;
          m.wx+=dx/dist*step;m.wy+=dy/dist*step;
        } else {
          // Cerco: gira rapidamente ao redor do alvo por um instante,
          // dando ao jogador uma janela clara pra fugir antes do
          // arremesso final — mais dinâmico que um simples aviso parado.
          m.circleT+=dt;
          const ang=m.circleT*7;
          m.wx=cx+Math.cos(ang)*orbitR;
          m.wy=cy+Math.sin(ang)*orbitR;
          if(m.circleT>=0.9){
            m.state='flying';
          }
        }
        return;
      }
      if(m.state==='flying'){
        if(!m.targetObj||m.targetObj.dead){
          // Alvo sumiu — volta direto pra órbita
          m.state='returning';
          return;
        }
        const dx=m.targetObj.x-m.wx, dy=m.targetObj.y-m.wy;
        const dist=Math.hypot(dx,dy)||1;
        const step=speed*dt;
        if(dist<=step+20){
          // Chegou no astro — aplica dano da lua (respeitando defesa
          // se for um combatente do Tech Pack) e inicia o retorno
          if(m.targetObj._galxHp!==undefined){
            _damageCombatant(m.targetObj,2200);
          } else {
            m.targetObj.dead=true;
          }
          _spawnMoonImpactFx(m.targetObj.x,m.targetObj.y);
          m.targetObj=null;
          m.state='returning';
        } else {
          m.wx+=dx/dist*step;
          m.wy+=dy/dist*step;
        }
      } else if(m.state==='returning'){
        const origin=_moonOrbitWorldPos(m.idx);
        const dx=origin.wx-m.wx, dy=origin.wy-m.wy;
        const dist=Math.hypot(dx,dy)||1;
        const step=speed*dt;
        if(dist<=step+8){
          m.state='orbit'; // volta a seguir a órbita normalmente
        } else {
          m.wx+=dx/dist*step;
          m.wy+=dy/dist*step;
        }
      }
    });
  }

  // ── Borda da arena (MUNDO → TELA): como a arena é maior que a
  // câmera, a barreira só aparece quando o jogador navega perto dela —
  // mesmo visual das outras arenas (cantos em L, pulso, partículas),
  // só que em roxo. ──
  function _drawArenaBorder(c,t){
    if(!_worldBounds)return;
    const tl=_w2s(_worldBounds.minX,_worldBounds.minY);
    const br=_w2s(_worldBounds.maxX,_worldBounds.maxY);
    const x=tl.sx,y=tl.sy,x2=br.sx,y2=br.sy;
    const w=x2-x,h=y2-y;
    const pulse=.55+.45*Math.sin(t*2.5);
    const alpha=.5+.35*Math.sin(t*3.1);
    c.save();
    c.strokeStyle=`rgba(160,90,255,${alpha})`;
    c.lineWidth=2.5;
    c.strokeRect(x,y,w,h);
    c.strokeStyle=`rgba(210,180,255,${alpha*.35})`;
    c.lineWidth=1;
    c.strokeRect(x+4,y+4,w-8,h-8);
    const cs=22;
    const corners=[
      [[x,y+cs],[x,y],[x+cs,y]],
      [[x2-cs,y],[x2,y],[x2,y+cs]],
      [[x,y2-cs],[x,y2],[x+cs,y2]],
      [[x2-cs,y2],[x2,y2],[x2,y2-cs]],
    ];
    corners.forEach(pts=>{
      c.beginPath();
      c.moveTo(pts[0][0],pts[0][1]);c.lineTo(pts[1][0],pts[1][1]);c.lineTo(pts[2][0],pts[2][1]);
      c.strokeStyle=`rgba(140,60,255,${.18*(.8+.2*pulse)})`;c.lineWidth=8;c.stroke();
      c.strokeStyle=`rgba(140,60,255,${.8+.2*pulse})`;c.lineWidth=3.2;c.stroke();
    });
    if(Math.random()<0.18){
      const side=Math.floor(Math.random()*4);
      let px,py;
      if(side===0){px=rand(x,x2);py=y;}
      else if(side===1){px=x2;py=rand(y,y2);}
      else if(side===2){px=rand(x,x2);py=y2;}
      else{px=x;py=rand(y,y2);}
      c.beginPath();c.arc(px,py,rand(1.5,4),0,Math.PI*2);
      c.fillStyle=`rgba(190,140,255,${rand(.4,.9)})`;c.fill();
    }
    c.restore();
  }

  function _draw(){
    const c=_riftCtx;
    if(!c)return;
    c.clearRect(0,0,_riftCanvas.width,_riftCanvas.height);
    _drawArenaBorder(c,_t);
    if(!_boss)return;
    const b=_boss;

    // ── Vínculo de Emaranhamento Quântico: linha pulsante ligando os
    // dois astros emaranhados, em coordenadas de tela. ──
    if(b.entangleA&&!b.entangleA.dead&&b.entangleB&&!b.entangleB.dead){
      const pa=_w2s(b.entangleA.x,b.entangleA.y);
      const pb=_w2s(b.entangleB.x,b.entangleB.y);
      const ep=0.5+0.5*Math.sin(_t*6);
      c.save();
      c.beginPath();c.moveTo(pa.sx,pa.sy);c.lineTo(pb.sx,pb.sy);
      c.strokeStyle=`rgba(120,220,255,${0.15+0.1*ep})`;c.lineWidth=6;c.stroke();
      c.beginPath();c.moveTo(pa.sx,pa.sy);c.lineTo(pb.sx,pb.sy);
      c.strokeStyle=`rgba(200,245,255,${0.55+0.35*ep})`;c.lineWidth=1.6;c.setLineDash([6,5]);
      c.lineDashOffset=-_t*30;
      c.stroke();
      c.setLineDash([]);
      c.restore();
    }

    const {sx,sy}=_w2s(b.wx,b.wy);
    // Núcleo pequeno de verdade — raio sólido, sem glow exagerado que
    // o fazia parecer gigante na tela. Escala com o zoom da câmera,
    // já que o boss agora vive em coordenadas de MUNDO.
    const baseR=Math.min(canvas.width,canvas.height)*0.042*b.sizeScale*cam.zoom;

    // ── Fantasmas de Superposição: 2 núcleos-ilusão desenhados ANTES
    // do núcleo real, levemente mais fracos/dessaturados — a diferença
    // sutil de brilho é a pista visual para identificar o núcleo real. ──
    if(b.superposActive&&b.superposGhosts.length){
      b.superposGhosts.forEach(g=>{
        const gsx=sx+g.ox*cam.zoom, gsy=sy+g.oy*cam.zoom;
        const ghostPulse=0.6+0.15*Math.sin(_t*2.4+g.phase);
        c.save();
        c.translate(gsx,gsy);
        c.beginPath();c.arc(0,0,baseR,0,Math.PI*2);
        c.fillStyle=`rgba(110,50,180,${ghostPulse*0.7})`;
        c.fill();
        c.strokeStyle=`rgba(170,130,220,${ghostPulse*0.5})`;
        c.lineWidth=Math.max(1,baseR*0.06);
        c.stroke();
        // olho simplificado, mais apagado que o real
        const eyeR=baseR*0.78,eyeOffsetY=baseR*0.12,straightY=-eyeR*0.55+eyeOffsetY;
        c.beginPath();
        c.moveTo(-eyeR,straightY);c.lineTo(eyeR,straightY);c.arc(0,straightY,eyeR,0,Math.PI,false);
        c.closePath();
        c.fillStyle=`rgba(255,255,255,${0.35+0.1*ghostPulse})`;
        c.fill();
        c.restore();
      });
    }

    c.save();
    c.translate(sx,sy);
    // ── Salto Quântico: fade out/in do núcleo real durante o piscar ──
    c.globalAlpha=b.blinkAlpha!==undefined?b.blinkAlpha:1;

    // ── Aura de distorção gravitacional (bem sutil, atrás de tudo) ──
    const distortR=baseR*9;
    const distortGrad=c.createRadialGradient(0,0,baseR*0.5,0,0,distortR);
    distortGrad.addColorStop(0,'rgba(120,60,220,0.08)');
    distortGrad.addColorStop(0.6,'rgba(60,20,140,0.04)');
    distortGrad.addColorStop(1,'rgba(20,10,40,0)');
    c.beginPath();c.arc(0,0,distortR,0,Math.PI*2);
    c.fillStyle=distortGrad;c.fill();

    // ── Raio central giratório: feixe fixo saindo do núcleo, girando
    // lentamente — ameaça própria do boss ativa desde a Fase 1. ──
    if(b.beamActive){
      const beamLen=Math.max(canvas.width,canvas.height)*1.4;
      const bx=Math.cos(b.beamAngle)*beamLen,by=Math.sin(b.beamAngle)*beamLen;
      c.save();
      c.beginPath();c.moveTo(0,0);c.lineTo(bx,by);
      c.strokeStyle='rgba(180,120,255,0.25)';c.lineWidth=baseR*1.1;c.lineCap='round';c.stroke();
      c.beginPath();c.moveTo(0,0);c.lineTo(bx,by);
      c.strokeStyle='rgba(230,200,255,0.8)';c.lineWidth=baseR*0.32;c.lineCap='round';c.stroke();
      c.restore();
    }

    // ── 3 órbitas elípticas cruzadas, girando RÁPIDO — alternando
    // sentido horário/anti-horário entre elas ──
    const orbitDefs=[
      {rx:baseR*8.6,ry:baseR*3.3,rot:b.ringAngle,        color:'rgba(210,190,255,0.55)'},
      {rx:baseR*8.6,ry:baseR*3.3,rot:-b.ringAngle2+Math.PI/3,color:'rgba(150,100,255,0.5)'},
      {rx:baseR*8.6,ry:baseR*3.3,rot:b.ringAngle3-Math.PI/3, color:'rgba(90,160,255,0.5)'},
    ];
    orbitDefs.forEach(od=>{
      c.save();
      c.rotate(od.rot);
      c.beginPath();
      c.ellipse(0,0,od.rx,od.ry,0,0,Math.PI*2);
      c.strokeStyle=od.color;
      c.lineWidth=Math.max(1.4,baseR*0.075);
      c.stroke();
      c.restore();
    });

    // ── Elétrons pequenos (bolinhas amarelas) GRUDADOS na borda do
    // núcleo, sem espaço entre eles e o núcleo — igual ao rascunho ──
    const smallElectronCount=10;
    const smallOrbitR=baseR*2.1;
    for(let i=0;i<smallElectronCount;i++){
      const a=(i/smallElectronCount)*Math.PI*2+b.ringAngle2*1.2;
      const ex=Math.cos(a)*smallOrbitR, ey=Math.sin(a)*smallOrbitR;
      const er=baseR*0.24;
      c.beginPath();c.arc(ex,ey,er,0,Math.PI*2);
      c.fillStyle='rgba(255,220,120,0.95)';
      c.shadowColor='rgba(255,210,100,0.7)';c.shadowBlur=er*1.2;
      c.fill();
      c.shadowBlur=0;
    }

    // ── Bolinhas maiores (satélites) do lado de FORA das órbitas
    // elípticas — só desenha aqui as que estão em órbita normal; as
    // que estão voando/voltando (ataque bumerangue) são desenhadas
    // depois, em coordenadas de MUNDO absolutas. ──
    const bigMoonCount=b.moons?b.moons.length:8;
    const bigOrbitR=baseR*11.5;
    for(let i=0;i<bigMoonCount;i++){
      if(b.moons&&b.moons[i]&&b.moons[i].state!=='orbit')continue;
      const a=(i/bigMoonCount)*Math.PI*2+b.ringAngle3*0.4;
      const mx=Math.cos(a)*bigOrbitR, my=Math.sin(a)*bigOrbitR;
      const mr=baseR*0.85;
      const moonGrad=c.createRadialGradient(mx-mr*0.3,my-mr*0.3,mr*0.1,mx,my,mr);
      moonGrad.addColorStop(0,'rgba(255,235,170,0.95)');
      moonGrad.addColorStop(1,'rgba(220,170,60,0.85)');
      c.beginPath();c.arc(mx,my,mr,0,Math.PI*2);
      c.fillStyle=moonGrad;
      c.shadowColor='rgba(255,210,100,0.5)';c.shadowBlur=mr*0.8;
      c.fill();
      c.shadowBlur=0;
    }

    // ── Núcleo central roxo, pequeno, com OLHO CARTOON BRAVO ──
    if(!b.invisible){
      const pulse=0.85+0.15*Math.sin(_t*3);
      c.beginPath();c.arc(0,0,baseR,0,Math.PI*2);
      c.fillStyle=`rgba(130,60,210,${pulse})`;
      c.shadowColor='rgba(160,100,255,0.7)';c.shadowBlur=baseR*0.4;
      c.fill();
      c.shadowBlur=0;
      c.strokeStyle=`rgba(210,170,255,${0.8*pulse})`;
      c.lineWidth=Math.max(1,baseR*0.06);
      c.stroke();

      // Olho: "D" deitado — uma reta horizontal em cima, conectada a um
      // semicírculo embaixo (mesmo raio da reta, geometria consistente).
      // Círculo preto pequeno, centralizado exatamente no meio da forma.
      const eyeR=baseR*0.78; // raio do semicírculo = metade da reta de cima
      const eyeOffsetY=baseR*0.12; // desloca o olho inteiro um pouco pra baixo
      const straightY=-eyeR*0.55+eyeOffsetY; // reta fica acima do centro do semicírculo
      c.beginPath();
      c.moveTo(-eyeR,straightY);
      c.lineTo(eyeR,straightY);
      c.arc(0,straightY,eyeR,0,Math.PI,false);
      c.closePath();
      c.fillStyle='#ffffff';
      c.fill();
      c.lineWidth=Math.max(1.4,baseR*0.1);
      c.strokeStyle='#0a0410';
      c.stroke();

      // Círculo preto pequeno, centralizado no centro geométrico da forma
      const eyeCenterY=straightY+eyeR*0.4; // centro visual do D (entre a reta e a base da curva)
      const irisR=eyeR*0.3;
      c.beginPath();c.arc(0,eyeCenterY,irisR,0,Math.PI*2);
      c.fillStyle='#0a0410';
      c.fill();
    }

    // Fase 3: pulso visual do Colapso Gravitacional (anéis convergindo
    // para o centro), substitui a cintilação puramente decorativa —
    // reforça a mecânica real de puxão gravitacional ativa nesse momento.
    if(b.phase===3&&b.collapsePulse>0){
      const cp=b.collapsePulse/1.4;
      for(let ri=0;ri<3;ri++){
        const rr=bigOrbitR*1.3*(1-((cp+ri*0.28)%1));
        c.beginPath();c.arc(0,0,Math.max(4,rr),0,Math.PI*2);
        c.strokeStyle=`rgba(180,120,255,${0.5*cp})`;
        c.lineWidth=2.4;c.stroke();
      }
    }

    c.restore();

    // ── Luas em ataque bumerangue (voando/voltando) — desenhadas em
    // coordenadas de MUNDO absolutas, já que se afastam do boss ──
    if(b.moons){
      b.moons.forEach(m=>{
        if(m.state==='orbit')return;
        const p=_w2s(m.wx,m.wy);
        const circling=m.state==='circling';
        const mr=baseR*(circling?0.95:0.85);
        const moonGrad=c.createRadialGradient(p.sx-mr*0.3,p.sy-mr*0.3,mr*0.1,p.sx,p.sy,mr);
        if(circling){
          moonGrad.addColorStop(0,'rgba(255,200,170,0.98)');
          moonGrad.addColorStop(1,'rgba(255,90,40,0.9)');
        } else {
          moonGrad.addColorStop(0,'rgba(255,235,170,0.95)');
          moonGrad.addColorStop(1,'rgba(220,170,60,0.85)');
        }
        c.beginPath();c.arc(p.sx,p.sy,mr,0,Math.PI*2);
        c.fillStyle=moonGrad;
        c.shadowColor=circling?'rgba(255,110,40,0.75)':'rgba(255,210,100,0.6)';
        c.shadowBlur=mr*(circling?1.5:1.1);
        c.fill();
        c.shadowBlur=0;
      });
    }
    _drawFx(c);
    _drawCombatantBars(c);

    // HP mini bar acima do boss (mesmo padrão dos outros bosses)

    const hpPct=Math.max(0,b.hp/b.maxHP);
    const bw=baseR*7.5,bh=5;
    const bx=sx-bw/2,by=sy-baseR*12.8;
    c.beginPath();c.rect(bx,by,bw,bh);c.fillStyle='rgba(0,0,0,.6)';c.fill();
    c.beginPath();c.rect(bx,by,bw*hpPct,bh);
    c.fillStyle=hpPct>.6?'#a06cff':hpPct>.3?'#7a3fe0':'#4a1fa0';c.fill();
  }

  // HP bar acima de cada astro do Tech Pack combatendo na arena —
  // mesmo padrão visual das outras (fundo preto + barra colorida).
  function _drawCombatantBars(c){
    if(typeof objects==='undefined')return;
    for(let i=0;i<objects.length;i++){
      const o=objects[i];
      if(o.dead||o._galxHp===undefined)continue;
      const p=_w2s(o.x,o.y);
      const r=(o.radius||14)*cam.zoom;
      const pct=Math.max(0,o._galxHp/o._galxMaxHp);
      const bw=Math.max(30,r*2.4),bh=4;
      const bx=p.sx-bw/2,by=p.sy-r-12*cam.zoom;
      c.beginPath();c.rect(bx,by,bw,bh);c.fillStyle='rgba(0,0,0,.6)';c.fill();
      c.beginPath();c.rect(bx,by,bw*pct,bh);
      c.fillStyle=pct>.6?'#44ddff':pct>.3?'#ffcc44':'#ff4444';c.fill();
    }
  }

  function _finish(victory){
    _active=false;
    window._invasionActive=false;
    // Zoom nunca foi travado nesta batalha (ver start()) — nada a restaurar.
    if(_animFrame){cancelAnimationFrame(_animFrame);_animFrame=null;}
    if(_riftCanvas)_riftCanvas.classList.remove('active');
    const bar=document.getElementById('galx-boss-hp-bar');
    if(bar)bar.classList.remove('active');
    _setInvasionAstroLockUI(false,GALAXIMY_BLOCKED_ASTRO_TYPES);
    _stopGalaximyAudio();
    window._galaximyAstroCaps=null;
    window._galaximyResetUses=0;
    window._galaximyMoveUses=0;
    const galxacBar=document.getElementById('galaximy-astro-counters-bar');
    if(galxacBar)galxacBar.classList.remove('active');
    if(victory){
      showTooltip('🌌🏆 Galaximy derrotado! O vórtice colapsa e se dissipa...');
      if(typeof _cosmonarioDiscover==='function')_cosmonarioDiscover('bossGalaximy');
      if(typeof _bossAchTrigger==='function')_bossAchTrigger('super_explosao_quantica');
      // Recompensa de Logs, Quantiks e Staris por vitória — repetível a
      // cada combate vencido, mesmo padrão dos demais bosses da Fase Cósmica.
      if(typeof addLogs==='function'){
        addLogs(1800);
        setTimeout(()=>showTooltip('📊 +1800 LOGS pela vitória!'),1400);
      }
      if(typeof addQuantiks==='function'){
        addQuantiks(500);
        setTimeout(()=>showTooltip('⚛️ +500 QUANTIKS pela vitória!'),2200);
      }
      if(typeof addStaris==='function'){
        addStaris(500);
        setTimeout(()=>showTooltip('✨ +500 STARIS pela vitória!'),3000);
      }
    }
    // Limpa os campos de combate dos astros do Tech Pack sobreviventes
    // — eles voltam a ser puramente passivos fora da batalha.
    if(typeof objects!=='undefined'){
      objects.forEach(o=>{
        if(o._galxHp!==undefined){
          delete o._galxHp;delete o._galxMaxHp;delete o._galxAtk;
          delete o._galxDef;delete o._galxAtkCooldown;
        }
      });
    }
    // ── Restaura TODOS os astros antigos guardados no início da batalha ──
    objects.length=0;
    objects.push(..._preInvasionStash);
    _preInvasionStash=[];
    selectedObj=null;
    _boss=null;
    _worldBounds=null;
    _fxParticles=[];
    _hosts=[];
  }

  function forceEnd(){ if(_active)_finish(false); }

  // ── Utilitários de Mod Menu / testes ────────────────────────────
  function forcePhase(n){
    if(!_active||!_boss||_boss.dying)return false;
    const target=n>=3?PHASE3_PCT*0.6:n===2?(PHASE2_PCT+PHASE3_PCT)/2:1;
    _boss.hp=Math.max(1,Math.round(_boss.maxHP*Math.min(target,0.999)));
    _applyPhaseTransition(_getPhase(_boss.hp,_boss.maxHP));
    return true;
  }
  function hitkill(){
    if(!_active||!_boss)return false;
    _boss.invisible=false;
    _boss.hp=0;
    _updateBar();
    if(!_boss.dying){_boss.dying=true;_boss.dyingT=0;}
    return true;
  }

  return { start, isActive, forceEnd, forcePhase, hitkill };
})();
//  Raros. Só ocorrem em astros comuns já existentes em `objects`
//  (planetas, estrelas, etc — não em astros das raças cósmicas nem em
//  Buracos Errantes). Um astro "vivo" persegue e ataca OUTROS astros,
//  nunca o próprio jogador diretamente. Visual diferenciado: pulso
//  orgânico + "olhos" simples desenhados por cima do astro original,
//  sem alterar a classe/lógica original do astro.
// ═══════════════════════════════════════════════════════════════════

const COSMIC_LIVING_CHECK_INTERVAL = 6; // segundos entre tentativas de "despertar" um astro
const COSMIC_LIVING_CHANCE = 0.05;       // chance de despertar por tentativa (raro)
const COSMIC_LIVING_MAX = 3;             // teto de astros vivos simultâneos
const COSMIC_LIVING_SPEED = 24;
const COSMIC_LIVING_ATTACK_RANGE = 34;
const COSMIC_LIVING_ATTACK_COOLDOWN = 1.4;

let _cosmicLivingTimer = 0;
let _cosmicLivingList = []; // referências a objetos de `objects` marcados como vivos

function _cosmicTryAwaken() {
  if (typeof objects === 'undefined' || !objects.length) return;
  if (_cosmicLivingList.length >= COSMIC_LIVING_MAX) return;
  if (_isBattle()) return; // não desperta astros vivos durante batalha de boss
  if (Math.random() > COSMIC_LIVING_CHANCE) return;

  const candidates = objects.filter(o =>
    !o.dead && !o._cosmicLiving && !o._cosmicColonizedBy &&
    ['planet','star','moon','comet','meteor','gasgiant','icegiant','superearth','dwarfplanet'].includes((o.type||'').toLowerCase())
  );
  if (!candidates.length) return;

  const target = candidates[Math.floor(rand(0, candidates.length))];
  target._cosmicLiving = true;
  target._cosmicAttackCd = 0;
  target._cosmicAwakenPhase = rand(0, Math.PI * 2);
  _cosmicLivingList.push(target);
}

function cosmicLivingUpdate(dt) {
  _cosmicLivingTimer += dt;
  if (_cosmicLivingTimer >= COSMIC_LIVING_CHECK_INTERVAL) {
    _cosmicLivingTimer = 0;
    _cosmicTryAwaken();
  }
  // Durante batalha de boss: astros vivos existentes ficam parados,
  // sem perseguir/atacar outros astros.
  if (_isBattle()) return;

  for (let i = _cosmicLivingList.length - 1; i >= 0; i--) {
    const o = _cosmicLivingList[i];
    if (o.dead) { _cosmicLivingList.splice(i, 1); continue; }
    o._cosmicAwakenPhase += dt;
    o._cosmicAttackCd = Math.max(0, (o._cosmicAttackCd || 0) - dt);

    // Acha o astro comum mais próximo (que não seja ele mesmo, nem
    // outro astro vivo, nem colonizado) para perseguir/atacar.
    let prey = null, bestD = Infinity;
    objects.forEach(other => {
      if (other === o || other.dead || other._cosmicLiving) return;
      const d = Math.hypot(other.x - o.x, other.y - o.y);
      if (d < bestD) { bestD = d; prey = other; }
    });

    if (prey) {
      const dx = prey.x - o.x, dy = prey.y - o.y;
      const d = Math.hypot(dx, dy) || 1;
      if (d > COSMIC_LIVING_ATTACK_RANGE) {
        o.x += (dx / d) * COSMIC_LIVING_SPEED * dt;
        o.y += (dy / d) * COSMIC_LIVING_SPEED * dt;
      } else if (o._cosmicAttackCd <= 0) {
        // Ataque simples: empurra o alvo com um pequeno impulso
        // (não altera HP/sistemas de dano existentes — é ambiental).
        prey.vx = (prey.vx || 0) + (dx / d) * 40;
        prey.vy = (prey.vy || 0) + (dy / d) * 40;
        o._cosmicAttackCd = COSMIC_LIVING_ATTACK_COOLDOWN;
      }
    }
  }
}

function cosmicLivingDraw(ctx) {
  if (_isBattle()) return; // esconde a aura hostil durante batalha de boss
  _cosmicLivingList.forEach(o => {
    if (o.dead) return;
    const sx = o.sx(), sy = o.sy(), r = o.sr();
    if (sx < -100 || sx > canvas.width + 100 || sy < -100 || sy > canvas.height + 100) return;

    // Aura pulsante vermelho-escura por cima do astro original
    const pulse = 0.5 + 0.5 * Math.sin(o._cosmicAwakenPhase * 3);
    ctx.save();
    ctx.beginPath();
    ctx.arc(sx, sy, r * 1.25, 0, Math.PI * 2);
    ctx.strokeStyle = `rgba(220,40,40,${0.35 + pulse * 0.35})`;
    ctx.lineWidth = 2;
    ctx.stroke();

    // "Olhos" simples — dois pontos claros na direção de movimento/presa
    const eyeDist = r * 0.35;
    const ang = Math.atan2(o.vy || 0, o.vx || 1) || 0;
    const perp = ang + Math.PI / 2;
    [-1, 1].forEach(side => {
      const ex = sx + Math.cos(ang) * r * 0.4 + Math.cos(perp) * eyeDist * side;
      const ey = sy + Math.sin(ang) * r * 0.4 + Math.sin(perp) * eyeDist * side;
      ctx.beginPath();
      ctx.arc(ex, ey, Math.max(1.2, r * 0.09), 0, Math.PI * 2);
      ctx.fillStyle = '#ffef8a';
      ctx.fill();
      ctx.beginPath();
      ctx.arc(ex, ey, Math.max(0.6, r * 0.045), 0, Math.PI * 2);
      ctx.fillStyle = '#1a0000';
      ctx.fill();
    });
    ctx.restore();
  });
}

function cosmicLivingReset() {
  _cosmicLivingList.forEach(o => { if(o) { o._cosmicLiving = false; } });
  _cosmicLivingList = [];
  _cosmicLivingTimer = 0;
}

// ═══════════════════════════════════════════════════════════════════
//  MÓDULO: COMETAS/METEOROS PERSEGUIDORES
// ═══════════════════════════════════════════════════════════════════
//  Cometas/meteoros comuns que, ao serem avistados em tela (dentro do
//  viewport atual) enquanto um astro do jogador está visível, passam a
//  perseguir esse astro permanentemente — mesmo que o astro saia da
//  tela depois. É um comportamento leve sobre astros já existentes,
//  sem criar uma nova classe.
// ═══════════════════════════════════════════════════════════════════

const COSMIC_CHASER_CHECK_INTERVAL = 4;
const COSMIC_CHASER_CHANCE = 0.12;
const COSMIC_CHASER_SPEED_BONUS = 1.6; // multiplicador de velocidade quando perseguindo

let _cosmicChaserTimer = 0;
let _cosmicChaserList = [];

function _isOnScreen(o) {
  const sx = o.sx(), sy = o.sy();
  return sx > -40 && sx < canvas.width + 40 && sy > -40 && sy < canvas.height + 40;
}

function _cosmicTryMarkChaser() {
  if (typeof objects === 'undefined' || !objects.length) return;
  if (_isBattle()) return; // não inicia novas perseguições durante batalha de boss
  const comets = objects.filter(o => !o.dead && !o._cosmicChasing &&
    ['comet','meteor'].includes((o.type||'').toLowerCase()) && _isOnScreen(o));
  if (!comets.length) return;

  // Astro "do jogador": qualquer astro comum visível em tela no momento
  // (o mais próximo do centro da tela é escolhido como alvo avistado).
  const playerAstros = objects.filter(o => !o.dead &&
    !['comet','meteor'].includes((o.type||'').toLowerCase()) && _isOnScreen(o));
  if (!playerAstros.length) return;

  comets.forEach(c => {
    if (Math.random() > COSMIC_CHASER_CHANCE) return;
    let target = null, bestD = Infinity;
    playerAstros.forEach(p => {
      const d = Math.hypot(p.x - c.x, p.y - c.y);
      if (d < bestD) { bestD = d; target = p; }
    });
    if (target) {
      c._cosmicChasing = true;
      c._cosmicChaseTargetId = target.id;
      _cosmicChaserList.push(c);
    }
  });
}

function cosmicChasersUpdate(dt) {
  _cosmicChaserTimer += dt;
  if (_cosmicChaserTimer >= COSMIC_CHASER_CHECK_INTERVAL) {
    _cosmicChaserTimer = 0;
    _cosmicTryMarkChaser();
  }
  // Durante batalha de boss: perseguições já em curso pausam (o cometa
  // mantém sua velocidade atual, mas para de re-mirar no alvo).
  if (_isBattle()) return;
  for (let i = _cosmicChaserList.length - 1; i >= 0; i--) {
    const c = _cosmicChaserList[i];
    if (c.dead) { _cosmicChaserList.splice(i, 1); continue; }
    const target = objects.find(o => o.id === c._cosmicChaseTargetId);
    if (!target || target.dead) { c._cosmicChasing = false; _cosmicChaserList.splice(i, 1); continue; }

    const dx = target.x - c.x, dy = target.y - c.y;
    const d = Math.hypot(dx, dy) || 1;
    const baseSpeed = Math.hypot(c.vx || 0, c.vy || 0) || 40;
    c.vx = (dx / d) * baseSpeed * COSMIC_CHASER_SPEED_BONUS;
    c.vy = (dy / d) * baseSpeed * COSMIC_CHASER_SPEED_BONUS;
  }
}

function cosmicChasersReset() {
  _cosmicChaserList.forEach(c => { if(c) c._cosmicChasing = false; });
  _cosmicChaserList = [];
  _cosmicChaserTimer = 0;
}

// ═══════════════════════════════════════════════════════════════════
//  MÓDULO: BURACOS NEGROS ERRANTES
// ═══════════════════════════════════════════════════════════════════
//  Extremamente raros. Vagam infinitamente em linha reta (nunca perdem
//  velocidade — sem atrito/desaceleração), com massa/raio variáveis a
//  cada um. NÃO dependem do sistema de chunks do mundo: continuam
//  existindo e se movendo mesmo bem fora da área carregada/visível,
//  ao contrário das outras entidades cósmicas (que despawnam em 12s
//  fora da área de referência). Visual bem distinto de um buraco negro
//  comum do jogo (anel externo pulsante + rastro de distorção).
// ═══════════════════════════════════════════════════════════════════

const COSMIC_WANDERER_SPAWN_INTERVAL_MIN = 40; // bem mais raro que as raças
const COSMIC_WANDERER_SPAWN_INTERVAL_MAX = 90;
const COSMIC_WANDERER_MAX = 3;
const COSMIC_WANDERER_MIN_RADIUS = 14;
const COSMIC_WANDERER_MAX_RADIUS = 46;
const COSMIC_WANDERER_MIN_SPEED = 18;
const COSMIC_WANDERER_MAX_SPEED = 55;

let _cosmicWanderers = [];
let _cosmicWandererTimer = 0;
let _cosmicWandererNextAt = rand(COSMIC_WANDERER_SPAWN_INTERVAL_MIN, COSMIC_WANDERER_SPAWN_INTERVAL_MAX);
let _cosmicWandererIdCounter = 1;

function _cosmicSpawnWanderer() {
  const pos = _cosmicRollSpawnPos();
  const angle = rand(0, Math.PI * 2);
  const speed = rand(COSMIC_WANDERER_MIN_SPEED, COSMIC_WANDERER_MAX_SPEED);
  const radius = rand(COSMIC_WANDERER_MIN_RADIUS, COSMIC_WANDERER_MAX_RADIUS);
  _cosmicWanderers.push({
    id: 'wanderer_' + (_cosmicWandererIdCounter++),
    x: pos.x, y: pos.y,
    vx: Math.cos(angle) * speed,
    vy: Math.sin(angle) * speed,
    radius,
    phase: rand(0, Math.PI * 2),
  });
}

function cosmicWanderersUpdate(dt) {
  _cosmicWandererTimer += dt;
  if (_cosmicWandererTimer >= _cosmicWandererNextAt && _cosmicWanderers.length < COSMIC_WANDERER_MAX) {
    _cosmicWandererTimer = 0;
    _cosmicWandererNextAt = rand(COSMIC_WANDERER_SPAWN_INTERVAL_MIN, COSMIC_WANDERER_SPAWN_INTERVAL_MAX);
    if (!_isBattle()) _cosmicSpawnWanderer();
  }
  // Durante batalha de boss: buracos negros errantes param no lugar —
  // evita que um deles cruze a arena e atrapalhe o combate.
  if (_isBattle()) return;
  // Movimento constante, sem atrito e SEM regra de despawn por chunk/
  // distância — vagam para sempre, estejam ou não perto do jogador.
  _cosmicWanderers.forEach(w => {
    w.x += w.vx * dt;
    w.y += w.vy * dt;
    w.phase += dt;
  });
}

function cosmicWanderersDraw(ctx) {
  if (_isBattle()) return; // some visualmente durante batalha de boss
  _cosmicWanderers.forEach(w => {
    const sx = (w.x - cam.x) * cam.zoom + canvas.width * 0.5;
    const sy = (w.y - cam.y) * cam.zoom + canvas.height * 0.5;
    if (sx < -150 || sx > canvas.width + 150 || sy < -150 || sy > canvas.height + 150) return;

    const r = w.radius * cam.zoom;
    ctx.save();

    // Rastro de distorção — leve trilha na direção contrária ao movimento
    const trailAng = Math.atan2(-w.vy, -w.vx);
    const trailGrd = ctx.createLinearGradient(sx, sy, sx + Math.cos(trailAng) * r * 4, sy + Math.sin(trailAng) * r * 4);
    trailGrd.addColorStop(0, 'rgba(150,0,255,0.28)');
    trailGrd.addColorStop(1, 'rgba(150,0,255,0)');
    ctx.beginPath();
    ctx.moveTo(sx, sy);
    ctx.lineTo(sx + Math.cos(trailAng) * r * 4 + Math.cos(trailAng + 1.4) * r * 0.6, sy + Math.sin(trailAng) * r * 4 + Math.sin(trailAng + 1.4) * r * 0.6);
    ctx.lineTo(sx + Math.cos(trailAng) * r * 4 + Math.cos(trailAng - 1.4) * r * 0.6, sy + Math.sin(trailAng) * r * 4 + Math.sin(trailAng - 1.4) * r * 0.6);
    ctx.closePath();
    ctx.fillStyle = trailGrd;
    ctx.fill();

    // Corpo — núcleo negro absoluto
    ctx.beginPath();
    ctx.arc(sx, sy, r, 0, Math.PI * 2);
    ctx.fillStyle = '#000000';
    ctx.fill();

    // Anel externo pulsante roxo/violeta (visual distinto do buraco negro comum)
    const pulse = 1 + Math.sin(w.phase * 2.2) * 0.15;
    ctx.beginPath();
    ctx.arc(sx, sy, r * 1.5 * pulse, 0, Math.PI * 2);
    ctx.strokeStyle = 'rgba(180,60,255,0.6)';
    ctx.lineWidth = 2;
    ctx.stroke();
    ctx.beginPath();
    ctx.arc(sx, sy, r * 1.9 * pulse, 0, Math.PI * 2);
    ctx.strokeStyle = 'rgba(180,60,255,0.25)';
    ctx.lineWidth = 1;
    ctx.stroke();

    ctx.restore();
  });
}

function cosmicWanderersReset() {
  _cosmicWanderers = [];
  _cosmicWandererTimer = 0;
}

// ═══════════════════════════════════════════════════════════════════
//  MÓDULO: ROCHAS ESPACIAIS COM MINÉRIO — Fase Cósmica
// ═══════════════════════════════════════════════════════════════════
//  Rochas invisíveis espalhadas pelo mapa, cada uma com um minério
//  (reaproveitando a lista MINERALS já usada nas abas de edição de
//  astro). Só ficam visíveis depois de serem "encontradas" por uma
//  Sonda Cósmica que chegue perto o suficiente. Puramente visual/
//  informativo por enquanto — não são coletadas.
// ═══════════════════════════════════════════════════════════════════

// Minérios EXCLUSIVOS de cada bioma cósmico — nomes fictícios/elegantes,
// temáticos à raça dona do território, nunca sorteados fora dele. Usam
// o mesmo formato de tier {weight, energy} de COSMIC_MINERAL_TIERS,
// então herdam de graça toda a lógica de raridade/cor/upgrade já
// existente — só entram num "pool" separado, específico do bioma.
const COSMIC_BIOME_MINERAL_TIERS = {
  plasmicea: {
    'Escória Ígnea':      { weight: 24, energy: 3 },  // comum, sobra da fundição natural do bioma
    'Sal de Magma':       { weight: 16, energy: 5 },
    'Cristal Piroclasto':  { weight: 8,  energy: 9 },
    'Núcleo Solar-Fóssil': { weight: 3,  energy: 16 }, // raríssimo, resquício de uma estrela morta
  },
  fungica: {
    'Esporo Vítreo':      { weight: 24, energy: 3 },
    'Resina Miceliar':    { weight: 16, energy: 5 },
    'Âmbar Bioluminoso':  { weight: 8,  energy: 9 },
    'Semente Primordial': { weight: 3,  energy: 16 },
  },
  necrida: {
    'Pó Ossífero':        { weight: 24, energy: 3 },
    'Cinza Sideral':       { weight: 16, energy: 5 },
    'Marfim Estelar':     { weight: 8,  energy: 9 },
    'Relicário Ancestral':{ weight: 3,  energy: 16 },
  },
  viscera: {
    'Coágulo Mineral':      { weight: 24, energy: 3 },
    'Membrana Cristalina':  { weight: 16, energy: 5 },
    'Plasma Vermelho':      { weight: 8,  energy: 9 },
    'Coração de Víscera':   { weight: 3,  energy: 16 },
  },
  robotica: {
    'Liga Ferrolume':          { weight: 24, energy: 3 },
    'Circuito Solidificado':   { weight: 16, energy: 5 },
    'Núcleo Supercondutor':    { weight: 8,  energy: 9 },
    'Chip Singularidade':      { weight: 3,  energy: 16 },
  },
};

// Sorteia um minério ponderado dentro do pool exclusivo de um bioma
// (mesma lógica de _cosmicRollWeightedMineral, mas restrita ao raceId).
function _cosmicRollBiomeMineral(raceId) {
  const pool = COSMIC_BIOME_MINERAL_TIERS[raceId];
  if (!pool) return _cosmicRollWeightedMineral(); // fallback de segurança
  const names = Object.keys(pool);
  const total = names.reduce((s, n) => s + pool[n].weight, 0);
  let r = Math.random() * total;
  for (const name of names) {
    r -= pool[name].weight;
    if (r <= 0) return name;
  }
  return names[0];
}

// Retorna o tier {weight, energy} de um minério, seja ele do pool
// global (COSMIC_MINERAL_TIERS) ou de algum pool temático de bioma —
// usado por qualquer código (cor, energia de upgrade) que precise da
// info sem saber de qual dos dois pools o minério veio.
function _cosmicMineralTierLookup(mineral) {
  if (COSMIC_MINERAL_TIERS[mineral]) return COSMIC_MINERAL_TIERS[mineral];
  for (const raceId in COSMIC_BIOME_MINERAL_TIERS) {
    const pool = COSMIC_BIOME_MINERAL_TIERS[raceId];
    if (pool[mineral]) return pool[mineral];
  }
  return null;
}

// ═══════════════════════════════════════════════════════════════════
//  NAVES ABANDONADAS — Fase Cósmica: destroços gigantes à deriva,
//  puramente visuais (sem interação por enquanto). Espalhadas pelo
//  mesmo sistema de chunk grande usado nas Cosmic Rocks, mas raras
//  (40% de chance por chunk) e SEM limite de 1 por chunk pra sempre —
//  cada chunk grande rola sua própria chance uma única vez.
// ═══════════════════════════════════════════════════════════════════
const DERELICT_CHUNK_SIZE = 2400;      // chunk um pouco maior que o de rochas: mais raras ainda
const DERELICT_SPAWN_CHANCE = 0.4;     // 40% de chance de existir 1 nave por chunk
const DERELICT_CHUNK_LOAD_RADIUS = 1;  // grade 3x3 ao redor da câmera
const DERELICT_MAX_TOTAL = 10;         // teto absoluto simultâneo (segurança de performance)
const DERELICT_MIN_SEPARATION = 900;   // são grandes, não podem nascer muito próximas

let _derelictShips = [];
let _derelictChunks = new Set(); // chunks "cx,cy" já resolvidos (spawnou ou não)

function _derelictChunkKey(cx,cy){return cx+','+cy;}
function _derelictChunkOf(x,y){return {cx:Math.floor(x/DERELICT_CHUNK_SIZE),cy:Math.floor(y/DERELICT_CHUNK_SIZE)};}

// Gera o casco em formato de polígono irregular alongado (silhueta de
// nave-mãe partida), mais alguns "destroços soltos" menores ao redor —
// tudo sem luzes acesas (nave morta, sem energia).
function _derelictMakeHull(len){
  const w=len*(0.32+rand(0,0.1));
  const pts=[
    {x:-len*0.5,y:0},
    {x:-len*0.32,y:-w*0.42},
    {x:-len*0.05,y:-w*0.5},
    {x:len*0.22,y:-w*0.36},
    {x:len*0.48,y:-w*0.12},
    {x:len*0.5,y:0},
    {x:len*0.46,y:w*0.18},
    {x:len*0.18,y:w*0.4},
    {x:-len*0.15,y:w*0.48},
    {x:-len*0.4,y:w*0.3},
  ];
  // desloca levemente cada ponto pra parecer avariado/irregular, não um casco liso
  return pts.map(p=>({x:p.x+rand(-len*0.03,len*0.03),y:p.y+rand(-len*0.03,len*0.03)}));
}
function _derelictMakeDebris(len,count){
  const debris=[];
  for(let i=0;i<count;i++){
    debris.push({
      ox:rand(-len*0.75,len*0.75),
      oy:rand(-len*0.4,len*0.4),
      r:rand(len*0.03,len*0.08),
      rot:rand(0,Math.PI*2),
      sides:3+Math.floor(rand(0,3)),
    });
  }
  return debris;
}

function _derelictSpawn(x,y){
  const len=rand(260,480); // GRANDES — pra sobrepor astros normais com folga
  _derelictShips.push({
    id:'derelict_'+(_cosmicIdCounter++),
    x,y,
    len,
    hull:_derelictMakeHull(len),
    debris:_derelictMakeDebris(len,4+Math.floor(rand(0,5))),
    angle:rand(0,Math.PI*2),
    // deriva bem lenta e aleatória — velocidade fixa por nave, direção fixa
    vx:rand(-1,1)*rand(1.5,4),
    vy:rand(-1,1)*rand(1.5,4),
    rotSpeed:rand(-1,1)*0.015, // rotação residual bem sutil (nave morta girando devagar)
    flicker:rand(0,Math.PI*2), // fase de uma luz de emergência piscando fraca
    tint:['#5a5f6b','#4a4536','#4b3d4a','#3d4a4a'][Math.floor(rand(0,4))], // variações de metal frio
  });
}

// Resolve um chunk uma única vez: rola 40%, se passar spawna 1 nave em
// posição aleatória dentro dele (respeitando separação mínima).
function _derelictPopulateChunk(cx,cy){
  const key=_derelictChunkKey(cx,cy);
  if(_derelictChunks.has(key))return;
  _derelictChunks.add(key);
  if(_derelictShips.length>=DERELICT_MAX_TOTAL)return;
  if(Math.random()>DERELICT_SPAWN_CHANCE)return;
  const x0=cx*DERELICT_CHUNK_SIZE,y0=cy*DERELICT_CHUNK_SIZE;
  let tries=0;
  while(tries<20){
    const x=x0+rand(0,DERELICT_CHUNK_SIZE),y=y0+rand(0,DERELICT_CHUNK_SIZE);
    const tooClose=_derelictShips.some(s=>Math.hypot(s.x-x,s.y-y)<DERELICT_MIN_SEPARATION);
    if(!tooClose){_derelictSpawn(x,y);return;}
    tries++;
  }
}

function _derelictEnsureSpawns(){
  const{cx:ccx,cy:ccy}=_derelictChunkOf(cam.x,cam.y);
  for(let dx=-DERELICT_CHUNK_LOAD_RADIUS;dx<=DERELICT_CHUNK_LOAD_RADIUS;dx++){
    for(let dy=-DERELICT_CHUNK_LOAD_RADIUS;dy<=DERELICT_CHUNK_LOAD_RADIUS;dy++){
      _derelictPopulateChunk(ccx+dx,ccy+dy);
    }
  }
}

function cosmicDerelictsUpdate(dt){
  _derelictEnsureSpawns();
  _derelictShips.forEach(s=>{
    s.x+=s.vx*dt;s.y+=s.vy*dt;
    s.angle+=s.rotSpeed*dt;
    s.flicker+=dt;
  });
}

function cosmicDerelictsDraw(ctx){
  _derelictShips.forEach(s=>{
    const scr=worldToScreen(s.x,s.y);
    const scale=cam.zoom;
    const visRadius=s.len*0.7*scale;
    // culling simples: não desenha se estiver bem fora da tela
    if(scr.x<-visRadius-100||scr.x>canvas.width+visRadius+100||
       scr.y<-visRadius-100||scr.y>canvas.height+visRadius+100)return;
    ctx.save();
    ctx.translate(scr.x,scr.y);
    ctx.rotate(s.angle);
    ctx.scale(scale,scale);
    // Casco principal — metal frio, sem brilho, levemente transparente
    // pra não parecer um astro "vivo" saturado.
    ctx.beginPath();
    s.hull.forEach((p,i)=>{i===0?ctx.moveTo(p.x,p.y):ctx.lineTo(p.x,p.y);});
    ctx.closePath();
    const g=ctx.createLinearGradient(-s.len*0.5,0,s.len*0.5,0);
    g.addColorStop(0,'#15161a');g.addColorStop(0.5,s.tint);g.addColorStop(1,'#0d0e10');
    ctx.fillStyle=g;ctx.fill();
    ctx.strokeStyle='rgba(0,0,0,0.6)';ctx.lineWidth=2;ctx.stroke();
    // Painéis/linhas internas do casco (sugerindo estrutura, sem luz própria)
    ctx.strokeStyle='rgba(0,0,0,0.35)';ctx.lineWidth=1;
    for(let i=1;i<4;i++){
      const fx=-s.len*0.5+(s.len*i/4);
      ctx.beginPath();ctx.moveTo(fx,-s.len*0.22);ctx.lineTo(fx,s.len*0.22);ctx.stroke();
    }
    // Rachadura central (avaria visível)
    ctx.strokeStyle='rgba(255,120,60,0.25)';ctx.lineWidth=1.4;
    ctx.beginPath();
    ctx.moveTo(-s.len*0.1,-s.len*0.15);
    ctx.lineTo(s.len*0.02,-s.len*0.02);
    ctx.lineTo(-s.len*0.03,s.len*0.05);
    ctx.lineTo(s.len*0.12,s.len*0.18);
    ctx.stroke();
    // Uma única luz de emergência fraca piscando (única fonte de cor viva)
    const flick=0.15+0.15*Math.max(0,Math.sin(s.flicker*0.8));
    ctx.beginPath();ctx.arc(s.len*0.4,0,s.len*0.02,0,Math.PI*2);
    ctx.fillStyle=`rgba(255,80,50,${flick})`;ctx.fill();
    // Destroços soltos ao redor do casco (placas menores, mesmo material)
    s.debris.forEach(d=>{
      ctx.save();
      ctx.translate(d.ox,d.oy);ctx.rotate(d.rot);
      ctx.beginPath();
      for(let i=0;i<d.sides;i++){
        const a=(i/d.sides)*Math.PI*2;
        const px=Math.cos(a)*d.r,py=Math.sin(a)*d.r*0.7;
        i===0?ctx.moveTo(px,py):ctx.lineTo(px,py);
      }
      ctx.closePath();
      ctx.fillStyle='#26282e';ctx.fill();
      ctx.strokeStyle='rgba(0,0,0,0.5)';ctx.lineWidth=1;ctx.stroke();
      ctx.restore();
    });
    ctx.restore();
  });
}

// ═══════════════════════════════════════════════════════════════════
//  FROTAS INVASORAS — reaproveita o visual das Naves Abandonadas
//  (casco grande) mas ATIVAS: buscam o astro criado pelo jogador
//  (playerCreated) mais próximo e navegam até ele. Ao chegar perto,
//  libera uma leva de Monstros Errantes e/ou um Cardume no local e
//  se afasta novamente à procura de outro alvo (ou volta a vagar
//  livre se não houver nenhum astro do jogador no mapa).
// ═══════════════════════════════════════════════════════════════════
const FLEET_SPAWN_INTERVAL_MIN = 45; // raras — reforço pontual, não constante
const FLEET_SPAWN_INTERVAL_MAX = 90;
const FLEET_MAX = 3;
const FLEET_SHIPS_PER_FLEET_MIN = 2;
const FLEET_SHIPS_PER_FLEET_MAX = 4;
const FLEET_APPROACH_SPEED = 26;
const FLEET_RELEASE_RANGE = 340;   // distância do astro-alvo em que a frota libera os inimigos
const FLEET_RELEASE_COOLDOWN = 18; // tempo mínimo entre duas liberações da MESMA frota

let _invasionFleets = [];
let _fleetIdCounter = 1;
let _fleetSpawnTimer = 0;
let _fleetNextSpawnAt = rand(FLEET_SPAWN_INTERVAL_MIN, FLEET_SPAWN_INTERVAL_MAX);

// Acha o astro playerCreated mais próximo de um ponto (usado tanto pra
// decidir se vale a pena spawnar uma frota quanto pra ela mirar).
function _fleetFindPlayerAstro(x, y) {
  if (typeof objects === 'undefined' || !objects.length) return null;
  let best = null, bestD = Infinity;
  for (const o of objects) {
    if (o.dead || !o.playerCreated) continue;
    const d = Math.hypot(o.x - x, o.y - y);
    if (d < bestD) { bestD = d; best = o; }
  }
  return best;
}

function _fleetSpawn() {
  if (_invasionFleets.length >= FLEET_MAX) return;
  // Sem nenhum astro do jogador no mapa, não há razão pra frota existir.
  const pos = _cosmicRollSpawnPos();
  if (!_fleetFindPlayerAstro(pos.x, pos.y)) return;
  const shipCount = randInt(FLEET_SHIPS_PER_FLEET_MIN, FLEET_SHIPS_PER_FLEET_MAX);
  const ships = [];
  for (let i = 0; i < shipCount; i++) {
    const len = rand(180, 320); // um pouco menores que as Naves Abandonadas, pra não confundir os dois
    ships.push({
      len,
      hull: _derelictMakeHull(len),
      debris: _derelictMakeDebris(len, 2 + Math.floor(rand(0, 3))),
      // offset fixo dentro da formação da frota (linha ao lado do líder)
      offX: (i - shipCount / 2) * 180,
      offY: rand(-40, 40),
      tint: ['#3d4550', '#4a3d3d', '#3d4a44'][Math.floor(rand(0, 3))],
      flicker: rand(0, Math.PI * 2),
    });
  }
  _invasionFleets.push({
    id: 'fleet_' + (_fleetIdCounter++),
    x: pos.x, y: pos.y,
    angle: rand(0, Math.PI * 2),
    ships,
    targetId: null,
    releaseCd: 0,
    phase: rand(0, Math.PI * 2),
    offscreenT: 0,
  });
}

function cosmicFleetsUpdate(dt) {
  _fleetSpawnTimer += dt;
  if (_fleetSpawnTimer >= _fleetNextSpawnAt && _invasionFleets.length < FLEET_MAX) {
    _fleetSpawnTimer = 0;
    _fleetNextSpawnAt = rand(FLEET_SPAWN_INTERVAL_MIN, FLEET_SPAWN_INTERVAL_MAX);
    if (!_isBattle()) _fleetSpawn();
  }
  if (_isBattle()) return;

  for (let i = _invasionFleets.length - 1; i >= 0; i--) {
    const fleet = _invasionFleets[i];
    fleet.phase += dt;
    if (fleet.releaseCd > 0) fleet.releaseCd -= dt;

    let target = fleet.targetId ? objects.find(o => o.id === fleet.targetId && !o.dead && o.playerCreated) : null;
    if (!target) {
      target = _fleetFindPlayerAstro(fleet.x, fleet.y);
      fleet.targetId = target ? target.id : null;
    }

    if (target) {
      const dx = target.x - fleet.x, dy = target.y - fleet.y;
      const d = Math.hypot(dx, dy) || 1;
      fleet.angle = Math.atan2(dy, dx);
      if (d > FLEET_RELEASE_RANGE) {
        fleet.x += (dx / d) * FLEET_APPROACH_SPEED * dt;
        fleet.y += (dy / d) * FLEET_APPROACH_SPEED * dt;
      } else if (fleet.releaseCd <= 0) {
        // ── Libera a leva de inimigos perto do astro do jogador ──────
        fleet.releaseCd = FLEET_RELEASE_COOLDOWN;
        const releasePos = { x: target.x + rand(-80, 80), y: target.y + rand(-80, 80) };
        if (Math.random() < 0.5 && typeof _cosmicSpawnMonsterWave === 'function') {
          // Onda de monstros direto na posição do astro (em vez do
          // ponto aleatório do mapa que _cosmicSpawnMonsterWave usaria).
          const _max = (typeof _eclipseActive !== 'undefined' && _eclipseActive) ? COSMIC_MONSTER_MAX * 3 : COSMIC_MONSTER_MAX;
          const typeId = COSMIC_MONSTER_TYPE_IDS[Math.floor(rand(0, COSMIC_MONSTER_TYPE_IDS.length))];
          const def = COSMIC_MONSTER_TYPES[typeId];
          const count = def.swarm ? def.swarmSize() : randInt(1, 2);
          for (let k = 0; k < count; k++) {
            if (_cosmicMonsters.length >= _max) break;
            const ox = rand(-50, 50), oy = rand(-50, 50);
            _cosmicMonsters.push(_cosmicMakeMonster(typeId, releasePos.x + ox, releasePos.y + oy));
          }
        } else if (typeof _cosmicSpawnShoal === 'function') {
          _cosmicSpawnShoal(releasePos);
        }
        if (typeof showTooltip === 'function') showTooltip('🚨 Uma frota inimiga liberou reforços perto de ' + (target.name || 'seu astro') + '!');
        // Depois de liberar, a frota se afasta em busca de outro alvo.
        fleet.targetId = null;
      }
    } else {
      // Sem astro do jogador por perto: vaga livre até achar um.
      if (!fleet.wanderTarget || Math.hypot(fleet.wanderTarget.x - fleet.x, fleet.wanderTarget.y - fleet.y) < 100) {
        fleet.wanderTarget = _cosmicRollSpawnPos();
      }
      const dx = fleet.wanderTarget.x - fleet.x, dy = fleet.wanderTarget.y - fleet.y;
      const d = Math.hypot(dx, dy) || 1;
      fleet.angle = Math.atan2(dy, dx);
      fleet.x += (dx / d) * FLEET_APPROACH_SPEED * 0.7 * dt;
      fleet.y += (dy / d) * FLEET_APPROACH_SPEED * 0.7 * dt;
    }

    if (_cosmicIsOutsideRef(fleet)) {
      fleet.offscreenT += dt;
      if (fleet.offscreenT >= COSMIC_MONSTER_DESPAWN_TIME * 3) { _invasionFleets.splice(i, 1); continue; }
    } else {
      fleet.offscreenT = 0;
    }
  }
}

function cosmicFleetsDraw(ctxRef) {
  if (_isBattle()) return;
  _invasionFleets.forEach(fleet => {
    const scr = worldToScreen(fleet.x, fleet.y);
    const scale = cam.zoom;
    const visRadius = 380 * scale;
    if (scr.x < -visRadius - 100 || scr.x > canvas.width + visRadius + 100 ||
        scr.y < -visRadius - 100 || scr.y > canvas.height + visRadius + 100) return;
    fleet.ships.forEach(s => {
      // Cada nave da frota fica num offset fixo em relação ao líder,
      // rotacionado junto com a direção atual da frota — formação
      // coesa de "esquadrão", não naves soltas aleatórias.
      const rx = Math.cos(fleet.angle) * s.offX - Math.sin(fleet.angle) * s.offY;
      const ry = Math.sin(fleet.angle) * s.offX + Math.cos(fleet.angle) * s.offY;
      const sx = scr.x + rx * scale, sy = scr.y + ry * scale;
      ctx.save();
      ctx.translate(sx, sy);
      ctx.rotate(fleet.angle);
      ctx.scale(scale, scale);
      ctx.beginPath();
      s.hull.forEach((p, idx) => { idx === 0 ? ctx.moveTo(p.x, p.y) : ctx.lineTo(p.x, p.y); });
      ctx.closePath();
      const g = ctx.createLinearGradient(-s.len * 0.5, 0, s.len * 0.5, 0);
      g.addColorStop(0, '#0f1014'); g.addColorStop(0.5, s.tint); g.addColorStop(1, '#0a0b0d');
      ctx.fillStyle = g; ctx.fill();
      ctx.strokeStyle = 'rgba(0,0,0,0.6)'; ctx.lineWidth = 2; ctx.stroke();
      // Naves ATIVAS: várias luzes vermelhas hostis acesas (diferente
      // das Abandonadas, que têm só 1 luz fraca piscando) — leitura
      // imediata de "isso está ligado e é perigoso".
      const flick = 0.5 + 0.3 * Math.sin(s.flicker + fleet.phase * 3);
      [[s.len * 0.42, 0], [-s.len * 0.1, -s.len * 0.16], [-s.len * 0.1, s.len * 0.16]].forEach(([lx, ly]) => {
        ctx.beginPath(); ctx.arc(lx, ly, s.len * 0.02, 0, Math.PI * 2);
        ctx.fillStyle = `rgba(255,40,30,${flick})`; ctx.fill();
      });
      s.debris.forEach(d => {
        ctx.save();
        ctx.translate(d.ox, d.oy); ctx.rotate(d.rot);
        ctx.beginPath();
        for (let k = 0; k < d.sides; k++) {
          const a = (k / d.sides) * Math.PI * 2;
          const px = Math.cos(a) * d.r, py = Math.sin(a) * d.r * 0.7;
          k === 0 ? ctx.moveTo(px, py) : ctx.lineTo(px, py);
        }
        ctx.closePath();
        ctx.fillStyle = '#20232a'; ctx.fill();
        ctx.strokeStyle = 'rgba(0,0,0,0.5)'; ctx.lineWidth = 1; ctx.stroke();
        ctx.restore();
      });
      ctx.restore();
    });
  });
}

function cosmicFleetsReset() {
  _invasionFleets = [];
  _fleetSpawnTimer = 0;
  _fleetNextSpawnAt = rand(FLEET_SPAWN_INTERVAL_MIN, FLEET_SPAWN_INTERVAL_MAX);
}


const COSMIC_CHUNK_SIZE = 2000; // chunk grande usado para o sistema de rochas
const COSMIC_ROCKS_PER_CHUNK = 1; // limite fixo de rochas por chunk grande (máx. global abaixo)
const COSMIC_CHUNK_LOAD_RADIUS = 1; // chunks ao redor da câmera mantidos carregados (3x3)
const COSMIC_ROCKS_MAX_TOTAL = 6; // teto absoluto de rochas simultâneas no jogo inteiro
const COSMIC_ROCK_MIN_SEPARATION = 260;
const COSMIC_ROCK_DISCOVER_RANGE = 130; // distância (mundo) para a sonda "achar" a rocha
const COSMIC_ROCK_COLLECT_RANGE = 46;   // distância (mundo) para o jogador coletar clicando

let _cosmicRocks = [];
let _cosmicRockChunks = new Set(); // chunks "kx,ky" já povoados com suas rochas

function _cosmicChunkKey(cx, cy) { return cx + ',' + cy; }
function _cosmicChunkOf(x, y) { return { cx: Math.floor(x / COSMIC_CHUNK_SIZE), cy: Math.floor(y / COSMIC_CHUNK_SIZE) }; }

function _cosmicMakeRockShape(radius) {
  // Contorno irregular simples (polígono), para não parecer um círculo perfeito.
  const points = 6 + Math.floor(rand(0, 4));
  const shape = [];
  for (let i = 0; i < points; i++) {
    const a = (i / points) * Math.PI * 2;
    shape.push({ a, r: radius * (0.7 + rand(0, 0.5)) });
  }
  return shape;
}

function _cosmicSpawnRock(x, y, biomeId) {
  const radius = rand(10, 22);
  const biome = biomeId ? _cosmicBiomeById(biomeId) : null;
  const mineral = biome ? _cosmicRollBiomeMineral(biome.raceId) : _cosmicRollWeightedMineral();
  _cosmicRocks.push({
    id: 'rock_' + (_cosmicIdCounter++),
    x, y, radius,
    shape: _cosmicMakeRockShape(radius),
    mineral,
    biomeId: biomeId || null,
    discovered: false,
    collected: false,
    phase: rand(0, Math.PI * 2),
  });
}

// Povoa um chunk específico com até COSMIC_ROCKS_PER_CHUNK rochas,
// uma única vez (chunks já povoados nunca ganham mais rochas, mesmo
// que o jogador colete todas — respeita o limite fixo por chunk),
// respeitando também o teto global COSMIC_ROCKS_MAX_TOTAL.
function _cosmicPopulateChunk(cx, cy) {
  const key = _cosmicChunkKey(cx, cy);
  if (_cosmicRockChunks.has(key)) return;
  _cosmicRockChunks.add(key);
  if (_cosmicRocks.length >= COSMIC_ROCKS_MAX_TOTAL) return;
  const x0 = cx * COSMIC_CHUNK_SIZE, y0 = cy * COSMIC_CHUNK_SIZE;
  let tries = 0, placed = 0;
  while (placed < COSMIC_ROCKS_PER_CHUNK && _cosmicRocks.length < COSMIC_ROCKS_MAX_TOTAL && tries < 30) {
    const x = x0 + rand(0, COSMIC_CHUNK_SIZE);
    const y = y0 + rand(0, COSMIC_CHUNK_SIZE);
    const tooClose = _cosmicRocks.some(r => Math.hypot(r.x - x, r.y - y) < COSMIC_ROCK_MIN_SEPARATION);
    if (!tooClose) { _cosmicSpawnRock(x, y); placed++; }
    tries++;
  }
}

// Garante que os chunks ao redor da câmera (grade 3x3) estejam povoados.
function _cosmicEnsureRocks() {
  const { cx: ccx, cy: ccy } = _cosmicChunkOf(cam.x, cam.y);
  for (let dx = -COSMIC_CHUNK_LOAD_RADIUS; dx <= COSMIC_CHUNK_LOAD_RADIUS; dx++) {
    for (let dy = -COSMIC_CHUNK_LOAD_RADIUS; dy <= COSMIC_CHUNK_LOAD_RADIUS; dy++) {
      _cosmicPopulateChunk(ccx + dx, ccy + dy);
    }
  }
}

function cosmicRocksUpdate(dt) {
  _cosmicEnsureRocks();
  _cosmicRocks.forEach(r => { r.phase += dt; });
  // Remove rochas coletadas da lista ativa (mantém o chunk "gasto" —
  // não gera novas rochas no lugar, respeitando o limite fixo).
  _cosmicRocks = _cosmicRocks.filter(r => !r.collected);
}

function cosmicRocksDraw(ctx) {
  _cosmicRocks.forEach(rock => {
    if (!rock.discovered) return; // invisíveis até serem encontradas
    const pulse = 1 + Math.sin(rock.phase * 0.6) * 0.03;
    ctx.save();
    ctx.beginPath();
    rock.shape.forEach((p, i) => {
      const wx = rock.x + Math.cos(p.a) * p.r * pulse;
      const wy = rock.y + Math.sin(p.a) * p.r * pulse;
      const s = worldToScreen(wx, wy);
      if (i === 0) ctx.moveTo(s.x, s.y); else ctx.lineTo(s.x, s.y);
    });
    ctx.closePath();
    ctx.fillStyle = '#8a7d6b';
    ctx.fill();
    ctx.strokeStyle = 'rgba(255,220,150,0.7)';
    ctx.lineWidth = 1.2;
    ctx.stroke();

    // Rótulo do minério, acima da rocha — cor indica raridade/valor
    const label = worldToScreen(rock.x, rock.y - rock.radius * 1.6);
    ctx.font = `${Math.max(10, 11 * cam.zoom)}px sans-serif`;
    ctx.textAlign = 'center';
    const tier = _cosmicMineralTierLookup(rock.mineral);
    ctx.fillStyle = tier ? _cosmicRarityColor(tier.energy) : '#ffe9b3';
    ctx.fillText('⛏️ ' + rock.mineral, label.x, label.y);
    ctx.restore();
  });
}

// Cor do rótulo de acordo com a energia (raridade) do minério: comuns em
// dourado padrão, intermediários em ciano/verde, raros em roxo/rosa.
function _cosmicRarityColor(energy) {
  if (energy >= 18) return '#ff8fe0'; // Diamante/Iridium — raríssimo
  if (energy >= 10) return '#c9a8ff'; // Ouro/Platina — raro
  if (energy >= 6)  return '#7fd7ff'; // Urânio/Osmium — incomum
  if (energy >= 3)  return '#9dffb0'; // Hidrogênio/Titânio — pouco comum
  return '#ffe9b3'; // Ferro/Silício/Carbono/Hélio — comum
}

// Tenta coletar uma rocha descoberta próxima ao ponto de clique (wx,wy).
// Retorna a rocha coletada (com seu mineral) ou null se nenhuma estava
// ao alcance. Chamado pelo handler de clique do canvas.
function cosmicTryCollectRockAt(wx, wy) {
  for (let i = 0; i < _cosmicRocks.length; i++) {
    const rock = _cosmicRocks[i];
    if (!rock.discovered || rock.collected) continue;
    if (Math.hypot(rock.x - wx, rock.y - wy) <= Math.max(COSMIC_ROCK_COLLECT_RANGE, rock.radius * 1.8)) {
      rock.collected = true;
      _cosmicAddMineral(rock.mineral, 1);
      // Minerar uma rocha nativa do bioma é uma das fontes de
      // Perturbação — ver cosmicAddBiomePerturbation().
      if (rock.biomeId) cosmicAddBiomePerturbation(rock.biomeId, COSMIC_PERTURBATION_PER_MINERAL);
      return rock;
    }
  }
  return null;
}

function cosmicRocksReset() {
  _cosmicRocks = [];
  _cosmicRockChunks = new Set();
}

// ═══════════════════════════════════════════════════════════════════
//  INVENTÁRIO DE MINÉRIOS E UPGRADES DAS SONDAS — Fase Cósmica
// ═══════════════════════════════════════════════════════════════════
//  Estoque de minério é GLOBAL (compartilhado entre todas as sondas do
//  jogador), coletado manualmente pelo jogador ao clicar numa rocha já
//  descoberta. Cada minério coletado vira pontos de upgrade proporcionais
//  à sua raridade (ver COSMIC_MINERAL_TIERS) — minérios mais raros (ex.
//  Diamante, Iridium) rendem bem mais energia que os comuns (ex. Ferro).
// ═══════════════════════════════════════════════════════════════════

let _cosmicMineralInventory = {}; // {Ferro:2, Ouro:1, ...} — por transparência/flavor
let _cosmicUpgradePoints = 0;     // pontos de upgrade acumulados (proporcional à raridade do minério)

function _cosmicAddMineral(mineral, qty) {
  _cosmicMineralInventory[mineral] = (_cosmicMineralInventory[mineral] || 0) + qty;
  const tier = _cosmicMineralTierLookup(mineral);
  const energy = (tier ? tier.energy : 1) * qty;
  _cosmicUpgradePoints += energy;
  showTooltip(`⛏️ +${qty} ${mineral} coletado! (+${energy} energia — ${_cosmicUpgradePoints} pontos de upgrade)`);
}

// Custo de upgrade por nível (cada nível fica mais caro).
function _cosmicUpgradeCost(level) { return 2 + level * 2; }

const COSMIC_PROBE_BASE_TERRITORY = 900;   // raio territorial inicial (mundo)
const COSMIC_PROBE_BASE_SPEED = 45;        // velocidade base
const COSMIC_PROBE_BASE_VISION = COSMIC_ROCK_DISCOVER_RANGE; // alcance de visão inicial
const COSMIC_PROBE_BASE_BATTERY = 240;     // segundos de bateria inicial (4 min)
const COSMIC_PROBE_UPGRADE_STEP = { territory: 260, speed: 12, vision: 34 };

// ── Upgrade Global: transforma uma Sonda Local numa Sonda Global ──────
// Cada nível de "global" aumenta o alcance territorial MUITO além do
// upgrade normal de território, simulando que a sonda deixou de vasculhar
// só uma área local e passou a cobrir múltiplos biomas à distância. É
// esse alcance ampliado que permite revelar/tocar Naves-Relíquia de
// bosses adormecidos (ver cosmicPerturbationUpdate / _cosmicRelicIsRevealed),
// e o nível mais alto entre todas as Sondas Globais do jogador conta
// como bônus para o gatilho de perturbação de qualquer bioma.
const COSMIC_PROBE_GLOBAL_STEP = 1400; // raio adicional por nível de Global (bem maior que o upgrade normal)
const COSMIC_PROBE_GLOBAL_MAX_LEVEL = 5;

const COSMIC_PROBE_BASE_LIMIT = 2; // limite inicial de sondas por jogo (upável)
let _cosmicProbeLimitUpgrades = 0; // cada upgrade de "limite" soma +1 sonda permitida

function cosmicProbeLimit() { return COSMIC_PROBE_BASE_LIMIT + _cosmicProbeLimitUpgrades; }
function cosmicProbeCount() {
  if (typeof objects === 'undefined') return 0;
  return objects.filter(o => !o.dead && o.type === 'cosmicProbe').length;
}

const COSMIC_PROBE_NAME_POOL = [
  'Nebulony','Draco','Orion','Constelly','Serpk','Crapy','Lib','Zodic',
  'Scorp','Canis','Sirius','Cignio','Triang','Cass','Taure','Pegasus','Centirus',
];
// Chance de sortear um nome da lista fixa. Se não sortear, gera um
// "código de sonda": 3–6 letras/números, um "-", e mais 2–8 letras/números.
const COSMIC_PROBE_NAME_POOL_CHANCE = 0.6;
const COSMIC_PROBE_CODE_CHARS = 'ABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789';

function _cosmicRandCodeChunk(len) {
  let s = '';
  for (let i = 0; i < len; i++) {
    s += COSMIC_PROBE_CODE_CHARS[Math.floor(rand(0, COSMIC_PROBE_CODE_CHARS.length))];
  }
  return s;
}

function _cosmicNextProbeName() {
  if (Math.random() < COSMIC_PROBE_NAME_POOL_CHANCE) {
    return COSMIC_PROBE_NAME_POOL[Math.floor(rand(0, COSMIC_PROBE_NAME_POOL.length))];
  }
  const partA = _cosmicRandCodeChunk(Math.floor(rand(3, 7)));  // 3–6 chars
  const partB = _cosmicRandCodeChunk(Math.floor(rand(2, 9)));  // 2–8 chars
  return partA + '-' + partB;
}

function cosmicResetProbeEconomy() {
  _cosmicMineralInventory = {};
  _cosmicUpgradePoints = 0;
  _cosmicProbeLimitUpgrades = 0;
}

// ═══════════════════════════════════════════════════════════════════
//  CLASSE: SONDA CÓSMICA (item criável pelo jogador)
// ═══════════════════════════════════════════════════════════════════
//  Cada sonda nasce presa a um TERRITÓRIO fixo (raio ao redor do ponto
//  onde foi criada). Ela vaga livremente dentro desse raio; ao se
//  aproximar do limite, curva suavemente de volta para dentro — nunca
//  trava tentando atravessar, nem faz bounce brusco na borda.
//
//  Gasta BATERIA com o tempo (não recarrega). Ao zerar, a sonda "some
//  eternamente" (é removida da lista `objects`) até que o jogador limpe
//  tudo — não fica um corpo morto/parado ocupando o mapa.
//
//  Upgrades (comprados com pontos de minério, individuais por sonda):
//    - Território: aumenta o raio de movimento.
//    - Velocidade: aumenta a velocidade de deslocamento.
//    - Visão (alcance): aumenta o raio de descoberta de rochas —
//      descrito em lore como "desenvolve placas que capturam raios UV
//      e infravermelho", permitindo enxergar mais longe.
//    - Global: transforma a sonda de Local pra Global — cada nível
//      estende MUITO o raio territorial (bem além do upgrade normal de
//      Território), simulando alcance interbiomas. É esse raio Global
//      que revela/permite tocar Naves-Relíquia de bosses adormecidos.
// ═══════════════════════════════════════════════════════════════════
class CosmicProbe extends CelestialObject {
  constructor(wx, wy) {
    super(wx, wy, 'cosmicProbe');
    this.probeName = _cosmicNextProbeName();
    this.radius = 9;
    this.mass = 2;
    this.color = '#9fd8ff';
    this.temp = 0;
    const ang = rand(0, Math.PI * 2);
    this.territoryCx = wx; this.territoryCy = wy; // centro fixo do território (ponto de criação)
    this.territoryRadius = COSMIC_PROBE_BASE_TERRITORY;
    this.baseSpeed = COSMIC_PROBE_BASE_SPEED;
    this.visionRange = COSMIC_PROBE_BASE_VISION;
    this.battery = COSMIC_PROBE_BASE_BATTERY;
    this.batteryMax = COSMIC_PROBE_BASE_BATTERY;
    this.upgrades = { territory: 0, speed: 0, vision: 0, global: 0 };
    this.isGlobal = false;   // vira true a partir do 1º nível de upgrade Global
    this.globalLevel = 0;    // nível atual do upgrade Global (0 = ainda Local)
    const spd = this.baseSpeed;
    this.vx = Math.cos(ang) * spd;
    this.vy = Math.sin(ang) * spd;
    this.fixed = false;
    this.foundArrowT = 0;   // tempo restante mostrando seta até a última rocha achada
    this.foundArrowRock = null;
    this._wanderRetarget = rand(1.5, 4);
    this._dead_battery = false;
  }
  update(dt) {
    // Move a sonda pela velocidade calculada em _tickProbeAI. baseSpeed
    // é "unidades por segundo" (mesmo padrão das raças cósmicas — ver
    // COSMIC_BEHAVIORS), então aplicamos vx/vy*dt puro, sem *60.
    this.x += this.vx * dt;
    this.y += this.vy * dt;
  }
  _tickProbeAI(dt) {
    // ── Bateria: gasta com o tempo, nunca recarrega ──
    this.battery = Math.max(0, this.battery - dt);
    if (this.battery <= 0) {
      // Bateria acabou: some para sempre (não fica corpo morto no mapa).
      this.dead = true;
      showTooltip(`🔋 Sonda ${this.probeName} ficou sem bateria e se perdeu no espaço...`);
      return;
    }

    // ── Leve variação de rota, como uma sonda "vasculhando" a área ──
    this._wanderRetarget -= dt;
    if (this._wanderRetarget <= 0) {
      this._wanderRetarget = rand(2, 5);
      const ang = Math.atan2(this.vy, this.vx) + rand(-0.9, 0.9);
      this.vx = Math.cos(ang) * this.baseSpeed;
      this.vy = Math.sin(ang) * this.baseSpeed;
    }

    // ── Limite territorial: aproximação suave da borda vira curva de
    // retorno ANTES de alcançar o limite — nunca trava nem faz bounce.
    const dCenter = Math.hypot(this.x - this.territoryCx, this.y - this.territoryCy);
    const softBorder = this.territoryRadius * 0.8; // começa a curvar aos 80% do raio
    if (dCenter > softBorder) {
      const toCenterAng = Math.atan2(this.territoryCy - this.y, this.territoryCx - this.x);
      const curAng = Math.atan2(this.vy, this.vx);
      // Interpola suavemente o ângulo atual em direção ao centro —
      // mais forte quanto mais perto do limite absoluto.
      const t = Math.min(1, (dCenter - softBorder) / (this.territoryRadius - softBorder));
      let diff = toCenterAng - curAng;
      while (diff > Math.PI) diff -= Math.PI * 2;
      while (diff < -Math.PI) diff += Math.PI * 2;
      const newAng = curAng + diff * Math.min(1, dt * (2 + t * 6));
      this.vx = Math.cos(newAng) * this.baseSpeed;
      this.vy = Math.sin(newAng) * this.baseSpeed;
    }
    // Clamp final de segurança (nunca deve realmente ser necessário
    // dada a curva suave acima, mas evita qualquer escape residual).
    if (dCenter > this.territoryRadius) {
      const ang2 = Math.atan2(this.y - this.territoryCy, this.x - this.territoryCx);
      this.x = this.territoryCx + Math.cos(ang2) * this.territoryRadius;
      this.y = this.territoryCy + Math.sin(ang2) * this.territoryRadius;
    }

    // ── Verifica rochas próximas ainda não descobertas (raio = visão) ──
    for (let i = 0; i < _cosmicRocks.length; i++) {
      const rock = _cosmicRocks[i];
      if (rock.discovered) continue;
      if (Math.hypot(rock.x - this.x, rock.y - this.y) <= this.visionRange) {
        rock.discovered = true;
        this.foundArrowRock = rock;
        this.foundArrowT = 6; // segundos mostrando a seta
        showTooltip(`🛰️ ${this.probeName} encontrou uma rocha com ${rock.mineral}!`);
        break;
      }
    }
    if (this.foundArrowT > 0) this.foundArrowT -= dt;
  }
  // ── Upgrades ──
  upgrade(kind) {
    if (kind === 'global' && this.globalLevel >= COSMIC_PROBE_GLOBAL_MAX_LEVEL) return false; // nível máximo atingido
    const cost = _cosmicUpgradeCost(this.upgrades[kind] || 0);
    if (_cosmicUpgradePoints < cost) return false;
    _cosmicUpgradePoints -= cost;
    this.upgrades[kind] = (this.upgrades[kind] || 0) + 1;
    if (kind === 'territory') this.territoryRadius += COSMIC_PROBE_UPGRADE_STEP.territory;
    if (kind === 'speed') this.baseSpeed += COSMIC_PROBE_UPGRADE_STEP.speed;
    if (kind === 'vision') this.visionRange += COSMIC_PROBE_UPGRADE_STEP.vision;
    if (kind === 'global') {
      this.globalLevel += 1;
      this.isGlobal = true;
      this.territoryRadius += COSMIC_PROBE_GLOBAL_STEP;
    }
    return true;
  }
  draw() {
    const sx = this.sx(), sy = this.sy(), r = this.sr();
    // ── Visual de satélite: corpo metálico central, antena parabólica
    // de um lado, painéis solares segmentados dos dois lados, antena
    // fina no topo — baseado em referência fotográfica real de satélite.
    ctx.save();
    ctx.translate(sx, sy);
    const ang = Math.atan2(this.vy, this.vx);
    ctx.rotate(ang);

    const bodyW = r * 1.3, bodyH = r * 0.85;
    const bodyRad = Math.min(bodyW, bodyH) * 0.22; // raio de canto arredondado

    // Painel solar traseiro (desenhado primeiro, fica "atrás")
    this._drawSolarPanel(-1, r);

    // Sombra suave de contato sob o corpo (dá volume/profundidade)
    ctx.save();
    ctx.globalAlpha = 0.35;
    ctx.filter = 'blur(2px)';
    ctx.fillStyle = 'rgba(0,0,0,0.5)';
    this._roundRectPath(-bodyW * 0.5, -bodyH * 0.42, bodyW, bodyH, bodyRad);
    ctx.fill();
    ctx.restore();

    // Corpo central metálico — gradiente para dar volume cilíndrico real
    const bodyGrad = ctx.createLinearGradient(-bodyW * 0.5, -bodyH * 0.5, bodyW * 0.5, bodyH * 0.5);
    bodyGrad.addColorStop(0, '#eef1f4');
    bodyGrad.addColorStop(0.45, '#c9ccd1');
    bodyGrad.addColorStop(0.7, '#9fa4ac');
    bodyGrad.addColorStop(1, '#7d838d');
    this._roundRectPath(-bodyW * 0.5, -bodyH * 0.5, bodyW, bodyH, bodyRad);
    ctx.fillStyle = bodyGrad;
    ctx.fill();
    ctx.strokeStyle = 'rgba(50,55,65,0.75)';
    ctx.lineWidth = Math.max(0.6, r * 0.03);
    this._roundRectPath(-bodyW * 0.5, -bodyH * 0.5, bodyW, bodyH, bodyRad);
    ctx.stroke();

    // Detalhe/painel escuro no corpo (janela térmica), com leve gradiente
    const winGrad = ctx.createLinearGradient(0, -bodyH * 0.28, 0, bodyH * 0.28);
    winGrad.addColorStop(0, 'rgba(70,100,150,0.6)');
    winGrad.addColorStop(1, 'rgba(30,45,70,0.6)');
    this._roundRectPath(-bodyW * 0.32, -bodyH * 0.28, bodyW * 0.4, bodyH * 0.56, bodyRad * 0.5);
    ctx.fillStyle = winGrad;
    ctx.fill();
    // Reflexo fino diagonal no corpo (dá brilho metálico realista)
    ctx.save();
    this._roundRectPath(-bodyW * 0.5, -bodyH * 0.5, bodyW, bodyH, bodyRad);
    ctx.clip();
    ctx.fillStyle = 'rgba(255,255,255,0.25)';
    ctx.beginPath();
    ctx.moveTo(-bodyW * 0.5, -bodyH * 0.1);
    ctx.lineTo(-bodyW * 0.2, -bodyH * 0.5);
    ctx.lineTo(-bodyW * 0.02, -bodyH * 0.5);
    ctx.lineTo(-bodyW * 0.32, -bodyH * 0.1);
    ctx.closePath();
    ctx.fill();
    ctx.restore();

    // Antena parabólica (lado da frente, na direção do movimento)
    const dishX = bodyW * 0.62, dishR = r * 0.5;
    ctx.save();
    ctx.translate(dishX, 0);
    const dishGrad = ctx.createRadialGradient(0, 0, dishR * 0.1, 0, 0, dishR);
    dishGrad.addColorStop(0, '#f4f6f8');
    dishGrad.addColorStop(1, '#aab0b8');
    ctx.beginPath();
    ctx.ellipse(0, 0, dishR, dishR * 0.72, 0, 0, Math.PI * 2);
    ctx.fillStyle = dishGrad;
    ctx.fill();
    ctx.strokeStyle = 'rgba(70,75,85,0.7)';
    ctx.lineWidth = Math.max(0.5, r * 0.025);
    ctx.stroke();
    // Haste + receptor central da parabólica
    ctx.beginPath();
    ctx.moveTo(0, 0);
    ctx.lineTo(dishR * 0.55, 0);
    ctx.strokeStyle = 'rgba(180,185,190,0.8)';
    ctx.stroke();
    ctx.beginPath();
    ctx.arc(dishR * 0.55, 0, Math.max(1, dishR * 0.1), 0, Math.PI * 2);
    ctx.fillStyle = '#8a9098';
    ctx.fill();
    ctx.restore();

    // Antena fina no topo do corpo
    ctx.beginPath();
    ctx.moveTo(-bodyW * 0.1, -bodyH * 0.5);
    ctx.lineTo(-bodyW * 0.1, -bodyH * 0.5 - r * 0.9);
    ctx.strokeStyle = 'rgba(200,205,210,0.8)';
    ctx.lineWidth = Math.max(0.5, r * 0.025);
    ctx.stroke();

    // Painel solar dianteiro (por cima, fica "na frente")
    this._drawSolarPanel(1, r);

    ctx.restore();

    // Nome da sonda acima do corpo
    ctx.save();
    ctx.font = `${Math.max(10, 11 * cam.zoom)}px sans-serif`;
    ctx.textAlign = 'center';
    ctx.fillStyle = '#cdeeff';
    ctx.fillText('🛰️ ' + this.probeName, sx, sy - r * 2.4);
    ctx.restore();

    // A seta apontando para rochas descobertas agora é um indicador
    // de borda de tela (HTML/CSS) — ver _cosmicSyncEdgeIndicators().
  }
  // Desenha um painel solar segmentado (asa) de um dos lados do corpo.
  // side = -1 (esquerda/trás) ou 1 (direita/frente), já dentro do
  // contexto rotacionado/traduzido para a posição da sonda.
  _drawSolarPanel(side, r) {
    const armLen = r * 0.55, panelLen = r * 1.9, panelW = r * 0.85;
    const cornerR = panelW * 0.08;
    const baseX = side * armLen;
    ctx.save();
    ctx.translate(baseX, 0);
    // Braço curto de conexão (com leve gradiente de metal)
    const armGrad = ctx.createLinearGradient(0, -r * 0.06, 0, r * 0.06);
    armGrad.addColorStop(0, 'rgba(190,195,202,0.9)');
    armGrad.addColorStop(1, 'rgba(130,135,142,0.9)');
    ctx.fillStyle = armGrad;
    ctx.fillRect(side > 0 ? 0 : -armLen * 0.4, -r * 0.06, armLen * 0.4, r * 0.12);
    ctx.translate(side * panelLen * 0.5, 0);

    // Painel: base azul escuro com gradiente + cantos levemente arredondados,
    // dando uma sensação de placa real em vez de bloco chapado.
    const panelGrad = ctx.createLinearGradient(0, -panelW * 0.5, 0, panelW * 0.5);
    panelGrad.addColorStop(0, '#1c2c4d');
    panelGrad.addColorStop(0.5, '#16213a');
    panelGrad.addColorStop(1, '#0f1830');
    this._roundRectPath(-panelLen * 0.5, -panelW * 0.5, panelLen, panelW, cornerR);
    ctx.fillStyle = panelGrad;
    ctx.fill();

    ctx.save();
    this._roundRectPath(-panelLen * 0.5, -panelW * 0.5, panelLen, panelW, cornerR);
    ctx.clip();
    // Segmentos (células solares) com leve variação de tom entre células
    ctx.strokeStyle = 'rgba(120,170,220,0.55)';
    ctx.lineWidth = Math.max(0.5, r * 0.02);
    const segs = 5;
    for (let i = 0; i < segs; i++) {
      const lx0 = -panelLen * 0.5 + (panelLen / segs) * i;
      if (i % 2 === 1) {
        ctx.fillStyle = 'rgba(255,255,255,0.035)';
        ctx.fillRect(lx0, -panelW * 0.5, panelLen / segs, panelW);
      }
      if (i > 0) {
        ctx.beginPath(); ctx.moveTo(lx0, -panelW * 0.5); ctx.lineTo(lx0, panelW * 0.5); ctx.stroke();
      }
    }
    // Linha central horizontal (barramento do painel)
    ctx.beginPath();
    ctx.moveTo(-panelLen * 0.5, 0); ctx.lineTo(panelLen * 0.5, 0);
    ctx.strokeStyle = 'rgba(120,170,220,0.35)';
    ctx.stroke();
    // Leve brilho/reflexo diagonal, mais suave e orgânico
    const shineGrad = ctx.createLinearGradient(-panelLen * 0.5, -panelW * 0.5, -panelLen * 0.1, panelW * 0.5);
    shineGrad.addColorStop(0, 'rgba(160,200,255,0.22)');
    shineGrad.addColorStop(1, 'rgba(160,200,255,0)');
    ctx.fillStyle = shineGrad;
    ctx.beginPath();
    ctx.moveTo(-panelLen * 0.5, -panelW * 0.5);
    ctx.lineTo(-panelLen * 0.15, -panelW * 0.5);
    ctx.lineTo(-panelLen * 0.35, panelW * 0.5);
    ctx.lineTo(-panelLen * 0.7, panelW * 0.5);
    ctx.closePath();
    ctx.fill();
    ctx.restore();

    this._roundRectPath(-panelLen * 0.5, -panelW * 0.5, panelLen, panelW, cornerR);
    ctx.strokeStyle = 'rgba(120,170,220,0.55)';
    ctx.lineWidth = Math.max(0.5, r * 0.02);
    ctx.stroke();

    ctx.restore();
  }
  // Helper: caminho de retângulo com cantos arredondados (compatível com
  // canvas sem suporte nativo a roundRect). Não altera nenhum outro
  // sistema de desenho do jogo — uso exclusivo da CosmicProbe.
  _roundRectPath(x, y, w, h, rad) {
    const rr = Math.max(0, Math.min(rad, Math.min(w, h) * 0.5));
    ctx.beginPath();
    ctx.moveTo(x + rr, y);
    ctx.lineTo(x + w - rr, y);
    ctx.arcTo(x + w, y, x + w, y + rr, rr);
    ctx.lineTo(x + w, y + h - rr);
    ctx.arcTo(x + w, y + h, x + w - rr, y + h, rr);
    ctx.lineTo(x + rr, y + h);
    ctx.arcTo(x, y + h, x, y + h - rr, rr);
    ctx.lineTo(x, y + rr);
    ctx.arcTo(x, y, x + rr, y, rr);
    ctx.closePath();
  }
}

// Tick de IA das sondas — chamado a cada frame (apenas na Fase Cósmica).
function cosmicProbesUpdate(dt) {
  if (typeof objects === 'undefined') return;
  objects.forEach(o => {
    if (!o.dead && o.type === 'cosmicProbe') {
      if (typeof o._tickProbeAI === 'function') o._tickProbeAI(dt);
      // O loop genérico de física só chama obj.update(dt) para tipos
      // presentes em listas específicas (PP_ORBIT_TYPES, SP_TYPES,
      // EX_TYPES, TECH_TYPES, raças) — cosmicProbe não está em nenhuma
      // delas, então chamamos aqui para garantir que a sonda realmente
      // se mova (sem isso, vx/vy eram calculados mas nunca aplicados).
      if (!o.dead && typeof o.update === 'function') o.update(dt);
    }
  });
  _cosmicSyncEdgeIndicators();
}

// ── Indicadores de borda: mostram, na moldura da tela, a direção de uma
// rocha recém-descoberta por uma sonda, apenas enquanto a rocha estiver
// fora do campo visível. Um indicador por sonda (múltiplos simultâneos).
// Implementado em HTML/CSS (não no canvas) para permitir animações de
// entrada/pulso suaves via transições/keyframes.
const _cosmicEdgeIndicatorEls = {}; // probeId -> elemento DOM
const COSMIC_EDGE_MARGIN = 24; // distância da borda da tela (px)

function _cosmicGetEdgeIndicatorEl(id) {
  let el = _cosmicEdgeIndicatorEls[id];
  if (el && el.isConnected) return el;
  const host = document.getElementById('cosmic-edge-indicators');
  if (!host) return null;
  el = document.createElement('div');
  el.className = 'cosmic-edge-ind';
  el.innerHTML = '<div class="cei-chevron"></div><div class="cei-label"></div>';
  host.appendChild(el);
  _cosmicEdgeIndicatorEls[id] = el;
  return el;
}

function _cosmicRemoveEdgeIndicator(id) {
  const el = _cosmicEdgeIndicatorEls[id];
  if (el) {
    el.classList.remove('show');
    setTimeout(() => { if (el.parentNode) el.parentNode.removeChild(el); }, 300);
    delete _cosmicEdgeIndicatorEls[id];
  }
}

function _cosmicSyncEdgeIndicators() {
  if (typeof objects === 'undefined') return;
  const activeIds = new Set();

  objects.forEach(o => {
    if (o.dead || o.type !== 'cosmicProbe') return;
    if (!(o.foundArrowT > 0) || !o.foundArrowRock || o.foundArrowRock.dead) return;

    const rock = o.foundArrowRock;
    const rs = worldToScreen(rock.x, rock.y);
    const w = canvas.width, h = canvas.height;
    const onScreen = rs.x >= 0 && rs.x <= w && rs.y >= 0 && rs.y <= h;
    if (onScreen) return; // só mostramos quando está fora da tela

    activeIds.add(o.id);
    const el = _cosmicGetEdgeIndicatorEl(o.id);
    if (!el) return;

    // Direção do centro da tela até a rocha (fora de tela).
    const cx = w * 0.5, cy = h * 0.5;
    const dx = rs.x - cx, dy = rs.y - cy;
    const ang = Math.atan2(dy, dx);

    // Interseção do raio com o retângulo da tela (com margem), para
    // posicionar o indicador exatamente na borda mais próxima.
    const m = COSMIC_EDGE_MARGIN;
    const halfW = cx - m, halfH = cy - m;
    const cosA = Math.cos(ang) || 1e-6, sinA = Math.sin(ang) || 1e-6;
    const tX = halfW / Math.abs(cosA);
    const tY = halfH / Math.abs(sinA);
    const t = Math.min(tX, tY);
    const px = cx + cosA * t, py = cy + sinA * t;

    el.style.left = px + 'px';
    el.style.top = py + 'px';
    el.style.transform = `rotate(${ang + Math.PI / 2}rad)`;
    // Reaplica a classe 'show' + rotação sem reiniciar a transição de
    // escala/opacidade a cada frame (só a rotação atualiza continuamente).
    const label = el.querySelector('.cei-label');
    if (label) {
      label.style.transform = `translateX(-50%) rotate(${-(ang + Math.PI / 2)}rad)`;
      label.textContent = (rock.mineral ? rock.mineral : 'Rocha');
    }
    el.classList.add('show');
  });

  // Remove indicadores de sondas que não estão mais ativas (rocha achada,
  // agora em tela, morta, ou a própria sonda morreu/perdeu a bateria).
  Object.keys(_cosmicEdgeIndicatorEls).forEach(id => {
    if (!activeIds.has(Number(id)) && !activeIds.has(id)) {
      _cosmicRemoveEdgeIndicator(id);
    }
  });
}

// ── Reset agregado de tudo do módulo cósmico (opcional, ao sair da Fase Cósmica) ──
function cosmicAllReset() {
  cosmicRacesReset();
  cosmicBiomesReset();
  cosmicCrittersReset();
  cosmicBossRelicsReset();
  cosmicLivingReset();
  cosmicChasersReset();
  cosmicWanderersReset();
  cosmicRocksReset();
  cosmicResetProbeEconomy();
  cosmicMonstersReset();
  galaxySerpentsReset();
  cosmicShoalReset();
  cosmicFleetsReset();
  cosmicGasCloudsReset();
  cosmicRupturesReset();
  _cosmicProjectiles = [];
  _cosmicAtmoEmbers = [];
  Object.keys(_cosmicEdgeIndicatorEls).forEach(id => _cosmicRemoveEdgeIndicator(id));
}

// ═══════════════════════════════════════════════════════════════════
//  COMETA DE QUANTIKS — evento raro: cruza o mapa periodicamente,
//  visual verde brilhante. Não dá Quantiks diretamente ao ser clicado;
//  precisa abrir o Microscópio nele para coletar a Molécula Gigante
//  de Quantiks que carrega, dando uma grande quantidade de uma vez.
// ═══════════════════════════════════════════════════════════════════
class QuantikComet extends CelestialObject{
  constructor(wx,wy,dirAngle,startFrozen){
    super(wx,wy,'quantikComet');
    this.radius=rand(9,13);this.mass=this.radius*.6;
    this.color='#7dffa0';this.temp=200;
    this._pendingAngle=(dirAngle!=null)?dirAngle:rand(0,Math.PI*2);
    if(startFrozen){
      // Spawnado parado (ex: pelo Mod Menu) — só ganha velocidade quando
      // _quantikCometLaunch() for chamado (ao fechar o painel).
      this.vx=0;this.vy=0;
      this._frozen=true;
    } else {
      const spd=rand(140,220);
      this.vx=Math.cos(this._pendingAngle)*spd;this.vy=Math.sin(this._pendingAngle)*spd;
      this._frozen=false;
    }
    this.fixed=false;this.trailPts=[];
    this._spawnTime=performance.now();
    this._autoSpawn=true; // não conta como astro criado pelo jogador p/ moléculas comuns
    this._giantMoleculeReward=randInt(QUANTIK_COMET_REWARD_MIN,QUANTIK_COMET_REWARD_MAX);
  }
  draw(){
    const sx=this.sx(),sy=this.sy(),r=this.sr();
    const pulse=0.85+Math.sin(performance.now()/280)*0.15;
    // Rastro esverdeado
    this.trailPts.unshift({x:this.x,y:this.y});
    if(this.trailPts.length>34)this.trailPts.length=34;
    for(let i=1;i<this.trailPts.length;i++){
      const pa=worldToScreen(this.trailPts[i-1].x,this.trailPts[i-1].y);
      const pb=worldToScreen(this.trailPts[i].x,this.trailPts[i].y);
      const alpha=(1-i/this.trailPts.length)*.75;
      ctx.beginPath();ctx.moveTo(pa.x,pa.y);ctx.lineTo(pb.x,pb.y);
      ctx.strokeStyle=`rgba(125,255,160,${alpha})`;ctx.lineWidth=Math.max(.6,(r-(i/this.trailPts.length)*r)*.9);ctx.stroke();
    }
    // Núcleo brilhante verde, com halo pulsante (indica que é especial)
    const glow=ctx.createRadialGradient(sx,sy,0,sx,sy,r*2.4*pulse);
    glow.addColorStop(0,'rgba(125,255,160,.5)');
    glow.addColorStop(1,'rgba(125,255,160,0)');
    ctx.beginPath();ctx.arc(sx,sy,r*2.4*pulse,0,Math.PI*2);ctx.fillStyle=glow;ctx.fill();
    const g=ctx.createRadialGradient(sx,sy,0,sx,sy,r*1.7);
    g.addColorStop(0,'#eaffef');g.addColorStop(.4,this.color);g.addColorStop(1,'rgba(40,140,70,0)');
    ctx.beginPath();ctx.arc(sx,sy,r*1.7,0,Math.PI*2);ctx.fillStyle=g;ctx.fill();
  }
}

// ── Spawn periódico do Cometa de Quantiks ──────────────────────────
const QUANTIK_COMET_REWARD_MIN=150,QUANTIK_COMET_REWARD_MAX=400; // Quantiks dados pela molécula gigante
const QUANTIK_COMET_DESPAWN_DIST=9000; // distância da câmera antes de sumir
const QUANTIK_COMET_INTERVAL_MIN=240,QUANTIK_COMET_INTERVAL_MAX=480; // 4-8 min entre aparições
let _quantikCometTimer=rand(60,150); // primeira aparição não demora tanto
function _quantikCometResetTimer(){
  _quantikCometTimer=rand(QUANTIK_COMET_INTERVAL_MIN,QUANTIK_COMET_INTERVAL_MAX);
}
function _quantikCometActive(){
  return objects.some(o=>o&&!o.dead&&o.type==='quantikComet');
}
function quantikCometUpdate(dt){
  if(window._invasionActive)return; // não durante invasões/bosses
  // Despawn automático se o cometa existente saiu muito da área de jogo
  objects.forEach(o=>{
    if(o&&!o.dead&&o.type==='quantikComet'){
      const distFromCam=Math.hypot(o.x-cam.x,o.y-cam.y);
      if(distFromCam>QUANTIK_COMET_DESPAWN_DIST)o.dead=true;
    }
  });
  if(_quantikCometActive())return; // só um por vez
  _quantikCometTimer-=dt;
  if(_quantikCometTimer<=0){
    _quantikCometResetTimer();
    _spawnQuantikComet();
  }
}
function _spawnQuantikComet(){
  // Nasce fora da área visível, cruzando em direção ao centro da câmera,
  // pra dar tempo do jogador perceber e ir até ele.
  const ang=rand(0,Math.PI*2);
  const spawnDist=Math.max(canvas.width,canvas.height)/cam.zoom*0.75+400;
  const wx=cam.x+Math.cos(ang)*spawnDist;
  const wy=cam.y+Math.sin(ang)*spawnDist;
  const dirAngle=ang+Math.PI+rand(-0.4,0.4); // aponta de volta pro centro, com variação
  const comet=new QuantikComet(wx,wy,dirAngle);
  objects.push(comet);
  showTooltip('🟢☄️ Um Cometa de Quantiks cruza o mapa! Abra o Microscópio nele para coletar a Molécula Gigante.');
}

// ── Spawn manual via Mod Menu: nasce PARADO no centro da tela, e só
// começa a voar quando o jogador fechar o painel (_quantikCometLaunch). ──
let _quantikCometPendingLaunch=null;
function _mmSpawnQuantikComet(){
  const wx=cam.x,wy=cam.y; // centro exato da câmera = centro da tela
  const dirAngle=rand(0,Math.PI*2);
  const comet=new QuantikComet(wx,wy,dirAngle,true); // startFrozen=true
  objects.push(comet);
  _quantikCometPendingLaunch=comet;
  showTooltip('🟢☄️ Cometa de Quantiks spawnado no centro — feche o Mod Menu para ele começar a voar.');
}
// Chamada ao fechar o Mod Menu: solta a velocidade do cometa pendente.
function _quantikCometLaunch(){
  const c=_quantikCometPendingLaunch;
  _quantikCometPendingLaunch=null;
  if(!c||c.dead)return;
  const spd=rand(140,220);
  c.vx=Math.cos(c._pendingAngle)*spd;c.vy=Math.sin(c._pendingAngle)*spd;
  c._frozen=false;
}

// ═══════════════════════════════════════════════════════════════════
//  _isBattle() — verificação central de "há uma Invasão/Boss em
//  andamento agora?". Usada para bloquear o SPAWN de novas entidades
//  vivas, raças cósmicas e inimigos durante qualquer combate de boss,
//  evitando que (ex.) um Ceifador ou uma nave Plasmícea apareçam do
//  nada e ataquem/orbitem astros no meio de uma luta contra Galaximy.
//  Não afeta entidades já existentes antes da batalha começar — só
//  novos spawns.
// ═══════════════════════════════════════════════════════════════════
function _isBattle(){
  // window._invasionActive já é setado por todos os 5 sistemas de boss
  // (Reptiliano/Quasord, Alien, Marsian, Polvicullus, Galaximy).
  if(window._invasionActive)return true;
  if(typeof GalaximyBoss!=='undefined'&&GalaximyBoss.isActive&&GalaximyBoss.isActive())return true;
  return false;
}

let _cosmonarioScanTimer=0;
function update(dt){
  // ── Bloqueio de aproximação do Núcleo Dimensional (Gigante Azul Colossal):
  //    a câmera não pode entrar na "zona de instabilidade" ao redor do
  //    centro do Núcleo. Se tentar, é empurrada de volta para a borda da
  //    zona. Isso NÃO altera nada do desenho do Núcleo em si — só limita
  //    a posição da câmera, então o Núcleo nunca fica invisível por causa
  //    disso. Efeito visual de glitch é 100% separado, em draw(). ────────
  _coreProximityUpdate();
  // ── Cometa de Quantiks: evento raro, cruza o mapa periodicamente ──
  quantikCometUpdate(dt);

  // ── Cosmonário: varredura periódica (não a cada frame) dos astros em

  // tela para registrar tipos já encontrados pelo jogador. ──────────
  _cosmonarioScanTimer+=dt;
  if(_cosmonarioScanTimer>=0.5){
    _cosmonarioScanTimer=0;
    for(let i=0;i<objects.length;i++){
      const o=objects[i];
      if(o&&o.type&&COSMONARIO_DB[o.type]&&!cosmonarioFound.has(o.type))_cosmonarioDiscover(o.type);
    }
    _cosmonarioScanInvasions();
  }
  // Sandbox: auto-spawn galaxies over time + on exploration
  // Bloqueado durante qualquer Invasão/Boss (window._invasionActive): astros
  // recém-nascidos (ex: Buraco Negro com planetas) ficariam sem colisão/
  // mecânicas ativas e vagando fora da arena, só ocupando o limite de astros.
  if(sandboxMode&&!window._invasionActive){
    sbGalaxyTimer+=dt;
    if(sbGalaxyTimer>=SB_GALAXY_INTERVAL){
      sbGalaxyTimer=0;
      // 7.5% de chance de surgir uma Galáxia Escura (se Pacote Exótico ativo)
      if(typeof _isExoticPackEnabled==='function'&&_isExoticPackEnabled()&&playerRank>=28&&Math.random()<.075){
        spawnDarkGalaxy();
      } else if(sandboxMode&&_sandboxPhase==='cosmic'){
        spawnCosmicPhaseGalaxy();
      } else {
        spawnSandboxGalaxy();
      }
    }
    checkExploreSpawn();
  }

  // Fase Cósmica (pós-derrota do Quasord): raças cósmicas vagam sozinhas.
  if(sandboxMode&&_sandboxPhase==='cosmic'){
    if(typeof CosmicMusicSys!=='undefined'){CosmicMusicSys.start();CosmicMusicSys.tick();}
    cosmicRacesUpdate(dt);
    cosmicBiomesUpdate(dt);
    cosmicCrittersUpdate(dt);
    cosmicLivingUpdate(dt);
    cosmicChasersUpdate(dt);
    cosmicWanderersUpdate(dt);
    cosmicRocksUpdate(dt);
    cosmicDerelictsUpdate(dt);
    cosmicFleetsUpdate(dt);
    cosmicProbesUpdate(dt);
    cosmicPerturbationUpdate(dt);
    cosmicMonstersUpdate(dt);
    galaxySerpentsUpdate(dt);
    cosmicShoalUpdate(dt);
    cosmicTerrorMonstersUpdate(dt);
    cosmicDefendersUpdate(dt);
    cosmicGasCloudsUpdate(dt);
    cosmicRupturesUpdate(dt);
    cosmicEclipseSpritesUpdate(dt);
    cosmicAtmosphereUpdate(dt);
  } else if(typeof CosmicMusicSys!=='undefined'){
    CosmicMusicSys.stop();
  }
  quantiksUpdate(dt); // Quantiks: funciona em qualquer modo/fase, não só Cósmica
  _moleculeRegenUpdate(dt); // Moléculas coletadas regeneram com o tempo (mesmo com Microscópio fechado)
  microscopeUpdate(dt);
  telescopeUpdate(dt);
  mineralFieldsUpdate(dt); // mineral de cada astro influencia astros vizinhos próximos

  // BH+BH
  const bhs=objects.filter(o=>o.type==='blackhole'&&!o.dead&&!o.merging);
  for(let i=0;i<bhs.length;i++)for(let j=i+1;j<bhs.length;j++){
    const a=bhs[i],b=bhs[j];
    if(dist(a,b)<(a.radius+b.radius)*1.4){
      a.merging=b.merging=a.dead=b.dead=true;
      const mx=(a.x+b.x)*.5,my=(a.y+b.y)*.5,newR=Math.min(a.radius+b.radius*.6,60);
      spawnExplosion(mx,my,1.8,false);
      const _mergedBH=new BlackHole(mx,my,newR);
      // Só herda _autoSpawn se AMBOS os BHs eram auto-gerados (galáxia)
      if(a._autoSpawn&&b._autoSpawn) _mergedBH._autoSpawn=true;
      pendingObjects.push(_mergedBH);
    }
  }
  // BH+Wormhole
  const worms=objects.filter(o=>o.type==='wormhole'&&!o.dead);
  bhs.forEach(bh=>{worms.forEach(wm=>{
    if(bh.dead||wm.dead)return;
    if(dist(bh,wm)<(bh.radius+wm.radius)*2.2){
      bh.dead=wm.dead=true;objects.forEach(o=>{if(o.type==='wormhole'&&o.id===wm.pairId)o.dead=true;});
      const mx=(bh.x+wm.x)*.5,my=(bh.y+wm.y)*.5,superR=Math.min(bh.radius*2.5+20,80);
      spawnExplosion(mx,my,3.0,true);
      const nb=new BlackHole(mx,my,superR);nb.mass=superR*120;
      // Herda _autoSpawn do BH original
      if(bh._autoSpawn) nb._autoSpawn=true;
      pendingObjects.push(nb);
    }
  });});

  // Reset per-frame flags on magnetars
  objects.forEach(o=>{if(o.type==='magnetar')o._orbitUpdated=false;});
  objects.forEach(obj=>{
    if(obj.dead)return;
    obj.age+=dt;

    // ── Durante invasão: pula toda física astro-astro ───────────
    // Astros continuam visíveis mas não interagem entre si
    if(window._invasionActive){
      if(typeof obj.update==='function') obj.update(dt);
      return;
    }

    // Immune objects (DarkMatter, VoidBelt, RiftFissure) skip ALL physics
    if(obj.immune)return;

    // Wolf-Rayet nebula: desativa gravidade externas do objeto temporariamente
    if(obj._wrNebula)return;

    // PolarStar — attract (red) or repel (blue)
    objects.forEach(ps=>{
      if(ps.type!=='polarstar'||ps===obj||ps.dead)return;
      const d=dist(obj,ps);if(d>ps.pullRange||d<1)return;
      if(obj.immune)return;
      if(obj.type==='planet'||obj.type==='moon'||PP_ORBIT_TYPES.includes(obj.type))obj.parent=null;
      const nx=(ps.x-obj.x)/d,ny=(ps.y-obj.y)/d;
      const acc=5000/(d*d+SOFT);
      const dir=ps.attracting?1:-1;
      obj.vx+=nx*acc*dir*dt;obj.vy+=ny*acc*dir*dt;
    });

    // RiftFissure — drastically slow nearby astros
    objects.forEach(rf=>{
      if(rf.type!=='riftfissure'||rf===obj||rf.dead)return;
      const d=dist(obj,rf);if(d>rf.slowRange)return;
      if(obj.immune||obj.fixed)return;
      // Quanto mais perto do centro, mais próximo de velocidade zero.
      // factor vai de 1 (borda) até ~0 (dentro do núcleo)
      const proximity=1-(d/rf.slowRange);          // 0..1
      const drag=1-(proximity*proximity*0.97);      // 0.03..1
      const dampen=Math.max(0.001,Math.pow(drag, 1+proximity*4));
      obj.vx*=dampen; obj.vy*=dampen;
    });

    // ── TWINSTAR — órbita em ∞/8: planeta dá 1 volta em A, cruza o meio, 1 volta em B ──
    objects.forEach(tw=>{
      if(tw.type!=='twinstar'||tw===obj||tw.dead)return;
      const d=dist(obj,tw);if(d>tw.captureRange||d<1)return;
      if(obj.fixed||obj.immune)return;
      if(obj.type==='planet'||obj.type==='moon'||PP_ORBIT_TYPES.includes(obj.type))obj.parent=null;

      // Posições das duas estrelas no mundo
      const axW=tw.x+Math.cos(tw._angle)*tw.sep;
      const ayW=tw.y+Math.sin(tw._angle)*tw.sep;
      const bxW=tw.x-Math.cos(tw._angle)*tw.sep;
      const byW=tw.y-Math.sin(tw._angle)*tw.sep;

      const dA=Math.max(1,Math.hypot(obj.x-axW,obj.y-ayW));
      const dB=Math.max(1,Math.hypot(obj.x-bxW,obj.y-byW));

      // Inicializar estado de órbita ∞ por objeto se ainda não existe
      if(!obj._twinState){
        obj._twinState={
          tw:tw.id,          // id do TwinStar dono
          phase:'toA',       // 'toA' | 'orbitA' | 'toB' | 'orbitB'
          orbitCount:0,      // quantas voltas já deu na estrela atual
          orbitAngle:Math.atan2(obj.y-ayW,obj.x-axW),
          orbitDist:dA,
          orbitSpeed:rand(1.4,2.2)*(dA<80?1.4:1),
        };
      }
      const ts=obj._twinState;
      // Se for um TwinStar diferente, ignora
      if(ts.tw!==tw.id)return;

      const ORBIT_TURNS=1;      // voltas por estrela antes de cruzar
      const CROSS_PULL =28;     // força de travessia ao cruzar o centro
      const ORBIT_PULL =32;     // força centrípeta durante a órbita
      const ORBIT_D    =tw.sep*0.85; // distância orbital ao redor de cada estrela

      if(ts.phase==='toA'||ts.phase==='toB'){
        // ── Cruzando para a próxima estrela ──
        const tx=ts.phase==='toA'?axW:bxW;
        const ty=ts.phase==='toA'?ayW:byW;
        const dx_=tx-obj.x, dy_=ty-obj.y;
        const dd=Math.max(1,Math.hypot(dx_,dy_));
        obj.vx+=dx_/dd*CROSS_PULL*dt;
        obj.vy+=dy_/dd*CROSS_PULL*dt;
        // Força tangencial para curvar a trajetória em arco (não em linha reta)
        const relX=obj.x-tw.x,relY=obj.y-tw.y;
        const theta=Math.atan2(relY,relX);
        obj.vx+=(-Math.sin(2*theta)*CROSS_PULL*.6)*dt;
        obj.vy+=( Math.cos(2*theta)*CROSS_PULL*.6)*dt;
        // Chegou perto da estrela destino → transição para órbita
        const targetD=ts.phase==='toA'?dA:dB;
        if(targetD<ORBIT_D*1.6){
          ts.phase=ts.phase==='toA'?'orbitA':'orbitB';
          ts.orbitAngle=Math.atan2(obj.y-(ts.phase==='orbitA'?ayW:byW),obj.x-(ts.phase==='orbitA'?axW:bxW));
          ts.orbitDist=Math.max(ORBIT_D*.5,targetD);
          ts.orbitCount=0;
          ts.orbitSpeed=1.8*(100/Math.max(ts.orbitDist,30));
        }
      } else {
        // ── Orbitando a estrela atual ──
        const cx=ts.phase==='orbitA'?axW:bxW;
        const cy=ts.phase==='orbitA'?ayW:byW;
        const dCurr=Math.max(1,Math.hypot(obj.x-cx,obj.y-cy));
        // Avança o ângulo de órbita
        const prevA=ts.orbitAngle;
        ts.orbitAngle+=ts.orbitSpeed*dt;
        // Conta voltas completas (cruzou 2π)
        if(ts.orbitAngle-prevA>0&&Math.floor(ts.orbitAngle/(Math.PI*2))>Math.floor(prevA/(Math.PI*2))){
          ts.orbitCount++;
        }
        // Força centrípeta para manter no raio orbital
        const targetX=cx+Math.cos(ts.orbitAngle)*ORBIT_D;
        const targetY=cy+Math.sin(ts.orbitAngle)*ORBIT_D;
        obj.vx+=(targetX-obj.x)*ORBIT_PULL*dt;
        obj.vy+=(targetY-obj.y)*ORBIT_PULL*dt;
        // Damping leve para não acelerar infinitamente
        obj.vx*=Math.pow(.988,dt*60);
        obj.vy*=Math.pow(.988,dt*60);
        // Completou N voltas → vai para a outra estrela
        if(ts.orbitCount>=ORBIT_TURNS){
          ts.phase=ts.phase==='orbitA'?'toB':'toA';
          ts.orbitCount=0;
        }
      }
    });

    // ── TRIPLE STAR — planeta percorre cada uma das 3 estrelas em sequência ──
    objects.forEach(trs=>{
      if(trs.type!=='triplestar'||trs===obj||trs.dead)return;
      const d=dist(obj,trs);if(d>trs.captureRange||d<1)return;
      if(obj.fixed||obj.immune)return;
      if(obj.type==='planet'||obj.type==='moon'||PP_ORBIT_TYPES.includes(obj.type))obj.parent=null;

      if(!obj._triState){
        obj._triState={trs:trs.id,starIdx:0,phase:'toStar',orbitAngle:0,orbitCount:0,orbitDist:60,orbitSpeed:1.6};
      }
      const ts=obj._triState;
      if(ts.trs!==trs.id)return;

      const z=1;
      const starAngle=trs._angle+ts.starIdx*(Math.PI*2/3);
      const starX=trs.x+Math.cos(starAngle)*trs.sep;
      const starY=trs.y+Math.sin(starAngle)*trs.sep;

      const ORBIT_D=trs.sep*0.75;
      const ORBIT_TURNS=1;

      if(ts.phase==='toStar'){
        const dx_=starX-obj.x,dy_=starY-obj.y;
        const dd=Math.max(1,Math.hypot(dx_,dy_));
        obj.vx+=dx_/dd*26*dt;obj.vy+=dy_/dd*26*dt;
        // Força tangencial para dar arco
        const relX=obj.x-trs.x,relY=obj.y-trs.y;
        const theta=Math.atan2(relY,relX);
        obj.vx+=(-Math.sin(theta)*16)*dt;obj.vy+=(Math.cos(theta)*16)*dt;
        const dStar=Math.hypot(obj.x-starX,obj.y-starY);
        if(dStar<ORBIT_D*1.5){
          ts.phase='orbit';
          ts.orbitAngle=Math.atan2(obj.y-starY,obj.x-starX);
          ts.orbitDist=Math.max(ORBIT_D*.5,dStar);
          ts.orbitSpeed=1.6*(80/Math.max(ts.orbitDist,25));
          ts.orbitCount=0;
        }
      } else {
        const prevA=ts.orbitAngle;
        ts.orbitAngle+=ts.orbitSpeed*dt;
        if(ts.orbitAngle-prevA>0&&Math.floor(ts.orbitAngle/(Math.PI*2))>Math.floor(prevA/(Math.PI*2))){
          ts.orbitCount++;
        }
        const tX=starX+Math.cos(ts.orbitAngle)*ORBIT_D;
        const tY=starY+Math.sin(ts.orbitAngle)*ORBIT_D;
        obj.vx+=(tX-obj.x)*28*dt;obj.vy+=(tY-obj.y)*28*dt;
        obj.vx*=Math.pow(.988,dt*60);obj.vy*=Math.pow(.988,dt*60);
        if(ts.orbitCount>=ORBIT_TURNS){
          ts.phase='toStar';ts.orbitCount=0;
          ts.starIdx=(ts.starIdx+1)%3; // próxima estrela do triângulo
        }
      }
    });

    // ── GREAT ATTRACTOR — atração colossal de alcance extremo (1/d não 1/d²) ──
    objects.forEach(ga=>{
      if(ga.type!=='greatattractor'||ga===obj||ga.dead)return;
      const d=dist(obj,ga);if(d>ga.pullRange||d<1)return;
      if(obj.fixed||obj.immune)return;
      if(obj.type==='planet'||obj.type==='moon'||PP_ORBIT_TYPES.includes(obj.type))obj.parent=null;
      const nx=(ga.x-obj.x)/d, ny=(ga.y-obj.y)/d;
      // Força escala com 1/d para alcance muito maior que gravidade normal
      const f=(G_BLACK*ga.mass*2.8)/Math.max(d,60);
      obj.vx+=nx*f*dt; obj.vy+=ny*f*dt;
    });

    // ── BOSONSTAR — sem colisão; captura individual, libera e cooldown de 10s ──
    objects.forEach(bs=>{
      if(bs.type!=='bosonstar'||bs===obj||bs.dead)return;
      const d=dist(obj,bs);
      if(obj.fixed||obj.immune)return;

      // Inicializa registro de captura por BosonStar para este obj
      if(!obj._bosonState)obj._bosonState={};
      const bid=bs.id;
      if(!obj._bosonState[bid])obj._bosonState[bid]={captured:false,cooldownUntil:0};
      const bst=obj._bosonState[bid];

      // ── Em cooldown: não interage até o tempo passar ──
      const now=performance.now();
      if(bst.cooldownUntil>now)return;

      // ── Fora do pullRange e ainda não capturado: nada ──
      if(d>bs.pullRange&&!bst.captured)return;

      const nx=(bs.x-obj.x)/d, ny=(bs.y-obj.y)/d;

      if(!bst.captured){
        // ── Fase 1: atração lenta até o centro ──
        if(obj.type==='planet'||obj.type==='moon'||PP_ORBIT_TYPES.includes(obj.type))obj.parent=null;
        const f=(G_BLACK*bs.mass*0.14)/(d*d+SOFT);
        obj.vx+=nx*f*dt; obj.vy+=ny*f*dt;
        // Quando chega muito perto do núcleo: captura e lança para fora
        if(d<bs.radius*1.1){
          bst.captured=true;
          obj.vx=-nx*rand(2.5,4.5);
          obj.vy=-ny*rand(2.5,4.5);
        }
      } else {
        // ── Fase 2: saindo — empurra para fora até se afastar
        if(d<bs.radius*2.5){
          obj.vx+=-nx*8*dt;
          obj.vy+=-ny*8*dt;
        } else {
          // Liberado — inicia cooldown de 10 segundos
          bst.captured=false;
          bst.cooldownUntil=now+10000; // 10 000 ms = 10s
        }
      }
    });

    // VoidBelt — seal ghost when object passes through
    objects.forEach(vb=>{
      if(vb.type!=='voidbelt'||vb===obj||vb.dead)return;
      if(obj.immune)return;
      const d=dist(obj,vb);
      if(d<vb.radius&&!obj._inVoid){
        obj._inVoid=true;
        // Seal glitch ghost
        vb.ghosts.push({
          x:obj.x,y:obj.y,
          type:obj.type,radius:obj.radius,
          color:obj.color||'#aaaaaa',
          glitchT:rand(0,Math.PI*2)
        });
        if(vb.ghosts.length>8)vb.ghosts.shift(); // cap
      } else if(d>=vb.radius){
        obj._inVoid=false;
      }
    });

    // Orbital mechanics
    if(!obj._noGravity){
      // Pacote Planetas: update próprio (órbita + habilidade)
      if(PP_ORBIT_TYPES.includes(obj.type)){
        if(typeof obj.update==='function') obj.update(dt);
      }
      // Pacote Estrelas: update próprio (animação + habilidade)
      if(SP_TYPES.includes(obj.type)){
        if(typeof obj.update==='function') obj.update(dt);
      }
      // Pacote Exótico: update próprio (animação + mecânica)
      if(EX_TYPES.includes(obj.type)){
        if(typeof obj.update==='function') obj.update(dt);
      }
      // Pacote Tecnológico: update próprio
      if(TECH_TYPES.includes(obj.type)){
        if(typeof obj.update==='function') obj.update(dt);
      }
      // Raças Inteligentes: update próprio (movimento + rastro + IA)
      if(obj.type===RACE_ALIEN||obj.type===RACE_MARCIAN||obj.type===RACE_REPTILIAN){
        if(typeof obj.update==='function') obj.update(dt);
      }
      // Decrementar efeitos visuais por objeto
      if(obj._quarkWhite>0)obj._quarkWhite=Math.max(0,obj._quarkWhite-dt);
      if(obj._heatFlash>0)obj._heatFlash=Math.max(0,obj._heatFlash-dt);
      if(obj._quasiHeat>0)obj._quasiHeat=Math.max(0,obj._quasiHeat-dt*0.15);
      if(obj.type==='planet'&&obj.parent&&!obj.parent.dead){
        let spd=obj.orbitSpeed;
        if(obj.parent.type==='cepheid'){
          // pulso normalizado 0..1 onde 0=mínimo e 1=máximo
          const raw=Math.sin((performance.now()*.001)*obj.parent.pulseFreq+obj.parent.glowPhase);
          const pulse=(raw+1)*.5; // 0..1
          // velocidade escala linearmente com o tamanho: mínimo 10% da base, máximo 100%
          spd=obj.orbitSpeed*(0.1+0.9*pulse);
        }
        obj.orbitAngle+=spd*dt;obj.x=obj.parent.x+Math.cos(obj.orbitAngle)*obj.orbitDist;obj.y=obj.parent.y+Math.sin(obj.orbitAngle)*obj.orbitDist;
      }
      if(obj.type==='moon'&&obj.parent&&!obj.parent.dead){obj.orbitAngle+=obj.orbitSpeed*dt;obj.x=obj.parent.x+Math.cos(obj.orbitAngle)*obj.orbitDist;obj.y=obj.parent.y+Math.sin(obj.orbitAngle)*obj.orbitDist;}
      // Luas de planetas do pacote — já tratadas acima pois parent pode ser qualquer tipo
    } else {
      obj.parent=null; // solta do pai enquanto sem gravidade
    }

    // Re-attach planets/moons (bloqueado se _noGravity ativo)
    if(!obj._noGravity){
      if(obj.type==='planet'&&(!obj.parent||obj.parent.dead)){
        const star=findNearest(obj,'star');
        const ceph=findNearest(obj,'cepheid');
        // Escolhe o mais próximo entre estrela e cefeida
        const dStar=star?dist(obj,star):Infinity;
        const dCeph=ceph?dist(obj,ceph):Infinity;
        const host=(dCeph<dStar&&dCeph<270)?ceph:(dStar<270?star:null);
        if(host&&!isNearBlackhole(obj)){obj.parent=host;obj.orbitDist=dist(obj,host);obj.orbitAngle=Math.atan2(obj.y-host.y,obj.x-host.x);obj.orbitSpeed=(0.4+rand(0,.3))/Math.sqrt(obj.orbitDist/50);}
      }
      if(obj.type==='moon'&&(!obj.parent||obj.parent.dead)){
        // Luas podem orbitar planet E qualquer tipo do Pacote Planetas
        const allPlanetTypes=['planet',...PP_ORBIT_TYPES];
        let bestHost=null,bestDist=90;
        allPlanetTypes.forEach(t=>{
          const p=findNearest(obj,t);
          if(p){const d=dist(obj,p);if(d<bestDist){bestDist=d;bestHost=p;}}
        });
        if(bestHost){obj.parent=bestHost;obj.orbitDist=Math.max(bestHost.radius+obj.radius+6,bestDist);obj.orbitAngle=Math.atan2(obj.y-bestHost.y,obj.x-bestHost.x);}
      }
    }

    // BH gravity
    objects.forEach(bh=>{
      if(bh.type!=='blackhole'||bh===obj||bh.dead)return;
      const d=dist(obj,bh);if(d>bh.pullRange)return;
      // Não atrai astros mais poderosos que um BH
      const BH_IMMUNE_TYPES=new Set(['blackhole','greatattractor','vetocrinazar','galaxy','quasar','blazar','darkmatter','voidbelt','riftfissure','bosonstar','polarstar','wormhole','whitehole','nebula']);
      if(BH_IMMUNE_TYPES.has(obj.type))return;
      if(obj.type==='planet'||obj.type==='moon'||PP_ORBIT_TYPES.includes(obj.type))obj.parent=null;
      if(!obj.merging){const acc=(G_BLACK*bh.mass*(obj.gravMultiplier||1))/(d*d+SOFT);const nx=(bh.x-obj.x)/d,ny=(bh.y-obj.y)/d;obj.vx+=nx*acc*dt;obj.vy+=ny*acc*dt;}
      if(d<bh.radius*1.25&&obj.type!=='blackhole'){spawnAbsorbParticles(obj,bh);obj.dead=true;
        // Gatilho de Invasão Alien: BH criado pelo jogador absorve astro habitado
        if(!bh._autoSpawn&&typeof AlienInvasion!=='undefined'){
          const _BH_INHABITED=new Set(['star','cepheid','redDwarf','yellowDwarf','blueStar',
            'redGiant','supergiant','hypergiant','vampireStar','quarkStar','thorneZytkow',
            'ironStar','strangeStar','electroweakStar','planckStar','wolfRayet','przybylski',
            'janusStar','gravastar','quasiStar']);
          if(_BH_INHABITED.has(obj.type))AlienInvasion.tryTrigger();
        }
        // Gatilho de Invasão Marciana: BH criado pelo jogador absorve planeta/lua habitado
        if(!bh._autoSpawn&&typeof MarsianInvasion!=='undefined'){
          const _BH_MARS_TYPES=new Set(['planet','moon','gasgiant','icegiant','superearth',
            'minineptune','dwarfplanet','lavaplt','oceanplt','desertplt','carbonplt','ironplt']);
          if(_BH_MARS_TYPES.has(obj.type))MarsianInvasion.tryTrigger();
        }
      }
    });

    // BH gravity — Buracos Negros Errantes da Fase Cósmica (lista própria,
    // fora de objects[]). Mesma física de atração inverso-quadrado e
    // devoração dos buracos negros normais, mas sem gatilho de invasão
    // (são fenômeno ambiente, não criação do jogador) e sem lista de
    // imunes reduzida — mantém as mesmas exceções por segurança/consistência.
    if(sandboxMode&&_sandboxPhase==='cosmic'&&typeof _cosmicWanderers!=='undefined'&&_cosmicWanderers.length){
      const BH_IMMUNE_TYPES_W=new Set(['blackhole','greatattractor','vetocrinazar','galaxy','quasar','blazar','darkmatter','voidbelt','riftfissure','bosonstar','polarstar','wormhole','whitehole','nebula']);
      if(!BH_IMMUNE_TYPES_W.has(obj.type)){
        for(let wi=_cosmicWanderers.length-1;wi>=0;wi--){
          const w=_cosmicWanderers[wi];
          const dx=w.x-obj.x,dy=w.y-obj.y;
          const d=Math.hypot(dx,dy)||1;
          const pullRange=w.radius*9; // mesma proporção do BlackHole comum
          if(d>pullRange)continue;
          if(obj.type==='planet'||obj.type==='moon'||PP_ORBIT_TYPES.includes(obj.type))obj.parent=null;
          if(!obj.merging){
            const acc=(G_BLACK*(w.radius*70)*(obj.gravMultiplier||1))/(d*d+SOFT);
            obj.vx+=(dx/d)*acc*dt;obj.vy+=(dy/d)*acc*dt;
          }
          if(d<w.radius*1.25){
            if(typeof spawnAbsorbParticles==='function')spawnAbsorbParticles(obj,w);
            obj.dead=true;
          }
        }
      }
    }

    // MICROQUASAR — pulls objects lighter/smaller than itself; spiral-in with mass loss
    objects.forEach(mq=>{
      if(mq.type!=='microquasar'||mq===obj||mq.dead)return;
      if(obj.mass>mq.mass*.6)return; // only attracts lighter objects
      const d=dist(obj,mq);if(d>mq.pullRange)return;
      if(obj.type==='planet'||obj.type==='moon'||PP_ORBIT_TYPES.includes(obj.type))obj.parent=null;
      // Inverse-square pull
      const acc=(G_BLACK*mq.mass*.25)/(d*d+SOFT);
      const nx=(mq.x-obj.x)/d,ny=(mq.y-obj.y)/d;
      obj.vx+=nx*acc*dt;obj.vy+=ny*acc*dt;
      // Tangential component for spiral
      obj.vx+=(-ny)*acc*.6*dt;obj.vy+=(nx)*acc*.6*dt;
      // Mass loss as object spirals in
      if(d<mq.radius*4){obj.radius=Math.max(.5,(obj.radius||4)-dt*.4);obj.mass=Math.max(.1,(obj.mass||1)-dt*2);}
      // Consume when very close
      if(d<mq.radius*1.5){spawnAbsorbParticles(obj,mq);obj.dead=true;}
    });

    // QUASAR — raio giratório que arranca partes + puxa lentamente para o núcleo
    objects.forEach(qs=>{
      if(qs.type!=='quasar'||qs===obj||qs.dead)return;
      const d=dist(obj,qs);if(d>qs.pullRange)return;
      if(obj.type==='planet'||obj.type==='moon'||PP_ORBIT_TYPES.includes(obj.type))obj.parent=null;

      // ── Atração gravitacional LENTÍSSIMA (quase imperceptível) ──
      if(!obj.fixed||(obj.type==='star')){
        const acc=(G_BLACK*qs.mass*.018)/(d*d+SOFT);
        const nx=(qs.x-obj.x)/d,ny=(qs.y-obj.y)/d;
        obj.vx+=nx*acc*dt;obj.vy+=ny*acc*dt;
      }

      // ── Verificar se o raio giratório toca o objeto ──
      // O raio gira a jetAngle; verificamos os 2 braços (jetAngle e jetAngle+PI)
      const jl=220; // comprimento do raio em world units
      const jetW=qs.radius*2.2; // largura (cone) do raio
      for(let s=-1;s<=1;s+=2){
        const jdx=Math.cos(qs.jetAngle+s*Math.PI);
        const jdy=Math.sin(qs.jetAngle+s*Math.PI);
        const relx=obj.x-qs.x,rely=obj.y-qs.y;
        const proj=relx*jdx+rely*jdy;
        if(proj<0||proj>jl)continue; // fora do alcance do braço
        const perpX=relx-proj*jdx,perpY=rely-proj*jdy;
        const perpDist=Math.hypot(perpX,perpY);
        // Cone cresce com a distância
        const coneW=jetW*(0.5+proj/jl*0.8);
        if(perpDist>coneW)continue;

        // ── O raio tocou o objeto: arranca uma fatia ──
        if(obj.dead)break;
        const STRIPPABLE=['planet','moon','star','comet','meteor','protostar','cepheid'];
        if(!STRIPPABLE.includes(obj.type))continue;

        // Taxa de erosão proporcional à proximidade do eixo
        const erosion=dt*(.8+.6*(1-perpDist/coneW));
        if((obj.radius||4)>1.2){
          // Reduz o tamanho do objeto
          obj.radius=Math.max(1.2,(obj.radius||4)-erosion*.25);
          obj.mass=Math.max(.1,(obj.mass||1)-erosion*2);

          // Gera partículas no anel do quasar com a COR EXATA do objeto
          const baseColor=obj.color||obj.cloudColor||'rgb(200,200,200)';
          // Converte cor para rgb() se necessário (hsl → usamos como está)
          const numShards=randInt(1,3);
          if(!qs._ring)qs._ring=[];
          if(qs._ring.length<320){
            for(let i=0;i<numShards;i++){
              const startAngle=Math.atan2(obj.y-qs.y,obj.x-qs.x)+rand(-.35,.35);
              const startDist=d+rand(-obj.radius*.5,obj.radius*.5);
              // Velocidade angular: orbita em torno do quasar
              const vA=(Math.random()<.5?1:-1)*rand(.008,.022);
              // Velocidade de queda: muito lenta em direção ao núcleo
              const infall=rand(.012,.04);
              // Converte cor para rgb() se vier em hsl()
              let col=baseColor;
              if(col.startsWith('hsl')){
                const m=col.match(/hsl\(\s*([\d.]+)\s*,\s*([\d.]+)%\s*,\s*([\d.]+)%/);
                if(m){const h=parseFloat(m[1])/360,s=parseFloat(m[2])/100,l=parseFloat(m[3])/100;const q=l<.5?l*(1+s):l+s-l*s,p=2*l-q;const hf=f=>{let v=f<0?f+1:f>1?f-1:f;if(v<1/6)return p+(q-p)*6*v;if(v<.5)return q;if(v<2/3)return p+(q-p)*(2/3-v)*6;return p;};col=`rgb(${Math.round(hf(h+1/3)*255)},${Math.round(hf(h)*255)},${Math.round(hf(h-1/3)*255)})`;}
              }
              qs._ring.push({
                a:startAngle,
                dist:startDist,
                vA,
                infall,
                r:rand(.9,2.4),
                color:col,
                alpha:rand(.55,.9),
                life:1.0,
              });
            }
          }
        }

        // Destrói objetos muito pequenos que chegaram perto do núcleo
        if(d<qs.radius*1.4&&(obj.radius||4)<3){spawnAbsorbParticles(obj,qs);obj.dead=true;break;}
        // Absorção normal por contato direto com núcleo
        if(d<qs.radius*1.1){spawnAbsorbParticles(obj,qs);obj.dead=true;break;}
      }

      // Absorção por contato direto (sem jet) para objetos muito pequenos
      if(!obj.dead&&d<qs.radius*1.1){spawnAbsorbParticles(obj,qs);obj.dead=true;}
    });

    // BLAZAR — jet beam violently launches objects; small ones evaporate
    objects.forEach(bz=>{
      if(bz.type!=='blazar'||bz===obj||bz.dead)return;
      if(obj.fixed||obj.immune)return;
      // Check if obj is within either jet arm (both directions)
      for(let s=-1;s<=1;s+=2){
        const jdx=Math.cos(bz.jetAngle+s*Math.PI);
        const jdy=Math.sin(bz.jetAngle+s*Math.PI);
        // Vector from blazar to obj
        const relx=obj.x-bz.x,rely=obj.y-bz.y;
        const d=Math.hypot(relx,rely);
        if(d<bz.radius||d>bz.jetRange)continue;
        // Project onto jet axis to find along-jet distance and perpendicular distance
        const proj=relx*jdx+rely*jdy; // dot product along jet direction
        if(proj<0)continue; // wrong direction for this arm
        const perpX=relx-proj*jdx,perpY=rely-proj*jdy;
        const perpDist=Math.hypot(perpX,perpY);
        // Jet cone: width grows with distance (from radius*1.5 near core to jetWidth far)
        const coneW=bz.radius*1.5+(bz.jetWidth-bz.radius*1.5)*(proj/bz.jetRange);
        if(perpDist>coneW)continue;

        // Object is in the jet beam!
        if(obj.type==='planet'||obj.type==='moon'||PP_ORBIT_TYPES.includes(obj.type))obj.parent=null;

        // Launch velocity — opposite direction from the blazar center (away along jet)
        // Só aplica o impulso inicial UMA VEZ por entrada no cone (evita aceleração infinita)
        if(!obj._inBlazarJet){
          obj._inBlazarJet=true;
          const launchPower=rand(80,160);
          obj.vx+=jdx*launchPower;
          obj.vy+=jdy*launchPower;
          // Track blazar launch for missions — só conta se o blazar é do jogador
          // E o objeto lançado também é do jogador (não de galáxia auto-gerada)
          if(sandboxMode&&!bz._autoSpawn&&!obj._autoSpawn) incrementStat('blazarLaunches');
        }

        // Small bodies evaporate: moon, planet (small), comet, meteor
        const SMALL_TYPES=['moon','comet','meteor'];
        const isSmall=SMALL_TYPES.includes(obj.type)||(obj.type==='planet'&&obj.radius<8);
        if(isSmall){
          // Spawn red/orange evaporation particles trailing behind
          const numP=randInt(18,32);
          for(let i=0;i<numP;i++){
            const ang=rand(0,Math.PI*2);
            const spd=rand(1.5,7);
            const hue=rand(0,38); // red to orange
            particles.push({
              x:obj.x+rand(-obj.radius,obj.radius),
              y:obj.y+rand(-obj.radius,obj.radius),
              vx:Math.cos(ang)*spd - jdx*rand(2,5),
              vy:Math.sin(ang)*spd - jdy*rand(2,5),
              r:rand(1.5,4),alpha:.95,
              color:`hsl(${hue},100%,${rand(55,75)}%)`
            });
          }
          // Shrink and destroy
          obj.radius=Math.max(0,(obj.radius||4)-dt*30);
          obj.mass=Math.max(0,(obj.mass||1)-dt*80);
          if(obj.radius<=0.5){obj.dead=true;}
        }

        break; // only apply once per blazar per frame
      }
      // Limpa flag quando objeto sai do alcance do blazar (qualquer cone)
      if(obj._inBlazarJet){
        const stillInRange=objects.some(b2=>{
          if(b2.type!=='blazar'||b2.dead)return false;
          for(let s=-1;s<=1;s+=2){
            const jdx2=Math.cos(b2.jetAngle+s*Math.PI),jdy2=Math.sin(b2.jetAngle+s*Math.PI);
            const rx=obj.x-b2.x,ry=obj.y-b2.y;
            const d2=Math.hypot(rx,ry);
            if(d2<b2.radius||d2>b2.jetRange)continue;
            const pr=rx*jdx2+ry*jdy2;if(pr<0)continue;
            const px=rx-pr*jdx2,py=ry-pr*jdy2;
            const cw=b2.radius*1.5+(b2.jetWidth-b2.radius*1.5)*(pr/b2.jetRange);
            if(Math.hypot(px,py)<=cw)return true;
          }
          return false;
        });
        if(!stillInRange)obj._inBlazarJet=false;
      }
    });

    // ── CEFEIDA — Dança Orbital + Onda de Revelação ────────────────
    // Efeito 1: planetas/luas/meteoros orbitando a Cefeida têm
    //   velocidade de translação modulada em sincronia com o pulso.
    // Efeito 2: no pico do pulso, emite onda que revela objetos ocultos
    //   (darkmatter, bosonstar, voidbelt) temporariamente.
    objects.forEach(cf=>{
      if(cf.type!=='cepheid'||cf.dead)return;
      const raw=Math.sin(simTime*cf.pulseFreq+cf.glowPhase); // -1..1
      const atPeak=raw>=0.92;

      // ── Efeito 1: modulação orbital ───────────────────────────────
      // Apenas objetos que orbitam a Cefeida (parent===cf) são afetados
      if(obj.parent===cf&&(obj.type==='planet'||obj.type==='moon'||obj.type==='meteor')){
        const dOrb=dist(obj,cf);
        if(dOrb>1){
          // Vetor tangencial (perpendicular à linha obj→cf)
          const nx=(cf.x-obj.x)/dOrb,ny=(cf.y-obj.y)/dOrb;
          const tx=-ny,ty=nx; // tangente
          // Factor: 1.0 no repouso, até 1.55 no pico, até 0.52 no vale
          const factor=1.0+0.55*raw; // raw ∈ [-1,1] → factor ∈ [0.45,1.55]
          // Calcula speed atual projetada na tangente
          const curSpeed=obj.vx*tx+obj.vy*ty;
          if(Math.abs(curSpeed)>0.05){
            // Velocidade alvo = speed_base * factor (armazenada no construtor ou estimada)
            if(!obj._cephBase) obj._cephBase=Math.abs(curSpeed);
            const targetSpeed=obj._cephBase*factor;
            const delta=targetSpeed-curSpeed;
            // Aplicar impulso suave (não instantâneo) para criar a dança
            const smoothing=Math.min(1,dt*3.5);
            obj.vx+=tx*delta*smoothing;
            obj.vy+=ty*delta*smoothing;
          }
        }
      }

      // ── Efeito 2: onda de revelação no pico ──────────────────────
      if(atPeak&&!cf._revealFired){
        cf._revealFired=true;
        const REVEAL_RANGE=cf.baseRadius*18; // raio da onda de revelação
        const REVEAL_DUR=2.8; // segundos de visibilidade
        objects.forEach(hidden=>{
          if(hidden.dead)return;
          if(!['darkmatter','bosonstar','voidbelt'].includes(hidden.type))return;
          if(dist(cf,hidden)>REVEAL_RANGE)return;
          // Marca o objeto como "revelado" temporariamente
          if(!hidden._revealTimer||hidden._revealTimer<=0){
            hidden._revealTimer=REVEAL_DUR;
            // Cria partículas de "faísca reveladora" saindo da Cefeida em direção ao hidden
            const steps=6;
            for(let s=0;s<steps;s++){
              const frac=(s+1)/(steps+1);
              const px=cf.x+(hidden.x-cf.x)*frac,py=cf.y+(hidden.y-cf.y)*frac;
              const hue=cf._hueBase||45;
              particles.push({x:px,y:py,vx:rand(-1.2,1.2),vy:rand(-1.2,1.2),
                r:rand(2,4.5),alpha:.92,
                color:`hsl(${hue},100%,90%)`});
            }
          }
        });
        // Emite anel de revelação visual (já existe no draw — aqui adicionamos um extra grande)
        if(cf._rings) cf._rings.push({r:cf.baseRadius*2.5,alpha:.7,reveal:true});
      }
      if(raw<0.7) cf._revealFired=false;

      // ── Decai timer de revelação por frame ───────────────────────
      // (feito fora do loop interno para cada objeto oculto)
    });

    // VETOCRINAZAR physics — mode-based gravity
    objects.forEach(vz=>{
      if(vz.type!=='vetocrinazar'||vz===obj||vz.dead)return;
      const d=dist(obj,vz);if(d>vz.pullRange||d<1)return;
      if(obj.type==='planet'||obj.type==='moon'||PP_ORBIT_TYPES.includes(obj.type))obj.parent=null;
      const nx=(vz.x-obj.x)/d,ny=(vz.y-obj.y)/d;
      switch(vz.mode){
        case 0:{ // extreme attract
          const f=(G_BLACK*vz.mass*3.5)/(d*d+SOFT);
          obj.vx+=nx*f*dt;obj.vy+=ny*f*dt;
          break;
        }
        case 1:{ // extreme repel
          const f=(G_BLACK*vz.mass*3.5)/(d*d+SOFT);
          obj.vx-=nx*f*dt;obj.vy-=ny*f*dt;
          break;
        }
        case 2:{ // orbit capture — tangential impulse + gentle pull
          const tx=-ny,ty=nx; // perpendicular (tangent)
          const fRadial=(G_BLACK*vz.mass*1.2)/(d*d+SOFT);
          // Target orbit distance changes each cycle
          const targetD=vz._orbitDist;
          const ecc=vz._orbitEcc;
          const fT=Math.sqrt((G_BLACK*vz.mass)/Math.max(50,d))*(1+ecc*Math.cos(Math.atan2(obj.y-vz.y,obj.x-vz.x)));
          obj.vx+=(nx*fRadial+tx*fT*0.018)*dt;
          obj.vy+=(ny*fRadial+ty*fT*0.018)*dt;
          break;
        }
        case 3:{ // chaotic — random direction flips
          const chaos=(Math.random()-.5)*2;
          const f=(G_BLACK*vz.mass*2)/(d*d+SOFT)*chaos;
          obj.vx+=nx*f*dt;obj.vy+=ny*f*dt;
          break;
        }
      }
    });

    // White hole repulsion
    objects.forEach(wh=>{
      if(wh.type!=='whitehole'||wh===obj||wh.dead)return;
      const d=dist(obj,wh);if(d>wh.pushRange||d<.5)return;
      if(obj.type==='planet'||obj.type==='moon'||PP_ORBIT_TYPES.includes(obj.type))obj.parent=null;
      if(!obj.fixed){const acc=(G_WHITE*wh.mass)/(d*d+SOFT);const nx=(obj.x-wh.x)/d,ny=(obj.y-wh.y)/d;obj.vx+=nx*acc*dt;obj.vy+=ny*acc*dt;}
    });

    // Pulsar push
    objects.forEach(psr=>{
      if(psr.type!=='pulsar'||psr===obj||psr.dead)return;
      const d=dist(obj,psr);if(d>psr.pushRange||d<1)return;
      if(!obj.fixed){const radP=14*(1-d/psr.pushRange),nx=(obj.x-psr.x)/d,ny=(obj.y-psr.y)/d;obj.vx+=nx*radP*dt;obj.vy+=ny*radP*dt;obj.vx+=(-ny)*radP*.3*dt;obj.vy+=(nx)*radP*.3*dt;}
    });

    // Pulsar — sorteia novo ângulo-alvo a cada ~1s e gira suavemente até lá
    objects.forEach(psr=>{
      if(psr.type!=='pulsar'||psr.dead)return;
      psr._angleTimer=(psr._angleTimer||0)+dt;
      if(psr._angleTimer>=(psr._angleInterval||1.0)){
        psr._angleTimer=0;
        psr._angleInterval=0.85+Math.random()*0.35;
        // Sorteia ângulo-alvo completamente aleatório (0..2π)
        psr._targetAngle=Math.random()*Math.PI*2;
        // Emite anel de onda ao mudar de direção
        psr.waves.push({r:psr.radius*1.1,alpha:0.55});
      }
      // Lerp angular suave em direção ao alvo
      if(psr._targetAngle!==undefined){
        let diff=psr._targetAngle-psr.poleAngle;
        // Normaliza diferença para -π..π (caminho mais curto)
        while(diff> Math.PI)diff-=Math.PI*2;
        while(diff<-Math.PI)diff+=Math.PI*2;
        const step=(psr._rotSpeed||2.0)*dt;
        if(Math.abs(diff)<step) psr.poleAngle=psr._targetAngle;
        else psr.poleAngle+=Math.sign(diff)*step;
      }
    });

    // Magnetar orbital capture — a cada 3s muda parâmetros de órbita
    objects.forEach(mag=>{
      if(mag.type!=='magnetar'||mag===obj||mag.dead)return;
      const d=dist(obj,mag);if(d>mag.fieldRange||d<1)return;
      if(obj.fixed)return;
      // Conta a primeira vez que um astro DO JOGADOR entra no campo de um magnetar DO JOGADOR
      if(sandboxMode&&!mag._autoSpawn&&!obj._autoSpawn&&!obj._magnetarCounted){
        obj._magnetarCounted=true;
        incrementStat('magnetarCaptured');
      }
      // Orbital timer update (only once per magnetar per frame, guard with flag)
      if(!mag._orbitUpdated){
        mag._orbitTimer=(mag._orbitTimer||0)+dt;
        if(mag._orbitTimer>=mag._orbitInterval){
          mag._orbitTimer=0;
          mag._orbitEcc=rand(0,.75);
          mag._orbitDir=Math.random()<.5?1:-1;
          mag._orbitSpeed=rand(0.5,2.0);
          mag._orbitTargetDist=rand(55,155);
          mag._shiftFlash=1.0;
          mag._orbitUpdated=true; // prevent multi-update same frame
          showTooltip('🔮 Magnetar alterou campo gravitacional!');
        }
      }
      const nx=(obj.x-mag.x)/d,ny=(obj.y-mag.y)/d;
      // Tangential (orbital) force — direction flips with _orbitDir
      const tang=mag._orbitSpeed*10*(1-d/mag.fieldRange);
      obj.vx+=(-ny)*mag._orbitDir*tang*dt;
      obj.vy+=(nx)*mag._orbitDir*tang*dt;
      // Radial bias — nudge toward _orbitTargetDist (gentle)
      const radErr=(d-mag._orbitTargetDist)/mag.fieldRange;
      const ecc=mag._orbitEcc;
      obj.vx+=(-nx)*radErr*ecc*8*dt;
      obj.vy+=(-ny)*radErr*ecc*8*dt;
    });

    // ── Magnetar Catastrophe active physics ──
    if(obj.type==='magnetar'&&obj._catMode&&!obj.dead){
      obj._catTimer+=dt;
      obj._dustTimer+=dt;
      const phase=obj._catPhase;
      // Emit purple/pink dust wave continuously
      if(obj._dustTimer>0.08){
        obj._dustTimer=0;
        const a=rand(0,Math.PI*2);
        particles.push({x:obj.x+Math.cos(a)*obj.radius*1.4,y:obj.y+Math.sin(a)*obj.radius*1.4,
          vx:Math.cos(a)*rand(.5,2.5),vy:Math.sin(a)*rand(.5,2.5),
          r:rand(2,5),alpha:.7,color:`hsl(${rand(280,330)},90%,${rand(60,80)}%)`});
      }
      // Crack fissure beams — draw extra in the draw loop via obj._crackAngle
      obj._crackAngle+=.04;
      if(phase==='crack'&&obj._catTimer<4){
        obj.radius=obj._catBaseR*(1+Math.sin(obj._catTimer*4)*.25);
        // Fissure beams launch nearby small objects violently
        objects.forEach(o=>{
          if(o===obj||o.dead||o.immune)return;
          const d=dist(obj,o);if(d>obj.radius*6)return;
          const small=o.type==='planet'||o.type==='moon'||o.type==='meteor'||o.type==='comet';
          const nx=(o.x-obj.x)/d,ny=(o.y-obj.y)/d;
          if(small&&d<obj.radius*3){spawnAbsorbParticles(o);o.dead=true;return;}
          if(!o.fixed){o.vx+=nx*rand(8,20)*dt;o.vy+=ny*rand(8,20)*dt;}
        });
      } else if(phase==='crack'&&obj._catTimer>=4){
        obj._catPhase='attract';obj._catTimer=0;obj.radius=obj._catBaseR*1.5;
        showTooltip('🌀 Magnetar atraindo tudo com força massiva!');
      }
      if(phase==='attract'&&obj._catTimer<12){
        // Pull everything with force stronger than black hole
        objects.forEach(o=>{
          if(o===obj||o.dead||o.immune)return;
          const d=dist(obj,o);if(d<1)return;
          const acc=(G_BLACK*2.8)/(d*d+SOFT);
          const nx=(obj.x-o.x)/d,ny=(obj.y-o.y)/d;
          if(o.type==='planet'||o.type==='moon')o.parent=null;
          if(!o.fixed){o.vx+=nx*acc*dt;o.vy+=ny*acc*dt;}
          if(d<obj.radius*1.8&&!o.fixed){spawnAbsorbParticles(o);o.dead=true;}
        });
        obj.radius=obj._catBaseR*(1.5+.3*Math.sin(obj._catTimer*6));
      } else if(phase==='attract'&&obj._catTimer>=12){
        obj._catPhase='collapse';obj._catTimer=0;showTooltip('⚡ Magnetar colapsando — EXPLOSÃO FINAL!');
      }
      if(phase==='collapse'){
        if(obj._catTimer<1){
          // Rapid grow to 3x three stars combined ≈ baseR*8
          obj.radius=obj._catBaseR*(2.5+obj._catTimer*5.5);
        } else {
          // Explode — push everything outward, become neutron star
          const ox=obj.x,oy=obj.y;
          obj.dead=true;
          for(let i=0;i<200;i++){const a=rand(0,Math.PI*2),spd=rand(5,28);particles.push({x:ox,y:oy,vx:Math.cos(a)*spd,vy:Math.sin(a)*spd,r:rand(2,8),alpha:1,color:`hsl(${rand(260,350)},100%,${rand(60,90)}%)`});}
          for(let i=0;i<7;i++)particles.push({x:ox,y:oy,vx:0,vy:0,r:(i+1)*38,alpha:.9,color:'rgba(200,100,255,1)',ring:true,grow:20});
          triggerFlash(.95,600);
          // Push all objects away
          objects.forEach(o=>{if(o===obj||o.dead||o.immune)return;const d=dist({x:ox,y:oy},o);if(d<1)return;const f=Math.max(0,1-d/800)*40;const nx=(o.x-ox)/d,ny=(o.y-oy)/d;if(!o.fixed){o.vx+=nx*f;o.vy+=ny*f;}});
          const ns=new NeutronStar(ox,oy);
          if(obj._autoSpawn) ns._autoSpawn=true;
          pendingObjects.push(ns);
          showTooltip('🌟 Magnetar colapsou — Estrela de Nêutrons nasceu!');
        }
      }
    }

    // Integrate velocity
    if(!obj.parent&&(obj.type==='planet'||obj.type==='moon'||obj.type==='star'||obj.type==='blackhole'||obj.type==='cepheid'||obj.type==='protostar'||obj.type==='comet'||obj.type==='meteor'||obj.type==='quantikComet')){
      obj.x+=obj.vx*dt;obj.y+=obj.vy*dt;obj.vx*=.9988;obj.vy*=.9988;
    }

    // Wormhole teleport
    objects.forEach(worm=>{
      if(worm.type!=='wormhole'||worm===obj||worm.dead)return;
      if(dist(obj,worm)<worm.radius*.55){const pair=objects.find(o=>o.type==='wormhole'&&o.id===worm.pairId&&!o.dead);if(pair){const ang=rand(0,Math.PI*2);obj.x=pair.x+Math.cos(ang)*pair.radius*1.8;obj.y=pair.y+Math.sin(ang)*pair.radius*1.8;if(obj.type==='planet'||obj.type==='moon')obj.parent=null;spawnTeleportParticles(pair);}}
    });

    // Velocity cap
    if(!obj.fixed||obj.type==='blackhole'||obj.type==='star'){const spd=Math.hypot(obj.vx,obj.vy);if(spd>800){obj.vx=obj.vx/spd*800;obj.vy=obj.vy/spd*800;}}
  });

  // ── SANDBOX COLLISIONS ───────────────────────────────────────────
  if(sandboxMode){
    const planets=objects.filter(o=>o.type==='planet'&&!o.dead);
    // Planet vs Planet
    for(let i=0;i<planets.length;i++){
      for(let j=i+1;j<planets.length;j++){
        const a=planets[i],b=planets[j];
        if(a.dead||b.dead)continue;
        const d=dist(a,b);
        if(d<(a.radius+b.radius)*1.1){
          const totalMass=a.mass+b.mass;
          const mx=(a.x*a.mass+b.x*b.mass)/totalMass;
          const my=(a.y*a.mass+b.y*b.mass)/totalMass;
          const scale=Math.min((a.radius+b.radius)/18,2.5);
          for(let k=0;k<60;k++){const ang=rand(0,Math.PI*2),spd=rand(3,16)*scale;particles.push({x:mx,y:my,vx:Math.cos(ang)*spd,vy:Math.sin(ang)*spd,r:rand(1.5,5)*scale,alpha:1,color:`hsl(${rand(0,40)},100%,${rand(55,85)}%)`});}
          particles.push({x:mx,y:my,vx:0,vy:0,r:8,alpha:.85,color:'rgba(255,180,80,1)',ring:true,grow:12});
          triggerFlash(.4,250);
          // Conta colisão como missão SOMENTE se AMBOS os planetas são do jogador
          // E ao menos um foi intencionalmente lançado/arrastado pelo jogador (_movedByPlayer).
          // Isso evita que colisões por física gravitacional passiva contem automaticamente.
          const _bothPlayer=!a._autoSpawn&&!b._autoSpawn;
          const _intentional=a._movedByPlayer||b._movedByPlayer;
          const _playerColl=_bothPlayer&&_intentional;
          if(a.radius>b.radius*1.4){
            a.radius=Math.max(3,a.radius-b.radius*.35);a.mass=a.radius*3;b.dead=true;
            showTooltip(`💥 ${b.name} destruído por colisão!`);
            if(_playerColl)incrementStat('collisions');
          } else if(b.radius>a.radius*1.4){
            b.radius=Math.max(3,b.radius-a.radius*.35);b.mass=b.radius*3;a.dead=true;
            showTooltip(`💥 ${a.name} destruído por colisão!`);
            if(_playerColl)incrementStat('collisions');
          } else {
            a.dead=true;b.dead=true;
            showTooltip(`💥 Colisão: ${a.name} e ${b.name} destruídos!`);
            if(_playerColl)incrementStat('collisions');
          }
          // Gatilho Marciano: colisão entre planetas/luas do jogador
          if(_playerColl)window._marsianPlanetCollision=true;
        }
      }
    }
    // Comet / Meteor vs Planet
    const smalls=objects.filter(o=>(o.type==='comet'||o.type==='meteor')&&!o.dead);
    smalls.forEach(sm=>{
      planets.filter(p=>!p.dead).forEach(p=>{
        if(dist(sm,p)<(sm.radius+p.radius)*1.05){
          const mx=(sm.x+p.x)*.5,my=(sm.y+p.y)*.5;
          for(let k=0;k<28;k++){const ang=rand(0,Math.PI*2),spd=rand(2,10);particles.push({x:mx,y:my,vx:Math.cos(ang)*spd,vy:Math.sin(ang)*spd,r:rand(1,4),alpha:1,color:sm.type==='comet'?`hsl(${rand(170,210)},90%,75%)`:`hsl(${rand(20,45)},100%,${rand(55,80)}%)`});}
          particles.push({x:mx,y:my,vx:0,vy:0,r:5,alpha:.75,color:'rgba(255,200,80,1)',ring:true,grow:8});
          triggerFlash(.25,180);
          const dmg=sm.radius*0.4;
          p.radius=Math.max(2,p.radius-dmg);p.mass=p.radius*3;
          if(p.bioLevel>0)p.bioLevel=Math.max(0,p.bioLevel-1);
          sm.dead=true;
          showTooltip(`☄️ Impacto em ${p.name} — população afetada!`);
          // Conta colisão SOMENTE se AMBOS (cometa/meteoro e planeta) são do jogador
          // E ao menos um foi lançado intencionalmente pelo jogador
          if(!sm._autoSpawn&&!p._autoSpawn&&(sm._movedByPlayer||p._movedByPlayer)){
            incrementStat('collisions');
            // Gatilho Marciano: impacto em planeta habitado
            window._marsianPlanetCollision=true;
          }
        }
      });
    });
  } // fim if(sandboxMode) — colisões

  // ── PROTOSTAR: absorve astros pequenos em AMBOS os modos ────────
  {
    const protostars=objects.filter(o=>o.type==='protostar'&&!o.dead);
    const absorbables=objects.filter(o=>!o.dead&&(o.type==='planet'||o.type==='moon'||o.type==='comet'||o.type==='meteor'));
    protostars.forEach(proto=>{
      if(!proto._absorbed)proto._absorbed=0;
      const absorbRange=proto.radius*2.5;
      absorbables.forEach(sm=>{
        if(sm.dead)return;
        const d=dist(proto,sm);
        if(d<absorbRange*3&&d>absorbRange&&!sm.fixed){
          const nx=(proto.x-sm.x)/d,ny=(proto.y-sm.y)/d;
          const pull=600/(d*d+80);
          sm.vx+=nx*pull*dt;sm.vy+=ny*pull*dt;
        }
        if(d<absorbRange){
          proto._absorbed++;
          proto.radius=Math.min(proto.radius+1.5,52);
          proto.mass=proto.radius*3;
          for(let i=0;i<14;i++){const a=rand(0,Math.PI*2);particles.push({x:sm.x,y:sm.y,vx:(proto.x-sm.x)*0.05+Math.cos(a)*rand(0.5,2),vy:(proto.y-sm.y)*0.05+Math.sin(a)*rand(0.5,2),r:rand(1,3),alpha:.9,color:proto.cloudColor||'#88aaff'});}
          particles.push({x:proto.x,y:proto.y,vx:0,vy:0,r:proto.radius*0.8,alpha:.35,color:'rgba(120,160,255,1)',ring:true,grow:5});
          if(sm.parent)sm.parent=null;
          sm.dead=true;
          showTooltip(`🌫️ ${proto.name} absorveu ${sm.name}… (${proto._absorbed}/10)`);
          if(proto._absorbed>=10){
            const ox=proto.x,oy=proto.y;
            proto.dead=true;
            for(let i=0;i<80;i++){const a=rand(0,Math.PI*2),spd=rand(2,12);particles.push({x:ox,y:oy,vx:Math.cos(a)*spd,vy:Math.sin(a)*spd,r:rand(1.5,5),alpha:1,color:`hsl(${rand(25,55)},100%,${rand(65,90)}%)`});}
            for(let i=0;i<3;i++)particles.push({x:ox,y:oy,vx:0,vy:0,r:(i+1)*22,alpha:.85,color:'rgba(255,190,70,1)',ring:true,grow:12});
            triggerFlash(.65,350);
            const ns=new Star(ox,oy);ns.radius=rand(14,20);ns.mass=ns.radius*12;
            if(proto._autoSpawn) ns._autoSpawn=true;
            pendingObjects.push(ns);
            showTooltip('🌟 Protoestrela colapsou e virou uma Estrela!');
            // Só conta missão se a protoestrela foi colocada pelo jogador
            if(!proto._autoSpawn){
              incrementStat('protoCollapse');
            }
          }
        }
      });
    });
  }
  // ── DARK MATTER INTERACTION ───────────────────────────────────────
  objects.filter(o=>o.type==='darkmatter'&&!o.dead).forEach(dm=>{
    const range=dm.radius*5.5;
    objects.forEach(o=>{
      if(o===dm||o.dead||o.immune||o._darkMatterHit)return;
      if(dist(dm,o)<range){
        o._darkMatterHit=true;
        // Velocidade extrema na direção atual (ou aleatória)
        const spd=Math.hypot(o.vx,o.vy)||1;
        const boostAng=Math.atan2(o.vy,o.vx);
        o.vx=Math.cos(boostAng)*rand(80,160);
        o.vy=Math.sin(boostAng)*rand(80,160);
        // Manchas escuras por 10s
        o._darkSpots=true; o._darkSpotsTimer=10;
        // Sem gravidade por 10s
        o._noGravity=true; o._noGravityTimer=10;
        // Ejetar filhos (luas, astros orbitando)
        objects.forEach(child=>{
          if(child.dead||child.parent!==o)return;
          child.parent=null;
          const ea=rand(0,Math.PI*2);
          child.vx=Math.cos(ea)*rand(5,12); child.vy=Math.sin(ea)*rand(5,12);
        });
        // Partículas escuras
        for(let i=0;i<22;i++){const a=rand(0,Math.PI*2);particles.push({x:o.x,y:o.y,vx:Math.cos(a)*rand(2,7),vy:Math.sin(a)*rand(2,7),r:rand(1.5,4),alpha:.85,color:`rgba(${randInt(30,70)},0,${randInt(80,160)},0.9)`});}
        triggerFlash(0.18,200);
        showTooltip(`🕳️ ${o.name} tocou Matéria Escura — velocidade extrema e gravidade suspensa por 10s!`);
      }
    });
  });
  // Timers de Matéria Escura
  objects.forEach(o=>{
    if(o._noGravityTimer>0){o._noGravityTimer=Math.max(0,o._noGravityTimer-dt);if(o._noGravityTimer<=0)o._noGravity=false;}
    if(o._darkSpotsTimer>0){o._darkSpotsTimer=Math.max(0,o._darkSpotsTimer-dt);if(o._darkSpotsTimer<=0){o._darkSpots=false;o._darkMatterHit=false;}}
  });

  // Vetocrinazar — cycle mode every 5s
  objects.forEach(vz=>{
    if(vz.type!=='vetocrinazar'||vz.dead)return;
    vz.modeTimer+=dt;
    if(vz.modeTimer>=vz.modeInterval){
      vz.modeTimer=0;
      vz.mode=(vz.mode+1)%4;
      if(vz.mode===2){vz._orbitEcc=rand(0,.8);vz._orbitDist=rand(55,200);}
      vz._shockT=1.0;
      if(sandboxMode&&!vz._autoSpawn) incrementStat('vetocrinaShifts');
    }
  });
  // TwinStar — as duas estrelas giram continuamente em torno do centro
  objects.forEach(tw=>{
    if(tw.type!=='twinstar'||tw.dead)return;
    tw._angle=(tw._angle||0)+tw._rotSpeed*dt;
  });
  objects.forEach(psr=>{
    if(psr.type!=='pulsar'||psr.dead)return;
    // No continuous spin — beam stays fixed
    psr.beamFlashTimer+=dt;if(psr.beamFlashTimer>=psr.beamFlashInterval){psr.beamFlashTimer=0;psr.beamOn=!psr.beamOn;}
    psr.pulseTimer+=dt;
    if(psr.pulseTimer>=psr.pulseInterval){
      psr.pulseTimer=0;
      // Spike pulse glow and jitter
      psr._pulseDecay=1.0;
      psr.waves.push({r:psr.radius*1.5,alpha:.88});
      objects.forEach(o=>{if(o===psr||o.dead)return;const d=dist(o,psr);if(d>psr.pushRange||d<1)return;if(o.type==='planet'||o.type==='moon')o.parent=null;const impulse=180*(1-d/psr.pushRange),nx=(o.x-psr.x)/d,ny=(o.y-psr.y)/d;o.vx+=nx*impulse;o.vy+=ny*impulse;});
    }
  });
  objects.forEach(qs=>{if(qs.type==='quasar'&&!qs.dead)qs.jetAngle+=qs.jetSpeed*dt;});
  // PolarStar switch tick
  objects.forEach(ps=>{
    if(ps.type!=='polarstar'||ps.dead)return;
    ps._switchTimer+=dt;
    if(ps._switchTimer>=ps._switchInterval){
      ps._switchTimer=0;ps._switchInterval=rand(5,10);
      ps.attracting=!ps.attracting;
      showTooltip(ps.attracting?'⭐ Estrela Polarizada: ATRAINDO':'⭐ Estrela Polarizada: REPELINDO');
    }
  });

  // ── FROZEN CORE — resfria objetos próximos e aplica efeitos criativos ──
  objects.forEach(fc=>{
    if(fc.type!=='frozencore'||fc.dead)return;
    objects.forEach(o=>{
      if(o===fc||o.dead||o.immune)return;
      const d=dist(o,fc);
      if(d>fc.coldRange)return;
      const proximity=1-(d/fc.coldRange); // 0=borda, 1=centro

      // ── Resfriamento de temperatura (drástico, exponencial perto do núcleo) ──
      if(o.temp!=null&&o.temp>2){
        const coolRate=dt*(18+proximity*proximity*280); // até 300K/s no centro
        o.temp=Math.max(2,o.temp-coolRate);
      }

      // ── Efeito em estrelas: resfriam visualmente (muda cor para azul-frio) ──
      if(o.type==='star'||o.type==='cepheid'){
        if(!o._frozenHue){o._frozenHue=0;}
        o._frozenHue=Math.min(1,o._frozenHue+dt*proximity*0.6);
        // Interpola cor da estrela para azul gelado
        const h=Math.round(30+o._frozenHue*170); // laranja→azul
        const l=Math.round(70-o._frozenHue*20);
        o.color=`hsl(${h},${Math.round(100-o._frozenHue*40)}%,${l}%)`;
        // Partículas de gelo saindo da estrela
        if(proximity>0.4&&Math.random()<dt*proximity*3){
          const ang=rand(0,Math.PI*2);
          particles.push({x:o.x+Math.cos(ang)*o.radius,y:o.y+Math.sin(ang)*o.radius,
            vx:Math.cos(ang)*rand(0.5,2)*proximity,vy:Math.sin(ang)*rand(0.5,2)*proximity,
            r:rand(1,2.5),alpha:0.7,color:'rgba(180,235,255,1)'});
        }
      }

      // ── Efeito em planetas: congela superfície (muda cor para tons de gelo) ──
      if(o.type==='planet'){
        if(!o._frozenSurface)o._frozenSurface=0;
        o._frozenSurface=Math.min(1,o._frozenSurface+dt*proximity*0.4);
        if(o._frozenSurface>0.35){
          // Interpola para branco-azulado de planeta congelado
          const frac=o._frozenSurface;
          const fr=Math.round(lerp(80,220,frac)),fg=Math.round(lerp(120,240,frac)),fb=Math.round(lerp(160,255,frac));
          o._frozenColor=`rgb(${fr},${fg},${fb})`;
        }
        // Partícula de neve esporádica saindo do planeta
        if(proximity>0.5&&Math.random()<dt*proximity*1.5){
          const ang=rand(0,Math.PI*2);
          particles.push({x:o.x+Math.cos(ang)*o.radius,y:o.y+Math.sin(ang)*o.radius,
            vx:Math.cos(ang)*rand(0.3,1.2),vy:Math.sin(ang)*rand(0.3,1.2)-0.5,
            r:rand(0.8,1.8),alpha:0.6,color:'rgba(220,245,255,1)'});
        }
      }

      // ── Efeito em cometas/meteoros: aceleram (efeito criogênico de propulsão) ──
      if((o.type==='comet'||o.type==='meteor')&&proximity>0.25){
        const nx=(o.x-fc.x)/d,ny=(o.y-fc.y)/d;
        o.vx+=nx*proximity*22*dt;o.vy+=ny*proximity*22*dt;
        if(!o._cryoBoosted){o._cryoBoosted=true;showTooltip('🧊 Cometa acelerado pelo Núcleo Gélido!');}
      }

      // ── Efeito em gases (protostar, nebula): condensam partículas de gelo ──
      if((o.type==='protostar'||o.type==='nebula')&&proximity>0.3&&Math.random()<dt*proximity*2){
        const ang=rand(0,Math.PI*2);const spd=rand(0.4,1.5)*proximity;
        particles.push({x:o.x+Math.cos(ang)*o.radius*rand(0.2,0.9),
          y:o.y+Math.sin(ang)*o.radius*rand(0.2,0.9),
          vx:Math.cos(ang)*spd,vy:Math.sin(ang)*spd,
          r:rand(1,2.8),alpha:0.55,color:'rgba(160,220,255,1)'});
      }
    });
  });

  // Restaura estrelas/planetas que saem do alcance do FrozenCore
  const activeFCs=objects.filter(o=>o.type==='frozencore'&&!o.dead);
  objects.forEach(o=>{
    if(o.dead)return;
    const inRange=activeFCs.some(fc=>dist(o,fc)<=fc.coldRange);
    if(!inRange){
      // Aquece de volta gradualmente
      if(o._frozenHue&&o._frozenHue>0){
        o._frozenHue=Math.max(0,o._frozenHue-dt*0.15);
        if(o._frozenHue===0)delete o._frozenHue;
      }
      if(o._frozenSurface&&o._frozenSurface>0){
        o._frozenSurface=Math.max(0,o._frozenSurface-dt*0.12);
        if(o._frozenSurface===0){delete o._frozenSurface;delete o._frozenColor;}
      }
    }
  });
  objects.forEach(mag=>{
    if(mag.type!=='magnetar'||mag.dead)return;
    mag.magAngle+=mag.spinSpeed*dt;mag.burstTimer+=dt;
    if(mag.burstActive){mag.burstR+=6;mag.burstAlpha*=.93;if(mag.burstAlpha<.02)mag.burstActive=false;}
    if(mag.burstTimer>=mag.burstInterval){mag.burstTimer=0;mag.burstActive=true;mag.burstR=mag.radius*1.2;mag.burstAlpha=.95;
      objects.forEach(o=>{if(o===mag||o.dead)return;const d=dist(o,mag);if(d>mag.fieldRange||d<1)return;if(o.type==='planet'||o.type==='moon')o.parent=null;const impulse=120*(1-d/mag.fieldRange),nx=(o.x-mag.x)/d,ny=(o.y-mag.y)/d;o.vx+=nx*impulse;o.vy+=ny*impulse;});}
  });

  // ── CEFEIDA: decai timer de revelação de objetos ocultos (1x por frame) ──
  objects.forEach(hidden=>{
    if(!['darkmatter','bosonstar','voidbelt'].includes(hidden.type))return;
    if((hidden._revealTimer||0)>0) hidden._revealTimer-=dt;
  });

  // Cleanup
  objects=objects.filter(o=>!o.dead);objects.push(...pendingObjects);pendingObjects=[];
  particles=particles.filter(p=>p.alpha>.02);
  particles.forEach(p=>{if(p.ring){p.r+=p.grow;p.alpha*=.92;}else{p.x+=p.vx;p.y+=p.vy;p.vx*=.96;p.vy*=.96;p.alpha*=.94;p.r*=.97;}});

  // ── TRAVA DE SEGURANÇA DE PAINEL: fecha painéis abertos se o objeto selecionado
  // foi destruído pela física (colisão, absorção, supernova, etc.) ──────────────
  if(sandboxMode&&selectedObj&&(selectedObj.dead||!objects.includes(selectedObj))){
    // Fecha info-panel e sp-panel sem erro — o objeto já não existe no array ativo
    _closePanel('info-panel');
    _closePanel('sp-panel');
    _closePanel('bio-panel');
    selectedObj=null;
  }

  // ── MISSILE UPDATE ────────────────────────────────────────────
  if(_missileObj&&_missileTarget&&!_missileTarget.dead){
    const tx=_missileTarget.x,ty=_missileTarget.y;
    const dx=tx-_missileObj.x,dy=ty-_missileObj.y;
    const d2=Math.hypot(dx,dy);
    if(d2<4){
      // Impact!
      const ox=_missileObj.x,oy=_missileObj.y;
      _missileObj=null;_missileTarget=null;_activePower=null;
      for(let i=0;i<80;i++){const a=rand(0,Math.PI*2);particles.push({x:ox,y:oy,vx:Math.cos(a)*rand(3,16),vy:Math.sin(a)*rand(3,16),r:rand(2,7),alpha:1,color:`hsl(${rand(120,280)},100%,${rand(55,90)}%)`});}
      for(let i=0;i<3;i++)particles.push({x:ox,y:oy,vx:0,vy:0,r:(i+1)*18,alpha:.8,color:'rgba(150,255,200,1)',ring:true,grow:12});
      triggerFlash(.6,350);
      // find target object and nullify physics
      const hitObj=objects.find(o=>!o.dead&&Math.hypot(o.x-ox,o.y-oy)<o.radius+8);
      if(hitObj){
        // FIX: fixed=true sozinho só impedia o astro de SE MOVER por forças externas,
        // mas vários sistemas de gravidade (buraco branco, pulsar, etc.) só checam
        // "immune" para decidir se atraem o astro — sem immune, o alvo continuava
        // sendo puxado gravitacionalmente mesmo "fixo". Agora immune=true remove
        // de vez qualquer gravidade agindo sobre ele, como o poder promete.
        hitObj.fixed=true;hitObj.immune=true;hitObj.vx=0;hitObj.vy=0;hitObj.mass=0;
        showTooltip(`💥 Antimatéria anulou a física de ${hitObj.name} — gravidade zerada!`);
      }
      else showTooltip('💥 Explosão de antimatéria!');
    } else {
      // FIX: clampa o passo à distância restante — antes, com d2 pequeno e spd
      // maior que d2, o míssil ultrapassava o alvo (overshoot) e nunca entrava
      // em d2<4, ficando oscilando ao redor do alvo para sempre.
      const spd=Math.min(_missileObj._speed*dt,d2);
      _missileObj.x+=dx/d2*spd;_missileObj.y+=dy/d2*spd;
      _missileObj._ang=Math.atan2(dy,dx)+Math.PI/2;
      // Exhaust trail
      if(Math.random()<0.5)particles.push({x:_missileObj.x,y:_missileObj.y,vx:rand(-1,1),vy:rand(-1,1),r:rand(1,3),alpha:.7,color:'rgba(255,150,50,0.8)'});
    }
  } else if(_missileObj&&(!_missileTarget||_missileTarget.dead)){
    _missileObj=null;_missileTarget=null;_activePower=null;
  }

  // ── DEVOURER UPDATE ───────────────────────────────────────────
  if(_devourerActive){
    _devourerTimer+=dt;
    _devourerX+=80*dt; // move right across screen
    // Chomp nearby planets
    objects.forEach(o=>{
      if(o.dead||o.immune)return;
      if(o.type==='planet'||o.type==='moon'||o.type==='meteor'){
        const d2=Math.hypot(o.x-_devourerX,o.y-_devourerY);
        if(d2<50){
          for(let i=0;i<20;i++){const a=rand(0,Math.PI*2);particles.push({x:o.x,y:o.y,vx:Math.cos(a)*rand(2,8),vy:Math.sin(a)*rand(2,8),r:rand(1,5),alpha:1,color:`hsl(${rand(0,40)},100%,${rand(55,80)}%)`});}
          triggerFlash(.2,150);
          o.dead=true;
          showTooltip(`🤖 Robô devorou ${o.name}!`);
        }
      }
    });
    // Left screen when too far right
    const rightBound=cam.x+canvas.width/cam.zoom*0.65;
    if(_devourerX>rightBound){_devourerActive=false;_activePower=null;showTooltip('🤖 Robô Devorador saiu do sistema.');}
  }
  // ── Eclipse do Núcleo Dimensional: ativo enquanto o planeta colossal
  //    estiver fisicamente dentro do raio do núcleo, OU se forçado pelo
  //    Mod Menu. Checado por último, depois que todos os objetos já
  //    tiveram sua posição atualizada. ──────────────────────────────
  {
    const _core=objects.find(o=>o.type==='colossalBlueGiant'&&!o.dead);
    const _corePlanet=objects.find(o=>o.type==='colossalGiantPlanet'&&!o.dead);
    const _touchedCore=!!(_core&&_corePlanet&&Math.hypot(_corePlanet.x-_core.x,_corePlanet.y-_core.y)<_core.radius);
    // Início do evento: planeta tocou o núcleo (ou forçado) e o evento
    // cronometrado ainda não está rodando — dispara os 12 minutos e trava
    // o planeta exatamente no centro do núcleo.
    if(!_eclipseEventActive && (_touchedCore || (_eclipseForced&&sandboxMode&&_sandboxPhase==='cosmic')) && _core && _corePlanet){
      _eclipseEventActive=true;
      _eclipseEventTimer=0;
      _eclipseLockedPlanet=_corePlanet;
      _corePlanet.x=_core.x;_corePlanet.y=_core.y;
      _corePlanet._eclipseOrbitSpeedBackup=_corePlanet.orbitSpeed;
      _corePlanet.orbitSpeed=0; // trava a órbita enquanto durar o evento
    }
    if(_eclipseEventActive){
      _eclipseEventTimer+=dt;
      // Mantém o planeta grudado no centro do núcleo durante todo o evento.
      if(_eclipseLockedPlanet&&!_eclipseLockedPlanet.dead&&_core){
        _eclipseLockedPlanet.x=_core.x;_eclipseLockedPlanet.y=_core.y;
      }
      if(_eclipseEventTimer>=ECLIPSE_EVENT_DURATION || !_core || !_eclipseLockedPlanet || _eclipseLockedPlanet.dead){
        // Fim do evento: solta o planeta de volta pra órbita normal, um
        // pouco fora do raio do núcleo pra não reativar o evento na hora.
        if(_eclipseLockedPlanet&&!_eclipseLockedPlanet.dead){
          _eclipseLockedPlanet.orbitSpeed=_eclipseLockedPlanet._eclipseOrbitSpeedBackup||rand(0.002,0.006);
          if(_core){
            _eclipseLockedPlanet.orbitDist=Math.max(_eclipseLockedPlanet.orbitDist,_core.radius*1.4);
            _eclipseLockedPlanet.x=_core.x+Math.cos(_eclipseLockedPlanet.orbitAngle)*_eclipseLockedPlanet.orbitDist;
            _eclipseLockedPlanet.y=_core.y+Math.sin(_eclipseLockedPlanet.orbitAngle)*_eclipseLockedPlanet.orbitDist;
          }
        }
        _eclipseEventActive=false;
        _eclipseEventTimer=0;
        _eclipseLockedPlanet=null;
        _eclipseForced=false;
        cosmicTerrorMonstersReset();
      }
    }
    _eclipseActive = _eclipseEventActive;
  }
}

// ═══════════════════════════════════════════════════════════════════
//  RENDER
// ═══════════════════════════════════════════════════════════════════
function draw(t){
  ctx.clearRect(0,0,canvas.width,canvas.height);
  const _cosmicShake=(sandboxMode&&_sandboxPhase==='cosmic')?cosmicAtmosphereShake():{x:0,y:0};
  const _tearShakeVec=_tearShake();
  const _totalShakeX=_cosmicShake.x+_tearShakeVec.x, _totalShakeY=_cosmicShake.y+_tearShakeVec.y;
  if(_totalShakeX||_totalShakeY){ctx.save();ctx.translate(_totalShakeX,_totalShakeY);}
  const bg=ctx.createRadialGradient(canvas.width*.5,canvas.height*.4,0,canvas.width*.5,canvas.height*.5,canvas.width);
  bg.addColorStop(0,'#080c1a');bg.addColorStop(1,'#020308');
  ctx.fillStyle=bg;ctx.fillRect(0,0,canvas.width,canvas.height);
  drawBgStars(t);
  if(_isEvcActive())drawEvcBackground(t);
  if(sandboxMode&&_sandboxPhase==='cosmic')cosmicAtmosphereDrawBg(ctx);
  drawGravGrid();
  // Fase Cósmica: biomas territoriais desenhados no fundo, antes dos astros.
  if(sandboxMode&&_sandboxPhase==='cosmic'){
    cosmicBiomesDraw(ctx);
    cosmicRocksDraw(ctx);
    cosmicCrittersDraw(ctx);
    cosmicBossRelicsDraw(ctx);
  }
  // Wormhole pair lines
  const drawnPairs=new Set();
  objects.filter(o=>o.type==='wormhole').forEach(w=>{
    const pair=objects.find(o=>o.type==='wormhole'&&o.id===w.pairId);
    if(!pair||drawnPairs.has(w.pairId))return;drawnPairs.add(w.id);
    const rgb=w.colorSet[0].replace('#','').match(/../g).map(h=>parseInt(h,16)).join(',');
    ctx.beginPath();ctx.moveTo(w.sx(),w.sy());ctx.lineTo(pair.sx(),pair.sy());
    ctx.strokeStyle=`rgba(${rgb},0.13)`;ctx.lineWidth=1;ctx.setLineDash([4,9]);ctx.stroke();ctx.setLineDash([]);
  });
  // Draw order — greatattractor primeiro (fundo opaco), depois tudo mais
  ['colossalBlueGiant','colossalGiantPlanet','greatattractor','galaxy','voidbelt','riftfissure','bosonstar','blackhole','quasar','blazar','microquasar','whitehole','wormhole','darkmatter','polarstar','twinstar','triplestar','vetocrinazar','nebula','frozencore','star','cepheid','protostar','magnetar','pulsar','neutronstar','pulsarplanet','planet','gasgiant','icegiant','superearth','minineptune','dwarfplanet','lavaplt','oceanplt','desertplt','carbonplt','ironplt','redDwarf','yellowDwarf','blueStar','redGiant','supergiant','whiteDwarf','hypergiant','vampireStar','quarkStar','thorneZytkow','ironStar','strangeStar','electroweakStar','planckStar','wolfRayet','przybylski','janusStar','cosmicString','gravastar','quasiStar','exDarkStar','exLittleRedDot','exMonsterStar','exIronStar','exCosmicString','exBlitzar','exBeStar','exBinaryNeutronStar','exHoagObject','exDarkGalaxy','exRedHole','exNakedSingularity','exBlanet','exBrownSubdwarf','exQBall','exGeon','exDomainWall','exSpacetimeCrystal','exKugelblitz','exDarkEnergyStar','techDysonSphere','techDysonSwarm','techShkadovThruster','techMatrioshkaBrain','techSpaceElevator','techAlcubierreDrive','techMassExtractor','techAldersonDisk','techNicollDyson','techGravityProjector','entityStarDevourer','entityInvasionFleet','entityMarcianFleet','entityReptilianFleet','entityCosmicParasite','entityVoidSerpent','entityMechaWorld','techProbe','techLaboratory','techStation','techTelescope','entityAlien','entityMarcian','entityReptilian','moon','comet','quantikComet','meteor','cosmicProbe'].forEach(type=>{
    objects.filter(o=>o.type===type&&!o.dead).forEach(o=>{
      if(o.skinHue){
        o.draw(t);
        // Tint leve por cima do astro já desenhado (evita ctx.filter em
        // canvas, que causa artefato de grade/tile em alguns navegadores
        // mobile). 'source-atop' só pinta onde já há pixels opacos do
        // astro, então o tint fica restrito à forma dele.
        const sx=o.sx(),sy=o.sy(),r=(o.sr?o.sr():o.radius*cam.zoom)*3.5;
        ctx.save();
        ctx.globalCompositeOperation='source-atop';
        ctx.globalAlpha=Math.min(.45,.18*(o.skinSat||1));
        ctx.fillStyle=`hsl(${o.skinHue},85%,55%)`;
        ctx.beginPath();ctx.arc(sx,sy,r,0,Math.PI*2);ctx.fill();
        ctx.restore();
      }else{
        o.draw(t);
      }
    });
  });
  // Fase Cósmica (pós-derrota do Quasord): raças cósmicas, astros vivos
  // e buracos negros errantes vagando sozinhos.
  if(sandboxMode&&_sandboxPhase==='cosmic'){
    cosmicGasCloudsDraw(ctx);
    cosmicRupturesDraw(ctx);
    cosmicEclipseSpritesDraw(ctx);
    cosmicRacesDraw(ctx);
    cosmicLivingDraw(ctx);
    cosmicWanderersDraw(ctx);
    cosmicMonstersDraw(ctx);
    galaxySerpentsDraw(ctx);
    cosmicShoalDraw(ctx);
    cosmicTerrorMonstersDraw(ctx);
    cosmicDefendersDraw(ctx);
    cosmicProjectilesDraw(ctx);
    cosmicFleetsDraw(ctx); // frotas ativas — desenhadas antes das abandonadas
    cosmicDerelictsDraw(ctx); // naves abandonadas — desenhadas por último, sobrepõem tudo
  }
  // ── EFEITOS DE SOBREPOSIÇÃO POR OBJETO (quarkWhite, heatFlash, quasiHeat) ──
  objects.forEach(o=>{
    if(o.dead)return;
    const ox=o.sx(),oy=o.sy(),or2=o.sr();
    if(o._quarkWhite>0){
      const qA=Math.min(1,o._quarkWhite/1.5)*(0.7+0.3*Math.sin(o._quarkWhite*12));
      const qg=ctx.createRadialGradient(ox,oy,0,ox,oy,or2*1.4);
      qg.addColorStop(0,`rgba(255,255,255,${qA})`);qg.addColorStop(0.5,`rgba(230,240,255,${qA*.6})`);qg.addColorStop(1,'transparent');
      ctx.beginPath();ctx.arc(ox,oy,or2*1.4,0,Math.PI*2);ctx.fillStyle=qg;ctx.fill();
    }
    if(o._heatFlash>0){
      const hA=Math.min(1,o._heatFlash/1.5)*.55;
      const hg=ctx.createRadialGradient(ox,oy,0,ox,oy,or2*1.6);
      hg.addColorStop(0,`rgba(255,255,200,${hA})`);hg.addColorStop(0.5,`rgba(255,140,30,${hA*.5})`);hg.addColorStop(1,'transparent');
      ctx.beginPath();ctx.arc(ox,oy,or2*1.6,0,Math.PI*2);ctx.fillStyle=hg;ctx.fill();
    }
  });
  // Sandbox selection ring
  if(sandboxMode&&selectedObj&&!selectedObj.dead){
    const sx=selectedObj.sx(),sy=selectedObj.sy(),r=selectedObj.sr()+6;
    ctx.beginPath();ctx.arc(sx,sy,r,0,Math.PI*2);
    ctx.strokeStyle='rgba(255,107,157,.75)';ctx.lineWidth=1.5;ctx.setLineDash([4,4]);ctx.stroke();ctx.setLineDash([]);
  }
  // ── MANCHAS ESCURAS (efeito Matéria Escura) ─────────────────────
  objects.forEach(o=>{
    if(!o._darkSpots||o.dead)return;
    const sx=o.sx(),sy=o.sy(),r=o.sr();
    const pulse=0.6+0.4*Math.sin(t*4+o.id);
    for(let i=0;i<6;i++){
      const a=(i/6)*Math.PI*2+(t*0.5);
      const dx=Math.cos(a)*r*0.55,dy=Math.sin(a)*r*0.55;
      const sr2=r*(0.18+0.08*Math.sin(t*3+i));
      const g=ctx.createRadialGradient(sx+dx,sy+dy,0,sx+dx,sy+dy,sr2*cam.zoom);
      g.addColorStop(0,`rgba(10,0,30,${0.82*pulse})`);
      g.addColorStop(0.5,`rgba(40,0,80,${0.45*pulse})`);
      g.addColorStop(1,'transparent');
      ctx.beginPath();ctx.arc(sx+dx,sy+dy,sr2*cam.zoom,0,Math.PI*2);ctx.fillStyle=g;ctx.fill();
    }
    // Barra de timer
    const pct=Math.max(0,(o._darkSpotsTimer||0)/10);
    ctx.save();
    ctx.beginPath();ctx.roundRect(sx-r,sy+r+4*cam.zoom,r*2,3*cam.zoom,1.5);ctx.fillStyle='rgba(60,0,120,0.45)';ctx.fill();
    ctx.beginPath();ctx.roundRect(sx-r,sy+r+4*cam.zoom,r*2*pct,3*cam.zoom,1.5);ctx.fillStyle='rgba(140,60,255,0.85)';ctx.fill();
    ctx.restore();
  });
  // Particles
  particles.forEach(p=>{
    const s=worldToScreen(p.x,p.y);
    if(p.ring){ctx.beginPath();ctx.arc(s.x,s.y,p.r*cam.zoom,0,Math.PI*2);ctx.strokeStyle=p.color.replace('1)',''+p.alpha+')');ctx.globalAlpha=p.alpha;ctx.lineWidth=3;ctx.stroke();ctx.globalAlpha=1;}
    else{ctx.beginPath();ctx.arc(s.x,s.y,Math.max(.5,p.r*cam.zoom),0,Math.PI*2);ctx.globalAlpha=p.alpha;ctx.fillStyle=p.color;ctx.fill();ctx.globalAlpha=1;}
  });
  // Destruction power overlays
  renderFusionLaser();
  renderMissile();
  renderDevourer(t);

  // ── Barras de HP dos astros durante invasão ──────────────────────
  if((typeof AlienInvasion!=='undefined'&&AlienInvasion.isActive())||(typeof MarsianInvasion!=='undefined'&&MarsianInvasion.isActive())||(typeof ReptilianInvasion!=='undefined'&&ReptilianInvasion.isActive())||(typeof PolvicullusBoss!=='undefined'&&PolvicullusBoss.isActive())){
    ctx.save();
    objects.forEach(o=>{
      if(o.dead||o._invasionHP===undefined)return;
      const sx=o.sx(),sy=o.sy(),r=o.sr()*cam.zoom;
      const pct=Math.max(0,o._invasionHP/100);
      const bw=Math.max(28,r*2.2), bh=5, bx=sx-bw/2, by=sy+r+5;
      // Fundo
      ctx.fillStyle='rgba(0,0,0,0.55)';
      ctx.beginPath();ctx.roundRect(bx,by,bw,bh,2.5);ctx.fill();
      // Preenchimento
      const hpColor=pct>0.6?'#44ff88':pct>0.3?'#ffcc00':'#ff3344';
      ctx.fillStyle=hpColor;
      ctx.beginPath();ctx.roundRect(bx,by,bw*pct,bh,2.5);ctx.fill();
      // Borda
      ctx.strokeStyle='rgba(255,255,255,0.18)';ctx.lineWidth=0.8;
      ctx.beginPath();ctx.roundRect(bx,by,bw,bh,2.5);ctx.stroke();
    });
    ctx.restore();
  }
  if(sandboxMode&&_sandboxPhase==='cosmic')cosmicAtmosphereDrawVignette(ctx);
  // ── Eclipse do Núcleo Dimensional: cor sólida vermelha em opacidade
  //    14% sobre tudo, deixando o jogo levemente mais vermelho. ────────
  if(_eclipseActive){
    ctx.fillStyle='rgba(200,20,20,0.14)';
    ctx.fillRect(0,0,canvas.width,canvas.height);
  }
  // ── Glitch visual ao se aproximar do Núcleo Dimensional: puramente
  //    decorativo, desenhado por cima de tudo. Nunca interfere no astro
  //    em si (que já foi desenhado normalmente acima), então o Núcleo
  //    nunca fica invisível por causa deste efeito. ─────────────────────
  if(_coreGlitchLevel>0)_drawCoreGlitchOverlay(_coreGlitchLevel,t);
  if(_totalShakeX||_totalShakeY){ctx.restore();}
}

function _drawCoreGlitchOverlay(level,t){
  ctx.save();
  const bandCount=Math.round(2+level*10);
  ctx.globalAlpha=0.5*level;
  for(let i=0;i<bandCount;i++){
    const bandH=rand(2,14)*level+1;
    const by=Math.random()*canvas.height;
    const offset=(Math.random()-0.5)*40*level;
    ctx.save();
    ctx.beginPath();ctx.rect(0,by,canvas.width,bandH);ctx.clip();
    ctx.fillStyle=Math.random()<0.5?'rgba(120,230,255,0.5)':'rgba(255,60,90,0.35)';
    ctx.fillRect(offset,by,canvas.width,bandH);
    ctx.restore();
  }
  ctx.globalAlpha=1;

  const blockCount=Math.round(level*18);
  for(let i=0;i<blockCount;i++){
    const bw=rand(6,26),bh=rand(4,16);
    const bx=Math.random()*canvas.width,by=Math.random()*canvas.height;
    ctx.globalAlpha=0.25*level*Math.random();
    ctx.fillStyle=['#8fe8ff','#ff3355','#ffffff','#2a9fc4'][Math.floor(Math.random()*4)];
    ctx.fillRect(bx,by,bw,bh);
  }
  ctx.globalAlpha=1;

  const pulse=0.75+0.25*Math.sin(t*9);
  const vig=ctx.createRadialGradient(
    canvas.width/2,canvas.height/2,Math.min(canvas.width,canvas.height)*0.25,
    canvas.width/2,canvas.height/2,Math.max(canvas.width,canvas.height)*0.7
  );
  vig.addColorStop(0,'rgba(255,40,60,0)');
  vig.addColorStop(1,`rgba(255,40,60,${0.45*level*pulse})`);
  ctx.fillStyle=vig;
  ctx.fillRect(0,0,canvas.width,canvas.height);

  if(level>0.55){
    ctx.globalAlpha=Math.min(1,(level-0.55)/0.45)*(0.6+0.4*Math.sin(t*14));
    ctx.fillStyle='#ff3355';
    ctx.font=`bold ${Math.max(14,Math.min(canvas.width,canvas.height)*0.035)}px 'Courier New'`;
    ctx.textAlign='center';
    ctx.fillText('⚠ INSTABILIDADE DIMENSIONAL — RECUE ⚠',canvas.width/2,canvas.height*0.12);
    ctx.textAlign='left';
    ctx.globalAlpha=1;
  }
  ctx.restore();
}

// ═══════════════════════════════════════════════════════════════════
//  MAIN LOOP
// ═══════════════════════════════════════════════════════════════════
let simTime=0; // tempo acumulado em segundos (usado pela física da Cefeida)
function loop(ts){
  const rawDt=Math.min((ts-lastTime)/1000,.05);
  const dt2=rawDt*(window._simSpeed||1);
  lastTime=ts;
  simTime+=dt2;
  frameCount++;fpsTimer+=rawDt;
  if(fpsTimer>=.5){document.getElementById('fps-counter').textContent=`${Math.round(frameCount/fpsTimer)} fps`;frameCount=0;fpsTimer=0;}
  if(currentScreen==='game'){
    try{
      update(dt2);draw(ts/1000);
      if(typeof AudioSys!=='undefined')AudioSys.tickProximity();
      // Garante que o botão de funções de destruição some/apareça
      // imediatamente ao iniciar/terminar QUALQUER invasão, sem esperar
      // uma troca de modo Normal/Sandbox (que é quando startGame() roda).
      if(typeof updateDestructionToggleVisibility==='function')updateDestructionToggleVisibility();
      if(typeof updateInvasionHudVisibility==='function')updateInvasionHudVisibility();
    }catch(err){
      console.error('Erro no loop principal:',err);
    }
  }
  document.getElementById('obj-count').textContent=`${objects.length} obj`;
  document.getElementById('cam-coords').textContent=`${Math.round(cam.x)},${Math.round(cam.y)} z${Math.round(cam.zoom*100)}%`;
  requestAnimationFrame(loop);
}
requestAnimationFrame(loop);

// ═══════════════════════════════════════════════════════════════════
//  DESTRUCTION PANEL
// ═══════════════════════════════════════════════════════════════════
// ═══════════════════════════════════════════════════════════════════
//  DESTRUCTION POWER STATE
// ═══════════════════════════════════════════════════════════════════
let _activePower=null; // current active destruction mode
let _fusionLaserActive=false, _fusionLaserPts=[];
let _missileObj=null, _missileTarget=null;
let _devourerActive=false,_devourerX=-9999,_devourerY=0,_devourerTimer=0;
let _shrinkTarget=null,_shrinkInterval=null;
let _drainInterval=null;
let _greyGooTarget=null,_greyGooInterval=null;

// Fusion Laser — renders laser trail on canvas
function renderFusionLaser(){
  if(!_fusionLaserActive||_fusionLaserPts.length<2)return;
  ctx.save();
  ctx.lineJoin='round';ctx.lineCap='round';
  // Outer red glow
  ctx.beginPath();
  _fusionLaserPts.forEach((p,i)=>i===0?ctx.moveTo(worldToScreen(p.x,p.y).x,worldToScreen(p.x,p.y).y):ctx.lineTo(worldToScreen(p.x,p.y).x,worldToScreen(p.x,p.y).y));
  ctx.strokeStyle='rgba(255,50,0,0.35)';ctx.lineWidth=14*cam.zoom;ctx.stroke();
  // Mid
  ctx.beginPath();
  _fusionLaserPts.forEach((p,i)=>i===0?ctx.moveTo(worldToScreen(p.x,p.y).x,worldToScreen(p.x,p.y).y):ctx.lineTo(worldToScreen(p.x,p.y).x,worldToScreen(p.x,p.y).y));
  ctx.strokeStyle='rgba(255,120,20,0.75)';ctx.lineWidth=6*cam.zoom;ctx.stroke();
  // White core
  ctx.beginPath();
  _fusionLaserPts.forEach((p,i)=>i===0?ctx.moveTo(worldToScreen(p.x,p.y).x,worldToScreen(p.x,p.y).y):ctx.lineTo(worldToScreen(p.x,p.y).x,worldToScreen(p.x,p.y).y));
  ctx.strokeStyle='rgba(255,255,200,0.95)';ctx.lineWidth=2*cam.zoom;ctx.stroke();
  ctx.restore();
  // Fire particles along trail
  if(Math.random()<0.4&&_fusionLaserPts.length>0){
    const pt=_fusionLaserPts[Math.floor(Math.random()*_fusionLaserPts.length)];
    particles.push({x:pt.x,y:pt.y,vx:rand(-1.5,1.5),vy:rand(-3,-0.5),r:rand(1.5,4),alpha:0.9,color:`hsl(${rand(0,40)},100%,${rand(55,85)}%)`});
  }
}

// Missile obj — redesenhado: fuselagem afunilada, aletas, faixa de energia
// e chama em duas camadas (antes era uma capsule lisa + triângulo chapado).
function renderMissile(){
  if(!_missileObj)return;
  const s=worldToScreen(_missileObj.x,_missileObj.y);
  const ang=_missileObj._ang||0;
  const z=cam.zoom,r=11*z;
  ctx.save();ctx.translate(s.x,s.y);ctx.rotate(ang);

  // Chama de exaustão — camada externa laranja + núcleo claro
  ctx.beginPath();
  ctx.moveTo(-r*0.32,r*0.65);ctx.lineTo(r*0.32,r*0.65);ctx.lineTo(0,r*1.5);ctx.closePath();
  ctx.fillStyle='rgba(255,150,50,0.85)';ctx.fill();
  ctx.beginPath();
  ctx.moveTo(-r*0.16,r*0.65);ctx.lineTo(r*0.16,r*0.65);ctx.lineTo(0,r*1.05);ctx.closePath();
  ctx.fillStyle='rgba(255,230,170,0.9)';ctx.fill();

  // Aletas
  ctx.fillStyle='#8a9cc0';
  [-1,1].forEach(side=>{
    ctx.beginPath();
    ctx.moveTo(side*r*0.28,r*0.3);ctx.lineTo(side*r*0.62,r*0.7);ctx.lineTo(side*r*0.28,r*0.6);
    ctx.closePath();ctx.fill();
  });

  // Corpo — fuselagem afunilada (não é mais uma capsule simétrica)
  ctx.beginPath();
  ctx.moveTo(0,-r*1.35);
  ctx.lineTo(-r*0.28,-r*0.6);
  ctx.lineTo(-r*0.28,r*0.65);
  ctx.lineTo(r*0.28,r*0.65);
  ctx.lineTo(r*0.28,-r*0.6);
  ctx.closePath();
  const bodyG=ctx.createLinearGradient(-r*0.28,0,r*0.28,0);
  bodyG.addColorStop(0,'#7d90b0');bodyG.addColorStop(0.5,'#dce6f5');bodyG.addColorStop(1,'#7d90b0');
  ctx.fillStyle=bodyG;ctx.fill();
  ctx.strokeStyle='rgba(120,150,190,0.8)';ctx.lineWidth=1;ctx.stroke();

  // Faixa de energia central (fake-glow double-stroke)
  ctx.beginPath();ctx.moveTo(0,-r*0.5);ctx.lineTo(0,r*0.55);
  ctx.strokeStyle='rgba(120,220,255,0.35)';ctx.lineWidth=4*z;ctx.stroke();
  ctx.beginPath();ctx.moveTo(0,-r*0.5);ctx.lineTo(0,r*0.55);
  ctx.strokeStyle='rgba(190,240,255,0.9)';ctx.lineWidth=1.4*z;ctx.stroke();

  // Ogiva vermelha com brilho
  ctx.beginPath();
  ctx.moveTo(0,-r*1.4);ctx.lineTo(-r*0.28,-r*0.62);ctx.lineTo(r*0.28,-r*0.62);ctx.closePath();
  ctx.fillStyle='#e83030';ctx.fill();
  ctx.beginPath();ctx.arc(0,-r*1.05,r*0.11,0,Math.PI*2);
  ctx.fillStyle='rgba(255,220,220,0.9)';ctx.fill();

  ctx.restore();
}

// Devourer robot — redesenhado: corpo hexagonal blindado com placas internas,
// núcleo de energia pulsante, olhos em fenda (antes: círculos genéricos),
// mandíbulas mecânicas com dentes (antes: arco liso) e braços articulados
// com cotovelo e garra (antes: barras retas sem juntas).
function renderDevourer(t){
  if(!_devourerActive)return;
  const s=worldToScreen(_devourerX,_devourerY);
  const r=30*cam.zoom;
  ctx.save();ctx.translate(s.x,s.y);

  // Corpo — hexágono blindado
  ctx.beginPath();
  for(let i=0;i<6;i++){
    const a=Math.PI/6+i*Math.PI/3;
    const rr=r*(i%2===0?1.05:0.85);
    const px=Math.cos(a)*rr,py=Math.sin(a)*rr*1.15;
    i===0?ctx.moveTo(px,py):ctx.lineTo(px,py);
  }
  ctx.closePath();
  const bg=ctx.createRadialGradient(0,0,r*0.1,0,0,r*1.2);
  bg.addColorStop(0,'#3a5570');bg.addColorStop(0.6,'#1c2a3a');bg.addColorStop(1,'#080f18');
  ctx.fillStyle=bg;ctx.fill();
  ctx.strokeStyle='rgba(100,180,255,0.55)';ctx.lineWidth=1.5;ctx.stroke();

  // Placas internas (linhas do centro aos vértices)
  ctx.strokeStyle='rgba(80,140,190,0.4)';ctx.lineWidth=1;
  for(let i=0;i<6;i++){
    const a=Math.PI/6+i*Math.PI/3;
    ctx.beginPath();ctx.moveTo(0,0);ctx.lineTo(Math.cos(a)*r*0.5,Math.sin(a)*r*0.5*1.15);ctx.stroke();
  }

  // Núcleo de energia pulsante
  const pulse=0.85+0.15*Math.sin(_devourerTimer*6);
  const coreR=r*0.22*pulse;
  const coreG=ctx.createRadialGradient(0,0,0,0,0,coreR*2.2);
  coreG.addColorStop(0,'rgba(255,220,200,0.9)');coreG.addColorStop(0.5,'rgba(255,70,70,0.5)');coreG.addColorStop(1,'transparent');
  ctx.beginPath();ctx.arc(0,0,coreR*2.2,0,Math.PI*2);ctx.fillStyle=coreG;ctx.fill();
  ctx.beginPath();ctx.arc(0,0,coreR,0,Math.PI*2);ctx.fillStyle='#ff5050';ctx.fill();

  // Olhos — fendas triangulares (não círculos genéricos)
  [-1,1].forEach(side=>{
    const ex=side*r*0.35,ey=-r*0.35;
    ctx.beginPath();
    ctx.moveTo(ex-r*0.14,ey);ctx.lineTo(ex+r*0.14,ey);ctx.lineTo(ex+side*r*0.04,ey+r*0.3);
    ctx.closePath();
    ctx.fillStyle='rgba(255,50,50,0.95)';ctx.fill();
  });

  // Mandíbulas mecânicas com dentes
  const jawOpen=0.2+0.5*Math.abs(Math.sin(_devourerTimer*8));
  const jy=r*0.4;
  ctx.beginPath();
  ctx.moveTo(-r*0.45,jy);ctx.lineTo(r*0.45,jy);
  ctx.lineTo(r*0.3,jy+r*0.3*jawOpen+r*0.2);ctx.lineTo(-r*0.3,jy+r*0.3*jawOpen+r*0.2);
  ctx.closePath();
  ctx.fillStyle='rgba(20,20,25,0.95)';ctx.fill();
  ctx.strokeStyle='rgba(255,120,60,0.7)';ctx.lineWidth=1.5;ctx.stroke();
  ctx.fillStyle='#dcdce6';
  for(let i=0;i<5;i++){
    const tx=-r*0.36+i*(r*0.72/4);
    ctx.beginPath();ctx.moveTo(tx-3,jy);ctx.lineTo(tx+3,jy);ctx.lineTo(tx,jy+r*0.2);ctx.closePath();ctx.fill();
  }

  // Braços articulados com cotovelo e garra
  const armAngle=Math.sin(_devourerTimer*5)*0.35;
  [-1,1].forEach(side=>{
    const sx0=side*r*0.9,sy0=-r*0.05;
    const ea=side*(0.9+armAngle);
    const elbowX=sx0+Math.cos(ea)*r*0.5,elbowY=sy0+Math.sin(ea)*r*0.5+r*0.3;
    const handX=elbowX+side*r*0.15,handY=elbowY+r*0.5;
    ctx.lineWidth=r*0.16;ctx.strokeStyle='#4a7095';ctx.lineCap='round';
    ctx.beginPath();ctx.moveTo(sx0,sy0);ctx.lineTo(elbowX,elbowY);ctx.stroke();
    ctx.lineWidth=r*0.13;ctx.strokeStyle='#355070';
    ctx.beginPath();ctx.moveTo(elbowX,elbowY);ctx.lineTo(handX,handY);ctx.stroke();
    ctx.beginPath();ctx.arc(elbowX,elbowY,r*0.09,0,Math.PI*2);ctx.fillStyle='#7fb0e0';ctx.fill();
    // garra dupla
    ctx.strokeStyle='rgba(220,60,60,0.9)';ctx.lineWidth=3;ctx.lineCap='round';
    ctx.beginPath();ctx.moveTo(handX,handY);ctx.lineTo(handX-side*r*0.02-6,handY+14);ctx.stroke();
    ctx.beginPath();ctx.moveTo(handX,handY);ctx.lineTo(handX+side*r*0.02+6,handY+14);ctx.stroke();
  });

  ctx.restore();
}

function applyDestruction(id){
  // Bloqueado durante qualquer invasão ativa
  if((typeof AlienInvasion!=='undefined'&&AlienInvasion.isActive())||
     (typeof MarsianInvasion!=='undefined'&&MarsianInvasion.isActive())||
     (typeof ReptilianInvasion!=='undefined'&&ReptilianInvasion.isActive())){
    showTooltip('🚫 Poderes de Destruição bloqueados durante a invasão!');
    return;
  }
  // Encerra qualquer poder ativo anterior
  // FIX: NÃO reseta _fusionLaserActive aqui — ele é setado logo abaixo no case 'fusionlaser'.
  // Antes, era resetado para false no início e nunca chegava a true, travando renderFusionLaser().
  _activePower=null;
  if(id!=='dest-fusionlaser'){_fusionLaserActive=false;_fusionLaserPts=[];}
  if(_shrinkInterval){clearInterval(_shrinkInterval);_shrinkInterval=null;}
  if(_greyGooInterval){clearInterval(_greyGooInterval);_greyGooInterval=null;}
  // FIX: cancela míssil e devourer em voo se outro poder for escolhido no meio —
  // antes eles ficavam "fantasma" ativos e sumiam sem nunca aplicar seu efeito.
  if(id!=='dest-antimissile'){_missileObj=null;_missileTarget=null;}
  if(id!=='dest-planetdevourer'){_devourerActive=false;}
  if(id!=='dest-energydrain'&&_drainInterval){clearInterval(_drainInterval);_drainInterval=null;}

  // FIX: identificação do astro-alvo — o painel de destruição abre sem exigir que
  // o objeto já esteja em selectedObj. Aceita qualquer tipo, não só planetas.
  // Se não houver seleção, orienta o jogador a tocar num astro.
  const _requireTarget=(types=null)=>{
    if(!selectedObj||selectedObj.dead)return null;
    if(types&&!types.includes(selectedObj.type))return null;
    return selectedObj;
  };

  switch(id){

    // ── 1. LASER DE FUSÃO ESTELAR ─────────────────────────────────
    case 'dest-fusionlaser':{
      // FIX: _fusionLaserActive deve ser true para renderFusionLaser() funcionar.
      // O bug era que era setado false no início do applyDestruction e nunca restaurado.
      _activePower='fusionlaser';
      _fusionLaserActive=true;
      _fusionLaserPts=[];
      showTooltip('🔴 Arraste o dedo no canvas para cortar com o laser!');
      break;
    }

    // ── 2. SONDA SUGADORA DE ENERGIA ─────────────────────────────
    case 'dest-energydrain':{
      const tgt=_requireTarget();
      if(!tgt)return showTooltip('🛸 Toque em qualquer astro para selecionar!');
      _activePower='energydrain';
      showTooltip(`🛸 Sonda sugando energia de ${tgt.name}...`);
      const origColor=tgt.color||'#4a9eff';
      const origRadius=tgt.radius;
      const origMass=tgt.mass;
      let drainStep=0;
      if(_drainInterval)clearInterval(_drainInterval);
      _drainInterval=setInterval(()=>{
        if(!tgt||tgt.dead||_activePower!=='energydrain'){clearInterval(_drainInterval);_drainInterval=null;return;}
        drainStep++;
        const grayFrac=Math.min(drainStep/40,1);
        tgt.color=`hsl(0,${Math.round((1-grayFrac)*60)}%,${Math.round(35+grayFrac*15)}%)`;
        tgt.radius=Math.max(origRadius*(1-grayFrac*0.6),3);
        tgt.mass=Math.max(origMass*(1-grayFrac*0.7),1);
        for(let i=0;i<3;i++){
          particles.push({x:tgt.x+rand(-tgt.radius,tgt.radius),y:tgt.y+rand(-tgt.radius,tgt.radius),
            vx:rand(-1,1),vy:rand(-4,-1),r:rand(1,2.5),alpha:0.8,
            color:`hsl(${rand(190,240)},80%,70%)`});
        }
        if(drainStep>=40){
          clearInterval(_drainInterval);_drainInterval=null;
          tgt.color='#808080';tgt.radius=Math.max(origRadius*0.4,3);tgt.mass=1;
          if(tgt.bioLevel!==undefined)tgt.bioLevel=0;
          triggerFlash(0.2,300);
          showTooltip(`🪨 ${tgt.name} virou uma rocha cinza morta.`);
        }
      },80);
      break;
    }

    // ── 3. MÍSSIL ANTIMATÉRIA ────────────────────────────────────
    case 'dest-antimissile':{
      const tgt=_requireTarget();
      if(!tgt)return showTooltip('🚀 Toque em qualquer astro para selecionar!');
      _missileTarget=tgt;
      const _mSpawnX=cam.x-canvas.width/cam.zoom*0.6,_mSpawnY=cam.y;
      // FIX: velocidade fixa (120u/s) fazia o míssil levar dezenas de segundos
      // para cruzar a tela em zoom out (spawn escala com canvas.width/cam.zoom,
      // mas a velocidade não escalava junto) — parecia travado/não funcionar.
      // Agora a velocidade é calculada para cruzar a distância inicial em ~1.1s.
      const _mDist=Math.hypot(tgt.x-_mSpawnX,tgt.y-_mSpawnY);
      _missileObj={x:_mSpawnX,y:_mSpawnY,_ang:0,_speed:Math.max(_mDist/1.1,120)};
      _activePower='missile';
      showTooltip('🚀 Míssil de antimatéria lançado!');
      break;
    }

    // ── 4. ROBÔ DEVORADOR ─────────────────────────────────────────
    case 'dest-planetdevourer':{
      _devourerActive=true;
      _devourerTimer=0;
      _devourerX=cam.x-canvas.width/cam.zoom*0.6;
      _devourerY=cam.y+rand(-80,80);
      _activePower='devourer';
      showTooltip('🤖 Robô Devorador invadindo o sistema!');
      break;
    }

    // ── 5. RAIO ENCOLHEDOR ───────────────────────────────────────
    case 'dest-shrinkray':{
      // FIX: aceita estrela e lua também, não só planeta
      const tgt=_requireTarget(['planet','star','moon','meteor','comet','protostar','cepheid','pulsar','neutronstar']);
      if(!tgt)return showTooltip('💙 Toque num planeta, estrela ou lua primeiro!');
      const origR=tgt.radius;
      const origM=tgt.mass;
      let steps=0;
      const maxSteps=50;
      _shrinkTarget=tgt;
      showTooltip(`💙 Raio encolhendo ${tgt.name}...`);
      _shrinkInterval=setInterval(()=>{
        if(!tgt||tgt.dead){clearInterval(_shrinkInterval);_shrinkInterval=null;return;}
        steps++;
        const frac=steps/maxSteps;
        tgt.radius=Math.max(origR*(1-frac*0.85),1.5);
        tgt.mass=Math.max(origM*(1-frac*0.9),0.1);
        for(let i=0;i<4;i++){
          const ang=rand(Math.PI*0.85,Math.PI*1.15);
          particles.push({x:tgt.x+rand(-3,3),y:tgt.y-tgt.radius*2,
            vx:Math.cos(ang)*rand(0.5,2.5),vy:rand(1,4),
            r:rand(1,3),alpha:0.9,color:`rgba(80,160,255,0.9)`});
        }
        if(frac>0.5){
          objects.forEach(o=>{
            if(o.parent===tgt&&(o.type==='moon')){
              o.parent=null;
              const escapeSpd=rand(2,6);
              const escapeAng=rand(0,Math.PI*2);
              o.vx=Math.cos(escapeAng)*escapeSpd;
              o.vy=Math.sin(escapeAng)*escapeSpd;
            }
          });
        }
        if(steps>=maxSteps){
          clearInterval(_shrinkInterval);_shrinkInterval=null;
          tgt.radius=Math.max(origR*0.15,1.5);tgt.mass=0.1;
          // FIX: antes setava tgt.type='comet', mas o objeto continua sendo
          // uma instância de Planet/Star/etc — draw() renderizava com o visual
          // antigo em miniatura, não como cometa de verdade (sem trailPts).
          // Agora vira "asteroide" com cor cinza, condizente com o visual real.
          tgt.color='#8a8a8a';
          triggerFlash(0.3,250);
          showTooltip(`💙 ${tgt.name} encolheu — gravidade zero, luas voando!`);
        }
      },80);
      break;
    }

    // ── 6. NANOBOTS CINZENTOS ─────────────────────────────────────
    case 'dest-greygoo':{
      // FIX: aceita qualquer tipo de astro
      const tgt=_requireTarget();
      if(!tgt)return showTooltip('🌫️ Toque em qualquer astro para selecionar!');
      let gooStep=0;
      const gooSteps=60;
      showTooltip(`🌫️ Nanobots infectando ${tgt.name}...`);
      _greyGooInterval=setInterval(()=>{
        if(!tgt||tgt.dead){clearInterval(_greyGooInterval);_greyGooInterval=null;return;}
        gooStep++;
        const frac=gooStep/gooSteps;
        tgt.radius=Math.max(tgt.radius-0.3,0.5);
        tgt.mass=Math.max(tgt.mass*0.985,0.1);
        tgt.color=`hsl(0,${Math.round(Math.max(0,30-frac*30))}%,${Math.round(35+frac*5)}%)`;
        for(let i=0;i<5;i++){
          const ang=rand(0,Math.PI*2),dist2=rand(0,tgt.radius*1.5);
          particles.push({x:tgt.x+Math.cos(ang)*dist2,y:tgt.y+Math.sin(ang)*dist2,
            vx:rand(-1,1),vy:rand(-1,1),
            r:rand(0.8,2.5),alpha:rand(0.4,0.7),
            color:`hsl(0,0%,${rand(35,65)}%)`});
        }
        if(gooStep>=gooSteps||tgt.radius<=0.5){
          clearInterval(_greyGooInterval);_greyGooInterval=null;
          tgt.dead=true;
          triggerFlash(0.15,200);
          showTooltip(`🌫️ ${tgt.name} consumido pelos nanobots!`);
        }
      },60);
      break;
    }

    // ── 7. CANHÃO ESTELAR ─────────────────────────────────────────
    case 'dest-stellarcannon':{
      // FIX: aceita estrela também
      const tgt=_requireTarget(['planet','star','moon','protostar','cepheid','meteor','comet']);
      if(!tgt)return showTooltip('⚡ Toque num planeta ou estrela primeiro!');
      const ox=tgt.x,oy=tgt.y;
      const srcX=cam.x+canvas.width/cam.zoom*0.55;
      const srcY=cam.y-canvas.height/cam.zoom*0.55;
      showTooltip('⚡ Canhão estelar disparando...');
      let charge=0;
      const chargeInterval=setInterval(()=>{
        charge+=0.06;
        const ss=worldToScreen(srcX,srcY);
        const ts2=worldToScreen(tgt.x,tgt.y);
        ctx.save();
        const lg=ctx.createLinearGradient(ss.x,ss.y,ts2.x,ts2.y);
        lg.addColorStop(0,'rgba(255,255,100,0.9)');
        lg.addColorStop(0.4+Math.random()*0.2,'rgba(255,180,50,0.6)');
        lg.addColorStop(1,'rgba(255,255,255,0)');
        ctx.beginPath();ctx.moveTo(ss.x,ss.y);
        const mx=ss.x+(ts2.x-ss.x)*Math.min(charge,1),my=ss.y+(ts2.y-ss.y)*Math.min(charge,1);
        ctx.lineTo(mx,my);
        ctx.strokeStyle=lg;ctx.lineWidth=(6+Math.random()*4)*cam.zoom;ctx.lineCap='round';ctx.stroke();
        ctx.restore();
        if(charge>=1){clearInterval(chargeInterval);}
      },30);
      setTimeout(()=>{
        if(tgt.dead)return;
        tgt.radius*=2.5;tgt.mass=tgt.radius*6;
        for(let i=0;i<40;i++){const a=rand(0,Math.PI*2);particles.push({x:ox,y:oy,vx:Math.cos(a)*rand(2,7),vy:Math.sin(a)*rand(2,7),r:rand(2,6),alpha:1,color:`hsl(${rand(20,55)},100%,${rand(60,90)}%)`});}
        triggerFlash(0.5,200);
        showTooltip('💥 Impacto! Astro inflando...');
        setTimeout(()=>{
          if(tgt.dead)return;
          const pieces=rand(5,10)|0;
          for(let i=0;i<pieces;i++){
            const a=rand(0,Math.PI*2),spd=rand(4,14);
            const m=new Meteor(ox+Math.cos(a)*tgt.radius*.5,oy+Math.sin(a)*tgt.radius*.5);
            m.vx=Math.cos(a)*spd;m.vy=Math.sin(a)*spd;m.radius=rand(2,5);m.mass=m.radius*1.5;
            pendingObjects.push(m);
          }
          tgt.dead=true;selectedObj=null;
          spawnExplosion(ox,oy,1.5,false);
          showTooltip('💥 Astro estilhaçado em fragmentos!');
        },600);
      },900);
      break;
    }

    // ── 8. RASGO TEMPORAL ────────────────────────────────────────
    // FIX: substitui o Big Bang Local por uma função completamente nova.
    // O Rasgo Temporal congela o tempo ao redor do astro e o desintegra em espiral.
    case 'dest-timewarp':{
      const tgt=_requireTarget();
      if(!tgt)return showTooltip('⏳ Toque em qualquer astro para selecionar!');
      const ox=tgt.x,oy=tgt.y;
      tgt.fixed=true;tgt.vx=0;tgt.vy=0;
      showTooltip(`⏳ Rasgo temporal consumindo ${tgt.name}...`);
      // Anel de distorção crescente
      for(let i=0;i<5;i++)particles.push({x:ox,y:oy,vx:0,vy:0,r:(i+1)*tgt.radius*.8,alpha:.7,color:'rgba(160,80,255,1)',ring:true,grow:6});
      let warpStep=0;const warpMax=80;
      const warpInterval=setInterval(()=>{
        if(!tgt||tgt.dead){clearInterval(warpInterval);return;}
        warpStep++;
        const frac=warpStep/warpMax;
        // Espiral para dentro — reduz e rotaciona
        tgt.radius=Math.max(tgt.radius*(1-0.025),0.5);
        tgt.mass=Math.max(tgt.mass*0.97,0.1);
        // Partículas em espiral coloridas
        const spiralA=frac*Math.PI*16;
        const spiralR=tgt.radius*2.5*(1-frac);
        for(let i=0;i<4;i++){
          const a=spiralA+i*(Math.PI/2);
          particles.push({
            x:tgt.x+Math.cos(a)*spiralR,y:tgt.y+Math.sin(a)*spiralR,
            vx:-Math.sin(a)*rand(0.5,2.5),vy:Math.cos(a)*rand(0.5,2.5),
            r:rand(1,3),alpha:0.85,
            color:`hsl(${~~(260+frac*80)},90%,${~~(60+frac*30)}%)`
          });
        }
        // Distorção visual — anel pulsante
        if(warpStep%12===0)particles.push({x:ox,y:oy,vx:0,vy:0,r:tgt.radius*3,alpha:.55,color:'rgba(180,100,255,1)',ring:true,grow:8});
        if(warpStep>=warpMax||tgt.radius<=0.5){
          clearInterval(warpInterval);
          // Implosão final — flash branco + fragmentos roxos
          for(let i=0;i<60;i++){const a=rand(0,Math.PI*2),spd=rand(1,8);particles.push({x:ox,y:oy,vx:Math.cos(a)*spd,vy:Math.sin(a)*spd,r:rand(1.5,4),alpha:1,color:`hsl(${rand(250,310)},100%,${rand(65,90)}%)`});}
          for(let i=0;i<3;i++)particles.push({x:ox,y:oy,vx:0,vy:0,r:(i+1)*22,alpha:.8,color:'rgba(160,80,255,1)',ring:true,grow:14});
          triggerFlash(0.55,400);
          tgt.dead=true;selectedObj=null;
          showTooltip('⏳ Rasgo temporal — matéria desintegrada!');
        }
      },60);
      break;
    }

    // ── 9. COLAPSO GRAVITACIONAL ─────────────────────────────────
    case 'dest-gravitycollapse':{
      const cx=cam.x,cy=cam.y;
      showTooltip('🌑 Colapso gravitacional — tudo sendo comprimido!');
      // Congela todos os astros imunes não fixos
      const allMoving=objects.filter(o=>!o.dead&&!o.immune);
      // Fase 1: puxa tudo para o centro por 3s
      let colStep=0;
      const colInterval=setInterval(()=>{
        colStep++;
        allMoving.forEach(o=>{
          if(o.dead)return;
          const dx=cx-o.x,dy=cy-o.y;
          const d=Math.max(1,Math.hypot(dx,dy));
          const f=Math.min(120,8000/d); // força aumenta conforme aproxima
          o.vx+=dx/d*f*(1/60);
          o.vy+=dy/d*f*(1/60);
          if(o.type==='planet'||o.type==='moon')o.parent=null;
          // Estrias de compressão
          if(Math.random()<0.12)particles.push({x:o.x,y:o.y,vx:dx/d*rand(1,4),vy:dy/d*rand(1,4),r:rand(1,3),alpha:.8,color:'rgba(180,220,255,.9)'});
        });
        if(colStep>=180){ // 3s @ 60fps
          clearInterval(colInterval);
          // Fase 2: explosão de colisão no centro
          for(let i=0;i<200;i++){const a=rand(0,Math.PI*2),spd=rand(4,22);particles.push({x:cx,y:cy,vx:Math.cos(a)*spd,vy:Math.sin(a)*spd,r:rand(2,9),alpha:1,color:`hsl(${rand(0,60)},100%,${rand(60,92)}%)`});}
          for(let i=0;i<7;i++)particles.push({x:cx,y:cy,vx:0,vy:0,r:(i+1)*45,alpha:.9,color:'rgba(255,210,80,1)',ring:true,grow:20});
          triggerFlash(0.9,600);
          // Destrói tudo dentro de 300u do centro
          objects.forEach(o=>{
            if(o.immune||o.dead)return;
            if(Math.hypot(o.x-cx,o.y-cy)<300){spawnAbsorbParticles(o);o.dead=true;}
          });
          selectedObj=null;
          showTooltip('🌑 Colapso total — matéria aniquilada no centro!');
        }
      },1000/60);
      break;
    }

    // ── 10. EJEÇÃO DE COROA SOLAR ─────────────────────────────────
    case 'dest-solarcorona':{
      // Requer estrela, cefeida ou pulsar
      const tgt=_requireTarget(['star','cepheid','pulsar','magnetar','protostar']);
      if(!tgt)return showTooltip('☀️ Toque numa estrela ou cefeida primeiro!');
      const ox=tgt.x,oy=tgt.y;
      showTooltip(`☀️ ${tgt.name} ejetando corona solar massiva!`);
      // Flash solar imediato
      triggerFlash(0.65,350);
      // Expande raio visual temporariamente
      const origR=tgt.radius;
      tgt.radius*=3.5;
      setTimeout(()=>{if(!tgt.dead)tgt.radius=origR;},600);
      // Onda de plasma em 3 pulsos
      for(let wave=0;wave<3;wave++){
        setTimeout(()=>{
          const waveR=origR*(4+wave*3);
          for(let i=0;i<5;i++)particles.push({x:ox,y:oy,vx:0,vy:0,r:waveR+(i*origR*.8),alpha:.8-i*.1,color:`rgba(255,${~~(180-wave*40)},${~~(40-wave*10)},1)`,ring:true,grow:15+wave*5});
          // Plasma que destrói objetos no raio de alcance
          const blastR=origR*(12+wave*6);
          objects.forEach(o=>{
            if(o===tgt||o.dead||o.immune)return;
            const d=Math.hypot(o.x-ox,o.y-oy);
            if(d<blastR){
              // Pequenos destruídos; grandes sofrem dano massivo
              if(o.type==='planet'||o.type==='moon'||o.type==='meteor'||o.type==='comet'){
                spawnAbsorbParticles(o);o.dead=true;
              } else {
                o.radius=Math.max(o.radius*0.6,3);
                o.mass=o.radius*3;
                const nx=(o.x-ox)/Math.max(d,1),ny=(o.y-oy)/Math.max(d,1);
                o.vx+=nx*rand(8,18);o.vy+=ny*rand(8,18);
              }
            }
            // Emite partículas de plasma em direção a cada objeto
            else if(d<blastR*2){
              for(let k=0;k<3;k++){
                const nx2=(o.x-ox)/d,ny2=(o.y-oy)/d;
                particles.push({x:ox+nx2*origR*2,y:oy+ny2*origR*2,vx:nx2*rand(6,14),vy:ny2*rand(6,14),r:rand(2,5),alpha:.9,color:`hsl(${rand(10,45)},100%,${rand(60,85)}%)`});
              }
            }
          });
        },wave*500);
      }
      showTooltip('☀️ Plasma varrendo o sistema!');
      break;
    }

    // ── 11. CONSUMO DO VAZIO ─────────────────────────────────────
    case 'dest-voidconsume':{
      const cx=cam.x,cy=cam.y;
      showTooltip('🕳️ Vazio se expandindo — toda matéria será consumida!');
      let voidR=0;
      let voidStep=0;
      const voidInterval=setInterval(()=>{
        voidStep++;
        voidR+=2.8; // cresce ~2.8u por frame
        // Anel de borda do vazio — visual
        particles.push({x:cx,y:cy,vx:0,vy:0,r:voidR,alpha:.55,color:'rgba(40,0,80,1)',ring:true,grow:2.8});
        // Partículas de "rasgo" ao longo da borda
        for(let i=0;i<3;i++){
          const a=rand(0,Math.PI*2);
          particles.push({x:cx+Math.cos(a)*voidR,y:cy+Math.sin(a)*voidR,
            vx:rand(-1.5,1.5),vy:rand(-1.5,1.5),r:rand(1.5,4),alpha:.8,
            color:`hsl(${rand(250,300)},80%,${rand(30,55)}%)`});
        }
        // Destrói tudo dentro do vazio
        objects.forEach(o=>{
          if(o.dead||o.immune)return;
          if(Math.hypot(o.x-cx,o.y-cy)<voidR){
            // Efeito de desaparecimento — sem flash, silencioso
            for(let k=0;k<8;k++){const a=rand(0,Math.PI*2);particles.push({x:o.x,y:o.y,vx:Math.cos(a)*rand(0.5,3),vy:Math.sin(a)*rand(0.5,3),r:rand(1,3),alpha:.7,color:'rgba(80,0,160,.9)'});}
            o.dead=true;
          }
        });
        // Para quando cobrir toda a tela (~2x diagonal)
        const screenDiag=Math.hypot(canvas.width,canvas.height)/cam.zoom;
        if(voidR>screenDiag*0.9||voidStep>400){
          clearInterval(voidInterval);
          selectedObj=null;
          showTooltip('🕳️ Vazio dissipou — universo consumido.');
        }
      },1000/60);
      break;
    }

    // ── 12. GOLPE QUÂNTICO ───────────────────────────────────────
    case 'dest-quantumstrike':{
      showTooltip('⚛️ Colapso quântico — superposição colapsando!');
      let pass=0;
      // 3 passes com intervalo crescente — chance de 50% por astro em cada pass
      const doPass=()=>{
        pass++;
        const targets=objects.filter(o=>!o.dead&&!o.immune);
        let destroyed=0;
        targets.forEach(o=>{
          if(Math.random()<0.5){ // 50% de chance
            // Flash branco no ponto do astro antes de destruir
            const sx2=worldToScreen(o.x,o.y).x,sy2=worldToScreen(o.x,o.y).y;
            for(let i=0;i<25;i++){const a=rand(0,Math.PI*2);particles.push({x:o.x,y:o.y,vx:Math.cos(a)*rand(2,10),vy:Math.sin(a)*rand(2,10),r:rand(1.5,5),alpha:1,color:`hsl(${rand(180,280)},100%,${rand(70,95)}%)`});}
            particles.push({x:o.x,y:o.y,vx:0,vy:0,r:o.radius*2.5,alpha:.85,color:'rgba(180,255,255,1)',ring:true,grow:10});
            spawnAbsorbParticles(o);o.dead=true;destroyed++;
          }
        });
        triggerFlash(0.35+pass*0.1,220);
        if(pass<3){
          setTimeout(doPass,900+pass*300); // passes ficam mais espaçados
          showTooltip(`⚛️ Pass ${pass}/3 — ${destroyed} astros colapsados!`);
        } else {
          selectedObj=null;
          showTooltip(`⚛️ Golpe Quântico completo — ${destroyed} destruídos no pass final!`);
        }
      };
      setTimeout(doPass,300);
      break;
    }
  }
}


function refreshDestructionPanel(){
  const list=document.getElementById('dest-btn-list');
  if(!list)return;
  list.innerHTML='';
  list.style.cssText='display:flex;flex-direction:column;align-items:center;gap:5px;width:100%';
  DESTRUCTION_UNLOCKS.forEach(d=>{
    const locked=!isRankUnlocked(d.rank);
    const btn=document.createElement('button');
    btn.className='dest-btn';
    btn.setAttribute('data-locked',locked);
    btn.setAttribute('data-id',d.id);
    btn.innerHTML=d.icon+(locked?`<span class="dest-rank-lbl">R${d.rank}</span>`:'');
    btn.addEventListener('click',()=>openDestInfo(d,locked));
    list.appendChild(btn);
  });
}

