  const _alienActive=typeof AlienInvasion!=='undefined'&&AlienInvasion.isActive();
  const _marsActive=typeof MarsianInvasion!=='undefined'&&MarsianInvasion.isActive();
  const _reptActive=typeof ReptilianInvasion!=='undefined'&&ReptilianInvasion.isActive();
