function triggerPulsarCollapse(obj){
  if(!obj||obj.dead)return;
  const ox=obj.x,oy=obj.y,baseR=obj.radius;
  // Phase 1 — pulse flash and shrink
  for(let i=0;i<40;i++){const a=rand(0,Math.PI*2);particles.push({x:ox,y:oy,vx:Math.cos(a)*rand(1,6),vy:Math.sin(a)*rand(1,6),r:rand(1,4),alpha:1,color:'#7be8ff'});}
  obj.radius=baseR*1.8;obj.mass=obj.radius*20;
  triggerFlash(.5,250);
  setTimeout(()=>{
    if(obj.dead)return;
    obj.dead=true;
    for(let i=0;i<80;i++){const a=rand(0,Math.PI*2),spd=rand(2,10);particles.push({x:ox,y:oy,vx:Math.cos(a)*spd,vy:Math.sin(a)*spd,r:rand(1.5,5),alpha:1,color:`hsl(${rand(180,240)},100%,80%)`});}
    for(let i=0;i<3;i++)particles.push({x:ox,y:oy,vx:0,vy:0,r:(i+1)*20,alpha:.8,color:'rgba(100,220,255,1)',ring:true,grow:10});
    triggerFlash(.6,350);
    // 60% NeutronStar, 40% PulsarPlanet
    const roll=Math.random();
    if(roll<.6){
      const ns=new NeutronStar(ox,oy);ns.vx=rand(-1.5,1.5);ns.vy=rand(-1.5,1.5);
      if(obj._autoSpawn) ns._autoSpawn=true;
      pendingObjects.push(ns);showTooltip('🌟 Pulsar colapsou — Estrela de Nêutrons!');
    } else {
      const pp=new PulsarPlanet(ox,oy);pp.vx=rand(-2,2);pp.vy=rand(-2,2);
      if(obj._autoSpawn) pp._autoSpawn=true;
      pendingObjects.push(pp);showTooltip('🪐 Planeta de Pulsar exótico formado!');
    }
  },900);
}

