function triggerBlackHoleExplosion(obj){
  if(!obj||obj.dead)return;
  obj._bhExploding=true;
  obj.fixed=true; // freeze in place during event
  const baseR=obj.radius;
  const ox=obj.x,oy=obj.y;
  showTooltip('💀 Buraco Negro colapsando...');

  // Phase 1 (0–8s): slowly shrink
  const shrinkInterval=setInterval(()=>{
    if(!obj||obj.dead){clearInterval(shrinkInterval);return;}
    obj.radius=Math.max(0.5,obj.radius-baseR*0.018);
    obj.mass=obj.radius*60;
    obj.pullRange=obj.radius*9;
    // Emit subtle dark particles while shrinking
    if(Math.random()<0.35){
      const ang=rand(0,Math.PI*2);
      particles.push({x:ox,y:oy,vx:Math.cos(ang)*rand(0.5,2),vy:Math.sin(ang)*rand(0.5,2),r:rand(1,2.5),alpha:0.7,color:'rgba(180,80,255,0.8)'});
    }
  },80);

  // Phase 2 (8s): final collapse flash + micro-dot
  setTimeout(()=>{
    clearInterval(shrinkInterval);
    if(!obj||obj.dead)return;
    obj.radius=0.3;obj.mass=1;obj.pullRange=0;
    triggerFlash(0.5,200);
    for(let i=0;i<30;i++){const a=rand(0,Math.PI*2);particles.push({x:ox,y:oy,vx:Math.cos(a)*rand(1,4),vy:Math.sin(a)*rand(1,4),r:rand(1,3),alpha:1,color:'rgba(200,100,255,1)'});}
    showTooltip('💥 Singularidade — explosão iminente!');
  },8000);

  // Phase 3 (9s): MASSIVE smoke + particle burst covering entire screen
  setTimeout(()=>{
    if(!obj||obj.dead)return;
    // Giant smoke cloud of particles covering screen
    const W=canvas.width/cam.zoom,H=canvas.height/cam.zoom;
    for(let i=0;i<320;i++){
      const ang=rand(0,Math.PI*2);
      const spd=rand(3,W*.35);
      const hue=Math.random()<0.5?rand(0,30):rand(270,320); // red-orange or magenta
      particles.push({x:ox,y:oy,vx:Math.cos(ang)*spd,vy:Math.sin(ang)*spd,
        r:rand(4,18),alpha:rand(0.6,0.95),
        color:`hsl(${hue},100%,${rand(55,80)}%)`});
    }
    // Smoke puffs (big slow ones)
    for(let i=0;i<80;i++){
      const ang=rand(0,Math.PI*2);const spd=rand(1,W*.18);
      particles.push({x:ox,y:oy,vx:Math.cos(ang)*spd,vy:Math.sin(ang)*spd,
        r:rand(14,40),alpha:rand(0.25,0.55),color:'rgba(40,0,60,0.7)'});
    }
    triggerFlash(0.92,800);
    showTooltip('☢️ Raios Gama — TUDO ESTÁ SENDO EVAPORADO!');
  },9000);

  // Phase 4 (10–18s): gamma ray beams + evaporate ALL objects progressively
  const NUM_BEAMS=12;
  const beamAngles=Array.from({length:NUM_BEAMS},(_,i)=>i*(Math.PI*2/NUM_BEAMS)+rand(-0.2,0.2));
  let beamFrame=0;
  const beamInterval=setInterval(()=>{
    beamFrame++;
    // Gamma ray beam particles along each direction
    beamAngles.forEach(ang=>{
      const dist=beamFrame*8;
      const bx=ox+Math.cos(ang)*dist,by=oy+Math.sin(ang)*dist;
      if(Math.random()<0.7){
        particles.push({x:bx+rand(-8,8),y:by+rand(-8,8),
          vx:Math.cos(ang)*rand(3,9)+rand(-1,1),vy:Math.sin(ang)*rand(3,9)+rand(-1,1),
          r:rand(2,7),alpha:0.9,
          color:`hsl(${rand(50,90)},100%,${rand(70,95)}%)`}); // yellow-white gamma rays
      }
    });
    if(beamFrame>100)clearInterval(beamInterval);
  },80);

  // Evaporate everything progressively over 8 seconds (10–18s)
  setTimeout(()=>{
    const allObj=[...objects].filter(o=>o!==obj&&!o.dead);
    allObj.forEach((o,idx)=>{
      setTimeout(()=>{
        if(o.dead)return;
        // Evaporation particles
        for(let i=0;i<20;i++){
          const a=rand(0,Math.PI*2);
          particles.push({x:o.x,y:o.y,vx:Math.cos(a)*rand(1,5),vy:Math.sin(a)*rand(1,5),
            r:rand(1.5,5),alpha:0.95,
            color:`hsl(${rand(40,80)},100%,${rand(65,90)}%)`});
        }
        o.dead=true;
      }, idx*(8000/Math.max(allObj.length,1)));
    });
  },10000);

  // Phase 5 (20s): BH dies, White Hole is born
  setTimeout(()=>{
    if(obj)obj.dead=true;
    // Final mega flash
    triggerFlash(1.0,1200);
    for(let i=0;i<200;i++){const a=rand(0,Math.PI*2),spd=rand(5,30);particles.push({x:ox,y:oy,vx:Math.cos(a)*spd,vy:Math.sin(a)*spd,r:rand(2,9),alpha:1,color:`hsl(${rand(40,100)},100%,${rand(70,95)}%)`});}
    for(let i=0;i<7;i++)particles.push({x:ox,y:oy,vx:0,vy:0,r:(i+1)*55,alpha:0.9,color:'rgba(255,255,200,1)',ring:true,grow:25});
    // Spawn white hole
    setTimeout(()=>{
      const wh=new WhiteHole(ox,oy);
      wh.radius=rand(14,20);wh.mass=wh.radius*45;
      if(obj&&obj._autoSpawn) wh._autoSpawn=true;
      pendingObjects.push(wh);
      showTooltip('🌟 Buraco Branco nasceu das cinzas!');
    },800);
  },20000);
}

