function triggerWhSingularity(obj){
  if(!obj||obj.dead)return;
  obj.fixed=true;
  const baseR=obj.radius;
  showTooltip('🌀 Buraco Branco retraindo em singularidade...');

  // Slowly shrink over ~6 seconds down to 0.4 (sub-background-star size)
  const shrinkInterval=setInterval(()=>{
    if(!obj||obj.dead){clearInterval(shrinkInterval);return;}
    if(obj.radius>0.4){
      obj.radius=Math.max(0.4,obj.radius-baseR*0.012);
      obj.mass=Math.max(0,obj.mass-obj.mass*0.012);
      obj.pushRange=Math.max(0,(obj.pushRange||0)-obj.pushRange*0.012);
      // Emit fading light particles as it shrinks
      if(Math.random()<0.4){
        const ang=rand(0,Math.PI*2);
        particles.push({x:obj.x,y:obj.y,
          vx:Math.cos(ang)*rand(0.3,1.5),vy:Math.sin(ang)*rand(0.3,1.5),
          r:rand(0.8,2.5),alpha:0.6,color:'rgba(150,235,255,0.8)'});
      }
    } else {
      // Fully retracted — freeze it as a microscopic dot
      obj.radius=0.4;obj.mass=0;obj.pushRange=0;
      obj.emitTimer=-999999; // stop emitting particles
      clearInterval(shrinkInterval);
      showTooltip('🔵 Singularidade estável — Buraco Branco congelado.');
    }
  },80);
}
let touchStart={x:0,y:0},lastMovePos={x:0,y:0},touchStartTime=0;
let dragObj=null,dragPrevW=null,isPanning=false;
// FIX: _dragStartedMoving rastreia se o dedo REALMENTE arrastou (>8px).
// Sem isso, qualquer toque em objeto não-fixed definia dragObj no onStart
// e o onEnd caia no branch de drag, nunca chegando no código de tap/info-panel.
let _dragStartedMoving=false;
// FIX: após criar um astro, bloqueia abertura do painel por 900ms
// para evitar que o tap de criação abra o painel do astro recém-criado.
let _lastCreationTime=0;
const modeBadge=document.getElementById('mode-badge');
// Hold-for-supernova state
let holdTimer=null,holdTarget=null;

function getScreenPos(e){
  const r=canvas.getBoundingClientRect();
  // FIX: touchend usa changedTouches; touches pode estar vazio no touchend
  const src=e.changedTouches?e.changedTouches[0]:e.touches?e.touches[0]:e;
  if(src)return{x:src.clientX-r.left,y:src.clientY-r.top};
  return{x:e.clientX-r.left,y:e.clientY-r.top};
}
function findObjAt(sx,sy,tol=18){
  // Tolerância extra para astros menores (mais difíceis de tocar em mobile)
  // e para astros grandes cujo visual excede o raio físico base
  const EXTRA_TOL={
    star:22,moon:28,comet:26,meteor:26,planet:20,cepheid:22,
    blackhole:18,galaxy:20,greatattractor:24,quasar:16,blazar:16,
    magnetar:18,pulsar:18,whitehole:16,wormhole:16,
  };
  for(let i=objects.length-1;i>=0;i--){
    const o=objects[i];
    if(o.dead)continue;
    const minHit=Math.max(o.sr(),16);
    const extraTol=(EXTRA_TOL[o.type]||0);
    if(Math.hypot(sx-o.sx(),sy-o.sy())<=minHit+tol+extraTol)return o;
  }
  return null;
}

// ─── Pacote Tecnológico: ancoragem por toque PRÓXIMO ao astro ────
// Esses tipos não precisam de toque EXATO sobre o astro — basta tocar
// perto dele (findObjAt já cuida da tolerância de toque em mobile).
// OBS: techLaboratory e techStation NÃO estão aqui — eles usam busca
// automática do astro válido mais próximo (ver _findNearestHostFor),
// já que não são megaestruturas e o jogador não precisa mirar nelas.
const TECH_ANCHOR_TOOLS=['techDysonSphere','techDysonSwarm','techShkadovThruster',
  'techMatrioshkaBrain','techMassExtractor','techAldersonDisk','techNicollDyson',
  'techSpaceElevator'];
const TECH_ELEVATOR_HOST_TYPES=['planet','gasgiant','icegiant','superearth','minineptune',
  'dwarfplanet','lavaplt','oceanplt','desertplt','carbonplt','ironplt'];
function _techAnchorClassFor(tool){
  const map={
    techDysonSphere:DysonSphere, techDysonSwarm:DysonSwarm,
    techShkadovThruster:ShkadovThruster, techMatrioshkaBrain:MatrioshkaBrain,
    techMassExtractor:MassExtractor, techAldersonDisk:AldersonDisk,
    techNicollDyson:NicollDysonBeam, techSpaceElevator:SpaceElevator
  };
  return map[tool];
}
// ─── Busca automática de astro-alvo (Laboratório / Estação) ──────
// Diferente das megaestruturas, esses astros não exigem que o jogador
// toque perto de um alvo: ao criar, o jogo PROCURA sozinho o astro
// válido mais próximo do ponto tocado (em toda a tela/mundo) e ancora
// nele automaticamente.
const TECH_STATION_HOST_TYPES=TECH_ELEVATOR_HOST_TYPES; // planetas
function _findNearestHostFor(tool,wx,wy){
  const validTypes = tool==='techStation' ? TECH_STATION_HOST_TYPES : null; // Laboratório: qualquer astro massivo
  let best=null,bestD=Infinity;
  objects.forEach(o=>{
    if(o.dead)return;
    if(validTypes&&!validTypes.includes(o.type))return;
    if(!validTypes&&(o.mass===undefined||o.mass<=0))return; // Laboratório precisa de um astro com massa (não outra entidade solta)
    const d=Math.hypot(o.x-wx,o.y-wy);
    if(d<bestD){bestD=d;best=o;}
  });
  return best;
}
// Ancora a megaestrutura selecionada em hostObj (o toque foi PERTO dele,
// não precisa ter sido exatamente em cima)
function _tryAnchorTechStructure(hostObj){
  if(!sandboxMode||!hostObj||hostObj.dead)return;
  if(selectedTool==='techSpaceElevator'&&!TECH_ELEVATOR_HOST_TYPES.includes(hostObj.type)){
    showTooltip('🔧 Toque perto de um planeta para construir o Elevador Espacial.');
    return;
  }
  const Cls=_techAnchorClassFor(selectedTool);
  if(!Cls)return;
  // ── Limite de 1 Megaestrutura por astro-hospedeiro durante o combate
  // do Galaximy: se o astro já tem uma megaestrutura viva ancorada,
  // bloqueia a criação de uma segunda nele. ──
  if(hostObj._galxMegaOccupant&&!hostObj._galxMegaOccupant.dead){
    showTooltip('🚫 Este astro já possui uma Megaestrutura ancorada!');
    return;
  }
  // ── Limite justo (max+cooldown) por categoria Ataque/Defesa/Controle ──
  if(typeof GalaximyBoss!=='undefined'&&GalaximyBoss.isActive()&&window._galaximyAstroCaps){
    const _gCap=window._galaximyAstroCaps[selectedTool];
    if(_gCap){
      const _gName=TYPE_LABELS[selectedTool]||selectedTool;
      if(_gCap.cooldown>0){
        showTooltip(`🚫 ${_gName} em recarga! Aguarde ${Math.ceil(_gCap.cooldown)}s.`);
        return;
      }
      if(_gCap.used>=_gCap.max){
        showTooltip(`🚫 Limite de ${_gCap.max} ${_gName} já atingido! Aguardando recarga...`);
        return;
      }
    }
  }
  const inst=new Cls(hostObj.x,hostObj.y);
  inst.attachTo(hostObj);
  if(hostObj._galxHost!==undefined)hostObj._galxMegaOccupant=inst;
  objects.push(inst);
  if(typeof GalaximyBoss!=='undefined'&&GalaximyBoss.isActive()&&window._galaximyAstroCaps){
    const _gCap=window._galaximyAstroCaps[selectedTool];
    if(_gCap){
      _gCap.used++;
      if(_gCap.used>=_gCap.max)_gCap.cooldown=_gCap.cooldownTime;
      _refreshGalaximyAstroCounterUI(selectedTool,_gCap);
    }
  }
  _techCancelAnchor();
  showTooltip(`⚙️ ${TYPE_LABELS[selectedTool]} ancorada em ${hostObj.name||TYPE_LABELS[hostObj.type]}!`);
  _lastCreationTime=Date.now();
}

canvas.addEventListener('mousedown',onStart,{passive:false});
canvas.addEventListener('touchstart',onStart,{passive:false});
canvas.addEventListener('mousemove',onMove,{passive:false});
canvas.addEventListener('touchmove',onMove,{passive:false});
canvas.addEventListener('mouseup',onEnd);
canvas.addEventListener('touchend',onEnd);

function onStart(e){
  if(e.touches&&e.touches.length>1)return;
  e.preventDefault();
  const pos=getScreenPos(e);touchStart=pos;lastMovePos=pos;touchStartTime=Date.now();
  isPanning=false;dragObj=null;dragPrevW=null;_dragStartedMoving=false;

  // Fusion laser — start trail
  if(_activePower==='fusionlaser'){
    // FIX #4a: _fusionLaserActive DEVE ser true para renderFusionLaser() desenhar.
    // Antes só era setado em applyDestruction mas podia ser perdido entre frames.
    _fusionLaserActive=true;
    _fusionLaserPts=[screenToWorld(pos.x,pos.y)];
    return;
  }
  // Cancel any running hold timer
  clearTimeout(holdTimer);holdTimer=null;holdTarget=null;
  if(selectedTool==='pan'){isPanning=true;canvas.style.cursor='grabbing';return;}
  if(selectedTool==='move'){
    dragObj=findObjAt(pos.x,pos.y,18);
    if(dragObj){dragPrevW={x:dragObj.x,y:dragObj.y};canvas.style.cursor='grabbing';}
    return;
  }
  const hit=findObjAt(pos.x,pos.y,12);
  // 5-second hold: star/cepheid → supernova | pulsar → collapse | magnetar → catastrophe | blackhole → explosion | whitehole → singularity
  if(hit&&!hit.dead){
    const t=hit.type;
    if(t==='star'||t==='cepheid'||t==='pulsar'||t==='magnetar'||t==='blackhole'||t==='whitehole'){
      holdTarget=hit;
      holdTimer=setTimeout(()=>{
        if(holdTarget&&!holdTarget.dead){
          const ht=holdTarget.type;
          if(ht==='star'||ht==='cepheid') openSnovaModal(holdTarget);
          else if(ht==='pulsar') openPulsarCollapseModal(holdTarget);
          else if(ht==='magnetar') openMagnetarCatModal(holdTarget);
          else if(ht==='blackhole') openBhExplodeModal(holdTarget);
          else if(ht==='whitehole') openWhSingularityModal(holdTarget);
        }
        holdTimer=null;holdTarget=null;
      },5000);
    }
  }
  // FIX: NÃO define dragObj aqui. Armazena apenas o candidato a drag.
  // Só vira drag real no onMove quando o dedo se move >8px.
  // Isso impede que onEnd caia no branch de drag em taps normais.
  // GLOBAL: só permite drag se o botão Mover estiver ativo.
  if(selectedTool==='move'&&hit&&!hit.fixed){
    dragObj=hit;
    dragPrevW={x:hit.x,y:hit.y};
    // _dragStartedMoving=false já foi resetado acima
  }
}
function onMove(e){
  if(e.touches&&e.touches.length>1)return;
  e.preventDefault();
  const pos=getScreenPos(e);const dx=pos.x-lastMovePos.x,dy=pos.y-lastMovePos.y;

  // Fusion laser — extend trail
  if(_activePower==='fusionlaser'&&_fusionLaserPts.length>0){
    const w=screenToWorld(pos.x,pos.y);
    _fusionLaserPts.push(w);
    if(_fusionLaserPts.length>80)_fusionLaserPts.shift();
    // Damage any object under the laser
    objects.forEach(o=>{
      if(o.dead||o.immune)return;
      const s=worldToScreen(o.x,o.y);
      if(Math.hypot(s.x-pos.x,s.y-pos.y)<o.sr()+8){
        o.radius=Math.max(o.radius-0.4,0.5);
        o.mass=Math.max(o.mass*0.99,0.1);
        // Fire particles at hit point
        for(let i=0;i<3;i++)particles.push({x:o.x,y:o.y,vx:rand(-3,3),vy:rand(-3,0),r:rand(1,3),alpha:0.9,color:`hsl(${rand(0,35)},100%,${rand(55,80)}%)`});
        if(o.radius<=0.5){o.dead=true;showTooltip(`🔴 Laser destruiu ${o.name}!`);}
      }
    });
    lastMovePos=pos;return;
  }
  const totalMoved=Math.hypot(pos.x-touchStart.x,pos.y-touchStart.y);
  // Cancel hold if moved too much
  if(holdTimer&&totalMoved>10){clearTimeout(holdTimer);holdTimer=null;holdTarget=null;}
  if(isPanning){cam.x-=dx/cam.zoom;cam.y-=dy/cam.zoom;lastMovePos=pos;return;}
  if(dragObj){
    // FIX: só marca como drag real depois de 8px de movimento.
    // Abaixo disso ainda pode ser um tap — não move o objeto.
    if(totalMoved>8){
      _dragStartedMoving=true;
      const w=screenToWorld(pos.x,pos.y);
      dragPrevW={x:dragObj.x,y:dragObj.y};
      if(dragObj.type==='planet'||dragObj.type==='moon')dragObj.parent=null;
      dragObj._movedByPlayer=true; // marca que este objeto foi lançado manualmente
      dragObj.x=w.x;dragObj.y=w.y;dragObj.vx=0;dragObj.vy=0;
      canvas.style.cursor='grabbing';
    }
  }
  lastMovePos=pos;
}
function onEnd(e){
  // Fusion laser — end trail
  if(_activePower==='fusionlaser'){
    // FIX #4b: limpa os pontos do trail E reseta _fusionLaserActive.
    // Antes só limpava _fusionLaserPts mas mantinha _fusionLaserActive=true,
    // causando renderFusionLaser() tentar desenhar com array vazio no próximo frame
    // e deixar o laser "fantasma" ativo até a próxima pincelada.
    _fusionLaserPts=[];
    _fusionLaserActive=false;
    _activePower=null; // FIX: sem isso o laser ficava "preso" como poder ativo para sempre,
                        // bloqueando toques normais no canvas após o primeiro uso.
    lastMovePos=touchStart;
  }
  canvas.style.cursor=selectedTool==='pan'?'grab':'crosshair';
  // Cancel hold if released before 5s
  clearTimeout(holdTimer);holdTimer=null;holdTarget=null;
  if(isPanning){isPanning=false;return;}

  // FIX: só trata como drag se o objeto REALMENTE se moveu (_dragStartedMoving).
  // Antes, qualquer toque em objeto não-fixed setava dragObj e bloqueava o tap.
  if(dragObj&&dragPrevW&&_dragStartedMoving){
    dragObj.vx=(dragObj.x-dragPrevW.x)*60*.2;
    dragObj.vy=(dragObj.y-dragPrevW.y)*60*.2;
    // Conta movimento real durante invasão
    if(typeof AlienInvasion!=='undefined'&&AlienInvasion.isActive()&&selectedTool==='move'){
      window._invasionMoveUses=Math.max(0,(window._invasionMoveUses||0)-1);
      const mu=document.getElementById('alien-move-uses');
      const mc2=document.getElementById('alien-move-counter');
      if(mu)mu.textContent=window._invasionMoveUses;
      if(window._invasionMoveUses===0){
        if(mc2)mc2.classList.add('depleted');
        showTooltip('🚫 Mover esgotado! Limite de 3 movimentos atingido.');
      } else {
        showTooltip(`✋ Astro movido! Restam ${window._invasionMoveUses} movimento(s).`);
      }
    }
    if(typeof MarsianInvasion!=='undefined'&&MarsianInvasion.isActive()&&selectedTool==='move'){
      window._marsianMoveUses=Math.max(0,(window._marsianMoveUses||0)-1);
      const mmu=document.getElementById('marsian-move-uses');
      const mmc=document.getElementById('marsian-move-counter');
      if(mmu)mmu.textContent=window._marsianMoveUses;
      if(window._marsianMoveUses===0){
        if(mmc)mmc.classList.add('depleted');
        showTooltip('🚫 Mover esgotado! Limite de 3 astros movidos atingido.');
      } else {
        showTooltip(`✋ Astro movido! Restam ${window._marsianMoveUses} movimento(s).`);
      }
    }
    if(typeof PolvicullusBoss!=='undefined'&&PolvicullusBoss.isActive()&&selectedTool==='move'){
      window._polvicullusMoveUses=Math.max(0,(window._polvicullusMoveUses||0)-1);
      const pmu=document.getElementById('polvicullus-move-uses');
      const pmc=document.getElementById('polvicullus-move-counter');
      if(pmu)pmu.textContent=window._polvicullusMoveUses;
      if(window._polvicullusMoveUses===0){
        if(pmc)pmc.classList.add('depleted');
        showTooltip('🚫 Mover esgotado! Limite de 3 astros movidos atingido.');
      } else {
        showTooltip(`✋ Astro movido! Restam ${window._polvicullusMoveUses} movimento(s).`);
      }
    }
    if(typeof GalaximyBoss!=='undefined'&&GalaximyBoss.isActive()&&selectedTool==='move'){
      window._galaximyMoveUses=Math.max(0,(window._galaximyMoveUses||0)-1);
      const gmu=document.getElementById('galaximy-move-uses');
      const gmc=document.getElementById('galaximy-move-counter');
      if(gmu)gmu.textContent=window._galaximyMoveUses;
      if(window._galaximyMoveUses===0){
        if(gmc)gmc.classList.add('depleted');
        showTooltip('🚫 Mover esgotado! Limite de 3 astros movidos atingido.');
      } else {
        showTooltip(`✋ Astro movido! Restam ${window._galaximyMoveUses} movimento(s).`);
      }
    }
    dragObj=null;dragPrevW=null;_dragStartedMoving=false;
    return;
  }

  // FIX: usa touchStart como posição de referência para hit-test no tap,
  // pois é o ponto exato onde o dedo desceu (mais confiável que changedTouches no end).
  const pos=touchStart;
  const elapsed=Date.now()-touchStartTime;
  // FIX: aumentado de 320ms para 500ms — taps em mobile podem ser mais lentos
  if(elapsed<500){
    // FIX bug card-ao-criar: em modo de criação usa tolerância MÍNIMA (4px) para
    // não abrir o painel de edição quando o tap é perto (mas não EM CIMA) de um astro.
    // Em modo pan/move/select usa tolerância normal (14px) para facilitar seleção.
    const isCreationTool = selectedTool!=='pan' && selectedTool!=='move' && selectedTool!=='reset';
    const isTechAnchorTool = TECH_ANCHOR_TOOLS.includes(selectedTool);
    // Ferramentas de ancoragem do Pacote Tecnológico usam tolerância maior:
    // o jogador pode tocar PERTO do astro, não precisa ser em cima dele.
    const tapTol = isTechAnchorTool ? 30 : (isCreationTool ? 4 : 14);
    const hit=findObjAt(pos.x,pos.y,tapTol);
    if(hit&&!hit.dead){
      // Pacote Tecnológico: toque perto de um astro ancora a megaestrutura nele
      if(sandboxMode&&isTechAnchorTool){
        if(Date.now()-_lastCreationTime>=300) _tryAnchorTechStructure(hit);
        lastTap={id:-1,t:0};
        dragObj=null;dragPrevW=null;_dragStartedMoving=false;
        return;
      }
      const now=Date.now();
      // Bloqueia abertura de painel por 900ms após criação de astro
      if(now-_lastCreationTime<900){lastTap={id:-1,t:0};return;}
      if(lastTap.id===hit.id&&now-lastTap.t<500){
        // Duplo tap
        if(isInvasionEditLocked()){lastTap={id:-1,t:0};return;}
        if(sandboxMode){openSandboxPanel(hit);}
        else{hit.dead=true;objects.forEach(o=>{if(o.parent===hit)o.parent=null;if(o.type==='wormhole'&&o.pairId===hit.id)o.pairId=-1;});if(hit===wormholePending)wormholePending=null;}
        lastTap={id:-1,t:0};
      } else {
        // Primeiro tap — só abre painel, NÃO cria astro
        lastTap={id:hit.id,t:now};
        if(sandboxMode&&!isInvasionEditLocked()){selectedObj=hit;openInfoPanel(hit);}
      }
    } else {
      lastTap={id:-1,t:0};
      if(!isCreationTool) { dragObj=null;dragPrevW=null;_dragStartedMoving=false; return; }
      // Verificação de segurança: não cria objeto se o toque está dentro do raio
      // visual de qualquer astro existente — mesmo que findObjAt não o tenha retornado
      // acima (pode acontecer com astros fixos em posições sobrepostas).
      const w=screenToWorld(pos.x,pos.y);
      // Fase Cósmica: clique perto de uma rocha já descoberta coleta o
      // minério em vez de criar um astro (mesmo com uma ferramenta de
      // criação selecionada — coleta tem prioridade sobre criação aqui).
      // Mesma prioridade vale para a nave-relíquia de boss adormecido —
      // só é de fato tocável se já revelada por uma Sonda Global.
      if(sandboxMode&&_sandboxPhase==='cosmic'&&typeof cosmicTryCollectRockAt==='function'){
        const collected=cosmicTryCollectRockAt(w.x,w.y);
        if(collected){ dragObj=null;dragPrevW=null;_dragStartedMoving=false; return; }
        if(typeof cosmicTryCollectRelicAt==='function'){
          const relicCollected=cosmicTryCollectRelicAt(w.x,w.y);
          if(relicCollected){ dragObj=null;dragPrevW=null;_dragStartedMoving=false; return; }
        }
      }
      const blocked=objects.some(o=>{
        if(o.dead)return false;
        return Math.hypot(w.x-o.x,w.y-o.y)<o.radius*1.1;
      });
      if(!blocked){
        _playerActionPending=true; // sinaliza que addObject é ação manual
        try{
          addObject(w.x,w.y);
        }catch(err){
          console.error('Erro ao criar astro:',err);
          showTooltip('⚠️ Não foi possível criar este astro.');
        }finally{
          _playerActionPending=false;
        }
        _lastCreationTime=Date.now(); // bloqueia painel por 900ms após criar
      }
    }
  }
  dragObj=null;dragPrevW=null;_dragStartedMoving=false;
}

