// Verdadeiro se QUALQUER invasão ativa proíbe edição/seleção de astros
function isInvasionEditLocked(){
  return (typeof AlienInvasion!=='undefined'&&AlienInvasion.isActive())
      || (typeof MarsianInvasion!=='undefined'&&MarsianInvasion.isActive())
      || (typeof ReptilianInvasion!=='undefined'&&ReptilianInvasion.isActive())
      || (typeof PolvicullusBoss!=='undefined'&&PolvicullusBoss.isActive())
      || (typeof GalaximyBoss!=='undefined'&&GalaximyBoss.isActive());
}
// Troca o ícone dos botões bloqueados por 🚫 (e restaura ao sair da invasão)
function _setInvasionAstroLockUI(active,blockedSet){
  (blockedSet||INVASION_BLOCKED_ASTRO_TYPES).forEach(type=>{
    const btn=document.querySelector(`.tool-btn[data-type="${type}"]`);
    if(!btn)return;
    const icoEl=btn.querySelector('.icon');
    if(!icoEl)return;
    if(active){
      if(icoEl.dataset.origIcon===undefined)icoEl.dataset.origIcon=icoEl.textContent;
      icoEl.textContent='🚫';
      btn.classList.add('invasion-locked');
    } else {
      if(icoEl.dataset.origIcon!==undefined){
        icoEl.textContent=icoEl.dataset.origIcon;
        delete icoEl.dataset.origIcon;
      }
      btn.classList.remove('invasion-locked');
    }
  });
}
// ── Mapeia subtipos de astros (Pacote de Estrelas, Pacote de Planetas etc.)
//    para a categoria de limite usada na Invasão Alienígena. Sem isso, ex.:
//    selecionar "Gigante Vermelha" (selectedTool='redGiant') não batia com
//    a chave 'star' do limite, deixando passar sem contar no limite.
const ASTRO_CAP_CATEGORY=(()=>{
  const map={};
  const starSubtypes=['redDwarf','yellowDwarf','blueStar','redGiant','supergiant','whiteDwarf',
    'hypergiant','vampireStar','quarkStar','thorneZytkow','ironStar','strangeStar','electroweakStar',
    'planckStar','wolfRayet','przybylski','janusStar','cosmicString','gravastar','quasiStar',
    'triplestar','twinstar','polarstar'];
  const planetSubtypes=['gasgiant','superearth','minineptune','dwarfplanet','lavaplt','oceanplt',
    'desertplt','carbonplt','ironplt','icegiant','exoticplanet_free'];
  map.star='star'; starSubtypes.forEach(t=>map[t]='star');
  map.planet='planet'; planetSubtypes.forEach(t=>map[t]='planet');
  map.moon='moon';
  map.cepheid='cepheid';
  map.comet='comet';
  map.meteor='meteor';
  map.blackhole='blackhole';
  map.whitehole='whitehole';
  map.magnetar='magnetar';
  map.pulsar='pulsar'; map.pulsarplanet='pulsar'; map.neutronstar='pulsar'; map.neutronstar_free='pulsar';
  map.quasar='quasar';
  map.blazar='blazar';
  return map;
})();
function astroCapCategory(type){return ASTRO_CAP_CATEGORY[type]||null;}

function addObject(wx,wy){
  const _preAddCount=objects.length; // snapshot p/ marcar playerCreated no fim
  // ── Limite de astros durante invasão alien ──────────────────────────
  const _astroNames={planet:'Planeta',star:'Estrela',moon:'Lua',cepheid:'Cefeida',comet:'Cometa',meteor:'Meteoro',blackhole:'Buraco Negro',whitehole:'Buraco Branco',magnetar:'Magnetar',pulsar:'Pulsar',quasar:'Quasar',blazar:'Blazar'};
  // ── Bloqueio durante invasão marciana: só Pacote Planetas é permitido ─
  if(typeof MarsianInvasion!=='undefined'&&MarsianInvasion.isActive()&&isMarsianInvasionBlockedType(selectedTool)){
    showTooltip('🚫 Apenas astros do Pacote Planetas durante a Invasão Marciana!');
    return;
  }
  // ── Limite justo (max + cooldown) por tipo de Planeta durante a invasão ─
  if(typeof MarsianInvasion!=='undefined'&&MarsianInvasion.isActive()&&window._marsianAstroCaps){
    const _mCap=window._marsianAstroCaps[selectedTool];
    if(_mCap){
      const _mName=TYPE_LABELS[selectedTool]||selectedTool;
      if(_mCap.cooldown>0){
        showTooltip(`🚫 ${_mName} em recarga! Aguarde ${Math.ceil(_mCap.cooldown)}s.`);
        return;
      }
      if(_mCap.used>=_mCap.max){
        showTooltip(`🚫 Limite de ${_mCap.max} ${_mName} já atingido! Aguardando recarga...`);
        return;
      }
    }
  }
  // ── Bloqueio e limite durante invasão Reptiliana (verificação ANTES de criar) ──
  if(typeof ReptilianInvasion!=='undefined'&&ReptilianInvasion.isActive()&&window._reptilianAstroCaps){
    if(isReptilianInvasionBlockedType(selectedTool)){
      showTooltip('🚫 Apenas astros do Pacote Estrelas durante a Invasão Reptiliana!');
      return;
    }
    const _rCapPre=window._reptilianAstroCaps[selectedTool];
    if(_rCapPre){
      const _rName=TYPE_LABELS[selectedTool]||selectedTool;
      if(_rCapPre.cooldown>0){
        showTooltip(`🚫 ${_rName} em recarga! Aguarde ${Math.ceil(_rCapPre.cooldown)}s.`);
        return;
      }
      if(_rCapPre.used>=_rCapPre.max){
        showTooltip(`🚫 Limite de ${_rCapPre.max} ${_rName} já atingido! Aguardando recarga...`);
        return;
      }
    } else {
      // tipo não está na lista de permitidos reptiliana → bloqueia
      showTooltip('🚫 Este astro não está disponível durante a Invasão Reptiliana!');
      return
    }
  }
  // ── Bloqueio e limite durante o combate do Polvicullus (verificação ANTES de criar) ──
  if(typeof PolvicullusBoss!=='undefined'&&PolvicullusBoss.isActive()&&window._polvicullusAstroCaps){
    if(isPolvicullusBlockedType(selectedTool)){
      showTooltip('🚫 Apenas astros do Pacote Exótico de combate durante o Polvicullus!');
      return;
    }
    const _pvCapPre=window._polvicullusAstroCaps[selectedTool];
    if(_pvCapPre){
      const _pvName=TYPE_LABELS[selectedTool]||selectedTool;
      if(_pvCapPre.cooldown>0){
        showTooltip(`🚫 ${_pvName} em recarga! Aguarde ${Math.ceil(_pvCapPre.cooldown)}s.`);
        return;
      }
      if(_pvCapPre.used>=_pvCapPre.max){
        showTooltip(`🚫 Limite de ${_pvCapPre.max} ${_pvName} já atingido! Aguardando recarga...`);
        return;
      }
    } else {
      showTooltip('🚫 Este astro não está disponível durante o combate do Polvicullus!');
      return;
    }
  }
  // ── Bloqueio durante o combate do Galaximy (verificação ANTES de criar) ──
  // Os astros ancorados (Dyson Sphere, Swarm, Shkadov, Matrioshka, Mass
  // Extractor, Alderson Disk, Nicoll-Dyson, Space Elevator) têm o cap
  // checado no próprio fluxo de ancoragem (_tryAnchorTechStructure / case
  // do switch). Aqui cobrimos o bloqueio geral + os 2 "freeStanding"
  // (Alcubierre Drive, Gravity Projector), que são criados livremente.
  if(typeof GalaximyBoss!=='undefined'&&GalaximyBoss.isActive()){
    if(isGalaximyBlockedType(selectedTool)){
      showTooltip('🚫 Apenas astros do Pacote Tecnológico durante o combate do Galaximy!');
      return;
    }
    if(window._galaximyAstroCaps){
      const _gCapPre=window._galaximyAstroCaps[selectedTool];
      if(_gCapPre){
        const _gName=TYPE_LABELS[selectedTool]||selectedTool;
        if(_gCapPre.cooldown>0){
          showTooltip(`🚫 ${_gName} em recarga! Aguarde ${Math.ceil(_gCapPre.cooldown)}s.`);
          return;
        }
        if(_gCapPre.used>=_gCapPre.max){
          showTooltip(`🚫 Limite de ${_gCapPre.max} ${_gName} já atingido! Aguardando recarga...`);
          return;
        }
      }
    }
  }
  if(typeof AlienInvasion!=='undefined'&&AlienInvasion.isActive()&&window._invasionAstroCaps){
    if(isInvasionBlockedType(selectedTool)){
      showTooltip('🚫 Astro de Pacote/Desbloqueável indisponível durante a Invasão!');
      return;
    }
    if(selectedTool==='microquasar'||selectedTool==='protostar'){
      showTooltip('🚫 '+(selectedTool==='microquasar'?'Microquasar':'Protoestrela')+' não disponível durante a Invasão!');
      return;
    }
    const capCat=astroCapCategory(selectedTool);
    const cap=capCat?window._invasionAstroCaps[capCat]:null;
    if(cap){
      if(capCat==='star'){
        // Estrela (e todos os subtipos do Pacote de Estrelas): limite por
        // contagem real de estrelas na arena (sem cooldown)
        if(cap.used>=cap.max){
          showTooltip(`🚫 Limite de ${cap.max} Estrelas na arena já atingido!`);
          return;
        }
        // cap.used/cap.max já refletem a contagem viva (atualizada pelo tick)
      } else {
      const cdTime=cap.cooldownTime||10;
      if(cap.cooldown>0){
        const s=Math.ceil(cap.cooldown);
        showTooltip(`🚫 ${_astroNames[capCat]||capCat} em recarga! Aguarde ${s}s.`);
        return;
      }
      if(cap.used>=cap.max){
        showTooltip(`🚫 Limite de ${cap.max} já atingido! Aguardando recarga...`);
        return;
      }
      cap.used++;
      const rem=cap.max-cap.used;
      const nome=_astroNames[capCat]||capCat;
      if(rem===0){
        cap.cooldown=cdTime;
        showTooltip(`⏳ ${nome}: limite atingido! Recarga em ${cdTime}s.`);
        _refreshAstroCounterUI(capCat,cap);
      } else {
        showTooltip(`${nome}: ${rem} restante(s).`);
        _refreshAstroCounterUI(capCat,cap);
      }
      if(cap.despawn){
        window._invasionPendingDespawn=window._invasionPendingDespawn||[];
        window._invasionPendingDespawn.push({type:selectedTool,timer:cap.despawn});
      }
      }
    }
  }
  // ── Zona de exclusão do Núcleo Dimensional e seu planeta: nenhum astro
  //    pode ser CRIADO ARTIFICIALMENTE dentro do raio deles (podem surgir
  //    ali só naturalmente, ex: galáxias automáticas do mapa) ──────────
  {
    const _excl=objects.filter(o=>(o.type==='colossalBlueGiant'||o.type==='colossalGiantPlanet')&&!o.dead);
    for(const _e of _excl){
      const _d=Math.hypot(wx-_e.x,wy-_e.y);
      if(_d<_e.radius){
        showTooltip('🔵 Não é possível criar astros dentro do Núcleo Dimensional ou seu planeta.');
        return;
      }
    }
  }
  // ───────────────────────────────────────────────────────────────────
  switch(selectedTool){
    case 'cosmicProbe':{
      if(!(sandboxMode&&_sandboxPhase==='cosmic')){showTooltip('🛰️ Sonda Cósmica disponível apenas na Fase Cósmica');break;}
      if(cosmicProbeCount()>=cosmicProbeLimit()){showTooltip(`🚫 Limite de ${cosmicProbeLimit()} sondas atingido! Compre upgrades de limite para criar mais.`);break;}
      objects.push(new CosmicProbe(wx,wy));
      break;
    }
    case 'cosmicTower': case 'cosmicSentinel': case 'cosmicKnight': case 'cosmicMage': {
      const _defTypeMap={cosmicTower:'tower',cosmicSentinel:'sentinel',cosmicKnight:'knight',cosmicMage:'mage'};
      trySpawnCosmicDefender(_defTypeMap[selectedTool],wx,wy);
      break;
    }
    case 'star':{const s=new Star(wx,wy);objects.push(s);objects.filter(o=>(o.type==='planet'||PP_ORBIT_TYPES.includes(o.type))&&!o.parent).forEach(p=>{const d=dist(p,s);if(d<280){p.parent=s;p.orbitDist=d;p.orbitAngle=Math.atan2(p.y-s.y,p.x-s.x);p.orbitSpeed=(0.4+rand(0,.3))/Math.sqrt(d/50);}});break;}
    case 'planet':{const star=findNearest({x:wx,y:wy},'star');const p=new Planet(wx,wy,star||null);if(star){p.orbitDist=dist(p,star);p.orbitAngle=Math.atan2(wy-star.y,wx-star.x);p.orbitSpeed=(0.4+rand(0,.3))/Math.sqrt(p.orbitDist/50);}objects.push(p);break;}
    case 'moon':{
      // Procura o astro-pai mais próximo: planet OU qualquer tipo do Pacote Planetas
      let _mHost=null,_mDist=999;
      ['planet',...PP_ORBIT_TYPES].forEach(t=>{const p=findNearest({x:wx,y:wy},t);if(p){const d=dist({x:wx,y:wy},p);if(d<_mDist){_mDist=d;_mHost=p;}}});
      const m=new Moon(wx,wy,_mHost||null);
      if(_mHost){m.orbitDist=Math.max(_mHost.radius+m.radius+10,_mDist);m.orbitAngle=Math.atan2(wy-_mHost.y,wx-_mHost.x);}
      objects.push(m);break;
    }
    case 'comet':  objects.push(new Comet(wx,wy));break;
    case 'meteor': objects.push(new Meteor(wx,wy));break;
    case 'blackhole':  objects.push(new BlackHole(wx,wy));break;
    case 'pulsar':     objects.push(new Pulsar(wx,wy));break;
    case 'whitehole':  objects.push(new WhiteHole(wx,wy));break;
    case 'quasar':     objects.push(new Quasar(wx,wy));break;
    case 'magnetar':   objects.push(new Magnetar(wx,wy));break;
    case 'protostar':  objects.push(new Protostar(wx,wy));break;
    case 'cepheid':    {const cf=new Cepheid(wx,wy);objects.push(cf);objects.filter(o=>(o.type==='planet'||PP_ORBIT_TYPES.includes(o.type))&&!o.parent).forEach(p=>{const d=dist(p,cf);if(d<280){p.parent=cf;p.orbitDist=d;p.orbitAngle=Math.atan2(p.y-cf.y,p.x-cf.x);p.orbitSpeed=(0.4+rand(0,.3))/Math.sqrt(d/50);}});break;}
    case 'blazar':     objects.push(new Blazar(wx,wy));break;
    case 'microquasar':objects.push(new Microquasar(wx,wy));break;
    case 'galaxy':
      if(sandboxMode){objects.push(new Galaxy(wx,wy));}
      else showTooltip('🌌 Galáxias disponíveis apenas no Modo Sandbox');
      break;
    case 'darkmatter':
      if(sandboxMode){objects.push(new DarkMatter(wx,wy));}
      else showTooltip('Apenas no Modo Sandbox');break;
    case 'polarstar':
      if(sandboxMode){objects.push(new PolarStar(wx,wy));}
      else showTooltip('Apenas no Modo Sandbox');break;
    case 'voidbelt':
      if(sandboxMode){objects.push(new VoidBelt(wx,wy));}
      else showTooltip('Apenas no Modo Sandbox');break;
    case 'riftfissure':
      if(sandboxMode){objects.push(new RiftFissure(wx,wy));}
      else showTooltip('Apenas no Modo Sandbox');break;
    case 'twinstar':
      if(sandboxMode){objects.push(new TwinStar(wx,wy));}
      else showTooltip('Apenas no Modo Sandbox');break;
    case 'bosonstar':
      if(sandboxMode){objects.push(new BosonStar(wx,wy));}
      else showTooltip('Apenas no Modo Sandbox');break;
    case 'greatattractor':
      if(sandboxMode){objects.push(new GreatAttractor(wx,wy));}
      else showTooltip('Apenas no Modo Sandbox');break;
    case 'colossalBlueGiant':
      if(sandboxMode){
        const bg=new ColossalBlueGiant(wx,wy);
        objects.push(bg);
        // spawna 1-2 planetas gigantes já orbitando, pra visualizar o conjunto
        const nPlanets=randInt(1,2);
        for(let i=0;i<nPlanets;i++){
          const gp=new ColossalGiantPlanet(wx,wy,bg);
          objects.push(gp);
        }
      }
      else showTooltip('Apenas no Modo Sandbox');break;
    case 'vetocrinazar':
      if(sandboxMode){objects.push(new Vetocrinazar(wx,wy));}
      else showTooltip('Apenas no Modo Sandbox');break;
    case 'triplestar':
      if(sandboxMode&&_achGetUnlocks().has('triplestar')){spawnTripleStar(wx,wy);}
      else if(!_achGetUnlocks().has('triplestar'))showTooltip('🔒 Desbloqueie na conquista "Sucção Tripla"');
      else showTooltip('Apenas no Modo Sandbox');break;
    case 'exoticplanet_free':
      if(sandboxMode&&_achGetUnlocks().has('exoticplanet_free')){objects.push(new PulsarPlanet(wx,wy));}
      else if(!_achGetUnlocks().has('exoticplanet_free'))showTooltip('🔒 Desbloqueie na conquista "Autêntico!"');
      else showTooltip('Apenas no Modo Sandbox');break;
    case 'neutronstar_free':
      if(sandboxMode&&_achGetUnlocks().has('neutronstar_free')){objects.push(new NeutronStar(wx,wy));}
      else if(!_achGetUnlocks().has('neutronstar_free'))showTooltip('🔒 Desbloqueie na conquista "Ecos de um Passado"');
      else showTooltip('Apenas no Modo Sandbox');break;
    case 'wormhole':{const cs=WORM_COLORS[randInt(0,WORM_COLORS.length-1)];if(!wormholePending){const w=new Wormhole(wx,wy,-1,cs);wormholePending=w;objects.push(w);showTooltip('Toque novamente para a saída!');}else{const w2=new Wormhole(wx,wy,wormholePending.id,wormholePending.colorSet);wormholePending.pairId=w2.id;objects.push(w2);wormholePending=null;showTooltip('Buraco de minhoca conectado!');}break;}
    case 'nebula':      if(sandboxMode){objects.push(new Nebula(wx,wy));}break;
    case 'frozencore':  if(sandboxMode){objects.push(new FrozenCore(wx,wy));}else showTooltip('🧊 Núcleo Gélido disponível apenas no Modo Sandbox');break;
    case 'gasgiant':case 'icegiant':case 'superearth':case 'minineptune':
    case 'dwarfplanet':case 'lavaplt':case 'oceanplt':case 'desertplt':
    case 'carbonplt':case 'ironplt':{
      if(!sandboxMode) break;
      const _ppClasses={gasgiant:GasGiant,icegiant:IceGiant,superearth:SuperEarth,
        minineptune:MiniNeptune,dwarfplanet:DwarfPlanet,lavaplt:LavaPlanet,
        oceanplt:OceanPlanet,desertplt:DesertPlanet,carbonplt:CarbonPlanet,ironplt:IronPlanet};
      const _ppObj=new _ppClasses[selectedTool](wx,wy);
      const _ppHost=_ppFindHost(wx,wy);
      if(_ppHost) _ppAttach(_ppObj,_ppHost);
      objects.push(_ppObj);
      // ── Limite justo durante a Invasão Marciana (igual à Alienígena) ──
      if(typeof MarsianInvasion!=='undefined'&&MarsianInvasion.isActive()&&window._marsianAstroCaps){
        const _mCap=window._marsianAstroCaps[selectedTool];
        if(_mCap){
          _mCap.used++;
          if(_mCap.used>=_mCap.max){
            _mCap.cooldown=_mCap.cooldownTime;
          }
          _refreshMarsianAstroCounterUI(selectedTool,_mCap);
          if(_mCap.despawn){
            setTimeout(()=>{ if(_ppObj&&!_ppObj.dead) _ppObj.dead=true; },_mCap.despawn*1000);
          }
        }
      }
      break;
    }
    case 'redDwarf':case 'yellowDwarf':case 'blueStar':case 'redGiant':case 'supergiant':
    case 'whiteDwarf':case 'hypergiant':case 'vampireStar':case 'quarkStar':case 'thorneZytkow':
    case 'ironStar':case 'strangeStar':case 'electroweakStar':case 'planckStar':case 'wolfRayet':
    case 'przybylski':case 'janusStar':case 'cosmicString':case 'gravastar':case 'quasiStar':{
      if(!sandboxMode) break;
      const _spClasses={redDwarf:RedDwarf,yellowDwarf:YellowDwarf,blueStar:BlueStar,
        redGiant:RedGiant,supergiant:Supergiant,whiteDwarf:WhiteDwarf,hypergiant:Hypergiant,
        vampireStar:VampireStar,quarkStar:QuarkStar,thorneZytkow:ThorneZytkow,
        ironStar:IronStar,strangeStar:StrangeStar,electroweakStar:ElectroweakStar,
        planckStar:PlanckStar,wolfRayet:WolfRayet,przybylski:PrzybylskiStar,
        janusStar:JanusStar,cosmicString:CosmicString,gravastar:Gravastar,quasiStar:QuasiStar};
      const _spObj=new _spClasses[selectedTool](wx,wy);
      objects.push(_spObj);
      // ── Limite justo durante a Invasão Reptiliana (max+cooldown+despawn) ──
      if(typeof ReptilianInvasion!=='undefined'&&ReptilianInvasion.isActive()&&window._reptilianAstroCaps){
        const _rCap=window._reptilianAstroCaps[selectedTool];
        if(_rCap){
          _rCap.used++;
          if(_rCap.used>=_rCap.max) _rCap.cooldown=_rCap.cooldownTime;
          _refreshReptilianAstroCounterUI(selectedTool,_rCap);
          if(_rCap.despawn){
            setTimeout(()=>{if(_spObj&&!_spObj.dead)_spObj.dead=true;},_rCap.despawn*1000);
          }
        }
      }
      break;
    }
    case 'exDarkStar':case 'exLittleRedDot':case 'exMonsterStar':case 'exIronStar':
    case 'exCosmicString':case 'exBlitzar':case 'exBeStar':case 'exBinaryNeutronStar':
    case 'exHoagObject':case 'exDarkGalaxy':case 'exRedHole':case 'exNakedSingularity':
    case 'exBlanet':case 'exBrownSubdwarf':case 'exQBall':case 'exGeon':
    case 'exDomainWall':case 'exSpacetimeCrystal':case 'exKugelblitz':case 'exDarkEnergyStar':{
      if(!sandboxMode) break;
      const _exClasses={exDarkStar:DarkStar,exLittleRedDot:LittleRedDot,exMonsterStar:MonsterStar,
        exIronStar:ExoticIronStar,exCosmicString:ExoticCosmicString,exBlitzar:Blitzar,
        exBeStar:BeStar,exBinaryNeutronStar:BinaryNeutronStar,exHoagObject:HoagObject,exDarkGalaxy:DarkGalaxy,
        exRedHole:RedHole,exNakedSingularity:NakedSingularity,exBlanet:Blanet,
        exBrownSubdwarf:BrownSubdwarf,exQBall:QBall,exGeon:Geon,exDomainWall:DomainWall,
        exSpacetimeCrystal:SpacetimeCrystal,exKugelblitz:Kugelblitz,exDarkEnergyStar:DarkEnergyStar};
      objects.push(new _exClasses[selectedTool](wx,wy));
      // ── Limite justo durante o combate do Polvicullus (max+cooldown) ──
      if(typeof PolvicullusBoss!=='undefined'&&PolvicullusBoss.isActive()&&window._polvicullusAstroCaps){
        const _pvCap=window._polvicullusAstroCaps[selectedTool];
        if(_pvCap){
          _pvCap.used++;
          if(_pvCap.used>=_pvCap.max) _pvCap.cooldown=_pvCap.cooldownTime;
          _refreshPolvicullusAstroCounterUI(selectedTool,_pvCap);
        }
        // HP e tempo de vida próprios (mesmo padrão _invasionHP/_invasionVanishTimer
        // usado nas outras Invasões) — o astro NÃO tem vida infinita, é destruído
        // pelos tentáculos/lasers do boss ou dissolve sozinho após o tempo limite.
        const _pvObj=objects[objects.length-1];
        _pvObj._invasionHP=100;
        _pvObj._invasionVanishTimer=POLVICULLUS_ASTRO_LIFESPAN;
      }
      break;
    }
    // ── Pacote Tecnológico ─────────────────────────────────────────
    case 'techDysonSphere':case 'techDysonSwarm':case 'techShkadovThruster':
    case 'techMatrioshkaBrain':case 'techMassExtractor':case 'techAldersonDisk':
    case 'techNicollDyson':{
      // Esses 7 precisam de âncora em astro existente
      if(!sandboxMode) break;
      const _techAnchorClasses={
        techDysonSphere:DysonSphere, techDysonSwarm:DysonSwarm,
        techShkadovThruster:ShkadovThruster, techMatrioshkaBrain:MatrioshkaBrain,
        techMassExtractor:MassExtractor, techAldersonDisk:AldersonDisk,
        techNicollDyson:NicollDysonBeam
      };
      // Verifica se tocou num astro existente
      const hitObj=objects.find(o=>!o.dead&&Math.hypot(o.x-wx,o.y-wy)<o.radius*1.5);
      if(hitObj){
        if(hitObj._galxMegaOccupant&&!hitObj._galxMegaOccupant.dead){
          showTooltip('🚫 Este astro já possui uma Megaestrutura ancorada!');
          break;
        }
        if(typeof GalaximyBoss!=='undefined'&&GalaximyBoss.isActive()&&window._galaximyAstroCaps){
          const _gCapPre=window._galaximyAstroCaps[selectedTool];
          if(_gCapPre){
            const _gName=TYPE_LABELS[selectedTool]||selectedTool;
            if(_gCapPre.cooldown>0){showTooltip(`🚫 ${_gName} em recarga! Aguarde ${Math.ceil(_gCapPre.cooldown)}s.`);break;}
            if(_gCapPre.used>=_gCapPre.max){showTooltip(`🚫 Limite de ${_gCapPre.max} ${_gName} já atingido! Aguardando recarga...`);break;}
          }
        }
        const inst=new _techAnchorClasses[selectedTool](wx,wy);
        inst.attachTo(hitObj);
        if(hitObj._galxHost!==undefined)hitObj._galxMegaOccupant=inst;
        objects.push(inst);
        if(typeof GalaximyBoss!=='undefined'&&GalaximyBoss.isActive()&&window._galaximyAstroCaps){
          const _gCap=window._galaximyAstroCaps[selectedTool];
          if(_gCap){_gCap.used++;if(_gCap.used>=_gCap.max)_gCap.cooldown=_gCap.cooldownTime;_refreshGalaximyAstroCounterUI(selectedTool,_gCap);}
        }
        _techCancelAnchor();
      } else {
        showTooltip(`🔧 Toque perto de um astro para ancorar a ${TYPE_LABELS[selectedTool]}.`);
      }
      break;
    }
    case 'techSpaceElevator':{
      if(!sandboxMode) break;
      const hitPlanet=objects.find(o=>!o.dead&&['planet','gasgiant','icegiant','superearth','minineptune','dwarfplanet','lavaplt','oceanplt','desertplt','carbonplt','ironplt'].includes(o.type)&&Math.hypot(o.x-wx,o.y-wy)<o.radius*2);
      if(hitPlanet){
        if(hitPlanet._galxMegaOccupant&&!hitPlanet._galxMegaOccupant.dead){
          showTooltip('🚫 Este astro já possui uma Megaestrutura ancorada!');
          break;
        }
        if(typeof GalaximyBoss!=='undefined'&&GalaximyBoss.isActive()&&window._galaximyAstroCaps){
          const _gCapPre=window._galaximyAstroCaps.techSpaceElevator;
          if(_gCapPre){
            if(_gCapPre.cooldown>0){showTooltip(`🚫 Elevador Espacial em recarga! Aguarde ${Math.ceil(_gCapPre.cooldown)}s.`);break;}
            if(_gCapPre.used>=_gCapPre.max){showTooltip(`🚫 Limite de ${_gCapPre.max} Elevador Espacial já atingido! Aguardando recarga...`);break;}
          }
        }
        const elev=new SpaceElevator(wx,wy);
        elev.attachTo(hitPlanet);
        if(hitPlanet._galxHost!==undefined)hitPlanet._galxMegaOccupant=elev;
        objects.push(elev);
        if(typeof GalaximyBoss!=='undefined'&&GalaximyBoss.isActive()&&window._galaximyAstroCaps){
          const _gCap=window._galaximyAstroCaps.techSpaceElevator;
          if(_gCap){_gCap.used++;if(_gCap.used>=_gCap.max)_gCap.cooldown=_gCap.cooldownTime;_refreshGalaximyAstroCounterUI('techSpaceElevator',_gCap);}
        }
      } else {
        showTooltip('🔧 Toque perto de um planeta para construir o Elevador Espacial.');
      }
      break;
    }
    case 'techAlcubierreDrive':{
      if(!sandboxMode) break;
      objects.push(new AlcubierreDrive(wx,wy));
      if(typeof GalaximyBoss!=='undefined'&&GalaximyBoss.isActive()&&window._galaximyAstroCaps){
        const _gCap=window._galaximyAstroCaps.techAlcubierreDrive;
        if(_gCap){_gCap.used++;if(_gCap.used>=_gCap.max)_gCap.cooldown=_gCap.cooldownTime;_refreshGalaximyAstroCounterUI('techAlcubierreDrive',_gCap);}
      }
      break;
    }
    case 'techGravityProjector':{
      if(!sandboxMode) break;
      objects.push(new GravityProjector(wx,wy));
      if(typeof GalaximyBoss!=='undefined'&&GalaximyBoss.isActive()&&window._galaximyAstroCaps){
        const _gCap=window._galaximyAstroCaps.techGravityProjector;
        if(_gCap){_gCap.used++;if(_gCap.used>=_gCap.max)_gCap.cooldown=_gCap.cooldownTime;_refreshGalaximyAstroCounterUI('techGravityProjector',_gCap);}
      }
      break;
    }
    case 'entityStarDevourer':{
      if(!sandboxMode) break;
      objects.push(new StarDevourerEntity(wx,wy));
      showTooltip('🔥 Devorador de Estrelas invocado! Ele caça estrelas autonomamente.');
      break;
    }
    case 'entityInvasionFleet':{
      if(!sandboxMode) break;
      objects.push(new InvasionFleetEntity(wx,wy));
      showTooltip('🛸 Frota Alienígena Militar invocada! Ela captura planetas e combate os Reptilianos.');
      break;
    }
    case 'entityMarcianFleet':{
      if(!sandboxMode) break;
      objects.push(new MarcianFleetEntity(wx,wy));
      showTooltip('🚁 Frota Militar Marciana invocada! Ela se alia à Frota Alienígena e reforça sua defesa.');
      break;
    }
    case 'entityReptilianFleet':{
      if(!sandboxMode) break;
      objects.push(new ReptilianFleetEntity(wx,wy));
      showTooltip('🔻 Frota Militar Reptiliana invocada! Uma nave-mãe colossal que caça Alienígenas, Marcianos e suas Frotas Militares.');
      break;
    }
    case 'entityCosmicParasite':{
      if(!sandboxMode) break;
      objects.push(new CosmicParasiteEntity(wx,wy));
      showTooltip('🦠 Parasita Cósmico invocado! Ele infecta cometas e meteoros.');
      break;
    }
    case 'entityVoidSerpent':{
      if(!sandboxMode) break;
      objects.push(new VoidSerpentEntity(wx,wy));
      showTooltip('🐍 Serpente do Vácuo invocada! Ela quebra órbitas com sua gravidade.');
      break;
    }
    case 'entityMechaWorld':{
      if(!sandboxMode) break;
      objects.push(new MechaWorldEntity(wx,wy));
      showTooltip('⚙️ Mecha-Mundo invocado! Ele fragmenta planetas em meteoros.');
      break;
    }
    case 'techProbe':{
      if(!sandboxMode) break;
      objects.push(new ProbeEntity(wx,wy));
      showTooltip('🛰️ Sonda lançada! Ela vai catalogar os astros próximos automaticamente.');
      break;
    }
    case 'techLaboratory':{
      if(!sandboxMode) break;
      const labHost=_findNearestHostFor('techLaboratory',wx,wy);
      if(!labHost){
        showTooltip('🔧 Nenhum astro encontrado para ancorar o Laboratório Orbital.');
        break;
      }
      const labInst=new LabEntity(labHost.x,labHost.y);
      labInst.attachTo(labHost);
      objects.push(labInst);
      showTooltip(`🔬 Laboratório Orbital ancorado em ${labHost.name||TYPE_LABELS[labHost.type]}!`);
      break;
    }
    case 'techStation':{
      if(!sandboxMode) break;
      const stHost=_findNearestHostFor('techStation',wx,wy);
      if(!stHost){
        showTooltip('🔧 Nenhum planeta encontrado para construir a Estação Espacial.');
        break;
      }
      const stInst=new StationEntity(stHost.x,stHost.y);
      stInst.attachTo(stHost);
      objects.push(stInst);
      showTooltip(`🏗️ Estação Espacial construída em ${stHost.name||TYPE_LABELS[stHost.type]}!`);
      break;
    }
    case 'techTelescope':{
      if(!sandboxMode) break;
      objects.push(new TelescopeEntity(wx,wy));
      showTooltip('🔭 Telescópio instalado! Ele vigia a região e alerta sobre ameaças Reptilianas.');
      break;
    }
    case 'entityAlien':{
      if(!sandboxMode) break;
      objects.push(new AlienEntity(wx,wy));
      showTooltip('👽 Alien invocado! Coloniza estrelas com Esferas de Dyson e abate ameaças.');
      break;
    }
    case 'entityMarcian':{
      if(!sandboxMode) break;
      objects.push(new MarcianEntity(wx,wy));
      showTooltip('🟢 Marciano invocado! Coloniza planetas — e pode se rebelar...');
      break;
    }
    case 'entityReptilian':{
      if(!sandboxMode) break;
      objects.push(new ReptilianEntity(wx,wy));
      showTooltip('🦎 Reptiliano invocado! Escraviza Aliens e Marcianos.');
      break;
    }
    case 'neutronstar': if(sandboxMode){objects.push(new NeutronStar(wx,wy));}break;
    case 'pulsarplanet':if(sandboxMode){objects.push(new PulsarPlanet(wx,wy));}break;
  }
  // ── Marca o astro recém-criado para despawn automático durante invasão ──
  if(window._invasionPendingDespawn&&window._invasionPendingDespawn.length){
    const pend=window._invasionPendingDespawn.pop();
    const last=objects[objects.length-1];
    if(last&&last.type===pend.type){
      last._invasionDespawnTimer=pend.timer;
    }
    window._invasionPendingDespawn.length=0;
  }
  // ── Marca todos os astros criados manualmente nesta chamada como
  //    playerCreated (para elegibilidade de Quantiks e skins cosméticas) ──
  for(let _i=_preAddCount;_i<objects.length;_i++){
    const _o=objects[_i];
    if(_o){
      _o.playerCreated=true;
      if(typeof _applyActiveSkin==='function')_applyActiveSkin(_o);
    }
  }
}

