  hypergiant:'Hipergigante',vampireStar:'Vampira Estelar',quarkStar:'Estrela de Quarks',
  thorneZytkow:'Obj. Thorne-Żytkow',ironStar:'Estrela de Ferro',strangeStar:'Estrela Estranha',
  electroweakStar:'Estrela Eletrofraca',planckStar:'Estrela de Planck',wolfRayet:'Estrela Wolf-Rayet',
  przybylski:'E. de Przybylski',janusStar:'Janus',cosmicString:'Estrela de Cordas',
  gravastar:'Gravastar',quasiStar:'Quasi-Star',
  exDarkStar:'Estrela Escura',exLittleRedDot:'Pequeno Ponto Vermelho',exMonsterStar:'Estrela Monstro',
  exIronStar:'Estrela de Ferro (Exótica)',exCosmicString:'Corda Cósmica',exBlitzar:'Blitzar',
  exBeStar:'Estrela Be',exBinaryNeutronStar:'Estrelas de Nêutrons Binárias',
  exHoagObject:'Objeto de Hoag',exDarkGalaxy:'Galáxia Escura',
  exRedHole:'Buraco Vermelho',exNakedSingularity:'Singularidade Desnuda',
  exBlanet:'Blaneta',exBrownSubdwarf:'Sub-anã Marrom',exQBall:'Q-Ball',exGeon:'Geon',
  exDomainWall:'Muralha de Domínio',exSpacetimeCrystal:'Cristal de Espaço-Tempo Crítico',
  exKugelblitz:'Kugelblitz',exDarkEnergyStar:'Estrela de Energia Escura',
  techDysonSphere:'Esfera de Dyson',techDysonSwarm:'Enxame de Dyson',
