// Conjunto de tipos/entidades já encontrados pelo jogador durante a gameplay
let cosmonarioFound=new Set();
function _cosmonarioDiscover(key){
  if(!COSMONARIO_DB[key])return;
  if(cosmonarioFound.has(key))return;
  cosmonarioFound.add(key);
  if(typeof _bpRenderCosmonario==='function')_bpRenderCosmonario();
}
