// ── Renderiza o preview REAL de um astro num mini-canvas isolado.
// Estratégia: troca temporariamente o `ctx`/canvas/câmera globais para
// apontar para o mini-canvas, instancia a classe real do astro, chama
// seu próprio draw() (arte 100% idêntica ao jogo), tira o resultado e
// restaura tudo ao estado original — de forma síncrona, sem deixar o
// jogo real perceber a troca. ──────────────────────────────────────
// ── Desenhos SIMPLIFICADOS e próprios dos 6 bosses de invasão.
// Não reaproveitam as funções de combate reais (muito amarradas a fase/
// arena/animação), mas usam as mesmas paletas de cor e silhueta central
// de cada um, para ficarem reconhecíveis no Cosmonário. ──────────────
// ── Imagens reais dos bosses (substituem os draws simplificados abaixo
// quando disponíveis). Pré-carregadas uma vez; se uma imagem falhar ao
// carregar (arquivo ausente/nome errado), o preview cai automaticamente
// de volta para o draw simplificado em COSMONARIO_BOSS_DRAWERS. ──────
const COSMONARIO_BOSS_IMAGES_SRC={
  bossQuasord:'images/Cosmonary/Quasord.png',
  bossReactorDevourer:'images/Cosmonary/Reactor.png',
  bossTecnoAlieNave:'images/Cosmonary/Techno.png',
  bossPolvicullus:'images/Cosmonary/Polvicullus.png',
  bossGalaximy:'images/Cosmonary/Galaximy.png',
};
const _cosmonarioBossImgCache={}; // key -> {img,ready,failed}
function _cosmonarioGetBossImg(key){
  const src=COSMONARIO_BOSS_IMAGES_SRC[key];
  if(!src)return null;
  let entry=_cosmonarioBossImgCache[key];
  if(!entry){
    entry={img:new Image(),ready:false,failed:false};
    entry.img.onload=()=>{entry.ready=true;if(typeof _bpRenderCosmonario==='function')_bpRenderCosmonario();};
    entry.img.onerror=()=>{entry.failed=true;};
    entry.img.src=src;
    _cosmonarioBossImgCache[key]=entry;
  }
  return entry;
}

const COSMONARIO_BOSS_DRAWERS={
  bossTecnoAlieNave(pctx,W,H,t){
    const cx=W/2,cy=H/2,r=Math.min(W,H)*0.3;
    pctx.save();pctx.translate(cx,cy);pctx.rotate(t*0.3);
    pctx.shadowColor='#00ff88';pctx.shadowBlur=14;
    pctx.beginPath();
    for(let i=0;i<6;i++){
      const a=i*Math.PI/3;
      const px=Math.cos(a)*r,py=Math.sin(a)*r*0.6;
      i===0?pctx.moveTo(px,py):pctx.lineTo(px,py);
    }
    pctx.closePath();
    const g=pctx.createRadialGradient(0,0,0,0,0,r);
    g.addColorStop(0,'#00ccff');g.addColorStop(1,'#00663a');
    pctx.fillStyle=g;pctx.fill();
    pctx.strokeStyle='#00ff88';pctx.lineWidth=2;pctx.stroke();
    pctx.beginPath();pctx.arc(0,0,r*0.25,0,Math.PI*2);
    pctx.fillStyle='#e8fff5';pctx.fill();
    pctx.restore();
  },
  bossReactorDevourer(pctx,W,H,t){
    const cx=W/2,cy=H/2,r=Math.min(W,H)*0.3;
    pctx.save();pctx.translate(cx,cy);
    pctx.shadowColor='#ff6a00';pctx.shadowBlur=14;
    pctx.beginPath();pctx.arc(0,0,r,0,Math.PI*2);
    const g=pctx.createRadialGradient(0,0,0,0,0,r);
    g.addColorStop(0,'#ffcf80');g.addColorStop(0.5,'#c83c00');g.addColorStop(1,'#3a1400');
    pctx.fillStyle=g;pctx.fill();
    pctx.strokeStyle='#ff8c30';pctx.lineWidth=2;pctx.stroke();
    // engrenagens simplificadas
    for(let i=0;i<8;i++){
      const a=i*Math.PI/4+t*0.4;
      pctx.beginPath();
      pctx.arc(Math.cos(a)*r*0.7,Math.sin(a)*r*0.7,r*0.12,0,Math.PI*2);
      pctx.fillStyle='#2a0e00';pctx.fill();
    }
    pctx.restore();
  },
  bossSolaris(pctx,W,H,t){
    const cx=W/2,cy=H/2,r=Math.min(W,H)*0.28;
    pctx.save();pctx.translate(cx,cy);
    pctx.shadowColor='#ff2020';pctx.shadowBlur=12;
    // corpo em cadeia (segmentos de trapézio, como o Quasord em miniatura)
    for(let i=-2;i<=2;i++){
      const w=r*(0.55-Math.abs(i)*0.08);
      pctx.beginPath();
      pctx.rect(i*r*0.42-w/2,-w*0.32,w,w*0.64);
      pctx.fillStyle=i===0?'#ff4040':'#3a0505';
      pctx.strokeStyle='#ff2020';pctx.lineWidth=1.4;
      pctx.fill();pctx.stroke();
    }
    pctx.restore();
  },
  bossNebulon(pctx,W,H,t){
    const cx=W/2,cy=H/2,r=Math.min(W,H)*0.3;
    pctx.save();pctx.translate(cx,cy);
    pctx.shadowColor='#ff2020';pctx.shadowBlur=12;
    pctx.beginPath();
    pctx.moveTo(0,-r);pctx.lineTo(r*0.85,0);pctx.lineTo(0,r);pctx.lineTo(-r*0.85,0);
    pctx.closePath();
    const g=pctx.createRadialGradient(0,0,0,0,0,r);
    g.addColorStop(0,'#5a1010');g.addColorStop(1,'#150202');
    pctx.fillStyle=g;pctx.fill();
    pctx.strokeStyle='#ff3030';pctx.lineWidth=2;pctx.stroke();
    // par de olhos giratórios
    [-1,1].forEach(s=>{
      pctx.beginPath();pctx.arc(s*r*0.28,-r*0.05,r*0.13,0,Math.PI*2);
      pctx.fillStyle='#ff5050';pctx.fill();
    });
    pctx.restore();
  },
  bossDrexcy(pctx,W,H,t){
    const cx=W/2,cy=H/2,r=Math.min(W,H)*0.3;
    pctx.save();pctx.translate(cx,cy);
    pctx.shadowColor='#ff2020';pctx.shadowBlur=14;
    // corpo
    pctx.beginPath();pctx.ellipse(0,r*0.1,r*0.55,r*0.4,0,0,Math.PI*2);
    pctx.fillStyle='#2a0303';pctx.fill();pctx.strokeStyle='#ff2020';pctx.lineWidth=1.6;pctx.stroke();
    // asas membranosas
    [-1,1].forEach(s=>{
      pctx.beginPath();
      pctx.moveTo(s*r*0.3,-r*0.05);
      pctx.lineTo(s*r*0.95,-r*0.55);
      pctx.lineTo(s*r*0.55,r*0.15);
      pctx.closePath();
      pctx.fillStyle='rgba(180,20,20,0.55)';pctx.fill();
      pctx.strokeStyle='#ff3030';pctx.lineWidth=1;pctx.stroke();
    });
    // cabeça/focinho
    pctx.beginPath();pctx.moveTo(0,-r*0.25);pctx.lineTo(r*0.2,-r*0.5);pctx.lineTo(-r*0.2,-r*0.5);pctx.closePath();
    pctx.fillStyle='#3a0505';pctx.fill();
    pctx.restore();
  },
  bossQuasord(pctx,W,H,t){
    const cx=W/2,cy=H/2,r=Math.min(W,H)*0.3;
    pctx.save();pctx.translate(cx,cy);
    pctx.shadowColor='#ff0000';pctx.shadowBlur=18;
    // 18 segmentos em miniatura (cadeia mecânica) — representa só uma fração
    for(let i=-4;i<=4;i++){
      const w=r*(0.5-Math.abs(i)*0.045);
      const wobble=Math.sin(t*2+i)*r*0.03;
      pctx.beginPath();
      pctx.rect(i*r*0.24-w/2,-w*0.3+wobble,w,w*0.6);
      pctx.fillStyle=i===0?'#ff2020':'#1a0000';
      pctx.strokeStyle='#ff0000';pctx.lineWidth=1.2;
      pctx.fill();pctx.stroke();
    }
    // olho central
    pctx.beginPath();pctx.arc(0,0,r*0.11,0,Math.PI*2);
    pctx.fillStyle='#ff6060';pctx.fill();
    pctx.restore();
  },
  bossPolvicullus(pctx,W,H,t){
    const cx=W/2,cy=H/2,r=Math.min(W,H)*0.28;
    pctx.save();pctx.translate(cx,cy);
    pctx.shadowColor='#8a5fc9';pctx.shadowBlur=14;
    // 8 tentáculos em miniatura
    for(let i=0;i<8;i++){
      const a=(i/8)*Math.PI*2+t*0.4;
      pctx.beginPath();pctx.moveTo(0,0);
      pctx.quadraticCurveTo(Math.cos(a)*r*0.7,Math.sin(a)*r*0.7,Math.cos(a)*r*1.15,Math.sin(a)*r*1.15);
      pctx.strokeStyle='#8a5fc9';pctx.lineWidth=3;pctx.stroke();
    }
    // corpo central
    pctx.beginPath();pctx.arc(0,0,r*0.45,0,Math.PI*2);
    pctx.fillStyle='#5c3d99';pctx.fill();
    pctx.strokeStyle='#c9a3ff';pctx.lineWidth=1.5;pctx.stroke();
    // olho
    pctx.beginPath();pctx.arc(0,0,r*0.12,0,Math.PI*2);
    pctx.fillStyle='#ffd93d';pctx.fill();
    pctx.restore();
  },
  bossGalaximy(pctx,W,H,t){
    const cx=W/2,cy=H/2,r=Math.min(W,H)*0.3;
    pctx.save();pctx.translate(cx,cy);
    pctx.shadowColor='#4dd0ff';pctx.shadowBlur=16;
    // núcleo atômico simplificado: núcleo + 2 órbitas
    pctx.strokeStyle='rgba(77,208,255,.6)';pctx.lineWidth=1.2;
    pctx.beginPath();pctx.ellipse(0,0,r,r*0.4,t*0.5,0,Math.PI*2);pctx.stroke();
    pctx.beginPath();pctx.ellipse(0,0,r,r*0.4,-t*0.5+Math.PI/3,0,Math.PI*2);pctx.stroke();
    pctx.beginPath();pctx.arc(0,0,r*0.4,0,Math.PI*2);
    const g=pctx.createRadialGradient(0,0,0,0,0,r*0.4);
    g.addColorStop(0,'#eaffff');g.addColorStop(1,'#2a8fb0');
    pctx.fillStyle=g;pctx.fill();
    pctx.restore();
  },
};

function _cosmonarioRenderBossPreview(key,canvasEl){
  if(!canvasEl)return false;
  const W=canvasEl.width,H=canvasEl.height;
  const pctx=canvasEl.getContext('2d');
  // 1) Tenta a imagem real do boss, se mapeada e já carregada.
  const imgEntry=_cosmonarioGetBossImg(key);
  if(imgEntry&&imgEntry.ready&&!imgEntry.failed){
    try{
      pctx.clearRect(0,0,W,H);
      // 'contain' manual: encaixa a imagem inteira no quadrado do ícone
      // sem distorcer proporção.
      const iw=imgEntry.img.naturalWidth||1,ih=imgEntry.img.naturalHeight||1;
      const scale=Math.min(W/iw,H/ih);
      const dw=iw*scale,dh=ih*scale;
      pctx.drawImage(imgEntry.img,(W-dw)/2,(H-dh)/2,dw,dh);
      return true;
    }catch(e){
      console.warn('[Cosmonário] falha ao desenhar imagem do boss',key,e);
    }
  }
  // 2) Fallback: draw simplificado em canvas (usado enquanto a imagem
  // carrega, se falhar, ou se o boss não tiver imagem mapeada).
  const drawer=COSMONARIO_BOSS_DRAWERS[key];
  if(!drawer)return false;
  try{
    pctx.clearRect(0,0,W,H);
    drawer(pctx,W,H,(typeof simTime!=='undefined'?simTime:0));
    return true;
  }catch(e){
    console.warn('[Cosmonário] preview de boss falhou para',key,e);
    return false;
  }
}
function _cosmonarioRenderPreview(type,canvasEl){
  const Cls=COSMONARIO_CLASS_MAP[type];
  if(!Cls||!canvasEl)return false;
  const W=canvasEl.width,H=canvasEl.height;
  const pctx=canvasEl.getContext('2d');
  // Salva estado global real
  const savedCtx=ctx, savedCanvas=canvas;
  const savedCamX=cam.x, savedCamY=cam.y, savedCamZoom=cam.zoom;
  const savedSandbox=sandboxMode;
  try{
    // Redireciona temporariamente para o mini-canvas
    ctx=pctx;
    canvas=canvasEl;
    cam.x=0;cam.y=0;cam.zoom=1;
    sandboxMode=false; // evita desenhar labels de nome no preview
    pctx.clearRect(0,0,W,H);
    const obj=new Cls(0,0);
    // Normaliza tamanho para caber confortavelmente no mini-canvas
    if(obj.radius){
      const targetR=Math.min(W,H)*0.32;
      cam.zoom=Math.max(0.3,Math.min(3,targetR/obj.radius));
    }
    obj.age=999; obj.glowPhase=0;
    pctx.save();
    obj.draw(simTime||0);
    pctx.restore();
    return true;
  }catch(e){
    console.warn('[Cosmonário] preview falhou para',type,e);
    return false;
  }finally{
    // Restaura TUDO ao estado real do jogo, sem deixar vazamento
    ctx=savedCtx;
    canvas=savedCanvas;
    cam.x=savedCamX;cam.y=savedCamY;cam.zoom=savedCamZoom;
    sandboxMode=savedSandbox;
  }
}
// ── Descoberta de entidades/bosses de invasão (chamada pelos ticks das
// 3 invasões — Alien/Marciano/Reptiliano — sempre que estão ativas) ──
function _cosmonarioScanInvasions(){
  try{
    if(typeof AlienInvasion!=='undefined'&&AlienInvasion.isActive()){
      _cosmonarioDiscover('entityAlien');
      if(typeof window._alienBossOnScreen!=='undefined'&&window._alienBossOnScreen)_cosmonarioDiscover('bossTecnoAlieNave');
    }
    if(typeof MarsianInvasion!=='undefined'&&MarsianInvasion.isActive()){
      _cosmonarioDiscover('entityMarcian');
      if(typeof window._marsianBossOnScreen!=='undefined'&&window._marsianBossOnScreen)_cosmonarioDiscover('bossReactorDevourer');
    }
    if(typeof ReptilianInvasion!=='undefined'&&ReptilianInvasion.isActive()){
      _cosmonarioDiscover('entityReptilian');
      const tf=window._reptTripleBossForm;
      if(tf==='serpente')_cosmonarioDiscover('bossSolaris');
      else if(tf==='camaleao')_cosmonarioDiscover('bossNebulon');
      else if(tf==='dragao')_cosmonarioDiscover('bossDrexcy');
      if(window._reptQuasordOnScreen)_cosmonarioDiscover('bossQuasord');
    }
  }catch(e){/* silencioso — não deve nunca quebrar o gameplay */}
}

