let tooltipTimer;
function showTooltip(msg){const el=document.getElementById('tooltip');el.textContent=msg;el.classList.add('show');clearTimeout(tooltipTimer);tooltipTimer=setTimeout(()=>el.classList.remove('show'),3200);}

function _refreshAstroCounterUI(type,cap){
  const el=document.getElementById(`alien-${type}-counter`);
  const sp=document.getElementById(`alien-${type}-uses`);
  if(!el||!sp)return;
  const mx=document.getElementById(`alien-${type}-max`);
  if(mx)mx.textContent=cap.max;
  const rem=Math.max(0,cap.max-cap.used);
  if(cap.cooldown>0){
    sp.textContent=`${Math.ceil(cap.cooldown)}s`;
    el.classList.remove('depleted');el.classList.add('cooldown');
  } else {
    sp.textContent=rem;
    el.classList.toggle('depleted',rem===0);
    el.classList.remove('cooldown');
  }
}
