// ═══════════════════════════════════════════════════════════════════
//  RESIZE + INIT
// ═══════════════════════════════════════════════════════════════════
function resizeCanvas(){
  const rect=app.getBoundingClientRect();
  if(document.body.classList.contains('desktop-mode')){
    // Desktop: toolbar vertical esquerda (72px) + zoom-bar vertical direita (44px)
    canvas.width=rect.width-72-44;
    canvas.height=rect.height;
    canvas.style.left='72px';
    canvas.style.top='0';
  } else if(document.body.classList.contains('landscape-mode')){
    // Landscape mobile: toolbar vertical esquerda (60px) + zoom-bar vertical direita (38px)
    canvas.width=rect.width-60-38;
    canvas.height=rect.height;
    canvas.style.left='60px';
    canvas.style.top='0';
  } else {
    // Portrait mobile: toolbar em baixo + zoom-bar em baixo
    const tb=document.getElementById('toolbar');
    const zb=document.getElementById('zoom-bar');
    canvas.width=rect.width;
    canvas.height=rect.height-(tb?tb.offsetHeight:0)-(zb?zb.offsetHeight:0);
    canvas.style.left='0';
    canvas.style.top='0';
  }
  gravCvs.width=canvas.width;gravCvs.height=canvas.height;
  gravCvs.style.left=canvas.style.left;
  gravCvs.style.top=canvas.style.top;
}
// NOTA: o listener de 'resize' que chamava resizeCanvas()+recalcArena() foi
// removido daqui porque havia OUTRO listener de 'resize' (applyLayoutMode,
// mais abaixo) que também chamava resizeCanvas() — os dois disparavam no
// mesmo evento, um logo depois do outro. O 2º resizeCanvas() podia mudar
// canvas.width/height de novo (ex: troca de modo desktop/landscape/portrait
// com margens diferentes) SEM que nenhum recalcArena() rodasse depois dele,
// deixando a arena (_arenaRect) calculada com dimensões já desatualizadas.
// Isso fazia a arena encolher, ficar fora de posição/mais vertical, e não
// voltar ao normal em resizes sucessivos. A chamada de recalcArena() das
// três invasões foi movida para dentro de applyLayoutMode(), logo após o
// ÚNICO resizeCanvas() que agora roda por evento — ver mais abaixo.

function initScene(){
  objects=[];particles=[];pendingObjects=[];wormholePending=null;selectedObj=null;
  cam.x=0;cam.y=0;cam.zoom=1;sbGalaxyTimer=0;
  const star=new Star(0,0);star.radius=20;star.mass=300;objects.push(star);
  const p1=new Planet(95,0,star);p1.orbitDist=95;p1.orbitAngle=0;p1.orbitSpeed=.52;p1.color='#4a9eff';objects.push(p1);
  const p2=new Planet(-150,0,star);p2.orbitDist=150;p2.orbitAngle=Math.PI;p2.orbitSpeed=.33;p2.color='#ff6b6b';p2.radius=10;objects.push(p2);
  const m1=new Moon(118,0,p1);m1.orbitDist=23;m1.orbitAngle=.5;m1.orbitSpeed=2.0;objects.push(m1);
  // Núcleo Dimensional (Gigante Azul Colossal) — obrigatória e única, mas
  // exclusiva da Fase Cósmica do Sandbox (não existe na Fase Espacial nem
  // no Modo Normal). Spawnada longe do sistema inicial.
  if(sandboxMode&&_sandboxPhase==='cosmic'){
    const bgAngle=rand(0,Math.PI*2),bgDist=rand(60000,90000);
    const bgx=Math.cos(bgAngle)*bgDist,bgy=Math.sin(bgAngle)*bgDist;
    const bg=new ColossalBlueGiant(bgx,bgy);
    objects.push(bg);
    const nPlanets=randInt(1,2);
    for(let i=0;i<nPlanets;i++){
      const gp=new ColossalGiantPlanet(bgx,bgy,bg);
      objects.push(gp);
    }
  }
  // Sandbox: pre-spawn a couple galaxies at start
  if(sandboxMode){
    for(let i=0;i<2;i++){
      const a=rand(0,Math.PI*2),d=rand(600,1400);
      const g=new Galaxy(Math.cos(a)*d,Math.sin(a)*d);
      g._autoSpawn=true; // não conta para missão
      pendingObjects.push(g);
    }
  }
}

// ═══════════════════════════════════════════════════════════════════
//  MISSIONS & RANK SYSTEM — Sandbox only
//  All stat increments happen via incrementStat() — no function wrapping
// ═══════════════════════════════════════════════════════════════════

// Simple boolean: returns true if player has reached the required rank
function isRankUnlocked(requiredRank){ return playerRank>=requiredRank; }

// Increment a mission stat safely and refresh UI
// ── _playerActionPending: flag que garante que incrementStat só conta ações manuais ──
// Setada para true APENAS dentro do handler de tap/clique do canvas (onEnd).
// addObject e outros gatilhos automáticos verificam esta flag antes de incrementar stats.
// É resetada para false imediatamente após cada uso, nunca fica true entre frames.
let _playerActionPending=false;

function incrementStat(key,amount){
  if(!(key in mStats))return;
  mStats[key]=(mStats[key]||0)+(amount||1);
  if(sandboxMode) _scheduleMissionsRefresh();
  scheduleSave();
}

// Debounce UI refresh so rapid stat changes don't thrash the DOM
let _missionsRefreshPending=false;
function _scheduleMissionsRefresh(){
  if(_missionsRefreshPending)return;
  _missionsRefreshPending=true;
  requestAnimationFrame(()=>{_missionsRefreshPending=false;updateMissionsUI();});
}

// ── BASELINE SYSTEM ────────────────────────────────────────────────
// Problema central: mStats é GLOBAL e cumulativo entre sessões (dentro
// do mesmo jogo). Quando uma missão fica visível (desbloqueada por rank),
// seu stat já pode ter valor alto de missões anteriores que usam o mesmo
// stat (ex: starsCreated já é 8 quando m11 "8 estrelas" é desbloqueada).
//
// Solução: ao desbloquear uma missão, registramos mBaseline[id] = mStats[stat].
// O progresso real = mStats[stat] - mBaseline[id].
// Missões visíveis desde o início (rank 0) têm baseline 0 implicitamente.
// ──────────────────────────────────────────────────────────────────
// mBaseline é persistido junto com mStats no save.
let mBaseline={};  // { missionId: statValueAtUnlockTime }

function _ensureBaseline(m){
  // Chama quando uma missão se torna visível pela primeira vez.
  // Só registra se ainda não foi registrada (e não foi claimed).
  if(mBaseline[m.id]===undefined && !mClaimed.has(m.id)){
    mBaseline[m.id]=mStats[m.stat]||0;
    scheduleSave();
  }
}

function getMissionProgress(m){
  if(!mStats||!m||!m.stat)return 0;
  const baseline=mBaseline[m.id]||0;
  const raw=(mStats[m.stat]||0)-baseline;
  return Math.min(Math.max(raw,0),m.goal);
}
function isMissionDone(m){return getMissionProgress(m)>=m.goal;}
function isMissionVisible(m){
  const req=m.unlockAtRank||1;
  // unlockAtRank:1 → visível desde rank 0. unlockAtRank:2 → rank 1. Etc.
  const minRank=req-1;
  if(playerRank<minRank)return false;
  if(mClaimed.has(m.id))return false;
  // Garante baseline no momento exato em que a missão fica visível
  _ensureBaseline(m);
  return true;
}
