let _sbTutStep = 0;
let _sbTutPhase = 'dr'; // 'dr' | 'cosmy'
let _sbTutActive = false;

function _isSandboxTutDone(){
  try{return !!localStorage.getItem(SANDBOX_TUT_KEY);}catch(e){return true;}
}

function _setSbSpeaker(step){
  const imgEl = document.getElementById('cosmy-img');
  const bubble = document.getElementById('cosmy-bubble');
  const stepLbl = document.getElementById('cosmy-step-label');
  if(!imgEl||!bubble)return;

  if(step.speaker === 'Dr. Blackholy'){
    const src = DR_IMAGES[step.mood] || DR_IMAGES['neutro'];
    imgEl.src = src;
    imgEl.classList.add('blackholy-img');
    bubble.classList.add('blackholy-theme');
    stepLbl.style.color = 'rgba(200,100,255,.6)';
  } else {
    const src = COSMY_IMAGES[step.mood] || COSMY_IMAGES['point'];
    imgEl.src = src;
    imgEl.classList.remove('blackholy-img');
    bubble.classList.remove('blackholy-theme');
    stepLbl.style.color = '';
  }
  imgEl.classList.remove('cosmy-entrance');
  void imgEl.offsetWidth;
  imgEl.classList.add('cosmy-entrance');
}

function _showSbStep(idx){
  const overlay = document.getElementById('cosmy-overlay');
  const spotEl  = document.getElementById('cosmy-spotlight');
  const arrowEl = document.getElementById('cosmy-arrow');
  const msgEl   = document.getElementById('cosmy-msg');
  const stepLbl = document.getElementById('cosmy-step-label');
  const progressFill = document.getElementById('cosmy-progress-fill');
  const nextBtn  = document.getElementById('cosmy-next');
  const skipBtn  = document.getElementById('cosmy-skip');

  const allSteps = [...DR_STEPS, ...SANDBOX_COSMY_STEPS];
  const total    = allSteps.length;

  if(idx >= total){ _endSbTutorial(true); return; }
  _sbTutStep = idx;
  const step = allSteps[idx];

  // Texto
  msgEl.classList.remove('cosmy-text-anim');
  void msgEl.offsetWidth;
  msgEl.innerHTML = step.msg;
  msgEl.classList.add('cosmy-text-anim');

  // Label de passo
  stepLbl.textContent = `${step.speaker} · PASSO ${idx+1} DE ${total}`;

  // Progresso
  progressFill.style.width = ((idx+1)/total*100)+'%';

  // Personagem
  _setSbSpeaker(step);

  // Botão
  if(step.last){
    nextBtn.textContent='🚀 Vamos lá!';nextBtn.classList.add('finish');
  } else if(step.lastDr){
    nextBtn.textContent='Próximo →';nextBtn.classList.remove('finish');
  } else {
    nextBtn.textContent='Próximo →';nextBtn.classList.remove('finish');
  }

  // Pular: mostra "Pular" apenas na fase Dr., na fase Cosmy mantém
  skipBtn.textContent = 'Pular Tutorial';

  // Spotlight
  const targetEl = step.target ? step.target() : null;
  if(targetEl){
    const r = _getSpotlightRect(targetEl);
    if(r){
      spotEl.style.top=r.top+'px';spotEl.style.left=r.left+'px';
      spotEl.style.width=r.width+'px';spotEl.style.height=r.height+'px';
      spotEl.classList.add('visible');
      _positionArrow(r,arrowEl,step.arrow);
    }
  } else {
    spotEl.classList.remove('visible');
    arrowEl.classList.remove('visible');
  }
}

function _startSbTutorial(){
  if(currentScreen!=='game'||!sandboxMode)return;
  _sbTutActive=true;
  _sbTutStep=0;
  const overlay=document.getElementById('cosmy-overlay');
  overlay.classList.add('active');
  setTimeout(()=>_showSbStep(0),150);
}

function _endSbTutorial(completed){
  _sbTutActive=false;
  const overlay=document.getElementById('cosmy-overlay');
  // Limpa tema do Dr. Blackholy
  document.getElementById('cosmy-bubble').classList.remove('blackholy-theme');
  document.getElementById('cosmy-img').classList.remove('blackholy-img');
  overlay.style.opacity='0';
  setTimeout(()=>{
    overlay.classList.remove('active');
    overlay.style.opacity='';
    document.getElementById('cosmy-spotlight').classList.remove('visible');
    document.getElementById('cosmy-arrow').classList.remove('visible');
  },400);
  if(completed){
    try{localStorage.setItem(SANDBOX_TUT_KEY,'1');}catch(e){}
    showTooltip('⚙️ Tutorial Sandbox concluído! Bom caos, Cosmonauta!');
  } else {
    try{localStorage.setItem(SANDBOX_TUT_KEY,'1');}catch(e){}
  }
  // Atualiza bloqueios na mode-screen
  if(typeof window._refreshModeLocks==='function')window._refreshModeLocks();
}

// ── Patch: ao entrar no Sandbox pela 1ª vez, dispara Dr. Blackholy ──
const _origStartGame2 = startGame;
startGame = function(){
  _origStartGame2.apply(this,arguments);
  if(sandboxMode && !_isSandboxTutDone() && !_isFirstTimePlayer()){
    setTimeout(_startSbTutorial, 400);
  } else if(!sandboxMode && _isFirstTimePlayer()){
    // Tutorial normal já vai ser disparado pelo patch anterior
  }
};

