document.addEventListener('DOMContentLoaded', function(){
  // Remove a splash screen do DOM assim que o fade-out termina (3.4s = 2.8s delay + 0.6s fade)
  const bootSplash=document.getElementById('boot-splash');
  if(bootSplash)setTimeout(()=>bootSplash.remove(),3500);
  const btn = document.getElementById('pack-unlock-btn');
  if(btn) btn.addEventListener('click', _hidePackUnlockModal);
  const modal = document.getElementById('pack-unlock-modal');
  if(modal) modal.addEventListener('click', function(e){
    if(e.target === this) _hidePackUnlockModal();
  });
});

// ── Chave nova (v2) para limpar estado bugado de versões anteriores ──
const DR9_KEY = 'cosmos_sim_dr7_planets_done_v2';

function _isDr9Done(){
  try{return !!localStorage.getItem(DR9_KEY);}catch(e){return true;}
}

// Passos da interrupção do Dr. Blackholy ao atingir o Rank 7
const DR9_STEPS = [
  {
    msg: '…Interrompendo transmissão.<br><br>Eu sei que você estava ocupado. Mas o que acabou de acontecer <em>não pode esperar</em>.',
    mood:'neutro', speaker:'Dr. Blackholy'
  },
  {
    msg: 'Rank <strong>7</strong>. Isso é… inesperado.<br><br>A maioria das pessoas para no 3. Ou perde o interesse no 5.<br><br><em>Mas você continuou.</em>',
    mood:'chateado', speaker:'Dr. Blackholy'
  },
  {
    msg: 'E por isso — deixa eu deixar muito claro que isso é <strong>contra meu julgamento científico</strong> — decidi liberar algo do meu arquivo pessoal.',
    mood:'transe', speaker:'Dr. Blackholy'
  },
  {
    msg: '🪐 O <strong>Pacote Planetas</strong> foi desbloqueado.<br><br>Uma coleção que cataloguei ao longo de anos: Gigantes Gasosos, Gigantes de Gelo, Super-Terras, Mini-Netunos, Planetas Anões e muito mais.',
    mood:'boas vindas', speaker:'Dr. Blackholy'
  },
  {
    msg: 'Você os verá em uma <strong>barra separada acima das ferramentas</strong>.<br><br>Cada tipo tem física, temperatura e aparência próprias. Não os trate como planetas comuns.',
    mood:'neutro', speaker:'Dr. Blackholy',
    last: true
  }
];

let _dr9Active = false;
let _dr9Step   = 0;

function _showDr9Step(idx){
  const overlay      = document.getElementById('cosmy-overlay');
  const msgEl        = document.getElementById('cosmy-msg');
  const stepLbl      = document.getElementById('cosmy-step-label');
  const progressFill = document.getElementById('cosmy-progress-fill');
  const nextBtn      = document.getElementById('cosmy-next');
  const skipBtn      = document.getElementById('cosmy-skip');
  const spotEl       = document.getElementById('cosmy-spotlight');
  const arrowEl      = document.getElementById('cosmy-arrow');

  const total = DR9_STEPS.length;
  if(idx >= total){ _endDr9(true); return; }
  _dr9Step = idx;
  const step = DR9_STEPS[idx];

  msgEl.classList.remove('cosmy-text-anim');
  void msgEl.offsetWidth;
  msgEl.innerHTML = step.msg;
  msgEl.classList.add('cosmy-text-anim');

  stepLbl.textContent = `Dr. Blackholy · PASSO ${idx+1} DE ${total}`;
  progressFill.style.width = ((idx+1)/total*100)+'%';

  const imgEl  = document.getElementById('cosmy-img');
  const bubble = document.getElementById('cosmy-bubble');
  const src = DR_IMAGES[step.mood] || DR_IMAGES['neutro'];
  imgEl.src = src;
  imgEl.classList.add('blackholy-img');
  imgEl.classList.remove('dk910-img');
  bubble.classList.add('blackholy-theme');
  bubble.classList.remove('dk910-theme');
  stepLbl.style.color = 'rgba(200,100,255,.6)';
  imgEl.classList.remove('cosmy-entrance');
  void imgEl.offsetWidth;
  imgEl.classList.add('cosmy-entrance');

  spotEl.classList.remove('visible');
  arrowEl.classList.remove('visible');

  if(step.last){
    nextBtn.textContent = '🪐 Entendido, Doutor.';
    nextBtn.classList.add('finish');
  } else {
    nextBtn.textContent = 'Próximo →';
    nextBtn.classList.remove('finish');
  }
  skipBtn.textContent = 'Pular';
}

function _startDr9(){
  if(currentScreen !== 'game' || !sandboxMode) return;
  _dr9Active = true;
  _dr9Step   = 0;
  const overlay = document.getElementById('cosmy-overlay');
  overlay.classList.add('active');
  setTimeout(()=>_showDr9Step(0), 200);
}

function _endDr9(completed){
  _dr9Active = false;
  const overlay = document.getElementById('cosmy-overlay');
  const bubble  = document.getElementById('cosmy-bubble');
  const imgEl   = document.getElementById('cosmy-img');
  bubble.classList.remove('blackholy-theme');
  imgEl.classList.remove('blackholy-img');
  overlay.style.opacity = '0';
  setTimeout(()=>{
    overlay.classList.remove('active');
    overlay.style.opacity = '';
    document.getElementById('cosmy-spotlight').classList.remove('visible');
    document.getElementById('cosmy-arrow').classList.remove('visible');
  }, 400);
  try{ localStorage.setItem(DR9_KEY,'1'); }catch(e){}
  // Ativa a barra de planetas
  _setPlanetPackActive(true);
  if(completed){
    // Mostra o modal de desbloqueio após o overlay fechar
    setTimeout(_showPackUnlockModal, 600);
  }
}

// ── Dispatcher central dos botões cosmy-next / cosmy-skip ────────
// Usa delegação no document para nunca perder o listener após replaceWith
document.addEventListener('click', function _cosmyCentralDispatch(e){
  const btn = e.target.closest('#cosmy-next, #cosmy-skip');
  if(!btn) return;
  const isNext = btn.id === 'cosmy-next';
  const isSkip = btn.id === 'cosmy-skip';

  // ── Reptilian invasion warning (Dr. Blackholy) ──
  if(window._blackholyReptWarningActive){
    if(isNext){
      const steps=window._blackholyReptWarningSteps||[];
      const cur=window._blackholyReptWarningStep||0;
      const s=steps[cur];
      if(s&&s.last){
        if(typeof window._handleBlackholyReptWarningEnd==='function')window._handleBlackholyReptWarningEnd(true);
      } else {
        window._blackholyReptWarningShowStep&&window._blackholyReptWarningShowStep(cur+1);
      }
    }
    if(isSkip){
      if(typeof window._handleBlackholyReptWarningEnd==='function')window._handleBlackholyReptWarningEnd(false);
    }
    return;
  }

  // ── Mars invasion warning ──
  if(window._marsWarningActive){
    if(isNext){
      const steps=window._marsWarningSteps||[];
      const cur=window._marsWarningStep||0;
      const s=steps[cur];
      if(s&&s.last){
        if(typeof window._handleMarsWarningEnd==='function')window._handleMarsWarningEnd(true);
      } else {
        window._marsWarningShowStep&&window._marsWarningShowStep(cur+1);
      }
    }
    if(isSkip){
      if(typeof window._handleMarsWarningEnd==='function')window._handleMarsWarningEnd(false);
    }
    return;
  }

  // ── Alien invasion warning ──
  if(window._alienWarningActive){
    if(isNext){
      const steps=window._alienWarningSteps||[];
      const cur=window._alienWarningStep||0;
      const s=steps[cur];
      if(s&&s.last){
        window._alienWarningActive=false;
        const overlay=document.getElementById('cosmy-overlay');
        const bubble=document.getElementById('cosmy-bubble');
        const imgEl=document.getElementById('cosmy-img');
        bubble.classList.remove('blackholy-theme','dk910-theme');
        imgEl.classList.remove('blackholy-img','dk910-img');
        overlay.style.opacity='0';
        setTimeout(()=>{
          overlay.classList.remove('active');
          overlay.style.opacity='';
          document.getElementById('cosmy-spotlight').classList.remove('visible');
          document.getElementById('cosmy-arrow').classList.remove('visible');
        },400);
        const cb=window._alienWarningCb;
        window._alienWarningCb=null;
        if(cb)setTimeout(cb,500);
      } else {
        window._alienWarningShowStep&&window._alienWarningShowStep(cur+1);
      }
    }
    if(isSkip){
      window._alienWarningActive=false;
      const overlay=document.getElementById('cosmy-overlay');
      const bubble=document.getElementById('cosmy-bubble');
      const imgEl=document.getElementById('cosmy-img');
      bubble.classList.remove('blackholy-theme','dk910-theme');
      imgEl.classList.remove('blackholy-img','dk910-img');
      overlay.style.opacity='0';
      setTimeout(()=>{overlay.classList.remove('active');overlay.style.opacity='';
        document.getElementById('cosmy-spotlight').classList.remove('visible');
        document.getElementById('cosmy-arrow').classList.remove('visible');},400);
      const cb=window._alienWarningCb;window._alienWarningCb=null;
      if(cb)setTimeout(cb,500);
    }
    return;
  }

  if(isNext){
    if(typeof _quasordAftermathActive !== 'undefined' && _quasordAftermathActive){
      const step=QUASORD_AFTERMATH_STEPS[_quasordAftermathStep];
      if(step&&step.last){ _endQuasordAftermath(); }
      else { _showQuasordAftermathStep(_quasordAftermathStep+1); }
    } else if(typeof _quasordVictoryActive !== 'undefined' && _quasordVictoryActive){
      const step=QUASORD_VICTORY_STEPS[_quasordVictoryStep];
      if(step&&step.last){ _endQuasordVictory(); }
      else { _showQuasordVictoryStep(_quasordVictoryStep+1); }
    } else if(typeof _dr38Active !== 'undefined' && _dr38Active){
      const step=DR38_STEPS[_dr38Step];
      if(step&&step.last){ _endDr38(true); } else { _showDr38Step(_dr38Step+1); }
    } else if(typeof _dr18Active !== 'undefined' && _dr18Active){
      const step = DR18_STEPS[_dr18Step];
      if(step && step.last){ _endDr18(true); }
      else { _showDr18Step(_dr18Step+1); }
    } else if(typeof _dr9Active !== 'undefined' && _dr9Active){
      const step = DR9_STEPS[_dr9Step];
      if(step && step.last){ _endDr9(true); }
      else { _showDr9Step(_dr9Step+1); }
    } else if(typeof _dk910Active !== 'undefined' && _dk910Active){
      const step = DK910_STEPS[_dk910Step];
      if(step && step.last){ _endDK910(true); }
      else { _showDK910Step(_dk910Step+1); }
    } else if(typeof _evcCI !== 'undefined' && _evcCI){
      if(typeof _evcNextHandler==='function') _evcNextHandler();
    } else if(typeof _sbTutActive !== 'undefined' && _sbTutActive){
      const allSteps=[...DR_STEPS,...SANDBOX_COSMY_STEPS];
      const step=allSteps[_sbTutStep];
      if(step&&step.last){_endSbTutorial(true);}
      else{_showSbStep(_sbTutStep+1);}
    } else {
      const step=COSMY_STEPS[_cosmyStep];
      if(step&&step.last){_endCosmyTutorial(true);}
      else{_showCosmyStep(_cosmyStep+1);}
    }
  }

  if(isSkip){
    if(typeof _quasordAftermathActive !== 'undefined' && _quasordAftermathActive){ _endQuasordAftermath(); }
    else if(typeof _quasordVictoryActive !== 'undefined' && _quasordVictoryActive){ _endQuasordVictory(); }
    else if(typeof _dr38Active !== 'undefined' && _dr38Active){ _endDr38(false); }
    else if(typeof _dr18Active !== 'undefined' && _dr18Active){ _endDr18(false); }
    else if(typeof _dr9Active !== 'undefined' && _dr9Active){ _endDr9(false); }
    else if(typeof _dk910Active !== 'undefined' && _dk910Active){ _endDK910(false); }
    else if(typeof _evcCI !== 'undefined' && _evcCI){
      if(typeof _evcSkipHandler==='function') _evcSkipHandler();
    } else if(typeof _sbTutActive !== 'undefined' && _sbTutActive){ _endSbTutorial(false); }
    else { _endCosmyTutorial(false); try{localStorage.setItem(COSMY_KEY,'1');}catch(e){} }
  }
});

// ═══════════════════════════════════════════════════════════════════
//  ABAS DA TOOLBAR — card "Normal / Planetas" acima da barra
// ═══════════════════════════════════════════════════════════════════

// Qual aba está ativa: 'normal' | 'planets'


// Rank atingido (independe de sandboxMode) — habilita seção nas configs
function _isPlanetPackUnlocked(){
  return playerRank >= 7;
}

// Barra de planetas só aparece em jogo sandbox com pacote habilitado
function _isPlanetPackAvailableInGame(){
  return sandboxMode && playerRank >= 7;
}

function _isPlanetPackEnabled(){
  try{
    const v = localStorage.getItem(PLANET_PACK_KEY);
    return v === null ? true : v === '1';
  }catch(e){ return true; }
}

function _setPlanetPackActive(on){
  try{ localStorage.setItem(PLANET_PACK_KEY, on?'1':'0'); }catch(e){}
  const ck = document.getElementById('cfg-planet-pack');
  if(ck) ck.checked = !!on;
  _refreshPlanetPackCfg();
    if(typeof _refreshStarPackCfg==='function') _refreshStarPackCfg();
    if(typeof _refreshExoticPackCfg==='function') _refreshExoticPackCfg();
  // Se desativado, volta para aba Normal
}

function _refreshPlanetPackCfg(){
  const unlocked = _isPlanetPackUnlocked();        // rank >= 7 (mostra na tela de configs)
  const inGame   = _isPlanetPackAvailableInGame(); // sandbox + rank >= 7 (mostra barra)
  const enabled  = _isPlanetPackEnabled();
  const show     = inGame && enabled;
  // Seção nas configurações — visível sempre que rank >= 7, mesmo fora do sandbox
  const sec = document.getElementById('packs-cfg-sec');
  const row = document.getElementById('packs-cfg-row');
  if(sec) sec.style.display = unlocked ? '' : 'none';
  if(row) row.style.display = unlocked ? '' : 'none';
  // Botões do pacote na toolbar — aparecem/somem livremente
  document.querySelectorAll('.planet-pack-btn').forEach(btn => {
    btn.style.display = show ? '' : 'none';
  });
  // Sincroniza toggle
  const ck = document.getElementById('cfg-planet-pack');
  if(ck) ck.checked = enabled;
}





// Toggle nas configurações
document.getElementById('cfg-planet-pack').addEventListener('change', e=>{
  _setPlanetPackActive(e.target.checked);
  showTooltip(e.target.checked ? '🪐 Pacote Planetas ativado!' : '🪐 Pacote Planetas desativado.');
});

// Inicialização ao carregar
(function _initPlanetPack(){
  _refreshPlanetPackCfg();
    if(typeof _refreshStarPackCfg==='function') _refreshStarPackCfg();
    if(typeof _refreshExoticPackCfg==='function') _refreshExoticPackCfg();
})();

