let _dr38Active=false, _dr38Step=0;

function _showDr38Step(idx){
  const overlay=document.getElementById('cosmy-overlay');
  const msgEl=document.getElementById('cosmy-msg');
  const stepLbl=document.getElementById('cosmy-step-label');
  const progressFill=document.getElementById('cosmy-progress-fill');
  const nextBtn=document.getElementById('cosmy-next');
  const spotEl=document.getElementById('cosmy-spotlight');
  const arrowEl=document.getElementById('cosmy-arrow');
  const total=DR38_STEPS.length;
  if(idx>=total){_endDr38(true);return;}
  _dr38Step=idx;
  const step=DR38_STEPS[idx];
  msgEl.classList.remove('cosmy-text-anim');void msgEl.offsetWidth;
  msgEl.innerHTML=step.msg;msgEl.classList.add('cosmy-text-anim');
  stepLbl.textContent=`Dr. Blackholy · PASSO ${idx+1} DE ${total}`;
  progressFill.style.width=((idx+1)/total*100)+'%';
  const imgEl=document.getElementById('cosmy-img');
  const bubble=document.getElementById('cosmy-bubble');
  imgEl.src=DR_IMAGES[step.mood]||DR_IMAGES['neutro'];
  imgEl.classList.add('blackholy-img');imgEl.classList.remove('dk910-img');
  bubble.classList.add('blackholy-theme');bubble.classList.remove('dk910-theme');
  stepLbl.style.color='rgba(200,100,255,.6)';
  imgEl.classList.remove('cosmy-entrance');void imgEl.offsetWidth;imgEl.classList.add('cosmy-entrance');
  spotEl.classList.remove('visible');arrowEl.classList.remove('visible');
  if(step.last){nextBtn.textContent='⚙️ Construir!';nextBtn.classList.add('finish');}
  else{nextBtn.textContent='Próximo →';nextBtn.classList.remove('finish');}
}
function _startDr38(){
  if(currentScreen!=='game'||!sandboxMode) return;
  _dr38Active=true;_dr38Step=0;
  const overlay=document.getElementById('cosmy-overlay');
  overlay.classList.add('active');
  setTimeout(()=>_showDr38Step(0),200);
}
function _endDr38(completed){
  _dr38Active=false;
  const overlay=document.getElementById('cosmy-overlay');
  const bubble=document.getElementById('cosmy-bubble');
  const imgEl=document.getElementById('cosmy-img');
  bubble.classList.remove('blackholy-theme');imgEl.classList.remove('blackholy-img');
  overlay.style.opacity='0';
  setTimeout(()=>{overlay.classList.remove('active');overlay.style.opacity='';
    document.getElementById('cosmy-spotlight').classList.remove('visible');
    document.getElementById('cosmy-arrow').classList.remove('visible');},400);
  try{localStorage.setItem(DR38_KEY,'1');}catch(e){}
  _setTechPackActive(true);
  if(completed) setTimeout(_showTechPackModal,600);
}

(function _initTechPack(){ _refreshTechPackCfg(); })();





