function _dk910NextMsg(){
  if(_dk910Queue.length === 0){
    _dk910MsgActive = false;
    const w = document.getElementById('dk910-msg-widget');
    if(w){ w.classList.remove('visible'); }
    return;
  }
  const item = _dk910Queue.shift();
  const img  = document.getElementById('dk910w-img');
  const txt  = document.getElementById('dk910w-text');
  const btn  = document.getElementById('dk910w-next');
  if(img) img.src = DK910_IMAGES[item.mood] || DK910_IMAGES['normal'];
  if(txt) txt.innerHTML = item.msg;
  btn.textContent = _dk910Queue.length === 0 ? 'Entendido. ✓' : 'Ok →';
}

function _dk910ShowQueue(steps){
  // Não interrompe overlay principal
  if(_dk910Active || _sbTutActive || _cosmyStep > 0) return;
  _dk910Queue = [...steps];
  _dk910MsgActive = true;
  const w = document.getElementById('dk910-msg-widget');
  if(w) w.classList.add('visible');
  _dk910NextMsg();
}

// ── Controle de quais astros/conquistas já foram explicados ────────
const _dk910SeenKey = 'cosmos_dk910_seen_v1';
function _dk910GetSeen(){
  try{ return new Set(JSON.parse(localStorage.getItem(_dk910SeenKey)||'[]')); }
  catch(e){ return new Set(); }
}
function _dk910MarkSeen(id){
  try{
    const s = _dk910GetSeen(); s.add(id);
    localStorage.setItem(_dk910SeenKey, JSON.stringify([...s]));
  }catch(e){}
}

