// ── Conquistas que a DK-910 comenta ───────────────────────────────
// ── Hook em checkUnlocks para disparar explicação ao desbloquear ──
const _dk910OrigCheckUnlocks = checkUnlocks;
checkUnlocks = function(){
  const beforeTypes = new Set(unlockedTypes);
  _dk910OrigCheckUnlocks.apply(this, arguments);
  // Verifica se algum novo tipo foi desbloqueado agora
  for(const type of unlockedTypes){
    if(beforeTypes.has(type)) continue;
    if(!sandboxMode) continue;
    const seen = _dk910GetSeen();
    if(seen.has('unlock_'+type)) continue;
    const explain = DK910_UNLOCK_EXPLAINS[type];
    if(!explain) continue;
    _dk910MarkSeen('unlock_'+type);
    // Delay para não colidir com o toast de desbloqueio
    setTimeout(()=>{
      if(!_dk910Active && !_sbTutActive){
        _dk910ShowQueue([...explain.steps]);
      }
    }, 5500);
  }
};

