function _bossAchGetDone(){
  try{return new Set(JSON.parse(localStorage.getItem(BOSS_ACH_KEY)||'[]'));}catch(e){return new Set();}
}
function _bossAchMarkDone(id){
  try{const s=_bossAchGetDone();s.add(id);localStorage.setItem(BOSS_ACH_KEY,JSON.stringify([...s]));}catch(e){}
}
// Dispara a conquista de boss (chamar na primeira vitória). Idempotente:
// se já concluída, não repete o toast.
function _bossAchTrigger(id){
  const ach=BOSS_ACHIEVEMENTS.find(a=>a.id===id);
  if(!ach)return;
  const done=_bossAchGetDone();
  if(done.has(id))return;
  _bossAchMarkDone(id);
  _achRenderBossList();
  _achShowBossToast(ach);
}

// ── Persistência ──────────────────────────────────────────────────
function _achGetDone(){
  try{return new Set(JSON.parse(localStorage.getItem(ACH_KEY)||'[]'));}catch(e){return new Set();}
}
function _achMarkDone(id){
  try{const s=_achGetDone();s.add(id);localStorage.setItem(ACH_KEY,JSON.stringify([...s]));}catch(e){}
}
function _achGetUnlocks(){
  try{return new Set(JSON.parse(localStorage.getItem(ACH_UNLOCK_KEY)||'[]'));}catch(e){return new Set();}
}
function _achMarkUnlock(id){
  try{const s=_achGetUnlocks();s.add(id);localStorage.setItem(ACH_UNLOCK_KEY,JSON.stringify([...s]));}catch(e){}
}

// ── Funções de desbloqueio de astros ─────────────────────────────
function _unlockTripleStar(){
  _achMarkUnlock('triplestar');
  showTooltip('🌠 Sistema Triplo desbloqueado! 3 estrelas em órbita mútua.');
}
function _unlockNeutronStarFree(){
  _achMarkUnlock('neutronstar_free');
  showTooltip('⭐ Estrela de Nêutrons desbloqueada para criação livre!');
}
function _unlockExoticPlanetFree(){
  _achMarkUnlock('exoticplanet_free');
  showTooltip('🪐 Planeta Exótico desbloqueado para criação livre!');
}

// ── Toast de conquista ────────────────────────────────────────────
let _achToastQueue=[];
let _achToastTimer=null;

function _achShowToast(ach, info){
  const toast=document.getElementById('ach-toast');
  const img=document.getElementById('ach-toast-char');
  const labelEl=document.getElementById('ach-toast-label');
  const name=document.getElementById('ach-toast-name');
  if(!toast)return;

  // Imagem correta para o humor do personagem
  img.src=info.img;

  // Label mostra o personagem que fala
  if(labelEl) labelEl.textContent='🏆 '+info.char.name+' diz:';

  // Nome da conquista
  name.textContent=ach.icon+' '+ach.name;

  // Fala do personagem (bolha de diálogo)
  let speechEl=document.getElementById('ach-toast-speech');
  if(!speechEl){
    speechEl=document.createElement('div');
    speechEl.id='ach-toast-speech';
    speechEl.style.cssText=[
      'font-size:9.5px','color:rgba(255,255,220,.82)','letter-spacing:.03em',
      'margin-top:5px','line-height:1.5','font-style:italic',
      'border-top:1px solid rgba(255,214,0,.18)','padding-top:5px',
      'max-width:220px','word-break:break-word'
    ].join(';');
    name.parentNode.appendChild(speechEl);
  }
  speechEl.textContent=info.speech||'';

  // Desc (pequena, abaixo da fala)
  let descEl=document.getElementById('ach-toast-desc');
  if(!descEl){
    descEl=document.createElement('div');
    descEl.id='ach-toast-desc';
    descEl.style.cssText='font-size:8px;color:rgba(255,214,0,.38);letter-spacing:.04em;margin-top:4px;line-height:1.3';
    name.parentNode.appendChild(descEl);
  }
  descEl.textContent=ach.desc||'';

  toast.classList.add('show');
  if(_achToastTimer)clearTimeout(_achToastTimer);
  // Conquistas com fala ficam mais tempo na tela
  const dur=info.speech?5200:3800;
  _achToastTimer=setTimeout(()=>{
    toast.classList.remove('show');
    _achToastTimer=null;
    if(_achToastQueue.length>0){
      const next=_achToastQueue.shift();
      setTimeout(()=>_achShowToast(next.ach,next.info),600);
    }
  },dur);
}

function _achTrigger(ach){
  _achMarkDone(ach.id);
  const info=_achCharForId(ach.id);
  if(typeof ach.onUnlock==='function') ach.onUnlock();
  // Mostrar botão na toolbar se for desbloqueio de astro
  const achBtnMap={triplestar:'btn-triplestar',exoticplanet_free:'btn-exoticplanet_free',neutronstar_free:'btn-neutronstar_free'};
  Object.keys(achBtnMap).forEach(k=>{
    if(_achGetUnlocks().has(k)&&sandboxMode){
      const btn=document.getElementById(achBtnMap[k]);
      if(btn)btn.style.display='inline-flex';
    }
  });
  _achRenderList();
  if(_achToastTimer){
    _achToastQueue.push({ach,info});
  } else {
    _achShowToast(ach,info);
  }
}

// ── Toast de conquista de BOSS (reaproveita o mesmo elemento visual) ──
function _achShowBossToast(ach){
  const toast=document.getElementById('ach-toast');
  const img=document.getElementById('ach-toast-char');
  const labelEl=document.getElementById('ach-toast-label');
  const name=document.getElementById('ach-toast-name');
  if(!toast)return;

  img.src=ach.img;
  if(labelEl) labelEl.textContent='🐙 Boss Derrotado!';
  name.textContent='🏆 '+ach.name;

  let speechEl=document.getElementById('ach-toast-speech');
  if(!speechEl){
    speechEl=document.createElement('div');
    speechEl.id='ach-toast-speech';
    speechEl.style.cssText=[
      'font-size:9.5px','color:rgba(255,255,220,.82)','letter-spacing:.03em',
      'margin-top:5px','line-height:1.5','font-style:italic',
      'border-top:1px solid rgba(255,214,0,.18)','padding-top:5px',
      'max-width:220px','word-break:break-word'
    ].join(';');
    name.parentNode.appendChild(speechEl);
  }
  speechEl.textContent=ach.speech||'';

  let descEl=document.getElementById('ach-toast-desc');
  if(!descEl){
    descEl=document.createElement('div');
    descEl.id='ach-toast-desc';
    descEl.style.cssText='font-size:8px;color:rgba(255,214,0,.38);letter-spacing:.04em;margin-top:4px;line-height:1.3';
    name.parentNode.appendChild(descEl);
  }
  descEl.textContent=ach.desc||'';

  toast.classList.add('show');
  if(_achToastTimer)clearTimeout(_achToastTimer);
  const dur=ach.speech?5200:3800;
  _achToastTimer=setTimeout(()=>{
    toast.classList.remove('show');
    _achToastTimer=null;
    if(_achToastQueue.length>0){
      const next=_achToastQueue.shift();
      setTimeout(()=>_achShowToast(next.ach,next.info),600);
    }
  },dur);
}

// ── Render da aba de Bosses ────────────────────────────────────────
function _achRenderBossList(){
  const list=document.getElementById('ach-boss-list');
  if(!list)return;
  const done=_bossAchGetDone();
  list.innerHTML='';
  BOSS_ACHIEVEMENTS.forEach(ach=>{
    const isDone=done.has(ach.id);
    const el=document.createElement('div');
    el.className='ach-boss-item'+(isDone?' done':' locked');
    el.innerHTML=`
      <img class="ach-boss-icon" src="${isDone?ach.img:''}" alt="" onerror="this.style.opacity=0">
      <div class="ach-boss-info">
        <div class="ach-boss-name">${isDone?ach.name:'???'}</div>
        <div class="ach-boss-desc">${isDone?ach.desc:'Derrote este boss para desbloquear.'}</div>
      </div>
      <div class="ach-boss-check">${isDone?'✓':'🔒'}</div>`;
    list.appendChild(el);
  });
}

// ── Classificação das conquistas por nível ────────────────────────
// Fácil  (8): podem ser feitas a qualquer momento
// Médio  (8): precisam de astros desbloqueáveis ou mais dificuldade
// Difícil(8): precisam de astros poderosos e raciocínio lógico
const ACH_LEVELS = {
  easy:   ['materia_galactica','passando_limites','ta_quente','por_um_triz',
            'familia_cosmica','avacalhou','fui_descoberto','quente_habitavel'],
  medium: ['briga_magnetica','interrupção_estelar','interrupcao_estelar','deriva_vazio',
            'espaco_tempo','nao_magnetita','revolucao_maquinas','velocidade_luz'],
  hard:   ['succao_tripla','ecos_passado','deixa_mag_paz','hora_vinganca',
            'olho_destruicao','autentico','volta_nunca_foram','nasceu_caixao',
            'sol_nasce_duas_vezes'],
};
// Normaliza: monta sets por nível de forma definitiva na ordem das conquistas
(function _buildAchLevels(){
  // Atribui level a cada achievement pela posição declarada
  const easy  = new Set(['materia_galactica','passando_limites','ta_quente','por_um_triz',
                          'familia_cosmica','avacalhou','fui_descoberto','quente_habitavel']);
  const medium= new Set(['briga_magnetica','interrupcao_estelar','deriva_vazio',
                          'espaco_tempo','nao_magnetita','revolucao_maquinas','velocidade_luz',
                          'sol_nasce_duas_vezes']);
  // Difícil = o restante
  ACHIEVEMENTS.forEach(a=>{
    if(easy.has(a.id))         a._level='easy';
    else if(medium.has(a.id))  a._level='medium';
    else                       a._level='hard';
  });
})();

// Estado da aba ativa
let _achActiveLevel='easy';

// Render do modal ─────────────────────────────────────────────────
function _achRenderList(){
  const list=document.getElementById('ach-list');
  const lbl=document.getElementById('ach-progress-lbl');
  const fill=document.getElementById('ach-progress-fill');
  if(!list)return;

  const done=_achGetDone();
  const total=ACHIEVEMENTS.length;
  const count=ACHIEVEMENTS.filter(a=>done.has(a.id)).length;
  if(lbl)lbl.textContent=count+' / '+total;
  if(fill)fill.style.width=(count/total*100)+'%';

  // Atualizar aparência das abas
  document.querySelectorAll('.ach-tab').forEach(tab=>{
    tab.className='ach-tab';
    if(tab.dataset.level===_achActiveLevel)
      tab.classList.add('active-'+_achActiveLevel);
  });

  // Filtrar conquistas pelo nível ativo
  const levelList=ACHIEVEMENTS.filter(a=>a._level===_achActiveLevel);

  // Lógica de visibilidade 4 a 4:
  // O grupo N só aparece se TODAS as do grupo N-1 estiverem concluídas.
  // Dentro do grupo visível, mostra todas (concluídas ou com cadeado).
  const groupSize=4;
  let visibleCount=groupSize; // começa mostrando primeiro grupo
  for(let g=0;g<Math.ceil(levelList.length/groupSize);g++){
    const start=g*groupSize;
    const end=Math.min(start+groupSize,levelList.length);
    const groupAchs=levelList.slice(start,end);
    const groupDone=groupAchs.filter(a=>done.has(a.id)).length;
    if(groupDone===groupAchs.length && end<levelList.length){
      visibleCount=end+groupSize; // desbloqueia próximo grupo
    } else { break; }
  }

  list.innerHTML='';

  // Nomes dos grupos por nível
  const groupLabels={
    easy:  ['🌱 Iniciante','🌿 Explorador','🍃 Aventureiro','🌳 Veterano — Grupo IV'],
    medium:['⚡ Desbravador','🌩️ Especialista','🌪️ Mestre','🔥 Elite — Grupo IV'],
    hard:  ['💀 Lendário','☠️ Titã','👁️ Absoluto','🔮 Transcendente — Grupo IV'],
  };
  const labels=groupLabels[_achActiveLevel]||['Grupo I','Grupo II','Grupo III','Grupo IV'];

  levelList.forEach((ach,idx)=>{
    // Cabeçalho de grupo a cada 4
    if(idx%groupSize===0){
      const sep=document.createElement('div');
      sep.className='ach-group-sep';
      const gIdx=Math.floor(idx/groupSize);
      const isVisible=idx<visibleCount;
      sep.textContent=isVisible ? labels[gIdx]||('Grupo '+(gIdx+1)) : '· · ·';
      if(!isVisible)sep.style.opacity='.25';
      list.appendChild(sep);
    }

    const isVisible=idx<visibleCount;
    const isDone=done.has(ach.id);

    const el=document.createElement('div');
    if(!isVisible){
      // Grupo ainda bloqueado — mostra título mas apagado com cadeado
      el.className='ach-item locked';
      el.innerHTML=`
        <div class="ach-icon" style="opacity:.25">🔒</div>
        <div class="ach-info"><div class="ach-name" style="opacity:.28;filter:blur(1.5px)">${ach.name}</div></div>
        <div class="ach-check"></div>`;
    } else {
      // Item visível — título sempre aparece, ícone só ao completar
      el.className='ach-item'+(isDone?' done':'');
      el.innerHTML=`
        <div class="ach-icon">${isDone?ach.icon:'🔒'}</div>
        <div class="ach-info">
          <div class="ach-name">${ach.name}</div>
        </div>
        <div class="ach-check">${isDone?'✓':''}</div>`;
    }
    list.appendChild(el);
  });
}

