// ═══════════════════════════════════════════════════════════════════
//  MOCHILA (INVENTÁRIO) — itens guardados, acesso a Conquistas/
//  Configurações e cartão de informações do jogador. Acessível durante
//  o gameplay (Sandbox) via botão 🎒 no HUD, sem sair da tela de jogo.
// ═══════════════════════════════════════════════════════════════════
let backpackItems=[]; // {id,name,desc,icon,useLabel,onUse}

function addBackpackItem(item){
  // Evita duplicar o mesmo item único (ex: só pode haver 1 Escama Robótica guardada)
  if(backpackItems.some(i=>i.id===item.id))return;
  backpackItems.push(item);
  const notif=document.getElementById('backpack-notif');
  if(notif)notif.classList.add('show');
  _bpRenderItems();
}
function removeBackpackItem(id){
  backpackItems=backpackItems.filter(i=>i.id!==id);
  _bpRenderItems();
  const notif=document.getElementById('backpack-notif');
  if(notif&&backpackItems.length===0)notif.classList.remove('show');
}

function _bpRenderItems(){
  const list=document.getElementById('bp-items-list');
  const empty=document.getElementById('bp-empty-msg');
  if(!list)return;
  list.innerHTML='';
  if(backpackItems.length===0){
    if(empty)empty.style.display='block';
    return;
  }
  if(empty)empty.style.display='none';
  backpackItems.forEach(item=>{
    const el=document.createElement('div');
    el.className='bp-item';
    const isImg=item.icon&&(item.icon.includes('/')||item.icon.includes('.png')||item.icon.includes('.jpg'));
    // ── Itens toggle (ex: Caixas de Música) permanecem na mochila e
    // apenas alternam entre ligado/desligado, em vez de serem consumidos. ──
    const label=item.toggle?(item.isOn?(item.onLabel||'🔇 Desligar'):(item.offLabel||'🔊 Ligar')):(item.useLabel||'Usar');
    el.innerHTML=`
      ${isImg?`<img class="bp-item-icon" src="${item.icon}" alt="">`:`<div class="bp-item-icon emoji">${item.icon||'❔'}</div>`}
      <div class="bp-item-info">
        <div class="bp-item-name">${item.name}${item.toggle?(item.isOn?' <span style="color:#5cf;font-size:.8em;">(ativa)</span>':''):''}</div>
        <div class="bp-item-desc">${item.desc||''}</div>
      </div>
      <button class="bp-item-use" data-item-id="${item.id}">${label}</button>
    `;
    list.appendChild(el);
  });
  list.querySelectorAll('.bp-item-use').forEach(btn=>{
    btn.addEventListener('click',()=>{
      const item=backpackItems.find(i=>i.id===btn.dataset.itemId);
      if(!item)return;
      if(item.toggle){
        // Item persistente: alterna estado, não remove da mochila
        item.isOn=!item.isOn;
        if(typeof item.onToggle==='function')item.onToggle(item.isOn);
        _bpRenderItems();
        return;
      }
      document.getElementById('bp-modal').classList.remove('open');
      removeBackpackItem(item.id);
      if(typeof item.onUse==='function')item.onUse();
    });
  });
}

// ── Cosmonário: lista de astros/entidades já encontrados na gameplay ──
function _bpRenderCosmonario(){
  const list=document.getElementById('cosmonario-list');
  const countEl=document.getElementById('cosmonario-count');
  const totalEl=document.getElementById('cosmonario-total');
  if(!list)return;
  const keys=Object.keys(COSMONARIO_DB);
  if(countEl)countEl.textContent=cosmonarioFound.size;
  if(totalEl)totalEl.textContent=keys.length;
  list.innerHTML='';
  keys.forEach(key=>{
    const def=COSMONARIO_DB[key];
    const found=cosmonarioFound.has(key);
    const el=document.createElement('div');
    el.className='cosmo-item'+(found?'':' undiscovered');
    const name=found?(def.name||TYPE_LABELS[key]||key):'???';
    const desc=found?def.desc:'Astro/entidade ainda não encontrado. Continue explorando o cosmos!';
    el.innerHTML=`
      <canvas class="cosmo-icon" width="44" height="44"></canvas>
      <div class="cosmo-info">
        <div class="cosmo-name">${name}</div>
        <div class="cosmo-desc">${desc}</div>
      </div>
    `;
    list.appendChild(el);
    if(found){
      const cvs=el.querySelector('.cosmo-icon');
      const isBoss=!!COSMONARIO_BOSS_DRAWERS[key];
      const ok=isBoss?_cosmonarioRenderBossPreview(key,cvs):_cosmonarioRenderPreview(key,cvs);
      if(!ok){
        // Fallback discreto caso o preview falhe por qualquer motivo —
        // evita deixar o retângulo vazio, mas nunca usa emoji.
        const pctx=cvs.getContext('2d');
        pctx.clearRect(0,0,44,44);
        pctx.beginPath();pctx.arc(22,22,14,0,Math.PI*2);
        pctx.fillStyle='rgba(255,255,255,.15)';pctx.fill();
      }
    }
  });
}

// ═══════════════════════════════════════════════════════════════════
//  CAIXAS DE MÚSICA — drop ao vencer uma invasão
//  30% de chance: Caixa de Música da invasão (música de invasão)
//  18% de chance (independente): Caixa de Música do Boss (música do boss)
//  Guardadas na mochila como itens PERSISTENTES (toggle liga/desliga).
//  Enquanto ativa, substitui a música padrão de gameplay pela faixa
//  escolhida, em loop. Ligar uma caixa desliga qualquer outra ativa.
// ═══════════════════════════════════════════════════════════════════
const MUSIC_BOX_DEFS={
  alien:{
    id:'musicbox-alien',name:'Caixa de Música — Invasão Alienígena',
    desc:'Toca a trilha da invasão Alienígena durante o gameplay.',
    icon:'👽',track:'songs/Invasions/Alien.ogg',
  },
  alienBoss:{
    id:'musicbox-alien-boss',name:'Caixa de Música — TecnoAlieNave',
    desc:'Toca a trilha do boss TecnoAlieNave durante o gameplay.',
    icon:'👽',track:'songs/Invasions/Bosses/TechnoAlienShip.ogg',
  },
  marsian:{
    id:'musicbox-marsian',name:'Caixa de Música — Invasão Marciana',
    desc:'Toca a trilha da invasão Marciana durante o gameplay.',
    icon:'🟢',track:'songs/Invasions/Marcian.ogg',
  },
  marsianBoss:{
    id:'musicbox-marsian-boss',name:'Caixa de Música — Devorador de Reatores',
    desc:'Toca a trilha do boss Devorador de Reatores durante o gameplay.',
    icon:'🟢',track:'songs/Invasions/Bosses/Reactor_Devourer.ogg',
  },
  reptilian:{
    id:'musicbox-reptilian',name:'Caixa de Música — Invasão Reptiliana',
    desc:'Toca a trilha da invasão Reptiliana durante o gameplay.',
    icon:'🦎',track:'songs/Invasions/Reptilian.ogg',
  },
  reptilianBoss:{
    id:'musicbox-reptilian-boss',name:'Caixa de Música — Quasord',
    desc:'Toca a trilha do Quasord (Leviatã Mecânico) durante o gameplay.',
    icon:'🦎',track:'songs/Invasions/Bosses/Galaxy_Annihilator/Fase_123.ogg',
  },
};

function _musicBoxToggle(defKey,isOn){
  // Exclusividade: ligar uma Caixa desliga qualquer outra ativa
  if(isOn){
    Object.values(MUSIC_BOX_DEFS).forEach(d=>{
      if(d.id!==MUSIC_BOX_DEFS[defKey].id){
        const other=backpackItems.find(i=>i.id===d.id);
        if(other&&other.isOn)other.isOn=false;
      }
    });
    if(typeof AudioSys!=='undefined')AudioSys.setGameplayOverride(MUSIC_BOX_DEFS[defKey].track);
    showTooltip(`🎵 ${MUSIC_BOX_DEFS[defKey].name} ativada.`);
  } else {
    if(typeof AudioSys!=='undefined')AudioSys.setGameplayOverride(null);
    showTooltip('🔇 Caixa de Música desativada.');
  }
}

function _grantMusicBox(defKey){
  const def=MUSIC_BOX_DEFS[defKey];
  if(!def)return;
  if(backpackItems.some(i=>i.id===def.id))return; // já possui esta caixa
  addBackpackItem({
    id:def.id,name:def.name,desc:def.desc,icon:def.icon,
    toggle:true,isOn:false,
    onLabel:'🔇 Desligar',offLabel:'🔊 Ligar',
    onToggle:(isOn)=>_musicBoxToggle(defKey,isOn),
  });
  showTooltip(`🎁 Você recebeu: ${def.name}!`);
}

// ── Gatilho: chamar ao final de QUALQUER invasão vencida pelo jogador ──
// invasionKey: 'alien' | 'marsian' | 'reptilian'
function rollInvasionMusicBoxDrops(invasionKey){
  const bossKey=invasionKey+'Boss';
  if(Math.random()<0.30) _grantMusicBox(invasionKey);
  if(Math.random()<0.18 && MUSIC_BOX_DEFS[bossKey]) _grantMusicBox(bossKey);
}

// ── Cartão de Informações do Jogador (Nível/Rank/XP/Galáxias/Astros) ──
function _bpRenderInfo(){
  try{
    const rankIdx=Math.min(playerRank,RANK_NAMES.length-1);
    const rankEl=document.getElementById('bp-info-rank');
    const lvlEl=document.getElementById('bp-info-lvl');
    const fillEl=document.getElementById('bp-info-xpfill');
    const curEl=document.getElementById('bp-info-xpcur');
    const nextEl=document.getElementById('bp-info-xpnext');
    const galEl=document.getElementById('bp-stat-galaxies');
    const astroEl=document.getElementById('bp-stat-astros');
    if(rankEl)rankEl.textContent=RANK_NAMES[rankIdx];
    if(lvlEl)lvlEl.textContent=`Nível ${playerRank+1}`;
    const lo=playerRank>0?RANK_THRESHOLDS[playerRank-1]:0;
    const hi=playerRank<RANK_THRESHOLDS.length?RANK_THRESHOLDS[playerRank]:RANK_THRESHOLDS[RANK_THRESHOLDS.length-1];
    const pct=playerRank>=RANK_THRESHOLDS.length?100:clamp(Math.round((playerLogs-lo)/(hi-lo)*100),0,100);
    if(fillEl)fillEl.style.width=pct+'%';
    if(curEl)curEl.textContent=playerLogs;
    if(nextEl)nextEl.textContent=playerRank<RANK_THRESHOLDS.length?hi:'MAX';
    if(galEl)galEl.textContent=mStats.galaxiesCreated||0;
    if(astroEl)astroEl.textContent=unlockedTypes.size||0;
  }catch(e){console.warn('_bpRenderInfo error:',e);}
}

